def _build_demo_launch_prompts(environment: Mapping[str, Any]) -> list[dict[str, str]]:
    target_lines = _demo_launch_prompt_target_lines(environment)
    common_lines = _demo_launch_prompt_common_lines()
    topology_lines = [
        "Three-lane execution topology:",
        "Prepare three independent demo environments, one dedicated environment for each launch prompt.",
        "Pin every environment to the same exact Owner release candidate commit before starting any lane.",
        "Run the lanes sequentially in this fixed order: Direct Main, then MF Parallel, then MF Batch Parallel.",
        "Do not reuse one environment, repository root, backlog row, or dirty worktree across lane modes.",
        "This prompt owns only its named lane and dedicated environment; do not start either of the other lane modes here.",
        "If this lane reaches a genuine governance gate, preserve the duplicate Gate result and stop this lane; do not convert it into another mode or bypass it.",
    ]
    variants = [
        {
            "id": "direct_main",
            "label": "Direct Main",
            "description": "Observer-supervised direct_main path for one tiny deterministic planner change.",
            "path_lines": [
                "Path-specific route:",
                "Use operator_supervised_direct_main for a tiny deterministic implementation.",
                "Create or select exactly one backlog row for the planner requirement, then call onboard_route_guide with work_type=operator_supervised_direct_main.",
                "The observer must run rg and graph_query before mutation, call the Guide's literal observer_direct_mutation_exception action with DB-verified graph trace ids, and edit only approved row-scoped files.",
                "Do not write mf_sub implementation evidence in this path. Use independent QA/verifier evidence before merge, reconcile, or close.",
                "If direct_main guide or close gate demands worker-owned evidence, stop and report that route friction instead of backfilling fake worker evidence.",
            ],
        },
        {
            "id": "mf_parallel",
            "label": "MF Parallel",
            "description": "Single-backlog mf_parallel path with exactly two bounded Codex Desktop workers.",
            "path_lines": [
                "Path-specific route:",
                "Use mf_parallel for exactly one backlog row covering the Today Focus and reminder visual planner board.",
                "",
                "Parallel implementation shape:",
                "Create exactly one backlog row for that requirement, then dispatch exactly two Codex Desktop bounded mf_sub workers in parallel:",
                "- Focus/UI lane: src/app.js, index.html, styles.css, tests/planner.test.mjs",
                "- Reminder/domain lane: src/reminders.js, tests/reminders.test.mjs",
                "- The two workers must have distinct RuntimeContexts/worktrees/branches and disjoint owned_files fences; do not collapse the lanes into one worker.",
                "- If shared-file or dependency conflicts appear, record the observer decision and stop at the contract gate rather than collapsing the fanout.",
                "",
                "Observer starts the mf_parallel contract through onboard_route_guide/mf_parallel_enter, scopes with rg + graph, atomically dispatches both bounded workers, then waits for both lanes' worker-owned read/startup/graph/implementation/commit/finish evidence.",
                "Each bounded worker must be a separate Codex Desktop host-created subagent using its own runtime envelope; do not use the CLI Agent Service and the observer session must not act as either worker.",
                "After both finish gates pass, merge both durable queue items, reconcile the final canonical HEAD, then dispatch a fresh independent QA session against that canonical HEAD/reconciled graph.",
                "If final QA returns NO-PASS, start the bounded worker-fix successor from the QA finding and repeat merge/reconcile/fresh QA. If token scope, merge queue, or finish gate rejects, stop and summarize friction.",
            ],
        },
        {
            "id": "mf_batch_parallel",
            "label": "MF Batch Parallel",
            "description": "Two-backlog mf_batch_parallel path proving row-scoped fanout and serial merge.",
            "path_lines": [
                "Path-specific route:",
                "Use mf_batch_parallel for two compatible backlog rows, then let the batch fan out into row-scoped mf_parallel successors.",
                "",
                "Batch rows:",
                "- Row A: Today Focus area, default focused demo task, and focused-task sorting.",
                "- Row B: per-task reminder toggle defaulting off and reminder tests.",
                "",
                "The batch observer must run rg + graph before selecting row scopes. Each row observer/worker repeats graph queries with its own identity before implementation.",
                "For every row lane, the row observer must launch or hand off to a separate Codex Desktop host-created subagent as the bounded worker; do not use the CLI Agent Service, and the observer session must not edit the worker worktree or submit worker-owned evidence.",
                "Land row commits through the batch merge queue in the order returned by runtime guidance; do not bypass merge materialize/apply when gates are healthy.",
                "If a shared test file or merge queue mismatch appears, record the batch friction and stop rather than silently converting the work into a single-row or direct_main flow.",
            ],
        },
    ]
    prompts: list[dict[str, str]] = []
    for variant in variants:
        lines = [
            f"Run the Aming Claw Daily Planner Lite {variant['label']} happy-path demo from start to finish.",
            "",
            *target_lines,
            "",
            *topology_lines,
            "",
            *variant["path_lines"],
            *common_lines,
            "",
            "Demo work:",
            "Do not stop after planning. Run the full governed happy path unless a real governance gate returns a blocker.",
        ]
        prompts.append({
            "id": str(variant["id"]),
            "label": str(variant["label"]),
            "description": str(variant["description"]),
            "prompt": "\n".join(lines),
        })
    return prompts


def _build_demo_launch_prompt(environment: Mapping[str, Any]) -> str:
    prompts = _build_demo_launch_prompts(environment)
    for prompt in prompts:
        if prompt.get("id") == "mf_parallel":
            return str(prompt.get("prompt") or "")
    return "\n".join([
        "Run the Aming Claw Daily Planner Lite visual happy-path demo from start to finish.",
        "",
        *_demo_launch_prompt_target_lines(environment),
    ])


def _daily_planner_fixture_script() -> Path:
    return Path(__file__).resolve().parents[2] / "frontend" / "dashboard" / "scripts" / "e2e-vibe-queue-fixture.mjs"


def _demo_node_executable() -> str:
    candidates: list[str] = []
    for env_key in ("AMING_CLAW_NODE_BIN", "NODE_BIN"):
        value = str(os.environ.get(env_key) or "").strip()
        if value:
            candidates.append(value)
    found = shutil.which("node")
    if found:
        candidates.append(found)
    candidates.append(
        str(
            Path.home()
            / ".cache"
            / "codex-runtimes"
            / "codex-primary-runtime"
            / "dependencies"
            / "node"
            / "bin"
            / "node"
        )
    )
    for candidate in candidates:
        path = Path(candidate).expanduser()
        if path.exists() and os.access(path, os.X_OK):
            return str(path)
    raise RuntimeError(
        "Node.js executable not found for Daily Planner Lite fixture. "
        "Set AMING_CLAW_NODE_BIN or NODE_BIN to an executable node binary."
    )


def _run_daily_planner_lite_fixture(
    *,
    environment_id: str,
    fixture_root: Path,
    target_project_id: str,
    preview_port: int,
) -> dict[str, Any]:
    script = _daily_planner_fixture_script()
    if not script.exists():
        raise RuntimeError(f"Daily Planner Lite fixture script is missing: {script}")
    command = [
        _demo_node_executable(),
        str(script),
        "--run-id",
        environment_id,
        "--project-id",
        target_project_id,
        "--fixture-root",
        str(fixture_root),
        "--preview-port",
        str(preview_port),
        "--reset",
        "--no-browser",
    ]
    proc = subprocess.run(
        command,
        capture_output=True,
        text=True,
        timeout=180,
        cwd=str(Path(__file__).resolve().parents[2]),
    )
    if proc.returncode != 0:
        raise RuntimeError((proc.stderr or proc.stdout or "fixture script failed").strip()[:1200])
    try:
        payload = json.loads(proc.stdout)
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"fixture script returned invalid JSON: {exc}") from exc
    if not payload.get("ok"):
        raise RuntimeError(str(payload.get("error") or "fixture script returned ok=false"))
    return payload


def _demo_environment_from_fixture(
    *,
    owner_project_id: str,
    environment_id: str,
    template_id: str,
    fixture_root: Path,
    created_at: str,
    fixture_result: Mapping[str, Any],
) -> dict[str, Any]:
    target_project_id = str(fixture_result.get("project_id") or f"{template_id}-{environment_id}")
    dashboard_links = fixture_result.get("dashboard_links") if isinstance(fixture_result.get("dashboard_links"), Mapping) else {}
    environment = {
        "id": environment_id,
        "template_id": template_id,
        "label": "Daily Planner Lite",
        "owner_project_id": owner_project_id,
        "project_id": target_project_id,
        "fixture_root": str(fixture_root),
        "baseline_commit": str(fixture_result.get("baseline_commit") or ""),
        "owner_runtime_identity": _demo_owner_runtime_identity(),
        "created_at": created_at,
        "dashboard_url": str(fixture_result.get("dashboard_url") or _demo_dashboard_url(target_project_id, "backlog")),
        "backlog_url": str(dashboard_links.get("backlog") or _demo_dashboard_url(target_project_id, "backlog")),
        "timeline_url": str(dashboard_links.get("timeline") or _demo_dashboard_url(target_project_id, "timeline")),
        "graph_url": str(dashboard_links.get("graph") or _demo_dashboard_url(target_project_id, "graph")),
        "planner_preview_url": str(fixture_result.get("planner_preview_url") or ""),
        "planner_preview_command": str(fixture_result.get("planner_preview_command") or ""),
        "status": "ready",
    }
    environment["launch_prompts"] = _build_demo_launch_prompts(environment)
    environment["launch_prompt"] = _build_demo_launch_prompt(environment)
    return environment


def _visible_demo_environments(project_id: str) -> list[dict[str, Any]]:
    visible: list[dict[str, Any]] = []
    for row in _read_demo_environment_registry(project_id):
        ok, _, _ = _validate_managed_demo_environment(row, project_id)
        if ok:
            environment = dict(row)
            environment["status"] = environment.get("status") or "ready"
            environment["launch_prompts"] = _build_demo_launch_prompts(environment)
            environment["launch_prompt"] = _build_demo_launch_prompt(environment)
            visible.append(environment)
    visible.sort(key=_demo_environment_sort_key, reverse=True)
    return visible


