def _observer_repair_id_list(value: Any) -> list[str]:
    if isinstance(value, str):
        raw = value.replace("\r", "\n").replace(",", "\n").split("\n")
    elif isinstance(value, list):
        raw = value
    elif isinstance(value, tuple):
        raw = list(value)
    elif value in (None, ""):
        raw = []
    else:
        raw = [value]
    return sorted({str(item or "").strip() for item in raw if str(item or "").strip()})


def _build_observer_repair_run_plan_from_body(
    conn,
    project_id: str,
    body: Mapping[str, Any],
) -> dict[str, Any]:
    root_backlog_ids = _observer_repair_id_list(
        body.get("root_backlog_ids") or body.get("backlog_ids") or body.get("bug_ids")
    )
    backlog_rows: list[dict[str, Any]] = []
    missing_backlog_ids: list[str] = []
    if root_backlog_ids:
        placeholders = ",".join("?" for _ in root_backlog_ids)
        rows = conn.execute(
            f"SELECT * FROM backlog_bugs WHERE bug_id IN ({placeholders})",
            root_backlog_ids,
        ).fetchall()
        by_id = {str(row["bug_id"]): dict(row) for row in rows}
        backlog_rows = [by_id[bug_id] for bug_id in root_backlog_ids if bug_id in by_id]
        missing_backlog_ids = [bug_id for bug_id in root_backlog_ids if bug_id not in by_id]

    timeline_prechecks: list[dict[str, Any]] = []
    if body.get("include_timeline_precheck"):
        from . import task_timeline

        for row in backlog_rows:
            bug_id = str(row.get("bug_id") or "")
            events = task_timeline.list_events(conn, project_id, backlog_id=bug_id, limit=1000)
            if _mf_close_timeline_applicability(row)["is_mf"]:
                contract = backlog_runtime.parse_json_object(
                    _row_get(row, "chain_trigger_json", "{}")
                )
                contract = _mf_close_contract_with_route_context(contract, row, {})
                verification = _mf_close_gate_verification(
                    events,
                    contract=contract,
                    conn=conn,
                    project_id=project_id,
                )
            else:
                verification = {"passed": True, "missing_event_kinds": []}
            timeline_prechecks.append(
                {
                    "project_id": project_id,
                    "bug_id": bug_id,
                    "can_close": bool(verification.get("passed")),
                    "timeline_gate": verification,
                }
            )

    blockers = list(body.get("blockers") or [])
    blockers.extend(f"missing backlog row: {bug_id}" for bug_id in missing_backlog_ids)
    from . import observer_repair_run

    plan = observer_repair_run.build_repair_run_plan(
        project_id=project_id,
        root_backlog_ids=root_backlog_ids,
        backlog_rows=backlog_rows,
        blockers=blockers,
        graph_status=body.get("graph_status") if isinstance(body.get("graph_status"), dict) else {},
        operations_queue=body.get("operations_queue")
        if isinstance(body.get("operations_queue"), dict)
        else {},
        version_check=body.get("version_check") if isinstance(body.get("version_check"), dict) else {},
        timeline_prechecks=timeline_prechecks,
        route_context_seed=body.get("route_context_seed")
        if isinstance(body.get("route_context_seed"), dict)
        else {},
        actor=str(body.get("actor") or "observer"),
    )
    plan["missing_backlog_ids"] = missing_backlog_ids
    return plan


@route("POST", "/api/projects/{project_id}/observer-repair-run/plan")
def handle_observer_repair_run_plan(ctx: RequestContext):
    """Build a read-only, replayable observer repair-run plan."""

    project_id = ctx.get_project_id()
    body = ctx.body if isinstance(ctx.body, dict) else {}
    conn = get_connection(project_id)
    try:
        return _build_observer_repair_run_plan_from_body(conn, project_id, body)
    finally:
        conn.close()


@route("POST", "/api/projects/{project_id}/observer-repair-run/route-evidence")
def handle_observer_repair_run_route_evidence(ctx: RequestContext):
    """Dry-run or record route-service source events for an observer repair plan."""

    project_id = ctx.get_project_id()
    body = ctx.body if isinstance(ctx.body, dict) else {}
    actor = str(body.get("actor") or "observer")
    record = _query_bool(body, "record", False)
    action_precheck_id = str(
        body.get("action_precheck_id") or body.get("precheck_id") or ""
    ).strip()
    conn = get_connection(project_id)
    try:
        from . import observer_repair_run, task_timeline

        plan = _build_observer_repair_run_plan_from_body(conn, project_id, body)
        route_context_seed = (
            body.get("route_context_seed")
            if isinstance(body.get("route_context_seed"), Mapping)
            else {}
        )
        action_precheck = (
            body.get("action_precheck")
            or body.get("external_action_precheck")
            or body.get("action_precheck_packet")
            or route_context_seed.get("action_precheck")
            or route_context_seed.get("external_action_precheck")
            or route_context_seed.get("action_precheck_packet")
            or route_context_seed.get("route_action_precheck")
        )
        if not isinstance(action_precheck, Mapping):
            action_precheck = {}
        external_route_identity = (
            body.get("route_identity")
            or body.get("external_route_identity")
            or body.get("claimed_route_identity")
            or body.get("command_route_identity")
            or body.get("observer_command_route_identity")
            or body.get("route_context")
            or route_context_seed.get("route_identity")
            or route_context_seed.get("external_route_identity")
            or route_context_seed.get("claimed_route_identity")
            or route_context_seed.get("command_route_identity")
            or route_context_seed.get("observer_command_route_identity")
            or route_context_seed.get("route_context")
        )
        if not isinstance(external_route_identity, Mapping):
            external_route_identity = {
                key: body.get(key) or route_context_seed.get(key)
                for key in (
                    "route_id",
                    "route_context_hash",
                    "prompt_contract_id",
                    "prompt_contract_hash",
                    "visible_injection_manifest_hash",
                    "visible_injection_manifest",
                )
                if body.get(key) or route_context_seed.get(key)
            }
        if not external_route_identity and action_precheck:
            external_route_identity = dict(action_precheck)
        if isinstance(external_route_identity, Mapping):
            lineage_sources: list[Mapping[str, Any]] = [
                source
                for source in (body, route_context_seed, action_precheck)
                if isinstance(source, Mapping)
            ]
            for source in list(lineage_sources):
                for nested_key in (
                    "route_identity",
                    "route_context",
                    "route",
                    "contract_binding",
                    "active_contract_execution",
                    "contract_execution",
                    "selected_successor_contract",
                    "successor_contract",
                    "next_legal_action",
                    "route_action_gate",
                ):
                    nested = source.get(nested_key)
                    if isinstance(nested, Mapping):
                        lineage_sources.append(nested)
            lineage: dict[str, str] = {}
            for field in (
                "route_token_ref",
                "contract_execution_id",
                "active_contract_execution_id",
                "parent_contract_execution_id",
                "successor_contract_execution_id",
            ):
                for source in lineage_sources:
                    token = str(source.get(field) or "").strip()
                    if token:
                        lineage[field] = token
                        break
            if lineage:
                external_route_identity = {
                    **dict(external_route_identity),
                    **{
                        field: value
                        for field, value in lineage.items()
                        if not str(external_route_identity.get(field) or "").strip()
                    },
                }
        force_supersede = bool(body.get("force_supersede") or False)
        force_reason = str(body.get("force_reason") or "").strip()
        materialization = observer_repair_run.build_route_service_materialization(
            plan,
            action_precheck_id=action_precheck_id,
            external_route_identity=external_route_identity,
            action_precheck=action_precheck,
            graph_status=body.get("graph_status")
            if isinstance(body.get("graph_status"), dict)
            else {},
            version_check=body.get("version_check")
            if isinstance(body.get("version_check"), dict)
            else {},
            actor=actor,
            record=record,
        )
        materialization["record"] = record
        materialization["mode"] = "record" if record else "dry_run"
        if not record:
            if body.get("include_plan"):
                materialization["plan"] = plan
            return materialization
        # AC-REPAIR-RUN-LIVE-IDENTITY-SUPERSEDE-GUARD-20260610:
        # When record=True and the materialization would write a route.identity.superseded
        # event, call guard_live_identity_supersession to refuse silent supersession of any
        # live lane identity that already has accepted startup or QA lineage.
        if materialization.get("route_identity_supersession"):
            supersession = materialization["route_identity_supersession"]
            proposed_superseded = (
                supersession.get("supplied_route_identity")
                or supersession.get("proposed_superseded_identity")
                or external_route_identity
                or {}
            )
            backlog_id_for_guard = str(
                materialization.get("backlog_id") or ""
            )
            guard_timeline_events: list[dict] = []
            if backlog_id_for_guard:
                guard_timeline_events = task_timeline.list_events(
                    conn,
                    project_id,
                    backlog_id=backlog_id_for_guard,
                    limit=200,
                )
            guard_result = observer_repair_run.guard_live_identity_supersession(
                proposed_superseded_identity=proposed_superseded,
                timeline_events=guard_timeline_events,
                force_supersede=force_supersede,
                force_reason=force_reason,
            )
            if not guard_result.get("ok"):
                raise GovernanceError(
                    "observer_repair_run_supersession_refused",
                    guard_result.get("reason") or "identity supersession refused by guard",
                    409,
                    {
                        "guard_result": guard_result,
                        "record_blocked": True,
                        "record_blocked_reason": "live_identity_supersession_refused",
                    },
                )
        if not materialization.get("recordable"):
            raise GovernanceError(
                "observer_repair_route_evidence_not_recordable",
                "route evidence can be recorded only for one existing root backlog id with source events",
                422,
                materialization,
            )

        recorded_sources: list[dict[str, Any]] = []
        recorded_service_events: list[dict[str, Any]] = []
        reused_source_event_ids: list[int] = []
        for event in materialization.get("source_events") or []:
            if not isinstance(event, Mapping):
                continue
            backlog_id = str(event.get("backlog_id") or materialization.get("backlog_id") or "")
            event_type = str(event.get("event_type") or "")
            correlation_id = str(event.get("source_event_id") or "")
            existing = [
                item
                for item in task_timeline.list_events(
                    conn,
                    project_id,
                    backlog_id=backlog_id,
                    correlation_id=correlation_id,
                    limit=20,
                )
                if str(item.get("event_type") or "") == event_type
            ]
            if existing:
                recorded = existing[0]
                reused_source_event_ids.append(int(recorded.get("id") or 0))
            else:
                recorded = task_timeline.record_event(
                    conn,
                    project_id=project_id,
                    backlog_id=backlog_id,
                    event_type=event_type,
                    phase=str(event.get("phase") or ""),
                    event_kind=str(event.get("event_kind") or ""),
                    actor=str(event.get("actor") or actor),
                    status=str(event.get("status") or "requested"),
                    payload=dict(event.get("payload") or {}),
                    verification=dict(event.get("verification") or {}),
                    artifact_refs=dict(event.get("artifact_refs") or {}),
                    correlation_id=correlation_id,
                )
            # F5-LIFECYCLE / F-SUPERSESSION-HOOK: delegate to the shared helper
            # so that extraction + invalidation logic is identical across both
            # the repair-run path and the direct-append path.  A DB failure is
            # logged as a warning (not swallowed silently) but does NOT abort
            # the parent record.  See _apply_supersession_hook_if_needed.
            _apply_supersession_hook_if_needed(
                conn,
                project_id=project_id,
                event_kind=str(event.get("event_kind") or ""),
                event_type=str(event.get("event_type") or ""),
                payload=dict(event.get("payload") or {}),
            )
            service_events = task_timeline.list_events(
                conn,
                project_id,
                backlog_id=str(recorded.get("backlog_id") or ""),
                parent_event_id=int(recorded.get("id") or 0),
                event_kind="service_route",
                limit=50,
            )
            if not service_events:
                from . import service_router

                service_router.route_timeline_event(conn, recorded, record=True)
                service_events = task_timeline.list_events(
                    conn,
                    project_id,
                    backlog_id=str(recorded.get("backlog_id") or ""),
                    parent_event_id=int(recorded.get("id") or 0),
                    event_kind="service_route",
                    limit=50,
                )
            recorded_sources.append(recorded)
            recorded_service_events.extend(service_events)
        conn.commit()
        materialization["recorded"] = True
        materialization["reused_source_event_ids"] = reused_source_event_ids
        materialization["recorded_source_events"] = recorded_sources
        materialization["recorded_service_events"] = recorded_service_events
        materialization["recorded_source_event_ids"] = [
            int(event.get("id") or 0) for event in recorded_sources
        ]
        materialization["recorded_service_event_ids"] = [
            int(event.get("id") or 0) for event in recorded_service_events
        ]
        # AC3: Persist full payload to scratch; return compact response.
        full_payload_path, full_payload_sha256 = _persist_full_payload(
            project_id,
            "repair-run-route-evidence",
            str(ctx.request_id),
            materialization,
        )
        # Collect recorded event ids+kinds+status for compact summary
        recorded_event_ids = []
        for ev in recorded_sources + recorded_service_events:
            recorded_event_ids.append({
                "id": int(ev.get("id") or 0),
                "event_kind": str(ev.get("event_kind") or ""),
                "status": str(ev.get("status") or ""),
            })
        # Supersession summary (if present)
        supersession_summary = {}
        if materialization.get("superseded_event_ids") or materialization.get("supersession"):
            supersession_summary = {
                "superseded_event_ids": materialization.get("superseded_event_ids") or [],
                "supersession": materialization.get("supersession") or {},
            }
        route_identity_used = {
            key: materialization.get(key) or ""
            for key in ("route_id", "route_context_hash", "prompt_contract_id", "prompt_contract_hash", "visible_injection_manifest_hash")
            if materialization.get(key)
        }
        # Compact response: include new compact fields + backward-compat keys from materialization
        # so existing callers (e.g. tests using recorded_source_event_ids / reused_source_event_ids)
        # are not broken. The large repeated plan/source_events bodies are dropped.
        compact = {
            "ok": bool(materialization.get("ok") or materialization.get("recorded")),
            "recorded": True,
            # backward-compat keys retained for existing callers
            "recorded_source_event_ids": materialization["recorded_source_event_ids"],
            "recorded_service_event_ids": materialization["recorded_service_event_ids"],
            "reused_source_event_ids": materialization["reused_source_event_ids"],
            "recorded_service_events": recorded_service_events,
            # new compact summary fields
            "recorded_event_ids": recorded_event_ids,
            "route_identity_used": route_identity_used,
            "full_payload_path": full_payload_path,
            "full_payload_sha256": full_payload_sha256,
            "request_id": str(ctx.request_id),
        }
        if supersession_summary:
            compact["supersession_summary"] = supersession_summary
        return compact
    finally:
        conn.close()


