def _route_token_ref_error_details(
    exc: BaseException,
    *,
    project_id: str = "",
    backlog_id: str = "",
    task_id: str = "",
    route_token_ref: str = "",
    observer_session_id: str = "",
) -> dict[str, Any]:
    code = str(getattr(exc, "code", "") or "").strip()
    raw_details = getattr(exc, "details", {})
    exc_details = dict(raw_details) if isinstance(raw_details, Mapping) else {}
    next_action = exc_details.get("next_action")
    if not isinstance(next_action, Mapping):
        expiry_status = exc_details.get("expiry_status")
        if isinstance(expiry_status, Mapping):
            next_action = expiry_status.get("next_action")
    if not isinstance(next_action, Mapping) and (
        code in {"route_token_ref_expired", "route_token_ref_near_expiry"}
        or "expired" in str(exc).lower()
        or "near expiry" in str(exc).lower()
    ):
        next_action = _observer_route_context_renewal_guidance(
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            route_token_ref=route_token_ref,
            observer_session_id=observer_session_id,
            reason=code or "route_token_ref_expiry",
        )
    payload: dict[str, Any] = {
        "schema_version": "route_token_ref.semantic_error.v1",
        "route_token_ref": str(route_token_ref or "").strip(),
        "route_token_ref_error_code": code,
        "route_token_ref_error_details": exc_details,
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
    }
    if isinstance(next_action, Mapping):
        payload["next_action"] = dict(next_action)
        payload["next_legal_action"] = dict(next_action)
        payload["semantic_next_action"] = str(
            next_action.get("semantic_next_action")
            or next_action.get("action")
            or "observer_route_context_renew"
        )
    return payload


def _iter_nested_mappings(value: Any, *, _depth: int = 0) -> Iterable[Mapping[str, Any]]:
    if _depth > 8:
        return
    if isinstance(value, Mapping):
        yield value
        for child in value.values():
            yield from _iter_nested_mappings(child, _depth=_depth + 1)
    elif isinstance(value, list):
        for child in value:
            yield from _iter_nested_mappings(child, _depth=_depth + 1)


def _multi_backlog_task_binding_from_timeline(
    conn: sqlite3.Connection,
    *,
    project_id: str,
    task_id: str,
) -> dict[str, Any]:
    try:
        rows = conn.execute(
            """
            SELECT id, payload_json
            FROM task_timeline_events
            WHERE project_id = ? AND event_type = 'mf_batch_parallel.entered'
            ORDER BY id DESC
            LIMIT 100
            """,
            (project_id,),
        ).fetchall()
    except sqlite3.OperationalError as exc:
        if "no such table" in str(exc).lower():
            return {}
        raise
    for row in rows:
        raw_payload = row["payload_json"] if isinstance(row, sqlite3.Row) else row[1]
        try:
            payload = json.loads(raw_payload or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(payload, Mapping):
            continue
        for item in _iter_nested_mappings(payload):
            if str(item.get("task_id") or "").strip() != task_id:
                continue
            backlog_id = str(item.get("backlog_id") or "").strip()
            if not backlog_id:
                continue
            return {
                "source": "task_timeline_events.mf_batch_parallel.entered",
                "source_event_id": int(row["id"] if isinstance(row, sqlite3.Row) else row[0]),
                "expected_backlog_id": backlog_id,
                "task_id": task_id,
                "merge_queue_id": str(item.get("merge_queue_id") or "").strip(),
                "queue_item_id": str(item.get("queue_item_id") or "").strip(),
                "queue_index": int(item.get("queue_index") or 0),
            }
    return {}


def _multi_backlog_task_binding(
    conn: sqlite3.Connection,
    *,
    project_id: str,
    task_id: str,
) -> dict[str, Any]:
    task = str(task_id or "").strip()
    if not task:
        return {}
    try:
        from .parallel_branch_runtime import ensure_branch_runtime_schema

        ensure_branch_runtime_schema(conn)
        row = conn.execute(
            """
            SELECT merge_queue_id, queue_item_id, backlog_id, task_id, queue_index
            FROM parallel_branch_merge_queue_items
            WHERE project_id = ? AND task_id = ? AND backlog_id <> ''
            ORDER BY updated_at DESC, queue_index DESC, queue_item_id DESC
            LIMIT 1
            """,
            (project_id, task),
        ).fetchone()
    except sqlite3.OperationalError as exc:
        if "no such table" in str(exc).lower() or "no such column" in str(exc).lower():
            row = None
        else:
            raise
    if row:
        return {
            "source": "parallel_branch_merge_queue_items",
            "expected_backlog_id": str(row["backlog_id"] or ""),
            "task_id": str(row["task_id"] or ""),
            "merge_queue_id": str(row["merge_queue_id"] or ""),
            "queue_item_id": str(row["queue_item_id"] or ""),
            "queue_index": int(row["queue_index"] or 0),
        }
    return _multi_backlog_task_binding_from_timeline(
        conn,
        project_id=project_id,
        task_id=task,
    )


def _multi_backlog_task_binding_mismatch(
    conn: sqlite3.Connection,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
) -> dict[str, Any]:
    received = str(backlog_id or "").strip()
    task = str(task_id or "").strip()
    if not received or not task:
        return {}
    binding = _multi_backlog_task_binding(conn, project_id=project_id, task_id=task)
    expected = str(binding.get("expected_backlog_id") or "").strip()
    if not expected or expected == received:
        return {}
    return {
        "ok": False,
        "error": "task_backlog_binding_mismatch",
        "message": "task_id is already bound to a different multi-backlog row",
        "schema_version": "multi_backlog_task_backlog_binding_gate.v1",
        "project_id": project_id,
        "task_id": task,
        "expected_backlog_id": expected,
        "received_backlog_id": received,
        "merge_queue_id": str(binding.get("merge_queue_id") or ""),
        "queue_item_id": str(binding.get("queue_item_id") or ""),
        "queue_index": int(binding.get("queue_index") or 0),
        "binding_source": str(binding.get("source") or ""),
        "source_event_id": int(binding.get("source_event_id") or 0),
        "next_action": "use the backlog_id bound to this task_id or allocate a distinct task_id",
    }


def _observer_route_context_issue_safe_actual(
    value: Any,
    *,
    missing: bool = False,
) -> Any:
    """Describe rejected route-issue input without reflecting caller secrets."""

    if missing or value is None:
        return {"present": False, "type": "missing"}
    if isinstance(value, str):
        return {
            "present": True,
            "type": "string",
            "non_empty": bool(value.strip()),
        }
    if isinstance(value, list):
        return {
            "present": True,
            "type": "list",
            "item_count": len(value),
        }
    if isinstance(value, Mapping):
        return {
            "present": True,
            "type": "object",
            "field_count": len(value),
        }
    return {
        "present": True,
        "type": type(value).__name__,
    }


def _observer_route_context_issue_declared_target_files(
    *,
    project_id: str,
    backlog_id: str,
) -> list[str]:
    """Read the row-declared file scope for a host-correctable rejection."""

    if not project_id or not backlog_id:
        return []
    conn = get_connection(project_id)
    try:
        return _backlog_declared_direct_file_scope(conn, backlog_id)
    finally:
        conn.close()


def _observer_route_context_issue_rejection(
    *,
    status: int,
    project_id: str,
    body: Mapping[str, Any],
    error: str,
    field: str,
    expected: Any,
    actual: Any,
    source_gate: str,
    guide_target_files: Sequence[str] | None = None,
    correction_overrides: Mapping[str, Any] | None = None,
    required_replacements: Sequence[str] | None = None,
) -> tuple[int, dict[str, Any]]:
    """Return one public, deterministic, fail-closed route-issue correction.

    Rejections from this helper occur before token creation or ref persistence.
    The guide copies only route-issuance fields, never arbitrary request keys or
    raw route/session credentials.  Unresolved required values remain guarded
    by values that the issuance facade itself rejects, so copying a partial
    guide cannot accidentally mint a widened route.
    """

    backlog_id = str(body.get("backlog_id") or body.get("bug_id") or "").strip()
    task_id = str(body.get("task_id") or "").strip()
    raw_target_files = (
        body.get("target_files")
        if "target_files" in body
        else body.get("owned_files")
    )
    target_files = [
        str(path).strip()
        for path in (
            list(guide_target_files)
            if guide_target_files is not None
            else raw_target_files
            if isinstance(raw_target_files, list)
            else []
        )
        if str(path or "").strip()
    ]
    raw_allowed_actions = body.get("allowed_actions")
    allowed_actions = (
        [
            str(action).strip()
            for action in raw_allowed_actions
            if str(action or "").strip()
        ]
        if isinstance(raw_allowed_actions, list)
        else []
    )
    unresolved_fields: list[str] = []
    if not backlog_id:
        unresolved_fields.append("backlog_id")
    if not task_id:
        unresolved_fields.append("task_id")
    if not target_files:
        unresolved_fields.append("target_files")
    if raw_allowed_actions is not None and (
        not isinstance(raw_allowed_actions, list) or not allowed_actions
    ):
        unresolved_fields.append("allowed_actions")
    for replacement in required_replacements or ():
        replacement_field = str(replacement or "").strip()
        if replacement_field and replacement_field not in unresolved_fields:
            unresolved_fields.append(replacement_field)

    corrected_body: dict[str, Any] = {
        "project_id": str(project_id or "").strip(),
        "caller_role": "observer",
        "backlog_id": backlog_id,
        "task_id": task_id,
        "target_files": target_files,
    }
    if raw_allowed_actions is not None:
        # A wildcard is intentionally used as a fail-closed replacement when
        # the caller supplied an invalid type.  It must be replaced with the
        # exact action grants before the guide becomes copy-ready.
        corrected_body["allowed_actions"] = (
            allowed_actions if allowed_actions else ["*"]
        )
    raw_evidence_refs = body.get("evidence_refs")
    if raw_evidence_refs is not None:
        # Evidence refs are optional.  Invalid or arbitrary caller values are
        # not reflected; an empty list is a safe correction.
        corrected_body["evidence_refs"] = []
    if correction_overrides:
        corrected_body.update(dict(correction_overrides))

    guide = {
        "schema_version": (
            "observer_route_context_issue.host_correction_guide.v1"
        ),
        "semantic_next_action": "observer_route_context_issue",
        "mcp_tool": "observer_route_context_issue",
        "http_entrypoint": {
            "method": "POST",
            "path": "/api/projects/{project_id}/observer/route-context/issue",
            "path_params": {"project_id": str(project_id or "").strip()},
        },
        "observer_route_context_issue_body": corrected_body,
        "correction_ready": not unresolved_fields,
        "required_replacements": unresolved_fields,
        "field_descriptions": {
            "caller_role": "exact literal observer",
            "backlog_id": "authorization backlog row id",
            "task_id": "authorization task or contract execution id",
            "target_files": (
                "non-empty exact row-declared or operation-owned file list; "
                "never invent a path merely to mint a route"
            ),
            "allowed_actions": (
                "optional non-empty exact action grants; replace the fail-closed "
                "wildcard when listed in required_replacements"
            ),
            "evidence_refs": "optional list of durable public evidence refs",
        },
        "target_files_source": (
            "backlog_bugs.target_files+test_files"
            if guide_target_files is not None
            else "validated request target_files/owned_files"
        ),
        "copy_rule": (
            "Copy only the projected body. Replace every required_replacements "
            "field from row/operation authority before retrying; never copy or "
            "persist a raw route token or observer session token."
        ),
        "route_issued": False,
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
        "raw_observer_session_token_required": False,
        "raw_observer_session_token_exposed": False,
        "public_safe": True,
        "secret_safe": True,
        "source": (
            "agent/governance/server.py::"
            f"handle_observer_route_context_issue.{source_gate}"
        ),
    }
    return status, {
        "ok": False,
        "error": error,
        "field": field,
        "expected": expected,
        "actual": actual,
        "guide": guide,
        "source": guide["source"],
        "fail_closed": True,
        "zero_write_rejection": True,
        "writes_performed": False,
        "mutation_performed": False,
        "route_issued": False,
        "route_token_ref_registered": False,
        "retry_same_world_allowed": True,
        "public_safe": True,
        "secret_safe": True,
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
        "raw_observer_session_token_required": False,
        "raw_observer_session_token_exposed": False,
    }


@route("POST", "/api/projects/{project_id}/observer/route-context/issue")
def handle_observer_route_context_issue(ctx: RequestContext):
    """Mint an Aming-owned, write-authorizing observer route token.

    This is the native counterpart to the read-only observer repair-run route
    context: it returns a route token that passes
    ``validate_route_token_mutation_gate`` (decision ``route_token``) for the
    observer's protected write actions, plus a consumable ``route_token_ref``
    and ``merge_queue_id`` (and a ready ``execute_backlog_row_payload``), without
    depending on any external route provider at runtime.
    """

    project_id = ctx.get_project_id()
    body = ctx.body if isinstance(ctx.body, dict) else {}
    canonical_final_authority: Mapping[str, Any] | None = None
    try:
        request_kind = _observer_route_context_issue_request_kind(body)
    except ValueError as exc:
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error=str(exc),
            field="request_kind",
            expected="one closed canonical-adoption or Direct-bootstrap request shape",
            actual={"canonical_ref_adoption_present": "canonical_ref_adoption" in body},
            source_gate="request_kind_discriminator",
        )

    # Canonical-ref adoption is the one route kind whose authority may not be
    # self-declared in the request.  Convert its three references into the
    # normal issuer shape only after session/CEX/QA/route verification.
    if request_kind == "canonical_ref_adoption":
        try:
            body = _canonical_ref_adoption_server_issue_body(
                ctx, project_id=project_id, body=body,
            )
            candidate_final_authority = body.pop(
                "__canonical_ref_adoption_final_authority__", None
            )
            if not isinstance(candidate_final_authority, Mapping):
                raise ValueError("canonical_ref_adoption final authority is missing")
            canonical_final_authority = dict(candidate_final_authority)
        except (ValueError, PermissionError) as exc:
            return _observer_route_context_issue_rejection(
                status=403, project_id=project_id, body=body,
                error=str(exc), field="canonical_ref_adoption",
                expected="authenticated session + route + CEX + QA Fact references",
                actual={"present": True}, source_gate="canonical_ref_adoption_authority",
            )

    # Canonical adoption has already crossed its strict authority gate above.
    # Keep the ordinary dev bootstrap behaviour for every other issue shape,
    # but never permit that shortcut to preempt canonical QA validation.
    if _runtime_plane() == "dev":
        if request_kind == "completed_source_free_system_operation":
            return _handle_ac_dev_completed_source_free_route_context_issue(
                ctx,
                project_id=project_id,
                body=body,
            )
        if request_kind == "direct_bootstrap":
            return _handle_ac_dev_direct_route_context_issue(
                ctx,
                project_id=project_id,
                body=body,
            )

    # Authorization: this endpoint mints a WRITE-authorizing route token, so the
    # caller must declare the observer role. The shared operator gate does not
    # cleanly apply here — in token-free mode anonymous callers get a coordinator
    # session, which would let any caller mint write tokens — so we require an
    # explicit caller_role == "observer" (body, or the X-Caller-Role header the
    # request may carry) and reject everything else with 403. This mirrors the
    # token's own CALLER_ROLE ("observer").
    try:
        header_role = str(ctx.handler.headers.get("X-Caller-Role", "") or "").strip()
    except Exception:
        header_role = ""
    caller_role = str(body.get("caller_role") or header_role or "").strip().lower()
    if caller_role != "observer":
        return _observer_route_context_issue_rejection(
            status=403,
            project_id=project_id,
            body=body,
            error=(
                "caller_role must be 'observer' to issue a write-authorizing "
                "route token"
            ),
            field="caller_role",
            expected="observer",
            actual=_observer_route_context_issue_safe_actual(
                body.get("caller_role") or header_role,
                missing=not bool(body.get("caller_role") or header_role),
            ),
            source_gate="caller_role",
        )

    backlog_id = str(body.get("backlog_id") or body.get("bug_id") or "").strip()
    task_id = str(body.get("task_id") or "").strip()
    target_files = (
        body.get("target_files")
        if "target_files" in body
        else body.get("owned_files") or []
    )
    if target_files is None:
        target_files = []
    if not isinstance(target_files, list):
        guide_target_files = (
            _observer_route_context_issue_declared_target_files(
                project_id=project_id,
                backlog_id=backlog_id,
            )
        )
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error="target_files must be a list of file paths",
            field="target_files",
            expected={"type": "list", "min_items": 1},
            actual=_observer_route_context_issue_safe_actual(target_files),
            source_gate="target_files_type",
            guide_target_files=guide_target_files,
        )
    if not backlog_id:
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error="backlog_id is required",
            field="backlog_id",
            expected={"type": "string", "non_empty": True},
            actual=_observer_route_context_issue_safe_actual(
                body.get("backlog_id") or body.get("bug_id"),
                missing=True,
            ),
            source_gate="backlog_id_required",
        )
    if not task_id:
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error="task_id is required",
            field="task_id",
            expected={"type": "string", "non_empty": True},
            actual=_observer_route_context_issue_safe_actual(
                body.get("task_id"), missing=True
            ),
            source_gate="task_id_required",
        )
    if not target_files:
        guide_target_files = (
            _observer_route_context_issue_declared_target_files(
                project_id=project_id,
                backlog_id=backlog_id,
            )
        )
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error="target_files must be a non-empty list of file paths",
            field="target_files",
            expected={"type": "list", "min_items": 1},
            actual=_observer_route_context_issue_safe_actual(target_files),
            source_gate="target_files_non_empty",
            guide_target_files=guide_target_files,
        )

    conn = get_connection(project_id)
    try:
        binding_mismatch = _multi_backlog_task_binding_mismatch(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
        )
    finally:
        conn.close()
    if binding_mismatch:
        return 409, binding_mismatch

    allowed_actions = body.get("allowed_actions")
    if allowed_actions is not None and not isinstance(allowed_actions, list):
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error="allowed_actions must be a list",
            field="allowed_actions",
            expected={"type": "list", "min_items": 1},
            actual=_observer_route_context_issue_safe_actual(allowed_actions),
            source_gate="allowed_actions_type",
        )
    allowed_actions = _observer_route_context_issue_allowed_actions(allowed_actions)
    try:
        canonical_ref_adoption = _canonical_ref_adoption_issue_intent(
            body.get("canonical_ref_adoption"),
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            allowed_actions=allowed_actions,
        )
    except ValueError as exc:
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error=str(exc),
            field="canonical_ref_adoption",
            expected="server-validated canonical_ref_adoption_route_bound.v1",
            actual=_observer_route_context_issue_safe_actual(body.get("canonical_ref_adoption")),
            source_gate="canonical_ref_adoption_scope",
        )
    # A pre-issue lookup is diagnostic only.  The complete typed token claims
    # its replay identity in the registry's single BEGIN IMMEDIATE transaction.
    evidence_refs = body.get("evidence_refs")
    if evidence_refs is not None and not isinstance(evidence_refs, list):
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error="evidence_refs must be a list",
            field="evidence_refs",
            expected={"type": "list"},
            actual=_observer_route_context_issue_safe_actual(evidence_refs),
            source_gate="evidence_refs_type",
        )

    parent_route_identity = body.get("parent_route_identity")
    if parent_route_identity is not None and not isinstance(parent_route_identity, Mapping):
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error="parent_route_identity must be an object",
            field="parent_route_identity",
            expected={"type": "object"},
            actual=_observer_route_context_issue_safe_actual(
                parent_route_identity
            ),
            source_gate="parent_route_identity_type",
        )
    raw_parent_fields = (
        "parent_route_token",
        "parent_raw_route_token",
        "parent_token",
        "parent_token_body",
        "parent_session_token",
    )
    for field in raw_parent_fields:
        if field in body:
            return _observer_route_context_issue_rejection(
                status=400,
                project_id=project_id,
                body=body,
                error=(
                    "parent route identity must not include raw route/session "
                    "token fields"
                ),
                field=field,
                expected={"present": False},
                actual={"present": True, "value_redacted": True},
                source_gate="raw_parent_credential_refused",
            )
    parent_identity_fields = (
        "parent_route_id",
        "parent_route_context_hash",
        "parent_prompt_contract_id",
        "parent_prompt_contract_hash",
        "parent_visible_injection_manifest_hash",
        "parent_route_token_ref",
    )
    parent_identity_args: dict[str, str] = {}
    for field in parent_identity_fields:
        value = body.get(field, "")
        if value is None:
            value = ""
        if not isinstance(value, str):
            return _observer_route_context_issue_rejection(
                status=400,
                project_id=project_id,
                body=body,
                error=f"{field} must be a string",
                field=field,
                expected={"type": "string"},
                actual=_observer_route_context_issue_safe_actual(value),
                source_gate="parent_identity_field_type",
            )
        parent_identity_args[field] = value.strip()

    try:
        ttl_hours = float(body.get("ttl_hours", 24))
    except (TypeError, ValueError):
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error="ttl_hours must be a number",
            field="ttl_hours",
            expected={"type": "number", "exclusive_minimum": 0},
            actual=_observer_route_context_issue_safe_actual(
                body.get("ttl_hours")
            ),
            source_gate="ttl_hours_type",
            correction_overrides={"ttl_hours": 24},
        )

    issue_now = datetime.now(timezone.utc).replace(microsecond=0)
    if canonical_ref_adoption is not None:
        canonical_ref_adoption = _canonical_ref_adoption_bind_issued_intent(
            canonical_ref_adoption,
            issued_at=issue_now,
            expires_at=issue_now + timedelta(hours=ttl_hours),
        )

    try:
        from . import observer_route_context

        project_root = None
        try:
            project_root = _graph_governance_project_root(project_id, body)
        except Exception:
            project_root = None

        issued = observer_route_context.issue_observer_write_route_context(
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            target_files=target_files,
            allowed_actions=allowed_actions,
            ttl_hours=ttl_hours,
            now=issue_now,
            evidence_refs=evidence_refs,
            project_root=project_root,
            parent_route_identity=parent_route_identity,
            canonical_ref_adoption=canonical_ref_adoption,
            **parent_identity_args,
        )
        issued_token = issued.get("route_token")
        if isinstance(issued_token, dict):
            owned_scope = body.get("owned_files") if isinstance(body.get("owned_files"), list) else target_files
            issued_token.setdefault(
                "owned_files",
                [str(path).strip() for path in owned_scope if str(path or "").strip()],
            )
    except ValueError as exc:
        message = str(exc)
        value_field = (
            "allowed_actions"
            if message.startswith("allowed_actions")
            else "target_files"
            if message.startswith("target_files")
            else "ttl_hours"
            if message.startswith("ttl_hours")
            else "parent_route_identity"
            if "parent" in message
            else "request"
        )
        return _observer_route_context_issue_rejection(
            status=400,
            project_id=project_id,
            body=body,
            error=message,
            field=value_field,
            expected="server-validated observer route issuance input",
            actual=_observer_route_context_issue_safe_actual(
                body.get(value_field), missing=value_field not in body
            ),
            source_gate="route_input_validation",
            guide_target_files=(
                _observer_route_context_issue_declared_target_files(
                    project_id=project_id,
                    backlog_id=backlog_id,
                )
                if value_field == "target_files"
                else None
            ),
            correction_overrides=(
                {"ttl_hours": 24} if value_field == "ttl_hours" else None
            ),
            required_replacements=(
                ["allowed_actions"]
                if value_field == "allowed_actions"
                else []
            ),
        )
    except Exception as exc:  # pragma: no cover - defensive
        return 400, {"ok": False, "error": f"route token issuance failed: {exc}"}

    # A superseded route ref cannot be renewed directly.  When the caller uses
    # the server-provided same-scope issue recovery, bind the fresh child to the
    # exact inactive parent and prove that no action/file/task scope widened.
    # The proof is persisted with the child and survives the later active-
    # session renewal consumed by runtime-context initial_join.
    try:
        conn = get_connection(project_id)
        try:
            observer_route_context.attach_same_scope_reissue_proof(
                conn,
                project_id=project_id,
                storage_project_id=_route_registry_storage_project_id(project_id),
                route_token_ref=str(issued.get("route_token_ref") or ""),
                token=issued["route_token"],
            )
        finally:
            conn.close()
    except observer_route_context.RouteTokenRefError as exc:
        return 409, {
            "ok": False,
            "error": exc.code,
            "message": str(exc),
            "details": dict(exc.details or {}),
            "next_legal_action": (
                "retry_observer_route_context_issue_with_the_exact_"
                "server_provided_same_scope_payload"
            ),
            "fail_closed": True,
        }

    # Persist the ref→token-digest mapping so gate resolution can work without
    # the caller re-supplying the full token body.  Failure is non-fatal for the
    # HTTP response (the caller still receives the full token and can use the
    # full-token path), but we log a warning in the payload.
    ref_persist_warning: str = ""
    try:
        conn = get_connection(project_id)
        try:
            final_revalidator = None
            if canonical_ref_adoption is not None:
                if canonical_final_authority is None:
                    raise ValueError("canonical_ref_adoption final authority is missing")

                def final_revalidator(
                    writer_conn: sqlite3.Connection,
                    writer_token: Mapping[str, Any],
                ) -> None:
                    _canonical_ref_adoption_revalidate_in_writer(
                        writer_conn,
                        project_id=project_id,
                        authority=canonical_final_authority,
                        token=writer_token,
                    )

            observer_route_context.persist_route_token_ref(
                conn,
                project_id=project_id,
                storage_project_id=_route_registry_storage_project_id(project_id),
                route_token_ref=issued["route_token_ref"],
                token=issued["route_token"],
                canonical_adoption_authority_revalidator=final_revalidator,
            )
        finally:
            conn.close()
    except Exception as exc:  # pragma: no cover - defensive
        if canonical_ref_adoption is not None:
            # Unlike ordinary advisory ref registration, this registry write is
            # the adoption route's unique issuance claim.  Returning a token
            # after it loses that claim would create an unverifiable route.
            return _observer_route_context_issue_rejection(
                status=409,
                project_id=project_id,
                body=body,
                error=f"canonical_ref_adoption route persistence failed: {exc}",
                field="canonical_ref_adoption",
                expected="one durable server-issued canonical_ref_adoption lifecycle",
                actual=_observer_route_context_issue_safe_actual(
                    body.get("canonical_ref_adoption")
                ),
                source_gate="canonical_ref_adoption_atomic_persist",
            )
        ref_persist_warning = f"route_token_ref persist failed (ref-resolution disabled): {exc}"

    route_token = issued["route_token"]
    route_identity = {
        key: str(route_token.get(key) or "")
        for key in (
            "route_id",
            "route_context_hash",
            "prompt_contract_id",
            "prompt_contract_hash",
            "visible_injection_manifest_hash",
        )
        if str(route_token.get(key) or "").strip()
    }
    route_identity["route_token_ref"] = str(issued.get("route_token_ref") or "")

    response: dict = {
        "ok": True,
        "project_id": project_id,
        "route_token": route_token,
        "route_token_ref": issued["route_token_ref"],
        "route_identity": route_identity,
        "canonical_route_identity": dict(route_identity),
        "merge_queue_id": issued["merge_queue_id"],
        "execute_backlog_row_payload": issued["execute_backlog_row_payload"],
        "provider": issued.get("provider", {}),
        "ref_registered": not bool(ref_persist_warning),
        "merge_queue_id_diagnostics": {
            "schema_version": (
                "observer_route_context_issue.merge_queue_id_diagnostics.v1"
            ),
            "merge_queue_id": str(issued.get("merge_queue_id") or ""),
            "merge_queue_id_scope": "route_issue_response_only",
            "runtime_context_merge_queue_id_authoritative": True,
            "newly_minted_route_token_merge_queue_id_allowed_for_batch_merge": False,
            "message": (
                "If this differs from runtime_context.current_values.merge_queue_id, "
                "keep the runtime-context merge_queue_id for mf_batch durable merge "
                "materialization/apply semantics."
            ),
        },
    }
    if canonical_ref_adoption is not None:
        response["canonical_ref_adoption_intent"] = {
            "schema_version": _CANONICAL_REF_ADOPTION_SCHEMA,
            "route_token_ref": issued["route_token_ref"],
            "canonical_ref_adoption": dict(canonical_ref_adoption),
        }
    for key, value in route_identity.items():
        response.setdefault(key, value)
    for key in ("parent_route_lineage", "child_route_lineage", "route_lineage"):
        value = issued.get(key)
        if isinstance(value, Mapping):
            response[key] = dict(value)
    if ref_persist_warning:
        response["ref_persist_warning"] = ref_persist_warning
    return response


@route("POST", "/api/projects/{project_id}/observer/route-context/renew")
def handle_observer_route_context_renew(ctx: RequestContext):
    """Renew an expired/near-expired same-scope route_token_ref."""

    project_id = ctx.get_project_id()
    body = ctx.body if isinstance(ctx.body, dict) else {}
    if _runtime_plane() == "dev":
        return _handle_ac_dev_direct_route_context_renew(
            ctx,
            project_id=project_id,
            body=body,
        )
    try:
        header_role = str(ctx.handler.headers.get("X-Caller-Role", "") or "").strip()
    except Exception:
        header_role = ""
    caller_role = str(body.get("caller_role") or header_role or "").strip().lower()
    if caller_role != "observer":
        return 403, {
            "ok": False,
            "error": "caller_role must be 'observer' to renew a route_token_ref",
        }

    observer_session_id = str(
        body.get("observer_session_id") or body.get("observer_session_ref") or ""
    ).strip()
    route_token_ref = str(
        body.get("route_token_ref") or body.get("observer_route_token_ref") or ""
    ).strip()
    backlog_id = str(body.get("backlog_id") or body.get("bug_id") or "").strip()
    task_id = str(body.get("task_id") or body.get("contract_execution_id") or "").strip()
    missing = [
        field
        for field, value in (
            ("observer_session_id", observer_session_id),
            ("route_token_ref", route_token_ref),
            ("backlog_id", backlog_id),
            ("task_id", task_id),
        )
        if not value
    ]
    if missing:
        return 400, {
            "ok": False,
            "error": "route_token_ref renewal is missing required fields",
            "missing_fields": missing,
            "next_action": _observer_route_context_renewal_guidance(
                project_id=project_id,
                backlog_id=backlog_id,
                task_id=task_id,
                route_token_ref=route_token_ref,
                observer_session_id=observer_session_id,
                reason="missing_required_fields",
            ),
            "raw_route_token_required": False,
            "raw_route_token_exposed": False,
        }

    allowed_actions = body.get("allowed_actions")
    if allowed_actions is not None and not isinstance(allowed_actions, list):
        return 400, {"ok": False, "error": "allowed_actions must be a list"}
    allowed_actions = _observer_route_context_issue_allowed_actions(allowed_actions)
    target_files = body.get("target_files")
    if target_files is not None and not isinstance(target_files, list):
        return 400, {"ok": False, "error": "target_files must be a list"}
    owned_files = body.get("owned_files")
    if owned_files is not None and not isinstance(owned_files, list):
        return 400, {"ok": False, "error": "owned_files must be a list"}
    evidence_refs = body.get("evidence_refs")
    if evidence_refs is not None and not isinstance(evidence_refs, list):
        return 400, {"ok": False, "error": "evidence_refs must be a list"}
    try:
        ttl_hours = float(body.get("ttl_hours", 24))
    except (TypeError, ValueError):
        return 400, {"ok": False, "error": "ttl_hours must be a number"}

    from . import observer_route_context

    try:
        renew_within_seconds = int(
            body.get(
                "renew_within_seconds",
                observer_route_context.ROUTE_TOKEN_REF_RENEW_WITHIN_SECONDS,
            )
        )
    except (TypeError, ValueError):
        return 400, {"ok": False, "error": "renew_within_seconds must be an integer"}

    conn = get_connection(project_id)
    try:
        session = observer_session.get_session(
            conn,
            project_id=project_id,
            session_id=observer_session_id,
        )
        if not session or str(session.get("computed_status") or "") != "active":
            return 403, {
                "ok": False,
                "error": "active observer_session_id is required to renew route_token_ref",
                "observer_session_id": observer_session_id,
                "next_action": _observer_session_renewal_gate_guidance(
                    project_id=project_id,
                    observer_session_id=observer_session_id,
                    route_token_ref=route_token_ref,
                ),
                "raw_route_token_required": False,
                "raw_route_token_exposed": False,
            }
        project_root = None
        try:
            project_root = _graph_governance_project_root(project_id, body)
        except Exception:
            project_root = None
        renewed = observer_route_context.renew_route_token_ref(
            conn,
            project_id=project_id,
            storage_project_id=_route_registry_storage_project_id(project_id),
            route_token_ref=route_token_ref,
            backlog_id=backlog_id,
            task_id=task_id,
            caller_role=caller_role,
            allowed_actions=allowed_actions,
            target_files=target_files,
            owned_files=owned_files,
            ttl_hours=ttl_hours,
            renew_within_seconds=renew_within_seconds,
            evidence_refs=evidence_refs,
            project_root=project_root,
        )
    except observer_route_context.RouteTokenRefError as exc:
        return 422, {
            "ok": False,
            "error": str(exc),
            **_route_token_ref_error_details(
                exc,
                project_id=project_id,
                backlog_id=backlog_id,
                task_id=task_id,
                route_token_ref=route_token_ref,
                observer_session_id=observer_session_id,
            ),
        }
    except ValueError as exc:
        return 400, {"ok": False, "error": str(exc)}
    finally:
        conn.close()
    return renewed


@route("GET", "/api/projects/{project_id}/project-inbox")
def handle_project_inbox(ctx: RequestContext):
    project_id = ctx.get_project_id()
    conn = get_connection(project_id)
    backlog_lanes = _project_inbox_backlog_lanes(conn, project_id=project_id)
    raw_rows = raw_requirement.list_raw_requirements(
        conn,
        project_id=project_id,
        status=raw_requirement.STATUS_RAW_INBOX,
        limit=50,
    )
    confirmation_rows = raw_requirement.list_raw_requirements(
        conn,
        project_id=project_id,
        status=raw_requirement.STATUS_NEEDS_CONFIRMATION,
        limit=50,
    )
    counts = raw_requirement.lane_counts(conn, project_id=project_id)
    return {
        "ok": True,
        "project_id": project_id,
        "homepage_view": "project_inbox",
        "observer": observer_session.connection_summary(conn, project_id=project_id),
        "observer_commands": observer_session.command_summary(conn, project_id=project_id),
        "lanes": {
            "raw_inbox": {
                "count": counts.get(raw_requirement.STATUS_RAW_INBOX, 0),
                "items": raw_rows,
            },
            "needs_confirmation": {
                "count": counts.get(raw_requirement.STATUS_NEEDS_CONFIRMATION, 0),
                "items": confirmation_rows,
            },
            "ready_backlog": backlog_lanes["ready_backlog"],
            "in_progress": backlog_lanes["in_progress"],
            "review_needed": backlog_lanes["review_needed"],
            "done": backlog_lanes["done"],
        },
    }


def _project_inbox_backlog_sources(
    conn: sqlite3.Connection,
    *,
    project_id: str,
) -> dict[str, dict]:
    """Return source-backed request text for Project Inbox backlog rows.

    Backlog title/details are implementation summaries, not the user's original
    wording. Simple Mode can show a request excerpt only when it can trace the
    backlog row back to a raw requirement or an inbox command payload.
    """
    sources: dict[str, dict] = {}
    ids: set[str] = set()
    pid = (project_id or "").strip()
    if not pid:
        return sources
    try:
        rows = conn.execute(
            """
            SELECT raw_id, raw_text, source, promoted_bug_id
            FROM raw_requirements
            WHERE project_id = ? AND promoted_bug_id <> ''
            """,
            (pid,),
        ).fetchall()
    except sqlite3.OperationalError as exc:
        if "no such table" in str(exc).lower():
            rows = []
        else:
            raise
    for row in rows:
        data = dict(row)
        bug_id = str(data.get("promoted_bug_id") or "").strip()
        if not bug_id:
            continue
        ids.add(bug_id)
        sources[bug_id] = {
            "source_raw_id": str(data.get("raw_id") or ""),
            "original_request_excerpt": _compact_preview(data.get("raw_text", ""), limit=240),
            "original_request_source": str(data.get("source") or "raw_requirement"),
            "original_request_missing": False,
            "original_request_missing_reason": "",
        }

    try:
        command_rows = conn.execute(
            "SELECT payload_json FROM observer_command_queue WHERE project_id = ?",
            (pid,),
        ).fetchall()
    except sqlite3.OperationalError as exc:
        if "no such table" in str(exc).lower():
            command_rows = []
        else:
            raise
    for row in command_rows:
        payload_raw = row["payload_json"] if isinstance(row, sqlite3.Row) else row[0]
        try:
            payload = json.loads(payload_raw or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        source = str(payload.get("source") or "").strip()
        if source not in {"project_inbox", "dashboard_project_inbox"}:
            continue
        for key in ("bug_id", "backlog_id", "promoted_bug_id"):
            value = str(payload.get(key) or "").strip()
            if value:
                ids.add(value)
                raw_id = str(payload.get("raw_id") or "").strip()
                source_info = {
                    "source_raw_id": raw_id,
                    "original_request_excerpt": "",
                    "original_request_source": source,
                    "original_request_missing": True,
                    "original_request_missing_reason": "No linked raw request text was found for this work item.",
                }
                if raw_id:
                    try:
                        raw_row = conn.execute(
                            """
                            SELECT raw_text, source
                            FROM raw_requirements
                            WHERE project_id = ? AND raw_id = ?
                            """,
                            (pid, raw_id),
                        ).fetchone()
                    except sqlite3.OperationalError as exc:
                        if "no such table" in str(exc).lower():
                            raw_row = None
                        else:
                            raise
                    if raw_row:
                        raw_data = dict(raw_row)
                        source_info.update(
                            {
                                "original_request_excerpt": _compact_preview(
                                    raw_data.get("raw_text", ""),
                                    limit=240,
                                ),
                                "original_request_source": str(
                                    raw_data.get("source") or source
                                ),
                                "original_request_missing": False,
                                "original_request_missing_reason": "",
                            }
                        )
                sources.setdefault(
                    value,
                    source_info,
                )
    if ids:
        for bug_id in ids:
            sources.setdefault(
                bug_id,
                {
                    "source_raw_id": "",
                    "original_request_excerpt": "",
                    "original_request_source": "project_inbox",
                    "original_request_missing": True,
                    "original_request_missing_reason": "No linked raw request text was found for this work item.",
                },
            )
    return sources


def _project_inbox_backlog_ids(conn: sqlite3.Connection, *, project_id: str) -> set[str]:
    """Return backlog ids explicitly associated with the ordinary Project Inbox path."""
    return set(_project_inbox_backlog_sources(conn, project_id=project_id))


def _project_inbox_backlog_lanes(
    conn: sqlite3.Connection,
    *,
    project_id: str,
    item_limit: int = 50,
) -> dict[str, dict]:
    """Build operator-facing backlog lanes for the Project Inbox homepage."""
    lanes = {
        "ready_backlog": {"count": 0, "items": [], "source": "backlog"},
        "in_progress": {"count": 0, "items": [], "source": "backlog"},
        "review_needed": {"count": 0, "items": [], "source": "backlog"},
        "done": {"count": 0, "items": [], "source": "backlog"},
    }
    source_by_bug_id = _project_inbox_backlog_sources(conn, project_id=project_id)
    associated_bug_ids = set(source_by_bug_id)
    if not associated_bug_ids:
        return lanes
    placeholders = ", ".join("?" for _ in associated_bug_ids)
    try:
        rows = conn.execute(
            f"SELECT * FROM backlog_bugs WHERE bug_id IN ({placeholders}) ORDER BY created_at DESC",
            tuple(sorted(associated_bug_ids)),
        ).fetchall()
    except sqlite3.OperationalError as exc:
        if "no such table" in str(exc).lower():
            return lanes
        raise

    def add(lane: str, item: dict) -> None:
        bucket = lanes[lane]
        bucket["count"] += 1
        if len(bucket["items"]) < item_limit:
            bucket["items"].append(item)

    for row in rows:
        raw = dict(row)
        bug = _backlog_compact_bug(row)
        bug["kind"] = "backlog"
        bug.update(source_by_bug_id.get(str(raw.get("bug_id") or ""), {}))
        status = str(raw.get("status") or "OPEN").upper()
        runtime_state = str(raw.get("runtime_state") or "").strip().lower()
        chain_stage = str(raw.get("chain_stage") or "").strip().lower()
        current_task_id = str(raw.get("current_task_id") or "").strip()
        failure_reason = str(raw.get("last_failure_reason") or "").strip()

        if status in _BACKLOG_CLOSED_STATUSES:
            add("done", bug)
        elif status in {"REVIEW", "QA", "READY_FOR_REVIEW", "VERIFY", "VERIFICATION"}:
            add("review_needed", bug)
        elif runtime_state in {"blocked", "failed"} or failure_reason:
            add("review_needed", bug)
        elif runtime_state or chain_stage or current_task_id:
            add("in_progress", bug)
        else:
            add("ready_backlog", bug)
    return lanes


@route("GET", "/api/projects/{project_id}/git-refs")
def handle_project_git_refs(ctx: RequestContext):
    """Return current git branch/ref information for a registered project."""
    project_id = ctx.get_project_id()
    try:
        root = _graph_governance_project_root(project_id, {})
    except Exception as exc:
        return 404, {"error": f"project root not found: {exc}"}
    refs = _git_refs_for_root(root)
    project = project_service.get_project(project_id) or {}
    selected_ref = str(project.get("selected_ref") or "").strip()
