class _QACandidateOverlayError(ValueError):
    def __init__(self, reason: str, message: str, **details: Any):
        super().__init__(message)
        self.reason = str(reason or "candidate_overlay_unsafe")
        self.details = dict(details)


def _qa_overlay_fail(reason: str, message: str, **details: Any) -> None:
    raise _QACandidateOverlayError(reason, message, **details)


def _qa_overlay_identity_mismatches(
    exc: _QACandidateOverlayError,
) -> list[dict[str, Any]]:
    supplied = exc.details.get("identity_mismatches")
    if isinstance(supplied, Sequence) and not isinstance(
        supplied, (str, bytes, bytearray)
    ):
        normalized = [dict(item) for item in supplied if isinstance(item, Mapping)]
        if normalized:
            return normalized
    field = str(exc.details.get("field") or "").strip()
    if field:
        return [
            {
                "field": field,
                "expected": "available full git commit",
                "actual": str(exc.details.get("commit_sha") or ""),
            }
        ]
    if exc.reason == "exact_candidate_comparison_base_not_distinct":
        candidate = str(exc.details.get("candidate_commit_sha") or "")
        return [
            {
                "field": "comparison_base_commit_sha",
                "expected": f"full commit distinct from candidate {candidate}",
                "actual": str(
                    exc.details.get("comparison_base_commit_sha") or ""
                ),
            }
        ]
    if exc.reason == "exact_candidate_comparison_base_not_ancestor":
        candidate = str(exc.details.get("candidate_commit_sha") or "")
        return [
            {
                "field": "comparison_base_commit_sha",
                "expected": f"full ancestor of candidate {candidate}",
                "actual": str(
                    exc.details.get("comparison_base_commit_sha") or ""
                ),
            }
        ]
    return []


def _qa_git_bytes(
    project_root: Path,
    args: Sequence[str],
    *,
    timeout: int = 20,
) -> subprocess.CompletedProcess[bytes]:
    env = dict(os.environ)
    env["LC_ALL"] = "C"
    try:
        return subprocess.run(
            ["git", *[str(item) for item in args]],
            cwd=project_root,
            capture_output=True,
            timeout=timeout,
            check=False,
            env=env,
        )
    except Exception as exc:
        _qa_overlay_fail(
            "git_command_failed",
            f"candidate overlay git command failed: {exc}",
            command=list(args),
        )


def _qa_overlay_normalize_path(raw: bytes | str) -> str:
    try:
        text = raw.decode("utf-8") if isinstance(raw, bytes) else str(raw)
    except UnicodeDecodeError:
        _qa_overlay_fail(
            "non_utf8_git_path_requires_exact_candidate_snapshot",
            "candidate diff contains a non-UTF-8 path",
        )
    path = text.replace("\\", "/").strip("/")
    if not path or path.startswith("../") or "/../" in f"/{path}/" or Path(path).is_absolute():
        _qa_overlay_fail(
            "unsafe_git_path_requires_exact_candidate_snapshot",
            "candidate diff contains an unsafe repository path",
            path=path,
        )
    return path


def _qa_parse_name_status_z(raw: bytes) -> list[dict[str, Any]]:
    fields = raw.split(b"\0")
    if fields and fields[-1] == b"":
        fields.pop()
    changes: list[dict[str, Any]] = []
    index = 0
    while index < len(fields):
        try:
            status_token = fields[index].decode("ascii")
        except UnicodeDecodeError:
            _qa_overlay_fail(
                "invalid_git_status_requires_exact_candidate_snapshot",
                "candidate diff status is not ASCII",
            )
        index += 1
        status = status_token[:1]
        if status not in {"A", "M", "D", "R"}:
            _qa_overlay_fail(
                "unsupported_git_status_requires_exact_candidate_snapshot",
                "candidate diff contains a change type that the bounded overlay cannot model",
                status=status_token,
            )
        if status == "R":
            if index + 1 >= len(fields):
                _qa_overlay_fail(
                    "malformed_rename_requires_exact_candidate_snapshot",
                    "candidate rename record is incomplete",
                )
            old_path = _qa_overlay_normalize_path(fields[index])
            new_path = _qa_overlay_normalize_path(fields[index + 1])
            index += 2
            similarity = int(status_token[1:] or 0)
            changes.append(
                {
                    "status": "R",
                    "path": new_path,
                    "old_path": old_path,
                    "similarity": similarity,
                }
            )
            continue
        if index >= len(fields):
            _qa_overlay_fail(
                "malformed_diff_requires_exact_candidate_snapshot",
                "candidate diff path record is incomplete",
            )
        path = _qa_overlay_normalize_path(fields[index])
        index += 1
        changes.append({"status": status, "path": path, "old_path": ""})
    return changes


def _qa_overlay_deterministic_adapter(path: str) -> Any | None:
    from .language_adapters import (
        JavaScriptTypescriptAdapter,
        PythonAdapter,
        RubyAdapter,
    )
    from .language_policy import DEFAULT_LANGUAGE_POLICY

    if not DEFAULT_LANGUAGE_POLICY.is_source_path(path):
        return None
    return next(
        (
            adapter
            for adapter in (
                PythonAdapter(),
                JavaScriptTypescriptAdapter(),
                RubyAdapter(),
            )
            if adapter.supports(path)
        ),
        None,
    )


def _qa_git_object_source(
    project_root: Path,
    *,
    commit_sha: str,
    path: str,
) -> tuple[str, int, dict[str, Any]]:
    result = _qa_git_bytes(project_root, ["show", f"{commit_sha}:{path}"])
    if result.returncode != 0:
        _qa_overlay_fail(
            "git_blob_missing_requires_exact_candidate_snapshot",
            "candidate overlay could not read a required git blob",
            commit_sha=commit_sha,
            path=path,
        )
    raw = result.stdout
    if b"\0" in raw:
        _qa_overlay_fail(
            "binary_source_requires_exact_candidate_snapshot",
            "candidate overlay cannot safely inspect a binary file",
            path=path,
        )
    try:
        source = raw.decode("utf-8")
    except UnicodeDecodeError:
        _qa_overlay_fail(
            "non_utf8_source_requires_exact_candidate_snapshot",
            "candidate overlay requires UTF-8 source",
            path=path,
        )
    byte_size = len(raw)
    fallback_reason = ""
    adapter = None
    if byte_size > _QA_OVERLAY_MAX_FILE_BYTES:
        if byte_size > _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES:
            _qa_overlay_fail(
                "total_source_limit_requires_exact_candidate_snapshot",
                "candidate overlay source exceeds the elevated bounded inspection limit",
                path=path,
                byte_size=byte_size,
                max_total_bytes=_QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES,
            )
        adapter = _qa_overlay_deterministic_adapter(path)
        if adapter is None:
            _qa_overlay_fail(
                "oversized_source_requires_exact_candidate_snapshot",
                "candidate overlay file exceeds the ordinary per-file limit and has no supported deterministic source adapter",
                path=path,
                byte_size=byte_size,
                max_byte_size=_QA_OVERLAY_MAX_FILE_BYTES,
                fallback_policy=_QA_OVERLAY_OVERSIZED_SOURCE_POLICY,
            )
        fallback_reason = _QA_OVERLAY_OVERSIZED_SOURCE_POLICY
    return source, byte_size, {
        "schema_version": "qa_review_graph.source_inspection.v1",
        "policy": fallback_reason or "ordinary_per_file_bound",
        "fallback_reason": fallback_reason,
        "file_byte_size": byte_size,
        "ordinary_max_file_bytes": _QA_OVERLAY_MAX_FILE_BYTES,
        "ordinary_max_total_bytes": _QA_OVERLAY_MAX_TOTAL_BYTES,
        "elevated_fallback_max_total_bytes": (
            _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
        ),
        "deterministic_language_adapter": (
            str(adapter.language() or "") if adapter is not None else ""
        ),
    }


def _qa_git_object_byte_size(
    project_root: Path,
    *,
    commit_sha: str,
    path: str,
) -> int:
    result = _qa_git_bytes(
        project_root,
        ["cat-file", "-s", f"{commit_sha}:{path}"],
    )
    try:
        byte_size = int(result.stdout.decode("ascii").strip())
    except (UnicodeDecodeError, ValueError):
        byte_size = -1
    if result.returncode != 0 or byte_size < 0:
        _qa_overlay_fail(
            "git_blob_missing_requires_exact_candidate_snapshot",
            "candidate overlay could not read a required git blob",
            commit_sha=commit_sha,
            path=path,
        )
    return byte_size


def _qa_overlay_preflight_total_source_bytes(
    project_root: Path,
    *,
    base_commit_sha: str,
    candidate_commit_sha: str,
    file_changes: Sequence[Mapping[str, Any]],
) -> None:
    """Apply the existing overlay byte budget before source parsing."""

    total_bytes = 0
    oversized_fallback_files: set[str] = set()
    for change in file_changes:
        status = str(change["status"])
        path = str(change["path"])
        old_path = str(change.get("old_path") or "")
        base_path = old_path if status == "R" else path
        blob_refs: list[tuple[str, str]] = []
        if status != "A":
            blob_refs.append((base_commit_sha, base_path))
        if status != "D":
            blob_refs.append((candidate_commit_sha, path))
        for commit_sha, blob_path in blob_refs:
            byte_size = _qa_git_object_byte_size(
                project_root,
                commit_sha=commit_sha,
                path=blob_path,
            )
            if byte_size > _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES:
                _qa_overlay_fail(
                    "total_source_limit_requires_exact_candidate_snapshot",
                    "candidate overlay source exceeds the elevated bounded inspection limit",
                    path=blob_path,
                    byte_size=byte_size,
                    max_total_bytes=(
                        _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
                    ),
                )
            if byte_size > _QA_OVERLAY_MAX_FILE_BYTES:
                if _qa_overlay_deterministic_adapter(blob_path) is None:
                    _qa_overlay_fail(
                        "oversized_source_requires_exact_candidate_snapshot",
                        "candidate overlay file exceeds the ordinary per-file limit and has no supported deterministic source adapter",
                        path=blob_path,
                        byte_size=byte_size,
                        max_byte_size=_QA_OVERLAY_MAX_FILE_BYTES,
                        fallback_policy=(
                            _QA_OVERLAY_OVERSIZED_SOURCE_POLICY
                        ),
                    )
                oversized_fallback_files.add(blob_path)
            total_bytes += byte_size

    elevated_fallback_activated = bool(oversized_fallback_files)
    effective_max_total_bytes = (
        _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
        if elevated_fallback_activated
        else _QA_OVERLAY_MAX_TOTAL_BYTES
    )
    if total_bytes > effective_max_total_bytes:
        _qa_overlay_fail(
            "total_source_limit_requires_exact_candidate_snapshot",
            "candidate overlay total source limit was exceeded",
            ordinary_max_total_bytes=_QA_OVERLAY_MAX_TOTAL_BYTES,
            effective_max_total_bytes=effective_max_total_bytes,
            elevated_fallback_max_total_bytes=(
                _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
            ),
            elevated_fallback_activated=elevated_fallback_activated,
            fallback_reason=(
                _QA_OVERLAY_OVERSIZED_SOURCE_POLICY
                if elevated_fallback_activated
                else ""
            ),
            inspected_source_bytes=total_bytes,
        )


def _qa_overlay_file_kind(path: str) -> str:
    from .language_policy import DEFAULT_LANGUAGE_POLICY

    policy = DEFAULT_LANGUAGE_POLICY
    if policy.is_test_path(path):
        return "test"
    if policy.is_doc_path(path) or Path(path).suffix.lower() in policy.doc_extensions:
        return "doc"
    if policy.is_config_path(path):
        return "config"
    if policy.is_source_path(path):
        return "source"
    return "other"


def _qa_overlay_module_name(path: str) -> str:
    from .language_policy import DEFAULT_LANGUAGE_POLICY

    return DEFAULT_LANGUAGE_POLICY.strip_source_suffix(path).replace("/", ".")


def _qa_overlay_python_lexical_identities(
    module_name: str,
    source: str,
) -> dict[tuple[int, str, str], str]:
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return {}
    identities: dict[tuple[int, str, str], str] = {}

    class LexicalIdentityVisitor(ast.NodeVisitor):
        def __init__(self) -> None:
            self.scope: list[str] = []

        def _visit_named_scope(self, node: ast.AST, *, kind: str) -> None:
            name = str(getattr(node, "name", "") or "").strip()
            line_number = int(getattr(node, "lineno", 0) or 0)
            lexical_name = ".".join([*self.scope, name])
            if name and line_number:
                identities[(line_number, name, kind)] = (
                    f"{module_name}::{lexical_name}"
                )
            self.scope.append(name)
            self.generic_visit(node)
            self.scope.pop()

        def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
            self._visit_named_scope(node, kind="function")

        def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
            self._visit_named_scope(node, kind="function")

        def visit_ClassDef(self, node: ast.ClassDef) -> None:
            self._visit_named_scope(node, kind="class")

    LexicalIdentityVisitor().visit(tree)
    return identities


def _qa_overlay_source_facts(path: str, source: str) -> dict[str, Any]:
    from .language_adapters import PythonAdapter
    from .language_policy import DEFAULT_LANGUAGE_POLICY

    if not DEFAULT_LANGUAGE_POLICY.is_source_path(path):
        return {"language": "", "symbols": [], "imports": [], "relations": []}
    adapter = _qa_overlay_deterministic_adapter(path)
    if adapter is None:
        _qa_overlay_fail(
            "unsupported_source_language_requires_exact_candidate_snapshot",
            "candidate overlay has no deterministic language adapter for a source file",
            path=path,
            language=DEFAULT_LANGUAGE_POLICY.language_for_path(path),
        )

    module_name = _qa_overlay_module_name(path)
    raw_symbols: list[Mapping[str, Any]] = []
    lexical_identities: dict[tuple[int, str, str], str] = {}
    if isinstance(adapter, PythonAdapter):
        from .reconcile_phases import phase_z_v2

        parsed = phase_z_v2._parse_python_module(path, module_name, source)
        if parsed is None:
            _qa_overlay_fail(
                "source_parse_failed_requires_exact_candidate_snapshot",
                "candidate overlay could not parse Python source",
                path=path,
            )
        lexical_identities = _qa_overlay_python_lexical_identities(
            module_name,
            source,
        )
        source_hashes = phase_z_v2.function_source_hashes(parsed)
        raw_symbols.extend(
            {
                "name": item.name,
                "qualified_name": item.qualified_name,
                "kind": "function",
                "lineno": item.lineno,
                "end_lineno": item.end_lineno,
                "decorators": list(item.decorators),
                "calls": list(item.calls),
                "source_hash": source_hashes.get(item.qualified_name, ""),
            }
            for item in parsed.functions
        )
        raw_symbols.extend(
            item
            for item in adapter.parse_symbols(path, source)
            if isinstance(item, Mapping) and str(item.get("kind") or "") == "class"
        )
    else:
        raw_symbols = [
            item
            for item in adapter.parse_symbols(path, source)
            if isinstance(item, Mapping)
        ]

    lines = source.splitlines()
    symbols: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw_symbol in raw_symbols:
        name = str(raw_symbol.get("name") or "").strip()
        if not name or name.split(".")[-1].startswith("_"):
            continue
        kind = str(raw_symbol.get("kind") or "symbol").strip()
        qualified_name = str(raw_symbol.get("qualified_name") or name).strip()
        short_name = name.split(".")[-1]
        line_start = max(1, int(raw_symbol.get("lineno") or 1))
        lexical_identity = lexical_identities.get(
            (line_start, short_name, kind),
            "",
        )
        identity = lexical_identity or (
            qualified_name
            if "::" in qualified_name
            else f"{module_name}::{qualified_name}"
        )
        if identity in seen:
            _qa_overlay_fail(
                "ambiguous_symbol_identity_requires_exact_candidate_snapshot",
                "candidate overlay found duplicate public symbol identities",
                path=path,
                symbol_identity=identity,
            )
        seen.add(identity)
        line_end = max(line_start, int(raw_symbol.get("end_lineno") or line_start))
        snippet = "\n".join(lines[line_start - 1 : min(len(lines), line_end)])
        symbols.append(
            {
                "identity": identity,
                "name": name,
                "kind": kind,
                "visibility": "public",
                "line_start": line_start,
                "line_end": line_end,
                "source_hash": str(raw_symbol.get("source_hash") or "")
                or f"sha256:{hashlib.sha256(snippet.encode('utf-8')).hexdigest()}",
                "decorators": sorted(
                    {str(item) for item in raw_symbol.get("decorators") or [] if str(item)}
                ),
                "calls": sorted(
                    {str(item) for item in raw_symbol.get("calls") or [] if str(item)}
                ),
            }
        )
    symbols.sort(key=lambda item: item["identity"])
    imports = [
        dict(item)
        for item in adapter.parse_imports(path, source)
        if isinstance(item, Mapping)
    ]
    relations = [
        dict(item)
        for item in adapter.extract_relations(
            path,
            source,
            symbols=[dict(item) for item in raw_symbols],
            imports=imports,
        )
        if isinstance(item, Mapping)
    ]
    if len(imports) > 2_000 or len(relations) > 2_000:
        _qa_overlay_fail(
            "parse_limit_requires_exact_candidate_snapshot",
            "candidate overlay relation/import parse limit was exceeded",
            path=path,
        )
    return {
        "language": str(adapter.language() or DEFAULT_LANGUAGE_POLICY.language_for_path(path)),
        "symbols": symbols,
        "imports": imports,
        "relations": relations,
    }


def _qa_overlay_version(
    path: str,
    source: str,
    byte_size: int,
    source_inspection: Mapping[str, Any],
) -> dict[str, Any]:
    facts = _qa_overlay_source_facts(path, source)
    return {
        "path": path,
        "source_hash": f"sha256:{hashlib.sha256(source.encode('utf-8')).hexdigest()}",
        "byte_size": byte_size,
        "line_count": len(source.splitlines()),
        "source_inspection": dict(source_inspection),
        **facts,
    }


def _qa_overlay_symbol_delta(
    base: Mapping[str, Any] | None,
    candidate: Mapping[str, Any] | None,
) -> dict[str, Any]:
    base_symbols = {
        str(item.get("identity") or ""): dict(item)
        for item in (base or {}).get("symbols") or []
        if isinstance(item, Mapping) and str(item.get("identity") or "")
    }
    candidate_symbols = {
        str(item.get("identity") or ""): dict(item)
        for item in (candidate or {}).get("symbols") or []
        if isinstance(item, Mapping) and str(item.get("identity") or "")
    }
    added = [candidate_symbols[key] for key in sorted(candidate_symbols.keys() - base_symbols.keys())]
    removed = [base_symbols[key] for key in sorted(base_symbols.keys() - candidate_symbols.keys())]
    modified = [
        {"before": base_symbols[key], "after": candidate_symbols[key]}
        for key in sorted(base_symbols.keys() & candidate_symbols.keys())
        if stable_sha256(base_symbols[key]) != stable_sha256(candidate_symbols[key])
    ]
    return {
        "added": added,
        "modified": modified,
        "removed": removed,
        "counts": {
            "added": len(added),
            "modified": len(modified),
            "removed": len(removed),
        },
    }


def _qa_overlay_normalized_marker_line(raw: str) -> str:
    return " ".join(str(raw or "").strip().split())


def _qa_overlay_comment_text(raw: str) -> str:
    text = str(raw or "").lstrip()
    for marker in ("#", "//", "<!--"):
        if not text.startswith(marker):
            continue
        text = text[len(marker) :].strip()
        if marker == "<!--" and text.endswith("-->"):
            text = text[:-3].strip()
        return text
    return ""


def _qa_overlay_governance_hint_projection(source: str | None) -> dict[str, Any]:
    lines = str(source or "").splitlines()
    comment_lines = [
        _qa_overlay_normalized_marker_line(comment)
        for raw in lines
        if "governance-hint" in (comment := _qa_overlay_comment_text(raw)).lower()
    ]
    entry_pattern = re.compile(r"^\s*['\"]governance_hints['\"]\s*[:=]")
    entries: list[list[str]] = []
    for index, raw in enumerate(lines):
        if not entry_pattern.match(raw):
            continue
        indentation = len(raw) - len(raw.lstrip())
        entry = [_qa_overlay_normalized_marker_line(raw)]
        for child in lines[index + 1 :]:
            if not child.strip():
                continue
            child_indentation = len(child) - len(child.lstrip())
            if child_indentation <= indentation:
                break
            entry.append(_qa_overlay_normalized_marker_line(child))
        entries.append(entry)
    return {
        "governance_hint_comment_lines": comment_lines,
        "governance_hints_entries": entries,
    }


def _qa_overlay_graph_structure_hint_blocks(
    source: str | None,
    *,
    path: str,
    version: str,
) -> list[list[str]]:
    blocks: list[list[str]] = []
    current: list[str] | None = None
    start_line = 0
    for line_number, raw in enumerate(str(source or "").splitlines(), start=1):
        comment = _qa_overlay_comment_text(raw)
        lowered = comment.lower()
        has_start = "aming-claw-hint:start" in lowered
        has_end = "aming-claw-hint:end" in lowered
        if has_start and has_end:
            _qa_overlay_fail(
                "graph_structure_hint_change_requires_exact_candidate_snapshot",
                "candidate overlay found a malformed graph structure hint block",
                path=path,
                version=version,
                line_number=line_number,
                malformed_reason="start_and_end_on_same_line",
            )
        if has_start:
            if current is not None:
                _qa_overlay_fail(
                    "graph_structure_hint_change_requires_exact_candidate_snapshot",
                    "candidate overlay found a nested graph structure hint block",
                    path=path,
                    version=version,
                    line_number=line_number,
                    start_line=start_line,
                    malformed_reason="nested_start",
                )
            current = [_qa_overlay_normalized_marker_line(comment)]
            start_line = line_number
            continue
        if has_end:
            if current is None:
                _qa_overlay_fail(
                    "graph_structure_hint_change_requires_exact_candidate_snapshot",
                    "candidate overlay found an unmatched graph structure hint end marker",
                    path=path,
                    version=version,
                    line_number=line_number,
                    malformed_reason="unmatched_end",
                )
            current.append(_qa_overlay_normalized_marker_line(comment))
            blocks.append(current)
            current = None
            start_line = 0
            continue
        if current is not None:
            current.append(_qa_overlay_normalized_marker_line(raw))
    if current is not None:
        _qa_overlay_fail(
            "graph_structure_hint_change_requires_exact_candidate_snapshot",
            "candidate overlay found an unclosed graph structure hint block",
            path=path,
            version=version,
            start_line=start_line,
            malformed_reason="unclosed_block",
        )
    return blocks


def _qa_overlay_assert_safe_interpretation(
    *,
    path: str,
    old_path: str,
    base_source: str | None,
    candidate_source: str | None,
) -> None:
    from .graph_rule_fingerprint import ALGORITHM_INPUT_PATHS

    affected_paths = {item for item in (path, old_path) if item}
    unsafe_algorithm_paths = sorted(affected_paths.intersection(ALGORITHM_INPUT_PATHS))
    if unsafe_algorithm_paths:
        _qa_overlay_fail(
            "graph_algorithm_change_requires_exact_candidate_snapshot",
            "candidate changes graph-construction algorithm inputs",
            paths=unsafe_algorithm_paths,
        )
    unsafe_config_paths = sorted(
        affected_paths.intersection(_QA_OVERLAY_UNSAFE_CONFIG_PATHS)
    )
    if unsafe_config_paths:
        _qa_overlay_fail(
            "graph_config_change_requires_exact_candidate_snapshot",
            "candidate changes graph interpretation/configuration inputs",
            paths=unsafe_config_paths,
        )
    base_governance_projection = _qa_overlay_governance_hint_projection(base_source)
    candidate_governance_projection = _qa_overlay_governance_hint_projection(
        candidate_source
    )
    if base_governance_projection != candidate_governance_projection:
        _qa_overlay_fail(
            "governance_hint_change_requires_exact_candidate_snapshot",
            "candidate changes source-controlled governance hint entries",
            path=path,
            base_projection=base_governance_projection,
            candidate_projection=candidate_governance_projection,
        )
    base_structure_blocks = _qa_overlay_graph_structure_hint_blocks(
        base_source,
        path=old_path or path,
        version="base",
    )
    candidate_structure_blocks = _qa_overlay_graph_structure_hint_blocks(
        candidate_source,
        path=path,
        version="candidate",
    )
    if base_structure_blocks != candidate_structure_blocks:
        _qa_overlay_fail(
            "graph_structure_hint_change_requires_exact_candidate_snapshot",
            "candidate changes source-controlled graph structure hint blocks",
            path=path,
            base_projection=base_structure_blocks,
            candidate_projection=candidate_structure_blocks,
        )


def _qa_demo_control_marker_is_server_generated(
    query_root: Path,
    *,
    project_id: str,
) -> bool:
    marker_path = query_root / DEMO_ENVIRONMENT_MARKER
    try:
        payload = json.loads(marker_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return False
    if not isinstance(payload, Mapping):
        return False
    expected_keys = {
        "schema_version",
        "managed_by",
        "owner_project_id",
        "environment_id",
        "template_id",
        "project_id",
        "fixture_root",
        "created_at",
    }
    if set(payload) != expected_keys:
        return False
    reviewed_project_id = str(project_id or "").strip()
    owner_project_id = str(payload.get("owner_project_id") or "").strip()
    if (
        not reviewed_project_id
        or not owner_project_id
        or str(payload.get("project_id") or "").strip() != reviewed_project_id
        or not project_service.project_exists(owner_project_id)
    ):
        return False
    expected = {
        "schema_version": "demo_environment_marker.v1",
        "managed_by": DEMO_ENVIRONMENT_MANAGED_BY,
        "project_id": reviewed_project_id,
        "fixture_root": str(query_root.resolve()),
    }
    if any(str(payload.get(key) or "") != value for key, value in expected.items()):
        return False
    if not all(
        str(payload.get(key) or "").strip()
        for key in ("environment_id", "template_id", "project_id", "created_at")
    ):
        return False
    marker_registry_identity = {
        "id": str(payload.get("environment_id") or ""),
        "template_id": str(payload.get("template_id") or ""),
        "project_id": reviewed_project_id,
        "fixture_root": str(query_root.resolve()),
        "created_at": str(payload.get("created_at") or ""),
    }
    try:
        registry_rows = _read_demo_environment_registry(owner_project_id)
    except (OSError, UnicodeError, json.JSONDecodeError):
        return False
    for row in registry_rows:
        if any(
            str(row.get(key) or "") != value
            for key, value in marker_registry_identity.items()
        ):
            continue
        valid, fixture_root, _ = _validate_managed_demo_environment(
            row,
            owner_project_id,
        )
        if valid and fixture_root.resolve() == query_root.resolve():
            return True
    return False


def _qa_filter_authenticated_demo_control_metadata_entries(
    query_root: Path,
    *,
    project_id: str,
    dirty_entries: Sequence[bytes],
) -> tuple[list[bytes], list[str]]:
    """Project the one authenticated demo marker rule at clean-root gates."""

    retained_entries = list(dirty_entries)
    ignored_paths: list[str] = []
    demo_marker_entry = f"?? {DEMO_ENVIRONMENT_MARKER}".encode("utf-8")
    if (
        demo_marker_entry in retained_entries
        and _qa_demo_control_marker_is_server_generated(
            query_root,
            project_id=project_id,
        )
    ):
        retained_entries = [
            item for item in retained_entries if item != demo_marker_entry
        ]
        ignored_paths.append(DEMO_ENVIRONMENT_MARKER)
    return retained_entries, ignored_paths


def _qa_checkout_root_identity(
    *,
    project_id: str,
    query_root: Path,
    canonical_root: Path,
    base_commit_sha: str,
    candidate_commit_sha: str,
    require_canonical_base_head: bool = True,
    require_query_candidate_head: bool = False,
    require_query_review_head: bool = True,
    registered_allocator_worktree_paths: Sequence[str] = (),
    exact_snapshot_materialization_provenance: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    from .checkout_provenance import describe_checkout

    query = describe_checkout(query_root, project_id=project_id)
    canonical = describe_checkout(canonical_root, project_id=project_id)
    if not query.get("is_git_worktree") or not canonical.get("is_git_worktree"):
        _qa_overlay_fail(
            "non_git_root_requires_exact_candidate_snapshot",
            "bounded candidate overlay requires git-backed query and canonical roots",
        )
    query_git = query.get("git") if isinstance(query.get("git"), Mapping) else {}
    canonical_git = (
        canonical.get("git") if isinstance(canonical.get("git"), Mapping) else {}
    )
    query_common = str(query_git.get("git_common_dir") or "")
    canonical_common = str(canonical_git.get("git_common_dir") or "")
    query_remote = str(query_git.get("remote_url") or "")
    canonical_remote = str(canonical_git.get("remote_url") or "")
    query_head = str(query.get("commit_sha") or "").strip().lower()
    snapshot_provenance = (
        exact_snapshot_materialization_provenance
        if isinstance(exact_snapshot_materialization_provenance, Mapping)
        else {}
    )
    snapshot_execution_root_verified = False
    if snapshot_provenance:
        snapshot_git = (
            snapshot_provenance.get("git")
            if isinstance(snapshot_provenance.get("git"), Mapping)
            else {}
        )
        snapshot_project_identity = (
            snapshot_provenance.get("canonical_project_identity")
            if isinstance(
                snapshot_provenance.get("canonical_project_identity"), Mapping
            )
            else {}
        )
        snapshot_execution_root = str(
            snapshot_provenance.get("execution_root") or ""
        ).strip()
        snapshot_worktree_root = str(
            snapshot_git.get("worktree_root") or ""
        ).strip()
        snapshot_common = str(snapshot_git.get("git_common_dir") or "").strip()
        snapshot_remote = str(snapshot_git.get("remote_url") or "")
        identity_mismatches: list[dict[str, Any]] = []

        def _record_snapshot_mismatch(
            field: str,
            expected: Any,
            actual: Any,
        ) -> None:
            if actual != expected:
                identity_mismatches.append(
                    {"field": field, "expected": expected, "actual": actual}
                )

        _record_snapshot_mismatch(
            "snapshot_execution_root",
            str(query_root.resolve()),
            (
                str(Path(snapshot_execution_root).resolve())
                if snapshot_execution_root
                else ""
            ),
        )
        _record_snapshot_mismatch(
            "snapshot_execution_root_role",
            "execution_root",
            str(snapshot_provenance.get("execution_root_role") or ""),
        )
        _record_snapshot_mismatch(
            "snapshot_project_identity_type",
            "git",
            str(snapshot_project_identity.get("type") or ""),
        )
        _record_snapshot_mismatch(
            "snapshot_project_id",
            project_id,
            str(snapshot_project_identity.get("project_id") or ""),
        )
        _record_snapshot_mismatch(
            "snapshot_candidate_commit",
            candidate_commit_sha,
            str(snapshot_project_identity.get("commit_sha") or "")
            .strip()
            .lower(),
        )
        _record_snapshot_mismatch(
            "snapshot_query_root_head",
            candidate_commit_sha,
            query_head,
        )
        _record_snapshot_mismatch(
            "snapshot_git_worktree_root",
            str(query_root.resolve()),
            (
                str(Path(snapshot_worktree_root).resolve())
                if snapshot_worktree_root
                else ""
            ),
        )
        _record_snapshot_mismatch(
            "snapshot_git_common_dir",
            str(Path(query_common).resolve()) if query_common else "",
            str(Path(snapshot_common).resolve()) if snapshot_common else "",
        )
        _record_snapshot_mismatch(
            "snapshot_git_remote_url",
            query_remote,
            snapshot_remote,
        )
        if identity_mismatches:
            _qa_overlay_fail(
                "exact_candidate_snapshot_materialization_identity_mismatch",
                (
                    "exact candidate snapshot execution-root provenance no "
                    "longer matches the immutable candidate checkout"
                ),
                identity_mismatches=identity_mismatches,
            )
        snapshot_execution_root_verified = True
    query_repository_identity_hash = stable_sha256(
        {
            "type": "git",
            "project_id": project_id,
            "git_common_dir": query_common,
            "remote_url": query_remote,
        }
    )
    repository_identity_hash = stable_sha256(
        {
            "type": "git",
            "project_id": project_id,
            "git_common_dir": canonical_common,
            "remote_url": canonical_remote,
        }
    )
    repository_identity_match = (
        query_repository_identity_hash == repository_identity_hash
    )
    if not repository_identity_match and not snapshot_execution_root_verified:
        _qa_overlay_fail(
            "query_root_repository_mismatch",
            "QA query root is not a checkout of the registered canonical repository",
            query_root=str(query_root),
            canonical_project_root=str(canonical_root),
        )
    canonical_head = str(canonical.get("commit_sha") or "").strip().lower()
    accepted_canonical_heads = {base_commit_sha, candidate_commit_sha}
    if require_canonical_base_head and canonical_head not in accepted_canonical_heads:
        _qa_overlay_fail(
            "canonical_base_not_current",
            (
                "registered-project HEAD must be the canonical base or the "
                "immutable candidate under bounded review"
            ),
            expected_base_commit_sha=base_commit_sha,
            expected_candidate_commit_sha=candidate_commit_sha,
            canonical_head_commit=canonical_head,
        )
    accepted_query_heads = (
        {candidate_commit_sha}
        if require_query_candidate_head
        else {base_commit_sha, candidate_commit_sha}
    )
    if require_query_review_head and query_head not in accepted_query_heads:
        _qa_overlay_fail(
            "query_root_head_mismatch",
            (
                "QA query root must be checked out at the candidate commit"
                if require_query_candidate_head
                else "QA query root must be checked out at the canonical base or candidate commit"
            ),
            query_root_head_commit=query_head,
            accepted_commits=sorted(accepted_query_heads),
        )
    query_root_clean: bool | None = None
    query_root_status_hash = ""
    query_root_tree_sha = ""
    ignored_demo_control_metadata_paths: list[str] = []
    ignored_registered_allocator_worktree_paths: list[str] = []
    if require_query_candidate_head:
        status = _qa_git_bytes(
            query_root,
            ["status", "--porcelain=v1", "-z", "--untracked-files=all"],
        )
        if status.returncode != 0:
            _qa_overlay_fail(
                "exact_candidate_query_root_status_unavailable",
                "exact candidate review requires a verifiable clean query root",
                query_root=str(query_root),
            )
        dirty_entries = [item for item in status.stdout.split(b"\0") if item]
        (
            dirty_entries,
            ignored_demo_control_metadata_paths,
        ) = _qa_filter_authenticated_demo_control_metadata_entries(
            query_root,
            project_id=project_id,
            dirty_entries=dirty_entries,
        )
        registered_allocator_roots = {
            Path(path).resolve()
            for path in registered_allocator_worktree_paths
            if str(path or "").strip()
        }
        retained_dirty_entries: list[bytes] = []
        for item in dirty_entries:
            if not item.startswith(b"?? "):
                retained_dirty_entries.append(item)
                continue
            raw_path = item[3:].decode("utf-8", errors="surrogateescape").rstrip("/")
            dirty_path = (query_root / raw_path).resolve()
            registered_root = next(
                (
                    root
                    for root in registered_allocator_roots
                    if dirty_path == root or root in dirty_path.parents
                ),
                None,
            )
            if registered_root is None:
                retained_dirty_entries.append(item)
                continue
            ignored_path = registered_root.relative_to(query_root).as_posix()
            if ignored_path not in ignored_registered_allocator_worktree_paths:
                ignored_registered_allocator_worktree_paths.append(ignored_path)
        dirty_entries = retained_dirty_entries
        query_root_clean = not dirty_entries
        query_root_status_hash = (
            "sha256:" + hashlib.sha256(status.stdout).hexdigest()
        )
        if not query_root_clean:
            _qa_overlay_fail(
                "exact_candidate_query_root_dirty",
                "exact candidate review requires a clean query worktree",
                query_root=str(query_root),
                dirty_entry_count=len(dirty_entries),
                ignored_demo_control_metadata_entry_count=len(
                    ignored_demo_control_metadata_paths
                ),
                ignored_registered_allocator_worktree_entry_count=len(
                    ignored_registered_allocator_worktree_paths
                ),
                untracked_files_checked=True,
            )
        tree = _qa_git_bytes(
            query_root,
            ["rev-parse", "--verify", f"{candidate_commit_sha}^{{tree}}"],
        )
        query_root_tree_sha = tree.stdout.decode(
            "ascii", errors="ignore"
        ).strip().lower()
        if tree.returncode != 0 or not re.fullmatch(
            r"[0-9a-f]{40}|[0-9a-f]{64}", query_root_tree_sha
        ):
            _qa_overlay_fail(
                "exact_candidate_query_root_tree_unavailable",
                "exact candidate review requires the candidate Git tree identity",
                query_root=str(query_root),
                candidate_commit_sha=candidate_commit_sha,
            )
    query_root_identity_hash = stable_sha256(
        {
            "execution_root": str(query.get("execution_root") or ""),
            "head_commit": query_head,
            "checkout_identity": query.get("canonical_project_identity") or {},
            "repository_identity_hash": query_repository_identity_hash,
        }
    )
    canonical_project_identity_hash = stable_sha256(
        {
            "execution_root": str(canonical.get("execution_root") or ""),
            "head_commit": canonical_head,
            "checkout_identity": canonical.get("canonical_project_identity") or {},
            "repository_identity_hash": repository_identity_hash,
        }
    )
    identity = {
        "schema_version": "qa_review_graph.root_identity.v1",
        "base_commit_sha": base_commit_sha,
        "candidate_commit_sha": candidate_commit_sha,
        "query_root": str(Path(query_root).resolve()),
        "query_root_head_commit": query_head,
        "query_root_identity_hash": query_root_identity_hash,
        "query_root_is_linked_worktree": bool(query_git.get("is_linked_worktree")),
        "canonical_project_root": str(Path(canonical_root).resolve()),
        "canonical_head_commit": canonical_head,
        "canonical_head_policy": (
            "base_or_candidate"
            if require_canonical_base_head
            else "historical_audit_descendant"
        ),
        "canonical_head_relation": (
            "candidate"
            if canonical_head == candidate_commit_sha
            else "base"
            if canonical_head == base_commit_sha
            else "other"
        ),
        "canonical_project_identity_hash": canonical_project_identity_hash,
        "repository_identity_hash": repository_identity_hash,
        "query_repository_identity_hash": query_repository_identity_hash,
        "repository_identity_match": repository_identity_match,
        "repository_identity_authority": (
            "registered_canonical_repository"
            if repository_identity_match
            else "exact_candidate_snapshot_materialization_provenance"
        ),
        "snapshot_execution_root_verified": snapshot_execution_root_verified,
    }
    if require_query_candidate_head:
        identity.update(
            {
                "query_root_clean": query_root_clean is True,
                "query_root_status_hash": query_root_status_hash,
                "query_root_tree_sha": query_root_tree_sha,
                "query_root_untracked_files_checked": True,
                "query_root_ignored_demo_control_metadata_paths": (
                    ignored_demo_control_metadata_paths
                ),
                "query_root_ignored_registered_allocator_worktree_paths": sorted(
                    ignored_registered_allocator_worktree_paths
                ),
            }
        )
    return identity


def _qa_registered_allocator_worktree_paths(
    conn,
    *,
    project_id: str,
    canonical_project_root: Path,
) -> list[str]:
    """Return governance-clean registered worktrees owned by the allocator.

    The canonical repository sees linked worktrees below ``.worktrees`` as
    untracked directories.  Exact-candidate QA may ignore only directories
    that are both registered in BranchRuntimeContext and independently proven
    to be linked worktrees of this canonical repository.  The shared
    dirty-worktree policy may ignore only known generated/cache artifacts
    inside the linked worktree; product dirtiness still rejects the path.
    """

    canonical_root = Path(canonical_project_root).resolve()
    allocator_root = (canonical_root / ".worktrees").resolve()
    table = conn.execute(
        """
        SELECT 1 FROM sqlite_master
        WHERE type = 'table' AND name = 'parallel_branch_runtime_contexts'
        """
    ).fetchone()
    if not table:
        return []
    canonical_common_proc = _qa_git_bytes(
        canonical_root,
        ["rev-parse", "--path-format=absolute", "--git-common-dir"],
    )
    canonical_common = Path(
        canonical_common_proc.stdout.decode("utf-8", errors="ignore").strip()
    ).resolve()
    if canonical_common_proc.returncode != 0 or not str(canonical_common):
        return []
    rows = conn.execute(
        """
        SELECT target_project_root, worktree_path
        FROM parallel_branch_runtime_contexts
        WHERE project_id = ? AND worktree_path != ''
        ORDER BY task_id
        """,
        (project_id,),
    ).fetchall()
    registered: list[str] = []
    for row in rows:
        target_root = Path(str(row["target_project_root"] or "")).resolve()
        worktree_root = Path(str(row["worktree_path"] or "")).resolve()
        if (
            target_root not in {canonical_root, worktree_root}
            or worktree_root == allocator_root
        ):
            continue
        try:
            worktree_root.relative_to(allocator_root)
        except ValueError:
            continue
        if not worktree_root.is_dir():
            continue
        common_proc = _qa_git_bytes(
            worktree_root,
            ["rev-parse", "--path-format=absolute", "--git-common-dir"],
        )
        worktree_common = Path(
            common_proc.stdout.decode("utf-8", errors="ignore").strip()
        ).resolve()
        if common_proc.returncode != 0 or worktree_common != canonical_common:
            continue
        clean_proc = _qa_git_bytes(
            worktree_root,
            ["status", "--porcelain=v1", "--untracked-files=all"],
        )
        governed_dirty_paths: list[str] = []
        for line in clean_proc.stdout.decode(
            "utf-8", errors="surrogateescape"
        ).splitlines():
            dirty_paths = parse_git_porcelain_paths(line)
            if not dirty_paths:
                governed_dirty_paths.append("<unparseable-git-status-entry>")
                continue
            if line.startswith("?? ") and not filter_dirty_files(dirty_paths):
                continue
            governed_dirty_paths.extend(dirty_paths)
        if clean_proc.returncode != 0 or governed_dirty_paths:
            continue
        registered.append(str(worktree_root))
    return sorted(dict.fromkeys(registered))


def _qa_exact_candidate_diff_identity(
    canonical_project_root: Path,
    *,
    base_commit_sha: str,
    candidate_commit_sha: str,
    comparison_base_commit_source: str = _QA_WORKER_COMPARISON_BASE_SOURCE,
) -> dict[str, Any]:
    """Derive the immutable base-to-candidate tuple for an exact snapshot.

    An exact candidate graph snapshot is materialized at the candidate commit,
    so its graph base commit intentionally equals the candidate.  QA still
    needs the worker's cumulative runtime diff for scope and evidence binding.
    Keep that comparison tuple separate from the graph snapshot base and do not
    attempt to rebuild an overlay that the exact snapshot already replaces.
    """

    canonical_root = Path(canonical_project_root).resolve()
    base_commit_sha = str(base_commit_sha or "").strip().lower()
    candidate_commit_sha = str(candidate_commit_sha or "").strip().lower()
    comparison_base_commit_source = str(
        comparison_base_commit_source or ""
    ).strip()
    if comparison_base_commit_source not in _QA_COMPARISON_BASE_SOURCES:
        _qa_overlay_fail(
            "exact_candidate_comparison_source_invalid",
            "exact candidate comparison base requires trusted server authority",
            identity_mismatches=[
                {
                    "field": "comparison_base_commit_source",
                    "expected": sorted(_QA_COMPARISON_BASE_SOURCES),
                    "actual": comparison_base_commit_source,
                }
            ],
        )
    for field, commit_sha in (
        ("comparison_base_commit_sha", base_commit_sha),
        ("candidate_commit_sha", candidate_commit_sha),
    ):
        resolved = _qa_git_bytes(
            canonical_root,
            ["rev-parse", "--verify", f"{commit_sha}^{{commit}}"],
        )
        resolved_sha = resolved.stdout.decode(
            "ascii", errors="ignore"
        ).strip().lower()
        if resolved.returncode != 0 or resolved_sha != commit_sha:
            _qa_overlay_fail(
                "exact_candidate_comparison_commit_unavailable",
                f"{field} is not an available full commit",
                field=field,
                commit_sha=commit_sha,
            )
    if base_commit_sha == candidate_commit_sha:
        _qa_overlay_fail(
            "exact_candidate_comparison_base_not_distinct",
            "exact candidate comparison base must differ from the candidate",
            comparison_base_commit_sha=base_commit_sha,
            candidate_commit_sha=candidate_commit_sha,
        )
    ancestry = _qa_git_bytes(
        canonical_root,
        ["merge-base", "--is-ancestor", base_commit_sha, candidate_commit_sha],
    )
    if ancestry.returncode != 0:
        _qa_overlay_fail(
            "exact_candidate_comparison_base_not_ancestor",
            "trusted runtime comparison base is not an ancestor of the candidate",
            comparison_base_commit_sha=base_commit_sha,
            candidate_commit_sha=candidate_commit_sha,
        )

    changed = _qa_git_bytes(
        canonical_root,
        [
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--name-status",
            "-z",
            "-M",
            f"{base_commit_sha}..{candidate_commit_sha}",
            "--",
            ".",
        ],
    )
    if changed.returncode != 0:
        _qa_overlay_fail(
            "exact_candidate_comparison_diff_unavailable",
            "server could not derive the exact candidate file changes",
        )
    file_changes = _qa_parse_name_status_z(changed.stdout)
    changed_files: list[str] = []
    for item in file_changes:
        for candidate_path in (item.get("old_path"), item.get("path")):
            normalized = str(candidate_path or "")
            if normalized and normalized not in changed_files:
                changed_files.append(normalized)

    diff = _qa_git_bytes(
        canonical_root,
        [
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--binary",
            "--full-index",
            "-M",
            f"{base_commit_sha}..{candidate_commit_sha}",
            "--",
            ".",
        ],
    )
    if diff.returncode != 0:
        _qa_overlay_fail(
            "exact_candidate_comparison_diff_hash_unavailable",
            "server could not hash the exact candidate diff",
        )
    return {
        "changed_files": changed_files,
        "candidate_diff_hash": f"sha256:{hashlib.sha256(diff.stdout).hexdigest()}",
        "changed_files_source": (
            "server_runtime_context_base_to_exact_candidate_diff"
        ),
        "comparison_base_commit_sha": base_commit_sha,
        "comparison_base_commit_source": comparison_base_commit_source,
    }


def _contract_runtime_full_commit_value(project_id: str, value: Any) -> str:
    normalized = str(value or "").strip().lower()
    if re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", normalized):
        return normalized
    if not re.fullmatch(r"[0-9a-f]{7,64}", normalized):
        return ""
    project_root = project_service.resolve_project_root(
        project_id,
        None,
        fallback_self=True,
    )
    if project_root is None:
        return ""
    return _qa_post_merge_resolve_commit(Path(project_root), normalized)


def _qa_exact_candidate_direct_main_comparison_failure(
    machine_reason: str,
    *,
    field: str,
    expected: Any,
    actual: Any,
) -> dict[str, Any]:
    """Return one public-safe, non-authoritative direct-main diagnosis."""

    return {
        "source": _QA_DIRECT_MAIN_COMPARISON_LINEAGE_SOURCE,
        "machine_reason": str(machine_reason or "").strip(),
        "identity_mismatches": [
            {
                "field": str(field or "").strip(),
                "expected": expected,
                "actual": actual,
            }
        ],
        "fail_closed": True,
        "zero_write_rejection": True,
        "writes_performed": False,
    }


def _qa_exact_candidate_direct_main_strict_comparison_authority(
    *,
    strict_record: Mapping[str, Any],
    direct_event: Mapping[str, Any],
    implementation_event: Mapping[str, Any],
    project_id: str,
    backlog_id: str,
    task_id: str,
    project_root: Path,
    candidate_commit_sha: str,
    comparison_base: str,
) -> dict[str, Any]:
    """Bind strict Direct Main comparison to its immutable pre-mutation world."""

    metadata = (
        strict_record.get("metadata")
        if isinstance(strict_record.get("metadata"), Mapping)
        else {}
    )
    binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    binding_hash = str(binding.get("binding_hash") or "").strip()
    unsigned_binding = {
        key: value for key, value in binding.items() if key != "binding_hash"
    }
    canonical_root = Path(project_root).resolve()
    canonical_root_text = str(canonical_root)
    binding_owned_files = sorted(
        _runtime_context_service_dedupe(
            [str(path or "").strip() for path in binding.get("owned_files") or []]
        )
    )
    binding_target_files = sorted(
        _runtime_context_service_dedupe(
            [str(path or "").strip() for path in binding.get("target_files") or []]
        )
    )
    direct_identity = _observer_root_route_identity_from_event(direct_event)
    binding_route_identity = (
        binding.get("route_identity")
        if isinstance(binding.get("route_identity"), Mapping)
        else {}
    )
    binding_valid = bool(
        str(strict_record.get("project_id") or "").strip() == project_id
        and str(strict_record.get("backlog_id") or "").strip() == backlog_id
        and str(strict_record.get("contract_execution_id") or "").strip()
        == task_id
        and str(strict_record.get("contract_id") or "").strip()
        == "operator_supervised_direct_main"
        and str(strict_record.get("version") or "").strip() == "v1"
        and str(strict_record.get("revision") or "").strip()
        in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        and str(binding.get("schema_version") or "").strip()
        == "operator_supervised_direct_main.runtime_binding.v1"
        and binding.get("strict_runtime_binding_required") is True
        and binding.get("server_derived") is True
        and binding.get("caller_claims_trusted") is False
        and str(binding.get("project_id") or "").strip() == project_id
        and str(binding.get("backlog_id") or "").strip() == backlog_id
        and str(binding.get("contract_execution_id") or "").strip()
        == task_id
        and str(binding.get("target_project_root") or "").strip()
        == canonical_root_text
        and str(binding.get("worktree_path") or "").strip()
        == canonical_root_text
        and binding_owned_files
        and binding_owned_files == binding_target_files
        and _observer_root_route_identity_complete(binding_route_identity)
        and _observer_root_route_identity_complete(direct_identity)
        and _observer_root_route_identity_key(binding_route_identity)
        == _observer_root_route_identity_key(direct_identity)
        and str(binding_route_identity.get("route_token_ref") or "").strip()
        == str(direct_identity.get("route_token_ref") or "").strip()
        and binding_hash
        and binding_hash == stable_sha256(unsigned_binding)
    )
    if not binding_valid:
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_runtime_binding_invalid",
            field="operator_supervised_direct_main_runtime_binding",
            expected="one hash-valid exact strict runtime binding",
            actual="missing_ambiguous_or_invalid",
        )

    world_ref = (
        binding.get("pre_mutation_world_ref")
        if isinstance(binding.get("pre_mutation_world_ref"), Mapping)
        else {}
    )
    world_ref_hash = str(world_ref.get("authority_hash") or "").strip()
    unsigned_world_ref = {
        key: value for key, value in world_ref.items() if key != "authority_hash"
    }
    direct_payload = (
        direct_event.get("payload")
        if isinstance(direct_event.get("payload"), Mapping)
        else {}
    )
    direct_authority = (
        direct_payload.get("observer_direct_pre_mutation_authority")
        if isinstance(
            direct_payload.get("observer_direct_pre_mutation_authority"),
            Mapping,
        )
        else {}
    )
    graph_evidence = (
        direct_authority.get("graph_trace_db_evidence")
        if isinstance(
            direct_authority.get("graph_trace_db_evidence"), Mapping
        )
        else {}
    )
    accepted_world_ref = (
        graph_evidence.get("accepted_world_ref")
        if isinstance(graph_evidence.get("accepted_world_ref"), Mapping)
        else {}
    )
    world_ref_valid = bool(
        str(world_ref.get("schema_version") or "").strip()
        == "operator_supervised_direct_main.pre_mutation_world_ref.v1"
        and world_ref.get("accepted") is True
        and str(world_ref.get("status") or "").strip() == "accepted"
        and world_ref.get("server_derived") is True
        and world_ref.get("caller_claims_trusted") is False
        and world_ref.get("repository_root_exact") is True
        and str(world_ref.get("project_id") or "").strip() == project_id
        and str(world_ref.get("target_project_root") or "").strip()
        == canonical_root_text
        and str(world_ref.get("worktree_path") or "").strip()
        == canonical_root_text
        and world_ref_hash
        and world_ref_hash == stable_sha256(unsigned_world_ref)
        and dict(accepted_world_ref) == dict(world_ref)
    )
    if not world_ref_valid:
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_pre_mutation_world_mismatch",
            field="accepted_pre_mutation_world_ref",
            expected="runtime-bound hash-valid accepted world",
            actual="missing_or_mismatched",
        )

    implementation_payload = (
        implementation_event.get("payload")
        if isinstance(implementation_event.get("payload"), Mapping)
        else {}
    )
    prewrite = (
        implementation_payload.get(
            "direct_main_implementation_commit_prewrite_authority"
        )
        if isinstance(
            implementation_payload.get(
                "direct_main_implementation_commit_prewrite_authority"
            ),
            Mapping,
        )
        else {}
    )
    lineage_values = {
        _contract_runtime_full_commit_value(project_id, value)
        for value in (
            binding.get("base_commit"),
            binding.get("target_head_commit"),
            world_ref.get("base_commit"),
            world_ref.get("target_head_commit"),
            prewrite.get("expected_runtime_base_commit"),
            prewrite.get("implementation_parent_commit"),
        )
    }
    prewrite_candidate_values = {
        _contract_runtime_full_commit_value(project_id, value)
        for value in (
            implementation_event.get("commit_sha"),
            prewrite.get("commit_sha"),
            prewrite.get("resolved_commit_sha"),
            prewrite.get("canonical_head_commit"),
        )
    }
    if (
        lineage_values != {comparison_base}
        or prewrite_candidate_values != {candidate_commit_sha}
        or str(prewrite.get("expected_runtime_project_root") or "").strip()
        != canonical_root_text
        or str(prewrite.get("canonical_project_root") or "").strip()
        != canonical_root_text
        or str(prewrite.get("runtime_binding_hash") or "").strip()
        != binding_hash
    ):
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_base_lineage_mismatch",
            field="pre_mutation_parent_to_candidate_lineage",
            expected={
                "comparison_base_commit_sha": comparison_base,
                "candidate_commit_sha": candidate_commit_sha,
            },
            actual={
                "base_candidates": sorted(lineage_values),
                "candidate_candidates": sorted(prewrite_candidate_values),
            },
        )

    declared_files = sorted(
        _runtime_context_service_dedupe(
            [
                str(path or "").strip()
                for path in direct_authority.get("row_declared_files") or []
            ]
        )
    )
    prewrite_changed_files = sorted(
        _runtime_context_service_dedupe(
            [
                str(path or "").strip()
                for path in prewrite.get("verified_changed_files") or []
            ]
        )
    )
    try:
        diff_identity = _qa_exact_candidate_diff_identity(
            canonical_root,
            base_commit_sha=comparison_base,
            candidate_commit_sha=candidate_commit_sha,
            comparison_base_commit_source=(
                _QA_DIRECT_MAIN_COMPARISON_BASE_SOURCE
            ),
        )
    except _QACandidateOverlayError:
        diff_identity = {}
    diff_changed_files = sorted(
        _runtime_context_service_dedupe(
            [
                str(path or "").strip()
                for path in diff_identity.get("changed_files") or []
            ]
        )
    )
    if not (
        declared_files
        and declared_files == binding_owned_files
        and declared_files == binding_target_files
        and declared_files == prewrite_changed_files
        and declared_files == diff_changed_files
    ):
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_file_fence_mismatch",
            field="parent_to_candidate_changed_files",
            expected=declared_files,
            actual=diff_changed_files,
        )
    return {
        "commit_sha": comparison_base,
        "source": _QA_DIRECT_MAIN_COMPARISON_BASE_SOURCE,
        "lineage_source": _QA_DIRECT_MAIN_COMPARISON_LINEAGE_SOURCE,
    }


def _qa_exact_candidate_direct_main_events(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
) -> list[dict[str, Any]]:
    """Return accepted Direct boundaries for one legacy or pinned strict task."""

    if not backlog_id:
        return []
    legacy_task_id = _onboard_service_execution_id(project_id, backlog_id)
    strict_records = _operator_supervised_direct_main_strict_records(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
    )
    matching_strict_records = [
        record
        for record in strict_records
        if str(record.get("contract_execution_id") or "").strip()
        == task_id
    ]
    if matching_strict_records:
        if len(strict_records) != 1 or len(matching_strict_records) != 1:
            return []
        strict_record = matching_strict_records[0]
        if not (
            str(strict_record.get("project_id") or "").strip() == project_id
            and str(strict_record.get("backlog_id") or "").strip()
            == backlog_id
            and str(
                strict_record.get("contract_execution_id") or ""
            ).strip()
            == task_id
            and str(strict_record.get("contract_id") or "").strip()
            == "operator_supervised_direct_main"
            and str(strict_record.get("version") or "").strip() == "v1"
            and str(strict_record.get("revision") or "").strip()
            in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        ):
            return []
    elif task_id != legacy_task_id:
        return []
    by_id: dict[int, dict[str, Any]] = {}
    for event_kind in (
        "observer_direct_implementation_exception",
        "observer_direct_mutation_exception",
    ):
        for event in _onboard_parentless_direct_main_timeline_events(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            event_kind=event_kind,
        ):
            event_id = int(event.get("id") or event.get("event_id") or 0)
            if (
                event_id > 0
                and _onboard_parentless_direct_main_event_is_accepted(event)
            ):
                by_id[event_id] = event
    return [by_id[event_id] for event_id in sorted(by_id, reverse=True)]


def _qa_exact_candidate_direct_main_comparison_authority(
    conn,
    *,
    project_id: str,
    proof: Mapping[str, Any],
) -> dict[str, Any]:
    """Resolve a direct-main base only from durable event and Git lineage."""

    backlog_id = str(proof.get("backlog_id") or "").strip()
    task_id = str(proof.get("task_id") or "").strip()
    direct_events = _qa_exact_candidate_direct_main_events(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
    )
    if not direct_events:
        return {}
    if len(direct_events) != 1:
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_boundary_ambiguous",
            field="direct_main_pre_mutation_event_count",
            expected=1,
            actual=len(direct_events),
        )
    direct_event = direct_events[0]
    direct_event_id = int(
        direct_event.get("id") or direct_event.get("event_id") or 0
    )
    candidate_commit_sha = _contract_runtime_full_commit_value(
        project_id,
        proof.get("commit_sha"),
    )
    if not candidate_commit_sha:
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_candidate_commit_unavailable",
            field="candidate_commit_sha",
            expected="available full candidate commit",
            actual="missing_or_unavailable",
        )
    implementation_events = (
        _onboard_parentless_direct_main_timeline_events(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            event_kind="implementation",
            after_event_id=direct_event_id,
        )
    )
    authoritative_events = [
        event
        for event in implementation_events
        if _qa_exact_candidate_direct_main_implementation_is_authoritative(
            conn,
            event,
            direct_event=direct_event,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
        )
    ]
    authoritative_commits = sorted(
        {
            str(event.get("commit_sha") or "").strip().lower()
            for event in authoritative_events
            if str(event.get("commit_sha") or "").strip()
        }
    )
    if len(authoritative_events) != 1:
        return _qa_exact_candidate_direct_main_comparison_failure(
            (
                "exact_candidate_direct_main_implementation_missing"
                if not authoritative_events
                else "exact_candidate_direct_main_implementation_ambiguous"
            ),
            field="authoritative_implementation_event_count",
            expected=1,
            actual=len(authoritative_events),
        )
    if authoritative_commits != [candidate_commit_sha]:
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_implementation_commit_mismatch",
            field="candidate_commit_sha",
            expected=authoritative_commits[0] if authoritative_commits else "",
            actual=candidate_commit_sha,
        )

    project_root = project_service.resolve_project_root(
        project_id,
        None,
        fallback_self=True,
    )
    if project_root is None:
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_project_root_unavailable",
            field="canonical_project_root",
            expected="registered project root",
            actual="unavailable",
        )
    parents = _qa_git_bytes(
        Path(project_root).resolve(),
        ["rev-list", "--parents", "--max-count=1", candidate_commit_sha],
    )
    parent_tokens = parents.stdout.decode(
        "ascii", errors="ignore"
    ).strip().lower().split()
    if (
        parents.returncode != 0
        or not parent_tokens
        or parent_tokens[0] != candidate_commit_sha
        or len(parent_tokens) != 2
    ):
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_base_lineage_ambiguous",
            field="candidate_parent_count",
            expected=1,
            actual=max(len(parent_tokens) - 1, 0),
        )
    comparison_base = _contract_runtime_full_commit_value(
        project_id,
        parent_tokens[1],
    )
    if not comparison_base or comparison_base == candidate_commit_sha:
        return _qa_exact_candidate_direct_main_comparison_failure(
            "exact_candidate_direct_main_base_commit_unavailable",
            field="comparison_base_commit_sha",
            expected="available full commit distinct from candidate",
            actual="missing_or_equal_to_candidate",
        )
    strict_records = _operator_supervised_direct_main_strict_records(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
    )
    matching_strict_records = [
        record
        for record in strict_records
        if str(record.get("contract_execution_id") or "").strip()
        == task_id
    ]
    if matching_strict_records:
        if len(strict_records) != 1 or len(matching_strict_records) != 1:
            return _qa_exact_candidate_direct_main_comparison_failure(
                "exact_candidate_direct_main_runtime_binding_invalid",
                field="strict_runtime_record_count",
                expected=1,
                actual=len(matching_strict_records),
            )
        return _qa_exact_candidate_direct_main_strict_comparison_authority(
            strict_record=matching_strict_records[0],
            direct_event=direct_event,
            implementation_event=authoritative_events[0],
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            project_root=Path(project_root).resolve(),
            candidate_commit_sha=candidate_commit_sha,
            comparison_base=comparison_base,
        )
    return {
        "commit_sha": comparison_base,
        "source": _QA_DIRECT_MAIN_COMPARISON_BASE_SOURCE,
        "lineage_source": _QA_DIRECT_MAIN_COMPARISON_LINEAGE_SOURCE,
    }


def _qa_exact_candidate_postmerge_records(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
) -> list[Mapping[str, Any]]:
    """Return exact-execution post-merge records without trusting QA claims."""

    runtime_store = _contract_runtime_store(conn)
    candidate_records: list[Mapping[str, Any]] = []
    if contract_execution_id:
        try:
            direct_record = runtime_store.get(contract_execution_id)
        except ContractRuntimeError as exc:
            if str(exc) != (
                f"unknown contract execution: {contract_execution_id}"
            ):
                raise
        else:
            if isinstance(direct_record, Mapping):
                candidate_records.append(direct_record)
    list_by_backlog = getattr(runtime_store, "list_by_backlog", None)
    if callable(list_by_backlog) and backlog_id:
        candidate_records.extend(
            record
            for record in list_by_backlog(
                project_id=project_id,
                backlog_id=backlog_id,
            )
            if isinstance(record, Mapping)
        )
    postmerge_records: dict[str, Mapping[str, Any]] = {}
    for record in candidate_records:
        if not _is_mf_parallel_postmerge_revision(record):
            continue
        execution_id = str(
            record.get("contract_execution_id") or ""
        ).strip()
        if execution_id == contract_execution_id:
            postmerge_records[stable_sha256(record)] = record
    return list(postmerge_records.values())


def _qa_exact_candidate_postmerge_comparison_authority_for_record(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    candidate_commit_sha: str,
    record: Mapping[str, Any],
) -> dict[str, str]:
    """Resolve one combined candidate from server-verified post-merge state."""

    execution_id = str(record.get("contract_execution_id") or "").strip()
    if not (
        execution_id
        and str(record.get("project_id") or "").strip() == project_id
        and str(record.get("backlog_id") or "").strip() == backlog_id
    ):
        return {}
    postmerge = _contract_runtime_rev8_postmerge_qa_authority(
        conn,
        project_id=project_id,
        record=record,
    )
    unsigned_postmerge = {
        key: value
        for key, value in postmerge.items()
        if key != "authority_hash"
    }
    current_world_verified = bool(
        postmerge.get("verified") is True
        and postmerge.get("server_derived") is True
        and postmerge.get("db_verified") is True
        and postmerge.get("live_verified") is True
        and postmerge.get("graph_reconciled") is True
        and postmerge.get("active_snapshot_verified") is True
        and str(postmerge.get("project_id") or "").strip() == project_id
        and str(postmerge.get("backlog_id") or "").strip() == backlog_id
        and str(postmerge.get("contract_execution_id") or "").strip()
        == execution_id
        and str(postmerge.get("parent_task_id") or "").strip()
        == execution_id
        and str(postmerge.get("qa_graph_trace_task_id") or "").strip()
        == execution_id
        and str(postmerge.get("qa_graph_trace_task_source") or "").strip()
        == "ContractRuntime.contract_execution_id"
        and str(postmerge.get("candidate_commit_sha") or "").strip().lower()
        == candidate_commit_sha
        and str(postmerge.get("reconciled_commit_sha") or "").strip().lower()
        == candidate_commit_sha
        and str(postmerge.get("canonical_head_commit") or "").strip().lower()
        == candidate_commit_sha
        and str(postmerge.get("active_snapshot_commit") or "").strip().lower()
        == candidate_commit_sha
        and str(postmerge.get("authority_hash") or "").strip()
        == stable_sha256(unsigned_postmerge)
    )
    if current_world_verified:
        comparison = _contract_runtime_server_comparison_authority(
            conn,
            project_id=project_id,
            record=record,
            expected_candidate_commit=candidate_commit_sha,
        )
        if not (
            comparison.get("commit_sha")
            and comparison.get("source")
            == _QA_POSTMERGE_COMPARISON_BASE_SOURCE
        ):
            return {}
        return {
            **comparison,
            "lineage_source": _QA_POSTMERGE_COMPARISON_LINEAGE_SOURCE,
        }

    comparison_base = (
        _contract_runtime_server_postmerge_comparison_base_commit(
            conn,
            project_id=project_id,
            record=record,
            expected_candidate_commit=candidate_commit_sha,
        )
    )
    if not comparison_base:
        return {}
    project_root = project_service.resolve_project_root(
        project_id,
        None,
        fallback_self=True,
    )
    if project_root is None:
        return {}
    try:
        _qa_exact_candidate_diff_identity(
            Path(project_root).resolve(),
            base_commit_sha=comparison_base,
            candidate_commit_sha=candidate_commit_sha,
            comparison_base_commit_source=(
                _QA_POSTMERGE_COMPARISON_BASE_SOURCE
            ),
        )
    except _QACandidateOverlayError:
        return {}
    return {
        "commit_sha": comparison_base,
        "source": _QA_POSTMERGE_COMPARISON_BASE_SOURCE,
        "lineage_source": (
            _QA_EXISTING_POSTMERGE_COMPARISON_LINEAGE_SOURCE
        ),
    }


def _qa_exact_candidate_runtime_comparison_authority(
    conn,
    *,
    project_id: str,
    proof: Mapping[str, Any],
) -> dict[str, str]:
    """Resolve a worker base only through persisted ContractRuntime authority."""

    from .parallel_branch_runtime import get_branch_context

    task_id = str(proof.get("task_id") or "").strip()
    backlog_id = str(proof.get("backlog_id") or "").strip()
    candidate_commit_sha = _contract_runtime_full_commit_value(
        project_id,
        proof.get("commit_sha"),
    )
    context = get_branch_context(conn, project_id, task_id) if task_id else None
    if context is None:
        postmerge_records = _qa_exact_candidate_postmerge_records(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            contract_execution_id=task_id,
        )
        if postmerge_records:
            if len(postmerge_records) != 1:
                return {
                    "machine_reason": (
                        "postmerge_comparison_authority_ambiguous"
                    ),
                    "source": _QA_POSTMERGE_COMPARISON_BASE_SOURCE,
                    "lineage_source": (
                        _QA_EXISTING_POSTMERGE_COMPARISON_LINEAGE_SOURCE
                    ),
                }
            resolved_authorities: dict[str, dict[str, str]] = {}
            for record in postmerge_records:
                authority = (
                    _qa_exact_candidate_postmerge_comparison_authority_for_record(
                        conn,
                        project_id=project_id,
                        backlog_id=backlog_id,
                        candidate_commit_sha=candidate_commit_sha,
                        record=record,
                    )
                )
                if authority:
                    resolved_authorities[stable_sha256(authority)] = authority
            if len(resolved_authorities) == 1:
                return next(iter(resolved_authorities.values()))
            return {
                "machine_reason": (
                    "postmerge_comparison_authority_ambiguous"
                    if len(resolved_authorities) > 1
                    else "postmerge_comparison_authority_unverified"
                ),
                "source": _QA_POSTMERGE_COMPARISON_BASE_SOURCE,
                "lineage_source": (
                    _QA_POSTMERGE_COMPARISON_LINEAGE_SOURCE
                ),
            }
        return _qa_exact_candidate_direct_main_comparison_authority(
            conn,
            project_id=project_id,
            proof=proof,
        )
    if str(getattr(context, "backlog_id", "") or "").strip() != backlog_id:
        return {}
    execution_ids = [
        str(getattr(context, field, "") or "").strip()
        for field in ("parent_task_id", "root_task_id")
    ]
    runtime_store = _contract_runtime_store(conn)
    candidate_records: list[Mapping[str, Any]] = []
    seen_execution_ids: set[str] = set()
    for execution_id in dict.fromkeys(item for item in execution_ids if item):
        try:
            record = runtime_store.get(execution_id)
        except ContractRuntimeError as exc:
            if str(exc) == f"unknown contract execution: {execution_id}":
                continue
            raise
        if not isinstance(record, Mapping):
            continue
        seen_execution_ids.add(
            str(record.get("contract_execution_id") or execution_id).strip()
        )
        candidate_records.append(record)
    list_by_backlog = getattr(runtime_store, "list_by_backlog", None)
    if callable(list_by_backlog):
        for record in list_by_backlog(
            project_id=project_id,
            backlog_id=backlog_id,
        ):
            if not isinstance(record, Mapping):
                continue
            execution_id = str(
                record.get("contract_execution_id") or ""
            ).strip()
            if execution_id and execution_id in seen_execution_ids:
                continue
            if execution_id:
                seen_execution_ids.add(execution_id)
            candidate_records.append(record)

    resolved_authorities: dict[str, dict[str, str]] = {}
    for record in candidate_records:
        if str(record.get("backlog_id") or "").strip() != backlog_id:
            continue
        dispatch_match = _contract_runtime_dispatch_line_match(record, context)
        if not _contract_runtime_verified_dispatch_lineage(
            record,
            context,
            dispatch_match,
        ):
            continue
        authority = _contract_runtime_server_comparison_authority(
            conn,
            project_id=project_id,
            record=record,
            expected_candidate_commit=candidate_commit_sha,
            expected_context=context,
        )
        lane_head_commit = _contract_runtime_full_commit_value(
            project_id,
            getattr(context, "head_commit", ""),
        )
        if (
            not authority
            and candidate_commit_sha
            and lane_head_commit
            and candidate_commit_sha != lane_head_commit
        ):
            # A final QA session may retain its authenticated worker-lane task
            # scope after the observer has merged and reconciled the combined
            # candidate.  The verified dispatch above proves that this lane
            # belongs to the record; the post-merge authority then replaces
            # only the graph task/comparison projection, never the QA proof.
            authority = (
                _qa_exact_candidate_postmerge_comparison_authority_for_record(
                    conn,
                    project_id=project_id,
                    backlog_id=backlog_id,
                    candidate_commit_sha=candidate_commit_sha,
                    record=record,
                )
            )
        if authority:
            resolved_authorities[stable_sha256(authority)] = authority
    return (
        next(iter(resolved_authorities.values()))
        if len(resolved_authorities) == 1
        else {}
    )


def _qa_exact_candidate_runtime_comparison_base(
    conn,
    *,
    project_id: str,
    proof: Mapping[str, Any],
) -> str:
    return str(
        _qa_exact_candidate_runtime_comparison_authority(
            conn,
            project_id=project_id,
            proof=proof,
        ).get("commit_sha")
        or ""
    )


def _qa_exact_candidate_comparison_authority_required(
    conn,
    *,
    project_id: str,
    proof: Mapping[str, Any],
) -> bool:
    from .parallel_branch_runtime import get_branch_context

    task_id = str(proof.get("task_id") or "").strip()
    backlog_id = str(proof.get("backlog_id") or "").strip()
    selected_direct = (
        _operator_supervised_direct_main_selected_execution_identity(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
        if backlog_id
        else {}
    )
    strict_task_id = str(
        selected_direct.get("contract_execution_id") or ""
    ).strip()
    # The deterministic strict Direct task identity is only a requirement
    # selector, never comparison authority.  Missing, mismatched, or ambiguous
    # rev2 records must therefore fail closed instead of silently degrading to
    # an unmanaged self-comparison snapshot.
    if strict_task_id and task_id == strict_task_id:
        return True
    if (
        selected_direct.get("ambiguous") is True
        and task_id
        in set(selected_direct.get("candidate_execution_ids") or [])
    ):
        return True
    context = get_branch_context(conn, project_id, task_id) if task_id else None
    if context is not None:
        return bool(
            backlog_id
            and str(getattr(context, "backlog_id", "") or "").strip()
            == backlog_id
        )
    if task_id:
        if _qa_exact_candidate_postmerge_records(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            contract_execution_id=task_id,
        ):
            return True
    direct_events = _qa_exact_candidate_direct_main_events(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
    )
    # Once an accepted Direct Main pre-mutation boundary exists, exact-candidate
    # QA must resolve its unique commit-bound implementation lineage.  Treating
    # a missing, forged, or ambiguous implementation as "authority optional"
    # would silently collapse the immutable parent comparison back to the
    # candidate snapshot commit.
    return bool(direct_events)


def _qa_exact_candidate_context(
    project_root: Path,
    *,
    project_id: str,
    canonical_project_root: Path,
    candidate_commit_sha: str,
    escalation: Mapping[str, Any] | None = None,
    comparison_base_commit_sha: str = "",
    comparison_base_commit_source: str = "",
    comparison_base_commit_lineage_source: str = "",
    comparison_authority_required: bool = False,
    registered_allocator_worktree_paths: Sequence[str] = (),
    exact_snapshot_materialization_provenance: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    from . import graph_query_trace

    candidate_commit_sha = str(candidate_commit_sha or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", candidate_commit_sha):
        _qa_overlay_fail(
            "exact_candidate_commit_invalid",
            "exact candidate graph review requires a full candidate commit",
            candidate_commit_sha=candidate_commit_sha,
        )
    root_identity = _qa_checkout_root_identity(
        project_id=project_id,
        query_root=Path(project_root).resolve(),
        canonical_root=Path(canonical_project_root).resolve(),
        base_commit_sha=candidate_commit_sha,
        candidate_commit_sha=candidate_commit_sha,
        require_canonical_base_head=False,
        require_query_candidate_head=True,
        registered_allocator_worktree_paths=(
            registered_allocator_worktree_paths
        ),
        exact_snapshot_materialization_provenance=(
            exact_snapshot_materialization_provenance
        ),
    )
    comparison_base_commit_sha = str(
        comparison_base_commit_sha or ""
    ).strip().lower()
    comparison_authority_required = bool(comparison_authority_required)
    root_identity["comparison_authority_required"] = (
        comparison_authority_required
    )
    comparison_base_commit_lineage_source = str(
        comparison_base_commit_lineage_source or ""
    ).strip()
    if comparison_base_commit_lineage_source:
        root_identity["comparison_base_commit_lineage_source"] = (
            comparison_base_commit_lineage_source
        )
    if comparison_authority_required and not comparison_base_commit_sha:
        _qa_overlay_fail(
            "exact_candidate_comparison_base_required",
            "managed exact candidate review requires a trusted comparison base",
            identity_mismatches=[
                {
                    "field": "comparison_base_commit_sha",
                    "expected": (
                        "full distinct trusted ContractRuntime comparison base"
                    ),
                    "actual": "",
                }
            ],
        )
    if comparison_base_commit_sha:
        diff_identity = _qa_exact_candidate_diff_identity(
            project_root,
            base_commit_sha=comparison_base_commit_sha,
            candidate_commit_sha=candidate_commit_sha,
            comparison_base_commit_source=(
                comparison_base_commit_source
                or _QA_WORKER_COMPARISON_BASE_SOURCE
            ),
        )
        root_identity.update(
            {
                "comparison_base_commit_sha": diff_identity[
                    "comparison_base_commit_sha"
                ],
                "comparison_base_commit_source": diff_identity[
                    "comparison_base_commit_source"
                ],
            }
        )
    else:
        diff_identity = {
            "changed_files": [],
            "candidate_diff_hash": (
                "sha256:" + hashlib.sha256(b"").hexdigest()
            ),
            "changed_files_source": "server_exact_candidate_snapshot",
            "comparison_base_commit_sha": "",
            "comparison_base_commit_source": "",
        }
    escalation = escalation if isinstance(escalation, Mapping) else {}
    graph_basis_decision = graph_query_trace.bounded_qa_graph_basis_decision(
        "exact_candidate_snapshot",
        root_identity,
        exact_candidate_upgrade_trigger=str(
            escalation.get("exact_candidate_upgrade_trigger") or ""
        ),
        candidate_change_classification=str(
            escalation.get("candidate_change_classification") or ""
        ),
        exact_candidate_upgrade_ref=str(
            escalation.get("escalation_id") or ""
        ),
    )
    return {
        **diff_identity,
        "comparison_base_commit_lineage_source": (
            comparison_base_commit_lineage_source
        ),
        "comparison_authority_required": comparison_authority_required,
        "graph_basis_decision": graph_basis_decision,
        "graph_basis_decision_hash": stable_sha256(graph_basis_decision),
        "root_identity": root_identity,
        "root_identity_hash": stable_sha256(root_identity),
        "query_root_identity_hash": root_identity["query_root_identity_hash"],
        "canonical_project_identity_hash": root_identity[
            "canonical_project_identity_hash"
        ],
        "repository_identity_hash": root_identity["repository_identity_hash"],
    }


def _qa_candidate_diff_context(
    project_root: Path,
    *,
    project_id: str,
    canonical_project_root: Path,
    base_commit_sha: str,
    candidate_commit_sha: str,
    allow_historical_audit_descendant: bool = False,
) -> dict[str, Any]:
    from . import graph_query_trace

    query_root = Path(project_root).resolve()
    canonical_root = Path(canonical_project_root).resolve()
    base_commit_sha = str(base_commit_sha or "").strip().lower()
    candidate_commit_sha = str(candidate_commit_sha or "").strip().lower()

    for field, commit_sha in (
        ("base_commit_sha", base_commit_sha),
        ("candidate_commit_sha", candidate_commit_sha),
    ):
        resolved = _qa_git_bytes(
            canonical_root, ["rev-parse", "--verify", f"{commit_sha}^{{commit}}"]
        )
        resolved_sha = resolved.stdout.decode("ascii", errors="ignore").strip().lower()
        if resolved.returncode != 0 or resolved_sha != commit_sha:
            _qa_overlay_fail(
                "commit_unavailable_requires_exact_candidate_snapshot",
                f"{field} is not an available full commit",
                field=field,
                commit_sha=commit_sha,
            )
    ancestry = _qa_git_bytes(
        canonical_root,
        ["merge-base", "--is-ancestor", base_commit_sha, candidate_commit_sha],
    )
    if ancestry.returncode != 0:
        _qa_overlay_fail(
            "non_descendant_candidate_requires_exact_candidate_snapshot",
            "canonical base commit is not an ancestor of candidate commit",
        )

    root_identity = _qa_checkout_root_identity(
        project_id=project_id,
        query_root=query_root,
        canonical_root=canonical_root,
        base_commit_sha=base_commit_sha,
        candidate_commit_sha=candidate_commit_sha,
        require_canonical_base_head=not allow_historical_audit_descendant,
        require_query_review_head=not allow_historical_audit_descendant,
    )
    if allow_historical_audit_descendant:
        canonical_head_commit = str(
            root_identity.get("canonical_head_commit") or ""
        ).strip().lower()
        candidate_to_head = _qa_git_bytes(
            canonical_root,
            [
                "merge-base",
                "--is-ancestor",
                candidate_commit_sha,
                canonical_head_commit,
            ],
        )
        if candidate_to_head.returncode != 0:
            _qa_overlay_fail(
                "historical_candidate_not_ancestor_of_current_head",
                (
                    "historical audit-only overlay requires the reviewed "
                    "candidate to be an ancestor of current canonical HEAD"
                ),
                candidate_commit_sha=candidate_commit_sha,
                canonical_head_commit=canonical_head_commit,
            )
        root_identity["canonical_head_relation"] = (
            "candidate"
            if canonical_head_commit == candidate_commit_sha
            else "descendant_of_candidate"
        )
        root_identity["historical_audit_only"] = True
    changed = _qa_git_bytes(
        canonical_root,
        [
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--name-status",
            "-z",
            "-M",
            f"{base_commit_sha}..{candidate_commit_sha}",
            "--",
            ".",
        ],
    )
    if changed.returncode != 0:
        _qa_overlay_fail(
            "diff_unavailable_requires_exact_candidate_snapshot",
            "server could not derive candidate file changes",
        )
    file_changes = _qa_parse_name_status_z(changed.stdout)
    if len(file_changes) > _QA_OVERLAY_MAX_FILES:
        _qa_overlay_fail(
            "changed_file_limit_requires_exact_candidate_snapshot",
            "candidate overlay changed-file limit was exceeded",
            changed_file_count=len(file_changes),
            max_changed_files=_QA_OVERLAY_MAX_FILES,
        )
    _qa_overlay_preflight_total_source_bytes(
        canonical_root,
        base_commit_sha=base_commit_sha,
        candidate_commit_sha=candidate_commit_sha,
        file_changes=file_changes,
    )

    overlay_files: list[dict[str, Any]] = []
    candidate_sources: dict[str, dict[str, Any]] = {}
    total_bytes = 0
    total_symbols = 0
    oversized_fallback_files: set[str] = set()
    status_counts = {key: 0 for key in ("A", "M", "D", "R")}
    symbol_counts = {key: 0 for key in ("added", "modified", "removed")}
    for change in file_changes:
        status = str(change["status"])
        path = str(change["path"])
        old_path = str(change.get("old_path") or "")
        base_path = old_path if status == "R" else path
        base_source: str | None = None
        candidate_source: str | None = None
        base_bytes = 0
        candidate_bytes = 0
        base_inspection: dict[str, Any] = {}
        candidate_inspection: dict[str, Any] = {}
        if status != "A":
            base_source, base_bytes, base_inspection = _qa_git_object_source(
                canonical_root, commit_sha=base_commit_sha, path=base_path
            )
        if status != "D":
            candidate_source, candidate_bytes, candidate_inspection = _qa_git_object_source(
                canonical_root, commit_sha=candidate_commit_sha, path=path
            )
        if base_inspection.get("fallback_reason"):
            oversized_fallback_files.add(base_path)
        if candidate_inspection.get("fallback_reason"):
            oversized_fallback_files.add(path)
        total_bytes += base_bytes + candidate_bytes
        if total_bytes > _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES:
            elevated_fallback_activated = bool(oversized_fallback_files)
            _qa_overlay_fail(
                "total_source_limit_requires_exact_candidate_snapshot",
                "candidate overlay total source limit was exceeded",
                ordinary_max_total_bytes=_QA_OVERLAY_MAX_TOTAL_BYTES,
                effective_max_total_bytes=(
                    _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
                    if elevated_fallback_activated
                    else _QA_OVERLAY_MAX_TOTAL_BYTES
                ),
                elevated_fallback_activated=elevated_fallback_activated,
                fallback_reason=(
                    _QA_OVERLAY_OVERSIZED_SOURCE_POLICY
                    if elevated_fallback_activated
                    else ""
                ),
                inspected_source_bytes=total_bytes,
            )
        _qa_overlay_assert_safe_interpretation(
            path=path,
            old_path=old_path,
            base_source=base_source,
            candidate_source=candidate_source,
        )
        base_version = (
            _qa_overlay_version(
                base_path, base_source, base_bytes, base_inspection
            )
            if base_source is not None
            else None
        )
        candidate_version = (
            _qa_overlay_version(
                path, candidate_source, candidate_bytes, candidate_inspection
            )
            if candidate_source is not None
            else None
        )
        symbol_delta = _qa_overlay_symbol_delta(base_version, candidate_version)
        total_symbols += sum(symbol_delta["counts"].values())
        if total_symbols > _QA_OVERLAY_MAX_SYMBOLS:
            _qa_overlay_fail(
                "symbol_limit_requires_exact_candidate_snapshot",
                "candidate overlay public-symbol delta limit was exceeded",
                max_symbols=_QA_OVERLAY_MAX_SYMBOLS,
            )
        for key in symbol_counts:
            symbol_counts[key] += int(symbol_delta["counts"][key])
        status_counts[status] += 1
        file_kind = _qa_overlay_file_kind(path)
        language = str(
            (candidate_version or base_version or {}).get("language") or ""
        )
        overlay_files.append(
            {
                **change,
                "file_kind": file_kind,
                "language": language,
                "source_fallbacks": {
                    key: dict(inspection)
                    for key, inspection in (
                        ("base", base_inspection),
                        ("candidate", candidate_inspection),
                    )
                    if inspection.get("fallback_reason")
                },
                "base": base_version,
                "candidate": candidate_version,
                "symbol_delta": symbol_delta,
            }
        )
        source_entry = {
            "status": status,
            "path": path,
            "old_path": old_path,
            "base": base_source,
            "candidate": candidate_source,
        }
        candidate_sources[path] = source_entry
        if old_path:
            candidate_sources[old_path] = source_entry

    elevated_fallback_activated = bool(oversized_fallback_files)
    effective_max_total_bytes = (
        _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
        if elevated_fallback_activated
        else _QA_OVERLAY_MAX_TOTAL_BYTES
    )
    if total_bytes > effective_max_total_bytes:
        _qa_overlay_fail(
            "total_source_limit_requires_exact_candidate_snapshot",
            "candidate overlay total source limit was exceeded",
            ordinary_max_total_bytes=_QA_OVERLAY_MAX_TOTAL_BYTES,
            effective_max_total_bytes=effective_max_total_bytes,
            elevated_fallback_max_total_bytes=(
                _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
            ),
            elevated_fallback_activated=elevated_fallback_activated,
            fallback_reason=(
                _QA_OVERLAY_OVERSIZED_SOURCE_POLICY
                if elevated_fallback_activated
                else ""
            ),
            inspected_source_bytes=total_bytes,
        )

    source_inspection_budget = {
        "schema_version": "qa_review_graph.source_inspection_budget.v1",
        "ordinary_max_total_bytes": _QA_OVERLAY_MAX_TOTAL_BYTES,
        "effective_max_total_bytes": effective_max_total_bytes,
        "elevated_fallback_max_total_bytes": (
            _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
        ),
        "elevated_fallback_activated": elevated_fallback_activated,
        "activation_reason": (
            _QA_OVERLAY_OVERSIZED_SOURCE_POLICY
            if elevated_fallback_activated
            else ""
        ),
        "fallback_files": sorted(oversized_fallback_files),
        "inspected_source_bytes": total_bytes,
        "counts_base_and_candidate_blobs": True,
    }

    impact = {
        kind: sorted(
            {
                str(item.get("path") or "")
                for item in overlay_files
                if str(item.get("file_kind") or "") == kind
                and str(item.get("path") or "")
            }
        )
        for kind in ("source", "test", "doc", "config", "other")
    }
    overlay = {
        "schema_version": "qa_review_graph.overlay.v1",
        "graph_basis": "canonical_base_plus_candidate_diff",
        "base_commit_sha": base_commit_sha,
        "candidate_commit_sha": candidate_commit_sha,
        "files": overlay_files,
        "source_inspection_budget": source_inspection_budget,
        "summary": {
            "file_count": len(overlay_files),
            "status_counts": status_counts,
            "public_symbol_delta_counts": symbol_counts,
            "source_bytes_inspected": total_bytes,
        },
        "impact": impact,
        "limits": {
            "max_files": _QA_OVERLAY_MAX_FILES,
            "max_file_bytes": _QA_OVERLAY_MAX_FILE_BYTES,
            "max_total_bytes": _QA_OVERLAY_MAX_TOTAL_BYTES,
            "max_total_bytes_with_oversized_supported_source": (
                _QA_OVERLAY_OVERSIZED_SOURCE_MAX_TOTAL_BYTES
            ),
            "max_symbols": _QA_OVERLAY_MAX_SYMBOLS,
        },
    }
    diff = _qa_git_bytes(
        canonical_root,
        [
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--binary",
            "--full-index",
            "-M",
            f"{base_commit_sha}..{candidate_commit_sha}",
            "--",
            ".",
        ],
    )
    if diff.returncode != 0:
        _qa_overlay_fail(
            "diff_hash_unavailable_requires_exact_candidate_snapshot",
            "server could not hash the candidate diff",
        )
    changed_files: list[str] = []
    for item in file_changes:
        for candidate_path in (item.get("old_path"), item.get("path")):
            normalized = str(candidate_path or "")
            if normalized and normalized not in changed_files:
                changed_files.append(normalized)
    root_identity_hash = stable_sha256(root_identity)
    graph_basis_decision = graph_query_trace.bounded_qa_graph_basis_decision(
        "canonical_base_plus_candidate_diff",
        root_identity,
    )
    return {
        "changed_files": changed_files,
        "candidate_diff_hash": f"sha256:{hashlib.sha256(diff.stdout).hexdigest()}",
        "changed_files_source": "server_git_diff_name_status_z_m",
        "candidate_overlay": overlay,
        "candidate_overlay_hash": stable_sha256(overlay),
        "graph_basis_decision": graph_basis_decision,
        "graph_basis_decision_hash": stable_sha256(graph_basis_decision),
        "root_identity": root_identity,
        "root_identity_hash": root_identity_hash,
        "query_root_identity_hash": root_identity["query_root_identity_hash"],
        "canonical_project_identity_hash": root_identity[
            "canonical_project_identity_hash"
        ],
        "repository_identity_hash": root_identity["repository_identity_hash"],
        "_candidate_sources": candidate_sources,
    }


