def _qa_external_no_pass_failure_set_authority(
    ledger: Mapping[str, Any],
) -> dict[str, Any]:
    """Validate identical or exact parent-only fixed no-PASS failures.

    The immutable baseline may contain failures that the candidate fixed.  In
    that case the caller must name the exact parent-only difference in
    ``fixed_base_failure_identities``.  Candidate-only failures remain
    ineligible because they are candidate-new by definition.  Keeping this
    predicate shared prevents the timeline QA facade and ContractRuntime from
    drifting on the same strict-v2 ledger.
    """

    if not isinstance(ledger, Mapping):
        return {}
    base_reproduction = (
        ledger.get("base_reproduction")
        if isinstance(ledger.get("base_reproduction"), Mapping)
        else {}
    )
    candidate_counts = (
        ledger.get("candidate_suite_counts")
        if isinstance(ledger.get("candidate_suite_counts"), Mapping)
        else {}
    )
    if not (
        _QA_EXTERNAL_NO_PASS_COMPARISON_LEDGER_REQUIRED_KEYS <= set(ledger)
        and _QA_EXTERNAL_NO_PASS_BASE_REPRODUCTION_REQUIRED_KEYS
        <= set(base_reproduction)
        and _QA_EXTERNAL_NO_PASS_CANDIDATE_COUNTS_REQUIRED_KEYS
        <= set(candidate_counts)
    ):
        return {}

    def _failure_identities(value: Any) -> list[str]:
        if not isinstance(value, (list, tuple)):
            return []
        identities = [str(item or "").strip() for item in value]
        if (
            not identities
            or any(not item for item in identities)
            or len(set(identities)) != len(identities)
        ):
            return []
        return sorted(identities)

    base_failures = _failure_identities(
        ledger.get("base_failure_identities")
    )
    reproduced_failures = _failure_identities(
        base_reproduction.get("failure_identities")
    )
    candidate_failures = _failure_identities(
        ledger.get("candidate_failure_identities")
    )
    fixed_field_present = "fixed_base_failure_identities" in ledger
    fixed_base_failures = (
        _failure_identities(ledger.get("fixed_base_failure_identities"))
        if fixed_field_present
        else []
    )
    refs = _failure_identities(ledger.get("refs"))
    reproduced = base_reproduction.get("reproduced")
    total = base_reproduction.get("total")
    failed_count = candidate_counts.get("failed")
    passed_count = candidate_counts.get("passed")
    expected_fixed_base_failures = sorted(
        set(base_failures) - set(candidate_failures)
    )
    failure_sets_valid = bool(
        base_failures
        and candidate_failures
        and base_failures == reproduced_failures
        and (
            (
                fixed_field_present
                and fixed_base_failures
                and not (set(fixed_base_failures) & set(candidate_failures))
                and fixed_base_failures == expected_fixed_base_failures
                and base_failures
                == sorted([*candidate_failures, *fixed_base_failures])
            )
            or (
                not fixed_field_present
                and not expected_fixed_base_failures
                and base_failures == candidate_failures
            )
        )
    )
    if not (
        failure_sets_valid
        and isinstance(reproduced, int)
        and not isinstance(reproduced, bool)
        and isinstance(total, int)
        and not isinstance(total, bool)
        and reproduced == total == len(base_failures)
        and candidate_counts.get("baseline_known_non_green")
        == len(base_failures)
        and isinstance(failed_count, int)
        and not isinstance(failed_count, bool)
        and failed_count == len(candidate_failures)
        and isinstance(passed_count, int)
        and not isinstance(passed_count, bool)
        and passed_count > 0
        and refs
    ):
        return {}
    return {
        "base_failure_identities": base_failures,
        "candidate_failure_identities": candidate_failures,
        "fixed_base_failure_identities": fixed_base_failures,
        "base_reproduction": {
            **dict(base_reproduction),
            "failure_identities": reproduced_failures,
        },
        "candidate_suite_counts": dict(candidate_counts),
        "refs": refs,
    }


def _qa_is_immutable_external_audit_subtree(
    path: tuple[str, ...],
    value: Any,
) -> bool:
    """Identify the one raw external-source namespace excluded from authority."""

    if path not in _QA_IMMUTABLE_EXTERNAL_AUDIT_PATHS or not isinstance(
        value,
        Mapping,
    ):
        return False
    schema_version = str(value.get("schema_version") or "").strip().lower()
    authority_scope = str(value.get("authority_scope") or "").strip().lower()
    return bool(
        (
            not schema_version
            or schema_version in _QA_IMMUTABLE_EXTERNAL_AUDIT_SCHEMAS
        )
        and (
            not authority_scope
            or authority_scope in _QA_IMMUTABLE_EXTERNAL_AUDIT_SCOPES
        )
    )


def _qa_is_non_authoritative_differential_subtree(
    path: tuple[str, ...],
    value: Any,
    *,
    candidate_commit_sha: str,
) -> bool:
    """Exclude one explicitly non-authoritative differential namespace.

    This exception is deliberately narrower than a caller-selected authority
    scope.  Only the exact ``artifact_refs.affected_differential`` mapping is
    eligible, and it must opt out of both PASS use and graph-comparison
    authority.  Candidate identity inside the artifact remains bound to the
    server-derived candidate, while nested authority containers, comparison
    ledgers, or QA-session identities make the subtree ordinary (and thus
    subject to the recursive graph-review checks).
    """

    if (
        path not in _QA_NON_AUTHORITATIVE_DIFFERENTIAL_PATHS
        or not isinstance(value, Mapping)
        or str(value.get("classification") or "").strip().lower()
        != _QA_NON_AUTHORITATIVE_DIFFERENTIAL_CLASSIFICATION
        or value.get("used_as_pass") is not False
        or value.get("graph_comparison_authority_claimed") is not False
        or value.get("overall_release_pass_claimed") is not False
        or str(value.get("full_suite_claim") or "").strip().lower()
        != "not_claimed"
        or value.get("no_pass_claim") is not True
        or type(value.get("candidate_new_failures")) is not int
        or value.get("candidate_new_failures") != 0
    ):
        return False

    expected_candidate = str(candidate_commit_sha or "").strip().lower()
    invalid = False

    def inspect(nested: Any) -> None:
        nonlocal invalid
        if invalid:
            return
        if isinstance(nested, Mapping):
            for raw_key, child in nested.items():
                key = str(raw_key or "").strip().lower()
                if (
                    key in _QA_REVIEW_AUTHORITY_CONTAINERS
                    or key == "external_no_pass_baseline_ledger"
                    or key in {
                        "qa_session_id",
                        "qa_session_token_ref",
                        "qa_scope_binding_ref",
                    }
                ):
                    invalid = True
                    return
                if key in {"candidate_commit", "candidate_commit_sha"}:
                    actual_candidate = str(child or "").strip().lower()
                    if (
                        not expected_candidate
                        or actual_candidate != expected_candidate
                    ):
                        invalid = True
                        return
                inspect(child)
        elif isinstance(nested, (list, tuple)):
            for child in nested:
                inspect(child)

    inspect(value)
    return not invalid


def _qa_review_claim_containers(
    value: Any,
    *,
    _path: tuple[str, ...] = (),
    _candidate_commit_sha: str = "",
) -> list[tuple[tuple[str, ...], Mapping[str, Any]]]:
    if isinstance(value, Mapping):
        result: list[tuple[tuple[str, ...], Mapping[str, Any]]] = [
            (_path, value)
        ]
        for key, child in value.items():
            child_path = (*_path, str(key or "").strip())
            if _qa_is_immutable_external_audit_subtree(child_path, child):
                continue
            if _qa_is_non_authoritative_differential_subtree(
                child_path,
                child,
                candidate_commit_sha=_candidate_commit_sha,
            ):
                continue
            result.extend(
                _qa_review_claim_containers(
                    child,
                    _path=child_path,
                    _candidate_commit_sha=_candidate_commit_sha,
                )
            )
        return result
    if isinstance(value, list):
        result = []
        for index, child in enumerate(value):
            child_path = (
                (*_path, f"[{index}]")
                if _path in _QA_NON_AUTHORITATIVE_DIFFERENTIAL_PATHS
                else _path
            )
            result.extend(
                _qa_review_claim_containers(
                    child,
                    _path=child_path,
                    _candidate_commit_sha=_candidate_commit_sha,
                )
            )
        return result
    return []


def _qa_external_no_pass_comparison_tuple(
    body: Mapping[str, Any],
) -> dict[str, str]:
    """Return the narrow no-PASS base/candidate comparison namespace.

    The graph snapshot base remains candidate-scoped for an exact-candidate
    graph.  A separately reproduced non-green baseline may name an ancestor
    only when the canonical QA payload and its v2 external ledger agree.  The
    caller still has to match this tuple to the server-derived review context.
    """

    payload = body.get("payload")
    artifact_refs = body.get("artifact_refs")
    ledger = (
        artifact_refs.get("external_no_pass_baseline_ledger")
        if isinstance(artifact_refs, Mapping)
        else None
    )
    if not isinstance(payload, Mapping) or not isinstance(ledger, Mapping):
        return {}
    payload_schema = str(payload.get("schema_version") or "").strip()
    ledger_schema = str(ledger.get("schema_version") or "").strip()
    payload_issue_claims = payload.get("candidate_specific_issues")
    ledger_issue_claims = ledger.get("candidate_specific_issues")
    body_status = str(body.get("status") or "").strip().lower()
    qa_acceptance = (
        payload.get("qa_acceptance")
        if isinstance(payload.get("qa_acceptance"), Mapping)
        else {}
    )
    payload_targeted_scope_only = payload.get("targeted_scope_only")
    targeted_scope_pass = bool(
        body_status in {"accepted", "ok", "pass", "passed", "success"}
        and payload.get("row_scoped_qa_pass") is True
        and (
            payload_targeted_scope_only is None
            or payload_targeted_scope_only is True
        )
        and payload.get("used_as_pass") is False
        and qa_acceptance.get("passed") is True
        and qa_acceptance.get("targeted_scope_only") is True
        and qa_acceptance.get("used_as_pass") is False
    )
    payload_candidate_new = payload.get("candidate_new_failures")
    if targeted_scope_pass:
        payload_candidate_new_valid = payload_candidate_new is None or (
            type(payload_candidate_new) is int
            and payload_candidate_new == 0
        )
        payload_issue_claims_valid = payload_issue_claims is None or (
            isinstance(payload_issue_claims, list)
            and not payload_issue_claims
        )
        payload_no_pass_valid = (
            payload.get("no_pass_claim") is None
            or payload.get("no_pass_claim") is True
        )
    else:
        payload_candidate_new_valid = (
            type(payload_candidate_new) is int
            and payload_candidate_new == 0
        )
        payload_issue_claims_valid = (
            isinstance(payload_issue_claims, list)
            and not payload_issue_claims
        )
        payload_no_pass_valid = payload.get("no_pass_claim") is True
    if (
        payload_schema not in _QA_EXTERNAL_NO_PASS_COMPARISON_PAYLOAD_SCHEMAS
        or ledger_schema != _QA_EXTERNAL_NO_PASS_COMPARISON_LEDGER_SCHEMA
        or (
            body_status not in {"failed", "fail", "rejected", "blocked"}
            and not targeted_scope_pass
        )
        or not payload_no_pass_valid
        or payload.get("overall_release_pass_claimed") is not False
        or str(payload.get("full_suite_claim") or "").strip()
        != "not_claimed"
        or not payload_candidate_new_valid
        or not payload_issue_claims_valid
        or ledger.get("no_pass_claim") is not True
        or ledger.get("overall_release_pass_claimed") is not False
        or type(ledger.get("candidate_new_failures")) is not int
        or ledger.get("candidate_new_failures") != 0
        or not isinstance(ledger_issue_claims, list)
        or bool(ledger_issue_claims)
    ):
        return {}
    payload_base = str(payload.get("base_commit_sha") or "").strip().lower()
    payload_candidate = str(
        payload.get("candidate_commit_sha") or ""
    ).strip().lower()
    body_candidate = str(body.get("commit_sha") or "").strip().lower()
    ledger_base = str(ledger.get("base_commit_sha") or "").strip().lower()
    ledger_candidate = str(
        ledger.get("candidate_commit_sha") or ""
    ).strip().lower()
    full_commit = re.compile(r"[0-9a-f]{40}|[0-9a-f]{64}")
    if targeted_scope_pass:
        failure_set_authority = _qa_external_no_pass_failure_set_authority(
            ledger
        )
        candidate_claims = [
            claim for claim in (payload_candidate, body_candidate) if claim
        ]
        if not (
            full_commit.fullmatch(ledger_base)
            and full_commit.fullmatch(ledger_candidate)
            and ledger_base != ledger_candidate
            and (not payload_base or payload_base == ledger_base)
            and candidate_claims
            and all(
                full_commit.fullmatch(claim)
                and claim == ledger_candidate
                for claim in candidate_claims
            )
            and failure_set_authority
        ):
            return {}
    elif not (
        full_commit.fullmatch(payload_base)
        and full_commit.fullmatch(payload_candidate)
        and payload_base == ledger_base
        and payload_candidate == ledger_candidate
        and payload_base != payload_candidate
    ):
        return {}
    return {
        "base_commit_sha": ledger_base,
        "candidate_commit_sha": ledger_candidate,
    }


def _qa_is_exact_comparison_test_results_claim(
    body: Mapping[str, Any],
    path: tuple[str, ...],
    value: Mapping[str, Any],
    *,
    candidate_commit_sha: str,
    comparison_base_commit_sha: str,
) -> bool:
    """Identify one server-bound targeted comparison result namespace.

    Exact-candidate QA uses the candidate as the graph basis while a targeted
    differential may reproduce its immutable parent.  The parent commit is a
    comparison identity, not a second graph basis.  Only the two canonical
    test-result locations are eligible, and every no-overall-PASS safety bit
    plus both ends of the server-derived tuple must agree exactly.  Other
    nested claims remain visible to the ordinary recursive validator.
    """

    if path not in _QA_EXACT_COMPARISON_TEST_RESULTS_PATHS:
        return False
    schema_version = str(value.get("schema_version") or "").strip()
    expected_stage = _QA_EXACT_COMPARISON_TEST_RESULTS_SCHEMAS.get(
        schema_version
    )
    candidate = str(candidate_commit_sha or "").strip().lower()
    comparison_base = str(
        comparison_base_commit_sha or ""
    ).strip().lower()
    body_commit = str(body.get("commit_sha") or "").strip().lower()
    value_candidate = str(
        value.get("candidate_commit_sha") or ""
    ).strip().lower()
    value_base = str(value.get("base_commit_sha") or "").strip().lower()
    return bool(
        expected_stage
        and str(value.get("qa_stage") or "").strip().upper()
        == expected_stage
        and str(value.get("scope") or "").strip().lower()
        == "targeted_scoped"
        and str(value.get("verdict") or "").strip().upper() == "PASS"
        and value.get("passed") is True
        and value.get("used_as_pass") is False
        and value.get("close_satisfying") is False
        and value.get("overall_pass_claimed") is False
        and value.get("overall_release_pass_claimed") is False
        and value.get("full_suite_claimed") is False
        and str(value.get("full_suite_status") or "").strip().lower()
        == "not_claimed"
        and type(value.get("candidate_new_failures")) is int
        and value.get("candidate_new_failures") == 0
        and str(body.get("status") or "").strip().lower()
        in {"accepted", "ok", "pass", "passed", "success", "succeeded"}
        and candidate
        and comparison_base
        and candidate != comparison_base
        and body_commit == candidate
        and value_candidate == candidate
        and value_base == comparison_base
    )


def _qa_validate_candidate_review_claims(
    body: Mapping[str, Any],
    review_context: Mapping[str, Any],
) -> None:
    containers = _qa_review_claim_containers(
        body,
        _candidate_commit_sha=str(
            review_context.get("candidate_commit_sha") or ""
        ),
    )
    mismatches: list[dict[str, Any]] = []
    comparison_tuple = _qa_external_no_pass_comparison_tuple(body)
    artifact_refs = (
        body.get("artifact_refs")
        if isinstance(body.get("artifact_refs"), Mapping)
        else {}
    )
    comparison_ledger = artifact_refs.get(
        "external_no_pass_baseline_ledger"
    )
    if isinstance(comparison_ledger, Mapping) and not comparison_tuple:
        mismatches.append(
            {
                "field": "external_no_pass_baseline_ledger",
                "expected": (
                    "canonical server-bound comparison tuple, identical "
                    "failures or an exact declared parent-only fixed-base "
                    "difference, matching counts, candidate_new_failures=0, "
                    "and no overall PASS claim"
                ),
                "actual": "invalid_or_incomplete_comparison_ledger",
                "claim_namespace": "external_no_pass_baseline_comparison",
            }
        )
    comparison_base = str(
        comparison_tuple.get("base_commit_sha") or ""
    ).strip().lower()
    if comparison_tuple:
        expected_comparison_base = str(
            review_context.get("comparison_base_commit_sha") or ""
        ).strip().lower()
        expected_candidate = str(
            review_context.get("candidate_commit_sha") or ""
        ).strip().lower()
        for field, expected, actual in (
            (
                "comparison_base_commit_sha",
                expected_comparison_base,
                comparison_base,
            ),
            (
                "candidate_commit_sha",
                expected_candidate,
                comparison_tuple["candidate_commit_sha"],
            ),
        ):
            if actual != expected:
                mismatches.append(
                    {
                        "field": field,
                        "expected": expected,
                        "actual": actual,
                        "claim_namespace": (
                            "external_no_pass_baseline_comparison"
                        ),
                    }
                )
    for field, field_aliases in _QA_REVIEW_CLAIM_ALIASES.items():
        expected = review_context.get(field)
        for path, container in containers:
            for alias in field_aliases:
                if alias not in container:
                    continue
                if (
                    comparison_tuple
                    and path in _QA_EXTERNAL_NO_PASS_COMPARISON_PATHS
                    and field == "base_commit_sha"
                    and str(container.get(alias) or "").strip().lower()
                    == comparison_base
                ):
                    continue
                if (
                    field == "base_commit_sha"
                    and _qa_is_exact_comparison_test_results_claim(
                        body,
                        path,
                        container,
                        candidate_commit_sha=str(
                            review_context.get("candidate_commit_sha") or ""
                        ),
                        comparison_base_commit_sha=str(
                            review_context.get("comparison_base_commit_sha")
                            or ""
                        ),
                    )
                ):
                    continue
                supplied = container.get(alias)
                if field == "changed_files":
                    if isinstance(supplied, str):
                        actual = [supplied] if supplied.strip() else []
                    elif isinstance(supplied, (list, tuple, set)):
                        actual = [
                            str(item).strip().replace("\\", "/")
                            for item in supplied
                            if str(item).strip()
                        ]
                    else:
                        actual = []
                    # A changed-file tuple is an exact normalized membership
                    # claim, not an ordering claim.  Git-backed producers and
                    # independent QA runners may enumerate the same paths in a
                    # different stable order.  Sort both sides without
                    # deduplicating so missing, extra, duplicate, malformed,
                    # or otherwise different membership still fails closed.
                    actual = sorted(actual)
                    expected_value = sorted(
                        str(item).strip().replace("\\", "/")
                        for item in (expected or [])
                        if str(item).strip()
                    )
                else:
                    actual = str(supplied or "").strip().lower()
                    expected_value = str(expected or "").strip().lower()
                if actual != expected_value:
                    mismatches.append(
                        {
                            "field": alias,
                            "expected": expected_value,
                            "actual": actual,
                        }
                    )
    if mismatches:
        first_mismatch = mismatches[0]
        field = str(first_mismatch.get("field") or "").strip()
        expected = first_mismatch.get("expected")
        actual = first_mismatch.get("actual")
        expected_json = json.dumps(
            expected,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        )
        if field in _QA_REVIEW_CLAIM_ALIASES["changed_files"]:
            correction = (
                f"Remove the caller-supplied `{field}` claim (recommended), "
                f"or replace it exactly with the server-derived value "
                f"`{expected_json}`."
            )
        else:
            correction = (
                f"Remove the caller-supplied `{field}` claim, or replace it "
                f"exactly with the server-derived value `{expected_json}`."
            )
        raise GovernanceError(
            "qa_graph_review_context_mismatch",
            "QA graph review context must match the server-derived candidate tuple",
            409,
            {
                "field": field,
                "expected": expected,
                "actual": actual,
                "identity_mismatches": mismatches,
                "guide": (
                    f"{correction} Preserve the same authenticated QA session, "
                    "graph_trace_ids, backlog_id, task_id, and commit_sha, then "
                    "retry the same graph_query or task_timeline_append request. "
                    "Do not mint a new QA world, bypass, waive, or change "
                    "implementation evidence."
                ),
                "source": (
                    "agent/governance/server.py::"
                    "_qa_validate_candidate_review_claims"
                ),
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )


def _qa_graph_review_context_from_trace_row(
    row: Any,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    trace_id = str(row["trace_id"] or "").strip()
    try:
        changed_files_raw = json.loads(str(row["changed_files_json"] or "[]"))
    except (TypeError, ValueError, json.JSONDecodeError):
        changed_files_raw = None
    changed_files = (
        [
            str(item).strip().replace("\\", "/")
            for item in changed_files_raw
            if str(item).strip()
        ]
        if isinstance(changed_files_raw, list)
        else []
    )
    try:
        candidate_overlay_raw = json.loads(
            str(row["candidate_overlay_json"] or "{}")
        )
    except (TypeError, ValueError, json.JSONDecodeError):
        candidate_overlay_raw = None
    try:
        root_identity_raw = json.loads(str(row["root_identity_json"] or "{}"))
    except (TypeError, ValueError, json.JSONDecodeError):
        root_identity_raw = None
    from . import graph_query_trace

    try:
        persisted_decision = json.loads(
            str(row["graph_basis_decision_json"] or "{}")
        )
    except (IndexError, KeyError, TypeError, ValueError, json.JSONDecodeError):
        persisted_decision = None
    graph_basis_decision = (
        dict(persisted_decision)
        if isinstance(persisted_decision, Mapping) and persisted_decision
        else graph_query_trace.bounded_qa_graph_basis_decision(
            str(row["graph_basis"] or "").strip(),
            root_identity_raw if isinstance(root_identity_raw, Mapping) else {},
        )
    )
    try:
        persisted_decision_hash = str(
            row["graph_basis_decision_hash"] or ""
        ).strip().lower()
    except (IndexError, KeyError, TypeError):
        persisted_decision_hash = ""
    graph_basis_decision_hash = (
        persisted_decision_hash or stable_sha256(graph_basis_decision)
    )
    review_context = {
        "graph_basis": str(row["graph_basis"] or "").strip(),
        "graph_basis_decision": graph_basis_decision,
        "graph_basis_decision_hash": graph_basis_decision_hash,
        "canonical_base_snapshot_id": str(
            row["canonical_base_snapshot_id"] or ""
        ).strip(),
        "base_commit_sha": str(row["base_commit_sha"] or "").strip().lower(),
        "candidate_commit_sha": str(
            row["candidate_commit_sha"] or ""
        ).strip().lower(),
        "changed_files": changed_files,
        "candidate_diff_hash": str(row["candidate_diff_hash"] or "").strip().lower(),
        "changed_files_source": str(row["changed_files_source"] or "").strip(),
        "comparison_base_commit_sha": (
            str(root_identity_raw.get("comparison_base_commit_sha") or "")
            .strip()
            .lower()
            if isinstance(root_identity_raw, Mapping)
            else ""
        ),
        "comparison_base_commit_source": (
            str(root_identity_raw.get("comparison_base_commit_source") or "")
            .strip()
            if isinstance(root_identity_raw, Mapping)
            else ""
        ),
        "comparison_base_commit_lineage_source": (
            str(
                root_identity_raw.get(
                    "comparison_base_commit_lineage_source"
                )
                or ""
            ).strip()
            if isinstance(root_identity_raw, Mapping)
            else ""
        ),
        "comparison_authority_required": bool(
            isinstance(root_identity_raw, Mapping)
            and root_identity_raw.get("comparison_authority_required") is True
        ),
        "candidate_overlay_hash": str(
            row["candidate_overlay_hash"] or ""
        ).strip().lower(),
        "root_identity_hash": str(row["root_identity_hash"] or "").strip().lower(),
        "query_root_identity_hash": str(
            row["query_root_identity_hash"] or ""
        ).strip().lower(),
        "canonical_project_identity_hash": str(
            row["canonical_project_identity_hash"] or ""
        ).strip().lower(),
        "repository_identity_hash": str(
            row["repository_identity_hash"] or ""
        ).strip().lower(),
        "query_root": (
            str(root_identity_raw.get("query_root") or "").strip()
            if isinstance(root_identity_raw, Mapping)
            else ""
        ),
        "canonical_project_root": (
            str(root_identity_raw.get("canonical_project_root") or "").strip()
            if isinstance(root_identity_raw, Mapping)
            else ""
        ),
    }
    expected_context = {
        "canonical_base_snapshot_id": str(row["snapshot_id"] or "").strip(),
        "base_commit_sha": str(row["snapshot_commit_sha"] or "").strip().lower(),
        "candidate_commit_sha": str(row["commit_sha"] or "").strip().lower(),
    }
    mismatches: list[dict[str, Any]] = [
        {
            "trace_id": trace_id,
            "field": field,
            "expected": expected,
            "actual": str(review_context.get(field) or ""),
        }
        for field, expected in expected_context.items()
        if str(review_context.get(field) or "") != expected
    ]
    if graph_basis_decision_hash != stable_sha256(graph_basis_decision):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "graph_basis_decision_hash",
                "expected": stable_sha256(graph_basis_decision),
                "actual": graph_basis_decision_hash,
            }
        )
    graph_basis = review_context["graph_basis"]
    if graph_basis not in {
        "exact_candidate_snapshot",
        "canonical_base_plus_candidate_diff",
    }:
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "graph_basis",
                "expected": (
                    "exact_candidate_snapshot|canonical_base_plus_candidate_diff"
                ),
                "actual": graph_basis,
            }
        )
    diff_hash = review_context["candidate_diff_hash"]
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", diff_hash):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "candidate_diff_hash",
                "expected": "sha256:<64 lowercase hex characters>",
                "actual": diff_hash,
            }
        )
    if not review_context["changed_files_source"].startswith("server_"):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "changed_files_source",
                "expected": "server-derived",
                "actual": review_context["changed_files_source"],
            }
        )
    if changed_files_raw is None:
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "changed_files",
                "expected": "persisted JSON list",
                "actual": "invalid",
            }
        )
    for field in ("base_commit_sha", "candidate_commit_sha"):
        if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", review_context[field]):
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": field,
                    "expected": "full git object id",
                    "actual": review_context[field],
                }
            )
    if graph_basis == "exact_candidate_snapshot":
        if review_context["base_commit_sha"] != review_context["candidate_commit_sha"]:
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": "base_commit_sha",
                    "expected": review_context["candidate_commit_sha"],
                    "actual": review_context["base_commit_sha"],
                }
            )
        empty_diff_hash = f"sha256:{hashlib.sha256(b'').hexdigest()}"
        comparison_base_commit = review_context[
            "comparison_base_commit_sha"
        ]
        comparison_base_source = review_context[
            "comparison_base_commit_source"
        ]
        if comparison_base_commit:
            if not re.fullmatch(
                r"[0-9a-f]{40}|[0-9a-f]{64}", comparison_base_commit
            ) or comparison_base_commit == review_context[
                "candidate_commit_sha"
            ]:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "comparison_base_commit_sha",
                        "expected": "distinct full ancestor commit",
                        "actual": comparison_base_commit,
                    }
                )
            if comparison_base_source not in _QA_COMPARISON_BASE_SOURCES:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "comparison_base_commit_source",
                        "expected": sorted(_QA_COMPARISON_BASE_SOURCES),
                        "actual": comparison_base_source,
                    }
                )
            if review_context["changed_files_source"] != (
                "server_runtime_context_base_to_exact_candidate_diff"
            ):
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "changed_files_source",
                        "expected": (
                            "server_runtime_context_base_to_exact_candidate_diff"
                        ),
                        "actual": review_context["changed_files_source"],
                    }
                )
        else:
            if changed_files:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "changed_files",
                        "expected": [],
                        "actual": changed_files,
                    }
                )
            if review_context["candidate_diff_hash"] != empty_diff_hash:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "candidate_diff_hash",
                        "expected": empty_diff_hash,
                        "actual": review_context["candidate_diff_hash"],
                    }
                )
            if comparison_base_source:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "comparison_base_commit_source",
                        "expected": "",
                        "actual": comparison_base_source,
                    }
                )
        if candidate_overlay_raw or review_context["candidate_overlay_hash"]:
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": "candidate_overlay",
                    "expected": {},
                    "actual": candidate_overlay_raw,
                }
            )
    elif (
        graph_basis == "canonical_base_plus_candidate_diff"
        and review_context["base_commit_sha"]
        == review_context["candidate_commit_sha"]
    ):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "candidate_commit_sha",
                "expected": "different from base_commit_sha",
                "actual": review_context["candidate_commit_sha"],
            }
        )
    if graph_basis in {
        "exact_candidate_snapshot",
        "canonical_base_plus_candidate_diff",
    }:
        for field in (
            "root_identity_hash",
            "query_root_identity_hash",
            "canonical_project_identity_hash",
            "repository_identity_hash",
        ):
            if not re.fullmatch(r"sha256:[0-9a-f]{64}", review_context[field]):
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": field,
                        "expected": "sha256:<64 lowercase hex characters>",
                        "actual": review_context[field],
                    }
                )
        if not isinstance(root_identity_raw, Mapping) or not root_identity_raw:
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": "root_identity",
                    "expected": "persisted JSON object",
                    "actual": "invalid",
                }
            )
        else:
            expected_root_hash = stable_sha256(root_identity_raw)
            if expected_root_hash != review_context["root_identity_hash"]:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "root_identity_hash",
                        "expected": expected_root_hash,
                        "actual": review_context["root_identity_hash"],
                    }
                )
            for field in (
                "query_root_identity_hash",
                "canonical_project_identity_hash",
                "repository_identity_hash",
            ):
                actual = str(root_identity_raw.get(field) or "").strip().lower()
                if actual != review_context[field]:
                    mismatches.append(
                        {
                            "trace_id": trace_id,
                            "field": f"root_identity.{field}",
                            "expected": review_context[field],
                            "actual": actual,
                        }
                    )
    if graph_basis == "canonical_base_plus_candidate_diff":
        if not re.fullmatch(
            r"sha256:[0-9a-f]{64}", review_context["candidate_overlay_hash"]
        ):
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": "candidate_overlay_hash",
                    "expected": "sha256:<64 lowercase hex characters>",
                    "actual": review_context["candidate_overlay_hash"],
                }
            )
        if not isinstance(candidate_overlay_raw, Mapping):
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": "candidate_overlay",
                    "expected": "persisted JSON object",
                    "actual": "invalid",
                }
            )
        elif stable_sha256(candidate_overlay_raw) != review_context[
            "candidate_overlay_hash"
        ]:
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": "candidate_overlay_hash",
                    "expected": stable_sha256(candidate_overlay_raw),
                    "actual": review_context["candidate_overlay_hash"],
                }
            )
    return review_context, mismatches


def _qa_post_merge_deep_text_values(
    value: Any,
    keys: set[str],
    *,
    depth: int = 0,
) -> set[str]:
    if depth > 12:
        return set()
    values: set[str] = set()
    if isinstance(value, Mapping):
        for raw_key, child in value.items():
            key = str(raw_key or "").strip()
            if key in keys:
                text = _runtime_context_non_placeholder_text(child)
                if text:
                    values.add(text)
            values.update(
                _qa_post_merge_deep_text_values(
                    child,
                    keys,
                    depth=depth + 1,
                )
            )
    elif isinstance(value, (list, tuple, set)):
        for child in value:
            values.update(
                _qa_post_merge_deep_text_values(
                    child,
                    keys,
                    depth=depth + 1,
                )
            )
    return values


def _qa_post_merge_resolve_commit(project_root: Path, commit_sha: str) -> str:
    normalized = str(commit_sha or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{7,64}", normalized):
        return ""
    resolved = _qa_git_bytes(
        Path(project_root).resolve(),
        ["rev-parse", "--verify", f"{normalized}^{{commit}}"],
    )
    raw_stdout = resolved.stdout
    full_commit = (
        raw_stdout.decode("ascii", errors="ignore")
        if isinstance(raw_stdout, bytes)
        else str(raw_stdout or "")
    ).strip().lower()
    if resolved.returncode != 0 or not re.fullmatch(
        r"[0-9a-f]{40}|[0-9a-f]{64}",
        full_commit,
    ):
        return ""
    return full_commit


def _qa_exact_candidate_direct_main_post_merge_provenance(
    conn,
    *,
    project_id: str,
    row: Any,
    canonical_project_root: Path,
    candidate_commit_sha: str,
    canonical_head_commit: str,
) -> tuple[dict[str, Any], list[dict[str, Any]], bool]:
    """Re-derive post-merge QA authority for a parentless Direct Main lane.

    A parentless ``operator_supervised_direct_main`` execution intentionally has
    no branch RuntimeContext or durable ``live_merge`` event.  When its exact
    candidate becomes an ancestor of canonical HEAD before independent QA can
    append its verdict, the branch-only provenance gate must not demand those
    impossible identities.  This path is applicable only when the server can
    re-derive the admitted Direct Main exception and implementation from the
    timeline, then prove clean version sync, the current active graph, and (for
    the governance repository itself) the loaded runtime at canonical HEAD.
    """

    trace_id = str(row["trace_id"] or "").strip()
    backlog_id = str(row["backlog_id"] or "").strip()
    task_id = str(row["task_id"] or "").strip()
    candidate_commit = str(candidate_commit_sha or "").strip().lower()
    canonical_head = str(canonical_head_commit or "").strip().lower()

    from .parallel_branch_runtime import get_branch_context

    # A real branch lane remains exclusively governed by the existing
    # RuntimeContext + live_merge provenance path below.
    if get_branch_context(conn, project_id, task_id) is not None:
        return {}, [], False

    try:
        direct_record = _contract_runtime_store(conn).get(task_id)
    except ContractRuntimeError:
        direct_record = {}
    direct_metadata = (
        direct_record.get("metadata")
        if isinstance(direct_record.get("metadata"), Mapping)
        else {}
    )
    strict_direct_binding = (
        direct_metadata.get(
            "operator_supervised_direct_main_runtime_binding"
        )
        if isinstance(
            direct_metadata.get(
                "operator_supervised_direct_main_runtime_binding"
            ),
            Mapping,
        )
        else {}
    )
    legacy_onboard_direct = bool(
        task_id.startswith("onboard-service-")
        and _onboard_service_record(direct_record)
    )
    strict_contract_direct = bool(
        str(direct_record.get("contract_id") or "").strip()
        == "operator_supervised_direct_main"
        and str(direct_record.get("revision") or "").strip()
        in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        and strict_direct_binding.get("strict_runtime_binding_required")
        is True
    )
    if not (
        (legacy_onboard_direct or strict_contract_direct)
        and str(direct_record.get("project_id") or "").strip() == project_id
        and str(direct_record.get("backlog_id") or "").strip() == backlog_id
        and not str(
            direct_record.get("parent_contract_execution_id") or ""
        ).strip()
        and str(
            direct_record.get("root_contract_execution_id") or ""
        ).strip()
        == task_id
    ):
        return {}, [], False

    mismatches: list[dict[str, Any]] = []

    def mismatch(field: str, expected: Any, actual: Any) -> None:
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": field,
                "expected": expected,
                "actual": actual,
            }
        )

    try:
        from . import graph_snapshot_store, task_timeline

        timeline_events = task_timeline.list_events(
            conn,
            project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            limit=1000,
        )
    except Exception:
        timeline_events = []

    backlog_row = conn.execute(
        """
        SELECT target_files, test_files
          FROM backlog_bugs
         WHERE bug_id = ?
        """,
        (backlog_id,),
    ).fetchone()
    row_declared_files: list[str] = []
    if backlog_row is not None:
        for key in ("target_files", "test_files"):
            try:
                raw_files = json.loads(str(backlog_row[key] or "[]"))
            except (KeyError, TypeError, ValueError, json.JSONDecodeError):
                raw_files = []
            if isinstance(raw_files, list):
                row_declared_files.extend(
                    str(path or "").strip()
                    for path in raw_files
                    if str(path or "").strip()
                )
    row_declared_files = _runtime_context_service_dedupe(row_declared_files)

    direct_event: dict[str, Any] = {}
    direct_gate: dict[str, Any] = {}
    direct_identity: dict[str, str] = {}
    for raw_event in timeline_events:
        event = dict(raw_event) if isinstance(raw_event, Mapping) else {}
        if not event:
            continue
        identity = _observer_root_route_identity_from_event(event)
        event_gate = task_timeline.observer_direct_pre_mutation_authority_gate(
            event,
            identity,
            row_declared_files=row_declared_files,
        )
        if not event_gate.get("accepted"):
            continue
        if not _contract_runtime_close_authority_route_token_backed_event(
            event,
            identity,
            require_source_backed_authority=True,
        ):
            continue
        direct_event = event
        direct_gate = event_gate
        direct_identity = identity

    # A selected onboard service without the source-backed Direct Main event is
    # not this lane.  Let the ordinary branch provenance path reject or accept
    # it under its own identities.
    if not direct_event:
        return {}, [], False

    direct_event_id = _contract_runtime_projection_timeline_event_id(direct_event)
    implementation_event = task_timeline._latest_passing_close_event(
        timeline_events,
        "implementation",
        after_event_id=direct_event_id,
    )
    implementation_event_id = _contract_runtime_projection_timeline_event_id(
        implementation_event
    )
    implementation_scope = task_timeline._observer_direct_changed_file_scope(
        implementation_event,
        {"close_context": {"target_files": row_declared_files}},
    )
    implementation_identity = _observer_root_route_identity_from_event(
        implementation_event
    )
    implementation_valid = bool(
        implementation_event
        and str(implementation_event.get("commit_sha") or "").strip().lower()
        == candidate_commit
        and implementation_scope.get("passed") is True
        and _contract_runtime_close_authority_route_token_backed_event(
            implementation_event,
            implementation_identity,
            require_source_backed_authority=True,
        )
    )
    if not implementation_valid:
        mismatch(
            "implementation_event",
            "source-backed Direct Main implementation at exact candidate commit",
            f"timeline:{implementation_event_id}" if implementation_event_id else "missing",
        )

    root_route_ref = str(direct_identity.get("route_token_ref") or "").strip()
    root_route_gate = _contract_runtime_close_authority_first_deep_mapping(
        direct_event,
        "route_token_gate",
    )
    if not (
        root_route_ref
        and root_route_gate.get("registry_verified") is True
        and str(root_route_gate.get("route_token_ref") or "").strip()
        == root_route_ref
    ):
        mismatch(
            "root_route_registry",
            "append-time server-verified Direct Main route registry authority",
            root_route_ref or "missing",
        )

    version_row = conn.execute(
        """
        SELECT git_head, dirty_files, git_synced_at
          FROM project_version
         WHERE project_id = ?
        """,
        (project_id,),
    ).fetchone()
    synced_head = str(version_row["git_head"] or "").strip().lower() if version_row else ""
    git_synced_at = str(version_row["git_synced_at"] or "").strip() if version_row else ""
    try:
        synced_dirty_files = json.loads(
            str(version_row["dirty_files"] or "[]") if version_row else "[]"
        )
    except (TypeError, ValueError, json.JSONDecodeError):
        synced_dirty_files = ["invalid_dirty_files_json"]
    if synced_head != canonical_head or synced_dirty_files or not git_synced_at:
        mismatch(
            "version_sync",
            {"git_head": canonical_head, "dirty_files": [], "git_synced_at": "present"},
            {
                "git_head": synced_head,
                "dirty_files": synced_dirty_files,
                "git_synced_at": git_synced_at,
            },
        )

    active_snapshot = graph_snapshot_store.get_active_graph_snapshot(
        conn,
        project_id,
    ) or {}
    active_snapshot_id = str(active_snapshot.get("snapshot_id") or "").strip()
    active_snapshot_commit = str(active_snapshot.get("commit_sha") or "").strip().lower()
    if not active_snapshot_id or active_snapshot_commit != canonical_head:
        mismatch(
            "active_graph",
            {"snapshot_id": "present", "commit_sha": canonical_head},
            {
                "snapshot_id": active_snapshot_id,
                "commit_sha": active_snapshot_commit,
            },
        )

    self_root = Path(__file__).resolve().parents[2]
    governance_runtime_version = ""
    if Path(canonical_project_root).resolve() == self_root:
        governance_runtime_version = str(
            get_governance_runtime_version(default="") or ""
        ).strip().lower()
        if not (
            governance_runtime_version
            and (
                canonical_head.startswith(governance_runtime_version)
                or governance_runtime_version.startswith(canonical_head)
            )
        ):
            mismatch(
                "governance_runtime_version",
                canonical_head,
                governance_runtime_version or "missing",
            )

    if mismatches:
        return {}, mismatches, True

    authority = {
        "schema_version": "qa_exact_candidate.direct_main_post_merge_provenance.v1",
        "verified": True,
        "server_derived": True,
        "caller_claims_trusted": False,
        "source": (
            "direct_main_timeline+route_registry+git_ancestry+"
            "version_sync+active_graph+loaded_runtime"
        ),
        "trace_id": trace_id,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "task_id": task_id,
        "candidate_commit_sha": candidate_commit,
        "canonical_head_commit_sha": canonical_head,
        "direct_exception_event_id": direct_event_id,
        "direct_exception_event_ref": f"timeline:{direct_event_id}",
        "implementation_event_id": implementation_event_id,
        "implementation_event_ref": f"timeline:{implementation_event_id}",
        "root_route_token_ref": root_route_ref,
        "active_snapshot_id": active_snapshot_id,
        "version_sync_git_head": synced_head,
        "git_synced_at": git_synced_at,
        "governance_runtime_version": governance_runtime_version,
        "qa_performed_post_merge": True,
        "candidate_is_ancestor": True,
        "canonical_head_graph_current": True,
        "canonical_head_runtime_current": True,
        "branch_runtime_context_required": False,
        "branch_runtime_context_synthesized": False,
        "live_merge_event_synthesized": False,
        "direct_pre_mutation_authority_hash": stable_sha256(direct_gate),
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority, [], True


def _qa_exact_candidate_post_merge_provenance(
    conn,
    *,
    project_id: str,
    row: Any,
    canonical_project_root: Path,
    candidate_commit_sha: str,
    canonical_head_commit: str,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    trace_id = str(row["trace_id"] or "").strip()
    backlog_id = str(row["backlog_id"] or "").strip()
    task_id = str(row["task_id"] or "").strip()
    candidate_commit_sha = str(candidate_commit_sha or "").strip().lower()
    canonical_head_commit = str(canonical_head_commit or "").strip().lower()
    mismatches: list[dict[str, Any]] = []

    candidate_commit = _qa_post_merge_resolve_commit(
        canonical_project_root,
        candidate_commit_sha,
    )
    canonical_head = _qa_post_merge_resolve_commit(
        canonical_project_root,
        canonical_head_commit,
    )
    if (
        candidate_commit != candidate_commit_sha
        or canonical_head != canonical_head_commit
    ):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "canonical_head_commit",
                "expected": "available full candidate and canonical commits",
                "actual": canonical_head_commit,
            }
        )
        return {}, mismatches
    ancestry = _qa_git_bytes(
        canonical_project_root,
        ["merge-base", "--is-ancestor", candidate_commit, canonical_head],
    )
    if ancestry.returncode != 0:
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "canonical_head_commit",
                "expected": (
                    "canonical live-merge commit containing the exact candidate"
                ),
                "actual": canonical_head_commit,
            }
        )
        return {}, mismatches

    direct_provenance, direct_mismatches, direct_applicable = (
        _qa_exact_candidate_direct_main_post_merge_provenance(
            conn,
            project_id=project_id,
            row=row,
            canonical_project_root=canonical_project_root,
            candidate_commit_sha=candidate_commit,
            canonical_head_commit=canonical_head,
        )
    )
    if direct_applicable:
        return direct_provenance, direct_mismatches

    from .parallel_branch_runtime import (
        get_branch_context,
        runtime_context_id_for_branch_context,
    )

    runtime_context = get_branch_context(conn, project_id, task_id)
    runtime_context_id = (
        runtime_context_id_for_branch_context(runtime_context)
        if runtime_context is not None
        else ""
    )
    context_backlog_id = str(
        getattr(runtime_context, "backlog_id", "") or ""
    ).strip()
    if (
        runtime_context is None
        or not runtime_context_id
        or not backlog_id
        or context_backlog_id != backlog_id
    ):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "runtime_context_id",
                "expected": (
                    "task/backlog-bound branch runtime context for post-merge QA"
                ),
                "actual": runtime_context_id or "missing",
            }
        )
        return {}, mismatches

    try:
        from . import task_timeline

        timeline_events = task_timeline.list_events(
            conn,
            project_id,
            backlog_id=backlog_id,
            limit=1000,
        )
    except Exception:
        timeline_events = []

    qa_events: list[dict[str, Any]] = []
    for event in timeline_events:
        if not isinstance(event, Mapping):
            continue
        status = str(
            event.get("status") or event.get("decision") or ""
        ).strip().lower()
        if status not in {
            "accepted",
            "ok",
            "pass",
            "passed",
            "succeeded",
            "success",
        }:
            continue
        if _contract_runtime_projection_timeline_actor_role(event) != "qa":
            continue
        event_kind = _contract_runtime_close_normalized(event.get("event_kind"))
        event_type = _contract_runtime_close_normalized(event.get("event_type"))
        phase = _contract_runtime_close_normalized(event.get("phase"))
        if (
            event_kind
            not in {"independent_verification", "qa_verification"}
            and event_type
            not in {"independent_verification", "qa_verification"}
            and phase not in {"verification", "qa"}
        ):
            continue
        if str(event.get("backlog_id") or "").strip() != backlog_id:
            continue
        if str(event.get("task_id") or "").strip() != task_id:
            continue
        if trace_id not in set(
            _runtime_context_service_graph_trace_values_from_event(event)
        ):
            continue
        qa_payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        qa_artifact_refs = (
            event.get("artifact_refs")
            if isinstance(event.get("artifact_refs"), Mapping)
            else {}
        )
        qa_commit_claims = {
            str(value or "").strip().lower()
            for value in (
                event.get("commit_sha"),
                qa_payload.get("candidate_commit_sha"),
                qa_payload.get("exact_candidate_commit"),
                qa_artifact_refs.get("candidate_commit_sha"),
            )
            if str(value or "").strip()
        }
        resolved_qa_commits = {
            _qa_post_merge_resolve_commit(canonical_project_root, item)
            for item in qa_commit_claims
        }
        if (
            not qa_commit_claims
            or "" in resolved_qa_commits
            or resolved_qa_commits != {candidate_commit}
            or str(qa_payload.get("runtime_context_id") or "").strip()
            != runtime_context_id
        ):
            continue
        event_id = _contract_runtime_projection_timeline_event_id(event)
        event_created_at = _contract_runtime_projection_timeline_event_time(event)
        event_time = _contract_runtime_close_authority_time_order_value(
            event_created_at
        )
        if event_id <= 0 or event_time is None:
            continue
        qa_events.append(
            {
                "event": dict(event),
                "event_id": event_id,
                "event_ref": f"timeline:{event_id}",
                "event_created_at": event_created_at,
                "event_time": event_time,
            }
        )

    verified_provenance: dict[str, Any] = {}

    def exact_lane_merge_authority(
        event: Mapping[str, Any],
        qa_event: Mapping[str, Any],
    ) -> dict[str, Any]:
        """Bind a durable live merge to one QA event and branch lane.

        Merge rows retain nested route and contract diagnostics whose parent
        identities may legitimately describe the observer root.  Conversely,
        old rows may also retain stale guide copies.  Neither is lane
        authority.  Use only the canonical event tuple plus the direct
        recorded-merge context, queue item, and QA gate evidence.
        """

        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        recorded_merge = (
            payload.get("recorded_merge")
            if isinstance(payload.get("recorded_merge"), Mapping)
            else {}
        )
        merge_context = (
            recorded_merge.get("context")
            if isinstance(recorded_merge.get("context"), Mapping)
            else {}
        )
        queue_item = (
            recorded_merge.get("queue_item")
            if isinstance(recorded_merge.get("queue_item"), Mapping)
            else {}
        )
        if bool(merge_context) != bool(queue_item):
            return {}
        legacy_direct_merge = not merge_context and not queue_item

        expected_parent_task_id = str(
            getattr(runtime_context, "parent_task_id", "") or ""
        ).strip()
        expected_root_task_id = str(
            getattr(runtime_context, "root_task_id", "") or ""
        ).strip()
        if legacy_direct_merge:
            if {
                "event_task_id": str(event.get("task_id") or "").strip(),
                "event_backlog_id": str(
                    event.get("backlog_id") or ""
                ).strip(),
                "child_task_id": str(
                    payload.get("child_task_id") or ""
                ).strip(),
                "payload_parent_task_id": str(
                    payload.get("parent_task_id") or ""
                ).strip(),
                "payload_runtime_context_id": str(
                    payload.get("runtime_context_id") or ""
                ).strip(),
            } != {
                "event_task_id": expected_parent_task_id,
                "event_backlog_id": backlog_id,
                "child_task_id": task_id,
                "payload_parent_task_id": expected_parent_task_id,
                "payload_runtime_context_id": runtime_context_id,
            }:
                return {}
        else:
            direct_identity = {
                "event_task_id": str(event.get("task_id") or "").strip(),
                "event_backlog_id": str(
                    event.get("backlog_id") or ""
                ).strip(),
                "child_task_id": str(
                    payload.get("child_task_id") or ""
                ).strip(),
                "payload_parent_task_id": str(
                    payload.get("parent_task_id") or ""
                ).strip(),
                "payload_runtime_context_id": str(
                    payload.get("runtime_context_id") or ""
                ).strip(),
                "context_task_id": str(
                    merge_context.get("task_id") or ""
                ).strip(),
                "context_stage_task_id": str(
                    merge_context.get("stage_task_id") or ""
                ).strip(),
                "context_parent_task_id": str(
                    merge_context.get("parent_task_id") or ""
                ).strip(),
                "context_runtime_context_id": str(
                    merge_context.get("runtime_context_id") or ""
                ).strip(),
                "context_backlog_id": str(
                    merge_context.get("backlog_id") or ""
                ).strip(),
                "queue_task_id": str(
                    queue_item.get("task_id") or ""
                ).strip(),
                "queue_backlog_id": str(
                    queue_item.get("backlog_id") or ""
                ).strip(),
            }
            if direct_identity != {
                "event_task_id": task_id,
                "event_backlog_id": backlog_id,
                "child_task_id": task_id,
                "payload_parent_task_id": expected_parent_task_id,
                "payload_runtime_context_id": runtime_context_id,
                "context_task_id": task_id,
                "context_stage_task_id": task_id,
                "context_parent_task_id": expected_parent_task_id,
                "context_runtime_context_id": runtime_context_id,
                "context_backlog_id": backlog_id,
                "queue_task_id": task_id,
                "queue_backlog_id": backlog_id,
            }:
                return {}
            supplied_root_task_id = str(
                merge_context.get("root_task_id") or ""
            ).strip()
            if (
                expected_root_task_id
                and supplied_root_task_id != expected_root_task_id
            ):
                return {}

        qa_ref = str(qa_event.get("event_ref") or "").strip()
        qa_refs: set[str] = set()

        def collect_direct_qa_refs(qa_evidence: Any) -> None:
            if not isinstance(qa_evidence, Mapping):
                return
            gate_evidence = qa_evidence.get("gate_evidence")
            if isinstance(gate_evidence, list):
                for gate in gate_evidence:
                    if not isinstance(gate, Mapping):
                        continue
                    if gate.get("passed") is not True:
                        continue
                    value = str(gate.get("evidence_id") or "").strip()
                    if value:
                        qa_refs.add(value)
            request_evidence = (
                qa_evidence.get("request_evidence")
                if isinstance(qa_evidence.get("request_evidence"), Mapping)
                else {}
            )
            request_qa = (
                request_evidence.get("qa_evidence")
                if isinstance(request_evidence.get("qa_evidence"), Mapping)
                else {}
            )
            value = str(request_qa.get("event_ref") or "").strip()
            if value:
                qa_refs.add(value)

        collect_direct_qa_refs(payload.get("qa_evidence"))
        contract_evidence = payload.get("contract_evidence")
        if isinstance(contract_evidence, list):
            for item in contract_evidence:
                if isinstance(item, Mapping):
                    collect_direct_qa_refs(item.get("qa_evidence"))
        if legacy_direct_merge:
            legacy_qa_ref = str(payload.get("qa_event_ref") or "").strip()
            if legacy_qa_ref:
                qa_refs.add(legacy_qa_ref)
        if not qa_ref or qa_refs != {qa_ref}:
            return {}

        candidate_claims = (
            {
                str(payload.get("candidate_commit_sha") or "")
                .strip()
                .lower(),
                str(payload.get("branch_head") or "").strip().lower(),
            }
            if legacy_direct_merge
            else {
                str(merge_context.get("head_commit") or "")
                .strip()
                .lower(),
                str(queue_item.get("branch_head") or "").strip().lower(),
            }
        )
        direct_qa_evidence = [payload.get("qa_evidence")]
        if isinstance(contract_evidence, list):
            direct_qa_evidence.extend(
                item.get("qa_evidence")
                for item in contract_evidence
                if isinstance(item, Mapping)
            )
        for qa_evidence in direct_qa_evidence:
            if not isinstance(qa_evidence, Mapping):
                continue
            request_evidence = (
                qa_evidence.get("request_evidence")
                if isinstance(qa_evidence.get("request_evidence"), Mapping)
                else {}
            )
            request_qa = (
                request_evidence.get("qa_evidence")
                if isinstance(request_evidence.get("qa_evidence"), Mapping)
                else {}
            )
            value = str(request_qa.get("commit_sha") or "").strip().lower()
            if value:
                candidate_claims.add(value)
        if "" in candidate_claims:
            return {}
        candidate_commits = {
            _qa_post_merge_resolve_commit(canonical_project_root, value)
            for value in candidate_claims
        }
        if candidate_commits != {candidate_commit}:
            return {}

        merge_claims = {
            str(event.get("commit_sha") or "").strip().lower(),
            str(payload.get("merge_commit") or "").strip().lower(),
            str(payload.get("target_head_after_merge") or "").strip().lower(),
        }
        if not legacy_direct_merge:
            merge_claims.update(
                {
                    str(merge_context.get("target_head_commit") or "")
                    .strip()
                    .lower(),
                    str(queue_item.get("merge_commit") or "")
                    .strip()
                    .lower(),
                    str(queue_item.get("target_head_after_merge") or "")
                    .strip()
                    .lower(),
                }
            )
        if "" in merge_claims:
            return {}
        merge_commits = {
            _qa_post_merge_resolve_commit(canonical_project_root, value)
            for value in merge_claims
        }
        if "" in merge_commits or len(merge_commits) != 1:
            return {}
        return {
            "candidate_commit": candidate_commit,
            "merged_commit": next(iter(merge_commits)),
            "qa_event_ref": qa_ref,
        }

    for qa_event in sorted(
        qa_events,
        key=lambda item: (float(item["event_time"]), int(item["event_id"])),
        reverse=True,
    ):
        for event in timeline_events:
            if not isinstance(event, Mapping):
                continue
            status = str(
                event.get("status") or event.get("decision") or ""
            ).strip().lower()
            if status not in {
                "accepted",
                "ok",
                "pass",
                "passed",
                "succeeded",
                "success",
            }:
                continue
            if _contract_runtime_projection_timeline_actor_role(event) != "observer":
                continue
            event_kind = _contract_runtime_close_normalized(
                event.get("event_kind")
            )
            event_type = _contract_runtime_close_normalized(
                event.get("event_type")
            )
            phase = _contract_runtime_close_normalized(event.get("phase"))
            if "live_merge" not in {event_kind, event_type, phase}:
                continue
            event_id = _contract_runtime_projection_timeline_event_id(event)
            event_created_at = _contract_runtime_projection_timeline_event_time(
                event
            )
            event_time = _contract_runtime_close_authority_time_order_value(
                event_created_at
            )
            if (
                event_id <= int(qa_event["event_id"])
                or event_time is None
                or float(event_time) <= float(qa_event["event_time"])
            ):
                continue
            merge_authority = exact_lane_merge_authority(event, qa_event)
            if not merge_authority:
                continue
            scoped_merge_commit = str(
                merge_authority.get("merged_commit") or ""
            ).strip()
            if scoped_merge_commit == candidate_commit:
                continue
            candidate_to_scoped_merge = _qa_git_bytes(
                canonical_project_root,
                [
                    "merge-base",
                    "--is-ancestor",
                    candidate_commit,
                    scoped_merge_commit,
                ],
            )
            scoped_merge_to_canonical_head = _qa_git_bytes(
                canonical_project_root,
                [
                    "merge-base",
                    "--is-ancestor",
                    scoped_merge_commit,
                    canonical_head,
                ],
            )
            if (
                candidate_to_scoped_merge.returncode != 0
                or scoped_merge_to_canonical_head.returncode != 0
            ):
                continue
            verified_provenance = {
                "schema_version": "qa_exact_candidate.post_merge_provenance.v1",
                "verified": True,
                "source": "task_timeline.live_merge+git_ancestry",
                "trace_id": trace_id,
                "backlog_id": backlog_id,
                "task_id": task_id,
                "runtime_context_id": runtime_context_id,
                "candidate_commit_sha": candidate_commit,
                "merged_commit_sha": scoped_merge_commit,
                "canonical_head_commit_sha": canonical_head,
                "qa_event_id": int(qa_event["event_id"]),
                "qa_event_ref": qa_event["event_ref"],
                "qa_event_created_at": qa_event["event_created_at"],
                "merge_event_id": event_id,
                "merge_event_ref": f"timeline:{event_id}",
                "merge_event_created_at": event_created_at,
                "ordered_after_qa": True,
                "candidate_is_ancestor": True,
                "scoped_merge_is_ancestor_of_canonical_head": True,
            }
            break
        if verified_provenance:
            break

    if not verified_provenance:
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "canonical_head_commit",
                "expected": (
                    "task/runtime-context-scoped durable observer live_merge "
                    "ordered after accepted QA and containing the exact candidate"
                ),
                "actual": canonical_head_commit,
            }
        )
    return verified_provenance, mismatches


def _qa_reverify_candidate_trace_context(
    conn,
    *,
    project_id: str,
    row: Any,
    body: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    review_context, mismatches = _qa_graph_review_context_from_trace_row(row)
    if mismatches:
        return review_context, mismatches

    trace_id = str(row["trace_id"] or "").strip()
    from . import graph_query_trace, graph_snapshot_store
    try:
        root_identity = json.loads(str(row["root_identity_json"] or "{}"))
    except (TypeError, ValueError, json.JSONDecodeError):
        root_identity = {}
    query_root_raw = str(root_identity.get("query_root") or "").strip()
    snapshot = graph_snapshot_store.get_graph_snapshot(
        conn,
        project_id,
        str(row["snapshot_id"] or "").strip(),
    ) or {}
    snapshot_materialization = (
        graph_snapshot_store.snapshot_materialization_provenance(snapshot)
    )
    snapshot_execution_root = str(
        snapshot_materialization.get("execution_root") or ""
    ).strip()
    snapshot_execution_root_authoritative = bool(
        root_identity.get("snapshot_execution_root_verified")
        and snapshot_execution_root
        and query_root_raw
        and Path(snapshot_execution_root).resolve()
        == Path(query_root_raw).resolve()
    )
    canonical_root = project_service.resolve_project_root(
        project_id, None, fallback_self=True
    )
    if not query_root_raw or canonical_root is None:
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "root_identity",
                "expected": "available query and registered canonical roots",
                "actual": query_root_raw or "missing",
            }
        )
        return review_context, mismatches
    supplied_body = body or {}
    supplied_root = next(
        (
            str(supplied_body.get(key) or "").strip()
            for key in (
                "project_root",
                "target_project_root",
                "target_graph_root",
                "worktree_path",
                "workspace_path",
                "repo_root",
            )
            if str(supplied_body.get(key) or "").strip()
        ),
        "",
    )
    if (
        supplied_root
        and Path(supplied_root).resolve() != Path(query_root_raw).resolve()
        and not snapshot_execution_root_authoritative
    ):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "query_root",
                "expected": str(Path(query_root_raw).resolve()),
                "actual": str(Path(supplied_root).resolve()),
            }
        )
        return review_context, mismatches
    if review_context.get("graph_basis") == "exact_candidate_snapshot":
        comparison_authority_required = bool(
            review_context.get("comparison_authority_required")
            or root_identity.get("comparison_authority_required")
        )
        if comparison_authority_required:
            current_authority = (
                _qa_exact_candidate_runtime_comparison_authority(
                    conn,
                    project_id=project_id,
                    proof={
                        "backlog_id": str(row["backlog_id"] or "").strip(),
                        "task_id": str(row["task_id"] or "").strip(),
                        "commit_sha": review_context[
                            "candidate_commit_sha"
                        ],
                    },
                )
            )
            current_commit = str(
                current_authority.get("commit_sha") or ""
            ).strip().lower()
            if not current_commit:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "comparison_authority",
                        "expected": "current unambiguous server-owned lineage",
                        "actual": str(
                            current_authority.get("machine_reason")
                            or "missing"
                        ),
                    }
                )
                return review_context, mismatches
            current_fields = {
                "comparison_base_commit_sha": current_commit,
                "comparison_base_commit_source": str(
                    current_authority.get("source") or ""
                ).strip(),
                "comparison_base_commit_lineage_source": str(
                    current_authority.get("lineage_source") or ""
                ).strip(),
            }
            persisted_fields = {
                field: str(root_identity.get(field) or "").strip().lower()
                if field == "comparison_base_commit_sha"
                else str(root_identity.get(field) or "").strip()
                for field in current_fields
            }
            for field, expected in current_fields.items():
                actual = persisted_fields[field]
                if actual != expected:
                    mismatches.append(
                        {
                            "trace_id": trace_id,
                            "field": field,
                            "expected": expected,
                            "actual": actual,
                        }
                    )
            if mismatches:
                return review_context, mismatches
        persisted_decision = review_context.get("graph_basis_decision")
        persisted_decision = (
            persisted_decision
            if isinstance(persisted_decision, Mapping)
            else {}
        )
        persisted_trigger = str(
            persisted_decision.get("exact_candidate_upgrade_trigger") or ""
        ).strip()
        if persisted_trigger != "qa_explicit_exact_snapshot_request":
            escalation_ref = str(
                persisted_decision.get("exact_candidate_upgrade_ref") or ""
            ).strip()
            escalation = graph_query_trace.get_qa_graph_basis_escalation(
                conn,
                project_id,
                escalation_ref,
            )
            escalation_expected = {
                "backlog_id": str(row["backlog_id"] or "").strip(),
                "task_id": str(row["task_id"] or "").strip(),
                "qa_session_id": str(row["qa_session_id"] or "").strip(),
                "candidate_commit_sha": review_context["candidate_commit_sha"],
                "exact_candidate_upgrade_trigger": persisted_trigger,
            }
            escalation_mismatches = {
                field: {
                    "expected": expected,
                    "actual": str(escalation.get(field) or "").strip(),
                }
                for field, expected in escalation_expected.items()
                if str(escalation.get(field) or "").strip() != expected
            }
            if not escalation_ref or not escalation or escalation_mismatches:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "exact_candidate_upgrade_ref",
                        "expected": "matching persisted server escalation",
                        "actual": escalation_ref or "missing",
                        "identity_mismatches": escalation_mismatches,
                    }
                )
                return review_context, mismatches
        try:
            recomputed = _qa_exact_candidate_context(
                Path(query_root_raw),
                project_id=project_id,
                canonical_project_root=Path(canonical_root),
                candidate_commit_sha=review_context["candidate_commit_sha"],
                escalation={
                    "escalation_id": str(
                        persisted_decision.get("exact_candidate_upgrade_ref")
                        or ""
                    ),
                    "exact_candidate_upgrade_trigger": str(
                        persisted_decision.get("exact_candidate_upgrade_trigger")
                        or ""
                    ),
                    "candidate_change_classification": str(
                        persisted_decision.get("candidate_change_classification")
                        or ""
                    ),
                },
                comparison_base_commit_sha=str(
                    root_identity.get("comparison_base_commit_sha") or ""
                ),
                comparison_base_commit_source=str(
                    root_identity.get("comparison_base_commit_source") or ""
                ),
                comparison_base_commit_lineage_source=str(
                    root_identity.get("comparison_base_commit_lineage_source")
                    or ""
                ),
                comparison_authority_required=bool(
                    review_context.get("comparison_authority_required")
                    or root_identity.get("comparison_authority_required")
                ),
                registered_allocator_worktree_paths=(
                    _qa_registered_allocator_worktree_paths(
                        conn,
                        project_id=project_id,
                        canonical_project_root=Path(canonical_root),
                    )
                ),
                exact_snapshot_materialization_provenance=(
                    snapshot_materialization
                    if snapshot_execution_root_authoritative
                    else None
                ),
            )
        except _QACandidateOverlayError as exc:
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": "exact_candidate_root_reverification",
                    "expected": "registered candidate checkout verification succeeds",
                    "actual": exc.reason,
                    "details": exc.details,
                }
            )
            return review_context, mismatches
        for field in (
            "changed_files",
            "candidate_diff_hash",
            "changed_files_source",
            "comparison_base_commit_sha",
            "comparison_base_commit_source",
            "comparison_base_commit_lineage_source",
            "query_root_identity_hash",
            "repository_identity_hash",
        ):
            if recomputed[field] != review_context[field]:
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": field,
                        "expected": review_context[field],
                        "actual": recomputed[field],
                    }
                )
        stored_canonical_root = str(
            root_identity.get("canonical_project_root") or ""
        ).strip()
        current_canonical_root = str(
            recomputed["root_identity"].get("canonical_project_root") or ""
        ).strip()
        if (
            not stored_canonical_root
            or Path(stored_canonical_root).resolve()
            != Path(current_canonical_root).resolve()
        ):
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": "canonical_project_root",
                    "expected": stored_canonical_root,
                    "actual": current_canonical_root,
                }
            )
        stored_canonical_head = str(
            root_identity.get("canonical_head_commit") or ""
        ).strip().lower()
        current_canonical_head = str(
            recomputed["root_identity"].get("canonical_head_commit") or ""
        ).strip().lower()
        if current_canonical_head == stored_canonical_head:
            for field in (
                "graph_basis_decision_hash",
                "root_identity_hash",
                "canonical_project_identity_hash",
            ):
                if recomputed[field] != review_context[field]:
                    mismatches.append(
                        {
                            "trace_id": trace_id,
                            "field": field,
                            "expected": review_context[field],
                            "actual": recomputed[field],
                        }
                    )
            if stable_sha256(root_identity) != stable_sha256(
                recomputed["root_identity"]
            ):
                mismatches.append(
                    {
                        "trace_id": trace_id,
                        "field": "root_identity",
                        "expected": stable_sha256(root_identity),
                        "actual": stable_sha256(recomputed["root_identity"]),
                    }
                )
        elif current_canonical_head != review_context["candidate_commit_sha"]:
            post_merge_provenance, post_merge_mismatches = (
                _qa_exact_candidate_post_merge_provenance(
                    conn,
                    project_id=project_id,
                    row=row,
                    canonical_project_root=Path(canonical_root),
                    candidate_commit_sha=review_context[
                        "candidate_commit_sha"
                    ],
                    canonical_head_commit=current_canonical_head,
                )
            )
            mismatches.extend(post_merge_mismatches)
            if post_merge_provenance and not mismatches:
                review_context["post_merge_provenance"] = {
                    key: value
                    for key, value in post_merge_provenance.items()
                    if key != "trace_id"
                }
        return review_context, mismatches

    if review_context.get("graph_basis") != "canonical_base_plus_candidate_diff":
        return review_context, mismatches
    active = graph_snapshot_store.get_active_graph_snapshot(conn, project_id) or {}
    active_snapshot_id = str(active.get("snapshot_id") or "").strip()
    active_commit_sha = str(active.get("commit_sha") or "").strip().lower()
    expected_snapshot_id = review_context["canonical_base_snapshot_id"]
    expected_base_commit = review_context["base_commit_sha"]
    evidence_status = str((body or {}).get("status") or "").strip().lower()
    canonical_head = _qa_git_bytes(
        Path(canonical_root),
        ["rev-parse", "--verify", "HEAD^{commit}"],
    )
    canonical_head_commit = (
        canonical_head.stdout.decode("ascii", errors="ignore").strip().lower()
        if canonical_head.returncode == 0
        else ""
    )
    historical_audit_only = evidence_status in _QA_TIMELINE_AUDIT_STATUSES and (
        active_snapshot_id != expected_snapshot_id
        or active_commit_sha != expected_base_commit
        or canonical_head_commit
        not in {expected_base_commit, review_context["candidate_commit_sha"]}
    )
    post_merge_provenance: dict[str, Any] = {}
    post_merge_mismatches: list[dict[str, Any]] = []
    post_merge_candidate = bool(
        not historical_audit_only
        and canonical_head_commit
        and canonical_head_commit
        not in {expected_base_commit, review_context["candidate_commit_sha"]}
    )
    if post_merge_candidate:
        post_merge_provenance, post_merge_mismatches = (
            _qa_exact_candidate_post_merge_provenance(
                conn,
                project_id=project_id,
                row=row,
                canonical_project_root=Path(canonical_root),
                candidate_commit_sha=review_context[
                    "candidate_commit_sha"
                ],
                canonical_head_commit=canonical_head_commit,
            )
        )
        if not post_merge_provenance or post_merge_mismatches:
            mismatches.extend(post_merge_mismatches)
    post_merge_verified = bool(
        post_merge_provenance
        and not post_merge_mismatches
    )
    if (
        not historical_audit_only
        and not post_merge_verified
        and active_snapshot_id != expected_snapshot_id
    ):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "active_snapshot_id",
                "expected": expected_snapshot_id,
                "actual": active_snapshot_id,
            }
        )
    if (
        not historical_audit_only
        and not post_merge_verified
        and active_commit_sha != expected_base_commit
    ):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "active_snapshot_commit_sha",
                "expected": expected_base_commit,
                "actual": active_commit_sha,
            }
        )
    try:
        recomputed = _qa_candidate_diff_context(
            (
                Path(canonical_root)
                if historical_audit_only or post_merge_verified
                else Path(query_root_raw)
            ),
            project_id=project_id,
            canonical_project_root=canonical_root,
            base_commit_sha=expected_base_commit,
            candidate_commit_sha=review_context["candidate_commit_sha"],
            allow_historical_audit_descendant=(
                historical_audit_only or post_merge_verified
            ),
        )
    except _QACandidateOverlayError as exc:
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "candidate_overlay_reverification",
                "expected": "server-side recomputation succeeds",
                "actual": exc.reason,
                "details": exc.details,
            }
        )
        return review_context, mismatches
    immutable_reverification_fields = [
        "changed_files",
        "candidate_diff_hash",
        "changed_files_source",
        "candidate_overlay_hash",
        "repository_identity_hash",
    ]
    if not historical_audit_only and not post_merge_verified:
        immutable_reverification_fields.extend(
            [
                "graph_basis_decision_hash",
                "root_identity_hash",
                "query_root_identity_hash",
                "canonical_project_identity_hash",
            ]
        )
    for field in immutable_reverification_fields:
        expected = review_context[field]
        actual = recomputed[field]
        if actual != expected:
            mismatches.append(
                {
                    "trace_id": trace_id,
                    "field": field,
                    "expected": expected,
                    "actual": actual,
                }
            )
    try:
        persisted_overlay = json.loads(str(row["candidate_overlay_json"] or "{}"))
    except (TypeError, ValueError, json.JSONDecodeError):
        persisted_overlay = {}
    if stable_sha256(persisted_overlay) != stable_sha256(
        recomputed["candidate_overlay"]
    ):
        mismatches.append(
            {
                "trace_id": trace_id,
                "field": "candidate_overlay",
                "expected": stable_sha256(persisted_overlay),
                "actual": stable_sha256(recomputed["candidate_overlay"]),
            }
        )
    if historical_audit_only and not mismatches:
        current_head_commit = str(
            recomputed["root_identity"].get("canonical_head_commit") or ""
        ).strip().lower()
        review_context["historical_audit_reverification"] = {
            "schema_version": "qa_review_graph.historical_audit_reverification.v1",
            "verified": True,
            "authority_scope": "audit_only",
            "close_satisfying": False,
            "evidence_status": evidence_status,
            "source": "immutable_graph_trace+server_git_object_diff+git_ancestry",
            "canonical_base_snapshot_id": expected_snapshot_id,
            "base_commit_sha": expected_base_commit,
            "candidate_commit_sha": review_context["candidate_commit_sha"],
            "current_active_snapshot_id": active_snapshot_id,
            "current_active_snapshot_commit_sha": active_commit_sha,
            "current_canonical_head_commit_sha": current_head_commit,
            "candidate_is_ancestor_of_current_head": True,
            "historical_close_authority_granted": False,
        }
    if post_merge_verified and not mismatches:
        review_context["post_merge_provenance"] = {
            key: value
            for key, value in post_merge_provenance.items()
            if key != "trace_id"
        }
    return review_context, mismatches


def _qa_trace_reverification_cache_key(
    row: Any,
    *,
    body: Mapping[str, Any] | None = None,
) -> str:
    """Bind request-local reverify reuse to the full persisted review identity."""

    review_context, mismatches = _qa_graph_review_context_from_trace_row(row)
    if mismatches:
        return ""
    try:
        root_identity = json.loads(str(row["root_identity_json"] or "{}"))
    except (TypeError, ValueError, json.JSONDecodeError, KeyError, IndexError):
        return ""
    if not isinstance(root_identity, Mapping):
        return ""
    supplied_body = body or {}
    supplied_root = next(
        (
            str(supplied_body.get(key) or "").strip()
            for key in (
                "project_root",
                "target_project_root",
                "target_graph_root",
                "worktree_path",
                "workspace_path",
                "repo_root",
            )
            if str(supplied_body.get(key) or "").strip()
        ),
        "",
    )
    if supplied_root:
        supplied_root = str(Path(supplied_root).resolve())
    return stable_sha256(
        {
            "review_context": review_context,
            "root_identity": dict(root_identity),
            "supplied_root": supplied_root,
            "evidence_status": str(
                supplied_body.get("status") or ""
            ).strip().lower(),
        }
    )


def _require_bounded_qa_session_authority(
    ctx: RequestContext,
    conn,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    commit_sha: str,
    action: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    session = ctx.require_auth(conn)
    from .permissions import session_role

    role = session_role(session)
    if role != "qa":
        raise GovernanceError(
            "qa_session_required",
            f"{action} requires an authenticated QA session",
            403,
            {"required_role": "qa", "actual_role": role or "unknown"},
        )
    session_project_id = str(session.get("project_id") or "").strip()
    if session_project_id != project_id:
        raise GovernanceError(
            "qa_session_scope_violation",
            f"{action} QA session project scope does not match the request",
            403,
            {
                "required_project_id": project_id,
                "session_project_id": session_project_id,
            },
        )
    required_values = {
        "backlog_id": str(backlog_id or "").strip(),
        "task_id": str(task_id or "").strip(),
        "commit_sha": str(commit_sha or "").strip().lower(),
    }
    missing_values = [key for key, value in required_values.items() if not value]
    if missing_values:
        raise GovernanceError(
            "qa_session_scope_required",
            f"{action} requires explicit backlog, task, and full commit scope",
            422,
            {"missing_fields": missing_values},
        )
    if not re.fullmatch(r"[0-9a-f]{40,64}", required_values["commit_sha"]):
        raise GovernanceError(
            "qa_session_scope_required",
            f"{action} requires a full commit_sha",
            422,
            {"field": "commit_sha", "required_format": "full_git_object_id"},
        )
    required_refs = {
        f"backlog:{required_values['backlog_id']}",
        f"task:{required_values['task_id']}",
        f"commit:{required_values['commit_sha']}",
    }
    qa_scope_binding_ref = _qa_scope_binding_ref(
        project_id=project_id,
        backlog_id=required_values["backlog_id"],
        task_id=required_values["task_id"],
        commit_sha=required_values["commit_sha"],
    )
    required_refs.add(qa_scope_binding_ref)
    scope_refs = _qa_session_scope_refs(session)
    missing_refs = sorted(required_refs - scope_refs)
    if missing_refs:
        raise GovernanceError(
            "qa_session_scope_violation",
            f"{action} is outside the authenticated QA session scope",
            403,
            {
                "missing_scope_refs": missing_refs,
                "required_scope_refs": sorted(required_refs),
            },
        )
    principal_id = str(session.get("principal_id") or "").strip()
    session_id = str(session.get("session_id") or "").strip()
    if not principal_id or not session_id:
        raise GovernanceError(
            "qa_session_identity_invalid",
            f"{action} requires a concrete QA principal and session id",
            403,
            {},
        )
    proof = {
        "schema_version": "qa_session_scope_proof.v1",
        "source": "authenticated_qa_session",
        "role": "qa",
        "verified": True,
        "project_id": project_id,
        "backlog_id": required_values["backlog_id"],
        "task_id": required_values["task_id"],
        "commit_sha": required_values["commit_sha"],
        "principal_id": principal_id,
        "qa_session_id": session_id,
        "required_scope_refs": sorted(required_refs),
        "qa_scope_binding_ref": qa_scope_binding_ref,
        "raw_qa_session_token_persisted": False,
        "observer_impersonation": False,
    }
    return session, proof


_CLOSE_TRAVERSAL_MAX_DEPTH = 128


def _server_close_timeline_container_graph_safe(value: Any) -> bool:
    containers = (Mapping, list, tuple, set, frozenset)
    active_ids: set[int] = set()
    stack = [(value, 0, False)]
    while stack:
        current, depth, leaving = stack.pop()
        if not isinstance(current, containers):
            continue
        container_id = id(current)
        if leaving:
            active_ids.remove(container_id)
            continue
        if depth > _CLOSE_TRAVERSAL_MAX_DEPTH or container_id in active_ids:
            return False
        active_ids.add(container_id)
        stack.append((current, depth, True))
        children = current.values() if isinstance(current, Mapping) else current
        stack.extend((child, depth + 1, False) for child in children)
    return True


_CLOSE_TRAVERSAL_STATE = local()


def _bounded_close_helper(fallback):
    def decorate(fn):
        @wraps(fn)
        def bounded(value: Any, *args, **kwargs):
            active = getattr(_CLOSE_TRAVERSAL_STATE, "active_helpers", frozenset())
            if fn in active:
                return fn(value, *args, **kwargs)
            if not _server_close_timeline_container_graph_safe(value):
                return fallback(value)
            _CLOSE_TRAVERSAL_STATE.active_helpers = active | {fn}
            try:
                return fn(value, *args, **kwargs)
            finally:
                _CLOSE_TRAVERSAL_STATE.active_helpers = active

        return bounded

    return decorate


@_bounded_close_helper(lambda _: False)
def _qa_request_has_impersonation_claim(value: Any) -> bool:
    if isinstance(value, Mapping):
        for key, child in value.items():
            normalized = str(key).strip().lower().replace("-", "_")
            if normalized in {
                "filed_on_behalf",
                "filed_on_behalf_by",
                "observer_impersonation",
                "on_behalf",
                "on_behalf_of",
            } and (bool(child) if isinstance(child, bool) else bool(str(child or "").strip())):
                return True
            if _qa_request_has_impersonation_claim(child):
                return True
    elif isinstance(value, list):
        return any(_qa_request_has_impersonation_claim(item) for item in value)
    return False


def _observer_graph_query_route_authority(
    conn,
    *,
    project_id: str,
    body: dict[str, Any],
    action: str,
) -> dict[str, Any]:
    """Resolve observer graph identity exclusively from a registered route ref."""

    nested_identity = (
        body.get("route_identity")
        if isinstance(body.get("route_identity"), Mapping)
        else {}
    )
    route_token_refs = {
        str(value or "").strip()
        for value in (
            body.get("route_token_ref"),
            body.get("observer_route_token_ref"),
            nested_identity.get("route_token_ref"),
        )
        if str(value or "").strip()
    }
    if not route_token_refs:
        return {}
    if len(route_token_refs) != 1:
        raise GovernanceError(
            "observer_graph_query_route_identity_conflict",
            "observer graph query received conflicting route_token_ref aliases",
            422,
            {"route_token_ref_alias_conflict": True},
        )
    route_token_ref = next(iter(route_token_refs))
    from . import observer_route_context

    try:
        resolved = observer_route_context.resolve_route_token_ref(
            conn,
            project_id=project_id,
            storage_project_id=_route_registry_storage_project_id(project_id),
            route_token_ref=route_token_ref,
            renew_within_seconds=observer_route_context.ROUTE_TOKEN_REF_RENEW_WITHIN_SECONDS,
        )
    except observer_route_context.RouteTokenRefError as exc:
        raise GovernanceError(
            "observer_graph_query_route_token_invalid",
            str(exc),
            422,
            {"route_token_ref": route_token_ref},
        ) from exc

    if not resolved or str(resolved.get("caller_role") or "") != "observer":
        raise GovernanceError(
            "observer_graph_query_route_token_invalid",
            "observer graph query requires an active observer route token ref",
            403,
            {"route_token_ref": route_token_ref},
        )
    normalized_actions = {
        str(value or "").strip().lower().replace("-", "_").replace(".", "_")
        for value in resolved.get("allowed_actions") or []
        if str(value or "").strip()
    }
    if not normalized_actions & {"graph_query", "graph_governance_query"}:
        raise GovernanceError(
            "observer_graph_query_route_action_forbidden",
            "observer route token ref does not allow graph_query",
            403,
            {
                "route_token_ref": route_token_ref,
                "allowed_actions": sorted(normalized_actions),
                "field": "allowed_actions",
                "expected": ["graph_query"],
                "actual": sorted(normalized_actions),
                "guide": (
                    "refresh onboard_route_guide and copy its "
                    "observer_route_context_issue payload to issue a fresh "
                    "same-scoped route ref whose allowed_actions include "
                    "graph_query, then retry the unchanged graph_query request"
                ),
                "source": (
                    "agent/governance/server.py::"
                    "_observer_graph_query_route_authority"
                ),
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )

    scope = resolved.get("scope") if isinstance(resolved.get("scope"), Mapping) else {}
    trusted_scope = {
        "project_id": str(scope.get("project_id") or "").strip(),
        "backlog_id": str(scope.get("backlog_id") or "").strip(),
        "task_id": str(scope.get("task_id") or "").strip(),
    }
    if (
        trusted_scope["project_id"] != project_id
        or not trusted_scope["backlog_id"]
        or not trusted_scope["task_id"]
    ):
        raise GovernanceError(
            "observer_graph_query_route_scope_incomplete",
            "observer graph query route scope requires exact project, backlog, and task identity",
            422,
            {"route_token_ref": route_token_ref, "route_scope": trusted_scope},
        )
    scope_mismatches = {
        field: {
            "expected": trusted_scope[field],
            "actual": str(body.get(field) or "").strip(),
        }
        for field in ("backlog_id", "task_id")
        if str(body.get(field) or "").strip()
        and str(body.get(field) or "").strip() != trusted_scope[field]
    }
    if scope_mismatches:
        raise GovernanceError(
            "observer_graph_query_route_scope_mismatch",
            "observer graph query scope cannot override the registered route scope",
            403,
            {
                "route_token_ref": route_token_ref,
                "scope_mismatches": scope_mismatches,
            },
        )

    identity_fields = (
        "route_id",
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
        "visible_injection_manifest_hash",
    )
    trusted_identity: dict[str, str] = {"route_token_ref": route_token_ref}
    identity_mismatches: dict[str, dict[str, str]] = {}
    for field in identity_fields:
        expected = str(resolved.get(field) or "").strip()
        claims = {
            str(value or "").strip()
            for value in (body.get(field), nested_identity.get(field))
            if str(value or "").strip()
        }
        if len(claims) > 1 or (claims and expected not in claims):
            identity_mismatches[field] = {
                "expected": expected,
                "actual": ",".join(sorted(claims)),
            }
        trusted_identity[field] = expected
    if identity_mismatches:
        raise GovernanceError(
            "observer_graph_query_route_identity_mismatch",
            "observer graph query route identity cannot override the registered route token",
            403,
            {
                "route_token_ref": route_token_ref,
                "identity_mismatches": identity_mismatches,
            },
        )
    if any(not trusted_identity[field] for field in identity_fields):
        raise GovernanceError(
            "observer_graph_query_route_identity_incomplete",
            "observer graph query route token is missing required public identity fields",
            422,
            {"route_token_ref": route_token_ref},
        )

    body.update(trusted_scope)
    body.update(trusted_identity)
    body["route_identity"] = dict(trusted_identity)
    body["actor"] = "observer"
    proof = {
        "schema_version": "observer_graph_query_route_scope_proof.v1",
        "source": "server_registered_observer_route_token",
        "verified": True,
        "query_source": "observer",
        "action": action,
        **trusted_scope,
        **trusted_identity,
        "raw_route_token_persisted": False,
    }
    return proof


def _observer_parentless_direct_main_graph_world_authority(
    conn,
    *,
    project_id: str,
    body: dict[str, Any],
    route_proof: Mapping[str, Any],
    action: str,
) -> dict[str, Any]:
    """Bind a selected strict Direct observer trace to the current world."""

    query_source = str(body.get("query_source") or "").strip().lower()
    query_purpose = str(body.get("query_purpose") or "").strip().lower()
    backlog_id = str(route_proof.get("backlog_id") or "").strip()
    task_id = str(route_proof.get("task_id") or "").strip()
    selected_direct = (
        _operator_supervised_direct_main_selected_execution_identity(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
        if backlog_id
        else {}
    )
    if not (
        str(action or "").strip() == "graph-governance.query"
        and not str(body.get("trace_id") or "").strip()
        and query_source == "observer"
        and query_purpose == "gate_validation"
        and backlog_id
        and selected_direct.get("resolved") is True
        and task_id
        == str(selected_direct.get("contract_execution_id") or "").strip()
    ):
        return {}

    route_authority = _operator_supervised_direct_main_route_authority(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        contract_execution_id=task_id,
        route_token_ref=str(route_proof.get("route_token_ref") or ""),
    )
    if route_authority.get("accepted") is not True:
        return {}

    from . import graph_snapshot_store

    world_ref = _operator_supervised_direct_main_world_ref(
        project_id=project_id,
    )
    expected_commit = str(world_ref.get("base_commit") or "").strip().lower()
    expected_root = str(
        world_ref.get("target_project_root") or ""
    ).strip()
    requested_snapshot_id = str(body.get("snapshot_id") or "active").strip()
    try:
        active_snapshot_id = _resolve_graph_snapshot_id(
            conn,
            project_id,
            "active",
        )
        resolved_snapshot_id = _resolve_graph_snapshot_id(
            conn,
            project_id,
            requested_snapshot_id,
        )
        snapshot = graph_snapshot_store.get_graph_snapshot(
            conn,
            project_id,
            resolved_snapshot_id,
        ) or {}
    except (KeyError, ValueError, ValidationError) as exc:
        raise GovernanceError(
            "observer_direct_main_graph_world_unavailable",
            "Direct rev2 graph query requires the current active snapshot",
            409,
            {
                "requested_snapshot_id": requested_snapshot_id,
                "resolution_error": str(exc),
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        ) from exc

    snapshot_commit = str(snapshot.get("commit_sha") or "").strip().lower()
    commit_claims = {
        str(body.get(field) or "").strip().lower()
        for field in (
            "commit_sha",
            "head_commit",
            "base_commit",
            "target_head_commit",
        )
        if str(body.get(field) or "").strip()
    }
    root_claims: dict[str, str] = {}
    for field in (
        "project_root",
        "target_project_root",
        "target_graph_root",
        "workspace_path",
        "repo_root",
    ):
        supplied = str(body.get(field) or "").strip()
        if not supplied:
            continue
        try:
            root_claims[field] = str(Path(supplied).expanduser().resolve())
        except (OSError, RuntimeError):
            root_claims[field] = supplied
    world_mismatches: list[dict[str, Any]] = []
    if world_ref.get("accepted") is not True:
        world_mismatches.append(
            {
                "field": "pre_mutation_world_ref",
                "expected": "accepted_server_world_ref",
                "actual": str(world_ref.get("status") or "rejected"),
            }
        )
    if resolved_snapshot_id != active_snapshot_id:
        world_mismatches.append(
            {
                "field": "snapshot_id",
                "expected": active_snapshot_id,
                "actual": resolved_snapshot_id,
            }
        )
    if not expected_commit or snapshot_commit != expected_commit:
        world_mismatches.append(
            {
                "field": "snapshot_commit_sha",
                "expected": expected_commit,
                "actual": snapshot_commit,
            }
        )
    if commit_claims and commit_claims != {expected_commit}:
        world_mismatches.append(
            {
                "field": "caller_commit_claims",
                "expected": [expected_commit],
                "actual": sorted(commit_claims),
            }
        )
    mismatched_roots = {
        field: actual
        for field, actual in root_claims.items()
        if actual != expected_root
    }
    if mismatched_roots:
        world_mismatches.append(
            {
                "field": "caller_root_claims",
                "expected": expected_root,
                "actual": mismatched_roots,
            }
        )
    if world_mismatches:
        raise GovernanceError(
            "observer_direct_main_graph_world_mismatch",
            (
                "Direct rev2 graph query must use the exact current active "
                "pre-mutation world"
            ),
            409,
            {
                "identity_mismatches": world_mismatches,
                "requested_snapshot_id": requested_snapshot_id,
                "active_snapshot_id": active_snapshot_id,
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )

    canonical_root = Path(expected_root).resolve()
    try:
        from .checkout_provenance import describe_checkout

        checkout = describe_checkout(
            canonical_root,
            project_id=project_id,
        )
    except (OSError, TypeError, ValueError) as exc:
        raise GovernanceError(
            "observer_direct_main_graph_root_identity_invalid",
            (
                "Direct rev2 graph query could not verify the registered "
                "pre-mutation checkout identity"
            ),
            409,
            {
                "root_identity_error": str(exc),
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        ) from exc

    checkout_git = (
        checkout.get("git")
        if isinstance(checkout.get("git"), Mapping)
        else {}
    )
    checkout_identity = (
        checkout.get("canonical_project_identity")
        if isinstance(checkout.get("canonical_project_identity"), Mapping)
        else {}
    )
    checkout_head = str(checkout.get("commit_sha") or "").strip().lower()
    checkout_root = str(checkout.get("execution_root") or "").strip()
    repository_identity_hash = stable_sha256(
        {
            "type": "git",
            "project_id": project_id,
            "git_common_dir": str(checkout_git.get("git_common_dir") or ""),
            "remote_url": str(checkout_git.get("remote_url") or ""),
        }
    )
    query_root_identity_hash = stable_sha256(
        {
            "execution_root": checkout_root,
            "head_commit": checkout_head,
            "checkout_identity": dict(checkout_identity),
            "repository_identity_hash": repository_identity_hash,
        }
    )
    root_identity = {
        "schema_version": "graph_query.root_identity.v1",
        "query_root": checkout_root,
        "query_root_head_commit": checkout_head,
        "query_root_identity_hash": query_root_identity_hash,
        "canonical_project_root": checkout_root,
        "canonical_head_commit": checkout_head,
        "canonical_project_identity_hash": query_root_identity_hash,
        "repository_identity_hash": repository_identity_hash,
    }
    root_mismatches = []
    if checkout.get("is_git_worktree") is not True:
        root_mismatches.append(
            {
                "field": "is_git_worktree",
                "expected": True,
                "actual": checkout.get("is_git_worktree"),
            }
        )
    if checkout_root != str(canonical_root):
        root_mismatches.append(
            {
                "field": "execution_root",
                "expected": str(canonical_root),
                "actual": checkout_root,
            }
        )
    if checkout_head != expected_commit:
        root_mismatches.append(
            {
                "field": "head_commit",
                "expected": expected_commit,
                "actual": checkout_head,
            }
        )
    if root_mismatches:
        raise GovernanceError(
            "observer_direct_main_graph_root_identity_invalid",
            (
                "Direct rev2 graph query requires the registered checkout at "
                "the exact pre-mutation commit"
            ),
            409,
            {
                "identity_mismatches": root_mismatches,
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )

    body["snapshot_id"] = active_snapshot_id
    world_projection = {
        "schema_version": (
            "operator_supervised_direct_main.graph_world_projection.v1"
        ),
        "source": (
            "operator_supervised_direct_main_world_ref+active_graph_snapshot"
        ),
        "verified": True,
        "server_derived": True,
        "caller_claims_trusted": False,
        "pre_mutation_world_ref": dict(world_ref),
        "snapshot_id": active_snapshot_id,
        "snapshot_commit_sha": snapshot_commit,
        "root_identity": root_identity,
        "root_identity_hash": stable_sha256(root_identity),
        "query_root_identity_hash": query_root_identity_hash,
        "canonical_project_identity_hash": query_root_identity_hash,
        "repository_identity_hash": repository_identity_hash,
        "zero_write_on_failure": True,
    }
    return {
        "direct_main_graph_world_projection": world_projection,
        "commit_sha": expected_commit,
        "raw_route_token_persisted": False,
    }


def _observer_parentless_direct_main_bind_graph_trace_world(
    conn,
    *,
    project_id: str,
    trace_id: str,
    observer_proof: Mapping[str, Any],
) -> dict[str, Any]:
    """Persist the server-derived Direct world after one real query event."""

    from . import graph_query_trace

    projection = (
        observer_proof.get("direct_main_graph_world_projection")
        if isinstance(
            observer_proof.get("direct_main_graph_world_projection"),
            Mapping,
        )
        else {}
    )
    root_identity = (
        projection.get("root_identity")
        if isinstance(projection.get("root_identity"), Mapping)
        else {}
    )
    if not (
        projection.get("verified") is True
        and projection.get("server_derived") is True
        and trace_id
        and root_identity
    ):
        return {}
    root_identity_hash = stable_sha256(root_identity)
    cursor = conn.execute(
        """
        UPDATE graph_query_traces
           SET commit_sha = ?, root_identity_json = ?,
               root_identity_hash = ?, query_root_identity_hash = ?,
               canonical_project_identity_hash = ?,
               repository_identity_hash = ?
         WHERE project_id = ? AND trace_id = ?
           AND query_source = 'observer'
           AND query_purpose = 'gate_validation'
           AND commit_sha = ?
           AND EXISTS (
               SELECT 1 FROM graph_query_events e
                WHERE e.trace_id = graph_query_traces.trace_id
           )
        """,
        (
            str(projection.get("snapshot_commit_sha") or ""),
            json.dumps(root_identity, sort_keys=True, separators=(",", ":")),
            root_identity_hash,
            str(projection.get("query_root_identity_hash") or ""),
            str(projection.get("canonical_project_identity_hash") or ""),
            str(projection.get("repository_identity_hash") or ""),
            project_id,
            trace_id,
            str(projection.get("snapshot_commit_sha") or ""),
        ),
    )
    if cursor.rowcount != 1:
        raise GovernanceError(
            "observer_direct_main_graph_world_persistence_failed",
            "Direct rev2 graph query world could not be bound atomically",
            409,
            {
                "trace_id": trace_id,
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    return graph_query_trace.get_trace(conn, project_id, trace_id)["trace"]


def _require_graph_query_capability(ctx: RequestContext, conn, body: dict, action: str) -> dict:
    query_source = str(body.get("query_source") or "api_debug").strip().lower().replace("-", "_")
    if query_source == "qa":
        query_purpose = str(body.get("query_purpose") or "").strip()
        if query_purpose != "independent_verification":
            raise GovernanceError(
                "unsupported_qa_graph_query_purpose",
                "QA graph queries require query_purpose=independent_verification",
                422,
                {
                    "query_source": "qa",
                    "query_purpose": query_purpose,
                    "allowed_query_purposes": ["independent_verification"],
                },
            )
        if _qa_request_has_impersonation_claim(body):
            raise GovernanceError(
                "qa_observer_impersonation_forbidden",
                "QA graph queries cannot be filed on behalf of another lane",
                403,
                {"observer_impersonation": False},
            )
        session, proof = _require_bounded_qa_session_authority(
            ctx,
            conn,
            project_id=ctx.get_project_id(),
            backlog_id=str(body.get("backlog_id") or ""),
            task_id=str(body.get("task_id") or ""),
            commit_sha=str(body.get("commit_sha") or body.get("head_commit") or ""),
            action=action,
        )
        from . import graph_query_trace, graph_snapshot_store

        snapshot_id = _resolve_graph_snapshot_id(
            conn,
            ctx.get_project_id(),
            str(body.get("snapshot_id") or "active"),
        )
        snapshot = graph_snapshot_store.get_graph_snapshot(
            conn,
            ctx.get_project_id(),
            snapshot_id,
        ) or {}
        snapshot_commit_sha = str(snapshot.get("commit_sha") or "").strip().lower()
        try:
            review_context = graph_snapshot_store.resolve_bounded_qa_graph_basis(
                conn,
                ctx.get_project_id(),
                snapshot_id,
                str(proof.get("commit_sha") or ""),
            )
            query_root = _graph_governance_project_root(
                ctx.get_project_id(), body
            )
            canonical_root = project_service.resolve_project_root(
                ctx.get_project_id(), None, fallback_self=True
            )
            if canonical_root is None:
                _qa_overlay_fail(
                    "canonical_project_root_unavailable",
                    "bounded QA review requires a registered canonical project root",
                    project_id=ctx.get_project_id(),
                )
            if review_context.get("requires_candidate_diff"):
                review_context.update(
                    _qa_candidate_diff_context(
                        query_root,
                        project_id=ctx.get_project_id(),
                        canonical_project_root=canonical_root,
                        base_commit_sha=str(
                            review_context.get("base_commit_sha") or ""
                        ),
                        candidate_commit_sha=str(
                            review_context.get("candidate_commit_sha") or ""
                        ),
                    )
                )
            else:
                snapshot_materialization = (
                    graph_snapshot_store.snapshot_materialization_provenance(
                        snapshot
                    )
                )
                snapshot_execution_root = str(
                    snapshot_materialization.get("execution_root") or ""
                ).strip()
                if snapshot_execution_root:
                    query_root = Path(snapshot_execution_root).resolve()
                escalation = graph_query_trace.latest_qa_graph_basis_escalation(
                    conn,
                    ctx.get_project_id(),
                    backlog_id=str(proof.get("backlog_id") or ""),
                    task_id=str(proof.get("task_id") or ""),
                    qa_session_id=str(proof.get("qa_session_id") or ""),
                    candidate_commit_sha=str(
                        review_context.get("candidate_commit_sha") or ""
                    ),
                )
                comparison_authority = (
                    _qa_exact_candidate_runtime_comparison_authority(
                        conn,
                        project_id=ctx.get_project_id(),
                        proof=proof,
                    )
                )
                comparison_authority_required = (
                    _qa_exact_candidate_comparison_authority_required(
                        conn,
                        project_id=ctx.get_project_id(),
                        proof=proof,
                    )
                )
                if (
                    comparison_authority_required
                    and not comparison_authority.get("commit_sha")
                    and comparison_authority.get("machine_reason")
                ):
                    _qa_overlay_fail(
                        "exact_candidate_comparison_base_required",
                        (
                            "managed exact candidate review requires one "
                            "unambiguous server-owned comparison base"
                        ),
                        authority_machine_reason=str(
                            comparison_authority.get("machine_reason") or ""
                        ),
                        comparison_base_commit_source=str(
                            comparison_authority.get("source") or ""
                        ),
                        identity_mismatches=list(
                            comparison_authority.get("identity_mismatches")
                            or []
                        ),
                        fail_closed=True,
                        zero_write_rejection=True,
                        writes_performed=False,
                    )
                review_context.update(
                    {
                        **_qa_exact_candidate_context(
                            query_root,
                            project_id=ctx.get_project_id(),
                            canonical_project_root=Path(canonical_root),
                            candidate_commit_sha=str(
                                review_context.get("candidate_commit_sha") or ""
                            ),
                            escalation=escalation,
                            comparison_base_commit_sha=(
                                comparison_authority.get("commit_sha") or ""
                            ),
                            comparison_base_commit_source=(
                                comparison_authority.get("source") or ""
                            ),
                            comparison_base_commit_lineage_source=(
                                comparison_authority.get("lineage_source")
                                or ""
                            ),
                            comparison_authority_required=(
                                comparison_authority_required
                            ),
                            registered_allocator_worktree_paths=(
                                _qa_registered_allocator_worktree_paths(
                                    conn,
                                    project_id=ctx.get_project_id(),
                                    canonical_project_root=Path(canonical_root),
                                )
                            ),
                            exact_snapshot_materialization_provenance=(
                                snapshot_materialization
                                if snapshot_execution_root
                                else None
                            ),
                        ),
                    }
                )
        except _QACandidateOverlayError as exc:
            if exc.reason in _QA_EXACT_COMPARISON_FAILURE_REASONS:
                raise GovernanceError(
                    "qa_exact_candidate_comparison_authority_rejected",
                    (
                        "Exact-candidate review requires a complete, trusted "
                        "comparison authority before the graph query can run"
                    ),
                    409,
                    {
                        "snapshot_id": snapshot_id,
                        "snapshot_commit_sha": snapshot_commit_sha,
                        "required_commit_sha": proof.get("commit_sha", ""),
                        "machine_reason": exc.reason,
                        "identity_mismatches": (
                            _qa_overlay_identity_mismatches(exc)
                        ),
                        "exact_candidate_snapshot_required": False,
                        "fail_closed": True,
                        "write_performed": False,
                        "zero_write_rejection": True,
                        "writes_performed": False,
                        "public_safe": True,
                        "secret_safe": True,
                        "source": (
                            "agent.governance.server::"
                            "_require_graph_query_capability"
                        ),
                        "next_legal_action": (
                            "repair_the_existing_runtime_comparison_authority_"
                            "then_retry_the_same_graph_query"
                        ),
                        **exc.details,
                    },
                ) from exc
            escalation = graph_query_trace.record_qa_graph_basis_escalation(
                conn,
                ctx.get_project_id(),
                backlog_id=str(proof.get("backlog_id") or ""),
                task_id=str(proof.get("task_id") or ""),
                qa_session_id=str(proof.get("qa_session_id") or ""),
                candidate_commit_sha=str(proof.get("commit_sha") or ""),
                machine_reason=exc.reason,
            )
            conn.commit()
            raise GovernanceError(
                "qa_candidate_overlay_requires_exact_snapshot",
                (
                    "The candidate cannot be reviewed safely as a canonical-base "
                    "overlay; materialize an exact candidate graph snapshot"
                ),
                409,
                {
                    "snapshot_id": snapshot_id,
                    "snapshot_commit_sha": snapshot_commit_sha,
                    "required_commit_sha": proof.get("commit_sha", ""),
                    "machine_reason": exc.reason,
                    "identity_mismatches": (
                        _qa_overlay_identity_mismatches(exc)
                    ),
                    "exact_candidate_snapshot_required": True,
                    "exact_candidate_upgrade": escalation,
                    **exc.details,
                },
            ) from exc
        except (KeyError, ValueError, ValidationError) as exc:
            raise GovernanceError(
                "qa_graph_snapshot_commit_mismatch",
                (
                    "QA graph query requires either an exact candidate snapshot or "
                    "the active canonical base with a server-derived candidate diff"
                ),
                409,
                {
                    "snapshot_id": snapshot_id,
                    "snapshot_commit_sha": snapshot_commit_sha,
                    "required_commit_sha": proof.get("commit_sha", ""),
                    "candidate_diff_resolution_error": str(exc),
                },
            ) from exc
        _qa_validate_candidate_review_claims(body, review_context)
        proof.update(review_context)
        proof["snapshot_id"] = snapshot_id
        proof["snapshot_commit_sha"] = str(
            review_context.get("base_commit_sha") or snapshot_commit_sha
        )
        body["snapshot_id"] = snapshot_id
        principal_id = str(session.get("principal_id") or "").strip()
        supplied_actor = str(body.get("actor") or "").strip()
        if supplied_actor and supplied_actor != principal_id:
            raise GovernanceError(
                "qa_session_principal_mismatch",
                "QA graph query actor must match the authenticated QA principal",
                403,
                {
                    "authenticated_principal_id": principal_id,
                    "supplied_actor": supplied_actor,
                },
            )
        body["actor"] = principal_id
        setattr(ctx, "_trusted_qa_graph_query_authority", proof)
        return session
    if query_source == "observer":
        session = _require_graph_governance_operator(ctx, conn, action)
        observer_proof = _observer_graph_query_route_authority(
            conn,
            project_id=ctx.get_project_id(),
            body=body,
            action=action,
        )
        if observer_proof:
            observer_proof.update(
                _observer_parentless_direct_main_graph_world_authority(
                    conn,
                    project_id=ctx.get_project_id(),
                    body=body,
                    route_proof=observer_proof,
                    action=action,
                )
            )
            setattr(ctx, "_trusted_observer_graph_query_authority", observer_proof)
        return session
    if query_source != "mf_subagent":
        return _require_graph_governance_operator(ctx, conn, action)

    session = _require_graph_governance_mf_subagent(ctx, conn, action)
    query_purpose = str(body.get("query_purpose") or "").strip()
    allowed_query_purposes = {
        "subagent_context_build",
        "subagent_gate_validation",
    }
    if query_purpose not in allowed_query_purposes:
        raise GovernanceError(
            "unsupported_mf_subagent_graph_query_purpose",
            (
                "mf_subagent graph query requires query_purpose="
                "subagent_context_build or subagent_gate_validation"
            ),
            422,
            {
                "query_source": "mf_subagent",
                "query_purpose": query_purpose,
                "allowed_query_purposes": sorted(allowed_query_purposes),
                "next_legal_action": {
                    "tool": "graph_query",
                    "description": (
                        "Retry the audited subagent graph query with "
                            "query_purpose=subagent_context_build for context lookup "
                            "or subagent_gate_validation for gate evidence."
                    ),
                },
            },
        )
    task_id = str(body.get("task_id") or "").strip()
    parent_task_id = str(body.get("parent_task_id") or "").strip()
    runtime_context_id = str(body.get("runtime_context_id") or "").strip()
    worker_role = str(body.get("worker_role") or "").strip().lower().replace("-", "_")
    fence_token = str(body.get("fence_token") or "").strip()
    session_token = str(body.get("session_token") or "").strip()
    session_token_ref = str(
        body.get("session_token_ref")
        or body.get("worker_session_token_ref")
        or ""
    ).strip()
    target_project_id = str(
        body.get("target_project_id")
        or body.get("graph_project_id")
        or ctx.get_project_id()
    ).strip()
    governance_project_id = str(
        body.get("governance_project_id")
        or body.get("backlog_project_id")
        or ctx.get_project_id()
    ).strip()
    target_project_root = str(
        body.get("target_project_root")
        or body.get("target_graph_root")
        or body.get("project_root")
        or body.get("workspace_path")
        or body.get("repo_root")
        or ""
    ).strip()
    if runtime_context_id and not worker_role:
        worker_role = "mf_sub"
    if not runtime_context_id:
        if not task_id:
            raise ValidationError("task_id is required for mf_subagent graph query")
        if not parent_task_id:
            raise ValidationError("parent_task_id is required for mf_subagent graph query")
    if worker_role != "mf_sub":
        raise ValidationError("worker_role=mf_sub is required for mf_subagent graph query")
    if not fence_token and not session_token_ref:
        raise ValidationError("fence_token is required for mf_subagent graph query")
    if not fence_token and session_token_ref and (
        session_token or str(body.get("fence_token_hash") or "").strip()
    ):
        raise GovernanceError(
            "mf_subagent_graph_query_safe_ref_auth_ambiguous",
            (
                "copy-safe graph compatibility cannot be combined with caller "
                "raw session auth or a caller-claimed fence hash"
            ),
            422,
            {
                "runtime_context_id": runtime_context_id,
                "task_id": task_id,
                "session_token_ref_present": True,
                "raw_session_token_present": bool(session_token),
                "caller_fence_token_hash_present": bool(
                    str(body.get("fence_token_hash") or "").strip()
                ),
                "fail_closed": True,
                "zero_write_rejection": True,
                "writes_performed": False,
                "mutation_performed": False,
                "product_mutation_performed": False,
                "raw_worker_auth_exposed": False,
            },
        )
    nested_route_identity = (
        body.get("route_identity")
        if isinstance(body.get("route_identity"), Mapping)
        else {}
    )
    route_identity = {
        field: str(body.get(field) or nested_route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    from .parallel_branch_runtime import (
        ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES,
        BranchRuntimeFenceError,
        get_branch_context_by_runtime_context_id,
        runtime_context_effective_target_project_root,
        runtime_context_fence_token_verifier,
        runtime_context_has_fence_authority,
        runtime_context_id_for_branch_context,
        runtime_context_session_token_lease_view,
        runtime_context_session_token_ref_matches,
        validate_mf_subagent_graph_query_identity,
    )
    try:
        safe_ref_authority: dict[str, Any] = {}
        if fence_token:
            context = validate_mf_subagent_graph_query_identity(
                conn,
                project_id=ctx.get_project_id(),
                task_id=task_id,
                runtime_context_id=runtime_context_id,
                parent_task_id=parent_task_id,
                worker_role=worker_role,
                fence_token=fence_token,
                governance_project_id=governance_project_id,
                target_project_id=target_project_id,
                target_project_root=target_project_root,
                session_token=session_token,
                session_token_ref=session_token_ref,
                route_identity=route_identity,
            )
        else:
            def safe_ref_failure(reason: str, **details: Any) -> None:
                error = BranchRuntimeFenceError(reason)
                error.details = {  # type: ignore[attr-defined]
                    "runtime_context_id": runtime_context_id,
                    "task_id": task_id,
                    "parent_task_id": parent_task_id,
                    "governance_project_id": governance_project_id,
                    "target_project_id": target_project_id,
                    "safe_ref_server_compatibility": True,
                    "fail_closed": True,
                    "zero_write_rejection": True,
                    "writes_performed": False,
                    "mutation_performed": False,
                    "product_mutation_performed": False,
                    "raw_worker_auth_exposed": False,
                    **details,
                }
                raise error

            if not runtime_context_id:
                safe_ref_failure(
                    "fence_invalidated_or_unknown",
                    missing_fields=["runtime_context_id"],
                )
            missing_identity_fields = [
                field
                for field, value in (
                    ("task_id", task_id),
                    ("parent_task_id", parent_task_id),
                    ("target_project_root", target_project_root),
                )
                if not value
            ]
            if missing_identity_fields:
                safe_ref_failure(
                    "fence_invalidated_or_unknown",
                    missing_fields=missing_identity_fields,
                )
            context = get_branch_context_by_runtime_context_id(
                conn,
                governance_project_id,
                runtime_context_id,
            )
            if (
                context is None
                or not runtime_context_has_fence_authority(context)
                or not runtime_context_session_token_ref_matches(
                    context,
                    session_token_ref,
                )
            ):
                safe_ref_failure("fence_invalidated_or_unknown")
            if task_id != context.task_id:
                safe_ref_failure(
                    "runtime_context_task_mismatch",
                    expected_task_id=context.task_id,
                )
            if context.status not in ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES:
                safe_ref_failure(
                    "fence_invalidated_or_unknown",
                    runtime_context_status=context.status,
                )
            if (
                str(context.last_recovery_action or "").strip()
                != "mf_subagent_session_token_rejoin_issued"
                or bool(str(context.fence_token or "").strip())
            ):
                safe_ref_failure(
                    "fence_invalidated_or_unknown",
                    required_last_recovery_action=(
                        "mf_subagent_session_token_rejoin_issued"
                    ),
                    actual_last_recovery_action=str(
                        context.last_recovery_action or ""
                    ).strip(),
                    verifier_only_fence_authority_required=True,
                    raw_fence_stored=bool(
                        str(context.fence_token or "").strip()
                    ),
                )
            lease = runtime_context_session_token_lease_view(context)
            if str(lease.get("status") or "") == "expired":
                safe_ref_failure(
                    "runtime_session_token_expired",
                    lease_id=str(lease.get("lease_id") or ""),
                    lease_expires_at=str(
                        lease.get("lease_expires_at") or ""
                    ),
                )
            if (
                str(lease.get("status") or "") != "active"
                or lease.get("authorization_valid") is not True
                or lease.get("expired") is not False
            ):
                safe_ref_failure(
                    "fence_invalidated_or_unknown",
                    lease_status=str(lease.get("status") or ""),
                )
            context_governance_project_id = (
                context.governance_project_id or context.project_id
            )
            context_target_project_id = (
                context.target_project_id or context.project_id
            )
            if (
                governance_project_id != context_governance_project_id
                or ctx.get_project_id()
                not in {context.project_id, context_target_project_id}
                or target_project_id != context_target_project_id
            ):
                safe_ref_failure("fence_invalidated_or_unknown")

            def normalized_target_root(value: Any) -> str:
                text = str(value or "").strip()
                if not text:
                    return ""
                try:
                    return str(Path(text).expanduser().resolve())
                except (OSError, RuntimeError):
                    return text

            requested_target_root = normalized_target_root(target_project_root)
            context_target_root = normalized_target_root(
                runtime_context_effective_target_project_root(context)
            )
            if (
                not context_target_root
                or requested_target_root != context_target_root
            ):
                safe_ref_failure(
                    "fence_invalidated_or_unknown",
                    mismatched_fields=["target_project_root"],
                )
            expected_parent_task_id = _runtime_context_mf_sub_parent_task_id(
                context
            )
            if (
                not expected_parent_task_id
                or parent_task_id != expected_parent_task_id
            ):
                safe_ref_failure(
                    "fence_invalidated_or_unknown",
                    mismatched_fields=["parent_task_id"],
                    expected_parent_task_id=expected_parent_task_id,
                )
            expected_route_identity = _runtime_context_latest_route_identity(
                conn,
                context,
            )
            missing_route_identity = [
                field
                for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
                if str(expected_route_identity.get(field) or "").strip()
                and not str(route_identity.get(field) or "").strip()
            ]
            if missing_route_identity:
                safe_ref_failure(
                    "route_identity_missing",
                    missing_route_identity_fields=missing_route_identity,
                )
            route_identity_mismatches = [
                {
                    "field": field,
                    "expected": str(
                        expected_route_identity.get(field) or ""
                    ).strip(),
                    "actual": str(route_identity.get(field) or "").strip(),
                }
                for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
                if str(expected_route_identity.get(field) or "").strip()
                != str(route_identity.get(field) or "").strip()
            ]
            if route_identity_mismatches:
                safe_ref_failure(
                    "route_identity_mismatch",
                    route_identity_mismatches=route_identity_mismatches,
                )
            fence_token_hash = runtime_context_fence_token_verifier(context)
            safe_ref_authority = {
                "schema_version": (
                    "runtime_context.mf_sub_graph_query_safe_ref_authority.v1"
                ),
                "authorization_source": "runtime_context_session_token_ref",
                "server_derived": True,
                "caller_claims_trusted": False,
                "safe_ref_current": True,
                "runtime_context_id": runtime_context_id_for_branch_context(
                    context
                ),
                "task_id": context.task_id,
                "parent_task_id": parent_task_id,
                "session_token_ref": session_token_ref,
                "fence_token_hash": fence_token_hash,
                "lease_id": str(lease.get("lease_id") or ""),
                "lease_expires_at": str(
                    lease.get("lease_expires_at") or ""
                ),
                "lease_status": "active",
                "raw_session_token_required": False,
                "raw_fence_token_required": False,
                "raw_worker_auth_exposed": False,
                "write_scope": "graph_trace_and_canonical_worker_graph_context",
            }
            setattr(
                ctx,
                "_trusted_mf_sub_graph_query_safe_ref_authority",
                safe_ref_authority,
            )
    except BranchRuntimeFenceError as exc:
        reason = str(exc) or "fence_invalidated_or_unknown"
        details = {
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "governance_project_id": governance_project_id,
            "target_project_id": target_project_id,
            "reason": reason,
            "underlying_reason": reason,
        }
        exc_details = getattr(exc, "details", None)
        if isinstance(exc_details, Mapping):
            details.update(exc_details)
        details.update(
            _runtime_context_worker_recovery_details(
                ctx,
                conn,
                project_id=governance_project_id,
                runtime_context_id=runtime_context_id,
                task_id=task_id,
                parent_task_id=parent_task_id,
                fence_token=fence_token,
                session_token=session_token,
                session_token_ref=session_token_ref,
                target_project_root=target_project_root,
                route_identity=route_identity,
                reason=reason,
            )
        )
        if reason == "runtime_session_token_expired":
            raise GovernanceError(
                "runtime_session_token_expired",
                "mf_subagent runtime session token lease has expired",
                403,
                details,
            ) from exc
        if reason == "route_identity_missing" or reason.startswith(
            "route_identity_missing:"
        ):
            details["route_identity_missing"] = True
            raise GovernanceError(
                "route_identity_missing",
                "mf_subagent graph query route identity is incomplete",
                403,
                details,
            ) from exc
        raise GovernanceError(
            "fence_invalidated_or_unknown",
            "mf_subagent graph query fence is invalidated or unknown",
            403,
            details,
        ) from exc
    recovery_details = _runtime_context_worker_recovery_details(
        ctx,
        conn,
        project_id=context.project_id,
        runtime_context_id=runtime_context_id,
        task_id=task_id,
        parent_task_id=parent_task_id,
        fence_token=fence_token,
        session_token=session_token,
        session_token_ref=session_token_ref,
        target_project_root=target_project_root,
        route_identity=route_identity,
        reason="runtime_context_sequence_check",
        context=context,
    )
    if runtime_context_id and recovery_details.get("next_legal_action") in {
        "submit_mf_subagent_read_receipt",
        "record_mf_subagent_startup",
    }:
        raise GovernanceError(
            "runtime_context_sequence_incomplete",
            "mf_subagent graph query requires ordered read receipt and startup evidence",
            403,
            recovery_details,
        )
    trusted_safe_ref_authority = getattr(
        ctx,
        "_trusted_mf_sub_graph_query_safe_ref_authority",
        {},
    )
    trusted_safe_ref_authority = (
        trusted_safe_ref_authority
        if isinstance(trusted_safe_ref_authority, Mapping)
        else {}
    )
    trusted_fence_token_hash = str(
        trusted_safe_ref_authority.get("fence_token_hash") or ""
    ).strip()
    fence_hash = (
        trusted_fence_token_hash.removeprefix("sha256:")[:16]
        if trusted_fence_token_hash
        else hashlib.sha256(fence_token.encode("utf-8")).hexdigest()[:16]
    )
    body["task_id"] = context.task_id
    body["parent_task_id"] = (
        parent_task_id
        or context.root_task_id
        or context.chain_id
        or context.stage_task_id
        or context.backlog_id
        or context.task_id
    )
    from .parallel_branch_runtime import runtime_context_id_for_branch_context

    body["runtime_context_id"] = runtime_context_id_for_branch_context(context)
    body["worker_role"] = "mf_sub"
    if fence_token:
        body["fence_token"] = fence_token
    else:
        body.pop("fence_token", None)
        body["fence_token_hash"] = trusted_fence_token_hash
    if session_token_ref and not body.get("session_token_ref"):
        body["session_token_ref"] = session_token_ref
    body["governance_project_id"] = context.governance_project_id or context.project_id
    body["target_project_id"] = context.target_project_id or ctx.get_project_id()
    target_root = _runtime_context_effective_target_project_root(context)
    if target_root and not body.get("target_project_root"):
        body["target_project_root"] = target_root
    if target_root and not body.get("project_root"):
        body["project_root"] = target_root
    if target_root and not body.get("repo_root"):
        body["repo_root"] = target_root
    body["query_source"] = "mf_subagent"
    body["run_id"] = str(body.get("run_id") or "") or f"mf_subagent:{context.task_id}:fence:{fence_hash}"
    setattr(ctx, "_validated_mf_sub_graph_query_context", context)
    setattr(ctx, "_validated_mf_sub_graph_query_route_identity", route_identity)
    return session


def _bind_trusted_mf_sub_graph_query_authority(
    ctx: RequestContext,
    conn,
    body: Mapping[str, Any],
) -> None:
    """Bind persistence authority after all earlier query gates succeed."""

    context = getattr(ctx, "_validated_mf_sub_graph_query_context", None)
    route_identity = getattr(
        ctx,
        "_validated_mf_sub_graph_query_route_identity",
        {},
    )
    if context is None or not isinstance(route_identity, Mapping):
        return
    canonical_route_identity = _runtime_context_latest_route_identity(conn, context)
    trusted_route_identity = {
        field: str(canonical_route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    route_authority_required = any(trusted_route_identity.values()) or any(
        str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    )
    if route_authority_required and any(
        not trusted_route_identity[field]
        or trusted_route_identity[field]
        != str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    ):
        raise GovernanceError(
            "mf_subagent_graph_query_route_authority_changed",
            "mf_subagent graph query route authority changed after validation",
            409,
            {
                "runtime_context_id": body["runtime_context_id"],
                "task_id": body["task_id"],
                "parent_task_id": body["parent_task_id"],
                "fail_closed": True,
                "writes_performed": False,
            },
        )
    if route_authority_required:
        setattr(
            ctx,
            "_trusted_mf_sub_graph_query_authority",
            {
                "schema_version": "runtime_context.mf_sub_graph_query_authority.v1",
                "source": "validated_runtime_context_route_identity",
                "runtime_context_id": body["runtime_context_id"],
                "task_id": body["task_id"],
                "parent_task_id": body["parent_task_id"],
                "backlog_id": str(getattr(context, "backlog_id", "") or ""),
                "worker_role": "mf_sub",
                **trusted_route_identity,
                "server_derived": True,
                "caller_route_identity_persisted_directly": False,
                "raw_route_token_persisted": False,
            },
        )


def _require_graph_query_trace_capability(ctx: RequestContext, conn, trace: dict, action: str) -> dict:
    session = ctx.require_auth(conn)
    from .permissions import require_mf_subagent_capability, require_operator_capability, session_role
    role = session_role(session)
    if str(trace.get("query_source") or "") == "mf_subagent":
        require_mf_subagent_capability(session, action)
    else:
        require_operator_capability(session, action)
    if role == "mf_sub":
        parent_task_id = str(trace.get("parent_task_id") or "").strip()
        if not parent_task_id:
            raise ValidationError("mf_subagent graph query trace must be task-scoped")
    return session


def _graph_query_trace_fence_hash(value: Mapping[str, Any] | None) -> str:
    """Resolve one persisted graph-trace fence to its copy-safe full hash."""

    if isinstance(value, Mapping):
        source: Mapping[str, Any] = value
    elif value is not None and hasattr(value, "keys"):
        source = {str(key): value[key] for key in value.keys()}
    else:
        source = {}
    persisted = str(source.get("fence_token_hash") or "").strip().lower()
    if persisted:
        return (
            persisted
            if re.fullmatch(r"sha256:[0-9a-f]{64}", persisted)
            else ""
        )
    raw = str(source.get("fence_token") or "").strip()
    if not raw:
        return ""
    from .parallel_branch_runtime import runtime_context_secret_hash

    return runtime_context_secret_hash(raw)


def _graph_query_public_fence_projection(
    value: Mapping[str, Any] | None,
    *,
    force_redacted: bool = False,
) -> dict[str, Any]:
    """Remove a raw worker fence while retaining hash-bound identity authority."""

    payload = deepcopy(dict(value or {}))
    fence_hash = _graph_query_trace_fence_hash(payload)
    payload.pop("fence_token", None)
    payload["fence_token_hash"] = fence_hash
    payload["fence_token_present"] = bool(fence_hash)
    payload["fence_token_redacted"] = bool(force_redacted or fence_hash)
    payload["raw_fence_token_exposed"] = False
    identity_fields = payload.get("identity_fields")
    if isinstance(identity_fields, (list, tuple)):
        safe_fields = [
            str(field)
            for field in identity_fields
            if str(field) != "fence_token"
        ]
        for field in (
            "fence_token_hash",
            "fence_token_present",
            "fence_token_redacted",
        ):
            if field not in safe_fields:
                safe_fields.append(field)
        payload["identity_fields"] = safe_fields
    nested_identity = payload.get("graph_query_identity")
    if isinstance(nested_identity, Mapping):
        payload["graph_query_identity"] = _graph_query_public_fence_projection(
            nested_identity,
            force_redacted=force_redacted,
        )
    return payload


def _graph_query_trace_response_payload(result: dict) -> dict:
    payload = dict(result)
    trace = dict(payload.get("trace") or {})
    if str(trace.get("query_source") or "") != "mf_subagent":
        payload["trace"] = trace
        return payload
    payload["trace"] = _graph_query_public_fence_projection(
        trace,
        force_redacted=True,
    )
    return payload


def _raise_graph_api_validation(exc: Exception):
    from .errors import ValidationError
    raise ValidationError(str(exc)) from exc


def _raise_graph_api_conflict(exc: Exception):
    raise GovernanceError("graph_snapshot_conflict", str(exc), 409) from exc


def _parallel_branch_current_target_head(
    project_id: str,
    source: dict,
    *,
    target_ref: str = "",
) -> str:
    provided = str(
        source.get("current_target_head")
        or source.get("latest_target_head")
        or ""
    ).strip()
    if provided:
        return provided
    if not _query_bool(source, "resolve_current_target_head", False):
        return ""
    ref = str(target_ref or source.get("target_ref") or "refs/heads/main").strip()
    if not ref:
        return ""
    root = _graph_governance_project_root(project_id, source)
    return _git_output(root, ["rev-parse", "--verify", ref])


def _resolve_graph_snapshot_id(conn, project_id: str, snapshot_id: str) -> str:
    if snapshot_id and snapshot_id != "active":
        return snapshot_id
    from . import graph_snapshot_store as store

    active = store.get_active_graph_snapshot(conn, project_id)
    if not active:
        from .errors import ValidationError
        raise ValidationError("no active graph snapshot for project")
    return active["snapshot_id"]


def _graph_drift_backlog_id(snapshot_id: str, path: str, drift_type: str, target_symbol: str) -> str:
    seed = f"{snapshot_id}|{path}|{drift_type}|{target_symbol}"
    digest = hashlib.sha1(seed.encode("utf-8")).hexdigest()[:10]
    safe_type = re.sub(r"[^A-Za-z0-9]+", "-", drift_type or "drift").strip("-").upper()
    return f"GRAPH-DRIFT-{safe_type}-{digest}"


def _summarize_graph_drift_rows(rows: list[dict]) -> dict:
    by_status: dict[str, int] = {}
    by_type: dict[str, int] = {}
    open_sample: list[dict] = []
    for row in rows:
        status = str(row.get("status") or "")
        drift_type = str(row.get("drift_type") or "")
        if status:
            by_status[status] = by_status.get(status, 0) + 1
        if drift_type:
            by_type[drift_type] = by_type.get(drift_type, 0) + 1
        if status == "open" and len(open_sample) < 20:
            open_sample.append({
                "path": row.get("path", ""),
                "drift_type": drift_type,
                "node_id": row.get("node_id", ""),
                "target_symbol": row.get("target_symbol", ""),
            })
    return {
        "total": len(rows),
        "by_status": dict(sorted(by_status.items())),
        "by_type": dict(sorted(by_type.items())),
        "open_sample": open_sample,
    }


@route("GET", "/api/graph-governance/{project_id}/events/stream")
def handle_graph_governance_events_stream(ctx: RequestContext):
    """Server-Sent Events stream of governance events for the dashboard.

    Emits:
      - `ready` once on connect (project_id + server_version) so the client
        can flip into "live" state.
      - One event per EventBus publish whose payload's project_id matches
        (or whose payload has no project_id — those are treated as global).
      - `: ping\\n\\n` heartbeat comment every 15s so reverse proxies and
        EventSource don't kill the idle connection.

    The handler subscribes a queue-pushing callback via subscribe_all and
    unsubscribes in the finally block when the client disconnects or the
    server shuts down. Each connection runs on its own thread courtesy of
    ThreadingHTTPServer, so multiple dashboards can stream concurrently.
    """
    import queue
    from . import event_bus

    handler = ctx.handler
    project_id = ctx.get_project_id()

    try:
        handler.send_response(200)
        handler.send_header("Content-Type", "text/event-stream; charset=utf-8")
        handler.send_header("Cache-Control", "no-cache, no-transform")
        handler.send_header("Connection", "keep-alive")
        handler.send_header("X-Accel-Buffering", "no")  # disable nginx buffering
        for k, v in handler.CORS_HEADERS.items():
            handler.send_header(k, v)
        handler.end_headers()
    except (ConnectionAbortedError, ConnectionResetError, BrokenPipeError, OSError):
        return STREAMED_RESPONSE

    q: "queue.Queue[tuple[str, dict]]" = queue.Queue(maxsize=500)

    def on_event(event_name: str, payload: dict) -> None:
        # Bound the queue: drop on overflow rather than block the publisher.
        # Filter by project_id when payload carries one; global events
        # (no project_id) are forwarded to every connection.
        pid = payload.get("project_id") if isinstance(payload, dict) else None
        if pid and project_id and pid != project_id:
            return
        try:
            q.put_nowait((event_name, payload))
        except queue.Full:
            pass

    bus = event_bus.get_event_bus()
    bus.subscribe_all(on_event)

    def _write_sse(event_name: str, data: dict) -> None:
        try:
            line = (
                f"event: {event_name}\n"
                f"data: {json.dumps(data, ensure_ascii=False, default=str)}\n\n"
            )
            handler.wfile.write(line.encode("utf-8"))
            handler.wfile.flush()
        except (ConnectionAbortedError, ConnectionResetError, BrokenPipeError, OSError):
            raise

    try:
        _write_sse("ready", {
            "ts": datetime.now(timezone.utc).isoformat(),
            "project_id": project_id,
            "server_version": get_server_version(),
        })

        while True:
            try:
                event_name, payload = q.get(timeout=15.0)
            except queue.Empty:
                try:
                    handler.wfile.write(b": ping\n\n")
                    handler.wfile.flush()
                except (ConnectionAbortedError, ConnectionResetError, BrokenPipeError, OSError):
                    break
                continue

            try:
                _write_sse(event_name, {
                    "event": event_name,
                    "payload": payload,
                    "ts": datetime.now(timezone.utc).isoformat(),
                })
            except (ConnectionAbortedError, ConnectionResetError, BrokenPipeError, OSError):
                break
    finally:
        bus.unsubscribe_all(on_event)

    return STREAMED_RESPONSE


_DEV_GRAPH_ZERO_WRITE_EMPTY_TABLES = (
    "graph_snapshot_refs",
    "graph_snapshots",
    "pending_scope_reconcile",
    "reconcile_run_metrics",
    "graph_nodes_index",
    "graph_edges_index",
)


def _dev_graph_zero_write_readiness_projection(
    conn: sqlite3.Connection,
    *,
    project_id: str,
) -> dict[str, Any] | None:
    """Project an admitted, not-yet-materialized dev graph without DDL.

    Graph schema creation remains owned by the authorized full/current-full
    reconcile path.  Readiness GETs may recognize only source-derived owner
    states; altered or unknown partial schemas remain a typed 409.
    """

    if _runtime_plane() != "dev" or project_id != AC_PROJECT_ID:
        return None
    before_changes = conn.total_changes
    try:
        classification = classify_graph_materialization_preimage(conn)
    except ValueError as exc:
        raise GovernanceError(
            "ac_dev_graph_readiness_preimage_incompatible",
            "AC dev graph readiness preimage is not source-admissible",
            409,
            {
                "runtime_plane": "dev",
                "project_id": project_id,
                "materialization_required": False,
                "zero_write_rejection": True,
                "writes_performed": False,
                "pass_synthesized": False,
            },
        ) from exc
    if conn.total_changes != before_changes:
        raise GovernanceError(
            "ac_dev_graph_readiness_projection_wrote_state",
            "AC dev graph readiness classification must be zero-write",
            500,
            {
                "runtime_plane": "dev",
                "project_id": project_id,
                "zero_write_rejection": True,
                "writes_performed": True,
                "pass_synthesized": False,
            },
        )
    owner_states = dict(classification.get("owner_states") or {})
    if owner_states and all(state == "exact" for state in owner_states.values()):
        return None
    existing_tables = {
        str(row[0])
        for row in conn.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table'"
        ).fetchall()
    }
    row_counts = {
        table: (
            int(conn.execute(f'SELECT COUNT(*) FROM "{table}"').fetchone()[0])
            if table in existing_tables
            else 0
        )
        for table in _DEV_GRAPH_ZERO_WRITE_EMPTY_TABLES
    }
    if any(row_counts.values()):
        raise GovernanceError(
            "ac_dev_graph_readiness_preimage_incompatible",
            "AC dev graph readiness preimage contains materialized graph data",
            409,
            {
                "runtime_plane": "dev",
                "project_id": project_id,
                "materialization_required": False,
                "graph_row_counts": row_counts,
                "zero_write_rejection": True,
                "writes_performed": False,
                "pass_synthesized": False,
            },
        )
    return {
        "schema_version": "ac_dev_graph_zero_write_readiness.v1",
        "runtime_plane": "dev",
        "project_id": project_id,
        "materialization_required": True,
        "materialization_entrypoint": "graph_current_full_reconcile",
        "active_graph_activation_allowed": False,
        "owner_states": owner_states,
        "planned_objects": list(classification.get("planned_objects") or []),
        "graph_row_counts": row_counts,
        "writes_performed": False,
        "mutation_performed": False,
        "pass_synthesized": False,
    }


@route("GET", "/api/graph-governance/{project_id}/status")
def handle_graph_governance_status(ctx: RequestContext):
    """Return active graph snapshot, scan baseline, and pending scope status."""
    project_id = ctx.get_project_id()
    from . import graph_snapshot_store as store

    conn = get_connection(project_id)
    try:
        readiness = _dev_graph_zero_write_readiness_projection(
            conn,
            project_id=project_id,
        )
        if readiness is not None:
            return {
                "ok": True,
                **readiness,
                "active_snapshot_id": "",
                "graph_snapshot_commit": "",
                "materialized_graph_baseline_commit": "",
                "active_snapshot_materialization": {},
                "active_snapshot_warnings": [],
                "active_snapshot_rule_fingerprint": {},
                "active_snapshot_rule_fingerprint_id": "",
                "scan_baseline_commit": "",
                "scan_baseline_id": None,
                "pending_scope_reconcile_count": 0,
                "pending_scope_reconcile": [],
                "current_state": {
                    "state": "materialization_required",
                    "snapshot_id": "",
                },
            }
        status = store.graph_governance_status(conn, project_id)
        status["current_state"] = _dashboard_current_state(
            conn,
            project_id,
            status=status,
            snapshot_id=str(status.get("active_snapshot_id") or ""),
        )
        target_commit = str(ctx.query.get("target_commit") or "")
        if target_commit:
            status["strict_ready"] = store.strict_graph_ready(
                conn,
                project_id,
                target_commit=target_commit,
            )
        return {"ok": True, **status}
    finally:
        conn.close()


