        contract_revision_id=contract_identity["contract_revision_id"],
        contract_hash=contract_identity["contract_hash"],
        context_hash=str(scoped_content_address.get("projection_hash") or ""),
        worker_implementation_lineage=(
            contract_runtime_projection.get("worker_implementation_lineage")
            if isinstance(contract_runtime_projection, Mapping)
            else {}
        ),
        contract_runtime_dispatch_identity=(
            contract_runtime_projection.get("contract_runtime_dispatch_identity")
            if isinstance(contract_runtime_projection, Mapping)
            else {}
        ),
        authority_revision=current_authority_revision,
        session_token_rejoin_eligibility=session_token_rejoin_eligibility,
        writer_role_safe_copy_payload=(
            (
                contract_runtime_projection.get(
                    "contract_runtime_next_legal_action"
                )
                or {}
            ).get("writer_role_safe_copy_payload")
            if isinstance(contract_runtime_projection, Mapping)
            else {}
        ),
