def _runtime_context_finish_facade_alias_projection(
    actionable_payloads: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        alias: deepcopy(actionable_payloads.get(alias) or {})
        for alias in _RUNTIME_CONTEXT_FINISH_FACADE_ALIASES
    }


def _runtime_context_finish_facade_line_is_exact(
    *,
    contract_runtime_next_legal_action: Mapping[str, Any],
    expected_line_id: str,
    expected_action: str,
    contract_execution_id: str,
    runtime_context_id: str,
    task_id: str,
) -> bool:
    """Close facade discoverability over the canonical ContractRuntime writer."""

    next_action = (
        contract_runtime_next_legal_action
        if isinstance(contract_runtime_next_legal_action, Mapping)
        else {}
    )
    writer = next_action.get("writer_role_safe_copy_payload")
    writer = writer if isinstance(writer, Mapping) else {}
    copy_payload = writer.get("copy_payload")
    copy_payload = copy_payload if isinstance(copy_payload, Mapping) else {}
    if not writer or not copy_payload:
        return False
    next_exact_fields = {
        "contract_execution_id": contract_execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "line_id": expected_line_id,
    }
    if any(
        not expected
        or str(next_action.get(field) or "").strip() != expected
        for field, expected in next_exact_fields.items()
    ):
        return False
    for field in ("contract_execution_id", "line_id"):
        if str(copy_payload.get(field) or "").strip() != next_exact_fields[field]:
            return False
    if str(next_action.get("action") or "").strip() != expected_action:
        return False
    if str(next_action.get("owner_role") or "").strip() != "mf_sub":
        return False
    allowed_writer_roles = {
        str(value or "").strip()
        for value in next_action.get("allowed_writer_roles") or []
    }
    if "mf_sub" not in allowed_writer_roles:
        return False
    expected_revision = next_action.get("execution_state_revision")
    if expected_revision is not None and copy_payload.get(
        "execution_state_revision"
    ) != expected_revision:
        return False
    guidance = next_action.get("submit_line_guidance")
    guidance = guidance if isinstance(guidance, Mapping) else {}
    expected_guide_hash = str(
        guidance.get("current_required_runtime_guide_hash") or ""
    ).strip()
    if expected_guide_hash and str(
        copy_payload.get("runtime_guide_hash") or ""
    ).strip() != expected_guide_hash:
        return False
    return True


def _runtime_context_finish_facade_payload_skeleton(
    submission: Mapping[str, Any],
    *,
    schema_version: str,
) -> dict[str, Any]:
    body = submission.get("copy_safe_body")
    body = dict(body) if isinstance(body, Mapping) else {}
    if not body:
        return {}
    return {
        **deepcopy(dict(submission)),
        "schema_version": schema_version,
        "canonical_submission_schema_version": str(
            submission.get("schema_version") or ""
        ),
        "actionable": True,
        "body": dict(body),
        "copy_safe_body": dict(body),
        "post_body": dict(body),
        "action_input": dict(body),
        "body_source": "copy_safe_body",
        "server_derived": True,
        "caller_hand_built_body_allowed": False,
    }


def _runtime_context_materialized_finish_gate_submission(
    template: Mapping[str, Any],
    *,
    finish_attestation_hint: Mapping[str, Any],
) -> dict[str, Any]:
    """Materialize the post-attestation gate from its accepted durable event."""

    hint = (
        finish_attestation_hint
        if isinstance(finish_attestation_hint, Mapping)
        else {}
    )
    attestation = hint.get("finish_time_worker_self_attestation")
    if not isinstance(attestation, Mapping) or not attestation:
        return {}
    attestation_event_ref = str(
        hint.get("finish_time_attestation_event_ref") or ""
    ).strip()
    if not attestation_event_ref:
        return {}
    read_receipt_event_ref = str(
        hint.get("read_receipt_event_ref") or ""
    ).strip()
    read_receipt_event_id = str(
        hint.get("read_receipt_event_id") or ""
    ).strip()
    ref_event_id = _runtime_context_timeline_event_id(read_receipt_event_ref)
    if (
        not read_receipt_event_id
        or not ref_event_id
        or read_receipt_event_id != ref_event_id
    ):
        return {}
    read_receipt_hash = str(hint.get("read_receipt_hash") or "").strip()
    if not _runtime_context_non_placeholder_text(read_receipt_hash):
        return {}
    receipt_refs = hint.get("read_receipt_event_refs")
    if (
        not isinstance(receipt_refs, list)
        or receipt_refs != [read_receipt_event_ref]
    ):
        return {}
    receipt_authority = hint.get("read_receipt_authority")
    if not isinstance(receipt_authority, Mapping) or (
        str(receipt_authority.get("status") or "") != "unique_passing"
        or receipt_authority.get("candidate_count") != 1
        or receipt_authority.get("candidate_event_refs")
        != [read_receipt_event_ref]
        or str(receipt_authority.get("event_ref") or "")
        != read_receipt_event_ref
        or str(receipt_authority.get("read_receipt_hash") or "")
        != read_receipt_hash
    ):
        return {}
    result = deepcopy(dict(template))
    body = result.get("copy_safe_body")
    body = dict(body) if isinstance(body, Mapping) else {}
    if not body:
        return {}
    head_commit = str(body.get("head_commit") or "").strip()
    if not head_commit:
        return {}
    checkpoint_seed = re.sub(r"[^A-Za-z0-9_.-]+", "-", head_commit).strip("-")
    durable_fields = {
        "checkpoint_id": f"ckpt-finish-{checkpoint_seed[:24] or 'worker'}",
        "finish_time_worker_self_attestation": dict(attestation),
        "read_receipt_event_id": read_receipt_event_id,
        "read_receipt_hash": read_receipt_hash,
    }
    body.update(durable_fields)
    result.update(durable_fields)
    result["attestation_event_ref"] = attestation_event_ref
    result["body"] = dict(body)
    result["copy_safe_body"] = dict(body)
    result["post_body"] = dict(body)
    result["body_source"] = "copy_safe_body"
    result["required_fields"] = list(
        dict.fromkeys(
            [
                *list(result.get("required_fields") or []),
                "read_receipt_event_id",
                "read_receipt_hash",
            ]
        )
    )
    result["field_pointers"] = {
        **dict(result.get("field_pointers") or {}),
        "read_receipt_event_id": "copy_safe_body.read_receipt_event_id",
        "read_receipt_hash": "copy_safe_body.read_receipt_hash",
    }
    result["read_receipt_authority"] = {
        "schema_version": "runtime_context.finish_gate_read_receipt_authority.v1",
        "source": "accepted_task_timeline_read_receipt",
        "event_ref": read_receipt_event_ref,
        "event_id": read_receipt_event_id,
        "read_receipt_hash": read_receipt_hash,
        "server_derived": True,
    }
    return result


def _runtime_context_finish_guide_authority_projection(
    *,
    finish_gate_submission: Mapping[str, Any],
    contract_runtime_next_legal_action: Mapping[str, Any],
    contract_execution_id: str,
    runtime_context_id: str,
    task_id: str,
) -> dict[str, Any]:
    """Bind one advertised finish facade to unique durable server authority."""

    submission = (
        finish_gate_submission
        if isinstance(finish_gate_submission, Mapping)
        else {}
    )
    body = submission.get("copy_safe_body")
    body = dict(body) if isinstance(body, Mapping) else {}
    if not body or not _runtime_context_finish_facade_line_is_exact(
        contract_runtime_next_legal_action=contract_runtime_next_legal_action,
        expected_line_id="worker_finish_gate",
        expected_action="record_mf_subagent_finish_gate",
        contract_execution_id=contract_execution_id,
        runtime_context_id=runtime_context_id,
        task_id=task_id,
    ):
        return {}
    expected_identity = {
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "runtime_context_id": str(runtime_context_id or "").strip(),
        "task_id": str(task_id or "").strip(),
    }
    if (
        not _runtime_context_contract_line_execution_matches(
            body,
            expected_identity["contract_execution_id"],
        )
        or any(
            not expected
            or str(body.get(field) or submission.get(field) or "").strip()
            != expected
            for field, expected in expected_identity.items()
            if field != "contract_execution_id"
        )
    ):
        return {}
    if any(
        str(body.get(field) or "").strip() not in accepted
        for field, accepted in (
            _RUNTIME_CONTEXT_FINISH_GUIDE_HOST_AUTH_PLACEHOLDERS.items()
        )
    ):
        return {}
    attestation = body.get("finish_time_worker_self_attestation")
    if not isinstance(attestation, Mapping) or not attestation:
        return {}
    if dict(attestation) != dict(
        submission.get("finish_time_worker_self_attestation") or {}
    ):
        return {}
    attestation_event_ref = str(
        submission.get("attestation_event_ref") or ""
    ).strip()
    if not _runtime_context_non_placeholder_text(attestation_event_ref):
        return {}
    read_receipt_event_id = str(body.get("read_receipt_event_id") or "").strip()
    read_receipt_hash = str(body.get("read_receipt_hash") or "").strip()
    receipt_authority = submission.get("read_receipt_authority")
    receipt_authority = (
        receipt_authority if isinstance(receipt_authority, Mapping) else {}
    )
    receipt_event_ref = str(receipt_authority.get("event_ref") or "").strip()
    if (
        receipt_authority.get("server_derived") is not True
        or str(receipt_authority.get("source") or "")
        != "accepted_task_timeline_read_receipt"
        or not read_receipt_event_id
        or _runtime_context_timeline_event_id(receipt_event_ref)
        != read_receipt_event_id
        or str(receipt_authority.get("event_id") or "").strip()
        != read_receipt_event_id
        or not _runtime_context_non_placeholder_text(read_receipt_hash)
        or str(receipt_authority.get("read_receipt_hash") or "").strip()
        != read_receipt_hash
    ):
        return {}
    authority = {
        "schema_version": "runtime_context.finish_guide_authority.v1",
        "status": "unique_durable_finish_authority",
        "available": True,
        "candidate_count": 1,
        "server_derived": True,
        "source_of_authority": (
            "ContractRuntime.next_legal_action+"
            "accepted_task_timeline_finish_attestation+read_receipt"
        ),
        **expected_identity,
        "line_id": "worker_finish_gate",
        "action": "record_mf_subagent_finish_gate",
        "owner_role": "mf_sub",
        "attestation_event_ref": attestation_event_ref,
        "read_receipt_event_ref": receipt_event_ref,
        "read_receipt_event_id": read_receipt_event_id,
        "read_receipt_hash": read_receipt_hash,
        "copy_safe_body_hash": _stable_public_hash(body),
        "raw_session_token_exposed": False,
        "raw_fence_token_exposed": False,
        "raw_route_token_exposed": False,
        "caller_inference_allowed": False,
    }
    return authority


def _runtime_context_finish_guide_authority_is_exact(
    source: Mapping[str, Any],
    *,
    contract_execution_id: str,
) -> bool:
    """Accept only the server-bound authority attached during guide assembly."""

    if not isinstance(source, Mapping):
        return False
    body = source.get("copy_safe_body")
    body = dict(body) if isinstance(body, Mapping) else {}
    authority = source.get("durable_finish_authority")
    authority = authority if isinstance(authority, Mapping) else {}
    expected_contract_execution_id = str(contract_execution_id or "").strip()
    read_receipt_event_id = str(body.get("read_receipt_event_id") or "").strip()
    read_receipt_hash = str(body.get("read_receipt_hash") or "").strip()
    if (
        not body
        or source.get("server_derived") is not True
        or source.get("actionable") is not True
        or str(source.get("body_source") or "") != "copy_safe_body"
        or str(authority.get("schema_version") or "")
        != "runtime_context.finish_guide_authority.v1"
        or str(authority.get("source_of_authority") or "")
        != (
            "ContractRuntime.next_legal_action+"
            "accepted_task_timeline_finish_attestation+read_receipt"
        )
        or authority.get("server_derived") is not True
        or authority.get("available") is not True
        or authority.get("candidate_count") != 1
        or str(authority.get("status") or "")
        != "unique_durable_finish_authority"
        or str(authority.get("line_id") or "") != "worker_finish_gate"
        or str(authority.get("action") or "")
        != "record_mf_subagent_finish_gate"
        or str(authority.get("owner_role") or "") != "mf_sub"
        or authority.get("caller_inference_allowed") is not False
        or str(authority.get("contract_execution_id") or "").strip()
        != expected_contract_execution_id
        or not _runtime_context_contract_line_execution_matches(
            body,
            expected_contract_execution_id,
        )
        or str(authority.get("runtime_context_id") or "").strip()
        != str(body.get("runtime_context_id") or "").strip()
        or str(authority.get("task_id") or "").strip()
        != str(body.get("task_id") or "").strip()
        or not _runtime_context_non_placeholder_text(
            authority.get("runtime_context_id")
        )
        or not _runtime_context_non_placeholder_text(authority.get("task_id"))
        or not _runtime_context_non_placeholder_text(
            authority.get("attestation_event_ref")
        )
        or not _runtime_context_non_placeholder_text(
            authority.get("read_receipt_event_ref")
        )
        or not _runtime_context_non_placeholder_text(
            authority.get("read_receipt_hash")
        )
        or str(authority.get("read_receipt_event_id") or "").strip()
        != read_receipt_event_id
        or _runtime_context_timeline_event_id(
            str(authority.get("read_receipt_event_ref") or "")
        )
        != read_receipt_event_id
        or str(authority.get("read_receipt_hash") or "").strip()
        != read_receipt_hash
        or str(authority.get("copy_safe_body_hash") or "")
        != _stable_public_hash(body)
        or authority.get("raw_session_token_exposed") is not False
        or authority.get("raw_fence_token_exposed") is not False
        or authority.get("raw_route_token_exposed") is not False
    ):
        return False
    if any(
        str(body.get(field) or "").strip() not in accepted
        for field, accepted in (
            _RUNTIME_CONTEXT_FINISH_GUIDE_HOST_AUTH_PLACEHOLDERS.items()
        )
    ):
        return False
    return True


_RUNTIME_CONTEXT_GUIDE_STAGE_FACADES = {
    "join": "runtime_context_session_token_initial_join",
    "runtime_text_prepare": "observer_runtime_text_prepare",
    "receipt": "runtime_context_read_receipt",
    "startup": "parallel_branch_startup",
    "graph": "graph_query",
    "implementation": "runtime_context_implementation_evidence",
    "commit": "runtime_context_worker_commit",
    "attestation": "runtime_context_finish_time_worker_attestation",
    "finish": "runtime_context_finish_gate",
    "qa": "contract_runtime_submit_line",
    "observer_close": "contract_runtime_submit_line",
    "coordinator_close": "contract_runtime_submit_line",
}


def _runtime_context_guide_executable_actions(
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
    parent_contract_execution_id: str,
    actionable_payloads: Mapping[str, Any],
    graph_copy_safe_body: Mapping[str, Any],
    qa_verification_guide: Mapping[str, Any],
    contract_runtime_next_action: Mapping[str, Any],
) -> dict[str, Any]:
    """Join every advertised worker/QA/close stage to exactly one facade."""

    actions: dict[str, dict[str, Any]] = {}

    def add(
        stage: str,
        source: Mapping[str, Any],
        *,
        default_action: str,
        default_tool: str,
        default_facade: str = "",
        optional_omission_fields: Sequence[str] = (),
    ) -> None:
        if source.get("actionable") is False:
            return
        body = source.get("copy_safe_body")
        if not isinstance(body, Mapping) or not body:
            return
        if default_tool == "runtime_context_finish_time_worker_attestation" and any(
            not _runtime_context_non_placeholder_text(body.get(field))
            for field in ("runtime_context_id", "harness_type")
        ):
            return
        contract = _guide_canonical_executable_action(
            project_id=project_id,
            backlog_id=backlog_id,
            contract_execution_id=contract_execution_id,
            parent_contract_execution_id=parent_contract_execution_id,
            action=str(source.get("action") or default_action),
            facade=str(
                source.get("facade")
                or source.get("endpoint")
                or default_facade
                or default_tool
            ),
            mcp_tool=str(source.get("mcp_tool") or default_tool),
            method=str(source.get("method") or "POST"),
            path=str(source.get("path") or ""),
            stage_id=str(source.get("stage_id") or stage),
            line_id=str(source.get("line_id") or ""),
            body=body,
            optional_omission_fields=optional_omission_fields,
            host_realization=(
                source.get("host_realization")
                if isinstance(source.get("host_realization"), Mapping)
                else None
            ),
        )
        actions[stage] = contract
        if isinstance(source, dict):
            source["canonical_executable_action"] = deepcopy(contract)
            source["copy_safe_body"] = dict(contract["copy_safe_body"])
            if isinstance(source.get("body"), Mapping):
                source["body"] = dict(contract["copy_safe_body"])

    renewal = (
        actionable_payloads.get("session_renewal_hints")
        if isinstance(actionable_payloads.get("session_renewal_hints"), Mapping)
        else {}
    )
    initial_join = (
        renewal.get("initial_join")
        if isinstance(renewal.get("initial_join"), Mapping)
        else actionable_payloads.get("session_token_initial_join_submission")
    )
    if isinstance(initial_join, Mapping):
        add(
            "join",
            initial_join,
            default_action="request_runtime_context_initial_join_host_envelope",
            default_tool="runtime_context_session_token_initial_join",
            optional_omission_fields=("host_startup_id", "host_session_id"),
        )
    rejoin = (
        renewal.get("rejoin")
        if isinstance(renewal.get("rejoin"), Mapping)
        else actionable_payloads.get("session_token_rejoin_submission")
    )
    if isinstance(rejoin, Mapping):
        add(
            "rejoin",
            rejoin,
            default_action="request_runtime_context_rejoin_host_envelope",
            default_tool="runtime_context_session_token_rejoin",
            optional_omission_fields=("host_startup_id", "host_session_id"),
        )

    runtime_text_prepare = actionable_payloads.get(
        "runtime_text_prepare_submission"
    )
    if isinstance(runtime_text_prepare, Mapping):
        add(
            "runtime_text_prepare",
            runtime_text_prepare,
            default_action="prepare_runtime_context_launch_text",
            default_tool="observer_runtime_text_prepare",
            default_facade="observer.runtime_text_prepare",
        )

    for stage, key, action, tool, facade in (
        (
            "receipt",
            "read_receipt_facade_payload_skeleton",
            "record_runtime_context_read_receipt",
            "runtime_context_read_receipt",
            "runtime_context.read_receipts",
        ),
        (
            "startup",
            "startup_facade_payload_skeleton",
            "record_mf_subagent_startup",
            "parallel_branch_startup",
            "runtime_context.startup",
        ),
        (
            "implementation",
            "implementation_evidence_facade_payload_skeleton",
            "record_implementation_evidence",
            "runtime_context_implementation_evidence",
            "runtime_context.implementation_evidence",
        ),
        (
            "commit",
            "worker_commit_facade_payload_skeleton",
            "record_worker_commit",
            "runtime_context_worker_commit",
            "runtime_context.worker_commit",
        ),
        (
            "attestation",
            "finish_time_worker_attestation_submission",
            "record_finish_time_worker_attestation",
            "runtime_context_finish_time_worker_attestation",
            "runtime_context.finish_time_worker_attestation",
        ),
        (
            "finish",
            "finish_gate_facade_payload_skeleton",
            "record_finish_gate",
            "runtime_context_finish_gate",
            "runtime_context.finish_gate",
        ),
    ):
        source = actionable_payloads.get(key)
        if isinstance(source, Mapping) and (
            stage != "finish"
            or _runtime_context_finish_guide_authority_is_exact(
                source,
                contract_execution_id=contract_execution_id,
            )
        ):
            add(
                stage,
                source,
                default_action=action,
                default_tool=tool,
                default_facade=facade,
                optional_omission_fields=(
                    (
                        "implementation_diff_submission_guidance",
                        "worker_session_lifecycle_policy",
                        "write_authorization_policy",
                    )
                    if stage == "implementation"
                    else ("worker_transcript_path",)
                    if stage == "startup"
                    else ()
                ),
            )

    graph_source = {
        "action": "run_graph_query",
        "facade": "graph_query",
        "mcp_tool": "graph_query",
        "method": "POST",
        "path": "/api/graph-governance/{project_id}/query",
        "copy_safe_body": dict(graph_copy_safe_body),
    }
    add(
        "graph",
        graph_source,
        default_action="run_graph_query",
        default_tool="graph_query",
    )

    append_evidence = (
        qa_verification_guide.get("append_evidence")
        if isinstance(qa_verification_guide.get("append_evidence"), Mapping)
        else {}
    )
    qa_body = append_evidence.get("canonical_contract_runtime_body")
    if isinstance(qa_body, Mapping) and qa_body:
        qa_source = {
            "action": "record_qa_independent_verification",
            "facade": "contract_runtime.submit_line",
            "mcp_tool": "contract_runtime_submit_line",
            "method": "POST",
            "path": (
                "/api/projects/{project_id}/contract-runtime/"
                "{contract_execution_id}/lines"
            ),
            "stage_id": "qa",
            "line_id": "qa_independent_verification",
            "copy_safe_body": dict(qa_body),
        }
        add(
            "qa",
            qa_source,
            default_action="record_qa_independent_verification",
            default_tool="contract_runtime_submit_line",
        )

    writer = contract_runtime_next_action.get("writer_role_safe_copy_payload")
    writer_body = (
        writer.get("copy_payload")
        if isinstance(writer, Mapping)
        and isinstance(writer.get("copy_payload"), Mapping)
        else {}
    )
    current_line_id = str(contract_runtime_next_action.get("line_id") or "")
    current_stage_id = str(contract_runtime_next_action.get("stage_id") or "")
    current_role = str(
        contract_runtime_next_action.get("actor_role")
        or contract_runtime_next_action.get("owner_role")
        or ""
    )
    close_stage = (
        "observer_close"
        if current_line_id == "observer_close_ready" or current_role == "observer"
        else "coordinator_close"
        if "close" in current_line_id or "close" in current_stage_id
        else ""
    )
    if close_stage and writer_body:
        close_source = {
            "action": str(
                contract_runtime_next_action.get("action")
                or current_line_id
            ),
            "facade": "contract_runtime.submit_line",
            "mcp_tool": "contract_runtime_submit_line",
            "method": "POST",
            "path": (
                "/api/projects/{project_id}/contract-runtime/"
                "{contract_execution_id}/lines"
            ),
            "stage_id": current_stage_id,
            "line_id": current_line_id,
            "copy_safe_body": dict(writer_body),
        }
        add(
            close_stage,
            close_source,
            default_action=current_line_id,
            default_tool="contract_runtime_submit_line",
        )

    finish_action_count = sum(
        action.get("mcp_tool") == "runtime_context_finish_gate"
        for action in actions.values()
    )
    finish_available = "finish" in actions and finish_action_count == 1
    stage_facade_catalog = dict(_RUNTIME_CONTEXT_GUIDE_STAGE_FACADES)
    if not finish_available:
        stage_facade_catalog.pop("finish", None)
    finish_stage_availability = {
        "stage": "finish",
        "facade": "runtime_context_finish_gate",
        "available": finish_available,
        "advertised": finish_available,
        "canonical_action_count": finish_action_count if finish_available else 0,
        "one_canonical_facade_coverage": finish_available,
        "status": "available" if finish_available else "unavailable",
        "reason": (
            "unique_canonical_executable_action"
            if finish_available
            else "durable_finish_authority_unavailable"
        ),
        "caller_inference_allowed": False,
    }
    return {
        "schema_version": "runtime_context.guide_to_facade_coverage.v1",
        "stage_facade_catalog": stage_facade_catalog,
        "literal_stage_coverage": list(stage_facade_catalog),
        "actions": actions,
        "stage_availability": {"finish": deepcopy(finish_stage_availability)},
        "finish_stage_availability": finish_stage_availability,
        "unavailable_stages": [] if finish_available else ["finish"],
        "one_canonical_facade_per_advertised_stage": True,
        "copy_safe_body_spreads_directly_to_mcp": True,
        "raw_session_token_exposed": False,
        "raw_fence_token_exposed": False,
        "raw_route_token_exposed": False,
    }


_GUIDE_RAW_AUTH_BODY_FIELDS = {
    "fence_token",
    "qa_session_token",
    "route_token",
    "session_token",
}


def _runtime_context_graph_copy_safe_body(
    *,
    project_id: str,
    runtime_context_id: str,
    task_id: str,
    parent_task_id: str,
    target_project_root: str,
    session_token_ref: str,
    route_identity: Mapping[str, Any],
    graph_payload_shape: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Build the one canonical worker graph body shared by all guides."""

    body = dict(graph_payload_shape or {})
    # A graph Guide is executable through the managed safe-ref adapter.  Raw
    # auth fields from an older RuntimeContext payload shape must not survive
    # into the public action body (or create a dangling host replacement path).
    for field in _GUIDE_RAW_AUTH_BODY_FIELDS:
        body.pop(field, None)
    body.update(
        {
            "project_id": project_id,
            "tool": "function_index",
            "args": {"query": "<exact source symbol name>"},
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "target_project_root": target_project_root,
            "worker_role": "mf_sub",
            "query_source": "mf_subagent",
            "query_purpose": "subagent_context_build",
            "session_token_ref": session_token_ref,
            "route_identity": dict(route_identity),
            "raw_session_token_exposed": False,
        }
    )
    return body


