        "server_issued_session_token_verified",
        "checkpoint_id",
        "merge_queue_ready",
        "test_results",
        "test_results_acceptance",
        "no_pass",
        "overall_release_pass_claimed",
        "validated_head_commit",
        "runtime_status",
        "validated_changed_files",
        "caller_supplied_real_startup_events_ignored",
