def _runtime_context_write_response(
    *,
    action: str,
    project_id: str,
    runtime_context_id: str,
    context,
    legacy_endpoint: str,
    result: Mapping[str, Any] | tuple[Any, ...] | None = None,
    event: Mapping[str, Any] | None = None,
    gate: Mapping[str, Any] | None = None,
    updated_context: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    status_code, result = _runtime_context_result_payload(result)
    event_summary = _runtime_context_timeline_event_summary(event)
    ok = bool(result.get("ok", True))
    if status_code is not None and status_code >= 400 and "ok" not in result:
        ok = False
    response = {
        "ok": ok,
        "schema_version": "runtime_context.write_facade_response.v1",
        "project_id": project_id,
        "runtime_context_id": runtime_context_id,
        "task_id": getattr(context, "task_id", ""),
        "action": action,
        "legacy_bridge": {
            "method": "POST",
            "path": legacy_endpoint,
        },
        "timeline_event": event_summary,
        "gate": _runtime_context_gate_summary(gate),
        "context": _runtime_context_public_context_summary(
            updated_context or {},
            fallback_context=context,
        ),
        "privacy_boundary": {
            "raw_private_context_exposed": False,
            "raw_session_token_exposed": False,
            "raw_route_token_exposed": False,
            "raw_fence_token_exposed": False,
        },
    }
    if status_code is not None:
        response["status_code"] = status_code
    for key in (
        "status",
        "error",
        "code",
        "message",
        "recoverable",
        "missing",
        "missing_fields",
        "blockers",
        "actionable_fields",
        "next_legal_action",
        "repair",
        "field",
        "expected",
        "actual",
        "field_mismatches",
        "guide",
        "source",
        "host_correctable",
        "zero_write_rejection",
        "writes_performed",
        "mutation_performed",
        "retry_same_world_allowed",
        "public_safe",
        "secret_safe",
        "timeline_event_recorded",
        "refusal_timeline_recorded",
        "context_mutated",
        "raw_session_token_exposed",
        "raw_fence_token_exposed",
        "raw_route_token_exposed",
    ):
        if key in result:
            response[key] = result[key]
    return response


def _runtime_context_result_payload(
    result: Mapping[str, Any] | tuple[Any, ...] | None,
) -> tuple[int | None, dict[str, Any]]:
    if isinstance(result, tuple) and len(result) >= 2:
        if isinstance(result[0], int):
            payload = result[1]
            return int(result[0]), dict(payload) if isinstance(payload, Mapping) else {}
        if isinstance(result[1], int):
            payload = result[0]
            return int(result[1]), dict(payload) if isinstance(payload, Mapping) else {}
        return None, {}
    return None, dict(result) if isinstance(result, Mapping) else {}


_RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS = (
    "route_id",
    "route_context_hash",
    "prompt_contract_id",
    "prompt_contract_hash",
    "route_token_ref",
    "visible_injection_manifest_hash",
)


def _runtime_context_gate_identity_mismatches(
    gate: Mapping[str, Any],
    route_identity: Mapping[str, Any],
    *,
    expected_scope: Mapping[str, Any] | None = None,
) -> list[str]:
    mismatched: list[str] = []
    for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS:
        supplied = str(gate.get(field) or "").strip()
        if not supplied:
            continue
        derived = str(route_identity.get(field) or "").strip()
        if supplied != derived:
            mismatched.append(field)
    nested_identity = (
        gate.get("route_identity")
        if isinstance(gate.get("route_identity"), Mapping)
        else {}
    )
    for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS:
        supplied = str(nested_identity.get(field) or "").strip()
        if not supplied:
            continue
        derived = str(route_identity.get(field) or "").strip()
        if supplied != derived:
            mismatched.append(f"route_identity.{field}")
    scope = gate.get("scope") if isinstance(gate.get("scope"), Mapping) else {}
    expected = expected_scope or {}
    for field in ("project_id", "backlog_id", "task_id"):
        supplied = str(scope.get(field) or "").strip()
        if not supplied:
            continue
        derived = str(expected.get(field) or "").strip()
        if supplied != derived:
            mismatched.append(f"scope.{field}")
    return mismatched


