def _runtime_context_test_results_passed(value: Any) -> bool:
    if not isinstance(value, Mapping) or not value:
        return False
    status = str(value.get("status") or "").strip().lower()
    return bool(value.get("passed")) or status in {
        "pass",
        "passed",
        "ok",
        "succeeded",
        "success",
        "clean",
    }


_RUNTIME_CONTEXT_FINISH_ATTESTATION_NO_PASS_STATUS = (
    "accepted_with_known_baseline_failure"
)
_RUNTIME_CONTEXT_FINISH_ATTESTATION_UNRELATED_SYSTEM_BLOCK_STATUS = (
    "passed_with_unrelated_system_block_recorded"
)
_RUNTIME_CONTEXT_FINISH_ATTESTATION_AMBIGUOUS_STATUSES = frozenset(
    {
        "accepted",
        "blocked",
        "error",
        "errored",
        "fail",
        "failed",
        "failure",
        "partial_sibling_blocked",
        "rejected",
    }
)
_RUNTIME_CONTEXT_FINISH_ATTESTATION_HISTORICAL_BASE_SELECTORS = frozenset(
    {
        "rev8_postmerge_qa_graph_binding or pre_rev8_qa_graph_binding",
    }
)
_RUNTIME_CONTEXT_FINISH_ATTESTATION_NO_PASS_COUNT_FIELDS = (
    "candidate_new_failures",
    "full_failed",
    "inherited_failed",
    "baseline_failed",
    "focused_passed",
    "full_passed",
    "baseline_passed",
)


def _runtime_context_finish_attestation_unrelated_system_block_results_accepted(
    value: Any,
) -> bool:
    """Accept exact passed requirements plus bounded unrelated system blocks."""

    if not isinstance(value, Mapping) or not value:
        return False
    if (
        str(value.get("status") or "").strip().lower()
        != _RUNTIME_CONTEXT_FINISH_ATTESTATION_UNRELATED_SYSTEM_BLOCK_STATUS
        or ("no_pass" in value and value.get("no_pass") is not True)
        or ("passed" in value and value.get("passed") is not False)
        or (
            "overall_release_pass" in value
            and value.get("overall_release_pass") is not False
        )
        or (
            "overall_release_pass_claimed" in value
            and value.get("overall_release_pass_claimed") is not False
        )
    ):
        return False
    required_passed = value.get("required_passed")
    unrelated_system_blocks = value.get("unrelated_system_blocks")
    tests = value.get("tests")
    if (
        not isinstance(required_passed, int)
        or isinstance(required_passed, bool)
        or required_passed <= 0
        or not isinstance(unrelated_system_blocks, int)
        or isinstance(unrelated_system_blocks, bool)
        or unrelated_system_blocks <= 0
        or not isinstance(tests, list)
        or not tests
    ):
        return False
    passed_count = 0
    blocked_count = 0
    for test in tests:
        if (
            not isinstance(test, Mapping)
            or not str(test.get("name") or "").strip()
            or not str(test.get("command") or "").strip()
        ):
            return False
        status = str(test.get("status") or "").strip().lower()
        if status in {"pass", "passed", "ok", "succeeded", "success", "clean"}:
            passed_count += 1
        elif status == "blocked_unrelated" and str(
            test.get("detail") or ""
        ).strip():
            blocked_count += 1
        else:
            return False
    return bool(
        passed_count == required_passed
        and blocked_count == unrelated_system_blocks
        and len(tests) == passed_count + blocked_count
    )


def _runtime_context_finish_attestation_no_pass_results_accepted(
    value: Any,
) -> bool:
    """Accept one exact candidate-clean result without claiming release PASS."""

    if not isinstance(value, Mapping) or not value:
        return False
    status = str(value.get("status") or "").strip().lower()
    if (
        status
        == _RUNTIME_CONTEXT_FINISH_ATTESTATION_UNRELATED_SYSTEM_BLOCK_STATUS
    ):
        return (
            _runtime_context_finish_attestation_unrelated_system_block_results_accepted(
                value
            )
        )
    if (
        status != _RUNTIME_CONTEXT_FINISH_ATTESTATION_NO_PASS_STATUS
        or value.get("no_pass") is not True
        or ("passed" in value and value.get("passed") is not False)
        or (
            "overall_release_pass" in value
            and value.get("overall_release_pass") is not False
        )
        or (
            "overall_release_pass_claimed" in value
            and value.get("overall_release_pass_claimed") is not False
        )
    ):
        return False
    counts: dict[str, int] = {}
    for field in _RUNTIME_CONTEXT_FINISH_ATTESTATION_NO_PASS_COUNT_FIELDS:
        count = value.get(field)
        if not isinstance(count, int) or isinstance(count, bool):
            return False
        counts[field] = count
    return bool(
        counts["candidate_new_failures"] == 0
        and counts["full_failed"] > 0
        and counts["full_failed"]
        == counts["inherited_failed"]
        == counts["baseline_failed"]
        and counts["focused_passed"] > 0
        and counts["full_passed"] >= counts["baseline_passed"] >= 0
    )


def _runtime_context_finish_attestation_test_results_accepted(value: Any) -> bool:
    """Validate finish evidence without changing generic PASS semantics."""

    if not isinstance(value, Mapping) or not value:
        return False
    status = str(value.get("status") or "").strip().lower()
    if (
        status
        in {
            _RUNTIME_CONTEXT_FINISH_ATTESTATION_NO_PASS_STATUS,
            _RUNTIME_CONTEXT_FINISH_ATTESTATION_UNRELATED_SYSTEM_BLOCK_STATUS,
        }
        or value.get("no_pass") is True
    ):
        return _runtime_context_finish_attestation_no_pass_results_accepted(value)
    if status in _RUNTIME_CONTEXT_FINISH_ATTESTATION_AMBIGUOUS_STATUSES:
        return False
    if status in {
        "pass",
        "passed",
        "ok",
        "succeeded",
        "success",
        "clean",
    } and value.get("passed") is False:
        return False
    return _runtime_context_test_results_passed(value)


def _runtime_context_finish_attestation_test_results_payload(
    value: Mapping[str, Any],
) -> dict[str, Any]:
    """Return the public/persisted finish result with an explicit release boundary."""

    result = dict(value)
    if _runtime_context_finish_attestation_no_pass_results_accepted(result):
        result["no_pass"] = True
        result["overall_release_pass_claimed"] = False
        if (
            str(result.get("status") or "").strip().lower()
            == _RUNTIME_CONTEXT_FINISH_ATTESTATION_UNRELATED_SYSTEM_BLOCK_STATUS
        ):
            result["passed"] = False
            result["overall_release_pass"] = False
    return result


def _runtime_context_finish_attestation_project_test_results(
    value: Any,
) -> dict[str, Any]:
    """Project truthful worker test evidence into one facade-accepted shape.

    Already accepted PASS/no-PASS evidence is stable.  The only legacy worker
    result projected here is the bounded candidate/base comparison emitted by
    test workers: both candidate suites are green, the immutable base is
    explicitly red with its immutable selector, and candidate-new failures are
    exactly zero.  Missing, ambiguous, negative, contradictory, or inconsistent
    evidence fails closed instead of synthesizing generic PASS.  Historical
    count-only evidence is not upgraded with invented failure identities.
    """

    if not isinstance(value, Mapping) or not value:
        return {}
    source = dict(value)
    if _runtime_context_finish_attestation_test_results_accepted(source):
        if _runtime_context_finish_attestation_no_pass_results_accepted(source):
            return _runtime_context_finish_attestation_test_results_payload(source)
        return source

    status = str(source.get("status") or "").strip().lower()
    if status in _RUNTIME_CONTEXT_FINISH_ATTESTATION_AMBIGUOUS_STATUSES:
        return {}
    if any(
        source.get(field) is True
        for field in (
            "passed",
            "qa_claim",
            "release_claim",
            "overall_release_pass",
            "overall_release_pass_claimed",
            "old_world_reuse",
        )
    ):
        return {}

    focused = source.get("focused_candidate")
    expanded = source.get("expanded_candidate")
    immutable_base = source.get("immutable_base")
    if not all(
        isinstance(item, Mapping)
        for item in (focused, expanded, immutable_base)
    ):
        return {}

    immutable_base_selector = str(
        immutable_base.get("selector") or ""
    ).strip()
    if (
        str(source.get("schema_version") or "").strip()
        != "runtime_context.worker_test_results.v1"
        or immutable_base_selector
        not in _RUNTIME_CONTEXT_FINISH_ATTESTATION_HISTORICAL_BASE_SELECTORS
    ):
        return {}

    def _count(container: Mapping[str, Any], field: str) -> int | None:
        candidate = container.get(field)
        if not isinstance(candidate, int) or isinstance(candidate, bool):
            return None
        if candidate < 0:
            return None
        return candidate

    candidate_new_failures = _count(source, "candidate_new_failures")
    focused_failed = _count(focused, "failed")
    focused_passed = _count(focused, "passed")
    expanded_failed = _count(expanded, "failed")
    expanded_passed = _count(expanded, "passed")
    base_failed = _count(immutable_base, "failed")
    base_passed = _count(immutable_base, "passed")
    if any(
        count is None
        for count in (
            candidate_new_failures,
            focused_failed,
            focused_passed,
            expanded_failed,
            expanded_passed,
            base_failed,
            base_passed,
        )
    ):
        return {}
    if (
        candidate_new_failures != 0
        or focused_failed != 0
        or expanded_failed != 0
        or focused_passed <= 0
        or expanded_passed <= 0
        or base_failed <= 0
        or expanded_passed < base_passed
    ):
        return {}

    passing_statuses = {"clean", "ok", "pass", "passed", "succeeded", "success"}
    if (
        str(focused.get("status") or "").strip().lower()
        not in passing_statuses
        or str(expanded.get("status") or "").strip().lower()
        not in passing_statuses
        or str(immutable_base.get("status") or "").strip().lower()
        not in {
            "accepted_with_known_baseline_failure",
            "expected_red",
            "known_baseline_failure",
        }
    ):
        return {}

    def _identity_set(
        container: Mapping[str, Any],
        *fields: str,
    ) -> tuple[bool, frozenset[str]]:
        found = False
        resolved: frozenset[str] | None = None
        for field in fields:
            if field not in container:
                continue
            found = True
            raw = container.get(field)
            if not isinstance(raw, list):
                return True, frozenset()
            values = [str(item or "").strip() for item in raw]
            if any(not item for item in values) or len(set(values)) != len(values):
                return True, frozenset()
            current = frozenset(values)
            if resolved is not None and current != resolved:
                return True, frozenset()
            resolved = current
        return found, resolved or frozenset()

    focused_ids_present, focused_ids = _identity_set(
        focused,
        "failure_identities",
        "failure_ids",
        "failed_test_ids",
    )
    expanded_ids_present, expanded_ids = _identity_set(
        expanded,
        "failure_identities",
        "failure_ids",
        "failed_test_ids",
    )
    base_ids_present, base_ids = _identity_set(
        immutable_base,
        "failure_identities",
        "failure_ids",
        "failed_test_ids",
    )
    suite_ids_present = bool(
        focused_ids_present or expanded_ids_present or base_ids_present
    )
    if suite_ids_present and (
        not focused_ids_present
        or not expanded_ids_present
        or not base_ids_present
        or focused_ids
        or expanded_ids
        or not base_ids
        or len(base_ids) != base_failed
    ):
        return {}

    direct_identity_groups = []
    for fields in (
        (
            "candidate_failure_identities",
            "candidate_failure_ids",
            "full_failure_identities",
            "full_failure_ids",
        ),
        ("inherited_failure_identities", "inherited_failure_ids"),
        (
            "base_failure_identities",
            "base_failure_ids",
            "baseline_failure_identities",
            "baseline_failure_ids",
        ),
    ):
        present, identities = _identity_set(source, *fields)
        if present:
            if not identities:
                return {}
            direct_identity_groups.append(identities)
    if direct_identity_groups and (
        len(direct_identity_groups) != 3
        or any(group != direct_identity_groups[0] for group in direct_identity_groups)
        or len(direct_identity_groups[0]) != base_failed
        or (base_ids_present and direct_identity_groups[0] != base_ids)
    ):
        return {}
    projected = {
        "status": _RUNTIME_CONTEXT_FINISH_ATTESTATION_NO_PASS_STATUS,
        "no_pass": True,
        "candidate_new_failures": 0,
        "full_failed": base_failed,
        "inherited_failed": base_failed,
        "baseline_failed": base_failed,
        "focused_passed": focused_passed,
        "full_passed": expanded_passed,
        "baseline_passed": base_passed,
    }
    if not _runtime_context_finish_attestation_no_pass_results_accepted(projected):
        return {}
    return _runtime_context_finish_attestation_test_results_payload(projected)


def _runtime_context_restore_finish_gate_no_pass_results(
    value: Any,
    *,
    test_results: Mapping[str, Any],
) -> Any:
    """Remove the in-memory legacy adapter from every public gate projection."""

    if isinstance(value, Mapping):
        restored: dict[str, Any] = {}
        for key, nested in value.items():
            if key == "test_results" and isinstance(nested, Mapping):
                restored[key] = dict(test_results)
            else:
                restored[key] = _runtime_context_restore_finish_gate_no_pass_results(
                    nested,
                    test_results=test_results,
                )
        return restored
    if isinstance(value, list):
        return [
            _runtime_context_restore_finish_gate_no_pass_results(
                nested,
                test_results=test_results,
            )
            for nested in value
        ]
    return value


def _runtime_context_validate_finish_gate_test_results(
    payload: Mapping[str, Any],
    *,
    context: Any,
    validator: Any,
    validation_error: type[Exception],
) -> dict[str, Any]:
    """Run the legacy gate while preserving strict no-PASS release semantics.

    The legacy contract only models green tests.  Its complete identity, scope,
    startup, trace, and attestation checks remain authoritative, so an exact
    candidate-clean no-PASS result is translated only in a deep-copied input.
    The adapter is removed from every returned projection before persistence.
    """

    supplied = (
        payload.get("test_results")
        if isinstance(payload.get("test_results"), Mapping)
        else {}
    )
    if not _runtime_context_finish_attestation_test_results_accepted(supplied):
        supplied_status = str(supplied.get("status") or "").strip().lower()
        if (
            supplied_status == _RUNTIME_CONTEXT_FINISH_ATTESTATION_NO_PASS_STATUS
            or supplied.get("no_pass") is True
            or supplied_status
            in _RUNTIME_CONTEXT_FINISH_ATTESTATION_AMBIGUOUS_STATUSES
        ):
            raise validation_error(
                "MF subagent finish gate requires accepted finish-attestation "
                "test_results"
            )
        return validator(payload, context=context)
    if not _runtime_context_finish_attestation_no_pass_results_accepted(supplied):
        return validator(payload, context=context)

    public_results = _runtime_context_finish_attestation_test_results_payload(
        supplied
    )
    adapted_payload = deepcopy(dict(payload))
    adapted_payload["test_results"] = {
        **public_results,
        "passed": True,
        "_runtime_context_strict_no_pass_validation_adapter": True,
    }
    gate = validator(adapted_payload, context=context)
    restored = _runtime_context_restore_finish_gate_no_pass_results(
        gate,
        test_results=public_results,
    )
    if not isinstance(restored, Mapping):
        raise validation_error("MF subagent finish gate returned an invalid result")
    result = dict(restored)
    result.update(
        {
            "no_pass": True,
            "overall_release_pass_claimed": False,
            "test_results_acceptance": {
                "schema_version": (
                    "runtime_context.finish_gate_no_pass_acceptance.v1"
                ),
                "status": str(public_results.get("status") or ""),
                "no_pass": True,
                "candidate_new_failures": int(
                    public_results.get("candidate_new_failures") or 0
                ),
                "unrelated_system_blocks": int(
                    public_results.get("unrelated_system_blocks") or 0
                ),
                "worker_finish_ready": True,
                "overall_release_pass_claimed": False,
                "source": "strict_finish_attestation_test_results",
            },
        }
    )
    for projection_key in ("lane_ownership_projection", "close_gate_projection"):
        projection = result.get(projection_key)
        if isinstance(projection, Mapping):
            result[projection_key] = {
                **dict(projection),
                "no_pass": True,
                "overall_release_pass_claimed": False,
            }
    return result


_RUNTIME_CONTEXT_GRAPH_TRACE_ID_KEYS = {
    "graph_trace_id",
    "graph_trace_ids",
    "graph_query_trace_id",
    "graph_query_trace_ids",
    "trace_ids",
    "verified_trace_ids",
}


def _runtime_context_graph_trace_values(
    value: Any,
) -> tuple[bool, list[str]]:
    found_key = False
    values: list[str] = []
    if isinstance(value, Mapping):
        for key, nested in value.items():
            key_text = str(key)
            if key_text in _RUNTIME_CONTEXT_GRAPH_TRACE_ID_KEYS:
                found_key = True
                values.extend(
                    _runtime_context_service_query_values({key_text: nested}, key_text)
                )
            nested_found, nested_values = _runtime_context_graph_trace_values(nested)
            found_key = found_key or nested_found
            values.extend(nested_values)
    elif isinstance(value, (list, tuple, set)):
        for nested in value:
            nested_found, nested_values = _runtime_context_graph_trace_values(nested)
            found_key = found_key or nested_found
            values.extend(nested_values)
    return found_key, _runtime_context_service_dedupe(values)


def _runtime_context_implementation_graph_trace_db_evidence(
    conn,
    *,
    project_id: str,
    runtime_context_id: str,
    context,
    parent_task_id: str,
    fence_token: str,
    sources: Sequence[Any],
) -> dict[str, Any]:
    explicit_marker = False
    explicit_values: list[str] = []
    for source in sources:
        found_key, values = _runtime_context_graph_trace_values(source)
        explicit_marker = explicit_marker or found_key
        explicit_values.extend(values)
    explicit_trace_ids = _runtime_context_service_dedupe(explicit_values)
    if explicit_marker and not explicit_trace_ids:
        raise GovernanceError(
            "runtime_context_graph_trace_evidence_rejected",
            "runtime-context implementation evidence requires non-empty graph trace ids",
            422,
            {
                "runtime_context_id": runtime_context_id,
                "task_id": getattr(context, "task_id", ""),
                "missing_requirement_ids": ["graph_trace_ids_nonempty"],
                "rejects_empty_or_fake_graph_evidence": True,
            },
        )

    if explicit_trace_ids:
        refs = _runtime_context_service_graph_trace_refs(
            conn,
            project_id=project_id,
            runtime_context_id=runtime_context_id,
            task_id=context.task_id,
            parent_task_id=parent_task_id,
            backlog_id=context.backlog_id,
            fence_token=fence_token,
            explicit_trace_ids=explicit_trace_ids,
            strict_explicit_trace_ids=True,
        )
        if not refs.get("db_verified"):
            missing = ["graph_trace_ids_db_verified"]
            if refs.get("identity_mismatches"):
                missing.append("graph_trace_identity_current_runtime_context")
            raise GovernanceError(
                "runtime_context_graph_trace_evidence_rejected",
                (
                    "runtime-context implementation evidence graph trace ids must "
                    "resolve to DB-verified mf_sub graph_query_traces rows"
                ),
                422,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": getattr(context, "task_id", ""),
                    "missing_requirement_ids": missing,
                    "graph_trace_db_evidence": (
                        _runtime_context_service_redact_graph_trace_refs(refs)
                    ),
                    "rejects_empty_or_fake_graph_evidence": True,
                },
            )
        return refs

    refs = _runtime_context_service_graph_trace_refs(
        conn,
        project_id=project_id,
        runtime_context_id=runtime_context_id,
        task_id=context.task_id,
        parent_task_id=parent_task_id,
        backlog_id=context.backlog_id,
        fence_token=fence_token,
        explicit_trace_ids=[],
    )
    return refs if refs.get("db_verified") else {}


def _runtime_context_test_results_compatible(
    candidate: Mapping[str, Any],
    expected: Mapping[str, Any],
) -> bool:
    if dict(candidate) == dict(expected):
        return _runtime_context_finish_attestation_test_results_accepted(candidate)
    if not _runtime_context_finish_attestation_test_results_accepted(candidate):
        return False
    if not _runtime_context_finish_attestation_test_results_accepted(expected):
        return False
    candidate_no_pass = (
        _runtime_context_finish_attestation_no_pass_results_accepted(candidate)
    )
    expected_no_pass = (
        _runtime_context_finish_attestation_no_pass_results_accepted(expected)
    )
    if candidate_no_pass or expected_no_pass:
        if not candidate_no_pass or not expected_no_pass:
            return False
        if any(
            candidate.get(field) != expected.get(field)
            for field in (
                "status",
                "no_pass",
                *_RUNTIME_CONTEXT_FINISH_ATTESTATION_NO_PASS_COUNT_FIELDS,
            )
        ):
            return False
    candidate_commands = set(
        _runtime_context_service_query_values(candidate, "command", "commands")
    )
    expected_commands = set(
        _runtime_context_service_query_values(expected, "command", "commands")
    )
    if candidate_commands and expected_commands:
        return candidate_commands == expected_commands
    return True


def _runtime_context_finish_attestation_sources(
    body: Mapping[str, Any],
) -> list[Mapping[str, Any]]:
    sources: list[Mapping[str, Any]] = [body]
    for key in (
        "finish_time_worker_self_attestation",
        "worker_self_attestation",
        "self_attestation",
        "attestation",
        "artifact_refs",
        "payload",
    ):
        value = body.get(key)
        if isinstance(value, Mapping):
            sources.append(value)
    return sources


def _runtime_context_finish_attestation_text(
    body: Mapping[str, Any],
    *keys: str,
) -> str:
    for source in _runtime_context_finish_attestation_sources(body):
        for key in keys:
            if source is body:
                value = source.get(key)
            else:
                value = _timeline_first_deep_text(source, key)
            text = _runtime_context_non_placeholder_text(value)
            if text:
                return text
    return ""


def _runtime_context_finish_gate_submission_payload(
    *,
    project_id: str,
    runtime_context_id: str,
    context,
    parent_task_id: str,
    route_identity: Mapping[str, Any] | None,
    finish_time_worker_self_attestation: Mapping[str, Any],
    head_commit: str,
    changed_files: Sequence[str],
    test_results: Mapping[str, Any],
    graph_trace_ids: Sequence[str],
    read_receipt_event_id: str,
    read_receipt_hash: str,
    observer_command_id: str = "",
    contract_runtime_dispatch_identity: Mapping[str, Any] | None = None,
    worker_session_id: str = "",
    filer_principal: str = "",
    finish_order_projection: Mapping[str, Any] | None = None,
    request_body: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    body = request_body if isinstance(request_body, Mapping) else {}
    route = route_identity if isinstance(route_identity, Mapping) else {}
    dispatch_identity = (
        contract_runtime_dispatch_identity
        if isinstance(contract_runtime_dispatch_identity, Mapping)
        else {}
    )
    dispatch_identity_fields = (
        _contract_runtime_dispatch_identity_projection_fields(
            dispatch_identity
        )
    )
    dispatch_identity_fields.pop("observer_command_id", None)
    target_project_root = str(
        body.get("target_project_root")
        or getattr(context, "target_project_root", "")
        or getattr(context, "worktree_path", "")
        or ""
    ).strip()
    worktree_path = str(
        getattr(context, "worktree_path", "") or target_project_root
    ).strip()
    current_branch_head_commit = _runtime_context_git_head_commit(
        worktree_path,
        target_project_root,
    )
    row_scoped_finish_head_projection = (
        _runtime_context_row_scoped_finish_head_projection(
            row_scoped_implementation_head_commit=head_commit,
            runtime_context_head_commit=str(getattr(context, "head_commit", "") or ""),
            current_branch_head_commit=current_branch_head_commit,
            base_commit=str(getattr(context, "base_commit", "") or ""),
            target_head_commit=str(getattr(context, "target_head_commit", "") or ""),
            target_project_root=target_project_root,
            worktree_path=worktree_path,
            contract_worker_commit_required=bool(
                isinstance(finish_order_projection, Mapping)
                and finish_order_projection.get("canonical_worker_commit_required")
            ),
        )
    )
    checkpoint_id = str(
        body.get("checkpoint_id") or getattr(context, "checkpoint_id", "") or ""
    ).strip()
    if not checkpoint_id:
        checkpoint_seed = re.sub(
            r"[^A-Za-z0-9_.-]+",
            "-",
            (
                head_commit
                or runtime_context_id
                or str(getattr(context, "task_id", "") or "")
            )
        ).strip("-")
        checkpoint_id = f"ckpt-finish-{checkpoint_seed[:24] or 'worker'}"
    action = "record_finish_gate"
    path = (
        "/api/graph-governance/{project_id}/runtime-contexts/"
        "{runtime_context_id}/finish-gate"
    )
    concrete_path = (
        f"/api/graph-governance/{project_id}/runtime-contexts/"
        f"{runtime_context_id}/finish-gate"
    )
    route_identity_payload = {
        field: str(route.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        if str(route.get(field) or "").strip()
    }
    submission_body: dict[str, Any] = {
        "runtime_context_id": runtime_context_id,
        "task_id": str(getattr(context, "task_id", "") or ""),
        "parent_task_id": parent_task_id,
        "fence_token": "<same fence_token used for finish-time attestation>",
        "session_token": "<same runtime_context_session_token used for finish-time attestation>",
        "target_project_root": target_project_root,
        "checkpoint_id": checkpoint_id,
        "head_commit": head_commit,
        "current_branch_head_commit": current_branch_head_commit,
        "row_scoped_finish_head_projection": row_scoped_finish_head_projection,
        "changed_files": list(changed_files),
        "owned_files": list(changed_files),
        "status": "review_ready",
        "test_results": dict(test_results),
        "graph_trace_ids": list(graph_trace_ids),
        "read_receipt_event_id": read_receipt_event_id,
        "read_receipt_hash": read_receipt_hash,
        "finish_time_worker_self_attestation": dict(
            finish_time_worker_self_attestation
        ),
    }
    if isinstance(finish_order_projection, Mapping):
        submission_body["finish_order_projection"] = dict(finish_order_projection)
    if observer_command_id:
        submission_body["observer_command_id"] = observer_command_id
    submission_body.update(dispatch_identity_fields)
    if worker_session_id:
        submission_body["worker_session_id"] = worker_session_id
    if filer_principal:
        submission_body["filer_principal"] = filer_principal
    # The finish gate validates the worker's execution location against the
    # assigned worktree.  Caller-supplied attestation paths are not authoritative
    # and must not replace that runtime-context identity.
    for field in ("actual_cwd", "actual_git_root"):
        if worktree_path:
            submission_body[field] = worktree_path
    if route_identity_payload:
        submission_body["route_identity"] = route_identity_payload
    return {
        "schema_version": "runtime_context.finish_gate_submission.v1",
        "action": action,
        "name": action,
        "next_legal_action": action,
        "method": "POST",
        "endpoint": "runtime_context.finish_gate",
        "path": path,
        "concrete_path": concrete_path,
        "runtime_context_id": runtime_context_id,
        "task_id": str(getattr(context, "task_id", "") or ""),
        "parent_task_id": parent_task_id,
        "backlog_id": str(getattr(context, "backlog_id", "") or ""),
        "fence_token": submission_body["fence_token"],
        "session_token": submission_body["session_token"],
        "target_project_root": target_project_root,
        "checkpoint_id": checkpoint_id,
        "head_commit": head_commit,
        "current_branch_head_commit": current_branch_head_commit,
        "row_scoped_finish_head_projection": row_scoped_finish_head_projection,
        "changed_files": list(changed_files),
        "test_results": dict(test_results),
        "graph_trace_ids": list(graph_trace_ids),
        "read_receipt_event_id": read_receipt_event_id,
        "read_receipt_hash": read_receipt_hash,
        "finish_time_worker_self_attestation": dict(
            finish_time_worker_self_attestation
        ),
        **(
            {"finish_order_projection": dict(finish_order_projection)}
            if isinstance(finish_order_projection, Mapping)
            else {}
        ),
        **({"observer_command_id": observer_command_id} if observer_command_id else {}),
        **dispatch_identity_fields,
        "body": submission_body,
        "reminders": {
            "fence_token": "Use the same lane fence_token from the worker launch envelope.",
            "session_token": "Use the current runtime_context_session_token; raw token is not echoed.",
            "target_project_root": "Keep this equal to the assigned worker worktree/root.",
            "head_scope": (
                "Keep head_commit equal to the row-scoped implementation head. "
                "current_branch_head_commit is informational when successor "
                "repairs continue on the same branch."
            ),
            "contract_worker_commit_order": (
                "Finish evidence consumes the exact ContractRuntime worker_commit; "
                "later HEAD or worktree drift is rejected."
            ),
            "canonical_finish_gate_required": True,
            "raw_finish_time_attestation_alone_close_satisfying": False,
        },
        "privacy_boundary": {
            "raw_session_token_exposed": False,
            "raw_fence_token_exposed": False,
            "raw_route_token_exposed": False,
        },
    }


def _runtime_context_same_string_set(left: Any, right: Any) -> bool:
    return set(_runtime_context_service_query_values({"value": left}, "value")) == set(
        _runtime_context_service_query_values({"value": right}, "value")
    )


def _runtime_context_timeline_event_id(value: Any) -> str:
    event_id = str(value or "").strip()
    if event_id.startswith("timeline:"):
        event_id = event_id.split(":", 1)[1].strip()
    return event_id


def _runtime_context_finish_attestation_candidate(
    body: Mapping[str, Any],
) -> dict[str, Any]:
    evidence = body.get("evidence") if isinstance(body.get("evidence"), Mapping) else {}
    for source in (body, evidence):
        for key in (
            "finish_time_worker_self_attestation",
            "worker_self_attestation",
            "finish_attestation",
        ):
            candidate = source.get(key)
            if isinstance(candidate, Mapping):
                return dict(candidate)
    return {}


def _runtime_context_contract_line_execution_matches(
    value: Mapping[str, Any],
    contract_execution_id: str,
) -> bool:
    """Require every claimed execution identity to bind to one execution."""

    expected = str(contract_execution_id or "").strip()
    claimed = {
        str(candidate.get(key) or "").strip()
        for candidate in _contract_runtime_mapping_candidates(value)
        for key in ("contract_execution_id", "successor_contract_execution_id")
        if str(candidate.get(key) or "").strip()
    }
    return bool(expected and claimed == {expected})


def _runtime_context_contract_active_worker_round(
    record: Mapping[str, Any],
    *,
    runtime_context_id: str,
    task_id: str,
    parent_task_id: str,
) -> tuple[list[tuple[int, Mapping[str, Any]]], int, int, Mapping[str, Any], list[tuple[int, Mapping[str, Any]]]]:
    """Return the active worker commit and later finish attestations."""

    completed = _contract_runtime_completed_lines(record)
    failed_qa_index = _active_failed_qa_line_index([line for _, line in completed])

    def matches(line: Mapping[str, Any]) -> bool:
        return _contract_runtime_mapping_matches_context(
            line,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            parent_task_id=parent_task_id,
        )

    commits = [
        (index, line)
        for index, line in completed
        if index > failed_qa_index
        and str(line.get("line_id") or "").strip() == "worker_commit"
        and matches(line)
    ]
    commit_index, commit = commits[-1] if commits else (-1, {})
    attestations = [
        (index, line)
        for index, line in completed
        if index > commit_index
        and str(line.get("line_id") or "").strip()
        == "worker_finish_time_attestation"
        and matches(line)
    ]
    return completed, failed_qa_index, commit_index, commit, attestations


def _runtime_context_finish_attestation_recovery_marker(
    line: Mapping[str, Any],
    *,
    contract_execution_id: str,
    runtime_context_id: str,
    task_id: str,
    parent_task_id: str,
    active_worker_commit_line_index: int,
) -> dict[str, Any]:
    """Return one cryptographically bound strict-facade correction marker."""

    payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
    marker = (
        payload.get("canonical_finish_attestation_recovery")
        if isinstance(
            payload.get("canonical_finish_attestation_recovery"),
            Mapping,
        )
        else {}
    )
    if not marker:
        return {}
    canonical_payload = dict(payload)
    canonical_payload.pop("canonical_finish_attestation_recovery", None)
    try:
        superseded_index = int(
            marker.get("superseded_completed_line_index")
        )
        marker_commit_index = int(
            marker.get("active_worker_commit_line_index")
        )
    except (TypeError, ValueError):
        return {}
    expected = {
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "runtime_context_id": str(runtime_context_id or "").strip(),
        "task_id": str(task_id or "").strip(),
        "parent_task_id": str(parent_task_id or "").strip(),
    }
    if not (
        str(marker.get("schema_version") or "").strip()
        == "runtime_context.canonical_finish_attestation_recovery.v1"
        and str(marker.get("source") or "").strip()
        == "runtime_context_finish_time_worker_attestation"
        and marker.get("server_derived") is True
        and marker.get("strict_facade_verified") is True
        and marker.get("append_only_history_preserved") is True
        and marker.get("contract_runtime_state_transition_replayed") is False
        and marker.get("generic_contract_runtime_submit_line_allowed") is False
        and marker_commit_index == active_worker_commit_line_index
        and superseded_index > active_worker_commit_line_index
        and all(
            str(marker.get(field) or "").strip() == value
            for field, value in expected.items()
        )
        and str(marker.get("canonical_payload_hash") or "").strip()
        == stable_sha256(canonical_payload)
    ):
        return {}
    return dict(marker)


def _runtime_context_contract_finish_attestation_projection(
    conn,
    *,
    context: Any,
    contract_execution_id: str,
    runtime_context_id: str,
    parent_task_id: str,
    head_commit: str,
    changed_files: Sequence[str],
    test_results: Mapping[str, Any],
    supplied_worker_session_id: str = "",
    supplied_filer_principal: str = "",
    read_receipt_event_id: str = "",
    read_receipt_hash: str = "",
    supplied_attestation: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Project one exact accepted ContractRuntime finish attestation."""

    task_id = str(getattr(context, "task_id", "") or "").strip()
    try:
        record = _contract_runtime_store(conn).get(contract_execution_id)
    except (ContractRuntimeError, sqlite3.Error) as exc:
        raise GovernanceError(
            "contract_worker_finish_attestation_required",
            str(exc),
            422,
            {"contract_execution_id": contract_execution_id},
        ) from exc
    (
        completed_lines,
        failed_qa_index,
        active_worker_commit_index,
        active_worker_commit,
        matches,
    ) = _runtime_context_contract_active_worker_round(
        record,
        runtime_context_id=runtime_context_id,
        task_id=task_id,
        parent_task_id=parent_task_id,
    )
    requested_head = str(head_commit or "").strip()
    round_mismatched_fields: list[str] = []
    active_commit_session = ""
    active_commit_filer = ""
    if active_worker_commit:
        active_commit_payload = (
            active_worker_commit.get("payload")
            if isinstance(active_worker_commit.get("payload"), Mapping)
            else {}
        )
        active_commit_head = str(
            active_worker_commit.get("commit_sha")
            or active_commit_payload.get("worker_commit_sha")
            or active_commit_payload.get("commit_sha")
            or active_commit_payload.get("head_commit")
            or ""
        ).strip()
        if not _runtime_context_contract_line_execution_matches(
            active_worker_commit, contract_execution_id
        ):
            round_mismatched_fields.append("contract_execution_id")
        if not active_commit_head or active_commit_head != requested_head:
            round_mismatched_fields.append("head_commit")
        active_commit_session = _runtime_context_finish_attestation_text(
            active_worker_commit, "worker_session_id"
        )
        active_commit_filer = _runtime_context_finish_attestation_text(
            active_worker_commit, "filer_principal"
        )
        if not active_commit_session:
            round_mismatched_fields.append("worker_session_id")
        if not active_commit_filer or active_commit_filer != active_commit_session:
            round_mismatched_fields.append("filer_principal")
        if (
            supplied_worker_session_id
            and active_commit_session
            and active_commit_session != supplied_worker_session_id
        ):
            round_mismatched_fields.append("worker_session_id")
        if (
            supplied_filer_principal
            and active_commit_filer
            and active_commit_filer != supplied_filer_principal
        ):
            round_mismatched_fields.append("filer_principal")

    correction_matches: list[tuple[int, Mapping[str, Any], dict[str, Any]]] = []
    for index, line in matches:
        marker = _runtime_context_finish_attestation_recovery_marker(
            line,
            contract_execution_id=contract_execution_id,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            parent_task_id=parent_task_id,
            active_worker_commit_line_index=active_worker_commit_index,
        )
        if marker:
            correction_matches.append((index, line, marker))
    canonical_recovery: dict[str, Any] = {}
    if correction_matches:
        correction_index, correction_line, canonical_recovery = (
            correction_matches[0]
        )
        superseded_index = int(
            canonical_recovery["superseded_completed_line_index"]
        )
        match_indices = [index for index, _ in matches]
        if (
            len(correction_matches) != 1
            or correction_index <= superseded_index
            or match_indices != [superseded_index, correction_index]
        ):
            raise GovernanceError(
                "contract_worker_finish_attestation_ambiguous",
                "strict facade finish-attestation recovery is missing or ambiguous",
                422,
                {
                    "contract_execution_id": contract_execution_id,
                    "matching_completed_line_indexes": match_indices,
                    "recovery_completed_line_indexes": [
                        index for index, _, _ in correction_matches
                    ],
                    "active_failed_qa_line_index": failed_qa_index,
                    "active_worker_commit_line_index": active_worker_commit_index,
                },
            )
        matches = [(correction_index, correction_line)]
    if active_worker_commit_index < 0 or not matches:
        raise GovernanceError(
            "contract_worker_finish_attestation_required",
            "finish requires one exact accepted ContractRuntime finish attestation",
            422,
            {
                "contract_execution_id": contract_execution_id,
                "matching_completed_line_indexes": [index for index, _ in matches],
                "active_failed_qa_line_index": failed_qa_index,
                "active_worker_commit_line_index": active_worker_commit_index,
            },
        )
    if round_mismatched_fields:
        raise GovernanceError(
            "contract_worker_finish_attestation_mismatch",
            "canonical ContractRuntime worker round does not match finish gate",
            422,
            {
                "contract_execution_id": contract_execution_id,
                "mismatched_fields": list(dict.fromkeys(round_mismatched_fields)),
                "matching_completed_line_indexes": [index for index, _ in matches],
                "active_failed_qa_line_index": failed_qa_index,
                "active_worker_commit_line_index": active_worker_commit_index,
            },
        )
    if len(matches) != 1:
        raise GovernanceError(
            "contract_worker_finish_attestation_ambiguous",
            "finish requires one exact accepted ContractRuntime finish attestation",
            422,
            {
                "contract_execution_id": contract_execution_id,
                "matching_completed_line_indexes": [index for index, _ in matches],
                "active_failed_qa_line_index": failed_qa_index,
                "active_worker_commit_line_index": active_worker_commit_index,
            },
        )

    index, line = matches[0]
    payload = dict(line.get("payload") or {})
    from .mf_subagent_contract import _finish_time_worker_attestation_gate

    gate = _finish_time_worker_attestation_gate(payload)
    attestation = dict(gate.get("attestation") or {})
    canonical_head = str(
        line.get("commit_sha") or payload.get("head_commit") or ""
    ).strip()
    canonical_files = _runtime_context_service_query_values(payload, "changed_files")
    canonical_tests = dict(payload.get("test_results") or {})
    canonical_session = str(gate.get("worker_session_id") or "").strip()
    canonical_filer = str(gate.get("filer_principal") or "").strip()
    canonical_read_id = _runtime_context_timeline_event_id(
        payload.get("read_receipt_event_id")
    )
    canonical_read_hash = str(payload.get("read_receipt_hash") or "").strip()
    checks = {
        "contract_execution_id": _runtime_context_contract_line_execution_matches(
            line, contract_execution_id
        ),
        "finish_time_worker_self_attestation": bool(gate.get("passed")),
        "head_commit": canonical_head == requested_head,
        "changed_files": _runtime_context_same_string_set(
            canonical_files, changed_files
        ),
        "test_results": _runtime_context_finish_attestation_test_results_accepted(
            canonical_tests
        )
        and _runtime_context_test_results_compatible(canonical_tests, test_results),
        "worker_session_id": bool(canonical_session)
        and canonical_session == active_commit_session
        and (
            not supplied_worker_session_id
            or supplied_worker_session_id == canonical_session
        ),
        "filer_principal": bool(canonical_filer)
        and canonical_filer == canonical_session
        and canonical_filer == active_commit_filer
        and (
            not supplied_filer_principal
            or supplied_filer_principal == canonical_filer
        ),
        "read_receipt_event_id": bool(canonical_read_id)
        and (
            not read_receipt_event_id
            or _runtime_context_timeline_event_id(read_receipt_event_id)
            == canonical_read_id
        ),
        "read_receipt_hash": bool(canonical_read_hash)
        and (not read_receipt_hash or read_receipt_hash == canonical_read_hash),
        "graph_trace_ids": bool(
            _runtime_context_service_query_values(payload, "graph_trace_ids")
        ),
    }
    mismatched_fields = [field for field, passed in checks.items() if not passed]
    if any(
        _runtime_context_non_placeholder_text(value)
        and value != attestation.get(field)
        for field, value in (supplied_attestation or {}).items()
    ):
        mismatched_fields.append("finish_time_worker_self_attestation")
    if mismatched_fields:
        raise GovernanceError(
            "contract_worker_finish_attestation_mismatch",
            "canonical ContractRuntime finish attestation does not match finish gate",
            422,
            {
                "contract_execution_id": contract_execution_id,
                "mismatched_fields": list(dict.fromkeys(mismatched_fields)),
            },
        )
    return {
        "source_of_authority": (
            "ContractRuntime.completed_lines.worker_finish_time_attestation"
        ),
        "contract_execution_id": contract_execution_id,
        "contract_runtime_source_ref": (
            f"contract_runtime:{contract_execution_id}:completed_lines:{index}"
        ),
        "active_failed_qa_line_index": failed_qa_index,
        "active_worker_commit_line_index": active_worker_commit_index,
        "worker_session_id": canonical_session,
        "filer_principal": canonical_filer,
        "read_receipt_event_id": canonical_read_id,
        "read_receipt_hash": canonical_read_hash,
        "finish_time_worker_self_attestation": attestation,
        "canonical_finish_attestation_recovery": canonical_recovery,
    }


def _runtime_context_latest_finish_attestation(
    conn,
    *,
    project_id: str,
    context,
    runtime_context_id: str,
    parent_task_id: str,
    head_commit: str = "",
    changed_files: Sequence[str] | None = None,
    test_results: Mapping[str, Any] | None = None,
    worker_session_id: str = "",
    read_receipt_event_id: str = "",
    read_receipt_hash: str = "",
) -> dict[str, Any]:
    from . import task_timeline

    events = task_timeline.list_events(
        conn,
        project_id,
        task_id=str(getattr(context, "task_id", "") or ""),
        event_kind="worker_progress",
        limit=200,
    )
    expected_head = str(head_commit or "").strip()
    expected_changed = list(changed_files or [])
    expected_tests = dict(test_results or {})
    expected_worker_session_id = str(worker_session_id or "").strip()
    expected_read_receipt_event_id = _runtime_context_timeline_event_id(
        read_receipt_event_id
    )
    expected_read_receipt_hash = str(read_receipt_hash or "").strip()
    for event in reversed(events):
        if not isinstance(event, Mapping):
            continue
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        if payload.get("action") != "record_finish_time_worker_attestation":
            continue
        if str(payload.get("runtime_context_id") or "") != runtime_context_id:
            continue
        if str(payload.get("task_id") or "") != str(getattr(context, "task_id", "") or ""):
            continue
        if parent_task_id and str(payload.get("parent_task_id") or "") != parent_task_id:
            continue
        if expected_head and str(payload.get("head_commit") or "").strip() != expected_head:
            continue
        if expected_changed and not _runtime_context_same_string_set(
            payload.get("changed_files"),
            expected_changed,
        ):
            continue
        if expected_tests:
            candidate_tests = (
                payload.get("test_results")
                if isinstance(payload.get("test_results"), Mapping)
                else {}
            )
            if not _runtime_context_test_results_compatible(
                candidate_tests,
                expected_tests,
            ):
                continue
        attestation = payload.get("finish_time_worker_self_attestation")
        attestation_payload = attestation if isinstance(attestation, Mapping) else {}
        if expected_worker_session_id:
            candidate_worker_session_id = str(
                payload.get("worker_session_id")
                or payload.get("filer_principal")
                or attestation_payload.get("worker_session_id")
                or attestation_payload.get("filer_principal")
                or ""
            ).strip()
            if candidate_worker_session_id != expected_worker_session_id:
                continue
        if expected_read_receipt_event_id:
            candidate_read_receipt_event_id = _runtime_context_timeline_event_id(
                payload.get("read_receipt_event_id")
                or payload.get("read_receipt_timeline_id")
                or attestation_payload.get("read_receipt_event_id")
                or attestation_payload.get("read_receipt_timeline_id")
                or ""
            )
            if candidate_read_receipt_event_id != expected_read_receipt_event_id:
                continue
        if expected_read_receipt_hash:
            candidate_read_receipt_hash = str(
                payload.get("read_receipt_hash")
                or attestation_payload.get("read_receipt_hash")
                or ""
            ).strip()
            if candidate_read_receipt_hash != expected_read_receipt_hash:
                continue
        if isinstance(attestation, Mapping):
            return dict(attestation)
    return {}


@route("GET", "/api/graph-governance/{project_id}/parallel-branches/{task_id}/runtime-contract")
def handle_graph_governance_parallel_branch_runtime_contract(ctx: RequestContext):
    """Return a role-scoped runtime/contract view for one bounded worker lane."""
    project_id = ctx.get_project_id()
    from .parallel_branch_runtime import (
        BranchRuntimeFenceError,
        get_branch_context,
        validate_mf_subagent_graph_query_identity,
    )
    from .permissions import session_role

    task_id = str(ctx.path_params.get("task_id") or ctx.query.get("task_id") or "").strip()
    if not task_id:
        raise ValidationError("task_id is required")

    conn = get_connection(project_id)
    try:
        session = _require_graph_governance_mf_subagent(
            ctx,
            conn,
            "graph-governance.parallel-branches.runtime-contract",
        )
        role = session_role(session)
        if role == "mf_sub":
            fence_token = str(ctx.query.get("fence_token") or "").strip()
            if not fence_token:
                raise ValidationError("fence_token is required for mf_sub runtime contract query")
            try:
                context = validate_mf_subagent_graph_query_identity(
                    conn,
                    project_id=project_id,
                    task_id=task_id,
                    parent_task_id=str(ctx.query.get("parent_task_id") or ""),
                    worker_role="mf_sub",
                    fence_token=fence_token,
                    governance_project_id=str(
                        ctx.query.get("governance_project_id")
                        or ctx.query.get("backlog_project_id")
                        or project_id
                    ),
                    target_project_id=str(
                        ctx.query.get("target_project_id")
                        or ctx.query.get("graph_project_id")
                        or project_id
                    ),
                    target_project_root=str(
                        ctx.query.get("target_project_root")
                        or ctx.query.get("target_graph_root")
                        or ""
                    ),
                    session_token=str(ctx.query.get("session_token") or ""),
                    session_token_ref=str(
                        ctx.query.get("session_token_ref")
                        or ctx.query.get("worker_session_token_ref")
                        or ""
                    ),
                )
            except BranchRuntimeFenceError as exc:
                raise GovernanceError(
                    "fence_invalidated_or_unknown",
                    "mf_subagent runtime contract fence is invalidated or unknown",
                    403,
                    {
                        "task_id": task_id,
                        "governance_project_id": str(
                            ctx.query.get("governance_project_id")
                            or ctx.query.get("backlog_project_id")
                            or project_id
                        ),
                        "target_project_id": str(
                            ctx.query.get("target_project_id")
                            or ctx.query.get("graph_project_id")
                            or project_id
                        ),
                        "reason": "fence_invalidated_or_unknown",
                    },
                ) from exc
        else:
            context = get_branch_context(conn, project_id, task_id)
            if context is None:
                raise GovernanceError(
                    "runtime_context_not_found",
                    f"branch runtime context not found: {project_id}/{task_id}",
                    404,
                    {"task_id": task_id},
                )

        return _parallel_branch_runtime_contract_response(
            ctx,
            conn,
            project_id=project_id,
            context=context,
            role=role,
            session=session,
        )
    finally:
        conn.close()


@route("GET", "/api/graph-governance/{project_id}/runtime-contexts/{runtime_context_id}/runtime-contract")
@route("GET", "/api/graph-governance/{project_id}/parallel-branches/runtime-contexts/{runtime_context_id}/runtime-contract")
def handle_graph_governance_parallel_branch_runtime_contract_by_context(ctx: RequestContext):
    """Return a worker contract view by runtime_context_id plus current fence."""
    project_id = ctx.get_project_id()

    runtime_context_id = str(
        ctx.path_params.get("runtime_context_id") or ctx.query.get("runtime_context_id") or ""
    ).strip()
    if not runtime_context_id:
        raise ValidationError("runtime_context_id is required")

    conn = get_connection(project_id)
    try:
        context, role, session = _runtime_context_mf_sub_read_context(
            ctx,
            conn,
            action="graph-governance.parallel-branches.runtime-contract",
            runtime_context_id=runtime_context_id,
        )

        return _parallel_branch_runtime_contract_response(
            ctx,
            conn,
            project_id=project_id,
            context=context,
            role=role,
            session=session,
        )
    finally:
        conn.close()


@route("GET", "/api/graph-governance/{project_id}/runtime-contexts/{runtime_context_id}/current-state")
@route("GET", "/api/graph-governance/{project_id}/parallel-branches/runtime-contexts/{runtime_context_id}/current-state")
def handle_graph_governance_parallel_branch_runtime_context_current_state(ctx: RequestContext):
    """Return Runtime Context Service current-state or role-filtered worker view."""
    project_id = ctx.get_project_id()

    runtime_context_id = str(
        ctx.path_params.get("runtime_context_id") or ctx.query.get("runtime_context_id") or ""
    ).strip()
    if not runtime_context_id:
        raise ValidationError("runtime_context_id is required")

    conn = get_connection(project_id)
    try:
        context, role, session = _runtime_context_mf_sub_read_context(
            ctx,
            conn,
            action="graph-governance.parallel-branches.runtime-context.current-state",
            runtime_context_id=runtime_context_id,
        )

        explicit_view = str(ctx.query.get("view") or "compact").strip().lower()
        if role == "mf_sub" and explicit_view in {
            "compact",
            "current",
            "worker_view",
            "gate_inputs",
        }:
            return _runtime_context_position_bounded_current_state_response(
                ctx,
                conn,
                project_id=project_id,
                context=context,
                role=role,
                session=session,
                requested_view=explicit_view,
            )

        response = _runtime_context_projection_response(
            ctx,
            conn,
            project_id=project_id,
            context=context,
            role=role,
            session=session,
        )
        requested_view = str(ctx.query.get("view") or "compact").strip().lower()
        if requested_view not in {"auto", "compact", "worker_view"}:
            return response
        return _runtime_context_server_bounded_current_state_response(
            response,
            requested_view=requested_view,
        )
    finally:
        conn.close()


@route("GET", "/api/graph-governance/{project_id}/runtime-contexts/{runtime_context_id}/worker-guide")
@route("GET", "/api/graph-governance/{project_id}/parallel-branches/runtime-contexts/{runtime_context_id}/worker-guide")
def handle_graph_governance_parallel_branch_runtime_context_worker_guide(ctx: RequestContext):
    """Return public-safe instructions for a worker to consume runtime context."""
    query = dict(ctx.query or {})
    requested_view = str(query.get("view") or "compact").strip().lower()
    allowed_views = {
        "auto",
        "compact",
        "current",
        "gate_inputs",
        "worker_view",
        "close_gate_view",
        "all",
        "full",
    }
    if requested_view not in allowed_views:
        raise ValidationError(
            "view must be a declared Worker Guide response view"
        )
    compact = requested_view not in {"all", "full"}
    if compact:
        query["view"] = "compact"
        compact_ctx = RequestContext(
            ctx.handler,
            ctx.method,
            dict(ctx.path_params or {}),
            query,
            dict(ctx.body or {}),
            ctx.request_id,
            ctx.token,
            ctx.idem_key,
        )
        compact_ctx._session = ctx._session
        project_id = ctx.get_project_id()
        runtime_context_id = str(
            ctx.path_params.get("runtime_context_id")
            or ctx.query.get("runtime_context_id")
            or ""
        ).strip()
        if not runtime_context_id:
            raise ValidationError("runtime_context_id is required")
        conn = get_connection(project_id)
        try:
            context, role, _session = _runtime_context_mf_sub_read_context(
                compact_ctx,
                conn,
                action=(
                    "graph-governance.parallel-branches."
                    "runtime-context.worker-guide"
                ),
                runtime_context_id=runtime_context_id,
                bounded_worker_guide=True,
            )
            response = _runtime_context_worker_guide_early_compact_response(
                compact_ctx,
                conn,
                project_id=project_id,
                context=context,
                role=role,
            )
            detail_cursor = str(query.get("detail_cursor") or "").strip()
            if detail_cursor:
                return _runtime_context_worker_guide_detail_page(
                    response,
                    detail_ref=str(query.get("detail_ref") or ""),
                    detail_cursor=detail_cursor,
                )
            return _runtime_context_server_bounded_worker_guide_response(
                response,
                requested_view="compact",
            )
        finally:
            conn.close()
    query["view"] = (
        "all"
        if requested_view in {"all", "full"}
        else requested_view
    )
    state_ctx = RequestContext(
        ctx.handler,
        ctx.method,
        dict(ctx.path_params or {}),
        query,
        dict(ctx.body or {}),
        ctx.request_id,
        ctx.token,
        ctx.idem_key,
    )
    state_ctx._session = ctx._session
    current_state = handle_graph_governance_parallel_branch_runtime_context_current_state(
        state_ctx
    )
    if current_state.get("ok") is False and current_state.get("error"):
        return current_state
    response = _runtime_context_worker_guide_response(current_state)
    response["response_view"] = "all"
    return response


def _runtime_context_modern_special_rejoin_authority_valid(
    *,
    project_id: str,
    context: Any,
    event: Mapping[str, Any],
    timeline_events: Sequence[Mapping[str, Any]],
    contract_execution_id: str,
    route_identity: Mapping[str, Any],
) -> bool:
    """Validate one modern canonical pre-lineage special rejoin audit."""

    payload = (
        event.get("payload")
        if isinstance(event.get("payload"), Mapping)
        else {}
    )
    authority = (
        payload.get("pre_lineage_rejoin_authority")
        if isinstance(payload.get("pre_lineage_rejoin_authority"), Mapping)
        else {}
    )
    baseline = (
        payload.get("bounded_replacement_worker_write_baseline")
        if isinstance(
            payload.get("bounded_replacement_worker_write_baseline"),
            Mapping,
        )
        else {}
    )
    checkpoint = _runtime_context_rejoin_stage_checkpoint(baseline)
    bounded_replacement_authority = (
        payload.get("bounded_replacement_rejoin_authority")
        if isinstance(
            payload.get("bounded_replacement_rejoin_authority"),
            Mapping,
        )
        else {}
    )
    bounded_replacement_not_applicable = bool(
        checkpoint
        and str(
            bounded_replacement_authority.get("schema_version") or ""
        ).strip()
        == "runtime_context.bounded_replacement_rejoin_authority.v2"
        and bounded_replacement_authority.get("server_derived") is True
        and bounded_replacement_authority.get("caller_claims_trusted") is False
        and bounded_replacement_authority.get("applicable") is False
        and bounded_replacement_authority.get("eligible") is False
        and str(bounded_replacement_authority.get("mode") or "").strip()
        == "not_applicable"
        and int(
            bounded_replacement_authority.get("replacement_generation") or 0
        )
        == 0
        and str(
            bounded_replacement_authority.get("last_recovery_action") or ""
        ).strip()
        == "mf_subagent_initial_join_issued"
        and dict(
            bounded_replacement_authority.get("current_worker_write_baseline")
            or {}
        )
        == dict(baseline)
        and dict(
            bounded_replacement_authority.get("current_stage_checkpoint")
            or {}
        )
        == dict(checkpoint)
        and str(
            bounded_replacement_authority.get("current_stage_checkpoint_id")
            or ""
        ).strip()
        == str(checkpoint.get("stage_checkpoint_id") or "").strip()
        and not bounded_replacement_authority.get("errors")
        and not bounded_replacement_authority.get("identity_mismatches")
        and not bounded_replacement_authority.get(
            "current_checkpoint_issuance_event_refs"
        )
        and not bounded_replacement_authority.get(
            "current_checkpoint_replacement_event_refs"
        )
    )
    runtime_context_id = str(
        getattr(context, "runtime_context_id", "") or ""
    ).strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    worker_id = str(getattr(context, "worker_id", "") or "").strip()
    worker_slot_id = str(
        getattr(context, "worker_slot_id", "") or worker_id
    ).strip()
    actual_host_worker_id = str(
        getattr(context, "actual_host_worker_id", "") or ""
    ).strip()
    target_project_root = _runtime_context_effective_target_project_root(
        context
    )
    identity = {
        "project_id": project_id,
        "backlog_id": backlog_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "contract_execution_id": contract_execution_id,
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "actual_host_worker_id": actual_host_worker_id,
        "target_project_root": target_project_root,
    }
    canonical_route = {
        field: str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    event_route = (
        payload.get("route_identity")
        if isinstance(payload.get("route_identity"), Mapping)
        else {}
    )
    authority_route = (
        authority.get("route_identity")
        if isinstance(authority.get("route_identity"), Mapping)
        else {}
    )
    source_ref = str(authority.get("initial_join_event_ref") or "").strip()
    source_match = re.fullmatch(r"timeline:([1-9][0-9]*)", source_ref)
    source_id = int(source_match.group(1)) if source_match else 0
    special_id = int(event.get("id") or 0)
    initial_join_events = []
    if source_id and special_id and source_id < special_id:
        initial_join_events = [
            item
            for item in timeline_events
            if int(item.get("id") or 0) == source_id
            and str(item.get("event_type") or "").strip()
            == "observer.runtime_context_session_token_initial_join"
            and str(item.get("event_kind") or "").strip()
            == "observer_command"
            and str(item.get("phase") or "").strip()
            == "runtime_context_initial_join"
            and str(item.get("status") or "").strip().lower()
            == "accepted"
            and str(item.get("task_id") or "").strip() == task_id
            and str(item.get("backlog_id") or "").strip() == backlog_id
        ]
    initial_join_payload = (
        initial_join_events[0].get("payload")
        if len(initial_join_events) == 1
        and isinstance(initial_join_events[0].get("payload"), Mapping)
        else {}
    )
    return bool(
        checkpoint
        and str(event.get("event_type") or "").strip()
        == "observer.runtime_context_session_token_rejoin"
        and str(event.get("event_kind") or "").strip()
        == "observer_command"
        and str(event.get("phase") or "").strip()
        == "runtime_context_recovery"
        and str(event.get("status") or "").strip().lower() == "accepted"
        and str(event.get("task_id") or "").strip() == task_id
        and str(event.get("backlog_id") or "").strip() == backlog_id
        and payload.get("schema_version")
        == "mf_subagent_session_token_rejoin_response.v1"
        and str(payload.get("action") or "").strip()
        == "runtime_context_session_token_rejoin"
        and payload.get("bounded_rejoin_kind")
        == "special_authority_rejoin"
        and payload.get("pre_lineage_auth_only_rejoin") is True
        and payload.get("bounded_replacement_rejoin") is False
        and payload.get("bounded_replacement_generation") == 0
        and bounded_replacement_not_applicable
        and str(payload.get("rejoin_stage_checkpoint_id") or "").strip()
        == str(checkpoint.get("stage_checkpoint_id") or "").strip()
        and payload.get("host_envelope_returned") is True
        and payload.get("raw_session_token_persisted") is False
        and payload.get("raw_fence_token_persisted_to_timeline") is False
        and all(
            str(payload.get(field) or "").strip() == expected
            for field, expected in identity.items()
            if field
            in {
                "project_id",
                "backlog_id",
                "runtime_context_id",
                "task_id",
                "parent_task_id",
                "worker_id",
                "worker_slot_id",
            }
        )
        and all(
            str(authority.get(field) or "").strip() == expected
            for field, expected in identity.items()
        )
        and all(
            value
            and str(event_route.get(field) or "").strip() == value
            and str(authority_route.get(field) or "").strip() == value
            for field, value in canonical_route.items()
        )
        and authority.get("schema_version")
        == "runtime_context.pre_lineage_rejoin_authority.v1"
        and authority.get("server_derived") is True
        and authority.get("eligible") is True
        and authority.get("status") == "eligible"
        and authority.get("authorization_mode")
        == "exactly_one_accepted_initial_join_audit"
        and authority.get("auth_only") is True
        and authority.get("one_shot") is True
        and authority.get("evidence_synthesized") is False
        and authority.get("attempt_transition_applied") is False
        and authority.get("retry_round_transition_applied") is False
        and authority.get("status_transition_applied") is False
        and authority.get("audit_cardinality") == 1
        and authority.get("audit_valid") is True
        and authority.get("identity_contract_version")
        == "runtime_context.initial_join_identity.v2"
        and authority.get("canonical_identity_binding_required") is True
        and authority.get("canonical_identity_binding_valid") is True
        and authority.get("canonical_identity_cutover_valid") is True
        and authority.get("errors") == []
        and authority.get("fail_closed") is False
        and len(initial_join_events) == 1
        and str(initial_join_payload.get("runtime_context_id") or "").strip()
        == runtime_context_id
        and str(initial_join_payload.get("action") or "").strip()
        == "runtime_context_session_token_initial_join"
        and str(initial_join_payload.get("task_id") or "").strip()
        == task_id
        and str(initial_join_payload.get("parent_task_id") or "").strip()
        == parent_task_id
        and str(initial_join_payload.get("worker_id") or "").strip()
        == worker_id
        and str(initial_join_payload.get("worker_slot_id") or "").strip()
        == worker_slot_id
        and str(initial_join_payload.get("actual_host_worker_id") or "").strip()
        == actual_host_worker_id
        and str(initial_join_payload.get("session_token_ref") or "").strip()
        == str(authority.get("session_token_ref") or "").strip()
        and str(initial_join_payload.get("worker_session_id") or "").strip()
        == str(authority.get("worker_session_id") or "").strip()
        and initial_join_payload.get("host_envelope_returned") is True
        and initial_join_payload.get("raw_session_token_persisted") is False
        and initial_join_payload.get(
            "raw_fence_token_persisted_to_timeline"
        )
        is False
        and all(
            str(
                (
                    initial_join_payload.get("route_identity")
                    if isinstance(
                        initial_join_payload.get("route_identity"),
                        Mapping,
                    )
                    else {}
                ).get(field)
                or ""
            ).strip()
            == value
            for field, value in canonical_route.items()
        )
    )


_RUNTIME_CONTEXT_LEGACY_R2_MANAGED_CAPTURE_LOSS_RESCUE = {
    "schema_version": (
        "runtime_context.legacy_r2_managed_capture_loss_rescue_binding.v1"
    ),
    "project_id": "daily-planner-lite-20260816180518-8858affd",
    "backlog_id": "AC-DEMO-R4-BATCH-FOCUS-8858AFFD",
    "contract_execution_id": "cex-mf-parallel-d0f91cf2825d5de2f00a",
    "runtime_context_id": "mfrctx-74b9d971e1f08de3",
    "task_id": "r4-batch-focus-failed-qa-rework-2-8858affd",
    "parent_task_id": "cex-mf-parallel-d0f91cf2825d5de2f00a",
    "worker_id": "r4-batch-focus-failed-qa-rework-2-mf-sub-8858affd",
    "worker_slot_id": "r4-batch-focus-failed-qa-rework-2-mf-sub-8858affd",
    "source_event_ref": "timeline:49",
    "prior_reissue_event_ref": "timeline:48",
    "initial_join_event_ref": "timeline:45",
    "source_created_at": "2026-08-17T09:22:04Z",
    "r2_adapter_schema_version": "mcp.managed_host_envelope.v1",
    "r2_governance_commit": "2290553890dc4142f25723990e5b51b2e48bb06a",
}


def _runtime_context_exact_legacy_r2_capture_loss_rescue(
    *,
    project_id: str,
    context: Any,
    contract_execution_id: str,
    prior_event: Mapping[str, Any],
    stage_reissue_events: Sequence[Mapping[str, Any]],
    prior_loss_authority: Mapping[str, Any],
    stage_checkpoint_id: str,
    route_identity_hash: str,
) -> dict[str, Any]:
    """Authorize only the audited R2 capture-loss world exhausted at event 49.

    This is a one-time migration seam, not a third generic replacement.  The
    exact incident binding is source-owned and all mutable/current authority
    (safe ref, lease, route, receipt/startup state) is still checked by the
    ordinary safe-ref gate around this predicate.
    """

    binding = dict(_RUNTIME_CONTEXT_LEGACY_R2_MANAGED_CAPTURE_LOSS_RESCUE)
    payload = (
        prior_event.get("payload")
        if isinstance(prior_event.get("payload"), Mapping)
        else {}
    )
    event_ref = f"timeline:{prior_event.get('id', '')}"
    stage_refs = [f"timeline:{event.get('id', '')}" for event in stage_reissue_events]
    expected_identity = {
        "project_id": project_id,
        "backlog_id": str(context.backlog_id or "").strip(),
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "runtime_context_id": str(context.runtime_context_id or "").strip(),
        "task_id": str(context.task_id or "").strip(),
        "parent_task_id": _runtime_context_mf_sub_parent_task_id(context),
        "worker_id": str(context.worker_id or "").strip(),
        "worker_slot_id": str(
            context.worker_slot_id or context.worker_id or ""
        ).strip(),
    }
    if (
        len(stage_reissue_events) != 3
        or event_ref != str(binding.get("source_event_ref") or "").strip()
        or stage_refs[-2:] != [
            str(binding.get("prior_reissue_event_ref") or "").strip(),
            str(binding.get("source_event_ref") or "").strip(),
        ]
        or str(prior_event.get("created_at") or "").strip()
        != str(binding.get("source_created_at") or "").strip()
        or any(
            expected_identity[field]
            != str(binding.get(field) or "").strip()
            for field in expected_identity
        )
        or str(prior_loss_authority.get("schema_version") or "").strip()
        != "runtime_context.safe_ref_loss_replacement_authority.v1"
        or prior_loss_authority.get("server_derived") is not True
        or prior_loss_authority.get("caller_claims_trusted") is not False
        or int(prior_loss_authority.get("prior_stage_reissue_count") or 0) != 2
        or int(prior_loss_authority.get("loss_replacement_generation") or 0) != 2
        or int(prior_loss_authority.get("max_loss_replacements") or 0) != 2
        or prior_loss_authority.get("managed_host_continuity_loss_replacement")
        is not True
        or str(prior_loss_authority.get("prior_reissue_event_ref") or "").strip()
        != str(binding.get("prior_reissue_event_ref") or "").strip()
        or str(prior_loss_authority.get("stage_checkpoint_id") or "").strip()
        != stage_checkpoint_id
        or str(prior_loss_authority.get("route_identity_hash") or "").strip()
        != route_identity_hash
        or prior_loss_authority.get("worker_receipt_consumed") is not False
        or prior_loss_authority.get("worker_startup_consumed") is not False
        or prior_loss_authority.get("raw_credentials_persisted") is not False
        or str(prior_loss_authority.get("authority_hash") or "").strip()
        != _stable_public_hash(
            {
                key: value
                for key, value in prior_loss_authority.items()
                if key != "authority_hash"
            }
        )
        or str(
            (
                payload.get("safe_ref_reissue_authority")
                if isinstance(payload.get("safe_ref_reissue_authority"), Mapping)
                else {}
            ).get("initial_join_event_ref")
            or ""
        ).strip()
        != str(binding.get("initial_join_event_ref") or "").strip()
    ):
        return {}
    rescue = {
        "schema_version": (
            "runtime_context.legacy_r2_managed_capture_loss_rescue.v1"
        ),
        "server_derived": True,
        "caller_claims_trusted": False,
        "source_event_ref": event_ref,
        "prior_reissue_event_ref": str(
            binding.get("prior_reissue_event_ref") or ""
        ).strip(),
        "r2_adapter_schema_version": str(
            binding.get("r2_adapter_schema_version") or ""
        ).strip(),
        "r2_governance_commit": str(
            binding.get("r2_governance_commit") or ""
        ).strip(),
        "legacy_rescue_generation": 1,
        "max_legacy_rescues": 1,
        "general_loss_replacement_limit_raised": False,
        "worker_receipt_consumed": False,
        "worker_startup_consumed": False,
        "raw_credentials_persisted": False,
    }
    rescue["authority_hash"] = _stable_public_hash(rescue)
    return rescue


def _runtime_context_safe_ref_prestartup_reissue_authority(
    ctx: RequestContext,
    conn,
    *,
    project_id: str,
    runtime_context_id: str,
    body: Mapping[str, Any],
    now_iso: str,
):
    """Resolve one exact source-backed pre-startup safe-ref authority."""

    from .parallel_branch_runtime import (
        BranchRuntimeFenceError,
        build_safe_ref_prestartup_reissue_authority,
        get_branch_context_by_runtime_context_id,
        runtime_context_id_for_branch_context,
        runtime_context_session_token_lease_view,
        runtime_context_session_token_ref,
    )

    context = get_branch_context_by_runtime_context_id(
        conn,
        project_id,
        runtime_context_id,
    )
    if context is None:
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    expected_runtime_id = runtime_context_id_for_branch_context(context)
    expected_task_id = str(context.task_id or "").strip()
    expected_parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    expected_target_root = _runtime_context_effective_target_project_root(context)
    expected_worker_id = str(context.worker_id or "").strip()
    expected_worker_slot_id = str(
        context.worker_slot_id or expected_worker_id
    ).strip()
    expected_agent_id = str(
        context.worker_id or context.worker_slot_id or context.agent_id
    ).strip()
    expected_allocation_owner = str(
        context.allocation_owner
        or context.worker_id
        or context.worker_slot_id
        or context.agent_id
        or ""
    ).strip()
    expected_actual_host_worker_id = str(
        context.actual_host_worker_id or ""
    ).strip()
    expected_host_session_id = str(context.host_session_id or "").strip()
    expected_host_startup_id = str(context.host_startup_id or "").strip()
    requested_contract_execution_id = str(
        body.get("contract_execution_id") or ""
    ).strip()
    presented_session_ref = str(body.get("session_token_ref") or "").strip()
    exact_fields = {
        "runtime_context_id": (
            str(body.get("runtime_context_id") or expected_runtime_id).strip(),
            expected_runtime_id,
        ),
        "task_id": (str(body.get("task_id") or "").strip(), expected_task_id),
        "parent_task_id": (
            str(body.get("parent_task_id") or "").strip(),
            expected_parent_task_id,
        ),
        "target_project_root": (
            str(
                body.get("target_project_root")
                or body.get("project_root")
                or body.get("repo_root")
                or ""
            ).strip(),
            expected_target_root,
        ),
        "worker_id": (
            str(body.get("worker_id") or "").strip(),
            expected_worker_id,
        ),
        "worker_slot_id": (
            str(body.get("worker_slot_id") or "").strip(),
            expected_worker_slot_id,
        ),
        "agent_id": (
            str(body.get("agent_id") or "").strip(),
            expected_agent_id,
        ),
        "allocation_owner": (
            str(body.get("allocation_owner") or "").strip(),
            expected_allocation_owner,
        ),
        "actual_host_worker_id": (
            str(
                body.get("actual_host_worker_id")
                or body.get("host_worker_id")
                or ""
            ).strip(),
            expected_actual_host_worker_id,
        ),
        "session_token_ref": (
            presented_session_ref,
            runtime_context_session_token_ref(context),
        ),
    }
    # The public guide intentionally leaves opaque host adapter identities
    # empty when a historical context predates their projection.  They are not
    # caller-selected authority on the safe-ref path: the server binds the
    # durable context values into the proof passed to the runtime primitive.
    # A non-empty caller claim must still match exactly.
    for field, expected in (
        ("host_session_id", expected_host_session_id),
        ("host_startup_id", expected_host_startup_id),
    ):
        supplied = str(body.get(field) or "").strip()
        if supplied and supplied != expected:
            raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    if (
        any(not actual or actual != expected for actual, expected in exact_fields.values())
    ):
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")

    latest_revision = _runtime_context_latest_contract_revision_payload(
        conn,
        context,
    )
    revision_identity = _runtime_context_contract_execution_identity(
        latest_revision
    )
    resolved_identity, resolution = _runtime_context_resolve_contract_execution_identity(
        conn,
        project_id=project_id,
        context=context,
        runtime_context_id=expected_runtime_id,
        task_id=expected_task_id,
        contract_identity=revision_identity,
    )
    if (
        resolution.get("fail_closed")
        or not str(
            resolved_identity.get("contract_execution_id") or ""
        ).strip()
        or (
            requested_contract_execution_id
            and str(
                resolved_identity.get("contract_execution_id") or ""
            ).strip()
            != requested_contract_execution_id
        )
    ):
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    presented_contract_execution_id = str(
        resolved_identity.get("contract_execution_id") or ""
    ).strip()
    try:
        record = _contract_runtime_store(conn).get(presented_contract_execution_id)
    except (ContractRuntimeError, sqlite3.Error) as exc:
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown") from exc
    if (
        str(record.get("project_id") or "").strip() != project_id
        or str(record.get("backlog_id") or "").strip()
        != str(context.backlog_id or "").strip()
        or str(record.get("contract_execution_id") or "").strip()
        != presented_contract_execution_id
    ):
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    source_record = record
    projected_record, context_projection = (
        _contract_runtime_apply_mf_parallel_context_projection(
            conn,
            project_id=project_id,
            record=source_record,
            actor_role="mf_sub",
        )
    )
    projected_guide = (
        projected_record.get("runtime_guide")
        if isinstance(projected_record.get("runtime_guide"), Mapping)
        else {}
    )
    projected_next_action = _runtime_next_action_from_guide(
        projected_guide,
        source="contract_runtime_current_state",
    )
    next_action = _runtime_context_failed_qa_context_local_setup_next_action(
        projected_next_action,
        record=projected_record,
        projection=context_projection,
        context=context,
    )
    sequence = _runtime_context_prestartup_worker_sequence_evidence(
        conn,
        project_id=project_id,
        context=context,
        route_identity=_runtime_context_latest_route_identity(conn, context),
    )
    next_line_id = str(next_action.get("line_id") or "").strip()
    read_receipt_ref = str(sequence.get("read_receipt_ref") or "").strip()
    authority_read_receipt_ref = str(
        sequence.get("contract_runtime_prior_read_receipt_ref")
        or read_receipt_ref
        or ""
    ).strip()
    startup_ref = str(sequence.get("startup_ref") or "").strip()
    dispatch_match = _contract_runtime_dispatch_line_match(record, context)
    verified_dispatch = _contract_runtime_verified_dispatch_lineage(
        record,
        context,
        dispatch_match,
    )
    next_runtime_context_id = str(
        next_action.get("runtime_context_id") or ""
    ).strip()
    next_task_id = str(next_action.get("task_id") or "").strip()
    pre_read_special_stage = bool(
        not read_receipt_ref
        and not startup_ref
        and next_line_id == "worker_read_runtime_guide"
        and verified_dispatch
        and next_runtime_context_id in {"", expected_runtime_id}
        and next_task_id in {"", expected_task_id}
    )
    pinned_replacement_initial_join_ref = str(
        next_action.get("initial_join_event_ref") or ""
    ).strip()
    pre_read_pinned_replacement_stage = bool(
        pre_read_special_stage
        and next_action.get(
            "failed_qa_replacement_context_local_setup_projection"
        )
        is True
        and str(next_action.get("source") or "").strip()
        == "contract_runtime_failed_qa_context_local_setup_projection"
        and str(next_action.get("source_of_authority") or "").strip()
        == "server_verified_failed_qa_replacement_dispatch"
        and str(next_action.get("authority_decision_source") or "").strip()
        == "server_verified_failed_qa_replacement_dispatch"
        and str(next_action.get("precedence") or "").strip()
        == "server_verified_failed_qa_replacement_context_local_setup"
        and str(next_action.get("contract_execution_id") or "").strip()
        == presented_contract_execution_id
        and str(next_action.get("parent_task_id") or "").strip()
        == expected_parent_task_id
        and str(next_action.get("worker_id") or "").strip()
        == expected_worker_id
        and str(next_action.get("worker_slot_id") or "").strip()
        == expected_worker_slot_id
        and str(next_action.get("line_instance_id") or "").strip()
        == f"runtime_context:{expected_runtime_id}"
        and str(next_action.get("dispatch_source_ref") or "").strip()
        == str(dispatch_match.get("source_ref") or "").strip()
        and re.fullmatch(
            r"timeline:[1-9][0-9]*",
            pinned_replacement_initial_join_ref,
        )
        is not None
    )
    post_read_prestartup_stage = bool(
        str(sequence.get("contract_execution_id") or "").strip()
        == presented_contract_execution_id
        and read_receipt_ref
        and not startup_ref
        and next_line_id == "worker_startup"
    )
    if not (pre_read_special_stage or post_read_prestartup_stage):
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    context_local_post_read_authority = {}
    if str(sequence.get("source") or "") == (
        "task_timeline_context_local_receipt"
    ):
        context_local_post_read_authority = (
            _runtime_context_context_local_post_read_startup_receipt_authority(
                conn,
                project_id=project_id,
                context=context,
                route_identity=_runtime_context_latest_route_identity(
                    conn,
                    context,
                ),
                sequence=sequence,
            )
        )
        if not context_local_post_read_authority:
            raise BranchRuntimeFenceError("fence_invalidated_or_unknown")

    timeline_events = _runtime_context_service_timeline_events(
        conn,
        project_id=project_id,
        task_id=expected_task_id,
        backlog_id=str(context.backlog_id or "").strip(),
    )
    checkpoint_baseline = _runtime_context_rejoin_worker_write_baseline(
        conn,
        project_id=project_id,
        context=context,
        timeline_events=timeline_events,
    )
    stage_checkpoint = _runtime_context_rejoin_stage_checkpoint(
        checkpoint_baseline
    )
    if not stage_checkpoint:
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    stage_checkpoint_id = str(
        stage_checkpoint.get("stage_checkpoint_id") or ""
    ).strip()
    matching_initial_joins = []
    matching_session_authorities: list[
        tuple[Mapping[str, Any], str, str]
    ] = []
    validated_session_authorities: dict[
        str, list[tuple[Mapping[str, Any], str, str]]
    ] = {}
    stage_reissue_events: list[Mapping[str, Any]] = []
    matching_stage_reissue_events: list[Mapping[str, Any]] = []
    for event in timeline_events:
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        common_identity_matches = (
            str(event.get("status") or "").strip().lower()
            in {"accepted", "ok", "pass", "passed", "success", "succeeded"}
            and str(payload.get("runtime_context_id") or "").strip()
            == expected_runtime_id
            and str(
                payload.get("task_id") or event.get("task_id") or ""
            ).strip()
            == expected_task_id
        )
        if not common_identity_matches:
            continue
        event_execution_id = str(payload.get("contract_execution_id") or "").strip()
        if event_execution_id and event_execution_id != presented_contract_execution_id:
            continue
        action = str(payload.get("action") or "").strip()
        event_session_ref = str(payload.get("session_token_ref") or "").strip()
        if action == "runtime_context_session_token_reissue":
            prior_authority = payload.get("safe_ref_reissue_authority")
            if (
                isinstance(prior_authority, Mapping)
                and str(prior_authority.get("stage_checkpoint_id") or "").strip()
                == stage_checkpoint_id
            ):
                stage_reissue_events.append(event)
                if event_session_ref == presented_session_ref:
                    matching_stage_reissue_events.append(event)
            continue
        if (
            action == "runtime_context_session_token_initial_join"
            and str(payload.get("actual_host_worker_id") or "").strip()
            == expected_actual_host_worker_id
            and str(
                payload.get("host_session_id")
                or payload.get("worker_session_id")
                or ""
            ).strip()
            == expected_host_session_id
            and bool(str(payload.get("worker_session_id") or "").strip())
        ):
            matching_initial_joins.append(event)
            validated_session_authorities.setdefault(
                f"timeline:{event.get('id', '')}", []
            ).append((event, "initial_join", "initial_join"))
            if event_session_ref == presented_session_ref:
                matching_session_authorities.append(
                    (event, "initial_join", "initial_join")
                )
        elif (
            action == "runtime_context_session_token_rejoin"
            and str(payload.get("bounded_rejoin_kind") or "").strip()
            in {
                "special_authority_rejoin",
                "ordinary_initial_rejoin",
                "bounded_replacement_rejoin",
            }
            and (
                str(payload.get("bounded_rejoin_kind") or "").strip()
                != "bounded_replacement_rejoin"
                or payload.get("bounded_replacement_rejoin") is True
            )
            and (
                str(payload.get("bounded_rejoin_kind") or "").strip()
                != "special_authority_rejoin"
                or payload.get("pre_lineage_auth_only_rejoin") is True
            )
            and str(payload.get("worker_id") or "").strip()
            == expected_worker_id
            and str(
                payload.get("worker_slot_id") or expected_worker_slot_id
            ).strip()
            == expected_worker_slot_id
            and str(
                payload.get("actual_host_worker_id")
                or expected_actual_host_worker_id
            ).strip()
            == expected_actual_host_worker_id
            and str(
                payload.get("host_session_id")
                or payload.get("worker_session_id")
                or expected_host_session_id
            ).strip()
            == expected_host_session_id
        ):
            authority_kind = str(
                payload.get("bounded_rejoin_kind") or ""
            ).strip()
            legacy_audit = _runtime_context_legacy_v1_rejoin_audit(
                conn,
                project_id=project_id,
                context=context,
                event=event,
                current_baseline=checkpoint_baseline,
            )
            relation = str(legacy_audit.get("relation") or "").strip()
            modern_special_authority = bool(
                authority_kind == "special_authority_rejoin"
                and legacy_audit.get("applicable") is not True
                and _runtime_context_modern_special_rejoin_authority_valid(
                    project_id=project_id,
                    context=context,
                    event=event,
                    timeline_events=timeline_events,
                    contract_execution_id=presented_contract_execution_id,
                    route_identity=_runtime_context_latest_route_identity(
                        conn,
                        context,
                    ),
                )
            )
            if modern_special_authority:
                relation = _runtime_context_rejoin_checkpoint_relation(
                    payload.get("bounded_replacement_worker_write_baseline"),
                    checkpoint_baseline,
                )
            if (
                authority_kind != "special_authority_rejoin"
                and legacy_audit.get("applicable") is not True
            ):
                relation = _runtime_context_rejoin_checkpoint_relation(
                    payload.get("bounded_replacement_worker_write_baseline"),
                    checkpoint_baseline,
                )
            legacy_audit_accepted = bool(
                (
                    authority_kind == "special_authority_rejoin"
                    and (
                        modern_special_authority
                        or (
                            legacy_audit.get("applicable") is True
                            and legacy_audit.get("valid") is True
                        )
                    )
                )
                or (
                    authority_kind != "special_authority_rejoin"
                    and (
                        legacy_audit.get("applicable") is not True
                        or legacy_audit.get("valid") is True
                    )
                )
            )
            if legacy_audit_accepted and relation in {
                "exact",
                "advanced",
            }:
                normalized_authority_kind = (
                    "ordinary_initial_rejoin"
                    if authority_kind == "special_authority_rejoin"
                    else authority_kind
                )
                validated_session_authorities.setdefault(
                    f"timeline:{event.get('id', '')}", []
                ).append(
                    (
                        event,
                        normalized_authority_kind,
                        authority_kind,
                    )
                )
                if event_session_ref == presented_session_ref:
                    matching_session_authorities.append(
                        (
                            event,
                            normalized_authority_kind,
                            authority_kind,
                        )
                    )
    prior_safe_ref_reissue_event: Mapping[str, Any] | None = None
    if (
        not matching_session_authorities
        and len(stage_reissue_events) in {1, 2, 3}
        and len(matching_stage_reissue_events) == 1
    ):
        candidate_event = matching_stage_reissue_events[0]
        candidate_payload = (
            candidate_event.get("payload")
            if isinstance(candidate_event.get("payload"), Mapping)
            else {}
        )
        candidate_authority = candidate_payload.get(
            "safe_ref_reissue_authority"
        )
        source_ref = str(
            (candidate_authority or {}).get("session_authority_event_ref")
            if isinstance(candidate_authority, Mapping)
            else ""
        ).strip()
        source_kind = str(
            (candidate_authority or {}).get("session_authority_kind")
            if isinstance(candidate_authority, Mapping)
            else ""
        ).strip()
        source_matches = [
            item
            for item in validated_session_authorities.get(source_ref, [])
            if item[1] == source_kind
        ]
        latest_stage_event_id = max(
            int(item.get("id") or 0) for item in stage_reissue_events
        )
        if (
            len(source_matches) == 1
            and int(candidate_event.get("id") or 0) == latest_stage_event_id
        ):
            prior_safe_ref_reissue_event = candidate_event
            matching_session_authorities = source_matches
    selected_initial_join: Mapping[str, Any]
    if pre_read_pinned_replacement_stage:
        pinned_initial_joins = [
            event
            for event in matching_initial_joins
            if f"timeline:{event.get('id', '')}"
            == pinned_replacement_initial_join_ref
        ]
        if len(pinned_initial_joins) != 1:
            raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
        selected_initial_join = pinned_initial_joins[0]
    elif context_local_post_read_authority:
        context_local_initial_join_ref = str(
            context_local_post_read_authority.get("initial_join_event_ref")
            or ""
        ).strip()
        context_local_initial_joins = [
            event
            for event in matching_initial_joins
            if f"timeline:{event.get('id', '')}"
            == context_local_initial_join_ref
        ]
        if len(context_local_initial_joins) != 1:
            raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
        selected_initial_join = context_local_initial_joins[0]
    else:
        if len(matching_initial_joins) != 1:
            raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
        selected_initial_join = matching_initial_joins[0]
    selected_initial_join_payload = (
        selected_initial_join.get("payload")
        if isinstance(selected_initial_join.get("payload"), Mapping)
        else {}
    )
    expected_worker_session_id = str(
        selected_initial_join_payload.get("worker_session_id") or ""
    ).strip()
    supplied_worker_session_id = str(
        body.get("worker_session_id") or ""
    ).strip()
    if (
        not expected_worker_session_id
        or (
            supplied_worker_session_id
            and supplied_worker_session_id != expected_worker_session_id
        )
    ):
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    if len(matching_session_authorities) != 1:
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    (
        session_authority_event,
        session_authority_kind,
        session_authority_source_kind,
    ) = matching_session_authorities[0]
    if (
        pre_read_special_stage
        and not pre_read_pinned_replacement_stage
        and session_authority_source_kind != "special_authority_rejoin"
    ) or (
        pre_read_pinned_replacement_stage
        and (
            session_authority_source_kind != "initial_join"
            or session_authority_kind != "initial_join"
            or f"timeline:{session_authority_event.get('id', '')}"
            != pinned_replacement_initial_join_ref
        )
    ):
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")

    supplied_route_identity = _runtime_context_request_route_identity_shapes(ctx)[
        "supplied"
    ]
    route_token_ref = str(supplied_route_identity.get("route_token_ref") or "").strip()
    from . import observer_route_context

    resolved_route_candidates: list[Mapping[str, Any]] = []
    for route_task_id in dict.fromkeys(
        (presented_contract_execution_id, expected_task_id)
    ):
        try:
            candidate = observer_route_context.resolve_route_token_ref(
                conn,
                project_id=project_id,
                storage_project_id=_route_registry_storage_project_id(project_id),
                route_token_ref=route_token_ref,
                backlog_id=str(context.backlog_id or "").strip(),
                task_id=route_task_id,
            )
        except observer_route_context.RouteTokenRefError:
            continue
        if candidate and not any(
            dict(candidate) == dict(item)
            for item in resolved_route_candidates
        ):
            resolved_route_candidates.append(candidate)
    if len(resolved_route_candidates) != 1:
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    resolved_route_ref = resolved_route_candidates[0]
    expected_route_identity = {
        field: str((resolved_route_ref or {}).get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        if str((resolved_route_ref or {}).get(field) or "").strip()
    }
    revision_route_identity = _runtime_context_latest_route_identity(conn, context)
    if (
        not expected_route_identity
        or str((resolved_route_ref or {}).get("status") or "").strip() != "active"
        or (
            revision_route_identity
            and any(
                str(revision_route_identity.get(field) or "").strip()
                != str(expected_route_identity.get(field) or "").strip()
                for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
                if str(revision_route_identity.get(field) or "").strip()
            )
        )
        or any(
            not str(supplied_route_identity.get(field) or "").strip()
            or str(supplied_route_identity.get(field) or "").strip()
            != str(expected_route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
            if str(expected_route_identity.get(field) or "").strip()
        )
    ):
        raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
    route_identity_hash = _stable_public_hash(
        {
            field: str(expected_route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        }
    )
    safe_ref_loss_replacement_authority: dict[str, Any] = {}
    if prior_safe_ref_reissue_event is not None:
        prior_payload = (
            prior_safe_ref_reissue_event.get("payload")
            if isinstance(prior_safe_ref_reissue_event.get("payload"), Mapping)
            else {}
        )
        prior_authority = (
            prior_payload.get("safe_ref_reissue_authority")
            if isinstance(prior_payload.get("safe_ref_reissue_authority"), Mapping)
            else {}
        )
        prior_lease = (
            prior_payload.get("session_token_lease")
            if isinstance(prior_payload.get("session_token_lease"), Mapping)
            else {}
        )
        current_lease = runtime_context_session_token_lease_view(
            context,
            now_iso=now_iso,
        )
        current_lease_status = str(current_lease.get("status") or "").strip()
        expected_principal = str(
            context.actual_host_worker_id
            or context.worker_slot_id
            or context.worker_id
            or context.agent_id
            or ""
        ).strip()
        prior_identity = {
            "project_id": str(prior_payload.get("project_id") or "").strip(),
            "backlog_id": str(prior_payload.get("backlog_id") or "").strip(),
            "contract_execution_id": str(
                prior_payload.get("contract_execution_id") or ""
            ).strip(),
            "runtime_context_id": str(
                prior_payload.get("runtime_context_id") or ""
            ).strip(),
            "task_id": str(prior_payload.get("task_id") or "").strip(),
            "parent_task_id": str(
                prior_payload.get("parent_task_id") or ""
            ).strip(),
            "worker_id": str(prior_payload.get("worker_id") or "").strip(),
            "worker_slot_id": str(
                prior_payload.get("worker_slot_id") or ""
            ).strip(),
            "principal_id": str(
                prior_payload.get("principal_id") or ""
            ).strip(),
            "session_token_ref": str(
                prior_payload.get("session_token_ref") or ""
            ).strip(),
        }
        expected_prior_identity = {
            "project_id": project_id,
            "backlog_id": str(context.backlog_id or "").strip(),
            "contract_execution_id": presented_contract_execution_id,
            "runtime_context_id": expected_runtime_id,
            "task_id": expected_task_id,
            "parent_task_id": expected_parent_task_id,
            "worker_id": expected_worker_id,
            "worker_slot_id": expected_worker_slot_id,
            "principal_id": expected_principal,
            "session_token_ref": presented_session_ref,
        }
        prior_lease_expected = {
            "lease_id": str(context.lease_id or "").strip(),
            "lease_expires_at": str(context.lease_expires_at or "").strip(),
            "session_token_ref": presented_session_ref,
            "status": "active",
            "authorization_valid": True,
            "lease_record_valid": True,
            "expired": False,
        }
        prior_loss_authority = (
            prior_payload.get("safe_ref_loss_replacement_authority")
            if isinstance(
                prior_payload.get("safe_ref_loss_replacement_authority"),
                Mapping,
            )
            else {}
        )
        prior_stage_reissue_count = len(stage_reissue_events)
        expected_prior_stage_event_ref = (
            f"timeline:{stage_reissue_events[0].get('id', '')}"
            if stage_reissue_events
            else ""
        )
        legacy_r2_capture_loss_rescue = (
            _runtime_context_exact_legacy_r2_capture_loss_rescue(
                project_id=project_id,
                context=context,
                contract_execution_id=presented_contract_execution_id,
                prior_event=prior_safe_ref_reissue_event,
                stage_reissue_events=stage_reissue_events,
                prior_loss_authority=prior_loss_authority,
                stage_checkpoint_id=stage_checkpoint_id,
                route_identity_hash=route_identity_hash,
            )
            if prior_stage_reissue_count == 3
            else {}
        )
        prior_loss_chain_valid = bool(
            (
                prior_stage_reissue_count == 1
                and not prior_loss_authority
            )
            or (
                prior_stage_reissue_count == 2
                and str(
                    prior_loss_authority.get("schema_version") or ""
                ).strip()
                == "runtime_context.safe_ref_loss_replacement_authority.v1"
                and prior_loss_authority.get("server_derived") is True
                and prior_loss_authority.get("caller_claims_trusted") is False
                and int(
                    prior_loss_authority.get("prior_stage_reissue_count") or 0
                )
                == 1
                and int(
                    prior_loss_authority.get("loss_replacement_generation") or 1
                )
                == 1
                and int(
                    prior_loss_authority.get("max_loss_replacements") or 0
                )
                in {1, 2}
                and str(
                    prior_loss_authority.get("prior_reissue_event_ref") or ""
                ).strip()
                == expected_prior_stage_event_ref
                and prior_loss_authority.get("worker_receipt_consumed") is False
                and prior_loss_authority.get("worker_startup_consumed") is False
                and prior_loss_authority.get("raw_credentials_persisted") is False
                and re.fullmatch(
                    r"sha256:[0-9a-f]{64}",
                    str(prior_loss_authority.get("authority_hash") or ""),
                )
                is not None
                and str(
                    prior_loss_authority.get("authority_hash") or ""
                ).strip()
                == _stable_public_hash(
                    {
                        key: value
                        for key, value in prior_loss_authority.items()
                        if key != "authority_hash"
                    }
                )
            )
            or (
                prior_stage_reissue_count == 3
                and bool(legacy_r2_capture_loss_rescue)
            )
        )
        if (
            not prior_loss_chain_valid
            or prior_stage_reissue_count not in {1, 2, 3}
            or prior_identity != expected_prior_identity
            or prior_payload.get("ok") is not True
            or str(prior_payload.get("schema_version") or "").strip()
            != "mf_subagent_session_token_reissue_response.v1"
            or str(prior_payload.get("status") or "").strip()
            != "session_token_reissued"
            or str(prior_payload.get("action") or "").strip()
            != "runtime_context_session_token_reissue"
            or str(prior_payload.get("authorization_source") or "").strip()
            != "safe_ref_prestartup_reissue_authority"
            or str(prior_payload.get("delivery") or "").strip()
            != "worker_host_envelope"
            or str(prior_payload.get("expires_at") or "").strip()
            != str(context.lease_expires_at or "").strip()
            or str(prior_payload.get("session_token_hash") or "").strip()
            != str(context.session_token_hash or "").strip()
            or str(prior_payload.get("fence_token_hash") or "").strip()
            != str(context.fence_token_verifier or "").strip()
            or prior_payload.get("session_token_persisted") is not False
            or prior_payload.get("raw_session_token_persisted") is not False
            or prior_payload.get("raw_fence_token_persisted") is not False
            or prior_payload.get("raw_fence_token_persisted_to_timeline")
            is not False
            or dict(prior_payload.get("route_identity") or {})
            != expected_route_identity
            or any(
                prior_lease.get(field) != expected
                for field, expected in prior_lease_expected.items()
            )
            or current_lease.get("lease_record_valid") is not True
            or current_lease_status not in {"active", "expired"}
            or (
                current_lease_status == "active"
                and (
                    current_lease.get("authorization_valid") is not True
                    or current_lease.get("expired") is not False
                )
            )
            or (
                current_lease_status == "expired"
                and (
                    current_lease.get("authorization_valid") is not False
                    or current_lease.get("expired") is not True
                )
            )
            or str(prior_authority.get("schema_version") or "").strip()
            != "runtime_context.safe_ref_prestartup_reissue_authority.v2"
            or prior_authority.get("server_derived") is not True
            or prior_authority.get("caller_claims_trusted") is not False
            or str(prior_authority.get("read_receipt_ref") or "").strip()
            != authority_read_receipt_ref
            or str(prior_authority.get("initial_join_event_ref") or "").strip()
            != f"timeline:{selected_initial_join.get('id', '')}"
            or str(
                prior_authority.get("session_authority_event_ref") or ""
            ).strip()
            != f"timeline:{session_authority_event.get('id', '')}"
            or str(prior_authority.get("session_authority_kind") or "").strip()
            != session_authority_kind
            or str(prior_authority.get("route_identity_hash") or "").strip()
            != route_identity_hash
            or str(prior_authority.get("stage_checkpoint_id") or "").strip()
            != stage_checkpoint_id
            or prior_authority.get("stage_checkpoint_server_verified") is not True
            or not re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                str(prior_authority.get("authority_hash") or ""),
            )
        ):
            raise BranchRuntimeFenceError("fence_invalidated_or_unknown")
        replacement_core = {
            "schema_version": (
                "runtime_context.safe_ref_loss_replacement_authority.v1"
            ),
            "server_derived": True,
            "caller_claims_trusted": False,
            "prior_reissue_event_ref": (
                f"timeline:{prior_safe_ref_reissue_event.get('id', '')}"
            ),
            "stage_checkpoint_id": stage_checkpoint_id,
            "prior_stage_reissue_count": prior_stage_reissue_count,
            "loss_replacement_generation": prior_stage_reissue_count,
            "max_loss_replacements": 2,
            "managed_host_continuity_loss_replacement": (
                prior_stage_reissue_count >= 2
            ),
            "session_token_ref": presented_session_ref,
            "lease_id": str(context.lease_id or "").strip(),
            "lease_status_at_replacement": current_lease_status,
            "worker_receipt_consumed": False,
            "worker_startup_consumed": False,
            "route_identity_hash": route_identity_hash,
            "raw_credentials_persisted": False,
        }
        if legacy_r2_capture_loss_rescue:
            replacement_core["legacy_r2_capture_loss_rescue"] = dict(
                legacy_r2_capture_loss_rescue
            )
        safe_ref_loss_replacement_authority = {
            **replacement_core,
            "authority_hash": _stable_public_hash(replacement_core),
        }
    authority = build_safe_ref_prestartup_reissue_authority(
        context,
        contract_execution_id=presented_contract_execution_id,
        read_receipt_ref=authority_read_receipt_ref,
        initial_join_event_ref=f"timeline:{selected_initial_join.get('id', '')}",
        worker_session_id=expected_worker_session_id,
        session_authority_event_ref=(
            f"timeline:{session_authority_event.get('id', '')}"
        ),
        session_authority_kind=session_authority_kind,
        route_identity_hash=route_identity_hash,
        stage_checkpoint_id=stage_checkpoint_id,
        pre_read_special_authority=(
            pre_read_special_stage
            and not pre_read_pinned_replacement_stage
        ),
        pre_read_pinned_replacement_authority=(
            pre_read_pinned_replacement_stage
        ),
        now_iso=now_iso,
    )
    source_authority = {
        "schema_version": (
            "runtime_context.safe_ref_session_authority_source.v1"
        ),
        "server_derived": True,
        "caller_claims_trusted": False,
        "event_ref": f"timeline:{session_authority_event.get('id', '')}",
        "source_kind": session_authority_source_kind,
        "normalized_capability_kind": session_authority_kind,
        "normalization_applied": (
            session_authority_source_kind != session_authority_kind
        ),
    }
    if str(sequence.get("source") or "") == (
        "task_timeline_context_local_receipt"
    ):
        source_authority.update(
            {
                "context_local_receipt": True,
                "context_local_read_receipt_event_ref": read_receipt_ref,
                "context_local_read_receipt_hash": str(
                    sequence.get("read_receipt_hash") or ""
                ).strip(),
                "contract_runtime_prior_read_receipt_ref": (
                    authority_read_receipt_ref
                ),
                "contract_runtime_mutated": False,
            }
        )
    source_authority["authority_hash"] = _stable_public_hash(
        source_authority
    )
    return authority, safe_ref_loss_replacement_authority, source_authority


@route("POST", "/api/graph-governance/{project_id}/runtime-contexts/{runtime_context_id}/session-token/reissue")
@route("POST", "/api/graph-governance/{project_id}/runtime-contexts/{runtime_context_id}/session-token/renew")
@route("POST", "/api/graph-governance/{project_id}/parallel-branches/runtime-contexts/{runtime_context_id}/session-token/reissue")
@route("POST", "/api/graph-governance/{project_id}/parallel-branches/runtime-contexts/{runtime_context_id}/session-token/renew")
def handle_graph_governance_runtime_context_session_token_reissue(ctx: RequestContext):
    """Rotate an active mf_sub runtime session token after matching-token proof."""
    project_id = ctx.get_project_id()
    runtime_context_id = str(
        ctx.path_params.get("runtime_context_id")
        or _runtime_context_request_value(ctx, "runtime_context_id")
        or ""
    ).strip()
    if not runtime_context_id:
        raise ValidationError("runtime_context_id is required")
    body = dict(ctx.body or {})
    authoritative_now_iso = _utc_now()
    from .db import sqlite_write_lock

    conn = get_connection(project_id)
    write_lock = sqlite_write_lock()
    write_lock.acquire()
    try:
        conn.execute("BEGIN IMMEDIATE")
        from .parallel_branch_runtime import (
            BranchRuntimeFenceError,
            reissue_mf_subagent_runtime_session_token,
        )
        from . import task_timeline

        try:
            session_token_ref = str(body.get("session_token_ref") or "").strip()
            raw_fence_token = str(body.get("fence_token") or "").strip()
            raw_session_token = str(body.get("session_token") or "").strip()
            safe_ref_authority = None
            safe_ref_loss_replacement_authority: dict[str, Any] = {}
            safe_ref_session_authority_source: dict[str, Any] = {}
            if session_token_ref and not (raw_fence_token and raw_session_token):
                (
                    safe_ref_authority,
                    safe_ref_loss_replacement_authority,
                    safe_ref_session_authority_source,
                ) = (
                    _runtime_context_safe_ref_prestartup_reissue_authority(
                        ctx,
                        conn,
                        project_id=project_id,
                        runtime_context_id=runtime_context_id,
                        body=body,
                        now_iso=authoritative_now_iso,
                    )
                )
            result = reissue_mf_subagent_runtime_session_token(
                conn,
                project_id=project_id,
                runtime_context_id=runtime_context_id,
                task_id=(
                    safe_ref_authority.task_id
                    if safe_ref_authority is not None
                    else str(body.get("task_id") or "").strip()
                ),
                parent_task_id=(
                    safe_ref_authority.parent_task_id
                    if safe_ref_authority is not None
                    else str(body.get("parent_task_id") or "").strip()
                ),
                fence_token=raw_fence_token,
                session_token=raw_session_token,
                session_token_ref=session_token_ref,
                contract_execution_id=(
                    safe_ref_authority.contract_execution_id
                    if safe_ref_authority is not None
                    else str(body.get("contract_execution_id") or "").strip()
                ),
                target_project_root=(
                    safe_ref_authority.target_project_root
                    if safe_ref_authority is not None
                    else str(
                        body.get("target_project_root")
                        or body.get("project_root")
                        or body.get("repo_root")
                        or ""
                    ).strip()
                ),
                worker_id=(
                    safe_ref_authority.worker_id
                    if safe_ref_authority is not None
                    else str(body.get("worker_id") or "").strip()
                ),
                worker_slot_id=(
                    safe_ref_authority.worker_slot_id
                    if safe_ref_authority is not None
                    else str(body.get("worker_slot_id") or "").strip()
                ),
                agent_id=(
                    safe_ref_authority.agent_id
                    if safe_ref_authority is not None
                    else str(body.get("agent_id") or "").strip()
                ),
                allocation_owner=(
                    safe_ref_authority.allocation_owner
                    if safe_ref_authority is not None
                    else str(body.get("allocation_owner") or "").strip()
                ),
                actual_host_worker_id=(
                    safe_ref_authority.actual_host_worker_id
                    if safe_ref_authority is not None
                    else str(
                        body.get("actual_host_worker_id")
                        or body.get("host_worker_id")
                        or ""
                    ).strip()
                ),
                worker_session_id=(
                    safe_ref_authority.worker_session_id
                    if safe_ref_authority is not None
                    else str(body.get("worker_session_id") or "").strip()
                ),
                host_startup_id=(
                    safe_ref_authority.host_startup_id
                    if safe_ref_authority is not None
                    else str(body.get("host_startup_id") or "").strip()
                ),
                host_session_id=(
                    safe_ref_authority.host_session_id
                    if safe_ref_authority is not None
                    else str(body.get("host_session_id") or "").strip()
                ),
                safe_ref_authority=safe_ref_authority,
                ttl_seconds=body.get("ttl_seconds"),
                now_iso=(
                    authoritative_now_iso
                    if safe_ref_authority is not None
                    else str(body.get("now_iso") or "")
                ),
            )
            if safe_ref_authority is not None:
                result["contract_execution_id"] = (
                    safe_ref_authority.contract_execution_id
                )
                result["safe_ref_reissue_authority"] = {
                    "schema_version": safe_ref_authority.schema_version,
                    "authority_hash": safe_ref_authority.authority_hash,
                    "read_receipt_ref": safe_ref_authority.read_receipt_ref,
                    "initial_join_event_ref": (
                        safe_ref_authority.initial_join_event_ref
                    ),
                    "session_authority_event_ref": (
                        safe_ref_authority.session_authority_event_ref
                    ),
                    "session_authority_kind": (
                        safe_ref_authority.session_authority_kind
                    ),
                    "worker_session_id": (
                        safe_ref_authority.worker_session_id
                    ),
                    "host_session_id": safe_ref_authority.host_session_id,
                    "route_identity_hash": safe_ref_authority.route_identity_hash,
                    "stage_checkpoint_id": (
                        safe_ref_authority.stage_checkpoint_id
                    ),
                    "stage_checkpoint_server_verified": (
                        safe_ref_authority.stage_checkpoint_server_verified
                    ),
                    "lease_status_at_authorization": (
                        safe_ref_authority.lease_status_at_authorization
                    ),
                    "latest_ref_identifier_only": (
                        safe_ref_authority.latest_ref_identifier_only
                    ),
                    "pre_read_special_authority": (
                        safe_ref_authority.pre_read_special_authority
                    ),
                    "pre_read_pinned_replacement_authority": (
                        safe_ref_authority
                        .pre_read_pinned_replacement_authority
                    ),
                    "server_derived": True,
                    "caller_claims_trusted": False,
                }
                if safe_ref_loss_replacement_authority:
                    result["safe_ref_loss_replacement_authority"] = dict(
                        safe_ref_loss_replacement_authority
                    )
                result["safe_ref_session_authority_source"] = dict(
                    safe_ref_session_authority_source
                )
                expected_route_identity = {
                    field: str(value or "").strip()
                    for field, value in _runtime_context_request_route_identity_shapes(
                        ctx
                    )["supplied"].items()
                    if str(value or "").strip()
                }
                result["route_identity"] = dict(expected_route_identity)
                host_envelope = result.get("host_envelope")
                if isinstance(host_envelope, dict):
                    host_envelope["route_identity"] = dict(
                        expected_route_identity
                    )
        except BranchRuntimeFenceError as exc:
            reason = str(exc) or "fence_invalidated_or_unknown"
            recovery_details = _runtime_context_worker_recovery_details(
                ctx,
                conn,
                project_id=project_id,
                runtime_context_id=runtime_context_id,
                task_id=str(body.get("task_id") or "").strip(),
                parent_task_id=str(body.get("parent_task_id") or "").strip(),
                fence_token=str(body.get("fence_token") or "").strip(),
                session_token=str(body.get("session_token") or "").strip(),
                session_token_ref=str(body.get("session_token_ref") or "").strip(),
                target_project_root=str(
                    body.get("target_project_root")
                    or body.get("project_root")
                    or body.get("repo_root")
                    or ""
                ).strip(),
                reason=reason,
            )
            raise GovernanceError(
                "fence_invalidated_or_unknown",
                "mf_subagent session token reissue requires active matching runtime/fence/session identity",
                403,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": str(body.get("task_id") or ""),
                    "parent_task_id": str(body.get("parent_task_id") or ""),
                    "reason": reason,
                    "fail_closed": True,
                    **recovery_details,
                },
            ) from exc

        audit_payload = {
            key: value
            for key, value in result.items()
            if key
            not in {
                "session_token",
                "fence_token",
                "host_envelope",
            }
        }
        audit_payload["action"] = "runtime_context_session_token_reissue"
        audit_payload["raw_session_token_persisted"] = False
        audit_event = task_timeline.record_event(
            conn,
            project_id=project_id,
            task_id=str(result.get("task_id") or ""),
            backlog_id=str(result.get("backlog_id") or ""),
            event_type="mf_subagent.session_token_reissue",
            event_kind="mf_subagent_session_token_reissue",
            phase="runtime_context_recovery",
            status="accepted",
            actor=str(body.get("actor") or result.get("principal_id") or "mf_sub"),
            payload=audit_payload,
        )
        conn.commit()
        result["audit_event_ref"] = f"timeline:{audit_event.get('id', '')}"
        result["audit_event_id"] = audit_event.get("id", "")
        return result
    finally:
        try:
            if conn.in_transaction:
                conn.rollback()
        finally:
            try:
                conn.close()
            finally:
                write_lock.release()


def _runtime_context_initial_join_expected_canonical_identity_binding(
    *,
    project_id: str,
    context: Any,
    governed_worker_id: str,
    contract_execution_id: str,
    worker_session_id: str,
    host_startup_id: str,
    host_session_id: str,
    route_identity: Mapping[str, Any],
    dispatch_identity_anchor: Mapping[str, Any],
    missing_lineage: Sequence[str],
    now_iso: str = "",
) -> dict[str, Any]:
    """Build the closed copy-safe identity marker from durable authority."""

    from .parallel_branch_runtime import (
        runtime_context_id_for_branch_context,
        runtime_context_session_token_lease_view,
        runtime_context_session_token_ref,
    )

    lease = runtime_context_session_token_lease_view(context, now_iso=now_iso)
    binding_core = {
        "schema_version": (
            "runtime_context.initial_join_canonical_identity_binding.v1"
        ),
        "server_derived": True,
        "initial_join_identity_contract_version": (
            "runtime_context.initial_join_identity.v2"
        ),
        "project_id": str(project_id or "").strip(),
        "runtime_context_id": runtime_context_id_for_branch_context(context),
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "task_id": str(context.task_id or "").strip(),
        "parent_task_id": _runtime_context_mf_sub_parent_task_id(context),
        "backlog_id": str(context.backlog_id or "").strip(),
        "batch_id": str(context.batch_id or "").strip(),
        "worker_id": str(context.worker_id or "").strip(),
        "worker_slot_id": str(
            context.worker_slot_id or context.worker_id or ""
        ).strip(),
        "governed_worker_id": str(governed_worker_id or "").strip(),
        "agent_id": str(governed_worker_id or "").strip(),
        "actual_host_worker_id": str(governed_worker_id or "").strip(),
        "worker_session_id": str(worker_session_id or "").strip(),
        "host_startup_id": str(host_startup_id or "").strip(),
        "host_session_id": str(host_session_id or "").strip(),
        "session_token_ref": runtime_context_session_token_ref(context),
        "target_project_root": (
            _runtime_context_effective_target_project_root(context)
        ),
        "branch_ref": str(context.branch_ref or "").strip(),
        "worktree_path": str(context.worktree_path or "").strip(),
        "base_commit": str(context.base_commit or "").strip(),
        "head_commit": str(context.head_commit or "").strip(),
        "target_head_commit": str(
            context.target_head_commit or ""
        ).strip(),
        "merge_queue_id": str(context.merge_queue_id or "").strip(),
        "context_status": str(context.status or "").strip(),
        "last_recovery_action": str(
            context.last_recovery_action or ""
        ).strip(),
        "missing_lineage": list(missing_lineage),
        "route_identity": {
            field: str(route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        },
        "contract_dispatch_identity_anchor_required": bool(
            dispatch_identity_anchor
        ),
        "contract_dispatch_identity_anchor": dict(
            dispatch_identity_anchor
        ),
        "session_token_lease": {
            "schema_version": str(lease.get("schema_version") or ""),
            "lease_id": str(lease.get("lease_id") or ""),
            "lease_expires_at": str(lease.get("lease_expires_at") or ""),
            "session_token_ref": str(lease.get("session_token_ref") or ""),
            "status": str(lease.get("status") or ""),
            "authorization_valid": lease.get("authorization_valid") is True,
            "lease_record_valid": lease.get("lease_record_valid") is True,
            "expired": lease.get("expired") is True,
        },
        "raw_credentials_persisted": False,
    }
    return {**binding_core, "binding_hash": _stable_public_hash(binding_core)}


def _runtime_context_initial_join_canonical_identity_binding(
    *,
    project_id: str,
    original_context: Any,
    saved_context: Any,
    result: Mapping[str, Any],
    governed_worker_id: str,
    contract_execution_id: str,
    expected_worker_session_id: str,
    expected_host_startup_id: str,
    expected_host_session_id: str,
    route_identity: Mapping[str, Any],
    dispatch_identity_anchor: Mapping[str, Any],
    expected_missing_lineage: Sequence[str],
    actual_missing_lineage: Sequence[str],
    now_iso: str = "",
) -> tuple[dict[str, Any], list[str]]:
    """Validate the issued initial-join envelope before its audit can commit."""

    from .parallel_branch_runtime import (
        mf_subagent_session_token_hash,
        runtime_context_fence_token_verifier,
        runtime_context_secret_hash,
    )

    if saved_context is None:
        return {}, ["saved_runtime_context"]

    binding = _runtime_context_initial_join_expected_canonical_identity_binding(
        project_id=project_id,
        context=saved_context,
        governed_worker_id=governed_worker_id,
        contract_execution_id=contract_execution_id,
        worker_session_id=expected_worker_session_id,
        host_startup_id=expected_host_startup_id,
        host_session_id=expected_host_session_id,
        route_identity=route_identity,
        dispatch_identity_anchor=dispatch_identity_anchor,
        missing_lineage=expected_missing_lineage,
        now_iso=now_iso,
    )
    runtime_id = str(binding.get("runtime_context_id") or "")
    task_id = str(binding.get("task_id") or "")
    parent_task_id = str(binding.get("parent_task_id") or "")
    worker_id = str(binding.get("worker_id") or "")
    worker_slot_id = str(binding.get("worker_slot_id") or "")
    session_token_ref = str(binding.get("session_token_ref") or "")
    target_project_root = str(binding.get("target_project_root") or "")
    safe_route_identity = dict(binding.get("route_identity") or {})
    mismatches: list[str] = []

    def _compare_text(
        container: Mapping[str, Any],
        expected: Mapping[str, str],
        *,
        prefix: str,
    ) -> None:
        for field, expected_value in expected.items():
            if str(container.get(field) or "").strip() != expected_value:
                mismatches.append(f"{prefix}.{field}")

    expected_result = {
        "project_id": str(project_id or "").strip(),
        "runtime_context_id": runtime_id,
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "backlog_id": str(saved_context.backlog_id or "").strip(),
        "batch_id": str(saved_context.batch_id or "").strip(),
        "worker_role": "mf_sub",
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "agent_id": governed_worker_id,
        "actual_host_worker_id": governed_worker_id,
        "worker_session_id": expected_worker_session_id,
        "host_startup_id": expected_host_startup_id,
        "host_session_id": expected_host_session_id,
        "principal_id": governed_worker_id,
        "session_token_ref": session_token_ref,
        "fence_token_hash": runtime_context_fence_token_verifier(saved_context),
        "expires_at": str(saved_context.lease_expires_at or "").strip(),
    }
    _compare_text(result, expected_result, prefix="result")
    for field, expected_value in {
        "session_token_persisted": False,
        "raw_session_token_persisted": False,
        "raw_fence_token_persisted_to_timeline": False,
    }.items():
        if result.get(field) is not expected_value:
            mismatches.append(f"result.{field}")
    session_token = str(result.get("session_token") or "")
    fence_token = str(result.get("fence_token") or "")
    if (
        not session_token
        or mf_subagent_session_token_hash(session_token)
        != str(saved_context.session_token_hash or "").strip()
        or str(result.get("session_token_hash") or "").strip()
        != str(saved_context.session_token_hash or "").strip()
    ):
        mismatches.append("result.session_token_binding")
    if (
        not fence_token
        or runtime_context_secret_hash(fence_token)
        != runtime_context_fence_token_verifier(saved_context)
    ):
        mismatches.append("result.fence_token_binding")
    result_lease = result.get("session_token_lease")
    expected_lease_binding = dict(binding["session_token_lease"])
    if not isinstance(result_lease, Mapping) or any(
        result_lease.get(field) != expected
        for field, expected in expected_lease_binding.items()
    ):
        mismatches.append("result.session_token_lease")
    if dict(result.get("route_identity") or {}) != safe_route_identity:
        mismatches.append("result.route_identity")

    host_envelope = result.get("host_envelope")
    if not isinstance(host_envelope, Mapping):
        mismatches.append("result.host_envelope")
        host_envelope = {}
    expected_host_envelope = {
        **expected_result,
        "target_project_root": target_project_root,
        "branch": str(saved_context.branch_ref or "").strip(),
        "branch_ref": str(saved_context.branch_ref or "").strip(),
        "worktree_path": str(saved_context.worktree_path or "").strip(),
        "base_commit": str(saved_context.base_commit or "").strip(),
        "target_head_commit": str(
            saved_context.target_head_commit or ""
        ).strip(),
        "merge_queue_id": str(saved_context.merge_queue_id or "").strip(),
    }
    expected_host_envelope.pop("expires_at", None)
    _compare_text(
        host_envelope,
        expected_host_envelope,
        prefix="host_envelope",
    )
    if dict(host_envelope.get("route_identity") or {}) != safe_route_identity:
        mismatches.append("host_envelope.route_identity")
    host_env = host_envelope.get("env")
    if not isinstance(host_env, Mapping) or (
        str(host_env.get("AMING_WORKER_SESSION_TOKEN") or "")
        != session_token
        or str(host_env.get("AMING_WORKER_FENCE_TOKEN") or "")
        != fence_token
    ):
        mismatches.append("host_envelope.env")

    durable_fields = (
        "project_id",
        "governance_project_id",
        "target_project_id",
        "target_project_root",
        "task_id",
        "batch_id",
        "parent_task_id",
        "root_task_id",
        "backlog_id",
        "stage_task_id",
        "worker_id",
        "worker_slot_id",
        "agent_id",
        "allocation_owner",
        "branch_ref",
        "worktree_path",
        "base_commit",
        "head_commit",
        "target_head_commit",
        "merge_queue_id",
        "status",
    )
    for field in durable_fields:
        if getattr(original_context, field, None) != getattr(
            saved_context,
            field,
            None,
        ):
            mismatches.append(f"context.{field}")
    original_fence_verifier = runtime_context_secret_hash(
        str(original_context.fence_token or "")
    )
    if (
        not original_fence_verifier
        or str(saved_context.fence_token or "").strip()
        or str(saved_context.fence_token_verifier or "").strip()
        != original_fence_verifier
        or runtime_context_fence_token_verifier(saved_context)
        != original_fence_verifier
    ):
        mismatches.append("context.fence_token_custody_transition")
    if str(saved_context.actual_host_worker_id or "").strip() != governed_worker_id:
        mismatches.append("context.actual_host_worker_id")
    if str(saved_context.host_startup_id or "").strip() != expected_host_startup_id:
        mismatches.append("context.host_startup_id")
    if str(saved_context.host_session_id or "").strip() != expected_host_session_id:
        mismatches.append("context.host_session_id")
    if str(saved_context.last_recovery_action or "").strip() != (
        "mf_subagent_initial_join_issued"
    ):
        mismatches.append("context.last_recovery_action")
    if list(actual_missing_lineage) != list(expected_missing_lineage):
        mismatches.append("timeline.missing_lineage")

    return binding, list(dict.fromkeys(mismatches))


def _runtime_context_initial_join_identity_binding_anchor(
    *,
    project_id: str,
    runtime_context_id: str,
    contract_execution_id: str,
    task_id: str,
    backlog_id: str,
    initial_join_event_ref: str,
    canonical_binding: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the independent append-only cutover anchor for a fresh join."""

    route_identity = (
        canonical_binding.get("route_identity")
        if isinstance(canonical_binding.get("route_identity"), Mapping)
        else {}
    )
    core = {
        "schema_version": (
            "runtime_context.initial_join_identity_binding_anchor.v1"
        ),
        "action": (
            "runtime_context_session_token_initial_join_identity_binding_anchor"
        ),
        "caller_role": "observer",
        "server_derived": True,
        "project_id": str(project_id or "").strip(),
        "runtime_context_id": str(runtime_context_id or "").strip(),
        "contract_execution_id": str(
            contract_execution_id or ""
        ).strip(),
        "task_id": str(task_id or "").strip(),
        "backlog_id": str(backlog_id or "").strip(),
        "initial_join_event_ref": str(initial_join_event_ref or "").strip(),
        "canonical_binding_hash": str(
            canonical_binding.get("binding_hash") or ""
        ).strip(),
        "session_token_ref": str(
            canonical_binding.get("session_token_ref") or ""
        ).strip(),
        "route_identity_hash": _stable_public_hash(dict(route_identity)),
        "raw_credentials_persisted": False,
    }
    return {**core, "anchor_hash": _stable_public_hash(core)}


def _runtime_context_initial_join_cutover_authority(
    *,
    project_id: str,
    runtime_context_id: str,
    contract_execution_id: str,
    task_id: str,
    parent_task_id: str,
    backlog_id: str,
    initial_join_event_ref: str,
    identity_anchor_ref: str,
    canonical_binding: Mapping[str, Any],
    identity_anchor: Mapping[str, Any],
    operator_principal_id: str,
    operator_session_id: str,
    operator_role: str,
    created_at: str,
) -> dict[str, Any]:
    """Build the closed append-only access-audit authority for the v2 cutover."""

    route_identity = (
        canonical_binding.get("route_identity")
        if isinstance(canonical_binding.get("route_identity"), Mapping)
        else {}
    )
    core = {
        "schema_version": "runtime_context.initial_join_identity_cutover.v1",
        "server_derived": True,
        "project_id": str(project_id or "").strip(),
        "runtime_context_id": str(runtime_context_id or "").strip(),
        "contract_execution_id": str(
            contract_execution_id or ""
        ).strip(),
        "task_id": str(task_id or "").strip(),
        "parent_task_id": str(parent_task_id or "").strip(),
        "backlog_id": str(backlog_id or "").strip(),
        "initial_join_event_ref": str(initial_join_event_ref or "").strip(),
        "identity_anchor_ref": str(identity_anchor_ref or "").strip(),
        "canonical_binding_hash": str(
            canonical_binding.get("binding_hash") or ""
        ).strip(),
        "identity_anchor_hash": str(
            identity_anchor.get("anchor_hash") or ""
        ).strip(),
        "operator_principal_id": str(
            operator_principal_id or ""
        ).strip(),
        "operator_session_id": str(operator_session_id or "").strip(),
        "operator_role": str(operator_role or "").strip(),
        "created_at": str(created_at or "").strip(),
        "session_token_ref": str(
            canonical_binding.get("session_token_ref") or ""
        ).strip(),
        "route_identity_hash": _stable_public_hash(dict(route_identity)),
        "raw_credentials_persisted": False,
    }
    return {**core, "cutover_hash": _stable_public_hash(core)}


def _runtime_context_initial_join_cutover_audit_id(
    cutover: Mapping[str, Any],
) -> str:
    cutover_hash = str(cutover.get("cutover_hash") or "").strip()
    digest = cutover_hash.removeprefix("sha256:")
    return f"rtca-initial-join-binding-{digest[:24]}"


@route("POST", "/api/graph-governance/{project_id}/runtime-contexts/{runtime_context_id}/session-token/initial-join")
@route("POST", "/api/graph-governance/{project_id}/parallel-branches/runtime-contexts/{runtime_context_id}/session-token/initial-join")
def handle_graph_governance_runtime_context_session_token_initial_join(ctx: RequestContext):
    """Issue the first audited worker host envelope before worker lineage exists."""
    project_id = ctx.get_project_id()
    runtime_context_id = str(
        ctx.path_params.get("runtime_context_id")
        or _runtime_context_request_value(ctx, "runtime_context_id")
        or ""
    ).strip()
    if not runtime_context_id:
        raise ValidationError("runtime_context_id is required")
    body = dict(ctx.body or {})
    reason = str(body.get("reason") or body.get("join_reason") or "").strip()
    if not reason:
        raise ValidationError("reason is required for runtime-context initial join")

    conn = get_connection(project_id)
    try:
        from .parallel_branch_runtime import (
            BranchRuntimeFenceError,
            get_branch_context_by_runtime_context_id,
            initial_join_mf_subagent_runtime_session_token,
            runtime_context_id_for_branch_context,
            runtime_context_secret_hash,
            upsert_branch_context,
            validate_initial_join_mf_subagent_host_identity,
        )
        from .permissions import require_operator_capability, session_role
        from . import task_timeline

        session = _require_graph_governance_mf_subagent(
            ctx,
            conn,
            "graph-governance.runtime-context.session-token-initial-join",
        )
        require_operator_capability(
            session,
            "graph-governance.runtime-context.session-token-initial-join",
        )
        context = get_branch_context_by_runtime_context_id(
            conn,
            project_id,
            runtime_context_id,
        )
        if context is None:
            raise GovernanceError(
                "runtime_context_not_found",
                f"branch runtime context not found: {project_id}/{runtime_context_id}",
                404,
                {"runtime_context_id": runtime_context_id},
            )
        canonical_task_id = str(context.task_id or "").strip()
        canonical_parent_task_id = _runtime_context_mf_sub_parent_task_id(
            context
        )
        supplied_task_id = str(body.get("task_id") or "").strip()
        supplied_parent_task_id = str(
            body.get("parent_task_id") or ""
        ).strip()
        supplied_contract_execution_id = str(
            body.get("contract_execution_id") or ""
        ).strip()
        supplied_worker_id = str(body.get("worker_id") or "").strip()
        supplied_worker_slot_id = str(
            body.get("worker_slot_id") or ""
        ).strip()
        canonical_worker_id = str(context.worker_id or "").strip()
        canonical_worker_slot_id = str(
            context.worker_slot_id or context.worker_id or ""
        ).strip()
        identity_mismatch_fields = [
            field
            for field, supplied, canonical in (
                ("task_id", supplied_task_id, canonical_task_id),
                (
                    "parent_task_id",
                    supplied_parent_task_id,
                    canonical_parent_task_id,
                ),
                (
                    "contract_execution_id",
                    supplied_contract_execution_id,
                    canonical_parent_task_id,
                ),
                ("worker_id", supplied_worker_id, canonical_worker_id),
                (
                    "worker_slot_id",
                    supplied_worker_slot_id,
                    canonical_worker_slot_id,
                ),
            )
            if supplied != canonical
        ]
        if identity_mismatch_fields:
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_contract_identity_mismatch",
                "runtime-context initial join requires exact canonical task, parent contract, and worker identity",
                403,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": context.task_id,
                    "identity_mismatch_fields": identity_mismatch_fields,
                    "mutation_performed": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "submit_the_server_advertised_initial_join_identity"
                    ),
                },
            )
        task_id = canonical_task_id
        parent_task_id = canonical_parent_task_id
        contract_execution_id = canonical_parent_task_id
        timeline_events = _runtime_context_service_timeline_events(
            conn,
            project_id=project_id,
            task_id=context.task_id,
            backlog_id=context.backlog_id,
        )
        timeline_refs, _startup_gate, _finish_gate, _close_evidence = (
            _runtime_context_service_timeline_refs(
                conn,
                project_id=project_id,
                task_id=context.task_id,
                backlog_id=context.backlog_id,
                timeline_events=timeline_events,
                runtime_context_id=context.runtime_context_id,
                parent_task_id=_runtime_context_mf_sub_parent_task_id(context),
            )
        )
        missing_lineage = [
            item
            for item, present in (
                ("mf_subagent_read_receipt", timeline_refs.get("read_receipt_event_ref")),
                ("mf_subagent_startup", timeline_refs.get("startup_event_ref")),
            )
            if not present
        ]
        if not missing_lineage:
            raise GovernanceError(
                "runtime_context_initial_join_requires_missing_worker_lineage",
                "runtime-context initial join is only valid before complete worker read receipt/startup lineage; use rejoin for recovery",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": context.task_id,
                    "next_legal_action": "request_runtime_context_rejoin_host_envelope",
                    "fail_closed": True,
                },
            )
        contract_dispatch_anchor_required = (
            _runtime_context_contract_dispatch_anchor_required(
                conn,
                context=context,
                contract_execution_id=contract_execution_id,
            )
        )
        contract_dispatch_identity_anchor = (
            _runtime_context_pre_lineage_legacy_dispatch_identity_anchor(
                conn,
                project_id=project_id,
                context=context,
                runtime_context_id=runtime_context_id,
                contract_execution_id=contract_execution_id,
            )
        )
        if (
            contract_dispatch_anchor_required
            and not contract_dispatch_identity_anchor
        ):
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_dispatch_identity_mismatch",
                "runtime-context identity does not match the accepted ContractRuntime dispatch",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": canonical_task_id,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "repair_runtime_context_from_accepted_dispatch_before_initial_join"
                    ),
                },
            )
        (
            expected_route_identity,
            expected_route_identity_source,
        ) = (
            _runtime_context_initial_join_expected_route_identity(
                conn,
                context,
                contract_dispatch_identity_anchor,
            )
        )
        supplied_route_identity = dict(
            _runtime_context_request_route_identity_shapes(ctx).get("supplied") or {}
        )
        initial_join_route_lineage_payload: dict[str, Any] = {}
        resolved_route_identity, initial_join_route_lineage_payload = (
            _runtime_context_initial_join_resolved_ref_route_identity(
                body,
                supplied_route_identity,
                project_id=project_id,
                runtime_context_id=runtime_context_id,
                context=context,
                expected_route_identity=expected_route_identity,
            )
        )
        if expected_route_identity and any(
            str(supplied_route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        ) and not resolved_route_identity:
            mismatches = _runtime_context_route_identity_mismatch_fields(
                expected_route_identity,
                supplied_route_identity,
            )
            if mismatches:
                raise GovernanceError(
                    "runtime_context_initial_join_route_identity_mismatch",
                    "runtime-context initial join route identity does not match the active runtime contract",
                    403,
                    {
                        "runtime_context_id": runtime_context_id,
                        "task_id": context.task_id,
                        "route_identity_mismatch_fields": mismatches,
                        "fail_closed": True,
                    },
                )
        selected_route_identity = (
            resolved_route_identity
            if resolved_route_identity
            else expected_route_identity
        )
        safe_route_identity = {
            field: str(selected_route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        }
        missing_route_identity_fields = [
            field
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
            if not safe_route_identity.get(field)
        ]
        if missing_route_identity_fields:
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_route_identity_incomplete",
                "runtime-context initial join requires the complete canonical route identity",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": context.task_id,
                    "missing_route_identity_fields": (
                        missing_route_identity_fields
                    ),
                    "mutation_performed": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "repair_complete_route_prompt_manifest_binding_before_initial_join"
                    ),
                },
            )
        try:
            host_identity = validate_initial_join_mf_subagent_host_identity(
                context,
                agent_id=str(
                    body.get("agent_id") or body.get("host_agent_id") or ""
                ).strip(),
                actual_host_worker_id=str(
                    body.get("actual_host_worker_id")
                    or body.get("host_worker_id")
                    or ""
                ).strip(),
                now_iso=str(body.get("now_iso") or ""),
            )
        except BranchRuntimeFenceError as exc:
            initial_join_error = str(exc) or "fence_invalidated_or_unknown"
            expected_worker_id = str(
                context.worker_id or context.worker_slot_id or ""
            ).strip()
            requested_agent_id = str(
                body.get("agent_id") or body.get("host_agent_id") or ""
            ).strip()
            requested_actual_host_worker_id = str(
                body.get("actual_host_worker_id")
                or body.get("host_worker_id")
                or requested_agent_id
                or ""
            ).strip()
            if initial_join_error == (
                "runtime_context_initial_join_host_identity_mismatch"
            ):
                raise GovernanceError(
                    initial_join_error,
                    "runtime-context initial join host identity does not match the allocated governed worker",
                    403,
                    {
                        "runtime_context_id": runtime_context_id,
                        "task_id": context.task_id,
                        "expected_actual_host_worker_id": expected_worker_id,
                        "actual_host_worker_id": requested_actual_host_worker_id,
                        "requested_agent_id": requested_agent_id,
                        "persisted_actual_host_worker_id": str(
                            context.actual_host_worker_id or ""
                        ).strip(),
                        "worker_session_id_is_independent": True,
                        "mutation_performed": False,
                        "fail_closed": True,
                    },
                ) from exc
            if initial_join_error == (
                "runtime_context_initial_join_active_lease_exists"
            ):
                raise GovernanceError(
                    initial_join_error,
                    "runtime-context initial join cannot rotate an active initial-join lease; use the existing host envelope",
                    409,
                    {
                        "runtime_context_id": runtime_context_id,
                        "task_id": context.task_id,
                        "expected_actual_host_worker_id": expected_worker_id,
                        "actual_host_worker_id": requested_actual_host_worker_id,
                        "next_legal_action": "use_existing_initial_join_host_envelope",
                        "credential_rotated": False,
                        "mutation_performed": False,
                        "fail_closed": True,
                    },
                ) from exc
            raise
        governed_worker_id = str(
            host_identity.get("expected_worker_id") or ""
        ).strip()
        if not governed_worker_id:
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_canonical_identity_missing",
                "runtime-context initial join could not derive the governed worker identity",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": context.task_id,
                    "mutation_performed": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "repair_runtime_context_governed_worker_binding_before_initial_join"
                    ),
                },
            )
        requested_worker_session_id = str(
            body.get("worker_session_id") or body.get("session_id") or ""
        ).strip()
        expected_host_session_id = str(
            body.get("host_session_id")
            or requested_worker_session_id
            or governed_worker_id
            or ""
        ).strip()
        expected_worker_session_id = str(
            requested_worker_session_id
            or expected_host_session_id
            or governed_worker_id
        ).strip()
        expected_host_startup_id = str(
            body.get("host_startup_id") or context.host_startup_id or ""
        ).strip()
        if conn.in_transaction:
            # All work above is schema/read preflight.  The timeline schema
            # guard uses executescript, so establish the write lock only after
            # that preflight is complete.
            conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        locked_context = get_branch_context_by_runtime_context_id(
            conn,
            project_id,
            runtime_context_id,
        )
        if locked_context != context:
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_authority_changed",
                "runtime-context initial join authority changed before issuance",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": canonical_task_id,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "refresh_initial_join_authority_and_retry"
                    ),
                },
            )
        context = locked_context
        try:
            if ctx.token:
                locked_session = role_service.authenticate(conn, ctx.token)
            else:
                locked_session = _require_graph_governance_mf_subagent(
                    ctx,
                    conn,
                    (
                        "graph-governance.runtime-context."
                        "session-token-initial-join"
                    ),
                )
        except Exception:
            conn.rollback()
            raise
        require_operator_capability(
            locked_session,
            "graph-governance.runtime-context.session-token-initial-join",
        )
        if any(
            str(locked_session.get(field) or "").strip()
            != str(session.get(field) or "").strip()
            for field in (
                "session_id",
                "principal_id",
                "project_id",
                "role",
            )
        ):
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_session_authority_changed",
                "runtime-context role-service session changed before issuance",
                403,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": canonical_task_id,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "reauthenticate_active_role_service_session_before_initial_join"
                    ),
                },
            )
        locked_contract_dispatch_anchor_required = (
            _runtime_context_contract_dispatch_anchor_required(
                conn,
                context=context,
                contract_execution_id=contract_execution_id,
            )
        )
        locked_contract_dispatch_identity_anchor = (
            _runtime_context_pre_lineage_legacy_dispatch_identity_anchor(
                conn,
                project_id=project_id,
                context=context,
                runtime_context_id=runtime_context_id,
                contract_execution_id=contract_execution_id,
            )
        )
        if (
            locked_contract_dispatch_anchor_required
            != contract_dispatch_anchor_required
            or locked_contract_dispatch_identity_anchor
            != contract_dispatch_identity_anchor
        ):
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_dispatch_authority_changed",
                "runtime-context ContractRuntime dispatch authority changed before issuance",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": canonical_task_id,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                },
            )
        (
            locked_expected_route_identity,
            locked_expected_route_identity_source,
        ) = (
            _runtime_context_initial_join_expected_route_identity(
                conn,
                context,
                locked_contract_dispatch_identity_anchor,
            )
        )
        if (
            dict(locked_expected_route_identity)
            != dict(expected_route_identity)
            or locked_expected_route_identity_source
            != expected_route_identity_source
        ):
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_route_authority_changed",
                "runtime-context route authority changed before issuance",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": canonical_task_id,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "refresh_active_route_and_session_authority_before_initial_join"
                    ),
                },
            )
        locked_resolved_route_identity, locked_route_lineage_payload = (
            _runtime_context_initial_join_resolved_ref_route_identity(
                body,
                supplied_route_identity,
                project_id=project_id,
                runtime_context_id=runtime_context_id,
                context=context,
                expected_route_identity=locked_expected_route_identity,
            )
        )
        locked_selected_route_identity = (
            locked_resolved_route_identity
            if locked_resolved_route_identity
            else locked_expected_route_identity
        )
        locked_safe_route_identity = {
            field: str(
                locked_selected_route_identity.get(field) or ""
            ).strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        }
        if (
            locked_safe_route_identity != safe_route_identity
            or dict(locked_route_lineage_payload)
            != dict(initial_join_route_lineage_payload)
            or not conn.in_transaction
        ):
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_route_authority_changed",
                "runtime-context route authority changed before issuance",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": canonical_task_id,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "refresh_active_route_and_session_authority_before_initial_join"
                    ),
                },
            )
        session = locked_session
        try:
            result = initial_join_mf_subagent_runtime_session_token(
                conn,
                project_id=project_id,
                runtime_context_id=runtime_context_id,
                task_id=task_id,
                parent_task_id=parent_task_id,
                target_project_root=str(
                    body.get("target_project_root")
                    or body.get("project_root")
                    or body.get("repo_root")
                    or ""
                ).strip(),
                agent_id=governed_worker_id,
                actual_host_worker_id=governed_worker_id,
                worker_session_id=requested_worker_session_id,
                host_startup_id=str(body.get("host_startup_id") or "").strip(),
                host_session_id=str(body.get("host_session_id") or "").strip(),
                ttl_seconds=body.get("ttl_seconds"),
                reason=reason,
                now_iso=str(body.get("now_iso") or ""),
            )
        except BranchRuntimeFenceError as exc:
            raise GovernanceError(
                "fence_invalidated_or_unknown",
                "runtime-context initial join requires active matching runtime identity",
                403,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": task_id,
                    "parent_task_id": parent_task_id,
                    "reason": str(exc) or "fence_invalidated_or_unknown",
                    "fail_closed": True,
                },
            ) from exc

        # Initial join is the custody boundary for the allocation fence.  The
        # raw credential leaves durable storage in the same transaction that
        # issues the worker host envelope; subsequent worker gates compare the
        # process-local bearer only with this explicit verifier.
        issued_fence_token = str(result.get("fence_token") or "").strip()
        issued_fence_verifier = runtime_context_secret_hash(issued_fence_token)
        issued_context = get_branch_context_by_runtime_context_id(
            conn,
            project_id,
            runtime_context_id,
        )
        initial_fence_verifier = runtime_context_secret_hash(
            str(context.fence_token or "")
        )
        persisted_explicit_verifier = str(
            getattr(issued_context, "fence_token_verifier", "") or ""
        ).strip()
        if (
            issued_context is None
            or not issued_fence_token
            or not issued_fence_verifier
            or initial_fence_verifier != issued_fence_verifier
            or str(result.get("fence_token_hash") or "").strip()
            != issued_fence_verifier
            or str(getattr(issued_context, "fence_token", "") or "").strip()
            != issued_fence_token
            or persisted_explicit_verifier
            not in {"", issued_fence_verifier}
        ):
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_fence_authority_mismatch",
                "runtime-context initial join fence does not match the issued host credential",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": task_id,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                },
            )
        issued_context = upsert_branch_context(
            conn,
            replace(
                issued_context,
                fence_token="",
                fence_token_verifier=issued_fence_verifier,
            ),
            now_iso=str(body.get("now_iso") or ""),
        )
        if (
            str(issued_context.fence_token or "").strip()
            or str(issued_context.fence_token_verifier or "").strip()
            != issued_fence_verifier
        ):
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_fence_authority_persistence_failed",
                "runtime-context initial join could not persist the issued fence verifier",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": task_id,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                },
            )

        renewed_contract_revision = None
        if resolved_route_identity and safe_route_identity:
            renewed_contract_revision = (
                _runtime_context_append_resolved_route_ref_contract_revision(
                    conn,
                    context=context,
                    expected_route_identity=expected_route_identity,
                    safe_route_identity=safe_route_identity,
                    route_lineage_payload=initial_join_route_lineage_payload,
                    acceptance_status="accepted_at_initial_join",
                    route_evidence_type="renewed_route_token_ref",
                    now_iso=str(body.get("now_iso") or ""),
                )
            )
        if safe_route_identity:
            result["contract_execution_id"] = contract_execution_id
            result["batch_id"] = str(context.batch_id or "").strip()
            result["route_identity"] = dict(safe_route_identity)
            if initial_join_route_lineage_payload:
                result["route_lineage"] = dict(initial_join_route_lineage_payload)
                result["route_identity_source"] = "resolved_renewed_route_token_ref"
            if renewed_contract_revision is not None:
                result["route_contract_revision_id"] = (
                    renewed_contract_revision.revision_id
                )
                result["route_contract_revision_source"] = (
                    "renewed_route_token_ref"
                )
            host_envelope = result.get("host_envelope")
            if isinstance(host_envelope, dict):
                host_envelope["contract_execution_id"] = (
                    contract_execution_id
                )
                host_envelope["batch_id"] = str(
                    context.batch_id or ""
                ).strip()
                host_envelope["route_identity"] = dict(safe_route_identity)
                if initial_join_route_lineage_payload:
                    host_envelope["route_lineage"] = dict(
                        initial_join_route_lineage_payload
                    )
                    host_envelope["route_identity_source"] = (
                        "resolved_renewed_route_token_ref"
                    )
                if renewed_contract_revision is not None:
                    host_envelope["route_contract_revision_id"] = (
                        renewed_contract_revision.revision_id
                    )
                    host_envelope["route_contract_revision_source"] = (
                        "renewed_route_token_ref"
                    )
                result["host_envelope"] = host_envelope
        saved_context = get_branch_context_by_runtime_context_id(
            conn,
            project_id,
            runtime_context_id,
        )
        post_join_event_ids = [
            int(row["id"])
            for row in conn.execute(
                """
                SELECT id FROM task_timeline_events
                WHERE project_id = ? AND task_id = ? AND backlog_id = ?
                ORDER BY id
                """,
                (project_id, context.task_id, context.backlog_id),
            ).fetchall()
        ]
        pre_join_event_ids = [
            int(event.get("id") or 0)
            for event in timeline_events
            if int(event.get("id") or 0) > 0
        ]
        post_join_missing_lineage = (
            list(missing_lineage)
            if post_join_event_ids == pre_join_event_ids
            else ["timeline_changed_during_initial_join"]
        )
        canonical_binding, identity_mismatches = (
            _runtime_context_initial_join_canonical_identity_binding(
                project_id=project_id,
                original_context=context,
                saved_context=saved_context,
                result=result,
                governed_worker_id=governed_worker_id,
                contract_execution_id=contract_execution_id,
                expected_worker_session_id=expected_worker_session_id,
                expected_host_startup_id=expected_host_startup_id,
                expected_host_session_id=expected_host_session_id,
                route_identity=safe_route_identity,
                dispatch_identity_anchor=(
                    contract_dispatch_identity_anchor
                ),
                expected_missing_lineage=missing_lineage,
                actual_missing_lineage=post_join_missing_lineage,
                now_iso=str(body.get("now_iso") or ""),
            )
        )
        if identity_mismatches:
            conn.rollback()
            raise GovernanceError(
                "runtime_context_initial_join_canonical_identity_mismatch",
                "runtime-context initial join returned an identity that canonical audit would reject",
                409,
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": context.task_id,
                    "identity_mismatch_fields": identity_mismatches,
                    "mutation_performed": False,
                    "timeline_event_persisted": False,
                    "credential_rotated": False,
                    "fail_closed": True,
                    "next_legal_action": (
                        "repair_initial_join_identity_binding_and_retry_same_runtime_context"
                    ),
                },
            )
        result["canonical_identity_binding"] = canonical_binding
        audit_payload = {
            key: value
            for key, value in result.items()
            if key
            not in {
                "session_token",
                "session_token_hash",
                "fence_token",
                "host_envelope",
            }
        }
        audit_payload.update(
            {
                "action": "runtime_context_session_token_initial_join",
                "initial_join_identity_contract_version": (
                    "runtime_context.initial_join_identity.v2"
                ),
                "canonical_identity_binding_required": True,
                "caller_role": "observer",
                "raw_session_token_persisted": False,
                "raw_fence_token_persisted_to_timeline": False,
                "host_envelope_returned": True,
                "host_envelope_env_keys": [
                    "AMING_WORKER_SESSION_TOKEN",
                    "AMING_WORKER_FENCE_TOKEN",
                ],
                "reason": reason,
                "operator_principal_id": str(
                    session.get("principal_id") or ""
                ).strip(),
                "operator_session_id": str(
                    session.get("session_id") or ""
                ).strip(),
                "operator_role": session_role(session),
                "operator_session_role": session_role(session),
                "missing_lineage": missing_lineage,
                "runtime_context_id": runtime_context_id_for_branch_context(context),
                "contract_execution_id": contract_execution_id,
                "agent_id": str(result.get("agent_id") or ""),
                "actual_host_worker_id": str(
                    result.get("actual_host_worker_id") or ""
                ),
                "worker_session_id": str(result.get("worker_session_id") or ""),
                "host_startup_id": str(result.get("host_startup_id") or ""),
                "host_session_id": str(result.get("host_session_id") or ""),
            }
        )
        try:
            audit_event = task_timeline.record_event(
                conn,
                project_id=project_id,
                task_id=context.task_id,
                backlog_id=context.backlog_id,
                event_type=(
                    "observer.runtime_context_session_token_initial_join"
                ),
                event_kind="observer_command",
                phase="runtime_context_initial_join",
                status="accepted",
                actor=str(session.get("principal_id") or "observer"),
                payload=audit_payload,
            )
            initial_join_event_ref = (
                f"timeline:{audit_event.get('id', '')}"
            )
            anchor_payload = (
                _runtime_context_initial_join_identity_binding_anchor(
                    project_id=project_id,
                    runtime_context_id=runtime_context_id,
                    contract_execution_id=contract_execution_id,
                    task_id=context.task_id,
                    backlog_id=context.backlog_id,
                    initial_join_event_ref=initial_join_event_ref,
                    canonical_binding=canonical_binding,
                )
            )
            anchor_event = task_timeline.record_event(
                conn,
                project_id=project_id,
                task_id=context.task_id,
                backlog_id=context.backlog_id,
                event_type=(
                    "observer.runtime_context_session_token_initial_join_identity_binding"
                ),
                event_kind="observer_command",
                phase="runtime_context_initial_join_identity_binding",
                status="accepted",
                actor=str(session.get("principal_id") or "observer"),
                payload=anchor_payload,
            )
            identity_anchor_ref = f"timeline:{anchor_event.get('id', '')}"
            cutover_authority = (
                _runtime_context_initial_join_cutover_authority(
                    project_id=project_id,
                    runtime_context_id=runtime_context_id,
                    contract_execution_id=contract_execution_id,
                    task_id=context.task_id,
                    parent_task_id=parent_task_id,
                    backlog_id=context.backlog_id,
                    initial_join_event_ref=initial_join_event_ref,
                    identity_anchor_ref=identity_anchor_ref,
                    canonical_binding=canonical_binding,
                    identity_anchor=anchor_payload,
                    operator_principal_id=str(
                        locked_session.get("principal_id") or ""
                    ).strip(),
                    operator_session_id=str(
                        locked_session.get("session_id") or ""
                    ).strip(),
                    operator_role=session_role(locked_session),
                    created_at=str(audit_event.get("created_at") or "").strip(),
                )
            )
            cutover_audit_id = (
                _runtime_context_initial_join_cutover_audit_id(
                    cutover_authority
                )
            )
            conn.execute(
                """
                INSERT INTO parallel_branch_runtime_access_audit (
                    audit_id, project_id, runtime_context_id, task_id,
                    principal_id, session_id, role, view_name, decision,
                    reason, projection_hash, nodes_read_json, metadata_json,
                    created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    cutover_audit_id,
                    project_id,
                    runtime_context_id,
                    context.task_id,
                    str(locked_session.get("principal_id") or "").strip(),
                    str(locked_session.get("session_id") or "").strip(),
                    session_role(locked_session),
                    "initial_join_identity_cutover",
                    "allowed",
                    "canonical_identity_binding_required",
                    cutover_authority["cutover_hash"],
                    "[]",
                    json.dumps(cutover_authority, sort_keys=True),
                    cutover_authority["created_at"],
                ),
            )
        except Exception:
            conn.rollback()
            raise
        # Publish the durable auth transition and its process-local capsule
        # epoch as one reader-visible critical section.  Capsule fetch/publish
        # cannot observe committed join state under the prior epoch.
        with _ONBOARD_GUIDE_CAPSULE_LOCK:
            conn.commit()
            _onboard_guide_capsule_invalidate_runtime_context_auth_transition(
                project_id=project_id,
                backlog_id=str(context.backlog_id or "").strip(),
                contract_execution_id=contract_execution_id,
            )
        result["audit_event_ref"] = initial_join_event_ref
        result["audit_event_id"] = audit_event.get("id", "")
        result["canonical_identity_binding_anchor_ref"] = (
            f"timeline:{anchor_event.get('id', '')}"
        )
        result["canonical_identity_binding_anchor_hash"] = (
            anchor_payload["anchor_hash"]
        )
        result["canonical_identity_cutover_audit_id"] = cutover_audit_id
        result["canonical_identity_cutover_hash"] = (
            cutover_authority["cutover_hash"]
        )
        result["raw_tokens_persisted_to_timeline"] = False
        return result
    finally:
        conn.close()


def _runtime_context_authenticated_failed_qa_rejoin_continuity(
    *,
    context: Any,
    runtime_context_id: str,
    timeline_events: Sequence[Mapping[str, Any]],
    active_failed_qa: Mapping[str, Any],
) -> dict[str, Any]:
    """Validate one failed-QA revision identity across auth-only rotations."""

    from .parallel_branch_runtime import (
        runtime_context_secret_hash,
        runtime_context_session_token_ref,
    )

    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    expected_attempt = int(getattr(context, "attempt", 0) or 0)
    expected_retry_round = int(getattr(context, "retry_round", 0) or 0)
    expected_worker_id = str(getattr(context, "worker_id", "") or "").strip()
    expected_worker_slot_id = str(
        getattr(context, "worker_slot_id", "")
        or getattr(context, "worker_id", "")
        or ""
    ).strip()
    expected_fence_token_hash = runtime_context_secret_hash(
        str(getattr(context, "fence_token", "") or "")
    )
    active_session_token_ref = runtime_context_session_token_ref(context)
    target_project_root = _runtime_context_effective_target_project_root(context)
    assigned_worktree = str(getattr(context, "worktree_path", "") or "").strip()
    if (
        not runtime_context_id
        or not task_id
        or not active_session_token_ref
        or expected_attempt <= 1
        or expected_retry_round <= 0
        or not expected_worker_id
        or not expected_worker_slot_id
        or not expected_fence_token_hash
        or not target_project_root
    ):
        return {}
    if assigned_worktree and Path(target_project_root).resolve() != Path(
        assigned_worktree
    ).resolve():
        return {}

    failed_qa_event_id = int(active_failed_qa.get("event_id") or 0)
    authoritative_rejoin: dict[str, Any] = {}
    latest_rotation: dict[str, Any] = {}
    passing_statuses = {"accepted", "ok", "pass", "passed", "succeeded", "success"}
    for event in sorted(
        (item for item in timeline_events if isinstance(item, Mapping)),
        key=lambda item: int(item.get("id") or 0),
    ):
        event_id = int(event.get("id") or 0)
        if event_id <= failed_qa_event_id:
            continue
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        event_runtime_context_id = str(
            payload.get("runtime_context_id") or ""
        ).strip()
        event_task_id = str(
            event.get("task_id") or payload.get("task_id") or ""
        ).strip()
        event_backlog_id = str(
            event.get("backlog_id") or payload.get("backlog_id") or ""
        ).strip()
        event_status = str(event.get("status") or "").strip().lower()
        event_kind = str(event.get("event_kind") or "").strip().lower()
        event_type = str(event.get("event_type") or "").strip().lower()

        worker_commit = bool(
            event_kind == "worker_commit"
            or event_type in {
                "mf_subagent.worker_commit",
                "runtime_context.worker_commit",
            }
            or str(payload.get("action") or "").strip()
            == "record_worker_commit"
        )
        if worker_commit and event_status in passing_statuses:
            if (
                event_task_id == task_id
                and event_backlog_id == backlog_id
                and event_runtime_context_id in {"", runtime_context_id}
            ):
                return {}
            continue

        rejoin_event = bool(
            event_type == "observer.runtime_context_session_token_rejoin"
            or (
                event_kind == "observer_command"
                and str(payload.get("action") or "").strip()
                == "runtime_context_session_token_rejoin"
            )
        )
        if not rejoin_event or event_status not in passing_statuses:
            continue
        if event_runtime_context_id != runtime_context_id:
            continue
        if event_task_id != task_id or event_backlog_id != backlog_id:
            return {}

        event_target_project_root = (
            _timeline_first_deep_text(payload, "target_project_root")
            or _timeline_first_deep_text(payload, "worktree_path")
        )
        identity_matches = bool(
            str(payload.get("parent_task_id") or "").strip() == parent_task_id
            and int(payload.get("attempt") or 0) == expected_attempt
            and int(payload.get("retry_round") or 0) == expected_retry_round
            and str(payload.get("current_status") or "").strip()
            == "worktree_ready"
            and str(payload.get("worker_id") or "").strip()
            == expected_worker_id
            and str(
                payload.get("worker_slot_id")
                or payload.get("worker_id")
                or ""
            ).strip()
            == expected_worker_slot_id
            and str(payload.get("fence_token_hash") or "").strip()
            == expected_fence_token_hash
            and (
                not event_target_project_root
                or Path(event_target_project_root).resolve()
                == Path(target_project_root).resolve()
            )
        )
        event_session_token_ref = str(
            payload.get("session_token_ref") or ""
        ).strip()
        if not identity_matches or not event_session_token_ref:
            return {}
        event_route_identity = (
            payload.get("route_identity")
            if isinstance(payload.get("route_identity"), Mapping)
            else {}
        )

        latest_rotation = {
            "event_id": event_id,
            "event_ref": f"timeline:{event_id}",
            "session_token_ref": event_session_token_ref,
            "route_identity": dict(event_route_identity),
        }
        if (
            _truthy_flag(payload.get("reopen_for_revision"))
            and _truthy_flag(payload.get("timeline_reopen_for_revision"))
        ):
            authoritative_rejoin = {
                "event_id": event_id,
                "event_ref": f"timeline:{event_id}",
                "session_token_ref": event_session_token_ref,
                "route_identity": dict(event_route_identity),
            }

    if (
        not authoritative_rejoin
        or not latest_rotation
        or latest_rotation.get("session_token_ref") != active_session_token_ref
    ):
        return {}
    return {
        "schema_version": (
            "runtime_context.authenticated_failed_qa_rejoin_continuity.v1"
        ),
        "source": "accepted_runtime_context_rejoin_history",
        "server_derived": True,
        "failed_qa_event_ref": active_failed_qa.get("source_ref") or "",
        "authoritative_rejoin_event_ref": authoritative_rejoin["event_ref"],
        "latest_rotation_event_ref": latest_rotation["event_ref"],
        "authoritative_rejoin_route_identity": dict(
            authoritative_rejoin.get("route_identity") or {}
        ),
        "latest_rotation_route_identity": dict(
            latest_rotation.get("route_identity") or {}
        ),
        "active_session_token_ref": active_session_token_ref,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "backlog_id": backlog_id,
        "worker_id": expected_worker_id,
        "worker_slot_id": expected_worker_slot_id,
        "target_project_root": target_project_root,
        "fence_token_hash": expected_fence_token_hash,
        "attempt": expected_attempt,
        "retry_round": expected_retry_round,
    }


def _runtime_context_failed_qa_revision_rejoin_allowed(
    *,
    conn,
    context: Any,
    runtime_context_id: str,
    timeline_events: Sequence[Mapping[str, Any]],
) -> bool:
    from .parallel_branch_runtime import (
        FAILED_QA_REVISION_REJOIN_STATES,
        STATE_WORKTREE_READY,
    )

    context_status = str(getattr(context, "status", "") or "").strip()
    if context_status not in FAILED_QA_REVISION_REJOIN_STATES:
        if context_status != STATE_WORKTREE_READY:
            return False
        active_failed_qa = (
            _runtime_context_authenticated_failed_qa_timeline_boundary(
                conn=conn,
                context=context,
                runtime_context_id=runtime_context_id,
                timeline_events=timeline_events,
            )
        )
        if not active_failed_qa:
            return False
        rejoin_continuity = (
            _runtime_context_authenticated_failed_qa_rejoin_continuity(
                context=context,
                runtime_context_id=runtime_context_id,
                timeline_events=timeline_events,
                active_failed_qa=active_failed_qa,
            )
        )
        return bool(rejoin_continuity)
    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    runtime_id = str(runtime_context_id or "").strip()
    blocking_statuses = {"blocked", "error", "fail", "failed", "invalid", "rejected"}
    passing_statuses = {"accepted", "ok", "pass", "passed", "succeeded", "success"}
    qa_kinds = {"independent_verification", "qa_review", "qa_verification"}
    latest_qa_status = ""

    for event in sorted(
        (item for item in timeline_events if isinstance(item, Mapping)),
        key=lambda item: int(item.get("id") or 0),
    ):
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        verification = (
            event.get("verification")
            if isinstance(event.get("verification"), Mapping)
            else {}
        )
        event_task_id = str(
            event.get("task_id")
            or payload.get("task_id")
            or verification.get("task_id")
            or ""
        ).strip()
        if event_task_id and task_id and event_task_id != task_id:
            continue
        event_backlog_id = str(
            event.get("backlog_id") or payload.get("backlog_id") or ""
        ).strip()
        if event_backlog_id and backlog_id and event_backlog_id != backlog_id:
            continue
        event_runtime_id = str(
            payload.get("runtime_context_id")
            or verification.get("runtime_context_id")
            or ""
        ).strip()
        if event_runtime_id and runtime_id and event_runtime_id != runtime_id:
            continue

        event_kind = str(event.get("event_kind") or "").strip().lower()
        event_type = str(event.get("event_type") or "").strip().lower()
        status = str(
            event.get("status")
            or verification.get("result")
            or payload.get("status")
            or ""
        ).strip().lower()
        if status not in blocking_statuses | passing_statuses:
            continue

        qa_marker = " ".join(
            str(value or "").strip().lower()
            for value in (
                event_kind,
                event_type,
                payload.get("reviewer_role"),
                payload.get("requirement_id"),
                verification.get("requirement_id"),
            )
            if str(value or "").strip()
        )
        if (
            event_kind in qa_kinds
            or "independent_verification" in qa_marker
            or "independent_qa" in qa_marker
        ):
            latest_qa_status = status
    return latest_qa_status in blocking_statuses


def _runtime_context_project_task_branch_runtime_rows(
    conn,
    *,
    project_id: str,
    task_id: str,
) -> list[dict[str, Any]]:
    """Read the server-owned project/task runtime binding without guessing."""

    try:
        rows = conn.execute(
            """
            SELECT project_id, task_id, runtime_context_id, backlog_id,
                   target_project_root, worktree_path
            FROM parallel_branch_runtime_contexts
            WHERE project_id = ? AND task_id = ?
            ORDER BY updated_at DESC, runtime_context_id
            """,
            (str(project_id or "").strip(), str(task_id or "").strip()),
        ).fetchall()
    except (sqlite3.Error, KeyError, TypeError):
        return []
    return [dict(row) for row in rows]


def _runtime_context_server_derived_legacy_qa_runtime_binding(
    conn,
    *,
    context: Any,
    runtime_context_id: str,
    event: Mapping[str, Any],
    qa_proof: Mapping[str, Any],
    event_commit: str,
) -> dict[str, Any]:
    """Bind legacy QA events with no runtime id to one server DB context."""

    project_id = str(getattr(context, "project_id", "") or "").strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    context_runtime_context_id = str(
        getattr(context, "runtime_context_id", "") or ""
    ).strip()
    event_project_id = str(event.get("project_id") or "").strip()
    runtime_id = str(runtime_context_id or "").strip()
    expected_target_root = _runtime_context_effective_target_project_root(context)
    expected_worktree = str(getattr(context, "worktree_path", "") or "").strip()
    if (
        not project_id
        or event_project_id != project_id
        or not task_id
        or not backlog_id
        or not runtime_id
        or context_runtime_context_id != runtime_id
        or not expected_target_root
        or not expected_worktree
    ):
        return {}

    rows = _runtime_context_project_task_branch_runtime_rows(
        conn,
        project_id=project_id,
        task_id=task_id,
    )
    if len(rows) != 1:
        return {}
    row = rows[0]
    row_runtime_context_id = str(row.get("runtime_context_id") or "").strip()
    row_backlog_id = str(row.get("backlog_id") or "").strip()
    row_target_root = str(row.get("target_project_root") or "").strip()
    row_worktree = str(row.get("worktree_path") or "").strip()
    row_effective_target_root = row_target_root or row_worktree
    qa_query_root = str(qa_proof.get("query_root") or "").strip()
    if (
        str(row.get("project_id") or "").strip() != project_id
        or str(row.get("task_id") or "").strip() != task_id
        or row_runtime_context_id != runtime_id
        or row_backlog_id != backlog_id
        or not row_effective_target_root
        or not row_worktree
        or not qa_query_root
    ):
        return {}

    try:
        expected_root_path = Path(expected_target_root).resolve()
        expected_worktree_path = Path(expected_worktree).resolve()
        row_target_path = Path(row_effective_target_root).resolve()
        row_worktree_path = Path(row_worktree).resolve()
        qa_query_root_path = Path(qa_query_root).resolve()
    except (OSError, RuntimeError, TypeError, ValueError):
        return {}
    if not (
        expected_root_path
        == expected_worktree_path
        == row_target_path
        == row_worktree_path
        == qa_query_root_path
    ):
        return {}

    expected_scope_ref = _qa_scope_binding_ref(
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
        commit_sha=event_commit,
    )
    if str(qa_proof.get("qa_scope_binding_ref") or "").strip() != expected_scope_ref:
        return {}
    return {
        "schema_version": "runtime_context.timeline_runtime_binding.v1",
        "source": "server_db_unique_project_task_branch_runtime_context",
        "server_derived": True,
        "runtime_context_id": row_runtime_context_id,
        "project_id": project_id,
        "task_id": task_id,
        "backlog_id": backlog_id,
        "target_project_root": str(expected_root_path),
        "qa_scope_binding_ref": expected_scope_ref,
    }


def _runtime_context_latest_authenticated_qa_timeline_verdict(
    *,
    conn,
    context: Any,
    runtime_context_id: str,
    timeline_events: Sequence[Mapping[str, Any]],
    before_event_id: int = 0,
) -> dict[str, Any]:
    """Return the latest server-authenticated QA timeline verdict.

    Historical PASS rows are immutable audit evidence, but they are not
    current authority once a newer authenticated QA verdict exists.  Keep the
    selection neutral here so callers can apply either the failed-QA rework
    boundary or the current merge-readiness barrier without falling back to an
    older PASS.
    """

    from . import task_timeline

    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    blocking_statuses = {"blocked", "error", "fail", "failed", "invalid", "rejected"}
    passing_statuses = {"accepted", "ok", "pass", "passed", "succeeded", "success"}
    latest: dict[str, Any] = {}
    for event in sorted(
        (item for item in timeline_events if isinstance(item, Mapping)),
        key=lambda item: int(item.get("id") or 0),
    ):
        event_id = int(event.get("id") or 0)
        if event_id <= 0 or (before_event_id > 0 and event_id >= before_event_id):
            continue
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        verification = (
            event.get("verification")
            if isinstance(event.get("verification"), Mapping)
            else {}
        )
        postmerge_failed_boundary = (
            payload.get("postmerge_failed_qa_boundary_authority")
            if isinstance(
                payload.get("postmerge_failed_qa_boundary_authority"), Mapping
            )
            else {}
        )
        postmerge_failed_boundary_valid = bool(
            str(postmerge_failed_boundary.get("schema_version") or "").strip()
            == "contract_runtime.postmerge_failed_qa_boundary_authority.v1"
            and postmerge_failed_boundary.get("server_derived") is True
            and postmerge_failed_boundary.get("db_verified") is True
            and postmerge_failed_boundary.get("audit_only") is True
            and postmerge_failed_boundary.get("close_satisfying") is False
            and postmerge_failed_boundary.get("failed_qa_rework_eligible") is True
            and str(postmerge_failed_boundary.get("authority_hash") or "").strip()
            == stable_sha256(
                {
                    key: value
                    for key, value in postmerge_failed_boundary.items()
                    if key != "authority_hash"
                }
            )
            and str(postmerge_failed_boundary.get("project_id") or "").strip()
            == str(event.get("project_id") or "").strip()
            and str(postmerge_failed_boundary.get("backlog_id") or "").strip()
            == backlog_id
            and str(postmerge_failed_boundary.get("runtime_context_id") or "").strip()
            == str(runtime_context_id or "").strip()
            and str(postmerge_failed_boundary.get("task_id") or "").strip()
            == task_id
            and str(postmerge_failed_boundary.get("parent_task_id") or "").strip()
            == str(getattr(context, "parent_task_id", "") or "").strip()
        )
        qa_scope_task_id = (
            str(
                postmerge_failed_boundary.get("qa_graph_trace_task_id") or ""
            ).strip()
            if postmerge_failed_boundary_valid
            else task_id
        )
        event_task_id = str(
            event.get("task_id")
            or payload.get("task_id")
            or verification.get("task_id")
            or ""
        ).strip()
        event_backlog_id = str(
            event.get("backlog_id") or payload.get("backlog_id") or ""
        ).strip()
        if qa_scope_task_id and event_task_id != qa_scope_task_id:
            continue
        if backlog_id and event_backlog_id != backlog_id:
            continue
        event_kind = str(event.get("event_kind") or "").strip().lower()
        event_type = str(event.get("event_type") or "").strip().lower()
        qa_marker = " ".join(
            str(value or "").strip().lower()
            for value in (
                event_kind,
                event_type,
                payload.get("reviewer_role"),
                payload.get("requirement_id"),
                verification.get("requirement_id"),
            )
            if str(value or "").strip()
        )
        if not (
            event_kind in {"independent_verification", "qa_verification"}
            or "independent_verification" in qa_marker
            or "independent_qa" in qa_marker
        ):
            continue

        gate = (
            payload.get("contract_gate_decision")
            if isinstance(payload.get("contract_gate_decision"), Mapping)
            else {}
        )
        source_authority = (
            payload.get("source_backed_contract_gate_authority")
            if isinstance(
                payload.get("source_backed_contract_gate_authority"), Mapping
            )
            else {}
        )
        qa_proof = (
            source_authority.get("qa_session_proof")
            if isinstance(source_authority.get("qa_session_proof"), Mapping)
            else {}
        )
        status = str(
            event.get("status")
            or verification.get("result")
            or payload.get("status")
            or ""
        ).strip().lower()
        actor = str(event.get("actor") or "").strip()
        event_commit = str(
            event.get("commit_sha")
            or payload.get("commit_sha")
            or qa_proof.get("commit_sha")
            or ""
        ).strip()
        if postmerge_failed_boundary_valid and (
            str(
                postmerge_failed_boundary.get("candidate_commit_sha") or ""
            )
            .strip()
            .lower()
            != event_commit.lower()
        ):
            continue
        qa_observer_impersonation_forbidden = (
            qa_proof.get("observer_impersonation") is False
            and (
                "observer_impersonation" not in payload
                or payload.get("observer_impersonation") is False
            )
        )
        authenticated = bool(
            task_timeline._source_backed_qa_session_authority_valid(
                source_authority,
                conn=conn,
            )
            and gate.get("ok") is True
            and gate.get("primary_decision_source") is True
            and str(gate.get("source_of_authority") or "").strip()
            in {"contract_runtime", "qa_session_verification"}
            and str(gate.get("required_role") or "").strip() == "qa"
            and not list(gate.get("missing_proof_fields") or [])
            and str(source_authority.get("source") or "").strip()
            == "server_qa_session_verification"
            and str(source_authority.get("source_of_authority") or "").strip()
            == "qa_session_verification"
            and qa_proof.get("verified") is True
            and str(qa_proof.get("source") or "").strip()
            == "authenticated_qa_session"
            and str(qa_proof.get("role") or "").strip() == "qa"
            and bool(str(qa_proof.get("qa_session_id") or "").strip())
            and bool(str(qa_proof.get("qa_scope_binding_ref") or "").strip())
            and str(qa_proof.get("project_id") or "").strip()
            == str(event.get("project_id") or "").strip()
            and str(qa_proof.get("task_id") or "").strip()
            == qa_scope_task_id
            and str(qa_proof.get("backlog_id") or "").strip() == backlog_id
            and str(qa_proof.get("event_kind") or "").strip()
            in {"independent_verification", "qa_verification"}
            and str(qa_proof.get("evidence_status") or "").strip().lower()
            == status
            and str(qa_proof.get("principal_id") or "").strip() == actor
            and re.fullmatch(r"[0-9a-f]{40,64}", event_commit)
            and str(qa_proof.get("commit_sha") or "").strip() == event_commit
            and bool(str(source_authority.get("authority_hash") or "").strip())
            and qa_observer_impersonation_forbidden
        )
        if not authenticated or status not in blocking_statuses | passing_statuses:
            continue
        premerge_receipt = (
            payload.get("premerge_candidate_qa_receipt_authority")
            if isinstance(
                payload.get("premerge_candidate_qa_receipt_authority"),
                Mapping,
            )
            else {}
        )
        premerge_receipt_only = bool(
            str(premerge_receipt.get("schema_version") or "").strip()
            == "contract_runtime.premerge_candidate_qa_receipt_authority.v1"
            and premerge_receipt.get("server_derived") is True
            and premerge_receipt.get("qa_verdict_passing") is True
            and premerge_receipt.get("materialize_receipt_only") is True
            and premerge_receipt.get("materialize_satisfying") is True
            and premerge_receipt.get("close_satisfying") is False
            and premerge_receipt.get("observer_merge_written") is False
            and premerge_receipt.get("global_observer_merge_ready") is False
            and str(premerge_receipt.get("project_id") or "").strip()
            == str(event.get("project_id") or "").strip()
            and str(premerge_receipt.get("backlog_id") or "").strip()
            == backlog_id
            and str(premerge_receipt.get("task_id") or "").strip()
            == task_id
            and str(
                premerge_receipt.get("runtime_context_id") or ""
            ).strip()
            == str(runtime_context_id or "").strip()
            and str(premerge_receipt.get("candidate_commit_sha") or "").strip()
            == event_commit
            and str(premerge_receipt.get("qa_session_id") or "").strip()
            == str(qa_proof.get("qa_session_id") or "").strip()
            and str(premerge_receipt.get("authority_hash") or "").strip()
            == stable_sha256(
                {
                    key: value
                    for key, value in premerge_receipt.items()
                    if key != "authority_hash"
                }
            )
        )
        explicit_runtime_context_ids = {
            str(value or "").strip()
            for value in (
                payload.get("runtime_context_id"),
                verification.get("runtime_context_id"),
            )
            if str(value or "").strip()
        }
        if postmerge_failed_boundary_valid:
            runtime_context_binding = {
                "schema_version": "runtime_context.timeline_runtime_binding.v1",
                "source": "server_postmerge_failed_qa_boundary_authority",
                "server_derived": True,
                "runtime_context_id": str(runtime_context_id or "").strip(),
                "project_id": str(getattr(context, "project_id", "") or "").strip(),
                "task_id": task_id,
                "backlog_id": backlog_id,
                "qa_scope_task_id": qa_scope_task_id,
            }
        elif explicit_runtime_context_ids:
            if explicit_runtime_context_ids != {
                str(runtime_context_id or "").strip()
            }:
                continue
            runtime_context_binding = {
                "schema_version": "runtime_context.timeline_runtime_binding.v1",
                "source": "timeline_event_explicit_runtime_context_id",
                "server_derived": False,
                "runtime_context_id": str(runtime_context_id or "").strip(),
            }
        else:
            runtime_context_binding = (
                _runtime_context_server_derived_legacy_qa_runtime_binding(
                    conn,
                    context=context,
                    runtime_context_id=runtime_context_id,
                    event=event,
                    qa_proof=qa_proof,
                    event_commit=event_commit,
                )
            )
            if not runtime_context_binding:
                continue
        latest = {
            "schema_version": "runtime_context.authenticated_qa_timeline_verdict.v1",
            "source": "server_qa_session_verification",
            "source_of_authority": "qa_session_verification",
            "event_id": event_id,
            "source_ref": f"timeline:{event_id}",
            "created_at": str(event.get("created_at") or "").strip(),
            "execution_state_revision": int(
                gate.get("execution_state_revision") or 0
            ),
            "status": status,
            "commit_sha": event_commit,
            "actor": actor,
            "qa_session_id": str(qa_proof.get("qa_session_id") or "").strip(),
            "qa_scope_binding_ref": str(
                qa_proof.get("qa_scope_binding_ref") or ""
            ).strip(),
            "authority_hash": str(
                source_authority.get("authority_hash") or ""
            ).strip(),
            "runtime_context_id": runtime_context_id,
            "runtime_context_binding_source": runtime_context_binding["source"],
            "runtime_context_binding_server_derived": runtime_context_binding[
                "server_derived"
            ],
            "runtime_context_binding": runtime_context_binding,
            "premerge_candidate_receipt_only": premerge_receipt_only,
            "premerge_candidate_receipt_authority_hash": str(
                premerge_receipt.get("authority_hash") or ""
            ).strip()
            if premerge_receipt_only
            else "",
            "task_id": task_id,
            "backlog_id": backlog_id,
        }
    return latest


def _runtime_context_authenticated_failed_qa_timeline_boundary(
    *,
    conn,
    context: Any,
    runtime_context_id: str,
    timeline_events: Sequence[Mapping[str, Any]],
    before_event_id: int = 0,
) -> dict[str, Any]:
    """Return the latest active server-authenticated failed-QA boundary."""

    latest = _runtime_context_latest_authenticated_qa_timeline_verdict(
        conn=conn,
        context=context,
        runtime_context_id=runtime_context_id,
        timeline_events=timeline_events,
        before_event_id=before_event_id,
    )
    if str(latest.get("status") or "") not in {
        "blocked",
        "error",
        "fail",
        "failed",
        "invalid",
        "rejected",
    }:
        return {}
    latest = dict(latest)
    latest["schema_version"] = (
        "runtime_context.authenticated_failed_qa_timeline_boundary.v1"
    )
    return latest


def _runtime_context_failed_qa_revision_rejoin_marker(
    *,
    conn,
    context: Any,
    runtime_context_id: str,
    timeline_events: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Return the latest accepted same-context failed-QA revision boundary."""

    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    expected_attempt = int(getattr(context, "attempt", 0) or 0)
    expected_retry_round = int(getattr(context, "retry_round", 0) or 0)
    from .parallel_branch_runtime import (
        runtime_context_fence_token_verifier,
        runtime_context_secret_hash,
        runtime_context_session_token_ref,
    )

    active_session_token_ref = runtime_context_session_token_ref(context)
    expected_worker_id = str(getattr(context, "worker_id", "") or "").strip()
    expected_worker_slot_id = str(
        getattr(context, "worker_slot_id", "")
        or getattr(context, "worker_id", "")
        or ""
    ).strip()
    expected_target_project_root = _runtime_context_effective_target_project_root(
        context
    )
    expected_fence_token_hash = runtime_context_fence_token_verifier(context)
    successor_contract_evidence = (
        _runtime_context_failed_qa_revision_contract_runtime_evidence(
            conn,
            project_id=str(getattr(context, "project_id", "") or ""),
            context=context,
        )
    )
    successor_dispatch_authority = (
        successor_contract_evidence.get(
            "successor_dispatch_revision_authority"
        )
        if isinstance(
            successor_contract_evidence.get(
                "successor_dispatch_revision_authority"
            ),
            Mapping,
        )
        else {}
    )
    if (
        not runtime_context_id
        or not task_id
        or expected_attempt <= 1
        or (expected_retry_round <= 0 and not successor_dispatch_authority)
    ):
        return {}
    expected_route_identity = _runtime_context_latest_route_identity(conn, context)

    # A fresh failed-QA replacement uses initial-join, not revision-rejoin.
    # Bind that pre-lineage host transition to the canonical successor
    # dispatch and its independently persisted identity anchor before allowing
    # the replacement context to project its own read/startup setup evidence.
    # This is deliberately context-local: it never reopens or duplicates the
    # globally completed worker-read/startup Contract lines.
    if successor_dispatch_authority:
        route_identity_hash = _stable_public_hash(expected_route_identity)
        initial_join_candidates: list[tuple[Mapping[str, Any], Mapping[str, Any]]] = []
        identity_anchor_candidates: list[Mapping[str, Any]] = []
        safe_ref_reissue_candidates = [
            event
            for event in timeline_events
            if isinstance(event, Mapping)
            and isinstance(event.get("payload"), Mapping)
            and str(event["payload"].get("action") or "").strip()
            == "runtime_context_session_token_reissue"
        ]
        for event in timeline_events:
            if not isinstance(event, Mapping):
                continue
            event_payload = (
                event.get("payload")
                if isinstance(event.get("payload"), Mapping)
                else {}
            )
            event_status = str(event.get("status") or "").strip().lower()
            if event_status not in {
                "accepted",
                "ok",
                "pass",
                "passed",
                "success",
                "succeeded",
            }:
                continue
            action = str(event_payload.get("action") or "").strip()
            if action == "runtime_context_session_token_reissue":
                continue
            if action == (
                "runtime_context_session_token_initial_join_identity_binding_anchor"
            ):
                identity_anchor_candidates.append(event)
                continue
            if (
                str(event.get("event_type") or "").strip()
                != "observer.runtime_context_session_token_initial_join"
                or str(event.get("event_kind") or "").strip()
                != "observer_command"
                or str(event.get("phase") or "").strip()
                != "runtime_context_initial_join"
                or action != "runtime_context_session_token_initial_join"
            ):
                continue
            canonical_binding = (
                event_payload.get("canonical_identity_binding")
                if isinstance(
                    event_payload.get("canonical_identity_binding"), Mapping
                )
                else {}
            )
            binding_core = {
                key: value
                for key, value in canonical_binding.items()
                if key != "binding_hash"
            }
            dispatch_anchor = (
                canonical_binding.get("contract_dispatch_identity_anchor")
                if isinstance(
                    canonical_binding.get("contract_dispatch_identity_anchor"),
                    Mapping,
                )
                else {}
            )
            initial_join_event_ref = f"timeline:{event.get('id', '')}"
            initial_join_session_ref = str(
                event_payload.get("session_token_ref") or ""
            ).strip()
            initial_join_fence_hash = str(
                event_payload.get("fence_token_hash") or ""
            ).strip()
            current_initial_join_binding = bool(
                initial_join_session_ref == active_session_token_ref
                and initial_join_fence_hash == expected_fence_token_hash
            )
            pinned_reissue_matches = []
            if not current_initial_join_binding:
                for reissue_event in safe_ref_reissue_candidates:
                    reissue_payload = (
                        reissue_event.get("payload")
                        if isinstance(reissue_event.get("payload"), Mapping)
                        else {}
                    )
                    reissue_authority = (
                        reissue_payload.get("safe_ref_reissue_authority")
                        if isinstance(
                            reissue_payload.get("safe_ref_reissue_authority"),
                            Mapping,
                        )
                        else {}
                    )
                    reissue_source = (
                        reissue_payload.get(
                            "safe_ref_session_authority_source"
                        )
                        if isinstance(
                            reissue_payload.get(
                                "safe_ref_session_authority_source"
                            ),
                            Mapping,
                        )
                        else {}
                    )
                    if (
                        int(reissue_event.get("id") or 0)
                        > int(event.get("id") or 0)
                        and str(
                            reissue_event.get("status") or ""
                        ).strip().lower()
                        in {
                            "accepted",
                            "ok",
                            "pass",
                            "passed",
                            "success",
                            "succeeded",
                        }
                        and str(reissue_event.get("event_type") or "").strip()
                        == "mf_subagent.session_token_reissue"
                        and str(reissue_event.get("event_kind") or "").strip()
                        == "mf_subagent_session_token_reissue"
                        and str(reissue_event.get("phase") or "").strip()
                        == "runtime_context_recovery"
                        and str(reissue_event.get("task_id") or "").strip()
                        == task_id
                        and str(reissue_event.get("backlog_id") or "").strip()
                        == backlog_id
                        and str(
                            reissue_payload.get("runtime_context_id") or ""
                        ).strip()
                        == runtime_context_id
                        and str(
                            reissue_payload.get("contract_execution_id") or ""
                        ).strip()
                        == str(
                            successor_contract_evidence.get(
                                "contract_execution_id"
                            )
                            or ""
                        ).strip()
                        and str(
                            reissue_payload.get("session_token_ref") or ""
                        ).strip()
                        == active_session_token_ref
                        and str(
                            reissue_payload.get("fence_token_hash") or ""
                        ).strip()
                        == expected_fence_token_hash
                        and str(
                            reissue_payload.get("authorization_source") or ""
                        ).strip()
                        == "safe_ref_prestartup_reissue_authority"
                        and reissue_payload.get("session_token_persisted") is False
                        and reissue_payload.get("raw_session_token_persisted")
                        is False
                        and reissue_payload.get("raw_fence_token_persisted")
                        is False
                        and reissue_payload.get(
                            "raw_fence_token_persisted_to_timeline"
                        )
                        is False
                        and dict(reissue_payload.get("route_identity") or {})
                        == expected_route_identity
                        and str(
                            reissue_authority.get("initial_join_event_ref")
                            or ""
                        ).strip()
                        == initial_join_event_ref
                        and str(
                            reissue_authority.get(
                                "session_authority_event_ref"
                            )
                            or ""
                        ).strip()
                        == initial_join_event_ref
                        and str(
                            reissue_authority.get("session_authority_kind")
                            or ""
                        ).strip()
                        == "initial_join"
                        and reissue_authority.get(
                            "pre_read_pinned_replacement_authority"
                        )
                        is True
                        and reissue_authority.get("pre_read_special_authority")
                        is False
                        and reissue_authority.get(
                            "stage_checkpoint_server_verified"
                        )
                        is True
                        and re.fullmatch(
                            r"sha256:[0-9a-f]{64}",
                            str(
                                reissue_authority.get("authority_hash") or ""
                            ).strip(),
                        )
                        and str(reissue_source.get("event_ref") or "").strip()
                        == initial_join_event_ref
                        and str(
                            reissue_source.get("source_kind") or ""
                        ).strip()
                        == "initial_join"
                        and str(
                            reissue_source.get("normalized_capability_kind")
                            or ""
                        ).strip()
                        == "initial_join"
                    ):
                        pinned_reissue_matches.append(reissue_event)
            expected_values = {
                "project_id": str(
                    getattr(context, "project_id", "") or ""
                ).strip(),
                "runtime_context_id": runtime_context_id,
                "contract_execution_id": str(
                    successor_contract_evidence.get("contract_execution_id")
                    or ""
                ).strip(),
                "task_id": task_id,
                "parent_task_id": parent_task_id,
                "backlog_id": backlog_id,
                "worker_id": expected_worker_id,
                "worker_slot_id": expected_worker_slot_id,
                "target_project_root": expected_target_project_root,
            }
            if (
                int(event.get("id") or 0) <= 0
                or str(event.get("task_id") or "").strip() != task_id
                or str(event.get("backlog_id") or "").strip() != backlog_id
                or any(
                    str(event_payload.get(field) or "").strip() != expected
                    for field, expected in expected_values.items()
                    if field != "target_project_root"
                )
                or not (
                    current_initial_join_binding
                    or len(pinned_reissue_matches) == 1
                )
                or not initial_join_session_ref
                or not initial_join_fence_hash
                or event_payload.get("raw_session_token_persisted") is not False
                or event_payload.get("raw_fence_token_persisted_to_timeline")
                is not False
                or event_payload.get("session_token_persisted") is not False
                or event_payload.get("canonical_identity_binding_required")
                is not True
                or str(canonical_binding.get("schema_version") or "").strip()
                != "runtime_context.initial_join_canonical_identity_binding.v1"
                or canonical_binding.get("server_derived") is not True
                or any(
                    str(canonical_binding.get(field) or "").strip()
                    != expected
                    for field, expected in expected_values.items()
                )
                or str(
                    canonical_binding.get("session_token_ref") or ""
                ).strip()
                != initial_join_session_ref
                or str(canonical_binding.get("governed_worker_id") or "").strip()
                != expected_worker_id
                or str(canonical_binding.get("agent_id") or "").strip()
                != expected_worker_id
                or str(
                    canonical_binding.get("actual_host_worker_id") or ""
                ).strip()
                != expected_worker_id
                or str(canonical_binding.get("context_status") or "").strip()
                != "worktree_ready"
                or str(
                    canonical_binding.get("last_recovery_action") or ""
                ).strip()
                != "mf_subagent_initial_join_issued"
                or list(canonical_binding.get("missing_lineage") or [])
                != ["mf_subagent_read_receipt", "mf_subagent_startup"]
                or canonical_binding.get("raw_credentials_persisted") is not False
                or canonical_binding.get(
                    "contract_dispatch_identity_anchor_required"
                )
                is not True
                or str(canonical_binding.get("binding_hash") or "").strip()
                != _stable_public_hash(binding_core)
                or dict(canonical_binding.get("route_identity") or {})
                != expected_route_identity
                or str(dispatch_anchor.get("schema_version") or "").strip()
                != "runtime_context.pre_lineage_legacy_dispatch_identity_anchor.v1"
                or dispatch_anchor.get("server_derived") is not True
                or str(dispatch_anchor.get("source") or "").strip()
                != "ContractRuntime.completed_lines.observer_dispatch_bounded_workers"
                or str(dispatch_anchor.get("source_ref") or "").strip()
                != str(
                    successor_dispatch_authority.get("dispatch_source_ref")
                    or ""
                ).strip()
                or any(
                    str(dispatch_anchor.get(field) or "").strip()
                    != expected
                    for field, expected in expected_values.items()
                    if field
                    in {
                        "project_id",
                        "runtime_context_id",
                        "contract_execution_id",
                        "task_id",
                        "parent_task_id",
                        "backlog_id",
                        "worker_id",
                        "worker_slot_id",
                        "target_project_root",
                    }
                )
                or dict(dispatch_anchor.get("route_identity") or {})
                != expected_route_identity
                or dict(event_payload.get("route_identity") or {})
                != expected_route_identity
            ):
                continue
            initial_join_candidates.append((event, canonical_binding))

        if len(initial_join_candidates) == 1:
            initial_join_event, canonical_binding = initial_join_candidates[0]
            initial_join_event_id = int(initial_join_event.get("id") or 0)
            initial_join_event_ref = f"timeline:{initial_join_event_id}"
            matching_anchors: list[Mapping[str, Any]] = []
            for event in identity_anchor_candidates:
                event_payload = (
                    event.get("payload")
                    if isinstance(event.get("payload"), Mapping)
                    else {}
                )
                anchor_core = {
                    key: value
                    for key, value in event_payload.items()
                    if key
                    not in {
                        "anchor_hash",
                        "contract_gate_decision",
                        "meta_contract_gate",
                        "agent_facing_decision_source",
                        "meta_contract_gate_decision_source",
                    }
                }
                if (
                    int(event.get("id") or 0) <= initial_join_event_id
                    or str(event.get("event_type") or "").strip()
                    != "observer.runtime_context_session_token_initial_join_identity_binding"
                    or str(event.get("event_kind") or "").strip()
                    != "observer_command"
                    or str(event.get("phase") or "").strip()
                    != "runtime_context_initial_join_identity_binding"
                    or str(event.get("task_id") or "").strip() != task_id
                    or str(event.get("backlog_id") or "").strip()
                    != backlog_id
                    or str(event_payload.get("schema_version") or "").strip()
                    != "runtime_context.initial_join_identity_binding_anchor.v1"
                    or event_payload.get("server_derived") is not True
                    or event_payload.get("raw_credentials_persisted") is not False
                    or str(
                        event_payload.get("runtime_context_id") or ""
                    ).strip()
                    != runtime_context_id
                    or str(event_payload.get("contract_execution_id") or "").strip()
                    != str(
                        successor_contract_evidence.get("contract_execution_id")
                        or ""
                    ).strip()
                    or str(event_payload.get("task_id") or "").strip()
                    != task_id
                    or str(event_payload.get("backlog_id") or "").strip()
                    != backlog_id
                    or str(event_payload.get("initial_join_event_ref") or "").strip()
                    != initial_join_event_ref
                    or str(
                        event_payload.get("canonical_binding_hash") or ""
                    ).strip()
                    != str(canonical_binding.get("binding_hash") or "").strip()
                    or str(event_payload.get("session_token_ref") or "").strip()
                    != str(
                        initial_join_event.get("payload", {}).get(
                            "session_token_ref"
                        )
                        or ""
                    ).strip()
                    or str(event_payload.get("route_identity_hash") or "").strip()
                    != route_identity_hash
                    or str(event_payload.get("anchor_hash") or "").strip()
                    != _stable_public_hash(anchor_core)
                ):
                    continue
                matching_anchors.append(event)
            if len(matching_anchors) == 1:
                identity_anchor = matching_anchors[0]
                return {
                    "schema_version": (
                        "contract_runtime.failed_qa_revision_initial_join_marker.v1"
                    ),
                    "source": "accepted_runtime_context_initial_join",
                    "reopen_authority_source": (
                        "canonical_successor_dispatch_revision+"
                        "initial_join_identity_anchor"
                    ),
                    "revision_event_id": initial_join_event_id,
                    "revision_event_ref": initial_join_event_ref,
                    "authoritative_rejoin_event_ref": initial_join_event_ref,
                    "latest_rotation_event_ref": initial_join_event_ref,
                    "composed_across_auth_rotation": False,
                    "contract_execution_id": str(
                        successor_contract_evidence.get("contract_execution_id")
                        or ""
                    ).strip(),
                    "failed_qa_source_ref": str(
                        successor_dispatch_authority.get("failed_qa_source_ref")
                        or successor_contract_evidence.get("failed_qa_source_ref")
                        or ""
                    ).strip(),
                    "failed_qa_source": "contract_runtime_completed_lines",
                    "dispatch_source_ref": str(
                        successor_dispatch_authority.get(
                            "dispatch_source_ref"
                        )
                        or ""
                    ).strip(),
                    "failed_qa_event_id": 0,
                    "failed_qa_authority_hash": "",
                    "runtime_context_id": runtime_context_id,
                    "task_id": task_id,
                    "parent_task_id": parent_task_id,
                    "backlog_id": backlog_id,
                    "attempt": expected_attempt,
                    "retry_round": expected_retry_round,
                    "route_token_ref": str(
                        expected_route_identity.get("route_token_ref") or ""
                    ).strip(),
                    "route_identity_rebound": False,
                    "evidence_backfill": False,
                    "initial_join_identity_anchor_event_ref": (
                        f"timeline:{int(identity_anchor.get('id') or 0)}"
                    ),
                    "successor_dispatch_revision_authority": dict(
                        successor_dispatch_authority
                    ),
                }

    def _matches_preserved_auth_only(event: Mapping[str, Any]) -> bool:
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        route_identity = (
            payload.get("route_identity")
            if isinstance(payload.get("route_identity"), Mapping)
            else {}
        )
        return bool(
            str(event.get("status") or "").strip().lower()
            in {"accepted", "passed", "succeeded"}
            and (
                str(event.get("event_type") or "").strip().lower()
                == "observer.runtime_context_session_token_rejoin"
                or (
                    str(event.get("event_kind") or "").strip().lower()
                    == "observer_command"
                    and str(payload.get("action") or "").strip()
                    == "runtime_context_session_token_rejoin"
                )
            )
            and not _truthy_flag(payload.get("revision_rejoin_applied"))
            and not _truthy_flag(payload.get("reopen_for_revision"))
            and str(payload.get("runtime_context_id") or "").strip()
            == runtime_context_id
            and str(payload.get("task_id") or "").strip() == task_id
            and str(payload.get("parent_task_id") or "").strip()
            == parent_task_id
            and int(payload.get("attempt") or 0) == expected_attempt
            and int(payload.get("retry_round") or 0) == expected_retry_round
            and str(payload.get("worker_id") or "").strip()
            == expected_worker_id
            and str(
                payload.get("worker_slot_id") or payload.get("worker_id") or ""
            ).strip()
            == expected_worker_slot_id
            and str(payload.get("fence_token_hash") or "").strip()
            == expected_fence_token_hash
            and str(payload.get("session_token_ref") or "").strip()
            == active_session_token_ref
            and str(
                event.get("backlog_id") or payload.get("backlog_id") or ""
            ).strip()
            == backlog_id
            and bool(expected_route_identity)
            and not _runtime_context_route_identity_mismatch_fields(
                expected_route_identity,
                route_identity,
            )
        )

    preserved_auth_only_events = [
        event
        for event in timeline_events
        if isinstance(event, Mapping) and _matches_preserved_auth_only(event)
    ]
    preserved_auth_only_event_id = (
        int(preserved_auth_only_events[0].get("id") or 0)
        if successor_dispatch_authority
        and len(preserved_auth_only_events) == 1
        else 0
    )
    if preserved_auth_only_event_id:
        for later in timeline_events:
            if (
                not isinstance(later, Mapping)
                or int(later.get("id") or 0) <= preserved_auth_only_event_id
            ):
                continue
            later_payload = (
                later.get("payload")
                if isinstance(later.get("payload"), Mapping)
                else {}
            )
            if str(
                later.get("task_id") or later_payload.get("task_id") or ""
            ).strip() != task_id:
                continue
            later_kind = str(later.get("event_kind") or "").strip().lower()
            later_type = str(later.get("event_type") or "").strip().lower()
            later_status = str(later.get("status") or "").strip().lower()
            if later_status not in {
                "accepted",
                "ok",
                "pass",
                "passed",
                "succeeded",
                "success",
            }:
                continue
            if later_kind == "worker_commit" or later_type in {
                "mf_subagent.worker_commit",
                "runtime_context.worker_commit",
            }:
                preserved_auth_only_event_id = 0
                break
            if later_kind in {
                "independent_verification",
                "qa_review",
                "qa_verification",
            }:
                preserved_auth_only_event_id = 0
                break
    active_timeline_failed_qa = (
        _runtime_context_authenticated_failed_qa_timeline_boundary(
            conn=conn,
            context=context,
            runtime_context_id=runtime_context_id,
            timeline_events=timeline_events,
        )
    )
    rejoin_continuity = {}
    if active_timeline_failed_qa:
        rejoin_continuity = (
            _runtime_context_authenticated_failed_qa_rejoin_continuity(
                context=context,
                runtime_context_id=runtime_context_id,
                timeline_events=timeline_events,
                active_failed_qa=active_timeline_failed_qa,
            )
        )
    if rejoin_continuity:
        expected_route_identity = _runtime_context_latest_route_identity(
            conn,
            context,
        )
        latest_rotation_route_identity = (
            rejoin_continuity.get("latest_rotation_route_identity")
            if isinstance(
                rejoin_continuity.get("latest_rotation_route_identity"),
                Mapping,
            )
            else {}
        )
        expected_route_identity_complete = all(
            str(expected_route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        )
        latest_rotation_route_identity_complete = all(
            str(latest_rotation_route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        )
        if (
            not expected_route_identity_complete
            or not latest_rotation_route_identity_complete
            or _runtime_context_route_identity_mismatch_fields(
                expected_route_identity,
                latest_rotation_route_identity,
            )
        ):
            rejoin_continuity = {}
    for event in reversed(list(timeline_events)):
        if not isinstance(event, Mapping):
            continue
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        event_id = int(event.get("id") or 0)
        if event_id <= 0:
            continue
        event_ref = f"timeline:{event_id}"
        event_type = str(event.get("event_type") or "").strip().lower()
        event_kind = str(event.get("event_kind") or "").strip().lower()
        status = str(event.get("status") or "").strip().lower()
        if status not in {"accepted", "passed", "succeeded"}:
            continue
        if not (
            event_type == "observer.runtime_context_session_token_rejoin"
            or (
                event_kind == "observer_command"
                and str(payload.get("action") or "").strip()
                == "runtime_context_session_token_rejoin"
            )
        ):
            continue
        contract_runtime_failed_qa = (
            payload.get("contract_runtime_failed_qa_revision")
            if isinstance(
                payload.get("contract_runtime_failed_qa_revision"),
                Mapping,
            )
            else {}
        )
        timeline_reopen_authority = bool(
            _truthy_flag(payload.get("reopen_for_revision"))
            and _truthy_flag(payload.get("timeline_reopen_for_revision"))
        )
        contract_runtime_reopen_authority = bool(
            _truthy_flag(payload.get("reopen_for_revision"))
            and str(contract_runtime_failed_qa.get("status") or "").strip()
            == "revision_required"
            and str(contract_runtime_failed_qa.get("source") or "").strip()
            == "contract_runtime_completed_lines"
            and str(
                contract_runtime_failed_qa.get("runtime_context_id") or ""
            ).strip()
            == runtime_context_id
            and str(contract_runtime_failed_qa.get("task_id") or "").strip()
            == task_id
        )
        composed_timeline_reopen_authority = bool(
            rejoin_continuity
            and str(
                rejoin_continuity.get("latest_rotation_event_ref") or ""
            ).strip()
            == event_ref
        )
        preserved_auth_only_successor_authority = bool(
            preserved_auth_only_event_id == event_id
        )
        if not (
            timeline_reopen_authority
            or contract_runtime_reopen_authority
            or composed_timeline_reopen_authority
            or preserved_auth_only_successor_authority
        ):
            continue
        if str(payload.get("runtime_context_id") or "").strip() != runtime_context_id:
            continue
        if str(payload.get("task_id") or "").strip() != task_id:
            continue
        if (
            parent_task_id
            and str(payload.get("parent_task_id") or "").strip()
            != parent_task_id
        ):
            continue
        if int(payload.get("attempt") or 0) != expected_attempt:
            continue
        if int(payload.get("retry_round") or 0) != expected_retry_round:
            continue
        event_context_status = str(
            payload.get("current_status") or ""
        ).strip()
        if (
            event_context_status != "worktree_ready"
            and not (
                event_context_status == "running"
                and (
                    contract_runtime_reopen_authority
                    or preserved_auth_only_successor_authority
                )
            )
        ):
            continue
        event_session_token_ref = str(
            payload.get("session_token_ref") or ""
        ).strip()
        if (
            not active_session_token_ref
            or event_session_token_ref != active_session_token_ref
        ):
            continue
        if str(payload.get("worker_id") or "").strip() != expected_worker_id:
            continue
        if str(
            payload.get("worker_slot_id") or payload.get("worker_id") or ""
        ).strip() != expected_worker_slot_id:
            continue
        if str(payload.get("fence_token_hash") or "").strip() != (
            expected_fence_token_hash
        ):
            continue
        event_backlog_id = str(
            event.get("backlog_id") or payload.get("backlog_id") or ""
        ).strip()
        if backlog_id and event_backlog_id != backlog_id:
            continue
        timeline_failed_qa_boundary = (
            _runtime_context_authenticated_failed_qa_timeline_boundary(
                conn=conn,
                context=context,
                runtime_context_id=runtime_context_id,
                timeline_events=timeline_events,
                before_event_id=event_id,
            )
        )
        canonical_timeline_reopen_authority = bool(
            (
                timeline_reopen_authority
                or composed_timeline_reopen_authority
            )
            and timeline_failed_qa_boundary
        )
        legacy_timeline_reopen_authority = bool(
            timeline_reopen_authority
            and not canonical_timeline_reopen_authority
            and not contract_runtime_reopen_authority
        )
        effective_contract_runtime_reopen_authority = bool(
            contract_runtime_reopen_authority
            and not canonical_timeline_reopen_authority
        )
        effective_successor_dispatch_authority = bool(
            preserved_auth_only_successor_authority
            and successor_dispatch_authority
        )
        if not (
            canonical_timeline_reopen_authority
            or legacy_timeline_reopen_authority
            or effective_contract_runtime_reopen_authority
            or effective_successor_dispatch_authority
        ):
            continue
        route_identity = (
            payload.get("route_identity")
            if isinstance(payload.get("route_identity"), Mapping)
            else {}
        )
        pre_lineage_rejoin_authority = (
            payload.get("pre_lineage_rejoin_authority")
            if isinstance(
                payload.get("pre_lineage_rejoin_authority"), Mapping
            )
            else {}
        )
        current_reissue_route_binding = (
            pre_lineage_rejoin_authority.get(
                "current_reissue_route_binding"
            )
            if isinstance(
                pre_lineage_rejoin_authority.get(
                    "current_reissue_route_binding"
                ),
                Mapping,
            )
            else {}
        )
        bounded_replacement_authority = (
            payload.get("bounded_replacement_rejoin_authority")
            if isinstance(
                payload.get("bounded_replacement_rejoin_authority"), Mapping
            )
            else {}
        )
        if (
            current_reissue_route_binding.get("valid") is not True
            and str(payload.get("bounded_rejoin_kind") or "").strip()
            == "bounded_replacement_rejoin"
        ):
            source_event_ref = str(
                bounded_replacement_authority.get("source_event_ref") or ""
            ).strip()
            source_event_id_text = source_event_ref.removeprefix("timeline:")
            source_event_id = (
                int(source_event_id_text)
                if source_event_id_text.isdigit()
                else 0
            )
            source_events = [
                candidate
                for candidate in timeline_events
                if isinstance(candidate, Mapping)
                and int(candidate.get("id") or 0) == source_event_id
            ]
            source_event = source_events[0] if len(source_events) == 1 else {}
            source_payload = (
                source_event.get("payload")
                if isinstance(source_event.get("payload"), Mapping)
                else {}
            )
            source_pre_lineage_authority = (
                source_payload.get("pre_lineage_rejoin_authority")
                if isinstance(
                    source_payload.get("pre_lineage_rejoin_authority"),
                    Mapping,
                )
                else {}
            )
            source_route_binding = (
                source_pre_lineage_authority.get(
                    "current_reissue_route_binding"
                )
                if isinstance(
                    source_pre_lineage_authority.get(
                        "current_reissue_route_binding"
                    ),
                    Mapping,
                )
                else {}
            )
            source_route_identity = (
                source_payload.get("route_identity")
                if isinstance(source_payload.get("route_identity"), Mapping)
                else {}
            )
            if (
                source_event_id > 0
                and source_event_id < event_id
                and str(source_event.get("status") or "").strip().lower()
                in {"accepted", "passed", "succeeded"}
                and str(source_payload.get("action") or "").strip()
                == "runtime_context_session_token_rejoin"
                and str(source_payload.get("runtime_context_id") or "").strip()
                == runtime_context_id
                and str(source_payload.get("task_id") or "").strip()
                == task_id
                and str(source_payload.get("bounded_rejoin_kind") or "").strip()
                == "special_authority_rejoin"
                and dict(source_route_identity) == dict(route_identity)
                and source_route_binding.get("valid") is True
                and source_route_binding.get("registry_verified") is True
                and source_route_binding.get("exact_scope_verified") is True
                and source_route_binding.get("scope_actions_files_verified")
                is True
                and source_route_binding.get("historical_event_rewritten")
                is False
            ):
                current_reissue_route_binding = {
                    **dict(source_route_binding),
                    "composed_through_bounded_replacement": True,
                    "bounded_replacement_event_ref": event_ref,
                    "bounded_replacement_source_event_ref": source_event_ref,
                }
        if (
            not current_reissue_route_binding
            and payload.get("route_identity_rebound") is True
            and isinstance(payload.get("previous_route_identity"), Mapping)
        ):
            current_reissue_route_binding = (
                _runtime_context_current_reissue_route_binding(
                    conn,
                    project_id=str(
                        getattr(context, "project_id", "") or ""
                    ).strip(),
                    historical_route_identity=payload[
                        "previous_route_identity"
                    ],
                    canonical_route_identity=route_identity,
                )
            )
        route_token_ref = str(route_identity.get("route_token_ref") or "").strip()
        contract_runtime_worker_sequence = (
            payload.get("contract_runtime_worker_sequence")
            if isinstance(
                payload.get("contract_runtime_worker_sequence"),
                Mapping,
            )
            else {}
        )
        marker_contract_execution_id = str(
            contract_runtime_failed_qa.get("contract_execution_id")
            or successor_contract_evidence.get("contract_execution_id")
            or contract_runtime_worker_sequence.get("contract_execution_id")
            or ""
        ).strip()
        failed_qa_source_ref = ""
        if canonical_timeline_reopen_authority:
            failed_qa_source_ref = str(
                timeline_failed_qa_boundary.get("source_ref") or ""
            ).strip()
        if not failed_qa_source_ref:
            failed_qa_source_ref = str(
                contract_runtime_failed_qa.get("failed_qa_source_ref")
                or successor_contract_evidence.get("failed_qa_source_ref")
                or ""
            ).strip()
        return {
            "schema_version": "contract_runtime.failed_qa_revision_rejoin_marker.v1",
            "source": "accepted_runtime_context_rejoin_event",
            "reopen_authority_source": (
                "failed_qa_timeline_event"
                if (
                    canonical_timeline_reopen_authority
                    or legacy_timeline_reopen_authority
                )
                else "contract_runtime_failed_qa_revision"
            ),
            "revision_event_id": event_id,
            "revision_event_ref": event_ref,
            "authoritative_rejoin_event_ref": str(
                rejoin_continuity.get("authoritative_rejoin_event_ref") or ""
            ).strip()
            if composed_timeline_reopen_authority
            else event_ref,
            "latest_rotation_event_ref": str(
                rejoin_continuity.get("latest_rotation_event_ref") or ""
            ).strip()
            if composed_timeline_reopen_authority
            else event_ref,
            "composed_across_auth_rotation": composed_timeline_reopen_authority,
            "contract_execution_id": marker_contract_execution_id,
            "failed_qa_source_ref": failed_qa_source_ref,
            "dispatch_source_ref": str(
                successor_dispatch_authority.get("dispatch_source_ref") or ""
            ).strip(),
            "failed_qa_source": (
                "server_qa_session_verification"
                if canonical_timeline_reopen_authority
                else (
                    "contract_runtime_completed_lines"
                    if (
                        effective_contract_runtime_reopen_authority
                        or effective_successor_dispatch_authority
                    )
                    else ""
                )
            ),
            "failed_qa_event_id": int(
                timeline_failed_qa_boundary.get("event_id") or 0
            ),
            "failed_qa_authority_hash": str(
                timeline_failed_qa_boundary.get("authority_hash") or ""
            ),
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "backlog_id": backlog_id,
            "attempt": expected_attempt,
            "retry_round": expected_retry_round,
            "route_token_ref": route_token_ref,
            "route_identity_rebound": bool(payload.get("route_identity_rebound")),
            "current_reissue_route_binding": dict(
                current_reissue_route_binding
            ),
            "evidence_backfill": False,
            "successor_dispatch_revision_authority": dict(
                successor_dispatch_authority
            )
            if effective_successor_dispatch_authority
            else {},
            "session_token_ref_rotation": {
                "schema_version": (
                    "contract_runtime.failed_qa_rejoin_session_ref_rotation.v1"
                ),
                "source": "accepted_runtime_context_rejoin_event",
                "server_derived": True,
                "revision_event_ref": event_ref,
                "authoritative_rejoin_event_ref": str(
                    rejoin_continuity.get(
                        "authoritative_rejoin_event_ref"
                    )
                    or ""
                ).strip()
                if composed_timeline_reopen_authority
                else event_ref,
                "latest_rotation_event_ref": str(
                    rejoin_continuity.get("latest_rotation_event_ref") or ""
                ).strip()
                if composed_timeline_reopen_authority
                else event_ref,
                "composed_across_auth_rotation": (
                    composed_timeline_reopen_authority
                ),
                "contract_execution_id": marker_contract_execution_id,
                "runtime_context_id": runtime_context_id,
                "task_id": task_id,
                "parent_task_id": parent_task_id,
                "worker_id": expected_worker_id,
                "worker_slot_id": expected_worker_slot_id,
                "target_project_root": expected_target_project_root,
                "fence_token_hash": expected_fence_token_hash,
                "active_session_token_ref": active_session_token_ref,
                "raw_session_tokens_persisted": False,
            },
        }
    return {}


def _runtime_context_precommit_correction_rejoin_marker(
    *,
    context: Any,
    runtime_context_id: str,
    contract_execution_id: str,
    prior_implementation: Mapping[str, Any],
    timeline_events: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Project an audited same-worker token rotation for precommit correction."""

    from .parallel_branch_runtime import (
        runtime_context_fence_token_verifier,
        runtime_context_session_token_ref,
    )

    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    prior_session_token_ref = _worker_commit_text(
        prior_implementation,
        "session_token_ref",
    )
    prior_fence_token_hash = _worker_commit_text(
        prior_implementation,
        "fence_token_hash",
    )
    active_session_token_ref = runtime_context_session_token_ref(context)
    expected_worker_id = str(getattr(context, "worker_id", "") or "").strip()
    expected_worker_slot_id = str(
        getattr(context, "worker_slot_id", "")
        or getattr(context, "worker_id", "")
        or ""
    ).strip()
    expected_target_project_root = _runtime_context_effective_target_project_root(
        context
    )
    expected_fence_token_hash = runtime_context_fence_token_verifier(context)
    if (
        not runtime_context_id
        or not task_id
        or not contract_execution_id
        or not prior_session_token_ref
        or not prior_fence_token_hash
        or not active_session_token_ref
        or not expected_fence_token_hash
        or prior_session_token_ref == active_session_token_ref
    ):
        return {}

    for event in reversed(list(timeline_events)):
        if not isinstance(event, Mapping):
            continue
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        event_type = str(event.get("event_type") or "").strip().lower()
        event_kind = str(event.get("event_kind") or "").strip().lower()
        if str(event.get("status") or "").strip().lower() not in {
            "accepted",
            "passed",
            "succeeded",
        }:
            continue
        if not (
            event_type == "observer.runtime_context_session_token_rejoin"
            or (
                event_kind == "observer_command"
                and str(payload.get("action") or "").strip()
                == "runtime_context_session_token_rejoin"
            )
        ):
            continue
        if str(payload.get("runtime_context_id") or "").strip() != (
            runtime_context_id
        ):
            continue
        if str(payload.get("task_id") or "").strip() != task_id:
            continue
        if (
            parent_task_id
            and str(payload.get("parent_task_id") or "").strip()
            != parent_task_id
        ):
            continue
        event_backlog_id = str(
            event.get("backlog_id") or payload.get("backlog_id") or ""
        ).strip()
        if backlog_id and event_backlog_id != backlog_id:
            continue
        if str(payload.get("session_token_ref") or "").strip() != (
            active_session_token_ref
        ):
            continue
        if str(payload.get("worker_id") or "").strip() != expected_worker_id:
            continue
        if str(
            payload.get("worker_slot_id") or payload.get("worker_id") or ""
        ).strip() != expected_worker_slot_id:
            continue
        if str(payload.get("fence_token_hash") or "").strip() != (
            expected_fence_token_hash
        ):
            continue
        if str(payload.get("target_project_root") or "").strip() != (
            expected_target_project_root
        ):
            continue
        if str(payload.get("current_status") or "").strip() not in {
            "running",
            "worktree_ready",
        }:
            continue
        worker_sequence = (
            payload.get("contract_runtime_worker_sequence")
            if isinstance(
                payload.get("contract_runtime_worker_sequence"),
                Mapping,
            )
            else {}
        )
        if (
            str(worker_sequence.get("source") or "").strip()
            != "contract_runtime_completed_lines"
            or str(worker_sequence.get("source_of_authority") or "").strip()
            != "contract_runtime"
            or worker_sequence.get("ordered") is not True
            or str(
                worker_sequence.get("contract_execution_id") or ""
            ).strip()
            != contract_execution_id
            or str(worker_sequence.get("runtime_context_id") or "").strip()
            != runtime_context_id
            or str(worker_sequence.get("task_id") or "").strip() != task_id
            or (
                parent_task_id
                and str(
                    worker_sequence.get("parent_task_id") or ""
                ).strip()
                != parent_task_id
            )
        ):
            continue
        event_id = int(event.get("id") or 0)
        if event_id <= 0:
            continue
        route_identity = (
            payload.get("route_identity")
            if isinstance(payload.get("route_identity"), Mapping)
            else {}
        )
        rejoin_event_ref = f"timeline:{event_id}"
        return {
            "schema_version": (
                "contract_runtime.precommit_correction_rejoin_marker.v1"
            ),
            "source": "accepted_runtime_context_rejoin_event",
            "server_derived": True,
            "rejoin_event_id": event_id,
            "rejoin_event_ref": rejoin_event_ref,
            "contract_execution_id": contract_execution_id,
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "backlog_id": backlog_id,
            "worker_id": expected_worker_id,
            "worker_slot_id": expected_worker_slot_id,
            "target_project_root": expected_target_project_root,
            "fence_token_hash": expected_fence_token_hash,
            "prior_fence_token_hash": prior_fence_token_hash,
            "active_fence_token_hash": expected_fence_token_hash,
            "prior_session_token_ref": prior_session_token_ref,
            "active_session_token_ref": active_session_token_ref,
            "route_token_ref": str(
                route_identity.get("route_token_ref") or ""
            ).strip(),
            "raw_session_tokens_persisted": False,
            "session_token_ref_rotation": {
                "schema_version": (
                    "contract_runtime.precommit_rejoin_session_ref_rotation.v1"
                ),
                "source": "accepted_runtime_context_rejoin_event",
                "server_derived": True,
                "rejoin_event_ref": rejoin_event_ref,
                "contract_execution_id": contract_execution_id,
                "runtime_context_id": runtime_context_id,
                "task_id": task_id,
                "parent_task_id": parent_task_id,
                "worker_id": expected_worker_id,
                "worker_slot_id": expected_worker_slot_id,
                "target_project_root": expected_target_project_root,
                "fence_token_hash": expected_fence_token_hash,
                "prior_fence_token_hash": prior_fence_token_hash,
                "active_fence_token_hash": expected_fence_token_hash,
                "prior_session_token_ref": prior_session_token_ref,
                "active_session_token_ref": active_session_token_ref,
                "raw_session_tokens_persisted": False,
            },
        }
    return {}


def _runtime_context_contract_runtime_qa_verification_evidence(
    conn,
    *,
    project_id: str,
    context: Any,
) -> dict[str, Any]:
    """Project canonical QA completion without inventing a timeline event."""
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    context_head = str(getattr(context, "head_commit", "") or "").strip()
    if not conn or not backlog_id or not context_head:
        return {}
    runtime_context_id, task_id, _parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    contract_identity, resolution = (
        _runtime_context_source_backed_contract_identity(
            conn,
            project_id=project_id,
            context=context,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
        )
    )
    execution_id = str(
        contract_identity.get("contract_execution_id") or ""
    ).strip()
    if not execution_id:
        return {}
    try:
        record = _contract_runtime_store(conn).get(execution_id)
    except (ContractRuntimeError, sqlite3.Error):
        return {}
    if not _is_mf_parallel_record_contract_id(
        str((record or {}).get("contract_id") or "")
    ):
        return {}
    completed_lines = record.get("completed_lines")
    if not isinstance(completed_lines, list):
        return {}
    for index, raw_line in reversed(list(enumerate(completed_lines))):
        if not isinstance(raw_line, Mapping):
            continue
        line = dict(raw_line)
        if str(line.get("line_id") or "").strip() != (
            "qa_independent_verification"
        ):
            continue
        if _contract_runtime_value_reports_failed_qa(line):
            return {}
        if not _contract_runtime_line_status_passes(line):
            return {}
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        actor_role = str(
            line.get("actor_role")
            or line.get("evidence_owner_role")
            or payload.get("actor_role")
            or ""
        ).strip().lower()
        if actor_role != "qa" or bool(line.get("observer_impersonation")):
            return {}
        verified_commit = str(
            line.get("commit_sha")
            or payload.get("candidate_commit")
            or payload.get("snapshot_commit_sha")
            or payload.get("commit_sha")
            or ""
        ).strip()
        if verified_commit != context_head:
            return {}
        source_ref = f"contract_runtime:{execution_id}:completed_lines:{index}"
        return {
            "schema_version": (
                "runtime_context.contract_runtime_qa_verification_evidence.v1"
            ),
            "source": "contract_runtime_completed_lines",
            "source_of_authority": "contract_runtime",
            "status": "passed",
            "project_id": project_id,
            "backlog_id": backlog_id,
            "contract_execution_id": execution_id,
            "contract_execution_resolution": dict(resolution),
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "commit_sha": verified_commit,
            "verification_ref": source_ref,
            "graph_trace_ids": _runtime_context_service_query_values(
                payload,
                "graph_trace_ids",
                "graph_query_trace_ids",
                "trace_ids",
            ),
            "observer_authored_qa_evidence": False,
            "synthetic_timeline_event_created": False,
        }
    return {}


def _runtime_context_failed_qa_line_matches_context(
    failed_line: Mapping[str, Any],
    *,
    context: Any,
    server_identity: Mapping[str, Any] | None = None,
) -> bool:
    runtime_context_id, task_id, parent_task_id = _contract_runtime_context_identity(
        context
    )
    if not runtime_context_id or not task_id or not parent_task_id:
        return False

    exact_mapping = False
    incomplete_runtime_mapping = False
    for candidate in _contract_runtime_mapping_candidates(failed_line):
        candidate_runtime_id = _contract_runtime_mapping_value(
            candidate,
            "runtime_context_id",
        )
        if candidate_runtime_id != runtime_context_id:
            continue
        task_values = _contract_runtime_mapping_values(
            candidate,
            "task_id",
            "worker_task_id",
        )
        candidate_parent_task_id = _contract_runtime_mapping_value(
            candidate,
            "parent_task_id",
        )
        if task_values and task_id not in task_values:
            return False
        if candidate_parent_task_id and candidate_parent_task_id != parent_task_id:
            return False
        if task_id in task_values and candidate_parent_task_id == parent_task_id:
            exact_mapping = True
            continue
        incomplete_runtime_mapping = True
    if exact_mapping:
        return True
    if not incomplete_runtime_mapping or not isinstance(server_identity, Mapping):
        return False
    return bool(
        str(server_identity.get("schema_version") or "").strip()
        == "contract_runtime.dispatch_line_match.v1"
        and str(server_identity.get("runtime_context_id") or "").strip()
        == runtime_context_id
        and str(server_identity.get("task_id") or "").strip() == task_id
        and str(server_identity.get("parent_task_id") or "").strip()
        == parent_task_id
        and str(server_identity.get("source_ref") or "").strip().startswith(
            "contract_runtime:"
        )
    )


def _runtime_context_active_failed_qa_line_index_for_context(
    record: Mapping[str, Any],
    *,
    context: Any,
) -> int:
    """Return the active failed-QA line for the exact worker lane.

    ``_active_failed_qa_line_index`` intentionally models completion for the
    whole ContractRuntime.  A failed-QA worker revision is lane-local instead:
    a canonical failure from a sibling worker must not replace the selected
    worker's authenticated timeline boundary.  Filter by the persisted exact
    dispatch/context binding first, then reuse the canonical active/superseded
    QA state machine on that lane and map its result back to the source record.
    """

    if not isinstance(record, Mapping):
        return -1
    completed_lines = record.get("completed_lines")
    if not isinstance(completed_lines, list):
        return -1
    dispatch_match = _contract_runtime_dispatch_line_match(record, context)
    if not dispatch_match:
        return -1

    lane_indices: list[int] = []
    lane_qa_lines: list[Mapping[str, Any]] = []
    for index, line in enumerate(completed_lines):
        if (
            not isinstance(line, Mapping)
            or str(line.get("line_id") or "").strip()
            != "qa_independent_verification"
            or not _runtime_context_failed_qa_line_matches_context(
                line,
                context=context,
                server_identity=dispatch_match,
            )
        ):
            continue
        lane_indices.append(index)
        lane_qa_lines.append(line)

    lane_failed_qa_index = _active_failed_qa_line_index(
        lane_qa_lines,
        source_record=record,
    )
    if lane_failed_qa_index < 0:
        return -1
    return lane_indices[lane_failed_qa_index]


def _runtime_context_failed_qa_accepted_line_binding(
    record: Mapping[str, Any],
    failed_line: Mapping[str, Any],
    *,
    context: Any,
    dispatch_match: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind an accepted-but-noncompleting QA line to the active worker.

    Explicit failed/rejected QA already carries a blocking status.  Accepted
    no-PASS evidence is subtler: before it can reopen a validated worker, the
    immutable line must match the exact current runtime/task/parent and the
    canonical worker commit must match the current worker, fence, and
    candidate HEAD.  Only the subsequent session-token ref may rotate.
    """

    status = str(failed_line.get("status") or "").strip().lower()
    if status not in {"accepted", "passed", "pass", "ok", "succeeded"}:
        return {
            "schema_version": (
                "runtime_context.failed_qa_revision_identity_binding.v1"
            ),
            "source": "explicit_failed_qa_status",
            "server_derived": True,
            "accepted_no_pass_completion_failure": False,
        }
    if not _runtime_context_failed_qa_line_matches_context(
        failed_line,
        context=context,
        server_identity=dispatch_match,
    ):
        return {}

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    expected_worker_id = str(getattr(context, "worker_id", "") or "").strip()
    expected_worker_slot_id = str(
        getattr(context, "worker_slot_id", "")
        or getattr(context, "worker_id", "")
        or ""
    ).strip()
    expected_candidate_commit = str(
        getattr(context, "head_commit", "") or ""
    ).strip().lower()
    raw_fence_token = str(getattr(context, "fence_token", "") or "").strip()
    if not (
        expected_worker_id
        and expected_worker_slot_id
        and raw_fence_token
        and re.fullmatch(
            r"[0-9a-f]{40}|[0-9a-f]{64}",
            expected_candidate_commit,
        )
    ):
        return {}

    from .parallel_branch_runtime import runtime_context_secret_hash

    expected_fence_token_hash = runtime_context_secret_hash(raw_fence_token)
    canonical_worker_commit: Mapping[str, Any] = {}
    canonical_candidate_commit = ""
    for line in reversed(list(record.get("completed_lines") or [])):
        if (
            not isinstance(line, Mapping)
            or str(line.get("line_id") or "").strip() != "worker_commit"
        ):
            continue
        if not _contract_runtime_mapping_matches_context(
            line,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            parent_task_id=parent_task_id,
        ):
            continue
        line_worker_id = _timeline_first_deep_text(line, "worker_id")
        line_worker_slot_id = _timeline_first_deep_text(
            line,
            "worker_slot_id",
        )
        line_fence_token_hash = _timeline_first_deep_text(
            line,
            "fence_token_hash",
        )
        if (
            line_worker_id != expected_worker_id
            or line_worker_slot_id != expected_worker_slot_id
            or line_fence_token_hash != expected_fence_token_hash
        ):
            continue
        commit_values = {
            str(value or "").strip().lower()
            for value in (
                line.get("commit_sha"),
                _timeline_first_deep_text(line, "worker_commit_sha"),
                _timeline_first_deep_text(line, "head_commit"),
                _timeline_first_deep_text(line, "immutable_head_commit"),
                _timeline_first_deep_text(line, "validated_head_commit"),
            )
            if str(value or "").strip()
        }
        if commit_values != {expected_candidate_commit}:
            continue
        canonical_worker_commit = line
        canonical_candidate_commit = expected_candidate_commit
        break
    if not canonical_worker_commit:
        return {}

    failed_commit = str(
        failed_line.get("commit_sha")
        or _timeline_first_deep_text(failed_line, "candidate_commit_sha")
        or _timeline_first_deep_text(failed_line, "candidate_commit")
        or ""
    ).strip().lower()
    if failed_commit != canonical_candidate_commit:
        return {}

    binding = {
        "schema_version": (
            "runtime_context.failed_qa_revision_identity_binding.v1"
        ),
        "source": (
            "contract_runtime_active_failed_qa+canonical_worker_commit+"
            "branch_runtime_context"
        ),
        "server_derived": True,
        "accepted_no_pass_completion_failure": True,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "worker_id": expected_worker_id,
        "worker_slot_id": expected_worker_slot_id,
        "fence_token_hash": expected_fence_token_hash,
        "candidate_commit_sha": canonical_candidate_commit,
        "dispatch_source_ref": str(dispatch_match.get("source_ref") or ""),
        "worker_commit_source": "ContractRuntime.completed_lines.worker_commit",
        "raw_fence_token_exposed": False,
        "raw_session_token_exposed": False,
    }
    binding["binding_hash"] = stable_sha256(binding)
    return binding


def _runtime_context_failed_qa_successor_dispatch_revision_authority(
    record: Mapping[str, Any],
    *,
    failed_line: Mapping[str, Any],
    context: Any,
    dispatch_match: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind an old failed-QA line to one exact replacement dispatch."""

    failed_index = int(failed_line.get("_completed_line_index") or -1)
    dispatch_index = int(dispatch_match.get("line_index") or -1)
    payload = (
        dispatch_match.get("payload")
        if isinstance(dispatch_match.get("payload"), Mapping)
        else {}
    )
    revision = (
        payload.get("failed_qa_rework_dispatch_revision")
        if isinstance(payload.get("failed_qa_rework_dispatch_revision"), Mapping)
        else {}
    )
    authority = (
        payload.get("failed_qa_rework_dispatch_revision_authority")
        if isinstance(
            payload.get("failed_qa_rework_dispatch_revision_authority"), Mapping
        )
        else {}
    )
    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    contract_execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    if (
        failed_index < 0
        or dispatch_index <= failed_index
        or str(dispatch_match.get("source_ref") or "").strip()
        != f"contract_runtime:{contract_execution_id}:completed_lines:{dispatch_index}"
        or revision.get("append_only_history_preserved") is not True
        or revision.get("timeline_projection_authoritative") is not False
        or int(revision.get("failed_qa_completed_line_index") or -1)
        != failed_index
        or str(revision.get("runtime_context_id") or "").strip()
        != runtime_context_id
        or str(revision.get("task_id") or "").strip() != task_id
        or authority.get("server_derived") is not True
        or str(authority.get("source") or "").strip()
        != "parallel_branch_allocate_failed_qa_rework"
        or str(authority.get("contract_execution_id") or "").strip()
        != contract_execution_id
        or int(authority.get("failed_qa_completed_line_index") or -1)
        != failed_index
        or str(authority.get("runtime_context_id") or "").strip()
        != runtime_context_id
        or str(authority.get("task_id") or "").strip() != task_id
    ):
        return {}

    failed_runtime_context_id = _timeline_first_deep_text(
        failed_line, "runtime_context_id"
    )
    failed_task_id = _timeline_first_deep_text(failed_line, "task_id")
    failed_parent_task_id = _timeline_first_deep_text(
        failed_line, "parent_task_id"
    )
    failed_commit = str(
        failed_line.get("commit_sha")
        or _timeline_first_deep_text(failed_line, "candidate_commit_sha")
        or _timeline_first_deep_text(failed_line, "candidate_commit")
        or ""
    ).strip()
    if (
        not failed_runtime_context_id
        or not failed_task_id
        or not failed_parent_task_id
        or not parent_task_id
        or parent_task_id != contract_execution_id
        or failed_parent_task_id != parent_task_id
        or failed_runtime_context_id == runtime_context_id
        or failed_task_id == task_id
        or not re.fullmatch(r"[0-9a-f]{40,64}", failed_commit)
    ):
        return {}

    previous_implementation: Mapping[str, Any] | None = None
    previous_index = -1
    for index in range(failed_index - 1, -1, -1):
        line = (record.get("completed_lines") or [])[index]
        if not isinstance(line, Mapping):
            continue
        if str(line.get("line_id") or "").strip() != "worker_implementation":
            continue
        if (
            _timeline_first_deep_text(line, "runtime_context_id")
            != failed_runtime_context_id
            or _timeline_first_deep_text(line, "task_id") != failed_task_id
            or _timeline_first_deep_text(line, "parent_task_id")
            != failed_parent_task_id
        ):
            continue
        previous_implementation = line
        previous_index = index
        break
    superseded_commit_authority = (
        _runtime_context_superseded_implementation_commit_authority(
            record,
            implementation=previous_implementation,
            implementation_index=previous_index,
            runtime_context_id=failed_runtime_context_id,
            task_id=failed_task_id,
        )
    )
    failed_payload = (
        failed_line.get("payload")
        if isinstance(failed_line.get("payload"), Mapping)
        else {}
    )
    qa_provenance = (
        failed_line.get("qa_evidence_provenance")
        if isinstance(failed_line.get("qa_evidence_provenance"), Mapping)
        else {}
    )
    qa_binding = (
        qa_provenance.get("authenticated_qa_binding")
        if isinstance(qa_provenance.get("authenticated_qa_binding"), Mapping)
        else {}
    )
    timeline_materialized_commit_authority = bool(
        _runtime_context_contract_failed_qa_has_canonical_provenance(
            failed_line
        )
        and str(qa_provenance.get("source") or "").strip()
        == "authenticated_failed_qa_timeline_dispatch_boundary"
        and qa_provenance.get("server_derived") is True
        and qa_binding.get("server_derived") is True
        and qa_binding.get("independent_verification_session_matched") is True
        and str(failed_payload.get("schema_version") or "").strip()
        == "contract_runtime.authenticated_failed_qa_revision_boundary.v1"
        and str(failed_payload.get("source") or "").strip()
        == "server_authenticated_qa_timeline_materialization"
        and str(failed_payload.get("source_of_authority") or "").strip()
        == "qa_session_verification"
        and failed_payload.get("source_backed") is True
        and failed_payload.get("projection_persists_completed_line") is True
        and failed_payload.get("observer_authored_qa_backfill") is False
        and failed_payload.get("observer_authored_worker_backfill") is False
        and str(
            failed_payload.get("projection_contract_execution_id") or ""
        ).strip()
        == contract_execution_id
        and str(failed_payload.get("runtime_context_id") or "").strip()
        == failed_runtime_context_id
        and str(failed_payload.get("task_id") or "").strip()
        == failed_task_id
        and str(failed_payload.get("parent_task_id") or "").strip()
        == failed_parent_task_id
        and str(failed_payload.get("source_ref") or "").strip()
        == str(qa_binding.get("timeline_event_ref") or "").strip()
    )
    if not timeline_materialized_commit_authority and (
        superseded_commit_authority.get("errors")
        or str(superseded_commit_authority.get("commit_sha") or "").strip()
        != failed_commit
    ):
        return {}

    binding = {
        "schema_version": (
            "runtime_context.failed_qa_successor_dispatch_revision_authority.v1"
        ),
        "source": "canonical_successor_dispatch_revision",
        "server_derived": True,
        "contract_execution_id": contract_execution_id,
        "failed_qa_source_ref": (
            f"contract_runtime:{contract_execution_id}:completed_lines:{failed_index}"
        ),
        "failed_qa_completed_line_index": failed_index,
        "failed_runtime_context_id": failed_runtime_context_id,
        "failed_task_id": failed_task_id,
        "failed_parent_task_id": failed_parent_task_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "dispatch_source_ref": str(dispatch_match.get("source_ref") or ""),
        "failed_commit_authority_source": (
            "authenticated_failed_qa_timeline_materialization"
            if timeline_materialized_commit_authority
            else "superseded_implementation_commit_authority"
        ),
        "superseded_implementation_commit_authority": dict(
            superseded_commit_authority
        ),
        "append_only_history_preserved": True,
        "timeline_projection_authoritative": False,
    }
    binding["binding_hash"] = stable_sha256(binding)
    return binding


def _runtime_context_failed_qa_revision_contract_runtime_evidence(
    conn,
    *,
    project_id: str,
    context: Any,
) -> dict[str, Any]:
    from .parallel_branch_runtime import (
        FAILED_QA_REVISION_REJOIN_STATES,
        STATE_RUNNING,
        STATE_WORKTREE_READY,
    )

    context_status = str(getattr(context, "status", "") or "")
    revision_counters_advanced = (
        int(getattr(context, "attempt", 0) or 0) > 1
        and int(getattr(context, "retry_round", 0) or 0) > 0
    )
    failed_qa_rejoin_reopened = (
        context_status == STATE_WORKTREE_READY
        and (
            str(getattr(context, "last_recovery_action", "") or "")
            == "mf_subagent_failed_qa_revision_rejoin_issued"
            or revision_counters_advanced
        )
    ) or (
        context_status == STATE_RUNNING
        and revision_counters_advanced
    )
    fresh_failed_qa_replacement_running = (
        context_status == STATE_RUNNING
        and int(getattr(context, "attempt", 0) or 0) > 1
        and int(getattr(context, "retry_round", 0) or 0) == 0
    )
    fresh_failed_qa_replacement_host_joined_or_reissued = (
        context_status == STATE_WORKTREE_READY
        and int(getattr(context, "attempt", 0) or 0) > 1
        and int(getattr(context, "retry_round", 0) or 0) == 0
        and str(getattr(context, "last_recovery_action", "") or "")
        in {
            "mf_subagent_initial_join_issued",
            "mf_subagent_session_token_reissued",
            "mf_subagent_pre_lineage_session_token_rejoin_issued",
            _RUNTIME_CONTEXT_REJOIN_REPLACEMENT_RECOVERY_ACTION,
        }
    )
    if (
        context_status not in FAILED_QA_REVISION_REJOIN_STATES
        and not failed_qa_rejoin_reopened
        and not fresh_failed_qa_replacement_running
        and not fresh_failed_qa_replacement_host_joined_or_reissued
    ):
        return {}
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    if not conn or not backlog_id:
        return {}
    try:
        records = _contract_runtime_store(conn).list_by_backlog(
            project_id=project_id,
            backlog_id=backlog_id,
        )
    except (ContractRuntimeError, sqlite3.Error):
        return {}

    for record in records:
        if not _is_mf_parallel_record_contract_id(
            str((record or {}).get("contract_id") or "")
        ):
            continue
        dispatch_match = _contract_runtime_dispatch_line_match(record, context)
        if not dispatch_match:
            continue
        failed_line = _contract_runtime_latest_failed_qa_line(record)
        if not failed_line:
            continue
        successor_dispatch_revision_authority = {}
        if _runtime_context_failed_qa_line_matches_context(
            failed_line,
            context=context,
            server_identity=dispatch_match,
        ):
            identity_binding = _runtime_context_failed_qa_accepted_line_binding(
                record,
                failed_line,
                context=context,
                dispatch_match=dispatch_match,
            )
        else:
            successor_dispatch_revision_authority = (
                _runtime_context_failed_qa_successor_dispatch_revision_authority(
                    record,
                    failed_line=failed_line,
                    context=context,
                    dispatch_match=dispatch_match,
                )
            )
            identity_binding = dict(successor_dispatch_revision_authority)
        if not identity_binding:
            continue
        contract_execution_id = str(record.get("contract_execution_id") or "")
        line_index = failed_line.get("_completed_line_index")
        source_ref = (
            f"contract_runtime:{contract_execution_id}:completed_lines:{line_index}"
            if isinstance(line_index, int)
            else f"contract_runtime:{contract_execution_id}:qa_independent_verification"
        )
        payload = (
            failed_line.get("payload")
            if isinstance(failed_line.get("payload"), Mapping)
            else {}
        )
        dispatch_payload = (
            dispatch_match.get("payload")
            if isinstance(dispatch_match.get("payload"), Mapping)
            else {}
        )
        dispatch_route_identity = (
            dispatch_payload.get("route_identity")
            if isinstance(dispatch_payload.get("route_identity"), Mapping)
            else {}
        )
        return {
            "schema_version": (
                "runtime_context.contract_runtime_failed_qa_revision_evidence.v1"
            ),
            "source": "contract_runtime_completed_lines",
            "status": "revision_required",
            "project_id": project_id,
            "backlog_id": backlog_id,
            "contract_execution_id": contract_execution_id,
            "contract_id": str(record.get("contract_id") or ""),
            "failed_qa_line_id": str(failed_line.get("line_id") or ""),
            "failed_qa_status": str(
                failed_line.get("status") or payload.get("status") or ""
            ),
            "failed_qa_source_ref": source_ref,
            "dispatch_source_ref": str(dispatch_match.get("source_ref") or ""),
            "dispatch_route_identity": {
                field: str(dispatch_route_identity.get(field) or "").strip()
                for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
                if str(dispatch_route_identity.get(field) or "").strip()
            },
            "identity_binding": identity_binding,
            "successor_dispatch_revision_authority": dict(
                successor_dispatch_revision_authority
            ),
            "runtime_context_id": _contract_runtime_context_identity(context)[0],
            "task_id": str(getattr(context, "task_id", "") or ""),
            "parent_task_id": _runtime_context_mf_sub_parent_task_id(context),
            "worker_role": "mf_sub",
            "failed_qa_rejoin_reopened": failed_qa_rejoin_reopened,
            "raw_tokens_exposed": False,
            "observer_authored_worker_evidence": False,
        }
    return {}


def _runtime_context_failed_qa_running_revision_rejoin_authority(
    *,
    context: Any,
    evidence: Mapping[str, Any] | None,
    contract_execution_id: str,
    route_identity: Mapping[str, Any] | None,
    now_iso: str = "",
):
    """Bind immutable failed-QA evidence to one fresh running replacement."""

    from .parallel_branch_runtime import (
        BranchRuntimeFenceError,
        FailedQaRunningRevisionRejoinAuthority,
        STATE_RUNNING,
        failed_qa_running_revision_clean_worktree_head,
        failed_qa_running_revision_session_identity,
        runtime_context_secret_hash,
    )

    proof = dict(evidence or {})
    binding = (
        dict(proof.get("identity_binding") or {})
        if isinstance(proof.get("identity_binding"), Mapping)
        else {}
    )
    execution_id = str(contract_execution_id or "").strip()
    context_runtime_id = str(
        getattr(context, "runtime_context_id", "") or ""
    ).strip()
    context_task_id = str(getattr(context, "task_id", "") or "").strip()
    context_parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    context_project_id = str(
        getattr(context, "project_id", "") or ""
    ).strip()
    context_backlog_id = str(
        getattr(context, "backlog_id", "") or ""
    ).strip()
    replacement_attempt = int(getattr(context, "attempt", 0) or 0)
    replacement_retry_round = int(
        getattr(context, "retry_round", 0) or 0
    )
    if (
        str(getattr(context, "status", "") or "") != STATE_RUNNING
        or replacement_attempt <= 1
        or replacement_retry_round != 0
        or str(proof.get("schema_version") or "")
        != "runtime_context.contract_runtime_failed_qa_revision_evidence.v1"
        or str(proof.get("status") or "") != "revision_required"
        or str(proof.get("source") or "")
        != "contract_runtime_completed_lines"
        or bool(proof.get("failed_qa_rejoin_reopened"))
        or not binding
        or not execution_id
    ):
        return None

    expected_proof_identity = {
        "project_id": context_project_id,
        "backlog_id": context_backlog_id,
        "contract_execution_id": execution_id,
        "runtime_context_id": context_runtime_id,
        "task_id": context_task_id,
        "parent_task_id": context_parent_task_id,
    }
    if any(
        str(proof.get(field) or "").strip() != expected
        for field, expected in expected_proof_identity.items()
    ):
        return None

    binding_hash = str(binding.get("binding_hash") or "").strip()
    unhashed_binding = dict(binding)
    unhashed_binding.pop("binding_hash", None)
    expected_binding = {
        "runtime_context_id": context_runtime_id,
        "task_id": context_task_id,
        "parent_task_id": context_parent_task_id,
        "worker_id": str(getattr(context, "worker_id", "") or "").strip(),
        "worker_slot_id": str(
            getattr(context, "worker_slot_id", "")
            or getattr(context, "worker_id", "")
            or ""
        ).strip(),
        "fence_token_hash": runtime_context_secret_hash(
            str(getattr(context, "fence_token", "") or "")
        ),
        "candidate_commit_sha": str(
            getattr(context, "head_commit", "") or ""
        ).strip(),
    }
    if (
        not binding_hash
        or binding_hash != stable_sha256(unhashed_binding)
        or any(
            str(binding.get(field) or "").strip()
            != str(value or "").strip()
            for field, value in expected_binding.items()
        )
    ):
        return None

    source_prefix = f"contract_runtime:{execution_id}:"
    dispatch_source_ref = str(
        proof.get("dispatch_source_ref") or ""
    ).strip()
    failed_qa_source_ref = str(
        proof.get("failed_qa_source_ref") or ""
    ).strip()
    if (
        str(binding.get("dispatch_source_ref") or "").strip()
        != dispatch_source_ref
        or not dispatch_source_ref.startswith(source_prefix)
        or not failed_qa_source_ref.startswith(source_prefix)
    ):
        return None

    selected_route_identity = {
        field: str((route_identity or {}).get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    dispatch_route_identity = (
        proof.get("dispatch_route_identity")
        if isinstance(proof.get("dispatch_route_identity"), Mapping)
        else {}
    )
    safe_dispatch_route_identity = {
        field: str(dispatch_route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    selected_complete = all(selected_route_identity.values())
    dispatch_complete = all(safe_dispatch_route_identity.values())
    if selected_complete and dispatch_complete and any(
        selected_route_identity[field] != safe_dispatch_route_identity[field]
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    ):
        return None
    safe_route_identity = (
        selected_route_identity
        if selected_complete
        else safe_dispatch_route_identity
    )
    if not all(safe_route_identity.values()):
        return None

    candidate_commit = expected_binding["candidate_commit_sha"]
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", candidate_commit):
        return None
    session_identity = failed_qa_running_revision_session_identity(
        context,
        now_iso=now_iso,
    )
    if not session_identity:
        return None
    try:
        actual_worktree_head = (
            failed_qa_running_revision_clean_worktree_head(context)
        )
    except BranchRuntimeFenceError:
        return None
    if actual_worktree_head != candidate_commit.lower():
        return None
    owned_files = tuple(
        str(value or "").strip()
        for value in (
            getattr(context, "owned_files", ())
            or getattr(context, "target_files", ())
            or ()
        )
        if str(value or "").strip()
    )
    core = {
        "project_id": context_project_id,
        "backlog_id": context_backlog_id,
        **expected_binding,
        "contract_execution_id": execution_id,
        "dispatch_source_ref": dispatch_source_ref,
        "failed_qa_source_ref": failed_qa_source_ref,
        "identity_binding_hash": binding_hash,
        "route_identity_hash": stable_sha256(safe_route_identity),
        "branch_ref": str(getattr(context, "branch_ref", "") or "").strip(),
        "target_project_root": _runtime_context_effective_target_project_root(
            context
        ),
        "worktree_path": str(
            getattr(context, "worktree_path", "") or ""
        ).strip(),
        "merge_queue_id": str(
            getattr(context, "merge_queue_id", "") or ""
        ).strip(),
        "owned_files": owned_files,
        "replacement_attempt": replacement_attempt,
        "replacement_retry_round": replacement_retry_round,
        **session_identity,
        "actual_worktree_head": actual_worktree_head,
        "worktree_clean": True,
        "schema_version": (
            "parallel_branch.failed_qa_running_revision_rejoin_authority.v1"
        ),
        "server_derived": True,
        "caller_claims_trusted": False,
        "immutable_failed_qa_verified": True,
    }
    if not all(
        (
            core["project_id"],
            core["backlog_id"],
            core["runtime_context_id"],
            core["task_id"],
            core["parent_task_id"],
            core["worker_id"],
            core["worker_slot_id"],
            core["fence_token_hash"],
            core["branch_ref"],
            core["target_project_root"],
            core["worktree_path"],
            core["merge_queue_id"],
            core["owned_files"],
        )
    ):
        return None
    return FailedQaRunningRevisionRejoinAuthority(
        **core,
        authority_hash=stable_sha256(core),
    )


def _runtime_context_post_qa_explicit_positive_status(
    value: Mapping[str, Any],
) -> bool:
    """Require one explicit positive status without accepting omissions."""

    if not _contract_runtime_line_status_passes(value):
        return False
    return any(
        str(value.get(field) or "").strip().lower()
        in {
            "accept",
            "accepted",
            "complete",
            "completed",
            "ok",
            "pass",
            "passed",
            "success",
            "succeeded",
            "validate",
            "validated",
        }
        for field in ("status", "verdict", "decision")
    )


def _runtime_context_post_qa_dispatch_impersonation_safe(
    line: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> bool:
    """Fail closed for impersonation except an immutable legacy dispatch."""

    values = [
        source.get("observer_impersonation")
        for source in (line, payload)
        if "observer_impersonation" in source
    ]
    if any(value is not False for value in values):
        return False
    if len(values) == 2:
        return True

    ticket = (
        payload.get("dispatch_ticket_authority")
        if isinstance(payload.get("dispatch_ticket_authority"), Mapping)
        else {}
    )
    return bool(
        not values
        and str(ticket.get("schema_version") or "")
        == "mf_parallel.dispatch_ticket_authority.v1"
        and str(ticket.get("source") or "") == "observer_route_token_refs"
        and ticket.get("server_resolved_child_route_identity") is True
        and ticket.get("runtime_context_bound") is True
        and "observer_impersonation_explicit" not in ticket
    )


def _runtime_context_post_qa_legacy_worker_commit_acceptance(
    line: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> bool:
    """Recognize the immutable pre-status worker-commit projection only."""

    if any(
        field in source
        for source in (line, payload)
        for field in ("status", "verdict", "decision")
    ):
        return False
    implementation_lineage = (
        payload.get("worker_implementation_lineage")
        if isinstance(payload.get("worker_implementation_lineage"), Mapping)
        else {}
    )
    graph_evidence = (
        payload.get("graph_trace_db_evidence")
        if isinstance(payload.get("graph_trace_db_evidence"), Mapping)
        else {}
    )
    return bool(
        _contract_runtime_line_status_passes(line)
        and _contract_runtime_line_status_passes(payload)
        and str(payload.get("schema_version") or "")
        == "runtime_context.worker_commit.v1"
        and payload.get("db_verified") is True
        and payload.get("clean_worktree") is True
        and payload.get("raw_session_token_persisted") is False
        and payload.get("raw_fence_token_persisted") is False
        and payload.get("observer_impersonation") is False
        and str(payload.get("implementation_lineage_ref") or "").startswith(
            "contract-runtime:worker-implementation:sha256:"
        )
        and str(implementation_lineage.get("schema_version") or "")
        == "contract_runtime.worker_implementation_lineage.v1"
        and str(graph_evidence.get("schema_version") or "")
        == "mf_subagent_graph_trace_db_evidence.v1"
        and graph_evidence.get("db_verified") is True
    )


def _runtime_context_post_qa_worker_commit_acceptance(
    line: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> bool:
    """Require accepted line and payload, with one sealed legacy exception."""

    return bool(
        (
            _runtime_context_post_qa_explicit_positive_status(line)
            and _runtime_context_post_qa_explicit_positive_status(payload)
        )
        or _runtime_context_post_qa_legacy_worker_commit_acceptance(
            line,
            payload,
        )
    )


def _runtime_context_post_qa_qa_impersonation_safe(
    line: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> bool:
    """Require explicit non-impersonation or authenticated legacy QA."""

    values = [
        source.get("observer_impersonation")
        for source in (line, payload)
        if "observer_impersonation" in source
    ]
    if any(value is not False for value in values):
        return False
    if len(values) == 2:
        return True
    provenance = (
        line.get("qa_evidence_provenance")
        if isinstance(line.get("qa_evidence_provenance"), Mapping)
        else {}
    )
    completion_gate = (
        provenance.get("completion_status_gate")
        if isinstance(provenance.get("completion_status_gate"), Mapping)
        else {}
    )
    return bool(
        values == [False]
        and "payload_observer_impersonation_explicit" not in provenance
        and _contract_runtime_authenticated_qa_provenance(line)
        and str(completion_gate.get("schema_version") or "")
        == "contract_runtime.qa_completion_status_gate.v1"
        and completion_gate.get("server_derived") is True
        and completion_gate.get("top_level_status_present") is True
    )


def _runtime_context_post_qa_exact_dispatch_line_match(
    record: Mapping[str, Any],
    *,
    context: Any,
    route_identity: Mapping[str, Any],
) -> dict[str, Any]:
    """Return only a canonical dispatch that exactly binds this worker lane."""

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    execution_id = str(record.get("contract_execution_id") or "").strip()
    worker_id = str(getattr(context, "worker_id", "") or "").strip()
    worker_slot_id = str(
        getattr(context, "worker_slot_id", "") or worker_id
    ).strip()
    expected_text = {
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "worker_role": "mf_sub",
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "target_project_root": (
            _runtime_context_effective_target_project_root(context)
        ),
        "worktree_path": str(
            getattr(context, "worktree_path", "") or ""
        ).strip(),
        "branch_ref": str(getattr(context, "branch_ref", "") or "").strip(),
        "merge_queue_id": str(
            getattr(context, "merge_queue_id", "") or ""
        ).strip(),
    }
    expected_owned_files = tuple(
        sorted(
            {
                str(value or "").strip()
                for value in (
                    getattr(context, "owned_files", ())
                    or getattr(context, "target_files", ())
                    or ()
                )
                if str(value or "").strip()
            }
        )
    )
    expected_route = {
        field: str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    if not (
        all(expected_text.values())
        and expected_owned_files
        and all(expected_route.values())
    ):
        return {}

    def _same_path(actual: str, expected: str) -> bool:
        try:
            return bool(
                actual
                and expected
                and Path(actual).resolve() == Path(expected).resolve()
            )
        except (OSError, RuntimeError, TypeError, ValueError):
            return False

    completed_lines = record.get("completed_lines")
    if not isinstance(completed_lines, list):
        return {}
    for index, line in enumerate(completed_lines):
        if not isinstance(line, Mapping):
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        if (
            str(line.get("stage_id") or "").strip() != "dispatch"
            or str(line.get("line_id") or "").strip()
            != "observer_dispatch_bounded_workers"
            or str(line.get("evidence_kind") or "").strip()
            != "dispatch_bounded_worker"
            or str(line.get("actor_role") or "").strip() != "observer"
            or not _contract_runtime_line_status_passes(line)
            or not payload
            or not _runtime_context_post_qa_dispatch_impersonation_safe(
                line,
                payload,
            )
        ):
            continue
        exact = True
        for field, expected in expected_text.items():
            payload_value = str(payload.get(field) or "").strip()
            line_value = str(line.get(field) or "").strip()
            values = [value for value in (payload_value, line_value) if value]
            if not values or any(value != expected for value in values):
                exact = False
                break
            if field in {"target_project_root", "worktree_path"} and not all(
                _same_path(value, expected) for value in values
            ):
                exact = False
                break
        if not exact:
            continue
        observer_command_values = [
            str(source.get("observer_command_id") or "").strip()
            for source in (line, payload)
            if str(source.get("observer_command_id") or "").strip()
        ]
        if any(value != execution_id for value in observer_command_values):
            continue
        payload_owned_files = tuple(
            sorted(
                {
                    str(value or "").strip()
                    for value in payload.get("owned_files") or []
                    if str(value or "").strip()
                }
            )
        )
        if payload_owned_files != expected_owned_files:
            continue
        if "owned_files" in line:
            line_owned_files = tuple(
                sorted(
                    {
                        str(value or "").strip()
                        for value in line.get("owned_files") or []
                        if str(value or "").strip()
                    }
                )
            )
            if line_owned_files != expected_owned_files:
                continue
        dispatch_route = (
            payload.get("route_identity")
            if isinstance(payload.get("route_identity"), Mapping)
            else {}
        )
        if any(
            str(dispatch_route.get(field) or "").strip() != expected
            for field, expected in expected_route.items()
        ):
            continue
        if any(
            str(line.get(field) or "").strip()
            and str(line.get(field) or "").strip() != expected
            for field, expected in expected_route.items()
        ):
            continue
        return {
            "schema_version": (
                "runtime_context.post_qa_exact_dispatch_line_match.v1"
            ),
            "contract_execution_id": execution_id,
            "line_index": index,
            "line": dict(line),
            "payload": dict(payload),
            "source_ref": (
                f"contract_runtime:{execution_id}:completed_lines:{index}"
            ),
            "exact_identity": True,
        }
    return {}


def _runtime_context_post_qa_worker_startup_lineage(
    record: Mapping[str, Any],
    *,
    context: Any,
) -> dict[str, Any]:
    """Return the canonical startup identity for exact worker-commit binding."""

    from .parallel_branch_runtime import (
        runtime_context_secret_hash,
        runtime_context_session_token_ref,
    )

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    execution_id = str(record.get("contract_execution_id") or "").strip()
    worker_id = str(getattr(context, "worker_id", "") or "").strip()
    worker_slot_id = str(
        getattr(context, "worker_slot_id", "") or worker_id
    ).strip()
    target_project_root = _runtime_context_effective_target_project_root(context)
    expected_fence_token_hash = runtime_context_secret_hash(
        str(getattr(context, "fence_token", "") or "").strip()
    )
    expected_owned_files = tuple(
        sorted(
            {
                str(value or "").strip()
                for value in (
                    getattr(context, "owned_files", ())
                    or getattr(context, "target_files", ())
                    or ()
                )
                if str(value or "").strip()
            }
        )
    )
    if not all(
        (
            runtime_context_id,
            task_id,
            parent_task_id,
            execution_id,
            worker_id,
            worker_slot_id,
            target_project_root,
            expected_fence_token_hash,
            expected_owned_files,
        )
    ):
        return {}

    expected_text = {
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "worker_role": "mf_sub",
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "target_project_root": target_project_root,
        "fence_token_hash": expected_fence_token_hash,
    }
    completed_lines = record.get("completed_lines")
    if not isinstance(completed_lines, list):
        return {}
    for index in range(len(completed_lines) - 1, -1, -1):
        line = completed_lines[index]
        if not isinstance(line, Mapping):
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        if (
            str(line.get("stage_id") or "").strip() != "worker_startup"
            or str(line.get("line_id") or "").strip() != "worker_startup"
            or str(line.get("evidence_kind") or "").strip()
            != "mf_subagent_startup"
            or str(line.get("actor_role") or "").strip() != "mf_sub"
            or bool(line.get("observer_impersonation"))
            or bool(payload.get("observer_impersonation"))
            or not _contract_runtime_line_status_passes(line)
            or not payload
        ):
            continue
        exact = True
        for field, expected in expected_text.items():
            payload_value = str(payload.get(field) or "").strip()
            line_value = str(line.get(field) or "").strip()
            values = [value for value in (payload_value, line_value) if value]
            if not values or any(value != expected for value in values):
                exact = False
                break
        if not exact:
            continue
        startup_owned_files = tuple(
            sorted(
                {
                    str(value or "").strip()
                    for value in payload.get("owned_files") or []
                    if str(value or "").strip()
                }
            )
        )
        if startup_owned_files != expected_owned_files:
            continue
        worker_session_id = str(
            payload.get("worker_session_id")
            or line.get("worker_session_id")
            or ""
        ).strip()
        startup_session_token_ref = str(
            payload.get("session_token_ref")
            or line.get("session_token_ref")
            or ""
        ).strip()
        context_session_token_ref = runtime_context_session_token_ref(context)
        return {
            "schema_version": (
                "runtime_context.post_qa_worker_startup_lineage.v1"
            ),
            "line_index": index,
            "source_ref": (
                f"contract_runtime:{execution_id}:completed_lines:{index}"
            ),
            "worker_id": worker_id,
            "worker_slot_id": worker_slot_id,
            "worker_session_id": worker_session_id,
            "session_token_ref": (
                startup_session_token_ref or context_session_token_ref
            ),
            "session_token_ref_source": (
                "worker_startup"
                if startup_session_token_ref
                else (
                    "runtime_context_stored_hash_lineage"
                    if context_session_token_ref
                    else ""
                )
            ),
            "fence_token_hash": expected_fence_token_hash,
        }
    return {}


def _runtime_context_post_qa_merge_conflict_rejoin_authority(
    conn,
    *,
    project_id: str,
    context: Any,
    record: Mapping[str, Any],
    route_identity: Mapping[str, Any],
) -> tuple[Any | None, dict[str, Any]]:
    """Derive the only non-failed-QA authority that may reopen a closed lane."""

    from .parallel_branch_runtime import (
        FAILED_QA_REVISION_REJOIN_STATES,
        PostQaMergeConflictRejoinAuthority,
    )

    runtime_context_id = str(
        getattr(context, "runtime_context_id", "") or ""
    ).strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    merge_queue_id = str(
        getattr(context, "merge_queue_id", "") or ""
    ).strip()
    branch_ref = str(getattr(context, "branch_ref", "") or "").strip()
    target_project_root = _runtime_context_effective_target_project_root(context)
    worktree_path = str(getattr(context, "worktree_path", "") or "").strip()
    owned_files = tuple(
        str(value or "").strip()
        for value in (
            getattr(context, "owned_files", ())
            or getattr(context, "target_files", ())
            or ()
        )
        if str(value or "").strip()
    )
    execution_id = str(record.get("contract_execution_id") or "").strip()
    diagnostics: dict[str, Any] = {
        "schema_version": (
            "runtime_context.post_qa_merge_conflict_rejoin_diagnostics.v1"
        ),
        "status": "blocked",
        "eligible": False,
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": str(project_id or "").strip(),
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "merge_queue_id": merge_queue_id,
        "errors": [],
    }
    errors: list[str] = diagnostics["errors"]
    if str(getattr(context, "status", "") or "").strip() not in (
        FAILED_QA_REVISION_REJOIN_STATES
    ):
        errors.append("runtime context is not closed at validated/merge_ready")
    if not all(
        (
            project_id,
            runtime_context_id,
            task_id,
            parent_task_id,
            backlog_id,
            merge_queue_id,
            branch_ref,
            target_project_root,
            worktree_path,
            owned_files,
            execution_id,
        )
    ):
        errors.append("runtime/contract/file-fence identity is incomplete")
    if (
        str(record.get("project_id") or "").strip()
        != str(project_id or "").strip()
        or str(record.get("backlog_id") or "").strip() != backlog_id
        or not _is_mf_parallel_record_contract_id(
            str(record.get("contract_id") or "")
        )
    ):
        errors.append("ContractRuntime project/backlog/contract identity mismatch")
    next_action = (
        record.get("runtime_guide", {}).get("next_legal_action", {})
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    if str(next_action.get("line_id") or "").strip() != "observer_merge":
        errors.append("ContractRuntime is not at the post-QA observer_merge line")
    if any(
        isinstance(line, Mapping)
        and (
            str(line.get("evidence_kind") or "").strip()
            == "contract_line_bypass"
            or str(line.get("line_id") or "").strip() == "contract_line_bypass"
        )
        for line in record.get("completed_lines") or []
    ):
        errors.append("historical/bypass ContractRuntime contexts cannot rejoin")

    dispatch_match = _runtime_context_post_qa_exact_dispatch_line_match(
        record,
        context=context,
        route_identity=route_identity,
    )
    if not dispatch_match:
        errors.append("source-backed bounded worker dispatch identity is missing")
    dispatch_payload = (
        dispatch_match.get("payload")
        if isinstance(dispatch_match.get("payload"), Mapping)
        else {}
    )
    dispatch_root = _timeline_first_deep_text(
        dispatch_payload,
        "target_project_root",
    )
    dispatch_worktree = _timeline_first_deep_text(
        dispatch_payload,
        "worktree_path",
    )
    dispatch_branch = _timeline_first_deep_text(dispatch_payload, "branch_ref")
    dispatch_queue = _timeline_first_deep_text(
        dispatch_payload,
        "merge_queue_id",
    )
    dispatch_owned_files = tuple(
        sorted(
            set(
                _runtime_context_service_query_values(
                    dispatch_payload,
                    "owned_files",
                )
            )
        )
    )
    try:
        roots_match = bool(
            dispatch_root
            and Path(dispatch_root).resolve()
            == Path(target_project_root).resolve()
            and dispatch_worktree
            and Path(dispatch_worktree).resolve()
            == Path(worktree_path).resolve()
        )
    except (OSError, RuntimeError, TypeError, ValueError):
        roots_match = False
    if not roots_match:
        errors.append("source-backed dispatch root/worktree identity mismatch")
    if dispatch_branch != branch_ref or dispatch_queue != merge_queue_id:
        errors.append("source-backed dispatch branch/merge-queue identity mismatch")
    if dispatch_owned_files != tuple(sorted(set(owned_files))):
        errors.append("source-backed dispatch owned-file fence mismatch")

    safe_route_identity = {
        field: str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    if not all(safe_route_identity.values()):
        errors.append("active route identity is incomplete")
    for field, expected_value in safe_route_identity.items():
        if (
            _timeline_first_deep_text(dispatch_payload, field)
            != expected_value
        ):
            errors.append(f"source-backed dispatch {field} identity mismatch")

    startup_lineage = _runtime_context_post_qa_worker_startup_lineage(
        record,
        context=context,
    )
    if not startup_lineage:
        errors.append("exact source-backed worker startup lineage is missing")

    completed_lines = list(record.get("completed_lines") or [])
    worker_commit_index = -1
    worker_commit_line: Mapping[str, Any] = {}
    worker_commit_payload: Mapping[str, Any] = {}
    candidate_commit = ""
    for index in range(len(completed_lines) - 1, -1, -1):
        line = completed_lines[index]
        if (
            not isinstance(line, Mapping)
            or str(line.get("line_id") or "").strip() != "worker_commit"
            or str(line.get("stage_id") or "").strip() != "worker_commit"
            or str(line.get("evidence_kind") or "").strip() != "worker_commit"
            or str(line.get("actor_role") or "").strip() != "mf_sub"
            or bool(line.get("observer_impersonation"))
            or not _runtime_context_contract_line_matches_worker(
                line,
                runtime_context_id=runtime_context_id,
                task_id=task_id,
            )
        ):
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        expected_worker_id = str(
            startup_lineage.get("worker_id") or ""
        ).strip()
        expected_worker_slot_id = str(
            startup_lineage.get("worker_slot_id") or ""
        ).strip()
        expected_worker_session_id = str(
            startup_lineage.get("worker_session_id") or ""
        ).strip()
        expected_session_token_ref = str(
            startup_lineage.get("session_token_ref") or ""
        ).strip()
        expected_fence_token_hash = str(
            startup_lineage.get("fence_token_hash") or ""
        ).strip()
        if (
            not payload
            or bool(payload.get("observer_impersonation"))
            or not _runtime_context_post_qa_worker_commit_acceptance(
                line,
                payload,
            )
            or any(
                str(source.get(field) or "").strip() != expected
                for source in (line, payload)
                for field, expected in (
                    ("runtime_context_id", runtime_context_id),
                    ("task_id", task_id),
                    ("parent_task_id", parent_task_id),
                    ("worker_id", expected_worker_id),
                    ("worker_slot_id", expected_worker_slot_id),
                )
            )
        ):
            continue
        lineage_fields = (
            ("worker_session_id", expected_worker_session_id),
            ("session_token_ref", expected_session_token_ref),
            ("fence_token_hash", expected_fence_token_hash),
        )
        lineage_matches = True
        for field, expected in lineage_fields:
            values = [
                str(source.get(field) or "").strip()
                for source in (line, payload)
                if str(source.get(field) or "").strip()
            ]
            if not values or not expected or any(
                value != expected for value in values
            ):
                lineage_matches = False
                break
        if not lineage_matches:
            continue
        commits = {
            str(value or "").strip().lower()
            for value in (
                line.get("commit_sha"),
                payload.get("worker_commit_sha"),
                payload.get("commit_sha"),
                payload.get("immutable_head_commit"),
                payload.get("validated_head_commit"),
            )
            if str(value or "").strip()
        }
        if len(commits) != 1:
            continue
        candidate_commit = next(iter(commits))
        if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", candidate_commit):
            continue
        worker_commit_index = index
        worker_commit_line = line
        worker_commit_payload = payload
        break
    if worker_commit_index < 0:
        errors.append("exact source-backed worker_commit is missing")
    candidate_owned_files = tuple(
        sorted(
            set(
                _runtime_context_service_query_values(
                    worker_commit_payload,
                    "owned_files",
                )
            )
        )
    )
    candidate_changed_files = tuple(
        sorted(
            set(
                _runtime_context_service_query_values(
                    worker_commit_payload,
                    "changed_files",
                )
            )
        )
    )
    if (
        candidate_owned_files != tuple(sorted(set(owned_files)))
        or not candidate_changed_files
        or any(path not in set(owned_files) for path in candidate_changed_files)
    ):
        errors.append("worker_commit file-fence identity is missing or widened")
    if (
        _timeline_first_deep_text(
            worker_commit_line,
            "target_project_root",
        )
        != target_project_root
    ):
        errors.append("worker_commit target root identity mismatch")

    qa_index = -1
    for index in range(len(completed_lines) - 1, worker_commit_index, -1):
        line = completed_lines[index]
        if (
            not isinstance(line, Mapping)
            or str(line.get("line_id") or "").strip()
            != "qa_independent_verification"
            or not _runtime_context_contract_line_matches_worker(
                line,
                runtime_context_id=runtime_context_id,
                task_id=task_id,
            )
        ):
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        qa_commit = str(
            line.get("commit_sha")
            or payload.get("candidate_commit_sha")
            or payload.get("candidate_commit")
            or payload.get("commit_sha")
            or ""
        ).strip().lower()
        actor_role = str(
            line.get("actor_role")
            or line.get("evidence_owner_role")
            or payload.get("actor_role")
            or ""
        ).strip().lower()
        canonical_known_baseline = (
            _contract_runtime_known_baseline_qa_acceptance(
                line,
                record=record,
            )
        )
        true_passing_qa = bool(
            not _contract_runtime_value_reports_failed_qa(line)
            and _contract_runtime_line_status_passes(line)
        )
        if (
            qa_commit == candidate_commit
            and actor_role == "qa"
            and _runtime_context_post_qa_qa_impersonation_safe(
                line,
                payload,
            )
            and (true_passing_qa or canonical_known_baseline)
        ):
            qa_index = index
            break
    if qa_index < 0:
        errors.append("later exact independent QA-passed line is missing")
    if errors:
        return None, diagnostics

    conflict = _runtime_context_server_revalidated_merge_conflict_authority(
        conn,
        project_id=str(project_id or "").strip(),
        record=record,
        context=context,
        recorded_commit=candidate_commit,
    )
    diagnostics["merge_conflict_authority"] = dict(conflict)
    if conflict.get("verified") is not True:
        errors.extend(
            conflict.get("errors") or [
                "server did not reproduce the current-target merge conflict"
            ]
        )
        return None, diagnostics

    core = {
        "project_id": str(project_id or "").strip(),
        "backlog_id": backlog_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "runtime_context_id": runtime_context_id,
        "merge_queue_id": merge_queue_id,
        "queue_item_id": str(conflict.get("queue_item_id") or "").strip(),
        "branch_ref": branch_ref,
        "target_project_root": target_project_root,
        "worktree_path": worktree_path,
        "owned_files": tuple(owned_files),
        "candidate_commit": candidate_commit,
        "current_target_head": str(
            conflict.get("current_target_parent_commit") or ""
        ).strip(),
        "dispatch_source_ref": str(
            dispatch_match.get("source_ref") or ""
        ).strip(),
        "worker_commit_source_ref": (
            f"contract_runtime:{execution_id}:completed_lines:"
            f"{worker_commit_index}"
        ),
        "qa_source_ref": (
            f"contract_runtime:{execution_id}:completed_lines:{qa_index}"
        ),
        "merge_preview_id": str(
            conflict.get("preview_evidence_id") or ""
        ).strip(),
        "route_identity_hash": stable_sha256(safe_route_identity),
        "schema_version": (
            "parallel_branch.post_qa_merge_conflict_rejoin_authority.v1"
        ),
        "server_derived": True,
        "caller_claims_trusted": False,
        "independent_qa_passed": True,
        "merge_conflict_verified": True,
        "historical_bypass_context": False,
    }
    authority = PostQaMergeConflictRejoinAuthority(
        **{
            key: value
            for key, value in core.items()
            if key != "schema_version"
        },
        authority_hash=stable_sha256(core),
    )
    diagnostics.update(
        {
            "status": "eligible",
            "eligible": True,
            "errors": [],
            "authority_hash": authority.authority_hash,
            "candidate_commit": candidate_commit,
            "current_target_head": authority.current_target_head,
            "dispatch_source_ref": authority.dispatch_source_ref,
            "worker_commit_source_ref": authority.worker_commit_source_ref,
            "qa_source_ref": authority.qa_source_ref,
            "merge_preview_id": authority.merge_preview_id,
            "route_identity_hash": authority.route_identity_hash,
        }
    )
    return authority, diagnostics


def _runtime_context_latest_post_qa_rejoin_authority_event(
    timeline_events: Sequence[Mapping[str, Any]],
    *,
    runtime_context_id: str,
    task_id: str,
    retarget_only: bool = False,
) -> tuple[Mapping[str, Any], Mapping[str, Any], Mapping[str, Any]]:
    """Return the newest accepted typed rejoin authority for one worker lane."""

    def event_order(event: Mapping[str, Any]) -> int:
        raw = str(event.get("id") or event.get("event_id") or "0").strip()
        return int(raw) if raw.isdigit() else 0

    for event in sorted(timeline_events, key=event_order, reverse=True):
        if not isinstance(event, Mapping):
            continue
        payload = event.get("payload")
        if not isinstance(payload, Mapping):
            continue
        retarget = payload.get("post_qa_rejoin_retarget_authority")
        conflict = payload.get("post_qa_merge_conflict_rejoin_authority")
        authority = (
            retarget
            if isinstance(retarget, Mapping) and retarget
            else {}
            if retarget_only
            else conflict
            if isinstance(conflict, Mapping) and conflict
            else {}
        )
        if (
            str(event.get("event_type") or "").strip()
            == "observer.runtime_context_session_token_rejoin"
            and str(event.get("status") or "").strip() == "accepted"
            and str(payload.get("runtime_context_id") or "").strip()
            == runtime_context_id
            and str(payload.get("task_id") or "").strip() == task_id
            and (
                not retarget_only
                or payload.get("reopen_for_post_qa_target_retarget") is True
            )
            and authority
        ):
            return event, payload, authority
    return {}, {}, {}


def _runtime_context_current_target_preview(
    *,
    worktree_path: str,
    target_ref: str,
    expected_target_head: str,
) -> dict[str, Any]:
    """Read one clean worker HEAD and a stable server-side target preview."""

    from . import batch_jobs
    from .parallel_branch_runtime import git_merge_preview_evidence

    try:
        actual_head = batch_jobs.git_commit(worktree_path)
        dirty_files = _runtime_context_git_dirty_files(worktree_path)
        target_before = batch_jobs.git_commit(worktree_path, ref=target_ref)
        preview = git_merge_preview_evidence(
            repo_root_path=worktree_path,
            target_ref=target_ref,
            branch_ref=actual_head,
            expected_target_head=expected_target_head or target_before,
        )
        target_after = batch_jobs.git_commit(worktree_path, ref=target_ref)
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        return {"error": str(exc)}
    return {
        "actual_head": actual_head,
        "dirty_files": dirty_files,
        "target_before": target_before,
        "target_after": target_after,
        "preview": preview,
    }


def _runtime_context_post_qa_rejoin_retarget_authority(
    conn,
    *,
    project_id: str,
    context: Any,
    record: Mapping[str, Any],
    route_identity: Mapping[str, Any],
    timeline_events: Sequence[Mapping[str, Any]],
) -> tuple[Any | None, dict[str, Any]]:
    """Refresh target authority after a typed post-QA rejoin is already open."""

    from .parallel_branch_runtime import (
        PostQaRejoinRetargetAuthority,
        STATE_MERGE_READY,
        STATE_QUEUED_FOR_MERGE,
        STATE_WORKTREE_READY,
        list_merge_queue_items,
    )

    runtime_context_id = str(
        getattr(context, "runtime_context_id", "") or ""
    ).strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    merge_queue_id = str(
        getattr(context, "merge_queue_id", "") or ""
    ).strip()
    branch_ref = str(getattr(context, "branch_ref", "") or "").strip()
    target_project_root = _runtime_context_effective_target_project_root(
        context
    )
    worktree_path = str(getattr(context, "worktree_path", "") or "").strip()
    owned_files = tuple(
        str(value or "").strip()
        for value in (
            getattr(context, "owned_files", ())
            or getattr(context, "target_files", ())
            or ()
        )
        if str(value or "").strip()
    )
    worker_id = str(getattr(context, "worker_id", "") or "").strip()
    worker_slot_id = str(
        getattr(context, "worker_slot_id", "") or worker_id
    ).strip()
    last_recovery_action = str(
        getattr(context, "last_recovery_action", "") or ""
    ).strip()
    diagnostics: dict[str, Any] = {
        "schema_version": (
            "runtime_context.post_qa_rejoin_retarget_diagnostics.v1"
        ),
        "status": "blocked",
        "eligible": False,
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": str(project_id or "").strip(),
        "backlog_id": backlog_id,
        "contract_execution_id": str(
            record.get("contract_execution_id") or ""
        ).strip(),
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "merge_queue_id": merge_queue_id,
        "last_recovery_action": last_recovery_action,
        "last_recovery_action_authoritative": False,
        "errors": [],
    }
    errors: list[str] = diagnostics["errors"]
    if str(getattr(context, "status", "") or "").strip() != (
        STATE_WORKTREE_READY
    ):
        errors.append("runtime context is not an active worktree_ready rejoin")
    if not all(
        (
            project_id,
            backlog_id,
            runtime_context_id,
            task_id,
            parent_task_id,
            merge_queue_id,
            branch_ref,
            target_project_root,
            worktree_path,
            owned_files,
            worker_id,
            worker_slot_id,
        )
    ):
        errors.append("runtime/worker/file-fence identity is incomplete")
    if (
        str(record.get("project_id") or "").strip()
        != str(project_id or "").strip()
        or str(record.get("backlog_id") or "").strip() != backlog_id
        or not _is_mf_parallel_record_contract_id(
            str(record.get("contract_id") or "")
        )
    ):
        errors.append("ContractRuntime project/backlog/contract identity mismatch")
    next_action = (
        record.get("runtime_guide", {}).get("next_legal_action", {})
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    if str(next_action.get("line_id") or "").strip() != "observer_merge":
        errors.append("ContractRuntime is not at the post-QA observer_merge line")
    if any(
        isinstance(line, Mapping)
        and (
            str(line.get("evidence_kind") or "").strip()
            == "contract_line_bypass"
            or str(line.get("line_id") or "").strip()
            == "contract_line_bypass"
        )
        for line in record.get("completed_lines") or []
    ):
        errors.append("historical/bypass ContractRuntime contexts cannot retarget")
    if errors:
        return None, diagnostics

    safe_route_identity = {
        field: str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    if not all(safe_route_identity.values()):
        errors.append("active route identity is incomplete")
        return None, diagnostics
    route_identity_hash = stable_sha256(safe_route_identity)

    prior_event, prior_payload, prior_authority = (
        _runtime_context_latest_post_qa_rejoin_authority_event(
            timeline_events,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
        )
    )
    if not prior_event:
        errors.append("accepted prior post-QA rejoin authority is missing")
        return None, diagnostics
    diagnostics.update(
        {
            "lineage_source": "latest_accepted_typed_timeline_event",
            "lineage_event_ref": _runtime_context_event_ref(prior_event),
        }
    )

    prior_authority_payload = dict(prior_authority)
    prior_authority_hash = str(
        prior_authority_payload.pop("authority_hash", "") or ""
    ).strip()
    prior_schema = str(prior_authority.get("schema_version") or "").strip()
    if (
        prior_schema
        not in {
            "parallel_branch.post_qa_merge_conflict_rejoin_authority.v1",
            "parallel_branch.post_qa_rejoin_retarget_authority.v1",
        }
        or prior_authority.get("server_derived") is not True
        or prior_authority.get("caller_claims_trusted") is not False
        or prior_authority.get("historical_bypass_context") is not False
        or not prior_authority_hash.startswith("sha256:")
        or prior_authority_hash != stable_sha256(prior_authority_payload)
    ):
        errors.append("prior post-QA rejoin authority is invalid")
    for field, expected in (
        ("project_id", str(project_id or "").strip()),
        ("backlog_id", backlog_id),
        ("task_id", task_id),
        ("parent_task_id", parent_task_id),
        ("runtime_context_id", runtime_context_id),
        ("merge_queue_id", merge_queue_id),
        ("branch_ref", branch_ref),
        ("target_project_root", target_project_root),
        ("worktree_path", worktree_path),
    ):
        if str(prior_authority.get(field) or "").strip() != expected:
            errors.append(f"prior post-QA rejoin {field} identity mismatch")
    if tuple(prior_authority.get("owned_files") or ()) != owned_files:
        errors.append("prior post-QA rejoin owned-file fence mismatch")
    if (
        str(prior_payload.get("worker_id") or "").strip() != worker_id
        or str(
            prior_payload.get("worker_slot_id")
            or prior_payload.get("worker_id")
            or ""
        ).strip()
        != worker_slot_id
    ):
        errors.append("prior post-QA rejoin worker identity mismatch")
    if str(prior_authority.get("route_identity_hash") or "").strip() != (
        route_identity_hash
    ):
        errors.append("prior post-QA rejoin route identity mismatch")

    candidate_commit = str(
        prior_authority.get("candidate_commit") or ""
    ).strip()
    prior_target_head = str(
        prior_authority.get("current_target_head") or ""
    ).strip()
    if not re.fullmatch(r"[0-9a-f]{40,64}", candidate_commit):
        errors.append("prior candidate commit is not a full SHA")
    if not re.fullmatch(r"[0-9a-f]{40,64}", prior_target_head):
        errors.append("prior target head is not a full SHA")

    completed_worker_commit = next(
        (
            line
            for line in reversed(record.get("completed_lines") or [])
            if isinstance(line, Mapping)
            and str(line.get("line_id") or "").strip() == "worker_commit"
            and _runtime_context_contract_line_matches_worker(
                line,
                runtime_context_id=runtime_context_id,
                task_id=task_id,
            )
            and str(
                line.get("commit_sha")
                or (
                    line.get("payload", {}).get("worker_commit_sha")
                    if isinstance(line.get("payload"), Mapping)
                    else ""
                )
                or ""
            ).strip()
            == candidate_commit
        ),
        None,
    )
    if completed_worker_commit is None:
        errors.append("prior candidate lacks exact source-backed worker_commit")

    items = list_merge_queue_items(conn, project_id, merge_queue_id)
    matches = [item for item in items if item.task_id == task_id]
    if len(matches) != 1:
        errors.append("durable merge queue task identity is missing or ambiguous")
        return None, diagnostics
    item = matches[0]
    queue_previous_target = str(
        item.current_target_head or item.validated_target_head or ""
    ).strip()
    if str(item.backlog_id or "").strip() != backlog_id:
        errors.append("durable merge queue backlog identity mismatch")
    if str(item.branch_ref or "").strip() != branch_ref:
        errors.append("durable merge queue branch identity mismatch")
    if str(item.branch_head or "").strip() != candidate_commit:
        errors.append("durable merge queue candidate differs from prior worker_commit")
    if str(item.status or "").strip() not in {
        STATE_MERGE_READY,
        STATE_QUEUED_FOR_MERGE,
    }:
        errors.append("durable merge queue is not retargetable")
    target_ref = str(item.target_ref or "").strip()
    if not target_ref:
        errors.append("durable merge queue target ref is missing")
    if queue_previous_target != prior_target_head:
        errors.append("durable merge queue prior target identity drifted")
    if errors:
        return None, diagnostics

    target_state = _runtime_context_current_target_preview(
        worktree_path=worktree_path,
        target_ref=target_ref,
        expected_target_head="",
    )
    if target_state.get("error"):
        errors.append(
            f"post-QA rejoin retarget preview failed: {target_state['error']}"
        )
        return None, diagnostics
    actual_worker_head = str(target_state["actual_head"])
    dirty_files = list(target_state["dirty_files"])
    current_target_head = str(target_state["target_before"])
    preview = target_state["preview"]
    diagnostics.update(
        {
            "queue_item_id": str(item.queue_item_id or "").strip(),
            "candidate_commit": candidate_commit,
            "actual_worker_head": actual_worker_head,
            "previous_target_head": queue_previous_target,
            "current_target_head": current_target_head,
            "dirty_files": dirty_files,
        }
    )
    if dirty_files:
        errors.append("assigned worktree is dirty")
    if not _git_commit_is_ancestor(
        Path(worktree_path),
        candidate_commit,
        actual_worker_head,
    ):
        errors.append("current worker HEAD is not a descendant of prior candidate")
    if not re.fullmatch(r"[0-9a-f]{40,64}", current_target_head):
        errors.append("current durable target ref is not a full SHA")
    if current_target_head == queue_previous_target:
        diagnostics.update(
            {
                "status": "not_needed",
                "eligible": False,
                "errors": [],
            }
        )
        return None, diagnostics
    if errors:
        return None, diagnostics

    diagnostics["preview_evidence_id"] = str(
        preview.get("evidence_id") or ""
    ).strip()
    diagnostics["preview_status"] = str(preview.get("status") or "").strip()
    diagnostics["preview_reason"] = str(preview.get("reason") or "").strip()
    if str(preview.get("branch_commit") or "").strip() != actual_worker_head:
        errors.append("post-QA retarget preview worker identity mismatch")
    if str(preview.get("target_commit") or "").strip() != current_target_head:
        errors.append("post-QA retarget preview target identity mismatch")
    if str(target_state["target_after"]) != current_target_head:
        errors.append("durable merge target moved after retarget preview")
    if (
        preview.get("passed") is not True
        or str(preview.get("status") or "").strip() != "pass"
    ):
        errors.append("post-QA retarget requires a current clean preview")
    if errors:
        return None, diagnostics

    core = {
        "project_id": str(project_id or "").strip(),
        "backlog_id": backlog_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "runtime_context_id": runtime_context_id,
        "merge_queue_id": merge_queue_id,
        "queue_item_id": str(item.queue_item_id or "").strip(),
        "branch_ref": branch_ref,
        "target_ref": target_ref,
        "target_project_root": target_project_root,
        "worktree_path": worktree_path,
        "owned_files": owned_files,
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "candidate_commit": candidate_commit,
        "actual_worker_head": actual_worker_head,
        "previous_target_head": queue_previous_target,
        "current_target_head": current_target_head,
        "prior_rejoin_event_ref": _runtime_context_event_ref(prior_event),
        "prior_rejoin_authority_hash": prior_authority_hash,
        "merge_preview_id": str(preview.get("evidence_id") or "").strip(),
        "route_identity_hash": route_identity_hash,
        "schema_version": (
            "parallel_branch.post_qa_rejoin_retarget_authority.v1"
        ),
        "server_derived": True,
        "caller_claims_trusted": False,
        "current_preview_passed": True,
        "historical_bypass_context": False,
    }
    authority = PostQaRejoinRetargetAuthority(
        **{
            key: value
            for key, value in core.items()
            if key != "schema_version"
        },
        authority_hash=stable_sha256(core),
    )
    diagnostics.update(
        {
            "status": "eligible",
            "eligible": True,
            "errors": [],
            "authority_hash": authority.authority_hash,
            "prior_rejoin_event_ref": authority.prior_rejoin_event_ref,
            "prior_rejoin_authority_hash": (
                authority.prior_rejoin_authority_hash
            ),
        }
    )
    return authority, diagnostics


def _runtime_context_validated_missing_finish_rejoin_authority(
    conn,
    *,
    project_id: str,
    context: Any,
    body: Mapping[str, Any],
    contract_execution_id: str,
    route_identity: Mapping[str, Any],
    timeline_refs: Mapping[str, Any],
) -> dict[str, Any]:
    """Authorize one auth-only rejoin after a partially persisted finish.

    ``record_branch_finish_gate`` advances the RuntimeContext before the
    canonical ContractRuntime finish line and timeline event are written.  If
    the caller loses its raw worker auth in that narrow interval, the ordinary
    rejoin primitive rejects the already-validated context.  This projection
    recognizes only the exact source-backed worker round that is still waiting
    on ``worker_finish_gate``; it never reopens or revises the round.
    """

    from .parallel_branch_runtime import STATE_VALIDATED

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    authority = {
        "schema_version": (
            "runtime_context.validated_missing_finish_rejoin_authority.v1"
        ),
        "status": "blocked",
        "eligible": False,
        "server_derived": True,
        "caller_opt_in": False,
        "auth_only": True,
        "project_id": project_id,
        "backlog_id": str(getattr(context, "backlog_id", "") or "").strip(),
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "branch_ref": str(getattr(context, "branch_ref", "") or "").strip(),
        "worktree_path": str(getattr(context, "worktree_path", "") or "").strip(),
        "merge_queue_id": str(
            getattr(context, "merge_queue_id", "") or ""
        ).strip(),
        "checkpoint_id": str(
            getattr(context, "checkpoint_id", "") or ""
        ).strip(),
        "context_status": str(getattr(context, "status", "") or "").strip(),
        "context_replay_source": str(
            getattr(context, "replay_source", "") or ""
        ).strip(),
        "route_identity_hash": "",
        "worker_commit_sha": "",
        "finish_attestation_source_ref": "",
        "errors": [],
        "preserves": [
            "status",
            "candidate",
            "attempt",
            "retry_round",
            "implementation",
            "worker_commit",
            "qa",
            "merge",
            "close",
            "evidence",
        ],
    }
    errors: list[str] = authority["errors"]
    if (
        authority["context_status"] != STATE_VALIDATED
        or authority["context_replay_source"] != "mf_sub_finish_gate"
        or not authority["checkpoint_id"]
    ):
        errors.append("runtime_context_not_partially_advanced_by_finish_gate")
    if str(timeline_refs.get("finish_event_ref") or "").strip():
        errors.append("authoritative_finish_gate_timeline_already_exists")
    expected_target_root = _runtime_context_effective_target_project_root(
        context
    )
    request_scope = {
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "target_project_root": expected_target_root,
    }
    scope_mismatches = [
        field
        for field, expected in request_scope.items()
        if not expected or str(body.get(field) or "").strip() != expected
    ]
    if scope_mismatches:
        errors.append(
            "exact_runtime_scope_mismatch:" + ",".join(scope_mismatches)
        )

    execution_id = str(contract_execution_id or "").strip()
    record: Mapping[str, Any] = {}
    if execution_id:
        try:
            runtime = _contract_runtime(conn)
            record = runtime.current_record(
                execution_id,
                actor_role="mf_sub",
            )
        except (ContractRuntimeError, sqlite3.Error):
            record = {}
    if (
        not record
        or str(record.get("project_id") or "").strip() != project_id
        or str(record.get("backlog_id") or "").strip()
        != authority["backlog_id"]
        or not _contract_runtime_dispatch_line_match(record, context)
    ):
        errors.append("source_backed_contract_runtime_dispatch_missing")
    next_line = _contract_runtime_next_line(record)
    if (
        str(next_line.get("stage_id") or "").strip() != "worker_finish"
        or str(next_line.get("line_id") or "").strip()
        != "worker_finish_gate"
        or str(next_line.get("evidence_kind") or "").strip()
        != "mf_subagent_finish_gate"
        or str(next_line.get("owner_role") or "").strip() != "mf_sub"
    ):
        errors.append("contract_runtime_not_waiting_at_worker_finish_gate")

    expected_route = _runtime_context_latest_route_identity(conn, context)
    selected_route = {
        field: str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    if (
        not expected_route
        or any(not selected_route.get(field) for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS)
        or _runtime_context_route_identity_mismatch_fields(
            expected_route,
            selected_route,
        )
    ):
        errors.append("current_route_identity_mismatch")
    else:
        authority["route_identity_hash"] = stable_sha256(selected_route)

    startup_principal = (
        timeline_refs.get("startup_hint")
        if isinstance(timeline_refs.get("startup_hint"), Mapping)
        else {}
    )
    expected_actual_host = str(
        getattr(context, "actual_host_worker_id", "") or ""
    ).strip()
    expected_worker_session = str(
        getattr(context, "host_session_id", "")
        or startup_principal.get("worker_session_id")
        or ""
    ).strip()
    expected_identity = {
        "worker_id": str(getattr(context, "worker_id", "") or "").strip(),
        "worker_slot_id": str(
            getattr(context, "worker_slot_id", "")
            or getattr(context, "worker_id", "")
            or ""
        ).strip(),
        "agent_id": expected_actual_host,
        "actual_host_worker_id": expected_actual_host,
        "worker_session_id": expected_worker_session,
    }
    expected_host_startup_id = str(
        getattr(context, "host_startup_id", "") or ""
    ).strip()
    expected_host_session_id = str(
        getattr(context, "host_session_id", "") or ""
    ).strip()
    if expected_host_startup_id:
        expected_identity["host_startup_id"] = expected_host_startup_id
    if expected_host_session_id:
        expected_identity["host_session_id"] = expected_host_session_id
    identity_mismatches = [
        field
        for field, expected in expected_identity.items()
        if not expected or str(body.get(field) or "").strip() != expected
    ]
    if identity_mismatches:
        errors.append(
            "same_exact_host_identity_mismatch:"
            + ",".join(identity_mismatches)
        )
    authority["host_identity"] = {
        **expected_identity,
        "verified": not identity_mismatches,
        "source": "runtime_context+worker_startup",
    }

    completed_lines = _contract_runtime_completed_lines(record)
    failed_qa_index = _active_failed_qa_line_index(
        [line for _, line in completed_lines]
    )
    worker_commits = [
        (index, line)
        for index, line in completed_lines
        if index > failed_qa_index
        and str(line.get("line_id") or "").strip() == "worker_commit"
        and str(line.get("stage_id") or "").strip() == "worker_commit"
        and str(line.get("evidence_kind") or "").strip() == "worker_commit"
        and str(line.get("actor_role") or "").strip() == "mf_sub"
        and _contract_runtime_mapping_matches_context(
            line,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            parent_task_id=parent_task_id,
        )
        and _contract_runtime_line_status_passes(line)
    ]
    active_commit_index = worker_commits[-1][0] if worker_commits else -1
    active_commit = worker_commits[-1][1] if worker_commits else {}
    active_commit_payload = (
        active_commit.get("payload")
        if isinstance(active_commit.get("payload"), Mapping)
        else {}
    )
    worker_commit_sha = str(
        active_commit.get("commit_sha")
        or active_commit_payload.get("worker_commit_sha")
        or active_commit_payload.get("head_commit")
        or ""
    ).strip()
    authority["worker_commit_sha"] = worker_commit_sha
    worker_commit_changed_files = _runtime_context_service_query_values(
        active_commit_payload,
        "changed_files",
    )
    worker_commit_owned_files = _runtime_context_service_query_values(
        active_commit_payload,
        "owned_files",
    )
    expected_owned_files = sorted(
        set(
            getattr(context, "owned_files", ())
            or getattr(context, "target_files", ())
            or ()
        )
    )
    if (
        active_commit_index < 0
        or not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", worker_commit_sha)
        or not _runtime_context_contract_line_execution_matches(
            active_commit,
            execution_id,
        )
    ):
        errors.append("canonical_worker_commit_missing_or_mismatched")
    if (
        not worker_commit_changed_files
        or sorted(set(worker_commit_owned_files)) != expected_owned_files
        or not set(worker_commit_changed_files).issubset(expected_owned_files)
    ):
        errors.append("canonical_worker_commit_scope_mismatch")
    if any(
        index > active_commit_index
        and str(line.get("line_id") or "").strip() == "worker_finish_gate"
        and _contract_runtime_mapping_matches_context(
            line,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            parent_task_id=parent_task_id,
        )
        for index, line in completed_lines
    ):
        errors.append("canonical_worker_finish_gate_already_completed")

    worktree_path = authority["worktree_path"]
    actual_head = _runtime_context_git_head_commit(worktree_path)
    actual_branch_ref = ""
    if worktree_path and os.path.exists(worktree_path):
        try:
            actual_branch_ref = subprocess.run(
                ["git", "symbolic-ref", "-q", "HEAD"],
                cwd=worktree_path,
                check=True,
                capture_output=True,
                text=True,
            ).stdout.strip()
        except (OSError, subprocess.SubprocessError):
            actual_branch_ref = ""
    authority["actual_branch_head_commit"] = actual_head
    authority["actual_branch_ref"] = actual_branch_ref
    if (
        not actual_head
        or actual_head != worker_commit_sha
        or actual_head
        != str(getattr(context, "head_commit", "") or "").strip()
        or not actual_branch_ref
        or actual_branch_ref != authority["branch_ref"]
    ):
        errors.append("branch_ref_or_head_drift")

    attestation_matches = [
        (index, line)
        for index, line in completed_lines
        if index > active_commit_index
        and str(line.get("line_id") or "").strip()
        == "worker_finish_time_attestation"
        and str(line.get("stage_id") or "").strip() == "worker_attestation"
        and str(line.get("evidence_kind") or "").strip()
        == "record_finish_time_worker_attestation"
        and str(line.get("actor_role") or "").strip() == "mf_sub"
        and _contract_runtime_mapping_matches_context(
            line,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            parent_task_id=parent_task_id,
        )
        and _contract_runtime_line_status_passes(line)
    ]
    if len(attestation_matches) != 1:
        errors.append("canonical_finish_attestation_missing_or_ambiguous")
    else:
        attestation_index, attestation_line = attestation_matches[0]
        attestation_payload = (
            attestation_line.get("payload")
            if isinstance(attestation_line.get("payload"), Mapping)
            else {}
        )
        if sorted(
            set(
                _runtime_context_service_query_values(
                    attestation_payload,
                    "changed_files",
                )
            )
        ) != sorted(set(worker_commit_changed_files)):
            errors.append("canonical_finish_attestation_scope_mismatch")
        try:
            finish_projection = (
                _runtime_context_contract_finish_attestation_projection(
                    conn,
                    context=context,
                    contract_execution_id=execution_id,
                    runtime_context_id=runtime_context_id,
                    parent_task_id=parent_task_id,
                    head_commit=worker_commit_sha,
                    changed_files=_runtime_context_service_query_values(
                        attestation_payload,
                        "changed_files",
                    ),
                    test_results=(
                        attestation_payload.get("test_results")
                        if isinstance(
                            attestation_payload.get("test_results"),
                            Mapping,
                        )
                        else {}
                    ),
                    supplied_worker_session_id=expected_worker_session,
                    supplied_filer_principal=expected_worker_session,
                    read_receipt_event_id=str(
                        attestation_payload.get("read_receipt_event_id") or ""
                    ),
                    read_receipt_hash=str(
                        attestation_payload.get("read_receipt_hash") or ""
                    ),
                    supplied_attestation=(
                        attestation_payload.get(
                            "finish_time_worker_self_attestation"
                        )
                        if isinstance(
                            attestation_payload.get(
                                "finish_time_worker_self_attestation"
                            ),
                            Mapping,
                        )
                        else {}
                    ),
                )
            )
        except GovernanceError:
            finish_projection = {}
        if not finish_projection:
            errors.append("canonical_finish_attestation_mismatch")
        else:
            authority["finish_attestation_source_ref"] = str(
                finish_projection.get("contract_runtime_source_ref") or ""
            )
            authority["finish_attestation_completed_line_index"] = (
                attestation_index
            )

    if errors:
        authority["fail_closed"] = True
        return authority
    authority.update(
        {
            "status": "eligible",
            "eligible": True,
            "errors": [],
            "next_legal_action": "rotate_auth_only_then_record_finish_gate",
        }
    )
    return authority


def _runtime_context_rotate_validated_missing_finish_auth(
    conn,
    *,
    context: Any,
    ttl_seconds: Any,
    now_iso: str,
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    """Rotate only auth lease material under the typed narrow authority."""

    import secrets
    from datetime import timedelta
    from .parallel_branch_runtime import (
        _bounded_reissue_ttl_seconds,
        _runtime_context_iso,
        _runtime_context_now_dt,
        mf_subagent_session_token_hash,
        runtime_context_fence_token_verifier,
        runtime_context_secret_hash,
        runtime_context_session_token_lease_view,
        runtime_context_session_token_ref,
        upsert_branch_context,
    )

    if (
        authority.get("schema_version")
        != "runtime_context.validated_missing_finish_rejoin_authority.v1"
        or authority.get("eligible") is not True
        or authority.get("server_derived") is not True
        or authority.get("auth_only") is not True
    ):
        raise GovernanceError(
            "runtime_context_validated_missing_finish_rejoin_not_eligible",
            "validated runtime context is not eligible for auth-only finish rejoin",
            409,
            {"authority": dict(authority), "fail_closed": True},
        )
    ttl = _bounded_reissue_ttl_seconds(ttl_seconds)
    now_dt = _runtime_context_now_dt(now_iso)
    expires_at = _runtime_context_iso(now_dt + timedelta(seconds=ttl))
    session_token = secrets.token_urlsafe(32)
    session_token_hash = mf_subagent_session_token_hash(session_token)
    verifier_backed_context = bool(context.fence_token_verifier)
    fence_token = (
        secrets.token_urlsafe(32)
        if verifier_backed_context
        else context.fence_token
    )
    fence_token_verifier = (
        runtime_context_secret_hash(fence_token)
        if verifier_backed_context
        else context.fence_token_verifier
    )
    saved = upsert_branch_context(
        conn,
        replace(
            context,
            lease_id="mfrlease-" + uuid.uuid4().hex[:16],
            lease_expires_at=expires_at,
            session_token_hash=session_token_hash,
            fence_token="" if verifier_backed_context else context.fence_token,
            fence_token_verifier=fence_token_verifier,
            last_recovery_action=(
                "mf_subagent_validated_missing_finish_auth_rejoin_issued"
            ),
        ),
        now_iso=_runtime_context_iso(now_dt),
    )
    return {
        "ok": True,
        "schema_version": "mf_subagent_session_token_rejoin_response.v1",
        "status": "session_token_rejoin_issued",
        "project_id": saved.project_id,
        "runtime_context_id": str(
            getattr(saved, "runtime_context_id", "") or ""
        ),
        "task_id": saved.task_id,
        "parent_task_id": _runtime_context_mf_sub_parent_task_id(saved),
        "backlog_id": saved.backlog_id,
        "worker_role": "mf_sub",
        "worker_id": saved.worker_id,
        "worker_slot_id": saved.worker_slot_id or saved.worker_id,
        "principal_id": (
            saved.actual_host_worker_id
            or saved.worker_slot_id
            or saved.worker_id
            or saved.agent_id
        ),
        "reopen_for_revision": False,
        "reopen_for_failed_qa_revision": False,
        "reopen_for_post_qa_merge_conflict": False,
        "validated_missing_finish_auth_only_rejoin": True,
        "validated_missing_finish_rejoin_authority": dict(authority),
        "previous_status": context.status,
        "current_status": saved.status,
        "attempt": saved.attempt,
        "retry_round": saved.retry_round,
        "session_token": session_token,
        "session_token_hash": session_token_hash,
        "session_token_ref": runtime_context_session_token_ref(saved),
        "session_token_persisted": False,
        "raw_session_token_persisted": False,
        "fence_token": fence_token,
        "fence_token_hash": runtime_context_fence_token_verifier(saved),
        "raw_fence_token_returned_for_host_envelope": True,
        "raw_fence_token_persisted_to_timeline": False,
        "delivery": "worker_host_envelope",
        "ttl_seconds": ttl,
        "expires_at": expires_at,
        "session_token_lease": runtime_context_session_token_lease_view(
            saved,
            now_iso=_runtime_context_iso(now_dt),
        ),
    }


def _runtime_context_closed_canonical_owned_file_set(
    values: Any,
) -> tuple[str, ...]:
    """Return one strict order-independent repo-relative owned-path set.

    A single trailing slash is preserved as a directory-prefix identity. Empty,
    duplicate, absolute, traversal, placeholder, and other non-canonical path
    spellings are invalid. Returning an empty tuple is therefore a fail-closed
    result, not an empty file fence.
    """

    if not isinstance(values, (list, tuple)) or not values:
        return ()
    canonical_files: list[str] = []
    seen: set[str] = set()
    for value in values:
        if not isinstance(value, str):
            return ()
        path = value.strip()
        if (
            not path
            or path != value
            or path.startswith("<")
            or "\\" in path
            or "\x00" in path
            or Path(path).is_absolute()
            or re.match(r"^[A-Za-z]:/", path)
        ):
            return ()
        directory_prefix = path.endswith("/")
        base_path = path[:-1] if directory_prefix else path
        normalized_base = os.path.normpath(base_path).replace(os.sep, "/")
        normalized = (
            f"{normalized_base}/" if directory_prefix else normalized_base
        )
        if (
            not base_path
            or normalized_base != base_path
            or normalized_base in {"", ".", ".."}
            or normalized_base.startswith("../")
            or any(
                part in {"", ".", ".."} for part in base_path.split("/")
            )
            or normalized in seen
        ):
            return ()
        seen.add(normalized)
        canonical_files.append(normalized)
    return tuple(sorted(canonical_files))


def _runtime_context_contract_update_allocation_identity_anchor(
    conn,
    *,
    project_id: str,
    context: Any,
    runtime_context_id: str,
    contract_execution_id: str,
    contract_record: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind a contract_update worker to its accepted allocator evidence.

    ``contract_update.v1`` deliberately has no mf_parallel
    ``observer_dispatch_bounded_workers`` line.  Its worker allocation still
    has two independent, server-authored identity records: the immutable
    ``parallel_branch_allocate`` contract revision and the accepted bounded
    dispatch timeline event.  Both must agree byte-for-field with the durable
    RuntimeContext and with one live append-scoped observer route.

    This is not an mf_parallel fallback.  The caller has already resolved the
    exact parent ContractRuntime row, and this helper accepts only the
    ``contract_update`` contract id.  Any missing, duplicate, stale, or
    conflicting evidence returns an empty anchor so the existing initial-join
    Gate remains zero-write/fail-closed.
    """

    execution_id = str(contract_execution_id or "").strip()
    runtime_id = str(runtime_context_id or "").strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    if (
        not execution_id
        or not runtime_id
        or parent_task_id != execution_id
        or str(contract_record.get("contract_id") or "").strip()
        != "contract_update"
        or str(contract_record.get("project_id") or "").strip() != project_id
        or str(contract_record.get("backlog_id") or "").strip() != backlog_id
        or str(contract_record.get("contract_execution_id") or "").strip()
        != execution_id
    ):
        return {}

    revision_rows = conn.execute(
        """
        SELECT revision_id, task_id, parent_task_id, backlog_id,
               payload_json, route_identity_json, route_gate_json,
               route_evidence_type, actor, created_at
          FROM parallel_branch_runtime_contract_revisions
         WHERE project_id = ? AND runtime_context_id = ?
           AND route_evidence_type = 'parallel_branch_allocate'
        """,
        (project_id, runtime_id),
    ).fetchall()
    if len(revision_rows) != 1:
        return {}
    revision_row = revision_rows[0]
    try:
        revision_payload = json.loads(str(revision_row["payload_json"] or "{}"))
        revision_route = json.loads(
            str(revision_row["route_identity_json"] or "{}")
        )
        revision_route_gate = json.loads(
            str(revision_row["route_gate_json"] or "{}")
        )
    except (TypeError, ValueError, json.JSONDecodeError):
        return {}
    if not all(
        isinstance(value, Mapping)
        for value in (revision_payload, revision_route, revision_route_gate)
    ):
        return {}

    revision_receipt = (
        revision_payload.get("revision_receipt")
        if isinstance(revision_payload.get("revision_receipt"), Mapping)
        else {}
    )
    revision_id = str(revision_row["revision_id"] or "").strip()
    expected_owned_files = _runtime_context_closed_canonical_owned_file_set(
        tuple(getattr(context, "owned_files", ()) or ())
        or tuple(getattr(context, "target_files", ()) or ())
    )
    revision_owned_files = _runtime_context_closed_canonical_owned_file_set(
        revision_payload.get("owned_files")
    )
    revision_target_files = _runtime_context_closed_canonical_owned_file_set(
        revision_payload.get("target_files")
    )
    if (
        not expected_owned_files
        or revision_owned_files != expected_owned_files
        or revision_target_files != expected_owned_files
        or str(revision_row["task_id"] or "").strip() != task_id
        or str(revision_row["parent_task_id"] or "").strip()
        != parent_task_id
        or str(revision_row["backlog_id"] or "").strip() != backlog_id
        or str(revision_row["actor"] or "").strip()
        != "parallel_branch_allocate"
        or str(revision_payload.get("schema_version") or "").strip()
        != "parallel_branch_allocate_contract_revision.v1"
        or str(revision_payload.get("source") or "").strip()
        != "parallel_branch_allocate"
        or str(revision_payload.get("contract_execution_id") or "").strip()
        != execution_id
        or str(revision_payload.get("runtime_context_id") or "").strip()
        != runtime_id
        or str(
            revision_receipt.get("canonical_visible_contract_text_hash") or ""
        ).strip()
        != revision_id
    ):
        return {}

    identity = {
        "runtime_context_id": runtime_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "worker_id": str(getattr(context, "worker_id", "") or "").strip(),
        "worker_slot_id": str(
            getattr(context, "worker_slot_id", "")
            or getattr(context, "worker_id", "")
            or ""
        ).strip(),
        "target_project_root": _runtime_context_effective_target_project_root(
            context
        ),
        "worktree_path": str(
            getattr(context, "worktree_path", "") or ""
        ).strip(),
        "branch_ref": str(
            getattr(context, "branch_ref", "") or ""
        ).strip(),
        "base_commit": str(
            getattr(context, "base_commit", "") or ""
        ).strip(),
        "target_head_commit": str(
            getattr(context, "target_head_commit", "") or ""
        ).strip(),
        "merge_queue_id": str(
            getattr(context, "merge_queue_id", "") or ""
        ).strip(),
    }
    allocation_agent_id = str(
        getattr(context, "agent_id", "")
        or getattr(context, "allocation_owner", "")
        or ""
    ).strip()
    allocation_owner = str(
        getattr(context, "allocation_owner", "") or ""
    ).strip()
    if (
        any(not identity.get(field) for field in identity)
        or not allocation_agent_id
        or allocation_agent_id != allocation_owner
        or str(revision_payload.get("task_id") or task_id).strip() != task_id
        or str(revision_payload.get("parent_task_id") or parent_task_id).strip()
        != parent_task_id
        or str(revision_payload.get("target_project_root") or "").strip()
        != identity["target_project_root"]
        or str(revision_payload.get("worktree_path") or "").strip()
        != identity["worktree_path"]
        or str(revision_payload.get("branch_ref") or "").strip()
        != identity["branch_ref"]
        or str(revision_payload.get("base_commit") or "").strip()
        != identity["base_commit"]
        or str(revision_payload.get("target_head_commit") or "").strip()
        != identity["target_head_commit"]
        or str(revision_payload.get("merge_queue_id") or "").strip()
        != identity["merge_queue_id"]
    ):
        return {}

    revision_route_payload = (
        revision_payload.get("route_identity")
        if isinstance(revision_payload.get("route_identity"), Mapping)
        else {}
    )
    allocation_route = {
        field: str(
            revision_route.get(field)
            or revision_route_payload.get(field)
            or ""
        ).strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    if (
        any(not value for value in allocation_route.values())
        or any(
            str(revision_route_payload.get(field) or "").strip() != value
            for field, value in allocation_route.items()
        )
        or str(revision_route_gate.get("source") or "").strip()
        != "parallel_branch_allocate"
        or str(revision_route_gate.get("decision") or "").strip()
        != "allocated"
        or str(revision_route_gate.get("caller_role") or "").strip()
        != "observer"
        or str(revision_route_gate.get("allowed_action") or "").strip()
        != "parallel_branch_allocate"
        or any(
            str(revision_route_gate.get(field) or "").strip() != value
            for field, value in allocation_route.items()
        )
    ):
        return {}

    # Initial join evaluates this anchor once in read preflight and once under
    # ``BEGIN IMMEDIATE``.  Do not use the schema-ensuring timeline facade in
    # the locked check: its ``executescript`` can implicitly commit.  The
    # accepted allocation already proves the timeline table exists.
    timeline_rows = conn.execute(
        """
        SELECT id, event_kind, status, actor, payload_json
          FROM task_timeline_events
         WHERE project_id = ? AND task_id = ? AND backlog_id = ?
         ORDER BY id ASC
        """,
        (project_id, task_id, backlog_id),
    ).fetchall()
    timeline_events: list[dict[str, Any]] = []
    for row in timeline_rows:
        try:
            event_payload = json.loads(str(row["payload_json"] or "{}"))
        except (TypeError, ValueError, json.JSONDecodeError):
            return {}
        if not isinstance(event_payload, Mapping):
            return {}
        timeline_events.append(
            {
                "id": int(row["id"] or 0),
                "event_kind": str(row["event_kind"] or ""),
                "status": str(row["status"] or ""),
                "actor": str(row["actor"] or ""),
                "payload": event_payload,
            }
        )
    dispatch_candidates: list[tuple[Mapping[str, Any], Mapping[str, Any]]] = []
    for event in timeline_events:
        if (
            str(event.get("event_kind") or "").strip()
            != "bounded_implementation_worker_dispatch"
            or str(event.get("status") or "").strip().lower()
            not in {"accepted", "passed"}
        ):
            continue
        event_payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        dispatch = (
            event_payload.get("bounded_implementation_worker_dispatch")
            if isinstance(
                event_payload.get("bounded_implementation_worker_dispatch"),
                Mapping,
            )
            else {}
        )
        meta_contract_gate = (
            event_payload.get("meta_contract_gate")
            if isinstance(event_payload.get("meta_contract_gate"), Mapping)
            else {}
        )
        if (
            str(dispatch.get("runtime_context_id") or "").strip()
            == runtime_id
            and str(event.get("actor") or "").strip() == "observer"
            and str(event_payload.get("schema_version") or "").strip()
            == "bounded_implementation_worker_dispatch.v1"
            and str(event_payload.get("source") or "").strip()
            == "parallel_branch_allocate"
            and str(event_payload.get("dispatch_source") or "").strip()
            == "parallel_branch_allocate"
            and event_payload.get("service_generated") is True
            and meta_contract_gate.get("allowed") is True
            and str(meta_contract_gate.get("role") or "").strip()
            == "observer"
            and str(meta_contract_gate.get("action") or "").strip()
            == "dispatch_bounded_worker"
            and meta_contract_gate.get("observer_event_validated") is True
        ):
            dispatch_candidates.append((event, dispatch))
    if len(dispatch_candidates) != 1:
        return {}
    dispatch_event, dispatch = dispatch_candidates[0]
    dispatch_owned_files = _runtime_context_closed_canonical_owned_file_set(
        dispatch.get("owned_files")
    )
    if (
        str(dispatch.get("schema_version") or "").strip()
        != "bounded_implementation_worker_dispatch.v1"
        or str(dispatch.get("source") or "").strip()
        != "parallel_branch_allocate"
        or dispatch.get("service_generated") is not True
        or str(dispatch.get("backlog_id") or "").strip() != backlog_id
        or str(dispatch.get("observer_command_id") or "").strip()
        != execution_id
        or str(dispatch.get("task_id") or "").strip() != task_id
        or str(dispatch.get("parent_task_id") or "").strip()
        != parent_task_id
        or str(dispatch.get("worker_id") or "").strip()
        != identity["worker_id"]
        or str(dispatch.get("worker_slot_id") or "").strip()
        != identity["worker_slot_id"]
        or str(dispatch.get("agent_id") or "").strip()
        != allocation_agent_id
        or dispatch_owned_files != expected_owned_files
        or any(
            str(dispatch.get(field) or "").strip() != expected
            for field, expected in identity.items()
        )
        or any(
            str(dispatch.get(field) or "").strip() != expected
            for field, expected in allocation_route.items()
        )
    ):
        return {}

    route_rows = conn.execute(
        """
        SELECT route_id, route_context_hash, prompt_contract_id,
               prompt_contract_hash, visible_injection_manifest_hash,
               backlog_id, task_id, caller_role, allowed_actions_json,
               expires_at, scope_json, target_files_json, owned_files_json
          FROM observer_route_token_refs
         WHERE project_id = ? AND route_token_ref = ? AND status = 'active'
        """,
        (
            _route_registry_storage_project_id(project_id),
            allocation_route["route_token_ref"],
        ),
    ).fetchall()
    if len(route_rows) != 1:
        return {}
    try:
        route_row = route_rows[0]
        route_scope = json.loads(str(route_row["scope_json"] or "{}"))
        route_allowed_actions = json.loads(
            str(route_row["allowed_actions_json"] or "[]")
        )
        route_target_files = _runtime_context_closed_canonical_owned_file_set(
            json.loads(str(route_row["target_files_json"] or "[]"))
        )
        route_owned_files = _runtime_context_closed_canonical_owned_file_set(
            json.loads(str(route_row["owned_files_json"] or "[]"))
        )
    except (TypeError, ValueError, json.JSONDecodeError):
        return {}
    if not isinstance(route_scope, Mapping) or not isinstance(
        route_allowed_actions, list
    ):
        return {}
    current_route = {
        field: str(
            route_row[field]
            if field != "route_token_ref"
            else allocation_route["route_token_ref"]
        ).strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    normalized_route_actions = {
        str(action or "").strip().lower().replace("-", "_").replace(".", "_")
        for action in route_allowed_actions
        if str(action or "").strip()
    }
    if (
        current_route != allocation_route
        or str(route_row["backlog_id"] or "").strip() != backlog_id
        or str(route_row["task_id"] or "").strip() != execution_id
        or str(route_row["caller_role"] or "").strip() != "observer"
        or not {
            "parallel_branch_allocate",
            "task_timeline_append",
        }.issubset(normalized_route_actions)
        or any(
            str(route_scope.get(field) or "").strip() != expected
            for field, expected in (
                ("project_id", project_id),
                ("backlog_id", backlog_id),
                ("task_id", execution_id),
            )
        )
        or not str(route_row["expires_at"] or "").strip()
        or str(route_row["expires_at"] or "").strip()
        <= str(_utc_now() or "").strip()
        or route_target_files != expected_owned_files
        or route_owned_files != expected_owned_files
    ):
        return {}

    core = {
        "schema_version": (
            "runtime_context.contract_update_allocation_identity_anchor.v1"
        ),
        "server_derived": True,
        "source": (
            "parallel_branch_allocate_contract_revision+"
            "bounded_implementation_worker_dispatch"
        ),
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "contract_id": "contract_update",
        "allocation_revision_id": revision_id,
        "allocation_revision_ref": f"contract-revision:{revision_id}",
        "dispatch_event_ref": f"timeline:{int(dispatch_event.get('id') or 0)}",
        **identity,
        "route_identity": dict(current_route),
        "allocated_route_identity": dict(allocation_route),
        "owned_files": list(expected_owned_files),
        "agent_id": allocation_agent_id,
        "route_resolution_status": "resolved_append_scoped_ref",
        "raw_credentials_persisted": False,
    }
    return {**core, "anchor_hash": _stable_public_hash(core)}


def _contract_update_accepted_dispatch_authority(
    record: Mapping[str, Any],
    anchor: Mapping[str, Any],
    revision_body: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind the existing allocation anchor to its signed rev2 precheck."""

    receipt = (
        revision_body.get("allocation_precheck")
        if isinstance(revision_body.get("allocation_precheck"), Mapping)
        else {}
    )
    if not (
        _contract_update_rev2_dispatch_allocation_authority(record)
        and anchor.get("server_derived") is True
        and receipt.get("schema_version")
        == "parallel_branch_allocate_precheck.receipt.v2"
        and receipt.get("status") == "ready"
        and receipt.get("submit_unchanged") is True
        and receipt.get("zero_write") is True
        and receipt.get("expected_lane_count") == 1
        and receipt.get("atomic") is False
        and receipt.get("scope") == "contract_update_single_lane"
        and receipt.get("cardinality_source")
        == "contract_update_rev2_dispatch_line"
        and re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            str(receipt.get("authority_hash") or "").strip(),
        )
    ):
        return {}
    core = {
        "schema_version": "contract_update.accepted_dispatch_authority.v1",
        "status": "accepted_allocation",
        "server_derived": True,
        "db_verified": True,
        "project_id": str(record.get("project_id") or ""),
        "backlog_id": str(record.get("backlog_id") or ""),
        "contract_execution_id": str(
            record.get("contract_execution_id") or ""
        ),
        "contract_id": CONTRACT_UPDATE_CONTRACT_ID,
        "contract_revision": "rev2",
        "allocation_revision_ref": str(
            anchor.get("allocation_revision_ref") or ""
        ),
        "dispatch_event_ref": str(anchor.get("dispatch_event_ref") or ""),
        "allocation_anchor_hash": str(anchor.get("anchor_hash") or ""),
        "allocation_precheck_authority_hash": str(
            receipt.get("authority_hash") or ""
        ),
        "runtime_context_id": str(anchor.get("runtime_context_id") or ""),
        "task_id": str(anchor.get("task_id") or ""),
        "parent_task_id": str(anchor.get("parent_task_id") or ""),
        "worker_id": str(anchor.get("worker_id") or ""),
        "worker_slot_id": str(anchor.get("worker_slot_id") or ""),
        "worker_role": "mf_sub",
        "base_commit": str(anchor.get("base_commit") or ""),
        "target_head_commit": str(anchor.get("target_head_commit") or ""),
        "owned_files": list(anchor.get("owned_files") or []),
        "writes_performed": False,
    }
    if any(value in ("", []) for value in core.values()):
        return {}
    return {**core, "authority_hash": stable_sha256(core)}


def _runtime_context_pre_lineage_legacy_dispatch_identity_anchor(
    conn,
    *,
    project_id: str,
    context: Any,
    runtime_context_id: str,
    contract_execution_id: str,
) -> dict[str, Any]:
    """Read the independent accepted dispatch identity for legacy joins."""

    execution_id = str(contract_execution_id or "").strip()
    runtime_id = str(runtime_context_id or "").strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    worker_id = str(getattr(context, "worker_id", "") or "").strip()
    worker_slot_id = str(
        getattr(context, "worker_slot_id", "") or worker_id
    ).strip()
    try:
        record = _contract_runtime(conn).store.get(execution_id)
    except Exception:
        return {}
    if (
        str(record.get("project_id") or "").strip() != project_id
        or str(record.get("backlog_id") or "").strip() != backlog_id
        or str(record.get("contract_execution_id") or "").strip()
        != execution_id
    ):
        return {}

    if str(record.get("contract_id") or "").strip() == "contract_update":
        return _runtime_context_contract_update_allocation_identity_anchor(
            conn,
            project_id=project_id,
            context=context,
            runtime_context_id=runtime_id,
            contract_execution_id=execution_id,
            contract_record=record,
        )

    dispatch_match = _contract_runtime_dispatch_line_match(record, context)
    if not dispatch_match:
        return {}
    dispatch_line = (
        dispatch_match.get("line")
        if isinstance(dispatch_match.get("line"), Mapping)
        else {}
    )
    dispatch_payload = (
        dispatch_match.get("payload")
        if isinstance(dispatch_match.get("payload"), Mapping)
        else {}
    )
    line_index = dispatch_match.get("line_index")
    dispatch_schema_version = str(
        dispatch_payload.get("schema_version")
        or dispatch_line.get("schema_version")
        or ""
    ).strip()
    if (
        not isinstance(line_index, int)
        or str(dispatch_line.get("stage_id") or "").strip() != "dispatch"
        or str(dispatch_line.get("line_id") or "").strip()
        != "observer_dispatch_bounded_workers"
        or str(dispatch_line.get("evidence_kind") or "").strip()
        != "dispatch_bounded_worker"
        or str(dispatch_line.get("actor_role") or "").strip() != "observer"
        or str(dispatch_line.get("status") or "").strip().lower()
        not in {"", "accepted", "passed"}
        or not dispatch_schema_version
    ):
        return {}
    identity = {
        "runtime_context_id": runtime_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "target_project_root": _runtime_context_effective_target_project_root(
            context
        ),
        "worktree_path": str(
            getattr(context, "worktree_path", "") or ""
        ).strip(),
        "branch_ref": str(
            getattr(context, "branch_ref", "") or ""
        ).strip(),
        "base_commit": str(
            getattr(context, "base_commit", "") or ""
        ).strip(),
        "target_head_commit": str(
            getattr(context, "target_head_commit", "") or ""
        ).strip(),
        "merge_queue_id": str(
            getattr(context, "merge_queue_id", "") or ""
        ).strip(),
    }
    if any(
        not identity.get(field)
        for field in (
            "runtime_context_id",
            "task_id",
            "parent_task_id",
            "worker_id",
            "worker_slot_id",
            "target_project_root",
            "worktree_path",
            "branch_ref",
            "base_commit",
            "target_head_commit",
            "merge_queue_id",
        )
    ):
        return {}
    exact_runtime_dispatch_candidates = [
        candidate
        for source in (dispatch_line, dispatch_payload)
        for candidate in _contract_runtime_mapping_candidates(source)
        if str(candidate.get("runtime_context_id") or "").strip()
        == runtime_id
    ]
    if not exact_runtime_dispatch_candidates:
        return {}
    dispatch_route_identities: list[dict[str, str]] = []
    for candidate in exact_runtime_dispatch_candidates:
        route_identity = (
            candidate.get("route_identity")
            if isinstance(candidate.get("route_identity"), Mapping)
            else {}
        )
        if not route_identity:
            continue
        canonical_route_identity = {
            field: str(route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        }
        if any(not canonical_route_identity[field] for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS):
            return {}
        dispatch_route_identities.append(canonical_route_identity)
    if not dispatch_route_identities or any(
        candidate != dispatch_route_identities[0]
        for candidate in dispatch_route_identities[1:]
    ):
        return {}
    for candidate in exact_runtime_dispatch_candidates:
        for field, expected in (
            ("task_id", task_id),
            ("worker_id", worker_id),
            ("worker_slot_id", worker_slot_id),
        ):
            actual = str(candidate.get(field) or "").strip()
            if actual and actual != expected:
                return {}
    for field in (
        "target_project_root",
        "worktree_path",
        "branch_ref",
        "base_commit",
        "target_head_commit",
        "merge_queue_id",
    ):
        durable_values = {
            str(candidate.get(field) or "").strip()
            for candidate in exact_runtime_dispatch_candidates
            if str(candidate.get(field) or "").strip()
        }
        if durable_values != {identity[field]}:
            return {}
    expected_owned_files = _runtime_context_closed_canonical_owned_file_set(
        getattr(context, "owned_files", ())
        or getattr(context, "target_files", ())
        or ()
    )
    dispatch_owned_files = [
        list(candidate.get("owned_files") or [])
        for candidate in exact_runtime_dispatch_candidates
        if isinstance(candidate.get("owned_files"), (list, tuple))
    ]
    if (
        not expected_owned_files
        or not dispatch_owned_files
        or any(
            _runtime_context_closed_canonical_owned_file_set(files)
            != expected_owned_files
            for files in dispatch_owned_files
        )
    ):
        return {}
    agent_candidates = {
        str(candidate.get("agent_id") or "").strip()
        for candidate in exact_runtime_dispatch_candidates
        if str(candidate.get("agent_id") or "").strip()
    }
    if len(agent_candidates) > 1:
        return {}
    dispatch_agent_id = next(iter(agent_candidates), "")
    core = {
        "schema_version": (
            "runtime_context.pre_lineage_legacy_dispatch_identity_anchor.v1"
        ),
        "server_derived": True,
        "source": (
            "ContractRuntime.completed_lines."
            "observer_dispatch_bounded_workers"
        ),
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "source_line_index": line_index,
        "source_ref": str(dispatch_match.get("source_ref") or "").strip(),
        "source_line_hash": _stable_public_hash(dict(dispatch_line)),
        "dispatch_schema_version": dispatch_schema_version,
        "dispatch_actor_role": "observer",
        "dispatch_status": str(
            dispatch_line.get("status") or "accepted"
        ).strip().lower(),
        **identity,
        "route_identity": dict(dispatch_route_identities[0]),
        "owned_files": list(expected_owned_files),
        "agent_id": dispatch_agent_id,
        "raw_credentials_persisted": False,
    }
    return {**core, "anchor_hash": _stable_public_hash(core)}


def _runtime_context_contract_execution_record_exists(
    conn,
    contract_execution_id: str,
) -> bool:
    try:
        _contract_runtime(conn).store.get(
            str(contract_execution_id or "").strip()
        )
    except Exception:
        return False
    return True


def _runtime_context_contract_dispatch_anchor_required(
    conn,
    *,
    context: Any,
    contract_execution_id: str,
) -> bool:
    """Fail closed for contexts whose parent is a ContractRuntime execution.

    The allocation contract revision is independent of the ContractRuntime
    row.  Keeping that signal prevents a deleted or malformed execution row
    from being reclassified as an old hand-authored runtime context.
    """

    execution_id = str(contract_execution_id or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    if not execution_id or execution_id != parent_task_id:
        return False
    if _runtime_context_contract_execution_record_exists(conn, execution_id):
        return True
    runtime_id = str(
        getattr(context, "runtime_context_id", "") or ""
    ).strip()
    rows = conn.execute(
        """
        SELECT payload_json
        FROM parallel_branch_runtime_contract_revisions
        WHERE project_id = ? AND runtime_context_id = ?
        """,
        (
            str(getattr(context, "project_id", "") or "").strip(),
            runtime_id,
        ),
    ).fetchall()
    for row in rows:
        try:
            payload = json.loads(str(row["payload_json"] or "{}"))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if (
            isinstance(payload, Mapping)
            and payload.get("schema_version")
            == "parallel_branch_allocate_contract_revision.v1"
            and payload.get("source") == "parallel_branch_allocate"
        ):
            return True
    return False


def _runtime_context_pre_lineage_bootstrap_rejoin_authority(
    conn,
    *,
    project_id: str,
    context: Any,
    runtime_context_id: str,
    body: Mapping[str, Any],
    contract_execution_id: str,
    route_identity: Mapping[str, Any],
    timeline_events: Sequence[Mapping[str, Any]],
    effective_read_receipt_ref: str = "",
    effective_startup_ref: str = "",
    now_iso: str = "",
) -> dict[str, Any]:
    """Derive the one-shot authority for a lost initial-join envelope.

    This recovery is deliberately narrower than ordinary rejoin.  It only
    rotates auth while the first accepted initial-join lease is still active
    and no worker evidence exists.  All identity comes from durable runtime,
    route, contract, and canonical initial-join audit state; the caller cannot
    use this path to choose a new worker identity or synthesize lineage.
    """

    from .parallel_branch_runtime import (
        ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES,
        runtime_context_has_fence_authority,
        runtime_context_id_for_branch_context,
        runtime_context_session_token_lease_view,
        runtime_context_session_token_ref,
    )

    runtime_id = str(runtime_context_id or "").strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    target_project_root = _runtime_context_effective_target_project_root(context)
    worker_id = str(getattr(context, "worker_id", "") or "").strip()
    worker_slot_id = str(
        getattr(context, "worker_slot_id", "") or worker_id or ""
    ).strip()
    actual_host_worker_id = str(
        getattr(context, "actual_host_worker_id", "") or ""
    ).strip()
    host_startup_id = str(
        getattr(context, "host_startup_id", "") or ""
    ).strip()
    host_session_id = str(
        getattr(context, "host_session_id", "") or ""
    ).strip()
    lease = runtime_context_session_token_lease_view(context, now_iso=now_iso)
    active_session_token_ref = runtime_context_session_token_ref(context)
    errors: list[str] = []

    if effective_read_receipt_ref or effective_startup_ref:
        errors.append("worker_lineage_already_exists")
    last_recovery_action = str(
        getattr(context, "last_recovery_action", "") or ""
    ).strip()
    if last_recovery_action != "mf_subagent_initial_join_issued":
        errors.append("last_recovery_action_not_initial_join")
    if str(getattr(context, "status", "") or "").strip() not in (
        ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES
    ):
        errors.append("runtime_context_not_active")
    if not (
        str(getattr(context, "session_token_hash", "") or "").strip()
        and runtime_context_has_fence_authority(context)
        and active_session_token_ref
    ):
        errors.append("initial_join_auth_binding_missing")
    if not (
        lease.get("status") == "active"
        and lease.get("authorization_valid") is True
        and lease.get("expired") is False
        and lease.get("lease_record_valid") is True
    ):
        errors.append("initial_join_lease_not_active")

    candidate_initial_join_audits: list[Mapping[str, Any]] = []
    for event in timeline_events:
        if not isinstance(event, Mapping):
            continue
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        if not (
            str(event.get("event_type") or "").strip()
            == "observer.runtime_context_session_token_initial_join"
            and str(event.get("event_kind") or "").strip() == "observer_command"
            and str(event.get("phase") or "").strip()
            == "runtime_context_initial_join"
            and str(event.get("status") or "").strip().lower() == "accepted"
            and str(payload.get("action") or "").strip()
            == "runtime_context_session_token_initial_join"
            and str(event.get("task_id") or payload.get("task_id") or "").strip()
            == task_id
            and str(
                event.get("backlog_id") or payload.get("backlog_id") or ""
            ).strip()
            == backlog_id
        ):
            continue
        candidate_initial_join_audits.append(event)
    canonical_initial_join_audits = [
        event
        for event in candidate_initial_join_audits
        if str(
            (event.get("payload") or {}).get("runtime_context_id")
            if isinstance(event.get("payload"), Mapping)
            else ""
        ).strip()
        == runtime_id
    ]
    if (
        len(candidate_initial_join_audits) != 1
        or len(canonical_initial_join_audits) != 1
    ):
        errors.append("exactly_one_accepted_initial_join_audit_required")
    initial_join_audit = (
        candidate_initial_join_audits[0]
        if len(candidate_initial_join_audits) == 1
        else {}
    )
    initial_join_payload = (
        initial_join_audit.get("payload")
        if isinstance(initial_join_audit.get("payload"), Mapping)
        else {}
    )
    candidate_identity_anchors: list[Mapping[str, Any]] = []
    for event in timeline_events:
        if not isinstance(event, Mapping):
            continue
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        if not (
            str(event.get("event_type") or "").strip()
            == (
                "observer.runtime_context_session_token_"
                "initial_join_identity_binding"
            )
            and str(event.get("event_kind") or "").strip()
            == "observer_command"
            and str(event.get("phase") or "").strip()
            == "runtime_context_initial_join_identity_binding"
            and str(event.get("status") or "").strip().lower()
            == "accepted"
            and str(payload.get("action") or "").strip()
            == (
                "runtime_context_session_token_initial_join_"
                "identity_binding_anchor"
            )
            and str(
                event.get("task_id") or payload.get("task_id") or ""
            ).strip()
            == task_id
            and str(
                event.get("backlog_id")
                or payload.get("backlog_id")
                or ""
            ).strip()
            == backlog_id
        ):
            continue
        candidate_identity_anchors.append(event)
    identity_anchor = (
        candidate_identity_anchors[0]
        if len(candidate_identity_anchors) == 1
        else {}
    )
    identity_anchor_payload = (
        identity_anchor.get("payload")
        if isinstance(identity_anchor.get("payload"), Mapping)
        else {}
    )
    cutover_audit_rows = conn.execute(
        """
        SELECT audit_id, project_id, runtime_context_id, task_id,
               principal_id, session_id, role, view_name, decision, reason,
               projection_hash, nodes_read_json, metadata_json, created_at
        FROM parallel_branch_runtime_access_audit
        WHERE project_id = ? AND runtime_context_id = ?
          AND view_name = ?
        ORDER BY created_at, audit_id
        """,
        (
            project_id,
            runtime_id,
            "initial_join_identity_cutover",
        ),
    ).fetchall()
    discriminator_present = any(
        field in initial_join_payload
        for field in (
            "initial_join_identity_contract_version",
            "canonical_identity_binding_required",
        )
    )
    canonical_binding_present = "canonical_identity_binding" in initial_join_payload
    fresh_identity_cutover = bool(
        discriminator_present
        or canonical_binding_present
        or candidate_identity_anchors
        or cutover_audit_rows
    )
    worker_session_id = str(
        initial_join_payload.get("worker_session_id") or ""
    ).strip()

    persisted_runtime_id = runtime_context_id_for_branch_context(context)
    expected_request_identity = {
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "target_project_root": target_project_root,
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "agent_id": actual_host_worker_id,
        "actual_host_worker_id": actual_host_worker_id,
        "worker_session_id": worker_session_id,
        "host_session_id": host_session_id,
        "session_token_ref": active_session_token_ref,
        "contract_execution_id": str(contract_execution_id or "").strip(),
    }
    for field, expected in expected_request_identity.items():
        actual = str(body.get(field) or "").strip()
        if not expected:
            errors.append(f"persisted_{field}_missing")
        elif actual != expected:
            errors.append(f"{field}_mismatch_or_missing")

    if not runtime_id or runtime_id != persisted_runtime_id:
        errors.append("runtime_context_identity_mismatch")
    if not project_id or str(getattr(context, "project_id", "") or "").strip() != project_id:
        errors.append("project_identity_mismatch")

    expected_audit_identity = {
        "parent_task_id": parent_task_id,
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "agent_id": actual_host_worker_id,
        "actual_host_worker_id": actual_host_worker_id,
        "worker_session_id": worker_session_id,
        "host_session_id": host_session_id,
        "session_token_ref": active_session_token_ref,
    }
    legacy_agent_id_normalization_candidate = False
    durable_allocation_agent_id = str(
        getattr(context, "agent_id", "") or ""
    ).strip()
    durable_allocation_owner = str(
        getattr(context, "allocation_owner", "") or ""
    ).strip()
    contract_dispatch_anchor_required = (
        _runtime_context_contract_dispatch_anchor_required(
            conn,
            context=context,
            contract_execution_id=contract_execution_id,
        )
    )
    legacy_dispatch_anchor = (
        _runtime_context_pre_lineage_legacy_dispatch_identity_anchor(
            conn,
            project_id=project_id,
            context=context,
            runtime_context_id=runtime_id,
            contract_execution_id=contract_execution_id,
        )
    )
    if contract_dispatch_anchor_required and not legacy_dispatch_anchor:
        errors.append("initial_join_audit_dispatch_identity_anchor_invalid")
    dispatch_agent_id = str(
        legacy_dispatch_anchor.get("agent_id") or ""
    ).strip()
    for field, expected in expected_audit_identity.items():
        actual = str(initial_join_payload.get(field) or "").strip()
        if field == "agent_id" and expected and actual != expected:
            if (
                not fresh_identity_cutover
                and actual
                and actual == durable_allocation_agent_id
                and actual == durable_allocation_owner
                and actual == dispatch_agent_id
                and durable_allocation_agent_id != expected
            ):
                legacy_agent_id_normalization_candidate = True
                continue
        if not expected or actual != expected:
            errors.append(f"initial_join_audit_{field}_mismatch")
    request_host_startup_id = str(
        body.get("host_startup_id") or ""
    ).strip()
    audited_host_startup_id = str(
        initial_join_payload.get("host_startup_id") or ""
    ).strip()
    host_startup_identity = (
        host_startup_id,
        request_host_startup_id,
        audited_host_startup_id,
    )
    if any(host_startup_identity) and len(set(host_startup_identity)) != 1:
        errors.append("host_startup_id_conflict")
    if not (
        initial_join_payload.get("host_envelope_returned") is True
        and initial_join_payload.get("raw_session_token_persisted") is False
        and initial_join_payload.get("raw_fence_token_persisted_to_timeline")
        is False
    ):
        errors.append("initial_join_audit_privacy_or_delivery_proof_invalid")
    audited_lease = (
        initial_join_payload.get("session_token_lease")
        if isinstance(initial_join_payload.get("session_token_lease"), Mapping)
        else {}
    )
    if (
        not audited_lease
        or str(audited_lease.get("lease_id") or "").strip()
        != str(lease.get("lease_id") or "").strip()
        or str(audited_lease.get("lease_expires_at") or "").strip()
        != str(lease.get("lease_expires_at") or "").strip()
    ):
        errors.append("initial_join_audit_lease_mismatch")

    canonical_route_identity = {
        field: str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    audited_route_identity = (
        initial_join_payload.get("route_identity")
        if isinstance(initial_join_payload.get("route_identity"), Mapping)
        else {}
    )
    for field, expected in canonical_route_identity.items():
        if not expected:
            errors.append(f"canonical_route_{field}_missing")
            continue
        if str(body.get(field) or "").strip() != expected:
            errors.append(f"request_route_{field}_mismatch_or_missing")
        if str(audited_route_identity.get(field) or "").strip() != expected:
            errors.append(f"initial_join_audit_route_{field}_mismatch")

    expected_canonical_binding: dict[str, Any] = {}
    expected_identity_anchor: dict[str, Any] = {}
    if fresh_identity_cutover:
        operator_principal_id = str(
            initial_join_payload.get("operator_principal_id") or ""
        ).strip()
        operator_session_id = str(
            initial_join_payload.get("operator_session_id") or ""
        ).strip()
        operator_role = str(
            initial_join_payload.get("operator_role") or ""
        ).strip()
        if (
            not operator_principal_id
            or operator_principal_id
            != str(initial_join_audit.get("actor") or "").strip()
            or not operator_session_id
            or operator_role not in {"observer", "coordinator"}
            or str(
                initial_join_payload.get("operator_session_role") or ""
            ).strip()
            != operator_role
        ):
            errors.append("initial_join_audit_operator_identity_invalid")
        if (
            initial_join_payload.get("initial_join_identity_contract_version")
            != "runtime_context.initial_join_identity.v2"
            or initial_join_payload.get(
                "canonical_identity_binding_required"
            )
            is not True
        ):
            errors.append("initial_join_audit_identity_discriminator_invalid")
        canonical_binding = initial_join_payload.get(
            "canonical_identity_binding"
        )
        if not isinstance(canonical_binding, Mapping):
            errors.append("initial_join_audit_canonical_binding_missing")
            canonical_binding = {}
        expected_missing_lineage = [
            item
            for item, present in (
                ("mf_subagent_read_receipt", effective_read_receipt_ref),
                ("mf_subagent_startup", effective_startup_ref),
            )
            if not present
        ]
        expected_canonical_binding = (
            _runtime_context_initial_join_expected_canonical_identity_binding(
                project_id=project_id,
                context=context,
                governed_worker_id=actual_host_worker_id,
                contract_execution_id=contract_execution_id,
                worker_session_id=worker_session_id,
                host_startup_id=host_startup_id,
                host_session_id=host_session_id,
                route_identity=canonical_route_identity,
                dispatch_identity_anchor=legacy_dispatch_anchor,
                missing_lineage=expected_missing_lineage,
                now_iso=now_iso,
            )
        )
        if dict(canonical_binding) != expected_canonical_binding:
            errors.append("initial_join_audit_canonical_binding_mismatch")
        if len(candidate_identity_anchors) != 1:
            errors.append(
                "initial_join_audit_identity_anchor_cardinality_invalid"
            )
        if initial_join_audit:
            expected_identity_anchor = (
                _runtime_context_initial_join_identity_binding_anchor(
                    project_id=project_id,
                    runtime_context_id=runtime_id,
                    contract_execution_id=contract_execution_id,
                    task_id=task_id,
                    backlog_id=backlog_id,
                    initial_join_event_ref=(
                        f"timeline:{initial_join_audit.get('id', '')}"
                    ),
                    canonical_binding=expected_canonical_binding,
                )
            )
        persisted_identity_anchor = dict(identity_anchor_payload)
        persisted_meta_contract_gate = persisted_identity_anchor.pop(
            "meta_contract_gate",
            None,
        )
        expected_meta_contract_gate: Mapping[str, Any] | None = None
        if expected_identity_anchor and identity_anchor:
            try:
                from .mf_subagent_contract import (
                    validate_meta_contract_timeline_event,
                )

                expected_meta_contract_gate = (
                    validate_meta_contract_timeline_event(
                        {
                            "event_type": identity_anchor.get(
                                "event_type",
                                "",
                            ),
                            "phase": identity_anchor.get("phase", ""),
                            "event_kind": identity_anchor.get(
                                "event_kind",
                                "",
                            ),
                            "actor": identity_anchor.get("actor", ""),
                            "status": identity_anchor.get("status", ""),
                            "decision": identity_anchor.get(
                                "decision",
                                "",
                            ),
                            "payload": expected_identity_anchor,
                            "verification": identity_anchor.get(
                                "verification",
                                {},
                            ),
                            "artifact_refs": identity_anchor.get(
                                "artifact_refs",
                                {},
                            ),
                            "backlog_id": backlog_id,
                            "task_id": task_id,
                        }
                    )
                )
            except Exception:
                errors.append(
                    "initial_join_audit_identity_anchor_gate_invalid"
                )
        if (
            not expected_identity_anchor
            or persisted_identity_anchor != expected_identity_anchor
            or not isinstance(persisted_meta_contract_gate, Mapping)
            or expected_meta_contract_gate is None
            or dict(persisted_meta_contract_gate)
            != dict(expected_meta_contract_gate)
        ):
            errors.append("initial_join_audit_identity_anchor_mismatch")
        expected_cutover_authority: dict[str, Any] = {}
        expected_cutover_audit_id = ""
        if initial_join_audit and identity_anchor and expected_identity_anchor:
            expected_cutover_authority = (
                _runtime_context_initial_join_cutover_authority(
                    project_id=project_id,
                    runtime_context_id=runtime_id,
                    contract_execution_id=contract_execution_id,
                    task_id=task_id,
                    parent_task_id=parent_task_id,
                    backlog_id=backlog_id,
                    initial_join_event_ref=(
                        f"timeline:{initial_join_audit.get('id', '')}"
                    ),
                    identity_anchor_ref=(
                        f"timeline:{identity_anchor.get('id', '')}"
                    ),
                    canonical_binding=expected_canonical_binding,
                    identity_anchor=expected_identity_anchor,
                    operator_principal_id=operator_principal_id,
                    operator_session_id=operator_session_id,
                    operator_role=operator_role,
                    created_at=str(
                        initial_join_audit.get("created_at") or ""
                    ).strip(),
                )
            )
            expected_cutover_audit_id = (
                _runtime_context_initial_join_cutover_audit_id(
                    expected_cutover_authority
                )
            )
        if len(cutover_audit_rows) != 1:
            errors.append("initial_join_audit_cutover_cardinality_invalid")
        else:
            cutover_row = cutover_audit_rows[0]
            try:
                cutover_metadata = json.loads(
                    str(cutover_row["metadata_json"] or "")
                )
            except (TypeError, ValueError, json.JSONDecodeError):
                cutover_metadata = None
            created_at = str(cutover_row["created_at"] or "").strip()
            try:
                created_at_dt = datetime.fromisoformat(
                    created_at.replace("Z", "+00:00")
                )
                created_at_valid = bool(
                    created_at.endswith("Z")
                    and 20 <= len(created_at) <= 32
                    and created_at_dt.tzinfo is not None
                )
            except (TypeError, ValueError):
                created_at_valid = False
            cutover_row_exact = bool(
                expected_cutover_authority
                and str(cutover_row["audit_id"] or "").strip()
                == expected_cutover_audit_id
                and str(cutover_row["project_id"] or "").strip()
                == project_id
                and str(cutover_row["runtime_context_id"] or "").strip()
                == runtime_id
                and str(cutover_row["task_id"] or "").strip() == task_id
                and str(cutover_row["principal_id"] or "").strip()
                == operator_principal_id
                and str(cutover_row["session_id"] or "").strip()
                == operator_session_id
                and str(cutover_row["role"] or "").strip()
                == operator_role
                and str(cutover_row["view_name"] or "").strip()
                == "initial_join_identity_cutover"
                and str(cutover_row["decision"] or "").strip() == "allowed"
                and str(cutover_row["reason"] or "").strip()
                == "canonical_identity_binding_required"
                and str(cutover_row["projection_hash"] or "").strip()
                == str(
                    expected_cutover_authority.get("cutover_hash") or ""
                ).strip()
                and str(cutover_row["nodes_read_json"] or "").strip()
                == "[]"
                and cutover_metadata == expected_cutover_authority
                and created_at_valid
                and created_at
                == str(
                    expected_cutover_authority.get("created_at") or ""
                ).strip()
            )
            if not cutover_row_exact:
                errors.append("initial_join_audit_cutover_identity_mismatch")

    errors = list(dict.fromkeys(errors))
    audit_errors = [
        error
        for error in errors
        if error == "exactly_one_accepted_initial_join_audit_required"
        or error.startswith("initial_join_audit_")
        or error == "host_startup_id_conflict"
    ]
    identity_errors = [
        error
        for error in errors
        if (
            error.endswith("_mismatch_or_missing")
            or error
            in {
                "runtime_context_identity_mismatch",
                "project_identity_mismatch",
                "host_startup_id_conflict",
            }
        )
        and not error.startswith("request_route_")
        and not error.startswith("initial_join_audit_")
        and error != "contract_execution_id_mismatch_or_missing"
    ]
    route_errors = [
        error
        for error in errors
        if "route_" in error
        and error != "target_project_root_mismatch_or_missing"
    ]
    contract_errors = [
        error
        for error in errors
        if error == "contract_execution_id_mismatch_or_missing"
    ]
    if last_recovery_action in {
        "mf_subagent_pre_lineage_session_token_rejoin_issued",
        "mf_subagent_session_token_rejoin_issued",
    }:
        failure_code = "runtime_context_pre_lineage_rejoin_already_consumed"
        failure_reason = "pre_lineage_rejoin_already_consumed"
    elif "exactly_one_accepted_initial_join_audit_required" in errors:
        failure_code = (
            "runtime_context_pre_lineage_rejoin_initial_join_audit_invalid"
        )
        failure_reason = "canonical_initial_join_audit_invalid"
    elif contract_errors:
        failure_code = (
            "runtime_context_pre_lineage_rejoin_contract_identity_mismatch"
        )
        failure_reason = "contract_identity_mismatch"
    elif route_errors:
        failure_code = (
            "runtime_context_pre_lineage_rejoin_route_identity_mismatch"
        )
        failure_reason = "route_identity_mismatch"
    elif identity_errors:
        failure_code = "runtime_context_pre_lineage_rejoin_identity_mismatch"
        failure_reason = "runtime_identity_mismatch"
    elif "runtime_context_not_active" in errors:
        failure_code = "runtime_context_pre_lineage_rejoin_authority_invalid"
        failure_reason = "runtime_context_not_active"
    elif "initial_join_auth_binding_missing" in errors:
        failure_code = "runtime_context_pre_lineage_rejoin_authority_invalid"
        failure_reason = "initial_join_auth_binding_missing"
    elif "initial_join_lease_not_active" in errors:
        failure_code = "runtime_context_pre_lineage_rejoin_authority_invalid"
        failure_reason = "initial_join_lease_not_active"
    elif audit_errors:
        failure_code = (
            "runtime_context_pre_lineage_rejoin_initial_join_audit_invalid"
        )
        failure_reason = "canonical_initial_join_audit_invalid"
    else:
        failure_code = "runtime_context_rejoin_requires_existing_worker_lineage"
        failure_reason = "existing_worker_lineage_required"
    authority = {
        "schema_version": "runtime_context.pre_lineage_rejoin_authority.v1",
        "eligible": not errors,
        "status": "eligible" if not errors else "blocked",
        "server_derived": True,
        "authorization_mode": "exactly_one_accepted_initial_join_audit",
        "auth_only": True,
        "one_shot": True,
        "evidence_synthesized": False,
        "attempt_transition_applied": False,
        "retry_round_transition_applied": False,
        "status_transition_applied": False,
        "project_id": project_id,
        "runtime_context_id": runtime_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "backlog_id": backlog_id,
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "actual_host_worker_id": actual_host_worker_id,
        "worker_session_id": worker_session_id,
        "host_startup_id": host_startup_id,
        "host_session_id": host_session_id,
        "target_project_root": target_project_root,
        "session_token_ref": active_session_token_ref,
        "initial_join_event_ref": (
            f"timeline:{initial_join_audit.get('id', '')}"
            if initial_join_audit
            else ""
        ),
        "audit_cardinality": len(candidate_initial_join_audits),
        "audit_valid": bool(not audit_errors),
        "identity_contract_version": (
            "runtime_context.initial_join_identity.v2"
            if fresh_identity_cutover
            else "runtime_context.initial_join_identity.legacy"
        ),
        "canonical_identity_binding_required": fresh_identity_cutover,
        "canonical_identity_binding_valid": bool(
            fresh_identity_cutover
            and expected_canonical_binding
            and not any(
                error.startswith("initial_join_audit_canonical_binding_")
                or error.startswith("initial_join_audit_identity_")
                for error in errors
            )
        ),
        "canonical_identity_binding_anchor_ref": (
            f"timeline:{identity_anchor.get('id', '')}"
            if identity_anchor
            else ""
        ),
        "canonical_identity_cutover_audit_id": (
            str(cutover_audit_rows[0]["audit_id"] or "").strip()
            if len(cutover_audit_rows) == 1
            else ""
        ),
        "canonical_identity_cutover_valid": bool(
            fresh_identity_cutover
            and len(cutover_audit_rows) == 1
            and not any("cutover_" in error for error in errors)
        ),
        "legacy_agent_id_normalized": bool(
            legacy_agent_id_normalization_candidate and not errors
        ),
        "legacy_agent_id_normalization_source": (
            "accepted_contract_runtime_dispatch_worker_agent_id"
            if legacy_agent_id_normalization_candidate and not errors
            else ""
        ),
        "legacy_dispatch_identity_anchor": (
            dict(legacy_dispatch_anchor)
            if legacy_agent_id_normalization_candidate and not errors
            else {}
        ),
        "route_identity": canonical_route_identity,
        "lease": {
            "lease_id": str(lease.get("lease_id") or ""),
            "lease_expires_at": str(lease.get("lease_expires_at") or ""),
            "status": str(lease.get("status") or ""),
            "authorization_valid": lease.get("authorization_valid") is True,
            "expired": lease.get("expired") is True,
        },
        "errors": errors,
        "failure_code": failure_code if errors else "",
        "reason": failure_reason if errors else "",
        "fail_closed": bool(errors),
        "next_legal_action": (
            "rotate_pre_lineage_auth_once_then_parse_content_text_same_call"
            if not errors
            else (
                "stop_and_report_bounded_pre_lineage_recovery_exhausted"
                if failure_code
                == "runtime_context_pre_lineage_rejoin_already_consumed"
                else "stop_and_repair_pre_lineage_rejoin_authority"
            )
        ),
    }
    return authority


def _runtime_context_current_reissue_route_binding(
    conn,
    *,
    project_id: str,
    historical_route_identity: Mapping[str, Any],
    canonical_route_identity: Mapping[str, Any],
) -> dict[str, Any]:
    """Prove an immutable reissue route still reaches the current route.

    Reissue timeline evidence is append-only and therefore keeps the route
    identity that was current when the envelope was issued.  A later exact
    same-scope route renewal must not rewrite that event.  Instead, resolve
    the historical opaque ref through the server registry and accept only one
    active descendant whose full public identity is the current canonical
    identity.  The registry resolver also proves unchanged scope, caller
    role, actions, target files, and owned files at every hop.
    """

    historical = {
        field: str(historical_route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    canonical = {
        field: str(canonical_route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    binding: dict[str, Any] = {
        "schema_version": (
            "runtime_context.current_reissue_route_binding.v1"
        ),
        "valid": False,
        "status": "blocked",
        "binding_source": "",
        "historical_route_identity": historical,
        "canonical_route_identity": canonical,
        "historical_event_rewritten": False,
        "registry_verified": False,
        "exact_scope_verified": False,
        "scope_actions_files_verified": False,
        "writes_performed": False,
        "error_code": "",
    }
    if not all(historical.values()) or not all(canonical.values()):
        binding["error_code"] = "route_identity_missing"
        return binding
    if historical == canonical:
        binding.update(
            {
                "valid": True,
                "status": "exact_current_route",
                "binding_source": "immutable_event_exact_current_route",
            }
        )
        return binding

    from . import observer_route_context

    try:
        resolved = observer_route_context.resolve_route_token_ref_renewal_descendant(
            conn,
            project_id=project_id,
            storage_project_id=_route_registry_storage_project_id(project_id),
            route_token_ref=historical["route_token_ref"],
        )
    except (
        observer_route_context.RouteTokenRefError,
        sqlite3.Error,
        ValueError,
    ) as exc:
        binding.update(
            {
                "status": "renewal_lineage_rejected",
                "error_code": str(
                    getattr(exc, "code", "")
                    or type(exc).__name__
                ),
            }
        )
        return binding
    if not isinstance(resolved, Mapping):
        binding.update(
            {
                "status": "renewal_lineage_missing",
                "error_code": "route_token_ref_renewal_descendant_missing",
            }
        )
        return binding

    resolved_identity_source = _parallel_branch_runtime_contract_route_identity(
        resolved
    )
    resolved_identity = {
        field: str(resolved_identity_source.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    renewal = (
        dict(resolved.get("renewal_resolution") or {})
        if isinstance(resolved.get("renewal_resolution"), Mapping)
        else {}
    )
    requested_identity = (
        dict(renewal.get("requested_route_identity") or {})
        if isinstance(renewal.get("requested_route_identity"), Mapping)
        else {}
    )
    renewed_identity = (
        dict(renewal.get("resolved_route_identity") or {})
        if isinstance(renewal.get("resolved_route_identity"), Mapping)
        else {}
    )
    requested_identity = {
        field: str(requested_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    renewed_identity = {
        field: str(renewed_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    valid = bool(
        resolved.get("resolved_from_ref") is True
        and str(resolved.get("status") or "").strip() == "active"
        and str(renewal.get("status") or "").strip()
        == "resolved_active_descendant"
        and renewal.get("registry_verified") is True
        and renewal.get("exact_scope_verified") is True
        and requested_identity == historical
        and renewed_identity == canonical
        and resolved_identity == canonical
    )
    binding.update(
        {
            "valid": valid,
            "status": (
                "resolved_active_descendant"
                if valid
                else "renewal_lineage_identity_mismatch"
            ),
            "binding_source": (
                "server_registered_exact_same_scope_renewal_descendant"
                if valid
                else ""
            ),
            "registry_verified": renewal.get("registry_verified") is True,
            "exact_scope_verified": renewal.get("exact_scope_verified") is True,
            "scope_actions_files_verified": valid,
            "route_token_ref_chain": list(
                renewal.get("route_token_ref_chain") or []
            ),
            "resolved_route_identity": resolved_identity,
            "error_code": (
                "" if valid else "route_token_ref_renewal_binding_mismatch"
            ),
        }
    )
    return binding


def _runtime_context_verifier_backed_pre_lineage_rejoin_authority(
    conn,
    *,
    project_id: str,
    context: Any,
    runtime_context_id: str,
    body: Mapping[str, Any],
    contract_execution_id: str,
    route_identity: Mapping[str, Any],
    timeline_events: Sequence[Mapping[str, Any]],
    effective_read_receipt_ref: str = "",
    effective_startup_ref: str = "",
    now_iso: str = "",
) -> dict[str, Any]:
    """Authorize one verifier-backed rejoin after bounded reissue exhaustion.

    A failed-QA replacement can outlive every process-local envelope while its
    canonical successor dispatch, latest pinned initial join, identity anchor,
    current verifier and copy-safe ref remain durable.  Replaying initial_join
    in that world is both misleading and rejected by the raw-fence validator.
    This predicate instead grants exactly one ordinary rejoin, and only while
    no receipt/startup or prior pre-lineage rejoin exists.
    """

    from .parallel_branch_runtime import (
        ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES,
        runtime_context_fence_token_verifier,
        runtime_context_id_for_branch_context,
        runtime_context_session_token_lease_view,
        runtime_context_session_token_ref,
    )

    runtime_id = str(runtime_context_id or "").strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    parent_task_id = _runtime_context_mf_sub_parent_task_id(context)
    worker_id = str(getattr(context, "worker_id", "") or "").strip()
    worker_slot_id = str(
        getattr(context, "worker_slot_id", "") or worker_id
    ).strip()
    actual_host_worker_id = str(
        getattr(context, "actual_host_worker_id", "") or ""
    ).strip()
    host_session_id = str(
        getattr(context, "host_session_id", "") or ""
    ).strip()
    worker_session_id = _runtime_context_initial_join_worker_session_id(
        timeline_events,
        runtime_context_id=runtime_id,
        task_id=task_id,
        backlog_id=backlog_id,
    )
    host_startup_id = str(
        getattr(context, "host_startup_id", "") or ""
    ).strip()
    target_project_root = _runtime_context_effective_target_project_root(
        context
    )
    active_session_token_ref = runtime_context_session_token_ref(context)
    fence_token_hash = runtime_context_fence_token_verifier(context)
    last_recovery_action = str(
        getattr(context, "last_recovery_action", "") or ""
    ).strip()
    candidate_applicable = bool(
        not effective_read_receipt_ref
        and not effective_startup_ref
        and last_recovery_action
        in {
            "mf_subagent_session_token_reissued",
            "mf_subagent_pre_lineage_session_token_rejoin_issued",
        }
    )
    successor_contract_evidence = (
        _runtime_context_failed_qa_revision_contract_runtime_evidence(
            conn,
            project_id=project_id,
            context=context,
        )
        if candidate_applicable
        else {}
    )
    successor_dispatch_authority = (
        successor_contract_evidence.get(
            "successor_dispatch_revision_authority"
        )
        if isinstance(
            successor_contract_evidence.get(
                "successor_dispatch_revision_authority"
            ),
            Mapping,
        )
        else {}
    )
    marker = (
        _runtime_context_failed_qa_revision_rejoin_marker(
            conn=conn,
            context=context,
            runtime_context_id=runtime_id,
            timeline_events=timeline_events,
        )
        if candidate_applicable
        else {}
    )
    applicable = bool(
        candidate_applicable
        and successor_dispatch_authority
    )
    authority: dict[str, Any] = {
        "schema_version": "runtime_context.pre_lineage_rejoin_authority.v1",
        "applicable": applicable,
        "eligible": False,
        "status": "not_applicable" if not applicable else "blocked",
        "server_derived": True,
        "caller_claims_trusted": False,
        "authorization_mode": (
            "verifier_backed_exhausted_reissue_successor_dispatch"
        ),
        "auth_only": True,
        "one_shot": True,
        "evidence_synthesized": False,
        "attempt_transition_applied": False,
        "retry_round_transition_applied": False,
        "status_transition_applied": False,
        "project_id": project_id,
        "runtime_context_id": runtime_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "backlog_id": backlog_id,
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "actual_host_worker_id": actual_host_worker_id,
        "worker_session_id": worker_session_id,
        "host_startup_id": host_startup_id,
        "host_session_id": host_session_id,
        "target_project_root": target_project_root,
        "session_token_ref": active_session_token_ref,
        "fence_token_hash": fence_token_hash,
        "errors": [],
        "failure_code": "",
        "reason": "",
        "fail_closed": False,
    }
    if not applicable:
        return authority

    errors: list[str] = []
    lease = runtime_context_session_token_lease_view(
        context,
        now_iso=now_iso,
    )
    if str(getattr(context, "status", "") or "").strip() not in (
        ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES
    ):
        errors.append("runtime_context_not_active")
    if (
        not runtime_id
        or runtime_id != runtime_context_id_for_branch_context(context)
        or str(getattr(context, "project_id", "") or "").strip()
        != project_id
    ):
        errors.append("runtime_context_identity_mismatch")
    if not (
        re.fullmatch(r"sha256:[0-9a-f]{64}", fence_token_hash)
        and str(getattr(context, "session_token_hash", "") or "").strip()
        and active_session_token_ref
        and not str(getattr(context, "fence_token", "") or "").strip()
    ):
        errors.append("verifier_backed_current_auth_binding_invalid")
    if not (
        lease.get("lease_record_valid") is True
        and lease.get("status") == "expired"
        and lease.get("expired") is True
        and lease.get("authorization_valid") is False
    ):
        errors.append("current_reissue_lease_not_expired")

    expected_identity = {
        "runtime_context_id": runtime_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "target_project_root": target_project_root,
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "agent_id": actual_host_worker_id,
        "actual_host_worker_id": actual_host_worker_id,
        "worker_session_id": worker_session_id,
        "host_startup_id": host_startup_id,
        "host_session_id": host_session_id,
        "session_token_ref": active_session_token_ref,
    }
    for field, expected in expected_identity.items():
        actual = str(body.get(field) or "").strip()
        if not expected or actual != expected:
            errors.append(f"{field}_mismatch_or_missing")
    canonical_route_identity = {
        field: str(route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    for field, expected in canonical_route_identity.items():
        if not expected or str(body.get(field) or "").strip() != expected:
            errors.append(f"request_route_{field}_mismatch_or_missing")

    initial_join_event_ref = str(
        marker.get("revision_event_ref") or ""
    ).strip()
    identity_anchor_ref = str(
        marker.get("initial_join_identity_anchor_event_ref") or ""
    ).strip()
    if (
        str(marker.get("source") or "").strip()
        != "accepted_runtime_context_initial_join"
        or str(marker.get("contract_execution_id") or "").strip()
        != str(contract_execution_id or "").strip()
        or str(marker.get("runtime_context_id") or "").strip() != runtime_id
        or str(marker.get("task_id") or "").strip() != task_id
        or str(marker.get("parent_task_id") or "").strip() != parent_task_id
        or not re.fullmatch(r"timeline:[1-9][0-9]*", initial_join_event_ref)
        or not re.fullmatch(r"timeline:[1-9][0-9]*", identity_anchor_ref)
    ):
        errors.append("failed_qa_successor_join_lineage_invalid")

    accepted_reissues: list[Mapping[str, Any]] = []
    current_ref_reissues: list[Mapping[str, Any]] = []
    accepted_rejoins: list[Mapping[str, Any]] = []
    initial_join_event_id = int(
        initial_join_event_ref.removeprefix("timeline:") or 0
    )
    for event in timeline_events:
        if not isinstance(event, Mapping):
            continue
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        if str(event.get("status") or "").strip().lower() not in {
            "accepted",
            "ok",
            "pass",
            "passed",
            "success",
            "succeeded",
        }:
            continue
        if (
            str(payload.get("runtime_context_id") or "").strip()
            != runtime_id
            or str(payload.get("task_id") or event.get("task_id") or "").strip()
            != task_id
            or str(event.get("backlog_id") or payload.get("backlog_id") or "").strip()
            != backlog_id
        ):
            continue
        action = str(payload.get("action") or "").strip()
        if action == "runtime_context_session_token_reissue":
            accepted_reissues.append(event)
            if (
                str(payload.get("session_token_ref") or "").strip()
                == active_session_token_ref
            ):
                current_ref_reissues.append(event)
        elif (
            action == "runtime_context_session_token_rejoin"
            and int(event.get("id") or 0) > initial_join_event_id
        ):
            accepted_rejoins.append(event)

    current_reissue = (
        current_ref_reissues[0] if len(current_ref_reissues) == 1 else {}
    )
    current_reissue_payload = (
        current_reissue.get("payload")
        if isinstance(current_reissue.get("payload"), Mapping)
        else {}
    )
    current_reissue_authority = (
        current_reissue_payload.get("safe_ref_reissue_authority")
        if isinstance(
            current_reissue_payload.get("safe_ref_reissue_authority"), Mapping
        )
        else {}
    )
    current_reissue_source = (
        current_reissue_payload.get("safe_ref_session_authority_source")
        if isinstance(
            current_reissue_payload.get("safe_ref_session_authority_source"),
            Mapping,
        )
        else {}
    )
    loss_authority = (
        current_reissue_payload.get("safe_ref_loss_replacement_authority")
        if isinstance(
            current_reissue_payload.get("safe_ref_loss_replacement_authority"),
            Mapping,
        )
        else {}
    )
    loss_generation = int(
        loss_authority.get("loss_replacement_generation") or 0
    )
    max_loss_replacements = int(
        loss_authority.get("max_loss_replacements") or 0
    )
    current_reissue_route_binding = (
        _runtime_context_current_reissue_route_binding(
            conn,
            project_id=project_id,
            historical_route_identity=(
                current_reissue_payload.get("route_identity")
                if isinstance(
                    current_reissue_payload.get("route_identity"), Mapping
                )
                else {}
            ),
            canonical_route_identity=canonical_route_identity,
        )
    )
    if (
        len(current_ref_reissues) != 1
        or not accepted_reissues
        or int(current_reissue.get("id") or 0)
        != max(int(event.get("id") or 0) for event in accepted_reissues)
        or str(current_reissue_payload.get("contract_execution_id") or "").strip()
        != str(contract_execution_id or "").strip()
        or str(current_reissue_payload.get("fence_token_hash") or "").strip()
        != fence_token_hash
        or current_reissue_route_binding.get("valid") is not True
        or str(current_reissue_authority.get("initial_join_event_ref") or "").strip()
        != initial_join_event_ref
        or str(current_reissue_source.get("event_ref") or "").strip()
        != initial_join_event_ref
        or str(current_reissue_source.get("source_kind") or "").strip()
        != "initial_join"
    ):
        errors.append("current_reissue_source_binding_invalid")
    if not (
        loss_generation > 0
        and max_loss_replacements > 0
        and loss_generation >= max_loss_replacements
        and loss_authority.get("worker_receipt_consumed") is False
        and loss_authority.get("worker_startup_consumed") is False
    ):
        errors.append("safe_ref_reissue_budget_not_exhausted")
    if accepted_rejoins:
        errors.append("pre_lineage_rejoin_already_consumed")

    errors = list(dict.fromkeys(errors))
    failure_code = ""
    failure_reason = ""
    if "pre_lineage_rejoin_already_consumed" in errors:
        failure_code = "runtime_context_pre_lineage_rejoin_already_consumed"
        failure_reason = "pre_lineage_rejoin_already_consumed"
    elif any("mismatch" in error for error in errors):
        failure_code = "runtime_context_pre_lineage_rejoin_identity_mismatch"
        failure_reason = "runtime_identity_mismatch"
    elif "failed_qa_successor_join_lineage_invalid" in errors:
        failure_code = (
            "runtime_context_pre_lineage_rejoin_initial_join_audit_invalid"
        )
        failure_reason = "canonical_initial_join_audit_invalid"
    else:
        failure_code = "runtime_context_pre_lineage_rejoin_authority_invalid"
        failure_reason = errors[0] if errors else ""
    authority.update(
        {
            "eligible": not errors,
            "status": "eligible" if not errors else "blocked",
            "initial_join_event_ref": initial_join_event_ref,
            "canonical_identity_binding_anchor_ref": identity_anchor_ref,
            "audit_cardinality": 1 if initial_join_event_ref else 0,
            "audit_valid": bool(initial_join_event_ref and identity_anchor_ref),
            "identity_contract_version": (
                "runtime_context.initial_join_identity.v2"
            ),
            "canonical_identity_binding_required": True,
            "canonical_identity_binding_valid": bool(marker),
            "canonical_identity_cutover_valid": bool(marker),
            "route_identity": canonical_route_identity,
            "current_reissue_route_binding": (
                current_reissue_route_binding
            ),
            "lease": {
                "lease_id": str(lease.get("lease_id") or ""),
                "lease_expires_at": str(lease.get("lease_expires_at") or ""),
                "status": str(lease.get("status") or ""),
                "authorization_valid": lease.get("authorization_valid") is True,
                "expired": lease.get("expired") is True,
            },
            "reissue_event_ref": (
                f"timeline:{current_reissue.get('id', '')}"
                if current_reissue
                else ""
            ),
            "loss_replacement_generation": loss_generation,
            "max_loss_replacements": max_loss_replacements,
            "errors": errors,
            "failure_code": failure_code if errors else "",
            "reason": failure_reason if errors else "",
            "fail_closed": bool(errors),
            "next_legal_action": (
                "rotate_pre_lineage_auth_once_then_parse_content_text_same_call"
                if not errors
                else "stop_and_report_bounded_pre_lineage_recovery_exhausted"
            ),
        }
    )
    return authority


def _runtime_context_pre_lineage_guidance_authority(
    conn,
    *,
    project_id: str,
    context: Any,
    timeline_events: Sequence[Mapping[str, Any]],
    contract_runtime_sequence: Mapping[str, Any],
    effective_read_receipt_ref: str,
    effective_startup_ref: str,
    route_identity_override: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Run the same authority gate with server-projected copy-safe identity."""

    from .parallel_branch_runtime import runtime_context_session_token_ref

    runtime_context_id = str(
        getattr(context, "runtime_context_id", "") or ""
    ).strip()
    contract_identity, resolution = _runtime_context_source_backed_contract_identity(
        conn,
        project_id=project_id,
        context=context,
        runtime_context_id=runtime_context_id,
        task_id=str(getattr(context, "task_id", "") or "").strip(),
    )
    contract_execution_id = str(
        contract_runtime_sequence.get("contract_execution_id")
        or contract_identity.get("contract_execution_id")
        or _runtime_context_contract_execution_identity(
            _runtime_context_latest_contract_revision_payload(conn, context)
        ).get("contract_execution_id")
        or ""
    ).strip()
    latest_route_identity = _runtime_context_latest_route_identity(
        conn,
        context,
    )
    route_identity = (
        dict(route_identity_override)
        if isinstance(route_identity_override, Mapping)
        and route_identity_override
        else latest_route_identity
    )
    worker_id = str(getattr(context, "worker_id", "") or "").strip()
    actual_host_worker_id = str(
        getattr(context, "actual_host_worker_id", "") or ""
    ).strip()
    host_session_id = str(getattr(context, "host_session_id", "") or "").strip()
    worker_session_id = (
        _runtime_context_initial_join_worker_session_id(
            timeline_events,
            runtime_context_id=runtime_context_id,
            task_id=str(getattr(context, "task_id", "") or "").strip(),
            backlog_id=str(getattr(context, "backlog_id", "") or "").strip(),
        )
        or host_session_id
    )
    body = {
        "runtime_context_id": runtime_context_id,
        "task_id": str(getattr(context, "task_id", "") or "").strip(),
        "parent_task_id": _runtime_context_mf_sub_parent_task_id(context),
        "target_project_root": _runtime_context_effective_target_project_root(context),
        "worker_id": worker_id,
        "worker_slot_id": str(
            getattr(context, "worker_slot_id", "") or worker_id
        ).strip(),
        "agent_id": actual_host_worker_id,
        "actual_host_worker_id": actual_host_worker_id,
        "worker_session_id": worker_session_id,
        "host_startup_id": str(
            getattr(context, "host_startup_id", "") or ""
        ).strip(),
        "host_session_id": host_session_id,
        "session_token_ref": runtime_context_session_token_ref(context),
        "contract_execution_id": contract_execution_id,
        **{
            field: str(route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        },
    }
    verifier_backed_authority = (
        _runtime_context_verifier_backed_pre_lineage_rejoin_authority(
            conn,
            project_id=project_id,
            context=context,
            runtime_context_id=runtime_context_id,
            body=body,
            contract_execution_id=contract_execution_id,
            route_identity=route_identity,
            timeline_events=timeline_events,
            effective_read_receipt_ref=effective_read_receipt_ref,
            effective_startup_ref=effective_startup_ref,
            now_iso=_utc_now(),
        )
    )
    if verifier_backed_authority.get("applicable") is True:
        return verifier_backed_authority, resolution
    bootstrap_body = dict(body)
    bootstrap_body.update(
        {
            field: str(latest_route_identity.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        }
    )
    return (
        _runtime_context_pre_lineage_bootstrap_rejoin_authority(
            conn,
            project_id=project_id,
            context=context,
            runtime_context_id=runtime_context_id,
            body=bootstrap_body,
            contract_execution_id=contract_execution_id,
            route_identity=latest_route_identity,
            timeline_events=timeline_events,
            effective_read_receipt_ref=effective_read_receipt_ref,
            effective_startup_ref=effective_startup_ref,
        ),
        resolution,
    )


_RUNTIME_CONTEXT_REJOIN_FIRST_RECOVERY_ACTION = (
    "mf_subagent_session_token_rejoin_issued"
)
_RUNTIME_CONTEXT_REJOIN_REPLACEMENT_RECOVERY_ACTION = (
    "mf_subagent_session_token_rejoin_replacement_issued"
)
_RUNTIME_CONTEXT_REJOIN_CHECKPOINT_BASELINE_FIELDS = (
    "runtime_context_id",
    "contract_execution_id",
    "timeline_worker_write_count",
    "timeline_worker_write_hash",
    "contract_runtime_completed_line_count",
    "contract_runtime_completed_lines_hash",
)
_RUNTIME_CONTEXT_LEGACY_REJOIN_BASELINE_KEYS = frozenset(
    {
        "schema_version",
        *_RUNTIME_CONTEXT_REJOIN_CHECKPOINT_BASELINE_FIELDS,
    }
)
