@route("POST", "/api/graph-governance/{project_id}/query-traces/start")
def handle_graph_governance_query_trace_start(ctx: RequestContext):
    """Start an audited graph query trace for dashboard/AI/chain consumers."""
    project_id = ctx.get_project_id()
    body = ctx.body
    from . import graph_query_trace
    from .db import (
        admit_ac_dev_graph_materialization_schema,
        sqlite_write_lock,
    )

    conn = get_connection(project_id)
    try:
        _require_graph_query_capability(ctx, conn, body, "graph-governance.query-trace.start")
        _bind_trusted_mf_sub_graph_query_authority(ctx, conn, body)
        qa_proof = getattr(ctx, "_trusted_qa_graph_query_authority", {})
        qa_proof = qa_proof if isinstance(qa_proof, Mapping) else {}
        observer_proof = getattr(ctx, "_trusted_observer_graph_query_authority", {})
        observer_proof = observer_proof if isinstance(observer_proof, Mapping) else {}
        mf_sub_proof = getattr(ctx, "_trusted_mf_sub_graph_query_authority", {})
        mf_sub_proof = mf_sub_proof if isinstance(mf_sub_proof, Mapping) else {}
        route_proof = mf_sub_proof or observer_proof
        trace_proof = qa_proof
        snapshot_id = _resolve_graph_snapshot_id(conn, project_id, str(body.get("snapshot_id") or "active"))
        if _runtime_plane() == "dev":
            admit_ac_dev_graph_materialization_schema(
                conn, project_id=project_id,
            )
        try:
            with sqlite_write_lock():
                result = graph_query_trace.start_trace(
                    conn,
                    project_id,
                    snapshot_id,
                    actor=str(body.get("actor") or "observer"),
                    query_source=str(body.get("query_source") or "api_debug"),
                    query_purpose=str(body.get("query_purpose") or "api_debug"),
                    run_id=str(body.get("run_id") or ""),
                    parent_task_id=str(body.get("parent_task_id") or ""),
                    runtime_context_id=str(body.get("runtime_context_id") or ""),
                    task_id=str(
                        qa_proof.get("task_id")
                        or route_proof.get("task_id")
                        or body.get("task_id")
                        or ""
                    ),
                    backlog_id=str(
                        qa_proof.get("backlog_id")
                        or route_proof.get("backlog_id")
                        or ""
                    ),
                    route_id=str(route_proof.get("route_id") or ""),
                    route_context_hash=str(
                        route_proof.get("route_context_hash") or ""
                    ),
                    prompt_contract_id=str(
                        route_proof.get("prompt_contract_id") or ""
                    ),
                    prompt_contract_hash=str(
                        route_proof.get("prompt_contract_hash") or ""
                    ),
                    visible_injection_manifest_hash=str(
                        route_proof.get("visible_injection_manifest_hash") or ""
                    ),
                    route_token_ref=str(route_proof.get("route_token_ref") or ""),
                    commit_sha=str(trace_proof.get("commit_sha") or ""),
                    graph_basis=str(trace_proof.get("graph_basis") or ""),
                    graph_basis_decision=(
                        trace_proof.get("graph_basis_decision")
                        if isinstance(
                            trace_proof.get("graph_basis_decision"), Mapping
                        )
                        else None
                    ),
                    graph_basis_decision_hash=str(
                        trace_proof.get("graph_basis_decision_hash") or ""
                    ),
                    canonical_base_snapshot_id=str(
                        trace_proof.get("canonical_base_snapshot_id") or ""
                    ),
                    base_commit_sha=str(trace_proof.get("base_commit_sha") or ""),
                    candidate_commit_sha=str(
                        trace_proof.get("candidate_commit_sha") or ""
                    ),
                    changed_files=(
                        list(trace_proof.get("changed_files") or [])
                        if trace_proof.get("graph_basis")
                        else None
                    ),
                    candidate_diff_hash=str(
                        trace_proof.get("candidate_diff_hash") or ""
                    ),
                    changed_files_source=str(
                        trace_proof.get("changed_files_source") or ""
                    ),
                    candidate_overlay=(
                        trace_proof.get("candidate_overlay")
                        if isinstance(trace_proof.get("candidate_overlay"), Mapping)
                        else None
                    ),
                    candidate_overlay_hash=str(
                        trace_proof.get("candidate_overlay_hash") or ""
                    ),
                    root_identity=(
                        trace_proof.get("root_identity")
                        if isinstance(trace_proof.get("root_identity"), Mapping)
                        else None
                    ),
                    root_identity_hash=str(
                        trace_proof.get("root_identity_hash") or ""
                    ),
                    query_root_identity_hash=str(
                        trace_proof.get("query_root_identity_hash") or ""
                    ),
                    canonical_project_identity_hash=str(
                        trace_proof.get("canonical_project_identity_hash") or ""
                    ),
                    repository_identity_hash=str(
                        trace_proof.get("repository_identity_hash") or ""
                    ),
                    qa_session_id=str(qa_proof.get("qa_session_id") or ""),
                    qa_scope_binding_ref=str(
                        qa_proof.get("qa_scope_binding_ref") or ""
                    ),
                    worker_role=str(body.get("worker_role") or ""),
                    fence_token=str(body.get("fence_token") or ""),
                    budget=body.get("query_budget") if isinstance(body.get("query_budget"), dict) else None,
                    trace_id=body.get("trace_id") or None,
                )
                conn.commit()
            return result
        except (KeyError, ValueError) as exc:
            _raise_graph_api_validation(exc)
    finally:
        conn.close()


def _runtime_context_mf_sub_graph_query_canonical_eligibility(
    conn,
    *,
    project_id: str,
    context: Any,
) -> dict[str, Any]:
    """Classify whether this graph query owns a pinned canonical line.

    Legacy/runtime-only contexts may query and audit graph state, but there is
    no ContractRuntime line for them to advance.  Classify those compatibility
    paths before applying the canonical advancement gate so the gate cannot
    turn a successful read-only query into a failure.
    """

    revision_payload = _runtime_context_latest_contract_revision_payload(
        conn,
        context,
    )
    contract_identity = _runtime_context_contract_execution_identity(
        revision_payload,
    )
    runtime_context_id = str(
        getattr(context, "runtime_context_id", "") or ""
    ).strip()
    task_id = str(getattr(context, "task_id", "") or "").strip()
    resolved_identity, resolution = (
        _runtime_context_resolve_contract_execution_identity(
            conn,
            project_id=project_id,
            context=context,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            contract_identity=contract_identity,
        )
    )
    execution_id = str(
        resolved_identity.get("contract_execution_id") or ""
    ).strip()
    resolution_status = str(resolution.get("status") or "").strip()
    if not execution_id and resolution_status != (
        "ambiguous_active_source_backed_worker_lineage"
    ):
        return {
            "schema_version": (
                "runtime_context.mf_sub_graph_query_canonical_eligibility.v1"
            ),
            "canonical_gate_required": False,
            "status": "compatibility_no_contract_execution",
            "canonical": False,
            "line_id": "worker_graph_context",
            "contract_execution_resolution": resolution,
        }

    if execution_id:
        try:
            line_pinned = _contract_runtime(conn).pinned_definition_has_line(
                execution_id,
                "worker_graph_context",
            )
        except ContractRuntimeError:
            # A source-backed but unavailable execution must continue into the
            # strict path, where the canonical submitter reports its authority
            # failure instead of being mislabeled as compatibility mode.
            line_pinned = True
        if not line_pinned:
            return {
                "schema_version": (
                    "runtime_context.mf_sub_graph_query_canonical_eligibility.v1"
                ),
                "canonical_gate_required": False,
                "status": "compatibility_line_not_pinned",
                "canonical": False,
                "contract_execution_id": execution_id,
                "line_id": "worker_graph_context",
                "contract_execution_resolution": resolution,
            }

    return {
        "schema_version": (
            "runtime_context.mf_sub_graph_query_canonical_eligibility.v1"
        ),
        "canonical_gate_required": True,
        "status": "source_backed_canonical_line",
        "canonical": True,
        "contract_execution_id": execution_id,
        "line_id": "worker_graph_context",
        "contract_execution_resolution": resolution,
    }


def _runtime_context_mf_sub_graph_query_canonical_gate(
    conn,
    *,
    project_id: str,
    snapshot_id: str,
    query_result: Any,
    context: Any,
) -> dict[str, Any]:
    """Verify one completed graph read before it may advance ContractRuntime."""

    def reject(
        error: str,
        message: str,
        **details: Any,
    ) -> dict[str, Any]:
        return {
            "schema_version": (
                "runtime_context.mf_sub_graph_query_canonical_gate.v1"
            ),
            "ok": False,
            "status": "rejected",
            "error": error,
            "message": message,
            "fail_closed": True,
            "canonical_line_allowed": False,
            "contract_runtime_mutated": False,
            "completed_lines_mutated": False,
            "verified_projection_allowed": False,
            "finish_projection_allowed": False,
            "close_projection_allowed": False,
            **details,
        }

    if not isinstance(query_result, Mapping):
        return reject(
            "mf_sub_graph_query_result_malformed",
            "mf_sub canonical graph context requires a mapping query result",
            query_result_type=type(query_result).__name__,
        )
    inner_result = query_result.get("result")
    if query_result.get("ok") is not True:
        return reject(
            "mf_sub_graph_query_failed",
            "failed graph queries cannot advance worker_graph_context",
            original_query_failure_preserved=True,
        )
    if not isinstance(inner_result, Mapping) or not inner_result:
        return reject(
            "mf_sub_graph_query_inner_result_malformed",
            (
                "mf_sub canonical graph context requires a non-empty "
                "mapping inner result"
            ),
            inner_result_type=type(inner_result).__name__,
        )
    if inner_result.get("ok") is not True:
        return reject(
            "mf_sub_graph_query_inner_result_failed",
            "failed inner graph-query results cannot advance worker_graph_context",
            original_query_failure_preserved=True,
        )

    graph_trace_id = str(query_result.get("trace_id") or "").strip()
    if not graph_trace_id:
        return reject(
            "mf_sub_graph_query_trace_id_missing",
            "mf_sub canonical graph context requires a persisted trace id",
        )

    from . import graph_query_trace, graph_snapshot_store

    try:
        trace_response = graph_query_trace.get_trace(
            conn,
            project_id,
            graph_trace_id,
        )
    except (KeyError, TypeError, ValueError, sqlite3.Error) as exc:
        return reject(
            "mf_sub_graph_query_trace_unavailable",
            "mf_sub canonical graph context requires a DB-backed trace",
            graph_trace_id=graph_trace_id,
            trace_error=str(exc),
        )
    if not isinstance(trace_response, Mapping):
        return reject(
            "mf_sub_graph_query_trace_malformed",
            "DB graph trace lookup did not return a mapping response",
            graph_trace_id=graph_trace_id,
            trace_response_type=type(trace_response).__name__,
        )
    trace = (
        trace_response.get("trace")
        if isinstance(trace_response.get("trace"), Mapping)
        else {}
    )
    if trace_response.get("ok") is not True or not trace:
        return reject(
            "mf_sub_graph_query_trace_malformed",
            "DB graph trace lookup did not return a complete trace record",
            graph_trace_id=graph_trace_id,
        )
    persisted_trace_id = str(trace.get("trace_id") or "").strip()
    if persisted_trace_id != graph_trace_id:
        return reject(
            "mf_sub_graph_query_trace_identity_mismatch",
            "returned graph trace id does not match the persisted trace",
            graph_trace_id=graph_trace_id,
            persisted_trace_id=persisted_trace_id,
        )
    trace_status = str(trace.get("status") or "").strip().lower()
    if trace_status != "complete":
        return reject(
            "mf_sub_graph_query_trace_not_complete",
            "only COMPLETE DB graph traces may advance worker_graph_context",
            graph_trace_id=graph_trace_id,
            trace_status=trace_status,
        )
    trace_events = trace.get("events")
    trace_seq = query_result.get("seq")
    if (
        not isinstance(trace_events, Sequence)
        or isinstance(trace_events, (str, bytes))
        or not trace_events
        or not any(
            isinstance(event, Mapping) and event.get("seq") == trace_seq
            for event in trace_events
        )
    ):
        return reject(
            "mf_sub_graph_query_trace_event_missing",
            "completed graph trace does not contain the returned query event",
            graph_trace_id=graph_trace_id,
            trace_seq=trace_seq,
        )

    resolved_snapshot_id = str(snapshot_id or "").strip()
    trace_snapshot_id = str(trace.get("snapshot_id") or "").strip()
    if not resolved_snapshot_id or trace_snapshot_id != resolved_snapshot_id:
        return reject(
            "mf_sub_graph_query_trace_snapshot_mismatch",
            "graph trace snapshot does not match the resolved query snapshot",
            graph_trace_id=graph_trace_id,
            expected_snapshot_id=resolved_snapshot_id,
            actual_snapshot_id=trace_snapshot_id,
        )

    try:
        active_ref = conn.execute(
            """
            SELECT snapshot_id, commit_sha
            FROM graph_snapshot_refs
            WHERE project_id = ? AND ref_name = 'active'
            """,
            (project_id,),
        ).fetchone()
        active_snapshot = graph_snapshot_store.get_active_graph_snapshot(
            conn,
            project_id,
        )
        queried_snapshot = graph_snapshot_store.get_graph_snapshot(
            conn,
            project_id,
            resolved_snapshot_id,
        )
    except (KeyError, TypeError, ValueError, sqlite3.Error) as exc:
        return reject(
            "mf_sub_graph_query_snapshot_authority_unavailable",
            "graph snapshot authority could not be resolved",
            graph_trace_id=graph_trace_id,
            snapshot_id=resolved_snapshot_id,
            snapshot_error=str(exc),
        )
    if not queried_snapshot:
        return reject(
            "mf_sub_graph_query_snapshot_missing",
            "canonical graph context requires a persisted graph snapshot",
            graph_trace_id=graph_trace_id,
            snapshot_id=resolved_snapshot_id,
        )

    active_ref_snapshot_id = str(
        (active_ref["snapshot_id"] if active_ref else "") or ""
    ).strip()
    active_snapshot_id = str(
        (active_snapshot.get("snapshot_id") if active_snapshot else "") or ""
    ).strip()
    active_ref_commit = str(
        (active_ref["commit_sha"] if active_ref else "") or ""
    ).strip().lower()
    active_snapshot_commit = str(
        (active_snapshot.get("commit_sha") if active_snapshot else "") or ""
    ).strip().lower()
    queried_snapshot_commit = str(
        queried_snapshot.get("commit_sha") or ""
    ).strip().lower()
    queried_snapshot_kind = str(
        queried_snapshot.get("snapshot_kind") or ""
    ).strip().lower()
    queried_snapshot_status = str(
        queried_snapshot.get("status") or ""
    ).strip().lower()
    expected_runtime_commit, expected_runtime_commit_source = (
        _runtime_context_expected_graph_commit(context)
    )
    if queried_snapshot_kind != "full":
        return reject(
            "mf_sub_graph_query_snapshot_not_full",
            "worker_graph_context requires an exact full graph snapshot",
            graph_trace_id=graph_trace_id,
            snapshot_id=resolved_snapshot_id,
            snapshot_kind=queried_snapshot_kind,
            snapshot_status=queried_snapshot_status,
            expected_snapshot_kind="full",
        )
    if (
        not expected_runtime_commit
        or not queried_snapshot_commit
        or queried_snapshot_commit != expected_runtime_commit
    ):
        return reject(
            "mf_sub_graph_query_frozen_world_commit_mismatch",
            (
                "query snapshot is not bound to the frozen RuntimeContext "
                "WorldRef commit"
            ),
            graph_trace_id=graph_trace_id,
            snapshot_id=resolved_snapshot_id,
            query_snapshot_commit=queried_snapshot_commit,
            expected_runtime_context_commit=expected_runtime_commit,
            expected_runtime_context_commit_source=(
                expected_runtime_commit_source
            ),
            active_snapshot_id=active_snapshot_id,
            active_snapshot_commit=active_snapshot_commit,
            global_active_ref_authoritative=False,
        )

    active_binding_exact = bool(
        active_ref_snapshot_id
        and active_ref_snapshot_id == resolved_snapshot_id
        and active_snapshot_id == resolved_snapshot_id
        and active_ref_commit == queried_snapshot_commit
        and active_snapshot_commit == queried_snapshot_commit
    )
    snapshot_authority_mode = (
        "active_exact_frozen_world"
        if active_binding_exact
        else "historical_exact_frozen_world"
    )

    return {
        "schema_version": (
            "runtime_context.mf_sub_graph_query_canonical_gate.v1"
        ),
        "ok": True,
        "status": "verified",
        "fail_closed": True,
        "canonical_line_allowed": True,
        "graph_trace_id": graph_trace_id,
        "trace_status": trace_status,
        "trace_complete": True,
        "trace_snapshot_id": trace_snapshot_id,
        "snapshot_id": resolved_snapshot_id,
        "snapshot_kind": queried_snapshot_kind,
        "snapshot_status": queried_snapshot_status,
        "expected_active_snapshot_id": active_ref_snapshot_id,
        "expected_active_graph_commit": active_ref_commit,
        "observed_active_snapshot_id": active_snapshot_id,
        "observed_active_snapshot_commit": active_snapshot_commit,
        "expected_runtime_context_commit": expected_runtime_commit,
        "expected_runtime_context_commit_source": (
            expected_runtime_commit_source
        ),
        "snapshot_commit": queried_snapshot_commit,
        "snapshot_authority_mode": snapshot_authority_mode,
        "frozen_runtime_world_authoritative": True,
        "global_active_ref_authoritative": False,
        "active_snapshot_required": False,
        "active_binding_exact": active_binding_exact,
        "source_of_authority": (
            "runtime_context_frozen_world+graph_query_traces+"
            "graph_query_events+graph_snapshots"
        ),
    }


@route("POST", "/api/graph-governance/{project_id}/query")
def handle_graph_governance_query(ctx: RequestContext):
    """Run one graph query and append it to an auditable trace."""
    project_id = ctx.get_project_id()
    body = ctx.body
    from . import graph_query_trace, graph_snapshot_store
    from .db import (
        admit_ac_dev_graph_materialization_schema,
        sqlite_write_lock,
    )

    tool = str(body.get("tool") or "")
    root = None
    if (
        body.get("project_root")
        or body.get("target_project_root")
        or body.get("target_graph_root")
        or body.get("workspace_path")
        or body.get("repo_root")
        or tool in {"search_docs", "get_file_excerpt"}
    ):
        root = _graph_governance_project_root(project_id, body)
    conn = get_connection(project_id)
    try:
        _require_graph_query_capability(ctx, conn, body, "graph-governance.query")
        qa_proof = getattr(ctx, "_trusted_qa_graph_query_authority", {})
        qa_proof = qa_proof if isinstance(qa_proof, Mapping) else {}
        observer_proof = getattr(ctx, "_trusted_observer_graph_query_authority", {})
        observer_proof = observer_proof if isinstance(observer_proof, Mapping) else {}
        cross_project_contract_line = (
            _runtime_context_cross_project_graph_contract_preflight(
                target_project_id=project_id,
                body=body,
            )
        )
        _bind_trusted_mf_sub_graph_query_authority(ctx, conn, body)
        mf_sub_proof = getattr(ctx, "_trusted_mf_sub_graph_query_authority", {})
        mf_sub_proof = mf_sub_proof if isinstance(mf_sub_proof, Mapping) else {}
        safe_ref_authority = getattr(
            ctx,
            "_trusted_mf_sub_graph_query_safe_ref_authority",
            {},
        )
        safe_ref_authority = (
            safe_ref_authority
            if isinstance(safe_ref_authority, Mapping)
            else {}
        )
        safe_ref_fence_hash = str(
            safe_ref_authority.get("fence_token_hash") or ""
        ).strip()
        route_proof = mf_sub_proof or observer_proof
        trace_proof = qa_proof or observer_proof
        if root is None and (
            body.get("project_root")
            or body.get("target_project_root")
            or body.get("target_graph_root")
            or body.get("workspace_path")
            or body.get("repo_root")
        ):
            root = _graph_governance_project_root(project_id, body)
        if trace_proof.get("graph_basis") == "exact_candidate_snapshot":
            root_identity = trace_proof.get("root_identity")
            if isinstance(root_identity, Mapping) and root_identity.get(
                "query_root"
            ):
                root = Path(str(root_identity["query_root"]))
        elif root is None and trace_proof:
            root_identity = trace_proof.get("root_identity")
            if isinstance(root_identity, Mapping) and root_identity.get("query_root"):
                root = Path(str(root_identity["query_root"]))
        snapshot_id = _resolve_graph_snapshot_id(conn, project_id, str(body.get("snapshot_id") or "active"))
        if _runtime_plane() == "dev":
            admit_ac_dev_graph_materialization_schema(
                conn, project_id=project_id,
            )
        try:
            with sqlite_write_lock():
                result = graph_query_trace.traced_query(
                    conn,
                    project_id,
                    snapshot_id,
                    tool=tool,
                    args=body.get("args") if isinstance(body.get("args"), dict) else {},
                    trace_id=str(body.get("trace_id") or ""),
                    actor=str(body.get("actor") or "observer"),
                    query_source=str(body.get("query_source") or "api_debug"),
                    query_purpose=str(body.get("query_purpose") or "api_debug"),
                    run_id=str(body.get("run_id") or ""),
                    parent_task_id=str(body.get("parent_task_id") or ""),
                    runtime_context_id=str(body.get("runtime_context_id") or ""),
                    task_id=str(
                        qa_proof.get("task_id")
                        or route_proof.get("task_id")
                        or body.get("task_id")
                        or ""
                    ),
                    backlog_id=str(
                        qa_proof.get("backlog_id")
                        or route_proof.get("backlog_id")
                        or ""
                    ),
                    route_id=str(route_proof.get("route_id") or ""),
                    route_context_hash=str(
                        route_proof.get("route_context_hash") or ""
                    ),
                    prompt_contract_id=str(
                        route_proof.get("prompt_contract_id") or ""
                    ),
                    prompt_contract_hash=str(
                        route_proof.get("prompt_contract_hash") or ""
                    ),
                    visible_injection_manifest_hash=str(
                        route_proof.get("visible_injection_manifest_hash") or ""
                    ),
                    route_token_ref=str(route_proof.get("route_token_ref") or ""),
                    commit_sha=str(trace_proof.get("commit_sha") or ""),
                    graph_basis=str(trace_proof.get("graph_basis") or ""),
                    graph_basis_decision=(
                        trace_proof.get("graph_basis_decision")
                        if isinstance(
                            trace_proof.get("graph_basis_decision"), Mapping
                        )
                        else None
                    ),
                    graph_basis_decision_hash=str(
                        trace_proof.get("graph_basis_decision_hash") or ""
                    ),
                    canonical_base_snapshot_id=str(
                        trace_proof.get("canonical_base_snapshot_id") or ""
                    ),
                    base_commit_sha=str(trace_proof.get("base_commit_sha") or ""),
                    candidate_commit_sha=str(
                        trace_proof.get("candidate_commit_sha") or ""
                    ),
                    changed_files=(
                        list(trace_proof.get("changed_files") or [])
                        if trace_proof.get("graph_basis")
                        else None
                    ),
                    candidate_diff_hash=str(
                        trace_proof.get("candidate_diff_hash") or ""
                    ),
                    changed_files_source=str(
                        trace_proof.get("changed_files_source") or ""
                    ),
                    candidate_overlay=(
                        trace_proof.get("candidate_overlay")
                        if isinstance(trace_proof.get("candidate_overlay"), Mapping)
                        else None
                    ),
                    candidate_overlay_hash=str(
                        trace_proof.get("candidate_overlay_hash") or ""
                    ),
                    root_identity=(
                        trace_proof.get("root_identity")
                        if isinstance(trace_proof.get("root_identity"), Mapping)
                        else None
                    ),
                    root_identity_hash=str(
                        trace_proof.get("root_identity_hash") or ""
                    ),
                    query_root_identity_hash=str(
                        trace_proof.get("query_root_identity_hash") or ""
                    ),
                    canonical_project_identity_hash=str(
                        trace_proof.get("canonical_project_identity_hash") or ""
                    ),
                    repository_identity_hash=str(
                        trace_proof.get("repository_identity_hash") or ""
                    ),
                    candidate_sources=(
                        trace_proof.get("_candidate_sources")
                        if isinstance(trace_proof.get("_candidate_sources"), Mapping)
                        else None
                    ),
                    qa_session_id=str(qa_proof.get("qa_session_id") or ""),
                    qa_scope_binding_ref=str(
                        qa_proof.get("qa_scope_binding_ref") or ""
                    ),
                    worker_role=str(body.get("worker_role") or ""),
                    fence_token=str(
                        body.get("fence_token") or safe_ref_fence_hash or ""
                    ),
                    budget=body.get("query_budget") if isinstance(body.get("query_budget"), dict) else None,
                    project_root=root,
                )
                direct_world_trace = (
                    _observer_parentless_direct_main_bind_graph_trace_world(
                        conn,
                        project_id=project_id,
                        trace_id=str(result.get("trace_id") or ""),
                        observer_proof=observer_proof,
                    )
                )
                if direct_world_trace:
                    result["graph_query_identity"] = dict(
                        direct_world_trace.get("graph_query_identity") or {}
                    )
                if safe_ref_fence_hash:
                    result["mf_sub_graph_query_safe_ref_authority"] = dict(
                        safe_ref_authority
                    )
                result_error = str(
                    (result.get("result") or {}).get("error")
                    if isinstance(result.get("result"), Mapping)
                    else ""
                )
                if (
                    qa_proof.get("graph_basis")
                    == "canonical_base_plus_candidate_diff"
                    and not result.get("ok")
                    and "one-hop dependency query failed closed" in result_error
                ):
                    result["exact_candidate_upgrade"] = (
                        graph_query_trace.record_qa_graph_basis_escalation(
                            conn,
                            project_id,
                            backlog_id=str(qa_proof.get("backlog_id") or ""),
                            task_id=str(qa_proof.get("task_id") or ""),
                            qa_session_id=str(
                                qa_proof.get("qa_session_id") or ""
                            ),
                            candidate_commit_sha=str(
                                qa_proof.get("candidate_commit_sha") or ""
                            ),
                            machine_reason=(
                                "one_hop_dependency_query_failed_closed"
                            ),
                        )
                    )
                if qa_proof.get("graph_basis") == "exact_candidate_snapshot":
                    if root is None:
                        raise GovernanceError(
                            "qa_exact_candidate_root_required",
                            "exact candidate query requires its persisted assigned root",
                            409,
                            {},
                        )
                    canonical_project_root = Path(
                        project_service.resolve_project_root(
                            project_id,
                            None,
                            fallback_self=True,
                        )
                    )
                    exact_snapshot = graph_snapshot_store.get_graph_snapshot(
                        conn,
                        project_id,
                        snapshot_id,
                    ) or {}
                    exact_snapshot_materialization = (
                        graph_snapshot_store.snapshot_materialization_provenance(
                            exact_snapshot
                        )
                    )
                    recomputed_exact = _qa_exact_candidate_context(
                        Path(root),
                        project_id=project_id,
                        canonical_project_root=canonical_project_root,
                        candidate_commit_sha=str(
                            qa_proof.get("candidate_commit_sha") or ""
                        ),
                        escalation={
                            "escalation_id": str(
                                (
                                    qa_proof.get("graph_basis_decision") or {}
                                ).get("exact_candidate_upgrade_ref")
                                or ""
                            ),
                            "exact_candidate_upgrade_trigger": str(
                                (
                                    qa_proof.get("graph_basis_decision") or {}
                                ).get("exact_candidate_upgrade_trigger")
                                or ""
                            ),
                            "candidate_change_classification": str(
                                (
                                    qa_proof.get("graph_basis_decision") or {}
                                ).get("candidate_change_classification")
                                or ""
                            ),
                        }
                        if isinstance(
                            qa_proof.get("graph_basis_decision"), Mapping
                        )
                        else {},
                        comparison_base_commit_sha=str(
                            (
                                qa_proof.get("root_identity")
                                if isinstance(
                                    qa_proof.get("root_identity"), Mapping
                                )
                                else {}
                            ).get("comparison_base_commit_sha")
                            or ""
                        ),
                        comparison_base_commit_source=str(
                            (
                                qa_proof.get("root_identity")
                                if isinstance(
                                    qa_proof.get("root_identity"), Mapping
                                )
                                else {}
                            ).get("comparison_base_commit_source")
                            or ""
                        ),
                        comparison_base_commit_lineage_source=str(
                            (
                                qa_proof.get("root_identity")
                                if isinstance(
                                    qa_proof.get("root_identity"), Mapping
                                )
                                else {}
                            ).get("comparison_base_commit_lineage_source")
                            or ""
                        ),
                        comparison_authority_required=bool(
                            qa_proof.get("comparison_authority_required")
                            or (
                                qa_proof.get("root_identity")
                                if isinstance(
                                    qa_proof.get("root_identity"), Mapping
                                )
                                else {}
                            ).get("comparison_authority_required")
                        ),
                        registered_allocator_worktree_paths=(
                            _qa_registered_allocator_worktree_paths(
                                conn,
                                project_id=project_id,
                                canonical_project_root=canonical_project_root,
                            )
                        ),
                        exact_snapshot_materialization_provenance=(
                            exact_snapshot_materialization
                            if exact_snapshot_materialization.get(
                                "execution_root"
                            )
                            else None
                        ),
                    )
                    exact_mismatches = [
                        field
                        for field in (
                            "changed_files",
                            "candidate_diff_hash",
                            "changed_files_source",
                            "comparison_base_commit_sha",
                            "comparison_base_commit_source",
                            "comparison_base_commit_lineage_source",
                            "root_identity_hash",
                            "query_root_identity_hash",
                            "repository_identity_hash",
                        )
                        if recomputed_exact.get(field) != qa_proof.get(field)
                    ]
                    if exact_mismatches:
                        raise GovernanceError(
                            "qa_exact_candidate_root_changed",
                            "exact candidate root identity changed during the query",
                            409,
                            {"identity_mismatches": exact_mismatches},
                        )
                if str(body.get("query_source") or "") == "mf_subagent":
                    governance_project_id = str(
                        body.get("governance_project_id") or project_id
                    ).strip()
                    if governance_project_id != project_id:
                        result["contract_runtime_canonical_line"] = (
                            cross_project_contract_line
                        )
                        conn.commit()
                        return _runtime_context_server_bounded_mf_sub_graph_query_response(
                            result
                        )
                    from .parallel_branch_runtime import (
                        get_branch_context_by_runtime_context_id,
                        runtime_context_fence_token_verifier,
                        runtime_context_session_token_ref,
                    )
                    from .runtime_context import worker_proof_line_provenance

                    runtime_context_id = str(
                        body.get("runtime_context_id") or ""
                    ).strip()
                    runtime_context = get_branch_context_by_runtime_context_id(
                        conn,
                        project_id,
                        runtime_context_id,
                    )
                    if runtime_context is None:
                        raise GovernanceError(
                            "runtime_context_not_found",
                            "worker graph query requires an active runtime context",
                            404,
                            {"runtime_context_id": runtime_context_id},
                        )
                    canonical_eligibility = (
                        _runtime_context_mf_sub_graph_query_canonical_eligibility(
                            conn,
                            project_id=project_id,
                            context=runtime_context,
                        )
                    )
                    result["mf_sub_graph_query_canonical_eligibility"] = (
                        canonical_eligibility
                    )
                    if not canonical_eligibility.get(
                        "canonical_gate_required"
                    ):
                        result["contract_runtime_canonical_line"] = {
                            "schema_version": (
                                "runtime_context.canonical_contract_line.v1"
                            ),
                            "accepted": False,
                            "status": canonical_eligibility.get("status"),
                            "canonical": False,
                            "contract_execution_id": (
                                canonical_eligibility.get(
                                    "contract_execution_id"
                                )
                                or ""
                            ),
                            "line_id": "worker_graph_context",
                            "contract_execution_resolution": (
                                canonical_eligibility.get(
                                    "contract_execution_resolution"
                                )
                                or {}
                            ),
                        }
                        conn.commit()
                        return _runtime_context_server_bounded_mf_sub_graph_query_response(
                            result
                        )
                    canonical_graph_gate = (
                        _runtime_context_mf_sub_graph_query_canonical_gate(
                            conn,
                            project_id=project_id,
                            snapshot_id=snapshot_id,
                            query_result=result,
                            context=runtime_context,
                        )
                    )
                    result["mf_sub_graph_query_canonical_gate"] = (
                        canonical_graph_gate
                    )
                    if not canonical_graph_gate.get("ok"):
                        if result.get("ok") is True:
                            result["ok"] = False
                            result["error"] = str(
                                canonical_graph_gate.get("error")
                                or "mf_sub_graph_query_canonical_gate_rejected"
                            )
                        result["contract_runtime_canonical_line"] = {
                            "schema_version": (
                                "runtime_context.canonical_contract_line.v1"
                            ),
                            "accepted": False,
                            "status": "graph_query_canonical_gate_rejected",
                            "canonical": False,
                            "source_of_authority": (
                                canonical_graph_gate.get("source_of_authority")
                                or "graph_query_canonical_gate"
                            ),
                            "runtime_context_id": runtime_context_id,
                            "task_id": runtime_context.task_id,
                            "stage_id": "worker_context",
                            "line_id": "worker_graph_context",
                            "evidence_kind": "graph_trace",
                            "fail_closed": True,
                            "contract_runtime_mutated": False,
                            "completed_lines_mutated": False,
                            "verified_projection_allowed": False,
                            "finish_projection_allowed": False,
                            "close_projection_allowed": False,
                            "timeline_evidence_backfill_allowed": False,
                            "graph_query_canonical_gate": canonical_graph_gate,
                        }
                        conn.commit()
                        return _runtime_context_server_bounded_mf_sub_graph_query_response(
                            result
                        )
                    trace_payload = (
                        result.get("trace")
                        if isinstance(result.get("trace"), Mapping)
                        else {}
                    )
                    graph_trace_id = str(
                        result.get("trace_id")
                        or trace_payload.get("trace_id")
                        or ""
                    ).strip()
                    parent_task_id = str(
                        body.get("parent_task_id")
                        or runtime_context.parent_task_id
                        or runtime_context.root_task_id
                        or runtime_context.backlog_id
                        or ""
                    ).strip()
                    target_project_root = (
                        _runtime_context_effective_target_project_root(
                            runtime_context
                        )
                    )
                    route_identity = _runtime_context_latest_route_identity(
                        conn,
                        runtime_context,
                    )
                    session_token_ref = runtime_context_session_token_ref(
                        runtime_context
                    )
                    fence_token_hash = runtime_context_fence_token_verifier(
                        runtime_context
                    )
                    worker_provenance = worker_proof_line_provenance(
                        {
                            "runtime_context_id": runtime_context_id,
                            "task_id": runtime_context.task_id,
                            "parent_task_id": parent_task_id,
                            "worker_id": runtime_context.worker_id,
                            "worker_slot_id": (
                                runtime_context.worker_slot_id
                                or runtime_context.worker_id
                            ),
                            "target_project_root": target_project_root,
                            "session_token_ref": session_token_ref,
                            "fence_token_hash": fence_token_hash,
                        }
                    )
                    canonical_payload = {
                        "runtime_context_id": runtime_context_id,
                        "task_id": runtime_context.task_id,
                        "parent_task_id": parent_task_id,
                        "worker_role": "mf_sub",
                        "worker_id": runtime_context.worker_id,
                        "worker_slot_id": (
                            runtime_context.worker_slot_id
                            or runtime_context.worker_id
                        ),
                        "target_project_root": target_project_root,
                        "session_token_ref": session_token_ref,
                        "fence_token_hash": fence_token_hash,
                        "graph_trace_ids": [graph_trace_id],
                        "graph_query_trace_ids": [graph_trace_id],
                        "graph_trace_evidence": {
                            "db_verified": True,
                            "graph_trace_ids": [graph_trace_id],
                            "trace_status": canonical_graph_gate.get(
                                "trace_status"
                            ),
                            "trace_complete": canonical_graph_gate.get(
                                "trace_complete"
                            ),
                            "snapshot_id": canonical_graph_gate.get(
                                "snapshot_id"
                            ),
                            "snapshot_commit": canonical_graph_gate.get(
                                "snapshot_commit"
                            ),
                            "expected_active_snapshot_id": (
                                canonical_graph_gate.get(
                                    "expected_active_snapshot_id"
                                )
                            ),
                            "expected_active_graph_commit": (
                                canonical_graph_gate.get(
                                    "expected_active_graph_commit"
                                )
                            ),
                            "expected_runtime_context_commit": (
                                canonical_graph_gate.get(
                                    "expected_runtime_context_commit"
                                )
                            ),
                            "expected_runtime_context_commit_source": (
                                canonical_graph_gate.get(
                                    "expected_runtime_context_commit_source"
                                )
                            ),
                            "query_source": "mf_subagent",
                            "query_purpose": str(
                                body.get("query_purpose") or ""
                            ),
                            "runtime_context_id": runtime_context_id,
                            "task_id": runtime_context.task_id,
                            "parent_task_id": parent_task_id,
                        },
                        "db_verified": True,
                        "query_source": "mf_subagent",
                        "query_purpose": str(
                            body.get("query_purpose") or ""
                        ),
                        "worker_evidence_provenance": worker_provenance,
                        "observer_impersonation": False,
                        "raw_session_token_persisted": False,
                        "raw_fence_token_persisted": False,
                        **{
                            key: value
                            for key, value in route_identity.items()
                            if value
                        },
                    }
                    canonical_line = (
                        _runtime_context_submit_canonical_contract_line(
                            conn,
                            project_id=project_id,
                            context=runtime_context,
                            stage_id="worker_context",
                            line_id="worker_graph_context",
                            evidence_kind="graph_trace",
                            payload=canonical_payload,
                            completed_graph_query_read_only=True,
                        )
                    )
                    result["contract_runtime_canonical_line"] = canonical_line
                conn.commit()
            if str(body.get("query_source") or "") == "mf_subagent":
                return _runtime_context_server_bounded_mf_sub_graph_query_response(
                    result
                )
            return result
        except (KeyError, ValueError) as exc:
            _raise_graph_api_validation(exc)
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/query-traces/{trace_id}/finish")
def handle_graph_governance_query_trace_finish(ctx: RequestContext):
    """Finish an audited graph query trace."""
    project_id = ctx.get_project_id()
    trace_id = ctx.path_params["trace_id"]
    body = ctx.body
    from . import graph_query_trace
    from .db import sqlite_write_lock

    conn = get_connection(project_id)
    try:
        try:
            with sqlite_write_lock():
                existing = graph_query_trace.get_trace(conn, project_id, trace_id)["trace"]
                _require_graph_query_trace_capability(
                    ctx,
                    conn,
                    existing,
                    "graph-governance.query-trace.finish",
                )
                result = graph_query_trace.finish_trace(
                    conn,
                    project_id,
                    trace_id,
                    status=str(body.get("status") or "complete"),
                    reason=str(body.get("reason") or ""),
                )
                conn.commit()
            return result
        except (KeyError, ValueError) as exc:
            _raise_graph_api_validation(exc)
    finally:
        conn.close()


