@route("POST", "/api/graph-governance/{project_id}/snapshots/{snapshot_id}/export-cache")
def handle_graph_governance_snapshot_export_cache(ctx: RequestContext):
    """Export a non-authoritative .aming-claw/cache graph.current.json."""
    project_id = ctx.get_project_id()
    raw_snapshot_id = ctx.path_params["snapshot_id"]
    body = ctx.body
    root = _graph_governance_project_root(project_id, body)
    from . import graph_snapshot_store as store

    cache_dir = body.get("cache_dir") or None
    if _runtime_plane() == "dev":
        dedicated_cache = _dev_runtime_artifact_directory(
            "cache", "graph", project_id
        )
        if cache_dir and Path(str(cache_dir)).expanduser().resolve() != dedicated_cache:
            raise ValidationError(
                "AC dev graph cache must stay under its dedicated runtime root"
            )
        cache_dir = dedicated_cache

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.snapshot.export-cache")
        snapshot_id = _resolve_graph_snapshot_id(conn, project_id, raw_snapshot_id)
        try:
            result = store.export_graph_snapshot_cache(
                conn,
                project_id,
                snapshot_id,
                project_root=root,
                cache_dir=cache_dir,
            )
        except (KeyError, ValueError) as exc:
            _raise_graph_api_validation(exc)
        return 201, {"ok": True, **result}
    finally:
        conn.close()


@route("GET", "/api/graph-governance/{project_id}/drift")
def handle_graph_governance_drift_list(ctx: RequestContext):
    """List graph drift ledger rows for dashboard/operator review."""
    project_id = ctx.get_project_id()
    from . import graph_snapshot_store as store

    conn = get_connection(project_id)
    try:
        status_payload = store.graph_governance_status(conn, project_id)
        raw_snapshot_id = str(ctx.query.get("snapshot_id") or "")
        snapshot_id = _resolve_graph_snapshot_id(conn, project_id, raw_snapshot_id) if raw_snapshot_id else ""
        rows = store.list_graph_drift(
            conn,
            project_id,
            snapshot_id=snapshot_id,
            status=str(ctx.query.get("status") or ""),
            drift_type=str(ctx.query.get("drift_type") or ""),
            limit=_query_int(ctx.query, "limit", 200),
            offset=_query_int(ctx.query, "offset", 0),
        )
        resolved_snapshot_id = snapshot_id or str(status_payload.get("active_snapshot_id") or "")
        current_state = _dashboard_current_state(
            conn,
            project_id,
            status=status_payload,
            snapshot_id=resolved_snapshot_id,
        )
        return {
            "ok": True,
            "project_id": project_id,
            "snapshot_id": resolved_snapshot_id,
            "drift": rows,
            "count": len(rows),
            "ledger_count": len(rows),
            "ledger_only": True,
            "current_state": current_state,
            "graph_stale": current_state["graph_stale"],
            "semantic_drift": current_state["semantic_drift"],
            "note": "drift rows are explicit graph_drift_ledger entries; use current_state.graph_stale and current_state.semantic_drift for synthesized dashboard drift.",
        }
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/drift")
def handle_graph_governance_drift_record(ctx: RequestContext):
    """Record one graph drift row with evidence."""
    project_id = ctx.get_project_id()
    body = ctx.body
    required = ["snapshot_id", "commit_sha", "path", "drift_type"]
    missing = [key for key in required if not str(body.get(key) or "").strip()]
    if missing:
        from .errors import ValidationError
        raise ValidationError(f"missing required drift field(s): {', '.join(missing)}")
    from . import graph_snapshot_store as store
    from .db import sqlite_write_lock

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.drift.record")
        with sqlite_write_lock():
            store.record_drift(
                conn,
                project_id,
                snapshot_id=str(body.get("snapshot_id") or ""),
                commit_sha=str(body.get("commit_sha") or ""),
                path=str(body.get("path") or ""),
                drift_type=str(body.get("drift_type") or ""),
                target_symbol=str(body.get("target_symbol") or ""),
                node_id=str(body.get("node_id") or ""),
                status=str(body.get("status") or "open"),
                evidence=body.get("evidence") if isinstance(body.get("evidence"), dict) else {
                    "source": "graph_governance_api",
                    "actor": body.get("actor", "api"),
                },
            )
            conn.commit()
        row = store.list_graph_drift(
            conn,
            project_id,
            snapshot_id=str(body.get("snapshot_id") or ""),
            drift_type=str(body.get("drift_type") or ""),
            status=str(body.get("status") or "open"),
            limit=20,
        )
        return 201, {"ok": True, "project_id": project_id, "drift": row}
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/drift/file-backlog")
def handle_graph_governance_drift_file_backlog(ctx: RequestContext):
    """File one graph drift row into backlog and mark it backlog_filed."""
    project_id = ctx.get_project_id()
    body = ctx.body
    required = ["snapshot_id", "path", "drift_type"]
    missing = [key for key in required if not str(body.get(key) or "").strip()]
    if missing:
        from .errors import ValidationError
        raise ValidationError(f"missing required drift field(s): {', '.join(missing)}")
    from . import graph_snapshot_store as store
    from .db import sqlite_write_lock

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.drift.file-backlog")
        with sqlite_write_lock():
            snapshot_id = _resolve_graph_snapshot_id(conn, project_id, str(body.get("snapshot_id") or ""))
            target_symbol_raw = body.get("target_symbol")
            target_symbol = None if target_symbol_raw is None else str(target_symbol_raw)
            try:
                drift = store.get_graph_drift(
                    conn,
                    project_id,
                    snapshot_id=snapshot_id,
                    path=str(body.get("path") or ""),
                    drift_type=str(body.get("drift_type") or ""),
                    target_symbol=target_symbol,
                )
            except (KeyError, ValueError) as exc:
                _raise_graph_api_validation(exc)

            bug_id = str(body.get("bug_id") or "").strip() or _graph_drift_backlog_id(
                snapshot_id,
                drift["path"],
                drift["drift_type"],
                drift["target_symbol"],
            )
            now = _utc_now()
            actor = str(body.get("actor") or "graph_governance_api")
            title = str(body.get("title") or "").strip() or (
                f"Resolve graph drift: {drift['drift_type']} in {drift['path']}"
            )
            details_md = str(body.get("details_md") or "").strip()
            if not details_md:
                details_md = "\n".join([
                    f"Graph drift row filed from snapshot `{snapshot_id}`.",
                    "",
                    f"- path: `{drift['path']}`",
                    f"- drift_type: `{drift['drift_type']}`",
                    f"- node_id: `{drift['node_id']}`",
                    f"- target_symbol: `{drift['target_symbol']}`",
                    f"- commit: `{drift['commit_sha']}`",
                    "",
                    "Review the graph/drift evidence, then either repair through chain or explicitly waive.",
                ])
            acceptance = body.get("acceptance_criteria")
            if not isinstance(acceptance, list):
                acceptance = [
                    "Drift row is fixed, waived, or converted into a more precise graph/document/test task.",
                    "Backlog close evidence references the graph snapshot and affected path.",
                    "Update graph runs current full reconcile after any merge.",
                ]
            priority = str(body.get("priority") or "P2")
            target_files = body.get("target_files") if isinstance(body.get("target_files"), list) else [drift["path"]]
            conn.execute(
                """INSERT INTO backlog_bugs
                   (bug_id, title, status, priority, target_files, test_files,
                    acceptance_criteria, chain_task_id, "commit", discovered_at,
                    fixed_at, details_md, chain_trigger_json, required_docs,
                    provenance_paths, bypass_policy_json, mf_type, takeover_json,
                    created_at, updated_at)
                   VALUES (?, ?, 'OPEN', ?, ?, ?, ?, '', ?, ?, '', ?, ?, ?, ?, '{}', '', '{}', ?, ?)
                   ON CONFLICT(bug_id) DO UPDATE SET
                     title = excluded.title,
                     status = 'OPEN',
                     priority = excluded.priority,
                     target_files = excluded.target_files,
                     acceptance_criteria = excluded.acceptance_criteria,
                     details_md = excluded.details_md,
                     chain_trigger_json = excluded.chain_trigger_json,
                     provenance_paths = excluded.provenance_paths,
                     updated_at = excluded.updated_at
                """,
                (
                    bug_id,
                    title,
                    priority,
                    json.dumps(target_files, ensure_ascii=False, sort_keys=True),
                    json.dumps(body.get("test_files") if isinstance(body.get("test_files"), list) else [], ensure_ascii=False),
                    json.dumps(acceptance, ensure_ascii=False, sort_keys=True),
                    drift["commit_sha"],
                    now,
                    details_md,
                    json.dumps({
                        "source": "graph_drift_ledger",
                        "snapshot_id": snapshot_id,
                        "drift_type": drift["drift_type"],
                        "graph_gate_mode": "advisory",
                    }, ensure_ascii=False, sort_keys=True),
                    json.dumps(body.get("required_docs") if isinstance(body.get("required_docs"), list) else [], ensure_ascii=False),
                    json.dumps([drift["path"], f"graph_snapshot:{snapshot_id}"], ensure_ascii=False, sort_keys=True),
                    now,
                    now,
                ),
            )
            filed = store.update_graph_drift_status(
                conn,
                project_id,
                snapshot_id=snapshot_id,
                path=drift["path"],
                drift_type=drift["drift_type"],
                target_symbol=drift["target_symbol"],
                status="backlog_filed",
                evidence={
                    "backlog_bug_id": bug_id,
                    "filed_by": actor,
                    "filed_at": now,
                },
            )
            try:
                audit_service.record(
                    conn,
                    project_id,
                    "graph_drift_backlog_filed",
                    actor=actor,
                    bug_id=bug_id,
                    details=json.dumps({
                        "snapshot_id": snapshot_id,
                        "path": drift["path"],
                        "drift_type": drift["drift_type"],
                        "target_symbol": drift["target_symbol"],
                    }, ensure_ascii=False, sort_keys=True),
                )
            except Exception:
                pass
            conn.commit()
        return 201, {
            "ok": True,
            "project_id": project_id,
            "bug_id": bug_id,
            "drift": filed,
        }
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/pending-scope")
def handle_graph_governance_pending_scope_queue(ctx: RequestContext):
    """Queue or update one pending scope-reconcile row."""
    project_id = ctx.get_project_id()
    body = ctx.body
    commit_sha = str(body.get("commit_sha") or body.get("target_commit_sha") or "").strip()
    if not commit_sha:
        from .errors import ValidationError
        raise ValidationError("commit_sha is required")
    from . import graph_snapshot_store as store
    from .db import sqlite_write_lock
    identity = _pending_scope_identity_from_body(body)

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.pending-scope")
        with sqlite_write_lock():
            try:
                row = store.queue_pending_scope_reconcile(
                    conn,
                    project_id,
                    commit_sha=commit_sha,
                    parent_commit_sha=str(body.get("parent_commit_sha") or ""),
                    ref_name=identity["ref_name"],
                    branch_ref=identity["branch_ref"],
                    worktree_id=identity["worktree_id"],
                    worktree_path=identity["worktree_path"],
                    status=str(body.get("status") or store.PENDING_STATUS_QUEUED),
                    snapshot_id=str(body.get("snapshot_id") or ""),
                    evidence=body.get("evidence") if isinstance(body.get("evidence"), dict) else {
                        "source": "graph_governance_api",
                        "actor": body.get("actor", "api"),
                        **identity,
                    },
                    force_requeue=_query_bool(body, "force_requeue", False),
                )
            except ValueError as exc:
                _raise_graph_api_validation(exc)
            conn.commit()
        return 201, {"ok": True, "project_id": project_id, "pending_scope_reconcile": row}
    finally:
        conn.close()


def _contract_timeline_scope_from_graph_body(body: Mapping[str, Any]) -> dict[str, str]:
    evidence = body.get("evidence") if isinstance(body.get("evidence"), Mapping) else {}
    backlog_id = str(
        body.get("backlog_id")
        or body.get("bug_id")
        or evidence.get("backlog_id")
        or evidence.get("bug_id")
        or evidence.get("parent_task_id")
        or ""
    ).strip()
    task_id = str(
        body.get("task_id")
        or body.get("contract_execution_id")
        or evidence.get("task_id")
        or evidence.get("parent_task_id")
        or backlog_id
        or ""
    ).strip()
    actor = str(
        body.get("contract_actor")
        or evidence.get("contract_actor")
        or "codex-observer"
    ).strip()
    return {
        "backlog_id": backlog_id,
        "task_id": task_id or backlog_id,
        "actor": actor,
    }


def _current_full_reconcile_batch_no_pass_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    target_commit_sha: str,
    exception_row: Any,
) -> dict[str, Any]:
    """Revalidate a consumed Batch recovery for one current-full reconcile."""

    from . import task_timeline
    from .parallel_branch_runtime import (
        AUDITED_POSTMERGE_RECOVERY_MODE,
        get_merge_queue_item,
    )

    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    merge_queue_id = str(
        getattr(context, "merge_queue_id", "") or ""
    ).strip()
    target_commit = str(target_commit_sha or "").strip().lower()
    exception_payload = _json_loads(
        _row_get(exception_row, "payload_json", "{}"),
        {},
    )
    exception_verification = _json_loads(
        _row_get(exception_row, "verification_json", "{}"),
        {},
    )
    if not isinstance(exception_payload, Mapping) or not isinstance(
        exception_verification,
        Mapping,
    ):
        return {}
    qa_ref = str(
        exception_payload.get("independent_qa_receipt_ref") or ""
    ).strip()
    live_ref = str(
        exception_payload.get("durable_merge_event_ref") or ""
    ).strip()
    diagnostic_id = str(
        exception_payload.get("diagnostic_backlog_id") or ""
    ).strip()
    generation_id = str(
        exception_payload.get("no_pass_generation_id") or ""
    ).strip()
    qa_event_id = _audited_postmerge_recovery_ref_id(qa_ref)
    live_event_id = _audited_postmerge_recovery_ref_id(live_ref)
    exception_id = int(_row_get(exception_row, "id", 0) or 0)
    exception_gate_authority = exception_payload.get(
        "source_backed_contract_gate_authority"
    )
    exception_gate = (
        exception_gate_authority.get("route_token_gate")
        if isinstance(exception_gate_authority, Mapping)
        and isinstance(
            exception_gate_authority.get("route_token_gate"),
            Mapping,
        )
        else {}
    )
    exception_scope = (
        exception_gate.get("scope")
        if isinstance(exception_gate.get("scope"), Mapping)
        else {}
    )
    if not all(
        (
            execution_id,
            backlog_id,
            runtime_context_id,
            task_id,
            parent_task_id == execution_id,
            merge_queue_id,
            qa_event_id,
            live_event_id,
            diagnostic_id,
            re.fullmatch(r"bypassgen-[0-9a-z]+", generation_id),
            re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", target_commit),
            exception_id > 0,
            str(_row_get(exception_row, "backlog_id", "") or "")
            == backlog_id,
            str(_row_get(exception_row, "task_id", "") or "") == task_id,
            str(_row_get(exception_row, "event_type", "") or "")
            == "graph_reconcile.contract_merge_authority_projection_blocked",
            str(_row_get(exception_row, "event_kind", "") or "")
            == "blocker",
            str(_row_get(exception_row, "phase", "") or "")
            == "post_merge_reconcile",
            str(_row_get(exception_row, "actor", "") or "") == "observer",
            str(_row_get(exception_row, "status", "") or "")
            == "proceeded_with_exception",
            str(_row_get(exception_row, "decision", "") or "")
            == "audited_system_route_bypass_no_pass",
            str(_row_get(exception_row, "commit_sha", "") or "").lower()
            == target_commit,
            str(exception_payload.get("merged_commit") or "").lower()
            == target_commit,
            str(exception_payload.get("source_contract_execution_id") or "")
            == execution_id,
            str(exception_payload.get("durable_merge_queue_id") or "")
            == merge_queue_id,
            exception_payload.get("system_reconcile_authority_bypassed")
            is True,
            exception_payload.get("business_qa_bypassed") is False,
            exception_payload.get("authoritative_pass_synthesized") is False,
            exception_payload.get("rejected_requests_created_snapshot")
            is False,
            exception_payload.get("actual_reconcile_count_before_bypass")
            == 0,
            str(exception_payload.get("allowed_bypass_operation") or "")
            == "one_current_full_reconcile_and_activation",
            str(exception_payload.get("classification") or "")
            == "stale_contract_runtime_missing_durable_merge_projection",
            str(exception_payload.get("diagnostic_status") or "") == "OPEN",
            exception_verification.get("no_pass_claim") is True,
            exception_verification.get("ordered_merge_complete") is True,
            exception_verification.get("main_tests_passed") is True,
            exception_verification.get("preflight_only_no_snapshot") is True,
            exception_verification.get("final_reconcile_still_required")
            is True,
            isinstance(exception_gate_authority, Mapping),
            task_timeline._source_backed_route_gate_authority_valid(
                exception_gate_authority
            ),
            str(exception_scope.get("project_id") or "") == project_id,
            str(exception_scope.get("backlog_id") or "") == backlog_id,
            str(exception_scope.get("task_id") or "") == task_id,
            str(exception_gate.get("action") or "") == "merge_execute",
            str(exception_gate.get("authorized_action") or "")
            == _PARALLEL_BRANCH_PARENT_ROUTE_MERGE_ACTION,
            exception_gate.get("child_task_scope_accepted") is True,
            str(exception_gate.get("accepted_task_scope") or "") == "child",
            str(exception_gate.get("child_task_id") or "") == task_id,
        )
    ):
        return {}

    referenced_rows = conn.execute(
        """
        SELECT id, backlog_id, task_id, event_type, event_kind, phase, actor,
               status, decision, correlation_id, commit_sha, created_at,
               payload_json, verification_json, artifact_refs_json
        FROM task_timeline_events
        WHERE project_id = ? AND id IN (?, ?)
        """,
        (project_id, qa_event_id, live_event_id),
    ).fetchall()
    by_id = {
        int(_row_get(row, "id", 0) or 0): row
        for row in referenced_rows
    }
    qa_row = by_id.get(qa_event_id)
    live_row = by_id.get(live_event_id)
    if qa_row is None or live_row is None:
        return {}
    qa_payload = _json_loads(qa_row["payload_json"], {})
    qa_verification = _json_loads(qa_row["verification_json"], {})
    live_payload = _json_loads(live_row["payload_json"], {})
    if not all(
        isinstance(value, Mapping)
        for value in (qa_payload, qa_verification, live_payload)
    ):
        return {}
    stored_authority = live_payload.get(
        "audited_postmerge_recovery_authority"
    )
    if not isinstance(stored_authority, Mapping):
        return {}
    stored_core = dict(stored_authority)
    stored_hash = str(stored_core.pop("authority_hash", "") or "")
    manual_ref = str(
        stored_authority.get("manual_merge_event_ref") or ""
    ).strip()
    manual_event_id = _audited_postmerge_recovery_ref_id(manual_ref)
    queue_item_id = str(live_payload.get("queue_item_id") or "").strip()
    live_gate = (
        live_payload.get("route_token_gate")
        if isinstance(live_payload.get("route_token_gate"), Mapping)
        else {}
    )
    live_scope = (
        live_gate.get("scope")
        if isinstance(live_gate.get("scope"), Mapping)
        else {}
    )
    if not all(
        (
            manual_event_id,
            queue_item_id,
            stored_hash == stable_sha256(stored_core),
            str(stored_authority.get("schema_version") or "")
            == "parallel_branch.audited_postmerge_recovery_authority.v1",
            str(stored_authority.get("project_id") or "") == project_id,
            str(stored_authority.get("backlog_id") or "") == backlog_id,
            str(stored_authority.get("task_id") or "") == task_id,
            str(stored_authority.get("parent_task_id") or "")
            == execution_id,
            str(stored_authority.get("runtime_context_id") or "")
            == runtime_context_id,
            str(stored_authority.get("merge_queue_id") or "")
            == merge_queue_id,
            str(stored_authority.get("merged_commit") or "").lower()
            == target_commit,
            str(stored_authority.get("qa_receipt_ref") or "") == qa_ref,
            str(stored_authority.get("diagnostic_backlog_id") or "")
            == diagnostic_id,
            str(stored_authority.get("no_pass_generation_id") or "")
            == generation_id,
            stored_authority.get("no_pass_claim") is True,
            stored_authority.get("authoritative_pass_synthesized") is False,
            stored_authority.get("business_qa_bypassed") is False,
            stored_authority.get("rejected_preflights_created_snapshot")
            is False,
            str(_row_get(live_row, "backlog_id", "") or "") == backlog_id,
            str(_row_get(live_row, "task_id", "") or "") == task_id,
            str(_row_get(live_row, "event_type", "") or "")
            == "parallel.live_merge_postmerge_recovery",
            str(_row_get(live_row, "event_kind", "") or "")
            == "live_merge",
            str(_row_get(live_row, "phase", "") or "") == "live_merge",
            str(_row_get(live_row, "actor", "") or "") == "observer",
            str(_row_get(live_row, "status", "") or "")
            == "proceeded_with_exception",
            str(_row_get(live_row, "decision", "") or "")
            == "audited_postmerge_durable_merge_projection_no_pass",
            str(_row_get(live_row, "commit_sha", "") or "").lower()
            == target_commit,
            str(live_payload.get("parent_task_id") or "") == execution_id,
            str(live_payload.get("child_task_id") or "") == task_id,
            str(live_payload.get("merge_queue_id") or "") == merge_queue_id,
            str(live_payload.get("merge_commit") or "").lower()
            == target_commit,
            str(live_payload.get("target_head_after_merge") or "").lower()
            == target_commit,
            str(live_payload.get("no_pass_generation_id") or "")
            == generation_id,
            live_payload.get("no_pass_claim") is True,
            live_payload.get("authoritative_pass_synthesized") is False,
            live_payload.get("business_qa_bypassed") is False,
            task_timeline._source_backed_route_gate_accepted(live_gate),
            str(live_scope.get("project_id") or "") == project_id,
            str(live_scope.get("backlog_id") or "") == backlog_id,
            str(live_scope.get("task_id") or "") == task_id,
            str(live_gate.get("action") or "") == "merge_execute",
            str(live_gate.get("authorized_action") or "")
            == _PARALLEL_BRANCH_PARENT_ROUTE_MERGE_ACTION,
            live_gate.get("child_task_scope_accepted") is True,
            str(live_gate.get("accepted_task_scope") or "") == "child",
            str(live_gate.get("child_task_id") or "") == task_id,
        )
    ):
        return {}

    manual_row = conn.execute(
        """
        SELECT id, backlog_id, task_id, event_type, event_kind, phase, actor,
               status, decision, correlation_id, commit_sha, created_at,
               payload_json, verification_json
        FROM task_timeline_events
        WHERE project_id = ? AND id = ?
        """,
        (project_id, manual_event_id),
    ).fetchone()
    if manual_row is None:
        return {}
    manual_payload = _json_loads(manual_row["payload_json"], {})
    manual_verification = _json_loads(manual_row["verification_json"], {})
    if not isinstance(manual_payload, Mapping) or not isinstance(
        manual_verification,
        Mapping,
    ):
        return {}
    try:
        derived = _audited_postmerge_recovery_batch_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            merge_queue_id=merge_queue_id,
            runtime_context_id=runtime_context_id,
            execution_id=execution_id,
            qa_ref=qa_ref,
            merge_ref=manual_ref,
            diagnostic_id=diagnostic_id,
            context=context,
            qa_row=qa_row,
            qa_payload=qa_payload,
            qa_verification=qa_verification,
            merge_row=manual_row,
            merge_payload=manual_payload,
            merge_verification=manual_verification,
            require_unconsumed=False,
        )
    except GovernanceError:
        return {}
    derived_payload = asdict(derived)
    if not (
        derived_payload == dict(stored_authority)
        and derived.authority_hash == stored_hash
        and derived.no_pass_generation_id == generation_id
    ):
        return {}

    materialized = _parallel_branch_postmerge_recovery_materialize_authority(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
        merge_queue_id=merge_queue_id,
        queue_item_id=queue_item_id,
    )
    queue_item = get_merge_queue_item(
        conn,
        project_id,
        merge_queue_id,
        queue_item_id,
    )
    if not (
        materialized == dict(stored_authority)
        and queue_item is not None
        and str(queue_item.recovery_mode or "")
        == AUDITED_POSTMERGE_RECOVERY_MODE
        and str(queue_item.recovery_authority_hash or "") == stored_hash
        and str(queue_item.status or "") == "merged"
        and str(queue_item.backlog_id or "") == backlog_id
        and str(queue_item.task_id or "") == task_id
        and str(queue_item.branch_head or "").lower()
        == derived.candidate_commit
        and str(queue_item.merge_commit or "").lower() == target_commit
        and str(queue_item.target_head_after_merge or "").lower()
        == target_commit
    ):
        return {}

    diagnostic = conn.execute(
        """
        SELECT status, bypass_policy_json, chain_trigger_json, provenance_paths
        FROM backlog_bugs WHERE bug_id = ?
        """,
        (diagnostic_id,),
    ).fetchone()
    policy = _json_loads(diagnostic["bypass_policy_json"], {}) if diagnostic else {}
    trigger = _json_loads(diagnostic["chain_trigger_json"], {}) if diagnostic else {}
    provenance = _json_loads(diagnostic["provenance_paths"], []) if diagnostic else []
    required_refs = {
        qa_ref,
        manual_ref,
        live_ref,
        f"timeline:{exception_id}",
        f"contract-runtime:{execution_id}",
        f"runtime-context:{runtime_context_id}",
        f"commit:{derived.candidate_commit}",
        f"commit:{target_commit}",
        f"merge:{target_commit}",
        f"no-pass-generation:{generation_id}",
    }
    if not diagnostic or not (
        str(diagnostic["status"] or "") == "OPEN"
        and isinstance(policy, Mapping)
        and policy.get("keep_open") is True
        and policy.get("no_pass_claim") is True
        and policy.get("authoritative_pass_synthesized") is False
        and str(policy.get("source_backlog_id") or "") == backlog_id
        and str(policy.get("contract_execution_id") or "") == execution_id
        and str(policy.get("no_pass_generation_id") or "") == generation_id
        and isinstance(trigger, Mapping)
        and trigger.get("no_pass_claim") is True
        and str(trigger.get("contract_execution_id") or "") == execution_id
        and str(trigger.get("no_pass_generation_id") or "") == generation_id
        and isinstance(provenance, list)
        and required_refs.issubset(set(provenance))
    ):
        return {}

    qa_time = _contract_runtime_close_authority_time_order_value(
        _row_get(qa_row, "created_at", "")
    )
    manual_time = _contract_runtime_close_authority_time_order_value(
        _row_get(manual_row, "created_at", "")
    )
    live_time = _contract_runtime_close_authority_time_order_value(
        _row_get(live_row, "created_at", "")
    )
    exception_time = _contract_runtime_close_authority_time_order_value(
        _row_get(exception_row, "created_at", "")
    )
    if not (
        qa_time is not None
        and manual_time is not None
        and live_time is not None
        and exception_time is not None
        and qa_time <= manual_time <= live_time <= exception_time
        and live_event_id < exception_id
    ):
        return {}
    consumed = conn.execute(
        """
        SELECT 1 FROM task_timeline_events
        WHERE project_id = ? AND backlog_id IN (?, ?)
          AND event_type = 'graph.reconcile'
          AND status IN ('accepted', 'ok', 'passed', 'succeeded')
          AND lower(commit_sha) = ? AND created_at > ?
        LIMIT 1
        """,
        (
            project_id,
            diagnostic_id,
            backlog_id,
            target_commit,
            str(_row_get(exception_row, "created_at", "") or ""),
        ),
    ).fetchone()
    if consumed is not None:
        return {}

    qa_authority = qa_payload.get("source_backed_contract_gate_authority")
    qa_proof = (
        qa_authority.get("qa_session_proof")
        if isinstance(qa_authority, Mapping)
        and isinstance(qa_authority.get("qa_session_proof"), Mapping)
        else {}
    )
    return {
        "schema_version": (
            "graph_current_full_reconcile.audited_no_pass_authority.v1"
        ),
        "source": "audited_no_pass_reconcile_exception",
        "authority_mode": "audited_no_pass_reconcile_exception",
        "server_derived": True,
        "db_verified": True,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "merge_queue_id": merge_queue_id,
        "queue_item_id": queue_item_id,
        "candidate_commit_sha": derived.candidate_commit,
        "merged_commit_sha": target_commit,
        "recovery_anchor_commit_sha": target_commit,
        "repair_descendant_commit_shas": [],
        "repair_descendant_verified": False,
        "canonical_base_snapshot_id": str(
            qa_proof.get("snapshot_id") or ""
        ),
        "canonical_base_commit": str(
            qa_proof.get("comparison_base_commit_sha") or ""
        ),
        "candidate_diff_sha256": derived.candidate_diff_sha256,
        "qa_source_ref": qa_ref,
        "qa_event_id": qa_event_id,
        "qa_event_created_at": str(_row_get(qa_row, "created_at", "") or ""),
        "qa_session_id": str(qa_proof.get("qa_session_id") or ""),
        "qa_principal_id": str(qa_proof.get("principal_id") or ""),
        "merge_source_ref": live_ref,
        "merge_event_id": live_event_id,
        "merge_event_created_at": str(
            _row_get(live_row, "created_at", "") or ""
        ),
        "exception_source_ref": f"timeline:{exception_id}",
        "exception_event_id": exception_id,
        "exception_event_created_at": str(
            _row_get(exception_row, "created_at", "") or ""
        ),
        "diagnostic_backlog_id": diagnostic_id,
        "no_pass_generation_id": generation_id,
        "qa_contract_runtime_verified": False,
        "ordinary_close_authority": False,
        "durable_recovery_marker_verified": True,
        "business_qa_bypassed": False,
        "system_gate_bypass_only": True,
        "authoritative_pass_synthesized": False,
        "no_pass_claim": True,
        "one_shot": True,
    }


def _current_full_reconcile_audited_no_pass_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    target_commit_sha: str,
) -> dict[str, Any]:
    """Verify a one-shot system-only reconcile exception.

    This is deliberately weaker than ContractRuntime QA/close authority and is
    usable only by the current-full post-merge reconcile gate.  It preserves a
    real independent business-QA receipt when historical graph trace
    materialization was blocked, but it never upgrades that receipt to an
    authoritative ContractRuntime PASS or ordinary close evidence.
    """

    from . import task_timeline

    execution_id = str(record.get("contract_execution_id") or "").strip()
    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    merge_queue_id = str(
        getattr(context, "merge_queue_id", "") or ""
    ).strip()
    target_commit = str(target_commit_sha or "").strip().lower()
    if not (
        execution_id
        and runtime_context_id
        and task_id
        and parent_task_id == execution_id
        and backlog_id
        and merge_queue_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", target_commit)
    ):
        return {}

    def _row_text(row: Any, key: str) -> str:
        try:
            return str(row[key] or "").strip()
        except (KeyError, TypeError, IndexError):
            return ""

    def _row_int(row: Any, key: str) -> int:
        try:
            return int(row[key] or 0)
        except (KeyError, TypeError, ValueError, IndexError):
            return 0

    def _value_int(value: Any, default: int = -1) -> int:
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    def _json_mapping(raw: Any) -> dict[str, Any]:
        parsed = _json_loads(raw, {})
        return dict(parsed) if isinstance(parsed, Mapping) else {}

    def _timeline_ref_id(value: Any) -> int:
        match = re.fullmatch(r"timeline:(\d+)", str(value or "").strip())
        return int(match.group(1)) if match else 0

    def _route_gate_scope_matches(
        payload: Mapping[str, Any],
        *,
        expected_task_id: str,
        require_authority_envelope: bool,
    ) -> bool:
        authority = payload.get("source_backed_contract_gate_authority")
        if require_authority_envelope:
            if not isinstance(authority, Mapping) or not (
                task_timeline._source_backed_route_gate_authority_valid(
                    authority
                )
            ):
                return False
            gate = authority.get("route_token_gate")
        else:
            gate = payload.get("route_token_gate")
        if not isinstance(gate, Mapping):
            return False
        gate_accepted = task_timeline._source_backed_route_gate_accepted(
            gate
        )
        if not gate_accepted:
            gate_status = str(
                gate.get("status") or gate.get("decision") or ""
            ).strip()
            gate_accepted = bool(
                gate.get("allowed") is True
                and gate_status in {
                    "accepted",
                    "ok",
                    "passed",
                    "route_token_ref_resolved",
                }
                and str(gate.get("action") or "") == "merge_execute"
                and str(gate.get("authorized_action") or "")
                == _PARALLEL_BRANCH_PARENT_ROUTE_MERGE_ACTION
                and gate.get("child_task_scope_accepted") is True
                and str(gate.get("accepted_task_scope") or "") == "child"
                and str(gate.get("child_task_id") or "")
                == expected_task_id
                and str(gate.get("backlog_id") or "") == backlog_id
                and gate.get("registry_verified") is True
                and gate.get("resolved_from_ref") is True
                and gate.get("server_issued_binding") is True
                and str(gate.get("binding_source") or "")
                == "observer_route_token_refs"
            )
        if not gate_accepted:
            return False
        scope = gate.get("scope")
        if not isinstance(scope, Mapping):
            return False
        return all(
            str(scope.get(field) or "").strip() == expected
            for field, expected in (
                ("project_id", project_id),
                ("backlog_id", backlog_id),
                ("task_id", expected_task_id),
            )
        )

    try:
        exception_rows = conn.execute(
            """
            SELECT id, backlog_id, task_id, event_type, event_kind, phase,
                   actor, status, decision, correlation_id, commit_sha,
                   created_at, payload_json, verification_json,
                   artifact_refs_json
            FROM task_timeline_events
            WHERE project_id = ? AND backlog_id = ?
              AND event_type = ? AND status = ? AND decision = ?
            ORDER BY id ASC
            LIMIT 100
            """,
            (
                project_id,
                backlog_id,
                "graph_reconcile.contract_merge_authority_projection_blocked",
                "proceeded_with_exception",
                "audited_system_route_bypass_no_pass",
            ),
        ).fetchall()
    except sqlite3.Error:
        return {}

    candidates: list[dict[str, Any]] = []
    for exception_row in exception_rows:
        exception_id = _row_int(exception_row, "id")
        exception_payload = _json_mapping(exception_row["payload_json"])
        exception_verification = _json_mapping(
            exception_row["verification_json"]
        )
        batch_authority = _current_full_reconcile_batch_no_pass_authority(
            conn,
            project_id=project_id,
            record=record,
            context=context,
            target_commit_sha=target_commit,
            exception_row=exception_row,
        )
        if batch_authority:
            candidates.append(batch_authority)
            continue
        exception_merge_commit = str(
            exception_payload.get("merged_commit") or ""
        ).strip().lower()
        if not (
            exception_id > 0
            and _row_text(exception_row, "task_id") == task_id
            and _row_text(exception_row, "event_kind") == "blocker"
            and _row_text(exception_row, "phase") == "post_merge_reconcile"
            and _row_text(exception_row, "actor") == "observer"
            and re.fullmatch(
                r"[0-9a-f]{40}|[0-9a-f]{64}",
                exception_merge_commit,
            )
            and _row_text(exception_row, "commit_sha").lower()
            == exception_merge_commit
            and exception_payload.get("system_reconcile_authority_bypassed")
            is True
            and exception_payload.get("business_qa_bypassed") is False
            and exception_payload.get("authoritative_pass_synthesized")
            is False
            and exception_payload.get("rejected_requests_created_snapshot")
            is False
            and _value_int(
                exception_payload.get("actual_reconcile_count_before_bypass")
            )
            == 0
            and str(exception_payload.get("classification") or "")
            == "stale_contract_runtime_missing_durable_merge_projection"
            and str(exception_payload.get("allowed_bypass_operation") or "")
            == "one_current_full_reconcile_and_activation"
            and str(exception_payload.get("source_contract_execution_id") or "")
            == execution_id
            and str(exception_payload.get("durable_merge_queue_id") or "")
            == merge_queue_id
            and exception_verification.get("no_pass_claim") is True
            and exception_verification.get("ordered_merge_complete") is True
            and exception_verification.get("main_tests_passed") is True
            and exception_verification.get("preflight_only_no_snapshot")
            is True
            and exception_verification.get("final_reconcile_still_required")
            is True
            and _route_gate_scope_matches(
                exception_payload,
                expected_task_id=task_id,
                require_authority_envelope=True,
            )
        ):
            continue

        qa_event_id = _timeline_ref_id(
            exception_payload.get("independent_qa_receipt_ref")
        )
        merge_event_id = _timeline_ref_id(
            exception_payload.get("durable_merge_event_ref")
        )
        diagnostic_id = str(
            exception_payload.get("diagnostic_backlog_id") or ""
        ).strip()
        if not qa_event_id or not merge_event_id or not diagnostic_id:
            continue
        try:
            referenced_rows = conn.execute(
                """
                SELECT id, backlog_id, task_id, event_type, event_kind, phase,
                       actor, status, decision, correlation_id, commit_sha,
                       created_at, payload_json, verification_json,
                       artifact_refs_json
                FROM task_timeline_events
                WHERE project_id = ? AND id IN (?, ?)
                """,
                (project_id, qa_event_id, merge_event_id),
            ).fetchall()
        except sqlite3.Error:
            continue
        rows_by_id = {
            _row_int(row, "id"): row
            for row in referenced_rows
            if _row_int(row, "id") > 0
        }
        qa_row = rows_by_id.get(qa_event_id)
        merge_row = rows_by_id.get(merge_event_id)
        if qa_row is None or merge_row is None:
            continue

        qa_payload = _json_mapping(qa_row["payload_json"])
        qa_verification = _json_mapping(qa_row["verification_json"])
        candidate_commit = _row_text(qa_row, "commit_sha").lower()
        qa_session_id = str(
            qa_payload.get("independent_qa_session_id") or ""
        ).strip()
        qa_principal = str(
            qa_payload.get("independent_qa_principal") or ""
        ).strip()
        diff_sha256 = str(qa_payload.get("diff_sha256") or "").strip()
        baseline_snapshot_id = str(
            qa_payload.get("canonical_base_snapshot_id") or ""
        ).strip()
        baseline_commit = str(
            qa_payload.get("canonical_base_commit") or ""
        ).strip().lower()
        acceptance_count = _value_int(
            qa_verification.get("acceptance_criteria_count")
        )
        if not (
            _row_text(qa_row, "backlog_id") == backlog_id
            and _row_text(qa_row, "task_id") == execution_id
            and _row_text(qa_row, "event_type")
            == "qa.independent_verification_completed_with_governance_exception"
            and _row_text(qa_row, "event_kind") == "blocker"
            and _row_text(qa_row, "phase") == "qa_verification"
            and _row_text(qa_row, "status") == "proceeded_with_exception"
            and _row_text(qa_row, "decision")
            == "business_qa_pass_authoritative_trace_blocked_no_pass"
            and _row_text(qa_row, "actor") == "observer"
            and candidate_commit
            and str(qa_payload.get("candidate_commit") or "").lower()
            == candidate_commit
            and re.fullmatch(r"sha256:[0-9a-f]{64}", diff_sha256)
            and baseline_snapshot_id
            and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", baseline_commit)
            and qa_session_id
            and _row_text(qa_row, "correlation_id") == qa_session_id
            and qa_principal
            and str(qa_payload.get("independent_qa_session_ref") or "").strip()
            and str(qa_payload.get("business_verdict") or "").upper()
            == "PASS"
            and str(
                qa_payload.get("governance_evidence_materialization") or ""
            ).upper()
            == "BLOCKED"
            and qa_payload.get("contract_runtime_authoritative_pass") is False
            and qa_payload.get("business_qa_bypassed") is False
            and qa_payload.get("system_gate_bypass_requested") is True
            and qa_payload.get("reconcile_before_qa") is False
            and qa_payload.get("historical_graph_data_readable") is True
            and not str(qa_payload.get("graph_trace_id") or "").strip()
            and str(qa_payload.get("graph_trace_status") or "")
            == "blocked_by_nonactive_snapshot_gate"
            and acceptance_count > 0
            and _value_int(
                qa_verification.get("acceptance_criteria_passed")
            )
            == acceptance_count
            and qa_verification.get("authoritative_pass_synthesized") is False
            and qa_verification.get("no_pass_claim") is True
            and qa_verification.get("candidate_head_exact") is True
            and qa_verification.get("candidate_worktree_clean") is True
            and qa_verification.get("merge_tree_clean") is True
            and _independent_qa_toolchain_evidence_passed(qa_verification)
            and str(qa_verification.get("git_diff_check") or "") == "passed"
            and str(qa_verification.get("current_main_regression") or "")
            == "passed"
            and _route_gate_scope_matches(
                qa_payload,
                expected_task_id=execution_id,
                require_authority_envelope=True,
            )
        ):
            continue

        try:
            snapshot_row = conn.execute(
                """
                SELECT commit_sha
                FROM graph_snapshots
                WHERE project_id = ? AND snapshot_id = ?
                """,
                (project_id, baseline_snapshot_id),
            ).fetchone()
            qa_session_row = conn.execute(
                """
                SELECT principal_id, project_id, role, scope_json
                FROM sessions
                WHERE session_id = ?
                """,
                (qa_session_id,),
            ).fetchone()
        except sqlite3.Error:
            continue
        if (
            snapshot_row is None
            or _row_text(snapshot_row, "commit_sha").lower()
            != baseline_commit
            or qa_session_row is None
            or _row_text(qa_session_row, "principal_id") != qa_principal
            or _row_text(qa_session_row, "project_id") != project_id
            or _row_text(qa_session_row, "role") != "qa"
        ):
            continue
        qa_scope = _json_loads(qa_session_row["scope_json"], [])
        if not isinstance(qa_scope, list):
            continue
        scope_refs = _qa_session_scope_refs({"scope": qa_scope})
        required_scope_refs = {
            f"backlog:{backlog_id}",
            f"task:{execution_id}",
            f"commit:{candidate_commit}",
            _qa_scope_binding_ref(
                project_id=project_id,
                backlog_id=backlog_id,
                task_id=execution_id,
                commit_sha=candidate_commit,
            ),
        }
        if not required_scope_refs.issubset(scope_refs):
            continue

        merge_payload = _json_mapping(merge_row["payload_json"])
        merge_event_type = _row_text(merge_row, "event_type")
        merge_status = _row_text(merge_row, "status")
        merge_decision = _row_text(merge_row, "decision")
        merge_evidence_commit = _row_text(
            merge_row, "commit_sha"
        ).lower()
        merge_recovery_authority = merge_payload.get(
            "audited_postmerge_recovery_authority"
        )
        recovery_authority_payload = (
            dict(merge_recovery_authority)
            if isinstance(merge_recovery_authority, Mapping)
            else {}
        )
        recovery_authority_hash = str(
            recovery_authority_payload.pop("authority_hash", "") or ""
        )
        ordinary_live_merge = bool(
            merge_event_type == "parallel.live_merge"
            and merge_status == "passed"
        )
        recovery_live_merge = bool(
            merge_event_type == "parallel.live_merge_postmerge_recovery"
            and merge_status == "proceeded_with_exception"
            and merge_decision
            == "audited_postmerge_durable_merge_projection_no_pass"
            and merge_payload.get("no_pass_claim") is True
            and merge_payload.get("authoritative_pass_synthesized") is False
            and merge_payload.get("business_qa_bypassed") is False
            and isinstance(merge_recovery_authority, Mapping)
            and str(merge_recovery_authority.get("schema_version") or "")
            == "parallel_branch.audited_postmerge_recovery_authority.v1"
            and merge_recovery_authority.get("no_pass_claim") is True
            and merge_recovery_authority.get(
                "authoritative_pass_synthesized"
            )
            is False
            and merge_recovery_authority.get("business_qa_bypassed") is False
            and recovery_authority_hash
            == stable_sha256(recovery_authority_payload)
            and str(merge_recovery_authority.get("project_id") or "")
            == project_id
            and str(merge_recovery_authority.get("backlog_id") or "")
            == backlog_id
            and str(merge_recovery_authority.get("task_id") or "") == task_id
            and str(merge_recovery_authority.get("parent_task_id") or "")
            == execution_id
            and str(merge_recovery_authority.get("runtime_context_id") or "")
            == runtime_context_id
            and str(merge_recovery_authority.get("merge_queue_id") or "")
            == merge_queue_id
            and str(merge_recovery_authority.get("candidate_commit") or "").lower()
            == candidate_commit
            and str(merge_recovery_authority.get("merged_commit") or "").lower()
            == merge_evidence_commit
            and str(
                merge_recovery_authority.get("candidate_diff_sha256") or ""
            )
            == diff_sha256
            and str(merge_recovery_authority.get("qa_receipt_ref") or "")
            == f"timeline:{qa_event_id}"
            and merge_recovery_authority.get(
                "rejected_preflights_created_snapshot"
            )
            is False
        )
        merge_qa = merge_payload.get("qa_evidence")
        merge_request_evidence = (
            merge_qa.get("request_evidence")
            if isinstance(merge_qa, Mapping)
            else {}
        )
        merge_qa_request = (
            merge_request_evidence.get("qa_evidence")
            if isinstance(merge_request_evidence, Mapping)
            else {}
        )
        queue_item_id = str(
            merge_payload.get("queue_item_id") or ""
        ).strip()
        if not (
            _row_text(merge_row, "backlog_id") == backlog_id
            and _row_text(merge_row, "task_id") == task_id
            and (ordinary_live_merge or recovery_live_merge)
            and _row_text(merge_row, "event_kind") == "live_merge"
            and _row_text(merge_row, "phase") == "live_merge"
            and _row_text(merge_row, "actor") == "observer"
            and merge_evidence_commit == exception_merge_commit
            and str(merge_payload.get("parent_task_id") or "")
            == execution_id
            and str(merge_payload.get("child_task_id") or "") == task_id
            and str(merge_payload.get("merge_queue_id") or "")
            == merge_queue_id
            and queue_item_id
            and str(merge_payload.get("merge_commit") or "").lower()
            == merge_evidence_commit
            and str(merge_payload.get("target_head_after_merge") or "").lower()
            == merge_evidence_commit
            and isinstance(merge_qa_request, Mapping)
            and str(merge_qa_request.get("receipt_event_ref") or "")
            == f"timeline:{qa_event_id}"
            and str(merge_qa_request.get("independent_qa_session_id") or "")
            == qa_session_id
            and merge_qa_request.get("no_authoritative_pass_claim") is True
            and _route_gate_scope_matches(
                merge_payload,
                expected_task_id=task_id,
                require_authority_envelope=False,
            )
        ):
            continue

        from .parallel_branch_runtime import get_merge_queue_item

        queue_item = get_merge_queue_item(
            conn,
            project_id,
            merge_queue_id,
            queue_item_id,
        )
        recovery_marker_valid = True
        if recovery_live_merge:
            from .parallel_branch_runtime import (
                AUDITED_POSTMERGE_RECOVERY_MODE,
            )

            recovery_marker_valid = bool(
                queue_item is not None
                and str(queue_item.recovery_mode or "").strip()
                == AUDITED_POSTMERGE_RECOVERY_MODE
                and str(queue_item.recovery_authority_hash or "").strip()
                == recovery_authority_hash
            )
        if queue_item is None or not all(
            (
                str(queue_item.backlog_id or "").strip() == backlog_id,
                str(queue_item.task_id or "").strip() == task_id,
                str(queue_item.status or "").strip() == "merged",
                str(queue_item.branch_head or "").strip().lower()
                == candidate_commit,
                str(queue_item.merge_commit or "").strip().lower()
                == merge_evidence_commit,
                str(queue_item.target_head_after_merge or "").strip().lower()
                == merge_evidence_commit,
                recovery_marker_valid,
            )
        ):
            continue

        try:
            diagnostic_row = conn.execute(
                """
                SELECT status, bypass_policy_json, chain_trigger_json,
                       provenance_paths, target_files, test_files
                FROM backlog_bugs
                WHERE bug_id = ?
                """,
                (diagnostic_id,),
            ).fetchone()
        except sqlite3.Error:
            continue
        if diagnostic_row is None or _row_text(
            diagnostic_row, "status"
        ) != "OPEN":
            continue
        diagnostic_policy = _json_mapping(
            diagnostic_row["bypass_policy_json"]
        )
        diagnostic_trigger = _json_mapping(
            diagnostic_row["chain_trigger_json"]
        )
        diagnostic_refs = _json_loads(
            diagnostic_row["provenance_paths"], []
        )
        diagnostic_ref_set = {
            str(item or "").strip()
            for item in diagnostic_refs
            if str(item or "").strip()
        } if isinstance(diagnostic_refs, list) else set()
        required_diagnostic_refs = {
            f"backlog:{backlog_id}",
            f"contract-runtime:{execution_id}",
            f"timeline:{qa_event_id}",
            f"timeline:{merge_event_id}",
            f"merge:{merge_evidence_commit}",
        }
        recovery_anchor_commit = str(
            diagnostic_trigger.get("recovery_head_commit") or ""
        ).strip().lower()
        recovery_repair_execution_id = str(
            diagnostic_trigger.get("repair_contract_execution_id") or ""
        ).strip()
        recovery_target_valid = bool(
            recovery_live_merge
            and recovery_anchor_commit == merge_evidence_commit
            and diagnostic_trigger.get("no_pass_claim") is True
            and _value_int(
                diagnostic_trigger.get("actual_reconcile_count")
            )
            == 0
            and diagnostic_trigger.get(
                "rejected_preflight_created_snapshot"
            )
            is False
            and (
                target_commit == recovery_anchor_commit
                or recovery_repair_execution_id
            )
        )
        repair_descendant_commits: list[str] = []
        if recovery_target_valid and target_commit != recovery_anchor_commit:
            root = _graph_governance_project_root(project_id, {})
            allowed_repair_files: set[str] = set()
            for raw_scope in (
                diagnostic_row["target_files"],
                diagnostic_row["test_files"],
            ):
                parsed_scope = _json_loads(raw_scope, [])
                if isinstance(parsed_scope, list):
                    allowed_repair_files.update(
                        str(item or "").strip()
                        for item in parsed_scope
                        if str(item or "").strip()
                    )
            repair_descendant_commits = [
                commit.strip().lower()
                for commit in _git_output(
                    root,
                    [
                        "rev-list",
                        "--reverse",
                        f"{recovery_anchor_commit}..{target_commit}",
                    ],
                ).splitlines()
                if commit.strip()
            ]
            recovery_target_valid = bool(
                allowed_repair_files
                and _git_clean_worktree_verified(root)
                and _git_output(
                    root, ["rev-parse", "refs/heads/main"]
                ).lower()
                == target_commit
                and _git_commit_is_ancestor(
                    root,
                    recovery_anchor_commit,
                    target_commit,
                )
                and repair_descendant_commits
                and repair_descendant_commits[-1] == target_commit
            )
            for repair_commit in repair_descendant_commits:
                commit_body = _git_output(
                    root,
                    ["show", "-s", "--format=%B", repair_commit],
                )
                changed_files = {
                    path.strip()
                    for path in _git_output(
                        root,
                        [
                            "diff-tree",
                            "--no-commit-id",
                            "--name-only",
                            "-r",
                            repair_commit,
                        ],
                    ).splitlines()
                    if path.strip()
                }
                bug_trailers = re.findall(
                    r"(?m)^Chain-Bug-Id:\s*(\S+)\s*$",
                    commit_body,
                )
                source_trailers = re.findall(
                    r"(?m)^Chain-Source-Task:\s*(\S+)\s*$",
                    commit_body,
                )
                if not (
                    recovery_target_valid
                    and bug_trailers == [diagnostic_id]
                    and source_trailers == [
                        recovery_repair_execution_id
                    ]
                    and changed_files
                    and changed_files.issubset(allowed_repair_files)
                ):
                    recovery_target_valid = False
                    break
        if ordinary_live_merge:
            recovery_target_valid = merge_evidence_commit == target_commit
        if not (
            str(exception_payload.get("diagnostic_status") or "") == "OPEN"
            and diagnostic_policy.get("keep_open") is True
            and diagnostic_policy.get("system_gate_bypass_only") is True
            and diagnostic_policy.get("business_qa_bypassed") is False
            and diagnostic_policy.get("authoritative_pass_synthesized")
            is False
            and str(diagnostic_policy.get("classification") or "")
            == "system_governance_projection_block"
            and str(diagnostic_policy.get("source_backlog_id") or "")
            == backlog_id
            and str(
                diagnostic_policy.get("source_contract_execution_id") or ""
            )
            == execution_id
            and str(diagnostic_policy.get("allowed_operation") or "")
            == "one_post_merge_current_full_reconcile_and_activation"
            and required_diagnostic_refs.issubset(diagnostic_ref_set)
            and recovery_target_valid
        ):
            continue

        qa_time = _contract_runtime_close_authority_time_order_value(
            _row_text(qa_row, "created_at")
        )
        merge_time = _contract_runtime_close_authority_time_order_value(
            _row_text(merge_row, "created_at")
        )
        exception_time = _contract_runtime_close_authority_time_order_value(
            _row_text(exception_row, "created_at")
        )
        if not (
            qa_time is not None
            and merge_time is not None
            and exception_time is not None
            and qa_time < merge_time
            and (
                merge_time < exception_time
                or (
                    merge_time == exception_time
                    and merge_event_id < exception_id
                )
            )
        ):
            continue

        # The exception authorizes one actual reconcile. Once a successful
        # reconcile is recorded on its diagnostic row, the authority is spent.
        try:
            consumed = conn.execute(
                """
                SELECT 1
                FROM task_timeline_events
                WHERE project_id = ? AND backlog_id IN (?, ?)
                  AND event_type = 'graph.reconcile'
                  AND status IN ('accepted', 'ok', 'passed', 'succeeded')
                  AND lower(commit_sha) = ? AND created_at > ?
                LIMIT 1
                """,
                (
                    project_id,
                    diagnostic_id,
                    backlog_id,
                    target_commit,
                    _row_text(exception_row, "created_at"),
                ),
            ).fetchone()
        except sqlite3.Error:
            continue
        if consumed is not None:
            continue

        candidates.append(
            {
                "schema_version": (
                    "graph_current_full_reconcile.audited_no_pass_authority.v1"
                ),
                "source": "audited_no_pass_reconcile_exception",
                "authority_mode": "audited_no_pass_reconcile_exception",
                "server_derived": True,
                "db_verified": True,
                "project_id": project_id,
                "backlog_id": backlog_id,
                "contract_execution_id": execution_id,
                "runtime_context_id": runtime_context_id,
                "task_id": task_id,
                "parent_task_id": parent_task_id,
                "merge_queue_id": merge_queue_id,
                "queue_item_id": queue_item_id,
                "candidate_commit_sha": candidate_commit,
                "merged_commit_sha": target_commit,
                "recovery_anchor_commit_sha": (
                    recovery_anchor_commit if recovery_live_merge else ""
                ),
                "repair_descendant_commit_shas": (
                    list(repair_descendant_commits)
                    if recovery_live_merge
                    else []
                ),
                "repair_descendant_verified": bool(
                    recovery_live_merge
                    and target_commit != recovery_anchor_commit
                    and recovery_target_valid
                ),
                "canonical_base_snapshot_id": baseline_snapshot_id,
                "canonical_base_commit": baseline_commit,
                "candidate_diff_sha256": diff_sha256,
                "qa_source_ref": f"timeline:{qa_event_id}",
                "qa_event_id": qa_event_id,
                "qa_event_created_at": _row_text(qa_row, "created_at"),
                "qa_session_id": qa_session_id,
                "qa_principal_id": qa_principal,
                "merge_source_ref": f"timeline:{merge_event_id}",
                "merge_event_id": merge_event_id,
                "merge_event_created_at": _row_text(
                    merge_row, "created_at"
                ),
                "exception_source_ref": f"timeline:{exception_id}",
                "exception_event_id": exception_id,
                "exception_event_created_at": _row_text(
                    exception_row, "created_at"
                ),
                "diagnostic_backlog_id": diagnostic_id,
                "qa_contract_runtime_verified": False,
                "ordinary_close_authority": False,
                "durable_recovery_marker_verified": bool(
                    recovery_live_merge and recovery_marker_valid
                ),
                "business_qa_bypassed": False,
                "system_gate_bypass_only": True,
                "authoritative_pass_synthesized": False,
                "no_pass_claim": True,
                "one_shot": True,
            }
        )

    unique = {stable_sha256(item): item for item in candidates}
    return next(iter(unique.values())) if len(unique) == 1 else {}


def _current_full_reconcile_contract_merge_authority(
    conn,
    *,
    project_id: str,
    context: Any,
    target_commit_sha: str,
    contract_record: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Resolve one route-bound runtime context to its durable MF merge.

    The lookup is deliberately anchored on the already-authorized branch
    runtime context.  A commit by itself must never let an unrelated route
    acquire another contract's reconcile authority.
    """

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    merge_queue_id = str(
        getattr(context, "merge_queue_id", "") or ""
    ).strip()
    target_commit = str(target_commit_sha or "").strip().lower()
    if not (
        runtime_context_id
        and task_id
        and backlog_id
        and merge_queue_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", target_commit)
    ):
        return {}

    records: list[Mapping[str, Any]] = []
    if isinstance(contract_record, Mapping) and contract_record:
        records = [contract_record]
    else:
        try:
            rows = conn.execute(
                """
                SELECT record_json
                FROM contract_runtime_executions
                WHERE project_id = ? AND backlog_id = ?
                ORDER BY updated_at DESC, contract_execution_id
                """,
                (project_id, backlog_id),
            ).fetchall()
        except sqlite3.Error:
            rows = []
        for row in rows:
            try:
                raw = row["record_json"] if isinstance(row, sqlite3.Row) else row[0]
                candidate = json.loads(str(raw or "{}"))
            except (KeyError, TypeError, ValueError, json.JSONDecodeError):
                continue
            if isinstance(candidate, Mapping):
                records.append(candidate)

    candidates: list[dict[str, Any]] = []
    for record in records:
        if not _is_mf_parallel_record_contract_id(
            str(record.get("contract_id") or "").strip()
        ):
            continue
        execution_id = str(
            record.get("contract_execution_id") or ""
        ).strip()
        if not execution_id:
            continue
        dispatched = False
        for line in record.get("completed_lines") or []:
            if not isinstance(line, Mapping) or str(
                line.get("line_id") or ""
            ).strip() != "observer_dispatch_bounded_workers":
                continue
            for dispatched_context in _contract_runtime_contexts_for_dispatch_line(
                conn,
                project_id=project_id,
                record=record,
                line=line,
            ):
                dispatched_identity = _contract_runtime_context_identity(
                    dispatched_context
                )
                if dispatched_identity[:2] == (runtime_context_id, task_id):
                    dispatched = True
                    break
            if dispatched:
                break
        if not dispatched:
            # A server-validated post-merge recovery can bind a newer exact
            # runtime child than the historical ContractRuntime dispatch line.
            # Its no-PASS authority independently revalidates the execution
            # parent, runtime, queue, QA receipt, route, diagnostic, chronology,
            # and target commit, so do not discard it at the ordinary dispatch
            # projection gate.
            audited_exception = (
                _current_full_reconcile_audited_no_pass_authority(
                    conn,
                    project_id=project_id,
                    record=record,
                    context=context,
                    target_commit_sha=target_commit,
                )
            )
            if audited_exception and audited_exception.get(
                "durable_recovery_marker_verified"
            ) is True:
                candidates.append(audited_exception)
            continue

        authority = _contract_runtime_trusted_merge_projection(
            conn,
            project_id=project_id,
            record=record,
        )
        qa_time = _contract_runtime_close_authority_time_order_value(
            authority.get("qa_acceptance_created_at")
            or authority.get("qa_event_created_at")
        )
        merge_time = _contract_runtime_close_authority_time_order_value(
            authority.get("merge_event_created_at")
        )
        identity_matches = all(
            str(authority.get(field) or "").strip()
            == str(expected or "").strip()
            for field, expected in (
                ("runtime_context_id", runtime_context_id),
                ("task_id", task_id),
                ("parent_task_id", parent_task_id),
                ("backlog_id", backlog_id),
                ("merge_queue_id", merge_queue_id),
            )
        )
        strict_authority = bool(
            authority.get("timeline_verified") is True
            and authority.get("authority_verified") is True
            and authority.get("qa_contract_runtime_verified") is True
            and str(authority.get("durable_merge_schema_version") or "")
            == _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
            and identity_matches
            and str(authority.get("merged_commit_sha") or "").strip().lower()
            == target_commit
            and str(authority.get("queue_item_id") or "").strip()
            and int(authority.get("merge_event_id") or 0) > 0
            and qa_time is not None
            and merge_time is not None
            and qa_time <= merge_time
        )
        if not strict_authority:
            audited_exception = (
                _current_full_reconcile_audited_no_pass_authority(
                    conn,
                    project_id=project_id,
                    record=record,
                    context=context,
                    target_commit_sha=target_commit,
                )
            )
            if audited_exception:
                candidates.append(audited_exception)
            continue
        candidates.append(
            {
                "schema_version": (
                    "graph_current_full_reconcile.contract_merge_authority.v1"
                ),
                "source": "contract_runtime_durable_merge_projection",
                "server_derived": True,
                "db_verified": True,
                "project_id": project_id,
                "backlog_id": backlog_id,
                "contract_execution_id": execution_id,
                "runtime_context_id": runtime_context_id,
                "task_id": task_id,
                "parent_task_id": parent_task_id,
                "merge_queue_id": merge_queue_id,
                "queue_item_id": str(authority.get("queue_item_id") or ""),
                "merged_commit_sha": target_commit,
                "merge_source_ref": str(
                    authority.get("merge_source_ref") or ""
                ),
                "merge_event_id": int(authority.get("merge_event_id") or 0),
                "merge_event_created_at": str(
                    authority.get("merge_event_created_at") or ""
                ),
                "qa_source_ref": str(authority.get("qa_source_ref") or ""),
                "qa_acceptance_created_at": str(
                    authority.get("qa_acceptance_created_at") or ""
                ),
                "qa_acceptance_revision": int(
                    authority.get("qa_acceptance_revision") or 0
                ),
            }
        )

    unique = {stable_sha256(item): item for item in candidates}
    return next(iter(unique.values())) if len(unique) == 1 else {}


def _current_full_reconcile_runtime_successor_contract_kind(
    conn,
    *,
    project_id: str,
    context: Any,
) -> str:
    """Classify a materialized runtime context from persisted lineage.

    ContractRuntime dispatch is the strongest proof because a batch may fan
    out into row-scoped MF parallel successors.  The append-only branch
    contract revision remains the authority for materialized batch contexts
    that predate a standalone batch ContractRuntime execution record.
    """

    runtime_context_id, task_id, _ = _contract_runtime_context_identity(
        context
    )
    backlog_id = str(getattr(context, "backlog_id", "") or "").strip()
    if not runtime_context_id or not task_id or not backlog_id:
        return ""

    dispatched_contract_kinds: set[str] = set()
    try:
        rows = conn.execute(
            """
            SELECT record_json
            FROM contract_runtime_executions
            WHERE project_id = ? AND backlog_id = ?
            ORDER BY updated_at DESC, contract_execution_id
            """,
            (project_id, backlog_id),
        ).fetchall()
    except sqlite3.Error:
        rows = []
    for row in rows:
        try:
            raw = row["record_json"] if isinstance(row, sqlite3.Row) else row[0]
            record = json.loads(str(raw or "{}"))
        except (KeyError, TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(record, Mapping):
            continue
        contract_id = str(record.get("contract_id") or "").strip()
        if _is_mf_parallel_record_contract_id(contract_id):
            contract_kind = "mf_parallel"
        elif contract_id in {
            MF_BATCH_PARALLEL_RECORD_CONTRACT_ID,
            MF_BATCH_PARALLEL_CONTRACT_ID,
        }:
            contract_kind = "mf_batch_parallel"
        else:
            continue
        for line in record.get("completed_lines") or []:
            if not isinstance(line, Mapping) or str(
                line.get("line_id") or ""
            ).strip() != "observer_dispatch_bounded_workers":
                continue
            if any(
                _contract_runtime_context_identity(candidate)[:2]
                == (runtime_context_id, task_id)
                for candidate in _contract_runtime_contexts_for_dispatch_line(
                    conn,
                    project_id=project_id,
                    record=record,
                    line=line,
                )
            ):
                dispatched_contract_kinds.add(contract_kind)
                break

    # A row-scoped MF successor dispatched by ContractRuntime is strict even
    # when its ancestry originated from mf_batch_parallel.
    if "mf_parallel" in dispatched_contract_kinds:
        return "mf_parallel"
    if dispatched_contract_kinds == {"mf_batch_parallel"}:
        return "mf_batch_parallel"

    revision = _runtime_context_latest_contract_revision_payload(
        conn,
        context,
    )
    revision_contract_id = str(
        revision.get("contract_version")
        or revision.get("contract_id")
        or (revision.get("payload") or {}).get("contract_id")
        or ""
    ).strip()
    if _is_mf_parallel_record_contract_id(revision_contract_id):
        return "mf_parallel"
    if revision_contract_id in {
        MF_BATCH_PARALLEL_RECORD_CONTRACT_ID,
        MF_BATCH_PARALLEL_CONTRACT_ID,
    }:
        return "mf_batch_parallel"
    return ""


def _current_full_reconcile_runtime_context_scope(
    conn,
    *,
    project_id: str,
    body: Mapping[str, Any],
    auth: Mapping[str, Any],
    target_commit_sha: str,
    candidate_only: bool = False,
    source_free_reconcile_authority: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Resolve current-full runtime provenance from persisted branch identity.

    Current-full materializes the canonical clean HEAD under an authorized
    route; it does not itself prove that a worker commit was merged.  Durable
    merge/reconcile ordering remains authoritative in ContractRuntime and the
    backlog close gates.  Merge authority may be attached here as compatible
    provenance when it already exists, but it is never a prerequisite for
    rebuilding the canonical current graph.
    """

    body_scope = _contract_timeline_scope_from_graph_body(body)
    route_scope = (
        auth.get("route_token_scope")
        if isinstance(auth.get("route_token_scope"), Mapping)
        else {}
    )
    backlog_id = str(
        route_scope.get("backlog_id") or body_scope.get("backlog_id") or ""
    ).strip()
    route_task_id = str(route_scope.get("task_id") or "").strip()
    body_task_id = str(body_scope.get("task_id") or "").strip()
    task_id = route_task_id or body_task_id
    runtime_context_claims = {
        str(candidate.get("runtime_context_id") or "").strip()
        for candidate in (
            body,
            body.get("evidence")
            if isinstance(body.get("evidence"), Mapping)
            else {},
        )
        if str(candidate.get("runtime_context_id") or "").strip()
    }
    if len(runtime_context_claims) > 1:
        raise GovernanceError(
            "current_full_reconcile_runtime_context_scope_conflict",
            "current-full reconcile received conflicting runtime_context_id claims",
            422,
            {
                "runtime_context_id_claim_count": len(runtime_context_claims),
                "fail_closed": True,
            },
        )
    claimed_runtime_context_id = (
        next(iter(runtime_context_claims)) if runtime_context_claims else ""
    )
    parent_task_claims = {
        str(candidate.get("parent_task_id") or "").strip()
        for candidate in (
            body,
            body.get("evidence")
            if isinstance(body.get("evidence"), Mapping)
            else {},
        )
        if str(candidate.get("parent_task_id") or "").strip()
    }
    if len(parent_task_claims) > 1:
        raise GovernanceError(
            "current_full_reconcile_parent_task_scope_conflict",
            "current-full reconcile received conflicting parent_task_id claims",
            422,
            {
                "parent_task_id_claim_count": len(parent_task_claims),
                "fail_closed": True,
            },
        )
    claimed_parent_task_id = (
        next(iter(parent_task_claims)) if parent_task_claims else ""
    )
    merge_queue_id = str(body.get("merge_queue_id") or "").strip()
    route_allowed_actions = {
        str(action or "").strip().lower().replace("-", "_").replace(".", "_")
        for action in auth.get("route_token_allowed_actions") or []
        if str(action or "").strip()
    }
    route_bound_direct_main = bool(
        str(auth.get("role_source") or "").strip()
        == "observer_session_route_token_ref"
        and "observer_direct_mutation_exception" in route_allowed_actions
        and "graph_current_full_reconcile" in route_allowed_actions
    )
    if not task_id:
        if claimed_runtime_context_id:
            raise GovernanceError(
                "current_full_reconcile_runtime_context_scope_required",
                "runtime-context-bound current-full reconcile requires a task_id",
                422,
                {
                    "runtime_context_id_claimed": bool(
                        claimed_runtime_context_id
                    ),
                    "fail_closed": True,
                },
            )
        return {}

    from .parallel_branch_runtime import (
        get_branch_context,
        get_branch_context_by_runtime_context_id,
        runtime_context_id_for_branch_context,
    )

    context = get_branch_context(conn, project_id, task_id)
    contract_record: Mapping[str, Any] = {}
    contract_execution_id = ""
    if context is None:
        try:
            contract_record = _contract_runtime_store(conn).get(task_id)
        except (ContractRuntimeError, sqlite3.Error):
            contract_record = {}
        if (
            contract_record
            and str(contract_record.get("project_id") or "").strip()
            == project_id
            and str(contract_record.get("backlog_id") or "").strip()
            == backlog_id
        ):
            trusted_merge = _contract_runtime_trusted_merge_projection(
                conn,
                project_id=project_id,
                record=contract_record,
            )
            if trusted_merge.get("timeline_verified") is True:
                contract_execution_id = str(
                    contract_record.get("contract_execution_id") or ""
                ).strip()
                canonical_runtime_context_id = str(
                    trusted_merge.get("runtime_context_id") or ""
                ).strip()
                if canonical_runtime_context_id:
                    context = get_branch_context_by_runtime_context_id(
                        conn,
                        project_id,
                        canonical_runtime_context_id,
                    )
                if context is None:
                    context = get_branch_context(
                        conn,
                        project_id,
                        str(trusted_merge.get("task_id") or "").strip(),
                    )
    if context is None:
        if (
            isinstance(source_free_reconcile_authority, Mapping)
            and source_free_reconcile_authority.get("accepted") is True
        ):
            # A completed source-free system operation is intentionally
            # contextless.  Its exact persisted backlog/CE/R/session/request
            # binding is established by the handler before any graph DDL.
            return {
                "project_id": project_id,
                "backlog_id": backlog_id,
                "task_id": task_id,
                "source": "completed_source_free_reconcile_authority",
                "server_derived": True,
                "runtime_context_required": False,
                "source_free_operation": True,
                "authority_hash": str(
                    source_free_reconcile_authority.get("authority_hash") or ""
                ),
            }
        # An incomplete-fanin batch parent is the one route-bound current-full
        # authority that intentionally has no child BranchTaskRuntimeContext.
        # Accept it only from the canonical observer route mode and only when
        # every explicit request/scope field selects the same active durable
        # reconcile-pending epoch.  Ordinary contextless batch/parallel routes
        # continue through the fail-closed path below.
        explicit_project_id = str(body.get("project_id") or "").strip()
        explicit_backlog_id = str(body.get("backlog_id") or "").strip()
        explicit_task_id = str(body.get("task_id") or "").strip()
        contextless_incomplete_epoch = None
        if (
            str(auth.get("role_source") or "").strip()
            == "observer_session_route_token_ref"
            and "graph_current_full_reconcile" in route_allowed_actions
            and not claimed_runtime_context_id
            and explicit_project_id == project_id
            and explicit_backlog_id
            and explicit_task_id
            and merge_queue_id
            and explicit_backlog_id == backlog_id
            and explicit_task_id == task_id == route_task_id
        ):
            from .parallel_branch_runtime import (
                INTEGRATION_EPOCH_RECONCILE_PENDING,
                get_active_integration_epoch,
            )

            candidate_epoch = get_active_integration_epoch(
                conn,
                project_id,
                merge_queue_id=merge_queue_id,
            )
            if (
                candidate_epoch is not None
                and candidate_epoch.status
                == INTEGRATION_EPOCH_RECONCILE_PENDING
                and bool(candidate_epoch.incomplete_fanin)
                and candidate_epoch.project_id == project_id
                and candidate_epoch.coordination_backlog_id
                == explicit_backlog_id
                and candidate_epoch.batch_id == explicit_task_id
                and candidate_epoch.merge_queue_id == merge_queue_id
            ):
                contextless_incomplete_epoch = candidate_epoch
        if contextless_incomplete_epoch is not None:
            return {
                "project_id": project_id,
                "backlog_id": explicit_backlog_id,
                "task_id": explicit_task_id,
                "merge_queue_id": merge_queue_id,
                "integration_epoch_id": contextless_incomplete_epoch.epoch_id,
                "integration_epoch_batch_id": contextless_incomplete_epoch.batch_id,
                "source": "durable_incomplete_fanin_batch_parent_epoch",
                "server_derived": True,
                "runtime_context_required": False,
                "contextless_batch_parent_authority": True,
            }
        route_bound_onboard_identity = bool(
            contract_record
            and str(contract_record.get("project_id") or "").strip()
            == project_id
            and str(contract_record.get("backlog_id") or "").strip()
            == backlog_id
            and str(contract_record.get("contract_id") or "").strip()
            == ONBOARD_ROUTE_GUIDE_SERVICE_ID
            and str(contract_record.get("contract_execution_id") or "").strip()
            == task_id
            and route_task_id == task_id
            and str(auth.get("role_source") or "").strip()
            == "observer_session_route_token_ref"
            and "graph_current_full_reconcile" in route_allowed_actions
            and not claimed_runtime_context_id
            and not merge_queue_id
        )
        route_bound_onboard_direct_main = bool(
            route_bound_onboard_identity
            and route_bound_direct_main
        )
        direct_metadata = (
            contract_record.get("metadata")
            if isinstance(contract_record.get("metadata"), Mapping)
            else {}
        )
        strict_direct_binding = (
            direct_metadata.get(
                "operator_supervised_direct_main_runtime_binding"
            )
            if isinstance(
                direct_metadata.get(
                    "operator_supervised_direct_main_runtime_binding"
                ),
                Mapping,
            )
            else {}
        )
        route_bound_strict_direct_identity = bool(
            contract_record
            and str(contract_record.get("project_id") or "").strip()
            == project_id
            and str(contract_record.get("backlog_id") or "").strip()
            == backlog_id
            and str(contract_record.get("contract_id") or "").strip()
            == "operator_supervised_direct_main"
            and str(contract_record.get("revision") or "").strip()
            in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
            and strict_direct_binding.get(
                "strict_runtime_binding_required"
            )
            is True
            and str(contract_record.get("contract_execution_id") or "").strip()
            == task_id
            and route_task_id == task_id
            and str(auth.get("role_source") or "").strip()
            == "observer_session_route_token_ref"
            and not claimed_runtime_context_id
            and not merge_queue_id
        )
        route_bound_strict_direct_main = bool(
            route_bound_strict_direct_identity and route_bound_direct_main
        )
        if route_bound_onboard_direct_main or route_bound_strict_direct_main:
            # operator_supervised_direct_main intentionally has no branch
            # runtime context. Its active observer session plus the exact
            # full-round route scope is the canonical authority. Returning no
            # runtime scope prevents direct-main provenance from masquerading
            # as parallel_branch_runtime_context evidence.
            return {}
        if route_bound_onboard_identity or route_bound_strict_direct_identity:
            expected_actions = list(
                _OPERATOR_SUPERVISED_DIRECT_MAIN_FULL_ROUND_ACTIONS
            )
            actual_actions = sorted(route_allowed_actions)
            source = (
                "server._current_full_reconcile_runtime_context_scope."
                "direct_main_full_round_prewrite_gate.v1"
            )
            issue_payload = {
                "project_id": project_id,
                "caller_role": "observer",
                "backlog_id": backlog_id,
                "task_id": task_id,
                "target_files": (
                    _onboard_contract_route_issue_target_files_from_record(
                        contract_record
                    )
                    if route_bound_onboard_identity
                    else list(strict_direct_binding.get("target_files") or [])
                ),
                "allowed_actions": expected_actions,
                "evidence_refs": [
                    f"contract_runtime:{task_id}",
                    f"backlog:{backlog_id}",
                ],
            }
            raise GovernanceError(
                "current_full_reconcile_runtime_context_not_found",
                (
                    "contextless onboard direct-main current-full reconcile "
                    "requires the canonical full-round route actions"
                ),
                409,
                {
                    "schema_version": (
                        "graph_current_full_reconcile."
                        "direct_main_full_round_route_diagnostics.v1"
                    ),
                    "project_id": project_id,
                    "backlog_id": backlog_id,
                    "task_id": task_id,
                    "runtime_context_id_claimed": False,
                    "merge_queue_id": "",
                    "field": "allowed_actions",
                    "expected": expected_actions,
                    "actual": actual_actions,
                    "field_mismatches": [
                        {
                            "field": "allowed_actions",
                            "expected": expected_actions,
                            "actual": actual_actions,
                        }
                    ],
                    "required_companion_actions": [
                        "observer_direct_mutation_exception",
                        "graph_current_full_reconcile",
                    ],
                    "guide": {
                        "schema_version": (
                            "graph_current_full_reconcile."
                            "direct_main_full_round_route_correction.v1"
                        ),
                        "action": (
                            "issue_canonical_direct_main_full_round_route_then_"
                            "retry_exact_current_full_call"
                        ),
                        "onboard": {
                            "mcp_tool": "onboard_route_guide",
                            "request": {
                                "project_id": project_id,
                                "backlog_id": backlog_id,
                                "role": "observer",
                                "work_type": (
                                    "operator_supervised_direct_main"
                                ),
                            },
                            "projection_path": (
                                "agent_onboard_guidance.route_token_issue."
                                "observer_route_context_issue_payload"
                            ),
                        },
                        "issue": {
                            "mcp_tool": "observer_route_context_issue",
                            "request": issue_payload,
                        },
                        "retry": {
                            "mcp_tool": "graph_current_full_reconcile",
                            "same_world": True,
                            "exact_request": True,
                            "replace_only_corrected_route_proof_fields": True,
                        },
                        "instruction": (
                            "issue the copy-safe canonical direct-main full-"
                            "round route, then retry the exact current-full "
                            "request with only the fresh route ref substituted"
                        ),
                    },
                    "source": source,
                    "host_correctable": True,
                    "public_safe": True,
                    "secret_safe": True,
                    "fail_closed": True,
                    "zero_write_rejection": True,
                    "writes_performed": False,
                    "mutation_performed": False,
                    "retry_same_world_allowed": True,
                    "raw_route_token_required": False,
                    "raw_route_token_exposed": False,
                },
            )
        if (
            claimed_runtime_context_id
            or (backlog_id and merge_queue_id)
            or contract_record
        ):
            raise GovernanceError(
                "current_full_reconcile_runtime_context_not_found",
                "contract-bound current-full reconcile task has no persisted branch runtime context",
                409,
                {
                    "project_id": project_id,
                    "backlog_id": backlog_id,
                    "task_id": task_id,
                    "runtime_context_id_claimed": bool(
                        claimed_runtime_context_id
                    ),
                    "merge_queue_id": merge_queue_id,
                    "fail_closed": True,
                },
            )
        return {}

    canonical_runtime_context_id = runtime_context_id_for_branch_context(context)
    canonical_scope = {
        "project_id": project_id,
        "backlog_id": str(getattr(context, "backlog_id", "") or "").strip(),
        "task_id": str(getattr(context, "task_id", "") or "").strip(),
        "parent_task_id": str(
            getattr(context, "parent_task_id", "")
            or getattr(context, "root_task_id", "")
            or ""
        ).strip(),
        "runtime_context_id": canonical_runtime_context_id,
        "merge_queue_id": str(
            getattr(context, "merge_queue_id", "") or ""
        ).strip(),
    }
    if contract_execution_id:
        canonical_scope["contract_execution_id"] = contract_execution_id
    mismatches: dict[str, dict[str, str]] = {}
    requested_values = {
        "backlog_id": backlog_id,
        "parent_task_id": claimed_parent_task_id,
        "runtime_context_id": claimed_runtime_context_id,
        "merge_queue_id": merge_queue_id,
    }
    for field, requested in requested_values.items():
        canonical = canonical_scope.get(field, "")
        if requested and requested != canonical:
            mismatches[field] = {
                "expected": canonical,
                "actual": requested,
            }
    allowed_task_ids = {canonical_scope["task_id"]}
    if contract_execution_id:
        allowed_task_ids.add(contract_execution_id)
    for source, requested in (
        ("route_task_id", route_task_id),
        ("body_task_id", body_task_id),
    ):
        if requested and requested not in allowed_task_ids:
            mismatches[source] = {
                "expected": "|".join(sorted(allowed_task_ids)),
                "actual": requested,
            }
    if not canonical_scope["backlog_id"]:
        mismatches["backlog_id"] = {
            "expected": "<persisted branch runtime backlog_id>",
            "actual": "",
        }
    if not canonical_runtime_context_id:
        mismatches["runtime_context_id"] = {
            "expected": "<persisted canonical runtime_context_id>",
            "actual": "",
        }
    if mismatches:
        raise GovernanceError(
            "current_full_reconcile_runtime_context_scope_mismatch",
            "current-full reconcile scope does not match the persisted branch runtime context",
            409,
            {
                "project_id": project_id,
                "task_id": task_id,
                "scope_mismatches": mismatches,
                "source": "parallel_branch_runtime_context",
                "fail_closed": True,
            },
        )
    successor_contract_kind = (
        _current_full_reconcile_runtime_successor_contract_kind(
            conn,
            project_id=project_id,
            context=context,
        )
    )
    contract_merge_authority: dict[str, Any] = {}
    if successor_contract_kind == "mf_parallel" and not candidate_only:
        contract_merge_authority = (
            _current_full_reconcile_contract_merge_authority(
                conn,
                project_id=project_id,
                context=context,
                target_commit_sha=target_commit_sha,
                contract_record=contract_record,
            )
        )
    if contract_merge_authority:
        resolved_contract_execution_id = str(
            contract_merge_authority.get("contract_execution_id") or ""
        ).strip()
        if contract_execution_id and (
            resolved_contract_execution_id != contract_execution_id
        ):
            # This is optional merge provenance, not graph-rebuild authority.
            # A stale ContractRuntime projection must not block a canonical
            # route-bound current-full reconcile.
            contract_merge_authority = {}
        elif resolved_contract_execution_id:
            canonical_scope["contract_execution_id"] = (
                resolved_contract_execution_id
            )
    result = {
        **canonical_scope,
        "source": "parallel_branch_runtime_context",
        "server_derived": True,
    }
    if candidate_only:
        result.update(
            {
                "candidate_only": True,
                "post_merge_reconcile_authority_required": False,
            }
        )
    if contract_merge_authority:
        result["contract_merge_authority"] = contract_merge_authority
    return result


def _current_full_reconcile_request_category(
    conn,
    *,
    request_context: RequestContext,
    project_id: str,
    body: Mapping[str, Any],
    auth: Mapping[str, Any],
    target_commit_sha: str,
) -> dict[str, Any]:
    """Select one closed reconcile category before graph schema admission.

    A source-free backlog is never allowed to fall through to ordinary or
    direct-main handling.  Its completed authority must reproduce the exact
    active route/session, target HEAD, and copy-safe request body.
    """

    route_scope = (
        auth.get("route_token_scope")
        if isinstance(auth.get("route_token_scope"), Mapping)
        else {}
    )
    backlog_id = str(
        route_scope.get("backlog_id") or body.get("backlog_id") or ""
    ).strip()
    route_token_ref = str(
        auth.get("route_token_ref")
        or body.get("observer_route_token_ref")
        or body.get("route_token_ref")
        or ""
    ).strip()
    raw_allowed_actions = [
        str(action or "").strip()
        for action in auth.get("route_token_allowed_actions") or []
        if str(action or "").strip()
    ]
    source_free_route_claim = bool(
        auth.get("route_token_source_free_operation") is True
        or raw_allowed_actions == list(_OPERATOR_SOURCE_FREE_ACTIONS)
    )
    source_free = (
        _backlog_source_free_operation_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
        if backlog_id
        else {}
    )
    if source_free or source_free_route_claim:
        completed = _completed_source_free_reconcile_authority(
            conn,
            request_context=request_context,
            project_id=project_id,
            backlog_id=backlog_id,
            route_token_ref=route_token_ref,
            source_free_authority=source_free,
        )
        expected_body = (
            completed.get("copy_safe_body")
            if isinstance(completed.get("copy_safe_body"), Mapping)
            else {}
        )
        exact_body = bool(expected_body and dict(body) == dict(expected_body))
        exact_target = bool(
            str(completed.get("target_commit") or "").strip().lower()
            == str(target_commit_sha or "").strip().lower()
        )
        if not (
            completed.get("accepted") is True
            and exact_body
            and exact_target
        ):
            raise GovernanceError(
                "current_full_reconcile_source_free_authority_required",
                "source-free reconcile requires one exact completed persisted authority",
                409,
                {
                    "schema_version": (
                        "graph_current_full_reconcile."
                        "source_free_category_diagnostics.v1"
                    ),
                    "project_id": project_id,
                    "backlog_id": backlog_id,
                    "category": "source_free_system_operation",
                    "completed_authority_count": (
                        1 if completed.get("accepted") is True else 0
                    ),
                    "request_body_exact": exact_body,
                    "target_head_exact": exact_target,
                    "fail_closed": True,
                    "fallback_allowed": False,
                    "source": (
                        "server._current_full_reconcile_request_category."
                        "pre_admission_gate.v1"
                    ),
                },
            )
        return {
            "category": "source_free_system_operation",
            "source_free_reconcile_authority": dict(completed),
        }

    allowed_actions = {
        str(action or "").strip().lower().replace("-", "_").replace(".", "_")
        for action in raw_allowed_actions
    }
    direct = bool(
        "observer_direct_mutation_exception" in allowed_actions
        and "graph_current_full_reconcile" in allowed_actions
    )
    return {
        "category": "operator_supervised_direct_main" if direct else "ordinary",
        "source_free_reconcile_authority": {},
    }


def _dev_direct_graph_bootstrap_reconcile_authority(
    conn,
    *,
    project_id: str,
    auth: Mapping[str, Any],
    direct_main_qa_preflight: Mapping[str, Any],
    body: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Compose existing gates for the pre-implementation AC-dev bootstrap."""

    if _runtime_plane() != "dev":
        return {"applicable": False, "accepted": False}
    route_scope = (
        auth.get("route_token_scope")
        if isinstance(auth.get("route_token_scope"), Mapping)
        else {}
    )
    backlog_id = str(route_scope.get("backlog_id") or "").strip()
    task_id = str(route_scope.get("task_id") or "").strip()
    active_route_authority = (
        direct_main_qa_preflight.get("active_route_authority")
        if isinstance(
            direct_main_qa_preflight.get("active_route_authority"),
            Mapping,
        )
        else {}
    )
    strict_direct_position = bool(
        direct_main_qa_preflight.get("applicable") is True
        and active_route_authority.get("passed") is True
        and direct_main_qa_preflight.get("contract_runtime_next_line_id")
        == "observer_graph_context"
        and auth.get("role_source") == "observer_session_route_token_ref"
        and str(auth.get("observer_session_id") or "").strip()
        and str(auth.get("route_token_ref") or "").strip()
        and str(route_scope.get("project_id") or "").strip() == project_id
        and backlog_id
        and task_id
    )
    next_line_id = str(
        direct_main_qa_preflight.get("contract_runtime_next_line_id") or ""
    ).strip()
    readiness = None
    readiness_compatible = True
    try:
        readiness = _dev_graph_zero_write_readiness_projection(
            conn,
            project_id=project_id,
        )
    except GovernanceError:
        readiness_compatible = False
    materialization_required = bool(
        isinstance(readiness, Mapping)
        and readiness.get("materialization_required") is True
    )
    active_snapshot: dict[str, Any] = {}
    if readiness_compatible and readiness is None:
        from . import graph_snapshot_store as store

        active_snapshot = (
            store.get_active_graph_snapshot(conn, project_id) or {}
        )
    local_active_graph_present = bool(active_snapshot)
    exact_schema_no_local_active = bool(
        readiness_compatible
        and readiness is None
        and not local_active_graph_present
    )
    try:
        world = _operator_supervised_direct_main_dev_world_authority()
    except GovernanceError:
        world = {}
    classification = classify_graph_activation_connection(conn)
    custody_verified = bool(
        classification.get("runtime_plane") == "dev"
        and classification.get("classification_reason")
        == "verified_dev_cow_successor_receipt_history"
        and classification.get("active_graph_activation_allowed") is True
        and classification.get("world_id") == "ac-dev"
        and classification.get("project_id") == AC_PROJECT_ID
        and int(classification.get("port") or 0) == AC_DEV_SERVICE_PORT
        and classification.get("cow_successor_verified") is True
        and classification.get("source_checkout_verified") is True
        and classification.get("live_runtime_custody_verified") is True
    )
    expected_body = {
        "backlog_id": backlog_id,
        "task_id": task_id,
        "observer_session_id": str(auth.get("observer_session_id") or "").strip(),
        "observer_route_token_ref": str(auth.get("route_token_ref") or "").strip(),
        "target_commit_sha": str(world.get("target_head_commit") or "").strip(),
        "run_id": "current-full-"
        + str(world.get("target_head_commit") or "").strip()[:7],
        "activate": True,
        "require_clean": True,
        "semantic_use_ai": False,
    }
    target_commit = str(expected_body["target_commit_sha"] or "").lower()
    target_root = Path(str(world.get("target_project_root") or ""))
    target_identity = {
        "status": "materialization_required",
        "snapshot_id": _current_full_deterministic_snapshot_id(target_commit),
    }
    if readiness_compatible and readiness is None and target_commit:
        target_identity = _current_full_requested_snapshot_identity(
            conn,
            project_id=project_id,
            target_commit_sha=target_commit,
        )
    target_identity_missing = bool(
        materialization_required
        or target_identity.get("status") == "missing"
    )
    active_commit = str(active_snapshot.get("commit_sha") or "").lower()
    active_snapshot_id = str(active_snapshot.get("snapshot_id") or "").strip()
    active_ref_rows = []
    active_status_rows = []
    active_binding: dict[str, Any] = {}
    if local_active_graph_present:
        from . import graph_snapshot_store as store

        active_ref_rows = conn.execute(
            "SELECT ref_name,snapshot_id,commit_sha FROM graph_snapshot_refs "
            "WHERE project_id=? AND (ref_name='active' OR snapshot_id=?)",
            (project_id, active_snapshot_id),
        ).fetchall()
        active_status_rows = conn.execute(
            "SELECT snapshot_id,commit_sha,snapshot_kind,status "
            "FROM graph_snapshots WHERE project_id=? AND status='active'",
            (project_id,),
        ).fetchall()
        active_binding = store._current_full_snapshot_provenance_binding(
            conn,
            project_id,
            active_snapshot,
        )
    unique_default_active_ref = bool(
        len(active_ref_rows) == 1
        and str(active_ref_rows[0]["ref_name"] or "").strip() == "active"
        and str(active_ref_rows[0]["snapshot_id"] or "").strip()
        == active_snapshot_id
        and str(active_ref_rows[0]["commit_sha"] or "").strip().lower()
        == active_commit
    )
    unique_full_active_status = bool(
        len(active_status_rows) == 1
        and str(active_status_rows[0]["snapshot_id"] or "").strip()
        == active_snapshot_id
        and str(active_status_rows[0]["commit_sha"] or "").strip().lower()
        == active_commit
        and str(active_status_rows[0]["snapshot_kind"] or "").strip()
        == "full"
    )
    active_provenance_exact = bool(
        active_binding.get("verified") is True
        and str(active_binding.get("snapshot_id") or "").strip()
        == active_snapshot_id
        and str(active_binding.get("snapshot_commit") or "").strip().lower()
        == active_commit
        and str(
            active_binding.get("provenance_target_commit") or ""
        ).strip().lower()
        == active_commit
    )
    canonical_dev_world = bool(
        world.get("runtime_plane") == "dev"
        and int(world.get("runtime_port") or 0) == AC_DEV_SERVICE_PORT
        and world.get("branch") == AC_DEV_BRANCH
        and world.get("target_ref") == f"refs/heads/{AC_DEV_BRANCH}"
        and str(world.get("worktree_path") or "")
        == str(world.get("target_project_root") or "")
    )
    worktree_clean = bool(
        world.get("target_project_root")
        and expected_body["target_commit_sha"]
        and _git_head_commit(Path(str(world["target_project_root"])))
        == expected_body["target_commit_sha"]
        and _git_clean_worktree_verified(
            Path(str(world["target_project_root"]))
        )
    )
    same_wip_descendant_active_predecessor = bool(
        readiness_compatible
        and readiness is None
        and local_active_graph_present
        and unique_default_active_ref
        and unique_full_active_status
        and active_provenance_exact
        and str(active_snapshot.get("ref_name") or "").strip() == ""
        and str(active_snapshot.get("branch_ref") or "").strip() == ""
        and canonical_dev_world
        and worktree_clean
        and target_identity_missing
        and active_commit
        and target_commit
        and active_commit != target_commit
        and _git_commit_is_ancestor(target_root, active_commit, target_commit)
    )
    if same_wip_descendant_active_predecessor:
        expected_body["expected_old_snapshot_id"] = active_snapshot_id
    request_body_exact = body is not None and dict(body) == expected_body
    eligibility_checks = {
        "strict_direct_graph_first_route_session": strict_direct_position,
        "compatible_graph_materialization_preimage": readiness_compatible,
        "graph_materialization_required_or_exact_schema_no_local_active": (
            materialization_required
            or exact_schema_no_local_active
            or same_wip_descendant_active_predecessor
        ),
        "deterministic_target_snapshot_identity_missing": (
            target_identity_missing
        ),
        "classified_dev_cow_runtime_custody": custody_verified,
        "exact_ac_dev_project_world": bool(
            world.get("accepted") is True and project_id == AC_PROJECT_ID
        ),
        "exact_clean_ac_dev_head": worktree_clean,
    }
    eligible = all(eligibility_checks.values())
    missing = [
        requirement
        for requirement, passed in eligibility_checks.items()
        if not passed
    ]
    if not request_body_exact:
        missing.append("exact_mcp_adapted_http_body")
    authority = {
        "schema_version": "ac_dev.direct_graph_bootstrap_reconcile_authority.v1",
        "applicable": True,
        "eligible": eligible,
        "accepted": bool(eligible and request_body_exact),
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "materialization_required": materialization_required,
        "exact_schema_no_local_active": exact_schema_no_local_active,
        "local_active_graph_present": local_active_graph_present,
        "same_wip_descendant_active_predecessor": (
            same_wip_descendant_active_predecessor
        ),
        "active_predecessor_snapshot_id": (
            active_snapshot_id
            if same_wip_descendant_active_predecessor
            else ""
        ),
        "active_predecessor_commit": (
            active_commit if same_wip_descendant_active_predecessor else ""
        ),
        "unique_default_active_ref": unique_default_active_ref,
        "unique_full_active_status": unique_full_active_status,
        "active_predecessor_provenance_verified": active_provenance_exact,
        "target_snapshot_identity": dict(target_identity),
        "contract_runtime_first_missing_line": next_line_id,
        "route_session_authority_verified": strict_direct_position,
        "runtime_custody_verified": custody_verified,
        "worktree_clean": worktree_clean,
        "request_body_exact": request_body_exact,
        "expected_http_body": expected_body,
        "copy_safe_action_input": {"project_id": project_id, **expected_body},
        "missing_requirement_ids": missing,
        "writes_performed": False,
        "mutation_performed": False,
        "qa_synthesized": False,
        "pass_synthesized": False,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _record_pending_scope_reconcile_contract_event(
    conn,
    *,
    project_id: str,
    body: Mapping[str, Any],
    result: Mapping[str, Any],
    target_commit_sha: str,
    runtime_context_scope: Mapping[str, Any] | None = None,
    declared_actor_role: str = "",
    post_commit_hooks: bool = True,
) -> dict[str, Any]:
    if not isinstance(result, Mapping) or result.get("ok") is False:
        return {}
    scope = _contract_timeline_scope_from_graph_body(body)
    canonical_scope = {
        key: str((runtime_context_scope or {}).get(key) or "").strip()
        for key in (
            "project_id",
            "backlog_id",
            "task_id",
            "parent_task_id",
            "runtime_context_id",
            "merge_queue_id",
            "contract_execution_id",
        )
        if str((runtime_context_scope or {}).get(key) or "").strip()
    }
    if canonical_scope:
        scope["backlog_id"] = canonical_scope.get(
            "backlog_id",
            scope["backlog_id"],
        )
        scope["task_id"] = canonical_scope.get("task_id", scope["task_id"])
    if not scope["backlog_id"]:
        return {}
    declared_role = str(declared_actor_role or "").strip().lower()
    if declared_role and declared_role != "observer":
        raise ValidationError(
            "current-full reconcile timeline role must be observer",
            {
                "field": "declared_actor_role",
                "expected": "observer",
                "actual": declared_role,
                "fail_closed": True,
            },
        )
    from . import task_timeline

    snapshot_id = str(
        result.get("snapshot_id")
        or result.get("active_snapshot_id")
        or result.get("candidate_snapshot_id")
        or ""
    ).strip()
    activation = (
        result.get("activation_verification")
        if isinstance(result.get("activation_verification"), Mapping)
        else {}
    )
    current_full = bool(result.get("current_full_reconcile")) or str(
        result.get("strategy") or ""
    ).strip() == "current_full_reconcile"
    canonical_head_commit = str(
        result.get("head_commit") or target_commit_sha or ""
    ).strip()
    active_graph_commit = str(
        result.get("active_graph_commit")
        or activation.get("active_graph_commit")
        or ""
    ).strip()
    canonical_head_verified = bool(
        current_full
        and canonical_head_commit
        and canonical_head_commit == target_commit_sha
    )
    active_snapshot_verified = bool(
        current_full
        and activation.get("verified") is True
        and active_graph_commit == target_commit_sha
        and snapshot_id
    )
    evidence_ref = f"reconcile:{snapshot_id}" if snapshot_id else ""
    contract_evidence = _parallel_branch_contract_evidence_item(
        "reconcile",
        evidence_refs=[evidence_ref] if evidence_ref else [],
        extra={
            "target_commit_sha": target_commit_sha,
            "snapshot_id": snapshot_id,
            "reconcile_status": result.get("status") or result.get("snapshot_status") or "",
            "active": bool(result.get("activated")),
            "elapsed_ms": result.get("elapsed_ms") or 0,
            "strategy": result.get("strategy") or result.get("scope_reconcile_strategy") or "",
            "graph_delta_mode": result.get("graph_delta_mode") or result.get("scope_graph_delta_mode") or "",
            "fallback_reason": result.get("fallback_reason") or "",
            "reconcile_mode": "current_full" if current_full else "scope_reconcile",
            "reconciled_commit_sha": target_commit_sha,
            "canonical_head_commit": canonical_head_commit,
            "merged_head_commit": target_commit_sha if current_full else "",
            "active_graph_commit": active_graph_commit,
            "canonical_head_verified": canonical_head_verified,
            "active_snapshot_verified": active_snapshot_verified,
            "graph_reconciled": bool(
                current_full
                and canonical_head_verified
                and active_snapshot_verified
            ),
        },
    )
    return task_timeline.record_event(
        conn,
        project_id=project_id,
        backlog_id=scope["backlog_id"],
        task_id=scope["task_id"],
        event_type="graph.reconcile",
        event_kind="reconcile",
        phase="reconcile",
        actor=scope["actor"],
        status="passed",
        payload={
            "schema_version": "graph_reconcile_contract_evidence.v1",
            "requirement_id": "reconcile",
            "contract_evidence": [contract_evidence],
            "requested_by_actor": str(body.get("actor") or "").strip(),
            **({"actor_role": declared_role} if declared_role else {}),
            "target_commit_sha": target_commit_sha,
            "snapshot_id": snapshot_id,
            "active_snapshot_id": str(
                result.get("active_snapshot_id")
                or activation.get("active_snapshot_id")
                or snapshot_id
            ).strip(),
            "reconcile_mode": "current_full" if current_full else "scope_reconcile",
            "current_full_reconcile": current_full,
            "reconciled_commit_sha": target_commit_sha,
            "canonical_head_commit": canonical_head_commit,
            "merged_head_commit": target_commit_sha if current_full else "",
            "active_graph_commit": active_graph_commit,
            "canonical_head_verified": canonical_head_verified,
            "active_snapshot_verified": active_snapshot_verified,
            "graph_reconciled": bool(
                current_full
                and canonical_head_verified
                and active_snapshot_verified
            ),
            **{
                key: value
                for key, value in canonical_scope.items()
                if key
                in {
                    "backlog_id",
                    "task_id",
                    "parent_task_id",
                    "runtime_context_id",
                    "merge_queue_id",
                    "contract_execution_id",
                }
            },
            **(
                {
                    "runtime_context_scope": {
                        **canonical_scope,
                        "source": "parallel_branch_runtime_context",
                        "server_derived": True,
                    }
                }
                if canonical_scope
                else {}
            ),
            "result_status": result.get("status") or result.get("snapshot_status") or "",
            "graph_reconcile_result": {
                key: value
                for key, value in dict(result).items()
                if key
                in {
                    "ok",
                    "status",
                    "reason",
                    "snapshot_id",
                    "active_snapshot_id",
                    "snapshot_status",
                    "target_commit_sha",
                    "target_commit_inferred",
                    "pending_count",
                    "elapsed_ms",
                    "strategy",
                    "scope_reconcile_strategy",
                    "graph_delta_mode",
                    "scope_graph_delta_mode",
                    "fallback_reason",
                    "fallback_required",
                    "operator_next_action",
                    "operation_trace",
                    "activation_verification",
                    "activated",
                }
            },
        },
        commit_sha=target_commit_sha,
        post_commit_hooks=post_commit_hooks,
    )


@route("POST", "/api/graph-governance/{project_id}/index")
def handle_graph_governance_index_build(ctx: RequestContext):
    """Build and persist governance index artifacts without source mutation."""
    project_id = ctx.get_project_id()
    body = ctx.body
    root = _graph_governance_project_root(project_id, body)
    from .governance_index import build_and_persist_governance_index

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.index")
        result = build_and_persist_governance_index(
            conn,
            project_id,
            root,
            run_id=str(body.get("run_id") or ""),
            commit_sha=str(body.get("commit_sha") or ""),
            include_active_graph=bool(body.get("include_active_graph", True)),
            persist_inventory=bool(body.get("persist_inventory", True)),
        )
        conn.commit()
        return {
            "ok": True,
            "project_id": project_id,
            "run_id": result.get("run_id"),
            "commit_sha": result.get("commit_sha"),
            "active_snapshot": result.get("active_snapshot") or {},
            "file_inventory_summary": result.get("file_inventory_summary") or {},
            "symbol_count": (result.get("symbol_index") or {}).get("symbol_count", 0),
            "doc_heading_count": (result.get("doc_index") or {}).get("heading_count", 0),
            "coverage_state": result.get("coverage_state") or {},
            "persist_summary": result.get("persist_summary") or {},
        }
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/snapshots/import-existing")
def handle_graph_governance_import_existing(ctx: RequestContext):
    """Import the latest non-empty legacy/baseline graph as a graph snapshot."""
    project_id = ctx.get_project_id()
    body = ctx.body
    from . import graph_snapshot_store as store
    from .db import sqlite_write_lock

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.import-existing")
        with sqlite_write_lock():
            try:
                result = store.import_existing_graph_snapshot(
                    conn,
                    project_id,
                    commit_sha=str(body.get("commit_sha") or ""),
                    snapshot_id=body.get("snapshot_id"),
                    created_by=str(body.get("actor") or "observer"),
                    activate=bool(body.get("activate", False)),
                    expected_old_snapshot_id=body.get("expected_old_snapshot_id"),
                    extra_graph_paths=body.get("extra_graph_paths") or [],
                )
            except store.GraphSnapshotConflictError as exc:
                _raise_graph_api_conflict(exc)
            except (FileNotFoundError, KeyError, ValueError) as exc:
                _raise_graph_api_validation(exc)
            conn.commit()
        return 201, {"ok": True, **result}
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/reconcile/full")
def handle_graph_governance_full_reconcile(ctx: RequestContext):
    """Create a state-only full-reconcile snapshot.

    Legacy callers may still use this lower-level endpoint for candidate builds.
    Normal operator Update Graph uses /reconcile/current-full, which defaults to
    clean HEAD and activate=true.
    """
    project_id = ctx.get_project_id()
    body = ctx.body
    root = _graph_governance_project_root(project_id, body)
    from .state_reconcile import run_state_only_full_reconcile
    semantic_use_ai = _semantic_use_ai_from_body(body)
    semantic_ai_call = _semantic_ai_call_from_body(project_id, root, body)
    notes_extra = (
        dict(body.get("notes_extra"))
        if isinstance(body.get("notes_extra"), Mapping)
        else {}
    )
    notes_extra.pop("current_full_reconcile", None)

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.reconcile.full")
        if dev_runtime_verify_only():
            admit_ac_dev_graph_materialization_schema(
                conn, project_id=project_id
            )
        try:
            result = run_state_only_full_reconcile(
                conn,
                project_id,
                root,
                run_id=str(body.get("run_id") or ""),
                commit_sha=str(body.get("commit_sha") or ""),
                snapshot_id=body.get("snapshot_id"),
                snapshot_kind=str(body.get("snapshot_kind") or "full"),
                created_by=str(body.get("actor") or "observer"),
                activate=bool(body.get("activate", False)),
                expected_old_snapshot_id=body.get("expected_old_snapshot_id"),
                notes_extra=notes_extra or None,
                semantic_enrich=bool(body.get("semantic_enrich", True)),
                semantic_use_ai=semantic_use_ai,
                semantic_feedback_items=body.get("semantic_feedback_items") or body.get("feedback_items"),
                semantic_feedback_round=body.get("semantic_feedback_round"),
                semantic_max_excerpt_chars=(
                    int(body["semantic_max_excerpt_chars"])
                    if body.get("semantic_max_excerpt_chars") is not None
                    else None
                ),
                semantic_ai_call=semantic_ai_call,
                semantic_ai_feature_limit=_semantic_ai_feature_limit_from_body(body),
                **_semantic_ai_batch_kwargs_from_body(body),
                **_semantic_state_kwargs_from_body(body),
                semantic_classify_feedback=bool(
                    _semantic_bool_from_body(body, "semantic_classify_feedback", "classify_feedback", default=True)
                ),
                **_semantic_ai_config_kwargs_from_body(body),
                **_semantic_selector_kwargs_from_body(body),
                semantic_config_path=body.get("semantic_config_path"),
                # Dashboard graph-build actions are structural by default:
                # rebuild the snapshot and projection without silently filling
                # graph_semantic_jobs. Operators enqueue AI explicitly later.
                semantic_enqueue_stale=bool(body.get("enqueue_stale", False)),
            )
        except (KeyError, ValueError) as exc:
            _raise_graph_api_validation(exc)
        conn.commit()
        return 201, result
    finally:
        conn.close()


def _current_full_reconcile_snapshot_id(result: Mapping[str, Any]) -> str:
    return str(
        result.get("snapshot_id")
        or result.get("active_snapshot_id")
        or result.get("candidate_snapshot_id")
        or ""
    ).strip()


def _current_full_reconcile_projection_id(
    conn,
    *,
    project_id: str,
    snapshot_id: str,
    result: Mapping[str, Any],
) -> str:
    candidates = [
        result.get("projection_id"),
        result.get("semantic_projection_id"),
    ]
    for key in ("semantic_projection", "semantic_snapshot", "semantic", "projection"):
        value = result.get(key)
        if isinstance(value, Mapping):
            candidates.extend(
                [
                    value.get("projection_id"),
                    value.get("semantic_projection_id"),
                ]
            )
    for candidate in candidates:
        projection_id = str(candidate or "").strip()
        if projection_id:
            return projection_id
    if not snapshot_id:
        return ""
    from . import graph_events

    projection = graph_events.get_semantic_projection(conn, project_id, snapshot_id) or {}
    return str(projection.get("projection_id") or "").strip()


def _current_full_existing_projection_id_read_only(
    conn,
    *,
    project_id: str,
    snapshot_id: str,
) -> str:
    """Read an existing projection without invoking any schema guard or DDL."""

    if not snapshot_id:
        return ""
    try:
        table = conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' "
            "AND name = 'graph_semantic_projections'"
        ).fetchone()
        if not table:
            return ""
        row = conn.execute(
            """
            SELECT projection_id FROM graph_semantic_projections
            WHERE project_id = ? AND snapshot_id = ?
            ORDER BY event_watermark DESC, created_at DESC LIMIT 1
            """,
            (project_id, snapshot_id),
        ).fetchone()
    except sqlite3.OperationalError:
        return ""
    return str(row["projection_id"] if row else "").strip()


def _current_full_reconcile_idempotency_scope(
    route_evidence: Mapping[str, Any],
) -> dict[str, str]:
    """Return the stable route scope used to fence one reconcile run id.

    Route refs and observer sessions may be renewed while a long rebuild is in
    flight, so idempotency is bound to the canonical task/runtime scope rather
    than to those ephemeral credentials.
    """

    route_scope = (
        route_evidence.get("route_token_scope")
        if isinstance(route_evidence.get("route_token_scope"), Mapping)
        else {}
    )
    runtime_scope = (
        route_evidence.get("runtime_context_scope")
        if isinstance(route_evidence.get("runtime_context_scope"), Mapping)
        else {}
    )
    return {
        key: str(runtime_scope.get(key) or route_scope.get(key) or "").strip()
        for key in (
            "project_id",
            "backlog_id",
            "task_id",
            "parent_task_id",
            "runtime_context_id",
            "merge_queue_id",
            "contract_execution_id",
        )
        if str(runtime_scope.get(key) or route_scope.get(key) or "").strip()
    }


def _current_full_deterministic_snapshot_id(commit_sha: str) -> str:
    """Return the canonical path-safe identity for one default full commit."""

    commit = str(commit_sha or "").strip().lower()
    digest = hashlib.sha256(f"full:{commit}".encode("utf-8")).hexdigest()
    return f"full-{commit[:12]}-{digest[:12]}"


def _current_full_requested_snapshot_identity(
    conn,
    *,
    project_id: str,
    target_commit_sha: str,
    explicit_snapshot_id: str = "",
) -> dict[str, Any]:
    """Select one default identity without silently choosing legacy duplicates."""

    explicit = str(explicit_snapshot_id or "").strip()
    if explicit:
        return {
            "status": "explicit",
            "snapshot_id": explicit,
            "canonical_snapshot_id": "",
        }
    canonical = _current_full_deterministic_snapshot_id(target_commit_sha)
    rows = conn.execute(
        """
        SELECT snapshot_id, status FROM graph_snapshots
        WHERE project_id = ? AND commit_sha = ? AND snapshot_kind = 'full'
        ORDER BY created_at ASC, snapshot_id ASC
        """,
        (project_id, target_commit_sha),
    ).fetchall()
    if len(rows) > 1:
        return {
            "status": "conflict",
            "reason": "current_full_commit_snapshot_identity_ambiguous",
            "snapshot_id": canonical,
            "canonical_snapshot_id": canonical,
            "existing_snapshot_ids": [str(row["snapshot_id"] or "") for row in rows],
        }
    if rows:
        return {
            "status": "existing",
            "snapshot_id": str(rows[0]["snapshot_id"] or ""),
            "canonical_snapshot_id": canonical,
            "legacy_identity_selected": str(rows[0]["snapshot_id"] or "") != canonical,
        }
    return {
        "status": "missing",
        "snapshot_id": canonical,
        "canonical_snapshot_id": canonical,
        "legacy_identity_selected": False,
    }


def _current_full_safe_terminal_tuple(
    terminal_tuple: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Project terminal refusal details without DB rows or physical paths."""

    value = terminal_tuple if isinstance(terminal_tuple, Mapping) else {}
    return {
        key: value.get(key)
        for key in (
            "valid",
            "errors",
            "route_bound",
            "run_id",
            "snapshot_id",
            "metric_evidence_canonical",
            "metric_evidence_keys",
            "timeline_scope_mismatch_fields",
            "request_id",
            "reconcile_event_id",
            "provenance_id",
            "companion_integrity",
        )
        if key in value
    }


def _current_full_reconcile_existing_run(
    conn,
    store,
    *,
    project_id: str,
    run_id: str,
    target_commit_sha: str,
    route_evidence: Mapping[str, Any],
    requested_snapshot_id: str = "",
) -> dict[str, Any]:
    """Resolve a durable candidate or terminal result without rebuilding it.

    A candidate-only request and its later activation may intentionally use
    different run ids (for example, after QA or a recovered client timeout).
    When the caller supplies an exact ``snapshot_id``, that immutable snapshot
    identity is therefore authoritative for candidate lookup.  Run id remains
    the idempotency key for activation metrics/evidence, while commit and kind
    checks prevent an explicit snapshot id from adopting unrelated graph data.
    """

    expected_scope = _current_full_reconcile_idempotency_scope(route_evidence)
    exact_snapshot_id = str(requested_snapshot_id or "").strip()
    metric_rows = conn.execute(
        """
        SELECT * FROM reconcile_run_metrics
        WHERE project_id = ? AND run_id = ?
        ORDER BY created_at DESC, snapshot_id DESC
        """,
        (project_id, run_id),
    ).fetchall()
    metrics = [dict(row) for row in metric_rows]
    conflicting_commits = sorted(
        {
            str(row.get("commit_sha") or "").strip()
            for row in metrics
            if str(row.get("commit_sha") or "").strip()
            and str(row.get("commit_sha") or "").strip() != target_commit_sha
        }
    )
    if conflicting_commits:
        return {
            "status": "conflict",
            "reason": "reconcile_run_id_target_commit_conflict",
            "run_id": run_id,
            "expected_target_commit_sha": conflicting_commits[0],
            "actual_target_commit_sha": target_commit_sha,
            "conflicting_target_commits": conflicting_commits,
        }
    snapshots = []
    if exact_snapshot_id:
        row = conn.execute(
            """
            SELECT * FROM graph_snapshots
            WHERE project_id = ? AND snapshot_id = ?
            """,
            (project_id, exact_snapshot_id),
        ).fetchone()
        if row:
            snapshot = dict(row)
            snapshot_commit = str(snapshot.get("commit_sha") or "").strip()
            if snapshot_commit != target_commit_sha:
                return {
                    "status": "conflict",
                    "reason": "reconcile_snapshot_id_target_commit_conflict",
                    "run_id": run_id,
                    "snapshot_id": exact_snapshot_id,
                    "expected_target_commit_sha": snapshot_commit,
                    "actual_target_commit_sha": target_commit_sha,
                }
            snapshot_kind = str(snapshot.get("snapshot_kind") or "").strip()
            if snapshot_kind != "full":
                return {
                    "status": "conflict",
                    "reason": "reconcile_snapshot_id_kind_conflict",
                    "run_id": run_id,
                    "snapshot_id": exact_snapshot_id,
                    "expected_snapshot_kind": "full",
                    "actual_snapshot_kind": snapshot_kind,
                }
            notes = _json_loads(snapshot.get("notes"), {})
            snapshot["notes_payload"] = (
                dict(notes) if isinstance(notes, Mapping) else {}
            )
            snapshots.append(snapshot)
    else:
        for row in conn.execute(
            """
            SELECT * FROM graph_snapshots
            WHERE project_id = ? AND commit_sha = ?
            ORDER BY created_at DESC, snapshot_id DESC
            """,
            (project_id, target_commit_sha),
        ).fetchall():
            snapshot = dict(row)
            notes = _json_loads(snapshot.get("notes"), {})
            if (
                not isinstance(notes, Mapping)
                or str(notes.get("run_id") or "") != run_id
            ):
                continue
            snapshot["notes_payload"] = dict(notes)
            snapshots.append(snapshot)

    # Preserve the older, more precise target-commit and explicit-snapshot
    # refusals above.  Once those immutable identity checks pass, enforce the
    # broader one-run/one-snapshot fence before interpreting resume state.
    run_identity = store.current_full_run_snapshot_identity_check(
        conn,
        project_id,
        run_id=run_id,
        snapshot_id=exact_snapshot_id,
        commit_sha=target_commit_sha,
        idempotency_scope=expected_scope,
    )
    if run_identity["conflict"]:
        return {
            "status": "conflict",
            "reason": "current_full_run_snapshot_identity_conflict",
            **{
                key: value
                for key, value in run_identity.items()
                if key not in {"conflict", "reason"}
            },
        }

    if len(snapshots) > 1:
        return {
            "status": "conflict",
            "reason": "reconcile_run_id_multiple_snapshots",
            "run_id": run_id,
            "snapshot_ids": [row.get("snapshot_id") for row in snapshots],
        }

    snapshot = snapshots[0] if snapshots else {}
    snapshot_id = str(snapshot.get("snapshot_id") or "").strip()
    metric = next(
        (
            row
            for row in metrics
            if not snapshot_id or str(row.get("snapshot_id") or "") == snapshot_id
        ),
        ({} if snapshot_id else (metrics[0] if metrics else {})),
    )
    metric_evidence = _json_loads(metric.get("evidence_json"), {})
    metric_evidence = (
        dict(metric_evidence) if isinstance(metric_evidence, Mapping) else {}
    )
    stored_scope = metric_evidence.get("idempotency_scope")
    stored_scope = dict(stored_scope) if isinstance(stored_scope, Mapping) else {}
    if stored_scope and stored_scope != expected_scope:
        return {
            "status": "conflict",
            "reason": "reconcile_run_id_scope_conflict",
            "run_id": run_id,
            "expected_scope": stored_scope,
            "actual_scope": expected_scope,
        }

    metric_status = str(metric.get("status") or "").strip().lower()
    if (
        snapshot_id
        and str(snapshot.get("status") or "") == "active"
        and metric
    ):
        terminal_tuple = store.current_full_active_terminal_tuple(
            conn,
            project_id=project_id,
            run_id=run_id,
            target_commit_sha=target_commit_sha,
            expected_scope=expected_scope,
            snapshot_id=snapshot_id,
        )
        if terminal_tuple["valid"]:
            return {
                "status": "complete",
                "run_id": run_id,
                "snapshot": terminal_tuple["snapshot"],
                "snapshot_id": snapshot_id,
                "metric": terminal_tuple["metric"],
                "metric_evidence": terminal_tuple["metric_evidence"],
                "provenance": terminal_tuple["provenance"],
                "timeline_event": terminal_tuple["timeline_event"],
                "terminal_tuple": terminal_tuple,
            }
        terminal_errors = set(terminal_tuple["errors"])
        reason = "reconcile_active_terminal_tuple_invalid"
        if metric_status != "complete":
            reason = "reconcile_active_without_atomic_terminal_evidence"
        elif "terminal_provenance_missing" in terminal_errors:
            reason = "reconcile_terminal_provenance_missing"
        elif "terminal_timeline_missing" in terminal_errors:
            reason = "reconcile_terminal_timeline_missing"
        elif terminal_errors & {
            "terminal_timeline_identity_mismatch",
            "terminal_timeline_payload_mismatch",
            "terminal_timeline_scope_mismatch",
            "terminal_timeline_runtime_scope_mismatch",
        }:
            reason = "reconcile_terminal_timeline_scope_mismatch"
        return {
            "status": "incomplete_active",
            "reason": reason,
            "run_id": run_id,
            "snapshot_id": snapshot_id,
            "metric_status": metric_status,
            "terminal_tuple": terminal_tuple,
        }
    if snapshot_id and str(snapshot.get("status") or "") == "active":
        return {"status": "missing", "run_id": run_id}
    if snapshot_id:
        resume_tuple = store.current_full_candidate_resume_tuple(
            conn,
            project_id=project_id,
            run_id=run_id,
            target_commit_sha=target_commit_sha,
            snapshot=snapshot,
            request_metric=metric,
        )
        if not resume_tuple["valid"]:
            return {
                "status": "conflict",
                "reason": "current_full_candidate_resume_tuple_invalid",
                "run_id": run_id,
                "snapshot_id": snapshot_id,
                "fail_closed": True,
                "rebuild_started": False,
                "resume_tuple": resume_tuple,
            }
        return {
            "status": "candidate_ready",
            "run_id": run_id,
            "snapshot": snapshot,
            "snapshot_id": snapshot_id,
            "candidate_origin_run_id": resume_tuple["origin_run_id"],
            "metric": metric,
            "resume_tuple": resume_tuple,
        }
    if metric_status in {"running", "finalizing"}:
        return {
            "status": "running",
            "run_id": run_id,
            "metric": metric,
            "metric_evidence": metric_evidence,
        }
    return {"status": "missing", "run_id": run_id}


def _current_full_reconcile_existing_snapshot_identity(
    conn,
    store,
    *,
    project_id: str,
    run_id: str,
    target_commit_sha: str,
    route_evidence: Mapping[str, Any],
    snapshot_id: str,
) -> dict[str, Any]:
    """Resolve a snapshot identity independently of the caller's fresh run id."""

    row = conn.execute(
        "SELECT * FROM graph_snapshots WHERE project_id = ? AND snapshot_id = ?",
        (project_id, snapshot_id),
    ).fetchone()
    if not row:
        return {"status": "missing", "run_id": run_id}
    snapshot = dict(row)
    if (
        str(snapshot.get("commit_sha") or "") != target_commit_sha
        or str(snapshot.get("snapshot_kind") or "") != "full"
    ):
        return {
            "status": "conflict",
            "reason": "current_full_snapshot_identity_exists_not_resumable",
            "run_id": run_id,
            "snapshot_id": snapshot_id,
            "snapshot_commit_sha": str(snapshot.get("commit_sha") or ""),
            "snapshot_kind": str(snapshot.get("snapshot_kind") or ""),
        }
    status = str(snapshot.get("status") or "")
    if status == "candidate":
        resume_tuple = store.current_full_candidate_tuple_from_db(
            conn,
            project_id=project_id,
            run_id=run_id,
            target_commit_sha=target_commit_sha,
            snapshot_id=snapshot_id,
        )
        if resume_tuple["valid"]:
            return {
                "status": "candidate_ready",
                "run_id": run_id,
                "snapshot": snapshot,
                "snapshot_id": snapshot_id,
                "candidate_origin_run_id": resume_tuple["origin_run_id"],
                "resume_tuple": resume_tuple,
            }
        return {
            "status": "conflict",
            "reason": "current_full_candidate_resume_tuple_invalid",
            "run_id": run_id,
            "snapshot_id": snapshot_id,
            "resume_tuple": resume_tuple,
        }
    last_terminal_tuple: Mapping[str, Any] = {}
    parent_terminal_matches: list[dict[str, Any]] = []
    if status == "active":
        complete_rows = conn.execute(
            """
            SELECT run_id FROM reconcile_run_metrics
            WHERE project_id = ? AND snapshot_id = ? AND commit_sha = ?
              AND status = 'complete'
            ORDER BY created_at DESC, run_id DESC
            """,
            (project_id, snapshot_id, target_commit_sha),
        ).fetchall()
        for complete_row in complete_rows:
            origin_run_id = str(complete_row["run_id"] or "")
            terminal_tuple = store.current_full_active_terminal_tuple(
                conn,
                project_id=project_id,
                run_id=origin_run_id,
                target_commit_sha=target_commit_sha,
                expected_scope=_current_full_reconcile_idempotency_scope(
                    route_evidence
                ),
                snapshot_id=snapshot_id,
            )
            last_terminal_tuple = _current_full_safe_terminal_tuple(
                terminal_tuple
            )
            if terminal_tuple.get("valid"):
                return {
                    "status": "complete",
                    "run_id": run_id,
                    "snapshot_id": snapshot_id,
                    "terminal": {
                        "status": "complete",
                        "run_id": origin_run_id,
                        "snapshot": terminal_tuple["snapshot"],
                        "snapshot_id": snapshot_id,
                        "metric": terminal_tuple["metric"],
                        "metric_evidence": terminal_tuple["metric_evidence"],
                        "provenance": terminal_tuple["provenance"],
                        "timeline_event": terminal_tuple["timeline_event"],
                        "terminal_tuple": terminal_tuple,
                    },
                }
            parent_resume_authority = (
                _current_full_reconcile_parent_terminal_resume_authority(
                    conn,
                    project_id=project_id,
                    target_commit_sha=target_commit_sha,
                    snapshot_id=snapshot_id,
                    expected_scope=_current_full_reconcile_idempotency_scope(
                        route_evidence
                    ),
                    stored_scope=(
                        terminal_tuple.get("stored_scope")
                        if isinstance(
                            terminal_tuple.get("stored_scope"), Mapping
                        )
                        else {}
                    ),
                )
            )
            if parent_resume_authority.get("valid") is True:
                parent_scope = parent_resume_authority["terminal_parent_scope"]
                parent_terminal_tuple = store.current_full_active_terminal_tuple(
                    conn,
                    project_id=project_id,
                    run_id=origin_run_id,
                    target_commit_sha=target_commit_sha,
                    expected_scope=parent_scope,
                    snapshot_id=snapshot_id,
                )
                if parent_terminal_tuple.get("valid"):
                    parent_terminal_matches.append(
                        {
                            "origin_run_id": origin_run_id,
                            "terminal_tuple": parent_terminal_tuple,
                            "resume_authority": parent_resume_authority,
                        }
                    )
        if len(parent_terminal_matches) == 1:
            match = parent_terminal_matches[0]
            terminal_tuple = match["terminal_tuple"]
            return {
                "status": "complete",
                "run_id": run_id,
                "snapshot_id": snapshot_id,
                "canonical_parent_snapshot_resume": True,
                "parent_snapshot_resume_authority": match["resume_authority"],
                "terminal": {
                    "status": "complete",
                    "run_id": match["origin_run_id"],
                    "snapshot": terminal_tuple["snapshot"],
                    "snapshot_id": snapshot_id,
                    "metric": terminal_tuple["metric"],
                    "metric_evidence": terminal_tuple["metric_evidence"],
                    "provenance": terminal_tuple["provenance"],
                    "timeline_event": terminal_tuple["timeline_event"],
                    "terminal_tuple": terminal_tuple,
                },
            }
        if len(parent_terminal_matches) > 1:
            return {
                "status": "conflict",
                "reason": "current_full_parent_terminal_resume_ambiguous",
                "run_id": run_id,
                "snapshot_id": snapshot_id,
                "parent_terminal_match_count": len(parent_terminal_matches),
                "fail_closed": True,
            }
    active_ref = conn.execute(
        "SELECT snapshot_id FROM graph_snapshot_refs "
        "WHERE project_id = ? AND ref_name = 'active'",
        (project_id,),
    ).fetchone()
    return {
        "status": "conflict",
        "reason": "current_full_snapshot_identity_exists_not_resumable",
        "run_id": run_id,
        "snapshot_id": snapshot_id,
        "snapshot_status": status,
        "active_snapshot_id": str(active_ref["snapshot_id"] if active_ref else ""),
        "terminal_tuple": last_terminal_tuple,
    }


def _current_full_reconcile_parent_terminal_resume_authority(
    conn,
    *,
    project_id: str,
    target_commit_sha: str,
    snapshot_id: str,
    expected_scope: Mapping[str, Any],
    stored_scope: Mapping[str, Any],
) -> dict[str, Any]:
    """Prove that a child route selects its batch parent's terminal snapshot.

    Older batch-parent reconciles correctly persisted the coordination backlog
    and batch task as the terminal route scope.  A later worker-scoped receipt
    has a richer RuntimeContext scope, including the ContractRuntime parent id.
    Treating those two scopes as interchangeable is unsafe, but rejecting the
    already-reconciled snapshot forever is also wrong.  This pure-read bridge
    accepts only the unique persisted child -> merge item -> closed integration
    epoch -> parent terminal chain.  It never backfills or normalizes history.
    """

    current_scope = {
        key: str(value or "").strip()
        for key, value in dict(expected_scope).items()
        if str(value or "").strip()
    }
    historical_scope = {
        key: str(value or "").strip()
        for key, value in dict(stored_scope).items()
        if str(value or "").strip()
    }
    required_current = (
        "project_id",
        "backlog_id",
        "task_id",
        "parent_task_id",
        "runtime_context_id",
        "merge_queue_id",
    )
    if any(not current_scope.get(key) for key in required_current):
        return {"valid": False, "reason": "current_scope_incomplete"}
    if current_scope["project_id"] != project_id:
        return {"valid": False, "reason": "current_scope_project_mismatch"}

    try:
        context_rows = conn.execute(
            """
            SELECT project_id, task_id, runtime_context_id, batch_id,
                   backlog_id, parent_task_id, root_task_id, merge_queue_id,
                   status, target_head_commit, snapshot_id
            FROM parallel_branch_runtime_contexts
            WHERE project_id = ? AND task_id = ? AND runtime_context_id = ?
              AND backlog_id = ? AND merge_queue_id = ?
            """,
            (
                project_id,
                current_scope["task_id"],
                current_scope["runtime_context_id"],
                current_scope["backlog_id"],
                current_scope["merge_queue_id"],
            ),
        ).fetchall()
    except sqlite3.OperationalError:
        return {"valid": False, "reason": "runtime_lineage_tables_missing"}
    if len(context_rows) != 1:
        return {
            "valid": False,
            "reason": "runtime_context_identity_not_unique",
            "runtime_context_match_count": len(context_rows),
        }
    context = dict(context_rows[0])
    persisted_parent_task_id = str(context.get("parent_task_id") or "").strip()
    persisted_root_task_id = str(context.get("root_task_id") or "").strip()
    runtime_parent_task_id = persisted_parent_task_id
    batch_task_id = str(context.get("batch_id") or "").strip()
    if (
        not runtime_parent_task_id
        or (
            persisted_parent_task_id
            and persisted_root_task_id
            and persisted_parent_task_id != persisted_root_task_id
        )
        or runtime_parent_task_id != current_scope["parent_task_id"]
        or not batch_task_id
        or str(context.get("status") or "").strip() != "merged"
        or str(context.get("target_head_commit") or "").strip()
        != target_commit_sha
        or str(context.get("snapshot_id") or "").strip() != snapshot_id
    ):
        return {"valid": False, "reason": "runtime_context_lineage_mismatch"}

    try:
        epoch_rows = conn.execute(
            """
            SELECT batch_id, coordination_backlog_id, merge_queue_id,
                   merge_cursor, merged_prefix_json,
                   remaining_queue_item_ids_json, reconcile_state, status,
                   snapshot_id, reconciled_target_head
            FROM parallel_branch_integration_epochs
            WHERE project_id = ? AND batch_id = ? AND merge_queue_id = ?
            """,
            (project_id, batch_task_id, current_scope["merge_queue_id"]),
        ).fetchall()
    except sqlite3.OperationalError:
        return {"valid": False, "reason": "runtime_lineage_tables_missing"}
    if len(epoch_rows) != 1:
        return {
            "valid": False,
            "reason": "integration_epoch_identity_not_unique",
            "integration_epoch_match_count": len(epoch_rows),
        }
    epoch = dict(epoch_rows[0])
    merged_prefix = _json_loads(epoch.get("merged_prefix_json"), [])
    merged_prefix = [
        str(value or "").strip()
        for value in merged_prefix
        if str(value or "").strip()
    ] if isinstance(merged_prefix, list) else []
    remaining_queue_item_ids = _json_loads(
        epoch.get("remaining_queue_item_ids_json"), []
    )
    remaining_queue_item_ids = [
        str(value or "").strip()
        for value in remaining_queue_item_ids
        if str(value or "").strip()
    ] if isinstance(remaining_queue_item_ids, list) else []
    coordination_backlog_id = str(
        epoch.get("coordination_backlog_id") or ""
    ).strip()
    if (
        not coordination_backlog_id
        or str(epoch.get("status") or "").strip() != "closed"
        or str(epoch.get("reconcile_state") or "").strip() != "reconciled"
        or str(epoch.get("snapshot_id") or "").strip() != snapshot_id
        or str(epoch.get("reconciled_target_head") or "").strip()
        != target_commit_sha
        or remaining_queue_item_ids
        or len(merged_prefix) != int(epoch.get("merge_cursor") or 0)
    ):
        return {"valid": False, "reason": "integration_epoch_lineage_mismatch"}

    prefix_rows = conn.execute(
        """
        SELECT queue_item_id, status, snapshot_id
        FROM parallel_branch_merge_queue_items
        WHERE project_id = ? AND merge_queue_id = ?
        """,
        (project_id, current_scope["merge_queue_id"]),
    ).fetchall()
    queue_rows_by_id = {
        str(row["queue_item_id"] or "").strip(): dict(row)
        for row in prefix_rows
        if str(row["queue_item_id"] or "").strip()
    }
    prefix_rows_by_id = {
        queue_item_id: queue_rows_by_id[queue_item_id]
        for queue_item_id in merged_prefix
        if queue_item_id in queue_rows_by_id
    }
    merged_queue_item_ids = {
        queue_item_id
        for queue_item_id, row in queue_rows_by_id.items()
        if str(row.get("status") or "").strip() == "merged"
    }
    if (
        len(prefix_rows_by_id) != len(merged_prefix)
        or merged_queue_item_ids != set(merged_prefix)
        or any(
            str(row.get("status") or "").strip() != "merged"
            or str(row.get("snapshot_id") or "").strip() != snapshot_id
            for row in prefix_rows_by_id.values()
        )
    ):
        return {"valid": False, "reason": "integration_epoch_prefix_custody_mismatch"}

    try:
        queue_rows = conn.execute(
            """
            SELECT queue_item_id, task_id, backlog_id, status, snapshot_id,
                   merge_commit, target_head_after_merge
            FROM parallel_branch_merge_queue_items
            WHERE project_id = ? AND merge_queue_id = ? AND task_id = ?
              AND backlog_id = ?
            """,
            (
                project_id,
                current_scope["merge_queue_id"],
                current_scope["task_id"],
                current_scope["backlog_id"],
            ),
        ).fetchall()
    except sqlite3.OperationalError:
        return {"valid": False, "reason": "runtime_lineage_tables_missing"}
    if len(queue_rows) != 1:
        return {
            "valid": False,
            "reason": "merge_queue_child_identity_not_unique",
            "merge_queue_child_match_count": len(queue_rows),
        }
    queue_item = dict(queue_rows[0])
    queue_item_id = str(queue_item.get("queue_item_id") or "").strip()
    child_landing_commit = str(queue_item.get("merge_commit") or "").strip()
    child_target_head_after_merge = str(
        queue_item.get("target_head_after_merge") or ""
    ).strip()
    if (
        str(queue_item.get("status") or "").strip() != "merged"
        or str(queue_item.get("snapshot_id") or "").strip() != snapshot_id
        or not queue_item_id
        or merged_prefix.count(queue_item_id) != 1
        or not child_landing_commit
        or child_landing_commit != child_target_head_after_merge
    ):
        return {"valid": False, "reason": "merge_queue_child_lineage_mismatch"}

    canonical_parent_scope = {
        "project_id": project_id,
        "backlog_id": coordination_backlog_id,
        "task_id": batch_task_id,
    }
    if historical_scope.get("merge_queue_id"):
        canonical_parent_scope["merge_queue_id"] = current_scope[
            "merge_queue_id"
        ]
    if historical_scope.get("parent_task_id"):
        canonical_parent_scope["parent_task_id"] = batch_task_id
    if historical_scope != canonical_parent_scope:
        return {"valid": False, "reason": "terminal_parent_scope_mismatch"}

    return {
        "valid": True,
        "schema_version": (
            "graph_current_full_reconcile.parent_terminal_resume_authority.v1"
        ),
        "server_derived": True,
        "source": (
            "parallel_branch_runtime_contexts+"
            "parallel_branch_merge_queue_items+"
            "parallel_branch_integration_epochs+terminal_tuple"
        ),
        "terminal_parent_scope": canonical_parent_scope,
        "runtime_parent_task_id": runtime_parent_task_id,
        "canonical_parent_task_id": batch_task_id,
        "runtime_context_id": current_scope["runtime_context_id"],
        "child_task_id": current_scope["task_id"],
        "child_backlog_id": current_scope["backlog_id"],
        "merge_queue_id": current_scope["merge_queue_id"],
        "queue_item_id": queue_item_id,
        "child_landing_commit_sha": child_landing_commit,
        "snapshot_id": snapshot_id,
        "target_commit_sha": target_commit_sha,
        "history_rewritten": False,
    }


def _current_full_reconcile_idempotent_response(
    existing: Mapping[str, Any],
    *,
    project_id: str,
    target_commit_sha: str,
    head_commit: str,
) -> dict[str, Any]:
    snapshot_id = str(existing.get("snapshot_id") or "").strip()
    provenance = (
        existing.get("provenance")
        if isinstance(existing.get("provenance"), Mapping)
        else {}
    )
    timeline_event = (
        existing.get("timeline_event")
        if isinstance(existing.get("timeline_event"), Mapping)
        else {}
    )
    reconcile_event_id = int(timeline_event.get("id") or 0)
    return {
        "ok": True,
        "project_id": project_id,
        "status": "complete",
        "run_id": str(existing.get("run_id") or ""),
        "snapshot_id": snapshot_id,
        "active_snapshot_id": snapshot_id,
        "snapshot_status": "active",
        "target_commit_sha": target_commit_sha,
        "head_commit": head_commit,
        "current_full_reconcile": True,
        "strategy": "current_full_reconcile",
        "scope_reconcile_strategy": "current_full_reconcile",
        "graph_delta_mode": "full_rebuild",
        "scope_graph_delta_mode": "full_rebuild",
        "activated": True,
        "idempotent_replay": True,
        "rebuild_skipped": True,
        "timeline_event_recorded": (
            {
                "id": reconcile_event_id,
                "ref": f"timeline:{reconcile_event_id}",
                "event_kind": str(timeline_event.get("event_kind") or ""),
                "phase": str(timeline_event.get("phase") or ""),
                "status": str(timeline_event.get("status") or ""),
                "requirement_id": "reconcile",
            }
            if reconcile_event_id
            else {}
        ),
        "current_full_reconcile_provenance": provenance,
    }


_CURRENT_FULL_RECONCILE_HTTP_COMPACT_TRIGGER_BYTES = 64 * 1024


def _current_full_reconcile_http_public_fields(
    value: Any,
    fields: tuple[str, ...],
) -> dict[str, Any]:
    """Project bounded copy-safe scalar fields from one reconcile mapping."""

    if not isinstance(value, Mapping):
        return {}
    projected: dict[str, Any] = {}
    for field in fields:
        item = value.get(field)
        if isinstance(item, (str, int, float, bool)) or item is None:
            if isinstance(item, str) and len(item.encode("utf-8")) > 2_048:
                continue
            if item not in (None, ""):
                projected[field] = item
    return projected


def _current_full_reconcile_bounded_http_response(
    response: Mapping[str, Any],
    *,
    request_id: str,
    db_total_changes_delta: int,
) -> dict[str, Any]:
    """Bound current-full output before an already-loaded MCP adapter sees it.

    A reconcile may commit activation, timeline, and provenance before its full
    materialization trace is serialized.  Stale MCP adapters cannot acquire a
    newly added adapter-side projector, so the governance HTTP boundary must
    preserve the durable result and current-request write truth in a bounded
    copy-safe response.  Historical small responses retain their exact shape.
    """

    source = dict(response)
    try:
        source_serialized_bytes = len(
            json.dumps(
                source,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
                default=str,
            ).encode("utf-8")
        )
    except Exception:
        return source
    if (
        source_serialized_bytes
        <= _CURRENT_FULL_RECONCILE_HTTP_COMPACT_TRIGGER_BYTES
    ):
        return source

    timeline_event = _current_full_reconcile_http_public_fields(
        source.get("timeline_event_recorded"),
        ("id", "ref", "event_kind", "phase", "status", "requirement_id"),
    )
    activation_verification = (
        source.get("activation_verification")
        if isinstance(source.get("activation_verification"), Mapping)
        else {}
    )
    provenance = (
        source.get("current_full_reconcile_provenance")
        if isinstance(source.get("current_full_reconcile_provenance"), Mapping)
        else {}
    )
    idempotent_replay = bool(source.get("idempotent_replay"))
    explicit_write = bool(
        source.get("writes_performed") is True
        or source.get("mutation_performed") is True
    )
    db_write_proven = int(db_total_changes_delta or 0) > 0
    activation_write_proven = bool(
        source.get("ok") is True
        and source.get("activated") is True
        and activation_verification.get("verified") is True
        and timeline_event.get("id")
        and str(provenance.get("provenance_id") or "").strip()
        and not idempotent_replay
    )
    timeline_write_proven = bool(
        source.get("ok") is True
        and timeline_event.get("id")
        and not idempotent_replay
    )
    current_request_mutated = bool(
        explicit_write
        or db_write_proven
        or activation_write_proven
        or timeline_write_proven
    )
    explicit_zero_write = bool(
        source.get("zero_write_rejection") is True
        or source.get("zero_write") is True
        or (source.get("ok") is False and not current_request_mutated)
    )

    compact: dict[str, Any] = {
        "schema_version": (
            "graph_current_full_reconcile.http_bounded_response.v1"
        ),
        "source_response_schema_version": str(
            source.get("schema_version") or ""
        ),
        "response_view": "compact",
        "bounded_response": True,
        "source_serialized_bytes": source_serialized_bytes,
        "max_serialized_bytes": (
            _CURRENT_FULL_RECONCILE_HTTP_COMPACT_TRIGGER_BYTES
        ),
        **_current_full_reconcile_http_public_fields(
            source,
            (
                "ok",
                "status",
                "error",
                "message",
                "project_id",
                "run_id",
                "snapshot_id",
                "candidate_snapshot_id",
                "active_snapshot_id",
                "snapshot_status",
                "target_commit_sha",
                "head_commit",
                "active_graph_commit",
                "current_full_reconcile",
                "strategy",
                "scope_reconcile_strategy",
                "graph_delta_mode",
                "scope_graph_delta_mode",
                "activated",
                "candidate_only",
                "exact_candidate_snapshot",
                "resumed_candidate",
                "idempotent_replay",
                "rebuild_skipped",
                "elapsed_ms",
                "fallback_reason",
                "fallback_required",
                "operator_next_action",
                "zero_write_rejection",
            ),
        ),
        "request_id": request_id,
        "http_request_performed": True,
        "current_request_mutation_proven": current_request_mutated,
        "zero_write_proven": bool(
            explicit_zero_write and not current_request_mutated
        ),
        "write_disposition": (
            "written"
            if current_request_mutated
            else "not_written"
            if explicit_zero_write
            else "ambiguous"
        ),
        "safe_retry": bool(
            source.get("ok") is False
            and explicit_zero_write
            and not current_request_mutated
        ),
        "semantic_truncation_performed": False,
        "raw_materialization_trace_omitted": True,
        "raw_graph_payload_omitted": True,
        "raw_route_token_exposed": False,
        "raw_observer_session_token_exposed": False,
        "mutation_authority": {
            "schema_version": (
                "graph_current_full_reconcile.mutation_authority.v1"
            ),
            "db_total_changes_delta": max(
                0, int(db_total_changes_delta or 0)
            ),
            "db_write_proven": db_write_proven,
            "explicit_write_flag": explicit_write,
            "activation_write_proven": activation_write_proven,
            "timeline_write_proven": timeline_write_proven,
            "timeline_event_id": int(timeline_event.get("id") or 0),
            "provenance_id": str(provenance.get("provenance_id") or ""),
            "idempotent_replay": idempotent_replay,
            "source": "governance_http_request_connection",
        },
    }
    if current_request_mutated:
        compact["writes_performed"] = True
        compact["mutation_performed"] = True
    elif explicit_zero_write:
        compact["writes_performed"] = False
        compact["mutation_performed"] = False

    nested_fields = {
        "activation_verification": (
            "schema_version",
            "source",
            "requested",
            "verified",
            "active_snapshot_id",
            "active_graph_commit",
            "target_commit_sha",
            "head_commit",
            "matches_target_commit",
            "matches_head_commit",
            "pending_scope_reconcile_count",
            "pending_scope_reconcile_zero",
            "ref_name",
            "branch_ref",
            "worktree_id",
            "worktree_path",
        ),
        "activation": (
            "ok",
            "status",
            "snapshot_id",
            "active_snapshot_id",
            "previous_snapshot_id",
            "commit_sha",
            "projection_id",
            "projection_status",
            "graph_ref_event_id",
            "activated",
        ),
        "current_full_reconcile_provenance": (
            "schema_version",
            "provenance_id",
            "project_id",
            "snapshot_id",
            "target_commit_sha",
            "request_id",
            "reconcile_event_id",
            "route_bound",
            "status",
        ),
        "operation_trace": (
            "schema_version",
            "operation_id",
            "operation_type",
            "status",
            "target_commit_sha",
            "snapshot_id",
            "run_id",
            "elapsed_ms",
        ),
        "current_full_target_identity": (
            "schema_version",
            "authority_source",
            "ref_name",
            "branch_ref",
            "requested_ref_name",
            "requested_branch_ref",
            "canonicalized",
        ),
        "merge_queue_graph_epoch_auto_record": (
            "schema_version",
            "status",
            "recorded",
            "reason",
            "merge_queue_id",
            "queue_item_id",
            "snapshot_id",
            "projection_id",
        ),
        "post_commit_activation_events": ("published", "error"),
        "graph_stats": ("nodes", "edges", "files", "symbols"),
    }
    if timeline_event:
        compact["timeline_event_recorded"] = timeline_event
    for field, allowed in nested_fields.items():
        projected = _current_full_reconcile_http_public_fields(
            source.get(field), allowed
        )
        if projected:
            compact[field] = projected
    return compact


@route("POST", "/api/graph-governance/{project_id}/reconcile/current-full")
def handle_graph_governance_current_full_reconcile(ctx: RequestContext):
    """Build a candidate, then atomically activate it with route evidence."""
    project_id = ctx.get_project_id()
    body, manager_action = _consume_reconcile_terminalization_action(
        ctx.body if isinstance(ctx.body, Mapping) else {}
    )
    if manager_action is not None:
        from . import graph_snapshot_store as terminalization_store

        terminalization_conn = get_connection(project_id)
        try:
            terminalization_auth = _require_reconcile_terminalization_auth(
                ctx,
                terminalization_conn,
                str(manager_action.get("action") or ""),
            )
            route_scope = terminalization_auth.get("route_token_scope")
            route_scope = (
                dict(route_scope) if isinstance(route_scope, Mapping) else {}
            )
            if manager_action["action"] == _RECONCILE_RELEASE_PREFLIGHT_ACTION:
                from . import task_timeline as terminalization_timeline

                changes_before_prewarm = terminalization_conn.total_changes
                _prewarm_reconcile_terminalization_schemas(
                    terminalization_conn,
                    terminalization_store,
                    terminalization_timeline,
                )
                result = _graph_release_recovery_retention_preflight(
                    terminalization_conn,
                    terminalization_store,
                    project_id,
                    apply=bool(manager_action["apply"]),
                    backlog_id=str(route_scope.get("backlog_id") or ""),
                    task_id=str(route_scope.get("task_id") or ""),
                )
                schema_writes = (
                    terminalization_conn.total_changes > changes_before_prewarm
                )
                result["schema_migration_writes_performed"] = schema_writes
                result["writes_performed"] = bool(
                    result.get("writes_performed") or schema_writes
                )
                result.update(
                    {
                        "ok": True,
                        "action": _RECONCILE_RELEASE_PREFLIGHT_ACTION,
                        "maintenance_only": True,
                        "rebuild_started": False,
                        "snapshot_materialized": False,
                        "route_proof": {
                            "observer_session_id": str(
                                terminalization_auth.get("observer_session_id")
                                or ""
                            ),
                            "route_token_ref": str(
                                terminalization_auth.get("route_token_ref") or ""
                            ),
                            "scope": route_scope,
                            "allowed_actions": list(
                                terminalization_auth.get(
                                    "route_token_allowed_actions"
                                )
                                or []
                            ),
                            "raw_route_token_persisted": False,
                        },
                    }
                )
                return (201 if result["writes_performed"] else 200), result
            candidate = _resolve_reconcile_terminalization_candidate(
                terminalization_conn,
                terminalization_store,
                project_id,
                manager_action["candidate_id"],
            )
        finally:
            close = getattr(terminalization_conn, "close", None)
            if callable(close):
                close()
        append_receipt = _record_reconcile_run_terminalization(
            project_id,
            run_id=candidate["run_id"],
            snapshot_id=candidate["snapshot_id"],
            backlog_id=str(route_scope.get("backlog_id") or ""),
            task_id=str(route_scope.get("task_id") or ""),
        )
        receipt_fields = (
            "schema_version",
            "terminalization_id_sha256",
            "source_identity_sha256",
            "replacement_identity_sha256",
            "manager_certificate_hash",
            "ledger_hash",
            "timeline_event_hash",
            "writes_performed",
            "replayed",
            "server_derived",
        )
        safe_receipt = {
            key: append_receipt.get(key)
            for key in receipt_fields
            if key in append_receipt
        }
        writes_performed = safe_receipt.get("writes_performed") is True
        return (201 if writes_performed else 200), {
            "ok": True,
            "project_id": project_id,
            "action": _RECONCILE_TERMINALIZATION_ACTION,
            "candidate_id": manager_action["candidate_id"],
            "terminalization_only": True,
            "rebuild_started": False,
            "snapshot_materialized": False,
            "graph_reconciled": False,
            "receipt": safe_receipt,
            "route_proof": {
                "observer_session_id": str(
                    terminalization_auth.get("observer_session_id") or ""
                ),
                "route_token_ref": str(
                    terminalization_auth.get("route_token_ref") or ""
                ),
                "scope": route_scope,
                "allowed_actions": list(
                    terminalization_auth.get("route_token_allowed_actions") or []
                ),
                "raw_route_token_persisted": False,
            },
        }
    root = _graph_governance_project_root(project_id, body)
    from .state_reconcile import run_state_only_full_reconcile
    from . import graph_snapshot_store as store
    from .parallel_branch_runtime import (
        record_merge_queue_graph_epoch_after_reconcile,
    )

    request_started_at = _utc_now()
    request_started_monotonic = time.monotonic()
    conn = get_connection(project_id)
    request_total_changes_before = int(conn.total_changes)
    process_build_key: tuple[str, str] | None = None
    try:
        current_full_auth = _require_current_full_reconcile_auth(
            ctx,
            conn,
            "graph-governance.reconcile.current-full",
        )
        head_commit = _git_head_commit(root)
        target_commit = str(
            body.get("target_commit_sha")
            or body.get("commit_sha")
            or head_commit
            or ""
        ).strip()
        if not head_commit or not target_commit:
            return 400, {
                "ok": False,
                "project_id": project_id,
                "reason": "current_head_required",
                "message": "current-full reconcile requires a git HEAD commit",
                "head_commit": head_commit,
                "target_commit_sha": target_commit,
            }
        activate_requested = bool(body.get("activate", True))
        request_category = _current_full_reconcile_request_category(
            conn,
            request_context=ctx,
            project_id=project_id,
            body=body,
            auth=current_full_auth,
            target_commit_sha=target_commit,
        )
        source_free_reconcile_authority = request_category.get(
            "source_free_reconcile_authority"
        )
        direct_main_qa_preflight_authority = (
            _operator_supervised_direct_main_reconcile_qa_preflight_authority(
                conn,
                project_id=project_id,
                target_commit=target_commit,
                current_full_auth=current_full_auth,
            )
        )
        direct_graph_bootstrap_request = bool(
            request_category.get("category")
            == "operator_supervised_direct_main"
            and direct_main_qa_preflight_authority.get(
                "contract_runtime_next_line_id"
            )
            == "observer_graph_context"
        )
        dev_graph_bootstrap_authority = (
            _dev_direct_graph_bootstrap_reconcile_authority(
                conn,
                project_id=project_id,
                auth=current_full_auth,
                direct_main_qa_preflight=(
                    direct_main_qa_preflight_authority
                ),
                body=dict(body),
            )
            if direct_graph_bootstrap_request
            else {"applicable": False, "eligible": False, "accepted": False}
        )
        if (
            activate_requested
            and direct_main_qa_preflight_authority.get("applicable") is True
            and direct_main_qa_preflight_authority.get("mutation_allowed")
            is not True
            and dev_graph_bootstrap_authority.get("accepted") is not True
        ):
            return 409, {
                "ok": False,
                "project_id": project_id,
                "error": (
                    "operator_supervised_direct_main_qa_before_reconcile_required"
                ),
                "message": (
                    "Direct Main current-full reconcile requires either one "
                    "exact authenticated QA Fact or one exact open no-PASS "
                    "deposit generation before any graph mutation"
                ),
                "rebuild_started": False,
                "snapshot_materialized": False,
                "writes_performed": False,
                "mutation_performed": False,
                "fail_closed": True,
                "qa_preflight_authority": (
                    direct_main_qa_preflight_authority
                ),
            }
        requested_identity = store.normalize_pending_scope_identity(
            ref_name=str(body.get("ref_name") or ""),
            branch_ref=str(body.get("branch_ref") or ""),
        )
        # ``current-full`` is the canonical active-graph path surfaced by
        # graph_status.  A client-supplied run/branch label is trace metadata,
        # not a second graph-ref authority.  Routing the CAS through that label
        # makes graph_status report one active snapshot while activation reads
        # an unrelated (often empty) ref.  Materialize both candidate-only and
        # activating requests as active-target candidates so an exact candidate
        # remains resumable after QA or a failed CAS.
        identity = store.normalize_pending_scope_identity(ref_name="active")
        require_clean = True if not activate_requested else bool(body.get("require_clean", True))

        runtime_context_scope = _current_full_reconcile_runtime_context_scope(
            conn,
            project_id=project_id,
            body=body,
            auth=current_full_auth,
            target_commit_sha=target_commit,
            candidate_only=not activate_requested,
            source_free_reconcile_authority=(
                source_free_reconcile_authority
                if isinstance(source_free_reconcile_authority, Mapping)
                else {}
            ),
        )
        merge_queue_id = str(
            runtime_context_scope.get("merge_queue_id")
            or body.get("merge_queue_id")
            or ""
        ).strip()
        incomplete_fanin_descendant_verified = (
            _verify_incomplete_fanin_reconcile_target(
                conn,
                project_id=project_id,
                merge_queue_id=merge_queue_id,
                project_root=root,
                target_commit=target_commit,
                head_commit=head_commit,
            )
        )
        # All category, target/HEAD, Direct-QA, and runtime-scope decisions are
        # read-only and must complete before graph materialization can create
        # or alter schema.
        if dev_runtime_verify_only():
            admit_ac_dev_graph_materialization_schema(
                conn, project_id=project_id
            )
        queue_item_id = str(body.get("queue_item_id") or "").strip()
        run_id = str(body.get("run_id") or "").strip() or (
            f"current-full-{target_commit[:7]}"
        )
        route_evidence = _current_full_reconcile_route_evidence(
            current_full_auth,
            runtime_context_scope=runtime_context_scope,
        )
        if direct_main_qa_preflight_authority.get("applicable") is True:
            route_evidence = {
                **route_evidence,
                "direct_main_qa_preflight_authority": dict(
                    direct_main_qa_preflight_authority
                ),
            }
        if dev_graph_bootstrap_authority.get("accepted") is True:
            route_evidence = {
                **route_evidence,
                "dev_graph_bootstrap_reconcile_authority": dict(
                    dev_graph_bootstrap_authority
                ),
            }
        idempotency_scope = _current_full_reconcile_idempotency_scope(route_evidence)
        route_evidence = {
            **route_evidence,
            "reconcile_run_id": run_id,
            "idempotency_scope": idempotency_scope,
        }
        explicit_snapshot_id = str(body.get("snapshot_id") or "").strip()
        snapshot_identity = _current_full_requested_snapshot_identity(
            conn,
            project_id=project_id,
            target_commit_sha=target_commit,
            explicit_snapshot_id=explicit_snapshot_id,
        )
        if snapshot_identity.get("status") == "conflict":
            return 409, {
                "ok": False,
                "project_id": project_id,
                "error": snapshot_identity.get("reason"),
                "run_id": run_id,
                "target_commit_sha": target_commit,
                "rebuild_started": False,
                "fail_closed": True,
                **{
                    key: value
                    for key, value in snapshot_identity.items()
                    if key not in {"status", "reason"}
                },
            }
        requested_snapshot_id = str(
            snapshot_identity.get("snapshot_id") or ""
        ).strip()
        existing = _current_full_reconcile_existing_run(
            conn,
            store,
            project_id=project_id,
            run_id=run_id,
            target_commit_sha=target_commit,
            route_evidence=route_evidence,
            requested_snapshot_id=requested_snapshot_id,
        )
        if existing.get("status") == "conflict":
            return 409, {
                "ok": False,
                "project_id": project_id,
                "error": existing.get("reason"),
                "message": "current-full reconcile run_id is already bound to different durable state",
                "run_id": run_id,
                "rebuild_started": False,
                "fail_closed": True,
                **{key: value for key, value in existing.items() if key not in {"status", "reason"}},
            }
        if existing.get("status") == "incomplete_active":
            return 409, {
                "ok": False,
                "project_id": project_id,
                "error": existing.get("reason"),
                "message": (
                    "an active snapshot exists without the atomic terminal evidence for this run; "
                    "do not replay or synthesize evidence"
                ),
                "run_id": run_id,
                "snapshot_id": existing.get("snapshot_id") or "",
                "terminal_tuple_errors": list(
                    (
                        existing.get("terminal_tuple")
                        if isinstance(existing.get("terminal_tuple"), Mapping)
                        else {}
                    ).get("errors")
                    or []
                ),
                "terminal_tuple_scope_mismatch_fields": list(
                    (
                        existing.get("terminal_tuple")
                        if isinstance(existing.get("terminal_tuple"), Mapping)
                        else {}
                    ).get("timeline_scope_mismatch_fields")
                    or []
                ),
                "fail_closed": True,
                "next_legal_action": "file_or_resume_audited_system_repair",
            }
        if existing.get("status") == "complete":
            response = _current_full_reconcile_idempotent_response(
                existing,
                project_id=project_id,
                target_commit_sha=target_commit,
                head_commit=head_commit,
            )
            if activate_requested and target_commit == head_commit:
                existing_snapshot_id = str(
                    existing.get("snapshot_id") or ""
                ).strip()
                response["merge_queue_graph_epoch_auto_record"] = (
                    record_merge_queue_graph_epoch_after_reconcile(
                        conn,
                        project_id=project_id,
                        target_head_commit=target_commit,
                        snapshot_id=existing_snapshot_id,
                        projection_id=_current_full_reconcile_projection_id(
                            conn,
                            project_id=project_id,
                            snapshot_id=existing_snapshot_id,
                            result=(
                                existing.get("snapshot")
                                if isinstance(
                                    existing.get("snapshot"),
                                    Mapping,
                                )
                                else {}
                            ),
                        ),
                        merge_queue_id=merge_queue_id,
                        queue_item_id=queue_item_id,
                        incomplete_fanin_descendant_verified=(
                            incomplete_fanin_descendant_verified
                        ),
                        now_iso=_utc_now(),
                    )
                )
                conn.commit()
            response["historical_terminal_projection_replay"] = bool(
                target_commit != head_commit
            )
            return 200, response
        if existing.get("status") == "running":
            return 202, {
                "ok": True,
                "project_id": project_id,
                "status": "running",
                "run_id": run_id,
                "target_commit_sha": target_commit,
                "rebuild_started": False,
                "idempotent_replay": True,
                "next_legal_action": {
                    "action": "poll_graph_operations_queue",
                    "tool": "graph_operations_queue",
                    "run_id": run_id,
                    "retry_allowed": False,
                },
            }
        snapshot_existing = (
            existing
            if existing.get("status") == "candidate_ready"
            else _current_full_reconcile_existing_snapshot_identity(
                conn,
                store,
                project_id=project_id,
                run_id=run_id,
                target_commit_sha=target_commit,
                route_evidence=route_evidence,
                snapshot_id=requested_snapshot_id,
            )
        )
        if snapshot_existing.get("status") == "conflict":
            return 409, {
                "ok": False,
                "project_id": project_id,
                "error": snapshot_existing.get("reason"),
                "run_id": run_id,
                "snapshot_id": requested_snapshot_id,
                "rebuild_started": False,
                "fail_closed": True,
                **{
                    key: value
                    for key, value in snapshot_existing.items()
                    if key not in {"status", "reason", "run_id", "snapshot_id"}
                },
            }
        if snapshot_existing.get("status") == "complete":
            response = _current_full_reconcile_idempotent_response(
                snapshot_existing["terminal"],
                project_id=project_id,
                target_commit_sha=target_commit,
                head_commit=head_commit,
            )
            response["requested_run_id"] = run_id
            response["fresh_run_snapshot_resume"] = True
            if snapshot_existing.get("canonical_parent_snapshot_resume") is True:
                response["canonical_parent_snapshot_resume"] = True
                response["parent_snapshot_resume_authority"] = dict(
                    snapshot_existing.get("parent_snapshot_resume_authority")
                    if isinstance(
                        snapshot_existing.get("parent_snapshot_resume_authority"),
                        Mapping,
                    )
                    else {}
                )
            response["historical_terminal_projection_replay"] = bool(
                target_commit != head_commit
            )
            return 200, response
        resumed_candidate = snapshot_existing.get("status") == "candidate_ready"
        if resumed_candidate:
            existing = snapshot_existing
            if target_commit != head_commit:
                return 409, {
                    "ok": False,
                    "project_id": project_id,
                    "error": "current_full_historical_candidate_not_terminal",
                    "run_id": run_id,
                    "snapshot_id": requested_snapshot_id,
                    "rebuild_started": False,
                    "fail_closed": True,
                }

        # Only a terminal idempotent replay may target a commit that is no
        # longer the worktree HEAD.  That replay consumes the already-active
        # exact full snapshot plus its durable terminal provenance above; it
        # does not rebuild, reactivate, or synthesize timeline/provenance.
        if target_commit != head_commit:
            return 400, {
                "ok": False,
                "project_id": project_id,
                "error": "target_not_head",
                "message": "current-full reconcile rebuilds the current worktree; target_commit_sha must equal HEAD",
                "target_commit_sha": target_commit,
                "head_commit": head_commit,
                "terminal_idempotent_replay_checked": True,
            }
        dirty_paths = filter_dirty_files(_git_dirty_paths(root)) if require_clean else []
        if dirty_paths:
            return 409, {
                "ok": False,
                "project_id": project_id,
                "error": "dirty_worktree",
                "message": "current-full reconcile requires a clean worktree by default",
                "dirty_files": dirty_paths,
                "dirty_file_count": len(dirty_paths),
                "target_commit_sha": target_commit,
                "head_commit": head_commit,
            }

        semantic_use_ai = _semantic_use_ai_from_body(body)
        semantic_ai_call = _semantic_ai_call_from_body(project_id, root, body)
        notes_extra = (
            dict(body.get("notes_extra"))
            if isinstance(body.get("notes_extra"), Mapping)
            else {}
        )
        notes_extra.pop("current_full_reconcile", None)
        build_claim: dict[str, Any] = {}
        build_manager = _current_full_build_manager_identity(project_id)
        if resumed_candidate:
            snapshot_id = str(existing.get("snapshot_id") or "")
            result = {
                "ok": True,
                "project_id": project_id,
                "run_id": run_id,
                "commit_sha": target_commit,
                "snapshot_id": snapshot_id,
                "snapshot_status": "candidate",
                "projection_id": _current_full_existing_projection_id_read_only(
                    conn,
                    project_id=project_id,
                    snapshot_id=snapshot_id,
                ),
                "resumed_candidate": True,
                "candidate_origin_run_id": str(
                    existing.get("candidate_origin_run_id") or ""
                ),
                "rebuild_skipped": True,
            }
        else:
            conn.commit()
            process_build_key = _acquire_current_full_process_build_key(
                project_id, requested_snapshot_id
            )
            if process_build_key is None:
                return 409, {
                    "ok": False,
                    "project_id": project_id,
                    "error": "current_full_snapshot_build_claimed_in_process",
                    "run_id": run_id,
                    "snapshot_id": requested_snapshot_id,
                    "rebuild_started": False,
                    "fail_closed": True,
                }
            try:
                build_claim = store.acquire_current_full_build_claim(
                    conn,
                    project_id,
                    run_id=run_id,
                    snapshot_id=requested_snapshot_id,
                    commit_sha=target_commit,
                    manager_epoch=str(build_manager["generation_id"]),
                    manager_pid=int(build_manager["manager_pid"]),
                    manager_started_at=str(build_manager["manager_started_at"]),
                    manager_start_identity=str(
                        build_manager["manager_start_identity"]
                    ),
                    metric_evidence={
                        "phase": "materializing_candidate",
                        "activate_requested": activate_requested,
                        "idempotency_scope": idempotency_scope,
                        "request_id": str(ctx.request_id),
                        "manager_start_identity": str(
                            build_manager["manager_start_identity"]
                        ),
                    },
                    created_at=request_started_at,
                )
            except store.GraphSnapshotBuildClaimConflictError as exc:
                return 409, {
                    "ok": False,
                    "project_id": project_id,
                    "error": exc.reason,
                    "run_id": run_id,
                    "snapshot_id": requested_snapshot_id,
                    "claim_id": str(exc.claim.get("claim_id") or ""),
                    "claim_run_id": str(exc.claim.get("run_id") or ""),
                    "rebuild_started": False,
                    "fail_closed": True,
                }
            try:
                # Candidate persistence may outlive a client connection.  The
                # active ref is intentionally deferred to the final evidence
                # transaction below.
                result = run_state_only_full_reconcile(
                    conn,
                    project_id,
                    root,
                    run_id=run_id,
                    commit_sha=target_commit,
                    snapshot_id=requested_snapshot_id,
                    snapshot_kind="full",
                    created_by=str(body.get("actor") or "dashboard_user"),
                    activate=False,
                    expected_old_snapshot_id=body.get("expected_old_snapshot_id"),
                    ref_name=identity["ref_name"],
                    branch_ref=identity["branch_ref"],
                    notes_extra=notes_extra,
                    semantic_enrich=bool(body.get("semantic_enrich", True)),
                    semantic_use_ai=semantic_use_ai,
                    semantic_feedback_items=body.get("semantic_feedback_items") or body.get("feedback_items"),
                    semantic_feedback_round=body.get("semantic_feedback_round"),
                    semantic_max_excerpt_chars=(
                        int(body["semantic_max_excerpt_chars"])
                        if body.get("semantic_max_excerpt_chars") is not None
                        else None
                    ),
                    semantic_ai_call=semantic_ai_call,
                    semantic_ai_feature_limit=_semantic_ai_feature_limit_from_body(body),
                    **_semantic_ai_batch_kwargs_from_body(body),
                    **_semantic_state_kwargs_from_body(body),
                    semantic_classify_feedback=bool(
                        _semantic_bool_from_body(body, "semantic_classify_feedback", "classify_feedback", default=True)
                    ),
                    **_semantic_ai_config_kwargs_from_body(body),
                    **_semantic_selector_kwargs_from_body(body),
                    semantic_config_path=body.get("semantic_config_path"),
                    semantic_enqueue_stale=bool(body.get("enqueue_stale", False)),
                )
                conn.commit()
            except Exception as exc:
                conn.rollback()
                try:
                    store.terminalize_current_full_build_claim(
                        conn,
                        project_id,
                        claim_id=str(build_claim["claim_id"]),
                        run_id=run_id,
                        snapshot_id=requested_snapshot_id,
                        commit_sha=target_commit,
                        terminal_status="failed",
                        manager_start_identity=str(
                            build_manager["manager_start_identity"]
                        ),
                        metric_evidence={
                            "phase": "candidate_materialization_failed",
                            "error": str(exc),
                            "idempotency_scope": idempotency_scope,
                        },
                        created_at=request_started_at,
                    )
                except Exception as terminal_exc:
                    conn.rollback()
                    raise GovernanceError(
                        "current_full_build_failure_terminalization_failed",
                        "current-full build failed and its durable claim could not be terminalized",
                        500,
                        {
                            "run_id": run_id,
                            "snapshot_id": requested_snapshot_id,
                            "build_error": str(exc),
                            "terminalization_error": str(terminal_exc),
                            "durable_claim_left_active": True,
                            "fail_closed": True,
                        },
                    ) from terminal_exc
                if isinstance(exc, (KeyError, ValueError)):
                    _raise_graph_api_validation(exc)
                raise

            build_elapsed_ms = int(
                (time.monotonic() - request_started_monotonic) * 1000
            )
            failure_result = result if isinstance(result, Mapping) else {}
            result_snapshot_id = _current_full_reconcile_snapshot_id(failure_result)
            if (
                not isinstance(result, dict)
                or result.get("ok", True) is False
                or result_snapshot_id != requested_snapshot_id
            ):
                error = str(
                    failure_result.get("error")
                    or failure_result.get("reason")
                    or (
                        "current_full_candidate_snapshot_identity_mismatch"
                        if result_snapshot_id != requested_snapshot_id
                        else "invalid reconcile result"
                    )
                )
                store.terminalize_current_full_build_claim(
                    conn,
                    project_id,
                    claim_id=str(build_claim["claim_id"]),
                    run_id=run_id,
                    snapshot_id=requested_snapshot_id,
                    commit_sha=target_commit,
                    terminal_status="failed",
                    manager_start_identity=str(
                        build_manager["manager_start_identity"]
                    ),
                    elapsed_ms=build_elapsed_ms,
                    metric_evidence={
                        "phase": "candidate_materialization_rejected",
                        "error": error,
                        "idempotency_scope": idempotency_scope,
                    },
                    created_at=request_started_at,
                )
                if result_snapshot_id != requested_snapshot_id:
                    raise GovernanceError(
                        "current_full_candidate_snapshot_identity_mismatch",
                        "current-full builder returned a different snapshot identity",
                        500,
                        {
                            "run_id": run_id,
                            "requested_snapshot_id": requested_snapshot_id,
                            "actual_snapshot_id": result_snapshot_id,
                            "fail_closed": True,
                        },
                    )
                request_db_total_changes_delta = max(
                    0,
                    int(conn.total_changes) - request_total_changes_before,
                )
                return 201, _current_full_reconcile_bounded_http_response(
                    result,
                    request_id=str(ctx.request_id),
                    db_total_changes_delta=request_db_total_changes_delta,
                )
            store.terminalize_current_full_build_claim(
                conn,
                project_id,
                claim_id=str(build_claim["claim_id"]),
                run_id=run_id,
                snapshot_id=requested_snapshot_id,
                commit_sha=target_commit,
                terminal_status="candidate_ready",
                manager_start_identity=str(
                    build_manager["manager_start_identity"]
                ),
                elapsed_ms=build_elapsed_ms,
                trace_summary_path=str(
                    (result.get("trace") or {}).get("summary_path") or ""
                )
                if isinstance(result.get("trace"), Mapping)
                else "",
                metric_evidence={
                    "phase": "candidate_ready",
                    "activate_requested": activate_requested,
                    "idempotency_scope": idempotency_scope,
                    "request_id": str(ctx.request_id),
                    "claim_id": str(build_claim["claim_id"]),
                },
                created_at=request_started_at,
            )

        elapsed_ms = int((time.monotonic() - request_started_monotonic) * 1000)
        result = dict(result)
        result["status"] = result.get("status") or result.get("snapshot_status") or "complete"
        result["target_commit_sha"] = target_commit
        result["head_commit"] = head_commit
        result["current_full_reconcile"] = True
        result["strategy"] = "current_full_reconcile"
        result["scope_reconcile_strategy"] = "current_full_reconcile"
        result["graph_delta_mode"] = "full_rebuild"
        result["scope_graph_delta_mode"] = "full_rebuild"
        result["fallback_reason"] = ""
        result["fallback_required"] = False
        result["operator_next_action"] = ""
        result["elapsed_ms"] = int(result.get("elapsed_ms") or elapsed_ms)
        result["current_full_target_identity"] = {
            "schema_version": "graph_current_full_reconcile.target_identity.v1",
            "authority_source": "graph_status.active_snapshot_id",
            "ref_name": identity["ref_name"],
            "branch_ref": identity["branch_ref"],
            "requested_ref_name": str(body.get("ref_name") or ""),
            "requested_branch_ref": str(body.get("branch_ref") or ""),
            "canonicalized": bool(
                requested_identity["ref_name"] != identity["ref_name"]
                or requested_identity["branch_ref"] != identity["branch_ref"]
            ),
        }
        graph_epoch_snapshot_id = _current_full_reconcile_snapshot_id(result)
        if not graph_epoch_snapshot_id:
            raise GovernanceError(
                "current_full_reconcile_candidate_snapshot_required",
                "current-full reconcile did not produce a candidate snapshot id",
                500,
                {"run_id": run_id, "fail_closed": True},
            )
        result["operation_trace"] = _scope_reconcile_operation_trace(
            operation_type="current_full_reconcile",
            status=str(result.get("snapshot_status") or result.get("status") or "candidate"),
            target_commit_sha=target_commit,
            snapshot_id=graph_epoch_snapshot_id,
            run_id=run_id,
            identity=identity,
            result=result,
            elapsed_ms=int(result.get("elapsed_ms") or elapsed_ms),
            started_at=request_started_at,
            updated_at=_utc_now(),
        )
        if not activate_requested:
            result["activated"] = False
            result.setdefault("candidate_only", True)
            result["candidate_snapshot_id"] = graph_epoch_snapshot_id
            result["exact_candidate_snapshot"] = True
            result["next_action"] = _exact_candidate_snapshot_qa_retry_guidance(
                snapshot_id=graph_epoch_snapshot_id,
                target_commit_sha=target_commit,
            )
            if resumed_candidate:
                result["merge_queue_graph_epoch_auto_record"] = {
                    "status": "skipped",
                    "recorded": False,
                    "reason": "resumed_candidate_read_only",
                }
            elif merge_queue_id and queue_item_id:
                result["merge_queue_graph_epoch_auto_record"] = record_merge_queue_graph_epoch_after_reconcile(
                    conn,
                    project_id=project_id,
                    target_head_commit=target_commit,
                    snapshot_id=graph_epoch_snapshot_id,
                    projection_id=_current_full_reconcile_projection_id(
                        conn,
                        project_id=project_id,
                        snapshot_id=graph_epoch_snapshot_id,
                        result=result,
                    ),
                    merge_queue_id=merge_queue_id,
                    queue_item_id=queue_item_id,
                    activation_completed=False,
                    incomplete_fanin_descendant_verified=(
                        incomplete_fanin_descendant_verified
                    ),
                    now_iso=_utc_now(),
                )
            else:
                result["merge_queue_graph_epoch_auto_record"] = {
                    "status": "skipped",
                    "recorded": False,
                    "reason": "candidate_only_without_explicit_merge_queue_scope",
                }
            if not resumed_candidate:
                conn.commit()
            request_db_total_changes_delta = max(
                0,
                int(conn.total_changes) - request_total_changes_before,
            )
            return (
                200 if resumed_candidate else 201
            ), _current_full_reconcile_bounded_http_response(
                result,
                request_id=str(ctx.request_id),
                db_total_changes_delta=request_db_total_changes_delta,
            )

        from .db import sqlite_write_lock
        from .state_reconcile import (
            _full_reconcile_pending_scope_waiver_commits,
            _sync_project_registry_active_snapshot,
        )

        route_bound = bool(
            str(current_full_auth.get("role_source") or "")
            == "observer_session_route_token_ref"
        )
        # Every helper used after activation must avoid executescript-based
        # schema guards, because sqlite3.executescript implicitly commits the
        # current transaction.  Prewarm all required schemas before the
        # atomic block and use the schema_ready variants inside it.
        from . import graph_events as _graph_events
        from . import task_timeline as _task_timeline
        from .parallel_branch_runtime import ensure_branch_runtime_schema

        store.ensure_schema(conn)
        _graph_events.ensure_schema(conn)
        _task_timeline.ensure_schema(conn)
        ensure_branch_runtime_schema(conn)
        conn.commit()
        pending_rows = store.list_pending_scope_reconcile(
            conn,
            project_id,
            statuses=[
                store.PENDING_STATUS_QUEUED,
                store.PENDING_STATUS_RUNNING,
                store.PENDING_STATUS_FAILED,
            ],
            ref_name=identity["ref_name"],
            branch_ref=identity["branch_ref"],
            worktree_id="",
            worktree_path="",
        )
        pending_scope_commits = _full_reconcile_pending_scope_waiver_commits(
            root,
            pending_rows,
            target_commit,
        )
        graph_epoch_projection_id = _current_full_reconcile_projection_id(
            conn,
            project_id=project_id,
            snapshot_id=graph_epoch_snapshot_id,
            result=result,
        )
        conn.commit()
        try:
            with sqlite_write_lock():
                conn.execute("BEGIN IMMEDIATE")
                locked_run_identity = store.current_full_run_snapshot_identity_check(
                    conn,
                    project_id,
                    run_id=run_id,
                    snapshot_id=graph_epoch_snapshot_id,
                    commit_sha=target_commit,
                    idempotency_scope=idempotency_scope,
                )
                if locked_run_identity["conflict"]:
                    conn.rollback()
                    return 409, {
                        "ok": False,
                        "project_id": project_id,
                        "error": "current_full_run_snapshot_identity_conflict",
                        "run_id": run_id,
                        "snapshot_id": graph_epoch_snapshot_id,
                        "run_identity": locked_run_identity,
                        "rebuild_started": False,
                        "fail_closed": True,
                    }
                # Two same-run requests may both observe candidate_ready before
                # either acquires the SQLite writer lock.  Recheck terminal
                # state under the lock so only the winner can append reconcile
                # evidence; the loser returns the already committed result.
                locked_active = conn.execute(
                    "SELECT snapshot_id FROM graph_snapshot_refs "
                    "WHERE project_id = ? AND ref_name = ?",
                    (project_id, identity["ref_name"]),
                ).fetchone()
                locked_metric = conn.execute(
                    """
                    SELECT status FROM reconcile_run_metrics
                    WHERE project_id = ? AND run_id = ? AND snapshot_id = ?
                    """,
                    (project_id, run_id, graph_epoch_snapshot_id),
                ).fetchone()
                if (
                    locked_active
                    and str(locked_active["snapshot_id"] or "")
                    == graph_epoch_snapshot_id
                    and locked_metric
                    and str(locked_metric["status"] or "").lower()
                    == "complete"
                ):
                    conn.rollback()
                    terminal = _current_full_reconcile_existing_run(
                        conn,
                        store,
                        project_id=project_id,
                        run_id=run_id,
                        target_commit_sha=target_commit,
                        route_evidence=route_evidence,
                        requested_snapshot_id=explicit_snapshot_id,
                    )
                    if terminal.get("status") != "complete":
                        return 409, {
                            "ok": False,
                            "project_id": project_id,
                            "error": terminal.get("reason")
                            or "reconcile_terminal_evidence_incomplete",
                            "message": (
                                "the concurrent terminal reconcile is missing "
                                "durable atomic evidence; do not synthesize PASS"
                            ),
                            "run_id": run_id,
                            "snapshot_id": graph_epoch_snapshot_id,
                            "fail_closed": True,
                            "next_legal_action": (
                                "file_or_resume_audited_system_repair"
                            ),
                        }
                    return 200, _current_full_reconcile_idempotent_response(
                        terminal,
                        project_id=project_id,
                        target_commit_sha=target_commit,
                        head_commit=head_commit,
                    )
                locked_resume_tuple = store.current_full_candidate_tuple_from_db(
                    conn,
                    project_id=project_id,
                    run_id=run_id,
                    target_commit_sha=target_commit,
                    snapshot_id=graph_epoch_snapshot_id,
                )
                if not locked_resume_tuple.get("valid"):
                    conn.rollback()
                    return 409, {
                        "ok": False,
                        "project_id": project_id,
                        "error": "current_full_candidate_resume_tuple_invalid",
                        "run_id": run_id,
                        "snapshot_id": graph_epoch_snapshot_id,
                        "resume_tuple": locked_resume_tuple,
                        "rebuild_started": False,
                        "fail_closed": True,
                    }
                activation = store.activate_graph_snapshot(
                    conn,
                    project_id,
                    graph_epoch_snapshot_id,
                    expected_old_snapshot_id=body.get("expected_old_snapshot_id"),
                    ref_name=identity["ref_name"],
                    branch_ref=identity["branch_ref"],
                    actor=str(body.get("actor") or "dashboard_user"),
                    auto_rebuild_projection=False,
                    schema_ready=True,
                    post_commit_hooks=False,
                )
                pending_scope_waiver = {
                    "project_id": project_id,
                    "waived_count": 0,
                    "commit_shas": [],
                    "snapshot_id": graph_epoch_snapshot_id,
                }
                if pending_scope_commits:
                    pending_scope_waiver = store.waive_pending_scope_reconcile(
                        conn,
                        project_id,
                        commit_shas=pending_scope_commits,
                        ref_name=identity["ref_name"],
                        branch_ref=identity["branch_ref"],
                        worktree_id="",
                        worktree_path="",
                        snapshot_id=graph_epoch_snapshot_id,
                        actor=str(body.get("actor") or "dashboard_user"),
                        reason="full reconcile activated current graph snapshot",
                        evidence={
                            "source": "current_full_atomic_activation",
                            "run_id": run_id,
                            "target_commit_sha": target_commit,
                        },
                        schema_ready=True,
                    )
                # Snapshot companions are manager-owned.  SQLite cannot fence
                # arbitrary external filesystem writers, so paired exact
                # checks bracket activation and fail closed before evidence is
                # committed if manager-side materialization changes in between.
                post_activation_tuple = store.current_full_candidate_tuple_from_db(
                    conn,
                    project_id=project_id,
                    run_id=run_id,
                    target_commit_sha=target_commit,
                    snapshot_id=graph_epoch_snapshot_id,
                    expected_snapshot_status="active",
                )
                if not post_activation_tuple.get("valid"):
                    conn.rollback()
                    return 409, {
                        "ok": False,
                        "project_id": project_id,
                        "error": "current_full_candidate_resume_tuple_invalid",
                        "run_id": run_id,
                        "snapshot_id": graph_epoch_snapshot_id,
                        "validation_phase": "post_activation_precommit",
                        "resume_tuple": post_activation_tuple,
                        "rebuild_started": False,
                        "fail_closed": True,
                    }
                result["activation"] = activation
                result["pending_scope_waiver"] = pending_scope_waiver
                active_row = conn.execute(
                    """
                    SELECT s.*
                    FROM graph_snapshot_refs r
                    JOIN graph_snapshots s
                      ON s.project_id = r.project_id
                     AND s.snapshot_id = r.snapshot_id
                    WHERE r.project_id = ? AND r.ref_name = ?
                    """,
                    (project_id, identity["ref_name"]),
                ).fetchone()
                active_snapshot = dict(active_row) if active_row else {}
                active_graph_commit = str(active_snapshot.get("commit_sha") or "")
                active_snapshot_id = str(active_snapshot.get("snapshot_id") or "")
                pending_count = int(
                    conn.execute(
                        """
                        SELECT COUNT(*) FROM pending_scope_reconcile
                        WHERE project_id = ? AND status IN (?, ?, ?)
                        """,
                        (
                            project_id,
                            store.PENDING_STATUS_QUEUED,
                            store.PENDING_STATUS_RUNNING,
                            store.PENDING_STATUS_FAILED,
                        ),
                    ).fetchone()[0]
                )
                matches_target = active_graph_commit == target_commit
                matches_head = active_graph_commit == head_commit
                activation_verification = {
                    "schema_version": "scope_reconcile_activation_verification.v1",
                    "source": "atomic_transaction",
                    "requested": True,
                    "verified": bool(
                        matches_target and matches_head and pending_count == 0
                    ),
                    "active_snapshot_id": active_snapshot_id,
                    "active_graph_commit": active_graph_commit,
                    "target_commit_sha": target_commit,
                    "head_commit": head_commit,
                    "matches_target_commit": matches_target,
                    "matches_head_commit": matches_head,
                    "pending_scope_reconcile_count": pending_count,
                    "pending_scope_reconcile_zero": pending_count == 0,
                    "ref_name": str(identity.get("ref_name") or ""),
                    "branch_ref": str(identity.get("branch_ref") or ""),
                    "worktree_id": str(identity.get("worktree_id") or ""),
                    "worktree_path": str(identity.get("worktree_path") or ""),
                }
                result["activation_verification"] = activation_verification
                result["activated"] = bool(activation_verification.get("verified"))
                if not result["activated"]:
                    raise GovernanceError(
                        "current_full_reconcile_atomic_activation_not_verified",
                        "current-full activation verification failed before evidence commit",
                        409,
                        {
                            "run_id": run_id,
                            "snapshot_id": graph_epoch_snapshot_id,
                            "activation_verification": activation_verification,
                            "fail_closed": True,
                        },
                    )
                result["snapshot_status"] = "active"
                result["status"] = "complete"
                result["active_snapshot_id"] = activation_verification.get("active_snapshot_id") or ""
                result["active_graph_commit"] = activation_verification.get("active_graph_commit") or ""
                timeline_event = _record_pending_scope_reconcile_contract_event(
                    conn,
                    project_id=project_id,
                    body=body,
                    result=result,
                    target_commit_sha=target_commit,
                    runtime_context_scope=runtime_context_scope,
                    declared_actor_role=(
                        "observer"
                        if str(current_full_auth.get("role") or "").strip()
                        == "observer"
                        else ""
                    ),
                    post_commit_hooks=False,
                )
                if route_bound and not timeline_event:
                    raise GovernanceError(
                        "current_full_reconcile_atomic_timeline_required",
                        "route-bound current-full activation requires durable reconcile timeline evidence",
                        409,
                        {"run_id": run_id, "snapshot_id": graph_epoch_snapshot_id, "fail_closed": True},
                    )
                provenance = {}
                if timeline_event:
                    result["timeline_event_recorded"] = {
                        "id": timeline_event.get("id"),
                        "ref": f"timeline:{timeline_event.get('id')}",
                        "event_kind": timeline_event.get("event_kind"),
                        "phase": timeline_event.get("phase"),
                        "status": timeline_event.get("status"),
                        "requirement_id": "reconcile",
                    }
                    provenance = store.record_current_full_reconcile_provenance(
                        conn,
                        project_id=project_id,
                        snapshot_id=graph_epoch_snapshot_id,
                        target_commit_sha=target_commit,
                        request_id=str(ctx.request_id),
                        request_started_at=request_started_at,
                        route_evidence=route_evidence,
                        runtime_context_scope=runtime_context_scope,
                        reconcile_event_id=int(timeline_event.get("id") or 0),
                        reconcile_event_created_at=str(timeline_event.get("created_at") or ""),
                        marker_created_at=_utc_now(),
                        schema_ready=True,
                    )
                    result["current_full_reconcile_provenance"] = provenance
                if route_bound and not provenance:
                    raise GovernanceError(
                        "current_full_reconcile_atomic_provenance_required",
                        "route-bound current-full activation requires durable reconcile provenance",
                        409,
                        {"run_id": run_id, "snapshot_id": graph_epoch_snapshot_id, "fail_closed": True},
                    )
                store.record_reconcile_run_metric(
                    conn,
                    project_id,
                    run_id=run_id,
                    snapshot_id=graph_epoch_snapshot_id,
                    commit_sha=target_commit,
                    snapshot_kind="full",
                    strategy="current_full_reconcile",
                    graph_delta_mode="full_rebuild",
                    status="complete",
                    elapsed_ms=int(result.get("elapsed_ms") or elapsed_ms),
                    evidence={
                        "phase": "atomic_finalize_complete",
                        "activate_requested": True,
                        "idempotency_scope": idempotency_scope,
                        "request_id": str(ctx.request_id),
                        "reconcile_event_id": int(timeline_event.get("id") or 0) if timeline_event else 0,
                        "provenance_id": str(provenance.get("provenance_id") or ""),
                    },
                    created_at=request_started_at,
                    schema_ready=True,
                )
                conn.commit()
        except Exception as exc:
            conn.rollback()
            store.record_reconcile_run_metric(
                conn,
                project_id,
                run_id=run_id,
                snapshot_id=graph_epoch_snapshot_id,
                commit_sha=target_commit,
                snapshot_kind="full",
                strategy="current_full_reconcile",
                graph_delta_mode="full_rebuild",
                status="failed",
                elapsed_ms=int((time.monotonic() - request_started_monotonic) * 1000),
                evidence={
                    "phase": "atomic_finalize_failed",
                    "error": str(exc),
                    "candidate_preserved": True,
                    "idempotency_scope": idempotency_scope,
                },
                created_at=request_started_at,
            )
            conn.commit()
            raise

        if timeline_event:
            _task_timeline.run_post_commit_hooks(conn, timeline_event)
            conn.commit()

        # Queue-epoch propagation and advisory activation hooks run only after
        # the activation/evidence transaction is durable.  A failure here can
        # be safely answered by the same-run terminal lookup without creating
        # duplicate timeline or provenance rows.
        result["merge_queue_graph_epoch_auto_record"] = record_merge_queue_graph_epoch_after_reconcile(
            conn,
            project_id=project_id,
            target_head_commit=target_commit,
            snapshot_id=graph_epoch_snapshot_id,
            projection_id=graph_epoch_projection_id,
            merge_queue_id=merge_queue_id,
            queue_item_id=queue_item_id,
            incomplete_fanin_descendant_verified=(
                incomplete_fanin_descendant_verified
            ),
            now_iso=_utc_now(),
        )
        conn.commit()
        try:
            from . import event_bus

            event_bus.publish(
                "snapshot.activated",
                {
                    "project_id": project_id,
                    "snapshot_id": graph_epoch_snapshot_id,
                    "previous_snapshot_id": str(activation.get("previous_snapshot_id") or ""),
                    "commit_sha": target_commit,
                    "ref_name": identity["ref_name"],
                    "projection_status": activation.get("projection_status") or "skipped",
                    "graph_ref_event_id": activation.get("graph_ref_event_id") or "",
                    "source": "current_full_atomic_activation",
                },
            )
            event_bus.publish(
                "dashboard.changed",
                {
                    "project_id": project_id,
                    "path": "/api/graph-governance/{project_id}/reconcile/current-full",
                    "method": "POST",
                    "source": "current_full_atomic_activation",
                },
            )
            result["post_commit_activation_events"] = {"published": True}
        except Exception as exc:
            result["post_commit_activation_events"] = {
                "published": False,
                "error": str(exc),
            }
        try:
            with _CURRENT_FULL_BUILD_KEYS_LOCK:
                build_fence = _graph_release_build_fence_state(
                    conn,
                    project_id,
                    allowed_process_key=process_build_key,
                )
                if not build_fence["clear"]:
                    retention_gc = {
                        "ok": False,
                        "error": "graph_release_retention_build_fence_active",
                        "dry_run": False,
                    }
                else:
                    referenced_snapshot_ids = _graph_release_referenced_snapshot_ids(
                        conn,
                        project_id,
                    )
                    retention_gc = store.run_snapshot_retention_gc(
                        conn,
                        project_id,
                        dry_run=False,
                        actor=f"post_activate:{str(body.get('actor') or 'dashboard_user')}",
                        extra_bundle_snapshot_ids=referenced_snapshot_ids,
                    )
                    conn.commit()
        except Exception as exc:
            conn.rollback()
            retention_gc = {"ok": False, "error": str(exc), "dry_run": False}
        result["activation"]["retention_gc"] = retention_gc

        result["project_registry_activation"] = _sync_project_registry_active_snapshot(
            project_id,
            graph_epoch_snapshot_id,
            node_count=int((result.get("graph_stats") or {}).get("nodes") or 0) if isinstance(result.get("graph_stats"), Mapping) else None,
            ref_name=identity["ref_name"],
        )
        if runtime_context_scope:
            result["current_full_reconcile_runtime_context_scope"] = dict(runtime_context_scope)
        request_db_total_changes_delta = max(
            0,
            int(conn.total_changes) - request_total_changes_before,
        )
        return (
            200 if resumed_candidate else 201
        ), _current_full_reconcile_bounded_http_response(
            result,
            request_id=str(ctx.request_id),
            db_total_changes_delta=request_db_total_changes_delta,
        )
    finally:
        if process_build_key is not None:
            _release_current_full_process_build_key(process_build_key)
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/reconcile/pending-scope")
def handle_graph_governance_pending_scope_materialize(ctx: RequestContext):
    """Legacy recovery: create a state-only scope candidate and optionally activate.

    Normal operator Update Graph now uses /reconcile/current-full. This endpoint
    remains for internal/deprecated recovery when a specific pending-scope row
    must be inspected or retried.
    """
    project_id = ctx.get_project_id()
    body = ctx.body
    root = _graph_governance_project_root(project_id, body)
    from .state_reconcile import run_pending_scope_reconcile_candidate
    from . import graph_snapshot_store as store
    from .db import sqlite_write_lock
    semantic_use_ai = _semantic_use_ai_from_body(body)
    semantic_ai_call = _semantic_ai_call_from_body(project_id, root, body)
    identity = _pending_scope_identity_from_body(body)
    request_started_at = _utc_now()
    request_started_monotonic = time.monotonic()

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.reconcile.pending-scope")
        target_commit = str(body.get("target_commit_sha") or "").strip()
        target_commit_inferred = False
        if not target_commit:
            try:
                from . import batch_jobs
                target_commit = batch_jobs.git_commit(root)
                target_commit_inferred = bool(target_commit)
            except Exception:
                target_commit = ""
        if not target_commit:
            elapsed_ms = int((time.monotonic() - request_started_monotonic) * 1000)
            return 400, {
                "ok": False,
                "project_id": project_id,
                "reason": "target_commit_sha_required",
                "message": (
                    "target_commit_sha is required when governance cannot infer "
                    "the target git HEAD from the project root"
                ),
                "recommended_body": {
                    "target_commit_sha": "<git HEAD commit sha>",
                    "activate": True,
                    "semantic_use_ai": False,
                },
                "elapsed_ms": elapsed_ms,
                **identity,
            }
        target_pending_for_failure = False
        if target_commit and bool(body.get("ensure_pending_scope", True)):
            pending = store.list_pending_scope_reconcile(
                conn,
                project_id,
                commit_shas=[target_commit],
                ref_name=identity["ref_name"],
                branch_ref=identity["branch_ref"],
                worktree_id=identity["worktree_id"],
                worktree_path=identity["worktree_path"],
                statuses=[
                    store.PENDING_STATUS_QUEUED,
                    store.PENDING_STATUS_RUNNING,
                    store.PENDING_STATUS_FAILED,
                ],
            )
            if pending:
                target_pending_for_failure = True
                if bool(body.get("force_requeue", False)):
                    active = (
                        store.get_active_graph_snapshot(conn, project_id, ref_name=identity["ref_name"])
                        or store.get_active_graph_snapshot(conn, project_id)
                        or {}
                    )
                    parent_commit = str(
                        body.get("parent_commit_sha") or active.get("commit_sha") or ""
                    )
                    with sqlite_write_lock():
                        operation_trace = _scope_reconcile_operation_trace(
                            status=store.PENDING_STATUS_RUNNING,
                            target_commit_sha=target_commit,
                            parent_commit_sha=parent_commit,
                            identity=identity,
                            evidence={"strategy": "pending", "graph_delta_mode": "pending"},
                            started_at=request_started_at,
                        )
                        store.queue_pending_scope_reconcile(
                            conn,
                            project_id,
                            commit_sha=target_commit,
                            parent_commit_sha=parent_commit,
                            ref_name=identity["ref_name"],
                            branch_ref=identity["branch_ref"],
                            worktree_id=identity["worktree_id"],
                            worktree_path=identity["worktree_path"],
                            status=store.PENDING_STATUS_RUNNING,
                            evidence={
                                "source": "direct_update_graph_force_requeue",
                                "actor": body.get("actor", "api"),
                                "parent_commit_sha": parent_commit,
                                "started_at": request_started_at,
                                "operation_trace": operation_trace,
                                "reconcile_observability": {
                                    "strategy": "pending",
                                    "graph_delta_mode": "pending",
                                    "elapsed_ms": 0,
                                },
                                **identity,
                            },
                            force_requeue=True,
                        )
                        conn.commit()
            else:
                active = store.get_active_graph_snapshot(conn, project_id, ref_name=identity["ref_name"]) or {}
                if str(active.get("commit_sha") or "").strip() == target_commit:
                    elapsed_ms = int((time.monotonic() - request_started_monotonic) * 1000)
                    activation_verification = _pending_scope_activation_verification(
                        conn,
                        store,
                        project_id,
                        root=root,
                        target_commit_sha=target_commit,
                        activate_requested=bool(body.get("activate", False)),
                        identity=identity,
                    )
                    operation_trace = _scope_reconcile_operation_trace(
                        status="already_current",
                        target_commit_sha=target_commit,
                        snapshot_id=str(active.get("snapshot_id") or ""),
                        identity=identity,
                        result={"status": "already_current"},
                        elapsed_ms=elapsed_ms,
                        started_at=request_started_at,
                        updated_at=_utc_now(),
                    )
                    return 200, {
                        "ok": True,
                        "project_id": project_id,
                        "status": "already_current",
                        "reason": "already_current",
                        "target_commit_sha": target_commit,
                        "target_commit_inferred": target_commit_inferred,
                        **identity,
                        "snapshot_id": active.get("snapshot_id") or "",
                        "active_snapshot_id": active.get("snapshot_id") or "",
                        "pending_count": 0,
                        "elapsed_ms": elapsed_ms,
                        "strategy": "already_current",
                        "scope_reconcile_strategy": "already_current",
                        "graph_delta_mode": "none",
                        "scope_graph_delta_mode": "none",
                        "fallback_reason": "",
                        "fallback_required": False,
                        "operator_next_action": "",
                        "operation_trace": operation_trace,
                        "activation_verification": activation_verification,
                        "activated": bool(activation_verification.get("verified")),
                    }
                parent_active = active or store.get_active_graph_snapshot(conn, project_id) or {}
                parent_commit = str(
                    body.get("parent_commit_sha") or parent_active.get("commit_sha") or ""
                )
                with sqlite_write_lock():
                    operation_trace = _scope_reconcile_operation_trace(
                        status=store.PENDING_STATUS_RUNNING,
                        target_commit_sha=target_commit,
                        parent_commit_sha=parent_commit,
                        identity=identity,
                        evidence={"strategy": "pending", "graph_delta_mode": "pending"},
                        started_at=request_started_at,
                    )
                    row = store.queue_pending_scope_reconcile(
                        conn,
                        project_id,
                        commit_sha=target_commit,
                        parent_commit_sha=parent_commit,
                        ref_name=identity["ref_name"],
                        branch_ref=identity["branch_ref"],
                        worktree_id=identity["worktree_id"],
                        worktree_path=identity["worktree_path"],
                        status=store.PENDING_STATUS_RUNNING,
                        evidence={
                            "source": "direct_update_graph",
                            "actor": body.get("actor", "api"),
                            "parent_commit_sha": parent_commit,
                            "started_at": request_started_at,
                            "operation_trace": operation_trace,
                            "reconcile_observability": {
                                "strategy": "pending",
                                "graph_delta_mode": "pending",
                                "elapsed_ms": 0,
                            },
                            **identity,
                        },
                    )
                    _ = row
                    target_pending_for_failure = True
                    conn.commit()
        try:
            result = run_pending_scope_reconcile_candidate(
                conn,
                project_id,
                root,
                target_commit_sha=target_commit,
                run_id=str(body.get("run_id") or ""),
                snapshot_id=body.get("snapshot_id"),
                created_by=str(body.get("actor") or "observer"),
                ref_name=identity["ref_name"],
                branch_ref=identity["branch_ref"],
                worktree_id=identity["worktree_id"],
                worktree_path=identity["worktree_path"],
                # MF-2026-05-10-014: dashboard-driven incremental catchup
                # passes activate=true so the materialized snapshot becomes
                # active in one round-trip; MF-012 hook then auto-builds
                # the projection on activation.
                activate=bool(body.get("activate", False)),
                semantic_enrich=bool(body.get("semantic_enrich", True)),
                semantic_use_ai=semantic_use_ai,
                semantic_feedback_items=body.get("semantic_feedback_items") or body.get("feedback_items"),
                semantic_feedback_round=body.get("semantic_feedback_round"),
                semantic_max_excerpt_chars=(
                    int(body["semantic_max_excerpt_chars"])
                    if body.get("semantic_max_excerpt_chars") is not None
                    else None
                ),
                semantic_ai_call=semantic_ai_call,
                semantic_ai_feature_limit=_semantic_ai_feature_limit_from_body(body),
                **_semantic_ai_batch_kwargs_from_body(body),
                **_semantic_state_kwargs_from_body(body),
                semantic_classify_feedback=bool(
                    _semantic_bool_from_body(body, "semantic_classify_feedback", "classify_feedback", default=True)
                ),
                **_semantic_ai_config_kwargs_from_body(body),
                **_semantic_selector_kwargs_from_body(body),
                semantic_config_path=body.get("semantic_config_path"),
                # OPT-BACKLOG-MATERIALIZE-NO-WORKER-NOTIFY: default to NOT
                # auto-enqueueing stale nodes for AI on materialize. The
                # MF-016 in-process worker isn't notified by the persistence
                # path, so silent enqueues would just sit unfinished in
                # graph_semantic_jobs. Operators trigger enrichment
                # explicitly via POST /semantic/jobs (which DOES publish to
                # the EventBus). Caller can opt back into the legacy behavior
                # by passing `enqueue_stale: true` in the body.
                semantic_enqueue_stale=bool(body.get("enqueue_stale", False)),
            )
            if (
                isinstance(result, dict)
                and result.get("ok") is False
                and result.get("reason") == "no_pending_scope_reconcile"
                and target_commit
            ):
                active = store.get_active_graph_snapshot(conn, project_id, ref_name=identity["ref_name"]) or {}
                if str(active.get("commit_sha") or "").strip() == target_commit:
                    result = {
                        "ok": True,
                        "project_id": project_id,
                        "status": "already_current",
                        "reason": "already_current",
                        "target_commit_sha": target_commit,
                        "target_commit_inferred": target_commit_inferred,
                        **identity,
                        "snapshot_id": active.get("snapshot_id") or "",
                        "active_snapshot_id": active.get("snapshot_id") or "",
                        "pending_count": 0,
                    }
        except (KeyError, ValueError) as exc:
            if target_pending_for_failure:
                elapsed_ms = int((time.monotonic() - request_started_monotonic) * 1000)
                with sqlite_write_lock():
                    store.mark_pending_scope_reconcile_failed(
                        conn,
                        project_id,
                        commit_sha=target_commit,
                        ref_name=identity["ref_name"],
                        branch_ref=identity["branch_ref"],
                        worktree_id=identity["worktree_id"],
                        worktree_path=identity["worktree_path"],
                        actor=str(body.get("actor") or "api"),
                        reason=str(exc),
                        evidence={
                            "source": "direct_update_graph",
                            "error": str(exc),
                            "elapsed_ms": elapsed_ms,
                            "operation_trace": _scope_reconcile_operation_trace(
                                status=store.PENDING_STATUS_FAILED,
                                target_commit_sha=target_commit,
                                identity=identity,
                                evidence={"elapsed_ms": elapsed_ms},
                                elapsed_ms=elapsed_ms,
                                started_at=request_started_at,
                                updated_at=_utc_now(),
                            ),
                            **identity,
                        },
                    )
                    conn.commit()
            _raise_graph_api_validation(exc)
        except Exception as exc:
            if target_pending_for_failure:
                elapsed_ms = int((time.monotonic() - request_started_monotonic) * 1000)
                with sqlite_write_lock():
                    store.mark_pending_scope_reconcile_failed(
                        conn,
                        project_id,
                        commit_sha=target_commit,
                        ref_name=identity["ref_name"],
                        branch_ref=identity["branch_ref"],
                        worktree_id=identity["worktree_id"],
                        worktree_path=identity["worktree_path"],
                        actor=str(body.get("actor") or "api"),
                        reason=str(exc),
                        evidence={
                            "source": "direct_update_graph",
                            "error": str(exc),
                            "elapsed_ms": elapsed_ms,
                            "operation_trace": _scope_reconcile_operation_trace(
                                status=store.PENDING_STATUS_FAILED,
                                target_commit_sha=target_commit,
                                identity=identity,
                                evidence={"elapsed_ms": elapsed_ms},
                                elapsed_ms=elapsed_ms,
                                started_at=request_started_at,
                                updated_at=_utc_now(),
                            ),
                            **identity,
                        },
                    )
                    conn.commit()
            raise
        if isinstance(result, dict) and result.get("ok", True):
            result = dict(result)
            activate_requested = bool(body.get("activate", False))
            elapsed_ms = int((time.monotonic() - request_started_monotonic) * 1000)
            observability = _scope_reconcile_observability(
                result,
                elapsed_ms=elapsed_ms,
                status=str(result.get("status") or result.get("snapshot_status") or "complete"),
            )
            result.update(observability)
            result["elapsed_ms"] = observability["elapsed_ms"] or elapsed_ms
            result["operation_trace"] = _scope_reconcile_operation_trace(
                status=str(result.get("status") or result.get("snapshot_status") or "complete"),
                target_commit_sha=target_commit,
                parent_commit_sha=str(body.get("parent_commit_sha") or ""),
                snapshot_id=str(result.get("snapshot_id") or result.get("active_snapshot_id") or ""),
                run_id=str(result.get("run_id") or body.get("run_id") or ""),
                identity=identity,
                result=result,
                elapsed_ms=int(result.get("elapsed_ms") or elapsed_ms),
                started_at=request_started_at,
                updated_at=_utc_now(),
            )
            if activate_requested:
                activation_verification = _pending_scope_activation_verification(
                    conn,
                    store,
                    project_id,
                    root=root,
                    target_commit_sha=target_commit,
                    activate_requested=True,
                    identity=identity,
                )
                result["activation_verification"] = activation_verification
                result["activated"] = bool(activation_verification.get("verified"))
                if activation_verification.get("verified"):
                    result["snapshot_status"] = "active"
                    result["active_snapshot_id"] = activation_verification.get("active_snapshot_id") or ""
                    result["active_graph_commit"] = activation_verification.get("active_graph_commit") or ""
                else:
                    result["snapshot_status"] = "activation_unverified"
                    result["next_action"] = {
                        "schema_version": "graph_reconcile_next_action.v1",
                        "action": "verify_graph_current",
                        "description": (
                            "activate=true was requested, but active graph status "
                            "has not confirmed active_graph_commit == HEAD with "
                            "pending_scope_reconcile_count == 0."
                        ),
                        "endpoint": f"/api/graph-governance/{project_id}/status",
                        "method": "GET",
                    }
            else:
                snapshot_id = str(result.get("snapshot_id") or "")
                result.setdefault("snapshot_status", "candidate")
                result.setdefault("candidate_only", True)
                result["activated"] = False
                if snapshot_id:
                    active = (
                        store.get_active_graph_snapshot(conn, project_id, ref_name=identity["ref_name"])
                        or store.get_active_graph_snapshot(conn, project_id)
                        or {}
                    )
                    result.setdefault(
                        "next_action",
                        _candidate_snapshot_finalize_guidance(
                            project_id,
                            snapshot_id=snapshot_id,
                            target_commit_sha=target_commit,
                            expected_old_snapshot_id=str(active.get("snapshot_id") or ""),
                            actor=str(body.get("actor") or "observer"),
                            identity=identity,
                        ),
                    )
            if isinstance(result.get("operation_trace"), dict):
                result["operation_trace"]["activated"] = bool(result.get("activated"))
                if isinstance(result.get("activation_verification"), dict):
                    result["operation_trace"]["activation_verification"] = result[
                        "activation_verification"
                    ]
            timeline_event = _record_pending_scope_reconcile_contract_event(
                conn,
                project_id=project_id,
                body=body,
                result=result,
                target_commit_sha=target_commit,
            )
            if timeline_event:
                result["timeline_event_recorded"] = {
                    "id": timeline_event.get("id"),
                    "ref": f"timeline:{timeline_event.get('id')}",
                    "event_kind": timeline_event.get("event_kind"),
                    "phase": timeline_event.get("phase"),
                    "status": timeline_event.get("status"),
                    "requirement_id": "reconcile",
                }
        conn.commit()
        return 201, result
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/reconcile/pending-scope/catch-up")
def handle_graph_governance_pending_scope_catch_up(ctx: RequestContext):
    """Queue active..HEAD commits and materialize them through scope reconcile."""
    project_id = ctx.get_project_id()
    body = ctx.body
    root = _graph_governance_project_root(project_id, body)
    from .state_reconcile import run_pending_scope_reconcile_candidate
    from . import graph_snapshot_store as store
    from .db import sqlite_write_lock
    identity = _pending_scope_identity_from_body(body)

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.reconcile.pending-scope.catch-up")
        active = (
            store.get_active_graph_snapshot(conn, project_id, ref_name=identity["ref_name"])
            or store.get_active_graph_snapshot(conn, project_id)
            or {}
        )
        base_commit = str(body.get("base_commit_sha") or active.get("commit_sha") or "").strip()
        target_commit = str(body.get("target_commit_sha") or _git_head_commit(root) or "").strip()
        explicit_commits = [
            str(item or "").strip()
            for item in (body.get("commit_shas") or [])
            if str(item or "").strip()
        ]
        commit_shas = explicit_commits or _git_commit_range(root, base_commit, target_commit)
        if target_commit and commit_shas and commit_shas[-1] != target_commit:
            commit_shas.append(target_commit)
        if not commit_shas:
            return 200, {
                "ok": True,
                "project_id": project_id,
                "status": "already_current",
                "base_commit_sha": base_commit,
                "target_commit_sha": target_commit,
                **identity,
                "commit_count": 0,
                "commits": [],
            }
        if target_commit != _git_head_commit(root):
            return 400, {
                "ok": False,
                "error": "target_not_head",
                "message": "pending-scope catch-up materializes the current worktree; target_commit_sha must equal HEAD",
                "target_commit_sha": target_commit,
                "head_commit": _git_head_commit(root),
            }
        if bool(body.get("dry_run", False)):
            return 200, {
                "ok": True,
                "project_id": project_id,
                "dry_run": True,
                "base_commit_sha": base_commit,
                "target_commit_sha": target_commit,
                **identity,
                "commit_count": len(commit_shas),
                "commits": commit_shas,
                "progress": {"done": 0, "total": len(commit_shas)},
            }

        queued_rows: list[dict[str, Any]] = []
        parent = base_commit
        with sqlite_write_lock():
            for index, commit in enumerate(commit_shas, start=1):
                row = store.queue_pending_scope_reconcile(
                    conn,
                    project_id,
                    commit_sha=commit,
                    parent_commit_sha=parent,
                    ref_name=identity["ref_name"],
                    branch_ref=identity["branch_ref"],
                    worktree_id=identity["worktree_id"],
                    worktree_path=identity["worktree_path"],
                    status=store.PENDING_STATUS_QUEUED,
                    evidence={
                        "source": "pending_scope_catch_up",
                        "actor": body.get("actor", "api"),
                        "index": index,
                        "total": len(commit_shas),
                        "base_commit_sha": base_commit,
                        "target_commit_sha": target_commit,
                        **identity,
                    },
                    force_requeue=bool(body.get("force_requeue", False)),
                )
                queued_rows.append(row)
                parent = commit
            conn.commit()

        try:
            result = run_pending_scope_reconcile_candidate(
                conn,
                project_id,
                root,
                target_commit_sha=target_commit,
                run_id=str(body.get("run_id") or f"scope-catch-up-{target_commit[:7]}"),
                snapshot_id=body.get("snapshot_id"),
                created_by=str(body.get("actor") or "observer"),
                ref_name=identity["ref_name"],
                branch_ref=identity["branch_ref"],
                worktree_id=identity["worktree_id"],
                worktree_path=identity["worktree_path"],
                activate=bool(body.get("activate", True)),
                semantic_enrich=bool(body.get("semantic_enrich", True)),
                semantic_use_ai=_semantic_use_ai_from_body(body),
                semantic_ai_call=_semantic_ai_call_from_body(project_id, root, body),
                semantic_enqueue_stale=bool(body.get("enqueue_stale", False)),
            )
        except Exception as exc:
            with sqlite_write_lock():
                store.mark_pending_scope_reconcile_failed(
                    conn,
                    project_id,
                    commit_sha=target_commit,
                    ref_name=identity["ref_name"],
                    branch_ref=identity["branch_ref"],
                    worktree_id=identity["worktree_id"],
                    worktree_path=identity["worktree_path"],
                    actor=str(body.get("actor") or "api"),
                    reason=str(exc),
                    evidence={"source": "pending_scope_catch_up", "error": str(exc), **identity},
                )
                conn.commit()
            raise

        return 201, {
            "ok": bool(result.get("ok")),
            "project_id": project_id,
            "base_commit_sha": base_commit,
            "target_commit_sha": target_commit,
            **identity,
            "commit_count": len(commit_shas),
            "commits": [
                {
                    "index": index,
                    "commit_sha": commit,
                    "queued_status": queued_rows[index - 1].get("status", "") if index - 1 < len(queued_rows) else "",
                    "covered": commit in set(result.get("covered_commit_shas") or []),
                }
                for index, commit in enumerate(commit_shas, start=1)
            ],
            "progress": {
                "done": len(result.get("covered_commit_shas") or []),
                "total": len(commit_shas),
            },
            "materialize": result,
        }
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/reconcile/backfill-escape")
def handle_graph_governance_backfill_escape(ctx: RequestContext):
    """Activate a HEAD full snapshot and waive stuck pending scope rows."""
    project_id = ctx.get_project_id()
    body = ctx.body
    root = _graph_governance_project_root(project_id, body)
    from .state_reconcile import run_backfill_escape_hatch

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.reconcile.backfill-escape")
        try:
            result = run_backfill_escape_hatch(
                conn,
                project_id,
                root,
                target_commit_sha=str(body.get("target_commit_sha") or ""),
                run_id=str(body.get("run_id") or ""),
                snapshot_id=body.get("snapshot_id"),
                created_by=str(body.get("actor") or "observer"),
                reason=str(body.get("reason") or ""),
                expected_old_snapshot_id=body.get("expected_old_snapshot_id"),
            )
        except ValueError as exc:
            _raise_graph_api_validation(exc)
        conn.commit()
        return 201, result
    finally:
        conn.close()


@route("POST", "/api/graph-governance/{project_id}/snapshots/{snapshot_id}/finalize")
def handle_graph_governance_snapshot_finalize(ctx: RequestContext):
    """Activate a candidate graph snapshot with compare-and-swap signoff."""
    project_id = ctx.get_project_id()
    snapshot_id = ctx.path_params["snapshot_id"]
    body = ctx.body
    from . import graph_snapshot_store as store
    from .db import sqlite_write_lock
    identity = _pending_scope_identity_from_body(body)

    conn = get_connection(project_id)
    try:
        _require_graph_governance_operator(ctx, conn, "graph-governance.snapshot.finalize")
        with sqlite_write_lock():
            try:
                result = store.finalize_graph_snapshot(
                    conn,
                    project_id,
                    snapshot_id,
                    target_commit_sha=str(body.get("target_commit_sha") or ""),
                    expected_old_snapshot_id=body.get("expected_old_snapshot_id"),
                    ref_name=identity["ref_name"],
                    branch_ref=identity["branch_ref"],
                    worktree_id=identity["worktree_id"],
                    worktree_path=identity["worktree_path"],
                    actor=str(body.get("actor") or "observer"),
                    materialize_pending=bool(body.get("materialize_pending", True)),
                    covered_commit_shas=body.get("covered_commit_shas") or None,
                    evidence=body.get("evidence") if isinstance(body.get("evidence"), dict) else None,
                )
            except store.GraphSnapshotConflictError as exc:
                _raise_graph_api_conflict(exc)
            except (KeyError, ValueError) as exc:
                _raise_graph_api_validation(exc)
            conn.commit()
        return {"ok": True, **result}
    finally:
        conn.close()


