def _publish_event(event_name, payload):
    """Best-effort event publish to event bus (mirrors auto_chain pattern)."""
    try:
        from . import event_bus
        event_bus._bus.publish(event_name, payload)
    except Exception:
        pass


def _publish_current_task_changed(
    project_id: str,
    *,
    backlog_id: str = "",
    task_id: str = "",
    source: str = "",
    runtime_state: str = "",
    event_id: Any = "",
    contract_execution_id: str = "",
    contract_chain_id: str = "",
    contract_revision_id: str = "",
    execution_state_revision: int = 0,
    runtime_context_id: str = "",
) -> None:
    payload = {
        "project_id": project_id,
        "backlog_id": backlog_id,
        "task_id": task_id,
        "source": source,
        "runtime_state": runtime_state,
        "event_id": event_id,
        "ts": datetime.now(timezone.utc).isoformat(),
    }
    for key, value in (
        ("contract_execution_id", contract_execution_id),
        ("contract_chain_id", contract_chain_id),
        ("contract_revision_id", contract_revision_id),
        ("runtime_context_id", runtime_context_id),
    ):
        if value:
            payload[key] = value
    if execution_state_revision:
        payload["execution_state_revision"] = int(execution_state_revision)
    _publish_event("current_task.changed", payload)


def _publish_contract_runtime_current_changed(
    project_id: str,
    *,
    backlog_id: str,
    record: Mapping[str, Any],
    source: str,
) -> None:
    """Invalidate Activity Current after one accepted runtime revision."""

    current = _runtime_current_state_from_record(record)
    execution_id = str(current.get("contract_execution_id") or "")
    chain_id = str(current.get("contract_chain_id") or "")
    revision_id = str(current.get("contract_revision_id") or "")
    revision = int(current.get("execution_state_revision") or 0)
    next_action = (
        current.get("next_legal_action")
        if isinstance(current.get("next_legal_action"), Mapping)
        else {}
    )
    runtime_context_id = str(next_action.get("runtime_context_id") or "")
    task_id = str(next_action.get("task_id") or "")
    payload = {
        "project_id": project_id,
        "backlog_id": backlog_id,
        "task_id": task_id,
        "source": source,
        "runtime_state": str(current.get("readiness_state") or "recorded"),
        "contract_execution_id": execution_id,
        "contract_chain_id": chain_id,
        "contract_revision_id": revision_id,
        "execution_state_revision": revision,
        "runtime_context_id": runtime_context_id,
        "event_id": f"contract-runtime:{execution_id}:rev:{revision}",
        "ts": datetime.now(timezone.utc).isoformat(),
    }
    _publish_event("contract_runtime.changed", payload)
    if chain_id:
        _publish_event("contract_chain.current_changed", payload)
    if runtime_context_id:
        _publish_event("runtime_context.changed", payload)
    _publish_current_task_changed(
        project_id,
        backlog_id=backlog_id,
        task_id=task_id,
        source=source,
        runtime_state=payload["runtime_state"],
        event_id=payload["event_id"],
        contract_execution_id=execution_id,
        contract_chain_id=chain_id,
        contract_revision_id=revision_id,
        execution_state_revision=revision,
        runtime_context_id=runtime_context_id,
    )


def _publish_accepted_contract_runtime_line_write(
    project_id: str,
    *,
    result: Mapping[str, Any],
) -> None:
    """Publish one post-commit invalidation from a line-write facade result."""

    record = result.get("record")
    if not result.get("ok") or not isinstance(record, Mapping):
        return
    _onboard_guide_capsule_invalidate_contract_runtime_transition(
        project_id=project_id,
        result=result,
    )
    _publish_contract_runtime_current_changed(
        project_id,
        backlog_id=str(record.get("backlog_id") or ""),
        record=record,
        source="contract_runtime.line_write.accepted",
    )


_ROUTE_TOKEN_TASK_CREATE_TYPES = {"dev", "test", "qa", "gatekeeper", "merge", "deploy"}
_ROUTE_GATE_PAYLOAD_KEYS = (
    "route_token",
    "route_token_ref",
    "route_waiver",
    "route_token_waiver",
    "protected_route_waiver",
)


def _body_with_metadata_route_gate(body: dict, metadata: dict | None = None) -> dict:
    payload = dict(body or {})
    if isinstance(metadata, dict):
        if not payload.get("route_token") and metadata.get("route_token"):
            payload["route_token"] = metadata.get("route_token")
        if not payload.get("route_token_ref") and metadata.get("route_token_ref"):
            payload["route_token_ref"] = metadata.get("route_token_ref")
        if not payload.get("route_waiver") and metadata.get("route_waiver"):
            payload["route_waiver"] = metadata.get("route_waiver")
        if not payload.get("route_token_waiver") and metadata.get("route_token_waiver"):
            payload["route_token_waiver"] = metadata.get("route_token_waiver")
    return payload


def _stable_public_hash(value: Any) -> str:
    payload = json.dumps(value, sort_keys=True, separators=(",", ":"), default=str)
    return "sha256:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _route_gate_public_summary(gate: Mapping[str, Any] | None) -> dict[str, Any]:
    if not isinstance(gate, Mapping) or not gate:
        return {}
    allowed = {
        "schema_version",
        "allowed",
        "status",
        "action",
        "decision",
        "route_id",
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
        "visible_injection_manifest_hash",
        "caller_role",
        "route_token_hash",
        "waiver_hash",
        "source_event_gate_hash",
        "expires_at",
        "evidence_refs",
        "timeline_evidence",
        "source_event_refs",
        "server_issued_binding",
        "resolved_from_ref",
        "registry_verified",
        "route_token_ref",
        "binding_source",
        "scope",
        "required_fields",
        "protected_lane",
        "legal_next_action",
        "next_legal_action",
        "server_minted",
        "bootstrap_gate_decision",
        "first_run_bootstrap",
    }
    summary = {key: gate.get(key) for key in allowed if gate.get(key) not in (None, "", [], {})}
    route_identity = gate.get("route_identity")
    if isinstance(route_identity, Mapping):
        summary["route_identity"] = _route_identity_public_summary(route_identity)
    summary["server_projected"] = True
    summary["projection_source"] = "server_route_token_mutation_gate"
    return summary


def _route_token_input_redaction_summary(body: Mapping[str, Any]) -> dict[str, Any]:
    token = body.get("route_token") if isinstance(body, Mapping) else None
    if isinstance(token, str):
        try:
            token = json.loads(token)
        except Exception:
            token = {"unparseable": True}
    if not isinstance(token, Mapping) or not token:
        return {}
    scope = token.get("scope") if isinstance(token.get("scope"), Mapping) else {}
    return {
        "schema_version": "route_token_input_redaction.v1",
        "decision": "route_token_input_redacted",
        "route_token_hash": _stable_public_hash(token),
        "route_context_hash": str(token.get("route_context_hash") or ""),
        "prompt_contract_id": str(token.get("prompt_contract_id") or ""),
        "prompt_contract_hash": str(token.get("prompt_contract_hash") or ""),
        "caller_role": str(token.get("caller_role") or token.get("role") or ""),
        "evidence_refs": [
            str(item)
            for item in (
                token.get("evidence_refs")
                if isinstance(token.get("evidence_refs"), list)
                else []
            )
            if str(item)
        ],
        "scope": {
            "project_id": str(token.get("project_id") or scope.get("project_id") or ""),
            "backlog_id": str(
                token.get("backlog_id")
                or token.get("bug_id")
                or scope.get("backlog_id")
                or scope.get("bug_id")
                or ""
            ),
            "task_id": str(token.get("task_id") or scope.get("task_id") or ""),
        },
    }


def _timeline_payload_with_route_gate(
    body: dict,
    route_gate: Mapping[str, Any] | None = None,
) -> dict:
    payload_value = body.get("payload") if isinstance(body, dict) else {}
    payload = dict(payload_value) if isinstance(payload_value, dict) else {}
    payload.pop("source_backed_contract_gate_authority", None)
    payload.pop("contract_gate_decision", None)
    event_type = str(body.get("event_type", "") if isinstance(body, dict) else "")
    if event_type.startswith("service.route.") or payload.get("service_router_suppress") is True:
        return payload
    for key in _ROUTE_GATE_PAYLOAD_KEYS:
        if key == "route_token" and body.get(key):
            if not payload.get("route_token_gate"):
                payload["route_token_gate"] = (
                    _route_gate_public_summary(route_gate)
                    or _route_token_input_redaction_summary(body)
                )
            continue
        if not payload.get(key) and body.get(key):
            payload[key] = body.get(key)
    if route_gate:
        route_gate_summary = _route_gate_public_summary(route_gate)
        payload["route_token_gate"] = route_gate_summary
        from . import task_timeline as _task_timeline

        payload["source_backed_contract_gate_authority"] = (
            _task_timeline.source_backed_route_gate_authority(route_gate_summary)
        )
    return payload


_ROUTE_ACTION_SCOPE_LINEAGE_KEYS = (
    "route_action_scope_lineage",
    "action_scope_route_lineage",
    "route_token_action_scope_lineage",
    "server_route_lineage",
)


def _strip_route_action_scope_lineage_value(
    value: Any,
    depth: int = 0,
    active_container_ids: set[int] | None = None,
) -> Any:
    if not isinstance(value, (Mapping, list)):
        return value
    if (
        depth > _TIMELINE_GATE_PUBLIC_SANITIZER_MAX_DEPTH
        or id(value) in (active_container_ids or set())
    ):
        return {} if isinstance(value, Mapping) else []
    active_ids = active_container_ids if active_container_ids is not None else set()
    active_ids.add(id(value))
    try:
        if isinstance(value, Mapping):
            return {
                key: _strip_route_action_scope_lineage_value(
                    child,
                    depth + 1,
                    active_ids,
                )
                for key, child in value.items()
                if key not in _ROUTE_ACTION_SCOPE_LINEAGE_KEYS
            }
        return [
            _strip_route_action_scope_lineage_value(item, depth + 1, active_ids)
            for item in value
        ]
    finally:
        active_ids.remove(id(value))


def _strip_caller_route_action_scope_lineage(payload: Mapping[str, Any]) -> dict[str, Any]:
    stripped = _strip_route_action_scope_lineage_value(dict(payload))
    return dict(stripped) if isinstance(stripped, Mapping) else {}


_SERVER_PROJECTED_TIMELINE_KEYS = frozenset(
    {
        "contract_gate_decision",
        "meta_contract_gate",
        "observer_direct_pre_mutation_authority",
        "observer_failure_domain_authority",
        "source_backed_contract_gate_authority",
        *_ROUTE_ACTION_SCOPE_LINEAGE_KEYS,
    }
)
