def _contract_runtime_fresh_repair_canonical_envelope_sources(
    value: Mapping[str, Any],
    *,
    validated_authority_context: Mapping[str, Any],
) -> tuple[str, ...]:
    """Resolve a unique canonical source from its validated static inventory."""

    keys = {str(key or "").strip() for key in value}
    if len(keys) < 2 or "" in keys:
        return ()
    candidates = tuple(
        source_name
        for source_name, dispositions in validated_authority_context[
            "field_dispositions_by_source"
        ].items()
        if keys.issubset(dispositions)
    )
    return candidates if len(candidates) == 1 else ()


def _contract_runtime_monotone_disposition_join(
    dispositions: Sequence[Any],
    *,
    diagnostic_path: str,
) -> str:
    """Join closed authority dispositions without permitting demotion."""

    precedence = {
        "audited_non_authority": 0,
        "recursive_container": 1,
        "authority_leaf": 2,
    }
    normalized = tuple(dispositions)
    if not normalized:
        return ""
    if any(type(value) is not str or value not in precedence for value in normalized):
        _contract_runtime_raise_canonical_authority_registry_incomplete(
            [diagnostic_path]
        )
    return max(normalized, key=precedence.__getitem__)


def _contract_runtime_key_is_execution_authority_or_credential(
    key: Any,
    *,
    canonical_source_names: Sequence[str] = (),
    validated_authority_context: Mapping[str, Any] | None = None,
) -> bool:
    """Classify keys that cannot cross a retired execution generation."""

    key_name = str(key or "").strip()
    context = validated_authority_context or (
        _contract_runtime_require_canonical_authority_registry_complete()
    )
    source_dispositions = tuple(
        disposition
        for source_name in canonical_source_names
        if (
            disposition := context["field_dispositions_by_source"]
            .get(source_name, {})
            .get(key_name)
        )
    )
    global_disposition = context["global_compatibility_index"].get(key_name)
    if canonical_source_names and len(source_dispositions) != len(
        canonical_source_names
    ):
        _contract_runtime_raise_canonical_authority_registry_incomplete(
            [
                f"{source_name}.{key_name}"
                for source_name in canonical_source_names
                if key_name
                not in context["field_dispositions_by_source"].get(
                    source_name, {}
                )
            ]
        )
    if global_disposition is None and not source_dispositions:
        # Arbitrary acceptance prose may contain application-specific keys.
        # Only the validated global index can classify an unscoped key.
        return False
    disposition = _contract_runtime_monotone_disposition_join(
        (*source_dispositions, global_disposition)
        if global_disposition is not None
        else source_dispositions,
        diagnostic_path=f"global_compatibility_index.{key_name}",
    )
    return disposition in {"authority_leaf", "recursive_container"}


def _contract_runtime_unsafe_execution_authority_paths(
    value: Any,
    *,
    root_path: str,
) -> list[str]:
    """Return key paths carrying retired authority without copying values."""

    unsafe_paths: list[str] = []
    authority_context = (
        _contract_runtime_require_canonical_authority_registry_complete()
    )
    canonical_collection_sources = {
        source_name: frozenset(fields)
        for source_name, fields in authority_context["scalar_source_fields"].items()
    }

    def collect(child: Any, path: str) -> None:
        if isinstance(child, Mapping):
            canonical_source_names = (
                _contract_runtime_fresh_repair_canonical_envelope_sources(
                    child,
                    validated_authority_context=authority_context,
                )
            )
            for raw_key, nested in child.items():
                key = str(raw_key or "").strip()
                nested_path = f"{path}.{key}" if key else path
                if canonical_source_names:
                    missing_source_fields = [
                        f"{source_name}.{key}"
                        for source_name in canonical_source_names
                        if key
                        not in canonical_collection_sources.get(
                            source_name,
                            (),
                        )
                        or key
                        not in authority_context["field_dispositions_by_source"].get(
                            source_name, {}
                        )
                    ]
                    if missing_source_fields:
                        _contract_runtime_raise_canonical_authority_registry_incomplete(
                            missing_source_fields
                        )
                if _contract_runtime_key_is_execution_authority_or_credential(
                    key,
                    canonical_source_names=canonical_source_names,
                    validated_authority_context=authority_context,
                ):
                    unsafe_paths.append(nested_path)
                    continue
                collect(nested, nested_path)
        elif isinstance(child, (list, tuple)):
            for index, nested in enumerate(child):
                collect(nested, f"{path}[{index}]")

    collect(value, root_path)
    return sorted(set(unsafe_paths))


def _caller_timeline_key_is_server_projected(key: Any) -> bool:
    compact = re.sub(r"[^a-z0-9]+", "", str(key or "").casefold())
    return compact in _SERVER_PROJECTED_TIMELINE_KEY_COMPACT_DENYLIST


def _strip_caller_server_projected_timeline_value(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {
            key: _strip_caller_server_projected_timeline_value(child)
            for key, child in value.items()
            if not _caller_timeline_key_is_server_projected(key)
            and not _caller_timeline_key_is_credential(key)
        }
    if isinstance(value, list):
        return [
            _strip_caller_server_projected_timeline_value(item)
            for item in value
        ]
    return value


def _timeline_event_has_action_scope_verification_marker(
    body: Mapping[str, Any],
    event: Mapping[str, Any],
) -> bool:
    tokens: set[str] = set()
    for value in (
        event.get("event_type"),
        event.get("event_kind"),
        event.get("phase"),
        body.get("event_type"),
        body.get("event_kind"),
        body.get("phase"),
    ):
        text = str(value or "").strip().lower().replace("-", "_")
        if not text:
            continue
        tokens.add(text)
        tokens.update(
            part
            for part in re.split(r"[._:/\s]+", text)
            if part
        )
    payload = body.get("payload")
    if isinstance(payload, Mapping):
        for key in payload.keys():
            tokens.add(str(key).strip().lower().replace("-", "_"))
    return bool(
        tokens.intersection(
            {
                "bounded_implementation_worker_dispatch",
                "close_ready",
                "dispatch_bounded_worker",
                "finish_gate",
                "implementation",
                "independent_verification",
                "independent_verification_lane",
                "independent_qa",
                "mf_subagent_dispatch",
                "mf_subagent_dispatch_gate",
                "mf_subagent_finish_gate",
                "mf_subagent_startup",
                "mf_subagent_startup_adoption",
                "mf_subagent_startup_adoption_gate",
                "mf_subagent_startup_gate",
                "qa",
                "qa_lane",
                "qa_review",
                "qa_verification",
                "verification",
            }
        )
    )


def _route_gate_lineage_mapping(
    route_gate: Mapping[str, Any],
    public_key: str,
) -> dict[str, Any]:
    value = route_gate.get(public_key)
    if isinstance(value, Mapping):
        return dict(value)
    route_lineage = route_gate.get("route_lineage")
    if isinstance(route_lineage, Mapping):
        nested = route_lineage.get(public_key)
        if isinstance(nested, Mapping):
            return dict(nested)
    return {}


@_bounded_close_helper(lambda _: "")
def _deep_route_public_text(value: Any, field: str) -> str:
    if isinstance(value, Mapping):
        if field in value and str(value.get(field) or "").strip():
            return str(value.get(field) or "").strip()
        for key, child in value.items():
            if key in _ROUTE_ACTION_SCOPE_LINEAGE_KEYS:
                continue
            found = _deep_route_public_text(child, field)
            if found:
                return found
    if isinstance(value, list):
        for item in value:
            found = _deep_route_public_text(item, field)
            if found:
                return found
    return ""


def _route_request_identity_value(body: Mapping[str, Any], field: str) -> str:
    if not isinstance(body, Mapping):
        return ""
    direct = str(body.get(field) or "").strip()
    if direct:
        return direct
    for key in ("payload", "verification", "artifact_refs"):
        value = body.get(key)
        if isinstance(value, Mapping):
            found = _deep_route_public_text(
                _strip_route_action_scope_lineage_value(value),
                field,
            )
            if found:
                return found
    route_identity = body.get("route_identity")
    if isinstance(route_identity, Mapping):
        return str(route_identity.get(field) or "").strip()
    return ""


def _server_route_action_scope_lineage(
    body: Mapping[str, Any],
    event: Mapping[str, Any],
    route_gate: Mapping[str, Any] | None,
) -> dict[str, Any]:
    if not isinstance(route_gate, Mapping) or not route_gate:
        return {}
    if not _timeline_event_has_action_scope_verification_marker(body, event):
        return {}
    status = str(
        route_gate.get("status") or route_gate.get("decision") or ""
    ).strip().lower()
    gate_passed = bool(
        route_gate.get("allowed")
        or route_gate.get("accepted")
        or status in {"accepted", "ok", "passed", "succeeded", "success", "allowed"}
    )
    server_backed = bool(
        route_gate.get("resolved_from_ref")
        or route_gate.get("server_issued_binding")
        or route_gate.get("registry_verified")
        or str(route_gate.get("binding_source") or "").strip()
        == "observer_route_token_refs"
    )
    route_token_ref = str(
        route_gate.get("route_token_ref") or body.get("route_token_ref") or ""
    ).strip()
    parent_lineage = _route_gate_lineage_mapping(route_gate, "parent_route_lineage")
    child_lineage = _route_gate_lineage_mapping(route_gate, "child_route_lineage")
    if not (
        gate_passed
        and server_backed
        and route_token_ref
        and parent_lineage
        and child_lineage
    ):
        return {}

    return {
        "schema_version": "route_action_scope_lineage.v1",
        "accepted": True,
        "status": "accepted",
        "source": "server_route_token_action_scope",
        "acceptance_source": "server_route_token_action_scope",
        "projected_by": "handle_task_timeline_append",
        "server_projected": True,
        "allowed_action": "task_timeline_append",
        "server_issued_binding": bool(route_gate.get("server_issued_binding")),
        "registry_verified": True,
        "resolved_from_ref": bool(route_gate.get("resolved_from_ref")),
        "binding_source": str(route_gate.get("binding_source") or "")
        or "observer_route_token_refs",
        "route_token_ref": route_token_ref,
        "parent_route_identity": _route_identity_public_summary(parent_lineage),
        "child_route_identity": _route_identity_public_summary(child_lineage),
        "parent_route_lineage": parent_lineage,
        "child_route_lineage": child_lineage,
        "route_token_gate": _route_gate_public_summary(route_gate),
    }


def _resolve_route_token_ref_server_side(
    body: dict,
    *,
    pid: str,
    backlog_id: str = "",
    task_id: str = "",
    route_id: str = "",
    route_context_hash: str = "",
    prompt_contract_id: str = "",
    renew_within_seconds: int | None = None,
) -> dict | None:
    """Attempt server-side resolution of a route_token_ref in the request body.

    Returns the public token surface dict (ready to be injected as ``route_token``
    in the gate payload) if and only if:
    - The body contains ``route_token_ref`` but NO full ``route_token``.
    - The ref resolves to an active, non-expired, identity-matching entry.

    Returns ``None`` in all other cases (unknown ref, missing ref, body already
    has a full token). The caller must treat a ``None`` result as requiring the
    full-token path (no weakening of existing gate behavior).

    Fails closed: any ``RouteTokenRefError`` from the registry is re-raised so
    the caller can surface it as a gate failure.

    F2-BINDING: ``route_id`` and ``route_context_hash`` are forwarded from the
    request context into ``resolve_route_token_ref`` so that identity-binding
    checks are enforced.  A ref whose stored identity does not match the request
    route context will raise ``RouteTokenRefError`` (fails closed).
    """
    from . import observer_route_context as _orc

    if body.get("route_token"):
        # Full token present — ref resolution is not needed; leave body unchanged.
        return None

    route_token_ref = str(body.get("route_token_ref") or "").strip()
    if not route_token_ref:
        return None

    try:
        from .db import get_connection as _get_conn
        conn = _get_conn(pid)
    except Exception:
        return None

    try:
        resolved = _orc.resolve_route_token_ref(
            conn,
            project_id=pid,
            storage_project_id=_route_registry_storage_project_id(pid),
            route_token_ref=route_token_ref,
            backlog_id=backlog_id,
            task_id=task_id,
            route_id=route_id,
            route_context_hash=route_context_hash,
            prompt_contract_id=prompt_contract_id,
            renew_within_seconds=(
                _orc.ROUTE_TOKEN_REF_RENEW_WITHIN_SECONDS
                if renew_within_seconds is None
                else renew_within_seconds
            ),
        )
    finally:
        try:
            conn.close()
        except Exception:
            pass

    return resolved


def _verify_route_token_binding_server_side(
    body: dict,
    *,
    pid: str,
    backlog_id: str = "",
    task_id: str = "",
    route_id: str = "",
    route_context_hash: str = "",
    prompt_contract_id: str = "",
) -> dict | None:
    """Verify a full route_token against active server-side registry rows."""
    from . import observer_route_context as _orc

    raw_token = body.get("route_token") if isinstance(body, dict) else None
    if not raw_token:
        return None
    token = raw_token
    if isinstance(raw_token, str):
        try:
            token = json.loads(raw_token)
        except json.JSONDecodeError as exc:
            raise _orc.RouteTokenRefError(
                "route_token binding requires a JSON object token"
            ) from exc
    if not isinstance(token, dict):
        raise _orc.RouteTokenRefError(
            "route_token binding requires a full token mapping"
        )

    explicit_ref = str(
        token.get("route_token_ref") or body.get("route_token_ref") or ""
    ).strip()
    try:
        from .db import get_connection as _get_conn
        conn = _get_conn(pid)
    except Exception as exc:
        raise _orc.RouteTokenRefError(
            "route_token_ref registry unavailable; server-issued binding refused"
        ) from exc

    try:
        return _orc.verify_route_token_binding(
            conn,
            project_id=pid,
            storage_project_id=_route_registry_storage_project_id(pid),
            token=token,
            route_token_ref=explicit_ref,
            backlog_id=backlog_id,
            task_id=task_id,
            route_id=route_id,
            route_context_hash=route_context_hash,
            prompt_contract_id=prompt_contract_id,
        )
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _route_token_mutation_gate_failure_details(
    *,
    action: str,
    reason: str,
    details: Mapping[str, Any] | None = None,
    route_proof_supplied: bool = False,
) -> dict[str, Any]:
    """Complete protected-route failures with a public-safe retry contract."""

    protected_action = str(action or "").strip()
    field = "route_token_ref" if not route_proof_supplied else "route_proof"
    expected = (
        "active_server_registered_route_token_ref_authorizing_"
        f"{protected_action}"
    )
    actual = (
        "missing_or_empty"
        if not route_proof_supplied
        else "invalid_or_incomplete"
    )
    enriched = dict(details or {})
    route_ref_error_code = str(
        enriched.get("route_token_ref_error_code") or ""
    ).strip()
    if route_ref_error_code:
        field = "route_token_ref"
        actual = route_ref_error_code
    source = "server._require_route_token_mutation_gate.prewrite_gate.v1"
    guide = {
        "schema_version": "protected_route_mutation_gate.correction.v1",
        "action": "issue_or_renew_route_ref_then_retry_exact_action",
        "issue": {
            "mcp_tool": "observer_route_context_issue",
            "required_allowed_actions": [protected_action],
            "preserve_scope_fields": ["project_id", "backlog_id", "task_id"],
        },
        "renew": {
            "mcp_tool": "observer_route_context_renew",
            "allowed_only_for_same_or_narrower_scope": True,
            "required_allowed_actions": [protected_action],
        },
        "retry": {
            "mcp_tool": protected_action,
            "protected_action": protected_action,
            "same_world": True,
            "exact_request": True,
            "replace_only_corrected_route_proof_fields": True,
        },
        "instruction": (
            "issue a server-registered route ref authorizing the exact protected "
            f"action {protected_action}, or renew the same/narrower scope, then "
            "retry the exact rejected request in this world"
        ),
    }
    enriched.update(
        {
            "field": field,
            "expected": expected,
            "actual": actual,
            "field_mismatches": [
                {"field": field, "expected": expected, "actual": actual}
            ],
            "guide": guide,
            "source": source,
            "host_correctable": True,
            "public_safe": True,
            "secret_safe": True,
            "zero_write_rejection": True,
            "writes_performed": False,
            "mutation_performed": False,
            "retry_same_world_allowed": True,
            "raw_route_token_required": False,
            "raw_route_token_exposed": False,
        }
    )
    if reason:
        enriched["reason"] = reason
    return enriched


def _require_route_token_mutation_gate(
    ctx: RequestContext,
    *,
    action: str,
    project_id: str | None = None,
    backlog_id: str = "",
    task_id: str = "",
    metadata: dict | None = None,
) -> dict:
    from .mf_subagent_contract import (
        MfSubagentContractError,
        route_token_required_failure_details,
        validate_route_token_mutation_gate,
    )
    from . import observer_route_context as _orc

    pid = project_id if project_id is not None else ctx.get_project_id()
    body = _body_with_metadata_route_gate(ctx.body or {}, metadata)

    # --- Ref-resolution fast path -------------------------------------------
    # When the caller supplies route_token_ref WITHOUT a full route_token,
    # attempt server-side resolution.  The resolved surface is injected as
    # route_token so the existing validate_route_token_mutation_gate logic runs
    # unchanged.  resolved_from_ref=True is added to the gate result so callers
    # can distinguish the two passing forms.
    # Fails closed: RouteTokenRefError surfaces as a 422 gate failure just like
    # an invalid full token.
    #
    # F2-BINDING: extract route_id and route_context_hash from the request body
    # (protected appends carry both in their payload/route_token scope) and
    # forward them into the resolution call so that identity-binding checks are
    # actually enforced.  An identity-mismatched ref will raise RouteTokenRefError
    # (fail closed) instead of silently skipping the check.
    # Also check nested route_token / route_waiver structures for the fields.
    _rt_scope = body.get("route_token") if isinstance(body.get("route_token"), dict) else {}
    if _rt_scope:
        _req_route_id = str(_rt_scope.get("route_id") or "").strip()
        _req_route_context_hash = str(_rt_scope.get("route_context_hash") or "").strip()
        _req_prompt_contract_id = str(_rt_scope.get("prompt_contract_id") or "").strip()
    else:
        _req_route_id = _route_request_identity_value(body, "route_id")
        _req_route_context_hash = _route_request_identity_value(body, "route_context_hash")
        _req_prompt_contract_id = _route_request_identity_value(body, "prompt_contract_id")
    if not _req_route_id:
        _req_route_id = str(_rt_scope.get("route_id") or "").strip()
    if not _req_route_context_hash:
        _req_route_context_hash = str(_rt_scope.get("route_context_hash") or "").strip()
    if not _req_prompt_contract_id:
        _req_prompt_contract_id = str(_rt_scope.get("prompt_contract_id") or "").strip()
    resolved_from_ref: bool = False
    server_binding: dict | None = None
    try:
        if body.get("route_token"):
            server_binding = _verify_route_token_binding_server_side(
                body,
                pid=pid,
                backlog_id=backlog_id,
                task_id=task_id,
                route_id=_req_route_id,
                route_context_hash=_req_route_context_hash,
                prompt_contract_id=_req_prompt_contract_id,
            )
        else:
            resolved = _resolve_route_token_ref_server_side(
                body,
                pid=pid,
                backlog_id=backlog_id,
                task_id=task_id,
                route_id=_req_route_id,
                route_context_hash=_req_route_context_hash,
                prompt_contract_id=_req_prompt_contract_id,
            )
            if resolved is not None:
                resolved_from_ref = True
                server_binding = {
                    **dict(resolved),
                    "server_issued_binding": True,
                    "binding_source": "observer_route_token_refs",
                }
                # Inject the resolved public surface as route_token; gate validates it.
                body = dict(body)
                body["route_token"] = resolved
    except _orc.RouteTokenRefError as exc:
        details = route_token_required_failure_details(action=action, reason=str(exc))
        details.update(
            _route_token_ref_error_details(
                exc,
                project_id=pid,
                backlog_id=backlog_id,
                task_id=task_id,
                route_token_ref=str(body.get("route_token_ref") or "").strip(),
            )
        )
        details = _route_token_mutation_gate_failure_details(
            action=action,
            reason=str(exc),
            details=details,
            route_proof_supplied=bool(
                body.get("route_token_ref") or body.get("route_token")
            ),
        )
        raise GovernanceError(
            "route_token_required",
            str(exc),
            422,
            details,
        ) from exc

    try:
        result = validate_route_token_mutation_gate(
            body,
            action=action,
            project_id=pid,
            backlog_id=backlog_id,
            task_id=task_id,
            require_server_binding=bool(server_binding),
            server_binding=server_binding,
        )
    except MfSubagentContractError as exc:
        details = route_token_required_failure_details(action=action, reason=str(exc))
        if "route_waiver requires timeline evidence" in str(exc):
            details.update(_route_waiver_timeline_evidence_diagnostic())
        details = _route_token_mutation_gate_failure_details(
            action=action,
            reason=str(exc),
            details=details,
            route_proof_supplied=bool(
                body.get("route_token_ref") or body.get("route_token")
            ),
        )
        raise GovernanceError(
            "route_token_required",
            str(exc),
            422,
            details,
        ) from exc

    if resolved_from_ref:
        result = dict(result)
        result["decision"] = "route_token_ref_resolved"
        result["resolved_from_ref"] = True
    if server_binding:
        result = dict(result)
        result["route_token_ref"] = str(server_binding.get("route_token_ref") or "")
        result["server_issued_binding"] = True
        result["registry_verified"] = True
        result["binding_source"] = (
            str(server_binding.get("binding_source") or "")
            or "observer_route_token_refs"
        )
        for key in (
            "route_id",
            "route_context_hash",
            "prompt_contract_id",
            "prompt_contract_hash",
            "visible_injection_manifest_hash",
        ):
            value = str(server_binding.get(key) or "").strip()
            if value:
                result[key] = value
        for key in ("parent_route_lineage", "child_route_lineage", "route_lineage"):
            value = server_binding.get(key)
            if isinstance(value, Mapping):
                result[key] = dict(value)

    return result


def _optional_route_token_mutation_gate(
    ctx: RequestContext,
    *,
    action: str,
    project_id: str | None = None,
    backlog_id: str = "",
    task_id: str = "",
    metadata: dict | None = None,
) -> dict:
    body = _body_with_metadata_route_gate(ctx.body or {}, metadata)
    has_ref_only = bool(
        not body.get("route_token")
        and body.get("route_token_ref")
    )
    if not _body_has_route_token_input(body) and not _body_has_route_waiver(body) and not has_ref_only:
        return {}
    return _require_route_token_mutation_gate(
        ctx,
        action=action,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
        metadata=metadata,
    )


def _route_bootstrap_handoff(
    body: Mapping[str, Any],
    *,
    action: str,
    project_id: str,
    first_run: bool = False,
) -> dict[str, Any]:
    payload = body if isinstance(body, Mapping) else {}
    route_identity = (
        payload.get("route_identity")
        or payload.get("claimed_route_identity")
        or payload.get("command_route_identity")
        or payload.get("observer_command_route_identity")
        or payload.get("route_context")
        or {}
    )
    if not isinstance(route_identity, Mapping):
        route_identity = {}
    identity = _route_identity_public_summary(
        {
            **{
                key: payload.get(key)
                for key in (
                    "route_id",
                    "route_context_hash",
                    "prompt_contract_id",
                    "prompt_contract_hash",
                    "route_token_ref",
                    "visible_injection_manifest_hash",
                )
                if payload.get(key)
            },
            **dict(route_identity),
        }
    )
    return {
        "schema_version": "route_bootstrap_handoff.v1",
        "action": action,
        "project_id": project_id,
        "route_identity": identity,
        "first_run": bool(first_run),
        "server_minted_first_run_binding_available": bool(first_run),
        "route_token_required_before_bootstrap": not bool(first_run),
        "raw_prompt_persisted": False,
        "raw_route_token_persisted": False,
        "next_legal_action": (
            "server_mint_first_run_bootstrap_binding"
            if first_run and not identity
            else
            "supply_a_bound_route_token_before_project_bootstrap"
        ),
    }


def _body_has_route_waiver(body: dict | None) -> bool:
    payload = body or {}
    return any(payload.get(key) for key in (
        "route_waiver",
        "route_token_waiver",
        "protected_route_waiver",
    ))


def _body_has_usable_route_token(body: dict | None) -> bool:
    token = (body or {}).get("route_token")
    if isinstance(token, str):
        try:
            token = json.loads(token)
        except Exception:
            token = {}
    if not isinstance(token, Mapping):
        return False
    return bool(
        token.get("route_id")
        and token.get("route_context_hash")
        and token.get("prompt_contract_id")
    )


def _body_has_route_token_input(body: dict | None) -> bool:
    payload = body or {}
    return bool(
        payload.get("route_token")
        or str(payload.get("route_token_ref") or "").strip()
    )


def _route_waiver_payload(body: dict | None) -> dict:
    payload = body or {}
    waiver = (
        payload.get("route_waiver")
        or payload.get("route_token_waiver")
        or payload.get("protected_route_waiver")
    )
    if isinstance(waiver, str):
        try:
            waiver = json.loads(waiver)
        except Exception:
            waiver = {}
    return dict(waiver) if isinstance(waiver, Mapping) else {}


def _route_waiver_identity_mismatch(
    route_context_gate: dict,
    waiver: dict,
) -> list[str]:
    route_identity = route_context_gate.get("route_identity")
    if not isinstance(route_identity, Mapping) or not route_identity:
        return []
    mismatched: list[str] = []
    for field in (
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
        "route_token_ref",
    ):
        expected = str(route_identity.get(field) or "").strip()
        supplied = str(waiver.get(field) or "").strip()
        if supplied and expected and supplied != expected:
            mismatched.append(field)
    return mismatched


def _route_identity_public_summary(value: Mapping[str, Any] | None) -> dict[str, str]:
    if not isinstance(value, Mapping):
        return {}
    summary: dict[str, str] = {}
    for field in (
        "route_id",
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
        "route_token_ref",
        "visible_injection_manifest_hash",
    ):
        text = str(value.get(field) or "").strip()
        if text:
            summary[field] = text
    return summary


def _backlog_close_route_waiver_identity_block(
    route_gate: Mapping[str, Any],
    timeline_gate: Mapping[str, Any],
    body: Mapping[str, Any],
) -> dict[str, Any]:
    if str(route_gate.get("decision") or "") != "route_waiver":
        return {}
    route_context_gate = timeline_gate.get("route_context_gate")
    if not isinstance(route_context_gate, Mapping):
        return {}
    expected_identity = route_context_gate.get("route_identity")
    if not isinstance(expected_identity, Mapping) or not expected_identity:
        return {}

    waiver = _route_waiver_payload(dict(body) if isinstance(body, Mapping) else {})
    supplied_identity: dict[str, Any] = {**dict(waiver)}
    for field in (
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
        "route_token_ref",
    ):
        if not supplied_identity.get(field) and route_gate.get(field):
            supplied_identity[field] = route_gate.get(field)

    mismatched = _route_identity_mismatch_fields(
        expected_identity,
        supplied_identity,
    )
    mismatched = [
        field
        for field in mismatched
        if field in {"route_context_hash", "prompt_contract_id"}
    ]
    if not mismatched:
        return {}

    return {
        "route_identity_mismatch_fields": mismatched,
        "expected_route_identity": _route_identity_public_summary(expected_identity),
        "supplied_route_identity": _route_identity_public_summary(supplied_identity),
        "selected_route_identity_source": (
            "mf_close_timeline_gate.route_context_gate.route_identity"
        ),
        "route_identity_recovery": {
            "classification": "stale_or_mixed_route_evidence",
            "cleanup_event_kind": "route_identity_cleanup",
            "guidance": (
                "Record a route_identity_cleanup/route_identity_supersede timeline "
                "event for stale or mixed route evidence, or retry backlog_close "
                "with a route_waiver matching the selected close timeline route "
                "identity."
            ),
        },
    }


_TIMELINE_ROUTE_WAIVER_BOOTSTRAP_WORKER_REQUIREMENTS = {
    "bounded_implementation_worker_dispatch",
    "mf_subagent_startup",
}
_TIMELINE_ROUTE_WAIVER_BLOCKED_EVIDENCE_MARKERS = {
    "checkpoint",
    "checkpoint_branch_task",
    "close_ready",
    "evidence_checkpoint",
    "evidence_export",
    "export",
    "implementation",
    "verification",
}


def _timeline_event_route_consumption_candidate(body: dict, event: dict) -> dict:
    payload = body.get("payload") if isinstance(body, dict) else {}
    verification = body.get("verification") if isinstance(body, dict) else {}
    artifact_refs = body.get("artifact_refs") if isinstance(body, dict) else {}
    return {
        **(event if isinstance(event, dict) else {}),
        "status": body.get("status", "") if isinstance(body, dict) else "",
        "decision": body.get("decision", "") if isinstance(body, dict) else "",
        "payload": payload if isinstance(payload, Mapping) else {},
        "verification": verification if isinstance(verification, Mapping) else {},
        "artifact_refs": artifact_refs if isinstance(artifact_refs, Mapping) else {},
    }


def _timeline_event_blocked_evidence_markers(event: dict) -> set[str]:
    markers = {
        _route_gate_marker(event.get("event_type")),
        _route_gate_marker(event.get("event_kind")),
    }
    event_type = str(event.get("event_type") or "").strip().lower()
    for part in re.split(r"[.:/]+", event_type):
        marker = _route_gate_marker(part)
        if marker:
            markers.add(marker)
    phase_marker = _route_gate_marker(event.get("phase"))
    if phase_marker in {
        "checkpoint",
        "checkpoint_branch_task",
        "close_ready",
        "evidence_checkpoint",
        "evidence_export",
        "export",
    }:
        markers.add(phase_marker)
    return markers.intersection(_TIMELINE_ROUTE_WAIVER_BLOCKED_EVIDENCE_MARKERS)


_TIMELINE_BOUNDED_DISPATCH_RUNTIME_LINEAGE_FIELDS = (
    "runtime_context_id",
    "task_id",
    "parent_task_id",
    "fence_token",
)
_TIMELINE_BOUNDED_DISPATCH_RUNTIME_REQUIRED_FIELDS = (
    "route_id",
    "prompt_contract_hash",
    "visible_injection_manifest_hash",
    "worktree_path",
    "branch",
    "base_commit",
    "target_head_commit",
    "merge_queue_id",
)


def _timeline_event_requires_ordered_dispatch_lineage(event: dict) -> bool:
    return any(
        _route_gate_marker(event.get(key)) == "bounded_implementation_worker_dispatch"
        for key in ("event_type", "event_kind", "phase")
    )


def _timeline_ref_id_matches(supplied: Any, expected: Any) -> bool:
    expected_text = str(expected or "").strip()
    if not expected_text:
        return True
    supplied_text = str(supplied or "").strip()
    return supplied_text in {expected_text, f"timeline:{expected_text}"}


def _timeline_first_evidence_event_id(
    route_context_gate: Mapping[str, Any],
    requirement_id: str,
) -> str:
    evidence_events = route_context_gate.get("evidence_events")
    if not isinstance(evidence_events, Mapping):
        return ""
    events = evidence_events.get(requirement_id)
    if not isinstance(events, list) or not events:
        return ""
    event = events[0] if isinstance(events[0], Mapping) else {}
    return str(event.get("id") or "").strip()


def _timeline_bounded_dispatch_runtime_missing_fields(
    summary: Mapping[str, Any],
    route_context_gate: Mapping[str, Any],
    read_receipt_gate: Mapping[str, Any],
) -> list[str]:
    attempt = route_context_gate.get("attempt_lineage")
    expected_lineage = (
        attempt.get("lineage") if isinstance(attempt, Mapping) else {}
    )
    if not isinstance(expected_lineage, Mapping) or not expected_lineage.get(
        "runtime_context_id"
    ):
        return []

    candidate_lineage = summary.get("attempt_lineage")
    if not isinstance(candidate_lineage, Mapping):
        candidate_lineage = {}
    runtime_evidence = summary.get("runtime_dispatch_evidence")
    if not isinstance(runtime_evidence, Mapping):
        runtime_evidence = {}

    missing: list[str] = []
    for field in _TIMELINE_BOUNDED_DISPATCH_RUNTIME_LINEAGE_FIELDS:
        expected = str(expected_lineage.get(field) or "").strip()
        observed = str(
            candidate_lineage.get(field) or runtime_evidence.get(field) or ""
        ).strip()
        if expected and observed != expected:
            missing.append(field)
        elif not expected and not observed:
            missing.append(field)
    for field in _TIMELINE_BOUNDED_DISPATCH_RUNTIME_REQUIRED_FIELDS:
        if not str(runtime_evidence.get(field) or "").strip():
            missing.append(field)
    if not runtime_evidence.get("owned_files"):
        missing.append("owned_files")
    if not _timeline_ref_id_matches(
        runtime_evidence.get("read_receipt_event_id"),
        read_receipt_gate.get("read_receipt_event_id"),
    ):
        missing.append("read_receipt_event_id")
    if not _timeline_ref_id_matches(
        runtime_evidence.get("startup_event_id"),
        _timeline_first_evidence_event_id(
            route_context_gate,
            "mf_subagent_startup",
        ),
    ):
        missing.append("startup_event_id")
    return missing


def _route_waiver_is_manual_fix(waiver: Mapping[str, Any]) -> bool:
    waiver_type = _route_gate_marker(
        waiver.get("waiver_type") or waiver.get("type") or waiver.get("kind")
    )
    manual_fix_flag = str(
        waiver.get("manual_fix") or waiver.get("manual_fix_allowed") or ""
    ).strip().lower()
    return waiver_type in {
        "manual_fix",
        "manual_fix_route_gate",
        "observer_manual_fix",
    } or manual_fix_flag in {"1", "true", "yes", "y", "allowed", "accepted"}


def _route_identity_mismatch_fields(
    expected_identity: Mapping[str, Any],
    supplied_identity: Mapping[str, Any],
    *,
    require_required_fields: bool = False,
) -> list[str]:
    mismatched: list[str] = []
    for field in (
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
        "route_token_ref",
    ):
        expected = str(expected_identity.get(field) or "").strip()
        supplied = str(supplied_identity.get(field) or "").strip()
        if (
            require_required_fields
            and field in {"route_context_hash", "prompt_contract_id", "route_token_ref"}
            and expected
            and not supplied
        ):
            mismatched.append(field)
        elif supplied and expected and supplied != expected:
            mismatched.append(field)
    return mismatched


def _timeline_event_summary(body: dict, event: dict) -> dict[str, Any]:
    from . import task_timeline

    candidate = _timeline_event_route_consumption_candidate(body, event)
    return task_timeline.route_context_consumption_event_summary(candidate)


def _timeline_claimed_route_identity(
    body: dict,
    event: dict,
    route_context_gate: Mapping[str, Any] | None = None,
) -> dict[str, str]:
    payload = body.get("payload") if isinstance(body, Mapping) else {}
    payload = payload if isinstance(payload, Mapping) else {}
    summary = _timeline_event_summary(body, event)
    event_identity = _observer_root_route_identity_from_event(
        _timeline_event_route_consumption_candidate(body, event)
    )
    candidates: list[Mapping[str, Any]] = []
    for value in (
        event_identity,
        summary.get("route_identity"),
        summary.get("runtime_dispatch_evidence"),
        body.get("route_identity"),
        body.get("claimed_route_identity"),
        body.get("command_route_identity"),
        body.get("observer_command_route_identity"),
        payload.get("route_identity"),
        _route_waiver_payload(body),
        (route_context_gate or {}).get("route_identity")
        if isinstance(route_context_gate, Mapping)
        else {},
    ):
        if isinstance(value, Mapping):
            candidates.append(value)
    merged: dict[str, str] = {}
    for candidate in candidates:
        for field in (
            "route_id",
            "route_context_hash",
            "prompt_contract_id",
            "prompt_contract_hash",
            "route_token_ref",
            "visible_injection_manifest_hash",
        ):
            token = str(candidate.get(field) or "").strip()
            if token and not merged.get(field):
                merged[field] = token
    for field in (
        "route_id",
        "route_token_ref",
        "visible_injection_manifest_hash",
    ):
        if not merged.get(field):
            token = _timeline_first_deep_text(body, field) or _timeline_first_deep_text(
                event,
                field,
            )
            if token:
                merged[field] = token
    return merged


@_bounded_close_helper(lambda _: "")
def _timeline_first_deep_text(value: Any, key: str) -> str:
    if isinstance(value, Mapping):
        token = str(value.get(key) or "").strip()
        if token:
            return token
        for child in value.values():
            found = _timeline_first_deep_text(child, key)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = _timeline_first_deep_text(child, key)
            if found:
                return found
    return ""


def _timeline_supplied_route_categories(body: dict, event: dict) -> set[str]:
    summary = _timeline_event_summary(body, event)
    return {str(item) for item in summary.get("categories", []) if str(item)}


def _timeline_missing_protected_lanes(
    route_context_gate: Mapping[str, Any],
) -> list[str]:
    missing = {
        str(item)
        for item in route_context_gate.get("missing_requirement_ids", [])
        if str(item)
    }
    ordered = [
        "route_context",
        "route_action_precheck",
        "bounded_implementation_worker_dispatch",
        "mf_subagent_startup",
        "independent_verification_lane",
    ]
    return [item for item in ordered if item in missing]


def _timeline_claimed_protected_lane(
    body: dict,
    event: dict,
    route_context_gate: Mapping[str, Any],
) -> str:
    categories = _timeline_supplied_route_categories(body, event)
    for lane in (
        "bounded_implementation_worker_dispatch",
        "independent_verification_lane",
        "mf_subagent_startup",
    ):
        if lane in categories:
            return lane
    missing_lanes = _timeline_missing_protected_lanes(route_context_gate)
    return missing_lanes[0] if missing_lanes else ""


def _timeline_source_event_directly_authorizes_lane(body: dict, event: dict) -> bool:
    if _timeline_event_requires_ordered_dispatch_lineage(event):
        return True
    marker = _route_gate_marker(
        " ".join(
            str(event.get(key) or "")
            for key in ("event_type", "event_kind", "phase")
        )
    )
    return any(
        token in marker
        for token in (
            "mf_subagent_startup",
            "startup_gate",
            "independent_verification",
            "independent_verification_lane",
            "qa_verification",
            "independent_qa",
        )
    )


def _timeline_source_event_waiver_lane_allowed(
    events: list[dict[str, Any]],
    body: dict,
    event: dict,
    route_context_gate: dict,
    missing_requirement_ids: list[str],
) -> bool:
    marker = _route_gate_marker(
        " ".join(
            str(event.get(key) or "")
            for key in ("event_type", "event_kind", "phase")
        )
    )
    if any(
        token in marker
        for token in (
            "independent_verification",
            "independent_verification_lane",
            "qa_verification",
            "independent_qa",
        )
    ):
        return True
    if not _timeline_event_requires_ordered_dispatch_lineage(event):
        return False
    present = _route_gate_present_requirement_ids(route_context_gate)
    if "mf_subagent_startup" not in present:
        return True
    return _timeline_route_waiver_ordered_worker_lineage_allowed(
        events,
        body,
        event,
        route_context_gate,
        missing_requirement_ids,
    )


def _timeline_source_event_route_gate(
    events: list[dict[str, Any]],
    body: dict,
    event: dict,
    route_context_gate: Mapping[str, Any],
) -> dict[str, Any]:
    from . import task_timeline
    from .mf_subagent_contract import ROUTE_TOKEN_MUTATION_GATE_SCHEMA_VERSION

    route_identity = _timeline_claimed_route_identity(body, event, route_context_gate)
    protected_lane = _timeline_claimed_protected_lane(body, event, route_context_gate)
    if not route_identity.get("route_context_hash") or not route_identity.get(
        "prompt_contract_id"
    ):
        return {}
    source_gate = task_timeline.route_owned_source_event_gate_verification(
        events,
        route_identity=route_identity,
        protected_lane=protected_lane,
    )
    if not source_gate.get("passed"):
        return {}
    return {
        "schema_version": ROUTE_TOKEN_MUTATION_GATE_SCHEMA_VERSION,
        "allowed": True,
        "status": "accepted",
        "action": "task_timeline_append",
        "decision": "route_owned_source_event",
        "caller_role": "route_source_event",
        "route_id": route_identity.get("route_id", ""),
        "route_context_hash": route_identity.get("route_context_hash", ""),
        "prompt_contract_id": route_identity.get("prompt_contract_id", ""),
        "prompt_contract_hash": route_identity.get("prompt_contract_hash", ""),
        "route_token_ref": route_identity.get("route_token_ref", ""),
        "visible_injection_manifest_hash": route_identity.get(
            "visible_injection_manifest_hash",
            "",
        ),
        "protected_lane": protected_lane,
        "source_event_refs": source_gate.get("source_event_refs", []),
        "source_event_gate_hash": _stable_public_hash(source_gate),
        "route_identity": source_gate.get("route_identity", route_identity),
        "legal_next_action": source_gate.get("next_legal_action", ""),
        "source_event_gate": source_gate,
    }


def _timeline_route_context_state(
    conn,
    project_id: str,
    body: dict,
) -> tuple[dict[str, Any], list[dict[str, Any]], dict[str, Any]]:
    from . import task_timeline

    backlog_id = str(body.get("backlog_id") or "").strip()
    row = conn.execute(
        "SELECT * FROM backlog_bugs WHERE bug_id = ?", (backlog_id,)
    ).fetchone()
    if row:
        contract = backlog_runtime.parse_json_object(
            _row_get(row, "chain_trigger_json", "{}")
        )
        contract = _mf_close_contract_with_route_context(contract, row, body)
    else:
        contract = {
            "close_context": {
                key: body.get(key)
                for key in (
                    "priority",
                    "target_files",
                    "changed_files",
                    "owned_files",
                    "caller_role",
                    "task_summary",
                    "summary",
                )
                if body.get(key) not in (None, "", [], {})
            }
        }

    scoped_task_id = str(body.get("task_id") or "").strip()
    scoped_events = task_timeline.list_events(
        conn,
        project_id,
        backlog_id=backlog_id,
        task_id=scoped_task_id,
        limit=1000,
    )
    route_context_gate = task_timeline.mf_route_context_gate_verification(
        scoped_events,
        contract=contract,
    )
    selected_events = scoped_events
    if (
        scoped_task_id
        and route_context_gate.get("required")
        and not route_context_gate.get("passed")
    ):
        backlog_events = task_timeline.list_events(
            conn,
            project_id,
            backlog_id=backlog_id,
            limit=1000,
        )
        backlog_route_context_gate = task_timeline.mf_route_context_gate_verification(
            backlog_events,
            contract=contract,
        )
        if backlog_route_context_gate.get("required"):
            route_context_gate = _select_timeline_route_context_gate(
                route_context_gate,
                backlog_route_context_gate,
            )
            if route_context_gate is backlog_route_context_gate:
                selected_events = backlog_events
    return contract, selected_events, route_context_gate


def _timeline_no_token_source_event_gate_or_block(
    conn,
    project_id: str,
    body: dict,
    event: dict,
) -> tuple[dict[str, Any], dict[str, Any]]:
    from .mf_subagent_contract import route_token_required_failure_details

    if _body_has_route_token_input(body) or _body_has_route_waiver(body):
        return {}, {}
    backlog_id = str(body.get("backlog_id") or "").strip()
    if not backlog_id:
        return {}, {}
    _, selected_events, route_context_gate = _timeline_route_context_state(
        conn,
        project_id,
        body,
    )
    if not route_context_gate.get("required"):
        return {}, {}
    source_gate = _timeline_source_event_route_gate(
        selected_events,
        body,
        event,
        route_context_gate,
    )
    if source_gate and _timeline_source_event_directly_authorizes_lane(body, event):
        return source_gate, {}
    missing_protected_lanes = _timeline_missing_protected_lanes(route_context_gate)
    source_event_gate = (
        source_gate.get("source_event_gate", {})
        if source_gate
        else {}
    )
    route_identity = _timeline_claimed_route_identity(body, event, route_context_gate)
    reason = (
        "route_token or accepted route-owned source-event lineage is required "
        "before appending protected mf_parallel evidence"
    )
    return {}, route_token_required_failure_details(
        action="task_timeline_append",
        reason=reason,
        extra={
            "protected_event": {
                "event_type": event.get("event_type", ""),
                "event_kind": event.get("event_kind", ""),
                "phase": event.get("phase", ""),
            },
            "source_event_lineage_required": True,
            "route_owned_source_event_gate": source_event_gate,
            "route_token_ref": route_identity.get("route_token_ref", ""),
            "route_identity": _route_identity_public_summary(route_identity),
            "source_event_lineage": {
                "schema_version": "route_source_event_lineage_diagnostic.v1",
                "status": "present" if source_event_gate.get("passed") else "missing",
                "route_token_ref": route_identity.get("route_token_ref", ""),
                "source_event_refs": source_event_gate.get("source_event_refs", []),
                "next_action": (
                    source_event_gate.get("next_legal_action")
                    or "record_or_reuse_an_accepted_route_owned_source_event_for_the_claimed_route_identity"
                ),
                "raw_route_token_required": False,
            },
            "missing_requirement_ids": route_context_gate.get(
                "missing_requirement_ids",
                [],
            ),
            "missing_protected_lanes": missing_protected_lanes,
            "missing_protected_lane": (
                _timeline_claimed_protected_lane(body, event, route_context_gate)
                or (missing_protected_lanes[0] if missing_protected_lanes else "")
            ),
            "legal_next_action": (
                "pass_a_valid_route_token_or_record_an_accepted_route_owned_source_event_for_the_claimed_route_identity"
            ),
            "required_before_protected_evidence": [
                "bounded_implementation_worker_dispatch",
                "mf_subagent_startup",
                "independent_verification_lane",
            ],
            "present_requirement_ids": route_context_gate.get(
                "present_requirement_ids",
                [],
            ),
        },
    )


def _timeline_route_waiver_consumption_bootstrap_allowed(
    body: dict,
    event: dict,
    route_context_gate: dict,
    missing_requirement_ids: list[str],
) -> bool:
    waiver = _route_waiver_payload(body)
    if not _route_waiver_is_manual_fix(waiver):
        return False
    if _timeline_event_blocked_evidence_markers(event):
        return False

    summary = _timeline_event_summary(body, event)
    if not summary.get("passed"):
        return False
    supplied_categories = {
        str(item)
        for item in summary.get("categories", [])
        if str(item)
    }
    if (
        "bounded_implementation_worker_dispatch" in supplied_categories
        and _timeline_event_requires_ordered_dispatch_lineage(event)
    ):
        return False
    missing = {str(item) for item in missing_requirement_ids if str(item)}
    event_identity = summary.get("route_identity")
    expected_identity = route_context_gate.get("route_identity")
    if not isinstance(event_identity, Mapping) or not event_identity:
        return False
    if not isinstance(expected_identity, Mapping) or not expected_identity:
        return False
    if _route_identity_mismatch_fields(
        expected_identity,
        event_identity,
        require_required_fields=True,
    ):
        return False

    present = {
        str(item)
        for item in route_context_gate.get("present_requirement_ids", [])
        if str(item)
    }
    supplied_worker_categories = (
        supplied_categories
        & missing
        & _TIMELINE_ROUTE_WAIVER_BOOTSTRAP_WORKER_REQUIREMENTS
    )
    if supplied_worker_categories:
        return {"route_context", "route_action_precheck"}.issubset(present)

    return (
        missing == {"independent_verification_lane"}
        and "independent_verification_lane" in supplied_categories
    )


def _timeline_route_waiver_ordered_worker_lineage_allowed(
    events: list[dict[str, Any]],
    body: dict,
    event: dict,
    route_context_gate: dict,
    missing_requirement_ids: list[str],
) -> bool:
    waiver = _route_waiver_payload(body)
    if not _route_waiver_is_manual_fix(waiver):
        return False
    if _timeline_event_blocked_evidence_markers(event):
        return False

    from . import task_timeline

    summary = _timeline_event_summary(body, event)
    if not summary.get("passed"):
        return False
    supplied_categories = {
        str(item)
        for item in summary.get("categories", [])
        if str(item)
    }
    missing = {str(item) for item in missing_requirement_ids if str(item)}
    if "bounded_implementation_worker_dispatch" not in supplied_categories:
        return False
    if "bounded_implementation_worker_dispatch" not in missing:
        return False

    present = _route_gate_present_requirement_ids(route_context_gate)
    if "mf_subagent_startup" not in present:
        return False

    event_identity = summary.get("route_identity")
    expected_identity = route_context_gate.get("route_identity")
    if not isinstance(event_identity, Mapping) or not event_identity:
        return False
    if not isinstance(expected_identity, Mapping) or not expected_identity:
        return False
    if _route_identity_mismatch_fields(
        expected_identity,
        event_identity,
        require_required_fields=True,
    ):
        return False

    lineage_filter = task_timeline.read_receipt_lineage_filter_from_route_gate(
        route_context_gate
    )
    if not lineage_filter:
        lineage_filter = _route_identity_public_summary(expected_identity)
    read_receipt_gate = task_timeline.mf_subagent_read_receipt_gate_verification(
        events,
        route_identity_filter=lineage_filter,
    )
    if not bool(
        read_receipt_gate.get("required")
        and read_receipt_gate.get("passed")
        and read_receipt_gate.get("read_receipt_precedes_counted_evidence")
    ):
        return False
    if _timeline_event_requires_ordered_dispatch_lineage(event):
        return not _timeline_bounded_dispatch_runtime_missing_fields(
            summary,
            route_context_gate,
            read_receipt_gate,
        )
    return True


def _route_gate_present_requirement_ids(route_context_gate: Mapping[str, Any]) -> set[str]:
    return {
        str(item)
        for item in route_context_gate.get("present_requirement_ids", [])
        if str(item)
    }


def _route_gate_missing_requirement_ids(route_context_gate: Mapping[str, Any]) -> set[str]:
    return {
        str(item)
        for item in route_context_gate.get("missing_requirement_ids", [])
        if str(item)
    }


def _select_timeline_route_context_gate(
    scoped_gate: dict,
    backlog_gate: dict,
) -> dict:
    if not backlog_gate.get("required"):
        return scoped_gate
    if not scoped_gate.get("required"):
        return backlog_gate
    scoped_present = _route_gate_present_requirement_ids(scoped_gate)
    backlog_present = _route_gate_present_requirement_ids(backlog_gate)
    backlog_missing = _route_gate_missing_requirement_ids(backlog_gate)
    if "route_identity_mismatch" in backlog_missing:
        return backlog_gate
    if bool(backlog_gate.get("passed")) and not bool(scoped_gate.get("passed")):
        return backlog_gate
    if backlog_present and not backlog_present.issubset(scoped_present):
        return backlog_gate
    return scoped_gate


def _route_gate_marker(value: Any) -> str:
    return re.sub(r"[\s.\-]+", "_", str(value or "").strip().lower())


def _timeline_route_waiver_block_for_high_risk(
    conn,
    project_id: str,
    body: dict,
    event: dict,
) -> dict:
    """Return block details when a waiver is trying to stand in for mf_parallel evidence."""

    if not _body_has_route_waiver(body) or _body_has_usable_route_token(body):
        return {}
    backlog_id = str(body.get("backlog_id") or "").strip()
    if not backlog_id:
        return {}

    from .mf_subagent_contract import route_token_required_failure_details

    _, selected_events, route_context_gate = _timeline_route_context_state(
        conn,
        project_id,
        body,
    )
    if not route_context_gate.get("required"):
        return {}
    identity_mismatch = _route_waiver_identity_mismatch(
        route_context_gate,
        _route_waiver_payload(body),
    )
    source_gate = (
        {}
        if identity_mismatch
        else _timeline_source_event_route_gate(
            selected_events,
            body,
            event,
            route_context_gate,
        )
    )
    if route_context_gate.get("passed") and not identity_mismatch and source_gate:
        return {}
    missing_requirement_ids = [
        str(item)
        for item in route_context_gate.get("missing_requirement_ids", [])
        if str(item)
    ]
    if (
        not identity_mismatch
        and source_gate
        and (
            _timeline_source_event_waiver_lane_allowed(
                selected_events,
                body,
                event,
                route_context_gate,
                missing_requirement_ids,
            )
            or
            _timeline_route_waiver_consumption_bootstrap_allowed(
                body,
                event,
                route_context_gate,
                missing_requirement_ids,
            )
            or _timeline_route_waiver_ordered_worker_lineage_allowed(
                selected_events,
                body,
                event,
                route_context_gate,
                missing_requirement_ids,
            )
        )
    ):
        return {}

    present_requirement_ids = route_context_gate.get("present_requirement_ids", [])
    has_startup = "mf_subagent_startup" in {
        str(item) for item in present_requirement_ids if str(item)
    }
    missing_protected_lanes = _timeline_missing_protected_lanes(route_context_gate)
    source_lineage_required = not bool(source_gate)
    reason = (
        "route_waiver route identity does not match existing bounded worker "
        "route-context evidence"
        if identity_mismatch
        else (
            "generic route_waiver cannot append protected mf_parallel evidence "
            "without accepted route-owned source-event lineage for the claimed "
            "route identity"
            if source_lineage_required
            else (
            "generic route_waiver cannot append protected mf_parallel evidence "
            "before an accepted route token issuer or ordered read-receipt/startup "
            "lineage exists"
            if has_startup
            else "generic route_waiver cannot append protected mf_parallel evidence "
            "before bounded worker route-context consumption exists"
            )
        )
    )
    return route_token_required_failure_details(
        action="task_timeline_append",
        reason=reason,
        extra={
            "protected_event": {
                "event_type": event.get("event_type", ""),
                "event_kind": event.get("event_kind", ""),
                "phase": event.get("phase", ""),
            },
            "route_identity_mismatch_fields": identity_mismatch,
            "route_identity_recovery": {
                "classification": "stale_or_mixed_route_evidence"
                if identity_mismatch
                else "",
                "cleanup_event_kind": "route_identity_cleanup",
                "guidance": (
                    "Record a route_identity_cleanup/route_identity_supersede "
                    "timeline event for stale or mixed route evidence, or start "
                    "a fresh service-generated route attempt; do not delete audit "
                    "history."
                )
                if identity_mismatch
                else "",
            },
            "route_waiver_recording_allowed": True,
            "waiver_evidence_only": True,
            **_route_waiver_timeline_evidence_diagnostic(),
            "source_event_lineage_required": source_lineage_required,
            "route_owned_source_event_gate": (
                source_gate.get("source_event_gate", {}) if source_gate else {}
            ),
            "blocked_evidence_kinds": [
                "implementation",
                "verification",
                "close_ready",
                "checkpoint",
                "export",
            ],
            "required_before_protected_evidence": [
                "bounded_implementation_worker_dispatch",
                "mf_subagent_startup",
                "independent_verification_lane",
            ],
            "topology_policy": route_context_gate.get("topology_policy", {}),
            "missing_requirement_ids": route_context_gate.get(
                "missing_requirement_ids", []
            ),
            "missing_protected_lanes": missing_protected_lanes,
            "missing_protected_lane": (
                _timeline_claimed_protected_lane(body, event, route_context_gate)
                or (missing_protected_lanes[0] if missing_protected_lanes else "")
            ),
            "legal_next_action": (
                "record_or_reuse_an_accepted_route_owned_source_event_for_the_claimed_route_identity"
                if source_lineage_required
                else "append_the_exact_missing_protected_lane_before_retrying_close_evidence"
            ),
            "present_requirement_ids": present_requirement_ids,
        },
    )


def _route_waiver_timeline_evidence_diagnostic() -> dict[str, Any]:
    return {
        "timeline_evidence_required": True,
        "accepted_timeline_evidence_shapes": [
            {"timeline_evidence": {"event_id": "6040"}},
            {"timeline_evidence_refs": ["timeline:6036", "timeline:6040"]},
        ],
        "route_waiver_shape_hint": {
            "allowed_action": "task_timeline_append",
            "manual_fix": True,
            "reason": "<operator reason, at least 20 characters>",
            "timeline_evidence": {"event_id": "<accepted route/source event id>"},
        },
        "timeline_evidence_note": (
            "Put timeline_evidence or timeline_evidence_refs inside route_waiver; "
            "route_waiver evidence remains a waiver and does not itself satisfy "
            "implementation, QA, or close-ready evidence."
        ),
    }


def _backlog_upsert_requires_route_gate(body: dict | None, existing_row: Any | None) -> bool:
    payload = body or {}

    def _existing_value(key: str, default: str = "") -> str:
        if existing_row is None:
            return default
        try:
            return str(existing_row[key] or "")
        except Exception:
            return default

    if "commit" in payload and str(payload.get("commit") or "").strip() != _existing_value("commit"):
        return True
    if "fixed_at" in payload and str(payload.get("fixed_at") or "").strip() != _existing_value("fixed_at"):
        return True

    if "status" in payload:
        new_status = str(payload.get("status") or "").strip().upper()
        old_status = _existing_value("status", "OPEN").strip().upper() or "OPEN"
        if new_status in {"FIXED", "CLOSED", "DONE", "RESOLVED"}:
            return True
        if existing_row is not None and new_status != old_status:
            return True
        if existing_row is None and new_status != "OPEN":
            return True

    close_evidence_keys = {
        "close_evidence",
        "close_ready_evidence",
        "timeline_gate",
        "close_impact_check",
        "route_token_gate",
    }
    return any(payload.get(key) not in (None, "", [], {}) for key in close_evidence_keys)


def _task_complete_result_mutates(result: Any) -> bool:
    if not isinstance(result, dict):
        return False
    mutation_keys = {
        "changed_files",
        "file_changes",
        "files_written",
        "patches",
        "commit",
        "merge_commit",
        "checkpoint_id",
        "graph_delta",
        "graph_patch",
        "writes_state",
        "release_gate_passed",
        "backlog_closed",
    }
    if any(key in result and result.get(key) not in (None, "", [], {}) for key in mutation_keys):
        return True
    actions = result.get("actions")
    if isinstance(actions, list):
        return any(str(action).strip() for action in actions)
    return False


def _record_route_token_gate_event(
    conn,
    project_id: str,
    gate: dict,
    *,
    backlog_id: str = "",
    task_id: str = "",
    commit_sha: str = "",
) -> None:
    if not gate:
        return
    try:
        from . import task_timeline

        task_timeline.record_event(
            conn,
            project_id=project_id,
            task_id=task_id,
            backlog_id=backlog_id,
            event_type=f"route_token_gate.{gate.get('action', 'protected_mutation')}",
            phase="route_gate",
            event_kind="route_token_gate",
            actor=str(gate.get("caller_role") or gate.get("decision") or "route_gate"),
            status="accepted",
            payload={"route_token_gate": gate},
            verification=gate,
            commit_sha=commit_sha,
        )
    except Exception:
        log.debug("route_token_gate: failed to record timeline evidence", exc_info=True)


def _record_backlog_close_route_action_precheck_event(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    body: Mapping[str, Any],
    route_gate: Mapping[str, Any],
    commit_sha: str = "",
) -> dict[str, Any]:
    if not _backlog_close_route_gate_is_source_backed(route_gate):
        return {}
    from . import task_timeline

    gate_summary = _route_gate_public_summary(route_gate)
    verification = {
        "schema_version": "backlog_close.route_action_precheck.v1",
        "passed": True,
        "status": "accepted",
        "action": "backlog_close",
        "route_token_gate": gate_summary,
        "source_backed_contract_gate_authority": (
            task_timeline.source_backed_route_gate_authority(gate_summary)
        ),
    }
    return task_timeline.record_event(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=str(body.get("task_id") or backlog_id),
        event_type="contract_runtime.route_action_precheck",
        phase="route_gate",
        event_kind="route_action_precheck",
        actor=str(body.get("actor") or "observer"),
        status="accepted",
        decision="accepted",
        payload={
            "schema_version": "backlog_close.route_action_precheck.v1",
            "source": "authoritative_backlog_close",
            "action": "backlog_close",
            "route_token_ref": str(route_gate.get("route_token_ref") or ""),
            "route_token_gate": gate_summary,
            "contract_execution_id": str(
                body.get("contract_execution_id")
                or _onboard_service_execution_id(project_id, backlog_id)
            ),
            "close_commit": commit_sha,
        },
        verification=verification,
        commit_sha=commit_sha,
    )


def _record_backlog_close_blocked_event(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    row: Any,
    body: Mapping[str, Any],
    route_gate: Mapping[str, Any],
    gate_error: GovernanceError,
    route_action_precheck_event: Mapping[str, Any] | None = None,
    commit_sha: str = "",
) -> dict[str, Any]:
    if (
        gate_error.code
        not in {
            "mf_timeline_gate_failed",
            "missing_contract_runtime_close_authority",
            "contract_runtime_close_authority_incomplete",
        }
        or not _backlog_close_route_gate_is_source_backed(route_gate)
    ):
        return {}
    from . import task_timeline

    gate_summary = _route_gate_public_summary(route_gate)
    details = gate_error.details if isinstance(gate_error.details, Mapping) else {}
    timeline_gate = (
        details.get("timeline_gate")
        if isinstance(details.get("timeline_gate"), Mapping)
        else {}
    )
    failed_gates = list(
        details.get("failed_gates") if isinstance(details.get("failed_gates"), list) else []
    )
    missing_requirement_ids: list[str] = []
    for key in (
        "missing_event_kinds",
        "missing_contract_requirement_ids",
        "missing_route_context_requirement_ids",
        "missing_lane_ownership_ids",
        "missing_close_commit_requirement_ids",
        "missing_contract_runtime_close_authority_requirement_ids",
        "missing_contract_runtime_mf_parallel_authority_requirement_ids",
    ):
        values = details.get(key)
        if isinstance(values, list):
            missing_requirement_ids.extend(
                str(value) for value in values if str(value)
            )
    if isinstance(timeline_gate.get("missing_requirement_ids"), list):
        missing_requirement_ids.extend(
            str(value) for value in timeline_gate["missing_requirement_ids"] if str(value)
        )
    missing_requirement_ids = list(dict.fromkeys(missing_requirement_ids))
    parent_execution_id = str(
        body.get("contract_execution_id")
        or _onboard_service_execution_id(project_id, backlog_id)
    ).strip()
    next_action = _backlog_close_audited_bypass_next_action(
        project_id=project_id,
        backlog_id=backlog_id,
        parent_contract_execution_id=parent_execution_id,
        route_token_ref=str(route_gate.get("route_token_ref") or ""),
        blocked_gate=gate_error.code,
        close_commit=commit_sha,
    )
    payload = {
        "schema_version": "backlog_close.blocked_projection.v1",
        "source": "authoritative_backlog_close",
        "status": "blocked",
        "backlog_id": backlog_id,
        "row_status": str(_row_get(row, "status", "") or ""),
        "contract_execution_id": parent_execution_id,
        "blocked_gate": gate_error.code,
        "failed_gates": failed_gates,
        "missing_requirement_ids": missing_requirement_ids,
        "missing_event_kinds": list(
            details.get("missing_event_kinds")
            if isinstance(details.get("missing_event_kinds"), list)
            else []
        ),
        "missing_contract_requirement_ids": list(
            details.get("missing_contract_requirement_ids")
            if isinstance(details.get("missing_contract_requirement_ids"), list)
            else []
        ),
        "missing_route_context_requirement_ids": list(
            details.get("missing_route_context_requirement_ids")
            if isinstance(details.get("missing_route_context_requirement_ids"), list)
            else []
        ),
        "missing_close_commit_requirement_ids": list(
            details.get("missing_close_commit_requirement_ids")
            if isinstance(details.get("missing_close_commit_requirement_ids"), list)
            else []
        ),
        "route_token_ref": str(route_gate.get("route_token_ref") or ""),
        "route_token_gate": gate_summary,
        "route_action_precheck_event_ref": (
            f"timeline:{route_action_precheck_event.get('id')}"
            if isinstance(route_action_precheck_event, Mapping)
            and route_action_precheck_event.get("id")
            else ""
        ),
        "close_commit": commit_sha,
        "next_legal_action": next_action,
        "candidate_runtime_target_truth_activated": False,
        "requested_actor": str(body.get("actor") or ""),
    }
    event = task_timeline.record_event(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=str(body.get("task_id") or backlog_id),
        event_type="backlog.close.blocked",
        phase="close_gate",
        event_kind="backlog_close_blocked",
        actor="observer",
        status="blocked",
        decision="blocked",
        payload=payload,
        verification={
            "schema_version": "backlog_close.blocked_projection.v1",
            "passed": False,
            "status": "blocked",
            "blocked_gate": gate_error.code,
            "route_token_gate": gate_summary,
            "timeline_gate": timeline_gate,
        },
        commit_sha=commit_sha,
    )
    payload["next_legal_action"] = _backlog_close_audited_bypass_next_action(
        project_id=project_id,
        backlog_id=backlog_id,
        parent_contract_execution_id=parent_execution_id,
        blocked_event_id=int(event.get("id") or 0),
        route_token_ref=str(route_gate.get("route_token_ref") or ""),
        blocked_gate=gate_error.code,
        close_commit=commit_sha,
    )
    event["payload"] = payload
    try:
        conn.execute(
            "UPDATE task_timeline_events SET payload_json = ? WHERE id = ?",
            (
                json.dumps(payload, sort_keys=True, separators=(",", ":")),
                int(event.get("id") or 0),
            ),
        )
    except Exception:
        log.debug("backlog_close_blocked: failed to refresh payload", exc_info=True)
    return event


@route("POST", "/api/task/{project_id}/create")
def handle_task_create(ctx: RequestContext):
    """Create a task. Auth optional — uses principal_id if token provided, else 'anonymous'.

    Phase 4: Auto-enriches metadata with operation_type, intent_hash, and
    runs conflict rules for non-system task types.
    """
    project_id = ctx.get_project_id()
    log.info("API task.create: project=%s type=%s prompt=%r",
             project_id, ctx.body.get("type", "task"), (ctx.body.get("prompt", ""))[:80])
    from . import task_registry
    from .conflict_rules import extract_operation_type, compute_intent_hash, check_conflicts
    created_by = "anonymous"
    if ctx.token:
        try:
            with DBContext(project_id) as conn:
                session = ctx.require_auth(conn)
                created_by = session.get("principal_id", "anonymous")
        except Exception:
            pass

    prompt = ctx.body.get("prompt", "")
    task_type = ctx.body.get("type", "task")
    metadata = ctx.body.get("metadata") or {}
    if isinstance(metadata, str):
        import json as _json
        try:
            metadata = _json.loads(metadata)
        except Exception:
            metadata = {}
    if task_type in _ROUTE_TOKEN_TASK_CREATE_TYPES and created_by not in ("auto-chain", "auto-chain-retry"):
        route_gate = _require_route_token_mutation_gate(
            ctx,
            action="task_create",
            backlog_id=str(metadata.get("bug_id") or ""),
            metadata=metadata,
        )
        metadata["route_token_gate"] = route_gate

    # Auto-enrich metadata
    if "operation_type" not in metadata:
        metadata["operation_type"] = extract_operation_type(prompt)
    if "intent_hash" not in metadata:
        metadata["intent_hash"] = compute_intent_hash(prompt)
    if "intent_summary" not in metadata:
        metadata["intent_summary"] = prompt[:200]

    # §2.1-§2.3: Reconcile task creator allowlist + audit + rate limit (R2/R3/R4)
    _is_reconcile = task_type == "reconcile" or task_type.startswith("reconcile_")
    if _is_reconcile:
        # §2.1: Soft enforcement — warn for non-allowed creators (R2)
        _allowed_prefixes = ("observer-", "coordinator", "auto-chain-reconcile")
        if not any(created_by.startswith(p) for p in _allowed_prefixes):
            log.warning("reconcile_task: creator %r not in allowlist (soft enforce §2.1)", created_by)
        # §2.3: 3-tier rate limiting (R4)
        with DBContext(project_id) as _rl_conn:
            # Tier-1: max 1 active reconcile_run
            _active_runs = _rl_conn.execute(
                "SELECT COUNT(DISTINCT json_extract(metadata_json, '$.reconcile_run_id')) "
                "FROM tasks WHERE project_id=? AND type LIKE 'reconcile%' AND status IN ('pending','claimed','running')",
                (project_id,),
            ).fetchone()[0]
            if _active_runs > 1:
                raise GovernanceError("rate_limit", "Tier-1: max 1 active reconcile_run exceeded", status=429)
            # Tier-2: max 3 concurrent tasks per run
            _run_id = metadata.get("reconcile_run_id", "")
            if _run_id:
                _concurrent = _rl_conn.execute(
                    "SELECT COUNT(*) FROM tasks WHERE project_id=? AND type LIKE 'reconcile%' "
                    "AND status IN ('pending','claimed','running') AND json_extract(metadata_json, '$.reconcile_run_id')=?",
                    (project_id, _run_id),
                ).fetchone()[0]
                if _concurrent >= 3:
                    raise GovernanceError("rate_limit", "Tier-2: max 3 concurrent tasks per reconcile_run exceeded", status=429)
                # Tier-3: max 10 actions per task
                _actions = _rl_conn.execute(
                    "SELECT COUNT(*) FROM tasks WHERE project_id=? AND type LIKE 'reconcile%' "
                    "AND json_extract(metadata_json, '$.reconcile_run_id')=?",
                    (project_id, _run_id),
                ).fetchone()[0]
                if _actions >= 10:
                    raise GovernanceError("rate_limit", "Tier-3: max 10 actions per reconcile_run exceeded", status=429)

    # --- Backlog gate: check bug_id for code-change task types (R1/R4) ---
    # Z3 observer-hotfix 2026-04-24 (P0-1 + P0-2):
    #   - Default enforce mode changed from 'warn' to 'strict' (P0-1).
    #     Rollback: set env OPT_BACKLOG_ENFORCE=warn to revert.
    #   - Added bug_id existence check in backlog_bugs (P0-2). Reject if bug_id
    #     given but not found in backlog_bugs. Prevents typo'd or fabricated IDs
    #     (observed 2026-04-24: MCP task_create silently dropped metadata and
    #     3 tasks landed with bug_id=missing in `warn` mode).
    #   - auto-chain internal creator is exempt (auto_chain already copies
    #     bug_id from parent's metadata; gate would create chicken-and-egg).
    _CODE_CHANGE_TYPES = ("pm", "dev", "test", "qa", "gatekeeper", "merge", "deploy")
    if task_type in _CODE_CHANGE_TYPES and created_by not in ("auto-chain", "auto-chain-retry"):
        _bug_id = metadata.get("bug_id") or ""
        _force_bypass = metadata.get("force_no_backlog") is True
        _enforce_mode = os.environ.get("OPT_BACKLOG_ENFORCE", "strict")
        if _force_bypass:
            # R3: tighter force_no_backlog requirements — validate before bypass
            _bypass_reason = metadata.get("force_reason", "")
            _mf_id = metadata.get("mf_id", "")
            if not _bypass_reason or len(_bypass_reason) < 30:
                _msg = "force_no_backlog requires force_reason of at least 30 chars"
                log.warning("backlog_gate: %s (mode=%s)", _msg, _enforce_mode)
                if _enforce_mode == "strict":
                    raise GovernanceError("force_reason too short", _msg, status=422)
            if not _mf_id or not re.match(r'^MF-\d{4}-\d{2}-\d{2}-\d{3}$', _mf_id):
                _msg = "force_no_backlog requires mf_id matching MF-YYYY-MM-DD-NNN"
                log.warning("backlog_gate: %s (mode=%s)", _msg, _enforce_mode)
                if _enforce_mode == "strict":
                    raise GovernanceError("mf_id invalid", _msg, status=422)
            # R4: observer bypass — audit the event
            if not _bypass_reason:
                _bypass_reason = "no reason given"
            try:
                _publish_event("backlog_gate.observer_bypass", {
                    "project_id": project_id,
                    "task_type": task_type,
                    "force_reason": _bypass_reason,
                    "created_by": created_by,
                })
                with DBContext(project_id) as _evt_conn:
                    _evt_conn.execute(
                        "INSERT INTO chain_events (root_task_id, task_id, event_type, payload_json, ts) "
                        "VALUES (?, ?, ?, ?, datetime('now'))",
                        ("backlog_gate", "backlog_gate",
                         "backlog_gate.observer_bypass",
                         json.dumps({"project_id": project_id, "task_type": task_type,
                                     "force_reason": _bypass_reason, "created_by": created_by})),
                    )
                    _evt_conn.commit()
            except Exception:
                log.debug("backlog_gate: failed to audit observer bypass", exc_info=True)
            log.info("backlog_gate: observer bypass for %s task (reason: %s)", task_type, _bypass_reason)
        elif not _bug_id:
            log.warning("backlog_gate: missing bug_id for %s task in project %s (mode=%s)",
                        task_type, project_id, _enforce_mode)
            if _enforce_mode == "strict":
                raise GovernanceError(
                    "bug_id required",
                    f"Task type '{task_type}' requires metadata.bug_id (OPT_BACKLOG_ENFORCE=strict). "
                    f"Set metadata.force_no_backlog=true with force_reason to bypass.",
                    status=422,
                )
        else:
            # P0-2: bug_id existence check — must correspond to a real backlog row
            try:
                with DBContext(project_id) as _chk_conn:
                    _row = _chk_conn.execute(
                        "SELECT status, bypass_policy_json FROM backlog_bugs WHERE bug_id = ?",
                        (_bug_id,),
                    ).fetchone()
            except Exception:
                _row = None
            if _row is None:
                log.warning("backlog_gate: bug_id %r not found in backlog_bugs for %s task (mode=%s)",
                            _bug_id, task_type, _enforce_mode)
                if _enforce_mode == "strict":
                    raise GovernanceError(
                        "bug_id not in backlog",
                        f"metadata.bug_id '{_bug_id}' does not exist in backlog_bugs. "
                        f"Create the backlog row first via POST /api/backlog/{project_id}/{_bug_id}, "
                        f"or set force_no_backlog=true with force_reason to bypass.",
                        status=422,
                    )
            elif _row["status"] not in ("OPEN", "IN_PROGRESS", "MF_IN_PROGRESS"):
                # R2: bug_id status must be active; MF_IN_PROGRESS is allowed
                # because manual fixes are now audited through backlog runtime.
                _bug_status = _row["status"]
                _msg = (f"bug_id {_bug_id} is not active (current status={_bug_status}); "
                        f"cannot attach new work to closed bug")
                log.warning("backlog_gate: %s (mode=%s)", _msg, _enforce_mode)
                if _enforce_mode == "strict":
                    raise GovernanceError("bug_id not open", _msg, status=422)
            else:
                _policy = backlog_runtime.parse_json_object(_row["bypass_policy_json"])
                if _policy:
                    metadata = backlog_runtime.merge_policy_into_metadata(metadata, _policy)

        if not _force_bypass:
            try:
                from .parallel_agent_contract import (
                    ParallelAgentContractError,
                    validate_parallel_agent_task_gate,
                )

                with DBContext(project_id) as _contract_conn:
                    _contract_evidence = validate_parallel_agent_task_gate(
                        _contract_conn,
                        project_id,
                        task_type,
                        metadata,
                    )
                if _contract_evidence:
                    metadata["parallel_contract_evidence"] = _contract_evidence
            except ParallelAgentContractError as exc:
                _msg = str(exc)
                log.warning("parallel_contract_gate: %s (mode=%s)", _msg, _enforce_mode)
                if _enforce_mode == "strict":
                    raise GovernanceError("parallel_contract_invalid", _msg, status=422)

        # R1: parent_task_id requirement for non-pm code-change types
        _PARENT_REQUIRED_TYPES = ("dev", "test", "qa", "gatekeeper", "merge", "deploy")
        if task_type in _PARENT_REQUIRED_TYPES and not _force_bypass:
            _parent_task_id = metadata.get("parent_task_id") or ""
            if not _parent_task_id:
                _msg = (
                    "This task_create entrypoint creates a chain task "
                    "(pm->dev->test->qa->merge). For V1 observer-led Manual "
                    "Fix work, do NOT use this entrypoint. Instead: "
                    "1) backlog_upsert with chain_trigger_json.parallel_contract "
                    "using the mf_parallel.v2 template; 2) task_timeline_append "
                    "events tied to mf_id. Start from MCP onboard_route_guide; "
                    "aming-claw://mf-sop is archived provenance, not an entrypoint. "
                    "If you genuinely need to test chain automation, pass "
                    "metadata.parent_task_id pointing to an existing pm task_id."
                )
                log.warning("backlog_gate: %s (type=%s, mode=%s)", _msg, task_type, _enforce_mode)
                if _enforce_mode == "strict":
                    raise GovernanceError("parent_task_id missing", _msg, status=422)
            else:
                # Verify parent_task_id exists in tasks table
                try:
                    with DBContext(project_id) as _ptid_conn:
                        _ptid_row = _ptid_conn.execute(
                            "SELECT task_id FROM tasks WHERE task_id = ?",
                            (_parent_task_id,),
                        ).fetchone()
                except Exception:
                    _ptid_row = None
                if _ptid_row is None:
                    _msg = "parent_task_id not found in tasks table"
                    log.warning("backlog_gate: %s (parent=%r, mode=%s)",
                                _msg, _parent_task_id, _enforce_mode)
                    if _enforce_mode == "strict":
                        raise GovernanceError("parent_task_id invalid", _msg, status=422)

    # Run conflict rules for user-facing task types (not auto-chain internal)
    rule_decision = None
    if task_type in ("pm", "dev", "coordinator") and created_by not in ("auto-chain", "auto-chain-retry"):
        with DBContext(project_id) as conn:
            rule_decision = check_conflicts(
                conn, project_id,
                target_files=metadata.get("target_files", []),
                operation_type=metadata["operation_type"],
                intent_hash=metadata["intent_hash"],
                prompt=prompt,
                depends_on=metadata.get("depends_on"),
            )
        metadata["rule_decision"] = rule_decision["decision"]
        metadata["rule_reason"] = rule_decision["reason"]
        log.info("API conflict_rules: project=%s decision=%s reason=%s",
                 project_id, rule_decision["decision"], rule_decision["reason"])

    # CR0b R2: scoped-task blocker — when an active reconcile session exists,
    # block new scoped (reconcile_*) task dispatch BEFORE inserting. Existing
    # in-flight tasks are NOT cancelled; only NEW dispatch is blocked.
    if task_type.startswith("reconcile_"):
        try:
            with DBContext(project_id) as _sess_conn:
                _active_sess = reconcile_session.get_active_session(_sess_conn, project_id)
        except Exception:
            log.debug("reconcile session lookup failed (non-critical)", exc_info=True)
            _active_sess = None
        if _active_sess is not None:
            return 409, {
                "error": "reconcile_session_active_blocks_scoped",
                "session_id": _active_sess.session_id,
                "task_type": task_type,
            }

    with DBContext(project_id) as conn:
        result = task_registry.create_task(
            conn, project_id,
            prompt=prompt,
            task_type=task_type,
            related_nodes=ctx.body.get("related_nodes"),
            created_by=created_by,
            priority=int(ctx.body.get("priority", 0)),
            max_attempts=int(ctx.body.get("max_attempts", 3)),
            metadata=metadata,
        )
        _created_bug_id = metadata.get("bug_id", "")
        if _created_bug_id:
            backlog_runtime.update_backlog_runtime(
                conn,
                _created_bug_id,
                f"{task_type}_queued",
                project_id=project_id,
                task_id=result.get("task_id", ""),
                task_type=task_type,
                metadata=metadata,
                runtime_state=result.get("status", "queued"),
            )
            _publish_current_task_changed(
                project_id,
                backlog_id=_created_bug_id,
                task_id=result.get("task_id", ""),
                source="task.created",
                runtime_state=result.get("status", "queued"),
            )
        if metadata.get("route_token_gate"):
            _record_route_token_gate_event(
                conn,
                project_id,
                metadata.get("route_token_gate") or {},
                backlog_id=_created_bug_id,
                task_id=result.get("task_id", ""),
            )
    # §2.2: Audit reconcile task creation (R3)
    if _is_reconcile:
        try:
            with DBContext(project_id) as _ac:
                audit_service.record(_ac, project_id, event="reconcile_task.created",
                                     actor=created_by, ok=True, node_ids=None, request_id="",
                                     task_id=result.get("task_id", ""), task_type=task_type)
        except Exception:
            log.debug("reconcile_task.created audit failed (non-critical)", exc_info=True)
    # Best-effort publish task.created event to event bus
    try:
        _publish_event("task.created", {
            "task_id": result.get("task_id"),
            "project_id": project_id,
            "type": task_type,
            "created_by": created_by,
        })
    except Exception:
        pass
    # Attach rule decision to response
    if rule_decision:
        result["rule_decision"] = rule_decision
    return result


def _require_executor_session(
    ctx: RequestContext,
    conn: sqlite3.Connection,
    project_id: str,
) -> dict[str, Any]:
    """Bind an executor mutation to the existing role/session authority."""

    if not str(ctx.token or "").strip():
        raise PermissionDeniedError(
            "unknown",
            "executor_active_session",
            {"zero_write_rejection": True, "writes_performed": False},
        )
    session = ctx.require_auth(conn)
    if str(session.get("project_id") or "").strip() != project_id:
        raise PermissionDeniedError(
            str(session.get("role") or "unknown"),
            "executor_project_world",
            {
                "expected_project_id": project_id,
                "session_project_id": str(session.get("project_id") or ""),
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    if not (
        str(session.get("session_id") or "").strip()
        and str(session.get("principal_id") or "").strip()
        and str(session.get("role") or "").strip()
    ):
        raise PermissionDeniedError(
            "unknown",
            "executor_active_session",
            {"zero_write_rejection": True, "writes_performed": False},
        )
    return session


@route("POST", "/api/task/{project_id}/claim")
def handle_task_claim(ctx: RequestContext):
    """Claim a task for one active source-backed worker session."""
    project_id = ctx.get_project_id()
    from . import task_registry
    caller_pid = int(ctx.body.get("caller_pid", 0) or 0)
    with DBContext(project_id) as conn:
        session = _require_executor_session(ctx, conn, project_id)
        worker_id = str(session.get("principal_id") or "").strip()
        log.info("API task.claim: project=%s worker=%s", project_id, worker_id)
        claimed = task_registry.claim_task(conn, project_id, worker_id, caller_pid=caller_pid)
        if isinstance(claimed, tuple):
            task, fence_token = claimed
        else:
            task, fence_token = claimed, ""
        if task is None:
            return {"task": None, "message": "No tasks available"}
        metadata = task.get("metadata", {}) if isinstance(task, dict) else {}
        bug_id = metadata.get("bug_id", "")
        if bug_id:
            backlog_runtime.update_backlog_runtime(
                conn,
                bug_id,
                f"{task.get('type', 'task')}_claimed",
                project_id=project_id,
                task_id=task.get("task_id", ""),
                task_type=task.get("type", "task"),
                metadata=metadata,
                runtime_state="claimed",
            )
            _publish_current_task_changed(
                project_id,
                backlog_id=bug_id,
                task_id=task.get("task_id", ""),
                source="task.claimed",
                runtime_state="claimed",
            )
        return {"task": task, "fence_token": fence_token}


@route("POST", "/api/task/{project_id}/complete")
def handle_task_complete(ctx: RequestContext):
    """Complete a task for its authenticated worker session."""
    project_id = ctx.get_project_id()
    log.info("API task.complete: project=%s task=%s status=%s result_keys=%s",
             project_id, ctx.body.get("task_id", "?"), ctx.body.get("status", "?"),
             list((ctx.body.get("result") or {}).keys()))
    from . import task_registry
    route_gate = {}
    result_payload = ctx.body.get("result") or {}
    with DBContext(project_id) as conn:
        session = _require_executor_session(ctx, conn, project_id)
        if ctx.body.get("status", "succeeded") == "succeeded" and _task_complete_result_mutates(result_payload):
            route_gate = _require_route_token_mutation_gate(
                ctx,
                action="task_complete",
                task_id=ctx.body.get("task_id", ""),
            )
        if route_gate:
            _record_route_token_gate_event(
                conn,
                project_id,
                route_gate,
                task_id=ctx.body.get("task_id", ""),
            )
        return task_registry.complete_task(
            conn, ctx.body.get("task_id", ""),
            status=ctx.body.get("status", "succeeded"),
            result=ctx.body.get("result"),
            error_message=ctx.body.get("error_message", ""),
            fence_token=ctx.body.get("fence_token", ""),
            project_id=project_id,
            completed_by=str(session.get("principal_id") or ""),
            override_reason=ctx.body.get("override_reason", ""),
        )


