def _canonical_visible_injection_manifest_hash(
    events: list[dict[str, Any]],
    route_context_gate: dict[str, Any],
    route_identity: dict[str, Any],
) -> str:
    """Source the canonical visible_injection_manifest_hash from the pinning event.

    The route_context gate's ``route_identity`` summary intentionally only carries
    route_context_hash / prompt_contract_id / prompt_contract_hash, so the manifest
    hash that external-identity validation requires lives only on the raw timeline
    events. Read it from the event that pins the canonical identity:

      1. the ``route_identity_cleanup`` pinning event (the gate exposes its id), or
      2. failing that, the first passing ``route_context`` event whose identity
         matches the canonical route identity.

    Returns the hash verbatim, or an empty string when no pinning event carries
    one (caller surfaces the empty value as a present-but-empty identity field).
    """
    from . import task_timeline

    def _event_id(event: dict[str, Any]) -> str:
        return str(event.get("id") or event.get("event_id") or "").strip()

    cleanup = route_context_gate.get("route_identity_cleanup") or {}
    cleanup_event = cleanup.get("event") if isinstance(cleanup, dict) else None
    cleanup_event_id = ""
    if isinstance(cleanup_event, dict):
        cleanup_event_id = str(
            cleanup_event.get("id") or cleanup_event.get("event_id") or ""
        ).strip()

    # 1. Prefer the manifest hash carried on the canonical pinning event itself.
    if cleanup_event_id:
        for event in events:
            if not isinstance(event, dict) or _event_id(event) != cleanup_event_id:
                continue
            manifest_hash = _observer_root_route_identity_from_event(event).get(
                "visible_injection_manifest_hash", ""
            )
            if manifest_hash:
                return manifest_hash
            break

    # 2. Fall back to a passing route_context event matching the canonical identity.
    canonical_route_context_hash = str(
        route_identity.get("route_context_hash") or ""
    ).strip()
    canonical_prompt_contract_id = str(
        route_identity.get("prompt_contract_id") or ""
    ).strip()
    for event in events:
        if not isinstance(event, dict):
            continue
        summary = task_timeline.route_context_consumption_event_summary(event)
        if "route_context" not in (summary.get("categories") or []):
            continue
        if not summary.get("passed"):
            continue
        identity = summary.get("route_identity") or {}
        if canonical_route_context_hash and (
            str(identity.get("route_context_hash") or "").strip()
            != canonical_route_context_hash
        ):
            continue
        if canonical_prompt_contract_id and (
            str(identity.get("prompt_contract_id") or "").strip()
            != canonical_prompt_contract_id
        ):
            continue
        manifest_hash = _observer_root_route_identity_from_event(event).get(
            "visible_injection_manifest_hash", ""
        )
        if manifest_hash:
            return manifest_hash
    return ""


def _canonical_route_id(
    events: list[dict[str, Any]],
    route_context_gate: dict[str, Any],
    route_identity: dict[str, Any],
) -> str:
    """Source the canonical route_id from the pinning event.

    Like visible_injection_manifest_hash, route_id is part of the external route
    identity but is NOT carried by the route_context gate's ``route_identity``
    summary (route_id is not in MF_ROUTE_IDENTITY_FIELDS). For a row whose
    canonical identity is pinned by a ``route_identity_cleanup`` event, the
    route_id therefore lives only on the raw timeline events. Read it from the
    same pinning event the manifest hash is sourced from:

      1. the ``route_identity_cleanup`` pinning event (the gate exposes its id), or
      2. failing that, the first passing ``route_context`` event whose identity
         matches the canonical route identity.

    Returns the route_id verbatim, or an empty string when no pinning event
    carries one (caller keeps the present-but-empty / incomplete markers; never
    fabricated).
    """
    from . import task_timeline

    def _event_id(event: dict[str, Any]) -> str:
        return str(event.get("id") or event.get("event_id") or "").strip()

    cleanup = route_context_gate.get("route_identity_cleanup") or {}
    cleanup_event = cleanup.get("event") if isinstance(cleanup, dict) else None
    cleanup_event_id = ""
    if isinstance(cleanup_event, dict):
        cleanup_event_id = str(
            cleanup_event.get("id") or cleanup_event.get("event_id") or ""
        ).strip()

    # 1. Prefer the route_id carried on the canonical pinning event itself.
    if cleanup_event_id:
        for event in events:
            if not isinstance(event, dict) or _event_id(event) != cleanup_event_id:
                continue
            route_id = _observer_root_route_identity_from_event(event).get(
                "route_id", ""
            )
            if route_id:
                return route_id
            break

    # 2. Fall back to a passing route_context event matching the canonical identity.
    canonical_route_context_hash = str(
        route_identity.get("route_context_hash") or ""
    ).strip()
    canonical_prompt_contract_id = str(
        route_identity.get("prompt_contract_id") or ""
    ).strip()
    for event in events:
        if not isinstance(event, dict):
            continue
        summary = task_timeline.route_context_consumption_event_summary(event)
        if "route_context" not in (summary.get("categories") or []):
            continue
        if not summary.get("passed"):
            continue
        identity = summary.get("route_identity") or {}
        if canonical_route_context_hash and (
            str(identity.get("route_context_hash") or "").strip()
            != canonical_route_context_hash
        ):
            continue
        if canonical_prompt_contract_id and (
            str(identity.get("prompt_contract_id") or "").strip()
            != canonical_prompt_contract_id
        ):
            continue
        route_id = _observer_root_route_identity_from_event(event).get("route_id", "")
        if route_id:
            return route_id
    return ""


def _observer_root_route_event_id(event: Mapping[str, Any]) -> str:
    return str(event.get("id") or event.get("event_id") or "").strip()


def _observer_root_route_identity_missing_fields(
    identity: Mapping[str, Any],
) -> list[str]:
    return [
        field
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
        if not str(identity.get(field) or "").strip()
    ]


def _observer_root_route_identity_complete(identity: Mapping[str, Any]) -> bool:
    return not _observer_root_route_identity_missing_fields(identity)


def _observer_root_route_identity_matches_partial(
    candidate: Mapping[str, Any],
    partial: Mapping[str, Any],
) -> bool:
    for field in (
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
    ):
        expected = str(partial.get(field) or "").strip()
        actual = str(candidate.get(field) or "").strip()
        if expected and actual and expected != actual:
            return False
    return True


def _observer_root_route_identity_key(identity: Mapping[str, Any]) -> tuple[str, ...]:
    return tuple(
        str(identity.get(field) or "").strip()
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
    )


def _observer_root_route_merge_identity(
    base: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> dict[str, str]:
    merged = {
        field: str(base.get(field) or "").strip()
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
    }
    route_token_ref = str(base.get("route_token_ref") or "").strip()
    if route_token_ref:
        merged["route_token_ref"] = route_token_ref
    for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS:
        if not merged.get(field):
            token = str(candidate.get(field) or "").strip()
            if token:
                merged[field] = token
    if not merged.get("route_token_ref"):
        route_token_ref = str(candidate.get("route_token_ref") or "").strip()
        if route_token_ref:
            merged["route_token_ref"] = route_token_ref
    return merged


def _observer_root_route_prefer_identity(
    base: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> dict[str, str]:
    merged = {
        field: str(candidate.get(field) or base.get(field) or "").strip()
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
    }
    route_token_ref = str(
        candidate.get("route_token_ref") or base.get("route_token_ref") or ""
    ).strip()
    if route_token_ref:
        merged["route_token_ref"] = route_token_ref
    return merged


def _observer_root_route_direct_identity(value: Mapping[str, Any]) -> dict[str, str]:
    identity = {
        field: str(value.get(field) or "").strip()
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
        if str(value.get(field) or "").strip()
    }
    route_token_ref = str(value.get("route_token_ref") or "").strip()
    if route_token_ref:
        identity["route_token_ref"] = route_token_ref
    return identity


def _observer_root_route_identity_candidate_mappings(
    event: Mapping[str, Any],
) -> list[Mapping[str, Any]]:
    row = event if isinstance(event, Mapping) else {}
    payload = row.get("payload") if isinstance(row.get("payload"), Mapping) else {}
    verification = (
        row.get("verification") if isinstance(row.get("verification"), Mapping) else {}
    )
    artifact_refs = (
        row.get("artifact_refs") if isinstance(row.get("artifact_refs"), Mapping) else {}
    )
    containers: list[Mapping[str, Any]] = []

    def _append(value: Any) -> None:
        if isinstance(value, Mapping):
            containers.append(value)

    for source in (payload, verification, row):
        for key in (
            "route_context",
            "route_prompt_contract",
            "route_identity",
            "claimed_route_identity",
            "command_route_identity",
            "observer_command_route_identity",
            "route_action_precheck",
            "route_action_gate",
            "action_precheck",
            "route_evidence",
        ):
            _append(source.get(key) if isinstance(source, Mapping) else None)
    for key in (
        "bounded_implementation_worker_dispatch",
        "mf_subagent_dispatch_gate",
        "mf_subagent_startup_gate",
        "mf_subagent_finish_gate",
        "finish_gate",
        "finish_gate_result",
        "dispatch_evidence",
        "startup_evidence",
    ):
        _append(payload.get(key))
    for source in (verification, artifact_refs, payload, row):
        _append(source)
    return containers


def _observer_root_route_merge_candidate_identity(
    base: dict[str, str],
    candidate: Mapping[str, Any],
) -> dict[str, str]:
    merged = dict(base)
    for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS:
        if merged.get(field):
            continue
        token = str(candidate.get(field) or "").strip()
        if token:
            merged[field] = token
    if not merged.get("route_token_ref"):
        route_token_ref = str(candidate.get("route_token_ref") or "").strip()
        if route_token_ref:
            merged["route_token_ref"] = route_token_ref
    return merged


def _observer_root_route_identity_from_event(
    event: Mapping[str, Any],
) -> dict[str, str]:
    from . import task_timeline

    summary = task_timeline.route_context_consumption_event_summary(dict(event))
    identity: dict[str, str] = {}
    for candidate in _observer_root_route_identity_candidate_mappings(event):
        identity = _observer_root_route_merge_candidate_identity(
            identity,
            _observer_root_route_direct_identity(candidate),
        )
    for summary_key in ("route_identity", "runtime_dispatch_evidence"):
        summary_identity = (
            summary.get(summary_key)
            if isinstance(summary.get(summary_key), Mapping)
            else {}
        )
        identity = _observer_root_route_merge_candidate_identity(
            identity,
            _observer_root_route_direct_identity(summary_identity),
        )
    for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS:
        if identity.get(field):
            continue
        token = _timeline_first_deep_text(dict(event), field)
        if token:
            identity[field] = token
    if not identity.get("route_token_ref"):
        route_token_ref = _timeline_first_deep_text(dict(event), "route_token_ref")
        if route_token_ref:
            identity["route_token_ref"] = route_token_ref
    return identity


def _observer_root_route_event_summary(
    event: Mapping[str, Any],
) -> dict[str, Any]:
    from . import task_timeline

    return task_timeline.route_context_consumption_event_summary(dict(event))


def _observer_root_route_is_service_route_event(event: Mapping[str, Any]) -> bool:
    event_type = str(event.get("event_type") or "").strip().lower()
    event_kind = str(event.get("event_kind") or "").strip().lower()
    return event_type.startswith("service.route.") or event_kind == "service_route"


def _observer_root_route_identity_candidates(
    events: list[dict[str, Any]],
    *,
    base_identity: Mapping[str, Any],
) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []

    def _append(event: Mapping[str, Any], source: str) -> None:
        summary = _observer_root_route_event_summary(event)
        if not summary.get("passed"):
            return
        identity = _observer_root_route_identity_from_event(event)
        if not identity:
            return
        if not _observer_root_route_identity_matches_partial(identity, base_identity):
            return
        candidates.append({
            "source": source,
            "event_id": _observer_root_route_event_id(event),
            "event_kind": str(event.get("event_kind") or ""),
            "event_type": str(event.get("event_type") or ""),
            "identity": identity,
        })

    for event in events:
        if not isinstance(event, dict):
            continue
        if _observer_root_route_is_service_route_event(event):
            continue
        summary = _observer_root_route_event_summary(event)
        categories = {str(item) for item in (summary.get("categories") or [])}
        if "route_context" in categories:
            _append(event, "passing_route_context")
    for event in events:
        if not isinstance(event, dict):
            continue
        if _observer_root_route_is_service_route_event(event):
            _append(event, "service_route_source_evidence")
    return candidates


def _observer_root_route_canonical_identity_projection(
    events: list[dict[str, Any]],
    *,
    route_context_gate: dict[str, Any],
    route_identity: Mapping[str, Any],
    contract: Mapping[str, Any],
) -> dict[str, Any]:
    """Recover a complete external route identity from real timeline evidence."""

    base_identity = {
        field: str(route_identity.get(field) or "").strip()
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
    }
    if not base_identity.get("route_id"):
        base_identity["route_id"] = str(contract.get("route_id") or "").strip()

    cleanup = route_context_gate.get("route_identity_cleanup") or {}
    cleanup_identity = (
        cleanup.get("route_identity")
        if isinstance(cleanup, Mapping) and isinstance(cleanup.get("route_identity"), Mapping)
        else {}
    )
    if cleanup_identity:
        base_identity = _observer_root_route_merge_identity(base_identity, cleanup_identity)
        cleanup_event = cleanup.get("event") if isinstance(cleanup, Mapping) else {}
        cleanup_event_id = (
            _observer_root_route_event_id(cleanup_event)
            if isinstance(cleanup_event, Mapping)
            else ""
        )
        for event in events:
            if cleanup_event_id and _observer_root_route_event_id(event) == cleanup_event_id:
                base_identity = _observer_root_route_merge_identity(
                    base_identity,
                    _observer_root_route_identity_from_event(event),
                )
                break

    if not base_identity.get("route_id"):
        base_identity["route_id"] = _canonical_route_id(
            events, route_context_gate, dict(route_identity)
        )
    if not base_identity.get("visible_injection_manifest_hash"):
        base_identity["visible_injection_manifest_hash"] = (
            _canonical_visible_injection_manifest_hash(
                events, route_context_gate, dict(route_identity)
            )
        )

    candidates = _observer_root_route_identity_candidates(
        events,
        base_identity=base_identity,
    )
    for candidate in candidates:
        base_identity = _observer_root_route_merge_identity(
            base_identity,
            candidate.get("identity") or {},
        )
        if _observer_root_route_identity_complete(base_identity):
            return {
                "identity": base_identity,
                "source": candidate["source"],
                "event_id": candidate["event_id"],
                "ambiguous": False,
                "missing_fields": [],
                "candidates": candidates[:5],
            }

    complete_candidates = [
        candidate
        for candidate in candidates
        if _observer_root_route_identity_complete(candidate.get("identity") or {})
    ]
    unique_complete = {
        _observer_root_route_identity_key(candidate.get("identity") or {})
        for candidate in complete_candidates
    }
    if len(unique_complete) == 1 and complete_candidates:
        selected = complete_candidates[-1]
        return {
            "identity": dict(selected.get("identity") or {}),
            "source": selected["source"],
            "event_id": selected["event_id"],
            "ambiguous": False,
            "missing_fields": [],
            "candidates": candidates[:5],
        }
    if len(unique_complete) > 1:
        return {
            "identity": base_identity,
            "source": "ambiguous_route_source_evidence",
            "event_id": "",
            "ambiguous": True,
            "missing_fields": _observer_root_route_identity_missing_fields(base_identity),
            "candidates": candidates[:5],
        }
    return {
        "identity": base_identity,
        "source": "route_context_gate",
        "event_id": "",
        "ambiguous": False,
        "missing_fields": _observer_root_route_identity_missing_fields(base_identity),
        "candidates": candidates[:5],
    }


def _observer_root_route_route_token_ref_from_events(
    events: list[dict[str, Any]],
    *,
    canonical_identity: Mapping[str, Any],
) -> str:
    """Find a copy-safe route token ref carried by matching timeline evidence."""

    route_token_ref = ""
    for event in events:
        if not isinstance(event, Mapping):
            continue
        identity = _observer_root_route_identity_from_event(event)
        candidate_ref = str(identity.get("route_token_ref") or "").strip()
        if not candidate_ref:
            continue
        has_conflict = False
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS:
            expected = str(canonical_identity.get(field) or "").strip()
            actual = str(identity.get(field) or "").strip()
            if expected and actual and expected != actual:
                has_conflict = True
                break
        if has_conflict:
            continue
        route_token_ref = candidate_ref
    return route_token_ref


def _observer_root_route_worker_lane_task_ids(source: Any) -> list[str]:
    task_ids: list[str] = []

    def visit(value: Any, *, depth: int = 0) -> None:
        if depth > 5:
            return
        if isinstance(value, Mapping):
            lanes = value.get("worker_lanes") or value.get("lanes") or []
            if isinstance(lanes, list):
                for lane in lanes:
                    if isinstance(lane, Mapping):
                        task_id = str(lane.get("task_id") or "").strip()
                        if task_id:
                            task_ids.append(task_id)
            for key in (
                "contract",
                "payload",
                "chain_trigger",
                "contract_chain",
                "contract_executions",
                "execution_plan",
            ):
                child = value.get(key)
                if isinstance(child, (Mapping, list)):
                    visit(child, depth=depth + 1)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, (Mapping, list)):
                    visit(item, depth=depth + 1)

    visit(source)
    return _runtime_context_service_dedupe(task_ids)


def _observer_root_route_lineage_bridge_action(
    close_gate: Mapping[str, Any],
    route_context_gate: Mapping[str, Any],
    *,
    backlog_id: str = "",
    contract: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    cross_ref_gate = (
        close_gate.get("cross_ref_gate")
        if isinstance(close_gate.get("cross_ref_gate"), Mapping)
        else {}
    )
    child_task_ids: list[str] = []
    for item in route_context_gate.get("attempt_lineage_candidates") or []:
        if not isinstance(item, Mapping):
            continue
        lineage = item.get("lineage") if isinstance(item.get("lineage"), Mapping) else {}
        task_id = str(lineage.get("task_id") or item.get("task_id") or "").strip()
        if task_id:
            child_task_ids.append(task_id)
    for item in cross_ref_gate.get("rejected_cross_ref_evidence") or []:
        if not isinstance(item, Mapping):
            continue
        lineage = item.get("lineage") if isinstance(item.get("lineage"), Mapping) else {}
        task_id = str(lineage.get("task_id") or item.get("task_id") or "").strip()
        if task_id:
            child_task_ids.append(task_id)
    child_task_ids.extend(_observer_root_route_worker_lane_task_ids(contract or {}))
    child_task_ids = _runtime_context_service_dedupe(child_task_ids)

    merge_queue_id = _runtime_context_public_text(
        close_gate.get("merge_queue_id"),
        route_context_gate.get("merge_queue_id"),
        (contract or {}).get("merge_queue_id") if isinstance(contract, Mapping) else "",
    )
    if not merge_queue_id and isinstance(contract, Mapping):
        merge_queue_candidates: list[str] = []

        def visit_merge(value: Any, *, depth: int = 0) -> None:
            if depth > 5:
                return
            if isinstance(value, Mapping):
                candidate = str(value.get("merge_queue_id") or "").strip()
                if candidate:
                    merge_queue_candidates.append(candidate)
                for child in value.values():
                    if isinstance(child, (Mapping, list)):
                        visit_merge(child, depth=depth + 1)
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, (Mapping, list)):
                        visit_merge(item, depth=depth + 1)

        visit_merge(contract)
        merge_queue_id = _runtime_context_public_text(*merge_queue_candidates)

    parent_row_id = str(backlog_id or "").strip()
    return {
        "schema_version": "observer_root_route.cross_ref_lineage_bridge_action.v1",
        "id": "cross_ref_lineage_bridge",
        "event_kind": "cross_ref_lineage_bridge",
        "action": "record_cross_ref_lineage_bridge",
        "next_legal_action": "record_cross_ref_lineage_bridge",
        "parent_row_id": parent_row_id,
        "parent_backlog_id": parent_row_id,
        "child_task_ids": child_task_ids,
        "merge_queue_id": merge_queue_id,
        "status": "required",
        "raw_token_exposed": False,
    }


def _observer_root_route_public_event_ref(event: Mapping[str, Any]) -> str:
    event_id = _observer_root_route_event_id(event)
    return f"timeline:{event_id}" if event_id else ""


def _observer_root_route_deep_strings(value: Any, key: str) -> list[str]:
    values: list[str] = []
    if isinstance(value, Mapping):
        direct = value.get(key)
        if isinstance(direct, list):
            values.extend(str(item).strip() for item in direct if str(item or "").strip())
        elif str(direct or "").strip():
            values.append(str(direct).strip())
        for child in value.values():
            if isinstance(child, (Mapping, list)):
                values.extend(_observer_root_route_deep_strings(child, key))
    elif isinstance(value, list):
        for child in value:
            if isinstance(child, (Mapping, list)):
                values.extend(_observer_root_route_deep_strings(child, key))
    return _runtime_context_service_dedupe(values)


def _observer_root_route_event_task_id(event: Mapping[str, Any]) -> str:
    for key in ("task_id", "worker_id", "worker_slot_id", "runtime_context_id"):
        token = str(event.get(key) or "").strip()
        if token:
            return token
    for source_key in ("payload", "verification", "artifact_refs"):
        source = event.get(source_key)
        if isinstance(source, Mapping):
            for key in ("task_id", "worker_id", "worker_slot_id", "runtime_context_id"):
                token = _timeline_first_deep_text(source, key)
                if token:
                    return token
    return ""


def _observer_root_route_event_markers(event: Mapping[str, Any]) -> set[str]:
    markers = {
        _observer_root_route_normalize_action(event.get(key))
        for key in ("event_kind", "event_type", "phase", "status", "decision")
    }
    for source_key in ("payload", "verification", "artifact_refs"):
        source = event.get(source_key)
        if not isinstance(source, Mapping):
            continue
        for key in ("action", "kind", "status", "decision", "phase", "event_kind"):
            marker = _observer_root_route_normalize_action(source.get(key))
            if marker:
                markers.add(marker)
    return {marker for marker in markers if marker}


def _observer_root_route_changed_files(event: Mapping[str, Any]) -> list[str]:
    values: list[str] = []
    for key in (
        "changed_files",
        "owned_changed_files",
        "worker_changed_files",
        "modified_files",
        "touched_files",
    ):
        values.extend(_observer_root_route_deep_strings(event, key))
    return [
        value
        for value in _runtime_context_service_dedupe(values)
        if not value.startswith("<")
    ]


def _observer_root_route_event_claims_no_implementation(event: Mapping[str, Any]) -> bool:
    truthy_keys = {
        "implementation_recorded",
        "implementation_present",
        "has_implementation",
        "has_diff",
        "diff_present",
    }
    falsy_keys = {
        "zero_diff",
        "no_diff",
        "implementation_absent",
        "no_implementation",
    }
    for source in (
        event,
        event.get("payload") if isinstance(event.get("payload"), Mapping) else {},
        event.get("verification") if isinstance(event.get("verification"), Mapping) else {},
        event.get("artifact_refs") if isinstance(event.get("artifact_refs"), Mapping) else {},
    ):
        if not isinstance(source, Mapping):
            continue
        for key in truthy_keys:
            value = source.get(key)
            if isinstance(value, bool) and value:
                return False
            if isinstance(value, str) and value.strip().lower() in {"true", "yes", "1"}:
                return False
        for key in falsy_keys:
            value = source.get(key)
            if isinstance(value, bool) and value:
                return True
            if isinstance(value, str) and value.strip().lower() in {"true", "yes", "1"}:
                return True
    return False


def _observer_root_route_no_progress_failed_attempt(
    events: Sequence[Mapping[str, Any]] | None,
) -> dict[str, Any]:
    if not events:
        return {}

    implementation_task_ids: set[str] = set()
    for event in events:
        if not isinstance(event, Mapping):
            continue
        markers = _observer_root_route_event_markers(event)
        if not markers.intersection({"implementation", "hotfix_under_action"}):
            continue
        if _observer_root_route_changed_files(event):
            task_id = _observer_root_route_event_task_id(event)
            if task_id:
                implementation_task_ids.add(task_id)

    for event in reversed([event for event in events if isinstance(event, Mapping)]):
        markers = _observer_root_route_event_markers(event)
        if "no_progress_timeout" not in markers:
            continue
        task_id = _observer_root_route_event_task_id(event)
        if task_id and task_id in implementation_task_ids:
            continue
        if _observer_root_route_changed_files(event):
            continue
        if not _observer_root_route_event_claims_no_implementation(event):
            continue
        event_ref = _observer_root_route_public_event_ref(event)
        return {
            "task_id": task_id,
            "event_ref": event_ref,
            "event_kind": str(event.get("event_kind") or ""),
            "phase": str(event.get("phase") or ""),
            "status": str(event.get("status") or event.get("decision") or ""),
            "zero_diff": True,
            "implementation_recorded": False,
        }
    return {}


def _observer_root_route_close_gate_steps(
    close_gate: Mapping[str, Any],
    route_context_gate: Mapping[str, Any],
    *,
    backlog_id: str = "",
    contract: Mapping[str, Any] | None = None,
    events: Sequence[Mapping[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    steps: list[dict[str, Any]] = []

    def _add(step_id: str, action: str, reason: str, **extra: Any) -> None:
        if any(step["id"] == step_id for step in steps):
            return
        step: dict[str, Any] = {
            "id": step_id,
            "action": action,
            "reason": reason,
        }
        step.update({key: value for key, value in extra.items() if value not in ("", [], {})})
        steps.append(step)

    missing_route = {
        str(item)
        for item in (route_context_gate.get("missing_requirement_ids") or [])
        if str(item)
    }
    ignored_reasons = {
        str(item.get("reason") or "")
        for item in (route_context_gate.get("ignored_route_events") or [])
        if isinstance(item, Mapping)
    }
    cleanup = route_context_gate.get("route_identity_cleanup") or {}
    cleanup_applied = isinstance(cleanup, Mapping) and bool(cleanup.get("applied"))
    cleanup_required = (
        "route_identity_mismatch" in missing_route
        or "route_identity_mismatch" in ignored_reasons
        or (
            "superseded_route_identity" in ignored_reasons
            and not cleanup_applied
        )
    )
    if cleanup_required:
        _add(
            "route_identity_cleanup",
            "record_route_identity_cleanup",
            "route evidence is stale, mixed, or missing a canonical identity pin",
        )

    cross_ref_gate = close_gate.get("cross_ref_gate") or {}
    bridge_action = _observer_root_route_lineage_bridge_action(
        close_gate,
        route_context_gate,
        backlog_id=backlog_id,
        contract=contract,
    )
    if isinstance(cross_ref_gate, Mapping) and not cross_ref_gate.get("passed"):
        rejected = cross_ref_gate.get("rejected_cross_ref_evidence") or []
        if rejected:
            _add(
                "cross_ref_lineage_bridge",
                "record_cross_ref_lineage_bridge",
                "cross-ref lineage bridge required for sibling task attempts",
                parent_row_id=bridge_action.get("parent_row_id"),
                child_task_ids=bridge_action.get("child_task_ids"),
                merge_queue_id=bridge_action.get("merge_queue_id"),
                bridge_action=bridge_action,
                rejected_cross_ref_evidence=rejected,
            )
    attempt_task_ids = {
        str(((item.get("lineage") or {}).get("task_id") if isinstance(item, Mapping) else "") or "").strip()
        for item in (route_context_gate.get("attempt_lineage_candidates") or [])
        if isinstance(item, Mapping)
    }
    attempt_task_ids.discard("")
    bridged_membership = (
        cross_ref_gate.get("bridged_lane_membership")
        if isinstance(cross_ref_gate, Mapping)
        else []
    )
    if len(attempt_task_ids) > 1 and not bridged_membership:
        _add(
            "cross_ref_lineage_bridge",
            "record_cross_ref_lineage_bridge",
            "cross-ref lineage bridge required for sibling task attempts",
            parent_row_id=bridge_action.get("parent_row_id"),
            child_task_ids=bridge_action.get("child_task_ids"),
            merge_queue_id=bridge_action.get("merge_queue_id"),
            bridge_action=bridge_action,
            attempt_task_ids=sorted(attempt_task_ids),
        )

    close_startup_gate = close_gate.get("close_timeline_startup_gate") or {}
    checks = close_gate.get("checks") or {}
    no_progress_failed_attempt = _observer_root_route_no_progress_failed_attempt(events)
    startup_close_satisfying = (
        isinstance(checks, Mapping)
        and checks.get("mf_subagent_startup_close_satisfying") is True
    ) or (
        isinstance(close_startup_gate, Mapping)
        and close_startup_gate.get("passed") is True
        and bool(close_startup_gate.get("accepted_startup_events"))
    )

    def _add_no_progress_replacement_dispatch() -> None:
        _add(
            "dispatch_bounded_worker",
            "dispatch_bounded_worker",
            (
                "latest bounded worker lane ended with no_progress_timeout, "
                "zero diff, and no implementation evidence"
            ),
            failed_attempt=no_progress_failed_attempt,
            replacement_required=True,
        )

    if not startup_close_satisfying and (
        (
            isinstance(close_startup_gate, Mapping)
            and close_startup_gate.get("demoted_startup_events")
        ) or (
            isinstance(checks, Mapping)
            and checks.get("mf_subagent_startup_close_satisfying") is False
        )
    ):
        if no_progress_failed_attempt:
            _add_no_progress_replacement_dispatch()
        else:
            _add(
                "real_mf_subagent_startup",
                "record_server_verified_worker_startup_with_transcript",
                "DB-backed startup exists but is not close-satisfying real worker evidence",
            )

    route_step_map = [
        (
            "route_context",
            "route_context",
            "record_route_context",
            "route_context evidence is required before close",
        ),
        (
            "route_action_precheck",
            "route_action_precheck",
            "record_route_action_precheck",
            "route_action_precheck must be accepted for the canonical identity",
        ),
        (
            "bounded_implementation_worker_dispatch",
            "dispatch_bounded_worker",
            "dispatch_bounded_worker",
            "bounded implementation worker dispatch evidence is missing",
        ),
        (
            "mf_subagent_startup",
            "mf_subagent_startup",
            "record_mf_subagent_startup",
            "mf_subagent startup evidence is missing",
        ),
        (
            "independent_verification_lane",
            "independent_verification_lane",
            "record_independent_verification",
            "independent verification lane evidence is missing",
        ),
        (
            "architecture_review_lane",
            "architecture_review_lane",
            "record_architecture_review",
            "architecture/data-continuity review lane evidence is missing",
        ),
    ]
    for missing_id, step_id, action, reason in route_step_map:
        if missing_id in missing_route:
            if missing_id == "mf_subagent_startup":
                _add(
                    "worker_startup_handoff",
                    "handoff_worker_startup_or_recover_dispatch",
                    (
                        "mf_subagent startup evidence is worker-owned; observer "
                        "must hand off safe startup refs, recover worker auth, or "
                        "dispatch a bounded worker instead of appending startup "
                        "evidence directly"
                    ),
                    blocked_requirement_id="mf_subagent_startup",
                    evidence_owner_role="mf_sub",
                    worker_owned=True,
                    observer_owned=False,
                    safe_repair_actions=[
                        "dispatch_bounded_worker",
                        "provide_worker_startup_facade_with_safe_refs",
                        "recover_worker_auth_or_runtime_context",
                    ],
                    forbidden_observer_actions=["record_mf_subagent_startup"],
                )
            else:
                _add(step_id, action, reason)

    close_commit_evidence_gate = close_gate.get("close_commit_evidence_gate") or {}
    if (
        isinstance(close_commit_evidence_gate, Mapping)
        and not close_commit_evidence_gate.get("passed")
    ):
        close_commit = str(close_commit_evidence_gate.get("close_commit") or "").strip()
        if close_commit:
            _add(
                "close_commit_evidence",
                "record_close_ready_for_close_commit",
                (
                    "close-satisfying timeline evidence for the intended close "
                    f"commit {close_commit} is missing"
                ),
                close_commit=close_commit,
                close_commit_source=close_commit_evidence_gate.get("close_commit_source"),
                latest_evidence_commit=close_commit_evidence_gate.get(
                    "latest_evidence_commit"
                ),
                evidence_commits=close_commit_evidence_gate.get("evidence_commits"),
                missing_requirement_ids=close_commit_evidence_gate.get(
                    "missing_requirement_ids"
                ),
                next_action=close_commit_evidence_gate.get("next_action"),
            )

    missing_events = [
        str(item)
        for item in (close_gate.get("missing_event_kinds") or [])
        if str(item)
    ]
    ignored_hotfix_implementation_events = [
        item
        for item in (close_gate.get("ignored_required_events") or [])
        if isinstance(item, Mapping)
        and str(item.get("event_kind") or "").strip() == "hotfix_under_action"
        and str(item.get("reason") or "").strip()
        in {
            "missing_hotfix_implementation_policy_payload",
            "event_does_not_claim_implementation_projection",
            "missing_hotfix_implementation_close_evidence",
        }
    ]
    for event_kind in ("implementation", "verification", "close_ready"):
        if event_kind in missing_events:
            if event_kind == "implementation" and no_progress_failed_attempt:
                _add_no_progress_replacement_dispatch()
                continue
            if event_kind == "implementation" and ignored_hotfix_implementation_events:
                _add(
                    "hotfix_implementation_close_evidence",
                    "record_hotfix_under_action_implementation_close_evidence",
                    (
                        "hotfix_under_action exists but does not yet include "
                        "implementation_close_evidence for changed files, "
                        "verification refs, and QA lineage"
                    ),
                    rejected_hotfix_events=ignored_hotfix_implementation_events,
                )
                continue
            _add(
                event_kind,
                f"record_{event_kind}",
                f"{event_kind} timeline evidence is missing",
            )
    return steps


def _observer_root_route_next_legal_action_from_steps(
    steps: list[dict[str, Any]],
    *,
    default: Mapping[str, Any],
) -> dict[str, Any]:
    if not steps:
        return dict(default)
    first = steps[0]
    return {
        "id": first["id"],
        "action": first["action"],
        "detail": first["reason"],
        "missing_prerequisites": [step["id"] for step in steps],
        "ordered_missing_steps": steps,
    }


def _observer_root_route_priority_close_gate_step(
    close_gate_steps: list[dict[str, Any]],
    close_gate: Mapping[str, Any],
) -> dict[str, Any]:
    for step in close_gate_steps:
        if (
            str(step.get("id") or "") == "dispatch_bounded_worker"
            and bool(step.get("replacement_required"))
        ):
            return dict(step)

    close_commit_evidence_gate = close_gate.get("close_commit_evidence_gate")
    if (
        isinstance(close_commit_evidence_gate, Mapping)
        and not bool(close_commit_evidence_gate.get("passed"))
        and str(close_commit_evidence_gate.get("close_commit") or "").strip()
    ):
        for step in close_gate_steps:
            if str(step.get("id") or "") == "close_commit_evidence":
                return dict(step)

    missing_events = [
        str(item)
        for item in (close_gate.get("missing_event_kinds") or [])
        if str(item or "").strip()
    ]
    if missing_events == ["close_ready"]:
        for step in close_gate_steps:
            if str(step.get("id") or "") == "close_ready":
                return dict(step)
    return {}


def _observer_root_route_mapping(value: Any) -> dict[str, Any]:
    return dict(value) if isinstance(value, Mapping) else {}


def _observer_root_route_worker_startup_handoff_step(
    step: Mapping[str, Any],
) -> dict[str, Any]:
    original = dict(step)
    step_id = str(original.get("id") or original.get("action") or "").strip()
    if step_id not in {"mf_subagent_startup", "real_mf_subagent_startup"}:
        return original
    append_hint = _observer_root_route_mapping(original.get("timeline_append_hint"))
    actor_role = str(
        append_hint.get("actor_role")
        or append_hint.get("lane_actor_role")
        or original.get("actor_role")
        or original.get("lane_actor_role")
        or ""
    ).strip()
    if actor_role not in {"mf_sub", "mf_subagent", "worker"}:
        return original
    return {
        "id": "worker_startup_handoff",
        "action": "handoff_worker_startup_or_recover_dispatch",
        "detail": (
            "mf_subagent startup evidence is worker-owned; observer must hand "
            "off safe startup refs, recover worker auth, or dispatch a bounded "
            "worker instead of appending startup evidence directly"
        ),
        "reason": (
            "mf_subagent startup evidence is worker-owned; observer root cannot "
            "author mf_subagent_startup evidence"
        ),
        "source": original.get("source") or "contract_state",
        "precedence": original.get("precedence") or "role_bound_worker_handoff",
        "blocked_requirement_id": step_id,
        "blocked_requirement_action": original.get("action"),
        "evidence_owner_role": actor_role,
        "worker_owned": True,
        "observer_owned": False,
        "safe_repair_actions": [
            "dispatch_bounded_worker",
            "provide_worker_startup_facade_with_safe_refs",
            "recover_worker_auth_or_runtime_context",
        ],
        "forbidden_observer_actions": ["record_mf_subagent_startup"],
        "accepted_event_kinds": original.get("accepted_event_kinds") or [],
        "accepted_statuses": original.get("accepted_statuses") or [],
        "worker_handoff": {
            "target_actor_role": actor_role,
            "requirement_id": step_id,
            "timeline_append_hint": append_hint,
        },
    }


def _observer_root_route_steps_for_observer(
    steps: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    return [_observer_root_route_worker_startup_handoff_step(step) for step in steps]


def _observer_root_route_contract_state_action_has_priority(
    action: Mapping[str, Any],
) -> bool:
    action_id = str(action.get("id") or action.get("action") or "").strip()
    precedence = str(action.get("precedence") or "").strip().lower()
    if precedence == "legacy_hotfix_direct_followup" and action_id in {
        "independent_verification_lane",
        "independent_verification",
        "independent_qa",
        "independent_qa_lane",
        "qa_review",
        "qa_verification",
        "verification",
        "close_ready",
    }:
        return True
    if not action_id or action_id in {"close_ready", "successor_contract_complete"}:
        return False
    if action_id in {
        "select_or_enter_contract",
        "hotfix_post_action_summary",
        "recover_dirty_without_contract_first_evidence",
    }:
        return True
    source = str(action.get("source") or "").strip()
    if source and source != "contract_state":
        return False
    if action_id == "select_successor_contract" and action.get(
        "successor_contract_candidates"
    ):
        return True
    selected_state = action.get("selected_successor_contract_state")
    if not isinstance(selected_state, Mapping) or not selected_state:
        return False
    ordered_steps = action.get("ordered_missing_steps")
    if isinstance(ordered_steps, list) and ordered_steps:
        return True
    missing_source = str(action.get("ordered_missing_steps_source") or "").strip().lower()
    if "successor" in precedence and (
        "missing_step" in precedence or "contract_selection" in precedence
    ):
        return True
    return (
        missing_source
        in {
            "selected_successor_contract_state",
            "nested_successor_contract_state",
            "deep_successor_contract_state",
        }
        or (
            missing_source.startswith("successor_depth_")
            and missing_source.endswith("_contract_state.v1")
        )
    )


def _observer_root_route_contract_action_requires_execution_supervisor(
    action: Mapping[str, Any],
) -> bool:
    action_id = str(action.get("id") or action.get("action") or "").strip()
    if action_id in {
        "bounded_implementation_worker_dispatch",
        "dispatch_bounded_worker",
        "implementation",
        "record_implementation",
    }:
        return True
    action_name = str(action.get("action") or "").strip()
    return action_name in {
        "dispatch_bounded_worker",
        "record_implementation",
    }


def _observer_root_route_dirty_files_from_request_or_git(
    *,
    project_id: str,
    close_planning_body: Mapping[str, Any] | None,
) -> list[str]:
    body = close_planning_body if isinstance(close_planning_body, Mapping) else {}
    supplied = _string_list_field(
        body.get("dirty_files")
        or body.get("target_dirty_files")
        or body.get("dirty_scope_files")
        or body.get("changed_files")
        or ""
    )
    if supplied:
        return filter_dirty_files(supplied)

    self_root = Path(__file__).resolve().parents[2]
    project_entry = project_service.get_project(project_id)
    if project_entry and project_entry.get("workspace_path"):
        root = Path(str(project_entry["workspace_path"])).resolve()
    elif project_id == "aming-claw":
        root = self_root
    else:
        return []
    porcelain = _git_output(root, ["status", "--porcelain"])
    if not porcelain:
        return []
    return filter_dirty_files(parse_git_porcelain_paths(porcelain))


def _observer_root_route_has_contract_first_entry(
    events: list[dict[str, Any]],
) -> bool:
    contract_entry_kinds = {
        "contract_binding",
        "contract_bound",
        "contract_revision_created",
        "contract_revision_changed",
        "contract_state_changed",
        "hotfix_entered",
    }
    for event in events:
        event_kind = str(
            event.get("event_kind")
            or event.get("kind")
            or event.get("event_type")
            or ""
        ).strip()
        if event_kind not in contract_entry_kinds:
            continue
        status = str(event.get("status") or "").strip().lower()
        if status in {
            "accepted",
            "allowed",
            "complete",
            "completed",
            "ok",
            "passed",
            "succeeded",
        }:
            return True
    return False


def _observer_root_route_dirty_without_contract_step(
    *,
    project_id: str,
    backlog_id: str,
    row_target_files: list[str],
    events: list[dict[str, Any]],
    contract_state: Mapping[str, Any],
    close_planning_body: Mapping[str, Any] | None,
) -> dict[str, Any]:
    if not bool(contract_state.get("legacy_no_contract")):
        return {}
    if _observer_root_route_has_contract_first_entry(events):
        return {}
    dirty_files = _observer_root_route_dirty_files_from_request_or_git(
        project_id=project_id,
        close_planning_body=close_planning_body,
    )
    if not dirty_files:
        return {}
    target_files = set(row_target_files or [])
    dirty_target_files = sorted(
        path for path in dirty_files if not target_files or path in target_files
    )
    if not dirty_target_files:
        return {}
    return {
        "id": "recover_dirty_without_contract_first_evidence",
        "action": "record_late_recovery_or_audit_close_decision",
        "reason": (
            "target files are already dirty but this row has no accepted contract "
            "binding or hotfix_entered pre-mutation evidence"
        ),
        "detail": (
            "record a late-recovery/audit decision before continuing; do not "
            "pretend the clean contract-first path was followed"
        ),
        "source": "runtime_dirty_guard",
        "precedence": "dirty_without_contract_first_evidence",
        "recovery_state": "dirty_without_contract_first_evidence",
        "dirty_files": dirty_files,
        "dirty_target_files": dirty_target_files,
        "backlog_id": backlog_id,
        "project_id": project_id,
    }


def _observer_root_route_normalize_action(value: Any) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(".", "_")


def _observer_root_route_close_planning_body(source: Any) -> dict[str, Any]:
    """Return body fields that affect close planning without exposing secrets."""

    if not isinstance(source, Mapping):
        return {}
    nested_context = source.get("close_context")
    close_context = nested_context if isinstance(nested_context, Mapping) else {}
    keys = (
        "close_commit",
        "close_commit_sha",
        "requested_close_commit",
        "requested_commit",
        "commit",
        "commit_sha",
        "implementation_commit",
        "target_head_commit",
        "head_commit",
    )
    for container in (source, close_context):
        for key in keys:
            value = str(container.get(key) or "").strip()
            if value:
                return {"close_commit": value}
    return {}


def _observer_root_route_close_evidence_refs(
    events: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    refs: list[dict[str, Any]] = []
    seen: set[str] = set()
    close_evidence_kinds = {
        "route_context",
        "route_action_precheck",
        "bounded_implementation_worker_dispatch",
        "dispatch_bounded_worker",
        "mf_subagent_dispatch",
        "mf_subagent_startup",
        "implementation",
        "verification",
        "qa_review",
        "independent_verification",
        "independent_verification_lane",
        "independent_qa",
        "independent_qa_lane",
        "qa_verification",
        "close_ready",
    }

    def _evidence_markers(value: Any) -> list[str]:
        markers: list[str] = []

        def _add(candidate: Any) -> None:
            text = _observer_root_route_normalize_action(candidate)
            if text and text not in markers:
                markers.append(text)

        if isinstance(value, Mapping):
            for field in ("requirement_id", "id", "event_kind", "phase", "action"):
                _add(value.get(field))
            for field in ("requirement_ids", "required_evidence"):
                items = value.get(field)
                if isinstance(items, list):
                    for item in items:
                        _add(item)
            contract_evidence = value.get("contract_evidence")
            if isinstance(contract_evidence, list):
                for item in contract_evidence:
                    markers.extend(_evidence_markers(item))
            for field in ("payload", "verification"):
                child = value.get(field)
                if isinstance(child, Mapping):
                    markers.extend(_evidence_markers(child))
        return list(dict.fromkeys(markers))

    for event in events:
        if not isinstance(event, Mapping):
            continue
        event_id = str(event.get("id") or event.get("event_id") or "").strip()
        if not event_id:
            continue
        event_kind = str(event.get("event_kind") or "").strip()
        phase = str(event.get("phase") or "").strip()
        markers = _evidence_markers(event)
        evidence_kind = next(
            (marker for marker in markers if marker in close_evidence_kinds),
            "",
        )
        if phase == "verification" and _observer_root_route_normalize_action(event_kind) in {
            "independent_verification",
            "qa_review",
            "qa_verification",
        }:
            evidence_kind = "verification"
        if not evidence_kind:
            continue
        ref = f"timeline:{event_id}"
        if ref in seen:
            continue
        seen.add(ref)
        item = {
            "ref": ref,
            "event_kind": event_kind,
            "phase": phase,
            "status": str(event.get("status") or event.get("decision") or ""),
        }
        if evidence_kind != event_kind:
            item["evidence_kind"] = evidence_kind
        refs.append({key: value for key, value in item.items() if value})
    return refs


def _observer_root_route_close_action_card(
    close_gate: Mapping[str, Any],
    route_token_ref_projection: Mapping[str, Any],
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    target_files: list[str],
    events: list[dict[str, Any]],
    backlog_status: str = "",
) -> dict[str, Any]:
    passed = bool(close_gate.get("passed"))
    normalized_backlog_status = str(backlog_status or "").strip().upper()
    backlog_is_terminal = normalized_backlog_status in _BACKLOG_CLOSED_STATUSES
    current_ref = str(route_token_ref_projection.get("route_token_ref") or "").strip()
    current_allowed_actions = [
        str(item or "").strip()
        for item in (route_token_ref_projection.get("allowed_actions") or [])
        if str(item or "").strip()
    ]
    current_allowed_set = {
        _observer_root_route_normalize_action(action)
        for action in current_allowed_actions
        if action
    }
    has_close_ref = bool(current_ref and "backlog_close" in current_allowed_set)
    evidence_refs = _observer_root_route_close_evidence_refs(events)
    seen_refs = {str(item.get("ref") or "") for item in evidence_refs}
    for ref in route_token_ref_projection.get("evidence_refs") or []:
        ref_text = str(ref or "").strip()
        if not ref_text or ref_text in seen_refs:
            continue
        seen_refs.add(ref_text)
        evidence_refs.append({"ref": ref_text, "source": "route_token_ref"})

    required_scope = {
        "project_id": project_id,
        "backlog_id": backlog_id,
    }
    if task_id:
        required_scope["task_id"] = task_id

    issue_body = {
        "caller_role": "observer",
        "backlog_id": backlog_id,
        "task_id": task_id or backlog_id,
        "target_files": target_files,
        "allowed_actions": ["backlog_close"],
        "evidence_refs": [
            str(item.get("ref") or "").strip()
            for item in evidence_refs
            if str(item.get("ref") or "").strip()
        ],
    }
    parent_identity = (
        route_token_ref_projection.get("identity")
        if isinstance(route_token_ref_projection.get("identity"), Mapping)
        else {}
    )
    parent_identity_complete = all(
        str(parent_identity.get(field) or "").strip()
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
    )
    if current_ref and parent_identity_complete:
        issue_body["parent_route_token_ref"] = current_ref
    for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS:
        value = str(parent_identity.get(field) or "").strip()
        if value:
            issue_body[f"parent_{field}"] = value

    card = {
        "schema_version": "observer_root_route_close_action_card.v1",
        "action": "backlog_close",
        "allowed_action": "backlog_close",
        "protected_action": True,
        "close_gate_passed": passed,
        "status": "blocked",
        "protected_entrypoint": {
            "method": "POST",
            "path": "/api/backlog/{project_id}/{bug_id}/close",
            "path_params": {"project_id": project_id, "bug_id": backlog_id},
            "mcp_tool": "backlog_close",
        },
        "route_token_issue_entrypoint": {
            "method": "POST",
            "path": "/api/projects/{project_id}/observer/route-context/issue",
            "path_params": {"project_id": project_id},
            "mcp_tool": "observer_route_context_issue",
        },
        "required_scope": required_scope,
        "current_route_token_ref": current_ref,
        "current_route_token_allowed_actions": current_allowed_actions,
        "route_token_ref_resolved": bool(route_token_ref_projection.get("resolved")),
        "evidence_refs": evidence_refs,
        "issue_route_token_request": issue_body,
        "raw_route_token_exposed": False,
        "raw_secret_exposed": False,
    }
    if current_ref and not parent_identity_complete:
        card["current_route_token_ref_parent_omitted"] = True
        card["current_route_token_ref_parent_omitted_reason"] = (
            "current route_token_ref is not resolvable as the parent close "
            "route identity; mint the close-scoped token from close-gate "
            "evidence without attaching that unresolved parent ref"
        )
    if not target_files:
        card["target_files_required"] = True
        card["target_files_hint"] = (
            "route-token issue requires target_files from the backlog row, "
            "contract scope, or owned-file fence"
        )
    if backlog_is_terminal:
        card.update(
            {
                "action": "done",
                "allowed_action": "",
                "protected_action": False,
                "status": "done",
                "terminal": True,
                "terminal_status": normalized_backlog_status,
                "classification": (
                    "already_fixed"
                    if normalized_backlog_status == "FIXED"
                    else "already_terminal"
                ),
                "route_token_refresh_required": False,
                "detail": (
                    f"backlog row is already {normalized_backlog_status}; "
                    "no backlog_close action is required"
                ),
            }
        )
        card.pop("issue_route_token_request", None)
        return card
    close_commit_evidence_gate = close_gate.get("close_commit_evidence_gate") or {}
    close_commit_missing_for_planning = (
        isinstance(close_commit_evidence_gate, Mapping)
        and close_commit_evidence_gate.get("status") == "not_applicable"
        and close_commit_evidence_gate.get("reason") == "close_commit_not_supplied"
    )
    if close_commit_missing_for_planning:
        card.update(
            {
                "action": "provide_close_commit_for_close_planning",
                "allowed_action": "",
                "protected_action": False,
                "status": "close_commit_required",
                "close_commit_required": True,
                "route_token_refresh_required": False,
                "next_action": "provide_close_commit_for_close_planning",
                "detail": (
                    "observer-root-route close planning requires the intended "
                    "close commit before advertising backlog_close; rerun "
                    "observer-root-route-context or backlog_close planning with "
                    "close_commit, commit, commit_sha, target_head_commit, or "
                    "head_commit"
                ),
                "accepted_commit_fields": [
                    "close_commit",
                    "commit",
                    "commit_sha",
                    "target_head_commit",
                    "head_commit",
                ],
                "close_commit_evidence_gate": dict(close_commit_evidence_gate),
            }
        )
        for field in (
            "protected_entrypoint",
            "route_token_issue_entrypoint",
            "issue_route_token_request",
        ):
            card.pop(field, None)
        return card
    if not passed:
        close_commit = (
            str(close_commit_evidence_gate.get("close_commit") or "").strip()
            if isinstance(close_commit_evidence_gate, Mapping)
            else ""
        )
        next_action = "satisfy_close_gate_before_backlog_close"
        detail = "close gate is not yet passed; follow missing close evidence first"
        close_commit_fields: dict[str, Any] = {}
        if close_commit:
            next_action = "record_close_ready_for_close_commit"
            detail = (
                "close gate is not yet passed; record close-satisfying timeline "
                f"evidence for close commit {close_commit} before backlog_close"
            )
            close_commit_fields = {
                "close_commit": close_commit,
                "close_commit_source": close_commit_evidence_gate.get(
                    "close_commit_source"
                ),
                "latest_evidence_commit": close_commit_evidence_gate.get(
                    "latest_evidence_commit"
                ),
                "close_commit_evidence_gate": dict(close_commit_evidence_gate),
            }
        card.update(
            {
                "next_action": next_action,
                "detail": detail,
                "missing_event_kinds": close_gate.get("missing_event_kinds") or [],
                "missing_evidence_groups": close_gate.get("missing_evidence_groups") or {},
                **{
                    key: value
                    for key, value in close_commit_fields.items()
                    if value not in ("", [], {})
                },
            }
        )
        return card
    if has_close_ref:
        card.update(
            {
                "status": "ready",
                "next_action": "backlog_close",
                "route_token_ref": current_ref,
                "route_token_refresh_required": False,
                "detail": (
                    "close gate passed and current route_token_ref authorizes "
                    "backlog_close; call backlog_close by ref"
                ),
            }
        )
    else:
        card.update(
            {
                "status": "refresh_required",
                "next_action": "issue_close_scoped_route_token_ref",
                "route_token_refresh_required": True,
                "classification": "expected_action_token_refresh",
                "expected_behavior": True,
                "is_system_bug": False,
                "do_not_waive": True,
                "detail": (
                    "close gate passed, but the current route_token_ref does not "
                    "authorize backlog_close; mint a close-scoped route_token_ref "
                    "with allowed_actions=['backlog_close'], then call backlog_close by ref"
                ),
            }
        )
    return card


def _observer_root_route_close_next_legal_action(
    close_action_card: Mapping[str, Any],
) -> dict[str, Any]:
    if close_action_card.get("terminal"):
        action_id = "done"
        next_action = {
            "id": action_id,
            "action": action_id,
            "status": str(close_action_card.get("status") or "done"),
            "detail": str(close_action_card.get("detail") or ""),
            "source": "close_gate_projection",
            "precedence": "backlog_terminal_status",
            "terminal_status": str(close_action_card.get("terminal_status") or ""),
            "action_card": dict(close_action_card),
        }
        scope = close_action_card.get("required_scope")
        if isinstance(scope, Mapping):
            for field in ("project_id", "backlog_id", "task_id"):
                value = str(scope.get(field) or "").strip()
                if value:
                    next_action[field] = value
        return {key: value for key, value in next_action.items() if value}
    if not close_action_card.get("close_gate_passed"):
        return {}
    action_id = str(close_action_card.get("next_action") or "").strip()
    if not action_id:
        return {}
    next_action = {
        "id": action_id,
        "action": action_id,
        "detail": str(close_action_card.get("detail") or ""),
        "source": "close_gate_projection",
        "precedence": "close_gate_passed",
        "action_card": dict(close_action_card),
    }
    allowed_action = str(close_action_card.get("allowed_action") or "").strip()
    if allowed_action:
        next_action["allowed_action"] = allowed_action
    next_action["protected_action"] = bool(close_action_card.get("protected_action"))
    scope = close_action_card.get("required_scope")
    if isinstance(scope, Mapping):
        for field in ("project_id", "backlog_id", "task_id"):
            value = str(scope.get(field) or "").strip()
            if value:
                next_action[field] = value
    route_token_ref = str(
        close_action_card.get("route_token_ref")
        or close_action_card.get("current_route_token_ref")
        or ""
    ).strip()
    if route_token_ref:
        next_action["route_token_ref"] = route_token_ref
    return next_action


def _observer_root_route_close_action_drives_next_step(
    close_action_card: Mapping[str, Any],
    close_next_legal_action: Mapping[str, Any],
) -> bool:
    if not close_next_legal_action:
        return False
    if close_action_card.get("terminal"):
        return True
    if not close_action_card.get("close_gate_passed"):
        return False
    status = str(close_action_card.get("status") or "").strip()
    return status in {"close_commit_required", "ready", "refresh_required"}


def _observer_root_route_projection_authorizes_action(
    projection: Mapping[str, Any],
    action: str,
) -> bool:
    normalized_action = _observer_root_route_normalize_action(action)
    allowed = {
        _observer_root_route_normalize_action(item)
        for item in projection.get("allowed_actions") or []
        if str(item or "").strip()
    }
    return bool(projection.get("resolved") and normalized_action in allowed)


def _observer_root_route_close_ready_token_ref_candidates(
    event: Mapping[str, Any],
) -> list[str]:
    refs: list[str] = []

    def add(value: Any) -> None:
        text = str(value or "").strip()
        if text and text.startswith("rtok-") and text not in refs:
            refs.append(text)

    add(event.get("route_token_ref"))
    for container_key in ("payload", "verification"):
        container = event.get(container_key)
        if not isinstance(container, Mapping):
            continue
        add(container.get("route_token_ref"))
        gate = container.get("route_token_gate")
        if isinstance(gate, Mapping):
            add(gate.get("route_token_ref"))
    gate = event.get("route_token_gate")
    if isinstance(gate, Mapping):
        add(gate.get("route_token_ref"))
    return refs


def _observer_root_route_event_order(event: Mapping[str, Any]) -> int:
    for key in ("id", "event_id"):
        try:
            return int(event.get(key) or 0)
        except Exception:
            continue
    return 0


def _observer_root_route_close_ready_route_token_ref_projection(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    events: list[dict[str, Any]],
) -> dict[str, Any]:
    for event in sorted(
        (item for item in events if isinstance(item, Mapping)),
        key=_observer_root_route_event_order,
        reverse=True,
    ):
        event_kind = _observer_root_route_normalize_action(
            event.get("event_kind") or event.get("event_type")
        )
        if event_kind != "close_ready":
            continue
        status = str(event.get("status") or event.get("decision") or "").strip().lower()
        if status not in {
            "accepted",
            "passed",
            "ok",
            "succeeded",
            "success",
            "complete",
            "completed",
        }:
            continue
        for route_token_ref in _observer_root_route_close_ready_token_ref_candidates(event):
            projection = _observer_root_route_identity_from_route_token_ref(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                task_id=task_id,
                route_token_ref=route_token_ref,
            )
            if _observer_root_route_projection_authorizes_action(
                projection,
                "backlog_close",
            ):
                projection["source"] = "close_ready_route_token_ref"
                projection["source_event_ref"] = (
                    f"timeline:{_observer_root_route_event_order(event)}"
                )
                return projection
    return {}


def _timeline_gate_backlog_close_route_token_request_hint(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    row: Mapping[str, Any],
    contract: Mapping[str, Any],
    verification: Mapping[str, Any],
    events: list[dict[str, Any]],
    query: Mapping[str, Any],
) -> dict[str, Any]:
    """Project the protected backlog_close authorization step for repair view."""

    if not bool(verification.get("passed") or verification.get("can_close")):
        return {}
    task_id = str(
        query.get("task_id")
        or _row_get(row, "current_task_id", "")
        or _row_get(row, "root_task_id", "")
        or backlog_id
    ).strip()
    row_target_files = _string_list_field(_row_get(row, "target_files", ""))
    contract_target_files = _string_list_field(contract.get("target_files"))
    route_token_ref_projection = _observer_root_route_identity_from_route_token_ref(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
        route_token_ref=query.get("route_token_ref", ""),
    )
    if not _observer_root_route_projection_authorizes_action(
        route_token_ref_projection,
        "backlog_close",
    ):
        close_ready_projection = _observer_root_route_close_ready_route_token_ref_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            events=events,
        )
        if close_ready_projection:
            route_token_ref_projection = close_ready_projection
    action_card = _observer_root_route_close_action_card(
        verification,
        route_token_ref_projection,
        project_id=project_id,
        backlog_id=backlog_id,
        backlog_status=str(_row_get(row, "status", "")),
        task_id=task_id,
        target_files=row_target_files or contract_target_files,
        events=events,
    )
    if action_card.get("terminal"):
        return {
            "schema_version": "mf_timeline_precheck_backlog_close_route_token_hint.v1",
            "action": str(action_card.get("action") or "done"),
            "status": str(action_card.get("status") or "done"),
            "close_evidence_ready": True,
            "backlog_close_authorized": False,
            "authorization_required": False,
            "terminal": True,
            "terminal_status": str(action_card.get("terminal_status") or ""),
            "detail": str(action_card.get("detail") or ""),
            "raw_route_token_exposed": False,
            "raw_secret_exposed": False,
        }

    issue_request = (
        dict(action_card.get("issue_route_token_request") or {})
        if isinstance(action_card.get("issue_route_token_request"), Mapping)
        else {}
    )
    target_files = (
        issue_request.get("target_files") or row_target_files or contract_target_files
    )
    evidence_refs = action_card.get("evidence_refs") or _observer_root_route_close_evidence_refs(
        events
    )
    if not issue_request:
        issue_request = {
            "caller_role": "observer",
            "backlog_id": backlog_id,
            "task_id": task_id,
            "target_files": target_files,
            "allowed_actions": ["backlog_close"],
            "evidence_refs": [
                str(item.get("ref") or "").strip()
                for item in evidence_refs
                if isinstance(item, Mapping) and str(item.get("ref") or "").strip()
            ],
        }
    card_status = str(action_card.get("status") or "refresh_required")
    authorized = card_status == "ready"
    hint = {
        "schema_version": "mf_timeline_precheck_backlog_close_route_token_hint.v1",
        "action": (
            "backlog_close"
            if authorized
            else "issue_close_scoped_route_token_ref"
        ),
        "status": "ready" if authorized else "refresh_required",
        "close_evidence_ready": True,
        "backlog_close_authorized": authorized,
        "authorization_required": not authorized,
        "evidence_vs_authorization": (
            "can_close=true means close evidence is ready; backlog_close is a "
            "separate protected action and requires a route token/ref whose "
            "allowed_actions include backlog_close."
        ),
        "allowed_action": "backlog_close",
        "allowed_actions": ["backlog_close"],
        "protected_action": True,
        "backlog_id": backlog_id,
        "task_id": task_id,
        "target_files": target_files,
        "evidence_refs": evidence_refs,
        "issue_route_token_request": issue_request,
        "protected_entrypoint": action_card.get("protected_entrypoint")
        or {
            "method": "POST",
            "path": "/api/backlog/{project_id}/{bug_id}/close",
            "path_params": {"project_id": project_id, "bug_id": backlog_id},
            "mcp_tool": "backlog_close",
        },
        "route_token_issue_entrypoint": action_card.get("route_token_issue_entrypoint")
        or {
            "method": "POST",
            "path": "/api/projects/{project_id}/observer/route-context/issue",
            "path_params": {"project_id": project_id},
            "mcp_tool": "observer_route_context_issue",
        },
        "current_route_token_ref": str(
            action_card.get("current_route_token_ref") or ""
        ),
        "current_route_token_allowed_actions": action_card.get(
            "current_route_token_allowed_actions"
        )
        or [],
        "route_token_refresh_required": not authorized,
        "raw_route_token_exposed": False,
        "raw_secret_exposed": False,
        "detail": str(action_card.get("detail") or ""),
    }
    route_token_ref = str(action_card.get("route_token_ref") or "").strip()
    if route_token_ref:
        hint["route_token_ref"] = route_token_ref
    if authorized:
        hint.pop("issue_route_token_request", None)
        hint.pop("route_token_issue_entrypoint", None)
    return {key: value for key, value in hint.items() if value not in ("", [], {})}


def _observer_root_route_identity_from_route_token_ref(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str = "",
    route_token_ref: Any = "",
) -> dict[str, Any]:
    token_ref = str(route_token_ref or "").strip()
    if not token_ref:
        return {
            "schema_version": "observer_root_route_token_ref_projection.v1",
            "route_token_ref": "",
            "resolved": False,
            "identity": {},
        }
    from . import observer_route_context as _orc

    try:
        resolved = _orc.resolve_route_token_ref(
            conn,
            project_id=project_id,
            storage_project_id=_route_registry_storage_project_id(project_id),
            route_token_ref=token_ref,
            backlog_id=backlog_id,
            task_id=task_id,
        )
    except _orc.RouteTokenRefError as exc:
        return {
            "schema_version": "observer_root_route_token_ref_projection.v1",
            "route_token_ref": token_ref,
            "resolved": False,
            "identity": {},
            "error": str(exc),
        }
    if not isinstance(resolved, Mapping):
        return {
            "schema_version": "observer_root_route_token_ref_projection.v1",
            "route_token_ref": token_ref,
            "resolved": False,
            "identity": {},
            "error": "route_token_ref_not_registered",
        }
    identity = {
        field: str(resolved.get(field) or "").strip()
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
        if str(resolved.get(field) or "").strip()
    }
    allowed_actions = [
        str(item or "").strip()
        for item in (resolved.get("allowed_actions") or [])
        if str(item or "").strip()
    ]
    evidence_refs = [
        str(item or "").strip()
        for item in (resolved.get("evidence_refs") or [])
        if str(item or "").strip()
    ]
    return {
        "schema_version": "observer_root_route_token_ref_projection.v1",
        "route_token_ref": token_ref,
        "resolved": bool(identity),
        "identity": identity,
        "binding_source": "observer_route_token_refs",
        "allowed_actions": allowed_actions,
        "evidence_refs": evidence_refs,
        "scope": resolved.get("scope") if isinstance(resolved.get("scope"), Mapping) else {},
        "expires_at": str(resolved.get("expires_at") or ""),
        "status": str(resolved.get("status") or ""),
        "caller_role": str(resolved.get("caller_role") or ""),
    }


def _is_plausible_graph_trace_id(value: Any) -> bool:
    """Defensive format check for a caller-supplied graph query schema trace id.

    Accepts the documented gqt-YYYYMMDD-<hex> format.  This is a string-only
    check — no server-side ledger resolution is attempted.  Invalid or
    unsupported formats are silently dropped so callers cannot inject arbitrary
    strings into the response field.
    """
    import re

    s = str(value or "").strip()
    if not s:
        return False
    # Documented format: gqt-YYYYMMDD-<hex chars>
    return bool(re.match(r"^gqt-\d{8}-[0-9a-f]+$", s))


def _observer_root_route_ordered_missing_steps(
    *,
    route_context_gate: Mapping[str, Any],
    transition_gate: Mapping[str, Any],
    canonical_route_identity: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Return ordered recovery steps for root observer route-context projection."""

    present = {
        str(item or "").strip()
        for item in (route_context_gate.get("present_requirement_ids") or [])
        if str(item or "").strip()
    }
    missing = {
        str(item or "").strip()
        for item in (route_context_gate.get("missing_requirement_ids") or [])
        if str(item or "").strip()
    }
    transition_missing = {
        str(item or "").strip()
        for item in (transition_gate.get("missing") or [])
        if str(item or "").strip()
    }
    identity_missing = [
        field
        for field in observer_session.ROOT_ROUTE_CONTEXT_CANONICAL_IDENTITY_FIELDS
        if not str(canonical_route_identity.get(field) or "").strip()
    ]
    steps: list[dict[str, Any]] = []

    def _add(step_id: str, action: str, reason: str, **extra: Any) -> None:
        if any(step["id"] == step_id for step in steps):
            return
        step: dict[str, Any] = {
            "id": step_id,
            "action": action,
            "reason": reason,
        }
        step.update({key: value for key, value in extra.items() if value not in ("", [], {})})
        steps.append(step)

    if identity_missing:
        _add(
            "canonical_route_identity",
            "record_or_repair_canonical_route_identity",
            "canonical route identity is incomplete",
            missing_fields=identity_missing,
        )
    if "route_context" in missing or (
        bool(route_context_gate.get("required")) and "route_context" not in present
    ):
        _add(
            "route_context",
            "record_route_context",
            "route_context evidence is required before execution-supervisor lineage",
        )
    if (
        "route_action_precheck" in missing
        or "route_action_precheck_bound_to_canonical_route" in transition_missing
    ):
        _add(
            "route_action_precheck",
            "record_route_action_precheck",
            "route_action_precheck must be accepted and bound to the canonical route identity",
        )
    if "work_mode_transition_event" in transition_missing:
        _add(
            "observer_work_mode_transition",
            "record_work_mode_transition",
            "observer_work_mode_transition must be accepted before execution-supervisor mode",
        )
    return steps


def _source_backed_onboarding_enabled(contract: Mapping[str, Any]) -> bool:
    if not isinstance(contract, Mapping):
        return False
    candidates: list[str] = []
    nested = contract.get("contract")
    if isinstance(nested, Mapping):
        for key in (
            "root_contract_definition_id",
            "contract_definition_id",
            "source_contract_id",
            "contract_id",
        ):
            value = str(nested.get(key) or "").strip()
            if value:
                candidates.append(value)
    for key in (
        "root_contract_definition_id",
        "contract_definition_id",
        "source_contract_id",
    ):
        value = str(contract.get(key) or "").strip()
        if value:
            candidates.append(value)
    return "onboard_contract" in candidates


def _contract_runtime_store(conn) -> SQLiteContractExecutionStore:
    return SQLiteContractExecutionStore(conn)


_CONTRACT_DEFINITION_REGISTRY = ContractDefinitionRegistry()


def _contract_runtime(conn) -> ContractRuntime:
    return ContractRuntime(
        _CONTRACT_DEFINITION_REGISTRY,
        store=_contract_runtime_store(conn),
    )


def _contract_runtime_stable_id(prefix: str, *parts: Any) -> str:
    raw = "|".join(str(part or "") for part in parts)
    return f"{prefix}-{hashlib.sha256(raw.encode('utf-8')).hexdigest()[:20]}"


def _contract_runtime_submit_line_guidance(guide: Mapping[str, Any]) -> dict[str, Any]:
    next_action = (
        guide.get("next_legal_action")
        if isinstance(guide.get("next_legal_action"), Mapping)
        else {}
    )
    recovery_guidance = (
        next_action.get("submit_line_guidance")
        if isinstance(next_action.get("submit_line_guidance"), Mapping)
        else {}
    )
    if (
        recovery_guidance.get("generic_contract_runtime_submit_line_allowed")
        is False
    ):
        return dict(recovery_guidance)
    safe_copy = (
        guide.get("writer_role_safe_copy_payload")
        if isinstance(guide.get("writer_role_safe_copy_payload"), Mapping)
        else {}
    )
    copy_payload = (
        safe_copy.get("copy_payload")
        if isinstance(safe_copy.get("copy_payload"), Mapping)
        else {}
    )
    required_hash = str(copy_payload.get("runtime_guide_hash") or "")
    guidance = {
        "schema_version": "contract_runtime.submit_line_guidance.v1",
        "required_runtime_guide_hash_source": (
            "writer_role_safe_copy_payload.copy_payload.runtime_guide_hash"
        ),
        "target_writer_line_runtime_guide_hash_source": (
            "writer_role_safe_copy_payload.copy_payload.runtime_guide_hash"
        ),
        "every_line_must_copy_current_writer_hash": True,
        "hash_may_change_after_each_accepted_line": True,
        "writer_hash_may_change_after_each_accepted_line": True,
        "top_level_runtime_guide_hash_is_reader_hash": True,
        "copy_payload_available": bool(copy_payload),
        "message": (
            "For every contract_runtime_submit_line, copy "
            "writer_role_safe_copy_payload.copy_payload.runtime_guide_hash: "
            "the runtime_guide_hash from writer_role_safe_copy_payload."
            "copy_payload for the target writer line in the current guide. "
            "Re-read after each accepted line because the writer hash may "
            "change."
        ),
    }
    if required_hash:
        guidance["current_required_runtime_guide_hash"] = required_hash
    projection_guidance = (
        guide.get("post_projection_submit_line_guidance")
        if isinstance(guide.get("post_projection_submit_line_guidance"), Mapping)
        else {}
    )
    if projection_guidance:
        guidance["completed_lines_projection_present"] = True
        guidance["post_projection_submit_line_guidance"] = dict(projection_guidance)
        guidance["re_read_contract_runtime_current_after_projection"] = bool(
            projection_guidance.get("re_read_contract_runtime_current_required")
        )
        guidance["skip_duplicate_submit_line_when_projected_or_complete"] = bool(
            projection_guidance.get(
                "skip_duplicate_submit_line_when_projected_or_complete"
            )
        )
        guidance["skip_duplicate_submit_line_when_target_line_projected_or_complete"] = bool(
            projection_guidance.get(
                "skip_duplicate_submit_line_when_target_line_projected_or_complete"
            )
        )
        guidance["duplicate_submit_line_required"] = False
        guidance["projected_completed_lines_count"] = int(
            projection_guidance.get("projected_completed_lines_count") or 0
        )
        guidance["projected_line_ids"] = list(
            projection_guidance.get("projected_line_ids") or []
        )
    else:
        guidance["completed_lines_projection_present"] = False
    return guidance


_MF_SUB_HOST_BRIDGE_REQUIRED_FIELDS = (
    "runtime_context_id",
    "task_id",
    "parent_task_id",
    "fence_token",
    "target_project_root",
    "session_token_ref",
)


def _contract_runtime_next_action_requires_mf_sub(
    next_action: Mapping[str, Any],
) -> bool:
    roles = {
        str(role or "").strip().lower().replace("-", "_")
        for role in (next_action.get("allowed_writer_roles") or [])
    }
    owner_role = str(next_action.get("owner_role") or "").strip().lower().replace(
        "-",
        "_",
    )
    worker_role = str(next_action.get("worker_role") or "").strip().lower().replace(
        "-",
        "_",
    )
    return "mf_sub" in roles or owner_role == "mf_sub" or worker_role == "mf_sub"


def _mf_sub_capacity_fallback_guidance(
    *,
    runtime_context_id: str = "",
    task_id: str = "",
    parent_task_id: str = "",
    fence_token: str = "",
    target_project_root: str = "",
    session_token_ref: str = "",
    worker_id: str = "",
    worker_slot_id: str = "",
    merge_queue_id: str = "",
    route_identity: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    def _copy_value(value: str, placeholder: str) -> str:
        text = str(value or "").strip()
        return text or placeholder

    preserved_identity = {
        "runtime_context_id": _copy_value(runtime_context_id, "<worker runtime_context_id>"),
        "task_id": _copy_value(task_id, "<worker task_id>"),
        "parent_task_id": _copy_value(parent_task_id, "<parent MF task_id>"),
        "fence_token": _copy_value(
            fence_token,
            "<same fence_token from the bounded worker runtime envelope>",
        ),
        "target_project_root": _copy_value(
            target_project_root,
            "<runtime-context canonical target_project_root>",
        ),
        "session_token_ref": _copy_value(
            session_token_ref,
            "<copy-safe worker session_token_ref>",
        ),
    }
    worker_identity = {
        "worker_id": _copy_value(worker_id, "<allocated worker id>"),
        "worker_slot_id": _copy_value(worker_slot_id or worker_id, "<worker slot id>"),
    }
    safe_route_identity = {
        field: str((route_identity or {}).get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    safe_route_identity = {
        field: value for field, value in safe_route_identity.items() if value
    }
    preserved_dispatch = {
        **preserved_identity,
        **worker_identity,
        "merge_queue_id": _copy_value(merge_queue_id, "<runtime_context merge_queue_id>"),
        "route_identity": safe_route_identity,
    }
    return {
        "schema_version": "mf_sub.capacity_fallback_guidance.v1",
        "trigger": "codex_subagent_spawn_capacity_or_thread_limit",
        "status": "fallbacks_available_without_identity_change",
        "preserve_runtime_identity": preserved_identity,
        "required_identity_fields": list(preserved_identity.keys()),
        "official_fallback_options": [
            "reuse_existing_idle_subagent_same_runtime_envelope",
            "queue_dispatch_until_capacity_available",
            "stop_and_record_capacity_blocker",
        ],
        "fallback_options": [
            {
                "id": "reuse_existing_idle_subagent_same_runtime_envelope",
                "action": "reuse_existing_idle_subagent",
                "allowed_when": (
                    "an idle host-created subagent can receive the exact same "
                    "bounded runtime envelope"
                ),
                "requires": dict(preserved_dispatch),
                "worker_evidence_rule": (
                    "the reused worker must author its own read receipt, startup, "
                    "implementation evidence, finish-time attestation, and finish gate"
                ),
            },
            {
                "id": "queue_dispatch_until_capacity_available",
                "action": "queue_bounded_worker_dispatch",
                "allowed_when": (
                    "no idle matching subagent is available but capacity is expected later"
                ),
                "queue_preserves": dict(preserved_dispatch),
                "worker_evidence_rule": (
                    "dispatch resumes with the same runtime_context_id, task_id, "
                    "parent_task_id, fence_token, target_project_root, and "
                    "session_token_ref"
                ),
            },
            {
                "id": "stop_and_record_capacity_blocker",
                "action": "record_blocker",
                "blocker_type": "subagent_capacity_or_thread_limit",
                "allowed_when": (
                    "no idle matching subagent and no queue slot are available"
                ),
                "blocker_preserves": dict(preserved_dispatch),
            },
        ],
        "forbidden_shortcuts": [
            "observer_authored_mf_sub_evidence",
            "raw_token_persistence",
            "change_runtime_identity_to_work_around_capacity",
            "mint_new_runtime_context_id_to_bypass_capacity",
            "change_task_id_or_parent_task_id_to_bypass_capacity",
            "replace_fence_token_to_bypass_capacity",
            "route_token_ref_as_session_auth",
            "post_hoc_worker_evidence_backfill",
        ],
        "privacy_boundary": {
            "raw_session_token_persisted": False,
            "raw_fence_token_persisted": False,
            "raw_route_token_persisted": False,
        },
    }


def _mf_sub_worker_host_envelope_handoff(
    *,
    project_id: str,
    runtime_context_id: str = "",
    task_id: str = "",
    parent_task_id: str = "",
    target_project_root: str = "",
    worker_id: str = "",
    worker_slot_id: str = "",
    session_token_ref: str = "",
    fence_token: str = "",
    merge_queue_id: str = "",
    route_identity: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    runtime_context_id = runtime_context_id or "<worker runtime_context_id>"
    task_id = task_id or "<worker task_id>"
    parent_task_id = parent_task_id or "<parent MF task_id>"
    target_project_root = (
        target_project_root or "<runtime-context canonical target_project_root>"
    )
    worker_id = worker_id or "<actual host-created worker id>"
    worker_slot_id = worker_slot_id or worker_id
    safe_route_identity = {
        field: str((route_identity or {}).get(field) or f"<{field}>").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    session_token_ref = session_token_ref or "<copy-safe worker session_token_ref>"
    common_body = {
        "project_id": project_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "contract_execution_id": parent_task_id,
        "target_project_root": target_project_root,
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "agent_id": worker_id,
        "actual_host_worker_id": worker_id,
        "worker_session_id": "<actual host worker session id>",
        "session_token_ref": session_token_ref,
        **safe_route_identity,
        "ttl_seconds": 3600,
    }
    capacity_fallback_guidance = _mf_sub_capacity_fallback_guidance(
        runtime_context_id=runtime_context_id,
        task_id=task_id,
        parent_task_id=parent_task_id,
        fence_token=fence_token,
        target_project_root=target_project_root,
        session_token_ref=session_token_ref,
        worker_id=worker_id,
        worker_slot_id=worker_slot_id,
        merge_queue_id=merge_queue_id,
        route_identity=safe_route_identity,
    )
    initial_join_body = {
        **common_body,
        "reason": "<operator reason: host adapter needs first worker auth env>",
    }
    rejoin_body = {
        **common_body,
        "reason": "<operator reason: live worker lost raw auth env>",
    }
    base_path = (
        f"/api/graph-governance/{project_id}/runtime-contexts/"
        f"{runtime_context_id}/session-token"
    )
    return {
        "schema_version": "runtime_context.mf_sub_worker_host_envelope_handoff.v1",
        "purpose": (
            "recover or establish raw worker auth env without persisting raw tokens"
        ),
        "raw_worker_env_required": [
            "AMING_WORKER_SESSION_TOKEN",
            "AMING_WORKER_FENCE_TOKEN",
        ],
        "delivery": "worker_host_envelope",
        "session_token_ref_policy": {
            "copy_safe": True,
            "session_token_ref_alone_authorizes_writes": False,
            "raw_session_token_persisted": False,
            "raw_fence_token_persisted": False,
        },
        "observer_boundary": {
            "observer_requests_host_envelope": True,
            "observer_injects_envelope_into_real_worker": True,
            "observer_authors_worker_evidence": False,
            "raw_tokens_persisted_to_timeline": False,
        },
        "initial_join": {
            "schema_version": "runtime_context.session_token_initial_join_submission.v1",
            "action": "request_runtime_context_initial_join_host_envelope",
            "tool": "runtime_context_session_token_initial_join",
            "method": "POST",
            "path": f"{base_path}/initial-join",
            "body_source": "copy_safe_body",
            "copy_safe_body": initial_join_body,
            "host_realization": {
                "mode": "replace_declared_placeholders_then_spread_to_mcp",
                "mcp_tool": "runtime_context_session_token_initial_join",
                "adapter_fields_included": ["project_id"],
                "required_replacements": ["worker_session_id", "reason"],
                "optional_omission_fields": [],
            },
            "valid_when_lineage_missing": [
                "mf_subagent_read_receipt",
                "mf_subagent_startup",
            ],
            "after_success": [
                "inject returned host_envelope env into the real mf_sub worker",
                "worker records read receipt",
                "worker records startup",
            ],
        },
        "rejoin": {
            "schema_version": "runtime_context.session_token_rejoin_submission.v1",
            "action": "request_runtime_context_rejoin_host_envelope",
            "tool": "runtime_context_session_token_rejoin",
            "method": "POST",
            "path": f"{base_path}/rejoin",
            "body_source": "copy_safe_body",
            "copy_safe_body": rejoin_body,
            "host_realization": {
                "mode": "replace_declared_placeholders_then_spread_to_mcp",
                "mcp_tool": "runtime_context_session_token_rejoin",
                "adapter_fields_included": ["project_id"],
                "required_replacements": ["worker_session_id", "reason"],
                "optional_omission_fields": [
                    "host_startup_id",
                    "host_session_id",
                ],
            },
            "required_existing_lineage": [
                "mf_subagent_read_receipt",
                "mf_subagent_startup",
            ],
            "after_success": [
                "inject returned host_envelope env into the same live mf_sub worker",
                (
                    "worker continues protected writes such as implementation "
                    "evidence or finish gate"
                ),
            ],
        },
        "decision_tree": [
            {
                "when": "raw worker env is missing before read receipt or startup",
                "action": "request_runtime_context_initial_join_host_envelope",
            },
            {
                "when": "raw worker env is missing after read receipt and startup",
                "action": "request_runtime_context_rejoin_host_envelope",
            },
        ],
        "capacity_fallback_guidance": capacity_fallback_guidance,
    }


def _contract_runtime_mf_sub_host_bridge_guidance(
    guide: Mapping[str, Any],
    *,
    blocked_action: str = "",
) -> dict[str, Any]:
    next_action = (
        guide.get("next_legal_action")
        if isinstance(guide.get("next_legal_action"), Mapping)
        else {}
    )
    if not isinstance(next_action, Mapping) or not _contract_runtime_next_action_requires_mf_sub(
        next_action
    ):
        return {}
    execution = guide.get("execution") if isinstance(guide.get("execution"), Mapping) else {}
    contract = guide.get("contract") if isinstance(guide.get("contract"), Mapping) else {}
    safe_copy = (
        guide.get("writer_role_safe_copy_payload")
        if isinstance(guide.get("writer_role_safe_copy_payload"), Mapping)
        else {}
    )
    copy_payload = (
        dict(safe_copy.get("copy_payload"))
        if isinstance(safe_copy.get("copy_payload"), Mapping)
        else {}
    )
    execution_id = str(execution.get("contract_execution_id") or "").strip()
    project_id = str(
        execution.get("project_id") or copy_payload.get("project_id") or ""
    )
    backlog_id = str(
        copy_payload.get("backlog_id") or execution.get("backlog_id") or ""
    ).strip()
    next_route_identity = (
        next_action.get("route_identity")
        if isinstance(next_action.get("route_identity"), Mapping)
        else {}
    )

    def _exact_text(value: Any) -> str:
        text = str(value or "").strip()
        if text.startswith("<") and text.endswith(">"):
            return ""
        return text

    dispatch_candidates: list[Mapping[str, Any]] = []
    completed_lines = guide.get("completed_lines")
    if isinstance(completed_lines, list):
        selector_fields = (
            "runtime_context_id",
            "task_id",
            "parent_task_id",
            "worker_id",
            "worker_slot_id",
        )
        selectors = {
            field: _exact_text(next_action.get(field))
            for field in selector_fields
            if _exact_text(next_action.get(field))
        }
        for completed_line in completed_lines:
            if not isinstance(completed_line, Mapping):
                continue
            if str(completed_line.get("stage_id") or "").strip() != "dispatch":
                continue
            if (
                str(completed_line.get("line_id") or "").strip()
                != "observer_dispatch_bounded_workers"
            ):
                continue
            if (
                str(completed_line.get("evidence_kind") or "").strip()
                != "dispatch_bounded_worker"
            ):
                continue
            for candidate in _contract_runtime_mapping_candidates(completed_line):
                if not all(
                    _exact_text(candidate.get(field))
                    for field in (
                        "runtime_context_id",
                        "task_id",
                        "target_project_root",
                    )
                ):
                    continue
                if not _exact_text(
                    candidate.get("worker_slot_id") or candidate.get("worker_id")
                ):
                    continue
                if any(
                    _exact_text(candidate.get(field))
                    and _exact_text(candidate.get(field)) != expected
                    for field, expected in selectors.items()
                ):
                    continue
                dispatch_candidates.append(candidate)

    def _dispatch_candidate_identity(
        candidate: Mapping[str, Any],
    ) -> tuple[str, str, str, str, str, str]:
        worker_identity = _exact_text(
            candidate.get("worker_slot_id") or candidate.get("worker_id")
        )
        return (
            _exact_text(candidate.get("runtime_context_id")),
            _exact_text(candidate.get("task_id")),
            _exact_text(candidate.get("parent_task_id")),
            worker_identity,
            _exact_text(candidate.get("target_project_root")),
            _exact_text(candidate.get("worktree_path")),
        )

    candidate_identities = [
        (candidate, _dispatch_candidate_identity(candidate))
        for candidate in dispatch_candidates
    ]

    def _strict_compatible_identity_subset(
        candidate_identity: tuple[str, str, str, str, str, str],
        richer_identity: tuple[str, str, str, str, str, str],
    ) -> bool:
        if sum(bool(value) for value in candidate_identity) >= sum(
            bool(value) for value in richer_identity
        ):
            return False
        return all(
            not value or (richer_value and value == richer_value)
            for value, richer_value in zip(candidate_identity, richer_identity)
        )

    maximal_dispatch_candidates = [
        (candidate, identity)
        for index, (candidate, identity) in enumerate(candidate_identities)
        if not any(
            index != other_index
            and _strict_compatible_identity_subset(identity, other_identity)
            for other_index, (_other_candidate, other_identity) in enumerate(
                candidate_identities
            )
        )
    ]

    dispatch_candidates_by_identity: dict[
        tuple[str, str, str, str, str, str],
        list[Mapping[str, Any]],
    ] = {}
    for candidate, identity in maximal_dispatch_candidates:
        dispatch_candidates_by_identity.setdefault(identity, []).append(candidate)

    dispatch_payload: Mapping[str, Any] = {}
    if len(dispatch_candidates_by_identity) == 1:
        dispatch_payload = max(
            next(iter(dispatch_candidates_by_identity.values())),
            key=lambda candidate: sum(
                bool(_exact_text(candidate.get(field)))
                for field in (
                    "runtime_context_id",
                    "task_id",
                    "parent_task_id",
                    "worker_id",
                    "worker_slot_id",
                    "target_project_root",
                    "worktree_path",
                    "branch_ref",
                    "base_commit",
                    "target_head_commit",
                    "merge_queue_id",
                )
            )
            + int(isinstance(candidate.get("route_identity"), Mapping))
            + int(
                isinstance(candidate.get("owned_files"), (list, tuple))
                and bool(candidate.get("owned_files"))
            ),
        )
    dispatch_route_identity = (
        dispatch_payload.get("route_identity")
        if isinstance(dispatch_payload.get("route_identity"), Mapping)
        else {}
    )

    def next_text(field: str, default: str = "") -> str:
        for source in (
            next_action,
            next_route_identity,
            dispatch_payload,
            dispatch_route_identity,
            execution,
        ):
            text = _exact_text(source.get(field))
            if text:
                return text
        return str(default or "").strip()

    worker_task_id = next_text("task_id", "<bounded worker task_id>")
    parent_task_id = next_text(
        "parent_task_id",
        execution_id or "<contract execution id>",
    )
    worker_id = next_text("worker_id", next_text("worker_slot_id", "<worker id>"))
    worker_slot_id = next_text("worker_slot_id", worker_id)
    dispatch_merge_queue_id = _exact_text(
        dispatch_payload.get("merge_queue_id")
    )
    merge_queue_id = dispatch_merge_queue_id or next_text("merge_queue_id")
    target_project_root = next_text(
        "target_project_root",
        next_text("project_root", "<registered target project root>"),
    )
    owned_files = _runtime_context_service_query_values(
        next_action,
        "owned_files",
        "target_files",
    )
    if not owned_files and dispatch_payload:
        owned_files = _runtime_context_service_query_values(
            dispatch_payload,
            "owned_files",
            "target_files",
        )
    profile_requirements = next(
        (
            dict(source.get("profile_requirements") or {})
            for source in (next_action, dispatch_payload)
            if isinstance(source.get("profile_requirements"), Mapping)
            and source.get("profile_requirements")
        ),
        dict(_MF_PARALLEL_DEFAULT_PROFILE_REQUIREMENTS),
    )
    retry_policy = next(
        (
            dict(source.get("retry_policy") or {})
            for source in (next_action, dispatch_payload)
            if isinstance(source.get("retry_policy"), Mapping)
            and source.get("retry_policy")
        ),
        dict(_MF_PARALLEL_DEFAULT_RETRY_POLICY),
    )
    allocation_route_identity = {
        field: next_text(field, f"<{field}>")
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    canonical_allocation_body = {
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "successor_contract_execution_id": execution_id,
        "current_contract_execution_id": execution_id,
        "task_id": worker_task_id,
        "parent_task_id": parent_task_id,
        "root_task_id": next_text(
            "root_task_id",
            str(execution.get("root_contract_execution_id") or "<root task id>"),
        ),
        "worker_id": worker_id,
        "agent_id": next_text("agent_id", "<actual host-created worker id>"),
        "target_project_root": target_project_root,
        "worktree_path": next_text("worktree_path", "<absolute worker worktree>"),
        "branch_ref": next_text("branch_ref", "<refs/heads/worker-branch>"),
        "base_commit": next_text("base_commit", "<exact base commit>"),
        "target_head_commit": next_text(
            "target_head_commit",
            "<exact target HEAD commit>",
        ),
        "merge_queue_id": next_text(
            "merge_queue_id",
            "<runtime_context merge_queue_id>",
        ),
        "owned_files": owned_files or ["<repo-relative owned file>"],
        "profile_requirements": profile_requirements,
        "retry_policy": retry_policy,
        "route_identity": dict(allocation_route_identity),
        **allocation_route_identity,
    }
    bounded_worker_lanes: list[Mapping[str, Any]] = []
    for source in (next_action, copy_payload):
        candidates = source.get("bounded_workers")
        if isinstance(candidates, list):
            bounded_worker_lanes = [
                candidate for candidate in candidates if isinstance(candidate, Mapping)
            ]
            if bounded_worker_lanes:
                break
        nested_payload = source.get("payload")
        if isinstance(nested_payload, Mapping) and isinstance(
            nested_payload.get("bounded_workers"),
            list,
        ):
            bounded_worker_lanes = [
                candidate
                for candidate in nested_payload.get("bounded_workers") or []
                if isinstance(candidate, Mapping)
            ]
            if bounded_worker_lanes:
                break
    safe_parent_route_identity = {
        field: value
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        if (value := _exact_text(allocation_route_identity.get(field)))
    }
    observer_route_context_issue_request_bodies: list[dict[str, Any]] = []
    atomic_precheck_lane_templates: list[dict[str, Any]] = []
    route_token_ref_bindings: list[dict[str, Any]] = []
    for lane_index, lane in enumerate(bounded_worker_lanes):
        lane_task_id = _exact_text(lane.get("task_id")) or worker_task_id
        lane_worker_id = _exact_text(
            lane.get("worker_id") or lane.get("worker_slot_id")
        )
        lane_worker_slot_id = _exact_text(
            lane.get("worker_slot_id") or lane_worker_id
        )
        lane_owned_files = _runtime_context_service_query_values(
            lane,
            "owned_files",
            "target_files",
        )
        lane_test_files = _runtime_context_service_query_values(
            lane,
            "test_files",
        )
        lane_test_commands = _runtime_context_service_query_values(
            lane,
            "test_commands",
        )
        issue_body = {
            "project_id": project_id,
            "caller_role": "observer",
            "backlog_id": backlog_id,
            "task_id": execution_id,
            "target_files": list(lane_owned_files),
            "owned_files": list(lane_owned_files),
            "allowed_actions": [
                "parallel_branch_allocate",
                "task_timeline_append",
            ],
            "evidence_refs": [
                f"contract_runtime:{execution_id}",
                f"backlog:{backlog_id}",
                f"lane_task:{lane_task_id}",
            ],
            "parent_route_identity": dict(safe_parent_route_identity),
        }
        observer_route_context_issue_request_bodies.append(issue_body)
        # This is an input to the existing server-side allocation precheck, not
        # a caller-authored allocation body.  Keep only the admitted planning
        # identity/file fence plus Contract-derived defaults.  The precheck
        # remains the sole authority for repository root, commits, worktree,
        # branch, merge queue, and route identity.
        lane_template = {
            "project_id": project_id,
            "backlog_id": backlog_id,
            "contract_execution_id": execution_id,
            "successor_contract_execution_id": execution_id,
            "current_contract_execution_id": execution_id,
            "parent_task_id": execution_id,
            "task_id": lane_task_id,
            "worker_id": lane_worker_id,
            "worker_slot_id": lane_worker_slot_id,
            "agent_id": lane_worker_id,
            "owned_files": list(lane_owned_files),
            "target_files": list(lane_owned_files),
            "test_files": list(lane_test_files),
            "test_commands": list(lane_test_commands),
            "profile_requirements": dict(profile_requirements),
            "retry_policy": dict(retry_policy),
            "route_token_ref": (
                "<route_token_ref returned for "
                f"lane[{lane_index}] task_id={lane_task_id}>"
            ),
        }
        atomic_precheck_lane_templates.append(lane_template)
        route_token_ref_bindings.append(
            {
                "lane_index": lane_index,
                "task_id": lane_task_id,
                "source": "observer_route_context_issue.route_token_ref",
                "destination": f"lanes[{lane_index}].route_token_ref",
            }
        )
    per_lane_route_context_issue = {
        "schema_version": (
            "contract_runtime.mf_parallel_per_lane_route_context_issue.v1"
        ),
        "status": "distinct_child_route_token_refs_required",
        "mcp_tool": "observer_route_context_issue",
        "request_bodies": observer_route_context_issue_request_bodies,
        "required_issue_count": len(observer_route_context_issue_request_bodies),
        "route_token_ref_bindings": route_token_ref_bindings,
        "atomic_precheck": {
            "mcp_tool": "parallel_branch_allocate_precheck",
            "request_body_template": {
                "project_id": project_id,
                "expected_lane_count": len(atomic_precheck_lane_templates),
                "lanes": atomic_precheck_lane_templates,
            },
            "call_only_after_all_route_token_ref_bindings": True,
        },
        "instructions": [
            "call observer_route_context_issue once for each request body",
            (
                "copy each returned route_token_ref into only the same-index "
                "atomic precheck lane"
            ),
            (
                "after every lane has a distinct returned route_token_ref, call "
                "parallel_branch_allocate_precheck with the completed lane list"
            ),
        ],
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
    }
    parallel_branch_allocate_submission = {
        "schema_version": (
            "contract_runtime.parallel_branch_allocate_submission.v1"
        ),
        "mcp_tool": "parallel_branch_allocate",
        "body_source": "copy_safe_body",
        "copy_safe_body": canonical_allocation_body,
        "contract_scope_source": "contract_execution_id",
        "required_contract_scope_fields": [
            "backlog_id",
            "contract_execution_id",
        ],
        "observer_command_id_contract_scope_fallback_required": False,
        "source_spelunking_required": False,
        "after_success": [
            "use returned runtime_context_id and session_token_ref",
            "deliver worker_host_envelope to the actual host-created worker",
            "worker reads runtime_context_worker_guide before protected writes",
        ],
    }
    submit_line_body = dict(copy_payload)
    submit_line_body.update(
        {
            "runtime_context_id": next_text(
                "runtime_context_id",
                "<from parallel_branch_allocate/runtime_context>",
            ),
            "task_id": worker_task_id,
            "parent_task_id": parent_task_id,
            "worker_role": "mf_sub",
            "worker_id": worker_id,
            "worker_slot_id": worker_slot_id,
            "fence_token": "<worker fence_token from allocation envelope>",
            "target_project_root": target_project_root,
            "session_token_ref": next_text(
                "session_token_ref",
                "<copy-safe worker session_token_ref>",
            ),
        }
    )
    worker_host_envelope_handoff = _mf_sub_worker_host_envelope_handoff(
        project_id=project_id,
        runtime_context_id=str(submit_line_body.get("runtime_context_id") or ""),
        task_id=str(submit_line_body.get("task_id") or ""),
        parent_task_id=str(submit_line_body.get("parent_task_id") or ""),
        target_project_root=str(submit_line_body.get("target_project_root") or ""),
        worker_id=worker_id,
        worker_slot_id=worker_slot_id,
        session_token_ref=str(submit_line_body.get("session_token_ref") or ""),
        fence_token=str(submit_line_body.get("fence_token") or ""),
        merge_queue_id=next_text(
            "merge_queue_id",
            "<runtime_context merge_queue_id>",
        ),
        route_identity=submit_line_body,
    )
    capacity_fallback_guidance = worker_host_envelope_handoff.get(
        "capacity_fallback_guidance",
        {},
    )
    parallel_branch_allocate_submission["worker_host_envelope_handoff"] = (
        worker_host_envelope_handoff
    )
    return {
        "schema_version": "contract_runtime.mf_sub_host_bridge_guidance.v1",
        "status": "mf_sub_runtime_identity_required",
        "blocked_action": blocked_action,
        "reason": (
            "The next legal ContractRuntime line is owned by mf_sub; a host-created "
            "Codex subagent id is not enough to authorize the write."
        ),
        "contract_execution_id": str(execution.get("contract_execution_id") or ""),
        "contract_id": str(contract.get("contract_id") or ""),
        "next_line": {
            "stage_id": str(next_action.get("stage_id") or ""),
            "line_id": str(next_action.get("line_id") or ""),
            "evidence_kind": str(next_action.get("evidence_kind") or ""),
            "owner_role": str(next_action.get("owner_role") or ""),
            "allowed_writer_roles": list(next_action.get("allowed_writer_roles") or []),
        },
        "required_worker_runtime_fields": list(_MF_SUB_HOST_BRIDGE_REQUIRED_FIELDS),
        "next_action": {
            "id": "obtain_mf_sub_runtime_identity",
            "action": "allocate_or_read_worker_runtime_context_before_submit_line",
            "tools": [
                "parallel_branch_allocate",
                "runtime_context_worker_guide",
                "runtime_context_current",
                "runtime_context_session_token_initial_join",
                "runtime_context_session_token_reissue",
                "runtime_context_session_token_rejoin",
            ],
            "produces": [
                *list(_MF_SUB_HOST_BRIDGE_REQUIRED_FIELDS),
                "worker_host_envelope",
            ],
            "raw_env_recovery": "worker_host_envelope_handoff",
        },
        "copy_safe_bridge_payload": {
            "parallel_branch_allocate": parallel_branch_allocate_submission,
            "per_lane_observer_route_context_issue": per_lane_route_context_issue,
            "runtime_context_worker_guide": {
                "project_id": project_id,
                "runtime_context_id": str(
                    submit_line_body.get("runtime_context_id") or ""
                ),
                "parent_task_id": parent_task_id,
                "fence_token": "<worker fence_token>",
                "session_token_ref": str(
                    submit_line_body.get("session_token_ref") or ""
                ),
                "target_project_root": target_project_root,
                "view": "worker_view",
            },
            "contract_runtime_submit_line_body_after_bridge": submit_line_body,
            "worker_host_envelope_handoff": worker_host_envelope_handoff,
            "capacity_fallback_guidance": capacity_fallback_guidance,
        },
        "parallel_branch_allocate_submission": parallel_branch_allocate_submission,
        "observer_route_context_issue_request_bodies": (
            observer_route_context_issue_request_bodies
        ),
        "per_lane_observer_route_context_issue": per_lane_route_context_issue,
        "worker_host_envelope_handoff": worker_host_envelope_handoff,
        "capacity_fallback_guidance": capacity_fallback_guidance,
        "post_dispatch_runtime_identity": {
            "status": (
                "exact_completed_dispatch"
                if dispatch_payload and dispatch_merge_queue_id
                else "blocked_missing_authoritative_merge_queue_id"
                if dispatch_payload
                else "allocation_or_dispatch_required"
            ),
            "source": (
                "ContractRuntime.completed_lines.observer_dispatch_bounded_workers"
                if dispatch_payload
                else "next_legal_action_or_allocation_result"
            ),
            "runtime_context_id": str(
                submit_line_body.get("runtime_context_id") or ""
            ),
            "task_id": worker_task_id,
            "parent_task_id": parent_task_id,
            "worker_id": worker_id,
            "worker_slot_id": worker_slot_id,
            "merge_queue_id": (
                dispatch_merge_queue_id if dispatch_payload else merge_queue_id
            ),
            "merge_queue_id_source": (
                "ContractRuntime.completed_lines."
                "observer_dispatch_bounded_workers"
                if dispatch_payload and dispatch_merge_queue_id
                else ""
            ),
            "target_project_root": target_project_root,
            "worktree_path": next_text(
                "worktree_path",
                "<absolute worker worktree>",
            ),
            "target_project_root_fence": (
                "runtime_context_effective_target_project_root"
            ),
            "worktree_alias_submitted_as_target_project_root": False,
        },
        "forbidden_shortcuts": [
            "observer_body_actor_role_mf_sub",
            "observer_written_worker_evidence",
            "codex_subagent_id_without_runtime_context",
            "post_hoc_worker_identity_backfill",
            "observer_authored_mf_sub_evidence",
            "raw_token_persistence",
            "change_runtime_identity_to_work_around_capacity",
        ],
        "observer_body_actor_role_policy": {
            "body_actor_role_is_authorization": False,
            "effective_writer_role_source": "authenticated_runtime_context_worker_proof",
            "message": (
                "Do not rely on body.actor_role='mf_sub' from an observer/host request; "
                "the worker write must carry runtime_context_id, fence_token, "
                "session_token_ref, parent_task_id, task_id, and target_project_root."
            ),
        },
        "host_subagent_identity_policy": {
            "codex_subagent_id_sufficient": False,
            "requires_runtime_context_bridge": True,
            "raw_session_token_required": False,
            "raw_route_token_required": False,
            "raw_worker_env_delivery": "worker_host_envelope",
            "session_token_ref_alone_authorizes_writes": False,
        },
    }


def _contract_runtime_authoritative_runtime_context_projection(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Project one exact dispatched RuntimeContext into ContractRuntime reads."""

    if not _is_mf_parallel_record_contract_id(str(record.get("contract_id") or "")):
        return {}
    from .parallel_branch_runtime import (
        runtime_context_effective_target_project_root,
        runtime_context_id_for_branch_context,
    )

    contexts: dict[str, Any] = {}
    for line in record.get("completed_lines") or []:
        if not isinstance(line, Mapping):
            continue
        if (
            str(line.get("stage_id") or "").strip() != "dispatch"
            or str(line.get("line_id") or "").strip()
            != "observer_dispatch_bounded_workers"
            or str(line.get("evidence_kind") or "").strip()
            != "dispatch_bounded_worker"
        ):
            continue
        context = _contract_runtime_context_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=line,
        )
        if context is None:
            continue
        runtime_context_id = runtime_context_id_for_branch_context(context)
        if runtime_context_id:
            contexts[runtime_context_id] = context
    if len(contexts) != 1:
        return {}

    runtime_context_id, context = next(iter(contexts.items()))
    merge_queue_id = str(getattr(context, "merge_queue_id", "") or "").strip()
    durable_status = str(getattr(context, "status", "") or "").strip()
    last_recovery_action = str(
        getattr(context, "last_recovery_action", "") or ""
    ).strip()
    terminal_audit_only = durable_status == "released_unlandable"
    current_values = {
        "runtime_context_id": runtime_context_id,
        "task_id": str(getattr(context, "task_id", "") or "").strip(),
        "parent_task_id": _runtime_context_mf_sub_parent_task_id(context),
        "target_project_root": runtime_context_effective_target_project_root(
            context
        ),
        "worktree_path": str(
            getattr(context, "worktree_path", "") or ""
        ).strip(),
        "branch_ref": str(getattr(context, "branch_ref", "") or "").strip(),
        "base_commit": str(getattr(context, "base_commit", "") or "").strip(),
        "target_head_commit": str(
            getattr(context, "target_head_commit", "") or ""
        ).strip(),
        "merge_queue_id": merge_queue_id,
        "status": durable_status,
        "last_recovery_action": last_recovery_action,
    }
    return {
        "schema_version": "runtime_context.authoritative_current_values.v1",
        "status": (
            "released_unlandable"
            if terminal_audit_only
            else (
                "ready"
                if merge_queue_id
                else "blocked_missing_authoritative_merge_queue_id"
            )
        ),
        "terminal": terminal_audit_only,
        "actionable": not terminal_audit_only,
        "source": "parallel_branch_runtime_contexts",
        "source_of_authority": "RuntimeContext.current_values",
        "current_values": current_values,
        "required_worker_startup_field": (
            "runtime_context.current_values.merge_queue_id"
        ),
        "merge_queue_id_source": (
            "parallel_branch_runtime_contexts.merge_queue_id"
        ),
        "copy_safe": True,
        "route_local_merge_queue_id_allowed": False,
        "caller_inferred_merge_queue_id_allowed": False,
        "placeholder_merge_queue_id_actionable": False,
    }


def _contract_runtime_acceptance_criteria_claims(
    value: Any,
    *,
    depth: int = 0,
) -> list[Any]:
    """Collect explicit client acceptance claims from a bounded JSON payload."""

    if depth > 6:
        return []
    claims: list[Any] = []
    if isinstance(value, Mapping):
        if "acceptance_criteria" in value:
            claims.append(value.get("acceptance_criteria"))
        for child in value.values():
            if isinstance(child, (Mapping, list, tuple)):
                claims.extend(
                    _contract_runtime_acceptance_criteria_claims(
                        child,
                        depth=depth + 1,
                    )
                )
    elif isinstance(value, (list, tuple)):
        for child in value:
            claims.extend(
                _contract_runtime_acceptance_criteria_claims(
                    child,
                    depth=depth + 1,
                )
            )
    return claims


def _contract_runtime_mf_parallel_rev8_atomic_acceptance_gate(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    lane_owned_files: Sequence[Sequence[str]],
    acceptance_claim_source: Any,
) -> tuple[list[Any], dict[str, Any], list[str]]:
    """Close row acceptance only over the persisted two-lane file union."""

    from .contract_state_runtime import acceptance_file_fence_closure_gate

    backlog_id = str(record.get("backlog_id") or "").strip()
    execution_id = str(record.get("contract_execution_id") or "").strip()
    criteria, row_files = _backlog_acceptance_scope_authority(conn, backlog_id)
    normalized_lanes = [
        _runtime_context_public_file_values(list(files))
        for files in lane_owned_files
    ]
    persisted_union = sorted(
        set().union(*(set(files) for files in normalized_lanes))
        if normalized_lanes
        else set()
    )
    gate = acceptance_file_fence_closure_gate(
        criteria,
        persisted_union,
        authority_source=f"backlog_bugs:{backlog_id}:acceptance_criteria",
        actor_role="observer",
        implementation_started=False,
    )
    gate = _acceptance_scope_with_behavior_contract_gate(
        gate,
        criteria,
        authority_source=f"backlog_bugs:{backlog_id}:acceptance_criteria",
        implementation_started=False,
    )
    errors = list(gate.get("errors") or [])
    claims = _contract_runtime_acceptance_criteria_claims(
        acceptance_claim_source
    )
    authority_mismatch = False
    for claim in claims:
        claim_gate = acceptance_file_fence_closure_gate(
            criteria,
            persisted_union,
            authority_source=f"backlog_bugs:{backlog_id}:acceptance_criteria",
            actor_role="observer",
            reported_acceptance_criteria=claim,
            implementation_started=False,
        )
        claim_gate = _acceptance_scope_with_behavior_contract_gate(
            claim_gate,
            criteria,
            authority_source=f"backlog_bugs:{backlog_id}:acceptance_criteria",
            implementation_started=False,
        )
        if claim_gate.get("authority_mismatch"):
            authority_mismatch = True
            errors.extend(claim_gate.get("errors") or [])
    errors = list(dict.fromkeys(str(error) for error in errors if str(error)))
    accepted = not errors
    gate.update(
        {
            "schema_version": "mf_parallel.rev8_atomic_acceptance_union.v1",
            "accepted": accepted,
            "passed": accepted,
            "status": "passed" if accepted else "blocked",
            "errors": errors,
            "project_id": project_id,
            "backlog_id": backlog_id,
            "task_id": execution_id,
            "scope_mode": "mf_parallel_rev8_atomic_persisted_lane_union",
            "row_declared_files": row_files,
            "persisted_lane_count": len(normalized_lanes),
            "persisted_lane_owned_files": normalized_lanes,
            "persisted_lane_file_union": persisted_union,
            "minted_fence_files": persisted_union,
            "file_fence_source": "persisted_runtime_context_lane_union",
            "authority_mismatch": authority_mismatch,
            "row_union_closure_deferred_to_atomic_dispatch": False,
            "atomic_union_authoritative": True,
            "client_acceptance_rewrite_allowed": False,
            "evaluated_before_allocation_or_dispatch": True,
        }
    )
    return criteria, gate, errors


def _contract_runtime_mf_parallel_atomic_lane_errors(
    workers: Sequence[Mapping[str, Any]],
    *,
    distinct_fields: Sequence[str],
) -> list[str]:
    """Validate exact lane identities and disjoint worker-owned file fences."""

    errors: list[str] = []
    for field in distinct_fields:
        values = [str(worker.get(field) or "").strip() for worker in workers]
        if any(not value for value in values) or len(set(values)) != len(values):
            errors.append("atomic bounded workers require distinct " + field)
    owned_by_worker = [
        set(
            _runtime_context_service_query_values(
                worker,
                "owned_files",
                "target_files",
            )
        )
        for worker in workers
    ]
    overlap = sorted(
        {
            path
            for left_index, left in enumerate(owned_by_worker)
            for right in owned_by_worker[left_index + 1 :]
            for path in left.intersection(right)
        }
    )
    if overlap:
        errors.append(
            "atomic bounded workers require disjoint owned_files: "
            + ", ".join(overlap)
        )
    return list(dict.fromkeys(errors))


def _contract_runtime_mf_parallel_allocation_precheck_policy(
    cardinality_policy: Mapping[str, Any],
) -> dict[str, Any]:
    """Project allocation-precheck semantics from effective worker cardinality."""

    expected_lane_count = int(
        cardinality_policy.get("required_worker_count") or 2
    )
    declared_batch_child = bool(
        cardinality_policy.get("batch_row_scoped_successor") is True
    )
    verified_batch_child = bool(
        declared_batch_child
        and cardinality_policy.get("source") == "verified_batch_child_lineage"
    )
    atomic = expected_lane_count > 1
    nested_batch_fanout_supported = not (
        declared_batch_child and expected_lane_count > 1
    )
    target_ref_contract = (
        {
            "schema_version": "parallel_branch_allocate.target_ref_contract.v1",
            "worker_branch_field": "branch_ref",
            "planned_target_field": "ref_name",
            "accepted_target_alias_fields": ["ref_name", "target_branch"],
            "durable_target_source": (
                "parallel_branch_merge_queue_items.target_ref"
            ),
            "target_from_branch_ref_allowed": False,
            "copy_safe_precheck_injects_ref_name": True,
            "copy_safe_precheck_removes_target_branch": True,
            "mismatch_policy": (
                "reject_before_write_with_field_expected_actual"
            ),
        }
        if declared_batch_child
        else {
            "schema_version": "parallel_branch_allocate.target_ref_contract.v1",
            "worker_branch_field": "branch_ref",
            "planned_target_field": "ref_name",
            "accepted_target_alias_fields": ["ref_name", "target_branch"],
            "durable_target_source": "",
            "target_authority": "standalone_caller_allocation_contract",
            "target_from_branch_ref_allowed": False,
            "copy_safe_precheck_injects_ref_name": False,
            "copy_safe_precheck_removes_target_branch": False,
            "mismatch_policy": "not_applicable_no_durable_batch_authority",
        }
    )
    return {
        "schema_version": "mf_parallel.effective_allocation_precheck_policy.v1",
        "source": "effective_worker_cardinality_policy",
        "cardinality_source": str(cardinality_policy.get("source") or ""),
        "tool": "parallel_branch_allocate_precheck",
        "expected_lane_count": expected_lane_count,
        "allowed_lane_counts": [1, 2],
        "lane_count_policy": "exactly",
        "atomic": atomic,
        "scope": (
            "per_child_contract"
            if declared_batch_child
            else "standalone_contract"
        ),
        "verified_batch_child": verified_batch_child,
        "declared_batch_child": declared_batch_child,
        "allocation_supported": nested_batch_fanout_supported,
        "unsupported_reason": (
            "batch_child_nested_merge_queue_and_row_fan_in_not_implemented"
            if not nested_batch_fanout_supported
            else ""
        ),
        "submit_returned_bodies_unchanged": True,
        "standalone_mf_parallel_policy_unchanged": True,
        "caller_override_allowed": False,
        "target_ref_contract": target_ref_contract,
    }


def _contract_runtime_mf_parallel_dispatch_copy_safe_projection(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Hydrate the pre-dispatch writer body from persisted allocation authority."""

    contract_update_authority = (
        _contract_update_rev2_dispatch_allocation_authority(record)
    )
    projected = (
        dict(record)
        if contract_update_authority
        else _contract_runtime_apply_mf_parallel_prefill_plan_projection(record)
    )
    record = projected
    mf_parallel = _is_mf_parallel_record_contract_id(
        str(record.get("contract_id") or "")
    )
    if not (mf_parallel or contract_update_authority):
        return projected, {}
    guide = (
        dict(record.get("runtime_guide") or {})
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    next_action = (
        dict(guide.get("next_legal_action") or {})
        if isinstance(guide.get("next_legal_action"), Mapping)
        else {}
    )
    if contract_update_authority:
        cardinality_policy, allocation_precheck_policy = (
            _contract_update_allocation_precheck_policy(
                contract_update_authority
            )
        )
    else:
        cardinality_policy = (
            _contract_runtime_mf_parallel_worker_cardinality_policy(
                conn,
                project_id=project_id,
                record=record,
            )
        )
        allocation_precheck_policy = (
            _contract_runtime_mf_parallel_allocation_precheck_policy(
                cardinality_policy
            )
        )
    guide["effective_worker_cardinality_policy"] = cardinality_policy
    guide["effective_allocation_precheck_policy"] = allocation_precheck_policy
    if next_action:
        next_action["effective_worker_cardinality_policy"] = cardinality_policy
        next_action["effective_allocation_precheck_policy"] = (
            allocation_precheck_policy
        )
        guide["next_legal_action"] = next_action
    projected["runtime_guide"] = guide
    if (
        str(next_action.get("stage_id") or "").strip() != "dispatch"
        or str(next_action.get("line_id") or "").strip()
        != "observer_dispatch_bounded_workers"
        or str(next_action.get("evidence_kind") or "").strip()
        != "dispatch_bounded_worker"
    ):
        return projected, cardinality_policy

    safe_copy = (
        dict(guide.get("writer_role_safe_copy_payload") or {})
        if isinstance(guide.get("writer_role_safe_copy_payload"), Mapping)
        else {}
    )
    copy_payload = (
        dict(safe_copy.get("copy_payload") or {})
        if isinstance(safe_copy.get("copy_payload"), Mapping)
        else {}
    )
    if not copy_payload:
        return projected, cardinality_policy

    from .parallel_branch_runtime import (
        branch_contract_revision_to_dict,
        get_latest_branch_contract_revision,
        list_branch_contexts,
        runtime_context_effective_target_project_root,
        runtime_context_id_for_branch_context,
    )

    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(record.get("backlog_id") or "").strip()
    admitted_prefill_plan = (
        _contract_runtime_mf_parallel_admitted_prefill_child_plan(record)
    )
    admitted_lanes_by_task_id = {
        str(lane.get("task_id") or "").strip(): dict(lane)
        for lane in admitted_prefill_plan.get("lanes") or []
        if isinstance(lane, Mapping)
        and str(lane.get("task_id") or "").strip()
    }
    candidates: list[tuple[Any, dict[str, Any]]] = []
    contract_update_authorities: dict[str, dict[str, Any]] = {}
    for context in list_branch_contexts(conn, project_id):
        if str(getattr(context, "backlog_id", "") or "").strip() != backlog_id:
            continue
        if _runtime_context_mf_sub_parent_task_id(context) != execution_id:
            continue
        runtime_context_id = runtime_context_id_for_branch_context(context)
        revision = get_latest_branch_contract_revision(
            conn,
            project_id,
            runtime_context_id,
        )
        if revision is None:
            continue
        revision_payload = branch_contract_revision_to_dict(revision)
        contract_identity = _runtime_context_contract_execution_identity(
            revision_payload
        )
        if (
            str(contract_identity.get("contract_execution_id") or "").strip()
            != execution_id
        ):
            continue
        if contract_update_authority:
            anchor = _runtime_context_contract_update_allocation_identity_anchor(
                conn,
                project_id=project_id,
                context=context,
                runtime_context_id=runtime_context_id,
                contract_execution_id=execution_id,
                contract_record=record,
            )
            revision_body = (
                revision_payload.get("payload")
                if isinstance(revision_payload.get("payload"), Mapping)
                else {}
            )
            accepted_authority = _contract_update_accepted_dispatch_authority(
                record,
                anchor,
                revision_body,
            )
            if not accepted_authority:
                continue
            contract_update_authorities[runtime_context_id] = (
                accepted_authority
            )
        candidates.append((context, revision_payload))
    policy = (
        _contract_update_dispatch_authority_policy(record)
        if contract_update_authority
        else _contract_runtime_mf_parallel_dispatch_authority_policy(record)
    )
    required_worker_count = (
        1
        if contract_update_authority
        else _contract_runtime_mf_parallel_current_generation_worker_count(
            record,
            conn=conn,
            project_id=project_id,
        )
    )
    candidates.sort(
        key=lambda item: (
            str(getattr(item[0], "task_id", "") or ""),
            runtime_context_id_for_branch_context(item[0]),
        )
    )
    if len(candidates) != required_worker_count:
        return projected, {
            "schema_version": (
                "contract_runtime.mf_parallel_dispatch_copy_safe_projection.v2"
            ),
            "status": "blocked_worker_count_mismatch",
            "required_worker_count": required_worker_count,
            "persisted_worker_count": len(candidates),
            "atomic_dispatch_required": required_worker_count > 1,
            "copy_safe_body_available": False,
        }

    route_diagnostics: list[dict[str, Any]] = []
    canonical_route_identities: dict[str, dict[str, str]] = {}
    for context, revision_payload in candidates:
        route_identity = _parallel_branch_runtime_contract_route_identity(
            revision_payload
        )
        canonical_route_identity, route_diagnostic = (
            _contract_runtime_resolve_append_scoped_child_route(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                contract_execution_id=execution_id,
                route_token_ref=str(
                    route_identity.get("route_token_ref") or ""
                ).strip(),
                supplied_route_authority=revision_payload,
            )
        )
        runtime_context_id = runtime_context_id_for_branch_context(context)
        if canonical_route_identity:
            canonical_route_identities[runtime_context_id] = dict(
                canonical_route_identity
            )
        route_diagnostics.append(
            {
                **route_diagnostic,
                "runtime_context_id": runtime_context_id,
                "task_id": str(
                    getattr(context, "task_id", "") or ""
                ).strip(),
            }
        )
    blocked_route_diagnostics = [
        diagnostic
        for diagnostic in route_diagnostics
        if diagnostic.get("status") != "resolved_append_scoped_ref"
    ]
    if blocked_route_diagnostics:
        next_action["copy_safe_dispatch_ready"] = False
        next_action["dispatch_copy_safe_body_source"] = ""
        for field in (
            "writer_role_safe_copy_payload",
            "parallel_branch_allocate_submission",
            "copy_safe_dispatch_payload",
        ):
            guide.pop(field, None)
            next_action.pop(field, None)
        guide["next_legal_action"] = next_action
        projection = {
            "schema_version": (
                "contract_runtime.mf_parallel_dispatch_copy_safe_projection.v2"
            ),
            "status": "blocked_route_action_scope",
            "field": blocked_route_diagnostics[0].get("field"),
            "expected": blocked_route_diagnostics[0].get("expected"),
            "actual": blocked_route_diagnostics[0].get("actual"),
            "lane_diagnostics": blocked_route_diagnostics,
            "required_worker_count": required_worker_count,
            "persisted_worker_count": len(candidates),
            "atomic_dispatch_required": required_worker_count > 1,
            "copy_safe_body_available": False,
            "writes_performed": False,
            "raw_private_context_exposed": False,
        }
        guide["dispatch_copy_safe_projection"] = projection
        projected["runtime_guide"] = guide
        return projected, projection

    lane_owned_files = [
        _runtime_context_public_file_values(
            list(getattr(context, "owned_files", ()) or ())
            or list(getattr(context, "target_files", ()) or ())
        )
        for context, _revision_payload in candidates
    ]
    all_owned_files = sorted(
        set().union(*(set(files) for files in lane_owned_files))
        if lane_owned_files
        else set()
    )
    acceptance_bodies = [
        dict(revision_payload.get("payload") or {})
        for _context, revision_payload in candidates
        if isinstance(revision_payload.get("payload"), Mapping)
    ]
    if required_worker_count > 1:
        candidate_worker_authority: list[dict[str, Any]] = []
        for (context, revision_payload), owned_files in zip(
            candidates,
            lane_owned_files,
        ):
            route_identity = canonical_route_identities.get(
                runtime_context_id_for_branch_context(context),
                _parallel_branch_runtime_contract_route_identity(
                    revision_payload
                ),
            )
            candidate_worker_authority.append(
                {
                    "runtime_context_id": runtime_context_id_for_branch_context(
                        context
                    ),
                    "task_id": str(
                        getattr(context, "task_id", "") or ""
                    ).strip(),
                    "worker_id": str(
                        getattr(context, "worker_id", "")
                        or getattr(context, "worker_slot_id", "")
                        or ""
                    ).strip(),
                    "worker_slot_id": str(
                        getattr(context, "worker_slot_id", "")
                        or getattr(context, "worker_id", "")
                        or ""
                    ).strip(),
                    "worktree_path": str(
                        getattr(context, "worktree_path", "") or ""
                    ).strip(),
                    "branch_ref": str(
                        getattr(context, "branch_ref", "") or ""
                    ).strip(),
                    "merge_queue_id": str(
                        getattr(context, "merge_queue_id", "") or ""
                    ).strip(),
                    "route_token_ref": str(
                        route_identity.get("route_token_ref") or ""
                    ).strip(),
                    "owned_files": list(owned_files),
                    "target_files": list(owned_files),
                }
            )
        distinct_fields = [
            str(field or "").strip()
            for field in policy.get("distinct_identity_fields") or []
            if str(field or "").strip()
        ]
        if "route_token_ref" not in distinct_fields:
            distinct_fields.append("route_token_ref")
        lane_errors = _contract_runtime_mf_parallel_atomic_lane_errors(
            candidate_worker_authority,
            distinct_fields=distinct_fields,
        )
        if lane_errors:
            return projected, {
                "schema_version": (
                    "contract_runtime.mf_parallel_dispatch_copy_safe_projection.v2"
                ),
                "status": "blocked_atomic_lane_authority",
                "errors": lane_errors,
                "required_worker_count": required_worker_count,
                "persisted_worker_count": len(candidates),
                "atomic_dispatch_required": True,
                "copy_safe_body_available": False,
            }
        (
            acceptance_scope_criteria,
            acceptance_scope_closure,
            acceptance_errors,
        ) = _contract_runtime_mf_parallel_rev8_atomic_acceptance_gate(
            conn,
            project_id=project_id,
            record=record,
            lane_owned_files=lane_owned_files,
            acceptance_claim_source=acceptance_bodies,
        )
        if acceptance_errors:
            return projected, {
                "schema_version": (
                    "contract_runtime.mf_parallel_dispatch_copy_safe_projection.v2"
                ),
                "status": "blocked_atomic_acceptance_union",
                "errors": acceptance_errors,
                "acceptance_scope_closure": acceptance_scope_closure,
                "required_worker_count": required_worker_count,
                "persisted_worker_count": len(candidates),
                "atomic_dispatch_required": True,
                "copy_safe_body_available": False,
            }
    else:
        reported_acceptance = _ACCEPTANCE_SCOPE_REPORT_UNSET
        reported_values = [
            body.get("acceptance_criteria")
            for body in acceptance_bodies
            if "acceptance_criteria" in body
        ]
        if reported_values and all(
            value == reported_values[0] for value in reported_values[1:]
        ):
            reported_acceptance = reported_values[0]
        acceptance_scope_criteria, acceptance_scope_closure = (
            _require_backlog_acceptance_file_fence_closure(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                task_id=execution_id,
                allowed_files=all_owned_files,
                actor_role="observer",
                reported_acceptance_criteria=reported_acceptance,
                implementation_started=False,
            )
        )

    dispatch_payloads: list[dict[str, Any]] = []
    for context, revision_payload in candidates:
        revision_body = (
            dict(revision_payload.get("payload") or {})
            if isinstance(revision_payload.get("payload"), Mapping)
            else {}
        )
        route_identity = canonical_route_identities.get(
            runtime_context_id_for_branch_context(context),
            _parallel_branch_runtime_contract_route_identity(
                revision_payload
            ),
        )
        profile_requirements = (
            dict(revision_body.get("profile_requirements") or {})
            if isinstance(revision_body.get("profile_requirements"), Mapping)
            else {}
        )
        retry_policy = (
            dict(revision_body.get("retry_policy") or {})
            if isinstance(revision_body.get("retry_policy"), Mapping)
            else {}
        )
        branch_ref = str(getattr(context, "branch_ref", "") or "").strip()
        if branch_ref and not branch_ref.startswith("refs/"):
            branch_ref = f"refs/heads/{branch_ref}"
        worker_id = str(
            getattr(context, "worker_id", "")
            or getattr(context, "worker_slot_id", "")
            or ""
        ).strip()
        worker_slot_id = str(
            getattr(context, "worker_slot_id", "")
            or getattr(context, "worker_id", "")
            or ""
        ).strip()
        dispatch_owned_files = sorted(
            set(
                getattr(context, "owned_files", ())
                or getattr(context, "target_files", ())
                or ()
            )
        )
        observer_command_id = str(
            revision_body.get("observer_command_id") or execution_id
        ).strip()
        context_task_id = str(
            getattr(context, "task_id", "") or ""
        ).strip()
        admitted_lane = admitted_lanes_by_task_id.get(context_task_id, {})
        dispatch_payload = {
                "schema_version": (
                    "contract_update.dispatch_bounded_worker.v1"
                    if contract_update_authority
                    else "mf_parallel.dispatch_bounded_worker.v2"
                ),
                "line_instance_id": (
                    "runtime_context:"
                    + runtime_context_id_for_branch_context(context)
                ),
                "runtime_context_id": runtime_context_id_for_branch_context(
                    context
                ),
                "task_id": context_task_id,
                "parent_task_id": _runtime_context_mf_sub_parent_task_id(
                    context
                ),
                "root_task_id": str(
                    getattr(context, "root_task_id", "") or execution_id
                ).strip(),
                "worker_role": "mf_sub",
                "worker_id": worker_id,
                "worker_slot_id": worker_slot_id,
                "agent_id": str(
                    getattr(context, "agent_id", "")
                    or getattr(context, "allocation_owner", "")
                    or worker_id
                ).strip(),
                "observer_command_id": observer_command_id,
                "target_project_root": (
                    runtime_context_effective_target_project_root(context)
                ),
                "worktree_path": str(
                    getattr(context, "worktree_path", "") or ""
                ).strip(),
                "branch_ref": branch_ref,
                "base_commit": str(
                    getattr(context, "base_commit", "") or ""
                ).strip(),
                "target_head_commit": str(
                    getattr(context, "target_head_commit", "") or ""
                ).strip(),
                "merge_queue_id": str(
                    getattr(context, "merge_queue_id", "") or ""
                ).strip(),
                "owned_files": dispatch_owned_files,
                "target_files": dispatch_owned_files,
                "acceptance_criteria": acceptance_scope_criteria,
                "acceptance_scope_closure": acceptance_scope_closure,
                "profile_requirements": profile_requirements,
                "retry_policy": retry_policy,
                "route_identity": dict(route_identity),
                **dict(route_identity),
            }
        if contract_update_authority:
            dispatch_payload["accepted_dispatch_authority"] = dict(
                contract_update_authorities.get(
                    runtime_context_id_for_branch_context(context),
                    {},
                )
            )
        if admitted_lane:
            dispatch_payload["test_files"] = list(
                admitted_lane.get("test_files") or []
            )
            dispatch_payload["test_commands"] = list(
                admitted_lane.get("test_commands") or []
            )
        dispatch_payloads.append(dispatch_payload)

    required_fields = _runtime_context_service_dedupe(
        [
            *policy.get("required_dispatch_fields", []),
            *policy.get("required_child_route_fields", []),
        ]
    )
    missing_fields = [
        f"worker[{index}].{field}"
        for index, dispatch_payload in enumerate(dispatch_payloads, start=1)
        for field in required_fields
        if dispatch_payload.get(field) in (None, "", [], {})
    ]
    if missing_fields:
        blocked_projection = {
            "schema_version": (
                "contract_runtime.mf_parallel_dispatch_copy_safe_projection.v2"
            ),
            "status": "blocked_incomplete_persisted_authority",
            "missing_fields": sorted(set(missing_fields)),
            "runtime_context_ids": [
                payload["runtime_context_id"] for payload in dispatch_payloads
            ],
            "source_of_authority": (
                "RuntimeContext+ContractRevision+observer_route_token_refs"
            ),
            "copy_safe_body_available": False,
            "authorizes_write": False,
            "same_world_authority_repair_available": False,
            "historical_execution_resume_allowed": False,
            "next_legal_action": (
                "stop_current_product_world_and_repair_allocation_authority_"
                "before_minting_a_fresh_world"
            ),
        }
        next_action.update(
            {
                "status": "blocked_incomplete_persisted_authority",
                "copy_safe_dispatch_ready": False,
                "block_reason": (
                    "persisted allocation authority is incomplete; dispatch "
                    "is non-authorizing"
                ),
                "blocked_next_action": blocked_projection[
                    "next_legal_action"
                ],
                "current_line_blocker_policy": {
                    "schema_version": (
                        "mf_parallel.incomplete_persisted_allocation_"
                        "authority.v1"
                    ),
                    "classification": (
                        "blocked_incomplete_persisted_authority"
                    ),
                    "missing_fields": list(blocked_projection["missing_fields"]),
                    "runtime_context_ids": list(
                        blocked_projection["runtime_context_ids"]
                    ),
                    "authorizes_write": False,
                    "same_world_authority_repair_available": False,
                    "historical_execution_resume_allowed": False,
                    "next_legal_action": blocked_projection[
                        "next_legal_action"
                    ],
                },
            }
        )
        guide.pop("writer_role_safe_copy_payload", None)
        next_action.pop("writer_role_safe_copy_payload", None)
        guide["next_legal_action"] = next_action
        guide["dispatch_copy_safe_projection"] = blocked_projection
        projected["runtime_guide"] = guide
        return projected, blocked_projection

    if required_worker_count == 1:
        dispatch_payload = dict(dispatch_payloads[0])
        bounded_workers = [dict(dispatch_payload)]
        single_worker_payload = {
            **dispatch_payload,
            "bounded_workers": bounded_workers,
            "worker_count": required_worker_count,
            "required_worker_count": required_worker_count,
            "atomic_dispatch": False,
        }
        copy_payload.update(dispatch_payload)
        copy_payload["bounded_workers"] = bounded_workers
        copy_payload["worker_count"] = required_worker_count
        copy_payload["required_worker_count"] = required_worker_count
        copy_payload["atomic_dispatch"] = False
        copy_payload["payload"] = single_worker_payload
        next_action.update(single_worker_payload)
    else:
        atomic_payload = {
            "schema_version": "mf_parallel.atomic_two_worker_dispatch.v1",
            "bounded_workers": dispatch_payloads,
            "worker_count": required_worker_count,
            "required_worker_count": required_worker_count,
            "atomic_dispatch": True,
            "all_or_nothing": True,
            "owned_files": all_owned_files,
            "target_files": all_owned_files,
            "acceptance_criteria": acceptance_scope_criteria,
            "acceptance_scope_closure": acceptance_scope_closure,
        }
        copy_payload["bounded_workers"] = dispatch_payloads
        copy_payload["worker_count"] = required_worker_count
        copy_payload["atomic_dispatch"] = True
        copy_payload["payload"] = atomic_payload
        next_action.update(atomic_payload)
    safe_copy["copy_payload"] = copy_payload
    guide["writer_role_safe_copy_payload"] = safe_copy
    next_action["writer_role_safe_copy_payload"] = dict(safe_copy)
    next_action["copy_safe_dispatch_ready"] = True
    next_action["dispatch_copy_safe_body_source"] = (
        "RuntimeContext+ContractRevision+observer_route_token_refs"
    )
    if contract_update_authority:
        next_action["accepted_dispatch_authority"] = dict(
            dispatch_payloads[0]["accepted_dispatch_authority"]
        )
    guide["next_legal_action"] = next_action
    projection = {
        "schema_version": (
            "contract_runtime.mf_parallel_dispatch_copy_safe_projection.v2"
        ),
        "status": "ready",
        "worker_count": len(dispatch_payloads),
        "required_worker_count": required_worker_count,
        "atomic_dispatch": required_worker_count > 1,
        "runtime_context_ids": [
            payload["runtime_context_id"] for payload in dispatch_payloads
        ],
        "task_ids": [payload["task_id"] for payload in dispatch_payloads],
        "source_of_authority": (
            "RuntimeContext+ContractRevision+observer_route_token_refs"
        ),
        "lane_route_resolutions": route_diagnostics,
        "copy_safe_body_available": True,
        "raw_private_context_exposed": False,
    }
    guide["dispatch_copy_safe_projection"] = projection
    projected["runtime_guide"] = guide
    return projected, projection


def _contract_runtime_observer_reconcile_action_projection(
    guide: Mapping[str, Any],
    next_line: Mapping[str, Any],
) -> dict[str, Any]:
    """Surface the source contract's reconcile recipe with safe live inputs.

    The ContractRuntime route ref authorizes the later submit-line write; it is
    not interchangeable with the task-scoped reconcile-only route.  Therefore
    this projection copies only values already bound to the reconcile call and
    lists the observer session/ref inputs that the observer must obtain from
    its active reconcile route context.
    """

    if str(next_line.get("line_id") or "").strip() != "observer_reconcile":
        return {}
    contract = (
        guide.get("contract")
        if isinstance(guide.get("contract"), Mapping)
        else {}
    )
    if str(contract.get("contract_id") or "").strip() != MF_PARALLEL_CONTRACT_ID:
        return {}
    try:
        definition = _CONTRACT_DEFINITION_REGISTRY.get(
            MF_PARALLEL_CONTRACT_ID,
            version=str(contract.get("version") or "") or None,
            revision=str(contract.get("revision") or "") or None,
            include_deprecated=True,
        )
    except Exception:
        return {}
    system_layer = (
        definition.get("system_layer")
        if isinstance(definition.get("system_layer"), Mapping)
        else {}
    )
    graph_policy = (
        system_layer.get("graph_binding_policy")
        if isinstance(system_layer.get("graph_binding_policy"), Mapping)
        else {}
    )
    reconcile_policy = (
        graph_policy.get("current_full_reconcile_evidence_policy")
        if isinstance(
            graph_policy.get("current_full_reconcile_evidence_policy"),
            Mapping,
        )
        else {}
    )
    recipe = (
        reconcile_policy.get("observer_reconcile_next_action")
        if isinstance(
            reconcile_policy.get("observer_reconcile_next_action"),
            Mapping,
        )
        else {}
    )
    sequence = [
        item
        for item in recipe.get("sequence") or []
        if isinstance(item, Mapping)
    ]
    reconcile_step = next(
        (
            item
            for item in sequence
            if str(item.get("action") or "").strip()
            == "graph_current_full_reconcile"
        ),
        {},
    )
    required_fields = [
        str(field or "").strip()
        for field in reconcile_step.get("required_copy_safe_fields") or []
        if str(field or "").strip()
    ]
    if not recipe or not reconcile_step or not required_fields:
        return {}

    execution = (
        guide.get("execution")
        if isinstance(guide.get("execution"), Mapping)
        else {}
    )
    action_input: dict[str, Any] = {}
    for field, value in (
        ("project_id", execution.get("project_id")),
        ("backlog_id", execution.get("backlog_id")),
        ("task_id", next_line.get("task_id")),
    ):
        token = str(value or "").strip()
        if token:
            action_input[field] = token
    target_commit = str(
        next_line.get("target_head_commit")
        or next_line.get("merged_commit_sha")
        or next_line.get("commit_sha")
        or ""
    ).strip().lower()
    if re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", target_commit):
        action_input["target_commit_sha"] = target_commit
    action_input.update(
        {
            "activate": True,
            "require_clean": True,
            "semantic_use_ai": False,
            "semantic_enrich": False,
            "enqueue_stale": False,
        }
    )
    missing = [
        field for field in required_fields if not action_input.get(field)
    ]
    return {
        "observer_reconcile_next_action": deepcopy(dict(recipe)),
        "required_tool": "graph_current_full_reconcile",
        "action_input_copy_safe": True,
        "action_input_ready": not missing,
        "action_input": action_input,
        "action_input_required_copy_safe_fields": required_fields,
        "action_input_missing_required_fields": missing,
        "action_input_sources": {
            "project_id": "contract_runtime.execution.project_id",
            "backlog_id": "contract_runtime.execution.backlog_id",
            "task_id": "dispatched_runtime_context.task_id",
            "target_commit_sha": "canonical_target_head_commit",
            "observer_session_id": "active_observer_session.session_id",
            "route_token_ref": "reconcile_only_observer_route_context.route_token_ref",
        },
        "route_scopes_interchangeable": bool(
            recipe.get("route_scopes_interchangeable")
        ),
        "contract_runtime_submit_route_ref_reused_for_reconcile": False,
        "raw_route_token_required": False,
    }


def _runtime_next_action_from_guide(
    guide: Mapping[str, Any],
    *,
    source: str = "contract_runtime",
) -> dict[str, Any]:
    next_line = guide.get("next_legal_action")
    if not isinstance(next_line, Mapping):
        return {}
    dispatch_copy_safe_projection = (
        guide.get("dispatch_copy_safe_projection")
        if isinstance(guide.get("dispatch_copy_safe_projection"), Mapping)
        else {}
    )
    route_action_scope_blocked = bool(
        str(dispatch_copy_safe_projection.get("status") or "").strip()
        == "blocked_route_action_scope"
    )
    persisted_allocation_authority_blocked = bool(
        str(dispatch_copy_safe_projection.get("status") or "").strip()
        == "blocked_incomplete_persisted_authority"
    )
    execution = guide.get("execution") if isinstance(guide.get("execution"), Mapping) else {}
    evidence_kind = str(next_line.get("evidence_kind") or "")
    line_id = str(next_line.get("line_id") or "")
    action = str(next_line.get("action") or "").strip()
    if not action:
        action = (
            evidence_kind
            if evidence_kind.startswith("record_")
            else f"record_{evidence_kind}"
            if evidence_kind
            else "record_contract_line"
        )
    result = {
        "schema_version": "contract_runtime_next_legal_action.v1",
        "id": line_id,
        "action": action,
        "source": source,
        "precedence": "contract_runtime_first_missing_line",
        "contract_execution_id": str(execution.get("contract_execution_id") or ""),
        "runtime_guide_hash": str(guide.get("runtime_guide_hash") or ""),
        "execution_state_revision": int(
            execution.get("execution_state_revision") or 0
        ),
        "execution_state_hash": str(execution.get("execution_state_hash") or ""),
        "route_token_ref": str(execution.get("route_token_ref") or ""),
        "stage_id": str(next_line.get("stage_id") or ""),
        "line_id": line_id,
        "owner_role": str(next_line.get("owner_role") or ""),
        "allowed_writer_roles": list(next_line.get("allowed_writer_roles") or []),
        "evidence_kind": evidence_kind,
        "required": bool(next_line.get("required", True)),
        "meta_contract_gate_decision_source": False,
        "submit_line_guidance": _contract_runtime_submit_line_guidance(guide),
    }
    for key in (
        "line_instance_id",
        "runtime_context_id",
        "task_id",
        "parent_task_id",
        "worker_role",
        "lane_id",
        "worker_slot_id",
        "worker_id",
        "worker_index",
        "status",
        "blocked_by_line",
        "blocked_next_action",
        "body",
        "interface",
        "mutation_required",
        "diagnostic_required",
        "diagnostic_backlog_id",
        "no_pass_claim",
        "source_row_must_remain_open",
        "direct_fix_required",
        "audited_bypass_continuation",
        "current_line_blocker_policy",
        "original_contract_action",
        "child_route_token_required",
        "endpoint",
        "mode",
        "recommended_successor_contract_id",
        "recommended_successor_contract_template_id",
        "requires_route_token_ref",
        "return_to_parent",
        "source",
        "successor_contract_id",
        "successor_contract_execution_id",
        "successor_contract_template_id",
        "next_operator_action",
        "block_reason",
        "target_project_root",
        "project_root",
        "repo_root",
        "worktree_path",
        "branch_ref",
        "branch",
        "base_commit",
        "target_head_commit",
        "merge_queue_id",
        "root_task_id",
        "agent_id",
        "route_id",
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
        "visible_injection_manifest_hash",
        "route_identity",
        "session_token_ref",
        "graph_trace_id",
        "graph_trace_ids",
        "graph_query_trace_id",
        "graph_query_trace_ids",
        "caller_graph_query_schema_trace_id",
        "owned_files",
        "target_files",
        "profile_requirements",
        "retry_policy",
        "worker_session_lifecycle_policy",
        "write_authorization_policy",
        "same_lane_worker_commit_recovery_projection",
        "recovery_status",
        "current_target_baseline_commit",
        "actual_worktree_head_commit",
        "fresh_evidence_required",
        "ordered_recovery_actions",
        "canonical_next_action_before_recovery",
        "immutable_prior_evidence_policy",
        "submit_line_guidance",
        "copy_safe_dispatch_ready",
        "dispatch_copy_safe_body_source",
        "effective_worker_cardinality_policy",
        "effective_allocation_precheck_policy",
        "source_of_authority",
        "authority_decision_source",
        "accepted_dispatch_authority",
        "dispatch_source_ref",
        "read_receipt_event_ref",
        "contract_runtime_mutated",
        "global_contract_line_already_completed",
        "failed_qa_replacement_post_read_startup_projection",
    ):
        if key in next_line:
            result[key] = next_line[key]
    writer_safe_copy = guide.get("writer_role_safe_copy_payload")
    if (
        not route_action_scope_blocked
        and isinstance(writer_safe_copy, Mapping)
    ):
        result["writer_role_safe_copy_payload"] = dict(writer_safe_copy)
    contract = (
        guide.get("contract")
        if isinstance(guide.get("contract"), Mapping)
        else {}
    )
    contract_id = str(contract.get("contract_id") or "").strip()
    reconcile_projection = (
        _contract_runtime_observer_reconcile_action_projection(
            guide,
            next_line,
        )
    )
    if reconcile_projection:
        result.update(reconcile_projection)
    if (
        not route_action_scope_blocked
        and line_id == "observer_dispatch_bounded_workers"
        and contract_id in {
            MF_PARALLEL_CONTRACT_ID,
            CONTRACT_UPDATE_CONTRACT_ID,
        }
    ):
        if (
            next_line.get("copy_safe_dispatch_ready") is not True
            and not persisted_allocation_authority_blocked
        ):
            synthetic_guide = dict(guide)
            synthetic_next = {
                **dict(next_line),
                "owner_role": "mf_sub",
                "allowed_writer_roles": ["mf_sub"],
            }
            if contract_id == CONTRACT_UPDATE_CONTRACT_ID:
                request_lines = [
                    line
                    for line in guide.get("completed_lines") or []
                    if isinstance(line, Mapping)
                    and str(line.get("line_id") or "").strip()
                    == "observer_request_contract_update"
                ]
                request_payload = (
                    request_lines[0].get("payload")
                    if len(request_lines) == 1
                    and isinstance(request_lines[0].get("payload"), Mapping)
                    else {}
                )
                owned_files = _runtime_context_service_query_values(
                    request_payload,
                    "owned_files",
                    "target_files",
                )
                execution_id = str(
                    execution.get("contract_execution_id") or ""
                ).strip()
                backlog_id = str(execution.get("backlog_id") or "").strip()
                if owned_files and execution_id and backlog_id:
                    worker_id = _contract_runtime_stable_id(
                        "contract-update-worker",
                        execution_id,
                    )
                    synthetic_next["bounded_workers"] = [
                        {
                            "task_id": _contract_runtime_stable_id(
                                "contract-update-task",
                                execution_id,
                            ),
                            "parent_task_id": execution_id,
                            "worker_id": worker_id,
                            "worker_slot_id": worker_id,
                            "owned_files": owned_files,
                            "target_files": owned_files,
                            "profile_requirements": dict(
                                _MF_PARALLEL_DEFAULT_PROFILE_REQUIREMENTS
                            ),
                            "retry_policy": dict(
                                _MF_PARALLEL_DEFAULT_RETRY_POLICY
                            ),
                        }
                    ]
            synthetic_guide["next_legal_action"] = synthetic_next
            allocation_bridge = _contract_runtime_mf_sub_host_bridge_guidance(
                synthetic_guide
            )
            allocation_submission = dict(
                allocation_bridge.get("parallel_branch_allocate_submission")
                or {}
            )
            if allocation_submission:
                result["parallel_branch_allocate_submission"] = (
                    allocation_submission
                )
                result["copy_safe_dispatch_payload"] = {
                    "parallel_branch_allocate": allocation_submission,
                }
            route_issue_request_bodies = list(
                allocation_bridge.get(
                    "observer_route_context_issue_request_bodies"
                )
                or []
            )
            route_issue_recipe = dict(
                allocation_bridge.get("per_lane_observer_route_context_issue")
                or {}
            )
            if route_issue_request_bodies and route_issue_recipe:
                result["observer_route_context_issue_request_bodies"] = (
                    route_issue_request_bodies
                )
                result["per_lane_observer_route_context_issue"] = (
                    route_issue_recipe
                )
                result.setdefault("copy_safe_dispatch_payload", {})[
                    "per_lane_observer_route_context_issue"
                ] = route_issue_recipe
        copy_payload = (
            dict(writer_safe_copy.get("copy_payload") or {})
            if isinstance(writer_safe_copy, Mapping)
            and isinstance(writer_safe_copy.get("copy_payload"), Mapping)
            else {}
        )
        if next_line.get("copy_safe_dispatch_ready") is True and copy_payload:
            result.setdefault("copy_safe_dispatch_payload", {})[
                "contract_runtime_submit_line"
            ] = {
                "schema_version": (
                    "contract_runtime.copy_safe_dispatch_submission.v1"
                ),
                "mcp_tool": (
                    "contract_update_submit_line"
                    if contract_id == CONTRACT_UPDATE_CONTRACT_ID
                    else "contract_runtime_submit_line"
                ),
                "body_source": (
                    "writer_role_safe_copy_payload.copy_payload"
                ),
                "copy_safe_body": copy_payload,
                "submit_unchanged": True,
                "source_spelunking_required": False,
            }
    post_read_startup = (
        guide.get("failed_qa_replacement_post_read_startup_projection")
        if isinstance(
            guide.get(
                "failed_qa_replacement_post_read_startup_projection"
            ),
            Mapping,
        )
        else {}
    )
    replacement_startup_facade_ready = bool(
        line_id == "worker_startup"
        and next_line.get(
            "failed_qa_replacement_post_read_startup_projection"
        )
        is True
        and post_read_startup.get("status") == "projected"
        and post_read_startup.get("server_derived") is True
        and isinstance(next_line.get("accepted_dispatch_authority"), Mapping)
        and next_line["accepted_dispatch_authority"].get("server_derived")
        is True
    )
    bridge_guidance = (
        {}
        if route_action_scope_blocked
        or persisted_allocation_authority_blocked
        or replacement_startup_facade_ready
        else _contract_runtime_mf_sub_host_bridge_guidance(guide)
    )
    if bridge_guidance:
        result["mf_sub_host_bridge_guidance"] = bridge_guidance
    return result


def _runtime_readiness_state_from_guide(guide: Mapping[str, Any]) -> str:
    explicit_readiness = str(guide.get("readiness_state") or "").strip()
    if explicit_readiness:
        return explicit_readiness
    if "next_legal_action" not in guide:
        return ""
    if guide.get("next_legal_action") is None:
        return "contract_complete"
    return "contract_active"


def _contract_runtime_accepted_qa_graph_evidence(
    line: Mapping[str, Any],
    evidence: Mapping[str, Any],
) -> bool:
    authority_hash = str(evidence.get("authority_hash") or "").strip()
    unsigned = {
        key: value for key, value in evidence.items() if key != "authority_hash"
    }
    return bool(
        str(line.get("line_id") or "").strip() == "qa_graph_context"
        and _contract_runtime_line_status_passes(line)
        and _contract_runtime_authenticated_qa_provenance(line)
        and evidence.get("db_verified") is True
        and authority_hash
        and authority_hash == stable_sha256(unsigned)
    )


def _contract_runtime_comparison_base_verdict(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    completed_lines = record.get("completed_lines") or []
    for index in range(len(completed_lines) - 1, -1, -1):
        line = completed_lines[index]
        if not isinstance(line, Mapping) or str(
            line.get("line_id") or ""
        ).strip() != "qa_graph_context":
            continue
        payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
        evidence = (
            payload.get("graph_trace_evidence")
            if isinstance(payload.get("graph_trace_evidence"), Mapping)
            else {}
        )
        if not evidence:
            continue
        graph_basis = str(evidence.get("graph_basis") or "").strip()
        comparison_required = bool(
            evidence.get("comparison_authority_required")
        )
        comparison_base = str(
            evidence.get("comparison_base_commit_sha") or ""
        ).strip().lower()
        candidate_commit = str(
            evidence.get("candidate_commit_sha") or ""
        ).strip().lower()
        provenance = (
            evidence.get("post_merge_provenance")
            if isinstance(evidence.get("post_merge_provenance"), Mapping)
            else {}
        )
        if not (
            comparison_required
            or comparison_base
            or provenance
            or graph_basis == "exact_candidate_snapshot"
        ):
            continue
        frozen_evidence_valid = _contract_runtime_accepted_qa_graph_evidence(
            line,
            evidence,
        )
        mismatches: list[dict[str, Any]] = []
        for item in evidence.get("identity_mismatches") or []:
            if isinstance(item, Mapping):
                mismatches.append(
                    {
                        key: item.get(key)
                        for key in ("trace_id", "field", "expected", "actual")
                        if item.get(key) not in (None, "")
                    }
                )
            else:
                mismatches.append(
                    {
                        "field": "identity_mismatches",
                        "expected": "empty structured mismatch list",
                        "actual": str(item),
                        "legacy_unstructured": True,
                    }
                )
        if not frozen_evidence_valid:
            mismatches.append(
                {
                    "field": "graph_trace_evidence.authority_hash",
                    "expected": "authenticated accepted DB-verified frozen evidence",
                    "actual": str(evidence.get("authority_hash") or ""),
                }
            )
        comparison_verified = bool(
            frozen_evidence_valid
            and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", comparison_base)
            and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", candidate_commit)
            and comparison_base != candidate_commit
            and not mismatches
        )
        if comparison_required and not comparison_verified and not mismatches:
            mismatches.append(
                {
                    "field": "comparison_base_commit_sha",
                    "expected": "verified full commit distinct from candidate",
                    "actual": comparison_base,
                }
            )
        post_merge_verified = bool(
            comparison_verified
            and str(provenance.get("schema_version") or "")
            == "qa_exact_candidate.post_merge_provenance.v1"
            and provenance.get("verified") is True
            and str(provenance.get("candidate_commit_sha") or "").lower()
            == candidate_commit
            and re.fullmatch(
                r"timeline:[1-9][0-9]*",
                str(provenance.get("qa_event_ref") or ""),
            )
            and re.fullmatch(
                r"timeline:[1-9][0-9]*",
                str(provenance.get("merge_event_ref") or ""),
            )
            and provenance.get("ordered_after_qa") is True
            and provenance.get("candidate_is_ancestor") is True
            and provenance.get(
                "scoped_merge_is_ancestor_of_canonical_head"
            )
            is True
        )
        if post_merge_verified:
            status = "post_merge_verified"
        elif comparison_verified:
            status = "comparison_base_verified"
        elif comparison_required:
            status = "blocked"
        else:
            status = "legacy_unpersisted"
        verdict = {
            "schema_version": "contract_runtime.comparison_base_verdict.v1",
            "verification_status": status,
            "comparison_authority_required": comparison_required,
            "comparison_base_commit_sha": comparison_base,
            "comparison_base_commit_source": str(
                evidence.get("comparison_base_commit_source") or ""
            ),
            "candidate_commit_sha": candidate_commit,
            "changed_files_source": str(
                evidence.get("changed_files_source") or ""
            ),
            "db_verified": evidence.get("db_verified") is True,
            "post_merge_provenance_verified": post_merge_verified,
            "qa_event_ref": str(provenance.get("qa_event_ref") or ""),
            "merge_event_ref": str(provenance.get("merge_event_ref") or ""),
            "scoped_identity_mismatches": mismatches,
            "mismatch_count": len(mismatches),
            "source_ref": (
                f"contract_runtime:{record.get('contract_execution_id', '')}:"
                f"completed_lines:{index}"
            ),
        }
        return verdict
    return {}


def _contract_runtime_failed_qa_fresh_repair_action(
    record: Mapping[str, Any],
    failed_qa_line: Mapping[str, Any],
    *,
    failed_index: int,
    failed_source_ref: str,
) -> dict[str, Any]:
    """Project a copy-safe current-world row from one terminal rev10 failure.

    ``direct_fix`` is retired and the failed ContractRuntime generation is an
    audit source, not reusable execution authority.  The rev10 enter metadata
    already freezes the row scope and acceptance criteria, so use only those
    durable facts to advertise a new observer-owned backlog row.  An incomplete
    historical record remains readable but deliberately produces no executable
    body.
    """

    _contract_runtime_require_canonical_authority_registry_complete()

    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    child_plan = (
        metadata.get("observer_prefill_child_plan")
        if isinstance(metadata.get("observer_prefill_child_plan"), Mapping)
        else {}
    )
    acceptance_scope = (
        metadata.get("acceptance_scope_closure")
        if isinstance(metadata.get("acceptance_scope_closure"), Mapping)
        else {}
    )

    declared_files = _runtime_context_public_file_values(
        acceptance_scope.get("row_declared_files")
        or acceptance_scope.get("required_file_union")
        or child_plan.get("row_owned_files")
        or []
    )
    test_files = _runtime_context_public_file_values(
        child_plan.get("row_test_files")
        or metadata.get("test_files")
        or []
    )
    if not test_files:
        test_files = [
            path
            for path in declared_files
            if Path(path).name.startswith("test_")
            or "tests" in Path(path).parts
        ]
    test_file_set = set(test_files)
    target_files = [path for path in declared_files if path not in test_file_set]
    acceptance_criteria = (
        metadata.get("acceptance_criteria")
        if isinstance(metadata.get("acceptance_criteria"), list)
        else child_plan.get("acceptance_criteria")
        if isinstance(child_plan.get("acceptance_criteria"), list)
        else []
    )
    unsafe_acceptance_paths = (
        _contract_runtime_unsafe_execution_authority_paths(
            acceptance_criteria,
            root_path="acceptance_criteria",
        )
    )
    safe_acceptance_criteria = (
        [] if unsafe_acceptance_paths else deepcopy(acceptance_criteria)
    )

    project_id = str(record.get("project_id") or "").strip()
    source_backlog_id = str(record.get("backlog_id") or "").strip()
    contract_execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    failure_payload = (
        failed_qa_line.get("payload")
        if isinstance(failed_qa_line.get("payload"), Mapping)
        else {}
    )
    repair_suffix = stable_sha256(
        {
            "source_backlog_id": source_backlog_id,
            "contract_execution_id": contract_execution_id,
            "failed_qa_completed_line_index": failed_index,
            "failed_qa_line": dict(failed_qa_line),
        }
    ).split(":")[-1][:12].upper()
    fresh_backlog_id = (
        f"{source_backlog_id}-QA-REPAIR-{repair_suffix}"
        if source_backlog_id
        else f"AC-MF-PARALLEL-QA-REPAIR-{repair_suffix}"
    )
    required_fields = {
        "project_id": project_id,
        "bug_id": fresh_backlog_id,
        "title": (
            f"Repair failed QA from {source_backlog_id}"
            if source_backlog_id
            else "Repair failed mf_parallel QA"
        ),
        "priority": "P0",
        "status": "OPEN",
        "target_files": target_files,
        "test_files": test_files,
        "acceptance_criteria": safe_acceptance_criteria,
    }
    missing_fields = [
        field
        for field, value in required_fields.items()
        if value in ("", None, [], {})
    ]
    action_input_ready = not missing_fields
    action_input: dict[str, Any] = {}
    if action_input_ready:
        action_input = {
            **required_fields,
            "details_md": (
                "Fresh independently bounded current-world repair for the "
                f"failed QA source {failed_source_ref}. The source rev10 "
                "generation is immutable audit evidence and supplies no worker, "
                "route, worktree, merge, or write authority to this row."
            ),
            "provenance_paths": [failed_source_ref],
            "mf_type": "chain_rescue",
            "actor": "observer",
            "triage_action": "admit",
        }
    canonical_action = (
        _guide_canonical_executable_action(
            project_id=project_id,
            action="backlog_upsert",
            facade="backlog_upsert",
            mcp_tool="backlog_upsert",
            body=action_input,
            backlog_id=fresh_backlog_id,
        )
        if action_input_ready
        else {}
    )
    historical_direct_fix = {
        "contract_id": DIRECT_FIX_CONTRACT_ID,
        "status": "terminal_retired",
        "historical_evidence_readable": True,
        "scheduler_eligible": False,
        "authorizes_write": False,
    }
    return {
        "schema_version": (
            "contract_runtime.failed_qa_fresh_repair_successor.v1"
        ),
        "id": "file_fresh_bounded_row",
        "action": "backlog_upsert",
        "interface": "backlog_upsert",
        "facade": "backlog_upsert",
        "mcp_tool": "backlog_upsert",
        "method": "POST",
        "owner_role": "observer",
        "allowed_writer_roles": ["observer"],
        "actionable": action_input_ready,
        "action_input_ready": action_input_ready,
        "action_input": deepcopy(action_input),
        "copy_safe_body": deepcopy(action_input),
        "canonical_executable_action": canonical_action,
        "action_input_missing_fields": missing_fields,
        "unsafe_action_input_paths": unsafe_acceptance_paths,
        "failed_qa_source_ref": failed_source_ref,
        "failed_qa_status": str(
            failure_payload.get("status")
            or failed_qa_line.get("status")
            or "failed"
        ).strip(),
        "source_generation_terminal": True,
        "same_row_resume_allowed": False,
        "separate_bounded_successor_row_required": True,
        "fresh_authority_required": True,
        "source_runtime_authority_reusable": False,
        "historical_contract_successor": historical_direct_fix,
        "forbidden_authority_reuse": sorted(
            _CONTRACT_RUNTIME_EXECUTION_AUTHORITY_KEY_ALIAS_MATRIX
        ),
        "next_after_success": {
            "interface": "onboard_route_guide",
            "role": "observer",
            "work_type": "parallel_worker",
            "body": {
                "project_id": project_id,
                "backlog_id": fresh_backlog_id,
                "role": "observer",
                "work_type": "parallel_worker",
            },
        },
    }


def _runtime_current_state_from_record(record: Mapping[str, Any]) -> dict[str, Any]:
    guide = record.get("runtime_guide") if isinstance(record.get("runtime_guide"), Mapping) else {}
    state = record.get("execution_state") if isinstance(record.get("execution_state"), Mapping) else {}
    current_state = {
        "schema_version": "contract_runtime_current_state.v1",
        "contract_execution_id": str(record.get("contract_execution_id") or ""),
        "parent_contract_execution_id": str(
            record.get("parent_contract_execution_id") or ""
        ),
        "root_contract_execution_id": str(record.get("root_contract_execution_id") or ""),
        "contract_chain_id": str(record.get("contract_chain_id") or ""),
        "contract_id": str(record.get("contract_id") or ""),
        "contract_revision_id": str(record.get("revision") or ""),
        "contract_hash": str(record.get("definition_hash") or ""),
        "execution_state_revision": int(
            record.get("execution_state_revision")
            or state.get("execution_state_revision")
            or 0
        ),
        "execution_state_hash": str(state.get("execution_state_hash") or ""),
        "route_token_ref": str(record.get("route_token_ref") or ""),
        "runtime_guide_hash": str(guide.get("runtime_guide_hash") or ""),
        "next_legal_action": _runtime_next_action_from_guide(guide),
    }
    readiness_state = _runtime_readiness_state_from_guide(guide)
    if readiness_state:
        current_state["readiness_state"] = readiness_state
    terminal_retirement = (
        guide.get("terminal_retirement")
        if isinstance(guide.get("terminal_retirement"), Mapping)
        else {}
    )
    if terminal_retirement:
        precheck_decision = (
            guide.get("precheck_decision")
            if isinstance(guide.get("precheck_decision"), Mapping)
            else {}
        )
        current_state.update(
            {
                "readiness_state": "terminal_retired",
                "disposition": "terminal_retired",
                "terminal": True,
                "historical_pinned_read_only": True,
                "scheduler_eligible": False,
                "schedulable": False,
                "current_eligible": False,
                "close_eligible": False,
                "closeable": False,
                "resume_eligible": False,
                "resumable": False,
                "retry_eligible": False,
                "write_eligible": False,
                "terminal_retirement": dict(terminal_retirement),
                "precheck_decision": dict(precheck_decision),
                "decision": dict(precheck_decision),
            }
        )
    terminal = (
        guide.get("terminal_disposition")
        if isinstance(guide.get("terminal_disposition"), Mapping)
        else {}
    )
    if terminal and not terminal_retirement:
        recovery_fallback = (
            guide.get("bypass_recovery_fallback")
            if isinstance(guide.get("bypass_recovery_fallback"), Mapping)
            else terminal.get("bypass_recovery_fallback")
            if isinstance(terminal.get("bypass_recovery_fallback"), Mapping)
            else {}
        )
        current_state.update(
            {
                "row_status": str(
                    terminal.get("row_status") or "WAIVED"
                ).strip(),
                "source_row_status": str(
                    terminal.get("source_row_status") or "WAIVED"
                ).strip(),
                "disposition": str(
                    terminal.get("disposition")
                    or "completed_with_exception"
                ).strip(),
                "terminal": True,
                "scheduler_eligible": False,
                "schedulable": False,
                "current_eligible": False,
                "close_eligible": False,
                "closeable": False,
                "resume_eligible": False,
                "resumable": False,
                "terminal_disposition": dict(terminal),
            }
        )
        if recovery_fallback:
            current_state["bypass_recovery_fallback"] = dict(
                recovery_fallback
            )
    barrier_pending = (
        guide.get("bypass_barrier_pending")
        if isinstance(guide.get("bypass_barrier_pending"), Mapping)
        else {}
    )
    if barrier_pending:
        current_state.update(
            {
                "status": "blocked",
                "readiness_state": "bypass_barrier_pending",
                "terminal": False,
                "scheduler_eligible": False,
                "schedulable": False,
                "current_eligible": False,
                "close_eligible": False,
                "closeable": False,
                "resume_eligible": False,
                "resumable": False,
                "bypass_barrier_pending": dict(barrier_pending),
            }
        )
    bridge_guidance = _contract_runtime_mf_sub_host_bridge_guidance(guide)
    if bridge_guidance:
        current_state["mf_sub_host_bridge_guidance"] = bridge_guidance
    comparison_base_verdict = _contract_runtime_comparison_base_verdict(record)
    if comparison_base_verdict:
        current_state["comparison_base_verdict"] = comparison_base_verdict
    post_read_startup_projection = (
        record.get("failed_qa_replacement_post_read_startup_projection")
        if isinstance(
            record.get(
                "failed_qa_replacement_post_read_startup_projection"
            ),
            Mapping,
        )
        else {}
    )
    post_read_next = (
        current_state.get("next_legal_action")
        if isinstance(current_state.get("next_legal_action"), Mapping)
        else {}
    )
    post_read_dispatch = (
        post_read_next.get("accepted_dispatch_authority")
        if isinstance(
            post_read_next.get("accepted_dispatch_authority"), Mapping
        )
        else {}
    )
    if (
        post_read_startup_projection.get("status") == "projected"
        and post_read_startup_projection.get("server_derived") is True
        and post_read_startup_projection.get("contract_runtime_mutated")
        is False
        and post_read_startup_projection.get(
            "append_only_history_preserved"
        )
        is True
        and str(post_read_next.get("line_id") or "").strip()
        == "worker_startup"
        and post_read_dispatch.get("status") == "projected"
        and post_read_dispatch.get("server_derived") is True
        and all(
            str(post_read_startup_projection.get(field) or "").strip()
            == str(post_read_dispatch.get(field) or "").strip()
            == str(post_read_next.get(field) or "").strip()
            for field in (
                "runtime_context_id",
                "task_id",
                "parent_task_id",
                "worker_id",
                "worker_slot_id",
            )
        )
        and int(
            post_read_startup_projection.get(
                "dispatch_completed_line_index", -1
            )
        )
        == int(post_read_dispatch.get("dispatch_completed_line_index", -2))
        and str(
            post_read_startup_projection.get("dispatch_source_ref") or ""
        ).strip()
        == str(post_read_dispatch.get("source_ref") or "").strip()
    ):
        current_state["accepted_dispatch_authority"] = dict(
            post_read_dispatch
        )
        current_state[
            "failed_qa_replacement_post_read_startup_projection"
        ] = dict(post_read_startup_projection)
        current_state.pop("mf_sub_host_bridge_guidance", None)
    if (
        _is_mf_parallel_record_contract_id(
            str(record.get("contract_id") or "")
        )
        and _is_mf_parallel_postmerge_revision(record)
    ):
        failed_qa_line = _contract_runtime_latest_failed_qa_line(record)
        if failed_qa_line and not _runtime_record_is_complete(record):
            failed_index = int(
                failed_qa_line.get("_completed_line_index") or 0
            )
            current_next = (
                current_state.get("next_legal_action")
                if isinstance(
                    current_state.get("next_legal_action"), Mapping
                )
                else {}
            )
            current_next_line = str(
                current_next.get("line_id")
                or current_next.get("id")
                or ""
            ).strip()
            selected_dispatch = (
                _contract_runtime_current_dispatch_authority_line(record)
            )
            selected_dispatch_index = int(
                selected_dispatch.get("completed_line_index")
                if selected_dispatch.get("completed_line_index") is not None
                else -1
            )
            replacement_dispatch = (
                _contract_runtime_dispatch_ticket_authority(
                    record,
                    current_state,
                    allow_post_read_startup=(
                        current_next_line == "worker_startup"
                    ),
                    allow_post_startup_graph=(
                        current_next_line == "worker_graph_context"
                    ),
                )
                if (
                    selected_dispatch.get("status") == "selected"
                    and selected_dispatch_index > failed_index
                )
                else {}
            )
            replacement_dispatch_ready = (
                replacement_dispatch.get("status") == "projected"
            )
            if replacement_dispatch_ready:
                dispatch_action = (
                    replacement_dispatch.get("next_legal_action")
                    if isinstance(
                        replacement_dispatch.get("next_legal_action"),
                        Mapping,
                    )
                    else {}
                )
                rebound_next = dict(current_next)
                for field in (
                    "runtime_context_id",
                    "task_id",
                    "parent_task_id",
                    "worker_id",
                    "worker_slot_id",
                    "observer_command_id",
                    "worker_role",
                    "target_project_root",
                    "worktree_path",
                    "branch_ref",
                    "base_commit",
                    "target_head_commit",
                    "merge_queue_id",
                    "owned_files",
                    *_RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS,
                ):
                    value = dispatch_action.get(field)
                    if value:
                        rebound_next[field] = (
                            list(value)
                            if isinstance(value, tuple)
                            else value
                        )
                replacement_runtime_context_id = str(
                    dispatch_action.get("runtime_context_id") or ""
                ).strip()
                replacement_worker_slot_id = str(
                    dispatch_action.get("worker_slot_id")
                    or dispatch_action.get("worker_id")
                    or ""
                ).strip()
                if replacement_runtime_context_id:
                    rebound_next["line_instance_id"] = (
                        f"runtime_context:{replacement_runtime_context_id}"
                    )
                if replacement_worker_slot_id:
                    rebound_next["lane_id"] = replacement_worker_slot_id
                accepted_dispatch_authority = {
                    "schema_version": (
                        "contract_runtime.failed_qa_replacement_dispatch_authority.v1"
                    ),
                    "status": "projected",
                    "source": "server_verified_failed_qa_replacement_dispatch",
                    "server_derived": True,
                    "failed_qa_completed_line_index": failed_index,
                    "dispatch_completed_line_index": selected_dispatch_index,
                    "source_ref": str(
                        replacement_dispatch.get("source_ref") or ""
                    ),
                    "runtime_context_id": str(
                        dispatch_action.get("runtime_context_id") or ""
                    ),
                    "task_id": str(dispatch_action.get("task_id") or ""),
                    "parent_task_id": str(
                        dispatch_action.get("parent_task_id") or ""
                    ),
                    "worker_id": str(
                        dispatch_action.get("worker_id") or ""
                    ),
                    "worker_slot_id": replacement_worker_slot_id,
                    "lane_id": replacement_worker_slot_id,
                    "line_instance_id": str(
                        rebound_next.get("line_instance_id") or ""
                    ),
                }
                rebound_next["accepted_dispatch_authority"] = dict(
                    accepted_dispatch_authority
                )
                current_state["next_legal_action"] = rebound_next
                current_state["accepted_dispatch_authority"] = dict(
                    accepted_dispatch_authority
                )
            failed_source_ref = (
                f"contract_runtime:{record.get('contract_execution_id', '')}:"
                f"completed_lines:{failed_index}"
            )
            revision = str(record.get("revision") or "").strip()
            bounded_worker_fix = revision == "rev9"
            if replacement_dispatch_ready:
                return current_state
            if revision == "rev10":
                current_state.update(
                    {
                        "status": "blocked",
                        "readiness_state": (
                            "failed_qa_fresh_repair_successor_required"
                        ),
                        "next_legal_action": (
                            _contract_runtime_failed_qa_fresh_repair_action(
                                record,
                                failed_qa_line,
                                failed_index=failed_index,
                                failed_source_ref=failed_source_ref,
                            )
                        ),
                    }
                )
                current_state.pop("accepted_dispatch_authority", None)
                current_state.pop("mf_sub_host_bridge_guidance", None)
                return current_state
            current_state.update(
                {
                    "status": "blocked",
                    "readiness_state": "failed_qa_worker_fix_required",
                    "next_legal_action": {
                        "id": (
                            "allocate_bounded_worker_fix"
                            if bounded_worker_fix
                            else "enter_direct_fix_successor"
                        ),
                        "action": (
                            "parallel_branch_allocate"
                            if bounded_worker_fix
                            else "enter_direct_fix_successor"
                        ),
                        "owner_role": "observer",
                        "recommended_successor_contract_id": (
                            MF_PARALLEL_CONTRACT_ID
                            if bounded_worker_fix
                            else DIRECT_FIX_CONTRACT_ID
                        ),
                        "failed_qa_source_ref": failed_source_ref,
                        "bounded_worker_fix_required": True,
                        **(
                            {
                                "successor_mode": (
                                    "same_contract_append_only_failed_qa_rework"
                                ),
                                "worker_fix_cardinality": 1,
                                "allocation_precheck_required": False,
                                "allocation_tool": "parallel_branch_allocate",
                                "allocation_request_requirements": {
                                    "stage_type": "failed_qa_rework",
                                    "minimum_attempt": 2,
                                    "failed_qa_source_ref": failed_source_ref,
                                    "fresh_runtime_context_required": True,
                                },
                                "direct_fix_allowed": False,
                            }
                            if bounded_worker_fix
                            else {}
                        ),
                        "fresh_qa_session_required": True,
                        "return_sequence": [
                            "observer_merge",
                            "observer_reconcile",
                            "qa_graph_context",
                            "qa_independent_verification",
                        ],
                    },
                }
            )
    return current_state


