    "target_project_root",
    "project_root",
    "repo_root",
    "route_id",
    "route_context_hash",
    "prompt_contract_id",
    "prompt_contract_hash",
    "visible_injection_manifest_hash",
    "route_identity",
    "session_token_ref",
    "graph_trace_id",
    "graph_trace_ids",
    "graph_query_trace_id",
    "graph_query_trace_ids",
    "caller_graph_query_schema_trace_id",
    "read_receipt_hash",
    "startup_event_id",
    "startup_event_ref",
    "implementation_event_refs",
    "changed_files",
