def _contract_runtime_line_write_body(
    record: Mapping[str, Any],
    body: Mapping[str, Any],
    *,
    actor_role: str,
    worker_proof: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    next_line = (
        record.get("runtime_guide", {}).get("next_legal_action")
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    write = _contract_runtime_write_from_record(
        record,
        actor_role=actor_role,
        stage_id=str(body.get("stage_id") or (next_line or {}).get("stage_id") or ""),
        line_id=str(body.get("line_id") or (next_line or {}).get("line_id") or ""),
        evidence_kind=str(
            body.get("evidence_kind")
            or (next_line or {}).get("evidence_kind")
            or ""
        ),
    )
    # Keep the HTTP bridge and ContractRuntime persistence vocabulary aligned.
    # This is an allowlist, not a generic body copy: raw route/session/QA tokens
    # are transport credentials and must never become completed-line evidence.
    for key in dict.fromkeys(
        (*_CONTRACT_RUNTIME_LINE_WRITE_PROTOCOL_FIELDS, *LINE_EVIDENCE_OPTIONAL_FIELDS)
    ):
        if key in body:
            write[key] = body[key]
    if (
        write.get("line_id") == "observer_dispatch_bounded_workers"
        and write.get("evidence_kind") == "dispatch_bounded_worker"
    ):
        raw_payload = write.get("payload")
        payload = raw_payload if isinstance(raw_payload, Mapping) else {}
        worker_role = (
            str(write.get("worker_role") or "").strip()
            or _dispatch_payload_worker_role(payload)
        )
        if not worker_role:
            worker_role = "mf_sub"
        write["worker_role"] = worker_role
        if isinstance(payload, Mapping):
            write["payload"] = _normalize_dispatch_payload_worker_role(
                payload,
                worker_role,
            )
    if actor_role == "mf_sub" and worker_proof:
        from .runtime_context import attach_contract_runtime_worker_provenance

        write = attach_contract_runtime_worker_provenance(write, worker_proof)
        write.setdefault(
            "lane_id",
            str(
                write.get("worker_slot_id")
                or write.get("worker_id")
                or ""
            ).strip(),
        )
        proof_identity_mismatches = []
        for field in (
            "runtime_context_id",
            "task_id",
            "parent_task_id",
            "lane_id",
            "worker_slot_id",
            "worker_id",
        ):
            provided = str(body.get(field) or "").strip()
            expected = str(write.get(field) or "").strip()
            if provided and expected and provided != expected:
                proof_identity_mismatches.append(
                    {
                        "field": field,
                        "expected": expected,
                        "actual": provided,
                    }
                )
        if proof_identity_mismatches:
            raise ValidationError(
                "worker identity conflicts with authenticated RuntimeContext proof",
                {"identity_mismatches": proof_identity_mismatches},
            )
        if write.get("line_id") == "worker_commit":
            payload = (
                dict(write.get("payload"))
                if isinstance(write.get("payload"), Mapping)
                else {}
            )
            if (
                _contract_runtime_line_status_passes(write)
                and "status" not in write
            ):
                write["status"] = "accepted"
            if (
                _contract_runtime_line_status_passes(payload)
                and "status" not in payload
            ):
                payload["status"] = "accepted"
            write["payload"] = payload
    if write.get("line_id") == "worker_implementation":
        payload = (
            dict(write.get("payload"))
            if isinstance(write.get("payload"), Mapping)
            else {}
        )
        proof_fields = (
            "changed_files",
            "owned_changed_files",
            "graph_trace_ids",
            "graph_query_trace_ids",
        )
        for key in proof_fields:
            if key not in body:
                continue
            top_level = _runtime_context_service_query_values(body, key)
            nested = _runtime_context_service_query_values(payload, key)
            if nested and set(nested) != set(top_level):
                raise ValidationError(
                    f"worker_implementation {key} conflicts with payload.{key}"
                )
            payload[key] = top_level
        changed_files = _runtime_context_service_dedupe(
            _runtime_context_service_query_values(
                payload,
                "changed_files",
                "owned_changed_files",
            )
        )
        graph_trace_ids = _runtime_context_service_dedupe(
            _runtime_context_service_query_values(
                payload,
                "graph_trace_ids",
                "graph_query_trace_ids",
            )
        )
        missing_proof_fields = []
        if not changed_files:
            missing_proof_fields.append("changed_files")
        if not graph_trace_ids:
            missing_proof_fields.append("graph_trace_ids")
        if missing_proof_fields:
            raise ValidationError(
                "worker_implementation requires non-empty canonical lineage proof",
                {
                    "missing_proof_fields": missing_proof_fields,
                    "next_legal_action": "runtime_context_implementation_evidence",
                    "timeline_evidence_backfill_allowed": False,
                },
            )
        supplied_test_results = (
            _runtime_context_require_worker_implementation_test_results(
                body,
                contract_execution_id=str(
                    record.get("contract_execution_id") or ""
                ).strip(),
                runtime_context_id=str(
                    write.get("runtime_context_id")
                    or payload.get("runtime_context_id")
                    or ""
                ).strip(),
                task_id=str(
                    write.get("task_id") or payload.get("task_id") or ""
                ).strip(),
            )
        )
        from .parallel_branch_runtime import public_contract_revision_payload

        canonical_test_results = public_contract_revision_payload(
            supplied_test_results
        )
        payload["changed_files"] = changed_files
        payload["graph_trace_ids"] = graph_trace_ids
        payload["test_results"] = canonical_test_results
        write["payload"] = payload
        write["changed_files"] = changed_files
        write["graph_trace_ids"] = graph_trace_ids
        write["test_results"] = canonical_test_results
    return write


def _contract_runtime_mf_parallel_atomic_lane_write_record(
    runtime,
    *,
    record: Mapping[str, Any],
    source_record: Mapping[str, Any],
    projection: Mapping[str, Any] | None,
    body: Mapping[str, Any],
    actor_role: str,
    worker_proof: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Bind a generic worker write to the shared atomic per-lane gate view."""

    if actor_role != "mf_sub" or not worker_proof:
        return dict(record)
    provisional_write = _contract_runtime_line_write_body(
        record,
        actor_role=actor_role,
        body=body,
        worker_proof=worker_proof,
    )
    lane_state, lane_guide = runtime.mf_parallel_atomic_lane_gate_view(
        record,
        (
            record.get("runtime_guide")
            if isinstance(record.get("runtime_guide"), Mapping)
            else {}
        ),
        provisional_write,
        source_record=source_record,
        projection=projection,
    )
    lane_record = dict(record)
    lane_record["execution_state"] = lane_state
    lane_record["runtime_guide"] = lane_guide
    return lane_record


