def _contract_runtime_definition_for_record(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    return _CONTRACT_DEFINITION_REGISTRY.get(
        str(record.get("contract_id") or ""),
        version=str(record.get("version") or ""),
        revision=str(record.get("revision") or ""),
        include_deprecated=True,
    )


def _contract_state_pinned_source_definition_resolution(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    timeline_events: Sequence[Mapping[str, Any]],
    preferred_execution_id: str = "",
) -> tuple[dict[str, Any], dict[str, Any]]:
    records = _contract_runtime_store(conn).list_by_backlog(
        project_id=project_id,
        backlog_id=backlog_id,
    )
    by_execution_id = {
        str(record.get("contract_execution_id") or "").strip(): record
        for record in records
        if str(record.get("contract_execution_id") or "").strip()
    }

    def strict_policy_possible(record: Mapping[str, Any]) -> bool:
        revision = str(record.get("revision") or "").strip()
        if revision == "rev2":
            return True
        if (
            str(record.get("contract_id") or "").strip()
            == "operator_supervised_direct_main"
            and revision
            in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        ):
            return True
        try:
            definition = _contract_runtime_definition_for_record(record)
        except Exception:
            return False
        system_layer = (
            definition.get("system_layer")
            if isinstance(definition.get("system_layer"), Mapping)
            else {}
        )
        graph_policy = (
            system_layer.get("graph_binding_policy")
            if isinstance(system_layer.get("graph_binding_policy"), Mapping)
            else {}
        )
        return any(
            isinstance(policy, Mapping) and policy.get("enabled") is True
            for policy in graph_policy.values()
        )

    strict_possible = any(strict_policy_possible(record) for record in records)
    base_resolution = {
        "schema_version": "contract_state.source_definition_resolution.v1",
        "authority": "ContractRuntime.pinned_source_definition",
        "project_id": project_id,
        "backlog_id": backlog_id,
        "candidate_count": len(records),
        "strict_policy_possible": strict_possible,
    }
    if not records:
        return {}, {
            **base_resolution,
            "status": "no_contract_runtime_execution",
            "fail_closed": False,
        }

    selected: Mapping[str, Any] | None = None
    preferred_execution_id = str(preferred_execution_id or "").strip()
    if preferred_execution_id in by_execution_id:
        selected = by_execution_id[preferred_execution_id]
    if selected is None:
        for event in reversed(
            [item for item in timeline_events if isinstance(item, Mapping)]
        ):
            event_execution_ids: set[str] = set()
            event_task_id = str(event.get("task_id") or "").strip()
            if event_task_id in by_execution_id:
                event_execution_ids.add(event_task_id)
            for candidate in _contract_runtime_mapping_candidates(event):
                for key in (
                    "contract_execution_id",
                    "projection_contract_execution_id",
                    "successor_contract_execution_id",
                ):
                    execution_id = str(candidate.get(key) or "").strip()
                    if execution_id in by_execution_id:
                        event_execution_ids.add(execution_id)
            if len(event_execution_ids) == 1:
                selected = by_execution_id[next(iter(event_execution_ids))]
                break
            if len(event_execution_ids) > 1:
                return {}, {
                    **base_resolution,
                    "status": "ambiguous_timeline_execution_identity",
                    "fail_closed": strict_possible,
                    "matching_execution_ids": sorted(event_execution_ids),
                }
    if selected is None and len(records) == 1:
        selected = records[0]
    if selected is None:
        return {}, {
            **base_resolution,
            "status": "ambiguous_contract_runtime_execution",
            "fail_closed": strict_possible,
            "matching_execution_ids": sorted(by_execution_id),
        }

    execution_id = str(selected.get("contract_execution_id") or "").strip()
    try:
        definition = _contract_runtime_definition_for_record(selected)
    except Exception as exc:
        return {}, {
            **base_resolution,
            "status": "pinned_definition_unavailable",
            "fail_closed": strict_policy_possible(selected),
            "contract_execution_id": execution_id,
            "diagnostic": str(exc),
        }
    record_revision = str(selected.get("revision") or "").strip()
    record_hash = str(selected.get("definition_hash") or "").strip()
    definition_revision = str(definition.get("revision") or "").strip()
    definition_hash = str(definition.get("definition_hash") or "").strip()
    identity_matches = bool(
        record_revision
        and record_revision == definition_revision
        and record_hash
        and record_hash == definition_hash
    )
    resolution = {
        **base_resolution,
        "status": "pinned" if identity_matches else "definition_identity_mismatch",
        "fail_closed": not identity_matches and strict_policy_possible(selected),
        "contract_execution_id": execution_id,
        "contract_id": str(selected.get("contract_id") or "").strip(),
        "version": str(selected.get("version") or "").strip(),
        "record_revision": record_revision,
        "definition_revision": definition_revision,
        "record_definition_hash": record_hash,
        "definition_hash": definition_hash,
    }
    return (dict(definition), resolution) if identity_matches else ({}, resolution)


def _contract_runtime_line_evidence_policy(
    record: Mapping[str, Any],
    policy_name: str,
    *,
    line_id: str,
) -> Mapping[str, Any]:
    definition = _contract_runtime_definition_for_record(record)
    return contract_line_evidence_policy(
        definition,
        policy_name,
        line_id=line_id,
    )


def _contract_runtime_requested_trace_ids(
    body: Mapping[str, Any],
    policy: Mapping[str, Any],
) -> list[str]:
    payload = body.get("payload") if isinstance(body.get("payload"), Mapping) else {}
    authority_path = str(policy.get("authority_object_path") or "")
    authority_key = authority_path.split(".", 1)[1] if authority_path.startswith("payload.") else ""
    authority = (
        payload.get(authority_key)
        if authority_key and isinstance(payload.get(authority_key), Mapping)
        else {}
    )
    values: list[str] = []
    lookup_keys = list(policy.get("lookup_key_fields") or [])
    for source in (body, payload, authority):
        values.extend(_runtime_context_service_query_values(source, *lookup_keys))
    return _runtime_context_service_dedupe(values)


def _contract_runtime_durable_merge_identity(
    line: Mapping[str, Any],
) -> dict[str, str]:
    empty = {
        "runtime_context_id": "",
        "task_id": "",
        "parent_task_id": "",
        "identity_status": "missing",
        "identity_source_line_id": "",
    }
    if str(line.get("line_id") or "").strip() != "observer_merge":
        return empty
    payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
    durable = (
        payload.get("durable_merge_authority")
        if isinstance(payload.get("durable_merge_authority"), Mapping)
        else {}
    )
    if not durable:
        return empty
    identity = {
        key: _contract_runtime_mapping_value(durable, key)
        for key in ("runtime_context_id", "task_id", "parent_task_id")
    }
    top_level_identity = {
        "runtime_context_id": _contract_runtime_mapping_value(
            line, "runtime_context_id"
        ),
        "task_id": _contract_runtime_mapping_value(line, "task_id", "worker_task_id"),
        "parent_task_id": _contract_runtime_mapping_value(
            line, "parent_task_id", "root_task_id"
        ),
    }
    valid = bool(
        str(durable.get("schema_version") or "")
        == _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
        and durable.get("server_derived") is True
        and durable.get("db_verified") is True
        and all(identity.values())
        and all(
            not value or value == identity[field]
            for field, value in top_level_identity.items()
        )
    )
    if not valid:
        return {
            **empty,
            "identity_status": "ambiguous",
            "identity_source_line_id": "observer_merge",
        }
    return {
        **identity,
        "identity_status": "resolved",
        "identity_source_line_id": "observer_merge",
    }


def _contract_runtime_server_line_identity(
    record: Mapping[str, Any],
) -> dict[str, str]:
    empty = {
        "runtime_context_id": "",
        "task_id": "",
        "parent_task_id": "",
        "identity_status": "missing",
        "identity_source_line_id": "",
    }
    sources = [
        ("next_legal_action", _contract_runtime_next_line(record)),
        *[
            (str(line.get("line_id") or "").strip(), line)
            for line in reversed(
                [
                    item
                    for item in record.get("completed_lines") or []
                    if isinstance(item, Mapping)
                ]
            )
        ],
    ]
    latest_merge = next(
        (
            line
            for line in reversed(record.get("completed_lines") or [])
            if isinstance(line, Mapping)
            and str(line.get("line_id") or "").strip() == "observer_merge"
        ),
        {},
    )
    durable_merge_identity = _contract_runtime_durable_merge_identity(latest_merge)
    for source_line_id, source in sources:
        if (
            source_line_id == "observer_close_ready"
            and str(source.get("actor_role") or "").strip() == "observer"
            and str(source.get("evidence_kind") or "").strip() == "close_ready"
        ):
            payload = (
                source.get("payload")
                if isinstance(source.get("payload"), Mapping)
                else {}
            )
            contract_execution_id = str(
                record.get("contract_execution_id") or ""
            ).strip()
            payload_runtime_context_id = _contract_runtime_mapping_value(
                payload, "runtime_context_id"
            )
            payload_worker_task_id = _contract_runtime_mapping_value(
                payload, "worker_task_id"
            )
            runtime_context_id = durable_merge_identity["runtime_context_id"]
            task_id = durable_merge_identity["task_id"]
            parent_task_id = durable_merge_identity["parent_task_id"]
            retained_contract_envelope = bool(
                durable_merge_identity["identity_status"] == "resolved"
                and contract_execution_id
                and _contract_runtime_mapping_value(source, "task_id")
                == contract_execution_id
                and payload_runtime_context_id == runtime_context_id
                and payload_worker_task_id == task_id
                and _contract_runtime_mapping_value(
                    source, "runtime_context_id"
                )
                in {"", runtime_context_id}
                and _contract_runtime_mapping_value(source, "worker_task_id")
                in {"", task_id}
                and _contract_runtime_mapping_value(payload, "task_id")
                in {"", task_id, contract_execution_id}
                and _contract_runtime_mapping_value(payload, "parent_task_id")
                in {"", parent_task_id}
            )
            if retained_contract_envelope:
                return {
                    **durable_merge_identity,
                    "identity_source_line_id": source_line_id,
                }
            return {
                **empty,
                "identity_status": "ambiguous",
                "identity_source_line_id": source_line_id,
            }
        if source_line_id == "observer_merge":
            merge_identity = _contract_runtime_durable_merge_identity(source)
            if merge_identity.get("identity_status") != "missing":
                # Accepted observer_merge lines retain their immutable raw
                # caller payload for audit/playback.  Identity projection,
                # however, is owned by the durable server authority.  Ignore
                # conflicting caller-shaped duplicate fields inside payload;
                # the canonical top level and durable authority still have to
                # agree, and all later queue/timeline joins remain mandatory.
                return merge_identity
        identities: dict[tuple[str, str, str], dict[str, str]] = {}
        for candidate in _contract_runtime_mapping_candidates(source):
            runtime_context_id = _contract_runtime_mapping_value(
                candidate,
                "runtime_context_id",
            )
            task_id = _contract_runtime_mapping_value(
                candidate,
                "task_id",
                "worker_task_id",
            )
            if not runtime_context_id or not task_id:
                continue
            parent_task_id = _contract_runtime_mapping_value(
                candidate,
                "parent_task_id",
                "root_task_id",
            )
            identity = {
                "runtime_context_id": runtime_context_id,
                "task_id": task_id,
                "parent_task_id": parent_task_id,
            }
            identities[
                (runtime_context_id, task_id, parent_task_id)
            ] = identity
        if not identities:
            continue

        worker_scopes = {
            (identity["runtime_context_id"], identity["task_id"])
            for identity in identities.values()
        }
        parent_scopes = {
            identity["parent_task_id"]
            for identity in identities.values()
            if identity["parent_task_id"]
        }
        if len(worker_scopes) != 1 or len(parent_scopes) > 1:
            return {
                **empty,
                "identity_status": "ambiguous",
                "identity_source_line_id": source_line_id,
            }

        # Prefer the candidate that carries the parent scope, but never fill
        # missing identity fields from a different mapping or completed line.
        coherent = max(
            identities.values(),
            key=lambda identity: bool(identity["parent_task_id"]),
        )
        return {
            **coherent,
            "identity_status": "resolved",
            "identity_source_line_id": source_line_id,
        }
    return empty


def _contract_runtime_assigned_target_project_root(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    identity: Mapping[str, str],
) -> dict[str, Any]:
    if identity.get("identity_status") == "ambiguous":
        return {
            "status": "ambiguous_identity",
            "target_project_root": "",
            "candidate_roots": [],
        }
    roots: set[str] = set()
    dispatch_line_ids = {
        "observer_dispatch_bounded_workers",
        "direct_fix_dispatch_context",
    }
    dispatch_lines = [
        line
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
        and str(line.get("line_id") or "").strip() in dispatch_line_ids
    ]
    for line in dispatch_lines:
        matched_runtime_context = False
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=line,
        ):
            runtime_context_id, task_id, _parent_task_id = (
                _contract_runtime_context_identity(context)
            )
            if identity.get("runtime_context_id") and (
                runtime_context_id != identity["runtime_context_id"]
            ):
                continue
            if identity.get("task_id") and task_id != identity["task_id"]:
                continue
            # QA executes the candidate graph query from the allocated worker
            # worktree.  Its canonical project root remains separate identity.
            target_root = str(
                getattr(context, "worktree_path", "") or ""
            ).strip()
            target_root = target_root or _runtime_context_effective_target_project_root(
                context
            )
            if target_root:
                roots.add(str(Path(target_root).resolve()))
                matched_runtime_context = True

        if matched_runtime_context:
            continue
        for candidate in _contract_runtime_mapping_candidates(line):
            candidate_runtime_context_id = _contract_runtime_mapping_value(
                candidate,
                "runtime_context_id",
            )
            candidate_task_id = _contract_runtime_mapping_value(
                candidate,
                "task_id",
                "worker_task_id",
            )
            identity_bound = False
            if identity.get("runtime_context_id"):
                if candidate_runtime_context_id != identity["runtime_context_id"]:
                    continue
                identity_bound = True
            if identity.get("task_id"):
                if candidate_task_id != identity["task_id"]:
                    continue
                identity_bound = True
            if not identity_bound:
                continue
            target_root = _contract_runtime_mapping_value(
                candidate,
                "worktree_path",
                "target_project_root",
            )
            if target_root:
                roots.add(str(Path(target_root).resolve()))

    if len(roots) == 1:
        return {
            "status": "resolved",
            "target_project_root": next(iter(roots)),
        }
    return {
        "status": "missing" if not roots else "ambiguous",
        "target_project_root": "",
        "candidate_roots": sorted(roots),
    }


def _contract_runtime_bind_qa_worker_identity_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    server_identity: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Bind a QA row to the one active worker context selected by dispatch."""

    expected = (
        dict(server_identity)
        if isinstance(server_identity, Mapping)
        else _contract_runtime_server_line_identity(record)
    )
    expected_runtime_context_id = str(
        expected.get("runtime_context_id") or ""
    ).strip()
    expected_task_id = str(expected.get("task_id") or "").strip()
    identities: dict[tuple[str, str], tuple[str, str, str]] = {}
    for line in record.get("completed_lines") or []:
        if not isinstance(line, Mapping) or str(
            line.get("line_id") or ""
        ).strip() not in {
            "observer_dispatch_bounded_workers",
            "direct_fix_dispatch_context",
        }:
            continue
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=line,
        ):
            identity = _contract_runtime_context_identity(context)
            runtime_context_id, task_id, parent_task_id = identity
            if (
                runtime_context_id != expected_runtime_context_id
                or task_id != expected_task_id
            ):
                continue
            if runtime_context_id and task_id and parent_task_id:
                identities[(runtime_context_id, task_id)] = identity

    if (
        expected.get("identity_status") != "resolved"
        or not expected_runtime_context_id
        or not expected_task_id
        or len(identities) != 1
    ):
        raise GovernanceError(
            "contract_runtime_qa_worker_identity_unresolved",
            (
                "independent QA requires one server-verified active "
                "runtime-context/task identity"
            ),
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "identity_status": str(
                    expected.get("identity_status") or "missing"
                ),
                "identity_source_line_id": str(
                    expected.get("identity_source_line_id") or ""
                ),
                "candidate_count": len(identities),
                "fail_closed": True,
            },
        )

    runtime_context_id, task_id, parent_task_id = next(iter(identities.values()))
    claimed_runtime_context_ids: set[str] = set()
    claimed_task_ids: set[str] = set()
    claimed_parent_task_ids: set[str] = set()
    for candidate in _contract_runtime_mapping_candidates(write):
        claimed_runtime_context_ids.update(
            _contract_runtime_mapping_values(candidate, "runtime_context_id")
        )
        claimed_task_ids.update(
            _contract_runtime_mapping_values(
                candidate,
                "task_id",
                "worker_task_id",
            )
        )
        claimed_parent_task_ids.update(
            _contract_runtime_mapping_values(
                candidate,
                "parent_task_id",
                "root_task_id",
            )
        )
    mismatches = []
    for field, claimed, canonical in (
        (
            "runtime_context_id",
            claimed_runtime_context_ids,
            runtime_context_id,
        ),
        ("task_id", claimed_task_ids, task_id),
        ("parent_task_id", claimed_parent_task_ids, parent_task_id),
    ):
        wrong = sorted(value for value in claimed if value != canonical)
        if wrong:
            mismatches.append(
                {
                    "field": field,
                    "expected": canonical,
                    "actual": wrong,
                }
            )
    if mismatches:
        raise GovernanceError(
            "contract_runtime_qa_worker_identity_mismatch",
            (
                "independent QA runtime-context/task claims do not match "
                "the server-verified active worker"
            ),
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "identity_mismatches": mismatches,
                "fail_closed": True,
            },
        )

    effective = dict(write)
    effective.update(
        {
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
        }
    )
    payload = (
        dict(effective.get("payload"))
        if isinstance(effective.get("payload"), Mapping)
        else {}
    )
    payload.update(
        {
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
        }
    )
    effective["payload"] = payload
    return effective


def _contract_runtime_postmerge_qa_worker_identity_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Resolve the final worker lane from one frozen postmerge QA ticket.

    A postmerge ``qa_graph_context`` deliberately carries two scopes: its
    canonical worker identity remains the final merged lane, while its graph
    query task is the combined ContractRuntime execution.  Deep-scanning that
    line therefore produces an ambiguous worker identity.  Consume only the
    newest accepted, server-derived ticket and rejoin its final-lane identity
    to exactly one durable dispatch RuntimeContext.
    """

    def blocked(*codes: str) -> dict[str, Any]:
        return {
            "schema_version": (
                "contract_runtime.postmerge_qa_worker_identity_authority.v1"
            ),
            "status": "blocked",
            "verified": False,
            "server_derived": True,
            "fail_closed": True,
            "blocker_codes": list(codes) or [
                "persisted_postmerge_qa_worker_identity_unverified"
            ],
        }

    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(record.get("backlog_id") or "").strip()
    if not (
        _is_mf_parallel_postmerge_revision(record)
        and project_id
        and execution_id
        and backlog_id
    ):
        return blocked("postmerge_qa_contract_scope_invalid")

    latest_line: Mapping[str, Any] = {}
    for line in reversed(record.get("completed_lines") or []):
        if isinstance(line, Mapping) and str(
            line.get("line_id") or ""
        ).strip() == "qa_graph_context":
            latest_line = line
            break
    if not latest_line:
        return blocked("persisted_postmerge_qa_graph_context_missing")

    payload = (
        latest_line.get("payload")
        if isinstance(latest_line.get("payload"), Mapping)
        else {}
    )
    evidence = (
        payload.get("graph_trace_evidence")
        if isinstance(payload.get("graph_trace_evidence"), Mapping)
        else {}
    )
    raw_ticket = (
        evidence.get("postmerge_qa_authority")
        if isinstance(evidence.get("postmerge_qa_authority"), Mapping)
        else {}
    )
    ticket = _contract_runtime_persisted_postmerge_qa_authority(record)
    if ticket.get("verified") is not True:
        return blocked(
            *(
                str(code)
                for code in ticket.get("blocker_codes") or [
                    "persisted_postmerge_qa_authority_missing"
                ]
            )
        )

    runtime_context_id = str(
        ticket.get("runtime_context_id") or ""
    ).strip()
    task_id = str(ticket.get("task_id") or "").strip()
    parent_task_id = str(ticket.get("parent_task_id") or "").strip()
    graph_task_id = str(ticket.get("qa_graph_trace_task_id") or "").strip()
    candidate_commit = str(
        ticket.get("candidate_commit_sha") or ""
    ).strip().lower()
    ticket_source = str(ticket.get("source") or "").strip()
    ticket_hash = str(ticket.get("authority_hash") or "").strip()
    ticket_unsigned = {
        key: value for key, value in ticket.items() if key != "authority_hash"
    }
    line_candidate_commit = str(
        latest_line.get("commit_sha") or ""
    ).strip().lower()
    evidence_candidate_commit = str(
        evidence.get("candidate_commit_sha") or ""
    ).strip().lower()
    identity_checks = bool(
        str(ticket.get("schema_version") or "")
        == "contract_runtime.rev8_postmerge_qa_authority.v1"
        and str(ticket.get("status") or "") == "verified"
        and ticket.get("server_derived") is True
        and ticket.get("db_verified") is True
        and ticket.get("live_verified") is True
        and ticket.get("graph_reconciled") is True
        and ticket.get("active_snapshot_verified") is True
        and str(ticket.get("project_id") or "").strip() == project_id
        and str(ticket.get("backlog_id") or "").strip() == backlog_id
        and str(ticket.get("contract_execution_id") or "").strip()
        == execution_id
        and parent_task_id == execution_id
        and graph_task_id == execution_id
        and str(ticket.get("qa_graph_trace_task_source") or "").strip()
        == "ContractRuntime.contract_execution_id"
        and ticket_source.startswith("ContractRuntime.")
        and ticket_hash == stable_sha256(ticket_unsigned)
        and stable_sha256(raw_ticket) == stable_sha256(ticket)
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", candidate_commit)
        is not None
        and line_candidate_commit == candidate_commit
        and evidence_candidate_commit == candidate_commit
        and _contract_runtime_mapping_value(
            latest_line, "runtime_context_id"
        )
        == runtime_context_id
        and _contract_runtime_mapping_value(latest_line, "task_id")
        == graph_task_id
        and _contract_runtime_mapping_value(latest_line, "parent_task_id")
        == parent_task_id
        and _contract_runtime_mapping_value(evidence, "runtime_context_id")
        == runtime_context_id
        and _contract_runtime_mapping_value(evidence, "task_id")
        == graph_task_id
        and _contract_runtime_mapping_value(evidence, "parent_task_id")
        == parent_task_id
    )
    if not identity_checks:
        return blocked("persisted_postmerge_qa_worker_identity_mismatch")

    matching_contexts: list[tuple[str, str, str]] = []
    for line in record.get("completed_lines") or []:
        if not isinstance(line, Mapping) or str(
            line.get("line_id") or ""
        ).strip() not in {
            "observer_dispatch_bounded_workers",
            "direct_fix_dispatch_context",
        }:
            continue
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=line,
        ):
            identity = _contract_runtime_context_identity(context)
            if identity == (runtime_context_id, task_id, parent_task_id):
                matching_contexts.append(identity)
    if len(matching_contexts) != 1:
        return blocked("persisted_postmerge_qa_dispatch_identity_ambiguous")

    authority = {
        "schema_version": (
            "contract_runtime.postmerge_qa_worker_identity_authority.v1"
        ),
        "source": (
            "ContractRuntime.qa_graph_context.postmerge_qa_authority+"
            "observer_dispatch_bounded_workers"
        ),
        "status": "verified",
        "verified": True,
        "server_derived": True,
        "db_verified": True,
        "fail_closed": True,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "qa_graph_trace_task_id": graph_task_id,
        "qa_graph_trace_task_source": (
            "ContractRuntime.contract_execution_id"
        ),
        "candidate_commit_sha": candidate_commit,
        "postmerge_qa_authority_hash": ticket_hash,
        "identity_status": "resolved",
        "identity_source_line_id": (
            "qa_graph_context.postmerge_qa_authority"
        ),
        "candidate_count": 1,
        "blocker_codes": [],
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _contract_runtime_worker_implementation_bypass_continuation_anchor(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    completed: Sequence[Mapping[str, Any]],
    persisted_worker_commit_line: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Join one audited implementation bypass to its current worker lane.

    The bypass is not implementation PASS evidence.  It is only a durable,
    no-PASS predecessor anchor that lets the server inspect the exact assigned
    worktree before deciding whether the current worker_commit line may itself
    be bypassed.  No request identity participates in lane selection.
    """

    if conn is None:
        return {}
    from .parallel_branch_runtime import (
        ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES,
        MERGE_READY_INPUT_STATES,
        runtime_context_fence_token_verifier,
    )

    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(record.get("backlog_id") or "").strip()
    next_line = _contract_runtime_next_line(record)
    persisted_line = (
        persisted_worker_commit_line
        if isinstance(persisted_worker_commit_line, Mapping)
        else {}
    )
    persisted_payload = (
        persisted_line.get("payload")
        if isinstance(persisted_line.get("payload"), Mapping)
        else {}
    )
    persisted_continuation = (
        persisted_payload.get("continuation_authority")
        if isinstance(
            persisted_payload.get("continuation_authority"), Mapping
        )
        else {}
    )

    def exact_claim(value: Mapping[str, Any], field: str) -> str:
        claims = {
            str(candidate.get(field) or "").strip()
            for candidate in _contract_runtime_mapping_candidates(value)
            if str(candidate.get(field) or "").strip()
        }
        return next(iter(claims)) if len(claims) == 1 else ""

    identity_source = persisted_line or next_line
    runtime_context_id = exact_claim(identity_source, "runtime_context_id")
    task_id = exact_claim(identity_source, "task_id")
    lane_id = exact_claim(
        persisted_continuation if persisted_line else next_line,
        "lane_id",
    )
    line_instance_id = exact_claim(identity_source, "line_instance_id")
    pre_write_line_valid = bool(
        not persisted_line
        and str(next_line.get("stage_id") or "").strip() == "worker_commit"
        and str(next_line.get("line_id") or "").strip() == "worker_commit"
        and str(next_line.get("evidence_kind") or "").strip()
        == "worker_commit"
        and str(next_line.get("owner_role") or "").strip() == "mf_sub"
    )
    persisted_line_valid = bool(
        persisted_line
        and str(persisted_line.get("stage_id") or "").strip()
        == "worker_commit"
        and str(persisted_line.get("line_id") or "").strip()
        == "worker_commit"
        and str(persisted_line.get("evidence_kind") or "").strip()
        == "contract_line_bypass"
        and str(persisted_line.get("actor_role") or "").strip()
        in {"observer", "qa"}
        and str(persisted_line.get("status") or "").strip().lower()
        == "waived"
        and persisted_line.get("no_pass_claim") is True
        and str(persisted_payload.get("schema_version") or "").strip()
        == "contract_line_bypass.v1"
        and persisted_payload.get("no_pass_claim") is True
        and str(
            persisted_payload.get("blocked_evidence_kind") or ""
        ).strip()
        == "worker_commit"
        and str(persisted_payload.get("blocked_owner_role") or "").strip()
        == "mf_sub"
        and str(persisted_continuation.get("schema_version") or "").strip()
        == "contract_runtime.worker_commit_bypass_continuation.v2"
        and persisted_continuation.get("no_pass_claim") is True
        and persisted_continuation.get("authoritative_pass_synthesized")
        is False
        and persisted_continuation.get("implementation_pass_claimed")
        is False
    )
    if not (
        execution_id
        and backlog_id
        and str(record.get("project_id") or "").strip() == project_id
        and str(record.get("contract_id") or "").strip()
        == MF_PARALLEL_CONTRACT_ID
        and not _runtime_record_is_complete(record)
        and (pre_write_line_valid or persisted_line_valid)
        and runtime_context_id
        and task_id
        and lane_id
        and line_instance_id == f"runtime_context:{runtime_context_id}"
    ):
        return {}

    current_projection = (
        _contract_runtime_raw_current_chain_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
        if persisted_line
        else _contract_chain_current_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            rebuild_if_missing=False,
        )
    )
    active_chain = (
        current_projection.get("active_chain")
        if isinstance(current_projection.get("active_chain"), Mapping)
        else {}
    )
    active_execution_ids = {
        str(value or "").strip()
        for value in active_chain.get("execution_ids") or []
        if str(value or "").strip()
    }
    projected_next_line = (
        current_projection.get("next_legal_action")
        if isinstance(current_projection.get("next_legal_action"), Mapping)
        else {}
    )
    if not (
        current_projection
        and not bool(current_projection.get("degraded"))
        and str(current_projection.get("projection_source") or "").strip()
        == "backlog_contract_chain_current"
        and str(current_projection.get("source_of_proof") or "").strip()
        == "contract_runtime_executions.completed_lines"
        and str(current_projection.get("project_id") or "").strip()
        == project_id
        and str(current_projection.get("backlog_id") or "").strip()
        == backlog_id
        and str(current_projection.get("readiness_state") or "").strip()
        == "contract_active"
        and str(
            current_projection.get("current_contract_execution_id") or ""
        ).strip()
        == execution_id
        and str(
            current_projection.get("active_child_contract_execution_id")
            or ""
        ).strip()
        == execution_id
        and execution_id in active_execution_ids
        and (
            (
                str(projected_next_line.get("line_id") or "").strip()
                == "worker_commit"
                and str(
                    projected_next_line.get("stage_id") or ""
                ).strip()
                == "worker_commit"
            )
            if not persisted_line
            else str(projected_next_line.get("line_id") or "").strip()
            != "worker_commit"
        )
    ):
        return {}

    matching_bypasses: list[tuple[int, Mapping[str, Any], Mapping[str, Any]]] = []
    for index, line in enumerate(completed):
        if not isinstance(line, Mapping):
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        if not (
            str(line.get("stage_id") or "").strip()
            == "worker_implementation"
            and str(line.get("line_id") or "").strip()
            == "worker_implementation"
            and str(line.get("evidence_kind") or "").strip()
            == "contract_line_bypass"
            and str(line.get("actor_role") or "").strip()
            in {"observer", "qa"}
            and str(line.get("status") or "").strip().lower() == "waived"
            and line.get("no_pass_claim") is True
            and str(payload.get("schema_version") or "").strip()
            == "contract_line_bypass.v1"
            and payload.get("no_pass_claim") is True
            and str(payload.get("blocked_evidence_kind") or "").strip()
            == "implementation"
            and str(payload.get("blocked_owner_role") or "").strip()
            == "mf_sub"
            and exact_claim(line, "line_instance_id") == line_instance_id
        ):
            continue
        claimed_execution_ids = {
            str(candidate.get(key) or "").strip()
            for candidate in _contract_runtime_mapping_candidates(line)
            for key in (
                "contract_execution_id",
                "successor_contract_execution_id",
            )
            if str(candidate.get(key) or "").strip()
        }
        if claimed_execution_ids and claimed_execution_ids != {execution_id}:
            continue
        matching_bypasses.append((index, line, payload))
    if len(matching_bypasses) != 1:
        return {}
    bypass_index, bypass_line, _ = matching_bypasses[0]
    implementation_bypass_audit = (
        _contract_runtime_strict_no_pass_bypass_audit(
            conn,
            project_id=project_id,
            record=record,
            line=bypass_line,
            expected_line_id="worker_implementation",
            expected_blocked_evidence_kind="implementation",
            expected_event_task_ids={execution_id, task_id},
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            line_instance_id=line_instance_id,
        )
    )
    if not implementation_bypass_audit:
        return {}

    matching_contexts: list[Any] = []
    matching_dispatch_indexes: list[int] = []
    for dispatch_index, dispatch in enumerate(completed[:bypass_index]):
        if str(dispatch.get("line_id") or "").strip() != (
            "observer_dispatch_bounded_workers"
        ):
            continue
        dispatch_matched = False
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=dispatch,
        ):
            context_identity = _contract_runtime_context_identity(context)
            if context_identity[:2] != (runtime_context_id, task_id):
                continue
            matching_contexts.append(context)
            dispatch_matched = True
        if dispatch_matched:
            matching_dispatch_indexes.append(dispatch_index)
    if len(matching_contexts) != 1 or len(matching_dispatch_indexes) != 1:
        return {}
    context = matching_contexts[0]
    context_parent_task_id = _contract_runtime_context_identity(context)[2]
    context_lane_id = str(
        getattr(context, "worker_slot_id", "")
        or getattr(context, "worker_id", "")
        or ""
    ).strip()
    allowed_context_states = set(ACTIVE_MF_SUBAGENT_GRAPH_QUERY_STATES)
    if persisted_line:
        allowed_context_states.update(MERGE_READY_INPUT_STATES)
    if not (
        context_lane_id == lane_id
        and str(getattr(context, "status", "") or "").strip()
        in allowed_context_states
        and str(getattr(context, "backlog_id", "") or backlog_id).strip()
        == backlog_id
        and runtime_context_fence_token_verifier(context)
    ):
        return {}
    expected_optional_claims = {
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": context_parent_task_id,
        "lane_id": lane_id,
    }
    for field, expected in expected_optional_claims.items():
        claims = {
            str(candidate.get(field) or "").strip()
            for candidate in _contract_runtime_mapping_candidates(bypass_line)
            if str(candidate.get(field) or "").strip()
        }
        if claims and claims != {expected}:
            return {}
    return {
        "schema_version": (
            "contract_runtime.worker_implementation_bypass_continuation_anchor.v1"
        ),
        "server_derived": True,
        "db_verified": True,
        "no_pass_claim": True,
        "authoritative_pass_synthesized": False,
        "contract_execution_id": execution_id,
        "backlog_id": backlog_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": context_parent_task_id,
        "lane_id": lane_id,
        "line_instance_id": line_instance_id,
        "implementation_bypass_diagnostic_id": (
            implementation_bypass_audit["diagnostic_backlog_id"]
        ),
        "implementation_bypass_source_event_ref": (
            implementation_bypass_audit["source_event_ref"]
        ),
        "implementation_bypass_diagnostic_event_ref": (
            implementation_bypass_audit["diagnostic_event_ref"]
        ),
        "context": context,
    }


def _contract_runtime_strict_no_pass_bypass_audit(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    line: Mapping[str, Any],
    expected_line_id: str,
    expected_stage_id: str = "",
    expected_blocked_evidence_kind: str,
    expected_event_task_ids: set[str],
    runtime_context_id: str,
    task_id: str,
    line_instance_id: str,
    expected_actor_roles: set[str] | None = None,
    expected_blocked_owner_role: str = "mf_sub",
    line_instance_required: bool = True,
) -> dict[str, Any]:
    """Revalidate one exact no-PASS line, OPEN diagnostic, and audit pair."""

    if conn is None:
        return {}
    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(record.get("backlog_id") or "").strip()
    payload = (
        line.get("payload")
        if isinstance(line.get("payload"), Mapping)
        else {}
    )
    diagnostic_id = str(payload.get("diagnostic_backlog_id") or "").strip()
    bypass_identity = str(payload.get("bypass_identity") or "").strip()
    classification = str(payload.get("classification") or "").strip()
    actor_role = str(line.get("actor_role") or "").strip()
    line_instance_claims = {
        str(candidate.get("line_instance_id") or "").strip()
        for candidate in _contract_runtime_mapping_candidates(line)
        if str(candidate.get("line_instance_id") or "").strip()
    }
    execution_claims = {
        str(candidate.get(key) or "").strip()
        for candidate in _contract_runtime_mapping_candidates(line)
        for key in ("contract_execution_id", "successor_contract_execution_id")
        if str(candidate.get(key) or "").strip()
    }
    try:
        bypass_revision = int(payload.get("execution_state_revision") or 0)
    except (TypeError, ValueError):
        return {}
    accepted_actor_roles = (
        set(expected_actor_roles)
        if expected_actor_roles is not None
        else {"observer", "qa"}
    )
    expected_line_instance_claims = (
        {line_instance_id} if line_instance_id else set()
    )
    if not (
        execution_id
        and backlog_id
        and diagnostic_id
        and bypass_identity
        and classification
        and bypass_revision > 0
        and (not line_instance_required or bool(line_instance_id))
        and line_instance_claims == expected_line_instance_claims
        and (not execution_claims or execution_claims == {execution_id})
        and actor_role in accepted_actor_roles
        and str(line.get("stage_id") or "").strip()
        == str(expected_stage_id or expected_line_id).strip()
        and str(line.get("line_id") or "").strip() == expected_line_id
        and str(line.get("evidence_kind") or "").strip()
        == "contract_line_bypass"
        and str(line.get("status") or "").strip().lower() == "waived"
        and line.get("no_pass_claim") is True
        and str(payload.get("schema_version") or "").strip()
        == "contract_line_bypass.v1"
        and str(payload.get("source_backlog_id") or "").strip()
        == backlog_id
        and str(payload.get("blocked_owner_role") or "").strip()
        == str(expected_blocked_owner_role or "").strip()
        and str(payload.get("blocked_evidence_kind") or "").strip()
        == expected_blocked_evidence_kind
        and str(payload.get("disposition") or "").strip()
        == "proceeded_with_exception"
        and payload.get("no_pass_claim") is True
    ):
        return {}
    diagnostic_binding = {
        "source_backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "line_id": expected_line_id,
        "execution_state_revision": bypass_revision,
        "bypass_identity": bypass_identity,
        "classification": classification,
        "disposition": "proceeded_with_exception",
        "no_pass_claim": True,
    }
    generation_link = (
        payload.get("no_pass_generation")
        if isinstance(payload.get("no_pass_generation"), Mapping)
        else {}
    )
    inherited_generation = bool(
        str(generation_link.get("role") or "").strip() == "inherited_gate"
    )
    if inherited_generation:
        active_generation = _contract_runtime_no_pass_generation(record)
        if not (
            active_generation.get("root_generation_persisted") is True
            and str(generation_link.get("generation_id") or "").strip()
            == str(active_generation.get("generation_id") or "").strip()
            and str(
                generation_link.get("root_bypass_identity") or ""
            ).strip()
            == str(
                active_generation.get("root_bypass_identity") or ""
            ).strip()
            and str(
                generation_link.get("root_diagnostic_backlog_id") or ""
            ).strip()
            == diagnostic_id
            == str(
                active_generation.get("root_diagnostic_backlog_id") or ""
            ).strip()
            and str(generation_link.get("root_line_id") or "").strip()
            == str(active_generation.get("root_line_id") or "").strip()
            and generation_link.get("diagnostic_created") is False
            and generation_link.get("no_pass_claim") is True
            and generation_link.get("authoritative_pass_synthesized") is False
        ):
            return {}
        diagnostic_binding.update(
            {
                "line_id": str(
                    active_generation.get("root_line_id") or ""
                ).strip(),
                "execution_state_revision": int(
                    active_generation.get("root_execution_state_revision")
                    or 0
                ),
                "bypass_identity": str(
                    active_generation.get("root_bypass_identity") or ""
                ).strip(),
                "classification": str(
                    active_generation.get("root_classification") or ""
                ).strip(),
            }
        )
    try:
        diagnostic = conn.execute(
            "SELECT status, mf_type, chain_trigger_json, bypass_policy_json "
            "FROM backlog_bugs WHERE bug_id = ?",
            (diagnostic_id,),
        ).fetchone()
    except sqlite3.Error:
        return {}
    if not diagnostic:
        return {}
    chain = backlog_runtime.parse_json_object(
        diagnostic["chain_trigger_json"]
    )
    policy = backlog_runtime.parse_json_object(
        diagnostic["bypass_policy_json"]
    )
    if not (
        str(diagnostic["status"] or "").strip().upper() == "OPEN"
        and str(diagnostic["mf_type"] or "").strip() == "chain_rescue"
        and all(
            chain.get(key) == value
            for key, value in diagnostic_binding.items()
        )
        and all(
            policy.get(key) == value
            for key, value in diagnostic_binding.items()
        )
        and policy.get("keep_open") is True
    ):
        return {}

    correlation_id = f"contract-line-bypass:{bypass_identity}"
    source_events = [
        event
        for event in _runtime_context_service_timeline_events(
            conn,
            project_id=project_id,
            task_id="",
            backlog_id=backlog_id,
        )
        if str(event.get("event_type") or "").strip()
        == "contract_line_bypass"
        and str(event.get("correlation_id") or "").strip()
        == correlation_id
    ]
    diagnostic_events = [
        event
        for event in _runtime_context_service_timeline_events(
            conn,
            project_id=project_id,
            task_id="",
            backlog_id=diagnostic_id,
        )
        if str(event.get("event_type") or "").strip()
        == "contract_line_bypass_diagnostic_linked"
        and str(event.get("correlation_id") or "").strip()
        == correlation_id
    ]
    if len(source_events) != 1 or len(diagnostic_events) != 1:
        return {}

    def event_binding(event: Mapping[str, Any]) -> tuple[Any, ...]:
        event_payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        return (
            str(event.get("event_kind") or "").strip(),
            str(event.get("actor") or "").strip(),
            str(event.get("status") or "").strip(),
            str(event.get("decision") or "").strip(),
            str(event_payload.get("source_backlog_id") or "").strip(),
            str(
                event_payload.get("contract_execution_id") or ""
            ).strip(),
            str(event_payload.get("line_id") or "").strip(),
            str(
                event_payload.get("diagnostic_backlog_id") or ""
            ).strip(),
            str(event_payload.get("bypass_identity") or "").strip(),
            str(event_payload.get("classification") or "").strip(),
            str(event_payload.get("disposition") or "").strip(),
            event_payload.get("no_pass_claim"),
        )

    expected_source = (
        "record_blocker",
        actor_role,
        "proceeded_with_exception",
        (
            "inherited_root_diagnostic_no_pass"
            if inherited_generation
            else "linked_open_diagnostic_no_pass"
        ),
        backlog_id,
        execution_id,
        expected_line_id,
        diagnostic_id,
        bypass_identity,
        classification,
        "proceeded_with_exception",
        True,
    )
    expected_diagnostic = list(expected_source)
    expected_diagnostic[2] = "open"
    expected_diagnostic[3] = (
        "record_inherited_gate_reason_keep_root_open"
        if inherited_generation
        else "keep_open_until_block_repaired"
    )
    source_event = source_events[0]
    diagnostic_event = diagnostic_events[0]
    source_event_id = _contract_runtime_projection_timeline_event_id(
        source_event
    )
    diagnostic_event_id = _contract_runtime_projection_timeline_event_id(
        diagnostic_event
    )
    event_task_ids = {
        str(source_event.get("task_id") or "").strip(),
        str(diagnostic_event.get("task_id") or "").strip(),
    }
    if not (
        event_binding(source_event) == expected_source
        and event_binding(diagnostic_event) == tuple(expected_diagnostic)
        and len(event_task_ids) == 1
        and event_task_ids.issubset(expected_event_task_ids)
        and 0 < source_event_id < diagnostic_event_id
    ):
        return {}
    for event in (source_event, diagnostic_event):
        event_payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        for field, expected in {
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "line_instance_id": line_instance_id,
        }.items():
            claims = {
                str(candidate.get(field) or "").strip()
                for candidate in _contract_runtime_mapping_candidates(
                    event_payload
                )
                if str(candidate.get(field) or "").strip()
            }
            if claims and claims != {expected}:
                return {}
    return {
        "schema_version": (
            "contract_runtime.strict_no_pass_bypass_audit.v1"
        ),
        "server_derived": True,
        "db_verified": True,
        "no_pass_claim": True,
        "authoritative_pass_synthesized": False,
        "line_id": expected_line_id,
        "diagnostic_backlog_id": diagnostic_id,
        "source_event_ref": _runtime_context_event_ref(source_event),
        "diagnostic_event_ref": _runtime_context_event_ref(
            diagnostic_event
        ),
    }


def _contract_runtime_pinned_current_full_provenance(
    conn,
    *,
    project_id: str,
    snapshot_id: str,
    commit_sha: str,
    backlog_id: str,
    contract_execution_id: str,
    persisted: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Pin one protected current-full activation for later readback."""

    snapshot_id = str(snapshot_id or "").strip()
    commit_sha = str(commit_sha or "").strip().lower()
    backlog_id = str(backlog_id or "").strip()
    contract_execution_id = str(contract_execution_id or "").strip()
    if not (
        conn is not None
        and snapshot_id
        and backlog_id
        and contract_execution_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", commit_sha)
    ):
        return {}
    from . import graph_snapshot_store

    persisted_value = persisted if isinstance(persisted, Mapping) else {}
    persisted_source = str(persisted_value.get("source") or "").strip()
    if persisted_value and persisted_source == "protected_current_full_reconcile":
        provenance_id = str(
            persisted_value.get("provenance_id") or ""
        ).strip()
        provenance_hash = str(
            persisted_value.get("provenance_hash") or ""
        ).strip()
        try:
            rows = conn.execute(
                "SELECT provenance_id, snapshot_id, target_commit_sha, "
                "provenance_hash, reconcile_event_id, marker_json "
                "FROM graph_current_full_reconcile_provenance "
                "WHERE provenance_id = ? AND project_id = ? "
                "AND snapshot_id = ? AND target_commit_sha = ?",
                (
                    provenance_id,
                    project_id,
                    snapshot_id,
                    commit_sha,
                ),
            ).fetchall()
        except sqlite3.Error:
            return {}
        if len(rows) != 1:
            return {}
        row = rows[0]
        try:
            marker = json.loads(str(row["marker_json"] or "{}"))
        except (TypeError, ValueError, json.JSONDecodeError):
            return {}
        marker_core = dict(marker) if isinstance(marker, Mapping) else {}
        marker_hash = str(
            marker_core.pop("provenance_hash", "") or ""
        ).strip()
        if not (
            provenance_id
            and provenance_hash
            and provenance_hash
            == str(row["provenance_hash"] or "").strip()
            == marker_hash
            == stable_sha256(marker_core)
            and str(marker.get("schema_version") or "").strip()
            == "current_full_reconcile.provenance.v2"
            and marker.get("normal_update_path") is True
            and marker.get("activate") is True
            and str(marker.get("protected_action") or "").strip()
            == "graph_current_full_reconcile"
            and str(marker.get("snapshot_id") or "").strip()
            == snapshot_id
            and str(marker.get("target_commit_sha") or "").strip().lower()
            == commit_sha
            and int(marker.get("reconcile_event_id") or 0)
            == int(row["reconcile_event_id"] or 0)
        ):
            return {}
        proof = {
            "schema_version": (
                "contract_runtime.pinned_current_full_provenance.v1"
            ),
            "verified": True,
            "server_derived": True,
            "source": "protected_current_full_reconcile",
            "snapshot_id": snapshot_id,
            "commit_sha": commit_sha,
            "provenance_id": provenance_id,
            "provenance_hash": provenance_hash,
            "reconcile_event_id": int(row["reconcile_event_id"] or 0),
        }
        return (
            proof
            if stable_sha256(persisted_value) == stable_sha256(proof)
            else {}
        )

    snapshot = (
        graph_snapshot_store.get_graph_snapshot(
            conn,
            project_id,
            snapshot_id,
        )
        or {}
    )
    if not (
        str(snapshot.get("snapshot_id") or "").strip() == snapshot_id
        and str(snapshot.get("commit_sha") or "").strip().lower()
        == commit_sha
        and str(snapshot.get("snapshot_kind") or "").strip() == "full"
        and (
            bool(persisted_value)
            or str(snapshot.get("status") or "").strip() == "active"
        )
    ):
        return {}
    binding = graph_snapshot_store._current_full_snapshot_provenance_binding(
        conn,
        project_id,
        snapshot,
    )
    if not (
        binding.get("verified") is True
        and str(binding.get("snapshot_id") or "").strip() == snapshot_id
        and str(binding.get("snapshot_commit") or "").strip().lower()
        == commit_sha
        and str(binding.get("provenance_target_commit") or "")
        .strip()
        .lower()
        == commit_sha
    ):
        try:
            notes = json.loads(str(snapshot.get("notes") or "{}"))
        except (TypeError, ValueError, json.JSONDecodeError):
            notes = {}
        anchor = (
            notes.get("full_reconcile_anchor")
            if isinstance(notes.get("full_reconcile_anchor"), Mapping)
            else {}
        )
        try:
            qa_event_id = int(notes.get("candidate_qa_event_id") or 0)
        except (TypeError, ValueError):
            qa_event_id = 0
        try:
            qa_rows = conn.execute(
                "SELECT id, backlog_id, task_id, event_type, event_kind, "
                "phase, actor, status, commit_sha FROM task_timeline_events "
                "WHERE id = ? AND project_id = ?",
                (qa_event_id, project_id),
            ).fetchall()
        except sqlite3.Error:
            qa_rows = []
        qa_row = qa_rows[0] if len(qa_rows) == 1 else None
        operator_marker = {
            "backlog_id": str(notes.get("backlog_id") or "").strip(),
            "contract_execution_id": str(
                notes.get("contract_execution_id") or ""
            ).strip(),
            "candidate_qa_event_id": qa_event_id,
            "protected_route_failure_request_id": str(
                notes.get("protected_route_failure_request_id") or ""
            ).strip(),
            "recovery_scope": str(notes.get("recovery_scope") or "").strip(),
            "full_reconcile_anchor": dict(anchor),
            "no_pass_claim": notes.get("no_pass_claim"),
            "contract_reconcile_pass_synthesized": notes.get(
                "contract_reconcile_pass_synthesized"
            ),
        }
        operator_proof = {
            "schema_version": (
                "contract_runtime.pinned_current_full_provenance.v1"
            ),
            "verified": True,
            "server_derived": True,
            "source": "audited_operator_current_full_recovery",
            "snapshot_id": snapshot_id,
            "commit_sha": commit_sha,
            "provenance_id": f"operator-current-full:{snapshot_id}",
            "provenance_hash": stable_sha256(operator_marker),
            "reconcile_event_id": 0,
            "candidate_qa_event_id": qa_event_id,
            "protected_route_failure_request_id": operator_marker[
                "protected_route_failure_request_id"
            ],
        }
        if not (
            operator_marker["backlog_id"] == backlog_id
            and operator_marker["contract_execution_id"]
            == contract_execution_id
            and operator_marker["no_pass_claim"] is True
            and operator_marker["contract_reconcile_pass_synthesized"]
            is False
            and operator_marker["recovery_scope"]
            == "operator_exact_main_after_audited_two_lane_bypass_merge"
            and operator_marker["protected_route_failure_request_id"].startswith(
                "req-"
            )
            and str(anchor.get("project_id") or "").strip() == project_id
            and str(anchor.get("snapshot_id") or "").strip() == snapshot_id
            and str(anchor.get("anchor_commit") or "").strip().lower()
            == commit_sha
            and str(anchor.get("reconcile_mode") or "").strip() == "full"
            and qa_row is not None
            and str(qa_row["backlog_id"] or "").strip() == backlog_id
            and str(qa_row["task_id"] or "").strip()
            == contract_execution_id
            and str(qa_row["event_type"] or "").strip()
            == "qa.independent_verification"
            and str(qa_row["event_kind"] or "").strip()
            == "independent_verification"
            and str(qa_row["phase"] or "").strip() == "verification"
            and str(qa_row["actor"] or "").strip().startswith("qa:")
            and str(qa_row["status"] or "").strip().lower() == "passed"
            and str(qa_row["commit_sha"] or "").strip().lower()
            == commit_sha
        ):
            return {}
        if persisted_value and stable_sha256(persisted_value) != stable_sha256(
            operator_proof
        ):
            return {}
        return operator_proof
    proof = {
        "schema_version": (
            "contract_runtime.pinned_current_full_provenance.v1"
        ),
        "verified": True,
        "server_derived": True,
        "source": "protected_current_full_reconcile",
        "snapshot_id": snapshot_id,
        "commit_sha": commit_sha,
        "provenance_id": str(binding.get("provenance_id") or "").strip(),
        "provenance_hash": str(
            binding.get("provenance_hash") or ""
        ).strip(),
        "reconcile_event_id": int(
            binding.get("reconcile_event_id") or 0
        ),
    }
    if persisted_value and stable_sha256(persisted_value) != stable_sha256(
        proof
    ):
        return {}
    return proof


def _contract_runtime_canonical_owned_file_provenance(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    candidate_commit_sha: str,
    canonical_commit_sha: str,
    active_snapshot_id: str,
    owned_files: Sequence[str],
    repository_root: str,
    persisted: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Prove exact owned-blob equality at the pinned canonical commit."""

    candidate_commit = str(candidate_commit_sha or "").strip().lower()
    canonical_commit = str(canonical_commit_sha or "").strip().lower()
    active_snapshot_id = str(active_snapshot_id or "").strip()
    normalized_owned_files = sorted(
        {
            str(item or "").strip().replace("\\", "/")
            for item in owned_files
            if str(item or "").strip()
        }
    )
    if not (
        conn is not None
        and active_snapshot_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", candidate_commit)
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", canonical_commit)
        and normalized_owned_files
    ):
        return {}
    repository_root = str(repository_root or "").strip()
    if not repository_root:
        return {}
    root = Path(repository_root).resolve()
    if (
        _qa_post_merge_resolve_commit(root, candidate_commit)
        != candidate_commit
        or _qa_post_merge_resolve_commit(root, canonical_commit)
        != canonical_commit
    ):
        return {}

    def blob_oids(commit_sha: str) -> dict[str, str]:
        values: dict[str, str] = {}
        for path in normalized_owned_files:
            oid = _git_output(
                root,
                ["rev-parse", "--verify", f"{commit_sha}:{path}"],
                timeout=10,
            ).strip().lower()
            if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", oid):
                return {}
            values[path] = oid
        return values

    candidate_blobs = blob_oids(candidate_commit)
    if not candidate_blobs:
        return {}
    canonical_blobs = blob_oids(canonical_commit)
    if canonical_blobs != candidate_blobs:
        return {}
    persisted_value = persisted if isinstance(persisted, Mapping) else {}
    persisted_current_full = (
        persisted_value.get("current_full_provenance")
        if isinstance(
            persisted_value.get("current_full_provenance"),
            Mapping,
        )
        else None
    )
    current_full_provenance = (
        _contract_runtime_pinned_current_full_provenance(
            conn,
            project_id=project_id,
            snapshot_id=active_snapshot_id,
            commit_sha=canonical_commit,
            backlog_id=str(record.get("backlog_id") or "").strip(),
            contract_execution_id=str(
                record.get("contract_execution_id") or ""
            ).strip(),
            persisted=persisted_current_full,
        )
    )
    if not current_full_provenance:
        return {}

    proof = {
        "schema_version": (
            "contract_runtime.canonical_owned_file_provenance.v1"
        ),
        "verified": True,
        "server_derived": True,
        "source": "canonical_commit_owned_blob_match",
        "candidate_commit_sha": candidate_commit,
        "canonical_commit_sha": canonical_commit,
        "owned_files": normalized_owned_files,
        "blob_oids": candidate_blobs,
        "current_canonical_commit_contains_candidate_blobs": True,
        "current_full_provenance": current_full_provenance,
    }
    if isinstance(persisted, Mapping) and stable_sha256(persisted) != stable_sha256(
        proof
    ):
        return {}
    return proof


def _contract_runtime_worker_commit_graph_epoch_transition_authority(
    conn,
    *,
    project_id: str,
    context: Any,
    old_graph_trace_ids: Sequence[str],
    fresh_graph_trace_ids: Sequence[str],
    old_epoch_commit_candidates: Sequence[str] = (),
    persisted: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Verify an old implementation trace and one fresh active-epoch trace."""

    if conn is None:
        return {}
    old_ids = sorted(
        {
            str(item or "").strip()
            for item in old_graph_trace_ids
            if str(item or "").strip()
        }
    )
    fresh_ids = sorted(
        {
            str(item or "").strip()
            for item in fresh_graph_trace_ids
            if str(item or "").strip()
        }
    )
    if not old_ids or len(fresh_ids) != 1 or set(old_ids) & set(fresh_ids):
        return {}
    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    fence_token = str(getattr(context, "fence_token", "") or "").strip()
    if not all((runtime_context_id, task_id, parent_task_id, fence_token)):
        return {}

    persisted_value = persisted if isinstance(persisted, Mapping) else {}
    pinned_snapshot_id = str(
        persisted_value.get("active_snapshot_id") or ""
    ).strip()
    pinned_commit = str(
        persisted_value.get("active_graph_commit") or ""
    ).strip().lower()
    try:
        if pinned_snapshot_id and pinned_commit:
            snapshot = conn.execute(
                "SELECT snapshot_id, commit_sha FROM graph_snapshots "
                "WHERE project_id = ? AND snapshot_id = ?",
                (project_id, pinned_snapshot_id),
            ).fetchone()
            if not snapshot:
                return {}
            active_snapshot_id = str(snapshot["snapshot_id"] or "").strip()
            active_commit = str(snapshot["commit_sha"] or "").strip().lower()
        else:
            active = conn.execute(
                "SELECT r.snapshot_id, s.commit_sha "
                "FROM graph_snapshot_refs r "
                "JOIN graph_snapshots s ON s.project_id = r.project_id "
                " AND s.snapshot_id = r.snapshot_id "
                "WHERE r.project_id = ? AND r.ref_name = 'active'",
                (project_id,),
            ).fetchone()
            if not active:
                return {}
            active_snapshot_id = str(active["snapshot_id"] or "").strip()
            active_commit = str(active["commit_sha"] or "").strip().lower()
        trace_ids = [*old_ids, *fresh_ids]
        placeholders = ",".join("?" for _ in trace_ids)
        rows = conn.execute(
            f"""
            SELECT t.trace_id, t.snapshot_id, t.query_source,
                   t.query_purpose, t.parent_task_id, t.task_id,
                   t.runtime_context_id, t.worker_role, t.fence_token,
                   t.fence_token_hash,
                   t.status, t.route_id, t.route_context_hash,
                   t.prompt_contract_id, t.prompt_contract_hash,
                   t.visible_injection_manifest_hash, t.route_token_ref,
                   s.commit_sha AS snapshot_commit_sha
            FROM graph_query_traces t
            LEFT JOIN graph_snapshots s
              ON s.project_id = t.project_id
             AND s.snapshot_id = t.snapshot_id
            WHERE t.project_id = ? AND t.trace_id IN ({placeholders})
            """,
            (project_id, *trace_ids),
        ).fetchall()
    except sqlite3.Error:
        return {}
    if (
        not active_snapshot_id
        or not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", active_commit)
        or len(rows) != len(trace_ids)
    ):
        return {}
    rows_by_id = {
        str(row["trace_id"] or "").strip(): row for row in rows
    }
    if set(rows_by_id) != set(trace_ids):
        return {}

    identity_fields = (
        "query_source",
        "query_purpose",
        "parent_task_id",
        "task_id",
        "runtime_context_id",
        "worker_role",
        "fence_token_hash",
        "route_id",
        "route_context_hash",
        "prompt_contract_id",
        "prompt_contract_hash",
        "visible_injection_manifest_hash",
        "route_token_ref",
    )
    canonical_identity = {
        "query_source": "mf_subagent",
        "parent_task_id": parent_task_id,
        "task_id": task_id,
        "runtime_context_id": runtime_context_id,
        "worker_role": "mf_sub",
        "fence_token_hash": _graph_query_trace_fence_hash(
            {"fence_token": fence_token}
        ),
    }
    identity_anchor = rows_by_id[old_ids[0]]
    for trace_id in trace_ids:
        row = rows_by_id[trace_id]
        if str(row["status"] or "").strip().lower() != "complete":
            return {}
        if str(row["query_purpose"] or "").strip() not in {
            "subagent_context_build",
            "subagent_gate_validation",
        }:
            return {}
        for field, expected in canonical_identity.items():
            actual = (
                _graph_query_trace_fence_hash(row)
                if field == "fence_token_hash"
                else str(row[field] or "").strip()
            )
            if actual != expected:
                return {}
        for field in identity_fields:
            actual = (
                _graph_query_trace_fence_hash(row)
                if field == "fence_token_hash"
                else str(row[field] or "").strip()
            )
            anchor = (
                _graph_query_trace_fence_hash(identity_anchor)
                if field == "fence_token_hash"
                else str(identity_anchor[field] or "").strip()
            )
            if actual != anchor:
                return {}

    expected_old_commits = {
        str(getattr(context, field, "") or "").strip().lower()
        for field in ("target_head_commit", "base_commit")
        if str(getattr(context, field, "") or "").strip()
    }
    expected_old_commits.update(
        str(item or "").strip().lower()
        for item in old_epoch_commit_candidates
        if str(item or "").strip()
    )
    for trace_id in old_ids:
        row = rows_by_id[trace_id]
        snapshot_id = str(row["snapshot_id"] or "").strip()
        snapshot_commit = str(
            row["snapshot_commit_sha"] or ""
        ).strip().lower()
        if (
            not snapshot_id
            or snapshot_commit not in expected_old_commits
            or (
                snapshot_id == active_snapshot_id
                and snapshot_commit == active_commit
            )
        ):
            return {}
    fresh_row = rows_by_id[fresh_ids[0]]
    if not (
        str(fresh_row["snapshot_id"] or "").strip()
        == active_snapshot_id
        and str(fresh_row["snapshot_commit_sha"] or "").strip().lower()
        == active_commit
    ):
        return {}
    proof = {
        "schema_version": (
            "contract_runtime.worker_commit_graph_epoch_transition.v1"
        ),
        "server_derived": True,
        "db_verified": True,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "old_graph_trace_ids": old_ids,
        "fresh_graph_trace_ids": fresh_ids,
        "old_graph_trace_current": False,
        "fresh_graph_trace_current_at_authorization": True,
        "active_snapshot_id": active_snapshot_id,
        "active_graph_commit": active_commit,
    }
    if isinstance(persisted, Mapping) and stable_sha256(persisted) != stable_sha256(
        proof
    ):
        return {}
    return proof


def _contract_runtime_raw_current_chain_authority(
    conn,
    *,
    project_id: str,
    backlog_id: str,
) -> dict[str, Any]:
    """Read and hash-check the durable current-chain row without projection.

    Persisted worker-commit bypass evidence is itself consulted while the
    runtime-freshness overlay derives a candidate commit.  Re-entering that
    overlay from the bypass validator would recurse.  This reader deliberately
    performs one raw SELECT and reconstructs the exact persisted hash payload;
    it never rebuilds or refreshes the projection.
    """

    columns = (
        "project_id",
        "backlog_id",
        "contract_chain_id",
        "root_contract_execution_id",
        "current_contract_execution_id",
        "current_contract_id",
        "parent_to_resume_contract_execution_id",
        "active_child_contract_execution_id",
        "readiness_state",
        "generation",
        "projection_watermark",
        "projection_hash",
        "active_chain_json",
        "next_legal_action_json",
        "degraded_flags_json",
        "source_refs_json",
        "updated_at",
    )
    try:
        row = conn.execute(
            "SELECT " + ", ".join(columns) + " "
            "FROM backlog_contract_chain_current "
            "WHERE project_id = ? AND backlog_id = ?",
            (project_id, backlog_id),
        ).fetchone()
    except sqlite3.Error:
        return {}
    if row is None:
        return {}
    if isinstance(row, sqlite3.Row):
        data = dict(row)
    else:
        try:
            data = dict(zip(columns, row, strict=True))
        except (TypeError, ValueError):
            return {}

    def json_field(name: str, expected_type: type) -> Any:
        try:
            value = json.loads(str(data.get(name) or ""))
        except (TypeError, ValueError, json.JSONDecodeError):
            return None
        return value if isinstance(value, expected_type) else None

    active_chain = json_field("active_chain_json", dict)
    next_legal_action = json_field("next_legal_action_json", dict)
    degraded_flags = json_field("degraded_flags_json", dict)
    source_refs = json_field("source_refs_json", list)
    if any(
        value is None
        for value in (
            active_chain,
            next_legal_action,
            degraded_flags,
            source_refs,
        )
    ):
        return {}
    projection = {
        "schema_version": "backlog_contract_chain_current.v1",
        "project_id": str(data.get("project_id") or ""),
        "backlog_id": str(data.get("backlog_id") or ""),
        "contract_chain_id": str(data.get("contract_chain_id") or ""),
        "root_contract_execution_id": str(
            data.get("root_contract_execution_id") or ""
        ),
        "current_contract_execution_id": str(
            data.get("current_contract_execution_id") or ""
        ),
        "current_contract_id": str(data.get("current_contract_id") or ""),
        "parent_to_resume_contract_execution_id": str(
            data.get("parent_to_resume_contract_execution_id") or ""
        ),
        "active_child_contract_execution_id": str(
            data.get("active_child_contract_execution_id") or ""
        ),
        "readiness_state": str(data.get("readiness_state") or ""),
        "generation": int(data.get("generation") or 0),
        "projection_watermark": int(
            data.get("projection_watermark") or 0
        ),
        "projection_hash": str(data.get("projection_hash") or ""),
        "active_chain": active_chain,
        "next_legal_action": next_legal_action,
        "degraded_flags": degraded_flags,
        "source_refs": source_refs,
        "source_of_proof": "contract_runtime_executions.completed_lines",
        "updated_at": str(data.get("updated_at") or ""),
    }
    if not (
        projection["project_id"] == project_id
        and projection["backlog_id"] == backlog_id
        and projection["projection_hash"]
        and projection["projection_hash"]
        == contract_chain_projection_hash(projection)
    ):
        return {}
    projection["degraded"] = bool(degraded_flags)
    projection["projection_source"] = "backlog_contract_chain_current"
    return projection


def _contract_runtime_inherited_no_pass_continuation(
    record: Mapping[str, Any],
    *,
    before_completed_line_index: int,
) -> dict[str, Any]:
    """Project the existing modern no-PASS root without minting new custody."""

    generation = _contract_runtime_no_pass_generation(record)
    try:
        root_index = int(generation.get("root_completed_line_index"))
    except (TypeError, ValueError):
        return {}
    if not (
        generation.get("root_generation_persisted") is True
        and 0 <= root_index < int(before_completed_line_index)
    ):
        return {}
    inherited = {
        "schema_version": "contract_runtime.inherited_no_pass_continuation.v1",
        "generation_id": str(generation.get("generation_id") or "").strip(),
        "root_bypass_identity": str(
            generation.get("root_bypass_identity") or ""
        ).strip(),
        "root_diagnostic_backlog_id": str(
            generation.get("root_diagnostic_backlog_id") or ""
        ).strip(),
        "no_pass_claim": True,
        "authoritative_pass_synthesized": False,
    }
    if not all(
        inherited.get(field)
        for field in (
            "generation_id",
            "root_bypass_identity",
            "root_diagnostic_backlog_id",
        )
    ):
        return {}
    return inherited


def _contract_runtime_normal_worker_commit_epoch_bypass_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    request: Mapping[str, Any],
    completed: Sequence[Mapping[str, Any]],
    stop: int,
    commit_sha: str,
    persisted_request: bool,
) -> dict[str, Any]:
    """Authorize only the AC8 normal-lineage graph-epoch deadlock bypass."""

    if conn is None:
        return {}
    next_line = _contract_runtime_next_line(record)
    embedded = (
        request.get("payload")
        if isinstance(request.get("payload"), Mapping)
        else {}
    )
    embedded_continuation = (
        embedded.get("continuation_authority")
        if isinstance(embedded.get("continuation_authority"), Mapping)
        else {}
    )
    runtime_context_id = _timeline_first_deep_text(
        request if persisted_request else next_line,
        "runtime_context_id",
    )
    task_id = _timeline_first_deep_text(
        request if persisted_request else next_line,
        "task_id",
    )
    parent_task_id = _timeline_first_deep_text(
        request if persisted_request else next_line,
        "parent_task_id",
    )
    line_instance_id = _timeline_first_deep_text(
        request if persisted_request else next_line,
        "line_instance_id",
    )
    lane_id = _timeline_first_deep_text(
        request if persisted_request else next_line,
        "lane_id",
    )
    if runtime_context_id and not line_instance_id:
        line_instance_id = f"runtime_context:{runtime_context_id}"
    if persisted_request:
        for field, fallback in (
            ("parent_task_id", parent_task_id),
            ("lane_id", lane_id),
        ):
            if not fallback:
                value = str(embedded_continuation.get(field) or "").strip()
                if field == "parent_task_id":
                    parent_task_id = value
                else:
                    lane_id = value
    pre_write_line_valid = bool(
        not persisted_request
        and str(next_line.get("source") or "").strip()
        == "contract_runtime_same_lane_worker_commit_recovery"
        and str(next_line.get("action") or "").strip()
        == "record_worker_commit"
        and str(next_line.get("recovery_status") or "").strip()
        == "eligible"
        and next_line.get("same_lane_worker_commit_recovery_projection")
        is True
        and str(next_line.get("stage_id") or "").strip()
        == "worker_commit"
        and str(next_line.get("line_id") or "").strip()
        == "worker_commit"
        and str(next_line.get("evidence_kind") or "").strip()
        == "worker_commit"
        and str(next_line.get("owner_role") or "").strip() == "mf_sub"
    )
    persisted_line_valid = bool(
        persisted_request
        and str(request.get("stage_id") or "").strip() == "worker_commit"
        and str(request.get("line_id") or "").strip() == "worker_commit"
        and str(request.get("evidence_kind") or "").strip()
        == "contract_line_bypass"
        and str(request.get("status") or "").strip().lower() == "waived"
        and request.get("no_pass_claim") is True
        and str(embedded_continuation.get("schema_version") or "").strip()
        == "contract_runtime.worker_commit_bypass_continuation.v3"
    )
    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(record.get("backlog_id") or "").strip()
    if not (
        execution_id
        and backlog_id
        and str(record.get("project_id") or "").strip() == project_id
        and str(record.get("contract_id") or "").strip()
        == MF_PARALLEL_CONTRACT_ID
        and not _runtime_record_is_complete(record)
        and (pre_write_line_valid or persisted_line_valid)
        and all(
            (
                runtime_context_id,
                task_id,
                line_instance_id,
            )
        )
        and line_instance_id == f"runtime_context:{runtime_context_id}"
    ):
        return {}

    try:
        stored_record = _contract_runtime_store(conn).get(execution_id)
    except (ContractRuntimeError, sqlite3.Error):
        return {}
    authority_completed = [
        line
        for line in stored_record.get("completed_lines") or []
        if isinstance(line, Mapping)
    ]
    authority_stop = len(authority_completed)
    if persisted_request:
        persisted_matches = [
            index
            for index, line in enumerate(authority_completed)
            if str(line.get("stage_id") or "").strip() == "worker_commit"
            and str(line.get("line_id") or "").strip() == "worker_commit"
            and str(line.get("evidence_kind") or "").strip()
            == "contract_line_bypass"
            and _timeline_first_deep_text(line, "runtime_context_id")
            == runtime_context_id
            and _timeline_first_deep_text(line, "task_id") == task_id
            and stable_sha256(line) == stable_sha256(request)
        ]
        if len(persisted_matches) != 1:
            return {}
        authority_stop = persisted_matches[0]

    implementation_matches: list[tuple[int, Mapping[str, Any]]] = []
    worker_commit_matches: list[tuple[int, Mapping[str, Any]]] = []
    for index, line in enumerate(authority_completed[:authority_stop]):
        if not isinstance(line, Mapping) or not (
            _runtime_context_contract_line_matches_worker(
                line,
                runtime_context_id=runtime_context_id,
                task_id=task_id,
            )
        ):
            continue
        line_id = str(line.get("line_id") or "").strip()
        evidence_kind = str(line.get("evidence_kind") or "").strip()
        if line_id == "worker_implementation" and evidence_kind == "implementation":
            implementation_matches.append((index, line))
        elif line_id == "worker_commit" and evidence_kind == "worker_commit":
            worker_commit_matches.append((index, line))
    if len(implementation_matches) != 1 or len(worker_commit_matches) != 1:
        return {}
    implementation_index, implementation = implementation_matches[0]
    worker_commit_index, earlier_worker_commit = worker_commit_matches[0]
    if not implementation_index < worker_commit_index < authority_stop:
        return {}
    implementation_lineage = _worker_implementation_lineage(
        record,
        implementation,
    )
    implementation_trace_ids = sorted(
        set(implementation_lineage.get("graph_trace_ids") or [])
    )
    earlier_payload = (
        earlier_worker_commit.get("payload")
        if isinstance(earlier_worker_commit.get("payload"), Mapping)
        else {}
    )
    earlier_trace_ids = sorted(
        set(
            _runtime_context_service_query_values(
                earlier_payload,
                "graph_trace_ids",
                "verified_trace_ids",
            )
        )
    )
    earlier_commit_sha = str(
        earlier_worker_commit.get("commit_sha")
        or earlier_payload.get("worker_commit_sha")
        or earlier_payload.get("commit_sha")
        or ""
    ).strip().lower()
    if not (
        implementation_trace_ids
        and earlier_trace_ids == implementation_trace_ids
        and str(earlier_payload.get("implementation_lineage_ref") or "").strip()
        == str(implementation_lineage.get("implementation_lineage_ref") or "").strip()
        and re.fullmatch(
            r"[0-9a-f]{40}|[0-9a-f]{64}",
            earlier_commit_sha,
        )
        and earlier_commit_sha != commit_sha
        and _active_failed_qa_line_index(
            authority_completed[:authority_stop]
        )
        < 0
    ):
        return {}

    matching_contexts: list[Any] = []
    matching_dispatch_indexes: list[int] = []
    for dispatch_index, dispatch in enumerate(
        authority_completed[:implementation_index]
    ):
        if str(dispatch.get("line_id") or "").strip() != (
            "observer_dispatch_bounded_workers"
        ):
            continue
        dispatch_matched = False
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=dispatch,
        ):
            if _contract_runtime_context_identity(context)[:2] != (
                runtime_context_id,
                task_id,
            ):
                continue
            matching_contexts.append(context)
            dispatch_matched = True
        if dispatch_matched:
            matching_dispatch_indexes.append(dispatch_index)
    if len(matching_contexts) != 1 or len(matching_dispatch_indexes) != 1:
        return {}
    context = matching_contexts[0]
    context_runtime_id, context_task_id, context_parent_id = (
        _contract_runtime_context_identity(context)
    )
    context_lane_id = str(
        getattr(context, "worker_slot_id", "")
        or getattr(context, "worker_id", "")
        or ""
    ).strip()
    if parent_task_id and context_parent_id != parent_task_id:
        return {}
    if lane_id and context_lane_id != lane_id:
        return {}
    parent_task_id = context_parent_id
    lane_id = context_lane_id
    if (
        (context_runtime_id, context_task_id, context_parent_id)
        != (runtime_context_id, task_id, parent_task_id)
        or context_lane_id != lane_id
    ):
        return {}
    canonical_claims = {
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "lane_id": lane_id,
        "line_instance_id": line_instance_id,
    }
    for field, expected in canonical_claims.items():
        claims = {
            str(candidate.get(field) or "").strip()
            for candidate in _contract_runtime_mapping_candidates(request)
            if str(candidate.get(field) or "").strip()
        }
        if claims and claims != {expected}:
            return {}
    historical_record = {
        **dict(stored_record),
        "completed_lines": list(authority_completed[:authority_stop]),
    }
    recovery = _runtime_context_same_lane_worker_commit_recovery(
        historical_record,
        context,
        conn=conn,
        project_id=project_id,
    )
    if not (
        recovery.get("status") == "eligible"
        and recovery.get("blocked") is False
        and recovery.get("server_derived") is True
        and str(recovery.get("recovery_reason") or "").strip()
        == "pre_attestation_same_lane_descendant"
        and str(recovery.get("next_legal_action") or "").strip()
        == "record_worker_commit"
        and int(recovery.get("superseded_completed_line_index") or -1)
        == worker_commit_index
        and str(recovery.get("recorded_commit_sha") or "").strip().lower()
        == earlier_commit_sha
        and str(recovery.get("actual_worktree_head_commit") or "").strip().lower()
        == commit_sha
    ):
        return {}

    expected_changed_files = sorted(
        set(recovery.get("changed_files") or [])
    )
    expected_owned_files = sorted(
        set(recovery.get("owned_files") or [])
    )
    claimed_changed_files = sorted(
        set(
            _runtime_context_service_query_values(
                request,
                "changed_files",
                "commit_diff_files",
                "worker_changed_files",
            )
        )
    )
    claimed_owned_files = sorted(
        set(
            _runtime_context_service_query_values(
                request,
                "owned_files",
            )
        )
    )
    if (
        claimed_changed_files
        and claimed_changed_files != expected_changed_files
    ) or (
        claimed_owned_files
        and claimed_owned_files != expected_owned_files
    ):
        return {}
    expected_diff_base = str(
        recovery.get("diff_base_commit") or ""
    ).strip().lower()
    claimed_bases = {
        str(candidate.get(field) or "").strip().lower()
        for candidate in _contract_runtime_mapping_candidates(request)
        for field in ("base_commit", "diff_base_commit")
        if str(candidate.get(field) or "").strip()
    }
    if claimed_bases and claimed_bases != {expected_diff_base}:
        return {}
    expected_parent = str(
        recovery.get("commit_parent_sha") or ""
    ).strip().lower()
    claimed_parents = {
        str(candidate.get("commit_parent_sha") or "").strip().lower()
        for candidate in _contract_runtime_mapping_candidates(request)
        if str(candidate.get("commit_parent_sha") or "").strip()
    }
    if claimed_parents and claimed_parents != {expected_parent}:
        return {}

    direct_commit_sources = [request, embedded]
    if embedded_continuation:
        direct_commit_sources.append(embedded_continuation)
    claimed_commits = {
        str(source.get(field) or "").strip().lower()
        for source in direct_commit_sources
        for field in ("commit_sha", "worker_commit_sha", "head_commit")
        if str(source.get(field) or "").strip()
    }
    if claimed_commits and claimed_commits != {commit_sha}:
        return {}
    line_claims = {
        field: {
            str(candidate.get(field) or "").strip()
            for candidate in _contract_runtime_mapping_candidates(request)
            if str(candidate.get(field) or "").strip()
        }
        for field in ("stage_id", "line_id")
    }
    if any(
        claims and claims != {"worker_commit"}
        for claims in line_claims.values()
    ):
        return {}
    execution_claims = {
        str(candidate.get(field) or "").strip()
        for candidate in _contract_runtime_mapping_candidates(request)
        for field in (
            "contract_execution_id",
            "successor_contract_execution_id",
        )
        if str(candidate.get(field) or "").strip()
    }
    backlog_claims = {
        str(candidate.get("backlog_id") or "").strip()
        for candidate in _contract_runtime_mapping_candidates(request)
        if str(candidate.get("backlog_id") or "").strip()
    }
    if (
        execution_claims
        and execution_claims != {execution_id}
    ) or (backlog_claims and backlog_claims != {backlog_id}):
        return {}
    if any(
        str(line.get("stage_id") or "").strip()
        == "worker_implementation"
        and str(line.get("line_id") or "").strip()
        == "worker_implementation"
        and str(line.get("evidence_kind") or "").strip()
        == "contract_line_bypass"
        and _timeline_first_deep_text(line, "line_instance_id")
        == line_instance_id
        for line in authority_completed[:authority_stop]
    ):
        return {}

    current_projection = (
        _contract_runtime_raw_current_chain_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
        if persisted_request
        else _contract_chain_current_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            rebuild_if_missing=False,
        )
    )
    active_chain = (
        current_projection.get("active_chain")
        if isinstance(current_projection.get("active_chain"), Mapping)
        else {}
    )
    if not (
        current_projection
        and not bool(current_projection.get("degraded"))
        and str(current_projection.get("projection_source") or "").strip()
        == "backlog_contract_chain_current"
        and str(current_projection.get("source_of_proof") or "").strip()
        == "contract_runtime_executions.completed_lines"
        and str(current_projection.get("readiness_state") or "").strip()
        == "contract_active"
        and str(current_projection.get("current_contract_execution_id") or "").strip()
        == execution_id
        and str(current_projection.get("active_child_contract_execution_id") or "").strip()
        == execution_id
        and execution_id
        in {
            str(item or "").strip()
            for item in active_chain.get("execution_ids") or []
        }
    ):
        return {}

    fresh_trace_ids = (
        list(embedded_continuation.get("fresh_graph_trace_ids") or [])
        if persisted_request
        else _runtime_context_service_dedupe(
            _runtime_context_service_query_values(
                request,
                "graph_trace_ids",
            )
        )
    )
    persisted_epoch = (
        embedded_continuation.get("graph_epoch_transition_authority")
        if persisted_request
        and isinstance(
            embedded_continuation.get("graph_epoch_transition_authority"),
            Mapping,
        )
        else None
    )
    graph_epoch = (
        _contract_runtime_worker_commit_graph_epoch_transition_authority(
            conn,
            project_id=project_id,
            context=context,
            old_graph_trace_ids=implementation_trace_ids,
            fresh_graph_trace_ids=fresh_trace_ids,
            old_epoch_commit_candidates=[earlier_commit_sha],
            persisted=persisted_epoch,
        )
    )
    if not graph_epoch:
        return {}
    active_commit = str(graph_epoch.get("active_graph_commit") or "").strip()
    persisted_canonical = (
        embedded_continuation.get("canonical_owned_file_provenance")
        if persisted_request
        and isinstance(
            embedded_continuation.get("canonical_owned_file_provenance"),
            Mapping,
        )
        else None
    )
    canonical_provenance = _contract_runtime_canonical_owned_file_provenance(
        conn,
        project_id=project_id,
        record=record,
        candidate_commit_sha=commit_sha,
        canonical_commit_sha=active_commit,
        active_snapshot_id=str(
            graph_epoch.get("active_snapshot_id") or ""
        ).strip(),
        owned_files=list(recovery.get("owned_files") or []),
        repository_root=str(
            getattr(context, "worktree_path", "") or ""
        ).strip(),
        persisted=persisted_canonical,
    )
    if not canonical_provenance:
        return {}

    continuation = {
        "schema_version": (
            "contract_runtime.worker_commit_bypass_continuation.v3"
        ),
        "recovery_kind": "normal_implementation_graph_epoch_transition",
        "server_derived": True,
        "db_verified": True,
        "source": (
            "normal_worker_implementation+prior_worker_commit+"
            "current_graph_epoch_recovery"
        ),
        "authorization_scope": "worker_commit_bypass_only",
        "no_pass_claim": True,
        "authoritative_pass_synthesized": False,
        "implementation_pass_claimed": False,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "lane_id": lane_id,
        "line_instance_id": line_instance_id,
        "commit_sha": commit_sha,
        "worker_commit_sha": commit_sha,
        "earlier_worker_commit_sha": earlier_commit_sha,
        "changed_files": list(recovery.get("changed_files") or []),
        "commit_diff_files": list(recovery.get("changed_files") or []),
        "commit_parent_sha": str(recovery.get("commit_parent_sha") or "").strip(),
        "diff_base_commit": str(recovery.get("diff_base_commit") or "").strip(),
        "owned_files": list(recovery.get("owned_files") or []),
        "out_of_scope_files": [],
        "clean_worktree": True,
        "old_graph_trace_ids": implementation_trace_ids,
        "fresh_graph_trace_ids": fresh_trace_ids,
        "active_snapshot_id": str(
            graph_epoch.get("active_snapshot_id") or ""
        ).strip(),
        "active_graph_commit": active_commit,
        "implementation_lineage_ref": str(
            implementation_lineage.get("implementation_lineage_ref") or ""
        ).strip(),
        "graph_epoch_transition_authority": graph_epoch,
        "canonical_owned_file_provenance": canonical_provenance,
    }
    inherited_no_pass = _contract_runtime_inherited_no_pass_continuation(
        record,
        before_completed_line_index=stop,
    )
    if inherited_no_pass:
        continuation["inherited_no_pass_continuation"] = inherited_no_pass
    if persisted_request:
        if not embedded_continuation or stable_sha256(
            embedded_continuation
        ) != stable_sha256(continuation):
            return {}
        persisted_audit = _contract_runtime_strict_no_pass_bypass_audit(
            conn,
            project_id=project_id,
            record=record,
            line=request,
            expected_line_id="worker_commit",
            expected_blocked_evidence_kind="worker_commit",
            expected_event_task_ids={execution_id, task_id},
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            line_instance_id=line_instance_id,
        )
        if not persisted_audit:
            return {}
        continuation["persisted_worker_commit_bypass_audit"] = (
            persisted_audit
        )
    return continuation


def _contract_runtime_worker_commit_bypass_continuation_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    request: Mapping[str, Any],
) -> dict[str, Any]:
    """Recover candidate identity without treating a worker-commit bypass as PASS."""

    payload = request.get("payload") if isinstance(request.get("payload"), Mapping) else {}
    if str(request.get("line_id") or payload.get("line_id") or "").strip() != "worker_commit":
        return {}
    evidence_kind = str(request.get("evidence_kind") or "").strip()
    if evidence_kind and evidence_kind != "contract_line_bypass":
        return {}
    evidence_refs = [
        str(item or "").strip()
        for item in (request.get("evidence_refs") or payload.get("evidence_refs") or [])
        if str(item or "").strip()
    ]
    commit_candidates = {
        str(source.get(key) or "").strip()
        for source in (request, payload)
        for key in ("commit_sha", "worker_commit_sha", "head_commit")
        if str(source.get(key) or "").strip()
    }
    commit_candidates.update(
        ref.split(":", 1)[1].strip()
        for ref in evidence_refs
        if ref.startswith("commit:")
    )
    commit_candidates = {
        value.lower()
        for value in commit_candidates
        if re.fullmatch(r"[0-9a-fA-F]{40}|[0-9a-fA-F]{64}", value)
    }
    if len(commit_candidates) != 1:
        return {}
    commit_sha = next(iter(commit_candidates))

    completed = [
        line for line in record.get("completed_lines") or [] if isinstance(line, Mapping)
    ]

    def bind_inherited_no_pass_generation(
        continuation: Mapping[str, Any],
    ) -> dict[str, Any]:
        """Join modern no-PASS lineage to server-derived candidate custody."""

        if not inherited_no_pass:
            return dict(continuation)
        return {
            **dict(continuation),
            "inherited_no_pass_continuation": dict(inherited_no_pass),
        }
    stop = len(completed)
    persisted_request = False
    for index, line in enumerate(completed):
        if line is request:
            stop = index
            persisted_request = True
            break
    inherited_no_pass = _contract_runtime_inherited_no_pass_continuation(
        record,
        before_completed_line_index=stop,
    )
    requested_runtime_context_id = _timeline_first_deep_text(
        request, "runtime_context_id"
    )
    requested_task_id = _timeline_first_deep_text(request, "task_id")
    implementation = {}
    for candidate in reversed(completed[:stop]):
        if str(candidate.get("line_id") or "").strip() != "worker_implementation":
            continue
        if str(candidate.get("evidence_kind") or "").strip() != "implementation":
            continue
        candidate_runtime_context_id = _timeline_first_deep_text(
            candidate, "runtime_context_id"
        )
        candidate_task_id = _timeline_first_deep_text(candidate, "task_id")
        if (
            requested_runtime_context_id
            and candidate_runtime_context_id != requested_runtime_context_id
        ):
            continue
        if requested_task_id and candidate_task_id != requested_task_id:
            continue
        implementation = candidate
        break
    if not implementation:
        bypass_anchor = (
            _contract_runtime_worker_implementation_bypass_continuation_anchor(
                conn,
                project_id=project_id,
                record=record,
                completed=completed[:stop],
                persisted_worker_commit_line=(
                    request if persisted_request else None
                ),
            )
        )
        if not bypass_anchor:
            return {}
        context = bypass_anchor.get("context")
        if context is None:
            return {}
        runtime_context_id = str(
            bypass_anchor.get("runtime_context_id") or ""
        ).strip()
        task_id = str(bypass_anchor.get("task_id") or "").strip()
        parent_task_id = str(
            bypass_anchor.get("parent_task_id") or ""
        ).strip()
        canonical_claims = {
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "lane_id": str(bypass_anchor.get("lane_id") or "").strip(),
            "line_instance_id": str(
                bypass_anchor.get("line_instance_id") or ""
            ).strip(),
        }
        for field, expected in canonical_claims.items():
            claimed = {
                str(candidate.get(field) or "").strip()
                for candidate in _contract_runtime_mapping_candidates(request)
                if str(candidate.get(field) or "").strip()
            }
            if claimed and claimed != {expected}:
                return {}
        persisted_bypass_audit: dict[str, Any] = {}
        if persisted_request:
            persisted_bypass_audit = (
                _contract_runtime_strict_no_pass_bypass_audit(
                    conn,
                    project_id=project_id,
                    record=record,
                    line=request,
                    expected_line_id="worker_commit",
                    expected_blocked_evidence_kind="worker_commit",
                    expected_event_task_ids={
                        str(record.get("contract_execution_id") or "").strip(),
                        task_id,
                    },
                    runtime_context_id=runtime_context_id,
                    task_id=task_id,
                    line_instance_id=canonical_claims["line_instance_id"],
                )
            )
            if not persisted_bypass_audit:
                return {}

        worktree_path = str(
            getattr(context, "worktree_path", "") or ""
        ).strip()
        base_commit = str(
            getattr(context, "base_commit", "") or ""
        ).strip().lower()
        if not (
            worktree_path
            and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", base_commit)
        ):
            return {}
        try:
            if _runtime_context_git_dirty_files(worktree_path):
                return {}
            actual_head = _runtime_context_git_head_commit(
                worktree_path
            ).lower()
            revision_diff = _runtime_context_worker_commit_revision_diff(
                worktree_path,
                actual_head,
                base_commit=base_commit,
            )
        except (GovernanceError, ValidationError):
            return {}
        changed_files = sorted(
            set(revision_diff.get("changed_files") or [])
        )
        owned_files = sorted(
            set(
                getattr(context, "owned_files", ())
                or getattr(context, "target_files", ())
                or ()
            )
        )
        if not (
            re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", actual_head)
            and str(revision_diff.get("base_commit") or "").strip().lower()
            == base_commit
            and changed_files
            and owned_files
            and not (set(changed_files) - set(owned_files))
        ):
            return {}
        if commit_candidates != {actual_head}:
            return {}
        claimed_files = sorted(
            set(
                _runtime_context_service_query_values(
                    request,
                    "changed_files",
                    "commit_diff_files",
                    "worker_changed_files",
                )
            )
        )
        if claimed_files and claimed_files != changed_files:
            return {}
        claimed_owned_files = sorted(
            set(
                _runtime_context_service_query_values(
                    request,
                    "owned_files",
                )
            )
        )
        if claimed_owned_files and claimed_owned_files != owned_files:
            return {}
        claimed_bases = {
            str(candidate.get(field) or "").strip().lower()
            for candidate in _contract_runtime_mapping_candidates(request)
            for field in ("base_commit", "diff_base_commit")
            if str(candidate.get(field) or "").strip()
        }
        if claimed_bases and claimed_bases != {base_commit}:
            return {}
        public_anchor = {
            key: value
            for key, value in bypass_anchor.items()
            if key != "context"
        }
        continuation = bind_inherited_no_pass_generation({
            "schema_version": (
                "contract_runtime.worker_commit_bypass_continuation.v2"
            ),
            "server_derived": True,
            "db_verified": True,
            "source": (
                "audited_no_pass_worker_implementation_bypass+"
                "runtime_context_clean_base_head_diff"
            ),
            "authorization_scope": "worker_commit_bypass_only",
            "no_pass_claim": True,
            "authoritative_pass_synthesized": False,
            "implementation_pass_claimed": False,
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "lane_id": canonical_claims["lane_id"],
            "line_instance_id": canonical_claims["line_instance_id"],
            "commit_sha": actual_head,
            "worker_commit_sha": actual_head,
            "changed_files": changed_files,
            "commit_diff_files": changed_files,
            "commit_parent_sha": str(
                revision_diff.get("parent_commit") or ""
            ).strip().lower(),
            "diff_base_commit": base_commit,
            "owned_files": owned_files,
            "out_of_scope_files": [],
            "clean_worktree": True,
            "historical_lineage_stale": False,
            "canonical_historical_commit_sha": "",
            "implementation_bypass_anchor": public_anchor,
        })
        if not continuation:
            return {}
        if persisted_request:
            embedded_continuation = (
                payload.get("continuation_authority")
                if isinstance(
                    payload.get("continuation_authority"), Mapping
                )
                else {}
            )
            if not embedded_continuation or stable_sha256(
                embedded_continuation
            ) != stable_sha256(continuation):
                return {}
            continuation["persisted_worker_commit_bypass_audit"] = (
                persisted_bypass_audit
            )
        return continuation
    epoch_transition = (
        _contract_runtime_normal_worker_commit_epoch_bypass_authority(
            conn,
            project_id=project_id,
            record=record,
            request=request,
            completed=completed,
            stop=stop,
            commit_sha=commit_sha,
            persisted_request=persisted_request,
        )
    )
    if epoch_transition:
        return bind_inherited_no_pass_generation(epoch_transition)
    runtime_context_id = _timeline_first_deep_text(
        implementation, "runtime_context_id"
    )
    task_id = _timeline_first_deep_text(implementation, "task_id")
    parent_task_id = _timeline_first_deep_text(implementation, "parent_task_id")
    contexts: dict[str, Any] = {}
    for dispatch in completed:
        if str(dispatch.get("line_id") or "").strip() != "observer_dispatch_bounded_workers":
            continue
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn, project_id=project_id, record=record, line=dispatch
        ):
            identity = _contract_runtime_context_identity(context)
            if identity[:2] != (runtime_context_id, task_id):
                continue
            contexts[identity[0]] = context
    if len(contexts) != 1:
        return {}
    context = next(iter(contexts.values()))
    worktree_path = str(getattr(context, "worktree_path", "") or "").strip()
    base_commit = str(getattr(context, "base_commit", "") or "").strip()
    if not worktree_path or _runtime_context_git_dirty_files(worktree_path):
        return {}
    try:
        actual_head = _runtime_context_git_head_commit(worktree_path)
        revision_diff = _runtime_context_worker_commit_revision_diff(
            worktree_path, actual_head, base_commit=base_commit
        )
    except GovernanceError:
        return {}
    changed_files = list(revision_diff.get("changed_files") or [])
    implementation_payload = (
        implementation.get("payload")
        if isinstance(implementation.get("payload"), Mapping)
        else {}
    )
    implementation_files = [
        str(item or "").strip()
        for item in (
            implementation.get("changed_files")
            or implementation_payload.get("changed_files")
            or []
        )
        if str(item or "").strip()
    ]
    claimed_files = sorted(
        set(_runtime_context_service_query_values(request, "changed_files"))
    )
    owned_files = sorted(
        set(
            getattr(context, "owned_files", ())
            or getattr(context, "target_files", ())
            or ()
        )
    )
    out_of_scope = sorted(set(changed_files) - set(owned_files))
    canonical_historical_commit_sha = str(
        implementation.get("commit_sha")
        or implementation_payload.get("worker_commit_sha")
        or implementation_payload.get("validated_head_commit")
        or implementation_payload.get("commit_sha")
        or implementation_payload.get("head_commit")
        or ""
    ).strip().lower()
    # Normal workers record implementation before creating the clean git
    # commit.  An empty implementation commit is therefore not historical
    # drift: the current HEAD is independently re-derived from the assigned
    # worktree and its exact base..HEAD diff below.  A real non-empty prior
    # commit remains strict and may only diverge on the failed-QA path.
    historical_lineage_stale = bool(
        (
            canonical_historical_commit_sha
            and canonical_historical_commit_sha != actual_head
        )
        or set(implementation_files) != set(changed_files)
    )
    if actual_head != commit_sha:
        return {}
    if claimed_files and claimed_files != sorted(set(changed_files)):
        return {}
    if not changed_files or not owned_files or out_of_scope:
        return {}
    if historical_lineage_stale and _active_failed_qa_line_index(completed[:stop]) < 0:
        return {}
    return bind_inherited_no_pass_generation({
        "schema_version": "contract_runtime.worker_commit_bypass_continuation.v1",
        "server_derived": True,
        "db_verified": True,
        "source": (
            "runtime_context_clean_base_head_diff_after_historical_lineage_stale"
            if historical_lineage_stale
            else "canonical_worker_implementation+runtime_context_git"
        ),
        **(
            {"authorization_scope": "worker_commit_bypass_only"}
            if not historical_lineage_stale
            else {}
        ),
        "no_pass_claim": True,
        "authoritative_pass_synthesized": False,
        "implementation_pass_claimed": False,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "commit_sha": commit_sha,
        "worker_commit_sha": commit_sha,
        "changed_files": changed_files,
        "commit_diff_files": changed_files,
        "commit_parent_sha": str(revision_diff.get("parent_commit") or ""),
        "diff_base_commit": str(revision_diff.get("base_commit") or ""),
        "owned_files": owned_files,
        "out_of_scope_files": [],
        "clean_worktree": True,
        "historical_lineage_stale": historical_lineage_stale,
        "canonical_historical_commit_sha": canonical_historical_commit_sha,
    })


def _contract_runtime_server_candidate_commit(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> str:
    definition = _contract_runtime_definition_for_record(record)
    system_layer = (
        definition.get("system_layer")
        if isinstance(definition.get("system_layer"), Mapping)
        else {}
    )
    graph_binding_policy = (
        system_layer.get("graph_binding_policy")
        if isinstance(system_layer.get("graph_binding_policy"), Mapping)
        else {}
    )
    policy = (
        graph_binding_policy.get("candidate_commit_evidence_policy")
        if isinstance(
            graph_binding_policy.get("candidate_commit_evidence_policy"),
            Mapping,
        )
        else {}
    )
    if policy.get("enabled") is not True:
        return ""
    candidate_path = str(policy.get("candidate_commit_path") or "").strip()
    if candidate_path != "commit_sha":
        return ""
    trusted_line_ids = {
        str(item or "").strip() for item in policy.get("line_ids") or []
    }
    for line in reversed(
        [item for item in record.get("completed_lines") or [] if isinstance(item, Mapping)]
    ):
        if str(line.get("line_id") or "").strip() not in trusted_line_ids:
            continue
        if str(line.get("evidence_kind") or "").strip() == "contract_line_bypass":
            continuation = _contract_runtime_worker_commit_bypass_continuation_authority(
                conn,
                project_id=project_id,
                record=record,
                request=line,
            )
            if (
                continuation.get("server_derived") is True
                and continuation.get("db_verified") is True
                and continuation.get("no_pass_claim") is True
                and continuation.get("authoritative_pass_synthesized")
                is not True
            ):
                return str(continuation.get("commit_sha") or "").strip().lower()
            continue
        value = str(line.get(candidate_path) or "").strip().lower()
        if re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", value):
            return value
    return ""


def _contract_runtime_server_candidate_base_commit(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    expected_candidate_commit: str,
    expected_context: Any | None = None,
) -> str:
    """Return the trusted cumulative diff base for the candidate commit."""

    if str(record.get("project_id") or "").strip() != str(
        project_id or ""
    ).strip():
        return ""
    if expected_context is not None:
        dispatch_match = _contract_runtime_dispatch_line_match(
            record,
            expected_context,
        )
        if not _contract_runtime_verified_dispatch_lineage(
            record,
            expected_context,
            dispatch_match,
        ):
            return ""
        runtime_context_id, task_id, _ = _contract_runtime_context_identity(
            expected_context
        )
    else:
        identity = _contract_runtime_server_line_identity(record)
        runtime_context_id = str(
            identity.get("runtime_context_id") or ""
        ).strip()
        task_id = str(identity.get("task_id") or "").strip()
    if not runtime_context_id or not task_id:
        return ""
    expected_candidate_commit = str(
        _contract_runtime_full_commit_value(
            project_id,
            expected_candidate_commit,
        )
    ).strip().lower()
    if not expected_candidate_commit:
        return ""
    matching_worker_commit_bases: list[str] = []
    for line in reversed(
        [
            item
            for item in record.get("completed_lines") or []
            if isinstance(item, Mapping)
        ]
    ):
        if str(line.get("line_id") or "").strip() != "worker_commit":
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        if str(line.get("evidence_kind") or "").strip() == "contract_line_bypass":
            payload = _contract_runtime_worker_commit_bypass_continuation_authority(
                conn,
                project_id=project_id,
                record=record,
                request=line,
            )
            if not (
                payload.get("server_derived") is True
                and payload.get("db_verified") is True
                and payload.get("no_pass_claim") is True
                and payload.get("authoritative_pass_synthesized")
                is not True
            ):
                continue
        if (
            _timeline_first_deep_text(line, "runtime_context_id")
            != runtime_context_id
            or _timeline_first_deep_text(line, "task_id") != task_id
        ):
            continue
        raw_commit_values = [
            str(value or "").strip().lower()
            for value in (
                line.get("commit_sha"),
                payload.get("commit_sha"),
                payload.get("worker_commit_sha"),
                payload.get("validated_head_commit"),
            )
            if str(value or "").strip()
        ]
        commit_values = {
            _contract_runtime_full_commit_value(project_id, value)
            for value in raw_commit_values
        }
        if "" in commit_values:
            continue
        if commit_values != {expected_candidate_commit}:
            continue
        matching_worker_commit_bases.append(
            _contract_runtime_full_commit_value(
                project_id,
                payload.get("diff_base_commit"),
            )
        )
    if len(matching_worker_commit_bases) != 1:
        return ""
    worker_commit_base = matching_worker_commit_bases[0]

    context_bases: set[str] = set()
    context_retarget_bases: set[str] = set()
    if expected_context is not None:
        context_bases.add(
            _contract_runtime_full_commit_value(
                project_id,
                getattr(expected_context, "base_commit", ""),
            )
        )
        context_retarget_bases.add(
            _contract_runtime_full_commit_value(
                project_id,
                getattr(expected_context, "target_head_commit", ""),
            )
        )
    else:
        for dispatch_line in record.get("completed_lines") or []:
            if not isinstance(dispatch_line, Mapping) or str(
                dispatch_line.get("line_id") or ""
            ).strip() != "observer_dispatch_bounded_workers":
                continue
            for context in _contract_runtime_contexts_for_dispatch_line(
                conn,
                project_id=project_id,
                record=record,
                line=dispatch_line,
            ):
                context_id, context_task_id, _ = (
                    _contract_runtime_context_identity(context)
                )
                if (
                    context_id == runtime_context_id
                    and context_task_id == task_id
                ):
                    context_bases.add(
                        _contract_runtime_full_commit_value(
                            project_id,
                            getattr(context, "base_commit", ""),
                        )
                    )
                    context_retarget_bases.add(
                        _contract_runtime_full_commit_value(
                            project_id,
                            getattr(context, "target_head_commit", ""),
                        )
                    )
    valid_context_bases = {
        value
        for value in {*context_bases, *context_retarget_bases}
        if re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", value)
        and value != expected_candidate_commit
    }
    if (
        re.fullmatch(
            r"[0-9a-f]{40}|[0-9a-f]{64}", worker_commit_base
        )
        and worker_commit_base != expected_candidate_commit
    ):
        return (
            worker_commit_base
            if worker_commit_base in valid_context_bases
            else ""
        )
    return next(iter(valid_context_bases)) if len(valid_context_bases) == 1 else ""


def _contract_runtime_server_postmerge_comparison_base_commit(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    expected_candidate_commit: str,
) -> str:
    """Return the pre-campaign target head for a verified post-merge candidate."""

    if not _is_mf_parallel_postmerge_revision(record):
        return ""
    expected_candidate = _contract_runtime_full_commit_value(
        project_id,
        expected_candidate_commit,
    )
    required_worker_count = (
        _contract_runtime_mf_parallel_current_generation_worker_count(
            record,
            conn=conn,
            project_id=project_id,
        )
    )
    merge_record = record
    merge = _contract_runtime_rev8_two_worker_merge_projection(
        record,
        required_worker_count=required_worker_count,
        conn=conn,
        project_id=project_id,
    )
    if not (
        merge.get("timeline_verified") is True
        and merge.get("all_lane_merges_verified") is True
    ):
        projected_record, runtime_projection = (
            _contract_runtime_apply_mf_parallel_context_projection(
                conn,
                project_id=project_id,
                record=record,
                actor_role="qa",
            )
        )
        projected_merge = _contract_runtime_rev8_two_worker_merge_projection(
            projected_record,
            required_worker_count=required_worker_count,
            conn=conn,
            project_id=project_id,
        )
        if (
            str(runtime_projection.get("status") or "").strip()
            == "projected"
            and runtime_projection.get("persistence")
            == {
                "mutates_contract_runtime_completed_lines": False,
                "observer_authored_worker_backfill": False,
            }
            and projected_merge.get("timeline_verified") is True
            and projected_merge.get("all_lane_merges_verified") is True
        ):
            merge_record = projected_record
            merge = projected_merge
    lane_merge_commit = _contract_runtime_full_commit_value(
        project_id,
        merge.get("merged_commit_sha"),
    )
    if (
        not expected_candidate
        or not lane_merge_commit
    ):
        return ""
    dispatch_index = int(merge.get("dispatch_completed_line_index") or -1)
    lane_ids = {
        str(item or "").strip()
        for item in merge.get("lane_runtime_context_ids") or []
        if str(item or "").strip()
    }
    from .parallel_branch_runtime import (
        get_merge_queue_item,
        list_merge_queue_items,
    )

    ordered: list[tuple[int, str, str]] = []
    for index, line in enumerate(merge_record.get("completed_lines") or []):
        if index <= dispatch_index or not isinstance(line, Mapping):
            continue
        if str(line.get("line_id") or "").strip() != "observer_merge":
            continue
        payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
        durable = (
            payload.get("durable_merge_authority")
            if isinstance(payload.get("durable_merge_authority"), Mapping)
            else {}
        )
        runtime_context_id = str(
            durable.get("runtime_context_id") or ""
        ).strip()
        if runtime_context_id not in lane_ids:
            continue
        merge_queue_id = str(durable.get("merge_queue_id") or "").strip()
        queue_item_id = str(durable.get("queue_item_id") or "").strip()
        try:
            queue_item = (
                get_merge_queue_item(
                    conn,
                    project_id,
                    merge_queue_id,
                    queue_item_id,
                )
                if merge_queue_id and queue_item_id
                else None
            )
        except (sqlite3.Error, TypeError, ValueError):
            return ""
        before = _contract_runtime_full_commit_value(
            project_id,
            getattr(queue_item, "target_head_before_merge", ""),
        )
        after = _contract_runtime_full_commit_value(
            project_id,
            getattr(queue_item, "target_head_after_merge", ""),
        )
        event_id = int(durable.get("merge_event_id") or 0)
        if not (
            queue_item is not None
            and durable.get("server_derived") is True
            and durable.get("db_verified") is True
            and str(getattr(queue_item, "task_id", "") or "").strip()
            == str(durable.get("task_id") or "").strip()
            and str(getattr(queue_item, "backlog_id", "") or "").strip()
            == str(record.get("backlog_id") or "").strip()
            and str(getattr(queue_item, "status", "") or "").strip()
            == "merged"
            and event_id > 0
            and before
            and after
            and _contract_runtime_full_commit_value(
                project_id,
                durable.get("merge_commit"),
            )
            == after
            and _contract_runtime_full_commit_value(
                project_id,
                getattr(queue_item, "merge_commit", ""),
            )
            == after
            and (
                not str(
                    durable.get("target_head_before_merge") or ""
                ).strip()
                or _contract_runtime_full_commit_value(
                    project_id,
                    durable.get("target_head_before_merge"),
                )
                == before
            )
            and _contract_runtime_full_commit_value(
                project_id,
                durable.get("target_head_after_merge"),
            )
            == after
        ):
            return ""
        ordered.append((event_id, before, after))
    ordered.sort(key=lambda item: item[0])
    if len(ordered) != required_worker_count:
        return ""
    if any(
        ordered[index - 1][2] != ordered[index][1]
        for index in range(1, len(ordered))
    ):
        return ""
    comparison_base = ordered[0][1]
    final_lane_head = ordered[-1][2]
    exact_candidate_relation_verified = final_lane_head == expected_candidate
    if not exact_candidate_relation_verified and required_worker_count == 1:
        dispatch_line = (record.get("completed_lines") or [])[dispatch_index]
        batch_contexts: dict[str, Any] = {}
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=dispatch_line,
        ):
            runtime_context_id, context_task_id, _parent_task_id = (
                _contract_runtime_context_identity(context)
            )
            if (
                runtime_context_id in lane_ids
                and context_task_id
                == str(merge.get("task_id") or "").strip()
                and str(getattr(context, "batch_id", "") or "").strip()
                and str(
                    getattr(context, "merge_queue_id", "") or ""
                ).strip()
                == str(merge.get("merge_queue_id") or "").strip()
            ):
                batch_contexts[runtime_context_id] = context
        if len(batch_contexts) == 1:
            batch_context = next(iter(batch_contexts.values()))
            batch_id = str(
                getattr(batch_context, "batch_id", "") or ""
            ).strip()
            merge_queue_id = str(
                getattr(batch_context, "merge_queue_id", "") or ""
            ).strip()
            try:
                epoch_rows = conn.execute(
                    """
                    SELECT *
                    FROM parallel_branch_integration_epochs
                    WHERE project_id = ? AND batch_id = ?
                    LIMIT 2
                    """,
                    (project_id, batch_id),
                ).fetchall()
                queue_rows = list_merge_queue_items(
                    conn,
                    project_id,
                    merge_queue_id,
                )
            except (sqlite3.Error, TypeError, ValueError):
                epoch_rows = []
                queue_rows = []
            epoch = dict(epoch_rows[0]) if len(epoch_rows) == 1 else {}
            queue_item_ids = [
                str(item.queue_item_id or "").strip()
                for item in queue_rows
            ]
            merged_prefix = _json_loads(
                epoch.get("merged_prefix_json"),
                [],
            )
            matching_child_rows = [
                item
                for item in queue_rows
                if str(item.task_id or "").strip()
                == str(merge.get("task_id") or "").strip()
                and str(item.backlog_id or "").strip()
                == str(record.get("backlog_id") or "").strip()
                and str(item.queue_item_id or "").strip()
                == str(merge.get("queue_item_id") or "").strip()
                and _contract_runtime_full_commit_value(
                    project_id,
                    item.target_head_after_merge,
                )
                == final_lane_head
            ]
            queue_linear = bool(
                len(queue_rows) >= 2
                and all(
                    str(item.status or "").strip() == "merged"
                    and _contract_runtime_full_commit_value(
                        project_id,
                        item.target_head_before_merge,
                    )
                    and _contract_runtime_full_commit_value(
                        project_id,
                        item.target_head_after_merge,
                    )
                    for item in queue_rows
                )
                and all(
                    _contract_runtime_full_commit_value(
                        project_id,
                        queue_rows[index - 1].target_head_after_merge,
                    )
                    == _contract_runtime_full_commit_value(
                        project_id,
                        queue_rows[index].target_head_before_merge,
                    )
                    for index in range(1, len(queue_rows))
                )
            )
            final_queue_head = (
                _contract_runtime_full_commit_value(
                    project_id,
                    queue_rows[-1].target_head_after_merge,
                )
                if queue_rows
                else ""
            )
            epoch_head = _contract_runtime_full_commit_value(
                project_id,
                epoch.get("current_head"),
            )
            epoch_last_merge = _contract_runtime_full_commit_value(
                project_id,
                epoch.get("last_merge_commit"),
            )
            root = project_service.resolve_project_root(
                project_id,
                None,
                fallback_self=True,
            )
            canonical_root = Path(root).resolve() if root else None
            exact_candidate_relation_verified = bool(
                len(matching_child_rows) == 1
                and str(epoch.get("merge_queue_id") or "").strip()
                == merge_queue_id
                and str(epoch.get("coordination_backlog_id") or "").strip()
                and str(epoch.get("status") or "").strip() == "closed"
                and str(epoch.get("reconcile_state") or "").strip()
                == "reconciled"
                and str(epoch.get("snapshot_id") or "").strip()
                and isinstance(merged_prefix, list)
                and [str(item or "").strip() for item in merged_prefix]
                == queue_item_ids
                and queue_linear
                and final_queue_head == expected_candidate
                and epoch_head == expected_candidate
                and epoch_last_merge == expected_candidate
                and canonical_root is not None
                and _git_head_commit(canonical_root).strip().lower()
                == expected_candidate
                and _git_commit_is_ancestor(
                    canonical_root,
                    final_lane_head,
                    expected_candidate,
                )
            )
    return (
        comparison_base
        if exact_candidate_relation_verified
        and comparison_base != expected_candidate
        else ""
    )


def _contract_runtime_server_comparison_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    expected_candidate_commit: str,
    expected_context: Any | None = None,
) -> dict[str, str]:
    """Resolve worker or combined post-merge comparison authority."""

    if expected_context is not None:
        commit_sha = _contract_runtime_server_candidate_base_commit(
            conn,
            project_id=project_id,
            record=record,
            expected_candidate_commit=expected_candidate_commit,
            expected_context=expected_context,
        )
        source = _QA_WORKER_COMPARISON_BASE_SOURCE
    elif _is_mf_parallel_postmerge_revision(record):
        commit_sha = _contract_runtime_server_postmerge_comparison_base_commit(
            conn,
            project_id=project_id,
            record=record,
            expected_candidate_commit=expected_candidate_commit,
        )
        source = _QA_POSTMERGE_COMPARISON_BASE_SOURCE
    else:
        commit_sha = _contract_runtime_server_candidate_base_commit(
            conn,
            project_id=project_id,
            record=record,
            expected_candidate_commit=expected_candidate_commit,
            expected_context=expected_context,
        )
        source = _QA_WORKER_COMPARISON_BASE_SOURCE
    return (
        {"commit_sha": commit_sha, "source": source}
        if commit_sha
        else {}
    )


def _contract_runtime_server_comparison_base_commit(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    expected_candidate_commit: str,
) -> str:
    return str(
        _contract_runtime_server_comparison_authority(
            conn,
            project_id=project_id,
            record=record,
            expected_candidate_commit=expected_candidate_commit,
        ).get("commit_sha")
        or ""
    )


def _contract_runtime_strip_authority_claims(
    value: Any,
    *,
    field_names: set[str],
    container_names: set[str] | None = None,
    preserve_top_level: set[str] | None = None,
    _depth: int = 0,
) -> Any:
    containers = container_names or set()
    preserved = preserve_top_level or set()
    if isinstance(value, Mapping):
        return {
            str(key): _contract_runtime_strip_authority_claims(
                child,
                field_names=field_names,
                container_names=containers,
                preserve_top_level=preserved,
                _depth=_depth + 1,
            )
            for key, child in value.items()
            if (
                str(key) not in containers
                and (
                    str(key) not in field_names
                    or (_depth == 0 and str(key) in preserved)
                )
            )
        }
    if isinstance(value, list):
        return [
            _contract_runtime_strip_authority_claims(
                child,
                field_names=field_names,
                container_names=containers,
                preserve_top_level=preserved,
                _depth=_depth + 1,
            )
            for child in value
        ]
    return value


def _contract_runtime_bind_authenticated_qa_provenance(
    session: Mapping[str, Any],
    *,
    write: Mapping[str, Any],
    source: str,
    binding_claims: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Replace caller-shaped QA authority with authenticated session facts."""

    sanitized = _contract_runtime_strip_authority_claims(
        write,
        field_names=_CONTRACT_RUNTIME_QA_PROVENANCE_SECURITY_FIELDS,
    )
    effective = dict(sanitized) if isinstance(sanitized, Mapping) else {}
    caller_provenance = (
        write.get("qa_evidence_provenance")
        if isinstance(write.get("qa_evidence_provenance"), Mapping)
        else {}
    )
    canonical_provenance = _contract_runtime_strip_authority_claims(
        caller_provenance,
        field_names=_CONTRACT_RUNTIME_QA_PROVENANCE_SECURITY_FIELDS,
    )
    canonical_provenance = (
        dict(canonical_provenance)
        if isinstance(canonical_provenance, Mapping)
        else {}
    )
    qa_principal = str(session.get("principal_id") or "qa").strip() or "qa"
    qa_session_id = str(session.get("session_id") or "").strip()
    authenticated_binding = {
        "schema_version": "contract_runtime.authenticated_qa_binding.v1",
        "server_derived": True,
        "qa_principal": qa_principal,
        "qa_session_id": qa_session_id,
    }
    authenticated_binding.update(dict(binding_claims or {}))
    canonical_provenance.update(
        {
            "schema_version": "qa_evidence_provenance.v1",
            "source": source,
            "server_derived": True,
            "authorization_source": "qa_session_token_ref",
            "evidence_owner_role": "qa",
            "evidence_owner_actor": qa_principal,
            "evidence_owner_session": qa_session_id,
            "submitter_principal": qa_principal,
            "submitter_session": qa_session_id,
            "observer_impersonation": False,
            "payload_observer_impersonation_explicit": True,
            "parent_materialization_authorized": False,
            "authenticated_qa_binding": authenticated_binding,
        }
    )
    payload = (
        dict(effective.get("payload"))
        if isinstance(effective.get("payload"), Mapping)
        else {}
    )
    payload["observer_impersonation"] = False
    effective.update(
        {
            "actor_session_principal": qa_principal,
            "authorization_source": "qa_session_token_ref",
            "evidence_owner_actor": qa_principal,
            "evidence_owner_role": "qa",
            "evidence_owner_session": qa_session_id,
            "submitter_principal": qa_principal,
            "submitter_session": qa_session_id,
            "observer_impersonation": False,
            "parent_materialization_authorized": False,
            "qa_evidence_provenance": canonical_provenance,
            "payload": payload,
        }
    )
    return effective


_CONTRACT_RUNTIME_NO_PASS_LEDGER_SCHEMA_VERSION = (
    "contract_runtime.external_no_pass_baseline_ledger.v2"
)


def _contract_runtime_authenticated_qa_provenance(
    line: Mapping[str, Any],
) -> bool:
    provenance = (
        line.get("qa_evidence_provenance")
        if isinstance(line.get("qa_evidence_provenance"), Mapping)
        else {}
    )
    binding = (
        provenance.get("authenticated_qa_binding")
        if isinstance(provenance.get("authenticated_qa_binding"), Mapping)
        else {}
    )
    return bool(
        str(line.get("authorization_source") or "")
        == "qa_session_token_ref"
        and line.get("observer_impersonation") is False
        and str(provenance.get("schema_version") or "")
        == "qa_evidence_provenance.v1"
        and provenance.get("server_derived") is True
        and str(provenance.get("authorization_source") or "")
        == "qa_session_token_ref"
        and str(provenance.get("evidence_owner_role") or "") == "qa"
        and provenance.get("observer_impersonation") is False
        and provenance.get("parent_materialization_authorized") is False
        and str(binding.get("schema_version") or "")
        == "contract_runtime.authenticated_qa_binding.v1"
        and binding.get("server_derived") is True
        and (
            binding.get("independent_verification_session_matched") is True
            or binding.get("graph_trace_session_matched") is True
        )
        and str(binding.get("qa_principal") or "").strip()
        and str(binding.get("qa_session_id") or "").strip()
    )


def _contract_runtime_no_pass_requested(line: Mapping[str, Any]) -> bool:
    payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
    test_results = (
        line.get("test_results")
        if isinstance(line.get("test_results"), Mapping)
        else {}
    )
    payload_test_results = (
        payload.get("test_results")
        if isinstance(payload.get("test_results"), Mapping)
        else {}
    )
    return any(
        source.get("no_pass_claim") is True or source.get("no_pass") is True
        for source in (payload, test_results, payload_test_results)
    )


def _contract_runtime_no_pass_graph_scope(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Return the last DB-verified QA graph base/candidate tuple."""

    for line in reversed(
        [
            item
            for item in record.get("completed_lines") or []
            if isinstance(item, Mapping)
        ]
    ):
        if str(line.get("line_id") or "").strip() != "qa_graph_context":
            continue
        if not _contract_runtime_authenticated_qa_provenance(line):
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        evidence = (
            payload.get("graph_trace_evidence")
            if isinstance(payload.get("graph_trace_evidence"), Mapping)
            else {}
        )
        graph_base_commit = str(
            evidence.get("base_commit_sha") or ""
        ).strip().lower()
        comparison_base_commit = str(
            evidence.get("comparison_base_commit_sha") or ""
        ).strip().lower()
        candidate_commit = str(
            evidence.get("candidate_commit_sha")
            or evidence.get("candidate_commit")
            or ""
        ).strip().lower()
        base_commit = comparison_base_commit or graph_base_commit
        line_commit = str(line.get("commit_sha") or "").strip().lower()
        trace_ids = _runtime_context_service_dedupe(
            _runtime_context_service_query_values(
                evidence,
                "verified_trace_ids",
                "trace_ids",
            )
        )
        if not (
            re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", base_commit)
            and re.fullmatch(
                r"[0-9a-f]{40}|[0-9a-f]{64}", candidate_commit
            )
            and (
                not comparison_base_commit
                or (
                    str(evidence.get("graph_basis") or "").strip()
                    == "exact_candidate_snapshot"
                    and graph_base_commit == candidate_commit
                    and comparison_base_commit != candidate_commit
                    and str(
                        evidence.get("graph_snapshot_base_commit_sha") or ""
                    ).strip().lower()
                    == candidate_commit
                    and str(
                        evidence.get("comparison_base_commit_source") or ""
                    ).strip()
                    in _QA_COMPARISON_BASE_SOURCES
                )
            )
            and line_commit == candidate_commit
            and evidence.get("db_verified") is True
            and not list(evidence.get("identity_mismatches") or [])
            and trace_ids
        ):
            continue
        return {
            "base_commit_sha": base_commit,
            "candidate_commit_sha": candidate_commit,
            "graph_trace_ids": trace_ids,
        }
    return {}


def _contract_runtime_failure_identities(value: Any) -> list[str]:
    if not isinstance(value, (list, tuple)):
        return []
    identities = [str(item or "").strip() for item in value]
    if any(not item for item in identities) or len(set(identities)) != len(
        identities
    ):
        return []
    return sorted(identities)


def _contract_runtime_qa_no_pass_ledger_authority(
    line: Mapping[str, Any],
    *,
    record: Mapping[str, Any] | None = None,
    allow_immutable_legacy: bool = False,
) -> dict[str, Any]:
    """Validate one no-PASS line and return its canonical baseline ledger.

    New writes carry the v2 ledger.  The legacy branch is read-only
    compatibility for immutable, server-accepted QA lines; it still requires
    authenticated QA provenance and the exact DB-verified graph commit tuple.
    """

    if not _contract_runtime_authenticated_qa_provenance(line):
        return {}
    provenance = line["qa_evidence_provenance"]
    authenticated_binding = provenance["authenticated_qa_binding"]
    if authenticated_binding.get("independent_verification_session_matched") is not True:
        return {}
    graph_scope = (
        _contract_runtime_no_pass_graph_scope(record)
        if isinstance(record, Mapping)
        else {}
    )
    if not graph_scope:
        return {}
    base_commit = graph_scope["base_commit_sha"]
    candidate_commit = graph_scope["candidate_commit_sha"]
    if str(line.get("commit_sha") or "").strip().lower() != candidate_commit:
        return {}

    payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
    test_results = (
        line.get("test_results")
        if isinstance(line.get("test_results"), Mapping)
        else {}
    )
    verification = (
        line.get("verification")
        if isinstance(line.get("verification"), Mapping)
        else (
            payload.get("verification")
            if isinstance(payload.get("verification"), Mapping)
            else {}
        )
    )
    verification_candidate_new = verification.get(
        "candidate_new_failures",
        verification.get("candidate_specific_new_failures"),
    )
    if not (
        str(line.get("line_id") or "").strip()
        == "qa_independent_verification"
        and str(line.get("actor_role") or "").strip() == "qa"
        and str(line.get("evidence_kind") or "").strip()
        == "independent_verification"
        and str(line.get("status") or "").strip().lower() == "accepted"
        and str(payload.get("schema_version") or "")
        in {
            "qa_independent_verification.v1",
            "mf_parallel.qa_independent_verification.v1",
        }
        and (
            str(payload.get("acceptance_scope") or "")
            == "candidate_regression_and_acceptance_criteria"
            or payload.get("row_scoped_qa_pass") is True
        )
        and str(payload.get("verdict") or "").strip().lower() == "accepted"
        and str(payload.get("full_suite_claim") or "") == "not_claimed"
        and payload.get("candidate_new_failures") == 0
        and test_results.get("candidate_new_failures") == 0
        and verification_candidate_new == 0
        and not list(payload.get("candidate_specific_issues") or [])
        and not list(test_results.get("candidate_specific_issues") or [])
        and not list(verification.get("candidate_specific_issues") or [])
        and payload.get("no_pass_claim") is True
        and payload.get("overall_release_pass_claimed") is False
        and (
            test_results.get("no_pass_claim") is True
            or test_results.get("no_pass") is True
        )
        and test_results.get("passed") is not True
        and test_results.get("overall_release_pass") is not True
        and test_results.get("overall_release_pass_claimed") is False
        and verification.get("no_pass_claim") is True
        and verification.get("overall_release_pass_claimed") is False
        and str(verification.get("verdict") or "").strip().lower()
        == "accepted"
    ):
        return {}
    artifact_refs = (
        line.get("artifact_refs")
        if isinstance(line.get("artifact_refs"), Mapping)
        else {}
    )
    ledger = (
        artifact_refs.get("external_no_pass_baseline_ledger")
        if isinstance(
            artifact_refs.get("external_no_pass_baseline_ledger"), Mapping
        )
        else {}
    )
    if ledger:
        failure_set_authority = _qa_external_no_pass_failure_set_authority(
            ledger
        )
        if not (
            str(ledger.get("schema_version") or "")
            == _CONTRACT_RUNTIME_NO_PASS_LEDGER_SCHEMA_VERSION
            and str(ledger.get("base_commit_sha") or "").strip().lower()
            == base_commit
            and str(ledger.get("candidate_commit_sha") or "").strip().lower()
            == candidate_commit
            and failure_set_authority
            and ledger.get("candidate_new_failures") == 0
            and not list(ledger.get("candidate_specific_issues") or [])
            and ledger.get("no_pass_claim") is True
            and ledger.get("overall_release_pass_claimed") is False
            and list(ledger.get("refs") or [])
        ):
            return {}
        normalized = {
            **dict(ledger),
            "server_normalized": True,
            **failure_set_authority,
        }
        if not failure_set_authority["fixed_base_failure_identities"]:
            normalized.pop("fixed_base_failure_identities", None)
        return normalized

    if not allow_immutable_legacy:
        return {}
    nested_results = (
        payload.get("test_results")
        if isinstance(payload.get("test_results"), Mapping)
        else {}
    )
    if not test_results or stable_sha256(test_results) != stable_sha256(
        nested_results
    ):
        return {}
    base_failures = _contract_runtime_failure_identities(
        test_results.get("baseline_failure_node_ids")
    )
    candidate_failures = _contract_runtime_failure_identities(
        test_results.get("candidate_failure_node_ids")
    )
    base_failed = test_results.get("baseline_failed")
    candidate_failed = test_results.get("candidate_failed")
    base_passed = test_results.get("baseline_passed")
    candidate_passed = test_results.get("candidate_passed")
    if not (
        str(payload.get("base_commit_sha") or "").strip().lower()
        == base_commit
        and str(payload.get("candidate_commit_sha") or "").strip().lower()
        == candidate_commit
        and base_failures
        and base_failures == candidate_failures
        and base_failed == candidate_failed == len(base_failures)
        and isinstance(base_passed, int)
        and not isinstance(base_passed, bool)
        and isinstance(candidate_passed, int)
        and not isinstance(candidate_passed, bool)
        and base_passed > 0
        and candidate_passed > 0
        and payload.get("candidate_new_failures") == 0
        and test_results.get("candidate_new_failures") == 0
        and not list(payload.get("candidate_specific_issues") or [])
        and not list(test_results.get("candidate_specific_issues") or [])
        and not list(test_results.get("baseline_only_failure_node_ids") or [])
        and not list(test_results.get("candidate_only_failure_node_ids") or [])
        and test_results.get("passed") is False
        and test_results.get("overall_release_pass") is False
        and verification.get("candidate_specific_new_failures") == 0
        and str(verification.get("full_suite_claim") or "") == "not_claimed"
    ):
        return {}
    return {
        "schema_version": _CONTRACT_RUNTIME_NO_PASS_LEDGER_SCHEMA_VERSION,
        "server_normalized": True,
        "source": "immutable_authenticated_qa_line+db_verified_qa_graph_context",
        "base_commit_sha": base_commit,
        "candidate_commit_sha": candidate_commit,
        "base_failure_identities": base_failures,
        "candidate_failure_identities": candidate_failures,
        "base_reproduction": {
            "reproduced": len(base_failures),
            "total": len(base_failures),
            "failure_identities": base_failures,
        },
        "candidate_suite_counts": {
            "baseline_known_non_green": len(base_failures),
            "failed": len(candidate_failures),
            "passed": candidate_passed,
        },
        "candidate_new_failures": 0,
        "candidate_specific_issues": [],
        "no_pass_claim": True,
        "overall_release_pass_claimed": False,
        "refs": list(graph_scope["graph_trace_ids"]),
    }


def _contract_runtime_bind_qa_no_pass_ledger_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
) -> dict[str, Any]:
    effective = dict(write)
    if not _contract_runtime_no_pass_requested(effective):
        return effective
    ledger = _contract_runtime_qa_no_pass_ledger_authority(
        effective,
        record=record,
        allow_immutable_legacy=True,
    )
    expected_candidate_commit = _contract_runtime_server_candidate_commit(
        conn,
        project_id=project_id,
        record=record,
    )
    if not ledger or (
        str(ledger.get("candidate_commit_sha") or "").strip().lower()
        != expected_candidate_commit
    ):
        raise GovernanceError(
            "contract_runtime_qa_no_pass_authority_shape_invalid",
            (
                "no-PASS QA requires authenticated exact base/candidate commits, "
                "identical non-green failures or an exact declared parent-only "
                "fixed-base difference, zero candidate-new failures, and no "
                "overall PASS claim"
            ),
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "canonical_ledger_path": (
                    "artifact_refs.external_no_pass_baseline_ledger"
                ),
                "required_schema_version": (
                    _CONTRACT_RUNTIME_NO_PASS_LEDGER_SCHEMA_VERSION
                ),
                "fail_closed": True,
            },
        )
    artifact_refs = (
        dict(effective.get("artifact_refs"))
        if isinstance(effective.get("artifact_refs"), Mapping)
        else {}
    )
    artifact_refs["external_no_pass_baseline_ledger"] = ledger
    effective["artifact_refs"] = artifact_refs
    return effective


def _contract_runtime_bind_qa_independent_verification_authority(
    ctx: RequestContext,
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
) -> dict[str, Any]:
    session = ctx.require_auth(conn)
    if _normalized_contract_runtime_action(session.get("role")) != "qa":
        raise PermissionDeniedError(
            str(session.get("role") or "unknown"),
            "contract_runtime_qa_independent_verification_authority",
            {
                "required_role": "qa",
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "authority_source": "authenticated_qa_session",
            },
        )
    effective = _contract_runtime_bind_authenticated_qa_provenance(
        session,
        write=write,
        source="contract_runtime_qa_independent_verification_binding",
        binding_claims={"independent_verification_session_matched": True},
    )
    if _is_mf_parallel_record_contract_id(
        str(record.get("contract_id") or "")
    ):
        postmerge_independent_verification = bool(
            _is_mf_parallel_postmerge_revision(record)
            and str(write.get("line_id") or "").strip()
            == "qa_independent_verification"
            and str(
                _contract_runtime_next_line(record).get("line_id") or ""
            ).strip()
            == "qa_independent_verification"
        )
        postmerge_identity = (
            _contract_runtime_postmerge_qa_worker_identity_authority(
                conn,
                project_id=project_id,
                record=record,
            )
            if postmerge_independent_verification
            else {}
        )
        if (
            postmerge_independent_verification
            and postmerge_identity.get("verified") is not True
        ):
            raise GovernanceError(
                "contract_runtime_qa_worker_identity_unresolved",
                (
                    "postmerge independent QA requires one persisted, "
                    "server-verified final-lane worker identity"
                ),
                409,
                {
                    "contract_execution_id": str(
                        record.get("contract_execution_id") or ""
                    ),
                    "line_id": str(write.get("line_id") or ""),
                    "identity_status": "blocked",
                    "identity_source_line_id": (
                        "qa_graph_context.postmerge_qa_authority"
                    ),
                    "candidate_count": 0,
                    "blocker_codes": list(
                        postmerge_identity.get("blocker_codes") or []
                    ),
                    "fail_closed": True,
                },
            )
        effective = _contract_runtime_bind_qa_worker_identity_authority(
            conn,
            project_id=project_id,
            record=record,
            write=effective,
            server_identity=(
                postmerge_identity
                if postmerge_independent_verification
                else None
            ),
        )
    return _contract_runtime_bind_qa_no_pass_ledger_authority(
        conn,
        project_id=project_id,
        record=record,
        write=effective,
    )


def _contract_runtime_transient_post_worker_lines(
    record: Mapping[str, Any],
) -> list[Mapping[str, Any]]:
    """Return server-shaped, non-persisting post-worker projection lines."""

    lines: list[Mapping[str, Any]] = []
    for line in record.get("completed_lines") or []:
        if not isinstance(line, Mapping):
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        if (
            str(payload.get("schema_version") or "")
            == "mf_parallel.runtime_context_post_worker_line_projection.v1"
            and str(payload.get("source") or "")
            == "runtime_context_post_worker_timeline_evidence"
            and str(line.get("line_id") or "").strip()
            in {"observer_merge", "observer_reconcile"}
        ):
            lines.append(line)
    return lines


def _contract_runtime_canonical_post_worker_projection(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    required_worker_count: int,
) -> dict[str, Any]:
    """Re-derive an already-projected read model from canonical raw history.

    Public current/guide is allowed to pass its read-only projected record into
    the canonical QA precheck.  Those transient lines have no persisted-line
    acceptance receipt.  Re-read the exact canonical ContractRuntime record,
    project it once on the server, and accept the projected branch only when
    the supplied transient lines are byte-identical to that derivation.
    """

    supplied_lines = _contract_runtime_transient_post_worker_lines(record)
    if not supplied_lines:
        return {}
    execution_id = str(record.get("contract_execution_id") or "").strip()
    if not execution_id:
        return {}
    try:
        canonical = _contract_runtime_store(conn).get(execution_id)
    except (ContractRuntimeError, sqlite3.Error, AttributeError, TypeError):
        return {}
    if not isinstance(canonical, Mapping):
        return {}
    identity_fields = (
        "project_id",
        "backlog_id",
        "contract_execution_id",
        "contract_id",
        "contract_chain_id",
        "parent_contract_execution_id",
        "root_contract_execution_id",
    )
    if any(
        str(canonical.get(field) or "").strip()
        != str(record.get(field) or "").strip()
        for field in identity_fields
    ):
        return {}
    if (
        str(canonical.get("project_id") or "").strip() != project_id
        or _contract_runtime_transient_post_worker_lines(canonical)
    ):
        return {}
    projected_record, runtime_projection = (
        _contract_runtime_apply_mf_parallel_context_projection(
            conn,
            project_id=project_id,
            record=canonical,
            actor_role="qa",
        )
    )
    if not (
        isinstance(projected_record, Mapping)
        and isinstance(runtime_projection, Mapping)
    ):
        return {}
    if not (
        str(runtime_projection.get("status") or "").strip() == "projected"
        and runtime_projection.get("persistence")
        == {
            "mutates_contract_runtime_completed_lines": False,
            "observer_authored_worker_backfill": False,
        }
    ):
        return {}
    canonical_lines = _contract_runtime_transient_post_worker_lines(
        projected_record
    )
    if (
        len(canonical_lines) != len(supplied_lines)
        or [stable_sha256(line) for line in canonical_lines]
        != [stable_sha256(line) for line in supplied_lines]
    ):
        return {}
    projected_merge = _contract_runtime_rev8_two_worker_merge_projection(
        projected_record,
        required_worker_count=required_worker_count,
        conn=conn,
        project_id=project_id,
    )
    if not (
        projected_merge.get("timeline_verified") is True
        and projected_merge.get("authority_verified") is True
        and projected_merge.get("dispatch_lineage_verified") is True
        and projected_merge.get("all_lane_merges_verified") is True
    ):
        return {}
    return {"record": projected_record, "merge": projected_merge}


def _contract_runtime_rev8_postmerge_qa_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Resolve the one combined rev8 target allowed to enter final QA.

    Worker task/session identity remains bound to the final merge lane.  The
    graph candidate and execution root, however, come from the durable target
    ref owner after both lane merges and current-full reconcile.  This keeps a
    final QA session out of both the last worker worktree and a detached
    registered project root.
    """

    if not _is_mf_parallel_postmerge_revision(record):
        return {}

    def blocked(*codes: str) -> dict[str, Any]:
        return {
            "schema_version": (
                "contract_runtime.rev8_postmerge_qa_authority.v1"
            ),
            "status": "blocked",
            "verified": False,
            "server_derived": True,
            "fail_closed": True,
            "blocker_codes": [code for code in codes if code],
        }

    required_worker_count = (
        _contract_runtime_mf_parallel_current_generation_worker_count(
            record,
            conn=conn,
            project_id=project_id,
        )
    )
    merge_record = record
    merge = _contract_runtime_rev8_two_worker_merge_projection(
        record,
        required_worker_count=required_worker_count,
        conn=conn,
        project_id=project_id,
    )
    projected_post_worker_authority = False
    merge_verified = bool(
        merge.get("timeline_verified") is True
        and merge.get("authority_verified") is True
        and merge.get("dispatch_lineage_verified") is True
        and merge.get("all_lane_merges_verified") is True
    )
    if merge_verified:
        canonical_projection = (
            _contract_runtime_canonical_post_worker_projection(
                conn,
                project_id=project_id,
                record=record,
                required_worker_count=required_worker_count,
            )
        )
        if canonical_projection:
            merge_record = canonical_projection["record"]
            merge = canonical_projection["merge"]
            projected_post_worker_authority = True
    else:
        projected_record, runtime_projection = (
            _contract_runtime_apply_mf_parallel_context_projection(
                conn,
                project_id=project_id,
                record=record,
                actor_role="qa",
            )
        )
        projected_merge = (
            _contract_runtime_rev8_two_worker_merge_projection(
                projected_record,
                required_worker_count=required_worker_count,
                conn=conn,
                project_id=project_id,
            )
        )
        if (
            str(runtime_projection.get("status") or "").strip()
            == "projected"
            and runtime_projection.get("persistence")
            == {
                "mutates_contract_runtime_completed_lines": False,
                "observer_authored_worker_backfill": False,
            }
            and projected_merge.get("timeline_verified") is True
            and projected_merge.get("authority_verified") is True
            and projected_merge.get("dispatch_lineage_verified") is True
            and projected_merge.get("all_lane_merges_verified") is True
        ):
            merge_record = projected_record
            merge = projected_merge
            projected_post_worker_authority = True
    merged_commit = str(
        merge.get("merged_commit_sha") or ""
    ).strip().lower()
    runtime_context_id = str(
        merge.get("runtime_context_id") or ""
    ).strip()
    task_id = str(merge.get("task_id") or "").strip()
    parent_task_id = str(merge.get("parent_task_id") or "").strip()
    merge_queue_id = str(
        merge.get("merge_queue_id") or ""
    ).strip()
    queue_item_id = str(merge.get("queue_item_id") or "").strip()
    if not (
        merge.get("timeline_verified") is True
        and merge.get("authority_verified") is True
        and merge.get("dispatch_lineage_verified") is True
        and merge.get("all_lane_merges_verified") is True
        and int(merge.get("lane_merge_count") or 0)
        == required_worker_count
        and runtime_context_id
        and task_id
        and parent_task_id
        and merge_queue_id
        and queue_item_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", merged_commit)
    ):
        return blocked("required_lane_merge_projection_unverified")

    merge_completed_line_index_value = merge.get(
        "merge_completed_line_index"
    )
    dispatch_completed_line_index_value = merge.get(
        "dispatch_completed_line_index"
    )
    merge_completed_line_index = (
        int(merge_completed_line_index_value)
        if isinstance(merge_completed_line_index_value, int)
        and not isinstance(merge_completed_line_index_value, bool)
        else -1
    )
    dispatch_completed_line_index = (
        int(dispatch_completed_line_index_value)
        if isinstance(dispatch_completed_line_index_value, int)
        and not isinstance(dispatch_completed_line_index_value, bool)
        else -1
    )
    if (
        dispatch_completed_line_index < 0
        or merge_completed_line_index <= dispatch_completed_line_index
    ):
        return blocked("observer_reconcile_line_not_unique")
    declared_batch_child = _parallel_branch_allocate_declares_batch_child(
        record
    )
    persisted_reconcile_lines = [
        line
        for line in record.get("completed_lines") or []
        if required_worker_count > 1
        and not declared_batch_child
        and isinstance(line, Mapping)
        and str(line.get("line_id") or "").strip() == "observer_reconcile"
        and str(line.get("actor_role") or "").strip() == "observer"
        and str(line.get("evidence_kind") or "").strip() == "reconcile"
        and str(
            (
                line.get("payload")
                if isinstance(line.get("payload"), Mapping)
                else {}
            ).get("schema_version")
            or ""
        ).strip()
        != "mf_parallel.runtime_context_post_worker_line_projection.v1"
    ]
    persisted_reconcile_line_present = bool(persisted_reconcile_lines)
    persisted_expected_reconcile_receipt = (
        _contract_runtime_close_authority_payload_mapping(
            persisted_reconcile_lines[-1],
            "reconcile_authority",
        )
        if persisted_reconcile_line_present
        else {}
    )
    persisted_receipt_resolution = (
        _contract_runtime_reconcile_receipt_resolution(
            conn,
            project_id=project_id,
            record=record,
            authority=persisted_expected_reconcile_receipt,
        )
        if persisted_reconcile_line_present
        else {}
    )
    persisted_reconcile_receipt_available = (
        persisted_receipt_resolution.get("status")
        in {"current", "corrected"}
    )
    if (
        persisted_reconcile_line_present
        and not persisted_reconcile_receipt_available
    ):
        return blocked("observer_reconcile_receipt_unverified")
    expected_reconcile_receipt = (
        persisted_expected_reconcile_receipt
        if persisted_reconcile_receipt_available
        else _contract_runtime_reconcile_record_authority(
            conn,
            project_id=project_id,
            record=merge_record,
        )
    )
    if persisted_reconcile_receipt_available:
        # Once observer_reconcile is durably accepted, its server-authored
        # receipt is the only authority for final QA.  A canonical transient
        # post-worker projection can still exist for read continuity, but it
        # must never reinterpret that persisted line as a transient
        # runtime_context_post_worker_line_projection payload.
        projected_post_worker_authority = False
    reconcile_runtime_context_id = runtime_context_id
    reconcile_task_id = task_id
    reconcile_parent_task_id = parent_task_id
    reconcile_merge_queue_id = merge_queue_id
    projected_reconcile_authority: dict[str, Any] = {}
    if projected_post_worker_authority:
        projected_reconcile_lines = [
            (index, line)
            for index, line in enumerate(
                merge_record.get("completed_lines") or []
            )
            if index > merge_completed_line_index
            and isinstance(line, Mapping)
            and str(line.get("line_id") or "").strip()
            == "observer_reconcile"
        ]
        if len(projected_reconcile_lines) != 1:
            return blocked("observer_reconcile_line_not_unique")
        reconcile_line_index, reconcile_line = projected_reconcile_lines[0]
        reconcile_payload = (
            reconcile_line.get("payload")
            if isinstance(reconcile_line.get("payload"), Mapping)
            else {}
        )
        projected_reconcile_authority = (
            dict(reconcile_payload.get("reconcile_authority"))
            if isinstance(
                reconcile_payload.get("reconcile_authority"), Mapping
            )
            else {}
        )
        projected_reconcile_line_commit_verified = (
            _contract_runtime_projected_reconcile_line_commit_verified(
                declared_batch_child=declared_batch_child,
                line_commit=reconcile_line.get("commit_sha"),
                merged_commit=merged_commit,
                reconcile_authority=projected_reconcile_authority,
            )
        )
        if not (
            str(reconcile_payload.get("schema_version") or "")
            == "mf_parallel.runtime_context_post_worker_line_projection.v1"
            and str(reconcile_payload.get("source") or "")
            == "runtime_context_post_worker_timeline_evidence"
            and reconcile_payload.get("source_backed") is True
            and reconcile_payload.get("projection_persists_completed_line")
            is False
            and reconcile_payload.get("observer_authored_worker_backfill")
            is False
            and str(reconcile_payload.get("source_ref") or "")
            == str(merge.get("reconcile_source_ref") or "")
            and int(reconcile_payload.get("source_event_id") or 0)
            == int(merge.get("reconcile_event_id") or 0)
            and str(reconcile_line.get("runtime_context_id") or "")
            == runtime_context_id
            and str(reconcile_line.get("task_id") or "") == task_id
            and str(reconcile_line.get("parent_task_id") or "")
            == parent_task_id
            and projected_reconcile_line_commit_verified
            and _contract_runtime_current_full_reconcile_activation_verified(
                projected_reconcile_authority
            )
            and str(
                projected_reconcile_authority.get("merged_commit_sha") or ""
            ).strip().lower()
            == merged_commit
            and str(
                projected_reconcile_authority.get("runtime_context_id") or ""
            ).strip()
            == runtime_context_id
            and str(
                projected_reconcile_authority.get("task_id") or ""
            ).strip()
            == task_id
            and str(
                projected_reconcile_authority.get("parent_task_id") or ""
            ).strip()
            == parent_task_id
            and str(
                projected_reconcile_authority.get("merge_queue_id") or ""
            ).strip()
            == merge_queue_id
        ):
            return blocked("observer_reconcile_receipt_unverified")

        reconcile_acceptance = {
            "db_verified": True,
            "acceptance_ref": str(
                reconcile_payload.get("source_ref") or ""
            ),
            "completed_line_ref": "",
        }
    else:
        receipt_resolution = (
            persisted_receipt_resolution
            if persisted_reconcile_receipt_available
            else _contract_runtime_reconcile_receipt_resolution(
                conn,
                project_id=project_id,
                record=record,
                authority=expected_reconcile_receipt,
            )
        )
        if receipt_resolution.get("status") not in {"current", "corrected"}:
            return blocked("observer_reconcile_receipt_unverified")
        reconcile_line_index = _contract_runtime_close_authority_line_index(
            receipt_resolution.get("line_index")
        )
        reconcile_line = receipt_resolution.get("line") or {}
        reconcile_acceptance = receipt_resolution.get("acceptance") or {}
        persisted_reconcile_receipt = (
            receipt_resolution.get("authority") or {}
        )
        if not (
            reconcile_line_index > merge_completed_line_index
            and reconcile_acceptance.get("db_verified") is True
            and persisted_reconcile_receipt.get("record_verified") is True
            and _contract_runtime_close_authority_hash_matches(
                persisted_reconcile_receipt
            )
            and stable_sha256(persisted_reconcile_receipt)
            == stable_sha256(expected_reconcile_receipt)
            and str(
                persisted_reconcile_receipt.get("merged_commit_sha") or ""
            ).strip().lower()
            == merged_commit
        ):
            return blocked("observer_reconcile_receipt_unverified")
        if persisted_reconcile_receipt_available:
            if not (
                str(
                    persisted_reconcile_receipt.get("project_id") or ""
                ).strip()
                == project_id
                and str(
                    persisted_reconcile_receipt.get("backlog_id") or ""
                ).strip()
                == str(record.get("backlog_id") or "").strip()
                and str(
                    persisted_reconcile_receipt.get(
                        "contract_execution_id"
                    )
                    or ""
                ).strip()
                == str(record.get("contract_execution_id") or "").strip()
                and str(
                    persisted_reconcile_receipt.get("parent_task_id") or ""
                ).strip()
                == parent_task_id
                and persisted_reconcile_receipt.get(
                    "all_lane_merges_verified"
                )
                is True
                and int(
                    persisted_reconcile_receipt.get("lane_merge_count") or 0
                )
                == required_worker_count
                and {
                    str(value or "").strip()
                    for value in persisted_reconcile_receipt.get(
                        "lane_runtime_context_ids"
                    )
                    or []
                    if str(value or "").strip()
                }
                == {
                    str(value or "").strip()
                    for value in merge.get("lane_runtime_context_ids") or []
                    if str(value or "").strip()
                }
                and {
                    str(value or "").strip()
                    for value in persisted_reconcile_receipt.get(
                        "lane_merge_queue_ids"
                    )
                    or []
                    if str(value or "").strip()
                }
                == {
                    str(value or "").strip()
                    for value in merge.get("lane_merge_queue_ids") or []
                    if str(value or "").strip()
                }
                and str(
                    persisted_reconcile_receipt.get("merge_source_ref") or ""
                ).strip()
                == str(merge.get("merge_source_ref") or "").strip()
                and int(
                    persisted_reconcile_receipt.get("merge_event_id") or 0
                )
                == int(merge.get("merge_event_id") or 0)
                and str(
                    persisted_reconcile_receipt.get(
                        "contract_runtime_dispatch_source_ref"
                    )
                    or ""
                ).strip()
                == str(
                    merge.get("contract_runtime_dispatch_source_ref") or ""
                ).strip()
                and persisted_reconcile_receipt.get(
                    "reconcile_event_recorded"
                )
                is True
                and int(
                    persisted_reconcile_receipt.get("reconcile_event_id") or 0
                )
                > int(merge.get("merge_event_id") or 0)
                and str(
                    persisted_reconcile_receipt.get("reconcile_source_ref")
                    or ""
                ).startswith("timeline:")
                and persisted_reconcile_receipt.get(
                    "current_full_reconcile_activation_verified"
                )
                is True
            ):
                return blocked("observer_reconcile_receipt_unverified")
            reconcile_runtime_context_id = str(
                persisted_reconcile_receipt.get("runtime_context_id") or ""
            ).strip()
            reconcile_task_id = str(
                persisted_reconcile_receipt.get("task_id") or ""
            ).strip()
            reconcile_parent_task_id = str(
                persisted_reconcile_receipt.get("parent_task_id") or ""
            ).strip()
            reconcile_merge_queue_id = str(
                persisted_reconcile_receipt.get("merge_queue_id") or ""
            ).strip()
            if not (
                reconcile_runtime_context_id
                in {
                    str(value or "").strip()
                    for value in merge.get("lane_runtime_context_ids") or []
                }
                and reconcile_merge_queue_id
                in {
                    str(value or "").strip()
                    for value in merge.get("lane_merge_queue_ids") or []
                }
                and str(
                    persisted_reconcile_receipt.get("reconcile_task_id") or ""
                ).strip()
                == reconcile_task_id
                and str(
                    persisted_reconcile_receipt.get(
                        "reconcile_runtime_context_id"
                    )
                    or ""
                ).strip()
                == reconcile_runtime_context_id
            ):
                return blocked("observer_reconcile_receipt_unverified")
        elif not (
            str(
                persisted_reconcile_receipt.get("runtime_context_id") or ""
            ).strip()
            == runtime_context_id
            and str(
                persisted_reconcile_receipt.get("task_id") or ""
            ).strip()
            == task_id
            and str(
                persisted_reconcile_receipt.get("parent_task_id") or ""
            ).strip()
            == parent_task_id
            and str(
                persisted_reconcile_receipt.get("merge_queue_id") or ""
            ).strip()
            == merge_queue_id
        ):
            return blocked("observer_reconcile_receipt_unverified")

    reconcile_merge = dict(merge)
    if (
        reconcile_runtime_context_id,
        reconcile_task_id,
        reconcile_parent_task_id,
        reconcile_merge_queue_id,
    ) != (
        runtime_context_id,
        task_id,
        parent_task_id,
        merge_queue_id,
    ):
        reconcile_merge.update(
            {
                "aggregate_final_merge_identity": {
                    "runtime_context_id": runtime_context_id,
                    "task_id": task_id,
                    "parent_task_id": parent_task_id,
                    "merge_queue_id": merge_queue_id,
                    "queue_item_id": queue_item_id,
                },
                "runtime_context_id": reconcile_runtime_context_id,
                "task_id": reconcile_task_id,
                "parent_task_id": reconcile_parent_task_id,
                "merge_queue_id": reconcile_merge_queue_id,
                "reconcile_line_instance_id": (
                    f"runtime_context:{reconcile_runtime_context_id}"
                ),
                "reconcile_lane_identity_source": (
                    "ContractRuntime.completed_lines.observer_reconcile."
                    "reconcile_authority"
                ),
            }
        )

    verified_batch_child = (
        _parallel_branch_allocate_verified_batch_child_lineage_authority(
            conn,
            project_id=project_id,
            record=record,
        )
        if declared_batch_child
        else {}
    )
    if declared_batch_child and not (
        verified_batch_child.get("db_verified") is True
        and verified_batch_child.get("server_derived") is True
        and str(verified_batch_child.get("project_id") or "").strip()
        == project_id
        and str(
            verified_batch_child.get("child_backlog_id") or ""
        ).strip()
        == str(record.get("backlog_id") or "").strip()
        and str(verified_batch_child.get("child_task_id") or "").strip()
        == task_id
        and str(verified_batch_child.get("merge_queue_id") or "").strip()
        == merge_queue_id
        and str(verified_batch_child.get("queue_item_id") or "").strip()
        == queue_item_id
        and str(verified_batch_child.get("batch_id") or "").strip()
        and str(verified_batch_child.get("authority_hash") or "")
        == stable_sha256(
            {
                key: value
                for key, value in verified_batch_child.items()
                if key != "authority_hash"
            }
        )
    ):
        return blocked("batch_child_lineage_unverified")

    terminal_current_full = (
        projected_reconcile_authority
        if projected_post_worker_authority
        else expected_reconcile_receipt.get(
            "terminal_current_full_reconcile_authority"
        )
        if isinstance(
            expected_reconcile_receipt.get(
                "terminal_current_full_reconcile_authority"
            ),
            Mapping,
        )
        else {}
    )
    terminal_commit = str(
        terminal_current_full.get("reconciled_commit_sha") or ""
    ).strip().lower()
    batch_terminal_current_full_verified = bool(
        verified_batch_child
        and _contract_runtime_current_full_reconcile_activation_verified(
            terminal_current_full
        )
        and re.fullmatch(
            r"[0-9a-f]{40}|[0-9a-f]{64}", terminal_commit
        )
        and str(terminal_current_full.get("project_id") or "").strip()
        == project_id
        and str(terminal_current_full.get("backlog_id") or "").strip()
        == str(record.get("backlog_id") or "").strip()
        and str(
            terminal_current_full.get("contract_execution_id") or ""
        ).strip()
        == str(record.get("contract_execution_id") or "").strip()
        and str(
            terminal_current_full.get("runtime_context_id") or ""
        ).strip()
        == runtime_context_id
        and str(terminal_current_full.get("task_id") or "").strip()
        == task_id
        and str(
            terminal_current_full.get("parent_task_id") or ""
        ).strip()
        == parent_task_id
        and str(
            terminal_current_full.get("merge_queue_id") or ""
        ).strip()
        == merge_queue_id
        and str(
            terminal_current_full.get("merged_commit_sha") or ""
        ).strip().lower()
        == merged_commit
        and str(
            terminal_current_full.get("active_snapshot_commit") or ""
        ).strip().lower()
        == terminal_commit
        and str(
            terminal_current_full.get("canonical_head_commit")
            or terminal_current_full.get("current_canonical_commit_sha")
            or ""
        ).strip().lower()
        == terminal_commit
        and str(
            terminal_current_full.get("reconcile_source_ref") or ""
        ).strip()
        == str(
            expected_reconcile_receipt.get("reconcile_source_ref") or ""
        ).strip()
        and int(terminal_current_full.get("reconcile_event_id") or 0)
        == int(expected_reconcile_receipt.get("reconcile_event_id") or 0)
        and str(
            terminal_current_full.get("target_project_root") or ""
        ).strip()
    )
    matching_contexts: dict[str, Any] = {}
    reconcile_matching_contexts: dict[str, Any] = {}
    for dispatch_line in record.get("completed_lines") or []:
        if not isinstance(dispatch_line, Mapping) or str(
            dispatch_line.get("line_id") or ""
        ).strip() != "observer_dispatch_bounded_workers":
            continue
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=dispatch_line,
        ):
            identity = _contract_runtime_context_identity(context)
            if identity == (runtime_context_id, task_id, parent_task_id):
                matching_contexts[runtime_context_id] = context
            if (
                identity
                == (
                    reconcile_runtime_context_id,
                    reconcile_task_id,
                    reconcile_parent_task_id,
                )
                and str(
                    getattr(context, "merge_queue_id", "") or ""
                ).strip()
                == reconcile_merge_queue_id
            ):
                reconcile_matching_contexts[
                    reconcile_runtime_context_id
                ] = context
    if len(matching_contexts) != 1:
        return blocked("final_merge_runtime_context_unresolved")
    context = next(iter(matching_contexts.values()))
    if len(reconcile_matching_contexts) != 1:
        return blocked("observer_reconcile_receipt_unverified")
    reconcile_context = next(iter(reconcile_matching_contexts.values()))

    from .parallel_branch_runtime import (
        _git_target_owner_alignment_evidence,
        _git_target_ref_owning_worktree,
        list_merge_queue_items,
    )

    queue_matches = [
        item
        for item in list_merge_queue_items(
            conn,
            project_id,
            merge_queue_id,
        )
        if str(item.task_id or "").strip() == task_id
    ]
    if len(queue_matches) != 1:
        return blocked("final_merge_queue_item_not_unique")
    queue_item = queue_matches[0]
    target_ref = str(queue_item.target_ref or "").strip()
    if not (
        str(queue_item.queue_item_id or "").strip() == queue_item_id
        and str(queue_item.backlog_id or "").strip()
        == str(record.get("backlog_id") or "").strip()
        and str(queue_item.merge_queue_id or "").strip() == merge_queue_id
        and str(queue_item.status or "").strip() == "merged"
        and target_ref
        and str(queue_item.merge_commit or "").strip().lower()
        == merged_commit
        and str(queue_item.target_head_after_merge or "").strip().lower()
        == merged_commit
    ):
        return blocked("final_merge_queue_item_mismatch")

    worker_root = str(getattr(context, "worktree_path", "") or "").strip()
    if not worker_root:
        return blocked("final_merge_worker_root_missing")
    target_owner, target_owner_source = _git_target_ref_owning_worktree(
        Path(worker_root),
        target_ref=target_ref,
        timeout_seconds=10,
    )
    if target_owner is None:
        return blocked("target_ref_owner_unresolved")

    timeline_events = _runtime_context_service_timeline_events(
        conn,
        project_id=project_id,
        task_id=reconcile_task_id,
        backlog_id=str(record.get("backlog_id") or ""),
    )
    reconciled_merge = _contract_runtime_completed_merge_reconcile_authority(
        conn,
        project_id=project_id,
        record=record,
        context=reconcile_context,
        timeline_events=timeline_events,
        merge=reconcile_merge,
    )
    if not (
        int(reconciled_merge.get("reconcile_event_id") or 0)
        > int(merge.get("merge_event_id") or 0)
        and str(reconciled_merge.get("reconcile_source_ref") or "").startswith(
            "timeline:"
        )
    ):
        return blocked("postmerge_reconcile_event_unverified")
    if declared_batch_child and not batch_terminal_current_full_verified:
        return blocked("batch_terminal_current_full_unverified")

    shared_batch_verified = (
        _contract_runtime_shared_batch_reconcile_activation_verified(
            reconciled_merge
        )
        or _contract_runtime_shared_batch_postmerge_qa_activation_verified(
            reconciled_merge
        )
    )
    shared_batch = (
        reconciled_merge.get("shared_batch_reconcile_authority")
        if isinstance(
            reconciled_merge.get("shared_batch_reconcile_authority"),
            Mapping,
        )
        else {}
    )
    qa_candidate_commit = (
        str(reconciled_merge.get("reconciled_commit_sha") or "")
        .strip()
        .lower()
        if shared_batch_verified
        else (
            terminal_commit
            if batch_terminal_current_full_verified
            else merged_commit
        )
    )
    dispatch_source_ref = str(
        merge.get("contract_runtime_dispatch_source_ref") or ""
    ).strip()
    if shared_batch_verified and not (
        _contract_runtime_current_full_reconcile_activation_verified(
            reconciled_merge
        )
        and re.fullmatch(
            r"[0-9a-f]{40}|[0-9a-f]{64}", qa_candidate_commit
        )
        and str(shared_batch.get("final_head_commit") or "")
        .strip()
        .lower()
        == qa_candidate_commit
        and queue_item_id
        in {
            str(item or "").strip()
            for item in shared_batch.get("ordered_queue_item_ids") or []
        }
        and dispatch_source_ref
        in {
            str(item or "").strip()
            for item in shared_batch.get("child_contract_dispatch_refs") or []
        }
        and str(reconciled_merge.get("merged_commit_sha") or "")
        .strip()
        .lower()
        == merged_commit
        and str(reconciled_merge.get("runtime_context_id") or "").strip()
        == runtime_context_id
        and str(reconciled_merge.get("task_id") or "").strip() == task_id
        and str(
            reconciled_merge.get("parent_task_id") or ""
        ).strip()
        == parent_task_id
        and str(reconciled_merge.get("merge_queue_id") or "").strip()
        == merge_queue_id
    ):
        return blocked("shared_batch_final_reconcile_unverified")

    target_alignment = _git_target_owner_alignment_evidence(
        target_owner,
        target_ref=target_ref,
        merge_commit=qa_candidate_commit,
        timeout_seconds=10,
    )
    if not (
        target_owner_source == "git_worktree_target_ref_owner"
        and target_alignment.get("passed") is True
        and str(target_alignment.get("head_commit") or "").strip().lower()
        == qa_candidate_commit
        and str(target_alignment.get("target_commit") or "").strip().lower()
        == qa_candidate_commit
        and target_alignment.get("index_clean") is True
        and target_alignment.get("worktree_clean") is True
    ):
        return blocked("target_ref_owner_not_clean_and_aligned")

    current_full = (
        dict(reconciled_merge)
        if shared_batch_verified
        else (
            dict(terminal_current_full)
            if batch_terminal_current_full_verified
            else _contract_runtime_current_full_reconcile_authority_from_merge(
                conn,
                project_id=project_id,
                record=record,
                merge=reconcile_merge,
                reconcile=reconciled_merge,
                target_project_root_override=str(target_owner),
            )
        )
    )
    if not (
        _contract_runtime_current_full_reconcile_activation_verified(current_full)
        and str(current_full.get("merged_commit_sha") or "").strip().lower()
        == merged_commit
        and str(current_full.get("reconciled_commit_sha") or "").strip().lower()
        == qa_candidate_commit
        and str(current_full.get("active_snapshot_commit") or "").strip().lower()
        == qa_candidate_commit
        and str(current_full.get("canonical_head_commit") or "")
        .strip()
        .lower()
        == qa_candidate_commit
        and str(current_full.get("target_project_root") or "").strip()
        == str(target_owner)
        and str(current_full.get("runtime_context_id") or "").strip()
        == reconcile_runtime_context_id
        and str(current_full.get("task_id") or "").strip()
        == reconcile_task_id
        and str(current_full.get("parent_task_id") or "").strip()
        == reconcile_parent_task_id
        and str(current_full.get("merge_queue_id") or "").strip()
        == reconcile_merge_queue_id
    ):
        return blocked("current_full_active_snapshot_unverified")

    contract_execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    if not contract_execution_id:
        return blocked("combined_qa_contract_execution_identity_mismatch")
    combined_qa_graph_trace_scope = (
        parent_task_id == contract_execution_id
    )
    qa_graph_trace_task_id = (
        contract_execution_id
        if combined_qa_graph_trace_scope
        else task_id
    )
    qa_graph_trace_task_source = (
        "ContractRuntime.contract_execution_id"
        if combined_qa_graph_trace_scope
        else "ContractRuntime.final_lane_task_id"
    )
    if not qa_graph_trace_task_id:
        return blocked("postmerge_qa_graph_trace_task_identity_unverified")

    authority = {
        "schema_version": "contract_runtime.rev8_postmerge_qa_authority.v1",
        "source": (
            "ContractRuntime.required_lane_merge+"
            "parallel_branch_merge_queue_items+git_target_ref_owner+"
            "graph_current_full_reconcile_provenance"
        ),
        "status": "verified",
        "verified": True,
        "server_derived": True,
        "db_verified": True,
        "live_verified": True,
        "graph_reconciled": True,
        "active_snapshot_verified": True,
        "fail_closed": True,
        "project_id": project_id,
        "backlog_id": str(record.get("backlog_id") or ""),
        "contract_execution_id": contract_execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        # The merge/reconcile authority above remains bound to the final
        # worker lane.  The post-merge QA graph round is a combined review of
        # the parent ContractRuntime execution, so its persisted graph-query
        # rows are deliberately scoped to the CEX task instead of that final
        # lane's task.  Persist both identities explicitly; never infer this
        # distinction from caller claims.
        "qa_graph_trace_task_id": qa_graph_trace_task_id,
        "qa_graph_trace_task_source": qa_graph_trace_task_source,
        "merge_queue_id": merge_queue_id,
        "queue_item_id": queue_item_id,
        "reconcile_runtime_context_id": reconcile_runtime_context_id,
        "reconcile_task_id": reconcile_task_id,
        "reconcile_parent_task_id": reconcile_parent_task_id,
        "reconcile_merge_queue_id": reconcile_merge_queue_id,
        "target_ref": target_ref,
        "target_project_root": str(target_owner),
        "target_root_source": target_owner_source,
        "candidate_commit_sha": qa_candidate_commit,
        "merged_commit_sha": merged_commit,
        "comparison_lineage_merge_commit_sha": merged_commit,
        "qa_candidate_commit_source": (
            "shared_batch_final_reconcile"
            if shared_batch_verified
            else (
                "verified_batch_child_terminal_current_full"
                if batch_terminal_current_full_verified
                else "standalone_final_merge"
            )
        ),
        "reconciled_commit_sha": str(
            current_full.get("reconciled_commit_sha") or ""
        ),
        "canonical_head_commit": str(
            current_full.get("canonical_head_commit") or ""
        ),
        "target_ref_head_commit": str(
            target_alignment.get("target_commit") or ""
        ),
        "target_ref_owner_head_commit": str(
            target_alignment.get("head_commit") or ""
        ),
        "merge_source_ref": str(merge.get("merge_source_ref") or ""),
        "merge_event_id": int(merge.get("merge_event_id") or 0),
        "reconcile_source_ref": str(
            current_full.get("reconcile_source_ref") or ""
        ),
        "reconcile_event_id": int(
            current_full.get("reconcile_event_id") or 0
        ),
        "active_snapshot_id": str(
            current_full.get("active_snapshot_id") or ""
        ),
        "active_snapshot_commit": str(
            current_full.get("active_snapshot_commit") or ""
        ),
        "reconcile_snapshot_id": str(
            current_full.get("reconcile_snapshot_id") or ""
        ),
        "reconcile_acceptance_ref": str(
            reconcile_acceptance.get("acceptance_ref") or ""
        ),
        "reconcile_completed_line_ref": str(
            reconcile_acceptance.get("completed_line_ref") or ""
        ),
        "blocker_codes": [],
    }
    if shared_batch_verified:
        authority["shared_batch_reconcile_authority"] = dict(shared_batch)
    if batch_terminal_current_full_verified:
        authority["batch_terminal_target_owner_authority"] = {
            "schema_version": (
                "contract_runtime.batch_terminal_target_owner_authority.v1"
            ),
            "source": (
                "verified_batch_child_lineage+"
                "observer_reconcile_receipt.terminal_current_full"
            ),
            "server_derived": True,
            "db_verified": True,
            "batch_id": str(
                verified_batch_child.get("batch_id") or ""
            ).strip(),
            "queue_item_id": queue_item_id,
            "child_merged_commit_sha": merged_commit,
            "terminal_reconciled_commit_sha": qa_candidate_commit,
            "active_snapshot_id": str(
                current_full.get("active_snapshot_id") or ""
            ).strip(),
            "reconcile_source_ref": str(
                current_full.get("reconcile_source_ref") or ""
            ).strip(),
            "batch_child_lineage_authority_hash": str(
                verified_batch_child.get("authority_hash") or ""
            ).strip(),
            "terminal_current_full_authority_hash": str(
                current_full.get("authority_hash") or ""
            ).strip(),
        }
        authority["batch_terminal_target_owner_authority"][
            "authority_hash"
        ] = stable_sha256(
            authority["batch_terminal_target_owner_authority"]
        )
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _contract_runtime_bind_qa_graph_authority(
    ctx: RequestContext,
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    body: Mapping[str, Any],
    policy: Mapping[str, Any],
) -> dict[str, Any]:
    requested_trace_ids = _contract_runtime_requested_trace_ids(body, policy)
    identity = _contract_runtime_server_line_identity(record)
    rev8_postmerge_qa = bool(
        _is_mf_parallel_postmerge_revision(record)
        and str(write.get("line_id") or "").strip() == "qa_graph_context"
    )
    postmerge_authority = (
        _contract_runtime_rev8_postmerge_qa_authority(
            conn,
            project_id=project_id,
            record=record,
        )
        if rev8_postmerge_qa
        else {}
    )
    if rev8_postmerge_qa and postmerge_authority.get("verified") is not True:
        raise GovernanceError(
            "contract_runtime_rev8_postmerge_qa_authority_required",
            (
                "rev8 final QA requires one verified combined merge target, "
                "current-full reconcile, and active graph snapshot"
            ),
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "authority_status": str(
                    postmerge_authority.get("status") or "missing"
                ),
                "blocker_codes": list(
                    postmerge_authority.get("blocker_codes") or []
                ),
                "fail_closed": True,
            },
        )
    if postmerge_authority.get("verified") is True:
        identity = {
            "runtime_context_id": str(
                postmerge_authority.get("runtime_context_id") or ""
            ),
            "task_id": str(postmerge_authority.get("task_id") or ""),
            "parent_task_id": str(
                postmerge_authority.get("parent_task_id") or ""
            ),
            "identity_status": "resolved",
            "identity_source_line_id": "observer_reconcile",
        }
        assigned_root = {
            "status": "resolved",
            "target_project_root": str(
                postmerge_authority.get("target_project_root") or ""
            ),
        }
    else:
        assigned_root = _contract_runtime_assigned_target_project_root(
            conn,
            project_id=project_id,
            record=record,
            identity=identity,
        )
    canonical_target_project_root = str(
        assigned_root.get("target_project_root") or ""
    ).strip()
    if not canonical_target_project_root:
        raise GovernanceError(
            "contract_runtime_target_project_root_required",
            "bounded QA requires one assigned target_project_root from trusted dispatch identity",
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "runtime_context_id": identity.get("runtime_context_id") or "",
                "task_id": identity.get("task_id") or "",
                "root_resolution_status": assigned_root.get("status") or "missing",
                "candidate_roots": assigned_root.get("candidate_roots") or [],
            },
        )
    session = ctx.require_auth(conn)
    if _normalized_contract_runtime_action(session.get("role")) != "qa":
        raise PermissionDeniedError(
            str(session.get("role") or "unknown"),
            "contract_runtime_qa_graph_authority",
            {
                "required_role": "qa",
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "authority_source": "authenticated_qa_session",
            },
        )
    expected_candidate_commit = str(
        postmerge_authority.get("candidate_commit_sha") or ""
    ).strip().lower()
    if not expected_candidate_commit:
        expected_candidate_commit = _contract_runtime_server_candidate_commit(
            conn,
            project_id=project_id,
            record=record,
        )
    if not re.fullmatch(
        r"[0-9a-f]{40}|[0-9a-f]{64}", expected_candidate_commit
    ):
        raise GovernanceError(
            "contract_runtime_candidate_commit_required",
            "bounded QA requires a preceding trusted full candidate commit",
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "candidate_commit_sha": expected_candidate_commit,
            },
        )
    expected_graph_trace_task_id = str(identity.get("task_id") or "").strip()
    if postmerge_authority.get("verified") is True:
        contract_execution_id = str(
            record.get("contract_execution_id") or ""
        ).strip()
        expected_graph_trace_task_id = str(
            postmerge_authority.get("qa_graph_trace_task_id") or ""
        ).strip()
        trace_task_source = str(
            postmerge_authority.get("qa_graph_trace_task_source") or ""
        ).strip()
        combined_qa_graph_trace_scope = (
            str(identity.get("parent_task_id") or "").strip()
            == contract_execution_id
        )
        combined_trace_scope_verified = bool(
            combined_qa_graph_trace_scope
            and expected_graph_trace_task_id == contract_execution_id
            and trace_task_source
            == "ContractRuntime.contract_execution_id"
        )
        final_lane_trace_scope_verified = bool(
            not combined_qa_graph_trace_scope
            and expected_graph_trace_task_id
            == str(identity.get("task_id") or "").strip()
            and expected_graph_trace_task_id
            == str(postmerge_authority.get("task_id") or "").strip()
            and trace_task_source == "ContractRuntime.final_lane_task_id"
        )
        if not (
            contract_execution_id
            and str(
                postmerge_authority.get("contract_execution_id") or ""
            ).strip()
            == contract_execution_id
            and (
                combined_trace_scope_verified
                or final_lane_trace_scope_verified
            )
        ):
            raise GovernanceError(
                "contract_runtime_rev8_postmerge_qa_authority_required",
                (
                    "rev8 final QA requires one server-derived combined "
                    "ContractRuntime graph-trace task identity"
                ),
                409,
                {
                    "contract_execution_id": contract_execution_id,
                    "line_id": str(write.get("line_id") or ""),
                    "authority_status": "blocked",
                    "blocker_codes": [
                        "postmerge_qa_graph_trace_task_identity_unverified"
                    ],
                    "fail_closed": True,
                },
            )

    evidence = _runtime_context_service_qa_graph_trace_refs(
        conn,
        project_id=project_id,
        explicit_trace_ids=requested_trace_ids,
        target_project_root=canonical_target_project_root,
        expected_backlog_id=str(record.get("backlog_id") or ""),
        expected_task_id=expected_graph_trace_task_id,
        expected_candidate_commit_sha=expected_candidate_commit,
        expected_qa_principal=str(session.get("principal_id") or ""),
        expected_qa_session_id=str(session.get("session_id") or ""),
        require_complete_authority=True,
        strict_bounded_qa=True,
    )
    evidence = dict(evidence)
    evidence = _contract_runtime_strip_authority_claims(
        evidence,
        field_names=set(),
        container_names=_CONTRACT_RUNTIME_QA_AUTHORITY_CONTAINERS,
    )
    evidence = dict(evidence) if isinstance(evidence, Mapping) else {}
    identity_mismatches = [
        dict(item)
        for item in evidence.get("identity_mismatches") or []
        if isinstance(item, Mapping)
    ]
    if identity_mismatches:
        raise GovernanceError(
            "contract_runtime_qa_graph_trace_identity_mismatch",
            "bounded QA graph trace identity does not match trusted runtime authority",
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": str(write.get("line_id") or ""),
                "identity_mismatches": identity_mismatches,
                "qa_graph_trace_db_evidence": evidence,
                "fail_closed": True,
            },
        )
    if evidence.get("graph_basis"):
        _qa_validate_candidate_review_claims(body, evidence)
    if (
        str(evidence.get("graph_basis") or "").strip()
        == "exact_candidate_snapshot"
        and evidence.get("comparison_authority_required") is True
        and _contract_runtime_full_commit_value(
            project_id,
            evidence.get("base_commit_sha"),
        )
        == expected_candidate_commit
    ):
        canonical_authority = _contract_runtime_server_comparison_authority(
            conn,
            project_id=project_id,
            record=record,
            expected_candidate_commit=expected_candidate_commit,
        )
        canonical_base_commit = str(
            canonical_authority.get("commit_sha") or ""
        )
        persisted_base_commit = _contract_runtime_full_commit_value(
            project_id,
            evidence.get("comparison_base_commit_sha"),
        )
        expected_base_source = str(canonical_authority.get("source") or "")
        persisted_base_source = str(
            evidence.get("comparison_base_commit_source") or ""
        ).strip()
        comparison_mismatches: list[dict[str, Any]] = []
        if not canonical_base_commit:
            comparison_mismatches.append(
                {
                    "field": "comparison_base_commit_sha",
                    "expected": "current trusted ContractRuntime comparison base",
                    "actual": persisted_base_commit,
                }
            )
        elif persisted_base_commit != canonical_base_commit:
            comparison_mismatches.append(
                {
                    "field": "comparison_base_commit_sha",
                    "expected": canonical_base_commit,
                    "actual": persisted_base_commit,
                }
            )
        if persisted_base_source != expected_base_source:
            comparison_mismatches.append(
                {
                    "field": "comparison_base_commit_source",
                    "expected": expected_base_source,
                    "actual": persisted_base_source,
                }
            )
        if comparison_mismatches:
            raise GovernanceError(
                "contract_runtime_qa_graph_trace_identity_mismatch",
                (
                    "bounded QA comparison base does not match current trusted "
                    "runtime authority"
                ),
                409,
                {
                    "contract_execution_id": str(
                        record.get("contract_execution_id") or ""
                    ),
                    "line_id": str(write.get("line_id") or ""),
                    "identity_mismatches": comparison_mismatches,
                    "qa_graph_trace_db_evidence": evidence,
                    "comparison_authority_required": True,
                    "fail_closed": True,
                },
            )
        evidence.update(
            {
                "exact_candidate_snapshot_commit_sha": expected_candidate_commit,
                "graph_snapshot_base_commit_sha": expected_candidate_commit,
            }
        )
    evidence.update(
        {
            "contract_execution_id": str(
                record.get("contract_execution_id") or ""
            ),
            # Postmerge graph traces deliberately use the combined CEX task
            # and may therefore be recorded through a reconcile lane that is
            # not the final merge lane.  Keep graph task scope from the trace,
            # but freeze worker runtime/parent identity from the verified
            # postmerge ticket.  This is the two-scope contract consumed by
            # independent QA; a trace-local runtime must not override it.
            "runtime_context_id": str(
                postmerge_authority.get("runtime_context_id")
                if postmerge_authority.get("verified") is True
                else evidence.get("runtime_context_id")
                or identity["runtime_context_id"]
                or ""
            ),
            "parent_task_id": str(
                postmerge_authority.get("parent_task_id")
                if postmerge_authority.get("verified") is True
                else evidence.get("parent_task_id")
                or identity["parent_task_id"]
                or ""
            ),
        }
    )
    if postmerge_authority.get("verified") is True:
        evidence["postmerge_qa_authority"] = dict(postmerge_authority)
    evidence["authority_hash"] = stable_sha256(evidence)

    authority_key = str(policy.get("authority_object_path") or "").split(".", 1)[-1]
    sanitized = _contract_runtime_strip_authority_claims(
        write,
        field_names=_CONTRACT_RUNTIME_QA_AUTHORITY_FIELDS,
        container_names=_CONTRACT_RUNTIME_QA_AUTHORITY_CONTAINERS,
        preserve_top_level=_CONTRACT_RUNTIME_AUTHORITY_TOP_LEVEL_FIELDS,
    )
    sanitized = dict(sanitized) if isinstance(sanitized, Mapping) else {}
    raw_payload = (
        sanitized.get("payload")
        if isinstance(sanitized.get("payload"), Mapping)
        else {}
    )
    payload = dict(raw_payload)
    payload = dict(payload) if isinstance(payload, Mapping) else {}
    payload["graph_trace_ids"] = list(requested_trace_ids)
    payload["graph_query_trace_ids"] = list(requested_trace_ids)
    payload[authority_key] = evidence

    effective = sanitized
    effective["payload"] = payload
    effective["graph_trace_ids"] = list(requested_trace_ids)
    effective["graph_query_trace_ids"] = list(requested_trace_ids)
    # The graph authority above is bound to the authenticated QA principal and
    # session as well as the persisted graph-query rows.  Rebuild provenance
    # from that trusted context instead of retaining caller-shaped ownership or
    # authorization claims.  The opaque QA-session ref is transport state in
    # the managed MCP process; it is not itself accepted as caller evidence.
    effective = _contract_runtime_bind_authenticated_qa_provenance(
        session,
        write=effective,
        source="contract_runtime_qa_graph_authority_binding",
        binding_claims={"graph_trace_session_matched": True},
    )
    # The candidate commit is authenticated by the bounded QA session and the
    # persisted graph-query rows above.  Persist it at the canonical top level
    # as well as inside graph_trace_evidence so later no-PASS and merge-round
    # resolvers never depend on a caller supplying the same identity twice.
    effective["commit_sha"] = expected_candidate_commit
    for field in ("runtime_context_id", "task_id", "parent_task_id"):
        value = str(evidence.get(field) or identity.get(field) or "").strip()
        if value:
            effective[field] = value
    return effective


def _contract_runtime_trusted_merge_projection(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    # Transient post-worker projection rows are read-model evidence, not
    # canonical line identity.  When they are present, resolve the canonical
    # record from the ContractRuntime store; caller-copyable projection
    # markers can never authorize filtering a persisted line.
    transient_projection_present = any(
        isinstance(line, Mapping)
        and isinstance(line.get("payload"), Mapping)
        and str(line.get("payload", {}).get("schema_version") or "")
        == "mf_parallel.runtime_context_post_worker_line_projection.v1"
        and line.get("payload", {}).get(
            "projection_persists_completed_line"
        )
        is False
        for line in record.get("completed_lines") or []
    )
    projection_record = dict(record)
    if transient_projection_present:
        execution_id = str(
            record.get("contract_execution_id") or ""
        ).strip()
        try:
            stored_record = _contract_runtime_store(conn).get(
                execution_id
            )
        except (ContractRuntimeError, KeyError, TypeError, ValueError):
            stored_record = {}
        canonical_scope_verified = bool(
            stored_record
            and execution_id
            and str(
                stored_record.get("contract_execution_id") or ""
            ).strip()
            == execution_id
            and str(stored_record.get("project_id") or "").strip()
            == str(record.get("project_id") or "").strip()
            and str(stored_record.get("backlog_id") or "").strip()
            == str(record.get("backlog_id") or "").strip()
        )
        if not canonical_scope_verified:
            return {
                "timeline_verified": False,
                "identity_mismatches": [
                    {
                        "field": "transient_projection_canonical_record",
                        "expected": (
                            "one DB-backed ContractRuntime record with exact "
                            "project/backlog/execution scope"
                        ),
                        "actual": "missing_or_scope_mismatch",
                    }
                ],
            }
        projection_record = dict(stored_record)
    expected_identity = _contract_runtime_server_line_identity(
        projection_record
    )
    if expected_identity.get("identity_status") == "ambiguous":
        return {
            "timeline_verified": False,
            "identity_mismatches": [
                {
                    "field": "server_line_identity",
                    "expected": "one coherent runtime_context_id/task_id tuple",
                    "actual": "ambiguous",
                    "source_line_id": expected_identity.get(
                        "identity_source_line_id"
                    )
                    or "",
                }
            ],
        }
    candidates: list[dict[str, Any]] = []
    dispatch_lines = [
        line
        for line in projection_record.get("completed_lines") or []
        if isinstance(line, Mapping)
        and str(line.get("line_id") or "").strip()
        == "observer_dispatch_bounded_workers"
    ]
    for dispatch_line in dispatch_lines:
        contexts = _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=projection_record,
            line=dispatch_line,
        )
        for context in contexts:
            dispatch_match = _contract_runtime_dispatch_line_match(
                projection_record,
                context,
            )
            runtime_context_id, task_id, parent_task_id = (
                _contract_runtime_context_identity(context)
            )
            if expected_identity["runtime_context_id"] and (
                runtime_context_id != expected_identity["runtime_context_id"]
            ):
                continue
            if expected_identity["task_id"] and task_id != expected_identity["task_id"]:
                continue
            backlog_id = str(
                getattr(context, "backlog_id", "")
                or projection_record.get("backlog_id")
                or ""
            )
            timeline_events = _runtime_context_service_timeline_events(
                conn,
                project_id=project_id,
                task_id=task_id,
                backlog_id=backlog_id,
            )
            contract_runtime_merge = (
                _contract_runtime_completed_merge_authority(
                    conn,
                    project_id=project_id,
                    record=projection_record,
                    context=context,
                    timeline_events=timeline_events,
                )
            )
            if contract_runtime_merge:
                dispatch_lineage = (
                    _contract_runtime_verified_dispatch_lineage(
                        projection_record,
                        context,
                        dispatch_match,
                    )
                )
                if not dispatch_lineage:
                    continue
                trusted_merge = {
                    **contract_runtime_merge,
                    **dispatch_lineage,
                }
                trusted_merge["authority_hash"] = stable_sha256(
                    {
                        key: value
                        for key, value in trusted_merge.items()
                        if key != "authority_hash"
                    }
                )
                trusted = _contract_runtime_completed_merge_reconcile_authority(
                    conn,
                    project_id=project_id,
                    record=projection_record,
                    context=context,
                    timeline_events=timeline_events,
                    merge=trusted_merge,
                )
                if (
                    isinstance(
                        trusted.get("shared_batch_reconcile_authority"),
                        Mapping,
                    )
                    and _contract_runtime_current_full_reconcile_activation_verified(
                        trusted
                    )
                ):
                    trusted["authority_hash"] = stable_sha256(
                        {
                            key: value
                            for key, value in trusted.items()
                            if key != "authority_hash"
                        }
                    )
                candidates.append(trusted)
                continue
            # A read-model record may already contain transient post-worker
            # lines.  Recompute that projection from the canonical completed
            # lines so those unpersisted lines cannot impersonate accepted
            # ContractRuntime evidence or suppress the DB-backed projection.
            projected_lines = _contract_runtime_projection_post_worker_lines(
                conn=conn,
                project_id=project_id,
                record=projection_record,
                context=context,
                timeline_events=timeline_events,
            )
            qa_line = next(
                (
                    line
                    for line in projected_lines
                    if str(line.get("line_id") or "")
                    == "qa_independent_verification"
                ),
                {},
            )
            qa_source_ref = str(qa_line.get("_source_ref") or "").strip()
            qa_source_event = next(
                (
                    event
                    for event in timeline_events
                    if _runtime_context_event_ref(event) == qa_source_ref
                ),
                {},
            )
            durable_merge = _contract_runtime_observer_merge_durable_authority(
                conn,
                project_id=project_id,
                record=projection_record,
            )
            qa_completed_line_index = int(
                durable_merge.get("qa_completed_line_index") or -1
            )
            canonical_completed = [
                line
                for line in projection_record.get("completed_lines") or []
                if isinstance(line, Mapping)
            ]
            canonical_qa_line = (
                canonical_completed[qa_completed_line_index]
                if 0 <= qa_completed_line_index < len(canonical_completed)
                else {}
            )
            qa_acceptance = (
                _contract_runtime_completed_line_acceptance(
                    conn,
                    project_id=project_id,
                    record=projection_record,
                    completed_line_index=qa_completed_line_index,
                    expected_line=canonical_qa_line,
                )
                if canonical_qa_line
                else {}
            )
            durable_qa_verified = bool(
                durable_merge.get("qa_contract_runtime_verified") is True
                and durable_merge.get("close_satisfying") is True
                and qa_acceptance.get("db_verified") is True
                and str(
                    durable_merge.get("qa_acceptance_ref") or ""
                ).strip()
                == str(qa_acceptance.get("acceptance_ref") or "").strip()
            )
            for line in projected_lines:
                if str(line.get("line_id") or "") != "observer_merge":
                    continue
                source_ref = str(line.get("_source_ref") or "").strip()
                merged_commit = str(line.get("commit_sha") or "").strip().lower()
                source_event = next(
                    (
                        event
                        for event in timeline_events
                        if _runtime_context_event_ref(event) == source_ref
                    ),
                    {},
                )
                projected_merge = _contract_runtime_projection_merge_authority(
                    record=projection_record,
                    context=context,
                    merge_event=source_event,
                    qa_event=qa_source_event,
                )
                durable_merge_ref = str(
                    durable_merge.get("merge_event_ref") or ""
                ).strip()
                durable_merge_commit = str(
                    durable_merge.get("merge_commit") or ""
                ).strip().lower()
                if not (
                    durable_qa_verified
                    and dispatch_match
                    and projected_merge.get("timeline_verified") is True
                    and source_ref == durable_merge_ref
                    and merged_commit == durable_merge_commit
                    and int(projected_merge.get("merge_event_id") or 0)
                    == int(durable_merge.get("merge_event_id") or 0)
                    and str(
                        projected_merge.get("merge_event_created_at") or ""
                    ).strip()
                    == str(
                        durable_merge.get("merge_event_created_at") or ""
                    ).strip()
                    and all(
                        str(durable_merge.get(field) or "").strip()
                        == str(expected or "").strip()
                        for field, expected in (
                            ("project_id", project_id),
                            ("backlog_id", backlog_id),
                            ("runtime_context_id", runtime_context_id),
                            ("task_id", task_id),
                            ("parent_task_id", parent_task_id),
                            (
                                "merge_queue_id",
                                getattr(context, "merge_queue_id", ""),
                            ),
                        )
                    )
                ):
                    continue
                qa_payload = (
                    canonical_qa_line.get("payload")
                    if isinstance(canonical_qa_line.get("payload"), Mapping)
                    else {}
                )
                transient_merge = {
                    **projected_merge,
                    "authority_verified": True,
                    "no_pass_claim": False,
                    "overall_release_pass_claimed": False,
                    "qa_acceptance_scope": str(
                        qa_payload.get("acceptance_scope") or ""
                    ),
                    "candidate_new_failures": qa_payload.get(
                        "candidate_new_failures"
                    ),
                    "authority_source": (
                        "contract_runtime_completed_qa+"
                        "server_durable_merge_schema+durable_merge_queue+"
                        "task_timeline_qa_merge"
                    ),
                    "durable_merge_schema_version": str(
                        durable_merge.get("schema_version") or ""
                    ),
                    "durable_merge_authority": dict(durable_merge),
                    "qa_acceptance_created_at": str(
                        qa_acceptance.get("accepted_at") or ""
                    ),
                    "qa_acceptance_revision": int(
                        qa_acceptance.get("execution_state_revision") or 0
                    ),
                    "qa_acceptance_ref": str(
                        qa_acceptance.get("acceptance_ref") or ""
                    ),
                    "qa_source_ref": str(
                        qa_acceptance.get("completed_line_ref") or ""
                    ),
                    "qa_event_id": 0,
                    "qa_event_created_at": "",
                    "qa_contract_runtime_verified": True,
                    "qa_graph_completed_line_index": int(
                        durable_merge.get(
                            "qa_graph_completed_line_index"
                        )
                        or -1
                    ),
                    "qa_completed_line_index": qa_completed_line_index,
                    "authoritative_pass_synthesized": False,
                    "close_satisfying": True,
                    "merge_queue_id": str(
                        durable_merge.get("merge_queue_id") or ""
                    ).strip(),
                    "queue_item_id": str(
                        durable_merge.get("queue_item_id") or ""
                    ).strip(),
                    "contract_execution_id": str(
                        projection_record.get("contract_execution_id")
                        or ""
                    ).strip(),
                    "contract_runtime_dispatch_source_ref": str(
                        dispatch_match.get("source_ref") or ""
                    ),
                    "dispatch_lineage_verified": True,
                }
                trusted = _contract_runtime_completed_merge_reconcile_authority(
                    conn,
                    project_id=project_id,
                    record=projection_record,
                    context=context,
                    timeline_events=timeline_events,
                    merge=transient_merge,
                )
                candidates.append(trusted)
    unique = {stable_sha256(item): item for item in candidates}
    if len(unique) != 1:
        return {
            "timeline_verified": False,
            "identity_mismatches": [
                {
                    "field": "observer_merge_projection",
                    "expected": "one durable timeline-backed merge tuple",
                    "actual": len(unique),
                }
            ],
        }
    return {"timeline_verified": True, **next(iter(unique.values()))}


def _contract_runtime_shared_batch_enter_binding_verified(
    payload: Mapping[str, Any],
    *,
    project_id: str,
    batch_id: str,
    coordination_backlog_id: str,
    merge_queue_id: str,
    queue_rows: Sequence[Mapping[str, Any]],
) -> bool:
    """Verify one server-authored batch enter against its durable queue.

    Current enter events carry the queue only inside ``merge_queue_plan``.
    Older events used the top-level ``merge_queue_id`` compatibility field.
    When the durable plan is present, its immutable ordered child identities
    must exactly match the closed queue; caller-shaped aliases never widen the
    accepted binding.
    """

    if not (
        str(payload.get("batch_id") or "").strip() == batch_id
        and str(payload.get("backlog_id") or "").strip()
        == coordination_backlog_id
    ):
        return False
    top_level_queue_id = str(
        payload.get("merge_queue_id") or ""
    ).strip()
    plan_claimed = "merge_queue_plan" in payload
    raw_plan = payload.get("merge_queue_plan")
    if plan_claimed and not isinstance(raw_plan, Mapping):
        return False
    plan = dict(raw_plan) if isinstance(raw_plan, Mapping) else {}
    plan_queue_id = str(plan.get("merge_queue_id") or "").strip()
    if (
        top_level_queue_id
        and plan_queue_id
        and top_level_queue_id != plan_queue_id
    ):
        return False
    entered_queue_id = plan_queue_id or top_level_queue_id
    if entered_queue_id != merge_queue_id:
        return False
    if not plan_claimed:
        return bool(top_level_queue_id)
    if not plan:
        return False
    if not (
        plan_queue_id == merge_queue_id
        and plan.get("planner_only") is False
        and plan.get("durable_queue_write") is True
        and str(plan.get("source_of_authority") or "").strip()
        == "server.handle_project_mf_batch_parallel_enter"
    ):
        return False
    durable_items = plan.get("durable_queue_items")
    if not isinstance(durable_items, list):
        return False
    try:
        durable_item_count = int(plan.get("durable_queue_item_count"))
    except (TypeError, ValueError):
        return False
    if durable_item_count != len(durable_items) or len(durable_items) != len(
        queue_rows
    ):
        return False

    def immutable_queue_identity(
        item: Mapping[str, Any],
    ) -> tuple[str, str, str, str, str, int] | None:
        try:
            queue_index = int(item.get("queue_index"))
        except (TypeError, ValueError):
            return None
        identity = (
            str(item.get("project_id") or "").strip(),
            str(item.get("merge_queue_id") or "").strip(),
            str(item.get("queue_item_id") or "").strip(),
            str(item.get("backlog_id") or "").strip(),
            str(item.get("task_id") or "").strip(),
            queue_index,
        )
        if not all(identity[:5]) or queue_index <= 0:
            return None
        return identity

    planned_identities = [
        immutable_queue_identity(item)
        if isinstance(item, Mapping)
        else None
        for item in durable_items
    ]
    durable_identities = [
        immutable_queue_identity(item) for item in queue_rows
    ]
    return bool(
        all(identity is not None for identity in planned_identities)
        and all(identity is not None for identity in durable_identities)
        and planned_identities == durable_identities
        and all(
            identity[0] == project_id and identity[1] == merge_queue_id
            for identity in planned_identities
            if identity is not None
        )
    )


def _entered_batch_successor_resume_projection(
    conn,
    *,
    project_id: str,
    coordination_backlog_id: str,
) -> dict[str, Any]:
    """Project the next durable batch child without reopening the batch.

    An accepted batch enter can outlive its integration epoch: before the
    first row is materialized there is deliberately no active epoch.  The
    guide must therefore recognize the immutable enter event + durable queue
    tuple itself.  This reader never creates schemas or updates the historical
    queue; only the executable target HEAD and active graph are refreshed from
    current server authority.
    """

    from . import graph_snapshot_store

    blocked_base = {
        "schema_version": "mf_batch_parallel.entered_successor_resume.v1",
        "source": "durable_entered_batch",
        "precedence": "entered_batch_before_fresh_batch",
        "project_id": project_id,
        "backlog_id": coordination_backlog_id,
        "scheduler_eligible": False,
        "position_skippable": False,
        "writes_performed": False,
    }

    def blocked(code: str) -> dict[str, Any]:
        return {
            **blocked_base,
            "status": "entered_batch_successor_blocked",
            "blocked": True,
            "blocker": {"code": code, "copy_safe": True},
            "next_legal_action": {
                "schema_version": "onboard_route_guide.next_action.v1",
                "id": "entered_batch_successor_resume_blocked",
                "action": "no_runtime_action",
                "source": "durable_entered_batch",
                "blocked": True,
                "blocker": {"code": code, "copy_safe": True},
            },
        }

    try:
        event_rows = conn.execute(
            """
            SELECT id, task_id, event_type, phase, event_kind, status,
                   payload_json, created_at
              FROM task_timeline_events
             WHERE project_id = ? AND backlog_id = ?
               AND event_type = 'mf_batch_parallel.entered'
             ORDER BY id DESC
             LIMIT 3
            """,
            (project_id, coordination_backlog_id),
        ).fetchall()
    except sqlite3.Error:
        return {}
    if not event_rows:
        return {}
    if len(event_rows) != 1:
        return blocked("entered_batch_event_ambiguous")
    event = event_rows[0]
    if not (
        str(event["phase"] or "") == "orchestration"
        and str(event["event_kind"] or "") == "contract_binding"
        and str(event["status"] or "") == "accepted"
    ):
        return blocked("entered_batch_event_not_authoritative")
    try:
        payload = json.loads(str(event["payload_json"] or "{}"))
    except (TypeError, ValueError, json.JSONDecodeError):
        return blocked("entered_batch_event_payload_invalid")
    if not isinstance(payload, Mapping):
        return blocked("entered_batch_event_payload_invalid")
    batch_id = str(payload.get("batch_id") or "").strip()
    merge_queue_id = _contract_runtime_mf_batch_parent_merge_queue_id(payload)
    if not batch_id or not merge_queue_id:
        return blocked("entered_batch_identity_incomplete")
    try:
        queue_rows = conn.execute(
            """
            SELECT * FROM parallel_branch_merge_queue_items
             WHERE project_id = ? AND merge_queue_id = ?
             ORDER BY queue_index, queue_item_id
            """,
            (project_id, merge_queue_id),
        ).fetchall()
    except sqlite3.Error:
        return blocked("entered_batch_queue_unavailable")
    queue = [dict(row) for row in queue_rows]
    if not queue or not _contract_runtime_shared_batch_enter_binding_verified(
        payload,
        project_id=project_id,
        batch_id=batch_id,
        coordination_backlog_id=coordination_backlog_id,
        merge_queue_id=merge_queue_id,
        queue_rows=queue,
    ):
        return blocked("entered_batch_queue_binding_invalid")
    planned = [row for row in queue if str(row.get("status") or "") == "planned"]
    if not planned:
        return blocked("entered_batch_has_no_planned_successor")
    selected = planned[0]
    fanout = payload.get("fanout_policy")
    successors = (
        fanout.get("per_row_successors")
        if isinstance(fanout, Mapping)
        and isinstance(fanout.get("per_row_successors"), list)
        else []
    )
    matching_successors = []
    for item in successors:
        if not isinstance(item, Mapping):
            continue
        body = item.get("body") if isinstance(item.get("body"), Mapping) else {}
        merge_item = (
            body.get("merge_queue_item")
            if isinstance(body.get("merge_queue_item"), Mapping)
            else {}
        )
        if (
            str(item.get("backlog_id") or "") == str(selected.get("backlog_id") or "")
            and str(body.get("task_id") or "") == str(selected.get("task_id") or "")
            and str(body.get("merge_queue_id") or "") == merge_queue_id
            and str(merge_item.get("queue_item_id") or "")
            == str(selected.get("queue_item_id") or "")
        ):
            matching_successors.append(dict(item))
    if len(matching_successors) != 1:
        return blocked("entered_batch_successor_identity_ambiguous")
    successor = matching_successors[0]
    successor_body = dict(successor.get("body") or {})
    durable_successor_item = dict(
        successor_body.get("merge_queue_item")
        if isinstance(successor_body.get("merge_queue_item"), Mapping)
        else {}
    )
    for field in (
        "project_id",
        "merge_queue_id",
        "queue_item_id",
        "backlog_id",
        "task_id",
        "queue_index",
        "status",
        "target_ref",
        "base_commit",
        "validated_target_head",
        "current_target_head",
        "snapshot_id",
    ):
        durable_successor_item[field] = selected.get(field)
    successor_body["merge_queue_item"] = durable_successor_item

    try:
        project_root = project_service.resolve_project_root(
            project_id,
            None,
            fallback_self=False,
        )
    except Exception:
        project_root = None
    if project_root is None:
        return blocked("entered_batch_current_project_root_unavailable")
    canonical_root = Path(project_root).resolve()
    if not _git_clean_worktree_verified(canonical_root):
        return blocked("entered_batch_current_worktree_not_clean")
    current_head = str(_git_head_commit(canonical_root) or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", current_head):
        return blocked("entered_batch_current_head_not_full")
    try:
        resolved_head = _parallel_branch_resolve_canonical_commit(
            canonical_root,
            current_head,
            field="current_target_head",
        )
    except GovernanceError:
        return blocked("entered_batch_current_head_not_canonical")
    if resolved_head != current_head:
        return blocked("entered_batch_current_head_not_canonical")
    target_ref = str(selected.get("target_ref") or "").strip()
    target_head = str(
        _git_output(
            canonical_root,
            ["rev-parse", "--verify", f"{target_ref}^{{commit}}"],
            timeout=10,
        )
        or ""
    ).strip().lower()
    if not (
        target_ref
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", target_head)
        and target_head == current_head
    ):
        return blocked("entered_batch_current_target_ref_not_head")
    historical_base = str(selected.get("base_commit") or "").strip().lower()
    if not (
        re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", historical_base)
        and _git_commit_is_ancestor(canonical_root, historical_base, current_head)
    ):
        return blocked("entered_batch_historical_base_not_ancestor")
    try:
        active_row = conn.execute(
            """
            SELECT s.*
              FROM graph_snapshot_refs AS r
              JOIN graph_snapshots AS s
                ON s.project_id = r.project_id
               AND s.snapshot_id = r.snapshot_id
             WHERE r.project_id = ? AND r.ref_name = 'active'
               AND r.commit_sha = ? AND s.commit_sha = ?
            """,
            (project_id, current_head, current_head),
        ).fetchone()
    except sqlite3.Error:
        active_row = None
    active_snapshot = dict(active_row) if active_row is not None else {}
    if not (
        active_snapshot
        and str(active_snapshot.get("snapshot_kind") or "") == "full"
        and str(active_snapshot.get("status") or "") == "active"
    ):
        return blocked("entered_batch_current_graph_snapshot_unavailable")
    integrity = graph_snapshot_store.validate_snapshot_companion_integrity(
        active_snapshot
    )
    if integrity.get("valid") is not True:
        return blocked("entered_batch_current_graph_snapshot_invalid")
    current_snapshot_id = str(active_snapshot.get("snapshot_id") or "").strip()
    if not re.fullmatch(
        r"full-(?:[0-9a-f]{7}-[0-9a-f]{4}|[0-9a-f]{12}-[0-9a-f]{12})",
        current_snapshot_id,
    ):
        return blocked("entered_batch_current_graph_snapshot_identity_invalid")
    stale_queue_item_count = sum(
        1
        for row in queue
        if str(row.get("current_target_head") or "").strip().lower()
        != current_head
    )

    successor_body["target_head_commit"] = current_head
    successor_body["graph_snapshot_id"] = current_snapshot_id
    child_backlog_id = str(selected.get("backlog_id") or "").strip()
    child_task_id = str(selected.get("task_id") or "").strip()
    batch_parent_execution_id = str(
        payload.get("parent_contract_execution_id") or ""
    ).strip()
    # Each Batch row remains a backlog-scoped ContractRuntime chain.  The
    # accepted Batch event owns scheduling/custody, while the generated
    # onboard-service waiver deterministically creates that child row's
    # service parent when mf_parallel_enter executes.
    child_parent_execution_id = _onboard_service_execution_id(
        project_id,
        child_backlog_id,
    )
    successor_execution_id = _mf_parallel_execution_id(
        project_id,
        child_backlog_id,
        child_parent_execution_id,
        child_task_id,
    )
    target_files = _runtime_context_public_file_values(
        successor.get("target_files") or successor.get("owned_files") or []
    )
    route_issue_body = {
        "project_id": project_id,
        "caller_role": "observer",
        "backlog_id": child_backlog_id,
        "task_id": successor_execution_id,
        "target_files": target_files,
        "allowed_actions": _observer_route_context_issue_allowed_actions(
            ["mf_parallel_enter", "mf_parallel_revise"]
        ),
        "evidence_refs": [
            f"timeline:{int(event['id'])}",
            f"backlog:{child_backlog_id}",
            f"merge_queue:{merge_queue_id}",
        ],
    }
    successor_action_input = {
        "schema_version": "mf_batch_parallel.entered_successor_action_input.v1",
        "interface": "mf_parallel_enter",
        "source": "durable_entered_batch",
        "copy_safe": True,
        "static_body": successor_body,
        "dynamic_fields": {
            "observer_session_id": {
                "required": True,
                "placeholder": "<active_observer_session_id>",
                "source": "observer_session_register.session_id",
            },
            "observer_route_token_ref": {
                "required": True,
                "placeholder": "<route_token_ref>",
                "source": "observer_route_context_issue.route_token_ref",
            },
        },
        "contract_execution_id_required": False,
        "raw_session_token_exposed": False,
        "raw_route_token_exposed": False,
    }
    action = {
        "schema_version": "onboard_route_guide.next_action.v1",
        "id": "resume_entered_batch_successor",
        "action": "mf_parallel_enter",
        "interface": "mf_parallel_enter",
        "path": "/api/projects/{project_id}/mf-parallel/enter",
        "source": "durable_entered_batch",
        "precedence": "entered_batch_before_fresh_batch",
        "requires_role": "observer",
        "requires_active_observer_session": True,
        "requires_route_token_ref": True,
        "action_input_interface": "observer_route_context_issue",
        "action_input": route_issue_body,
        "action_input_copy_safe": True,
        "action_input_ready": True,
        "successor_action_input_interface": "mf_parallel_enter",
        "successor_action_input": successor_action_input,
        "allowed_actions": list(route_issue_body["allowed_actions"]),
        "batch_id": batch_id,
        "merge_queue_id": merge_queue_id,
        "queue_item_id": str(selected.get("queue_item_id") or ""),
        "backlog_id": child_backlog_id,
        "task_id": child_task_id,
        "historical_base_commit": historical_base,
        "current_target_head": current_head,
        "current_graph_snapshot_id": current_snapshot_id,
        "stale_target_head": stale_queue_item_count > 0,
        "stale_count": stale_queue_item_count,
        "server_derived_authority": {
            "event_ref": f"timeline:{int(event['id'])}",
            "batch_parent_contract_execution_id": batch_parent_execution_id,
            "child_parent_contract_execution_id": child_parent_execution_id,
            "child_parent_source": "generated_onboard_service_waiver",
            "entered_batch_verified": True,
            "durable_queue_verified": True,
            "current_target_head_verified": True,
            "current_graph_snapshot_verified": True,
            "historical_lineage_preserved": True,
        },
        "raw_session_token_exposed": False,
        "raw_route_token_exposed": False,
    }
    return {
        **blocked_base,
        "status": "entered_batch_successor_ready",
        "blocked": False,
        "scheduler_eligible": True,
        "batch_id": batch_id,
        "merge_queue_id": merge_queue_id,
        "queue_item_id": str(selected.get("queue_item_id") or ""),
        "historical_base_commit": historical_base,
        "current_target_head": current_head,
        "current_graph_snapshot_id": current_snapshot_id,
        "stale_target_head": stale_queue_item_count > 0,
        "stale_count": stale_queue_item_count,
        "next_legal_action": action,
    }


def _contract_runtime_shared_batch_child_lane_merge_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    timeline_events: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Resolve one rev8/rev9 batch child's pre-QA lane merge authority.

    ``_contract_runtime_completed_merge_authority`` rebuilds a merge round in
    which QA precedes the merge; it returns nothing for rev8/rev9, which merge
    every lane *before* canonical reconcile and run the integration QA after
    it.  Record-grade, current-full, and close-grade authority already resolve
    those worlds through the pinned lane-merge projection, so the shared batch
    projection has to read the same projection for its children or it can
    never see a batch whose children are all still pre-QA - which is every
    ``mf_batch_parallel`` batch at the moment its children reach post-merge QA.

    The pinned projection stays fail-closed on its own terms: it returns ``{}``
    unless every required lane merge joins the selected dispatch, its durable
    queue identity, and its own timeline event.  Only the server-owned pre-QA
    merge shape is admitted here, and this helper additionally re-derives the
    merge line's acceptance revision, its durable merge-queue row, and its
    merge timeline event from the database, so the returned merge event id and
    time - which the caller uses to enforce strict merge-before-reconcile
    order - never come from the completed line itself.  ``conn`` is
    deliberately withheld from the projection: its reconcile join would
    re-enter the shared batch projection for the same batch.
    """

    if not _is_mf_parallel_postmerge_revision(record):
        return {}
    required_worker_count = (
        _contract_runtime_mf_parallel_current_generation_worker_count(
            record,
            conn=conn,
            project_id=project_id,
        )
    )
    projection_record = dict(record)
    projection = _contract_runtime_rev8_two_worker_merge_projection(
        projection_record,
        required_worker_count=required_worker_count,
    )
    transient_merge_projection = False
    if projection.get("all_lane_merges_verified") is not True:
        projected_lines = _contract_runtime_projection_post_worker_lines(
            conn=conn,
            project_id=project_id,
            record=record,
            context=context,
            timeline_events=timeline_events,
            include_shared_batch_reconcile=False,
        )
        projected_merge_lines = [
            line
            for line in projected_lines
            if isinstance(line, Mapping)
            and str(line.get("line_id") or "").strip() == "observer_merge"
        ]
        if len(projected_merge_lines) != 1:
            return {}
        projection_record["completed_lines"] = (
            _contract_runtime_merge_projected_completed_lines(
                record.get("completed_lines") or [],
                projected_lines,
                postmerge_revision=_is_mf_parallel_postmerge_revision(
                    record
                ),
            )
        )
        projection = _contract_runtime_rev8_two_worker_merge_projection(
            projection_record,
            required_worker_count=required_worker_count,
        )
        transient_merge_projection = True
    if not (
        projection.get("timeline_verified") is True
        and projection.get("authority_verified") is True
        and projection.get("dispatch_lineage_verified") is True
        and projection.get("all_lane_merges_verified") is True
        and projection.get("pre_qa_merge_authorized") is True
        and projection.get("final_qa_required_after_reconcile") is True
        and projection.get("qa_contract_runtime_verified") is not True
        and projection.get("close_satisfying") is not True
        and not projection.get("qa_audit_only_no_pass_authority")
        and projection.get("no_pass_claim") is not True
    ):
        return {}
    if not _contract_runtime_dispatch_line_match(record, context):
        return {}

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    backlog_id = str(
        getattr(context, "backlog_id", "") or record.get("backlog_id") or ""
    ).strip()
    execution_id = str(record.get("contract_execution_id") or "").strip()
    merged_commit = str(
        projection.get("merged_commit_sha") or ""
    ).strip().lower()
    merge_queue_id = str(projection.get("merge_queue_id") or "").strip()
    queue_item_id = str(projection.get("queue_item_id") or "").strip()
    if not (
        str(projection.get("project_id") or "").strip() == project_id
        and str(projection.get("backlog_id") or "").strip() == backlog_id
        and str(projection.get("contract_execution_id") or "").strip()
        == execution_id
        and str(projection.get("runtime_context_id") or "").strip()
        == runtime_context_id
        and str(projection.get("task_id") or "").strip() == task_id
        and str(projection.get("parent_task_id") or "").strip()
        == parent_task_id
        and all((project_id, backlog_id, execution_id, merge_queue_id))
        and queue_item_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", merged_commit)
    ):
        return {}

    merge_line_index_value = projection.get("merge_completed_line_index")
    merge_line_index = (
        int(merge_line_index_value)
        if isinstance(merge_line_index_value, int)
        and not isinstance(merge_line_index_value, bool)
        else -1
    )
    completed = [
        line
        for line in projection_record.get("completed_lines") or []
        if isinstance(line, Mapping)
    ]
    if not 0 <= merge_line_index < len(completed):
        return {}
    merge_line = completed[merge_line_index]
    if not (
        str(merge_line.get("line_id") or "").strip() == "observer_merge"
        and str(merge_line.get("actor_role") or "").strip() == "observer"
        and str(merge_line.get("evidence_kind") or "").strip() == "merge"
    ):
        return {}
    if transient_merge_projection:
        merge_payload = (
            merge_line.get("payload")
            if isinstance(merge_line.get("payload"), Mapping)
            else {}
        )
        durable_authority = (
            merge_payload.get("durable_merge_authority")
            if isinstance(
                merge_payload.get("durable_merge_authority"), Mapping
            )
            else {}
        )
        merge_acceptance = {
            "db_verified": bool(
                str(merge_payload.get("schema_version") or "").strip()
                == "mf_parallel.runtime_context_post_worker_line_projection.v1"
                and merge_payload.get("projection_persists_completed_line")
                is False
                and merge_payload.get("observer_authored_worker_backfill")
                is False
                and str(durable_authority.get("schema_version") or "").strip()
                == _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
                and durable_authority.get("server_derived") is True
                and durable_authority.get("db_verified") is True
                and str(durable_authority.get("runtime_context_id") or "").strip()
                == runtime_context_id
                and str(durable_authority.get("task_id") or "").strip()
                == task_id
                and str(durable_authority.get("parent_task_id") or "").strip()
                == parent_task_id
                and str(durable_authority.get("merge_commit") or "")
                .strip()
                .lower()
                == merged_commit
            ),
            "acceptance_ref": str(
                merge_payload.get("source_ref") or ""
            ).strip(),
        }
    else:
        merge_acceptance = _contract_runtime_completed_line_acceptance(
            conn,
            project_id=project_id,
            record=record,
            completed_line_index=merge_line_index,
            expected_line=merge_line,
        )
    if merge_acceptance.get("db_verified") is not True:
        return {}

    from .parallel_branch_runtime import get_merge_queue_item

    durable_item = get_merge_queue_item(
        conn,
        project_id,
        merge_queue_id,
        queue_item_id,
    )
    if (
        durable_item is None
        or str(durable_item.task_id or "").strip() != task_id
        or str(durable_item.backlog_id or "").strip() != backlog_id
        or str(durable_item.status or "").strip() != "merged"
        or str(durable_item.merge_commit or "").strip().lower()
        != merged_commit
        or str(durable_item.target_head_after_merge or "").strip().lower()
        != merged_commit
    ):
        return {}

    merge_source_ref = str(projection.get("merge_source_ref") or "").strip()
    merge_events: list[Mapping[str, Any]] = []
    for event in timeline_events:
        if not isinstance(event, Mapping):
            continue
        event_payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        event_commit = str(
            event.get("commit_sha")
            or event_payload.get("merge_commit")
            or event_payload.get("target_head_after_merge")
            or ""
        ).strip().lower()
        event_kind = str(
            event.get("event_kind") or event.get("event_type") or ""
        ).lower()
        if (
            event_commit == merged_commit
            and "merge" in event_kind
            and _runtime_context_event_ref(event) == merge_source_ref
        ):
            merge_events.append(event)
    if len(merge_events) != 1:
        return {}
    merge_event = merge_events[0]
    merge_event_id = _contract_runtime_projection_timeline_event_id(
        merge_event
    )
    merge_event_created_at = (
        _contract_runtime_projection_timeline_event_time(merge_event)
    )
    if merge_event_id <= 0 or not merge_event_created_at:
        return {}

    return {
        "timeline_verified": True,
        "authority_verified": True,
        "authority_source": (
            "contract_runtime_pinned_lane_merge_projection+"
            + (
                "runtime_context_transient_merge_authority+"
                if transient_merge_projection
                else "contract_runtime_completed_line_acceptance+"
            )
            + "durable_merge_queue+task_timeline_merge"
        ),
        "no_pass_claim": False,
        "overall_release_pass_claimed": False,
        "authoritative_pass_synthesized": False,
        "qa_audit_only_no_pass_authority": {},
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "merged_commit_sha": merged_commit,
        "qa_contract_runtime_verified": False,
        "close_satisfying": False,
        "pre_qa_merge_authorized": True,
        "final_qa_required_after_reconcile": True,
        "merge_completed_line_index": merge_line_index,
        "merge_acceptance_ref": str(
            merge_acceptance.get("acceptance_ref") or ""
        ),
        "merge_source_ref": _runtime_context_event_ref(merge_event),
        "merge_event_id": merge_event_id,
        "merge_event_created_at": merge_event_created_at,
        "merge_queue_id": merge_queue_id,
        "queue_item_id": queue_item_id,
    }


def _contract_runtime_shared_batch_reconcile_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    merge: Mapping[str, Any],
    allow_postmerge_qa_admission: bool = False,
) -> dict[str, Any]:
    """Project one closed batch reconcile onto an exact merged child.

    The final batch reconcile is coordination-scoped by design.  The default
    close projection requires every child's ContractRuntime QA/merge
    authority.  The explicit rev8/rev9 post-merge QA-admission projection
    instead requires every child to be either final-QA verified or still
    carrying the server-owned pre-QA merge marker; it never claims close
    satisfaction.  Both paths also prove the complete closed epoch, ordered
    queue, and one active current-HEAD coordination reconcile.  No
    caller-shaped scope is admitted into either projection.
    """

    from . import graph_snapshot_store
    from .parallel_branch_runtime import (
        get_branch_context,
        get_branch_context_by_runtime_context_id,
        runtime_context_id_for_branch_context,
    )

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    backlog_id = str(
        getattr(context, "backlog_id", "")
        or record.get("backlog_id")
        or ""
    ).strip()
    batch_id = str(getattr(context, "batch_id", "") or "").strip()
    merge_queue_id = str(merge.get("merge_queue_id") or "").strip()
    queue_item_id = str(merge.get("queue_item_id") or "").strip()
    merged_commit = str(
        merge.get("merged_commit_sha") or ""
    ).strip().lower()
    execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    dispatch_match = _contract_runtime_dispatch_line_match(record, context)
    qa_time = _contract_runtime_close_authority_time_order_value(
        merge.get("qa_acceptance_created_at")
    )
    merge_time = _contract_runtime_close_authority_time_order_value(
        merge.get("merge_event_created_at")
    )
    final_qa_verified = bool(
        merge.get("qa_contract_runtime_verified") is True
        and merge.get("close_satisfying") is True
        and qa_time is not None
        and merge_time is not None
        and qa_time <= merge_time
    )
    postmerge_qa_admission = bool(
        allow_postmerge_qa_admission
        and _is_mf_parallel_postmerge_revision(record)
        and merge.get("authority_verified") is True
        and merge.get("qa_contract_runtime_verified") is not True
        and merge.get("close_satisfying") is not True
        and merge.get("pre_qa_merge_authorized") is True
        and merge.get("final_qa_required_after_reconcile") is True
        and merge_time is not None
    )
    if not (
        merge.get("timeline_verified") is True
        and (final_qa_verified or postmerge_qa_admission)
        and dispatch_match
        and all(
            (
                project_id,
                execution_id,
                backlog_id,
                batch_id,
                runtime_context_id,
                task_id,
                parent_task_id,
                merge_queue_id,
                queue_item_id,
            )
        )
        and parent_task_id in {execution_id, batch_id}
        and str(getattr(context, "merge_queue_id", "") or "").strip()
        == merge_queue_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", merged_commit)
    ):
        return {}

    try:
        epoch_rows = conn.execute(
            """
            SELECT *
            FROM parallel_branch_integration_epochs
            WHERE project_id = ? AND batch_id = ?
            LIMIT 2
            """,
            (project_id, batch_id),
        ).fetchall()
    except sqlite3.Error:
        return {}
    if len(epoch_rows) != 1:
        return {}
    epoch = dict(epoch_rows[0])
    epoch_id = str(epoch.get("epoch_id") or "").strip()
    coordination_backlog_id = str(
        epoch.get("coordination_backlog_id") or ""
    ).strip()
    epoch_current_head = str(
        epoch.get("current_head") or ""
    ).strip().lower()
    epoch_last_merge_commit = str(
        epoch.get("last_merge_commit") or ""
    ).strip().lower()
    final_snapshot_id = str(epoch.get("snapshot_id") or "").strip()
    merged_prefix = _json_loads(epoch.get("merged_prefix_json"), [])
    remaining = _json_loads(
        epoch.get("remaining_queue_item_ids_json"),
        [],
    )
    try:
        merge_cursor = int(epoch.get("merge_cursor"))
    except (TypeError, ValueError):
        return {}
    if not (
        str(epoch.get("merge_queue_id") or "").strip() == merge_queue_id
        and epoch_id
        and str(epoch.get("status") or "").strip() == "closed"
        and str(epoch.get("reconcile_state") or "").strip() == "reconciled"
        and coordination_backlog_id
        and final_snapshot_id
        and re.fullmatch(r"[0-9a-f]{7,64}", epoch_current_head)
        and re.fullmatch(r"[0-9a-f]{7,64}", epoch_last_merge_commit)
        and isinstance(merged_prefix, list)
        and merged_prefix
        and isinstance(remaining, list)
        and not remaining
        and not any(
            str(epoch.get(field) or "").strip()
            for field in (
                "active_queue_item_id",
                "active_task_id",
                "active_backlog_id",
                "active_checkpoint_id",
                "failure_reason",
            )
        )
        and str(epoch.get("closed_at") or "").strip()
    ):
        return {}

    try:
        queue_rows = [
            dict(row)
            for row in conn.execute(
                """
                SELECT *
                FROM parallel_branch_merge_queue_items
                WHERE project_id = ? AND merge_queue_id = ?
                ORDER BY queue_index ASC, queue_item_id ASC
                """,
                (project_id, merge_queue_id),
            ).fetchall()
        ]
    except sqlite3.Error:
        return {}
    queue_item_ids = [
        str(item.get("queue_item_id") or "").strip()
        for item in queue_rows
    ]
    queue_final_head = (
        str(queue_rows[-1].get("merge_commit") or "").strip().lower()
        if queue_rows
        else ""
    )
    if not (
        len(queue_rows) >= 2
        and queue_item_ids
        == [str(item or "").strip() for item in merged_prefix]
        and merge_cursor == len(merged_prefix) == len(queue_rows)
        and len(set(queue_item_ids)) == len(queue_item_ids)
        and len(
            {
                str(item.get("task_id") or "").strip()
                for item in queue_rows
            }
        )
        == len(queue_rows)
        and all(
            str(item.get("status") or "").strip() == "merged"
            and str(item.get("backlog_id") or "").strip()
            and str(item.get("task_id") or "").strip()
            and str(item.get("completed_at") or "").strip()
            and re.fullmatch(
                r"[0-9a-f]{40}|[0-9a-f]{64}",
                str(item.get("merge_commit") or "").strip().lower(),
            )
            and str(item.get("target_head_after_merge") or "")
            .strip()
            .lower()
            == str(item.get("merge_commit") or "").strip().lower()
            for item in queue_rows
        )
        and queue_final_head.startswith(epoch_current_head)
        and queue_final_head.startswith(epoch_last_merge_commit)
    ):
        return {}
    final_head = queue_final_head
    child_queue_rows = [
        item
        for item in queue_rows
        if str(item.get("queue_item_id") or "").strip() == queue_item_id
    ]
    if len(child_queue_rows) != 1:
        return {}
    child_queue = child_queue_rows[0]
    if not (
        str(child_queue.get("task_id") or "").strip() == task_id
        and str(child_queue.get("backlog_id") or "").strip() == backlog_id
        and str(child_queue.get("merge_commit") or "").strip().lower()
        == merged_commit
    ):
        return {}

    expected_head = str(epoch.get("base_head") or "").strip().lower()
    child_authorities: list[dict[str, Any]] = []
    child_final_qa_verified: list[bool] = []
    child_postmerge_qa_admission_verified: list[bool] = []
    child_merge_event_ids: list[int] = []
    child_binding_refs: list[str] = []
    for item in queue_rows:
        before_head = str(
            item.get("target_head_before_merge") or ""
        ).strip().lower()
        item_merge_commit = str(
            item.get("merge_commit") or ""
        ).strip().lower()
        if not expected_head or before_head != expected_head:
            return {}
        expected_head = item_merge_commit

        child_task_id = str(item.get("task_id") or "").strip()
        child_backlog_id = str(item.get("backlog_id") or "").strip()
        child_context = get_branch_context(
            conn,
            project_id,
            child_task_id,
        )
        if child_context is None:
            return {}
        child_runtime_context_id = (
            runtime_context_id_for_branch_context(child_context)
        )
        child_parent_task_id = str(
            getattr(child_context, "parent_task_id", "") or ""
        ).strip()
        if not (
            str(getattr(child_context, "batch_id", "") or "").strip()
            == batch_id
            and str(
                getattr(child_context, "merge_queue_id", "") or ""
            ).strip()
            == merge_queue_id
            and str(getattr(child_context, "backlog_id", "") or "").strip()
            == child_backlog_id
            and child_runtime_context_id
            and child_parent_task_id
        ):
            return {}
        store = _contract_runtime_store(conn)
        try:
            candidate_records = store.list_by_backlog(
                project_id=project_id,
                backlog_id=child_backlog_id,
            )
        except (ContractRuntimeError, sqlite3.Error, TypeError, ValueError):
            return {}
        exact_child_records: list[
            tuple[Mapping[str, Any], Mapping[str, Any], Mapping[str, Any]]
        ] = []
        for candidate_record in candidate_records:
            if not isinstance(candidate_record, Mapping):
                continue
            candidate_execution_id = str(
                candidate_record.get("contract_execution_id") or ""
            ).strip()
            if not (
                candidate_execution_id
                and str(
                    candidate_record.get("project_id") or ""
                ).strip()
                == project_id
                and str(
                    candidate_record.get("backlog_id") or ""
                ).strip()
                == child_backlog_id
                and _is_mf_parallel_record_contract_id(
                    str(
                        candidate_record.get("contract_id") or ""
                    ).strip()
                )
            ):
                continue
            candidate_dispatch = _contract_runtime_dispatch_line_match(
                candidate_record,
                child_context,
            )
            candidate_lineage = (
                _contract_runtime_verified_dispatch_lineage(
                    candidate_record,
                    child_context,
                    candidate_dispatch,
                )
            )
            if candidate_lineage:
                exact_child_records.append(
                    (
                        candidate_record,
                        candidate_dispatch,
                        candidate_lineage,
                    )
                )
        if len(exact_child_records) != 1:
            return {}
        child_record, child_dispatch, child_dispatch_lineage = (
            exact_child_records[0]
        )
        child_execution_id = str(
            child_dispatch_lineage.get("contract_execution_id") or ""
        ).strip()
        child_dispatch_source_ref = str(
            child_dispatch_lineage.get(
                "contract_runtime_dispatch_source_ref"
            )
            or ""
        ).strip()
        if (
            child_task_id == task_id
            and child_execution_id != execution_id
        ):
            return {}
        if (
            child_parent_task_id != batch_id
            and child_parent_task_id != child_execution_id
        ):
            return {}
        child_timeline = _runtime_context_service_timeline_events(
            conn,
            project_id=project_id,
            task_id=child_task_id,
            backlog_id=child_backlog_id,
        )
        child_merge = _contract_runtime_completed_merge_authority(
            conn,
            project_id=project_id,
            record=child_record,
            context=child_context,
            timeline_events=child_timeline,
        )
        if not child_merge:
            # rev8/rev9 lanes merge before canonical reconcile, so the
            # pre-merge-QA round above resolves nothing for them.  Fall back to
            # the same pinned lane-merge projection every other rev8/rev9
            # authority reads.  It only ever yields the server-owned pre-QA
            # merge shape, which the admission branch below still has to
            # accept explicitly.
            child_merge = (
                _contract_runtime_shared_batch_child_lane_merge_authority(
                    conn,
                    project_id=project_id,
                    record=child_record,
                    context=child_context,
                    timeline_events=child_timeline,
                )
            )
        child_qa_time = _contract_runtime_close_authority_time_order_value(
            child_merge.get("qa_acceptance_created_at")
        )
        child_merge_time = (
            _contract_runtime_close_authority_time_order_value(
                child_merge.get("merge_event_created_at")
            )
        )
        child_final_qa = bool(
            child_merge.get("qa_contract_runtime_verified") is True
            and child_merge.get("close_satisfying") is True
            and child_qa_time is not None
            and child_merge_time is not None
            and child_qa_time <= child_merge_time
        )
        child_postmerge_qa_admission = bool(
            postmerge_qa_admission
            and child_merge.get("qa_contract_runtime_verified") is not True
            and child_merge.get("close_satisfying") is not True
            and child_merge.get("pre_qa_merge_authorized") is True
            and child_merge.get("final_qa_required_after_reconcile") is True
            and child_merge_time is not None
        )
        if not (
            child_dispatch
            and child_merge.get("timeline_verified") is True
            and (
                child_final_qa
                or child_postmerge_qa_admission
            )
            and str(child_merge.get("runtime_context_id") or "").strip()
            == child_runtime_context_id
            and str(child_merge.get("task_id") or "").strip()
            == child_task_id
            and str(child_merge.get("parent_task_id") or "").strip()
            == child_parent_task_id
            and str(child_merge.get("backlog_id") or "").strip()
            == child_backlog_id
            and str(child_merge.get("merge_queue_id") or "").strip()
            == merge_queue_id
            and str(child_merge.get("queue_item_id") or "").strip()
            == str(item.get("queue_item_id") or "").strip()
            and str(child_merge.get("merged_commit_sha") or "")
            .strip()
            .lower()
            == item_merge_commit
            and child_merge_time is not None
            and int(child_merge.get("merge_event_id") or 0) > 0
        ):
            return {}
        child_authorities.append(child_merge)
        child_final_qa_verified.append(child_final_qa)
        child_postmerge_qa_admission_verified.append(
            child_postmerge_qa_admission or child_final_qa
        )
        child_merge_event_ids.append(
            int(child_merge.get("merge_event_id") or 0)
        )
        child_binding_refs.append(
            child_dispatch_source_ref
        )
    if expected_head != final_head:
        return {}

    try:
        entered_rows = conn.execute(
            """
            SELECT *
            FROM task_timeline_events
            WHERE project_id = ?
              AND backlog_id = ?
              AND event_type = 'mf_batch_parallel.entered'
            ORDER BY id ASC
            """,
            (project_id, coordination_backlog_id),
        ).fetchall()
    except sqlite3.Error:
        return {}
    accepted_entered_bindings = []
    for raw_row in entered_rows:
        row = dict(raw_row)
        payload = _json_loads(row.get("payload_json"), {})
        if (
            isinstance(payload, Mapping)
            and str(row.get("event_kind") or "").strip()
            in {"contract_binding", "mf_batch_parallel_entered"}
            and str(row.get("status") or "").strip()
            in {"accepted", "passed"}
            and _contract_runtime_close_authority_timeline_actor_role(
                {
                    **row,
                    "payload": payload,
                }
            )
            == "observer"
        ):
            accepted_entered_bindings.append((row, payload))
    entered_candidates = [
        (row, payload)
        for row, payload in accepted_entered_bindings
        if _contract_runtime_shared_batch_enter_binding_verified(
            payload,
            project_id=project_id,
            batch_id=batch_id,
            coordination_backlog_id=coordination_backlog_id,
            merge_queue_id=merge_queue_id,
            queue_rows=queue_rows,
        )
    ]
    if len(entered_candidates) != 1:
        return {}
    entered_event = entered_candidates[0][0]
    entered_event_id = int(entered_event.get("id") or 0)
    batch_enter_task_id = str(
        entered_event.get("task_id") or ""
    ).strip()
    same_task_entered_bindings = [
        (row, payload)
        for row, payload in accepted_entered_bindings
        if str(row.get("task_id") or "").strip() == batch_enter_task_id
    ]
    if (
        not batch_enter_task_id
        or len(same_task_entered_bindings) != 1
        or int(same_task_entered_bindings[0][0].get("id") or 0)
        != entered_event_id
    ):
        return {}

    try:
        provenance_rows = conn.execute(
            """
            SELECT *
            FROM graph_current_full_reconcile_provenance
            WHERE project_id = ? AND snapshot_id = ?
              AND target_commit_sha = ?
            ORDER BY provenance_id ASC
            LIMIT 2
            """,
            (project_id, final_snapshot_id, final_head),
        ).fetchall()
    except sqlite3.Error:
        return {}
    if len(provenance_rows) != 1:
        return {}
    provenance = dict(provenance_rows[0])
    reconcile_event_id = int(
        provenance.get("reconcile_event_id") or 0
    )
    try:
        reconcile_rows = conn.execute(
            """
            SELECT *
            FROM task_timeline_events
            WHERE project_id = ? AND id = ?
            LIMIT 2
            """,
            (project_id, reconcile_event_id),
        ).fetchall()
    except sqlite3.Error:
        return {}
    if len(reconcile_rows) != 1:
        return {}
    reconcile_event = dict(reconcile_rows[0])
    reconcile_task_id = str(
        reconcile_event.get("task_id") or ""
    ).strip()
    reconcile_payload = _json_loads(
        reconcile_event.get("payload_json"),
        {},
    )
    route_evidence = _json_loads(
        provenance.get("route_evidence_json"),
        {},
    )
    marker = _json_loads(provenance.get("marker_json"), {})
    coordination_scope = (
        route_evidence.get("runtime_context_scope")
        if isinstance(route_evidence, Mapping)
        and isinstance(
            route_evidence.get("runtime_context_scope"),
            Mapping,
        )
        else {}
    )
    marker_scope = (
        marker.get("runtime_context_scope")
        if isinstance(marker, Mapping)
        and isinstance(marker.get("runtime_context_scope"), Mapping)
        else {}
    )
    event_scope = (
        reconcile_payload.get("runtime_context_scope")
        if isinstance(reconcile_payload, Mapping)
        and isinstance(
            reconcile_payload.get("runtime_context_scope"),
            Mapping,
        )
        else {}
    )
    coordination_runtime_context_id = str(
        coordination_scope.get("runtime_context_id") or ""
    ).strip()
    coordination_parent_task_id = str(
        coordination_scope.get("parent_task_id") or ""
    ).strip()
    coordination_contract_execution_id = str(
        coordination_scope.get("contract_execution_id") or ""
    ).strip()
    scope_identity = {
        field: str(coordination_scope.get(field) or "").strip()
        for field in (
            "project_id",
            "backlog_id",
            "task_id",
            "parent_task_id",
            "runtime_context_id",
            "merge_queue_id",
            "contract_execution_id",
        )
        if str(coordination_scope.get(field) or "").strip()
    }
    coordination_scope_claimed = bool(
        coordination_scope or marker_scope or event_scope
    )
    coordination_context = (
        get_branch_context_by_runtime_context_id(
            conn,
            project_id,
            coordination_runtime_context_id,
        )
        if coordination_runtime_context_id
        else None
    )
    route_token_scope = (
        route_evidence.get("route_token_scope")
        if isinstance(route_evidence, Mapping)
        and isinstance(route_evidence.get("route_token_scope"), Mapping)
        else {}
    )
    idempotency_scope = (
        route_evidence.get("idempotency_scope")
        if isinstance(route_evidence, Mapping)
        and isinstance(route_evidence.get("idempotency_scope"), Mapping)
        else {}
    )
    marker_route_evidence = (
        marker.get("route_evidence")
        if isinstance(marker, Mapping)
        and isinstance(marker.get("route_evidence"), Mapping)
        else {}
    )
    legacy_task_scope = {
        "project_id": project_id,
        "backlog_id": coordination_backlog_id,
        "task_id": reconcile_task_id,
    }
    deterministic_final_reconcile_task_id = (
        f"{epoch_id}:final-reconcile"
    )
    scoped_coordination_verified = bool(
        coordination_scope_claimed
        and coordination_context is not None
        and scope_identity
        and {
            field: str(marker_scope.get(field) or "").strip()
            for field in scope_identity
        }
        == scope_identity
        and {
            field: str(event_scope.get(field) or "").strip()
            for field in scope_identity
        }
        == scope_identity
        and scope_identity.get("project_id") == project_id
        and scope_identity.get("backlog_id")
        == coordination_backlog_id
        and scope_identity.get("task_id") == batch_enter_task_id
        and scope_identity.get("merge_queue_id") == merge_queue_id
        and str(getattr(coordination_context, "task_id", "") or "").strip()
        == batch_enter_task_id
        and str(
            getattr(coordination_context, "backlog_id", "") or ""
        ).strip()
        == coordination_backlog_id
        and str(
            getattr(coordination_context, "merge_queue_id", "") or ""
        ).strip()
        == merge_queue_id
        and str(
            getattr(coordination_context, "batch_id", "") or ""
        ).strip()
        == batch_id
        and reconcile_task_id == batch_enter_task_id
    )
    task_only_coordination_verified = bool(
        not coordination_scope_claimed
        and not scope_identity
        and reconcile_task_id
        in {
            batch_enter_task_id,
            batch_id,
            deterministic_final_reconcile_task_id,
        }
        and {
            str(field): str(value or "").strip()
            for field, value in route_token_scope.items()
        }
        == legacy_task_scope
        and {
            str(field): str(value or "").strip()
            for field, value in idempotency_scope.items()
        }
        == legacy_task_scope
        and dict(marker_route_evidence) == dict(route_evidence)
        and not any(
            str(route_evidence.get(field) or "").strip()
            for field in (
                "runtime_context_id",
                "parent_task_id",
                "merge_queue_id",
                "contract_execution_id",
            )
        )
    )
    reconcile_time = _contract_runtime_close_authority_time_order_value(
        reconcile_event.get("created_at")
    )
    if not (
        (
            scoped_coordination_verified
            or task_only_coordination_verified
        )
        and str(reconcile_event.get("backlog_id") or "").strip()
        == coordination_backlog_id
        and str(reconcile_event.get("task_id") or "").strip()
        == reconcile_task_id
        and str(reconcile_event.get("event_type") or "").strip()
        == "graph.reconcile"
        and str(reconcile_event.get("event_kind") or "").strip()
        == "reconcile"
        and str(reconcile_event.get("phase") or "").strip() == "reconcile"
        and str(reconcile_event.get("status") or "").strip() == "passed"
        and str(reconcile_event.get("commit_sha") or "").strip().lower()
        == final_head
        and str(reconcile_event.get("created_at") or "").strip()
        == str(provenance.get("reconcile_event_created_at") or "").strip()
        and reconcile_payload.get("current_full_reconcile") is True
        and str(reconcile_payload.get("reconcile_mode") or "").strip()
        == "current_full"
        and reconcile_payload.get("canonical_head_verified") is True
        and reconcile_payload.get("active_snapshot_verified") is True
        and reconcile_payload.get("graph_reconciled") is True
        and _contract_runtime_close_authority_timeline_actor_role(
            {
                **reconcile_event,
                "payload": reconcile_payload,
            }
        )
        == "observer"
        and entered_event_id > 0
        and reconcile_event_id > max(child_merge_event_ids)
        and reconcile_time is not None
        and all(
            reconcile_time
            >= _contract_runtime_close_authority_time_order_value(
                child.get("merge_event_created_at")
            )
            for child in child_authorities
        )
    ):
        return {}

    root = project_service.resolve_project_root(
        project_id,
        None,
        fallback_self=True,
    )
    canonical_head = (
        _git_head_commit(Path(root)).strip().lower() if root else ""
    )
    if not (
        root
        and canonical_head == final_head
        and all(
            _git_commit_is_ancestor(
                Path(root),
                str(child.get("merged_commit_sha") or "")
                .strip()
                .lower(),
                final_head,
            )
            for child in child_authorities
        )
    ):
        return {}

    state = graph_snapshot_store.current_full_reconcile_state(
        conn,
        project_id,
        merged_commit,
        current_canonical_commit_sha=canonical_head,
        reconcile_target_commit_sha=final_head,
        qa_event_id=int(merge.get("qa_event_id") or 0),
        qa_event_created_at=str(merge.get("qa_event_created_at") or ""),
        qa_source_ref=str(merge.get("qa_source_ref") or ""),
        qa_acceptance_created_at=str(
            merge.get("qa_acceptance_created_at") or ""
        ),
        qa_acceptance_revision=int(
            merge.get("qa_acceptance_revision") or 0
        ),
        qa_contract_runtime_verified=final_qa_verified,
        merge_event_id=int(merge.get("merge_event_id") or 0),
        merge_event_created_at=str(merge.get("merge_event_created_at") or ""),
        reconcile_event_id=reconcile_event_id,
        reconcile_event_created_at=str(
            reconcile_event.get("created_at") or ""
        ),
        expected_contract_execution_id=(
            coordination_contract_execution_id
        ),
        expected_task_id=reconcile_task_id,
        expected_runtime_context_id=coordination_runtime_context_id,
        expected_parent_task_id=coordination_parent_task_id,
        expected_merge_queue_id=(
            merge_queue_id if scoped_coordination_verified else ""
        ),
        trusted_contract_execution_lineage_verified=False,
        reconcile_task_id=reconcile_task_id,
        reconcile_runtime_context_id=coordination_runtime_context_id,
        allow_taskless=task_only_coordination_verified,
    )
    active_snapshot_commit = str(
        state.get("active_snapshot_commit") or ""
    ).strip().lower()
    shared_verified = bool(
        state.get("db_verified") is True
        and state.get("active_snapshot_verified") is True
        and state.get(
            "active_snapshot_current_full_reconcile_verified"
        )
        is True
        and state.get("reconcile_snapshot_verified") is True
        and state.get("provenance_scope_verified") is True
        and state.get("durable_order_verified") is True
        and str(state.get("active_snapshot_id") or "").strip()
        == final_snapshot_id
        and str(state.get("reconcile_snapshot_id") or "").strip()
        == final_snapshot_id
        and active_snapshot_commit == final_head
    )
    if not shared_verified:
        return {}

    shared_binding = {
        "schema_version": (
            "contract_runtime.shared_batch_final_reconcile_authority.v1"
        ),
        "source": (
            "parallel_branch_integration_epochs+"
            "parallel_branch_merge_queue_items+"
            "contract_runtime_executions.completed_lines+"
            "graph_current_full_reconcile_provenance"
        ),
        "server_derived": True,
        "db_verified": True,
        "authority_purpose": (
            "postmerge_qa_admission"
            if postmerge_qa_admission
            else "child_close"
        ),
        "project_id": project_id,
        "batch_id": batch_id,
        "merge_queue_id": merge_queue_id,
        "epoch_id": str(epoch.get("epoch_id") or "").strip(),
        "coordination_backlog_id": coordination_backlog_id,
        "coordination_task_id": reconcile_task_id,
        "batch_enter_task_id": batch_enter_task_id,
        "coordination_reconcile_task_id": reconcile_task_id,
        "coordination_runtime_context_id": (
            coordination_runtime_context_id
        ),
        "coordination_contract_execution_id": (
            coordination_contract_execution_id
        ),
        "batch_enter_event_ref": f"timeline:{entered_event_id}",
        "final_reconcile_event_ref": f"timeline:{reconcile_event_id}",
        "final_head_commit": final_head,
        "active_snapshot_id": final_snapshot_id,
        "ordered_queue_item_ids": queue_item_ids,
        "child_contract_dispatch_refs": child_binding_refs,
        "all_children_contract_qa_verified": all(
            child_final_qa_verified
        ),
        "all_children_postmerge_qa_admission_verified": all(
            child_postmerge_qa_admission_verified
        ),
        "current_child_contract_qa_verified": final_qa_verified,
        "final_qa_required_for_current_child": postmerge_qa_admission,
        "all_children_merged": True,
        "closed_epoch_verified": True,
        "final_snapshot_verified": True,
        "strict_child_qa_merge_reconcile_order_verified": (
            not postmerge_qa_admission
        ),
        "strict_child_merge_reconcile_order_verified": True,
        "child_reconcile_required": False,
    }
    shared_binding["authority_hash"] = stable_sha256(shared_binding)
    authority = {
        **dict(state),
        "source": "graph_snapshot_store.current_full_reconcile_state",
        "server_derived": True,
        "timeline_verified": True,
        "authority_verified": True,
        "close_satisfying": not postmerge_qa_admission,
        "db_verified": True,
        "live_verified": True,
        "canonical_head_verified": True,
        "active_snapshot_verified": True,
        "active_snapshot_matches_canonical_head": True,
        "graph_reconciled": True,
        "provenance_scope_verified": True,
        "contract_execution_scope_verified": True,
        "task_scope_verified": True,
        "runtime_context_scope_verified": True,
        "parent_task_scope_verified": True,
        "merge_queue_scope_verified": True,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "merge_queue_id": merge_queue_id,
        "merged_commit_sha": merged_commit,
        "reconciled_commit_sha": final_head,
        "reconcile_provenance_target_commit": final_head,
        "current_canonical_commit_sha": canonical_head,
        "canonical_head_commit": canonical_head,
        "canonical_head_equals_merged_commit": (
            canonical_head == merged_commit
        ),
        "canonical_head_equals_reconciled_commit": True,
        "reconciled_commit_is_ancestor_of_canonical_head": True,
        "target_project_root": str(Path(root).resolve()),
        "merge_source_ref": str(merge.get("merge_source_ref") or ""),
        "merge_event_id": int(merge.get("merge_event_id") or 0),
        "merge_event_created_at": str(
            merge.get("merge_event_created_at") or ""
        ),
        "merge_projection_verified": True,
        "dispatch_lineage_verified": True,
        "contract_runtime_dispatch_source_ref": str(
            dispatch_match.get("source_ref") or ""
        ),
        "qa_source_ref": str(merge.get("qa_source_ref") or ""),
        "qa_acceptance_ref": str(
            merge.get("qa_acceptance_ref") or ""
        ),
        "qa_acceptance_revision": int(
            merge.get("qa_acceptance_revision") or 0
        ),
        "qa_acceptance_created_at": str(
            merge.get("qa_acceptance_created_at") or ""
        ),
        "qa_contract_runtime_verified": final_qa_verified,
        "pre_qa_merge_authorized": postmerge_qa_admission,
        "final_qa_required_after_reconcile": postmerge_qa_admission,
        "reconcile_source_ref": f"timeline:{reconcile_event_id}",
        "reconcile_event_id": reconcile_event_id,
        "reconcile_event_created_at": str(
            reconcile_event.get("created_at") or ""
        ),
        "reconcile_task_id": reconcile_task_id,
        "reconcile_runtime_context_id": (
            coordination_runtime_context_id
        ),
        "shared_batch_reconcile_authority": shared_binding,
        "identity_mismatches": [],
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _contract_runtime_completed_merge_reconcile_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    timeline_events: Sequence[Mapping[str, Any]],
    merge: Mapping[str, Any],
) -> dict[str, Any]:
    """Join current-full reconcile authority onto a completed merge tuple.

    ContractRuntime-completed QA and merge lines intentionally do not require a
    redundant QA timeline event.  Reconcile authority is still task/runtime
    scoped and must resolve through the durable current-full provenance store.
    """

    trusted_merge = dict(merge)
    if trusted_merge.get("timeline_verified") is not True:
        return trusted_merge

    reconcile_policy = _contract_runtime_line_evidence_policy(
        record,
        "current_full_reconcile_evidence_policy",
        line_id="observer_reconcile",
    )
    if not reconcile_policy:
        return trusted_merge

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    backlog_id = str(
        getattr(context, "backlog_id", "") or record.get("backlog_id") or ""
    )
    related_task_ids = {
        str(parent_task_id or "").strip(),
        str(record.get("contract_execution_id") or "").strip(),
        str(record.get("parent_contract_execution_id") or "").strip(),
        str(record.get("root_contract_execution_id") or "").strip(),
    }
    related_task_ids = {item for item in related_task_ids if item}
    server_bound_root_task_ids = (
        _contract_runtime_observer_merge_bound_root_task_ids(
            record,
            context,
        )
    )
    allow_taskless_reconcile = bool(
        reconcile_policy.get(
            "allow_taskless_reconcile_only_for_explicit_shared_batch"
        )
        is True
        and str(getattr(context, "batch_id", "") or "").strip()
        and str(getattr(context, "merge_queue_id", "") or "").strip()
    )
    allow_postmerge_qa_admission = bool(
        _is_mf_parallel_postmerge_revision(record)
        and trusted_merge.get("pre_qa_merge_authorized") is True
        and trusted_merge.get("final_qa_required_after_reconcile") is True
    )
    projection_events = _contract_runtime_projection_post_worker_timeline_events(
        conn,
        project_id=project_id,
        task_id=task_id,
        backlog_id=backlog_id,
        timeline_events=timeline_events,
    )
    reconcile_event = _contract_runtime_projection_latest_timeline_event(
        projection_events,
        runtime_context_id=runtime_context_id,
        task_id=task_id,
        backlog_id=backlog_id,
        kind_tokens={"reconcile", "observer_reconcile"},
        phase_tokens={"reconcile"},
        actor_roles={"observer"},
        allow_taskless=allow_taskless_reconcile,
        related_task_ids=related_task_ids,
        direct_parent_task_id=parent_task_id,
        server_bound_supplemental_related_task_ids=server_bound_root_task_ids,
    )
    if not reconcile_event:
        shared = _contract_runtime_shared_batch_reconcile_authority(
            conn,
            project_id=project_id,
            record=record,
            context=context,
            merge=trusted_merge,
            allow_postmerge_qa_admission=allow_postmerge_qa_admission,
        )
        if not shared:
            return trusted_merge
        enriched = {**trusted_merge, **shared}
        enriched["authority_hash"] = stable_sha256(
            {
                key: value
                for key, value in enriched.items()
                if key != "authority_hash"
            }
        )
        return enriched

    reconcile_scope = _contract_runtime_projection_timeline_scope_values(
        reconcile_event
    )
    reconcile_source_ref = _runtime_context_event_ref(reconcile_event)
    reconcile_event_id = _contract_runtime_projection_timeline_event_id(
        reconcile_event
    )
    audit_authority = (
        trusted_merge.get("qa_audit_only_no_pass_authority")
        if isinstance(
            trusted_merge.get("qa_audit_only_no_pass_authority"), Mapping
        )
        else {}
    )
    expected_reconcile_event_ref = str(
        audit_authority.get("expected_reconcile_event_ref") or ""
    ).strip()
    if expected_reconcile_event_ref and (
        expected_reconcile_event_ref != reconcile_source_ref
    ):
        return trusted_merge
    if audit_authority and reconcile_event_id <= int(
        trusted_merge.get("merge_event_id") or 0
    ):
        return trusted_merge
    reconcile_projection = {
        "timeline_verified": True,
        "allow_taskless_reconcile": allow_taskless_reconcile,
        "reconcile_source_ref": reconcile_source_ref,
        "reconcile_event_id": reconcile_event_id,
        "reconcile_event_created_at": (
            _contract_runtime_projection_timeline_event_time(reconcile_event)
        ),
        "reconcile_task_id": (
            reconcile_scope["task_ids"][0]
            if len(reconcile_scope["task_ids"]) == 1
            else ""
        ),
        "reconcile_runtime_context_id": (
            reconcile_scope["runtime_context_ids"][0]
            if len(reconcile_scope["runtime_context_ids"]) == 1
            else ""
        ),
    }
    recorded_reconcile = {**trusted_merge, **reconcile_projection}
    reconcile_authority = _contract_runtime_current_full_reconcile_authority_from_merge(
        conn,
        project_id=project_id,
        record=record,
        merge=trusted_merge,
        reconcile=reconcile_projection,
    )
    if not _contract_runtime_current_full_reconcile_activation_verified(
        reconcile_authority
    ):
        if allow_postmerge_qa_admission:
            shared = _contract_runtime_shared_batch_reconcile_authority(
                conn,
                project_id=project_id,
                record=record,
                context=context,
                merge=trusted_merge,
                allow_postmerge_qa_admission=True,
            )
            if shared:
                enriched = {**recorded_reconcile, **shared}
                enriched["authority_hash"] = stable_sha256(
                    {
                        key: value
                        for key, value in enriched.items()
                        if key != "authority_hash"
                    }
                )
                return enriched
        return recorded_reconcile
    return {**recorded_reconcile, **reconcile_authority}


_CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION = (
    "contract_runtime.observer_merge_durable_authority.v1"
)
_CONTRACT_RUNTIME_AUDIT_ONLY_BYPASS_ROUND_SCHEMA_VERSION = (
    "contract_runtime.audit_only_no_pass_bypass_round_authority.v1"
)


def _contract_runtime_audit_only_no_pass_bypass_round_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    branch_head: str,
    qa_graph: tuple[int, Mapping[str, Any]],
    round_lines: Sequence[tuple[int, Mapping[str, Any]]],
) -> dict[str, Any]:
    """Join the one audited no-PASS bypass shape without synthesizing PASS."""

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(
        getattr(context, "backlog_id", "") or record.get("backlog_id") or ""
    ).strip()
    branch_head = str(branch_head or "").strip().lower()
    if not (
        execution_id
        and backlog_id
        and runtime_context_id
        and task_id
        and parent_task_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", branch_head)
    ):
        return {}

    qa_graph_index, qa_graph_line = qa_graph
    qa_payload = (
        qa_graph_line.get("payload")
        if isinstance(qa_graph_line.get("payload"), Mapping)
        else {}
    )
    graph = (
        qa_payload.get("graph_trace_evidence")
        if isinstance(qa_payload.get("graph_trace_evidence"), Mapping)
        else {}
    )
    provenance = (
        qa_graph_line.get("qa_evidence_provenance")
        if isinstance(qa_graph_line.get("qa_evidence_provenance"), Mapping)
        else {}
    )
    binding = (
        provenance.get("authenticated_qa_binding")
        if isinstance(provenance.get("authenticated_qa_binding"), Mapping)
        else {}
    )
    trace_ids = _runtime_context_service_dedupe(
        _runtime_context_service_query_values(
            graph, "verified_trace_ids", "trace_ids"
        )
    )
    base_commit = str(
        graph.get("comparison_base_commit_sha")
        or graph.get("base_commit_sha")
        or ""
    ).strip().lower()
    candidate_commit = str(
        graph.get("candidate_commit_sha") or ""
    ).strip().lower()
    qa_principal = str(binding.get("qa_principal") or "").strip()
    qa_session_id = str(binding.get("qa_session_id") or "").strip()
    graph_basis = str(graph.get("graph_basis") or "").strip()
    graph_base = str(graph.get("base_commit_sha") or "").strip().lower()
    graph_scope_valid = bool(
        (
            graph_basis == "canonical_base_plus_candidate_diff"
            and graph_base == base_commit
            and base_commit != branch_head
        )
        or (
            graph_basis == "exact_candidate_snapshot"
            and graph_base == branch_head
            and (
                not graph.get("comparison_base_commit_sha")
                or (
                    base_commit != branch_head
                    and str(
                        graph.get("graph_snapshot_base_commit_sha") or ""
                    )
                    .strip()
                    .lower()
                    == branch_head
                )
            )
        )
    )
    top_commit = str(qa_graph_line.get("commit_sha") or "").strip().lower()
    if not (
        _contract_runtime_authenticated_qa_provenance(qa_graph_line)
        and graph.get("db_verified") is True
        and not list(graph.get("identity_mismatches") or [])
        and candidate_commit == branch_head
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", base_commit)
        and graph_scope_valid
        and trace_ids
        and qa_principal
        and qa_session_id
        and (not top_commit or top_commit == branch_head)
    ):
        return {}

    placeholders = ",".join("?" for _ in trace_ids)
    try:
        rows = conn.execute(
            f"""
            SELECT trace_id, actor, commit_sha, qa_session_id,
                   qa_scope_binding_ref, backlog_id, task_id, status,
                   query_source, query_purpose, graph_basis,
                   base_commit_sha, candidate_commit_sha
            FROM graph_query_traces
            WHERE project_id = ? AND trace_id IN ({placeholders})
            """,
            (project_id, *trace_ids),
        ).fetchall()
    except sqlite3.Error:
        return {}
    expected_trace_tail = (
        qa_principal,
        branch_head,
        qa_session_id,
        _qa_scope_binding_ref(
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            commit_sha=branch_head,
        ),
        backlog_id,
        task_id,
        "complete",
        "qa",
        "independent_verification",
        graph_basis,
        graph_base,
        branch_head,
    )
    actual_traces = {
        (
            str(row["trace_id"] or "").strip(),
            *(
                str(row[key] or "").strip()
                for key in (
                    "actor",
                    "commit_sha",
                    "qa_session_id",
                    "qa_scope_binding_ref",
                    "backlog_id",
                    "task_id",
                    "status",
                    "query_source",
                    "query_purpose",
                    "graph_basis",
                    "base_commit_sha",
                    "candidate_commit_sha",
                )
            ),
        )
        for row in rows
    }
    if actual_traces != {
        (trace_id, *expected_trace_tail) for trace_id in trace_ids
    }:
        return {}

    bypasses = [
        (index, line)
        for index, line in round_lines
        if str(line.get("line_id") or "") == "qa_independent_verification"
        and str(line.get("evidence_kind") or "") == "contract_line_bypass"
    ]
    if len(bypasses) != 1:
        return {}
    bypass_index, bypass_line = bypasses[0]
    bypass = (
        bypass_line.get("payload")
        if isinstance(bypass_line.get("payload"), Mapping)
        else {}
    )
    try:
        bypass_revision = int(bypass.get("execution_state_revision") or 0)
    except (TypeError, ValueError):
        return {}
    bypass_identity = str(bypass.get("bypass_identity") or "").strip()
    diagnostic_id = str(bypass.get("diagnostic_backlog_id") or "").strip()
    refs = {
        str(ref or "").strip()
        for ref in bypass.get("evidence_refs") or []
        if str(ref or "").strip()
    }
    qa_refs = sorted(ref for ref in refs if re.fullmatch(r"timeline:\d+", ref))
    required_refs = {
        f"candidate:{branch_head}",
        f"base:{base_commit}",
        f"contract-runtime:{execution_id}:revision:{bypass_revision}",
        *(f"graph-query:{trace_id}" for trace_id in trace_ids),
    }
    if not (
        bypass_index > qa_graph_index
        and str(bypass_line.get("stage_id") or "") == "qa"
        and str(bypass_line.get("actor_role") or "") == "observer"
        and str(bypass_line.get("status") or "") == "waived"
        and bypass_line.get("no_pass_claim") is True
        and str(bypass.get("schema_version") or "")
        == "contract_line_bypass.v1"
        and str(bypass.get("source_backlog_id") or "") == backlog_id
        and str(bypass.get("classification") or "") == "system_logic"
        and str(bypass.get("blocked_owner_role") or "") == "qa"
        and str(bypass.get("blocked_evidence_kind") or "")
        == "independent_verification"
        and str(bypass.get("disposition") or "")
        == "proceeded_with_exception"
        and bypass.get("no_pass_claim") is True
        and bypass_identity
        == (
            f"bypass:{execution_id}:revision-{bypass_revision}:"
            "qa:qa_independent_verification"
        )
        and diagnostic_id
        and len(qa_refs) == 1
        and required_refs.issubset(refs)
    ):
        return {}
    qa_ref = qa_refs[0]
    qa_event_id = int(qa_ref.split(":", 1)[1])

    diagnostic = conn.execute(
        """
        SELECT status, mf_type, chain_trigger_json, bypass_policy_json
        FROM backlog_bugs WHERE bug_id = ?
        """,
        (diagnostic_id,),
    ).fetchone()
    if not diagnostic:
        return {}
    diagnostic_status = str(diagnostic["status"] or "").strip().upper()
    chain = backlog_runtime.parse_json_object(
        diagnostic["chain_trigger_json"]
    )
    policy = backlog_runtime.parse_json_object(
        diagnostic["bypass_policy_json"]
    )
    binding_shape = {
        "source_backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "line_id": "qa_independent_verification",
        "execution_state_revision": bypass_revision,
        "bypass_identity": bypass_identity,
        "classification": "system_logic",
        "disposition": "proceeded_with_exception",
        "no_pass_claim": True,
    }
    qa_ref_claim = str(chain.get("source_qa_event_ref") or "").strip()
    merge_ref = str(chain.get("source_merge_event_ref") or "").strip()
    reconcile_ref = str(chain.get("source_reconcile_event_ref") or "").strip()
    if not (
        diagnostic_status in {"OPEN", "FIXED"}
        and str(diagnostic["mf_type"] or "") == "chain_rescue"
        and all(chain.get(key) == value for key, value in binding_shape.items())
        and all(policy.get(key) == value for key, value in binding_shape.items())
        and policy.get("keep_open") is True
        and (not qa_ref_claim or qa_ref_claim == qa_ref)
        and (not merge_ref or re.fullmatch(r"timeline:\d+", merge_ref))
        and (
            not reconcile_ref
            or (
                merge_ref
                and re.fullmatch(r"timeline:\d+", reconcile_ref)
            )
        )
    ):
        return {}

    source_events = _runtime_context_service_timeline_events(
        conn,
        project_id=project_id,
        task_id=task_id,
        backlog_id=backlog_id,
    )
    events_by_ref = {
        _runtime_context_event_ref(event): event for event in source_events
    }
    qa_event = events_by_ref.get(qa_ref, {})
    qa_body = (
        qa_event.get("payload")
        if isinstance(qa_event.get("payload"), Mapping)
        else {}
    )
    verification = (
        qa_event.get("verification")
        if isinstance(qa_event.get("verification"), Mapping)
        else {}
    )
    authority = (
        qa_body.get("source_backed_contract_gate_authority")
        if isinstance(
            qa_body.get("source_backed_contract_gate_authority"), Mapping
        )
        else {}
    )
    boundary = _runtime_context_authenticated_failed_qa_timeline_boundary(
        conn=conn,
        context=context,
        runtime_context_id=runtime_context_id,
        timeline_events=source_events,
    )
    failures = (
        qa_body.get("failure_identities")
        if isinstance(qa_body.get("failure_identities"), Mapping)
        else {}
    )
    base_failures = _contract_runtime_failure_identities(failures.get("base"))
    candidate_failures = _contract_runtime_failure_identities(
        failures.get("candidate")
    )
    baseline_failures = _contract_runtime_failure_identities(
        verification.get("known_baseline_failures")
    )
    qa_created_at = _contract_runtime_projection_timeline_event_time(qa_event)
    if not (
        boundary.get("source_ref") == qa_ref
        and boundary.get("commit_sha") == branch_head
        and str(qa_event.get("decision") or "")
        == "accepted_in_scope_no_pass_system_blocked"
        and str(qa_event.get("correlation_id") or "") == execution_id
        and str(qa_body.get("schema_version") or "")
        == "qa.audit_only_no_pass_system_block.v1"
        and str(qa_body.get("base_commit_sha") or "").lower() == base_commit
        and str(qa_body.get("candidate_commit_sha") or "").lower()
        == branch_head
        and qa_body.get("candidate_new_failures") == 0
        and not list(qa_body.get("candidate_specific_issues") or [])
        and qa_body.get("canonical_contract_acceptance_recorded") is False
        and qa_body.get("close_satisfying") is False
        and qa_body.get("no_pass_claim") is True
        and qa_body.get("overall_release_pass_claimed") is False
        and _runtime_context_service_dedupe(
            _runtime_context_service_query_values(
                qa_body, "graph_trace_ids"
            )
        )
        == trace_ids
        and authority.get("audit_only") is True
        and boundary.get("authority_hash")
        == str(authority.get("authority_hash") or "")
        and base_failures
        and base_failures == candidate_failures == baseline_failures
        and str(verification.get("schema_version") or "")
        == "qa.audit_only_no_pass_verification.v1"
        and verification.get("candidate_new_failures") == 0
        and verification.get("close_satisfying") is False
        and verification.get("no_pass_claim") is True
        and verification.get("overall_release_pass_claimed") is False
        and qa_created_at
    ):
        return {}

    correlation_id = f"contract-line-bypass:{bypass_identity}"
    source_bypass = [
        event
        for event in source_events
        if str(event.get("event_type") or "") == "contract_line_bypass"
        and str(event.get("correlation_id") or "") == correlation_id
    ]
    diagnostic_links = [
        event
        for event in _runtime_context_service_timeline_events(
            conn,
            project_id=project_id,
            task_id=task_id,
            backlog_id=diagnostic_id,
        )
        if str(event.get("event_type") or "")
        == "contract_line_bypass_diagnostic_linked"
        and str(event.get("correlation_id") or "") == correlation_id
    ]
    if len(source_bypass) != 1 or len(diagnostic_links) != 1:
        return {}

    def event_identity(event: Mapping[str, Any]) -> tuple[Any, ...]:
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        return (
            str(event.get("event_kind") or ""),
            str(event.get("phase") or ""),
            str(event.get("actor") or ""),
            str(event.get("commit_sha") or "").lower(),
            str(payload.get("bypass_identity") or ""),
            str(payload.get("contract_execution_id") or ""),
            str(payload.get("source_backlog_id") or ""),
            str(payload.get("diagnostic_backlog_id") or ""),
            str(payload.get("classification") or ""),
            str(payload.get("disposition") or ""),
            payload.get("no_pass_claim"),
        )

    expected_event_identity = (
        "record_blocker",
        "qa",
        "observer",
        branch_head,
        bypass_identity,
        execution_id,
        backlog_id,
        diagnostic_id,
        "system_logic",
        "proceeded_with_exception",
        True,
    )
    bypass_event = source_bypass[0]
    diagnostic_event = diagnostic_links[0]
    bypass_event_id = _contract_runtime_projection_timeline_event_id(
        bypass_event
    )
    diagnostic_event_id = _contract_runtime_projection_timeline_event_id(
        diagnostic_event
    )
    merge_event_id = _contract_runtime_projection_timeline_event_id(
        events_by_ref.get(merge_ref, {})
    )
    reconcile_event_id = _contract_runtime_projection_timeline_event_id(
        events_by_ref.get(reconcile_ref, {})
    )
    if not (
        event_identity(bypass_event) == expected_event_identity
        and event_identity(diagnostic_event) == expected_event_identity
        and qa_event_id < bypass_event_id < diagnostic_event_id
        and (not merge_ref or diagnostic_event_id < merge_event_id)
        and (not reconcile_ref or merge_event_id < reconcile_event_id)
    ):
        return {}

    result = {
        "schema_version": (
            _CONTRACT_RUNTIME_AUDIT_ONLY_BYPASS_ROUND_SCHEMA_VERSION
        ),
        "source": (
            "ContractRuntime.qa_graph_context+contract_line_bypass+"
            "backlog_diagnostic+authenticated_qa_timeline+graph_query_traces"
        ),
        "server_derived": True,
        "db_verified": True,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "candidate_commit_sha": branch_head,
        "base_commit_sha": base_commit,
        "failure_identities": candidate_failures,
        "qa_contract_runtime_verified": False,
        "canonical_contract_acceptance_recorded": False,
        "authoritative_pass_synthesized": False,
        "close_satisfying": False,
        "no_pass_claim": True,
        "overall_release_pass_claimed": False,
        "bypass_completed_line_index": bypass_index,
        "qa_event_ref": qa_ref,
        "qa_event_id": qa_event_id,
        "qa_event_created_at": qa_created_at,
        "diagnostic_backlog_id": diagnostic_id,
        "diagnostic_status": diagnostic_status,
        "diagnostic_event_ref": _runtime_context_event_ref(diagnostic_event),
        "diagnostic_event_id": diagnostic_event_id,
        "source_reference_mode": (
            "explicit_post_diagnostic_event_refs"
            if merge_ref
            else "server_derived_post_diagnostic_events"
        ),
        "historical_diagnostic_backfill_required": False,
        "expected_merge_event_ref": merge_ref,
        "expected_reconcile_event_ref": reconcile_ref,
    }
    result["authority_hash"] = stable_sha256(result)
    return result


def _contract_runtime_qa_graph_bypass_round_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    branch_head: str,
    qa_verification: tuple[int, Mapping[str, Any], Mapping[str, Any]],
    round_lines: Sequence[tuple[int, Mapping[str, Any]]],
) -> dict[str, Any]:
    """Join a bypassed QA graph line to its later accepted independent QA.

    The graph line can be system-blocked even though the exact candidate
    snapshot and trace are durable.  In that shape the bypass remains the
    source-generation no-PASS fact, while a later authenticated QA line proves
    that the immutable candidate introduced no candidate-specific failures.
    """

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(
        getattr(context, "backlog_id", "") or record.get("backlog_id") or ""
    ).strip()
    branch_head = str(branch_head or "").strip().lower()
    if not (
        execution_id
        and backlog_id
        and runtime_context_id
        and task_id
        and parent_task_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", branch_head)
    ):
        return {}

    qa_index, qa_line, qa_acceptance = qa_verification
    qa_payload = (
        qa_line.get("payload")
        if isinstance(qa_line.get("payload"), Mapping)
        else {}
    )
    qa_verification_payload = (
        qa_line.get("verification")
        if isinstance(qa_line.get("verification"), Mapping)
        else {}
    )
    qa_provenance = (
        qa_line.get("qa_evidence_provenance")
        if isinstance(qa_line.get("qa_evidence_provenance"), Mapping)
        else {}
    )
    qa_binding = (
        qa_provenance.get("authenticated_qa_binding")
        if isinstance(
            qa_provenance.get("authenticated_qa_binding"), Mapping
        )
        else {}
    )
    qa_principal = str(qa_binding.get("qa_principal") or "").strip()
    qa_session_id = str(qa_binding.get("qa_session_id") or "").strip()
    trace_ids = _runtime_context_service_dedupe(
        _runtime_context_service_query_values(
            qa_payload,
            "graph_trace_ids",
            "graph_query_trace_ids",
            "graph_trace_id",
        )
    )
    candidate_snapshot_id = str(
        qa_payload.get("candidate_snapshot_id") or ""
    ).strip()
    if not (
        qa_acceptance.get("db_verified") is True
        and _contract_runtime_authenticated_qa_provenance(qa_line)
        and qa_binding.get("independent_verification_session_matched") is True
        and str(qa_line.get("stage_id") or "") == "qa"
        and str(qa_line.get("line_id") or "")
        == "qa_independent_verification"
        and str(qa_line.get("actor_role") or "") == "qa"
        and str(qa_line.get("evidence_kind") or "")
        == "independent_verification"
        and str(qa_line.get("status") or "").strip().lower() == "accepted"
        and str(qa_line.get("commit_sha") or "").strip().lower()
        == branch_head
        and str(qa_payload.get("schema_version") or "")
        in {
            "mf_parallel.qa_independent_verification.v1",
            "qa_independent_verification.v1",
        }
        and str(qa_payload.get("acceptance_scope") or "")
        == "candidate_regression_and_acceptance_criteria"
        and str(qa_payload.get("verdict") or "").strip().lower()
        == "accepted"
        and qa_payload.get("candidate_new_failures") == 0
        and not list(qa_payload.get("candidate_specific_issues") or [])
        and qa_payload.get("overall_release_pass_claimed") is False
        and qa_payload.get("source_backlog_pass_claimed") is False
        and qa_payload.get("source_generation_pass_claimed") is False
        and qa_payload.get("source_release_pass_claimed") is False
        and str(
            qa_payload.get("source_qa_graph_context_disposition") or ""
        )
        == "waived"
        and str(qa_payload.get("source_disposition") or "")
        == "proceeded_with_exception"
        and str(
            qa_verification_payload.get("schema_version") or ""
        )
        in {
            "mf_parallel.qa_independent_verification.v1",
            "qa_independent_verification.v1",
        }
        and str(
            qa_verification_payload.get("verdict") or ""
        ).strip().lower()
        == "accepted"
        and qa_verification_payload.get("candidate_new_failures") == 0
        and not list(
            qa_verification_payload.get("candidate_specific_issues") or []
        )
        and qa_verification_payload.get("overall_release_pass_claimed")
        is False
        and qa_verification_payload.get("source_backlog_pass_claimed")
        is False
        and qa_verification_payload.get("source_generation_pass_claimed")
        is False
        and qa_verification_payload.get("source_release_pass_claimed")
        is False
        and str(
            qa_verification_payload.get(
                "source_qa_graph_context_disposition"
            )
            or ""
        )
        == "waived"
        and qa_principal
        and qa_session_id
        and len(trace_ids) == 1
        and candidate_snapshot_id
    ):
        return {}

    bypasses = [
        (index, line)
        for index, line in round_lines
        if str(line.get("line_id") or "") == "qa_graph_context"
        and str(line.get("evidence_kind") or "") == "contract_line_bypass"
    ]
    if len(bypasses) != 1:
        return {}
    bypass_index, bypass_line = bypasses[0]
    bypass = (
        bypass_line.get("payload")
        if isinstance(bypass_line.get("payload"), Mapping)
        else {}
    )
    try:
        bypass_revision = int(bypass.get("execution_state_revision") or 0)
    except (TypeError, ValueError):
        return {}
    bypass_identity = str(bypass.get("bypass_identity") or "").strip()
    diagnostic_id = str(bypass.get("diagnostic_backlog_id") or "").strip()
    source_bypass_event_ref = str(
        qa_payload.get("source_bypass_event_ref") or ""
    ).strip()
    refs = {
        str(ref or "").strip()
        for ref in bypass.get("evidence_refs") or []
        if str(ref or "").strip()
    }
    block_refs = sorted(
        ref for ref in refs if re.fullmatch(r"timeline:\d+", ref)
    )
    trace_refs = {
        ref.split(":", 1)[1]
        for ref in refs
        if re.fullmatch(r"graph-(?:query|trace):[^:]+", ref)
    }
    required_refs = {
        f"backlog:{backlog_id}",
        f"contract-runtime:{execution_id}:revision:{bypass_revision}",
        f"graph-snapshot:{candidate_snapshot_id}",
    }
    if not (
        bypass_index < qa_index
        and str(bypass_line.get("stage_id") or "")
        == "qa_graph_context"
        and str(bypass_line.get("actor_role") or "") == "qa"
        and str(bypass_line.get("status") or "") == "waived"
        and bypass_line.get("no_pass_claim") is True
        and str(bypass.get("schema_version") or "")
        == "contract_line_bypass.v1"
        and str(bypass.get("source_backlog_id") or "") == backlog_id
        and str(bypass.get("classification") or "") == "system_logic"
        and str(bypass.get("blocked_owner_role") or "") == "qa"
        and str(bypass.get("blocked_evidence_kind") or "") == "graph_trace"
        and str(bypass.get("disposition") or "")
        == "proceeded_with_exception"
        and bypass.get("no_pass_claim") is True
        and bypass_identity
        == (
            f"bypass:{execution_id}:revision-{bypass_revision}:"
            "qa_graph_context:qa_graph_context"
        )
        and diagnostic_id
        and str(qa_payload.get("source_diagnostic_backlog_id") or "")
        == diagnostic_id
        and source_bypass_event_ref
        and len(block_refs) == 1
        and trace_refs == set(trace_ids)
        and required_refs.issubset(refs)
    ):
        return {}
    block_ref = block_refs[0]

    placeholders = ",".join("?" for _ in trace_ids)
    try:
        trace_rows = conn.execute(
            f"""
            SELECT trace_id, snapshot_id, actor, commit_sha, qa_session_id,
                   qa_scope_binding_ref, backlog_id, task_id, status,
                   query_source, query_purpose, graph_basis,
                   base_commit_sha, candidate_commit_sha,
                   changed_files_json, candidate_diff_hash
            FROM graph_query_traces
            WHERE project_id = ? AND trace_id IN ({placeholders})
            """,
            (project_id, *trace_ids),
        ).fetchall()
    except sqlite3.Error:
        return {}
    if len(trace_rows) != len(trace_ids):
        return {}
    trace_row = trace_rows[0]
    graph_basis = str(trace_row["graph_basis"] or "").strip()
    graph_base_commit = str(
        trace_row["base_commit_sha"] or ""
    ).strip().lower()
    try:
        changed_files = json.loads(
            str(trace_row["changed_files_json"] or "[]")
        )
    except (TypeError, ValueError, json.JSONDecodeError):
        return {}
    if not isinstance(changed_files, list):
        return {}
    changed_files = [str(item or "").strip() for item in changed_files]
    candidate_diff_hash = str(
        trace_row["candidate_diff_hash"] or ""
    ).strip()
    expected_trace = (
        trace_ids[0],
        candidate_snapshot_id,
        qa_principal,
        branch_head,
        qa_session_id,
        _qa_scope_binding_ref(
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            commit_sha=branch_head,
        ),
        backlog_id,
        task_id,
        "complete",
        "qa",
        "independent_verification",
        "exact_candidate_snapshot",
        branch_head,
        branch_head,
    )
    actual_trace = tuple(
        str(trace_row[key] or "").strip()
        for key in (
            "trace_id",
            "snapshot_id",
            "actor",
            "commit_sha",
            "qa_session_id",
            "qa_scope_binding_ref",
            "backlog_id",
            "task_id",
            "status",
            "query_source",
            "query_purpose",
            "graph_basis",
            "base_commit_sha",
            "candidate_commit_sha",
        )
    )
    if actual_trace != expected_trace:
        return {}
    snapshot = conn.execute(
        """
        SELECT commit_sha, snapshot_kind, status
        FROM graph_snapshots
        WHERE project_id = ? AND snapshot_id = ?
        """,
        (project_id, candidate_snapshot_id),
    ).fetchone()
    if not (
        snapshot
        and str(snapshot["commit_sha"] or "").strip().lower() == branch_head
        and str(snapshot["snapshot_kind"] or "") == "full"
        and str(snapshot["status"] or "")
        in {"candidate", "active", "superseded"}
    ):
        return {}

    diagnostic = conn.execute(
        """
        SELECT status, mf_type, chain_trigger_json, bypass_policy_json
        FROM backlog_bugs WHERE bug_id = ?
        """,
        (diagnostic_id,),
    ).fetchone()
    if not diagnostic:
        return {}
    diagnostic_status = str(diagnostic["status"] or "").strip().upper()
    chain = backlog_runtime.parse_json_object(
        diagnostic["chain_trigger_json"]
    )
    policy = backlog_runtime.parse_json_object(
        diagnostic["bypass_policy_json"]
    )
    binding_shape = {
        "source_backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "line_id": "qa_graph_context",
        "execution_state_revision": bypass_revision,
        "bypass_identity": bypass_identity,
        "classification": "system_logic",
        "disposition": "proceeded_with_exception",
        "no_pass_claim": True,
    }
    qa_ref_claim = str(chain.get("source_qa_event_ref") or "").strip()
    merge_ref = str(chain.get("source_merge_event_ref") or "").strip()
    reconcile_ref = str(chain.get("source_reconcile_event_ref") or "").strip()
    if not (
        diagnostic_status in {"OPEN", "FIXED"}
        and str(diagnostic["mf_type"] or "") == "chain_rescue"
        and all(chain.get(key) == value for key, value in binding_shape.items())
        and all(policy.get(key) == value for key, value in binding_shape.items())
        and policy.get("keep_open") is True
        and (not qa_ref_claim or qa_ref_claim == block_ref)
        and (not merge_ref or re.fullmatch(r"timeline:\d+", merge_ref))
        and (
            not reconcile_ref
            or (
                merge_ref
                and re.fullmatch(r"timeline:\d+", reconcile_ref)
            )
        )
    ):
        return {}

    source_events = _runtime_context_service_timeline_events(
        conn,
        project_id=project_id,
        task_id=task_id,
        backlog_id=backlog_id,
    )
    events_by_ref = {
        _runtime_context_event_ref(event): event for event in source_events
    }
    block_event = events_by_ref.get(block_ref, {})
    block_payload = (
        block_event.get("payload")
        if isinstance(block_event.get("payload"), Mapping)
        else {}
    )
    server_trace = (
        block_payload.get("server_trace_authority")
        if isinstance(block_payload.get("server_trace_authority"), Mapping)
        else {}
    )
    block_event_id = _contract_runtime_projection_timeline_event_id(
        block_event
    )
    block_created_at = _contract_runtime_projection_timeline_event_time(
        block_event
    )
    server_candidate_diff_hash = str(
        server_trace.get("candidate_diff_hash") or ""
    ).strip().lower()
    candidate_diff_hash_matches = bool(
        server_candidate_diff_hash == candidate_diff_hash.lower()
        or (
            re.fullmatch(r"sha256:[0-9a-f]{8,63}", server_candidate_diff_hash)
            and candidate_diff_hash.lower().startswith(
                server_candidate_diff_hash
            )
        )
    )
    if not (
        str(block_event.get("event_type") or "") == "observer.system_block"
        and str(block_event.get("event_kind") or "") == "record_blocker"
        and str(block_event.get("phase") or "") == "qa_graph_context"
        and str(block_event.get("actor") or "") == "observer"
        and str(block_event.get("status") or "") == "blocked"
        and str(block_event.get("commit_sha") or "").strip().lower()
        == branch_head
        and str(block_payload.get("contract_execution_id") or "")
        == execution_id
        and str(block_payload.get("runtime_context_id") or "")
        == runtime_context_id
        and str(block_payload.get("candidate_commit") or "").strip().lower()
        == branch_head
        and str(block_payload.get("candidate_snapshot_id") or "")
        == candidate_snapshot_id
        and str(block_payload.get("fresh_qa_graph_trace_id") or "")
        == trace_ids[0]
        and int(block_payload.get("contract_runtime_revision") or 0)
        == bypass_revision
        and block_payload.get("no_pass_accounting") is True
        and block_payload.get("acceptance_tests_recorded") is False
        and str(server_trace.get("graph_basis") or "") == graph_basis
        and str(
            server_trace.get("base_commit_sha") or ""
        ).strip().lower()
        == graph_base_commit
        and str(
            server_trace.get("candidate_commit_sha") or ""
        ).strip().lower()
        == branch_head
        and list(server_trace.get("changed_files") or []) == changed_files
        and candidate_diff_hash_matches
        and block_event_id > 0
        and block_created_at
    ):
        return {}

    correlation_id = f"contract-line-bypass:{bypass_identity}"
    source_bypass = [
        event
        for event in source_events
        if str(event.get("event_type") or "") == "contract_line_bypass"
        and str(event.get("correlation_id") or "") == correlation_id
    ]
    diagnostic_links = [
        event
        for event in _runtime_context_service_timeline_events(
            conn,
            project_id=project_id,
            task_id=task_id,
            backlog_id=diagnostic_id,
        )
        if str(event.get("event_type") or "")
        == "contract_line_bypass_diagnostic_linked"
        and str(event.get("correlation_id") or "") == correlation_id
    ]
    if len(source_bypass) != 1 or len(diagnostic_links) != 1:
        return {}

    def event_identity(event: Mapping[str, Any]) -> tuple[Any, ...]:
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        return (
            str(event.get("event_kind") or ""),
            str(event.get("phase") or ""),
            str(event.get("actor") or ""),
            str(event.get("commit_sha") or "").lower(),
            str(payload.get("bypass_identity") or ""),
            str(payload.get("contract_execution_id") or ""),
            str(payload.get("source_backlog_id") or ""),
            str(payload.get("diagnostic_backlog_id") or ""),
            str(payload.get("classification") or ""),
            str(payload.get("disposition") or ""),
            payload.get("no_pass_claim"),
        )

    expected_event_identity = (
        "record_blocker",
        "qa_graph_context",
        "qa",
        branch_head,
        bypass_identity,
        execution_id,
        backlog_id,
        diagnostic_id,
        "system_logic",
        "proceeded_with_exception",
        True,
    )
    bypass_event = source_bypass[0]
    diagnostic_event = diagnostic_links[0]
    bypass_event_ref = _runtime_context_event_ref(bypass_event)
    bypass_event_id = _contract_runtime_projection_timeline_event_id(
        bypass_event
    )
    diagnostic_event_id = _contract_runtime_projection_timeline_event_id(
        diagnostic_event
    )
    merge_event_id = _contract_runtime_projection_timeline_event_id(
        events_by_ref.get(merge_ref, {})
    )
    reconcile_event_id = _contract_runtime_projection_timeline_event_id(
        events_by_ref.get(reconcile_ref, {})
    )
    if not (
        event_identity(bypass_event) == expected_event_identity
        and event_identity(diagnostic_event) == expected_event_identity
        and source_bypass_event_ref == bypass_event_ref
        and str(
            qa_verification_payload.get("source_bypass_event_ref") or ""
        )
        == bypass_event_ref
        and block_event_id < bypass_event_id < diagnostic_event_id
        and (not merge_ref or diagnostic_event_id < merge_event_id)
        and (not reconcile_ref or merge_event_id < reconcile_event_id)
    ):
        return {}

    result = {
        "schema_version": (
            _CONTRACT_RUNTIME_AUDIT_ONLY_BYPASS_ROUND_SCHEMA_VERSION
        ),
        "source": (
            "ContractRuntime.qa_graph_context_bypass+"
            "ContractRuntime.qa_independent_verification+"
            "backlog_diagnostic+task_timeline+graph_query_traces"
        ),
        "source_shape": (
            "qa_graph_context_bypass_then_independent_verification"
        ),
        "server_derived": True,
        "db_verified": True,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "candidate_commit_sha": branch_head,
        "base_commit_sha": graph_base_commit,
        "candidate_snapshot_id": candidate_snapshot_id,
        "graph_trace_ids": trace_ids,
        "failure_identities": [],
        "qa_contract_runtime_verified": False,
        "qa_independent_verification_verified": True,
        "qa_independent_verification_completed_line_index": qa_index,
        "qa_contract_runtime_acceptance_ref": str(
            qa_acceptance.get("acceptance_ref") or ""
        ),
        "qa_contract_runtime_acceptance_revision": int(
            qa_acceptance.get("execution_state_revision") or 0
        ),
        "qa_contract_runtime_acceptance_created_at": str(
            qa_acceptance.get("accepted_at") or ""
        ),
        "canonical_contract_acceptance_recorded": False,
        "authoritative_pass_synthesized": False,
        "close_satisfying": False,
        "no_pass_claim": True,
        "overall_release_pass_claimed": False,
        "bypass_line_id": "qa_graph_context",
        "bypass_completed_line_index": bypass_index,
        "qa_event_ref": block_ref,
        "qa_event_id": block_event_id,
        "qa_event_created_at": block_created_at,
        "source_bypass_event_ref": bypass_event_ref,
        "source_bypass_event_id": bypass_event_id,
        "diagnostic_backlog_id": diagnostic_id,
        "diagnostic_status": diagnostic_status,
        "diagnostic_event_ref": _runtime_context_event_ref(diagnostic_event),
        "diagnostic_event_id": diagnostic_event_id,
        "source_reference_mode": (
            "explicit_post_diagnostic_event_refs"
            if merge_ref
            else "server_derived_post_diagnostic_events"
        ),
        "historical_diagnostic_backfill_required": False,
        "expected_merge_event_ref": merge_ref,
        "expected_reconcile_event_ref": reconcile_ref,
    }
    result["authority_hash"] = stable_sha256(result)
    return result


def _contract_runtime_observer_merge_completed_round(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    branch_head: str,
) -> dict[str, Any]:
    """Resolve the source-backed worker/QA round that owns ``branch_head``."""

    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    branch_head = str(branch_head or "").strip().lower()
    if not (
        runtime_context_id
        and task_id
        and parent_task_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", branch_head)
    ):
        return {}

    completed = [
        line
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
    ]

    def values(line: Mapping[str, Any], *keys: str) -> set[str]:
        return {
            str(candidate.get(key) or "").strip()
            for candidate in _contract_runtime_mapping_candidates(line)
            for key in keys
            if str(candidate.get(key) or "").strip()
        }

    def commit_values(line: Mapping[str, Any]) -> set[str]:
        """Return canonical candidate identity, not nested QA comparison commits.

        ``commit_sha`` and ``head_commit`` are authoritative only on the
        completed line or its direct payload transport.  Nested QA test/audit
        mappings retain those generic fields for playback (comparison base,
        baseline reproduction, immediate parent), but they do not identify the
        candidate.  Explicit candidate fields remain conflict-sensitive at any
        supported nesting depth.
        """

        canonical: set[str] = set()

        def add_values(
            candidate: Mapping[str, Any],
            keys: tuple[str, ...],
        ) -> None:
            for key in keys:
                value = str(candidate.get(key) or "").strip()
                if re.fullmatch(r"[0-9a-fA-F]{40}|[0-9a-fA-F]{64}", value):
                    canonical.add(value.lower())

        explicit_candidate_keys = (
            "worker_commit_sha",
            "candidate_commit_sha",
            "validated_head_commit",
            "immutable_head_commit",
        )
        add_values(
            line,
            ("commit_sha", "head_commit", *explicit_candidate_keys),
        )
        payload = line.get("payload")
        if isinstance(payload, Mapping):
            add_values(
                payload,
                ("commit_sha", "head_commit", *explicit_candidate_keys),
            )
        def add_nested_authority_values(
            value: Any,
            *,
            path: tuple[str, ...] = (),
        ) -> None:
            if isinstance(value, Mapping):
                current_key = path[-1].lower() if path else ""
                if _qa_is_immutable_external_audit_subtree(path, value) or (
                    "baseline" in current_key
                    or "comparison" in current_key
                    or current_key == "immediate_parent_full_file"
                ):
                    return
                add_values(value, explicit_candidate_keys)
                for raw_key, child in value.items():
                    key = str(raw_key or "").strip().lower()
                    child_path = (*path, key)
                    if _qa_is_immutable_external_audit_subtree(
                        child_path,
                        child,
                    ):
                        continue
                    if (
                        "baseline" in key
                        or "comparison" in key
                        or key == "immediate_parent_full_file"
                    ):
                        continue
                    add_nested_authority_values(child, path=child_path)
            elif isinstance(value, (list, tuple)):
                for child in value:
                    add_nested_authority_values(child, path=path)

        for key, nested in line.items():
            if key == "payload":
                continue
            add_nested_authority_values(nested, path=(str(key),))
        if isinstance(payload, Mapping):
            for key, nested in payload.items():
                add_nested_authority_values(nested, path=("payload", str(key)))
        return canonical

    def has_no_identity_conflict(
        line: Mapping[str, Any],
        *,
        allow_authenticated_qa_task_parent_alias: bool = False,
    ) -> bool:
        runtime_values = values(line, "runtime_context_id")
        task_values = values(line, "task_id", "worker_task_id")
        parent_values = values(line, "parent_task_id")
        if (
            (runtime_values and runtime_values != {runtime_context_id})
            or (task_values and task_values != {task_id})
        ):
            return False
        if not parent_values or parent_values == {parent_task_id}:
            return True
        return bool(
            allow_authenticated_qa_task_parent_alias
            and parent_values == {task_id}
            and _contract_runtime_authenticated_qa_provenance(line)
        )

    worker_commit_indexes = [
        index
        for index, line in enumerate(completed)
        if str(line.get("line_id") or "").strip() == "worker_commit"
        and str(line.get("actor_role") or "").strip() == "mf_sub"
        and str(line.get("evidence_kind") or "").strip() == "worker_commit"
        and str(line.get("status") or "").strip().lower()
        not in {"waived", "bypassed"}
        and _contract_runtime_line_status_passes(line)
        and commit_values(line) == {branch_head}
        and has_no_identity_conflict(line)
        and _contract_runtime_mapping_matches_context(
            line,
            runtime_context_id=runtime_context_id,
            task_id=task_id,
            parent_task_id=parent_task_id,
            task_id_keys=("task_id", "worker_task_id"),
        )
    ]
    if not worker_commit_indexes:
        return {}
    worker_commit_index = max(worker_commit_indexes)
    next_worker_commit_index = next(
        (
            index
            for index in range(worker_commit_index + 1, len(completed))
            if str(completed[index].get("line_id") or "").strip()
            == "worker_commit"
        ),
        len(completed),
    )

    round_lines = list(
        enumerate(
            completed[worker_commit_index + 1 : next_worker_commit_index],
            start=worker_commit_index + 1,
        )
    )
    qa_graph_lines = [
        (index, line)
        for index, line in round_lines
        if str(line.get("line_id") or "").strip() == "qa_graph_context"
        and str(line.get("actor_role") or "").strip() == "qa"
        and str(line.get("evidence_kind") or "").strip() == "graph_trace"
        and _contract_runtime_line_status_passes(line)
        and commit_values(line) == {branch_head}
        and has_no_identity_conflict(line)
        and isinstance(line.get("payload"), Mapping)
        and isinstance(line["payload"].get("graph_trace_evidence"), Mapping)
        and line["payload"]["graph_trace_evidence"].get("db_verified") is True
        and list(
            line["payload"]["graph_trace_evidence"].get("verified_trace_ids")
            or line["payload"]["graph_trace_evidence"].get("trace_ids")
            or []
        )
    ]
    qa_verification_lines = []
    for index, line in round_lines:
        if not (
            str(line.get("line_id") or "").strip()
            == "qa_independent_verification"
            and str(line.get("actor_role") or "").strip() == "qa"
            and str(line.get("evidence_kind") or "").strip()
            == "independent_verification"
            and _contract_runtime_line_status_passes(line)
            and not _contract_runtime_line_reports_disqualifying_failed_qa(
                line,
                record=record,
            )
            and commit_values(line) == {branch_head}
            and has_no_identity_conflict(
                line,
                allow_authenticated_qa_task_parent_alias=True,
            )
        ):
            continue
        acceptance = _contract_runtime_completed_line_acceptance(
            conn,
            project_id=project_id,
            record=record,
            completed_line_index=index,
            expected_line=line,
        )
        if acceptance.get("db_verified") is True:
            qa_verification_lines.append((index, line, acceptance))
    if (
        _is_mf_parallel_postmerge_revision(record)
        and not qa_graph_lines
        and not qa_verification_lines
    ):
        # rev8 deliberately fans in both worker lanes before canonical
        # reconcile and final integration QA.  The durable merge binder must
        # therefore be able to prove the worker round without inventing the
        # later QA lines.  Older revisions retain their QA-before-merge
        # contract below.
        return {
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "branch_head": branch_head,
            "worker_commit_completed_line_index": worker_commit_index,
            "qa_graph_completed_line_index": -1,
            "qa_completed_line_index": -1,
            "qa_acceptance_ref": "",
            "qa_contract_runtime_verified": False,
            "pre_qa_merge_authorized": True,
            "final_qa_required_after_reconcile": True,
        }
    if len(qa_graph_lines) > 1 or len(qa_verification_lines) > 1:
        return {}
    if len(qa_graph_lines) == 1 and len(qa_verification_lines) == 1:
        qa_graph_index, _qa_graph = qa_graph_lines[0]
        qa_index, _qa, qa_acceptance = qa_verification_lines[0]
        if qa_graph_index >= qa_index:
            return {}
        return {
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "branch_head": branch_head,
            "worker_commit_completed_line_index": worker_commit_index,
            "qa_graph_completed_line_index": qa_graph_index,
            "qa_completed_line_index": qa_index,
            "qa_acceptance_ref": str(qa_acceptance.get("acceptance_ref") or ""),
            "qa_contract_runtime_verified": True,
        }
    if not qa_graph_lines and len(qa_verification_lines) == 1:
        audit_authority = _contract_runtime_qa_graph_bypass_round_authority(
            conn,
            project_id=project_id,
            record=record,
            context=context,
            branch_head=branch_head,
            qa_verification=qa_verification_lines[0],
            round_lines=round_lines,
        )
        if not audit_authority:
            return {}
        return {
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "branch_head": branch_head,
            "worker_commit_completed_line_index": worker_commit_index,
            "qa_graph_completed_line_index": audit_authority[
                "bypass_completed_line_index"
            ],
            "qa_completed_line_index": qa_verification_lines[0][0],
            "qa_acceptance_ref": audit_authority["authority_hash"],
            "qa_contract_runtime_verified": False,
            "qa_audit_only_no_pass_authority": audit_authority,
        }
    if not qa_graph_lines or qa_verification_lines:
        return {}

    qa_graph_index, _qa_graph = qa_graph_lines[0]
    audit_authority = (
        _contract_runtime_audit_only_no_pass_bypass_round_authority(
            conn,
            project_id=project_id,
            record=record,
            context=context,
            branch_head=branch_head,
            qa_graph=qa_graph_lines[0],
            round_lines=round_lines,
        )
    )
    if not audit_authority:
        return {}
    return {
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "branch_head": branch_head,
        "worker_commit_completed_line_index": worker_commit_index,
        "qa_graph_completed_line_index": qa_graph_index,
        "qa_completed_line_index": audit_authority[
            "bypass_completed_line_index"
        ],
        "qa_acceptance_ref": audit_authority["authority_hash"],
        "qa_contract_runtime_verified": False,
        "qa_audit_only_no_pass_authority": audit_authority,
    }


def _contract_runtime_observer_merge_durable_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Export the one durable merge tuple accepted by observer_merge.

    This is the write-side counterpart of
    ``_contract_runtime_completed_merge_authority``.  Keeping the queue and
    timeline join here prevents a caller-shaped merge payload from passing the
    ContractRuntime gate only to lose authority during reconcile.
    """

    from .parallel_branch_runtime import get_merge_queue_item_for_branch_context

    dispatch_lines = [
        line
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
        and str(line.get("line_id") or "").strip()
        == "observer_dispatch_bounded_workers"
    ]
    rev8_two_worker_fanout = _is_mf_parallel_postmerge_revision(record)
    completed_merge_context_ids = {
        _contract_runtime_mapping_value(line, "runtime_context_id")
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
        and str(line.get("line_id") or "").strip() == "observer_merge"
        and _contract_runtime_mapping_value(line, "runtime_context_id")
    }
    dispatch_selection = _contract_runtime_current_dispatch_authority_line(
        record
    )
    dispatch_index = int(
        dispatch_selection.get("completed_line_index") or 0
    )
    contract_execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    dispatch_source_ref = (
        f"contract_runtime:{contract_execution_id}:completed_lines:"
        f"{dispatch_index}"
        if dispatch_selection.get("status") == "selected"
        and contract_execution_id
        else ""
    )
    candidates: list[dict[str, Any]] = []
    for dispatch_line in dispatch_lines:
        for context in _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=dispatch_line,
        ):
            runtime_context_id, task_id, parent_task_id = (
                _contract_runtime_context_identity(context)
            )
            if (
                rev8_two_worker_fanout
                and runtime_context_id in completed_merge_context_ids
            ):
                continue
            backlog_id = str(
                getattr(context, "backlog_id", "")
                or record.get("backlog_id")
                or ""
            ).strip()
            merge_queue_id = str(
                getattr(context, "merge_queue_id", "") or ""
            ).strip()
            durable_item = get_merge_queue_item_for_branch_context(
                conn,
                project_id,
                task_id,
                merge_queue_id=merge_queue_id,
            )
            if (
                durable_item is None
                or durable_item.task_id != task_id
                or durable_item.status != "merged"
            ):
                continue
            merged_commit = str(durable_item.merge_commit or "").strip().lower()
            target_head_after_merge = str(
                durable_item.target_head_after_merge or ""
            ).strip().lower()
            branch_head = str(durable_item.branch_head or "").strip().lower()
            if (
                not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", merged_commit)
                or target_head_after_merge != merged_commit
                or not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", branch_head)
            ):
                continue
            completed_round = _contract_runtime_observer_merge_completed_round(
                conn,
                project_id=project_id,
                record=record,
                context=context,
                branch_head=branch_head,
            )
            if not completed_round:
                continue
            timeline_events = _runtime_context_service_timeline_events(
                conn,
                project_id=project_id,
                task_id=task_id,
                backlog_id=backlog_id,
            )
            related_task_ids = {
                value
                for value in (
                    parent_task_id,
                    str(record.get("contract_execution_id") or "").strip(),
                    str(record.get("parent_contract_execution_id") or "").strip(),
                    str(record.get("root_contract_execution_id") or "").strip(),
                )
                if value
            }
            server_bound_root_task_ids = (
                _contract_runtime_observer_merge_bound_root_task_ids(
                    record,
                    context,
                )
            )
            merge_event = _contract_runtime_projection_latest_timeline_event(
                timeline_events,
                runtime_context_id=runtime_context_id,
                task_id=task_id,
                backlog_id=backlog_id,
                kind_tokens={"live_merge", "merge", "observer_merge"},
                phase_tokens={"live_merge", "merge"},
                actor_roles={"observer"},
                related_task_ids=related_task_ids,
                direct_parent_task_id=parent_task_id,
                server_bound_supplemental_related_task_ids=(
                    server_bound_root_task_ids
                ),
            )
            event_payload = (
                merge_event.get("payload")
                if isinstance(merge_event.get("payload"), Mapping)
                else {}
            )
            event_commit = str(
                merge_event.get("commit_sha")
                or event_payload.get("merge_commit")
                or event_payload.get("target_head_after_merge")
                or ""
            ).strip().lower()
            event_ref = _runtime_context_event_ref(merge_event)
            event_id = _contract_runtime_projection_timeline_event_id(merge_event)
            event_created_at = _contract_runtime_projection_timeline_event_time(
                merge_event
            )
            if (
                event_commit != merged_commit
                or not re.fullmatch(r"timeline:\d+", event_ref)
                or event_id <= 0
                or not event_created_at
            ):
                continue
            audit_authority = completed_round.get(
                "qa_audit_only_no_pass_authority"
            )
            audit_authority = (
                dict(audit_authority)
                if isinstance(audit_authority, Mapping)
                else {}
            )
            expected_merge_event_ref = str(
                audit_authority.get("expected_merge_event_ref") or ""
            ).strip()
            if expected_merge_event_ref and expected_merge_event_ref != event_ref:
                continue
            diagnostic_event_id = int(
                audit_authority.get("diagnostic_event_id") or 0
            )
            if audit_authority and (
                diagnostic_event_id <= 0 or event_id <= diagnostic_event_id
            ):
                continue
            candidates.append(
                {
                    "schema_version": (
                        _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
                    ),
                    "source": (
                        "parallel_branch_merge_queue+task_timeline_merge+"
                        "audit_only_no_pass_bypass_round"
                        if audit_authority
                        else "parallel_branch_merge_queue+task_timeline_merge"
                    ),
                    "server_derived": True,
                    "db_verified": True,
                    "project_id": project_id,
                    "backlog_id": backlog_id,
                    "contract_execution_id": contract_execution_id,
                    "runtime_context_id": runtime_context_id,
                    "task_id": task_id,
                    "parent_task_id": parent_task_id,
                    "worker_role": "mf_sub",
                    "worker_id": str(
                        getattr(context, "worker_id", "") or ""
                    ).strip(),
                    "worker_slot_id": str(
                        getattr(context, "worker_slot_id", "")
                        or getattr(context, "worker_id", "")
                        or ""
                    ).strip(),
                    "lane_id": str(
                        getattr(context, "worker_slot_id", "")
                        or getattr(context, "worker_id", "")
                        or ""
                    ).strip(),
                    "line_instance_id": (
                        f"runtime_context:{runtime_context_id}"
                    ),
                    "branch_head": branch_head,
                    "merge_commit": merged_commit,
                    "target_head_before_merge": str(
                        durable_item.target_head_before_merge or ""
                    ).strip().lower(),
                    "target_head_after_merge": target_head_after_merge,
                    "merge_gate_passed": True,
                    "merge_queue_id": durable_item.merge_queue_id,
                    "queue_item_id": durable_item.queue_item_id,
                    "queue_item_status": durable_item.status,
                    "worker_commit_completed_line_index": completed_round[
                        "worker_commit_completed_line_index"
                    ],
                    "qa_graph_completed_line_index": completed_round[
                        "qa_graph_completed_line_index"
                    ],
                    "qa_completed_line_index": completed_round[
                        "qa_completed_line_index"
                    ],
                    "qa_acceptance_ref": completed_round[
                        "qa_acceptance_ref"
                    ],
                    "qa_contract_runtime_verified": bool(
                        completed_round.get("qa_contract_runtime_verified")
                    ),
                    "pre_qa_merge_authorized": bool(
                        completed_round.get("pre_qa_merge_authorized")
                    ),
                    "final_qa_required_after_reconcile": bool(
                        completed_round.get(
                            "final_qa_required_after_reconcile"
                        )
                    ),
                    "no_pass_claim": bool(audit_authority),
                    "overall_release_pass_claimed": False,
                    "authoritative_pass_synthesized": False,
                    "close_satisfying": bool(
                        not audit_authority
                        and completed_round.get(
                            "pre_qa_merge_authorized"
                        )
                        is not True
                    ),
                    "qa_audit_only_no_pass_authority": audit_authority,
                    "timeline_event_refs": [event_ref],
                    "merge_event_ref": event_ref,
                    "merge_event_id": event_id,
                    "merge_event_created_at": event_created_at,
                    "contract_runtime_dispatch_source_ref": (
                        dispatch_source_ref
                    ),
                }
            )
    return _contract_runtime_select_observer_merge_durable_authority(
        record,
        candidates,
    )


def _contract_runtime_bind_observer_merge_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
) -> dict[str, Any]:
    authority = _contract_runtime_observer_merge_durable_authority(
        conn,
        project_id=project_id,
        record=record,
    )
    if not authority:
        raise GovernanceError(
            "contract_runtime_observer_merge_durable_authority_required",
            (
                "observer_merge requires one server-verified merged queue item "
                "and its matching observer merge timeline event"
            ),
            422,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "next_legal_action": (
                    "complete_durable_merge_queue_apply_then_retry_observer_merge"
                ),
                "fail_closed": True,
            },
        )
    payload = (
        dict(write.get("payload"))
        if isinstance(write.get("payload"), Mapping)
        else {}
    )
    supplied_durable = (
        payload.get("durable_merge_authority")
        if isinstance(payload.get("durable_merge_authority"), Mapping)
        else {}
    )
    expected_values = {
        "branch_head": authority["branch_head"],
        "merge_commit": authority["merge_commit"],
        "target_head_after_merge": authority["target_head_after_merge"],
        "merge_queue_id": authority["merge_queue_id"],
        "queue_item_id": authority["queue_item_id"],
        "queue_item_status": authority["queue_item_status"],
    }
    mismatches: list[dict[str, str]] = []
    mismatches.extend(
        _contract_runtime_observer_merge_lane_identity_mismatches(
            write,
            authority,
            require_all=True,
        )
    )
    mismatches.extend(
        _contract_runtime_observer_merge_lane_identity_mismatches(
            payload,
            authority,
            require_all=False,
            field_prefix="payload.",
        )
    )
    mismatches.extend(
        _contract_runtime_observer_merge_lane_identity_mismatches(
            supplied_durable,
            authority,
            require_all=False,
            field_prefix="durable_merge_authority.",
        )
    )
    supplied_commit = str(write.get("commit_sha") or "").strip().lower()
    if supplied_commit and supplied_commit != authority["merge_commit"]:
        mismatches.append(
            {
                "field": "commit_sha",
                "expected": authority["merge_commit"],
                "actual": supplied_commit,
            }
        )
    for field, expected in expected_values.items():
        supplied = str(payload.get(field) or "").strip().lower()
        if supplied and supplied != str(expected).strip().lower():
            mismatches.append(
                {"field": field, "expected": str(expected), "actual": supplied}
            )
    if payload.get("merge_gate_passed") is False:
        mismatches.append(
            {
                "field": "merge_gate_passed",
                "expected": "true",
                "actual": "false",
            }
        )
    if mismatches:
        raise GovernanceError(
            "contract_runtime_observer_merge_authority_mismatch",
            "observer_merge claims conflict with durable server merge authority",
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "mismatches": mismatches,
                "next_legal_action": (
                    "refresh_contract_runtime_guide_and_copy_observer_merge_"
                    "lane_identity"
                ),
                "guide_source": (
                    "contract_runtime_current.runtime_guide.next_legal_action."
                    "writer_role_safe_copy_payload.copy_payload"
                ),
                "server_may_infer_missing_caller_lane_identity": False,
                "fail_closed": True,
            },
        )
    payload.update(expected_values)
    payload["merge_gate_passed"] = True
    payload["timeline_event_refs"] = list(authority["timeline_event_refs"])
    payload["durable_merge_authority"] = dict(authority)
    audit_authority = authority.get("qa_audit_only_no_pass_authority")
    audit_authority = (
        audit_authority if isinstance(audit_authority, Mapping) else {}
    )
    if audit_authority:
        diagnostic_id = str(
            audit_authority.get("diagnostic_backlog_id") or ""
        ).strip()
        diagnostic_status = str(
            audit_authority.get("diagnostic_status") or ""
        ).strip().upper()
        payload.update(
            {
                "schema_version": "observer_merge.no_pass_exception.v1",
                "disposition": "audit_only_no_pass_bypass_recovery",
                "no_pass_claim": True,
                "overall_release_pass_claimed": False,
                "authoritative_pass_synthesized": False,
                "close_satisfying": False,
                "candidate_new_failures": 0,
                "candidate_specific_issues": [],
                "independent_qa_status": (
                    "accepted_in_scope_no_pass_system_blocked"
                ),
                "system_diagnostics": [
                    {
                        "backlog_id": diagnostic_id,
                        "status": diagnostic_status,
                    }
                ],
                "system_diagnostics_open": (
                    [diagnostic_id] if diagnostic_status == "OPEN" else []
                ),
                "qa_audit_only_no_pass_authority": dict(audit_authority),
            }
        )
    effective = dict(write)
    effective["payload"] = payload
    effective["commit_sha"] = authority["merge_commit"]
    for field in _CONTRACT_RUNTIME_OBSERVER_MERGE_LANE_IDENTITY_FIELDS:
        payload[field] = authority[field]
    if "worker_task_id" in payload:
        payload["worker_task_id"] = authority["task_id"]
    if "root_task_id" in payload:
        payload["root_task_id"] = authority["parent_task_id"]
    for field, value in expected_values.items():
        effective[field] = value
    for field in _CONTRACT_RUNTIME_OBSERVER_MERGE_LANE_IDENTITY_FIELDS:
        effective[field] = authority[field]
    return effective


def _contract_runtime_candidate_scoped_no_pass_line(
    line: Mapping[str, Any],
    *,
    record: Mapping[str, Any] | None = None,
    allow_missing_observer_merge_status: bool = False,
) -> bool:
    """Accept only the bounded, non-release-PASS no-PASS evidence shapes.

    ``no_pass_claim`` is not itself authority.  The exception below is limited
    to the three canonical mf_parallel lines whose other evidence is verified
    by the merge-authority resolver: QA graph traces, independent candidate QA,
    and the server-derived durable merge projection.
    """

    payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
    if (
        payload.get("no_pass_claim") is not True
        or payload.get("overall_release_pass_claimed") is not False
        or line.get("observer_impersonation") is True
        or not _contract_runtime_line_status_passes(line)
        or str(line.get("status") or "").strip().lower() in {"waived", "bypassed"}
        or str(payload.get("disposition") or "").strip()
        == "proceeded_with_exception"
    ):
        return False

    line_id = str(line.get("line_id") or "").strip()
    candidate_scope = "candidate_regression_and_acceptance_criteria"
    commit_sha = str(line.get("commit_sha") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", commit_sha):
        return False

    provenance = (
        line.get("qa_evidence_provenance")
        if isinstance(line.get("qa_evidence_provenance"), Mapping)
        else {}
    )
    qa_provenance_verified = bool(
        str(provenance.get("schema_version") or "")
        == "qa_evidence_provenance.v1"
        and str(provenance.get("authorization_source") or "")
        == "qa_session_token_ref"
        and str(provenance.get("evidence_owner_role") or "") == "qa"
        and provenance.get("observer_impersonation") is False
        and provenance.get("parent_materialization_authorized") is False
    )

    if line_id == "qa_graph_context":
        graph_evidence = (
            payload.get("graph_trace_evidence")
            if isinstance(payload.get("graph_trace_evidence"), Mapping)
            else {}
        )
        graph_commit = str(
            graph_evidence.get("candidate_commit_sha")
            or graph_evidence.get("candidate_commit")
            or ""
        ).strip().lower()
        explicit_candidate_scope = bool(
            payload.get("candidate_new_graph_failures") == 0
            and payload.get("exact_candidate") is True
        )
        canonical_overlay_round_verified = False
        if (
            not explicit_candidate_scope
            and isinstance(record, Mapping)
            and str(graph_evidence.get("graph_basis") or "").strip()
            == "canonical_base_plus_candidate_diff"
            and (
                payload.get("candidate_new_graph_failures") is None
                or payload.get("candidate_new_graph_failures") == 0
            )
            and _contract_runtime_authenticated_qa_provenance(line)
        ):
            completed = _contract_runtime_completed_line_items(record)
            expected_graph_hash = stable_sha256(
                {
                    key: value
                    for key, value in line.items()
                    if not str(key).startswith("_")
                }
            )
            matching_graph_indexes = [
                index
                for index, candidate in enumerate(completed)
                if str(candidate.get("line_id") or "").strip()
                == "qa_graph_context"
                and stable_sha256(
                    {
                        key: value
                        for key, value in candidate.items()
                        if not str(key).startswith("_")
                    }
                )
                == expected_graph_hash
            ]
            qa_candidates: list[tuple[int, Mapping[str, Any]]] = []
            merge_candidates: list[tuple[int, Mapping[str, Any]]] = []
            if len(matching_graph_indexes) == 1:
                graph_index = matching_graph_indexes[0]
                qa_candidates = [
                    (index, candidate)
                    for index, candidate in enumerate(completed)
                    if index > graph_index
                    and str(candidate.get("line_id") or "").strip()
                    == "qa_independent_verification"
                    and _contract_runtime_candidate_scoped_no_pass_line(
                        candidate,
                        record=record,
                    )
                    and _contract_runtime_authority_commit_matches(
                        graph_commit,
                        _contract_runtime_close_authority_explicit_commit(
                            candidate
                        ),
                    )
                ]
                if len(qa_candidates) == 1:
                    qa_index = qa_candidates[0][0]
                    merge_candidates = [
                        (index, candidate)
                        for index, candidate in enumerate(completed)
                        if index > qa_index
                        and str(candidate.get("line_id") or "").strip()
                        == "observer_merge"
                        and (
                            _contract_runtime_server_derived_observer_merge_no_pass_line(
                                candidate,
                                allow_missing_top_level_status=True,
                            )
                        )
                        and _contract_runtime_authority_commit_matches(
                            graph_commit,
                            str(
                                _contract_runtime_close_authority_payload_mapping(
                                    candidate,
                                    "durable_merge_authority",
                                ).get("branch_head")
                                or ""
                            ),
                        )
                    ]
            canonical_overlay_round_verified = bool(
                len(matching_graph_indexes) == 1
                and len(qa_candidates) == 1
                and len(merge_candidates) == 1
            )
        return bool(
            str(line.get("actor_role") or "").strip() == "qa"
            and str(line.get("evidence_kind") or "").strip() == "graph_trace"
            and str(line.get("authorization_source") or "")
            == "qa_session_token_ref"
            and str(payload.get("schema_version") or "")
            in {
                "mf_parallel.qa_graph_context.v1",
                "qa_graph_context.v1",
            }
            and str(payload.get("acceptance_scope") or "") == candidate_scope
            and (explicit_candidate_scope or canonical_overlay_round_verified)
            and qa_provenance_verified
            and graph_evidence.get("db_verified") is True
            and not list(graph_evidence.get("identity_mismatches") or [])
            and list(
                graph_evidence.get("verified_trace_ids")
                or graph_evidence.get("trace_ids")
                or []
            )
            and graph_commit == commit_sha
        )

    if line_id == "qa_independent_verification":
        completion_gate = (
            provenance.get("completion_status_gate")
            if isinstance(provenance.get("completion_status_gate"), Mapping)
            else {}
        )
        ledger = _contract_runtime_qa_no_pass_ledger_authority(
            line,
            record=record,
            allow_immutable_legacy=isinstance(record, Mapping),
        )
        return bool(
            ledger
            and completion_gate.get("server_derived") is True
            and completion_gate.get("top_level_status_present") is True
            and completion_gate.get("top_level_status_passing") is True
            and str(completion_gate.get("normalized_status") or "") == "accepted"
        )

    if line_id == "observer_merge":
        merge_status = str(line.get("status") or "").strip().lower()
        durable = (
            payload.get("durable_merge_authority")
            if isinstance(payload.get("durable_merge_authority"), Mapping)
            else {}
        )
        audit_authority = (
            payload.get("qa_audit_only_no_pass_authority")
            if isinstance(
                payload.get("qa_audit_only_no_pass_authority"), Mapping
            )
            else {}
        )
        durable_audit = (
            durable.get("qa_audit_only_no_pass_authority")
            if isinstance(
                durable.get("qa_audit_only_no_pass_authority"), Mapping
            )
            else {}
        )
        if audit_authority or durable_audit:
            diagnostic_id = str(
                audit_authority.get("diagnostic_backlog_id") or ""
            ).strip()
            diagnostic_status = str(
                audit_authority.get("diagnostic_status") or ""
            ).strip().upper()
            system_diagnostics = payload.get("system_diagnostics")
            return bool(
                audit_authority
                and stable_sha256(audit_authority)
                == stable_sha256(durable_audit)
                and str(audit_authority.get("schema_version") or "")
                == _CONTRACT_RUNTIME_AUDIT_ONLY_BYPASS_ROUND_SCHEMA_VERSION
                and audit_authority.get("server_derived") is True
                and audit_authority.get("db_verified") is True
                and audit_authority.get("qa_contract_runtime_verified") is False
                and audit_authority.get("canonical_contract_acceptance_recorded")
                is False
                and audit_authority.get("authoritative_pass_synthesized") is False
                and audit_authority.get("close_satisfying") is False
                and audit_authority.get("no_pass_claim") is True
                and audit_authority.get("overall_release_pass_claimed") is False
                and str(audit_authority.get("candidate_commit_sha") or "").lower()
                == str(durable.get("branch_head") or "").lower()
                and diagnostic_id
                and diagnostic_status in {"OPEN", "FIXED"}
                and system_diagnostics
                == [{"backlog_id": diagnostic_id, "status": diagnostic_status}]
                and list(payload.get("system_diagnostics_open") or [])
                == ([diagnostic_id] if diagnostic_status == "OPEN" else [])
                and str(line.get("actor_role") or "").strip() == "observer"
                and str(line.get("evidence_kind") or "").strip() == "merge"
                and (
                    merge_status == "accepted"
                    or (
                        allow_missing_observer_merge_status
                        and not merge_status
                    )
                )
                and str(payload.get("schema_version") or "")
                == "observer_merge.no_pass_exception.v1"
                and str(payload.get("disposition") or "")
                == "audit_only_no_pass_bypass_recovery"
                and payload.get("authoritative_pass_synthesized") is False
                and payload.get("close_satisfying") is False
                and payload.get("candidate_new_failures") == 0
                and not list(payload.get("candidate_specific_issues") or [])
                and str(payload.get("independent_qa_status") or "").strip()
                == "accepted_in_scope_no_pass_system_blocked"
                and str(durable.get("schema_version") or "")
                == _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
                and durable.get("server_derived") is True
                and durable.get("db_verified") is True
            )
        return bool(
            str(line.get("actor_role") or "").strip() == "observer"
            and str(line.get("evidence_kind") or "").strip() == "merge"
            and str(line.get("status") or "").strip().lower() == "accepted"
            and str(payload.get("schema_version") or "")
            == "observer_merge.no_pass_exception.v1"
            and payload.get("candidate_new_failures") == 0
            and str(payload.get("independent_qa_status") or "").strip().lower()
            == "accepted"
            and list(payload.get("system_diagnostics_open") or [])
            and str(durable.get("schema_version") or "")
            == _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
            and durable.get("server_derived") is True
            and durable.get("db_verified") is True
        )

    return False


def _contract_runtime_line_reports_disqualifying_failed_qa(
    line: Mapping[str, Any],
    *,
    record: Mapping[str, Any] | None = None,
) -> bool:
    """Separate immutable QA observations from candidate QA failures.

    The generic recursive detector intentionally treats every positive
    ``failed`` count as failed QA.  Two authenticated exceptions are narrow
    enough to preserve fail-closed behavior:

    * a canonical candidate-scoped no-PASS line whose accepted baseline ledger
      proves that inherited failures have no candidate delta; and
    * an explicit top-level QA PASS whose server-derived completion gate proves
      the verdict, while positive counts occur only on immutable
      ``baseline_observation`` rows.
    """

    if _contract_runtime_candidate_scoped_no_pass_line(line, record=record):
        return False
    if _contract_runtime_authenticated_qa_pass_has_only_baseline_observations(
        line
    ):
        return False
    return _contract_runtime_value_reports_failed_qa(line)


def _contract_runtime_server_derived_observer_merge_no_pass_line(
    line: Mapping[str, Any],
    *,
    allow_missing_top_level_status: bool = False,
) -> bool:
    """Allow no-PASS on merge only with the server's durable authority.

    Candidate-scoped QA evidence owns the baseline ledger.  The later
    ``observer_merge`` line must not duplicate that QA shape; its authority is
    instead the exact server-derived durable merge tuple, which the completed
    merge resolver subsequently joins to identity, queue, commit, and timeline
    state.
    """

    payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
    durable = (
        payload.get("durable_merge_authority")
        if isinstance(payload.get("durable_merge_authority"), Mapping)
        else {}
    )
    commit_sha = str(line.get("commit_sha") or "").strip().lower()
    return bool(
        str(line.get("line_id") or "").strip() == "observer_merge"
        and str(line.get("actor_role") or "").strip() == "observer"
        and str(line.get("evidence_kind") or "").strip() == "merge"
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", commit_sha)
        and payload.get("no_pass_claim") is True
        and payload.get("overall_release_pass_claimed") is False
        and line.get("observer_impersonation") is not True
        and _contract_runtime_line_status_passes(line)
        and str(line.get("status") or "").strip().lower()
        not in {"waived", "bypassed"}
        and str(payload.get("disposition") or "").strip()
        != "proceeded_with_exception"
        and str(durable.get("schema_version") or "")
        == _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
        and durable.get("server_derived") is True
        and durable.get("db_verified") is True
        and (
            not isinstance(
                durable.get("qa_audit_only_no_pass_authority"), Mapping
            )
            or not durable.get("qa_audit_only_no_pass_authority")
            or _contract_runtime_candidate_scoped_no_pass_line(
                line,
                allow_missing_observer_merge_status=(
                    allow_missing_top_level_status
                ),
            )
        )
    )


def _contract_runtime_authenticated_nonverdict_qa_graph_line(
    line: Mapping[str, Any],
) -> bool:
    """Recognize accepted QA graph evidence whose no-PASS flag is metadata.

    ``qa_graph_context`` is not a verdict-bearing line.  Some canonical graph
    writes therefore carry ``no_pass_claim=true`` while deferring the actual
    candidate decision to the later independent QA line.  Admit only the
    server-bound, exact-candidate, DB-verified graph shape here; merge
    authority separately requires this exact line's durable acceptance and a
    later authenticated exact-candidate QA PASS.
    """

    payload = (
        line.get("payload")
        if isinstance(line.get("payload"), Mapping)
        else {}
    )
    graph_evidence = (
        payload.get("graph_trace_evidence")
        if isinstance(payload.get("graph_trace_evidence"), Mapping)
        else {}
    )
    commit_sha = str(line.get("commit_sha") or "").strip().lower()
    graph_commit = str(
        graph_evidence.get("candidate_commit_sha")
        or graph_evidence.get("candidate_commit")
        or ""
    ).strip().lower()
    identity_mismatches = graph_evidence.get("identity_mismatches")
    verified_trace_ids = (
        graph_evidence.get("verified_trace_ids")
        or graph_evidence.get("trace_ids")
    )
    verdict_fields = (
        "verdict",
        "decision",
        "result",
        "qa_status",
        "qa_decision",
        "verification_status",
        "verification_decision",
    )
    return bool(
        str(line.get("line_id") or "").strip() == "qa_graph_context"
        and str(line.get("actor_role") or "").strip() == "qa"
        and str(line.get("evidence_kind") or "").strip() == "graph_trace"
        and str(line.get("status") or "").strip().lower()
        in _CONTRACT_RUNTIME_QA_PASSING_STATUSES
        and str(payload.get("schema_version") or "")
        in {
            "mf_parallel.qa_graph_context.v1",
            "qa_graph_context.v1",
        }
        and payload.get("no_pass_claim") is True
        and payload.get("overall_release_pass_claimed") is False
        and payload.get("exact_candidate") is True
        and payload.get("candidate_new_graph_failures") == 0
        and not any(
            str(container.get(field) or "").strip()
            for container in (line, payload)
            for field in verdict_fields
        )
        and line.get("observer_impersonation") is False
        and _contract_runtime_authenticated_qa_provenance(line)
        and not _contract_runtime_value_reports_failed_qa(line)
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", commit_sha)
        and graph_commit == commit_sha
        and graph_evidence.get("db_verified") is True
        and isinstance(identity_mismatches, list)
        and not identity_mismatches
        and isinstance(verified_trace_ids, list)
        and bool(verified_trace_ids)
        and all(str(trace_id or "").strip() for trace_id in verified_trace_ids)
    )


def _contract_runtime_authenticated_exact_candidate_qa_pass(
    line: Mapping[str, Any],
    *,
    candidate_commit_sha: str,
) -> bool:
    """Require the verdict-bearing QA successor for a non-verdict graph line."""

    payload = (
        line.get("payload")
        if isinstance(line.get("payload"), Mapping)
        else {}
    )
    verification = (
        line.get("verification")
        if isinstance(line.get("verification"), Mapping)
        else {}
    )
    test_results = (
        line.get("test_results")
        if isinstance(line.get("test_results"), Mapping)
        else {}
    )
    expected_commit = str(candidate_commit_sha or "").strip().lower()
    line_commit = str(line.get("commit_sha") or "").strip().lower()
    candidate_commits = [
        str(source.get("candidate_commit_sha") or "").strip().lower()
        for source in (payload, verification)
        if str(source.get("candidate_commit_sha") or "").strip()
    ]
    return bool(
        str(line.get("line_id") or "").strip()
        == "qa_independent_verification"
        and str(line.get("actor_role") or "").strip() == "qa"
        and str(line.get("evidence_kind") or "").strip()
        == "independent_verification"
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", expected_commit)
        and line_commit == expected_commit
        and candidate_commits
        and all(commit == expected_commit for commit in candidate_commits)
        and str(line.get("status") or "").strip().lower()
        in _CONTRACT_RUNTIME_QA_PASSING_STATUSES
        and str(payload.get("status") or "").strip().lower()
        in _CONTRACT_RUNTIME_QA_PASSING_STATUSES
        and str(payload.get("verdict") or "").strip().lower()
        in _CONTRACT_RUNTIME_QA_PASSING_STATUSES
        and str(verification.get("status") or "").strip().lower()
        in _CONTRACT_RUNTIME_QA_PASSING_STATUSES
        and str(verification.get("verdict") or "").strip().lower()
        in _CONTRACT_RUNTIME_QA_PASSING_STATUSES
        and payload.get("independent") is True
        and verification.get("independent") is True
        and not any(
            source.get("no_pass_claim") is True
            or source.get("no_pass") is True
            for source in (line, payload, verification, test_results)
        )
        and all(
            source.get("candidate_new_failures") is None
            or source.get("candidate_new_failures") == 0
            for source in (line, payload, verification, test_results)
        )
        and all(
            source.get("candidate_specific_issues") is None
            or source.get("candidate_specific_issues") == []
            for source in (line, payload, verification, test_results)
        )
        and line.get("observer_impersonation") is False
        and _contract_runtime_authenticated_qa_provenance(line)
        and _contract_runtime_authenticated_qa_pass_has_only_baseline_observations(
            line
        )
    )


def _contract_runtime_completed_merge_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    context: Any,
    timeline_events: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Derive merge authority from accepted ContractRuntime lines plus durable merge state.

    Bounded QA and its ordering are ContractRuntime facts.  A redundant QA
    timeline event is audit material, not an authority prerequisite.  The
    merge itself remains cross-checked against both the durable merge queue and
    its observer-authored timeline event.
    """

    from .parallel_branch_runtime import get_merge_queue_item

    completed = [
        line
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
    ]
    if not _contract_runtime_dispatch_line_match(record, context):
        return {}

    def usable_line(
        line: Mapping[str, Any],
        *,
        line_id: str,
        actor_role: str,
        evidence_kind: str,
    ) -> bool:
        payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
        return bool(
            str(line.get("line_id") or "").strip() == line_id
            and str(line.get("actor_role") or "").strip() == actor_role
            and str(line.get("evidence_kind") or "").strip() == evidence_kind
            and str(line.get("status") or "").strip().lower() not in {"waived", "bypassed"}
            and (
                payload.get("no_pass_claim") is not True
                or (
                    _contract_runtime_server_derived_observer_merge_no_pass_line(
                        line,
                        # Historical accepted observer-merge writes may have
                        # been persisted without copying the optional
                        # top-level status.  This only admits the exact
                        # server-derived no-PASS shape into the candidate scan;
                        # the canonical acceptance-revision join below remains
                        # mandatory before it becomes trusted authority.
                        allow_missing_top_level_status=True,
                    )
                    if line_id == "observer_merge"
                    else (
                        _contract_runtime_candidate_scoped_no_pass_line(
                            line,
                            record=record,
                        )
                        or (
                            line_id == "qa_graph_context"
                            and _contract_runtime_authenticated_nonverdict_qa_graph_line(
                                line
                            )
                        )
                    )
                )
            )
            and str(payload.get("disposition") or "").strip()
            != "proceeded_with_exception"
        )

    qa_graph: tuple[int, Mapping[str, Any]] | None = None
    qa_verification: tuple[int, Mapping[str, Any]] | None = None
    merge_line: tuple[int, Mapping[str, Any]] | None = None
    for index, line in enumerate(completed):
        if usable_line(
            line,
            line_id="qa_graph_context",
            actor_role="qa",
            evidence_kind="graph_trace",
        ):
            payload = line.get("payload") if isinstance(line.get("payload"), Mapping) else {}
            graph_evidence = (
                payload.get("graph_trace_evidence")
                if isinstance(payload.get("graph_trace_evidence"), Mapping)
                else {}
            )
            if (
                graph_evidence.get("db_verified") is True
                and not list(graph_evidence.get("identity_mismatches") or [])
                and list(graph_evidence.get("verified_trace_ids") or graph_evidence.get("trace_ids") or [])
            ):
                qa_graph = (index, line)
        if usable_line(
            line,
            line_id="qa_independent_verification",
            actor_role="qa",
            evidence_kind="independent_verification",
        ) and line.get("observer_impersonation") is not True:
            qa_verification = (index, line)
        if usable_line(
            line,
            line_id="observer_merge",
            actor_role="observer",
            evidence_kind="merge",
        ):
            merge_line = (index, line)

    if not merge_line:
        return {}
    merge_top_level_status = str(
        merge_line[1].get("status") or ""
    ).strip().lower()
    merge_payload_for_acceptance = (
        merge_line[1].get("payload")
        if isinstance(merge_line[1].get("payload"), Mapping)
        else {}
    )
    if (
        not merge_top_level_status
        and merge_payload_for_acceptance.get("no_pass_claim") is True
    ):
        merge_acceptance = _contract_runtime_completed_line_acceptance(
            conn,
            project_id=project_id,
            record=record,
            completed_line_index=merge_line[0],
            expected_line=merge_line[1],
            allow_missing_observer_merge_status=True,
        )
        if merge_acceptance.get("db_verified") is not True:
            return {}
    preliminary_merge_payload = (
        merge_line[1].get("payload")
        if isinstance(merge_line[1].get("payload"), Mapping)
        else {}
    )
    preliminary_durable = (
        preliminary_merge_payload.get("durable_merge_authority")
        if isinstance(
            preliminary_merge_payload.get("durable_merge_authority"),
            Mapping,
        )
        else {}
    )
    preliminary_branch_head = str(
        preliminary_durable.get("branch_head")
        or preliminary_merge_payload.get("branch_head")
        or ""
    ).strip().lower()
    durable_audit = (
        preliminary_durable.get("qa_audit_only_no_pass_authority")
        if isinstance(
            preliminary_durable.get("qa_audit_only_no_pass_authority"),
            Mapping,
        )
        else {}
    )
    durable_completed_round: dict[str, Any] = {}
    if preliminary_durable:
        if (
            str(preliminary_durable.get("schema_version") or "")
            != _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
            or preliminary_durable.get("server_derived") is not True
            or preliminary_durable.get("db_verified") is not True
        ):
            return {}
        durable_completed_round = (
            _contract_runtime_observer_merge_completed_round(
                conn,
                project_id=project_id,
                record=record,
                context=context,
                branch_head=preliminary_branch_head,
            )
        )
        if not durable_completed_round:
            return {}
        durable_round_fields = (
            "worker_commit_completed_line_index",
            "qa_graph_completed_line_index",
            "qa_completed_line_index",
            "qa_acceptance_ref",
        )
        if (
            any(
                str(preliminary_durable.get(field) or "").strip()
                != str(durable_completed_round.get(field) or "").strip()
                for field in durable_round_fields
            )
            or bool(
                preliminary_durable.get("qa_contract_runtime_verified")
            )
            != bool(
                durable_completed_round.get(
                    "qa_contract_runtime_verified"
                )
            )
        ):
            return {}

    qa_acceptance: dict[str, Any] = {}
    audit_authority: dict[str, Any] = {}
    completed_round: dict[str, Any] = {}
    if durable_audit:
        completed_round = durable_completed_round
        audit_authority = (
            dict(completed_round.get("qa_audit_only_no_pass_authority"))
            if isinstance(
                completed_round.get("qa_audit_only_no_pass_authority"),
                Mapping,
            )
            else {}
        )
        if not (
            audit_authority
            and stable_sha256(audit_authority) == stable_sha256(durable_audit)
            and completed_round.get("qa_contract_runtime_verified") is False
        ):
            return {}
        qa_graph_index = int(
            completed_round.get("qa_graph_completed_line_index") or -1
        )
        qa_index = int(completed_round.get("qa_completed_line_index") or -1)
        bypass_index = int(
            audit_authority.get("bypass_completed_line_index") or -1
        )
        if not (
            0 <= qa_graph_index < len(completed)
            and 0 <= qa_index < len(completed)
            and bypass_index >= 0
            and qa_graph_index < merge_line[0]
            and qa_index < merge_line[0]
        ):
            return {}
        source_shape = str(audit_authority.get("source_shape") or "")
        if source_shape == (
            "qa_graph_context_bypass_then_independent_verification"
        ):
            if not (
                qa_graph_index == bypass_index
                and qa_graph_index < qa_index < merge_line[0]
                and str(completed[qa_graph_index].get("line_id") or "")
                == "qa_graph_context"
                and str(
                    completed[qa_graph_index].get("evidence_kind") or ""
                )
                == "contract_line_bypass"
                and str(completed[qa_index].get("line_id") or "")
                == "qa_independent_verification"
                and str(completed[qa_index].get("evidence_kind") or "")
                == "independent_verification"
                and int(
                    audit_authority.get(
                        "qa_independent_verification_completed_line_index"
                    )
                    or -1
                )
                == qa_index
            ):
                return {}
            qa_graph = None
            qa_verification = (qa_index, completed[qa_index])
            qa_acceptance = {
                "acceptance_ref": str(
                    audit_authority.get(
                        "qa_contract_runtime_acceptance_ref"
                    )
                    or ""
                ),
                "execution_state_revision": int(
                    audit_authority.get(
                        "qa_contract_runtime_acceptance_revision"
                    )
                    or 0
                ),
                "accepted_at": str(
                    audit_authority.get(
                        "qa_contract_runtime_acceptance_created_at"
                    )
                    or ""
                ),
            }
        elif source_shape in {
            "",
            "qa_independent_verification_bypass",
        }:
            if not (
                qa_index == bypass_index
                and qa_graph_index < qa_index < merge_line[0]
                and qa_graph
                and qa_graph[0] == qa_graph_index
            ):
                return {}
            qa_verification = None
        else:
            return {}
    else:
        if preliminary_durable:
            if (
                durable_completed_round.get(
                    "qa_contract_runtime_verified"
                )
                is not True
            ):
                return {}
            qa_graph_index = int(
                durable_completed_round.get(
                    "qa_graph_completed_line_index"
                )
                or -1
            )
            qa_index = int(
                durable_completed_round.get("qa_completed_line_index")
                or -1
            )
            if not (
                0 <= qa_graph_index < qa_index < merge_line[0]
                and qa_index < len(completed)
            ):
                return {}
            qa_graph = (qa_graph_index, completed[qa_graph_index])
            qa_verification = (qa_index, completed[qa_index])
            qa_acceptance = _contract_runtime_completed_line_acceptance(
                conn,
                project_id=project_id,
                record=record,
                completed_line_index=qa_index,
                expected_line=qa_verification[1],
            )
            if not (
                qa_acceptance.get("db_verified") is True
                and str(
                    qa_acceptance.get("acceptance_ref") or ""
                ).strip()
                == str(
                    preliminary_durable.get("qa_acceptance_ref") or ""
                ).strip()
            ):
                return {}
        if not qa_graph or not qa_verification:
            return {}
        if not (qa_graph[0] < qa_verification[0] < merge_line[0]):
            return {}
        nonverdict_qa_graph = (
            _contract_runtime_authenticated_nonverdict_qa_graph_line(
                qa_graph[1]
            )
            and not _contract_runtime_candidate_scoped_no_pass_line(
                qa_graph[1],
                record=record,
            )
        )
        if nonverdict_qa_graph:
            graph_acceptance = _contract_runtime_completed_line_acceptance(
                conn,
                project_id=project_id,
                record=record,
                completed_line_index=qa_graph[0],
                expected_line=qa_graph[1],
            )
            graph_payload = (
                qa_graph[1].get("payload")
                if isinstance(qa_graph[1].get("payload"), Mapping)
                else {}
            )
            graph_evidence = (
                graph_payload.get("graph_trace_evidence")
                if isinstance(
                    graph_payload.get("graph_trace_evidence"),
                    Mapping,
                )
                else {}
            )
            if (
                graph_acceptance.get("db_verified") is not True
                or not _contract_runtime_authenticated_exact_candidate_qa_pass(
                    qa_verification[1],
                    candidate_commit_sha=str(
                        graph_evidence.get("candidate_commit_sha")
                        or graph_evidence.get("candidate_commit")
                        or ""
                    ),
                )
            ):
                return {}
        if (
            not _contract_runtime_line_status_passes(qa_verification[1])
            or _contract_runtime_line_reports_disqualifying_failed_qa(
                qa_verification[1],
                record=record,
            )
        ):
            return {}
        qa_acceptance = _contract_runtime_completed_line_acceptance(
            conn,
            project_id=project_id,
            record=record,
            completed_line_index=qa_verification[0],
            expected_line=qa_verification[1],
        )
        if qa_acceptance.get("db_verified") is not True:
            return {}

    qa_graph_payload = (
        qa_graph[1].get("payload")
        if qa_graph
        and isinstance(qa_graph[1].get("payload"), Mapping)
        else {}
    )
    graph_evidence = (
        qa_graph_payload.get("graph_trace_evidence")
        if isinstance(qa_graph_payload.get("graph_trace_evidence"), Mapping)
        else {}
    )
    qa_payload = (
        qa_verification[1].get("payload")
        if qa_verification
        and isinstance(qa_verification[1].get("payload"), Mapping)
        else {
            "acceptance_scope": (
                "candidate_regression_and_acceptance_criteria"
            ),
            "candidate_new_failures": 0,
        }
    )
    merge_payload = (
        merge_line[1].get("payload")
        if isinstance(merge_line[1].get("payload"), Mapping)
        else {}
    )
    durable_merge_authority = (
        merge_payload.get("durable_merge_authority")
        if isinstance(merge_payload.get("durable_merge_authority"), Mapping)
        else {}
    )
    if durable_merge_authority and (
        str(durable_merge_authority.get("schema_version") or "")
        != _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
        or durable_merge_authority.get("server_derived") is not True
        or durable_merge_authority.get("db_verified") is not True
    ):
        return {}
    merge_schema = durable_merge_authority or merge_payload
    qa_commit = str(
        audit_authority.get("candidate_commit_sha")
        or (
            qa_verification[1].get("commit_sha")
            if qa_verification
            else ""
        )
        or qa_payload.get("candidate_commit_sha")
        or ""
    ).strip().lower()
    graph_candidate_commit = str(
        graph_evidence.get("candidate_commit_sha")
        or graph_evidence.get("candidate_commit")
        or ""
    ).strip().lower()
    branch_head = str(merge_schema.get("branch_head") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", qa_commit):
        return {}
    if graph_candidate_commit and graph_candidate_commit != qa_commit:
        return {}
    if branch_head and branch_head != qa_commit:
        return {}

    merged_commit = str(
        merge_line[1].get("commit_sha")
        or merge_schema.get("merge_commit")
        or merge_schema.get("target_head_after_merge")
        or ""
    ).strip().lower()
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", merged_commit):
        return {}
    for key in ("merge_commit", "target_head_after_merge"):
        value = str(merge_schema.get(key) or "").strip().lower()
        if value and value != merged_commit:
            return {}
    if merge_schema.get("merge_gate_passed") is not True:
        return {}
    if str(merge_schema.get("queue_item_status") or "").strip() != "merged":
        return {}

    merge_queue_id = str(merge_schema.get("merge_queue_id") or "").strip()
    queue_item_id = str(merge_schema.get("queue_item_id") or "").strip()
    if not merge_queue_id or not queue_item_id:
        return {}
    durable_item = get_merge_queue_item(
        conn,
        project_id,
        merge_queue_id,
        queue_item_id,
    )
    runtime_context_id, task_id, parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    if durable_merge_authority and any(
        str(durable_merge_authority.get(field) or "").strip()
        != str(expected or "").strip()
        for field, expected in (
            ("project_id", project_id),
            (
                "backlog_id",
                str(
                    getattr(context, "backlog_id", "")
                    or record.get("backlog_id")
                    or ""
                ),
            ),
            ("runtime_context_id", runtime_context_id),
            ("task_id", task_id),
            ("parent_task_id", parent_task_id),
        )
    ):
        return {}
    if (
        durable_item is None
        or durable_item.task_id != task_id
        or durable_item.status != "merged"
        or str(durable_item.merge_commit or "").strip().lower() != merged_commit
        or str(durable_item.target_head_after_merge or "").strip().lower()
        != merged_commit
    ):
        return {}

    timeline_refs = {
        str(item or "").strip()
        for item in merge_schema.get("timeline_event_refs") or []
        if str(item or "").strip()
    }
    merge_events: list[Mapping[str, Any]] = []
    for event in timeline_events:
        if not isinstance(event, Mapping):
            continue
        event_payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        event_commit = str(
            event.get("commit_sha")
            or event_payload.get("merge_commit")
            or event_payload.get("target_head_after_merge")
            or ""
        ).strip().lower()
        source_ref = _runtime_context_event_ref(event)
        event_kind = str(event.get("event_kind") or event.get("event_type") or "").lower()
        if (
            event_commit == merged_commit
            and ("merge" in event_kind)
            and (not timeline_refs or source_ref in timeline_refs)
        ):
            merge_events.append(event)
    if len(merge_events) != 1:
        return {}
    merge_event = merge_events[0]
    merge_event_id = _contract_runtime_projection_timeline_event_id(merge_event)
    merge_event_created_at = _contract_runtime_projection_timeline_event_time(
        merge_event
    )
    if merge_event_id <= 0 or not merge_event_created_at:
        return {}

    no_pass_lines = [merge_line[1]]
    if qa_graph and not (
        _contract_runtime_authenticated_nonverdict_qa_graph_line(
            qa_graph[1]
        )
        and not _contract_runtime_candidate_scoped_no_pass_line(
            qa_graph[1],
            record=record,
        )
    ):
        no_pass_lines.append(qa_graph[1])
    if qa_verification:
        no_pass_lines.append(qa_verification[1])
    no_pass_claim = bool(audit_authority) or any(
        (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        ).get("no_pass_claim")
        is True
        for line in no_pass_lines
    )
    baseline_ledger = (
        qa_verification[1].get("artifact_refs", {}).get(
            "external_no_pass_baseline_ledger"
        )
        if qa_verification
        and isinstance(qa_verification[1].get("artifact_refs"), Mapping)
        and isinstance(
            qa_verification[1].get("artifact_refs", {}).get(
                "external_no_pass_baseline_ledger"
            ),
            Mapping,
        )
        else {}
    )
    base_reproduction = dict(baseline_ledger.get("base_reproduction") or {})
    if audit_authority:
        failure_identities = list(
            audit_authority.get("failure_identities") or []
        )
        base_reproduction = {
            "reproduced": len(failure_identities),
            "total": len(failure_identities),
            "failure_identities": failure_identities,
        }
    return {
        "timeline_verified": True,
        "authority_verified": True,
        "no_pass_claim": no_pass_claim,
        "overall_release_pass_claimed": False,
        "qa_acceptance_scope": str(qa_payload.get("acceptance_scope") or ""),
        "candidate_new_failures": qa_payload.get("candidate_new_failures"),
        "base_reproduction": base_reproduction,
        "authority_source": (
            "contract_runtime_audited_bypass_round+"
            "server_durable_merge_schema+durable_merge_queue+task_timeline_merge"
            if audit_authority
            else "contract_runtime_completed_lines+server_durable_merge_schema+"
            "durable_merge_queue+task_timeline_merge"
            if durable_merge_authority
            else "contract_runtime_completed_lines+durable_merge_queue+task_timeline_merge"
        ),
        "durable_merge_schema_version": str(
            durable_merge_authority.get("schema_version") or "legacy_flattened"
        ),
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "backlog_id": str(
            getattr(context, "backlog_id", "")
            or record.get("backlog_id")
            or ""
        ),
        "merged_commit_sha": merged_commit,
        "qa_source_ref": str(
            audit_authority.get("qa_event_ref")
            or qa_acceptance.get("completed_line_ref")
            or ""
        ),
        "qa_event_id": int(audit_authority.get("qa_event_id") or 0),
        "qa_event_created_at": str(
            audit_authority.get("qa_event_created_at") or ""
        ),
        "qa_acceptance_created_at": str(
            qa_acceptance.get("accepted_at") or ""
        ),
        "qa_acceptance_revision": int(
            qa_acceptance.get("execution_state_revision") or 0
        ),
        "qa_acceptance_ref": str(
            audit_authority.get("authority_hash")
            or qa_acceptance.get("acceptance_ref")
            or ""
        ),
        "qa_contract_runtime_verified": not bool(audit_authority),
        "qa_graph_completed_line_index": (
            int(completed_round.get("qa_graph_completed_line_index") or -1)
            if audit_authority
            else qa_graph[0]
        ),
        "qa_completed_line_index": (
            int(completed_round.get("qa_completed_line_index") or -1)
            if audit_authority
            else qa_verification[0]
        ),
        "qa_audit_only_no_pass_authority": audit_authority,
        "authoritative_pass_synthesized": False,
        "close_satisfying": False if audit_authority else True,
        "merge_completed_line_index": merge_line[0],
        "merge_source_ref": _runtime_context_event_ref(merge_event),
        "merge_event_id": merge_event_id,
        "merge_event_created_at": merge_event_created_at,
        "merge_queue_id": merge_queue_id,
        "queue_item_id": queue_item_id,
    }


def _contract_runtime_append_completed_line_correction(
    runtime: Any,
    record: Mapping[str, Any],
    line: Mapping[str, Any],
    *,
    contract_execution_id: str,
    actor_role: str,
    expected_next_line_id: str,
) -> dict[str, Any]:
    """Append evidence without replaying an already-completed transition."""

    expected_revision = int(record.get("execution_state_revision") or 1)
    completed_lines = [*(record.get("completed_lines") or []), dict(line)]
    candidate = {
        **record,
        "completed_lines": completed_lines,
        "execution_state_revision": expected_revision + 1,
    }
    updated = runtime._record_view(
        candidate,
        actor_role=actor_role,
        completed_lines=completed_lines,
    )
    next_line = (
        updated.get("runtime_guide", {}).get("next_legal_action", {})
        if isinstance(updated.get("runtime_guide"), Mapping)
        else {}
    )
    if str(next_line.get("line_id") or "").strip() != expected_next_line_id:
        return {}
    runtime.store.update(
        contract_execution_id,
        updated,
        expected_revision=expected_revision,
    )
    return runtime.store.get(contract_execution_id)


def _contract_runtime_statusless_worker_finish_gate_acceptance(
    line: Mapping[str, Any],
    *,
    expected_worker_identity: Mapping[str, Any],
) -> bool:
    """Recognize the canonical finish facade's statusless durable line.

    The finish facade predates generic top-level ``status`` normalization. Its
    payload retains the startup-time self-attestation diagnostics (which may
    legitimately be blocked before the implementation diff exists), then
    records a distinct finish-time PASS and close-ready checkpoint.  Only the
    historical startup observation is excluded from the failure scan; every
    current finish result remains closed and exact.
    """

    payload = (
        line.get("payload")
        if isinstance(line.get("payload"), Mapping)
        else {}
    )
    nested = (
        payload.get("mf_subagent_finish_gate")
        if isinstance(payload.get("mf_subagent_finish_gate"), Mapping)
        else {}
    )
    projection = (
        payload.get("close_gate_projection")
        if isinstance(payload.get("close_gate_projection"), Mapping)
        else {}
    )
    self_gate = (
        payload.get("worker_self_attestation_gate")
        if isinstance(payload.get("worker_self_attestation_gate"), Mapping)
        else {}
    )
    self_attestation = (
        payload.get("worker_self_attestation")
        if isinstance(payload.get("worker_self_attestation"), Mapping)
        else {}
    )
    test_results = (
        payload.get("test_results")
        if isinstance(payload.get("test_results"), Mapping)
        else {}
    )
    expected = {
        field: str(expected_worker_identity.get(field) or "").strip()
        for field in (
            "runtime_context_id",
            "task_id",
            "parent_task_id",
            "worker_id",
            "worker_slot_id",
            "merge_queue_id",
        )
    }
    runtime_context_id = expected["runtime_context_id"]
    line_instance_id = f"runtime_context:{runtime_context_id}"
    checkpoint_id = str(payload.get("checkpoint_id") or "").strip()
    validated_head = str(
        payload.get("validated_head_commit") or ""
    ).strip().lower()
    identity_fields = (
        "runtime_context_id",
        "task_id",
        "parent_task_id",
        "worker_id",
        "worker_slot_id",
    )
    if not (
        all(expected.values())
        and str(line.get("stage_id") or "").strip() == "worker_finish"
        and str(line.get("line_id") or "").strip()
        == "worker_finish_gate"
        and str(line.get("actor_role") or "").strip() == "mf_sub"
        and str(line.get("evidence_kind") or "").strip()
        == "mf_subagent_finish_gate"
        and not any(
            str(line.get(field) or "").strip()
            for field in ("status", "verdict", "decision")
        )
        and all(
            str(line.get(field) or "").strip() == expected[field]
            for field in identity_fields
        )
        and str(line.get("line_instance_id") or "").strip()
        == line_instance_id
        and str(payload.get("schema_version") or "")
        == "mf_subagent_finish_gate.v1"
        and str(nested.get("schema_version") or "")
        == "mf_subagent_finish_gate.v1"
        and all(
            str(source.get(field) or "").strip() == expected[field]
            for source in (payload, nested)
            for field in identity_fields
        )
        and str(payload.get("merge_queue_id") or "").strip()
        == expected["merge_queue_id"]
        and str(nested.get("merge_queue_id") or "").strip()
        == expected["merge_queue_id"]
        and str(payload.get("line_instance_id") or "").strip()
        == line_instance_id
        and re.fullmatch(r"ckpt-finish-[0-9a-f]{20,64}", checkpoint_id)
        and str(nested.get("checkpoint_id") or "").strip()
        == checkpoint_id
        and str(projection.get("checkpoint_id") or "").strip()
        == checkpoint_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", validated_head)
        and all(
            str(source.get(field) or "").strip().lower()
            == validated_head
            for source, field in (
                (line, "head_commit"),
                (line, "validated_head_commit"),
                (payload, "head_commit"),
                (nested, "head_commit"),
                (nested, "validated_head_commit"),
                (projection, "head_commit"),
            )
        )
        and payload.get("close_ready") is True
        and nested.get("close_ready") is True
        and projection.get("close_ready") is True
        and str(projection.get("schema_version") or "")
        == "mf_subagent_finish_gate_close_projection.v1"
        and payload.get("waiting_merge") is True
        and nested.get("waiting_merge") is True
        and str(payload.get("worker_status") or "") == "waiting_merge"
        and str(nested.get("worker_status") or "") == "waiting_merge"
        and test_results.get("passed") is True
        and str(test_results.get("status") or "").strip().lower()
        == "passed"
        and stable_sha256(test_results)
        == stable_sha256(nested.get("test_results"))
        and str(self_gate.get("schema_version") or "")
        == "mf_subagent_finish_time_worker_self_attestation_gate.v1"
        and self_gate.get("passed") is True
        and self_gate.get("close_satisfying") is True
        and str(self_gate.get("status") or "").strip().lower()
        == "passed"
        and not list(self_gate.get("blockers") or [])
        and not list(self_gate.get("finish_time_blockers") or [])
        and stable_sha256(self_gate)
        == stable_sha256(nested.get("worker_self_attestation_gate"))
        and self_attestation.get("ok") is True
        and str(self_attestation.get("status") or "").strip().lower()
        == "passed"
        and self_attestation.get("finish_time_self_attesting") is True
        and not list(self_attestation.get("blockers") or [])
        and not list(self_attestation.get("finish_time_blockers") or [])
        and stable_sha256(self_attestation)
        == stable_sha256(nested.get("worker_self_attestation"))
        and stable_sha256(projection)
        == stable_sha256(nested.get("close_gate_projection"))
    ):
        return False

    failure_scan = deepcopy(dict(payload))
    nested_scan = failure_scan.get("mf_subagent_finish_gate")
    sources = [failure_scan]
    if isinstance(nested_scan, dict):
        sources.append(nested_scan)
    for source in sources:
        for field in (
            "startup_evidence",
            "close_satisfying_startup_evidence",
        ):
            startup = source.get(field)
            if not isinstance(startup, Mapping):
                return False
            startup = deepcopy(dict(startup))
            if not (
                str(startup.get("status") or "").strip().lower()
                == "passed"
                and startup.get("actual_startup_recorded") is True
                and str(startup.get("runtime_context_id") or "").strip()
                == runtime_context_id
                and str(startup.get("task_id") or "").strip()
                == expected["task_id"]
                and str(startup.get("parent_task_id") or "").strip()
                == expected["parent_task_id"]
            ):
                return False
            startup.pop("worker_self_attestation", None)
            source[field] = startup
    return not _contract_runtime_value_reports_failed_qa(failure_scan)


def _contract_runtime_completed_line_acceptance(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    completed_line_index: int,
    expected_line: Mapping[str, Any],
    allow_missing_observer_merge_status: bool = False,
    allow_statusless_worker_finish_gate: bool = False,
    expected_worker_identity: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Resolve one completed line's server-written acceptance revision/time."""

    execution_id = str(record.get("contract_execution_id") or "").strip()
    if not execution_id or completed_line_index < 0:
        return {}
    try:
        canonical = _contract_runtime_store(conn).get(execution_id)
    except (ContractRuntimeError, sqlite3.Error):
        return {}
    if (
        str(canonical.get("project_id") or "").strip() != project_id
        or str(canonical.get("contract_execution_id") or "").strip()
        != execution_id
    ):
        return {}
    completed = [
        item
        for item in canonical.get("completed_lines") or []
        if isinstance(item, Mapping)
    ]
    if completed_line_index >= len(completed):
        return {}
    canonical_line = completed[completed_line_index]
    if stable_sha256(canonical_line) != stable_sha256(expected_line):
        return {}
    payload = (
        canonical_line.get("payload")
        if isinstance(canonical_line.get("payload"), Mapping)
        else {}
    )
    canonical_no_pass_exception = (
        _contract_runtime_candidate_scoped_no_pass_line(
            canonical_line,
            record=record,
        )
        or _contract_runtime_authenticated_nonverdict_qa_graph_line(
            canonical_line
        )
        or (
            allow_missing_observer_merge_status
            and not str(canonical_line.get("status") or "").strip()
            and _contract_runtime_server_derived_observer_merge_no_pass_line(
                canonical_line,
                allow_missing_top_level_status=True,
            )
        )
        or (
            allow_statusless_worker_finish_gate
            and _contract_runtime_statusless_worker_finish_gate_acceptance(
                canonical_line,
                expected_worker_identity=(expected_worker_identity or {}),
            )
        )
    )
    disqualifying_failed_qa = (
        _contract_runtime_line_reports_disqualifying_failed_qa(
            canonical_line,
            record=record,
        )
        and not canonical_no_pass_exception
    )
    if (
        not _contract_runtime_line_status_passes(canonical_line)
        or disqualifying_failed_qa
        or str(canonical_line.get("status") or "").strip().lower()
        in {"waived", "bypassed"}
        or (
            payload.get("no_pass_claim") is True
            and not canonical_no_pass_exception
        )
        or str(payload.get("disposition") or "").strip()
        == "proceeded_with_exception"
    ):
        return {}

    # Revisions also advance for prefill, service, and projection writes.  Join
    # the exact completed-line count transition through the immutable binding
    # snapshot hash instead of inferring a revision from the current count.
    rows = conn.execute(
        """
        SELECT execution_state_revision, source_ref, source_hash, created_at
        FROM backlog_contract_chain_bindings
        WHERE project_id = ? AND contract_execution_id = ?
        ORDER BY execution_state_revision, id
        """,
        (project_id, execution_id),
    ).fetchall()
    identity = {
        "project_id": str(canonical.get("project_id") or ""),
        "backlog_id": str(canonical.get("backlog_id") or ""),
        "contract_execution_id": execution_id,
        "contract_id": str(canonical.get("contract_id") or ""),
        "contract_chain_id": str(canonical.get("contract_chain_id") or ""),
        "parent_contract_execution_id": str(
            canonical.get("parent_contract_execution_id") or ""
        ),
        "root_contract_execution_id": str(
            canonical.get("root_contract_execution_id") or ""
        ),
    }
    decoded: dict[int, dict[str, Any]] = {}
    for row in rows:
        revision = int(row["execution_state_revision"] or 0)
        source_ref = str(row["source_ref"] or "").strip()
        source_hash = str(row["source_hash"] or "").strip()
        if revision <= 0 or source_ref != (
            f"contract_runtime:{execution_id}:revision:{revision}"
        ):
            continue
        matching_counts = [
            count
            for count in range(len(completed) + 1)
            if source_hash
            == stable_sha256(
                {
                    **identity,
                    "execution_state_revision": revision,
                    "completed_line_count": count,
                }
            )
        ]
        if len(matching_counts) != 1:
            continue
        candidate = {
            "execution_state_revision": revision,
            "completed_line_count": matching_counts[0],
            "source_ref": source_ref,
            "source_hash": source_hash,
            "created_at": str(row["created_at"] or "").strip(),
        }
        previous = decoded.get(revision)
        if previous is not None and previous != candidate:
            return {}
        decoded[revision] = candidate

    ordered = [decoded[key] for key in sorted(decoded)]
    target_count = completed_line_index + 1
    acceptance_candidates = [
        candidate
        for index, candidate in enumerate(ordered)
        if index > 0
        and candidate["completed_line_count"] == target_count
        and ordered[index - 1]["completed_line_count"] == target_count - 1
    ]
    if len(acceptance_candidates) != 1:
        return {}
    acceptance = acceptance_candidates[0]
    accepted_revision = int(acceptance["execution_state_revision"] or 0)
    expected_ref = f"contract_runtime:{execution_id}:revision:{accepted_revision}"
    accepted_at = str(acceptance["created_at"] or "").strip()
    if _contract_runtime_close_authority_time_order_value(accepted_at) is None:
        return {}
    completed_line_ref = (
        f"contract_runtime:{execution_id}:completed_lines:{completed_line_index}"
    )
    return {
        "schema_version": "contract_runtime.completed_line_acceptance.v1",
        "source": "backlog_contract_chain_bindings",
        "db_verified": True,
        "contract_execution_id": execution_id,
        "completed_line_index": completed_line_index,
        "completed_line_ref": completed_line_ref,
        "execution_state_revision": accepted_revision,
        "acceptance_ref": expected_ref,
        "accepted_at": accepted_at,
    }


def _contract_runtime_rev8_two_worker_merge_projection(
    record: Mapping[str, Any],
    *,
    required_worker_count: int = 2,
    conn=None,
    project_id: str = "",
) -> dict[str, Any]:
    """Join every required pre-QA lane merge to the pinned rev8 dispatch.

    The legacy name is retained for call-site stability. Standalone rev8 keeps
    two workers; an observer-selected, server-verified batch child uses one.
    """

    if (
        not _is_mf_parallel_postmerge_revision(record)
        or required_worker_count not in {1, 2}
    ):
        return {}
    dispatch_selection = _contract_runtime_current_dispatch_authority_line(
        record
    )
    if dispatch_selection.get("status") != "selected":
        return {}
    contract_execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    dispatch_index = int(dispatch_selection["completed_line_index"])
    dispatch_source_ref = (
        f"contract_runtime:{contract_execution_id}:completed_lines:"
        f"{dispatch_index}"
    )
    expected_workers = _contract_runtime_mf_parallel_bounded_workers(
        {"payload": dispatch_selection.get("payload") or {}}
    )
    if not expected_workers:
        rework_worker = (
            _contract_runtime_mf_parallel_verified_rework_dispatch_worker(
                record,
                dispatch_selection,
            )
        )
        if rework_worker:
            expected_workers = [rework_worker]
    expected_by_runtime = {
        str(worker.get("runtime_context_id") or "").strip(): worker
        for worker in expected_workers
        if str(worker.get("runtime_context_id") or "").strip()
    }
    if (
        len(expected_workers) != required_worker_count
        or len(expected_by_runtime) != required_worker_count
    ):
        return {}

    completed_merge_authorities: list[tuple[int, dict[str, Any]]] = []
    for line_index, line in enumerate(record.get("completed_lines") or []):
        if not isinstance(line, Mapping) or str(
            line.get("line_id") or ""
        ).strip() != "observer_merge":
            continue
        # ContractRuntime history is append-only.  Once rev9 selects a
        # failed-QA rework dispatch, merges from the initial two-lane
        # generation remain before that dispatch and are historical evidence,
        # not candidates for the current generation.  Everything after the
        # selected dispatch remains fail-closed below, including duplicates or
        # a merge carrying mixed dispatch/runtime identity.
        if line_index <= dispatch_index:
            continue
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        durable = (
            payload.get("durable_merge_authority")
            if isinstance(payload.get("durable_merge_authority"), Mapping)
            else {}
        )
        runtime_context_id = str(
            durable.get("runtime_context_id") or ""
        ).strip()
        expected_worker = expected_by_runtime.get(runtime_context_id) or {}
        line_instance_id = str(
            line.get("line_instance_id")
            or payload.get("line_instance_id")
            or ""
        ).strip()
        if not (
            str(durable.get("schema_version") or "")
            == _CONTRACT_RUNTIME_DURABLE_MERGE_SCHEMA_VERSION
            and durable.get("server_derived") is True
            and durable.get("db_verified") is True
            and durable.get("pre_qa_merge_authorized") is True
            and durable.get("final_qa_required_after_reconcile") is True
            and runtime_context_id
            and line_instance_id == f"runtime_context:{runtime_context_id}"
            and str(durable.get("contract_execution_id") or "").strip()
            == contract_execution_id
            and str(
                durable.get("contract_runtime_dispatch_source_ref") or ""
            ).strip()
            == dispatch_source_ref
            and str(durable.get("project_id") or "").strip()
            == str(record.get("project_id") or "").strip()
            and str(durable.get("backlog_id") or "").strip()
            == str(record.get("backlog_id") or "").strip()
            and str(durable.get("task_id") or "").strip()
            == str(expected_worker.get("task_id") or "").strip()
            and str(durable.get("parent_task_id") or "").strip()
            == str(expected_worker.get("parent_task_id") or "").strip()
            and str(durable.get("merge_queue_id") or "").strip()
            == str(expected_worker.get("merge_queue_id") or "").strip()
            and re.fullmatch(
                r"[0-9a-f]{40}|[0-9a-f]{64}",
                str(durable.get("merge_commit") or "").strip().lower(),
            )
            and str(durable.get("merge_event_ref") or "").startswith(
                "timeline:"
            )
            and int(durable.get("merge_event_id") or 0) > 0
            and _contract_runtime_close_authority_time_order_value(
                durable.get("merge_event_created_at")
            )
            is not None
        ):
            return {}
        completed_merge_authorities.append((line_index, dict(durable)))

    authority_lane_ids = {
        str(authority.get("runtime_context_id") or "").strip()
        for _line_index, authority in completed_merge_authorities
    }
    distinct_task_ids = {
        str(authority.get("task_id") or "").strip()
        for _line_index, authority in completed_merge_authorities
    }
    distinct_queue_ids = {
        str(authority.get("merge_queue_id") or "").strip()
        for _line_index, authority in completed_merge_authorities
    }
    event_ids = [
        int(authority.get("merge_event_id") or 0)
        for _line_index, authority in completed_merge_authorities
    ]
    if not (
        len(completed_merge_authorities) == required_worker_count
        and authority_lane_ids == set(expected_by_runtime)
        and len(distinct_task_ids) == required_worker_count
        and len(distinct_queue_ids) == required_worker_count
        and len(set(event_ids)) == required_worker_count
    ):
        return {}
    final_merge_index, final_merge = max(
        completed_merge_authorities,
        key=lambda item: int(item[1].get("merge_event_id") or 0),
    )
    projection = {
        **final_merge,
        "timeline_verified": True,
        "authority_verified": True,
        "dispatch_lineage_verified": True,
        "merged_commit_sha": str(
            final_merge.get("merge_commit") or ""
        ).strip().lower(),
        "merge_source_ref": str(
            final_merge.get("merge_event_ref") or ""
        ).strip(),
        "contract_runtime_dispatch_source_ref": dispatch_source_ref,
        "dispatch_completed_line_index": dispatch_index,
        "merge_completed_line_index": final_merge_index,
        "all_lane_merges_verified": True,
        "lane_merge_count": required_worker_count,
        "required_worker_count": required_worker_count,
        "lane_runtime_context_ids": sorted(authority_lane_ids),
        "lane_merge_queue_ids": sorted(distinct_queue_ids),
    }
    resolved_project_id = str(
        project_id or record.get("project_id") or ""
    ).strip()
    if conn is None or not resolved_project_id:
        return projection

    dispatch_line = (record.get("completed_lines") or [])[dispatch_index]
    final_runtime_context_id = str(
        projection.get("runtime_context_id") or ""
    ).strip()
    matching_contexts: dict[str, Any] = {}
    for context in _contract_runtime_contexts_for_dispatch_line(
        conn,
        project_id=resolved_project_id,
        record=record,
        line=dispatch_line,
    ):
        runtime_context_id, _task_id, _parent_task_id = (
            _contract_runtime_context_identity(context)
        )
        if runtime_context_id == final_runtime_context_id:
            matching_contexts[runtime_context_id] = context
    if len(matching_contexts) != 1:
        return projection
    context = next(iter(matching_contexts.values()))
    _runtime_context_id, task_id, _parent_task_id = (
        _contract_runtime_context_identity(context)
    )
    timeline_events = _runtime_context_service_timeline_events(
        conn,
        project_id=resolved_project_id,
        task_id=task_id,
        backlog_id=str(
            getattr(context, "backlog_id", "")
            or record.get("backlog_id")
            or ""
        ),
    )
    resolved_reconcile = _contract_runtime_completed_merge_reconcile_authority(
        conn,
        project_id=resolved_project_id,
        record=record,
        context=context,
        timeline_events=timeline_events,
        merge=projection,
    )
    return (
        {**projection, **resolved_reconcile}
        if resolved_reconcile
        else projection
    )


def _contract_runtime_rev8_superseded_terminal_reconcile_receipt_verified(
    authority: Mapping[str, Any],
) -> bool:
    """Verify one immutable terminal receipt after a later clean deployment.

    This is deliberately narrower than current-full activation.  The ordinary
    verifier continues to require the receipt itself to name the active HEAD.
    Rev8+ ordered multi-lane reconciliation may, however, be resumed after a
    later clean descendant has already become the active current-full world.
    In that one case the old receipt remains a lane-selection receipt only: it
    must be the exact fully verified receipt for the CEX merge commit, while an
    independent current-full provenance proves the clean loaded HEAD.
    """

    marker = authority.get("current_full_reconcile_marker")
    marker = marker if isinstance(marker, Mapping) else {}
    provenance = authority.get("current_full_reconcile_provenance")
    provenance = provenance if isinstance(provenance, Mapping) else {}
    marker_scope = marker.get("runtime_context_scope")
    marker_scope = marker_scope if isinstance(marker_scope, Mapping) else {}
    route_evidence = marker.get("route_evidence")
    route_evidence = (
        route_evidence if isinstance(route_evidence, Mapping) else {}
    )
    route_scope = route_evidence.get("runtime_context_scope")
    route_scope = route_scope if isinstance(route_scope, Mapping) else {}
    idempotency_scope = route_evidence.get("idempotency_scope")
    idempotency_scope = (
        idempotency_scope
        if isinstance(idempotency_scope, Mapping)
        else {}
    )
    route_token_scope = route_evidence.get("route_token_scope")
    route_token_scope = (
        route_token_scope
        if isinstance(route_token_scope, Mapping)
        else {}
    )

    project_id = str(authority.get("project_id") or "").strip()
    backlog_id = str(authority.get("backlog_id") or "").strip()
    execution_id = str(
        authority.get("contract_execution_id") or ""
    ).strip()
    runtime_context_id = str(
        authority.get("runtime_context_id") or ""
    ).strip()
    task_id = str(authority.get("task_id") or "").strip()
    parent_task_id = str(authority.get("parent_task_id") or "").strip()
    merge_queue_id = str(
        authority.get("merge_queue_id") or ""
    ).strip()
    merged_commit = str(
        authority.get("merged_commit_sha") or ""
    ).strip().lower()
    reconciled_commit = str(
        authority.get("reconciled_commit_sha") or ""
    ).strip().lower()
    provenance_target = str(
        authority.get("reconcile_provenance_target_commit") or ""
    ).strip().lower()
    canonical_head = str(
        authority.get("canonical_head_commit")
        or authority.get("current_canonical_commit_sha")
        or ""
    ).strip().lower()
    target_root_text = str(
        authority.get("target_project_root") or ""
    ).strip()
    if not target_root_text:
        return False
    target_root = Path(target_root_text)
    try:
        canonical_root = str(target_root.resolve())
    except OSError:
        return False
    live_head = _git_head_commit(target_root).strip().lower()
    runtime_identity = governance_loaded_runtime_identity(live_head)
    loaded_commit = str(
        runtime_identity.get("loaded_commit") or ""
    ).strip().lower()
    loaded_source_sha256 = str(
        runtime_identity.get("loaded_source_sha256") or ""
    ).strip()
    worktree_source_sha256 = str(
        runtime_identity.get("worktree_source_sha256") or ""
    ).strip()

    reconcile_snapshot_id = str(
        authority.get("reconcile_snapshot_id") or ""
    ).strip()
    active_snapshot_id = str(
        authority.get("active_snapshot_id") or ""
    ).strip()
    reconcile_event_id = int(authority.get("reconcile_event_id") or 0)
    active_reconcile_event_id = int(
        authority.get(
            "active_snapshot_current_full_reconcile_event_id"
        )
        or 0
    )
    provenance_hash = str(
        provenance.get("provenance_hash") or ""
    ).strip()
    active_provenance_hash = str(
        authority.get("active_snapshot_current_full_provenance_hash") or ""
    ).strip()
    required_true_fields = (
        "db_verified",
        "live_verified",
        "canonical_head_verified",
        "active_snapshot_verified",
        "active_snapshot_current_full_reconcile_verified",
        "active_snapshot_current_full_runtime_scope_verified",
        "active_snapshot_matches_canonical_head",
        "graph_reconciled",
        "provenance_verified",
        "provenance_scope_verified",
        "durable_order_verified",
        "reconcile_snapshot_verified",
        "current_full_reconcile_marker_verified",
        "contract_execution_scope_verified",
        "task_scope_verified",
        "runtime_context_scope_verified",
        "parent_task_scope_verified",
        "merge_queue_scope_verified",
        "trusted_contract_execution_lineage_verified",
    )
    scope_identity = {
        "project_id": project_id,
        "backlog_id": backlog_id,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "merge_queue_id": merge_queue_id,
    }
    return bool(
        str(authority.get("schema_version") or "")
        == "graph_snapshot_store.current_full_reconcile_state.v1"
        and str(authority.get("source") or "")
        == "graph_snapshot_store.current_full_reconcile_state"
        and authority.get("server_derived") is True
        and all(authority.get(field) is True for field in required_true_fields)
        and authority.get("current_full_reconcile") is True
        and str(authority.get("strategy") or "")
        == "current_full_reconcile"
        and not authority.get("identity_mismatches")
        and all(scope_identity.values())
        and parent_task_id == execution_id
        and all(
            str(authority.get(field) or "").strip() == expected
            for field, expected in (
                ("expected_contract_execution_id", execution_id),
                ("expected_runtime_context_id", runtime_context_id),
                ("expected_task_id", task_id),
                ("expected_parent_task_id", parent_task_id),
                ("expected_merge_queue_id", merge_queue_id),
            )
        )
        and str(
            authority.get("contract_runtime_dispatch_source_ref") or ""
        ).strip().startswith(f"contract_runtime:{execution_id}:")
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", merged_commit)
        and merged_commit == reconciled_commit == provenance_target
        and str(authority.get("reconcile_snapshot_commit") or "")
        .strip()
        .lower()
        == merged_commit
        and str(authority.get("reconcile_snapshot_status") or "")
        == "superseded"
        and reconcile_snapshot_id
        and reconcile_snapshot_id != active_snapshot_id
        and str(authority.get("source_ref") or "").strip()
        == f"graph_snapshot:{reconcile_snapshot_id}"
        and str(authority.get("active_snapshot_status") or "") == "active"
        and active_snapshot_id
        and str(authority.get("active_source_ref") or "").strip()
        == f"graph_snapshot:{active_snapshot_id}"
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", canonical_head)
        and canonical_head != merged_commit
        and str(authority.get("active_snapshot_commit") or "")
        .strip()
        .lower()
        == canonical_head
        and str(
            authority.get(
                "active_snapshot_current_full_provenance_target_commit"
            )
            or ""
        )
        .strip()
        .lower()
        == canonical_head
        and str(
            authority.get("active_snapshot_current_full_provenance_id") or ""
        ).strip()
        and re.fullmatch(r"sha256:[0-9a-f]{64}", active_provenance_hash)
        and active_reconcile_event_id > reconcile_event_id > int(
            authority.get("merge_event_id") or 0
        )
        and str(authority.get("reconcile_source_ref") or "").strip()
        == f"timeline:{reconcile_event_id}"
        and str(authority.get("reconcile_task_id") or "").strip()
        == task_id
        and str(
            authority.get("reconcile_runtime_context_id") or ""
        ).strip()
        == runtime_context_id
        and str(authority.get("active_snapshot_current_full_reconcile_event_created_at") or "").strip()
        and str(authority.get("reconcile_event_created_at") or "").strip()
        and str(provenance.get("project_id") or "").strip() == project_id
        and str(provenance.get("snapshot_id") or "").strip()
        == reconcile_snapshot_id
        and str(provenance.get("target_commit_sha") or "")
        .strip()
        .lower()
        == merged_commit
        and int(provenance.get("reconcile_event_id") or 0)
        == reconcile_event_id
        and str(provenance.get("reconcile_event_created_at") or "").strip()
        == str(authority.get("reconcile_event_created_at") or "").strip()
        and str(provenance.get("provenance_id") or "").strip()
        and re.fullmatch(r"sha256:[0-9a-f]{64}", provenance_hash)
        and str(marker.get("schema_version") or "")
        == "current_full_reconcile.provenance.v2"
        and str(marker.get("source") or "") == "graph_governance_api"
        and marker.get("activate") is True
        and marker.get("normal_update_path") is True
        and str(marker.get("protected_action") or "")
        == "graph_current_full_reconcile"
        and str(marker.get("snapshot_id") or "").strip()
        == reconcile_snapshot_id
        and str(marker.get("target_commit_sha") or "")
        .strip()
        .lower()
        == merged_commit
        and str(marker.get("provenance_id") or "").strip()
        == str(provenance.get("provenance_id") or "").strip()
        and str(marker.get("provenance_hash") or "").strip()
        == provenance_hash
        and int(marker.get("reconcile_event_id") or 0)
        == reconcile_event_id
        and all(
            str(marker_scope.get(field) or "").strip() == expected
            and str(route_scope.get(field) or "").strip() == expected
            and str(idempotency_scope.get(field) or "").strip() == expected
            for field, expected in scope_identity.items()
        )
        and str(route_token_scope.get("project_id") or "").strip()
        == project_id
        and str(route_token_scope.get("backlog_id") or "").strip()
        == backlog_id
        and str(route_token_scope.get("task_id") or "").strip() == task_id
        and canonical_root == target_root_text
        and live_head == canonical_head
        and _git_clean_worktree_verified(target_root)
        and authority.get("reconciled_commit_is_ancestor_of_canonical_head")
        is True
        and _git_commit_is_ancestor(
            target_root,
            merged_commit,
            canonical_head,
        )
        and str(runtime_identity.get("schema_version") or "")
        == LOADED_RUNTIME_IDENTITY_SCHEMA
        and str(runtime_identity.get("identity_source") or "")
        == "frozen_at_import"
        and runtime_identity.get("runtime_stale") is False
        and loaded_commit == live_head == canonical_head
        and re.fullmatch(r"sha256:[0-9a-f]{64}", loaded_source_sha256)
        and loaded_source_sha256 == worktree_source_sha256
        and str(authority.get("authority_hash") or "")
        == stable_sha256(
            {
                key: value
                for key, value in authority.items()
                if key != "authority_hash"
            }
        )
    )


def _contract_runtime_rev8_terminal_reconcile_receipt_lane_projection(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    aggregate_merge: Mapping[str, Any],
    dispatch_contexts: Sequence[Any],
) -> dict[str, Any]:
    """Resolve one exact current-full receipt from the sealed worker lanes.

    The current RuntimeContext projection is a work-progress cursor, not proof
    of which merged lane performed the terminal current-full reconcile.  After
    all ordered lane merges complete, that receipt may legitimately belong to
    another dispatched lane.  Select it only by replaying every exact sealed
    lane through the unchanged current-full scope verifier.  Zero or multiple
    verified candidates remain ambiguous.  The explicit resolution status is
    required so an ambiguous receipt set can never fall back to a single
    RuntimeContext cursor and accidentally become acceptable.
    """

    aggregate = dict(aggregate_merge)
    execution_id = str(record.get("contract_execution_id") or "").strip()
    backlog_id = str(record.get("backlog_id") or "").strip()
    merged_commit = str(
        aggregate.get("merged_commit_sha") or ""
    ).strip().lower()
    merge_event_id = int(aggregate.get("merge_event_id") or 0)
    lane_runtime_context_ids = {
        str(value or "").strip()
        for value in aggregate.get("lane_runtime_context_ids") or []
        if str(value or "").strip()
    }
    lane_merge_queue_ids = {
        str(value or "").strip()
        for value in aggregate.get("lane_merge_queue_ids") or []
        if str(value or "").strip()
    }
    aggregate_identity = {
        field: str(aggregate.get(field) or "").strip()
        for field in (
            "runtime_context_id",
            "task_id",
            "parent_task_id",
            "merge_queue_id",
        )
    }
    if not (
        execution_id
        and backlog_id
        and merged_commit
        and merge_event_id > 0
        and aggregate.get("timeline_verified") is True
        and aggregate.get("dispatch_lineage_verified") is True
        and aggregate.get("all_lane_merges_verified") is True
        and int(aggregate.get("lane_merge_count") or 0) >= 2
        and len(lane_runtime_context_ids)
        == int(aggregate.get("lane_merge_count") or 0)
        and lane_merge_queue_ids
    ):
        return {
            "status": "none",
            "verified_candidate_count": 0,
            "projection": {},
        }

    verified: list[dict[str, Any]] = []
    seen_context_identities: set[tuple[str, str, str, str]] = set()
    for context in dispatch_contexts:
        runtime_context_id, task_id, parent_task_id = (
            _contract_runtime_context_identity(context)
        )
        context_backlog_id = str(
            getattr(context, "backlog_id", "") or ""
        ).strip()
        merge_queue_id = str(
            getattr(context, "merge_queue_id", "") or ""
        ).strip()
        context_identity = (
            runtime_context_id,
            task_id,
            parent_task_id,
            merge_queue_id,
        )
        if not (
            all(context_identity)
            and context_identity not in seen_context_identities
            and context_backlog_id == backlog_id
            and parent_task_id == execution_id
            and runtime_context_id in lane_runtime_context_ids
            and merge_queue_id in lane_merge_queue_ids
        ):
            continue
        seen_context_identities.add(context_identity)
        candidate_merge = {
            **aggregate,
            "runtime_context_id": runtime_context_id,
            "task_id": task_id,
            "parent_task_id": parent_task_id,
            "merge_queue_id": merge_queue_id,
            "aggregate_final_merge_identity": aggregate_identity,
            "reconcile_line_instance_id": (
                f"runtime_context:{runtime_context_id}"
            ),
            "reconcile_lane_identity_source": (
                "terminal_current_full_reconcile_receipt"
            ),
        }
        timeline_events = _runtime_context_service_timeline_events(
            conn,
            project_id=project_id,
            task_id=task_id,
            backlog_id=backlog_id,
        )
        recorded_reconcile = (
            _contract_runtime_completed_merge_reconcile_authority(
                conn,
                project_id=project_id,
                record=record,
                context=context,
                timeline_events=timeline_events,
                merge=candidate_merge,
            )
        )
        terminal_authority = (
            _contract_runtime_current_full_reconcile_authority_from_merge(
                conn,
                project_id=project_id,
                record=record,
                merge=candidate_merge,
                reconcile=recorded_reconcile,
            )
        )
        terminal_activation_verified = bool(
            _contract_runtime_current_full_reconcile_activation_verified(
                terminal_authority
            )
            or _contract_runtime_rev8_superseded_terminal_reconcile_receipt_verified(
                terminal_authority
            )
        )
        if not (
            terminal_activation_verified
            and str(
                terminal_authority.get("runtime_context_id") or ""
            ).strip()
            == runtime_context_id
            and str(terminal_authority.get("task_id") or "").strip()
            == task_id
            and str(
                terminal_authority.get("parent_task_id") or ""
            ).strip()
            == parent_task_id
            and str(
                terminal_authority.get("merge_queue_id") or ""
            ).strip()
            == merge_queue_id
            and str(terminal_authority.get("merged_commit_sha") or "")
            .strip()
            .lower()
            == merged_commit
            and int(terminal_authority.get("merge_event_id") or 0)
            == merge_event_id
            and str(
                terminal_authority.get("merge_source_ref") or ""
            ).strip()
            == str(aggregate.get("merge_source_ref") or "").strip()
            and str(
                terminal_authority.get("merge_event_created_at") or ""
            ).strip()
            == str(
                aggregate.get("merge_event_created_at") or ""
            ).strip()
            and int(recorded_reconcile.get("reconcile_event_id") or 0)
            > merge_event_id
            and str(
                recorded_reconcile.get("reconcile_source_ref") or ""
            ).strip()
            == (
                "timeline:"
                f"{int(recorded_reconcile.get('reconcile_event_id') or 0)}"
            )
            and str(
                recorded_reconcile.get("reconcile_task_id") or ""
            ).strip()
            == task_id
            and str(
                recorded_reconcile.get("reconcile_runtime_context_id")
                or ""
            ).strip()
            == runtime_context_id
            and candidate_merge.get("all_lane_merges_verified") is True
            and int(candidate_merge.get("lane_merge_count") or 0)
            == int(aggregate.get("lane_merge_count") or 0)
            and {
                str(value or "").strip()
                for value in candidate_merge.get("lane_runtime_context_ids")
                or []
                if str(value or "").strip()
            }
            == lane_runtime_context_ids
            and {
                str(value or "").strip()
                for value in candidate_merge.get("lane_merge_queue_ids")
                or []
                if str(value or "").strip()
            }
            == lane_merge_queue_ids
        ):
            continue
        projection = {
            **candidate_merge,
            "reconcile_source_ref": str(
                recorded_reconcile.get("reconcile_source_ref") or ""
            ).strip(),
            "reconcile_event_id": int(
                recorded_reconcile.get("reconcile_event_id") or 0
            ),
            "reconcile_event_created_at": str(
                recorded_reconcile.get("reconcile_event_created_at") or ""
            ).strip(),
            "reconcile_task_id": task_id,
            "reconcile_runtime_context_id": runtime_context_id,
        }
        projection.pop("authority_hash", None)
        verified.append(projection)

    return {
        "status": (
            "selected"
            if len(verified) == 1
            else "ambiguous"
            if len(verified) > 1
            else "none"
        ),
        "verified_candidate_count": len(verified),
        "projection": verified[0] if len(verified) == 1 else {},
    }


def _contract_runtime_rev8_selected_reconcile_lane_projection(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    aggregate_merge: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind the aggregate merge to the exact current reconcile line lane.

    Rev8/rev9 merge authority is aggregate: the last durable live-merge event
    establishes the canonical merged commit.  The single observer_reconcile
    line is nevertheless bound by ContractRuntime to one exact dispatched
    RuntimeContext.  Those identities need not be the same lane.  Treating
    the final merge lane as the reconcile executor rejects a valid task-scoped
    current-full receipt whenever the other lane merged last.

    Only the server-selected current Guide line may choose the reconcile lane.
    Caller fields are not consulted.  Missing or ambiguous dispatch/context
    identity leaves the aggregate projection unchanged so the downstream Gate
    remains fail-closed.
    """

    aggregate = dict(aggregate_merge)
    if not (
        _is_mf_parallel_postmerge_revision(record)
        and aggregate.get("timeline_verified") is True
        and aggregate.get("all_lane_merges_verified") is True
    ):
        return aggregate
    guide = (
        record.get("runtime_guide")
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    selected = (
        guide.get("next_legal_action")
        if isinstance(guide.get("next_legal_action"), Mapping)
        else {}
    )
    execution_id = str(record.get("contract_execution_id") or "").strip()
    selected_line_pending = bool(
        str(selected.get("line_id") or "").strip()
        == "observer_reconcile"
    )
    restore_reconcile_lane_projection_metadata = selected_line_pending
    reconcile_lane_identity_source = "RuntimeContext.current_values"
    aggregate_identity = {
        field: str(aggregate.get(field) or "").strip()
        for field in (
            "runtime_context_id",
            "task_id",
            "parent_task_id",
            "merge_queue_id",
        )
    }
    dispatch_selection = _contract_runtime_current_dispatch_authority_line(
        record
    )
    if dispatch_selection.get("status") != "selected":
        return aggregate
    dispatch_index_value = dispatch_selection.get("completed_line_index")
    if not isinstance(dispatch_index_value, int) or isinstance(
        dispatch_index_value, bool
    ):
        return aggregate
    dispatch_index = dispatch_index_value
    completed_lines = list(record.get("completed_lines") or [])
    if not (0 <= dispatch_index < len(completed_lines)):
        return aggregate
    dispatch_line = completed_lines[dispatch_index]
    dispatch_contexts = list(
        _contract_runtime_contexts_for_dispatch_line(
            conn,
            project_id=project_id,
            record=record,
            line=dispatch_line,
        )
    )

    if selected_line_pending:
        terminal_receipt_resolution = (
            _contract_runtime_rev8_terminal_reconcile_receipt_lane_projection(
                conn,
                project_id=project_id,
                record=record,
                aggregate_merge=aggregate,
                dispatch_contexts=dispatch_contexts,
            )
        )
        if terminal_receipt_resolution.get("status") == "selected":
            projection = terminal_receipt_resolution.get("projection")
            return (
                dict(projection)
                if isinstance(projection, Mapping)
                else aggregate
            )
        if terminal_receipt_resolution.get("status") == "ambiguous":
            nonactivating = dict(aggregate)
            nonactivating.update(
                {
                    "reconcile_source_ref": "",
                    "reconcile_event_id": 0,
                    "reconcile_event_created_at": "",
                    "reconcile_task_id": "",
                    "reconcile_runtime_context_id": "",
                    "current_full_reconcile_activation_verified": False,
                    "reconcile_receipt_lane_resolution_status": (
                        "ambiguous"
                    ),
                    "reconcile_receipt_lane_verified_candidate_count": int(
                        terminal_receipt_resolution.get(
                            "verified_candidate_count"
                        )
                        or 0
                    ),
                }
            )
            nonactivating.pop(
                "terminal_current_full_reconcile_authority", None
            )
            return nonactivating
        runtime_context_projection = (
            _contract_runtime_authoritative_runtime_context_projection(
                conn,
                project_id=project_id,
                record=record,
            )
        )
        current_values = (
            runtime_context_projection.get("current_values")
            if isinstance(
                runtime_context_projection.get("current_values"), Mapping
            )
            else {}
        )
    else:
        # After observer_reconcile is accepted, the current Guide advances to
        # postmerge QA/close and no longer carries the selected reconcile-lane
        # identity.  Recover it only from the one immutable, server-authored
        # receipt whose hash and aggregate merge tuple still verify.  This is
        # a read-only close projection; caller fields never participate.
        receipt_candidates: list[dict[str, Any]] = []
        for line_index, line in enumerate(
            record.get("completed_lines") or []
        ):
            if not isinstance(line, Mapping) or str(
                line.get("line_id") or ""
            ).strip() != "observer_reconcile":
                continue
            payload = (
                line.get("payload")
                if isinstance(line.get("payload"), Mapping)
                else {}
            )
            authority = (
                payload.get("reconcile_authority")
                if isinstance(
                    payload.get("reconcile_authority"), Mapping
                )
                else {}
            )
            runtime_context_id = str(
                authority.get("runtime_context_id") or ""
            ).strip()
            task_id = str(authority.get("task_id") or "").strip()
            parent_task_id = str(
                authority.get("parent_task_id") or ""
            ).strip()
            merge_queue_id = str(
                authority.get("merge_queue_id") or ""
            ).strip()
            terminal_current_full = authority.get(
                "terminal_current_full_reconcile_authority"
            )
            terminal_current_full = (
                terminal_current_full
                if isinstance(terminal_current_full, Mapping)
                else {}
            )
            shared_batch = terminal_current_full.get(
                "shared_batch_reconcile_authority"
            )
            shared_batch = (
                shared_batch if isinstance(shared_batch, Mapping) else {}
            )
            task_only_shared_reconcile = bool(
                _contract_runtime_shared_batch_postmerge_qa_activation_verified(
                    terminal_current_full
                )
                and not str(
                    authority.get("reconcile_runtime_context_id") or ""
                ).strip()
                and not str(
                    shared_batch.get("coordination_runtime_context_id") or ""
                ).strip()
                and str(authority.get("reconcile_task_id") or "").strip()
                == str(
                    shared_batch.get("coordination_reconcile_task_id") or ""
                ).strip()
            )
            stored_aggregate_identity = terminal_current_full.get(
                "aggregate_final_merge_identity"
            )
            stored_aggregate_identity = (
                stored_aggregate_identity
                if isinstance(stored_aggregate_identity, Mapping)
                else {}
            )
            stored_line_instance_id = str(
                terminal_current_full.get("reconcile_line_instance_id") or ""
            ).strip()
            stored_lane_identity_source = str(
                terminal_current_full.get("reconcile_lane_identity_source")
                or ""
            ).strip()
            stored_projection_metadata_claimed = bool(
                stored_aggregate_identity
                or stored_line_instance_id
                or stored_lane_identity_source
            )
            terminal_receipt_projection_verified = bool(
                stored_lane_identity_source
                == "terminal_current_full_reconcile_receipt"
                and (
                    _contract_runtime_current_full_reconcile_activation_verified(
                        terminal_current_full
                    )
                    or _contract_runtime_rev8_superseded_terminal_reconcile_receipt_verified(
                        terminal_current_full
                    )
                )
                and all(
                    str(terminal_current_full.get(field) or "").strip()
                    == expected
                    for field, expected in (
                        ("project_id", str(project_id or "").strip()),
                        (
                            "backlog_id",
                            str(record.get("backlog_id") or "").strip(),
                        ),
                        ("contract_execution_id", execution_id),
                        ("runtime_context_id", runtime_context_id),
                        ("task_id", task_id),
                        ("parent_task_id", parent_task_id),
                        ("merge_queue_id", merge_queue_id),
                        (
                            "merged_commit_sha",
                            str(
                                aggregate.get("merged_commit_sha") or ""
                            )
                            .strip()
                            .lower(),
                        ),
                        (
                            "merge_source_ref",
                            str(
                                aggregate.get("merge_source_ref") or ""
                            ).strip(),
                        ),
                    )
                )
                and str(
                    terminal_current_full.get("reconcile_task_id") or ""
                ).strip()
                == task_id
                and str(
                    terminal_current_full.get(
                        "reconcile_runtime_context_id"
                    )
                    or ""
                ).strip()
                == runtime_context_id
            )
            stored_projection_metadata_verified = bool(
                stored_projection_metadata_claimed
                and stored_aggregate_identity == aggregate_identity
                and stored_line_instance_id
                == f"runtime_context:{runtime_context_id}"
                and (
                    stored_lane_identity_source
                    == "RuntimeContext.current_values"
                    or terminal_receipt_projection_verified
                )
            )
            if not (
                line_index > int(
                    aggregate.get("dispatch_completed_line_index") or -1
                )
                and _contract_runtime_line_status_passes(line)
                and str(line.get("actor_role") or "").strip()
                == "observer"
                and str(authority.get("schema_version") or "")
                == (
                    "contract_runtime."
                    "observer_reconcile_record_authority.v1"
                )
                and str(authority.get("source") or "")
                == "contract_runtime.server_reconcile_record_projection"
                and authority.get("server_derived") is True
                and authority.get("record_verified") is True
                and authority.get("merge_projection_verified") is True
                and authority.get("dispatch_lineage_verified") is True
                and authority.get("all_lane_merges_verified") is True
                and int(authority.get("lane_merge_count") or 0)
                == int(aggregate.get("lane_merge_count") or 0)
                and _contract_runtime_close_authority_hash_matches(
                    authority
                )
                and str(authority.get("project_id") or "").strip()
                == str(project_id or "").strip()
                and str(authority.get("backlog_id") or "").strip()
                == str(record.get("backlog_id") or "").strip()
                and str(
                    authority.get("contract_execution_id") or ""
                ).strip()
                == execution_id
                and parent_task_id == execution_id
                and runtime_context_id
                in {
                    str(value or "").strip()
                    for value in aggregate.get(
                        "lane_runtime_context_ids"
                    )
                    or []
                }
                and merge_queue_id
                in {
                    str(value or "").strip()
                    for value in aggregate.get("lane_merge_queue_ids")
                    or []
                }
                and task_id
                and str(
                    authority.get("merged_commit_sha") or ""
                ).strip().lower()
                == str(
                    aggregate.get("merged_commit_sha") or ""
                ).strip().lower()
                and int(authority.get("merge_event_id") or 0)
                == int(aggregate.get("merge_event_id") or 0)
                and str(authority.get("merge_source_ref") or "").strip()
                == str(aggregate.get("merge_source_ref") or "").strip()
                and str(
                    authority.get("merge_event_created_at") or ""
                ).strip()
                == str(
                    aggregate.get("merge_event_created_at") or ""
                ).strip()
                and authority.get("reconcile_event_recorded") is True
                and int(authority.get("reconcile_event_id") or 0)
                > int(authority.get("merge_event_id") or 0)
                and str(
                    authority.get("reconcile_source_ref") or ""
                ).strip()
                == f"timeline:{int(authority.get('reconcile_event_id') or 0)}"
                and str(
                    authority.get("reconcile_event_created_at") or ""
                ).strip()
                and (
                    (
                        str(
                            authority.get("reconcile_runtime_context_id")
                            or ""
                        ).strip()
                        == runtime_context_id
                        and str(
                            authority.get("reconcile_task_id") or ""
                        ).strip()
                        == task_id
                    )
                    or task_only_shared_reconcile
                )
                and (
                    not stored_projection_metadata_claimed
                    or stored_projection_metadata_verified
                )
            ):
                continue
            receipt_candidates.append(
                {
                    "runtime_context_id": runtime_context_id,
                    "task_id": task_id,
                    "parent_task_id": parent_task_id,
                    "merge_queue_id": merge_queue_id,
                    "restore_reconcile_lane_projection_metadata": (
                        stored_projection_metadata_verified
                    ),
                    "reconcile_lane_identity_source": (
                        stored_lane_identity_source
                        if stored_projection_metadata_verified
                        else ""
                    ),
                }
            )
        if len(receipt_candidates) != 1:
            return aggregate
        current_values = receipt_candidates[0]
        restore_reconcile_lane_projection_metadata = bool(
            current_values.get(
                "restore_reconcile_lane_projection_metadata"
            )
        )
        if restore_reconcile_lane_projection_metadata:
            reconcile_lane_identity_source = str(
                current_values.get("reconcile_lane_identity_source") or ""
            ).strip()
    runtime_context_id = str(
        current_values.get("runtime_context_id") or ""
    ).strip()
    task_id = str(current_values.get("task_id") or "").strip()
    parent_task_id = str(
        current_values.get("parent_task_id") or ""
    ).strip()
    merge_queue_id = str(
        current_values.get("merge_queue_id") or ""
    ).strip()
    line_instance_id = (
        f"runtime_context:{runtime_context_id}"
        if runtime_context_id
        else ""
    )
    lane_runtime_context_ids = {
        str(value or "").strip()
        for value in aggregate.get("lane_runtime_context_ids") or []
        if str(value or "").strip()
    }
    if not (
        execution_id
        and runtime_context_id
        and task_id
        and parent_task_id == execution_id
        and merge_queue_id
        and line_instance_id == f"runtime_context:{runtime_context_id}"
        and runtime_context_id in lane_runtime_context_ids
    ):
        return aggregate

    matches: list[Any] = []
    for context in dispatch_contexts:
        context_runtime_id, context_task_id, context_parent_task_id = (
            _contract_runtime_context_identity(context)
        )
        if (
            context_runtime_id == runtime_context_id
            and context_task_id == task_id
            and context_parent_task_id == parent_task_id
            and str(getattr(context, "backlog_id", "") or "").strip()
            == str(record.get("backlog_id") or "").strip()
            and str(getattr(context, "merge_queue_id", "") or "").strip()
            == merge_queue_id
        ):
            matches.append(context)
    if len(matches) != 1:
        return aggregate

    selected_context = matches[0]
    reconcile_merge = {
        **aggregate,
        "runtime_context_id": runtime_context_id,
        "task_id": task_id,
        "parent_task_id": parent_task_id,
        "merge_queue_id": merge_queue_id,
    }
    if restore_reconcile_lane_projection_metadata:
        reconcile_merge.update(
            {
                "aggregate_final_merge_identity": aggregate_identity,
                "reconcile_line_instance_id": line_instance_id,
                "reconcile_lane_identity_source": (
                    reconcile_lane_identity_source
                ),
            }
        )
    timeline_events = _runtime_context_service_timeline_events(
        conn,
        project_id=project_id,
        task_id=task_id,
        backlog_id=str(record.get("backlog_id") or "").strip(),
    )
    return _contract_runtime_completed_merge_reconcile_authority(
        conn,
        project_id=project_id,
        record=record,
        context=selected_context,
        timeline_events=timeline_events,
        merge=reconcile_merge,
    )


def _contract_runtime_current_full_reconcile_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    if _is_mf_parallel_postmerge_revision(record):
        merge = _contract_runtime_rev8_two_worker_merge_projection(
            record,
            required_worker_count=(
                _contract_runtime_mf_parallel_current_generation_worker_count(
                    record,
                    conn=conn,
                    project_id=project_id,
                )
            ),
            conn=conn,
            project_id=project_id,
        )
        if not merge.get("reconcile_event_id"):
            final_runtime_context_id = str(
                merge.get("runtime_context_id") or ""
            ).strip()
            for dispatch_line in record.get("completed_lines") or []:
                if not isinstance(dispatch_line, Mapping) or str(
                    dispatch_line.get("line_id") or ""
                ).strip() != "observer_dispatch_bounded_workers":
                    continue
                for context in _contract_runtime_contexts_for_dispatch_line(
                    conn,
                    project_id=project_id,
                    record=record,
                    line=dispatch_line,
                ):
                    runtime_context_id, task_id, _parent_task_id = (
                        _contract_runtime_context_identity(context)
                    )
                    if runtime_context_id != final_runtime_context_id:
                        continue
                    timeline_events = _runtime_context_service_timeline_events(
                        conn,
                        project_id=project_id,
                        task_id=task_id,
                        backlog_id=str(
                            getattr(context, "backlog_id", "")
                            or record.get("backlog_id")
                            or ""
                        ),
                    )
                    merge = (
                        _contract_runtime_completed_merge_reconcile_authority(
                            conn,
                            project_id=project_id,
                            record=record,
                            context=context,
                            timeline_events=timeline_events,
                            merge=merge,
                        )
                    )
                    break
                if merge.get("reconcile_event_id"):
                    break
    else:
        merge = _contract_runtime_trusted_merge_projection(
            conn,
            project_id=project_id,
            record=record,
        )
    return _contract_runtime_current_full_reconcile_authority_from_merge(
        conn,
        project_id=project_id,
        record=record,
        merge=merge,
        reconcile=merge,
    )


def _contract_runtime_current_full_reconcile_authority_from_merge(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    merge: Mapping[str, Any],
    reconcile: Mapping[str, Any] | None = None,
    target_project_root_override: str = "",
) -> dict[str, Any]:
    from . import graph_snapshot_store

    merged_commit = str(merge.get("merged_commit_sha") or "").strip().lower()
    reconcile = reconcile if isinstance(reconcile, Mapping) else {}
    root = str(target_project_root_override or "").strip()
    if root:
        root = str(Path(root).resolve())
    else:
        root = _contract_runtime_postmerge_canonical_project_root(
            conn,
            project_id=project_id,
            record=record,
            merge=merge,
        )
        if not root:
            root = project_service.resolve_project_root(
                project_id,
                None,
                fallback_self=True,
            )
    target_project_root = str(Path(root).resolve()) if root else ""
    canonical_head_commit = (
        _git_head_commit(Path(root)).strip().lower() if root else ""
    )
    requested_reconcile_event_id = int(
        reconcile.get("reconcile_event_id") or 0
    )
    reconcile_target_commit = canonical_head_commit
    if requested_reconcile_event_id > 0:
        try:
            provenance_rows = conn.execute(
                """
                SELECT target_commit_sha
                FROM graph_current_full_reconcile_provenance
                WHERE project_id = ? AND reconcile_event_id = ?
                ORDER BY created_at DESC, provenance_id DESC
                LIMIT 2
                """,
                (project_id, requested_reconcile_event_id),
            ).fetchall()
        except sqlite3.Error:
            provenance_rows = []
        if len(provenance_rows) == 1:
            exact_target = str(
                provenance_rows[0]["target_commit_sha"] or ""
            ).strip().lower()
            if re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", exact_target):
                # Resolve the immutable source-row reconcile provenance
                # independently from the live canonical HEAD.  The source
                # event keeps its own QA/merge/order/scope authority at this
                # target while current_full_reconcile_state separately proves
                # the active current-full snapshot at canonical HEAD.
                reconcile_target_commit = exact_target
    state = graph_snapshot_store.current_full_reconcile_state(
        conn,
        project_id,
        merged_commit,
        current_canonical_commit_sha=canonical_head_commit,
        reconcile_target_commit_sha=reconcile_target_commit,
        qa_event_id=int(merge.get("qa_event_id") or 0),
        qa_event_created_at=str(merge.get("qa_event_created_at") or ""),
        qa_source_ref=str(merge.get("qa_source_ref") or ""),
        qa_acceptance_created_at=str(
            merge.get("qa_acceptance_created_at") or ""
        ),
        qa_acceptance_revision=int(
            merge.get("qa_acceptance_revision") or 0
        ),
        qa_contract_runtime_verified=bool(
            merge.get("qa_contract_runtime_verified")
        ),
        merge_event_id=int(merge.get("merge_event_id") or 0),
        merge_event_created_at=str(merge.get("merge_event_created_at") or ""),
        reconcile_event_id=requested_reconcile_event_id,
        reconcile_event_created_at=str(
            reconcile.get("reconcile_event_created_at") or ""
        ),
        expected_contract_execution_id=str(
            record.get("contract_execution_id") or ""
        ),
        expected_task_id=str(merge.get("task_id") or ""),
        expected_runtime_context_id=str(
            merge.get("runtime_context_id") or ""
        ),
        expected_parent_task_id=str(merge.get("parent_task_id") or ""),
        expected_merge_queue_id=str(merge.get("merge_queue_id") or ""),
        trusted_contract_execution_lineage_verified=bool(
            merge.get("dispatch_lineage_verified") is True
            and str(merge.get("contract_execution_id") or "").strip()
            == str(record.get("contract_execution_id") or "").strip()
            and str(merge.get("contract_runtime_dispatch_source_ref") or "")
            .strip()
            .startswith("contract_runtime:")
        ),
        reconcile_task_id=str(reconcile.get("reconcile_task_id") or ""),
        reconcile_runtime_context_id=str(
            reconcile.get("reconcile_runtime_context_id") or ""
        ),
        allow_taskless=bool(
            reconcile.get("allow_taskless_reconcile")
            or merge.get("allow_taskless_reconcile")
        ),
    )
    active_snapshot_commit = str(
        state.get("active_snapshot_commit") or ""
    ).strip().lower()
    reconciled_commit = str(
        state.get("reconciled_commit_sha")
        or state.get("current_canonical_commit_sha")
        or ""
    ).strip().lower()
    canonical_head_equals_merged_commit = bool(
        merged_commit and canonical_head_commit == merged_commit
    )
    canonical_head_equals_reconciled_commit = bool(
        reconciled_commit and canonical_head_commit == reconciled_commit
    )
    reconciled_commit_is_ancestor_of_canonical_head = bool(
        canonical_head_equals_reconciled_commit
        or (
            root
            and reconciled_commit
            and canonical_head_commit
            and _git_commit_is_ancestor(
                Path(root),
                reconciled_commit,
                canonical_head_commit,
            )
        )
    )
    canonical_head_verified = bool(
        reconciled_commit_is_ancestor_of_canonical_head
    )
    db_verified = bool(
        merge.get("timeline_verified") is True and state.get("db_verified") is True
    )
    active_snapshot_matches_canonical_head = bool(
        active_snapshot_commit
        and active_snapshot_commit == canonical_head_commit
        and str(state.get("active_snapshot_status") or "").strip()
        == "active"
    )
    live_verified = bool(
        target_project_root
        and canonical_head_verified
        and active_snapshot_matches_canonical_head
    )
    active_snapshot_verified = bool(
        live_verified
        and state.get("active_snapshot_verified") is True
        and state.get(
            "active_snapshot_current_full_reconcile_verified"
        )
        is True
        and state.get("reconcile_snapshot_verified") is True
    )
    graph_reconciled = bool(db_verified and live_verified and active_snapshot_verified)
    authority = {
        **dict(state),
        "source": "graph_snapshot_store.current_full_reconcile_state",
        "server_derived": True,
        "db_verified": db_verified,
        "live_verified": live_verified,
        "canonical_head_verified": canonical_head_verified,
        "active_snapshot_verified": active_snapshot_verified,
        "active_snapshot_matches_canonical_head": (
            active_snapshot_matches_canonical_head
        ),
        "graph_reconciled": graph_reconciled,
        "project_id": project_id,
        "backlog_id": str(record.get("backlog_id") or ""),
        "contract_execution_id": str(record.get("contract_execution_id") or ""),
        "runtime_context_id": str(merge.get("runtime_context_id") or ""),
        "task_id": str(merge.get("task_id") or ""),
        "parent_task_id": str(merge.get("parent_task_id") or ""),
        "merge_queue_id": str(merge.get("merge_queue_id") or ""),
        "merged_commit_sha": merged_commit,
        "reconciled_commit_sha": reconciled_commit,
        "reconcile_provenance_target_commit": reconcile_target_commit,
        "current_canonical_commit_sha": canonical_head_commit,
        "canonical_head_commit": canonical_head_commit,
        "canonical_head_equals_merged_commit": (
            canonical_head_equals_merged_commit
        ),
        "canonical_head_equals_reconciled_commit": (
            canonical_head_equals_reconciled_commit
        ),
        "reconciled_commit_is_ancestor_of_canonical_head": (
            reconciled_commit_is_ancestor_of_canonical_head
        ),
        "target_project_root": target_project_root,
        "merge_source_ref": str(merge.get("merge_source_ref") or ""),
        "merge_event_id": int(merge.get("merge_event_id") or 0),
        "merge_event_created_at": str(
            merge.get("merge_event_created_at") or ""
        ),
        "merge_projection_verified": merge.get("timeline_verified") is True,
        "dispatch_lineage_verified": (
            merge.get("dispatch_lineage_verified") is True
        ),
        "contract_runtime_dispatch_source_ref": str(
            merge.get("contract_runtime_dispatch_source_ref") or ""
        ),
        "qa_source_ref": str(merge.get("qa_source_ref") or ""),
        "qa_acceptance_ref": str(merge.get("qa_acceptance_ref") or ""),
        "qa_acceptance_revision": int(
            merge.get("qa_acceptance_revision") or 0
        ),
        "qa_acceptance_created_at": str(
            merge.get("qa_acceptance_created_at") or ""
        ),
        "qa_contract_runtime_verified": bool(
            merge.get("qa_contract_runtime_verified")
        ),
        "reconcile_source_ref": str(
            reconcile.get("reconcile_source_ref") or ""
        ),
        "reconcile_event_id": int(
            reconcile.get("reconcile_event_id") or 0
        ),
        "reconcile_event_created_at": str(
            reconcile.get("reconcile_event_created_at") or ""
        ),
        "identity_mismatches": list(merge.get("identity_mismatches") or []),
    }
    if _is_mf_parallel_postmerge_revision(record):
        aggregate_identity = (
            merge.get("aggregate_final_merge_identity")
            if isinstance(
                merge.get("aggregate_final_merge_identity"), Mapping
            )
            else {}
        )
        line_instance_id = str(
            merge.get("reconcile_line_instance_id") or ""
        ).strip()
        lane_identity_source = str(
            merge.get("reconcile_lane_identity_source") or ""
        ).strip()
        aggregate_runtime_context_id = str(
            aggregate_identity.get("runtime_context_id") or ""
        ).strip()
        aggregate_parent_task_id = str(
            aggregate_identity.get("parent_task_id") or ""
        ).strip()
        aggregate_merge_queue_id = str(
            aggregate_identity.get("merge_queue_id") or ""
        ).strip()
        lane_runtime_context_ids = {
            str(value or "").strip()
            for value in merge.get("lane_runtime_context_ids") or []
            if str(value or "").strip()
        }
        lane_merge_queue_ids = {
            str(value or "").strip()
            for value in merge.get("lane_merge_queue_ids") or []
            if str(value or "").strip()
        }
        if (
            all(
                str(aggregate_identity.get(field) or "").strip()
                for field in (
                    "runtime_context_id",
                    "task_id",
                    "parent_task_id",
                    "merge_queue_id",
                )
            )
            and aggregate_parent_task_id
            == str(record.get("contract_execution_id") or "").strip()
            and aggregate_runtime_context_id in lane_runtime_context_ids
            and aggregate_merge_queue_id in lane_merge_queue_ids
            and str(authority.get("runtime_context_id") or "").strip()
            in lane_runtime_context_ids
            and str(authority.get("merge_queue_id") or "").strip()
            in lane_merge_queue_ids
            and line_instance_id
            == (
                "runtime_context:"
                f"{str(authority.get('runtime_context_id') or '').strip()}"
            )
            and lane_identity_source
            in {
                "RuntimeContext.current_values",
                "terminal_current_full_reconcile_receipt",
            }
        ):
            authority.update(
                {
                    "aggregate_final_merge_identity": dict(
                        aggregate_identity
                    ),
                    "reconcile_line_instance_id": line_instance_id,
                    "reconcile_lane_identity_source": lane_identity_source,
                }
            )
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _contract_runtime_postmerge_canonical_project_root(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    merge: Mapping[str, Any],
) -> str:
    """Resolve one canonical Git root from a sealed postmerge worker tuple.

    External governed projects are not necessarily registered in this server
    process's in-memory project catalog.  Their exact RuntimeContext still
    carries a server-written linked-worktree identity.  For rev8/rev9 only,
    bind that row to the ContractRuntime merge tuple and independently derive
    the canonical repository through Git's common directory.  Caller paths,
    path-string ancestry, and best-effort project fallbacks are never used.
    """

    if not _is_mf_parallel_postmerge_revision(record):
        return ""
    scope = {
        "project_id": str(project_id or "").strip(),
        "backlog_id": str(record.get("backlog_id") or "").strip(),
        "runtime_context_id": str(
            merge.get("runtime_context_id") or ""
        ).strip(),
        "task_id": str(merge.get("task_id") or "").strip(),
        "parent_task_id": str(
            merge.get("parent_task_id") or ""
        ).strip(),
        "merge_queue_id": str(
            merge.get("merge_queue_id") or ""
        ).strip(),
    }
    execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    if not (
        all(scope.values())
        and scope["parent_task_id"] == execution_id
        and merge.get("timeline_verified") is True
        and merge.get("dispatch_lineage_verified") is True
        and str(
            merge.get("contract_runtime_dispatch_source_ref") or ""
        ).strip().startswith(f"contract_runtime:{execution_id}:")
    ):
        return ""
    try:
        rows = conn.execute(
            """
            SELECT target_project_root, worktree_path, status
            FROM parallel_branch_runtime_contexts
            WHERE project_id = ? AND backlog_id = ?
              AND runtime_context_id = ? AND task_id = ?
              AND parent_task_id = ? AND merge_queue_id = ?
            ORDER BY runtime_context_id
            """,
            tuple(scope.values()),
        ).fetchall()
    except (AttributeError, sqlite3.Error):
        return ""
    if len(rows) != 1:
        return ""
    row = dict(rows[0])
    if str(row.get("status") or "").strip() != "merged":
        return ""
    linked_roots = {
        str(Path(str(row.get(field) or "")).resolve())
        for field in ("target_project_root", "worktree_path")
        if str(row.get(field) or "").strip()
    }
    if not linked_roots:
        return ""
    common_dirs: set[str] = set()
    for linked_root_text in linked_roots:
        linked_root = Path(linked_root_text)
        if not linked_root.is_dir():
            return ""
        shown_root = _git_output(linked_root, ["rev-parse", "--show-toplevel"])
        common_dir = _git_output(
            linked_root,
            ["rev-parse", "--path-format=absolute", "--git-common-dir"],
        )
        if not shown_root or not common_dir:
            return ""
        try:
            if not os.path.samefile(shown_root, linked_root):
                return ""
        except OSError:
            return ""
        common_dirs.add(str(Path(common_dir).resolve()))
    if len(common_dirs) != 1:
        return ""
    common_dir = Path(next(iter(common_dirs)))
    if common_dir.name != ".git" or not common_dir.is_dir():
        return ""
    canonical_root = common_dir.parent.resolve()
    canonical_shown_root = _git_output(
        canonical_root,
        ["rev-parse", "--show-toplevel"],
    )
    canonical_common_dir = _git_output(
        canonical_root,
        ["rev-parse", "--path-format=absolute", "--git-common-dir"],
    )
    try:
        root_exact = bool(
            canonical_shown_root
            and os.path.samefile(canonical_shown_root, canonical_root)
        )
        common_exact = bool(
            canonical_common_dir
            and os.path.samefile(canonical_common_dir, common_dir)
        )
    except OSError:
        return ""
    head_commit = _git_head_commit(canonical_root).strip().lower()
    if not (
        root_exact
        and common_exact
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", head_commit)
    ):
        return ""
    return str(canonical_root)


def _contract_runtime_shared_batch_reconcile_activation_verified(
    authority: Mapping[str, Any],
    *,
    allow_postmerge_qa_admission: bool = False,
) -> bool:
    shared = authority.get("shared_batch_reconcile_authority")
    if not isinstance(shared, Mapping):
        return False
    unsigned_shared = {
        key: value
        for key, value in shared.items()
        if key != "authority_hash"
    }
    ordered_queue_item_ids = shared.get("ordered_queue_item_ids")
    child_dispatch_refs = shared.get("child_contract_dispatch_refs")
    coordination_runtime_context_id = str(
        shared.get("coordination_runtime_context_id") or ""
    ).strip()
    coordination_contract_execution_id = str(
        shared.get("coordination_contract_execution_id") or ""
    ).strip()
    authority_purpose = str(
        shared.get("authority_purpose") or "child_close"
    ).strip()
    postmerge_qa_admission = bool(
        allow_postmerge_qa_admission
        and authority_purpose == "postmerge_qa_admission"
    )
    required_true_fields = (
        "all_children_merged",
        "closed_epoch_verified",
        "final_snapshot_verified",
    )
    return bool(
        str(shared.get("schema_version") or "")
        == "contract_runtime.shared_batch_final_reconcile_authority.v1"
        and str(shared.get("source") or "")
        == (
            "parallel_branch_integration_epochs+"
            "parallel_branch_merge_queue_items+"
            "contract_runtime_executions.completed_lines+"
            "graph_current_full_reconcile_provenance"
        )
        and shared.get("server_derived") is True
        and shared.get("db_verified") is True
        and all(shared.get(field) is True for field in required_true_fields)
        and (
            (
                postmerge_qa_admission
                and shared.get(
                    "all_children_postmerge_qa_admission_verified"
                )
                is True
                and shared.get("current_child_contract_qa_verified")
                is False
                and shared.get("final_qa_required_for_current_child")
                is True
                and shared.get(
                    "strict_child_qa_merge_reconcile_order_verified"
                )
                is False
                and shared.get(
                    "strict_child_merge_reconcile_order_verified"
                )
                is True
                and authority.get("qa_contract_runtime_verified") is False
                and authority.get("close_satisfying") is False
                and authority.get("pre_qa_merge_authorized") is True
                and authority.get("final_qa_required_after_reconcile")
                is True
            )
            or (
                not postmerge_qa_admission
                and authority_purpose == "child_close"
                and shared.get("all_children_contract_qa_verified") is True
                and shared.get(
                    "strict_child_qa_merge_reconcile_order_verified"
                )
                is True
                and authority.get("qa_contract_runtime_verified") is True
                and authority.get("close_satisfying") is True
            )
        )
        and shared.get("child_reconcile_required") is False
        and all(
            str(shared.get(field) or "").strip()
            for field in (
                "project_id",
                "batch_id",
                "merge_queue_id",
                "epoch_id",
                "coordination_backlog_id",
                "coordination_task_id",
                "batch_enter_task_id",
                "coordination_reconcile_task_id",
                "batch_enter_event_ref",
                "final_reconcile_event_ref",
                "final_head_commit",
                "active_snapshot_id",
            )
        )
        and bool(coordination_runtime_context_id)
        == bool(coordination_contract_execution_id)
    ) and bool(
        isinstance(ordered_queue_item_ids, list)
        and len(ordered_queue_item_ids) >= 2
        and all(
            str(queue_item_id or "").strip()
            for queue_item_id in ordered_queue_item_ids
        )
        and len(set(ordered_queue_item_ids)) == len(ordered_queue_item_ids)
        and isinstance(child_dispatch_refs, list)
        and len(child_dispatch_refs) == len(ordered_queue_item_ids)
        and all(
            str(dispatch_ref or "").strip()
            for dispatch_ref in child_dispatch_refs
        )
        and str(shared.get("batch_enter_event_ref") or "").startswith(
            "timeline:"
        )
        and str(shared.get("final_reconcile_event_ref") or "").startswith(
            "timeline:"
        )
        and str(shared.get("project_id") or "").strip()
        == str(authority.get("project_id") or "").strip()
        and str(shared.get("merge_queue_id") or "").strip()
        == str(authority.get("merge_queue_id") or "").strip()
        and str(shared.get("final_head_commit") or "").strip().lower()
        == str(authority.get("reconciled_commit_sha") or "").strip().lower()
        and str(shared.get("active_snapshot_id") or "").strip()
        == str(authority.get("active_snapshot_id") or "").strip()
        and str(shared.get("active_snapshot_id") or "").strip()
        == str(authority.get("reconcile_snapshot_id") or "").strip()
        and str(shared.get("final_reconcile_event_ref") or "").strip()
        == str(authority.get("reconcile_source_ref") or "").strip()
        and str(shared.get("authority_hash") or "")
        == stable_sha256(unsigned_shared)
    )


def _contract_runtime_shared_batch_postmerge_qa_activation_verified(
    authority: Mapping[str, Any],
) -> bool:
    return _contract_runtime_shared_batch_reconcile_activation_verified(
        authority,
        allow_postmerge_qa_admission=True,
    )


def _contract_runtime_projected_reconcile_line_commit_verified(
    *,
    declared_batch_child: bool,
    line_commit: Any,
    merged_commit: Any,
    reconcile_authority: Mapping[str, Any],
) -> bool:
    """Keep child merge lineage distinct from a Batch fan-in checkpoint.

    A standalone projected reconcile line remains pinned to its merge commit.
    A declared Batch child may instead name the final fan-in head, but only
    when the existing shared-Batch authority verifies and names that same
    head as both its final commit and the current-full reconciled commit.
    """

    line_commit = str(line_commit or "").strip().lower()
    merged_commit = str(merged_commit or "").strip().lower()
    if line_commit == merged_commit:
        return True
    shared = (
        reconcile_authority.get("shared_batch_reconcile_authority")
        if isinstance(
            reconcile_authority.get("shared_batch_reconcile_authority"),
            Mapping,
        )
        else {}
    )
    return bool(
        declared_batch_child
        and _contract_runtime_shared_batch_postmerge_qa_activation_verified(
            reconcile_authority
        )
        and line_commit
        == str(
            reconcile_authority.get("reconciled_commit_sha") or ""
        ).strip().lower()
        == str(shared.get("final_head_commit") or "").strip().lower()
    )


def _contract_runtime_current_full_reconcile_activation_verified(
    authority: Mapping[str, Any],
) -> bool:
    canonical_head = str(
        authority.get("canonical_head_commit")
        or authority.get("current_canonical_commit_sha")
        or ""
    ).strip().lower()
    required_true_fields = (
        "db_verified",
        "live_verified",
        "canonical_head_verified",
        "active_snapshot_verified",
        "active_snapshot_current_full_reconcile_verified",
        "active_snapshot_matches_canonical_head",
        "graph_reconciled",
        "provenance_verified",
        "provenance_scope_verified",
        "durable_order_verified",
        "reconcile_snapshot_verified",
        "contract_execution_scope_verified",
        "task_scope_verified",
        "runtime_context_scope_verified",
        "parent_task_scope_verified",
        "merge_queue_scope_verified",
    )
    return bool(
        str(authority.get("schema_version") or "")
        == "graph_snapshot_store.current_full_reconcile_state.v1"
        and authority.get("server_derived") is True
        and str(authority.get("source") or "")
        == "graph_snapshot_store.current_full_reconcile_state"
        and all(authority.get(field) is True for field in required_true_fields)
        and authority.get("current_full_reconcile") is True
        and str(authority.get("strategy") or "") == "current_full_reconcile"
        and str(authority.get("active_snapshot_status") or "") == "active"
        and canonical_head
        and str(authority.get("active_snapshot_commit") or "")
        .strip()
        .lower()
        == canonical_head
        and str(authority.get("reconciled_commit_sha") or "")
        .strip()
        .lower()
        == canonical_head
        and str(authority.get("reconcile_provenance_target_commit") or "")
        .strip()
        .lower()
        == canonical_head
        and str(authority.get("reconcile_source_ref") or "").startswith(
            "timeline:"
        )
        and (
            "shared_batch_reconcile_authority" not in authority
            or _contract_runtime_shared_batch_reconcile_activation_verified(
                authority
            )
            or _contract_runtime_shared_batch_postmerge_qa_activation_verified(
                authority
            )
        )
        and str(authority.get("authority_hash") or "")
        == stable_sha256(
            {
                key: value
                for key, value in authority.items()
                if key != "authority_hash"
            }
        )
    )


def _contract_runtime_reconcile_record_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the compact server-owned receipt used by observer_reconcile.

    This deliberately proves only the durable merge and sealed dispatch
    lineage.  A reconcile event/provenance may already exist and is exposed as
    advisory identity, but it is not required to record the line.  The full
    current-full verification is recomputed by close authority.
    """

    if _is_mf_parallel_postmerge_revision(record):
        merge = _contract_runtime_rev8_two_worker_merge_projection(
            record,
            required_worker_count=(
                _contract_runtime_mf_parallel_current_generation_worker_count(
                    record,
                    conn=conn,
                    project_id=project_id,
                )
            ),
            conn=conn,
            project_id=project_id,
        )
        merge = _contract_runtime_rev8_selected_reconcile_lane_projection(
            conn,
            project_id=project_id,
            record=record,
            aggregate_merge=merge,
        )
    else:
        merge = _contract_runtime_trusted_merge_projection(
            conn,
            project_id=project_id,
            record=record,
        )
    merged_commit = str(merge.get("merged_commit_sha") or "").strip().lower()
    merge_event_id = int(merge.get("merge_event_id") or 0)
    reconcile_event_id = int(merge.get("reconcile_event_id") or 0)
    merge_time = _contract_runtime_close_authority_time_order_value(
        merge.get("merge_event_created_at")
    )
    reconcile_time = _contract_runtime_close_authority_time_order_value(
        merge.get("reconcile_event_created_at")
    )
    reconcile_event_recorded = bool(
        reconcile_event_id > merge_event_id > 0
        and merge_time is not None
        and reconcile_time is not None
        and reconcile_time >= merge_time
        and str(merge.get("reconcile_source_ref") or "").startswith("timeline:")
    )
    authority = {
        "schema_version": (
            "contract_runtime.observer_reconcile_record_authority.v1"
        ),
        "source": "contract_runtime.server_reconcile_record_projection",
        "server_derived": True,
        "record_verified": bool(
            merge.get("timeline_verified") is True
            and merge.get("dispatch_lineage_verified") is True
            and str(merge.get("contract_runtime_dispatch_source_ref") or "")
            .strip()
            .startswith("contract_runtime:")
            and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", merged_commit)
            and merge_event_id > 0
            and merge_time is not None
            and all(
                str(merge.get(field) or "").strip()
                for field in (
                    "runtime_context_id",
                    "task_id",
                    "parent_task_id",
                    "backlog_id",
                    "merge_queue_id",
                    "merge_source_ref",
                )
            )
        ),
        "merge_projection_verified": merge.get("timeline_verified") is True,
        "dispatch_lineage_verified": (
            merge.get("dispatch_lineage_verified") is True
        ),
        "project_id": project_id,
        "backlog_id": str(record.get("backlog_id") or "").strip(),
        "contract_execution_id": str(
            record.get("contract_execution_id") or ""
        ).strip(),
        "runtime_context_id": str(
            merge.get("runtime_context_id") or ""
        ).strip(),
        "task_id": str(merge.get("task_id") or "").strip(),
        "parent_task_id": str(merge.get("parent_task_id") or "").strip(),
        "merge_queue_id": str(merge.get("merge_queue_id") or "").strip(),
        "merged_commit_sha": merged_commit,
        "merge_source_ref": str(merge.get("merge_source_ref") or "").strip(),
        "merge_event_id": merge_event_id,
        "merge_event_created_at": str(
            merge.get("merge_event_created_at") or ""
        ).strip(),
        "contract_runtime_dispatch_source_ref": str(
            merge.get("contract_runtime_dispatch_source_ref") or ""
        ).strip(),
        "all_lane_merges_verified": bool(
            merge.get("all_lane_merges_verified") is True
        ),
        "lane_merge_count": int(merge.get("lane_merge_count") or 0),
        "lane_runtime_context_ids": list(
            merge.get("lane_runtime_context_ids") or []
        ),
        "lane_merge_queue_ids": list(
            merge.get("lane_merge_queue_ids") or []
        ),
        "reconcile_event_recorded": reconcile_event_recorded,
        "reconcile_source_ref": (
            str(merge.get("reconcile_source_ref") or "").strip()
            if reconcile_event_recorded
            else ""
        ),
        "reconcile_event_id": (
            reconcile_event_id if reconcile_event_recorded else 0
        ),
        "reconcile_event_created_at": (
            str(merge.get("reconcile_event_created_at") or "").strip()
            if reconcile_event_recorded
            else ""
        ),
        "reconcile_task_id": (
            str(merge.get("reconcile_task_id") or "").strip()
            if reconcile_event_recorded
            else ""
        ),
        "reconcile_runtime_context_id": (
            str(merge.get("reconcile_runtime_context_id") or "").strip()
            if reconcile_event_recorded
            else ""
        ),
        "close_grade_authority_deferred": True,
        "close_grade_required_checks": [
            "durable_post_merge_reconcile_event",
            "current_full_reconcile_provenance",
            "contract_execution_scope",
            "worker_task_scope",
            "runtime_context_scope",
            "parent_task_scope",
            "merge_queue_scope",
        ],
    }
    shared_batch_authority = (
        merge
        if isinstance(
            merge.get("shared_batch_reconcile_authority"),
            Mapping,
        )
        and _contract_runtime_current_full_reconcile_activation_verified(
            merge
        )
        else {}
    )
    current_full_authority = (
        shared_batch_authority
        or _contract_runtime_current_full_reconcile_authority_from_merge(
            conn,
            project_id=project_id,
            record=record,
            merge=merge,
            reconcile=merge,
        )
    )
    current_full_activation_verified = bool(
        reconcile_event_recorded
        and (
            _contract_runtime_current_full_reconcile_activation_verified(
                current_full_authority
            )
            or (
                _is_mf_parallel_postmerge_revision(record)
                and str(
                    merge.get("reconcile_lane_identity_source") or ""
                ).strip()
                == "terminal_current_full_reconcile_receipt"
                and _contract_runtime_rev8_superseded_terminal_reconcile_receipt_verified(
                    current_full_authority
                )
            )
        )
        and str(current_full_authority.get("merge_source_ref") or "")
        == str(authority.get("merge_source_ref") or "")
        and str(current_full_authority.get("merged_commit_sha") or "")
        == str(authority.get("merged_commit_sha") or "")
    )
    authority["current_full_reconcile_activation_verified"] = (
        current_full_activation_verified
    )
    if current_full_activation_verified:
        authority["terminal_current_full_reconcile_authority"] = dict(
            current_full_authority
        )
    authority["authority_hash"] = stable_sha256(authority)
    return authority


_CONTRACT_RUNTIME_RECONCILE_RECEIPT_CORRECTION_SCHEMA = (
    "contract_runtime.observer_reconcile_receipt_correction.v1"
)


def _contract_runtime_reconcile_receipt_line_hash(
    line: Mapping[str, Any],
) -> str:
    """Hash the immutable stored line without transient read-model fields."""

    return stable_sha256(
        {
            key: value
            for key, value in line.items()
            if not str(key).startswith("_")
        }
    )


def _contract_runtime_legacy_reconcile_receipt_variants(
    current: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Reconstruct the only pre-current-full receipts accepted for repair."""

    if not _contract_runtime_current_full_reconcile_activation_verified(
        current.get("terminal_current_full_reconcile_authority")
        if isinstance(
            current.get("terminal_current_full_reconcile_authority"),
            Mapping,
        )
        else {}
    ):
        return []
    variants: list[dict[str, Any]] = []
    for preserve_event in (False, True):
        candidate = {
            key: deepcopy(value)
            for key, value in current.items()
            if key
            not in {
                "authority_hash",
                "terminal_current_full_reconcile_authority",
            }
        }
        candidate["current_full_reconcile_activation_verified"] = False
        if not preserve_event:
            candidate.update(
                {
                    "reconcile_event_recorded": False,
                    "reconcile_source_ref": "",
                    "reconcile_event_id": 0,
                    "reconcile_event_created_at": "",
                    "reconcile_task_id": "",
                    "reconcile_runtime_context_id": "",
                }
            )
        candidate["authority_hash"] = stable_sha256(candidate)
        variants.append(candidate)

    # A later same-commit current-full may supersede the source receipt's
    # snapshot while preserving that source reconcile as the immutable
    # reconcile provenance.  Reconstruct the exact prior active-snapshot
    # projection only from the verified terminal authority's own provenance;
    # never accept a caller-shaped snapshot transition.
    terminal = current.get("terminal_current_full_reconcile_authority")
    if isinstance(terminal, Mapping):
        terminal = deepcopy(dict(terminal))
        provenance = terminal.get("current_full_reconcile_provenance")
        reconcile_snapshot_id = str(
            terminal.get("reconcile_snapshot_id") or ""
        ).strip()
        if (
            isinstance(provenance, Mapping)
            and str(terminal.get("reconcile_snapshot_status") or "")
            == "superseded"
            and reconcile_snapshot_id
            and str(terminal.get("active_snapshot_id") or "").strip()
            != reconcile_snapshot_id
            and str(provenance.get("snapshot_id") or "").strip()
            == reconcile_snapshot_id
            and str(provenance.get("provenance_id") or "").strip()
            and str(provenance.get("provenance_hash") or "").strip()
        ):
            prior = deepcopy(dict(current))
            prior_terminal = deepcopy(terminal)
            prior_terminal.update(
                {
                    "active_snapshot_id": reconcile_snapshot_id,
                    "active_source_ref": (
                        f"graph_snapshot:{reconcile_snapshot_id}"
                    ),
                    "active_snapshot_current_full_provenance_id": str(
                        provenance.get("provenance_id") or ""
                    ).strip(),
                    "active_snapshot_current_full_provenance_hash": str(
                        provenance.get("provenance_hash") or ""
                    ).strip(),
                    "active_snapshot_current_full_reconcile_event_id": int(
                        terminal.get("reconcile_event_id") or 0
                    ),
                    "active_snapshot_current_full_reconcile_event_created_at": str(
                        terminal.get("reconcile_event_created_at") or ""
                    ).strip(),
                    "active_snapshot_current_full_runtime_context_id": str(
                        terminal.get("runtime_context_id") or ""
                    ).strip(),
                    "active_snapshot_current_full_task_id": str(
                        terminal.get("task_id") or ""
                    ).strip(),
                    "reconcile_snapshot_status": "active",
                }
            )
            prior_terminal["authority_hash"] = stable_sha256(
                {
                    key: value
                    for key, value in prior_terminal.items()
                    if key != "authority_hash"
                }
            )
            prior["terminal_current_full_reconcile_authority"] = (
                prior_terminal
            )
            prior["authority_hash"] = stable_sha256(
                {
                    key: value
                    for key, value in prior.items()
                    if key != "authority_hash"
                }
            )
            variants.append(prior)
    return variants


def _contract_runtime_reconcile_receipt_correction_marker(
    *,
    record: Mapping[str, Any],
    source_line: Mapping[str, Any],
    source_line_index: int,
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the closed append-only transition from one legacy receipt."""

    terminal = (
        authority.get("terminal_current_full_reconcile_authority")
        if isinstance(
            authority.get("terminal_current_full_reconcile_authority"),
            Mapping,
        )
        else {}
    )
    provenance = (
        terminal.get("current_full_reconcile_provenance")
        if isinstance(
            terminal.get("current_full_reconcile_provenance"), Mapping
        )
        else {}
    )
    activation = (
        terminal.get("current_full_reconcile_marker")
        if isinstance(
            terminal.get("current_full_reconcile_marker"), Mapping
        )
        else {}
    )
    activation_route_evidence = (
        activation.get("route_evidence")
        if isinstance(activation.get("route_evidence"), Mapping)
        else {}
    )
    reconcile_event_id = int(terminal.get("reconcile_event_id") or 0)
    reconcile_source_ref = str(
        terminal.get("reconcile_source_ref") or ""
    ).strip()
    timeline_event_core = {
        "event_id": reconcile_event_id,
        "event_ref": reconcile_source_ref,
        "created_at": str(
            terminal.get("reconcile_event_created_at") or ""
        ).strip(),
        "runtime_context_id": str(
            terminal.get("runtime_context_id") or ""
        ).strip(),
        "task_id": str(terminal.get("task_id") or "").strip(),
        "parent_task_id": str(
            terminal.get("parent_task_id") or ""
        ).strip(),
        "merge_queue_id": str(
            terminal.get("merge_queue_id") or ""
        ).strip(),
        "target_commit_sha": str(
            terminal.get("reconciled_commit_sha") or ""
        ).strip().lower(),
    }
    marker = {
        "schema_version": (
            _CONTRACT_RUNTIME_RECONCILE_RECEIPT_CORRECTION_SCHEMA
        ),
        "source": (
            "ContractRuntime.completed_lines+"
            "graph_current_full_reconcile_provenance+task_timeline_events"
        ),
        "server_derived": True,
        "append_only_history_preserved": True,
        "historical_line_rewritten": False,
        "project_id": str(record.get("project_id") or "").strip(),
        "backlog_id": str(record.get("backlog_id") or "").strip(),
        "contract_execution_id": str(
            record.get("contract_execution_id") or ""
        ).strip(),
        "runtime_context_id": timeline_event_core["runtime_context_id"],
        "task_id": timeline_event_core["task_id"],
        "parent_task_id": timeline_event_core["parent_task_id"],
        "merge_queue_id": timeline_event_core["merge_queue_id"],
        "merged_commit_sha": str(
            authority.get("merged_commit_sha") or ""
        ).strip().lower(),
        "source_completed_line_index": source_line_index,
        "source_completed_line_ref": (
            "contract_runtime:"
            f"{str(record.get('contract_execution_id') or '').strip()}:"
            f"completed_lines:{source_line_index}"
        ),
        "source_completed_line_hash": (
            _contract_runtime_reconcile_receipt_line_hash(source_line)
        ),
        "source_reconcile_authority_hash": str(
            _contract_runtime_close_authority_payload_mapping(
                source_line,
                "reconcile_authority",
            ).get("authority_hash")
            or ""
        ).strip(),
        "corrected_reconcile_authority_hash": str(
            authority.get("authority_hash") or ""
        ).strip(),
        "active_snapshot_id": str(
            terminal.get("active_snapshot_id") or ""
        ).strip(),
        "reconcile_snapshot_id": str(
            terminal.get("reconcile_snapshot_id") or ""
        ).strip(),
        "reconcile_run_id": str(
            activation.get("run_id")
            or activation_route_evidence.get("reconcile_run_id")
            or provenance.get("run_id")
            or ""
        ).strip(),
        "reconcile_request_id": str(
            activation.get("request_id")
            or provenance.get("request_id")
            or ""
        ).strip(),
        "reconcile_provenance_id": str(
            provenance.get("provenance_id") or ""
        ).strip(),
        "reconcile_provenance_hash": str(
            provenance.get("provenance_hash") or ""
        ).strip(),
        "reconcile_event_id": reconcile_event_id,
        "reconcile_event_ref": reconcile_source_ref,
        "reconcile_timeline_event_hash": stable_sha256(
            timeline_event_core
        ),
    }
    marker["correction_id"] = stable_sha256(marker)
    return marker


def _contract_runtime_reconcile_receipt_correction_valid(
    *,
    record: Mapping[str, Any],
    source_line: Mapping[str, Any],
    source_line_index: int,
    correction_line: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> bool:
    payload = (
        correction_line.get("payload")
        if isinstance(correction_line.get("payload"), Mapping)
        else {}
    )
    marker = (
        payload.get("canonical_reconcile_receipt_correction")
        if isinstance(
            payload.get("canonical_reconcile_receipt_correction"), Mapping
        )
        else {}
    )
    corrected = (
        payload.get("reconcile_authority")
        if isinstance(payload.get("reconcile_authority"), Mapping)
        else {}
    )
    expected_marker = _contract_runtime_reconcile_receipt_correction_marker(
        record=record,
        source_line=source_line,
        source_line_index=source_line_index,
        authority=authority,
    )
    required_text = (
        "project_id",
        "backlog_id",
        "contract_execution_id",
        "runtime_context_id",
        "task_id",
        "parent_task_id",
        "merge_queue_id",
        "merged_commit_sha",
        "source_completed_line_ref",
        "source_completed_line_hash",
        "source_reconcile_authority_hash",
        "corrected_reconcile_authority_hash",
        "active_snapshot_id",
        "reconcile_snapshot_id",
        "reconcile_run_id",
        "reconcile_request_id",
        "reconcile_provenance_id",
        "reconcile_provenance_hash",
        "reconcile_event_ref",
        "reconcile_timeline_event_hash",
        "correction_id",
    )
    return bool(
        all(str(expected_marker.get(field) or "").strip() for field in required_text)
        and int(expected_marker.get("reconcile_event_id") or 0) > 0
        and stable_sha256(marker) == stable_sha256(expected_marker)
        and stable_sha256(corrected) == stable_sha256(authority)
        and set(payload) == {
            "canonical_reconcile_receipt_correction",
            "reconcile_authority",
        }
        and str(correction_line.get("stage_id") or "").strip()
        == str(source_line.get("stage_id") or "").strip()
        and str(correction_line.get("stage_id") or "").strip()
        in {"observer_integration", "observer_reconcile"}
        and str(correction_line.get("line_id") or "").strip()
        == "observer_reconcile"
        and str(correction_line.get("actor_role") or "").strip()
        == "observer"
        and str(correction_line.get("evidence_kind") or "").strip()
        == "reconcile"
        and _contract_runtime_line_status_passes(correction_line)
    )


def _contract_runtime_bind_reconcile_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    policy: Mapping[str, Any],
) -> dict[str, Any]:
    authority = _contract_runtime_reconcile_record_authority(
        conn,
        project_id=project_id,
        record=record,
    )
    terminal = (
        authority.get("terminal_current_full_reconcile_authority")
        if isinstance(
            authority.get("terminal_current_full_reconcile_authority"),
            Mapping,
        )
        else {}
    )
    if not (
        authority.get("record_verified") is True
        and authority.get("reconcile_event_recorded") is True
        and authority.get("current_full_reconcile_activation_verified")
        is True
        and (
            _contract_runtime_current_full_reconcile_activation_verified(
                terminal
            )
            or _contract_runtime_rev8_superseded_terminal_reconcile_receipt_verified(
                terminal
            )
        )
    ):
        raise GovernanceError(
            "contract_runtime_observer_reconcile_current_full_required",
            (
                "observer_reconcile requires one unique exact durable "
                "graph_current_full_reconcile receipt before the contract "
                "line can be prechecked or submitted"
            ),
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "line_id": "observer_reconcile",
                "required_action": "graph_current_full_reconcile",
                "writes_performed": False,
                "fail_closed": True,
            },
        )
    for field in (
        "runtime_context_id",
        "task_id",
        "parent_task_id",
        "merge_queue_id",
    ):
        supplied = _contract_runtime_mapping_value(write, field)
        expected = str(authority.get(field) or "").strip()
        if supplied and supplied != expected:
            raise GovernanceError(
                "contract_runtime_observer_reconcile_identity_mismatch",
                f"observer_reconcile {field} does not match server authority",
                409,
                {
                    "field": field,
                    "contract_execution_id": str(
                        record.get("contract_execution_id") or ""
                    ),
                    "writes_performed": False,
                    "fail_closed": True,
                },
            )
    supplied_commit = str(write.get("commit_sha") or "").strip().lower()
    expected_commit = str(
        authority.get("merged_commit_sha") or ""
    ).strip().lower()
    if supplied_commit and supplied_commit != expected_commit:
        raise GovernanceError(
            "contract_runtime_observer_reconcile_identity_mismatch",
            "observer_reconcile commit_sha does not match server authority",
            409,
            {
                "field": "commit_sha",
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "writes_performed": False,
                "fail_closed": True,
            },
        )
    sanitized = _contract_runtime_strip_authority_claims(
        write,
        field_names=_CONTRACT_RUNTIME_RECONCILE_AUTHORITY_FIELDS,
        container_names={"reconcile_authority"},
        preserve_top_level=_CONTRACT_RUNTIME_AUTHORITY_TOP_LEVEL_FIELDS,
    )
    sanitized = dict(sanitized) if isinstance(sanitized, Mapping) else {}
    raw_payload = (
        sanitized.get("payload")
        if isinstance(sanitized.get("payload"), Mapping)
        else {}
    )
    payload = dict(raw_payload)
    payload = dict(payload) if isinstance(payload, Mapping) else {}
    authority_key = str(policy.get("authority_object_path") or "").split(".", 1)[-1]
    payload[authority_key] = authority

    effective = sanitized
    effective["payload"] = payload
    for field in (
        "runtime_context_id",
        "task_id",
        "parent_task_id",
        "merge_queue_id",
    ):
        value = str(authority.get(field) or "").strip()
        if value:
            effective[field] = value
    merged_commit = str(authority.get("merged_commit_sha") or "").strip()
    if merged_commit:
        effective["commit_sha"] = merged_commit
    return effective


def _contract_runtime_mf_parallel_dispatch_authority_policy(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    if not _is_mf_parallel_record_contract_id(
        str(record.get("contract_id") or "").strip()
    ):
        return {}
    if not str(record.get("version") or "").strip() or not str(
        record.get("revision") or ""
    ).strip():
        return {}
    definition = _contract_runtime_definition_for_record(record)
    system_layer = (
        definition.get("system_layer")
        if isinstance(definition.get("system_layer"), Mapping)
        else {}
    )
    policy = (
        system_layer.get("dispatch_ticket_authority_policy")
        if isinstance(
            system_layer.get("dispatch_ticket_authority_policy"), Mapping
        )
        else {}
    )
    if (
        policy.get("enabled") is not True
        or policy.get("validate_before_precheck_and_submit") is not True
    ):
        return {}
    return dict(policy)


def _contract_runtime_mf_batch_child_worker_cardinality_authority(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    batch_id: str,
    merge_queue_id: str,
    queue_item_id: str = "",
) -> dict[str, Any]:
    """Verify that one mf_parallel successor is a canonical batch row child.

    A caller-provided ``parent_batch_id`` is never sufficient to reduce the
    rev8 fan-out. The claim must resolve to exactly one server-authored batch
    enter event and its immutable durable merge-queue child identity.
    """

    values = {
        "project_id": str(project_id or "").strip(),
        "backlog_id": str(backlog_id or "").strip(),
        "task_id": str(task_id or "").strip(),
        "batch_id": str(batch_id or "").strip(),
        "merge_queue_id": str(merge_queue_id or "").strip(),
        "queue_item_id": str(queue_item_id or "").strip(),
    }
    if conn is None or not all(
        values[field]
        for field in (
            "project_id",
            "backlog_id",
            "task_id",
            "batch_id",
            "merge_queue_id",
        )
    ):
        return {}

    try:
        queue_rows = [
            dict(row)
            for row in conn.execute(
                """
                SELECT *
                FROM parallel_branch_merge_queue_items
                WHERE project_id = ? AND merge_queue_id = ?
                ORDER BY queue_index ASC, queue_item_id ASC
                """,
                (values["project_id"], values["merge_queue_id"]),
            ).fetchall()
        ]
    except sqlite3.Error:
        return {}
    child_rows = [
        row
        for row in queue_rows
        if str(row.get("backlog_id") or "").strip()
        == values["backlog_id"]
        and str(row.get("task_id") or "").strip() == values["task_id"]
    ]
    if len(queue_rows) < 2 or len(child_rows) != 1:
        return {}
    child_row = child_rows[0]
    canonical_queue_item_id = str(
        child_row.get("queue_item_id") or ""
    ).strip()
    if not canonical_queue_item_id or (
        values["queue_item_id"]
        and values["queue_item_id"] != canonical_queue_item_id
    ):
        return {}

    try:
        entered_rows = conn.execute(
            """
            SELECT *
            FROM task_timeline_events
            WHERE project_id = ? AND event_type = 'mf_batch_parallel.entered'
            ORDER BY id ASC
            """,
            (values["project_id"],),
        ).fetchall()
    except sqlite3.Error:
        return {}

    matches: list[
        tuple[dict[str, Any], Mapping[str, Any], Mapping[str, Any]]
    ] = []
    for raw_row in entered_rows:
        row = dict(raw_row)
        payload = _json_loads(row.get("payload_json"), {})
        if not isinstance(payload, Mapping):
            continue
        coordination_backlog_id = str(
            row.get("backlog_id") or payload.get("backlog_id") or ""
        ).strip()
        if not (
            str(row.get("event_kind") or "").strip()
            in {"contract_binding", "mf_batch_parallel_entered"}
            and str(row.get("status") or "").strip()
            in {"accepted", "passed"}
            and _contract_runtime_close_authority_timeline_actor_role(
                {**row, "payload": payload}
            )
            == "observer"
            and _contract_runtime_shared_batch_enter_binding_verified(
                payload,
                project_id=values["project_id"],
                batch_id=values["batch_id"],
                coordination_backlog_id=coordination_backlog_id,
                merge_queue_id=values["merge_queue_id"],
                queue_rows=queue_rows,
            )
        ):
            continue
        fanout = (
            payload.get("fanout_policy")
            if isinstance(payload.get("fanout_policy"), Mapping)
            else {}
        )
        successors = [
            item
            for item in fanout.get("per_row_successors") or []
            if isinstance(item, Mapping)
        ]
        child_matches = []
        for successor in successors:
            body = (
                successor.get("body")
                if isinstance(successor.get("body"), Mapping)
                else {}
            )
            merge_queue = (
                successor.get("merge_queue")
                if isinstance(successor.get("merge_queue"), Mapping)
                else {}
            )
            if (
                str(successor.get("backlog_id") or "").strip()
                == values["backlog_id"]
                and str(body.get("task_id") or "").strip()
                == values["task_id"]
                and str(body.get("parent_batch_id") or "").strip()
                == values["batch_id"]
                and str(body.get("merge_queue_id") or "").strip()
                == values["merge_queue_id"]
                and str(merge_queue.get("merge_queue_id") or "").strip()
                == values["merge_queue_id"]
                and str(merge_queue.get("queue_item_id") or "").strip()
                == canonical_queue_item_id
            ):
                child_matches.append(successor)
        if len(child_matches) == 1:
            matches.append((row, payload, child_matches[0]))
    if len(matches) != 1:
        return {}

    entered_row, entered_payload, entered_successor = matches[0]
    successor_body = (
        entered_successor.get("body")
        if isinstance(entered_successor.get("body"), Mapping)
        else {}
    )
    successor_metadata = (
        successor_body.get("metadata")
        if isinstance(successor_body.get("metadata"), Mapping)
        else {}
    )
    raw_lane_intents = successor_metadata.get("lane_intents")
    canonical_lane_intents = (
        deepcopy(raw_lane_intents)
        if isinstance(raw_lane_intents, list)
        else []
    )
    lane_intents_authority_present = bool(
        successor_metadata.get("required_worker_count") == 1
        and len(canonical_lane_intents) == 1
        and isinstance(canonical_lane_intents[0], Mapping)
        and str(canonical_lane_intents[0].get("task_id") or "").strip()
        == values["task_id"]
    )
    # Historical batch events predate typed lane intent persistence.  Their
    # queue/cardinality lineage remains valid for historical reads, but they
    # cannot authorize a fresh marker-enabled rev10 plan.
    if raw_lane_intents is not None and not lane_intents_authority_present:
        return {}
    authority = {
        "schema_version": (
            "contract_runtime.mf_batch_child_worker_cardinality_authority.v1"
        ),
        "source": (
            "server_authored_mf_batch_enter+durable_merge_queue_identity"
        ),
        "server_derived": True,
        "db_verified": True,
        "project_id": values["project_id"],
        "coordination_backlog_id": str(
            entered_row.get("backlog_id")
            or entered_payload.get("backlog_id")
            or ""
        ).strip(),
        "child_backlog_id": values["backlog_id"],
        "child_task_id": values["task_id"],
        "batch_id": values["batch_id"],
        "merge_queue_id": values["merge_queue_id"],
        "queue_item_id": canonical_queue_item_id,
        "batch_enter_event_id": int(entered_row.get("id") or 0),
        "lane_intents": canonical_lane_intents,
        "lane_intents_hash": stable_sha256(canonical_lane_intents),
        "lane_intents_authority_present": lane_intents_authority_present,
        "required_worker_count": 1,
        "worker_count_policy": "exactly",
        "atomic_dispatch_required": False,
        "standalone_mf_parallel_policy_unchanged": True,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _contract_runtime_mf_parallel_required_worker_count(
    record: Mapping[str, Any],
    *,
    conn=None,
    project_id: str = "",
) -> int:
    """Return the server-verified effective mf_parallel worker cardinality."""

    policy = _contract_runtime_mf_parallel_dispatch_authority_policy(record)
    try:
        count = int(policy.get("required_worker_count") or 1)
    except (TypeError, ValueError):
        count = 1
    pinned_count = max(1, count)
    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    selection = (
        metadata.get("observer_worker_cardinality_selection")
        if isinstance(
            metadata.get("observer_worker_cardinality_selection"), Mapping
        )
        else {}
    )
    if not selection:
        if _is_mf_parallel_postmerge_revision(record) and not policy:
            return 2
        return pinned_count
    if selection.get("observer_selected") is not True:
        # Compatibility for executions entered before observer cardinality was
        # a first-class input. Fresh Desktop observers must select explicitly;
        # only that explicit, hash-frozen selection can reduce a canonical
        # batch child to one worker. Legacy omission retains the pre-cutover
        # standalone exactly-two policy; it never infers one from batch shape.
        return pinned_count
    try:
        selected_count = int(selection.get("required_worker_count"))
    except (TypeError, ValueError):
        return pinned_count
    selection_valid = bool(
        selection.get("observer_selected") is True
        and selection.get("selection_frozen") is True
        and str(selection.get("selection_origin") or "")
        in {"mf_parallel_enter", "mf_parallel_revise"}
        and str(selection.get("selection_hash") or "")
        == stable_sha256(
            {
                key: value
                for key, value in selection.items()
                if key != "selection_hash"
            }
        )
    )
    if not selection_valid:
        return pinned_count
    if selected_count == 2:
        return 2
    if selected_count != 1:
        return pinned_count
    claimed = (
        selection.get("batch_child_authority")
        if isinstance(selection.get("batch_child_authority"), Mapping)
        else {}
    )
    if not claimed:
        return selected_count
    backlog_lineage = (
        record.get("backlog_lineage")
        if isinstance(record.get("backlog_lineage"), Mapping)
        else {}
    )
    record_project_id = str(
        project_id or record.get("project_id") or ""
    ).strip()
    record_backlog_id = str(record.get("backlog_id") or "").strip()
    record_task_id = str(
        backlog_lineage.get("task_id")
        or claimed.get("child_task_id")
        or ""
    ).strip()
    verified = _contract_runtime_mf_batch_child_worker_cardinality_authority(
        conn,
        project_id=record_project_id,
        backlog_id=record_backlog_id,
        task_id=record_task_id,
        batch_id=str(claimed.get("batch_id") or ""),
        merge_queue_id=str(claimed.get("merge_queue_id") or ""),
        queue_item_id=str(claimed.get("queue_item_id") or ""),
    )
    if not (
        verified.get("db_verified") is True
        and verified.get("server_derived") is True
        and str(verified.get("authority_hash") or "")
        == stable_sha256(
            {
                key: value
                for key, value in verified.items()
                if key != "authority_hash"
            }
        )
        and stable_sha256(verified) == stable_sha256(dict(claimed))
        and selection_valid
    ):
        return pinned_count
    return 1


_MF_PARALLEL_PREFILL_CHILD_PLAN_SCHEMA = (
    "mf_parallel.observer_prefill_child_plan.v1"
)
_MF_PARALLEL_PREFILL_PAYLOAD_SCHEMA = (
    "mf_parallel.observer_prefill_child_contracts.v1"
)
_MF_PARALLEL_LANE_INTENT_FIELDS = frozenset(
    {"task_id", "worker_id", "worker_slot_id", "owned_files"}
)


def _contract_runtime_mf_parallel_project_test_command_authority(
    project_id: str,
) -> dict[str, Any]:
    """Freeze registered project test commands without accepting caller input."""

    config, config_source = _registry_project_config(project_id)
    if not config:
        raise ValidationError(
            "mf_parallel rev10 prefill requires registered project test commands",
            {
                "project_id": project_id,
                "test_command_authority": "project_config.testing",
                "reason": "registered project config snapshot is missing",
                "writes_performed": False,
                "mutation_performed": False,
            },
        )
    testing = config.get("testing") if isinstance(config.get("testing"), Mapping) else {}
    command_fields = {
        "unit_command": _runtime_context_non_placeholder_text(
            testing.get("unit_command")
        ),
        "e2e_command": _runtime_context_non_placeholder_text(
            testing.get("e2e_command")
        ),
    }
    e2e = testing.get("e2e") if isinstance(testing.get("e2e"), Mapping) else {}
    e2e_auto_run = e2e.get("auto_run") is True
    commands = list(
        dict.fromkeys(
            value
            for field, value in command_fields.items()
            if value and (field == "unit_command" or e2e_auto_run)
        )
    )
    if not commands:
        raise ValidationError(
            "mf_parallel rev10 prefill requires registered project test commands",
            {
                "project_id": project_id,
                "test_command_authority": "project_config.testing",
                "missing_fields": [
                    "testing.unit_command",
                    "testing.e2e_command",
                ],
                "writes_performed": False,
                "mutation_performed": False,
            },
        )
    authority = {
        "schema_version": "mf_parallel.project_test_command_authority.v1",
        "project_id": project_id,
        "source": "project_config.testing",
        "config_source": str(
            config.get("config_source") or config_source or "aming_claw_registry"
        ).strip(),
        "command_fields": command_fields,
        "selection": {
            "unit_command_selected": bool(command_fields["unit_command"]),
            "e2e_command_selected": bool(
                command_fields["e2e_command"] and e2e_auto_run
            ),
            "e2e_auto_run": e2e_auto_run,
            "source": "project_config.testing.e2e.auto_run",
        },
        "test_commands": commands,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _contract_runtime_mf_parallel_build_prefill_child_plan(
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
    parent_contract_execution_id: str,
    root_contract_execution_id: str,
    required_worker_count: int,
    declared_files: Sequence[str],
    row_test_files: Sequence[str],
    acceptance_criteria: Sequence[Any],
    acceptance_scope_closure: Mapping[str, Any],
    test_command_authority: Mapping[str, Any],
    parent_route_binding: Mapping[str, Any],
    lane_intents: Any,
    source: str = "authenticated_observer_mf_parallel_enter",
) -> dict[str, Any]:
    """Canonicalize the observer's minimal child plan without minting routes.

    The observer owns the semantic lane split.  Every execution/materialization
    field remains absent here so the existing route issue and allocation
    precheck services stay authoritative for route, commit, worktree, branch,
    and merge-queue materialization.
    """

    if not isinstance(lane_intents, list):
        raise ValidationError(
            "mf_parallel lane_intents must be an array",
            {
                "field": "metadata.lane_intents",
                "required_worker_count": required_worker_count,
                "writes_performed": False,
            },
        )
    errors: list[str] = []
    if len(lane_intents) != required_worker_count:
        errors.append(
            "lane_intents count must equal required_worker_count"
        )
    normalized_lanes: list[dict[str, Any]] = []
    task_ids: list[str] = []
    worker_ids: list[str] = []
    worker_slot_ids: list[str] = []
    all_lane_files: list[str] = []
    test_file_set = set(_runtime_context_public_file_values(row_test_files))
    command_authority = deepcopy(dict(test_command_authority))
    authority_hash = str(command_authority.get("authority_hash") or "").strip()
    unsigned_authority = {
        key: value
        for key, value in command_authority.items()
        if key != "authority_hash"
    }
    test_commands = _runtime_context_service_query_values(
        command_authority,
        "test_commands",
    )
    if not (
        command_authority.get("schema_version")
        == "mf_parallel.project_test_command_authority.v1"
        and str(command_authority.get("project_id") or "").strip()
        == str(project_id or "").strip()
        and command_authority.get("source") == "project_config.testing"
        and test_commands
        and authority_hash == stable_sha256(unsigned_authority)
    ):
        errors.append("project test command authority must be complete and exact")
    for index, raw_lane in enumerate(lane_intents):
        if not isinstance(raw_lane, Mapping):
            errors.append(f"lane_intents[{index}] must be an object")
            continue
        forbidden = sorted(set(raw_lane) - _MF_PARALLEL_LANE_INTENT_FIELDS)
        if forbidden:
            errors.append(
                f"lane_intents[{index}] contains forbidden fields: "
                + ", ".join(forbidden)
            )
        task_id = _runtime_context_non_placeholder_text(
            raw_lane.get("task_id")
        )
        worker_id = _runtime_context_non_placeholder_text(
            raw_lane.get("worker_id")
        )
        worker_slot_id = _runtime_context_non_placeholder_text(
            raw_lane.get("worker_slot_id")
        )
        for field, value in (
            ("task_id", task_id),
            ("worker_id", worker_id),
            ("worker_slot_id", worker_slot_id),
        ):
            if not value:
                errors.append(
                    f"lane_intents[{index}].{field} must be concrete"
                )
        raw_owned_files = raw_lane.get("owned_files")
        lane_files: list[str] = []
        if not isinstance(raw_owned_files, list) or not raw_owned_files:
            errors.append(
                f"lane_intents[{index}].owned_files must be a non-empty array"
            )
        else:
            for path_index, raw_path in enumerate(raw_owned_files):
                path = _runtime_context_non_placeholder_text(raw_path)
                path_parts = Path(path).parts if path else ()
                if (
                    not path
                    or Path(path).is_absolute()
                    or ".." in path_parts
                ):
                    errors.append(
                        "lane_intents["
                        f"{index}].owned_files[{path_index}] must be a concrete "
                        "repo-relative path"
                    )
                    continue
                lane_files.append(path)
            if len(set(lane_files)) != len(lane_files):
                errors.append(
                    f"lane_intents[{index}].owned_files contains duplicates"
                )
        lane_files = sorted(set(lane_files))
        lane_slug = _parallel_branch_allocate_slug(
            f"{task_id}-{worker_id}"
        )
        if task_id and worker_id and not lane_slug:
            errors.append(
                f"lane_intents[{index}] identity cannot form a safe lane slug"
            )
        normalized_lanes.append(
            {
                "schema_version": "mf_parallel.child_lane_intent.v1",
                "lane_index": index,
                "task_id": task_id,
                "worker_id": worker_id,
                "worker_slot_id": worker_slot_id,
                "owned_files": lane_files,
                "target_files": lane_files,
                "test_files": sorted(set(lane_files).intersection(test_file_set)),
                "test_commands": list(test_commands),
                "test_command_authority_hash": authority_hash,
                "merge_queue_materialized": False,
            }
        )
        task_ids.append(task_id)
        worker_ids.append(worker_id)
        worker_slot_ids.append(worker_slot_id)
        all_lane_files.extend(lane_files)

    for field, values in (
        ("task_id", task_ids),
        ("worker_id", worker_ids),
        ("worker_slot_id", worker_slot_ids),
    ):
        concrete = [value for value in values if value]
        if len(concrete) != len(set(concrete)):
            errors.append(f"lane_intents require distinct {field}")
    if len(all_lane_files) != len(set(all_lane_files)):
        overlap = sorted(
            path
            for path in set(all_lane_files)
            if all_lane_files.count(path) > 1
        )
        errors.append(
            "lane_intents require disjoint owned_files: " + ", ".join(overlap)
        )
    declared_file_set = set(
        _runtime_context_public_file_values(declared_files)
    )
    actual_file_set = set(all_lane_files)
    missing_files = sorted(declared_file_set - actual_file_set)
    extra_files = sorted(actual_file_set - declared_file_set)
    if missing_files:
        errors.append(
            "lane_intents owned_files union is missing: "
            + ", ".join(missing_files)
        )
    if extra_files:
        errors.append(
            "lane_intents owned_files union contains extra files: "
            + ", ".join(extra_files)
        )
    if errors:
        raise ValidationError(
            "mf_parallel lane_intents do not conform to the frozen row scope",
            {
                "field": "metadata.lane_intents",
                "errors": list(dict.fromkeys(errors)),
                "required_worker_count": required_worker_count,
                "row_declared_files": sorted(declared_file_set),
                "writes_performed": False,
                "mutation_performed": False,
            },
        )

    route_binding = deepcopy(dict(parent_route_binding))
    route_binding_hash = str(route_binding.get("binding_hash") or "").strip()
    unsigned_route_binding = {
        key: value
        for key, value in route_binding.items()
        if key != "binding_hash"
    }
    if not (
        route_binding.get("schema_version")
        == "mf_parallel.parent_route_binding.v1"
        and str(route_binding.get("route_token_ref") or "").strip()
        and isinstance(route_binding.get("route_identity"), Mapping)
        and all(
            str(route_binding["route_identity"].get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        )
        and route_binding_hash == stable_sha256(unsigned_route_binding)
    ):
        raise ValidationError(
            "mf_parallel rev10 prefill requires the admitted parent route binding",
            {
                "project_id": project_id,
                "backlog_id": backlog_id,
                "contract_execution_id": contract_execution_id,
                "writes_performed": False,
                "mutation_performed": False,
            },
        )
    # A self-consistent hash is not sufficient route authority.  Prove that
    # the frozen parent identity is consumable by the existing child-route
    # lineage Gate before it can become an immutable prefill Fact.
    from . import observer_route_context as _observer_route_context

    try:
        _observer_route_context.build_parent_route_lineage(
            route_binding["route_identity"],
            project_id=project_id,
            backlog_id=backlog_id,
        )
    except ValueError as exc:
        raise ValidationError(
            "mf_parallel rev10 prefill requires a canonical parent route identity",
            {
                "project_id": project_id,
                "backlog_id": backlog_id,
                "contract_execution_id": contract_execution_id,
                "route_identity_error": str(exc),
                "writes_performed": False,
                "mutation_performed": False,
            },
        ) from exc

    plan = {
        "schema_version": _MF_PARALLEL_PREFILL_CHILD_PLAN_SCHEMA,
        "source": str(source or "").strip(),
        "server_canonicalized": True,
        "project_id": str(project_id or "").strip(),
        "backlog_id": str(backlog_id or "").strip(),
        "contract_execution_id": str(contract_execution_id or "").strip(),
        "parent_contract_execution_id": str(
            parent_contract_execution_id or ""
        ).strip(),
        "root_contract_execution_id": str(
            root_contract_execution_id or ""
        ).strip(),
        "required_worker_count": required_worker_count,
        "worker_count_policy": "exactly",
        "atomic_dispatch_required": required_worker_count > 1,
        "row_owned_files": sorted(declared_file_set),
        "row_test_files": sorted(test_file_set),
        "acceptance_criteria": deepcopy(list(acceptance_criteria)),
        "acceptance_scope_closure": deepcopy(dict(acceptance_scope_closure)),
        "parent_route_binding": route_binding,
        "test_command_authority": command_authority,
        "test_commands": list(test_commands),
        "lanes": normalized_lanes,
        "route_identity_materialized": False,
        "runtime_context_materialized": False,
        "worktree_materialized": False,
        "allocation_authority": "parallel_branch_allocate_precheck",
        "caller_materialization_authority_allowed": False,
    }
    plan["plan_hash"] = stable_sha256(plan)
    return plan


def _contract_runtime_mf_parallel_prefill_payload(
    plan: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "schema_version": _MF_PARALLEL_PREFILL_PAYLOAD_SCHEMA,
        "child_plan": deepcopy(dict(plan)),
        "child_plan_hash": str(plan.get("plan_hash") or "").strip(),
    }


def _contract_runtime_mf_parallel_prefill_plan_valid(
    record: Mapping[str, Any],
    plan: Mapping[str, Any],
) -> bool:
    if not isinstance(plan, Mapping):
        return False
    write = {
        "stage_id": "orchestration",
        "line_id": "observer_prefill_child_contracts",
        "evidence_kind": "contract_binding",
        "payload": _contract_runtime_mf_parallel_prefill_payload(plan),
    }
    return not _contract_runtime_mf_parallel_prefill_plan_write_errors(
        record,
        write,
    )


def _contract_runtime_mf_parallel_admitted_prefill_child_plan(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Return the exact typed plan only after its prefill Fact was admitted."""

    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    plan = (
        metadata.get("observer_prefill_child_plan")
        if isinstance(metadata.get("observer_prefill_child_plan"), Mapping)
        else {}
    )
    if not (
        metadata.get("observer_prefill_child_plan_required") is True
        and _contract_runtime_mf_parallel_prefill_plan_valid(record, plan)
    ):
        return {}
    expected_payload = _contract_runtime_mf_parallel_prefill_payload(plan)
    for line in record.get("completed_lines") or []:
        if not isinstance(line, Mapping):
            continue
        if (
            str(line.get("stage_id") or "").strip() == "orchestration"
            and str(line.get("line_id") or "").strip()
            == "observer_prefill_child_contracts"
            and str(line.get("evidence_kind") or "").strip()
            == "contract_binding"
            and isinstance(line.get("payload"), Mapping)
            and stable_sha256(dict(line["payload"]))
            == stable_sha256(expected_payload)
        ):
            return deepcopy(dict(plan))
    return {}


def _contract_runtime_mf_parallel_prefill_lane_mismatches(
    plan: Mapping[str, Any],
    lanes: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Compare only semantic lane custody; materialization stays downstream."""

    expected_lanes = [
        lane for lane in plan.get("lanes") or [] if isinstance(lane, Mapping)
    ]
    mismatches: list[dict[str, Any]] = []
    if len(lanes) != len(expected_lanes):
        return [
            {
                "field": "lane_count",
                "expected": len(expected_lanes),
                "actual": len(lanes),
            }
        ]
    for index, (expected, actual) in enumerate(
        zip(expected_lanes, lanes, strict=True)
    ):
        for field in ("task_id", "worker_id", "worker_slot_id"):
            expected_value = str(expected.get(field) or "").strip()
            actual_value = str(actual.get(field) or "").strip()
            if actual_value != expected_value:
                mismatches.append(
                    {
                        "lane_index": index,
                        "field": field,
                        "expected": expected_value,
                        "actual": actual_value,
                    }
                )
        for field in ("owned_files", "test_files"):
            expected_values = sorted(
                _runtime_context_public_file_values(expected.get(field) or [])
            )
            actual_values = sorted(
                _runtime_context_public_file_values(actual.get(field) or [])
            )
            if actual_values != expected_values:
                mismatches.append(
                    {
                        "lane_index": index,
                        "field": field,
                        "expected": expected_values,
                        "actual": actual_values,
                    }
                )
        expected_commands = _runtime_context_service_query_values(
            expected,
            "test_commands",
        )
        actual_commands = _runtime_context_service_query_values(
            actual,
            "test_commands",
        )
        if actual_commands != expected_commands:
            mismatches.append(
                {
                    "lane_index": index,
                    "field": "test_commands",
                    "expected": expected_commands,
                    "actual": actual_commands,
                }
            )
    return mismatches


def _contract_runtime_apply_mf_parallel_prefill_plan_projection(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Project only an admitted enter plan into prefill and dispatch Guides."""

    projected = deepcopy(dict(record))
    if (
        not _is_mf_parallel_record_contract_id(
            str(record.get("contract_id") or "")
        )
        or str(record.get("revision") or "").strip() != "rev10"
    ):
        return projected
    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    if metadata.get("observer_prefill_child_plan_required") is not True:
        return projected
    guide = (
        projected.get("runtime_guide")
        if isinstance(projected.get("runtime_guide"), dict)
        else {}
    )
    next_action = (
        guide.get("next_legal_action")
        if isinstance(guide.get("next_legal_action"), dict)
        else {}
    )
    line_id = str(next_action.get("line_id") or "").strip()
    if line_id not in {
        "observer_prefill_child_contracts",
        "observer_dispatch_bounded_workers",
    }:
        return projected
    plan = (
        metadata.get("observer_prefill_child_plan")
        if isinstance(metadata.get("observer_prefill_child_plan"), Mapping)
        else {}
    )
    plan_source = str(
        plan.get("source")
        or metadata.get("observer_prefill_child_plan_source")
        or "ContractRuntime.metadata.observer_prefill_child_plan"
    ).strip()
    plan_valid = _contract_runtime_mf_parallel_prefill_plan_valid(
        record,
        plan,
    )
    safe_copy = (
        guide.get("writer_role_safe_copy_payload")
        if isinstance(guide.get("writer_role_safe_copy_payload"), dict)
        else {}
    )
    if line_id == "observer_prefill_child_contracts":
        if not plan_valid or not safe_copy:
            guide.pop("writer_role_safe_copy_payload", None)
            next_action.pop("writer_role_safe_copy_payload", None)
            next_action.update(
                {
                    "status": "blocked_missing_prefill_child_plan",
                    "actionable": False,
                    "block_reason": (
                        "rev10 prefill requires the typed child plan admitted "
                        "by mf_parallel_enter"
                    ),
                }
            )
            guide["prefill_child_plan_projection"] = {
                "schema_version": "mf_parallel.prefill_child_plan_projection.v1",
                "status": "blocked_missing_admitted_plan",
                "source_of_authority": plan_source,
                "authorizes_write": False,
            }
        else:
            copy_payload = dict(safe_copy.get("copy_payload") or {})
            copy_payload["payload"] = _contract_runtime_mf_parallel_prefill_payload(
                plan
            )
            safe_copy["copy_payload"] = copy_payload
            guide["writer_role_safe_copy_payload"] = safe_copy
            next_action["writer_role_safe_copy_payload"] = deepcopy(safe_copy)
            next_action["actionable"] = True
            guide["prefill_child_plan_projection"] = {
                "schema_version": "mf_parallel.prefill_child_plan_projection.v1",
                "status": "ready",
                "source_of_authority": plan_source,
                "plan_hash": str(plan.get("plan_hash") or ""),
                "required_worker_count": int(
                    plan.get("required_worker_count") or 0
                ),
                "authorizes_write": True,
            }
    else:
        accepted_payload: Mapping[str, Any] = {}
        completed_lines = record.get("completed_lines")
        if not isinstance(completed_lines, list):
            completed_lines = guide.get("completed_lines")
        for line in completed_lines or []:
            if not isinstance(line, Mapping):
                continue
            if (
                str(line.get("stage_id") or "").strip() == "orchestration"
                and str(line.get("line_id") or "").strip()
                == "observer_prefill_child_contracts"
                and str(line.get("evidence_kind") or "").strip()
                == "contract_binding"
                and isinstance(line.get("payload"), Mapping)
            ):
                accepted_payload = line["payload"]
                break
        expected_payload = (
            _contract_runtime_mf_parallel_prefill_payload(plan)
            if plan_valid
            else {}
        )
        admitted = bool(
            expected_payload
            and stable_sha256(dict(accepted_payload))
            == stable_sha256(expected_payload)
        )
        if not admitted:
            guide.pop("writer_role_safe_copy_payload", None)
            next_action.pop("writer_role_safe_copy_payload", None)
            next_action.update(
                {
                    "status": "blocked_missing_admitted_prefill_child_plan",
                    "actionable": False,
                    "block_reason": (
                        "dispatch cannot synthesize a child plan absent from "
                        "the accepted prefill Fact"
                    ),
                }
            )
            guide["prefill_child_plan_projection"] = {
                "schema_version": "mf_parallel.prefill_child_plan_projection.v1",
                "status": "blocked_missing_admitted_plan",
                "source_of_authority": (
                    "completed_lines.observer_prefill_child_contracts"
                ),
                "authorizes_write": False,
            }
        else:
            bounded_workers = [
                {
                    "task_id": str(lane.get("task_id") or "").strip(),
                    "worker_id": str(lane.get("worker_id") or "").strip(),
                    "worker_slot_id": str(
                        lane.get("worker_slot_id") or ""
                    ).strip(),
                    "owned_files": list(lane.get("owned_files") or []),
                    "target_files": list(lane.get("owned_files") or []),
                    "test_files": list(lane.get("test_files") or []),
                    "test_commands": list(lane.get("test_commands") or []),
                }
                for lane in plan.get("lanes") or []
                if isinstance(lane, Mapping)
            ]
            parent_route_binding = (
                plan.get("parent_route_binding")
                if isinstance(plan.get("parent_route_binding"), Mapping)
                else {}
            )
            parent_route_identity = (
                parent_route_binding.get("route_identity")
                if isinstance(
                    parent_route_binding.get("route_identity"), Mapping
                )
                else {}
            )
            next_action.update(
                {
                    "bounded_workers": bounded_workers,
                    "worker_count": len(bounded_workers),
                    "required_worker_count": int(
                        plan.get("required_worker_count") or 0
                    ),
                    "atomic_dispatch": bool(
                        plan.get("atomic_dispatch_required") is True
                    ),
                    "source_of_authority": (
                        "completed_lines.observer_prefill_child_contracts"
                    ),
                    **{
                        field: str(parent_route_identity.get(field) or "").strip()
                        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
                    },
                }
            )
            guide["prefill_child_plan_projection"] = {
                "schema_version": "mf_parallel.prefill_child_plan_projection.v1",
                "status": "admitted_plan_projected",
                "source_of_authority": (
                    "completed_lines.observer_prefill_child_contracts"
                ),
                "plan_hash": str(plan.get("plan_hash") or ""),
                "required_worker_count": len(bounded_workers),
                "authorizes_allocation_recipe": True,
            }
    guide["next_legal_action"] = next_action
    projected["runtime_guide"] = guide
    return projected


def _contract_runtime_mf_parallel_prefill_plan_write_errors(
    record: Mapping[str, Any],
    write: Mapping[str, Any],
) -> list[str]:
    return mf_parallel_prefill_child_plan_errors(record, record, write)


def _contract_runtime_mf_parallel_current_generation_worker_count(
    record: Mapping[str, Any],
    *,
    conn=None,
    project_id: str = "",
) -> int:
    """Return cardinality for the dispatch generation that owns merge/QA.

    Rev9 keeps the initial standalone fan-out at two workers, but an accepted
    QA NO-PASS appends one server-bound ``failed_qa_rework`` dispatch to the
    same execution.  Post-merge authority must therefore follow that verified
    replacement generation instead of reusing the frozen initial cardinality.
    """

    initial_count = _contract_runtime_mf_parallel_required_worker_count(
        record,
        conn=conn,
        project_id=project_id,
    )
    if str(record.get("revision") or "").strip() != "rev9":
        return initial_count
    selected = _contract_runtime_current_dispatch_authority_line(record)
    if selected.get("status") != "selected":
        return initial_count
    if _contract_runtime_mf_parallel_verified_rework_dispatch_worker(
        record,
        selected,
    ):
        return 1
    return initial_count


def _contract_runtime_mf_parallel_verified_rework_dispatch_worker(
    record: Mapping[str, Any],
    selected: Mapping[str, Any],
) -> dict[str, Any]:
    """Project one server-bound rev9 rework dispatch as a worker lane."""

    if (
        str(record.get("revision") or "").strip() != "rev9"
        or selected.get("status") != "selected"
    ):
        return {}
    payload = (
        selected.get("payload")
        if isinstance(selected.get("payload"), Mapping)
        else {}
    )
    revision = (
        payload.get("failed_qa_rework_dispatch_revision")
        if isinstance(
            payload.get("failed_qa_rework_dispatch_revision"), Mapping
        )
        else {}
    )
    authority = (
        payload.get("failed_qa_rework_dispatch_revision_authority")
        if isinstance(
            payload.get("failed_qa_rework_dispatch_revision_authority"),
            Mapping,
        )
        else {}
    )
    if (
        revision.get("append_only_history_preserved") is True
        and revision.get("timeline_projection_authoritative") is False
        and authority.get("server_derived") is True
        and str(authority.get("source") or "").strip()
        == "parallel_branch_allocate_failed_qa_rework"
        and str(authority.get("contract_execution_id") or "").strip()
        == str(record.get("contract_execution_id") or "").strip()
    ):
        workers = _contract_runtime_mf_parallel_bounded_workers(
            {"payload": payload}
        )
        if len(workers) == 1:
            return dict(workers[0])
        if all(
            str(payload.get(field) or "").strip()
            for field in (
                "runtime_context_id",
                "task_id",
                "parent_task_id",
                "merge_queue_id",
            )
        ):
            return dict(payload)
    return {}


def _contract_runtime_mf_parallel_worker_cardinality_policy(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    required_worker_count = _contract_runtime_mf_parallel_required_worker_count(
        record,
        conn=conn,
        project_id=project_id,
    )
    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    selection = (
        metadata.get("observer_worker_cardinality_selection")
        if isinstance(
            metadata.get("observer_worker_cardinality_selection"), Mapping
        )
        else {}
    )
    declared_batch_child = bool(
        _is_mf_parallel_postmerge_revision(record)
        and _parallel_branch_allocate_declares_batch_child(record)
    )
    verified_batch_child = bool(
        declared_batch_child
        and _parallel_branch_allocate_verified_batch_child_lineage_authority(
            conn,
            project_id=project_id,
            record=record,
        )
    )
    revisions = (
        metadata.get("observer_worker_cardinality_revisions")
        if isinstance(
            metadata.get("observer_worker_cardinality_revisions"), list
        )
        else []
    )
    latest_revision = next(
        (
            item
            for item in reversed(revisions)
            if isinstance(item, Mapping)
        ),
        {},
    )
    strict_prefill_topology = bool(
        str(record.get("revision") or "").strip() == "rev10"
        and metadata.get("observer_prefill_child_plan_required") is True
    )
    return {
        "schema_version": "mf_parallel.effective_worker_cardinality_policy.v1",
        "source": (
            "verified_batch_child_lineage"
            if verified_batch_child
            else (
                "declared_batch_child_authority_missing"
                if declared_batch_child
                else (
                    "observer_selected_standalone_cardinality"
                    if selection.get("observer_selected") is True
                    else "legacy_implicit_cardinality_compatibility"
                )
            )
        ),
        "required_worker_count": required_worker_count,
        "worker_count_policy": "exactly",
        "atomic_dispatch_required": required_worker_count > 1,
        "batch_row_scoped_successor": declared_batch_child,
        "batch_child_lineage_verified": verified_batch_child,
        "standalone_mf_parallel_policy_unchanged": True,
        "caller_override_allowed": False,
        "fresh_mcp_contract_requires_explicit_selection": True,
        "legacy_implicit_compatibility": (
            selection.get("observer_selected") is not True
        ),
        "observer_selection_origin": str(
            selection.get("selection_origin") or "pinned_contract_definition"
        ),
        "selection_hash": str(selection.get("selection_hash") or ""),
        "latest_revision_id": str(latest_revision.get("revision_id") or ""),
        "revision_contract": ({
            "status": "immutable_prefill_topology",
            "actionable": False,
            "source": "mf_parallel.v2.rev10.observer_prefill_child_plan",
            "required_worker_count": required_worker_count,
            "fresh_successor_required_for_topology_change": True,
            "facade_projected": False,
        } if strict_prefill_topology else {
            "interface": "mf_parallel_revise",
            "facade": "mf_parallel_revise",
            "mcp_tool": "mf_parallel_revise",
            "method": "POST",
            "path": (
                "/api/projects/{project_id}/mf-parallel/"
                "{contract_execution_id}/revise"
            ),
            "observer_only": True,
            "body_source": "copy_safe_body",
            "copy_safe_body": {
                "project_id": project_id,
                "backlog_id": str(record.get("backlog_id") or "").strip(),
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ).strip(),
                "required_worker_count": (
                    1
                    if verified_batch_child
                    else (1 if required_worker_count == 2 else 2)
                ),
                "reason": "<observer reason for cardinality revision>",
                "observer_session_id": "<active observer session id>",
                "observer_route_token_ref": "<current child route token ref>",
            },
            "host_realization": {
                "mode": "replace_declared_placeholders_then_spread_to_mcp",
                "adapter_fields_included": ["project_id"],
                "required_replacements": [
                    "reason",
                    "observer_session_id",
                    "observer_route_token_ref",
                ],
                "optional_omission_fields": ["route_token_ref"],
                "required_worker_count_location": "top_level",
            },
            "allowed_before": "first_runtime_context_allocation_or_dispatch",
            "ordinary_reenter_change_allowed": False,
            "accepted_revisions_append_only": True,
            "batch_child_two_worker_revision_supported": False,
            "batch_parallelism_expansion": (
                "add_independent_batch_rows_not_nested_child_workers"
            ),
        }),
    }


def _contract_runtime_mf_parallel_bounded_workers(
    value: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Read one atomic dispatch's lane payloads without inventing identities."""

    payload = (
        value.get("payload")
        if isinstance(value.get("payload"), Mapping)
        else value
    )
    workers = payload.get("bounded_workers")
    if not isinstance(workers, list):
        return []
    return [dict(worker) for worker in workers if isinstance(worker, Mapping)]


def _contract_runtime_is_policy_bound_mf_parallel_dispatch(
    record: Mapping[str, Any],
    write: Mapping[str, Any],
) -> bool:
    policy = (
        _contract_update_dispatch_authority_policy(record)
        or _contract_runtime_mf_parallel_dispatch_authority_policy(record)
    )
    line_ids = {
        str(value or "").strip()
        for value in policy.get("line_ids") or []
        if str(value or "").strip()
    }
    return bool(
        policy
        and str(write.get("stage_id") or "").strip() == "dispatch"
        and str(write.get("line_id") or "").strip()
        == "observer_dispatch_bounded_workers"
        and (
            not line_ids
            or str(write.get("line_id") or "").strip() in line_ids
        )
        and str(write.get("evidence_kind") or "").strip()
        == "dispatch_bounded_worker"
    )


def _contract_runtime_bind_mf_parallel_dispatch_authority(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    _required_worker_count_override: int | None = None,
) -> tuple[dict[str, Any], list[str]]:
    """Bind a policy-enabled dispatch to persisted worker and route authority."""

    effective = dict(write)
    if not _contract_runtime_is_policy_bound_mf_parallel_dispatch(
        record, effective
    ):
        return effective, []
    contract_update_authority = (
        _contract_update_rev2_dispatch_allocation_authority(record)
    )
    authority_policy = (
        _contract_update_dispatch_authority_policy(record)
        if contract_update_authority
        else _contract_runtime_mf_parallel_dispatch_authority_policy(record)
    )
    required_dispatch_fields = {
        str(value or "").strip()
        for value in authority_policy.get("required_dispatch_fields") or []
        if str(value or "").strip()
    }
    required_child_route_fields = {
        str(value or "").strip()
        for value in authority_policy.get("required_child_route_fields") or []
        if str(value or "").strip()
    }

    payload = (
        dict(effective.get("payload"))
        if isinstance(effective.get("payload"), Mapping)
        else {}
    )
    required_worker_count = (
        int(_required_worker_count_override)
        if _required_worker_count_override is not None
        else _contract_runtime_mf_parallel_required_worker_count(
            record,
            conn=conn,
            project_id=project_id,
        )
    )
    raw_bounded_workers = payload.get("bounded_workers")
    if (
        required_worker_count > 1
        and _required_worker_count_override is None
    ):
        if (
            not isinstance(raw_bounded_workers, list)
            or len(raw_bounded_workers) != required_worker_count
            or any(
                not isinstance(worker, Mapping)
                for worker in raw_bounded_workers
            )
        ):
            return effective, [
                "mf_parallel policy-bound dispatch must atomically identify "
                f"exactly {required_worker_count} bounded workers"
            ]

        lane_authority_fields = {
            *required_dispatch_fields,
            *required_child_route_fields,
            "runtime_context_id",
            "task_id",
            "worker_task_id",
            "parent_task_id",
            "worker_id",
            "worker_slot_id",
            "worker_role",
            "role",
            "target_project_root",
            "project_root",
            "repo_root",
            "worktree_path",
            "worker_worktree_path",
            "assigned_worktree",
            "branch_ref",
            "branch",
            "base_commit",
            "target_head_commit",
            "merge_queue_id",
            "route_identity",
            "child_route_lineage",
        }
        canonical_workers: list[dict[str, Any]] = []
        lane_errors: list[str] = []
        for index, worker in enumerate(raw_bounded_workers, start=1):
            lane_payload = dict(worker)
            lane_payload["bounded_workers"] = [dict(worker)]
            lane_write = {
                key: value
                for key, value in effective.items()
                if key not in lane_authority_fields and key != "payload"
            }
            lane_write.update(dict(worker))
            lane_write["payload"] = lane_payload
            bound_lane, errors = (
                _contract_runtime_bind_mf_parallel_dispatch_authority(
                    conn,
                    project_id=project_id,
                    record=record,
                    write=lane_write,
                    _required_worker_count_override=1,
                )
            )
            if errors:
                lane_errors.extend(
                    f"bounded worker {index}: {error}" for error in errors
                )
                continue
            bound_payload = (
                bound_lane.get("payload")
                if isinstance(bound_lane.get("payload"), Mapping)
                else {}
            )
            bound_workers = bound_payload.get("bounded_workers")
            if (
                not isinstance(bound_workers, list)
                or len(bound_workers) != 1
                or not isinstance(bound_workers[0], Mapping)
            ):
                lane_errors.append(
                    f"bounded worker {index}: canonical lane binding missing"
                )
                continue
            canonical_worker = dict(bound_workers[0])
            canonical_worker["line_instance_id"] = (
                "runtime_context:"
                + str(canonical_worker.get("runtime_context_id") or "")
            )
            canonical_lane_files = _runtime_context_service_query_values(
                canonical_worker,
                "owned_files",
            )
            canonical_worker["owned_files"] = canonical_lane_files
            canonical_worker["target_files"] = canonical_lane_files
            canonical_workers.append(canonical_worker)
        if lane_errors:
            return effective, list(dict.fromkeys(lane_errors))

        distinct_fields = [
            str(field or "").strip()
            for field in authority_policy.get("distinct_identity_fields") or []
            if str(field or "").strip()
        ]
        if not distinct_fields:
            distinct_fields = [
                "runtime_context_id",
                "task_id",
                "worker_id",
                "worker_slot_id",
                "worktree_path",
                "branch_ref",
                "merge_queue_id",
            ]
        if "route_token_ref" not in distinct_fields:
            distinct_fields.append("route_token_ref")

        owned_by_worker = [
            set(_runtime_context_service_query_values(worker, "owned_files"))
            for worker in canonical_workers
        ]
        lane_errors.extend(
            _contract_runtime_mf_parallel_atomic_lane_errors(
                canonical_workers,
                distinct_fields=distinct_fields,
            )
        )
        if lane_errors:
            return effective, list(dict.fromkeys(lane_errors))

        (
            acceptance_scope_criteria,
            acceptance_scope_closure,
            acceptance_errors,
        ) = _contract_runtime_mf_parallel_rev8_atomic_acceptance_gate(
            conn,
            project_id=project_id,
            record=record,
            lane_owned_files=[sorted(files) for files in owned_by_worker],
            acceptance_claim_source=effective,
        )
        if acceptance_errors:
            return effective, acceptance_errors
        for canonical_worker in canonical_workers:
            canonical_worker["acceptance_criteria"] = list(
                acceptance_scope_criteria
            )
            canonical_worker["acceptance_scope_closure"] = dict(
                acceptance_scope_closure
            )

        canonical_workers.sort(
            key=lambda worker: (
                str(worker.get("task_id") or ""),
                str(worker.get("runtime_context_id") or ""),
            )
        )
        aggregate_payload = {
            key: value
            for key, value in payload.items()
            if key not in lane_authority_fields
            and key != "bounded_workers"
        }
        aggregate_payload.update(
            {
                "schema_version": (
                    "mf_parallel.atomic_two_worker_dispatch.v1"
                ),
                "bounded_workers": canonical_workers,
                "worker_count": len(canonical_workers),
                "required_worker_count": required_worker_count,
                "atomic_dispatch": True,
                "all_or_nothing": True,
                "owned_files": sorted(
                    set().union(*owned_by_worker)
                    if owned_by_worker
                    else set()
                ),
                "target_files": sorted(
                    set().union(*owned_by_worker)
                    if owned_by_worker
                    else set()
                ),
                "acceptance_criteria": list(acceptance_scope_criteria),
                "acceptance_scope_closure": dict(
                    acceptance_scope_closure
                ),
                "dispatch_ticket_authority": {
                    "schema_version": (
                        "mf_parallel.atomic_dispatch_ticket_authority.v1"
                    ),
                    "source": "observer_route_token_refs",
                    "server_resolved_child_route_identity": True,
                    "runtime_context_bound": True,
                    "all_workers_bound": True,
                    "atomic_dispatch": True,
                    "required_worker_count": required_worker_count,
                    "observer_impersonation_explicit": True,
                },
                "observer_impersonation": False,
            }
        )
        effective["bounded_workers"] = canonical_workers
        effective["worker_count"] = len(canonical_workers)
        effective["atomic_dispatch"] = True
        effective["observer_impersonation"] = False
        effective["payload"] = aggregate_payload
        return effective, []

    errors: list[str] = []
    bounded_worker: dict[str, Any] = {}
    bounded_workers = raw_bounded_workers
    if bounded_workers is not None:
        if (
            not isinstance(bounded_workers, list)
            or len(bounded_workers) != required_worker_count
            or not isinstance(bounded_workers[0], Mapping)
        ):
            errors.append(
                "mf_parallel policy-bound dispatch must identify exactly "
                f"{required_worker_count} bounded worker"
            )
        else:
            bounded_worker = dict(bounded_workers[0])
    sources = tuple(
        source for source in (effective, payload, bounded_worker) if source
    )

    def supplied_text(field: str, *aliases: str) -> str:
        values = {
            str(source.get(key) or "").strip()
            for source in sources
            for key in (field, *aliases)
            if str(source.get(key) or "").strip()
        }
        if len(values) > 1:
            errors.append(f"dispatch contains conflicting {field} values")
            return ""
        return next(iter(values)) if values else ""

    runtime_context_id = supplied_text("runtime_context_id")
    task_claims = [
        (
            source_name,
            key,
            str(source.get(key) or "").strip(),
        )
        for source_name, source in (
            ("write", effective),
            ("payload", payload),
            ("bounded_worker", bounded_worker),
        )
        if source
        for key in ("task_id", "worker_task_id")
        if str(source.get(key) or "").strip()
    ]
    task_id = ""
    parent_task_id = supplied_text("parent_task_id")
    worker_id = supplied_text("worker_id")
    worker_slot_id = supplied_text("worker_slot_id")
    supplied_observer_command_id = supplied_text("observer_command_id")
    observer_command_id = supplied_observer_command_id or str(
        record.get("contract_execution_id") or ""
    ).strip()
    worker_role = supplied_text("worker_role", "role")
    target_project_root = supplied_text(
        "target_project_root", "project_root", "repo_root"
    )
    worktree_path = supplied_text(
        "worktree_path", "worker_worktree_path", "assigned_worktree"
    )
    branch_ref = supplied_text("branch_ref", "branch")
    base_commit = supplied_text("base_commit")
    target_head_commit = supplied_text("target_head_commit")
    merge_queue_id = supplied_text("merge_queue_id")

    required_text = {
        "runtime_context_id": runtime_context_id,
        "parent_task_id": parent_task_id,
        "worker_id": worker_id,
        "worker_slot_id": worker_slot_id,
        "observer_command_id": observer_command_id,
        "worker_role": worker_role,
        "target_project_root": target_project_root,
        "worktree_path": worktree_path,
        "branch_ref": branch_ref,
        "base_commit": base_commit,
        "target_head_commit": target_head_commit,
        "merge_queue_id": merge_queue_id,
    }
    missing = [
        field
        for field, value in required_text.items()
        if field in required_dispatch_fields and not value
    ]

    owned_sources = [
        tuple(
            sorted(
                set(
                    _runtime_context_service_query_values(
                        source,
                        "owned_files",
                        "target_files",
                    )
                )
            )
        )
        for source in sources
        if _runtime_context_service_query_values(
            source,
            "owned_files",
            "target_files",
        )
    ]
    if len(set(owned_sources)) > 1:
        errors.append("dispatch contains conflicting owned_files values")
    owned_files = list(owned_sources[0]) if owned_sources else []
    if "owned_files" in required_dispatch_fields and not owned_files:
        missing.append("owned_files")

    def supplied_mapping(field: str) -> dict[str, Any]:
        values = [
            dict(source[field])
            for source in sources
            if isinstance(source.get(field), Mapping) and source.get(field)
        ]
        if any(value != values[0] for value in values[1:]):
            errors.append(f"dispatch contains conflicting {field} values")
        return values[0] if values else {}

    profile_requirements = supplied_mapping("profile_requirements")
    retry_policy = supplied_mapping("retry_policy")
    if (
        "profile_requirements" in required_dispatch_fields
        and not profile_requirements
    ):
        missing.append("profile_requirements")
    if "retry_policy" in required_dispatch_fields and not retry_policy:
        missing.append("retry_policy")
    if missing:
        errors.append(
            "mf_parallel policy-bound dispatch is missing required authority: "
            + ", ".join(sorted(set(missing)))
        )

    context = None
    if runtime_context_id:
        from .parallel_branch_runtime import get_branch_context_by_runtime_context_id

        context = get_branch_context_by_runtime_context_id(
            conn,
            project_id,
            runtime_context_id,
        )
    if context is None:
        errors.append(
            "mf_parallel policy-bound dispatch requires a persisted runtime context"
        )
    else:
        canonical_task_id = str(getattr(context, "task_id", "") or "").strip()
        contract_task_id = str(record.get("contract_execution_id") or "").strip()
        for source_name, key, claimed_task_id in task_claims:
            if claimed_task_id == canonical_task_id:
                continue
            if (
                source_name in {"write", "payload"}
                and key == "task_id"
                and claimed_task_id == contract_task_id
            ):
                continue
            errors.append(
                "dispatch task_id does not match persisted runtime context"
            )
        if not canonical_task_id:
            errors.append("persisted runtime context is missing task_id")
        task_id = canonical_task_id
        required_text["task_id"] = task_id
        canonical_worker_id = str(
            getattr(context, "worker_id", "")
            or getattr(context, "worker_slot_id", "")
            or ""
        ).strip()
        canonical_worker_slot_id = str(
            getattr(context, "worker_slot_id", "")
            or getattr(context, "worker_id", "")
            or ""
        ).strip()
        expected = {
            "runtime_context_id": str(
                getattr(context, "runtime_context_id", "") or ""
            ).strip(),
            "task_id": str(getattr(context, "task_id", "") or "").strip(),
            "parent_task_id": _runtime_context_mf_sub_parent_task_id(context),
            "worker_id": canonical_worker_id,
            "worker_slot_id": canonical_worker_slot_id,
            "worker_role": "mf_sub",
            "target_project_root": str(
                getattr(context, "target_project_root", "") or ""
            ).strip(),
            "worktree_path": str(
                getattr(context, "worktree_path", "") or ""
            ).strip(),
            "branch_ref": str(getattr(context, "branch_ref", "") or "").strip(),
            "base_commit": str(getattr(context, "base_commit", "") or "").strip(),
            "target_head_commit": str(
                getattr(context, "target_head_commit", "") or ""
            ).strip(),
            "merge_queue_id": str(
                getattr(context, "merge_queue_id", "") or ""
            ).strip(),
        }
        for field, actual in required_text.items():
            if field == "observer_command_id":
                continue
            canonical = expected.get(field, "")
            if not canonical:
                errors.append(f"persisted runtime context is missing {field}")
            elif actual and actual != canonical:
                errors.append(
                    f"dispatch {field} does not match persisted runtime context"
                )
        canonical_owned_files = sorted(
            set(
                getattr(context, "owned_files", ())
                or getattr(context, "target_files", ())
                or ()
            )
        )
        if not canonical_owned_files:
            errors.append("persisted runtime context is missing owned_files")
        elif owned_files and owned_files != canonical_owned_files:
            errors.append("dispatch owned_files do not match persisted runtime context")
        if contract_update_authority:
            revision = _runtime_context_latest_contract_revision_payload(
                conn,
                context,
            )
            revision_body = (
                revision.get("payload")
                if isinstance(revision.get("payload"), Mapping)
                else {}
            )
            anchor = _runtime_context_contract_update_allocation_identity_anchor(
                conn,
                project_id=project_id,
                context=context,
                runtime_context_id=runtime_context_id,
                contract_execution_id=str(
                    record.get("contract_execution_id") or ""
                ),
                contract_record=record,
            )
            expected_dispatch_authority = (
                _contract_update_accepted_dispatch_authority(
                    record,
                    anchor,
                    revision_body,
                )
            )
            supplied_dispatch_authority = supplied_mapping(
                "accepted_dispatch_authority"
            )
            if (
                not expected_dispatch_authority
                or supplied_dispatch_authority != expected_dispatch_authority
            ):
                errors.append(
                    "contract_update dispatch requires the exact accepted "
                    "allocation authority"
                )

    route_sources: list[Mapping[str, Any]] = list(sources)
    for source in sources:
        for field in ("route_identity", "child_route_lineage"):
            nested = source.get(field)
            if isinstance(nested, Mapping):
                route_sources.append(nested)

    def route_values(field: str) -> set[str]:
        return {
            str(source.get(field) or "").strip()
            for source in route_sources
            if str(source.get(field) or "").strip()
        }

    route_token_refs = route_values("route_token_ref")
    if len(route_token_refs) > 1:
        errors.append("dispatch route identity mixes parent and child route_token_ref")
    route_token_ref = next(iter(route_token_refs)) if route_token_refs else ""
    canonical_route_identity: dict[str, str] = {}
    if not route_token_ref:
        if required_child_route_fields:
            errors.append(
                "mf_parallel policy-bound dispatch is missing route_token_ref"
            )
    else:
        canonical_route_identity, append_route_diagnostic = (
            _contract_runtime_resolve_append_scoped_child_route(
                conn,
                project_id=project_id,
                backlog_id=str(record.get("backlog_id") or "").strip(),
                contract_execution_id=str(
                    record.get("contract_execution_id") or ""
                ).strip(),
                route_token_ref=route_token_ref,
                supplied_route_authority=effective,
            )
        )
        if not canonical_route_identity:
            if (
                append_route_diagnostic.get("status")
                == "blocked_route_action_scope"
            ):
                errors.append("dispatch route_token_ref is not append scoped")
            else:
                errors.append(
                    "dispatch child route identity failed append-scope "
                    "resolution: "
                    f"{append_route_diagnostic.get('field')} expected "
                    f"{append_route_diagnostic.get('expected')} actual "
                    f"{append_route_diagnostic.get('actual')}"
                )
        else:
            incomplete_route = [
                field
                for field in required_child_route_fields
                if not canonical_route_identity.get(field)
            ]
            if incomplete_route:
                errors.append(
                    "server-resolved child route identity is incomplete: "
                    + ", ".join(incomplete_route)
                )
            for field, canonical in canonical_route_identity.items():
                supplied = route_values(field)
                if len(supplied) > 1 or any(
                    value != canonical for value in supplied
                ):
                    errors.append(
                        "dispatch route identity mixes parent and child "
                        f"{field}"
                    )
        if (
            append_route_diagnostic.get("status")
            == "blocked_route_action_scope"
            and "dispatch route_token_ref is not append scoped" not in errors
        ):
            errors.append("dispatch route_token_ref is not append scoped")

    if errors:
        return effective, list(dict.fromkeys(errors))

    assert context is not None
    canonical_values = {
        "runtime_context_id": str(context.runtime_context_id),
        "task_id": str(context.task_id),
        "parent_task_id": _runtime_context_mf_sub_parent_task_id(context),
        "worker_id": str(context.worker_id or context.worker_slot_id),
        "worker_slot_id": str(context.worker_slot_id or context.worker_id),
        "worker_role": "mf_sub",
        "target_project_root": str(context.target_project_root),
        "worktree_path": str(context.worktree_path),
        "branch_ref": str(context.branch_ref),
        "base_commit": str(context.base_commit),
        "target_head_commit": str(context.target_head_commit),
        "merge_queue_id": str(context.merge_queue_id),
    }
    if supplied_observer_command_id:
        canonical_values["observer_command_id"] = observer_command_id
    for field, value in canonical_values.items():
        effective[field] = value
        payload[field] = value
    effective["owned_files"] = owned_files
    payload["owned_files"] = owned_files
    payload["profile_requirements"] = dict(profile_requirements)
    payload["retry_policy"] = dict(retry_policy)
    payload["route_identity"] = dict(canonical_route_identity)
    for field, value in canonical_route_identity.items():
        effective[field] = value
        payload[field] = value
    if bounded_worker:
        for field, value in canonical_values.items():
            bounded_worker[field] = value
        bounded_worker["owned_files"] = list(owned_files)
        bounded_worker["profile_requirements"] = dict(profile_requirements)
        bounded_worker["retry_policy"] = dict(retry_policy)
        bounded_worker["route_identity"] = dict(canonical_route_identity)
        for field, value in canonical_route_identity.items():
            bounded_worker[field] = value
        payload["bounded_workers"] = [bounded_worker]
    payload["dispatch_ticket_authority"] = {
        "schema_version": "mf_parallel.dispatch_ticket_authority.v1",
        "source": "observer_route_token_refs",
        "server_resolved_child_route_identity": True,
        "runtime_context_bound": True,
        "observer_impersonation_explicit": True,
    }
    payload["worker_count"] = required_worker_count
    payload["required_worker_count"] = required_worker_count
    payload["atomic_dispatch"] = False
    effective["observer_impersonation"] = False
    payload["observer_impersonation"] = False
    effective["payload"] = payload
    return effective, []


def _contract_runtime_unchanged_line_rejection(
    record: Mapping[str, Any],
    errors: Sequence[str],
) -> dict[str, Any]:
    guide = (
        record.get("runtime_guide")
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    state = (
        record.get("execution_state")
        if isinstance(record.get("execution_state"), Mapping)
        else {}
    )
    return {
        "ok": False,
        "record": dict(record),
        "decision": {
            "schema_version": "contract_write_gate_decision.v1",
            "ok": False,
            "errors": list(errors),
        },
        "completed_lines_count": len(record.get("completed_lines") or []),
        "execution_state_revision": int(
            record.get("execution_state_revision")
            or state.get("execution_state_revision")
            or 0
        ),
        "execution_state_hash": str(state.get("execution_state_hash") or ""),
        "runtime_guide_hash": str(guide.get("runtime_guide_hash") or ""),
    }


def _contract_runtime_finish_attestation_facade_only_rejection(
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    *,
    actor_role: str,
) -> dict[str, Any]:
    """Keep strict worker finish evidence out of the generic line facade."""

    if not (
        str(actor_role or "").strip() == "mf_sub"
        and str(record.get("contract_id") or "").strip()
        in {"mf_parallel", "mf_parallel.v2"}
    ):
        return {}
    requested_line = (
        str(write.get("stage_id") or "").strip(),
        str(write.get("line_id") or "").strip(),
        str(write.get("evidence_kind") or "").strip(),
    )
    required_facade = {
        (
            "worker_attestation",
            "worker_finish_time_attestation",
            "record_finish_time_worker_attestation",
        ): "runtime_context_finish_time_worker_attestation",
        (
            "worker_finish",
            "worker_finish_gate",
            "mf_subagent_finish_gate",
        ): "runtime_context_finish_gate",
    }.get(requested_line, "")
    if not required_facade:
        return {}
    line_id = requested_line[1]
    rejected = _contract_runtime_unchanged_line_rejection(
        record,
        [
            f"{line_id} requires {required_facade}"
        ],
    )
    rejected.update(
        {
            "generic_contract_runtime_submit_line_allowed": False,
            "required_facade": required_facade,
            "strict_worker_session_fence_binding_required": True,
            "completed_line_mutated": False,
        }
    )
    return rejected


_CONTRACT_RUNTIME_QA_NESTED_VERDICT_PATHS: tuple[tuple[str, ...], ...] = (
    ("verdict",),
    ("verification", "verdict"),
    ("verification", "status"),
    ("verification", "result"),
    ("test_results", "verdict"),
    ("test_results", "status"),
    ("payload", "verdict"),
    ("payload", "status"),
)


def _contract_runtime_qa_nested_passing_verdict(
    write: Mapping[str, Any],
) -> dict[str, str]:
    """Return the first nested QA verdict that records a passing result."""

    for path in _CONTRACT_RUNTIME_QA_NESTED_VERDICT_PATHS:
        node: Any = write
        for key in path:
            if not isinstance(node, Mapping):
                node = None
                break
            node = node.get(key)
        if not isinstance(node, str):
            continue
        text = node.strip().lower()
        if text in _CONTRACT_RUNTIME_QA_PASSING_STATUSES:
            return {"field": ".".join(path), "value": text}
    return {}


def _contract_runtime_qa_missing_status_rejection(
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    *,
    actor_role: str,
) -> dict[str, Any]:
    """Reject a passing QA verification that omits the top-level status.

    ``_enrich_qa_evidence_provenance`` derives ``completion_status_gate``
    from the top-level ``status`` field alone.  A ``qa_independent_
    verification`` line whose nested evidence records a passing verdict but
    which carries no top-level ``status`` is therefore accepted and then
    normalized into a *failing* completion gate, flipping the world into
    failed-QA rework without ever telling the author.  Fail loudly here,
    before any write, and name the exact remediation instead.

    Only the contradiction is rejected.  A QA line whose evidence genuinely
    does not pass carries no nested passing verdict, so it falls through and
    keeps failing exactly as before.
    """

    if (
        str(write.get("line_id") or "").strip()
        != "qa_independent_verification"
    ):
        return {}
    if (
        str(write.get("evidence_kind") or "").strip()
        != "independent_verification"
    ):
        return {}
    effective_role = (
        str(actor_role or "").strip()
        or str(write.get("actor_role") or "").strip()
    )
    if effective_role != "qa":
        return {}
    if str(write.get("status") or "").strip():
        return {}
    nested = _contract_runtime_qa_nested_passing_verdict(write)
    if not nested:
        return {}
    rejected = _contract_runtime_unchanged_line_rejection(
        record,
        [
            "qa_independent_verification records a passing "
            f"{nested['field']} but omits the top-level status field; "
            "the completion status gate is derived from the top-level "
            "status alone and would normalize this passing verification "
            "into a failing one"
        ],
    )
    rejected.update(
        {
            "missing_proof_fields": ["status"],
            "nested_passing_verdict_field": nested["field"],
            "nested_passing_verdict_value": nested["value"],
            "silent_failing_normalization_prevented": True,
            "completed_line_mutated": False,
            "zero_contract_runtime_write": True,
            "remediation": (
                "resubmit the same evidence with top-level "
                'status: "passed"'
            ),
            "next_legal_action": (
                "resubmit_qa_independent_verification_with_top_level_status"
            ),
        }
    )
    return rejected


_CONTRACT_RUNTIME_QA_REJECTION_RESPONSE_FIELDS = (
    "missing_proof_fields",
    "nested_passing_verdict_field",
    "nested_passing_verdict_value",
    "silent_failing_normalization_prevented",
    "qa_pass_write_compiler_parity_prevented",
    "completed_line_mutated",
    "zero_contract_runtime_write",
    "remediation",
    "next_legal_action",
)


def _contract_runtime_reconcile_receipt_resolution(
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    """Resolve one canonical receipt or one legacy+correction transition."""

    current_dispatch = _contract_runtime_current_dispatch_authority_line(
        record
    )
    current_dispatch_index = (
        int(current_dispatch.get("completed_line_index"))
        if current_dispatch.get("status") == "selected"
        and isinstance(current_dispatch.get("completed_line_index"), int)
        else -1
    )
    lines = [
        (index, line)
        for index, line in enumerate(record.get("completed_lines") or [])
        if index > current_dispatch_index
        and isinstance(line, Mapping)
        and str(line.get("stage_id") or "").strip()
        in {"reconcile", "observer_integration", "observer_reconcile"}
        and str(line.get("line_id") or "").strip()
        == "observer_reconcile"
        and str(line.get("evidence_kind") or "").strip() == "reconcile"
        and str(line.get("actor_role") or "").strip() == "observer"
    ]
    sources: list[tuple[int, Mapping[str, Any]]] = []
    corrections: list[tuple[int, Mapping[str, Any]]] = []
    for index, line in lines:
        payload = (
            line.get("payload")
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        if "canonical_reconcile_receipt_correction" in payload:
            corrections.append((index, line))
        else:
            sources.append((index, line))
    if len(sources) != 1 or len(corrections) > 1 or len(lines) not in {1, 2}:
        return {"status": "invalid", "reason": "receipt_cardinality"}
    source_index, source_line = sources[0]
    source_acceptance = _contract_runtime_completed_line_acceptance(
        conn,
        project_id=project_id,
        record=record,
        completed_line_index=source_index,
        expected_line=source_line,
    )
    source_receipt = _contract_runtime_close_authority_payload_mapping(
        source_line,
        "reconcile_authority",
    )
    if not (
        source_acceptance.get("db_verified") is True
        and _contract_runtime_close_authority_hash_matches(source_receipt)
        and _contract_runtime_line_status_passes(source_line)
    ):
        return {"status": "invalid", "reason": "source_acceptance"}
    if stable_sha256(source_receipt) == stable_sha256(authority):
        if corrections:
            return {"status": "invalid", "reason": "unexpected_correction"}
        return {
            "status": "current",
            "line_index": source_index,
            "line": source_line,
            "acceptance": source_acceptance,
            "authority": dict(authority),
        }
    legacy_variants = _contract_runtime_legacy_reconcile_receipt_variants(
        authority
    )
    if not any(
        stable_sha256(source_receipt) == stable_sha256(candidate)
        for candidate in legacy_variants
    ):
        return {"status": "invalid", "reason": "source_identity"}
    if not corrections:
        return {
            "status": "legacy_pending",
            "source_line_index": source_index,
            "source_line": source_line,
            "source_acceptance": source_acceptance,
            "authority": dict(authority),
        }
    correction_index, correction_line = corrections[0]
    correction_acceptance = _contract_runtime_completed_line_acceptance(
        conn,
        project_id=project_id,
        record=record,
        completed_line_index=correction_index,
        expected_line=correction_line,
    )
    if not (
        correction_index == source_index + 1
        and correction_acceptance.get("db_verified") is True
        and _contract_runtime_reconcile_receipt_correction_valid(
            record=record,
            source_line=source_line,
            source_line_index=source_index,
            correction_line=correction_line,
            authority=authority,
        )
    ):
        return {"status": "invalid", "reason": "correction_identity"}
    return {
        "status": "corrected",
        "source_line_index": source_index,
        "source_line": source_line,
        "line_index": correction_index,
        "line": correction_line,
        "acceptance": correction_acceptance,
        "authority": dict(authority),
    }


def _contract_runtime_reconcile_receipt_correction(
    conn,
    *,
    runtime: Any,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    actor_role: str,
    mutate: bool,
) -> dict[str, Any]:
    """Append the sole canonical repair for a pre-current-full receipt."""

    if not (
        actor_role == "observer"
        and str(write.get("stage_id") or "").strip()
        in {"reconcile", "observer_integration", "observer_reconcile"}
        and str(write.get("line_id") or "").strip()
        == "observer_reconcile"
        and str(write.get("evidence_kind") or "").strip() == "reconcile"
    ):
        return {}
    authority = _contract_runtime_close_authority_payload_mapping(
        write,
        "reconcile_authority",
    )
    resolution = _contract_runtime_reconcile_receipt_resolution(
        conn,
        project_id=project_id,
        record=record,
        authority=authority,
    )
    if (
        str(record.get("revision") or "").strip() == "rev10"
        and resolution.get("status") == "legacy_pending"
    ):
        definition = _CONTRACT_DEFINITION_REGISTRY.get(
            MF_PARALLEL_CONTRACT_ID,
            version="v2",
            revision="rev10",
            include_deprecated=True,
        )
        policy = (
            definition.get("system_layer", {}).get(
                "legacy_reconcile_receipt_correction_policy"
            )
            if isinstance(definition.get("system_layer"), Mapping)
            else {}
        )
        if not (
            isinstance(policy, Mapping)
            and policy.get("schema_version")
            == "mf_parallel.legacy_reconcile_receipt_correction_policy.v1"
            and policy.get("enabled_for_revision") is False
            and str(policy.get("revision") or "") == "rev10"
            and policy.get(
                "same_revision_business_evidence_mutation_allowed"
            )
            is False
            and policy.get(
                "exact_duplicate_idempotency_transport_only"
            )
            is True
        ):
            raise GovernanceError(
                "mf_parallel_rev10_reconcile_correction_policy_unavailable",
                "rev10 reconcile correction policy is unavailable",
                409,
                {"writes_performed": False, "fail_closed": True},
            )
        raise GovernanceError(
            "mf_parallel_rev10_legacy_reconcile_correction_forbidden",
            (
                "rev10 forbids legacy reconcile business-evidence "
                "correction; only an exact duplicate is transport-idempotent"
            ),
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "source_completed_line_index": int(
                    resolution.get("source_line_index") or 0
                ),
                "writes_performed": False,
                "mutation_performed": False,
                "exact_duplicate_idempotency_transport_only": True,
                "fail_closed": True,
            },
        )
    if resolution.get("status") == "corrected":
        guide = (
            record.get("runtime_guide")
            if isinstance(record.get("runtime_guide"), Mapping)
            else {}
        )
        state = (
            record.get("execution_state")
            if isinstance(record.get("execution_state"), Mapping)
            else {}
        )
        return {
            "ok": True,
            "record": dict(record),
            "decision": {
                "schema_version": "contract_write_gate_decision.v1",
                "ok": True,
                "errors": [],
            },
            "idempotent": True,
            "completed_line_already_recorded": True,
            "contract_runtime_line_mutated": False,
            "append_only_history_preserved": True,
            "legacy_reconcile_receipt_correction_replayed": True,
            "completed_lines_count": len(record.get("completed_lines") or []),
            "execution_state_revision": int(
                record.get("execution_state_revision")
                or state.get("execution_state_revision")
                or 0
            ),
            "execution_state_hash": str(
                state.get("execution_state_hash") or ""
            ),
            "runtime_guide_hash": str(
                guide.get("runtime_guide_hash") or ""
            ),
        }
    if resolution.get("status") == "invalid" and any(
        isinstance(line, Mapping)
        and str(line.get("line_id") or "").strip()
        == "observer_reconcile"
        for line in record.get("completed_lines") or []
    ):
        raise GovernanceError(
            "contract_runtime_observer_reconcile_correction_identity_mismatch",
            "persisted observer_reconcile receipt/correction is divergent",
            409,
            {
                "reason": str(resolution.get("reason") or "invalid"),
                "writes_performed": False,
                "fail_closed": True,
            },
        )
    if resolution.get("status") != "legacy_pending":
        return {}
    source_line = resolution["source_line"]
    source_index = int(resolution["source_line_index"])
    source_stage_id = str(source_line.get("stage_id") or "").strip()
    if str(write.get("stage_id") or "").strip() != source_stage_id:
        raise GovernanceError(
            "contract_runtime_observer_reconcile_correction_identity_mismatch",
            "observer_reconcile correction stage does not match the source line",
            409,
            {"writes_performed": False, "fail_closed": True},
        )
    marker = _contract_runtime_reconcile_receipt_correction_marker(
        record=record,
        source_line=source_line,
        source_line_index=source_index,
        authority=authority,
    )
    if not _contract_runtime_reconcile_receipt_correction_valid(
        record=record,
        source_line=source_line,
        source_line_index=source_index,
        correction_line={
            "stage_id": source_stage_id,
            "line_id": "observer_reconcile",
            "actor_role": "observer",
            "evidence_kind": "reconcile",
            "status": "passed",
            "payload": {
                "reconcile_authority": dict(authority),
                "canonical_reconcile_receipt_correction": marker,
            },
        },
        authority=authority,
    ):
        raise GovernanceError(
            "contract_runtime_observer_reconcile_correction_unverified",
            "legacy observer_reconcile correction authority is incomplete",
            409,
            {
                "contract_execution_id": str(
                    record.get("contract_execution_id") or ""
                ),
                "writes_performed": False,
                "fail_closed": True,
            },
        )
    correction_line = {
        "stage_id": source_stage_id,
        "line_id": "observer_reconcile",
        "actor_role": "observer",
        "evidence_kind": "reconcile",
        "status": "passed",
        "commit_sha": str(
            authority.get("merged_commit_sha") or ""
        ).strip().lower(),
        "runtime_context_id": str(
            authority.get("runtime_context_id") or ""
        ).strip(),
        "task_id": str(authority.get("task_id") or "").strip(),
        "parent_task_id": str(
            authority.get("parent_task_id") or ""
        ).strip(),
        "merge_queue_id": str(
            authority.get("merge_queue_id") or ""
        ).strip(),
        "payload": {
            "reconcile_authority": dict(authority),
            "canonical_reconcile_receipt_correction": marker,
        },
        "artifact_refs": {
            "source_reconcile_completed_line_ref": marker[
                "source_completed_line_ref"
            ],
            "current_full_reconcile_event_ref": marker[
                "reconcile_event_ref"
            ],
            "current_full_snapshot_ref": (
                f"graph_snapshot:{marker['active_snapshot_id']}"
            ),
        },
    }
    next_line = (
        record.get("runtime_guide", {}).get("next_legal_action", {})
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    expected_next_line_id = str(next_line.get("line_id") or "").strip()
    if not expected_next_line_id:
        raise GovernanceError(
            "contract_runtime_observer_reconcile_correction_transition_invalid",
            "legacy observer_reconcile correction has no durable next line",
            409,
            {"writes_performed": False, "fail_closed": True},
        )
    if not mutate:
        return {
            "ok": True,
            "decision": {
                "schema_version": "contract_write_gate_decision.v1",
                "ok": True,
                "errors": [],
            },
            "record": dict(record),
            "write": correction_line,
            "would_mutate_completed_lines": True,
            "legacy_reconcile_receipt_correction_required": True,
            "append_only_history_preserved": True,
            "completed_lines_count": len(record.get("completed_lines") or []),
        }
    try:
        persisted = _contract_runtime_append_completed_line_correction(
            runtime,
            record,
            correction_line,
            contract_execution_id=str(
                record.get("contract_execution_id") or ""
            ),
            actor_role="observer",
            expected_next_line_id=expected_next_line_id,
        )
    except ContractRuntimeError as exc:
        raise GovernanceError(
            "contract_runtime_observer_reconcile_correction_conflict",
            str(exc),
            409,
            {"writes_performed": False, "fail_closed": True},
        ) from exc
    if not persisted:
        raise GovernanceError(
            "contract_runtime_observer_reconcile_correction_transition_invalid",
            "legacy observer_reconcile correction changed the legal next line",
            409,
            {"writes_performed": False, "fail_closed": True},
        )
    return {
        "ok": True,
        "record": persisted,
        "decision": {
            "schema_version": "contract_write_gate_decision.v1",
            "ok": True,
            "errors": [],
        },
        "status": "corrected_observer_reconcile_receipt",
        "contract_runtime_line_mutated": True,
        "append_only_history_preserved": True,
        "historical_line_rewritten": False,
        "canonical_reconcile_receipt_correction": marker,
        "completed_lines_count": len(persisted.get("completed_lines") or []),
    }


def _contract_runtime_qa_rejection_response_fields(
    result: Mapping[str, Any],
) -> dict[str, Any]:
    """Project the bounded machine-readable QA rejection without collisions.

    ContractRuntime responses also carry a current runtime guide whose own
    ``missing_proof_fields`` and ``next_legal_action`` describe the unchanged
    record.  When the attempted QA write was rejected, those projections must
    not replace the rejection's exact field/remediation/action contract.
    """

    if not result.get("zero_contract_runtime_write") is True:
        return {}
    if not (
        result.get("silent_failing_normalization_prevented") is True
        or result.get("qa_pass_write_compiler_parity_prevented") is True
    ):
        return {}
    return {
        field: result[field]
        for field in _CONTRACT_RUNTIME_QA_REJECTION_RESPONSE_FIELDS
        if field in result
    }


def _contract_runtime_observer_reconcile_idempotency(
    *,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    actor_role: str,
) -> dict[str, Any]:
    """Return an unchanged success for an exact duplicate reconcile record."""

    if not (
        actor_role == "observer"
        and str(write.get("stage_id") or "").strip() == "observer_integration"
        and str(write.get("line_id") or "").strip() == "observer_reconcile"
        and str(write.get("evidence_kind") or "").strip() == "reconcile"
    ):
        return {}
    matches = [
        line
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
        and str(line.get("stage_id") or "").strip() == "observer_integration"
        and str(line.get("line_id") or "").strip() == "observer_reconcile"
        and str(line.get("evidence_kind") or "").strip() == "reconcile"
        and str(line.get("actor_role") or "").strip() == "observer"
    ]
    if len(matches) != 1:
        return {}
    matched = matches[0]
    errors: list[str] = []
    for field in (
        "runtime_context_id",
        "task_id",
        "parent_task_id",
        "merge_queue_id",
    ):
        supplied = _contract_runtime_mapping_value(write, field)
        canonical = _contract_runtime_mapping_value(matched, field)
        if supplied and canonical and supplied != canonical:
            errors.append(f"duplicate observer_reconcile {field} mismatch")
    supplied_commit = str(write.get("commit_sha") or "").strip().lower()
    canonical_commit = str(matched.get("commit_sha") or "").strip().lower()
    if supplied_commit and canonical_commit and supplied_commit != canonical_commit:
        errors.append("duplicate observer_reconcile commit_sha mismatch")
    if errors:
        return _contract_runtime_unchanged_line_rejection(record, errors)

    guide = (
        record.get("runtime_guide")
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    state = (
        record.get("execution_state")
        if isinstance(record.get("execution_state"), Mapping)
        else {}
    )
    return {
        "ok": True,
        "record": dict(record),
        "decision": {
            "schema_version": "contract_write_gate_decision.v1",
            "ok": True,
            "errors": [],
        },
        "idempotent": True,
        "completed_line_already_recorded": True,
        "contract_runtime_line_mutated": False,
        "source_of_authority": "ContractRuntime.completed_lines",
        "completed_line_ref": str(matched.get("_source_ref") or ""),
        "completed_lines_count": len(record.get("completed_lines") or []),
        "execution_state_revision": int(
            record.get("execution_state_revision")
            or state.get("execution_state_revision")
            or 0
        ),
        "execution_state_hash": str(state.get("execution_state_hash") or ""),
        "runtime_guide_hash": str(guide.get("runtime_guide_hash") or ""),
    }


def _contract_runtime_same_lane_worker_commit_precheck(
    *,
    stored_record: Mapping[str, Any],
    projected_record: Mapping[str, Any],
    projection: Mapping[str, Any],
    write: Mapping[str, Any],
    actor_role: str,
) -> dict[str, Any]:
    """Precheck the projected reopen without weakening normal commit writes."""

    recovery = projection.get("same_lane_worker_commit_recovery")
    if (
        not isinstance(recovery, Mapping)
        or recovery.get("status") not in {"eligible", "retarget_required"}
    ):
        return {}
    next_line = (
        projected_record.get("runtime_guide", {}).get("next_legal_action", {})
        if isinstance(projected_record.get("runtime_guide"), Mapping)
        else {}
    )
    requested = {
        "stage_id": str(write.get("stage_id") or "").strip(),
        "line_id": str(write.get("line_id") or "").strip(),
        "evidence_kind": str(write.get("evidence_kind") or "").strip(),
        "actor_role": str(write.get("actor_role") or actor_role or "").strip(),
    }
    expected = {
        "stage_id": "worker_commit",
        "line_id": "worker_commit",
        "evidence_kind": "worker_commit",
        "actor_role": "mf_sub",
    }
    errors = [
        f"{field} mismatch for same-lane worker_commit recovery"
        for field, expected_value in expected.items()
        if requested[field] != expected_value
    ]
    if recovery.get("status") == "retarget_required":
        errors.append(
            "same-lane worker_commit recovery requires current target sync "
            "before worker_commit"
        )
    if str(next_line.get("line_id") or "").strip() != "worker_commit":
        errors.append("projected ContractRuntime is not awaiting worker_commit")
    expected_write = _contract_runtime_write_from_record(
        projected_record,
        actor_role="mf_sub",
        stage_id="worker_commit",
        line_id="worker_commit",
        evidence_kind="worker_commit",
    )
    if int(write.get("execution_state_revision") or 0) != int(
        expected_write.get("execution_state_revision") or 0
    ):
        errors.append("execution_state_revision is stale")
    if str(write.get("runtime_guide_hash") or "").strip() != str(
        expected_write.get("runtime_guide_hash") or ""
    ).strip():
        errors.append("runtime_guide_hash is stale")
    if errors:
        rejected = _contract_runtime_unchanged_line_rejection(
            projected_record,
            errors,
        )
        rejected["same_lane_worker_commit_recovery"] = dict(recovery)
        rejected["generic_contract_runtime_submit_line_allowed"] = False
        rejected["required_facade"] = "runtime_context_worker_commit"
        return rejected
    guide = (
        projected_record.get("runtime_guide")
        if isinstance(projected_record.get("runtime_guide"), Mapping)
        else {}
    )
    state = (
        projected_record.get("execution_state")
        if isinstance(projected_record.get("execution_state"), Mapping)
        else {}
    )
    return {
        "schema_version": "contract_runtime_line_write_precheck_result.v1",
        "ok": True,
        "decision": {
            "schema_version": "contract_write_gate_decision.v1",
            "ok": True,
            "errors": [],
        },
        "record": dict(projected_record),
        "write": dict(write),
        "would_mutate_completed_lines": False,
        "completed_lines_count": len(stored_record.get("completed_lines") or []),
        "projected_completed_lines_count": len(
            projection.get("projected_completed_lines") or []
        ),
        "execution_state_revision": int(
            stored_record.get("execution_state_revision") or 0
        ),
        "execution_state_hash": str(state.get("execution_state_hash") or ""),
        "runtime_guide_hash": str(guide.get("runtime_guide_hash") or ""),
        "same_lane_worker_commit_recovery": dict(recovery),
    }


def _contract_runtime_bind_server_line_authority(
    ctx: RequestContext,
    conn,
    *,
    project_id: str,
    record: Mapping[str, Any],
    write: Mapping[str, Any],
    body: Mapping[str, Any],
) -> dict[str, Any]:
    line_id = str(write.get("line_id") or "").strip()
    if line_id == "observer_merge":
        return _contract_runtime_bind_observer_merge_authority(
            conn,
            project_id=project_id,
            record=record,
            write=write,
        )
    if line_id == "qa_independent_verification":
        return _contract_runtime_bind_qa_independent_verification_authority(
            ctx,
            conn,
            project_id=project_id,
            record=record,
            write=write,
        )
    qa_policy = _contract_runtime_line_evidence_policy(
        record,
        "bounded_qa_review_policy",
        line_id=line_id,
    )
    if qa_policy:
        return _contract_runtime_bind_qa_graph_authority(
            ctx,
            conn,
            project_id=project_id,
            record=record,
            write=write,
            body=body,
            policy=qa_policy,
        )
    reconcile_policy = _contract_runtime_line_evidence_policy(
        record,
        "current_full_reconcile_evidence_policy",
        line_id=line_id,
    )
    if reconcile_policy:
        return _contract_runtime_bind_reconcile_authority(
            conn,
            project_id=project_id,
            record=record,
            write=write,
            policy=reconcile_policy,
        )
    return dict(write)


def _dispatch_payload_worker_role(value: Any, *, depth: int = 0) -> str:
    if depth > 6:
        return ""
    if isinstance(value, Mapping):
        for key in ("worker_role", "role"):
            role = str(value.get(key) or "").strip()
            if role:
                return role
        for child in value.values():
            role = _dispatch_payload_worker_role(child, depth=depth + 1)
            if role:
                return role
    if isinstance(value, list):
        for child in value:
            role = _dispatch_payload_worker_role(child, depth=depth + 1)
            if role:
                return role
    return ""


def _normalize_dispatch_payload_worker_role(
    value: Any,
    worker_role: str,
    *,
    depth: int = 0,
) -> Any:
    if depth > 6:
        return value
    if isinstance(value, Mapping):
        normalized = dict(value)
        has_worker_context = bool(
            str(normalized.get("runtime_context_id") or "").strip()
        )
        has_worker_task = bool(
            str(
                normalized.get("task_id")
                or normalized.get("worker_task_id")
                or ""
            ).strip()
        )
        has_parent_task = bool(str(normalized.get("parent_task_id") or "").strip())
        if (
            has_worker_context
            and has_worker_task
            and has_parent_task
            and not str(
                normalized.get("worker_role") or normalized.get("role") or ""
            ).strip()
        ):
            normalized["worker_role"] = worker_role
        for key, child in list(normalized.items()):
            if isinstance(child, (Mapping, list)):
                normalized[key] = _normalize_dispatch_payload_worker_role(
                    child,
                    worker_role,
                    depth=depth + 1,
                )
        return normalized
    if isinstance(value, list):
        return [
            _normalize_dispatch_payload_worker_role(
                child,
                worker_role,
                depth=depth + 1,
            )
            for child in value
        ]
    return value


ONBOARD_CONTRACT_ID = "onboard_contract"
ONBOARD_ROUTE_GUIDE_SERVICE_ID = "onboard_route_guide"

_RELEASE_OPERATOR_HEAD_QUEUE_SCHEMA = "release_operator_head_queue.v1"


def _ensure_release_operator_head_queue_schema(conn) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS release_operator_head_queue (
            project_id TEXT NOT NULL,
            backlog_id TEXT NOT NULL,
            position INTEGER NOT NULL,
            pinned INTEGER NOT NULL DEFAULT 0,
            skip_count INTEGER NOT NULL DEFAULT 0,
            last_skip_reason TEXT NOT NULL DEFAULT '',
            last_skipped_at TEXT NOT NULL DEFAULT '',
            inserted_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (project_id, backlog_id)
        )
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_release_operator_head_queue_order
        ON release_operator_head_queue(project_id, position, backlog_id)
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS release_operator_head_queue_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id TEXT NOT NULL,
            action TEXT NOT NULL,
            backlog_id TEXT NOT NULL DEFAULT '',
            actor TEXT NOT NULL,
            reason TEXT NOT NULL DEFAULT '',
            before_json TEXT NOT NULL DEFAULT '{}',
            after_json TEXT NOT NULL DEFAULT '{}',
            created_at TEXT NOT NULL
        )
        """
    )


def _release_operator_head_queue_execution_projection(
    conn,
    *,
    project_id: str,
    backlog_id: str,
) -> dict[str, Any]:
    projection = read_backlog_contract_chain_current(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        rebuild_if_missing=False,
    )
    next_action = (
        projection.get("next_legal_action")
        if isinstance(projection.get("next_legal_action"), Mapping)
        else {}
    )
    readiness_state = str(projection.get("readiness_state") or "").strip()
    execution_id = str(
        projection.get("active_child_contract_execution_id")
        or projection.get("current_contract_execution_id")
        or ""
    ).strip()
    active = bool(
        execution_id
        and readiness_state not in {"", "contract_complete", "complete", "closed"}
        and (next_action or projection.get("active_child_contract_execution_id"))
    )
    return {
        "active_execution": active,
        "active_contract_execution_id": execution_id if active else "",
        "readiness_state": readiness_state,
    }


def _release_operator_head_queue_rows(conn, project_id: str) -> list[dict[str, Any]]:
    _ensure_release_operator_head_queue_schema(conn)
    rows = conn.execute(
        """
        SELECT q.*, b.status AS backlog_status, b.title AS backlog_title
        FROM release_operator_head_queue q
        LEFT JOIN backlog_bugs b ON b.bug_id = q.backlog_id
        WHERE q.project_id = ?
        ORDER BY q.position, q.backlog_id
        """,
        (project_id,),
    ).fetchall()
    result: list[dict[str, Any]] = []
    for row in rows:
        item = {
            "backlog_id": str(_row_get(row, "backlog_id", "") or ""),
            "title": str(_row_get(row, "backlog_title", "") or ""),
            "position": int(_row_get(row, "position", 0) or 0),
            "pinned": bool(_row_get(row, "pinned", 0)),
            "skip_count": int(_row_get(row, "skip_count", 0) or 0),
            "last_skip_reason": str(
                _row_get(row, "last_skip_reason", "") or ""
            ),
            "last_skipped_at": str(_row_get(row, "last_skipped_at", "") or ""),
            "inserted_at": str(_row_get(row, "inserted_at", "") or ""),
            "updated_at": str(_row_get(row, "updated_at", "") or ""),
            "backlog_status": str(_row_get(row, "backlog_status", "") or ""),
        }
        item["eligible"] = item["backlog_status"] == "OPEN"
        item.update(
            _release_operator_head_queue_execution_projection(
                conn,
                project_id=project_id,
                backlog_id=item["backlog_id"],
            )
        )
        result.append(item)
    return result


def _release_operator_head_queue_view(
    conn,
    project_id: str,
    *,
    temporarily_skipped_backlog_ids: set[str] | None = None,
) -> dict[str, Any]:
    items = _release_operator_head_queue_rows(conn, project_id)
    selection = select_release_operator_head_queue(
        items,
        temporarily_skipped_backlog_ids=temporarily_skipped_backlog_ids,
    )
    selected_id = str(selection.get("selected_backlog_id") or "")
    head = next(
        (dict(item) for item in items if item["backlog_id"] == selected_id),
        {},
    )
    events = conn.execute(
        """
        SELECT id, action, backlog_id, actor, reason, before_json, after_json,
               created_at
        FROM release_operator_head_queue_events
        WHERE project_id = ?
        ORDER BY id DESC
        LIMIT 50
        """,
        (project_id,),
    ).fetchall()
    audit_events = []
    for event in events:
        audit_events.append(
            {
                "id": int(_row_get(event, "id", 0) or 0),
                "action": str(_row_get(event, "action", "") or ""),
                "backlog_id": str(_row_get(event, "backlog_id", "") or ""),
                "actor": str(_row_get(event, "actor", "") or ""),
                "reason": str(_row_get(event, "reason", "") or ""),
                "before": backlog_runtime.parse_json_object(
                    _row_get(event, "before_json", "{}")
                ),
                "after": backlog_runtime.parse_json_object(
                    _row_get(event, "after_json", "{}")
                ),
                "created_at": str(_row_get(event, "created_at", "") or ""),
            }
        )
    revision_payload = [
        {
            key: item.get(key)
            for key in (
                "backlog_id",
                "position",
                "pinned",
                "skip_count",
                "last_skipped_at",
                "backlog_status",
                "active_contract_execution_id",
            )
        }
        for item in items
    ]
    return {
        "schema_version": _RELEASE_OPERATOR_HEAD_QUEUE_SCHEMA,
        "project_id": project_id,
        "bounded_capacity": RELEASE_OPERATOR_HEAD_QUEUE_MAX_ITEMS,
        "count": len(items),
        "items": items,
        "head": head,
        "selection": selection,
        "queue_revision": stable_sha256(revision_payload),
        "audit_events": audit_events,
        "ordinary_skip_policy": {
            "position_preserved": True,
            "skip_count_monotonic": True,
            "skip_is_one_selection_only": True,
        },
        "pinned_active_position_policy": {
            "takes_precedence": True,
            "ordinary_skip_allowed": False,
        },
    }


def _record_release_operator_head_queue_event(
    conn,
    *,
    project_id: str,
    action: str,
    backlog_id: str,
    actor: str,
    reason: str = "",
    before: Mapping[str, Any] | None = None,
    after: Mapping[str, Any] | None = None,
) -> int:
    cursor = conn.execute(
        """
        INSERT INTO release_operator_head_queue_events (
            project_id, action, backlog_id, actor, reason,
            before_json, after_json, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            project_id,
            action,
            backlog_id,
            actor,
            reason,
            json.dumps(dict(before or {}), ensure_ascii=False, sort_keys=True),
            json.dumps(dict(after or {}), ensure_ascii=False, sort_keys=True),
            _utc_now(),
        ),
    )
    return int(cursor.lastrowid or 0)


def _release_operator_head_queue_integration_epoch_guard(
    conn,
    *,
    project_id: str,
) -> dict[str, Any]:
    """Project the non-skippable/non-reorderable active epoch positions."""

    from .parallel_branch_runtime import (
        integration_epoch_child_backlog_ids,
        integration_epoch_resume_payload,
        integration_epoch_to_dict,
        list_active_integration_epochs,
    )

    epochs = list_active_integration_epochs(conn, project_id)
    if not epochs:
        return {}
    protected_ids: list[str] = []
    epoch_guards: list[dict[str, Any]] = []
    member_guards: dict[str, dict[str, Any]] = {}
    for epoch in epochs:
        resume = _server_integration_epoch_resume_payload(conn, epoch)
        epoch_members = tuple(
            dict.fromkeys(
                backlog_id
                for backlog_id in (
                    str(resume.get("backlog_id") or "").strip(),
                    epoch.active_backlog_id,
                    *integration_epoch_child_backlog_ids(conn, epoch),
                    epoch.coordination_backlog_id,
                )
                if backlog_id
            )
        )
        epoch_guard = {
            "integration_epoch": integration_epoch_to_dict(epoch),
            "next_legal_action": resume,
            "resume_backlog_id": str(resume.get("backlog_id") or "").strip(),
            "protected_backlog_ids": list(epoch_members),
        }
        epoch_guards.append(epoch_guard)
        for backlog_id in epoch_members:
            if backlog_id not in protected_ids:
                protected_ids.append(backlog_id)
            member_guards.setdefault(backlog_id, epoch_guard)
    primary = epoch_guards[0]
    return {
        **primary,
        "integration_epochs": [guard["integration_epoch"] for guard in epoch_guards],
        "epoch_guards": epoch_guards,
        "member_guards": member_guards,
        "protected_backlog_ids": protected_ids,
    }

