# Historical Direct Main routes could also authorize the read-only preflight
# surface.  Keep that compatibility out of newly issued full-round routes, but
# do not invalidate an otherwise exact durable root route solely because it
# preserves the action that was legal when the route was issued.
_OPERATOR_SUPERVISED_DIRECT_MAIN_HISTORICAL_ROOT_ROUTE_ACTIONS = (
    *_OPERATOR_SUPERVISED_DIRECT_MAIN_FULL_ROUND_ACTIONS,
    # Older root-route issuers included the read-only route-context surface in
    # the durable action set.  It is not part of newly issued full-round
    # routes, but must remain valid when rechecking that exact immutable root
    # registry row at close.
    "route_context",
    # Older direct-main route issuers used the persisted event-kind spelling
    # for this action.  Accept it only when revalidating an immutable root
    # route; newly issued full-round routes keep the canonical mutation name.
    "observer_direct_implementation_exception",
    # The pre-graph_current_full_reconcile direct-main issuer persisted this
    # action spelling in otherwise exact root route rows.  Accept it only at
    # this immutable historical registry boundary; newly issued full-round
    # routes continue to use graph_current_full_reconcile.
    "current_full_reconcile",
    "preflight_check",
)


def _contract_runtime_parentless_direct_main_root_route_action_authority(
    conn,
    *,
    project_id: str,
    route_token_ref: str,
) -> dict[str, Any]:
    """Validate the immutable root route action set shared by entry and close."""

    normalized_project_id = str(project_id or "").strip()
    storage_project_id = _route_registry_storage_project_id(
        normalized_project_id
    )
    normalized_route_token_ref = str(route_token_ref or "").strip()
    expected_actions = list(
        _OPERATOR_SUPERVISED_DIRECT_MAIN_HISTORICAL_ROOT_ROUTE_ACTIONS
    )
    expected_action_set = set(expected_actions)
    row = (
        conn.execute(
            """
            SELECT allowed_actions_json
            FROM observer_route_token_refs
            WHERE project_id = ? AND route_token_ref = ?
            """,
            (storage_project_id, normalized_route_token_ref),
        ).fetchone()
        if conn is not None
        and normalized_project_id
        and normalized_route_token_ref
        else None
    )
    raw_actions: Any = None
    if row is not None:
        try:
            raw_actions = json.loads(row["allowed_actions_json"] or "")
        except (KeyError, TypeError, ValueError, json.JSONDecodeError):
            raw_actions = None
    canonical = bool(
        isinstance(raw_actions, list)
        and raw_actions
        and all(
            isinstance(item, str) and item == item.strip() and item
            for item in raw_actions
        )
        and len(raw_actions) == len(set(raw_actions))
    )
    actual_actions = list(raw_actions) if canonical else []
    unexpected_actions = (
        sorted(set(actual_actions) - expected_action_set)
        if canonical
        else []
    )
    accepted = bool(row is not None and canonical and not unexpected_actions)
    return {
        "schema_version": (
            "parentless_direct_main.root_route_action_authority.v1"
        ),
        "accepted": accepted,
        "passed": accepted,
        "status": "passed" if accepted else "failed",
        "server_derived": True,
        "source": "observer_route_token_refs.allowed_actions_json",
        "project_id": normalized_project_id,
        "route_token_ref": normalized_route_token_ref,
        "route_registry_row_found": row is not None,
        "canonical_allowed_actions": canonical,
        "allowed_actions": actual_actions,
        "expected_allowed_actions": expected_actions,
        "unexpected_actions": unexpected_actions,
        "field": "allowed_actions",
        "historical_backfill_allowed": False,
    }
