def _onboard_selected_qa_contract_runtime_guidance(
    record: Mapping[str, Any],
    *,
    next_legal_action: Mapping[str, Any],
    qa_runtime_record: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Overlay selected-QA guidance for ContractRuntime's current line."""
    action = dict(next_legal_action or {})
    line_id = str(action.get("line_id") or "").strip()
    if line_id not in {"qa_graph_context", "qa_independent_verification"}:
        return {}
    project_id = str(record.get("project_id") or "").strip()
    backlog_id = str(record.get("backlog_id") or "").strip()
    execution_id = str(
        action.get("contract_execution_id") or record.get("contract_execution_id") or ""
    ).strip()
    current_action = str(action.get("action") or action.get("id") or line_id).strip()
    authority = str(
        action.get("source_of_authority") or "contract_runtime"
    ).strip()
    authority_source = str(
        action.get("authority_decision_source") or "backlog_contract_chain_current"
    ).strip()
    from .contract_state_runtime import (
        cli_agent_qa_onboard_guidance_binding,
        cli_agent_qa_onboard_guidance_contract,
    )

    guidance_contract = cli_agent_qa_onboard_guidance_contract()
    compact_projection_contract = guidance_contract.get(
        "compact_selected_role_projection"
    )
    canonical_dispatch_identity_fields = (
        list(
            compact_projection_contract.get(
                "canonical_dispatch_identity_fields"
            )
            or []
        )
        if isinstance(compact_projection_contract, Mapping)
        else []
    )
    line_contracts = guidance_contract.get("line_contracts")
    line_contract = (
        line_contracts.get(line_id) if isinstance(line_contracts, Mapping) else {}
    )
    ordered_steps_template = (
        list(line_contract.get("ordered_steps") or [])
        if isinstance(line_contract, Mapping)
        else []
    )
    ordered_step_ids = [
        str(step.get("id") or "").strip()
        if isinstance(step, Mapping)
        else ""
        for step in ordered_steps_template
    ]
    token_transport = guidance_contract.get("token_transport")
    guidance_schema = str(
        guidance_contract.get("selected_role_guidance_schema_version") or ""
    ).strip()
    base_guidance = {
        "schema_version": guidance_schema,
        "next_action": action,
        "contract_execution_id": execution_id,
        "current_line_id": line_id,
        "current_action": current_action,
        "current_action_source": str(
            action.get("source") or "ContractRuntime.next_legal_action"
        ).strip(),
        "source_of_authority": authority,
        "authority_decision_source": authority_source,
        "qa_onboard_guidance_contract": (
            cli_agent_qa_onboard_guidance_binding()
        ),
    }
    if (
        not guidance_schema
        or not isinstance(line_contract, Mapping)
        or not ordered_steps_template
        or not all(ordered_step_ids)
        or len(set(ordered_step_ids)) != len(ordered_step_ids)
        or not isinstance(token_transport, Mapping)
        or token_transport.get("raw_value_exposed") is not False
        or token_transport.get("persisted") is not False
        or guidance_contract.get("raw_qa_session_token_public") is not False
        or not isinstance(
            line_contract.get("redundant_graph_query_required"), bool
        )
    ):
        return {
            **base_guidance,
            "status": "blocked", "executable": False, "ordered_steps": [],
            "blocker": {
                "id": "qa_onboard_guidance_contract_invalid",
                "source": "cli_agent_qa_onboard_guidance_contract",
            },
        }
    dispatch_record = (
        qa_runtime_record if isinstance(qa_runtime_record, Mapping) else record
    )
    dispatch_line: Mapping[str, Any] = {}
    for _index, candidate in reversed(
        _contract_runtime_completed_lines(dispatch_record)
    ):
        if (
            str(candidate.get("stage_id") or "").strip() == "dispatch"
            and str(candidate.get("line_id") or "").strip()
            == "observer_dispatch_bounded_workers"
            and str(candidate.get("evidence_kind") or "").strip()
            == "dispatch_bounded_worker"
            and str(candidate.get("actor_role") or "").strip() == "observer"
        ):
            dispatch_line = candidate
            break
    dispatch_payload = (
        dispatch_line.get("payload")
        if isinstance(dispatch_line.get("payload"), Mapping)
        else {}
    )
    dispatch_route_identity = (
        dispatch_payload.get("route_identity")
        if isinstance(dispatch_payload.get("route_identity"), Mapping)
        else dispatch_line.get("route_identity")
        if isinstance(dispatch_line.get("route_identity"), Mapping)
        else {}
    )

    def _dispatch_identity(*aliases: str) -> tuple[str, bool, bool]:
        values = {
            str(source.get(alias) or "").strip()
            for source in (
                dispatch_line,
                dispatch_payload,
                dispatch_route_identity,
            )
            for alias in aliases
            if str(source.get(alias) or "").strip()
        }
        return (
            next(iter(values)) if len(values) == 1 else "",
            len(values) > 1,
            bool(values),
        )

    worker_task_id, task_conflict, _task_present = _dispatch_identity(
        "task_id", "worker_task_id"
    )
    worktree, worktree_conflict, worktree_present = _dispatch_identity(
        "worktree_path", "worker_worktree_path", "assigned_worktree"
    )
    target_root, target_root_conflict, _target_root_present = _dispatch_identity(
        "target_project_root", "project_root", "repo_root"
    )
    completed_line_ids = {
        str(candidate.get("line_id") or "").strip()
        for _index, candidate in _contract_runtime_completed_lines(dispatch_record)
        if _contract_runtime_line_status_passes(candidate)
    }
    postmerge_qa_ready = bool(
        _is_mf_parallel_postmerge_revision(dispatch_record)
        and {"observer_merge", "observer_reconcile"}.issubset(
            completed_line_ids
        )
    )
    registered_project_root = (
        project_service.resolve_project_root(
            project_id,
            None,
            fallback_self=True,
        )
        if postmerge_qa_ready
        else None
    )
    canonical_qa_root = (
        str(Path(registered_project_root).resolve())
        if registered_project_root is not None
        else ""
    )
    postmerge_qa_root = bool(postmerge_qa_ready and canonical_qa_root)
    repo_root = (
        canonical_qa_root
        if postmerge_qa_root
        else worktree
        if worktree_present
        else target_root
    )
    qa_root_source = (
        "reconciled_canonical_project_root"
        if postmerge_qa_root
        else "assigned_worker_worktree"
        if worktree_present
        else "canonical_target_project_root_fallback"
    )
    canonical_dispatch_identity = {
        "project_id": project_id,
        "backlog_id": backlog_id,
        "original_worker_task_id": worker_task_id,
        "assigned_worktree": worktree,
        "qa_query_root": repo_root,
        "qa_query_root_source": qa_root_source,
    }
    for field in canonical_dispatch_identity_fields:
        value, conflict, _present = _dispatch_identity(str(field))
        if value and not conflict:
            canonical_dispatch_identity[str(field)] = value
    missing = [
        field for field, value in (("task_id", worker_task_id), ("repo_root", repo_root))
        if not value
    ]
    if postmerge_qa_ready and not canonical_qa_root:
        missing.append("registered_canonical_project_root")
    conflicts = [
        field for field, conflict in (
            ("task_id", task_conflict),
            ("worktree_path", worktree_conflict),
            ("target_project_root", target_root_conflict),
        )
        if conflict
    ]
    if missing or conflicts:
        return {
            **base_guidance,
            "status": "blocked", "executable": False, "ordered_steps": [],
            "blocker": {
                "id": "qa_canonical_dispatch_identity_unavailable",
                "source": "ContractRuntime.completed_lines.observer_dispatch_bounded_workers",
                "missing_fields": missing,
                "conflicting_fields": conflicts,
            },
        }
    replacements: dict[str, Any] = {
        "$project_id": project_id,
        "$backlog_id": backlog_id,
        "$contract_execution_id": execution_id,
        "$original_worker_task_id": worker_task_id,
        "$principal_id": f"qa:{worker_task_id}",
        "$assigned_worktree": repo_root,
        "$qa_session_token_ref": dict(token_transport),
    }
    if postmerge_qa_root:
        replacements[
            "<full git HEAD from git rev-parse HEAD in assigned_worktree>"
        ] = "<full final canonical HEAD from git rev-parse HEAD in qa_query_root>"
    unresolved_placeholders: set[str] = set()

    def _render_machine_value(value: Any) -> Any:
        if isinstance(value, Mapping):
            return {
                str(key): _render_machine_value(item)
                for key, item in value.items()
            }
        if isinstance(value, list):
            return [_render_machine_value(item) for item in value]
        if isinstance(value, str) and value in replacements:
            return deepcopy(replacements[value])
        if isinstance(value, str) and value.startswith("$"):
            unresolved_placeholders.add(value)
        return value

    steps = _render_machine_value(ordered_steps_template)
    if unresolved_placeholders:
        return {
            **base_guidance,
            "status": "blocked", "executable": False, "ordered_steps": [],
            "blocker": {
                "id": "qa_onboard_guidance_contract_invalid",
                "source": "cli_agent_qa_onboard_guidance_contract",
                "unresolved_placeholders": sorted(unresolved_placeholders),
            },
        }
    onboard_execution_id = str(
        record.get("root_contract_execution_id") or ""
    ).strip()
    if isinstance(qa_runtime_record, Mapping):
        onboard_execution_id = str(
            record.get("contract_execution_id") or onboard_execution_id
        ).strip()
    return {
        **base_guidance,
        "ordered_steps": steps,
        "canonical_dispatch_identity": canonical_dispatch_identity,
        "legitimate_evidence_bindings": _governed_evidence_binding_guide(
            onboard_contract_execution_id=onboard_execution_id,
            assigned_worker_worktree=repo_root,
            qa_target_project_root_source=qa_root_source,
            canonical_project_root_is_query_target=postmerge_qa_root,
        ),
        "machine_contract": {
            "token_transport": deepcopy(token_transport),
            "line_contract": deepcopy(line_contract),
        },
        "redundant_graph_query_required": bool(
            line_contract["redundant_graph_query_required"]
        ),
    }


def _onboard_parentless_direct_main_graph_query_guidance(
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    route_token_ref: str,
    target_files: Sequence[str] = (),
) -> dict[str, Any]:
    approved_target_files = _runtime_context_service_dedupe(
        [str(path or "").strip() for path in target_files]
    )
    query_path = approved_target_files[0] if approved_target_files else ""
    arguments = {
        "project_id": str(project_id or "").strip(),
        "snapshot_id": "active",
        "tool": "find_node_by_path",
        "args": {"path": query_path},
        "query_source": "observer",
        "query_purpose": "gate_validation",
        "route_token_ref": str(route_token_ref or "").strip(),
        "backlog_id": str(backlog_id or "").strip(),
        "task_id": str(task_id or "").strip(),
    }
    return {
        "schema_version": (
            "onboard_route_guide.parentless_direct_main."
            "graph_query_close_authority.v1"
        ),
        "authority": "parentless_direct_main_close_gate",
        "server_gate": (
            "parentless_direct_main_pre_implementation_graph_trace_gate"
        ),
        "accepted_query_sources": sorted(
            _PARENTLESS_DIRECT_MAIN_GRAPH_QUERY_SOURCES
        ),
        "accepted_query_purposes": sorted(
            _PARENTLESS_DIRECT_MAIN_GRAPH_QUERY_PURPOSES
        ),
        "recommended_query_source": "observer",
        "recommended_query_purpose": "gate_validation",
        "copy_safe_graph_query": {
            "mcp_tool": "graph_query",
            "ready": all(
                [
                    arguments["project_id"],
                    arguments["route_token_ref"],
                    arguments["backlog_id"],
                    arguments["task_id"],
                    arguments["args"]["path"],
                ]
            ),
            "arguments": arguments,
            "raw_route_token_required": False,
        },
        "db_identity_binding": {
            "project_id": arguments["project_id"],
            "backlog_id": arguments["backlog_id"],
            "task_id": arguments["task_id"],
            "task_id_db_column": "graph_query_traces.task_id",
            "route_bound_observer_behavior": (
                "server derives canonical backlog_id/task_id from route_token_ref "
                "and rejects mismatched client claims"
            ),
        },
        "server_derived_world_ref": {
            "snapshot_selector": "active",
            "commit_and_root_are_caller_inputs": False,
            "commit_source": (
                "operator_supervised_direct_main.pre_mutation_world_ref"
            ),
            "root_source": "registered_canonical_project_root",
            "snapshot_commit_must_match_world_ref": True,
            "mismatch_creates_trace": False,
        },
        "exploration_only": {
            "query_purposes": ["inspect_node"],
            "graph_query_valid": True,
            "close_authoritative": False,
            "reason": (
                "inspect_node remains valid for exploration but is not accepted "
                "by the parentless direct-main close gate"
            ),
        },
        "ordering": {
            "required": "graph_query_before_pre_mutation_event_and_implementation",
            "record_trace_ids_in": (
                "observer_direct_mutation_exception.artifact_refs.graph_trace_ids"
            ),
            "late_or_post_hoc_traces_accepted": False,
        },
    }


def _onboard_parentless_direct_main_pre_mutation_event_guidance(
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    route_token_ref: str,
    target_files: Sequence[str] = (),
) -> dict[str, Any]:
    """Return one compact, copy-safe canonical direct-main event template."""

    from . import task_timeline

    authority_schema = (
        task_timeline.observer_direct_pre_mutation_authority_schema()
    )
    canonical_event = authority_schema["canonical_timeline_event"]
    allowed_files = _runtime_context_service_dedupe(
        [str(path or "").strip() for path in target_files]
    )
    graph_trace_placeholder = (
        "<replace with DB-verified trace_id from the immediately preceding "
        "graph_query>"
    )
    reason_placeholder = "<replace with the bounded operator-approved reason>"
    approval_ref_placeholder = "<replace with the operator approval reference>"
    arguments_template = {
        "project_id": str(project_id or "").strip(),
        "backlog_id": str(backlog_id or "").strip(),
        "task_id": str(task_id or "").strip(),
        **dict(canonical_event["top_level"]),
        "actor": "observer",
        "payload": {
            "reason": reason_placeholder,
            "observer_direct_mutation": True,
            "tiny_deterministic_scope": True,
            "allowed_files": allowed_files,
            "dirty_scope_check": {
                "allowed_files": allowed_files,
                "dirty_files": [],
                "exact_match": True,
            },
            "operator_approval": {
                "approved": True,
                "approved_by": "operator",
                "approval_ref": approval_ref_placeholder,
            },
            "graph_trace_ids": [graph_trace_placeholder],
            "graph_query_trace_ids": [graph_trace_placeholder],
        },
        "verification": {
            "db_verified_pre_implementation_graph_trace": True,
            "dirty_scope": {
                "allowed_files": allowed_files,
                "dirty_files": [],
                "exact_match": True,
            },
            "operator_approval": {
                "approved": True,
                "approved_by": "operator",
                "approval_ref": approval_ref_placeholder,
            },
            "graph_trace_ids": [graph_trace_placeholder],
            "graph_query_trace_ids": [graph_trace_placeholder],
        },
        "artifact_refs": {
            "allowed_files": allowed_files,
            "operator_approval_ref": approval_ref_placeholder,
            "graph_trace_ids": [graph_trace_placeholder],
            "graph_query_trace_ids": [graph_trace_placeholder],
        },
        "route_token_ref": str(route_token_ref or "").strip(),
    }
    return {
        "schema_version": (
            "onboard_route_guide.parentless_direct_main."
            "copy_safe_pre_mutation_event.v1"
        ),
        "authority_schema_version": authority_schema["schema_version"],
        "mcp_tool": "observer_direct_mutation_exception",
        "copy_safe": True,
        "raw_route_token_required": False,
        "identity_ready": all(
            [
                arguments_template["project_id"],
                arguments_template["backlog_id"],
                arguments_template["task_id"],
                arguments_template["route_token_ref"],
                allowed_files,
            ]
        ),
        "executable": False,
        "replace_before_submit": [
            "payload.reason",
            "payload.operator_approval.approval_ref",
            "payload.graph_trace_ids",
            "payload.graph_query_trace_ids",
            "verification.operator_approval.approval_ref",
            "verification.graph_trace_ids",
            "verification.graph_query_trace_ids",
            "artifact_refs.operator_approval_ref",
            "artifact_refs.graph_trace_ids",
            "artifact_refs.graph_query_trace_ids",
        ],
        "arguments_template": arguments_template,
        "ordering": "submit after graph_query and before any mutation",
        "fail_closed_if_omitted": [
            *authority_schema["required_requirement_ids"],
            "payload.graph_trace_ids",
            "route_token_ref",
        ],
    }


