def _operator_supervised_direct_main_dev_world_authority() -> dict[str, Any]:
    """Resolve the exact loaded, non-stale 40008 candidate world."""

    if _runtime_plane() != "dev":
        return {}
    identity = _runtime_plane_identity()
    loaded = governance_loaded_runtime_identity(get_server_version())
    root_raw = str(identity.get("worktree_root") or "").strip()
    try:
        root = Path(root_raw).resolve(strict=True)
    except (OSError, RuntimeError, ValueError):
        root = Path()
    commit = str(identity.get("commit") or "").strip().lower()
    stable_anchor = str(
        identity.get("stable_anchor_commit") or ""
    ).strip().lower()
    loaded_commit = str(loaded.get("loaded_commit") or "").strip().lower()
    loaded_source_sha256 = str(
        loaded.get("loaded_source_sha256") or ""
    ).strip().lower()
    database_identity = (
        dict(identity.get("database_identity") or {})
        if isinstance(identity.get("database_identity"), Mapping)
        else {}
    )
    violations: list[str] = []
    if identity.get("status") != "ready":
        violations.append("runtime_plane_identity_not_ready")
    if identity.get("plane") != "dev":
        violations.append("runtime_plane_not_dev")
    if int(identity.get("port") or 0) != AC_DEV_SERVICE_PORT:
        violations.append("runtime_port_not_40008")
    if identity.get("bind_host") != AC_DEV_BIND_HOST:
        violations.append("runtime_bind_not_loopback")
    if identity.get("branch") != AC_DEV_BRANCH:
        violations.append("runtime_branch_not_dev")
    if root != _dev_exact_source_root():
        violations.append("runtime_worktree_root_not_exact_dev_root")
    if identity.get("worktree_dirty") is True:
        violations.append("runtime_worktree_dirty")
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", commit):
        violations.append("runtime_commit_invalid")
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", stable_anchor):
        violations.append("stable_anchor_invalid")
    if loaded.get("runtime_stale") is not False:
        violations.append("loaded_runtime_stale")
    if loaded_commit != commit:
        violations.append("loaded_runtime_commit_mismatch")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", loaded_source_sha256):
        violations.append("loaded_runtime_source_sha256_invalid")
    if not _ac_dev_database_identity_valid(database_identity):
        violations.append("dev_database_identity_invalid")
    core = {
        "schema_version": (
            "operator_supervised_direct_main.dev_runtime_world.v1"
        ),
        "accepted": not violations,
        "server_derived": True,
        "caller_claims_trusted": False,
        "runtime_plane": "dev",
        "runtime_port": AC_DEV_SERVICE_PORT,
        "bind_host": AC_DEV_BIND_HOST,
        "target_project_root": str(root) if root else "",
        "worktree_path": str(root) if root else "",
        "branch": AC_DEV_BRANCH,
        "target_ref": f"refs/heads/{AC_DEV_BRANCH}",
        "target_head_commit": commit,
        "stable_anchor_commit": stable_anchor,
        "database_identity": database_identity,
        "world_id": "ac-dev",
        "loaded_runtime_commit": loaded_commit,
        "loaded_runtime_source_sha256": loaded_source_sha256,
        "runtime_stale": bool(loaded.get("runtime_stale")),
        "violations": violations,
        "zero_write_projection": True,
    }
    core["namespace_hash"] = direct_main_dev_namespace_hash(core)
    world_hash = stable_sha256(core)
    authority = {
        **core,
        "world_hash": world_hash,
        "storage_contract_id": "operator_supervised_direct_main",
    }
    authority["authority_hash"] = stable_sha256(authority)
    if violations:
        raise GovernanceError(
            "ac_dev_direct_main_runtime_world_invalid",
            "dev Direct Main requires the exact loaded non-stale 40008 world",
            409,
            {
                **authority,
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    return authority


def _operator_supervised_direct_main_dev_selector_authority(
    conn,
    *,
    project_id: str,
    backlog_id: str,
) -> dict[str, Any]:
    """Discover exact dev selectors without trusting caller-shaped values."""

    repository_root = Path(__file__).resolve().parents[2]
    listing = _branch_service_git_output(
        repository_root,
        ["worktree", "list", "--porcelain"],
    )
    dev_rows: list[dict[str, str]] = []
    for block in listing.split("\n\n") if listing else []:
        row = {
            key: value.strip()
            for line in block.splitlines()
            for key, separator, value in [line.partition(" ")]
            if separator
        }
        if row.get("branch") == f"refs/heads/{AC_DEV_BRANCH}":
            dev_rows.append(row)
    dev_root = ""
    dev_head = ""
    if len(dev_rows) == 1:
        try:
            dev_root = str(Path(dev_rows[0]["worktree"]).resolve(strict=True))
        except (KeyError, OSError, RuntimeError, ValueError):
            dev_root = ""
        dev_head = str(dev_rows[0].get("HEAD") or "").strip().lower()
        if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", dev_head):
            dev_head = ""

    execution_ids: list[str] = []
    try:
        query = (
            "SELECT project_id, backlog_id, contract_id, "
            "contract_execution_id, record_json "
            "FROM contract_runtime_executions "
            "WHERE project_id=? AND contract_id=?"
        )
        rows = conn.execute(
            query,
            (project_id, "operator_supervised_direct_main"),
        ).fetchall()
    except sqlite3.Error:
        rows = []
    for row in rows:
        physical_project_id = str(row["project_id"] or "")
        physical_backlog_id = str(row["backlog_id"] or "")
        physical_contract_id = str(row["contract_id"] or "")
        execution_id = str(row["contract_execution_id"] or "").strip()
        try:
            record = json.loads(str(row["record_json"] or "{}"))
        except (TypeError, ValueError):
            continue
        metadata = record.get("metadata") if isinstance(record, Mapping) else {}
        binding = (
            metadata.get("operator_supervised_direct_main_runtime_binding")
            if isinstance(metadata, Mapping)
            and isinstance(
                metadata.get("operator_supervised_direct_main_runtime_binding"),
                Mapping,
            )
            else {}
        )
        world = (
            binding.get("runtime_world_authority")
            if isinstance(binding.get("runtime_world_authority"), Mapping)
            else {}
        )
        if (
            record.get("project_id") == project_id
            and record.get("contract_id")
            == "operator_supervised_direct_main"
            and physical_project_id == project_id
            and physical_backlog_id
            == str(record.get("backlog_id") or "").strip()
            and physical_contract_id == "operator_supervised_direct_main"
            and execution_id
            == str(record.get("contract_execution_id") or "").strip()
        ):
            execution_ids.append(execution_id)
    core = {
        "schema_version": (
            "operator_supervised_direct_main.dev_selector_authority.v1"
        ),
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "dev_branch": AC_DEV_BRANCH,
        "dev_refs": [AC_DEV_BRANCH, f"refs/heads/{AC_DEV_BRANCH}"],
        "dev_runtime_port": AC_DEV_SERVICE_PORT,
        "dev_worktree_root": dev_root,
        "dev_head_commit": dev_head,
        "dev_contract_execution_ids": sorted(set(execution_ids)),
        "unique_dev_worktree": len(dev_rows) == 1 and bool(dev_root and dev_head),
        "physical_namespace_verified": bool(execution_ids),
        "zero_write_projection": True,
    }
    return {**core, "authority_hash": stable_sha256(core)}


def _operator_supervised_direct_main_request_claim_values(
    request_body: Mapping[str, Any] | None,
    field: str,
) -> list[Any]:
    body = request_body if isinstance(request_body, Mapping) else {}
    raw = body.get(field)
    if isinstance(raw, Sequence) and not isinstance(
        raw, (str, bytes, bytearray)
    ):
        return list(raw)
    return [raw]


def _operator_supervised_direct_main_request_uses_dev_selector(
    request_body: Mapping[str, Any] | None,
    *,
    selector_authority: Mapping[str, Any] | None = None,
) -> bool:
    body = request_body if isinstance(request_body, Mapping) else {}
    authority = (
        selector_authority if isinstance(selector_authority, Mapping) else {}
    )

    dev_refs = set(authority.get("dev_refs") or ()) or {
        AC_DEV_BRANCH,
        f"refs/heads/{AC_DEV_BRANCH}",
    }
    if any(
        str(value or "").strip() in dev_refs
        for field in (
            "target_ref",
            "branch",
            "branch_ref",
            "requested_branch_ref",
        )
        for value in _operator_supervised_direct_main_request_claim_values(
            body, field
        )
    ):
        return True
    if any(
        int(value or 0)
        == int(authority.get("dev_runtime_port") or AC_DEV_SERVICE_PORT)
        for field in ("runtime_port", "port")
        for value in _operator_supervised_direct_main_request_claim_values(
            body, field
        )
        if str(value or "").strip().isdigit()
    ):
        return True
    dev_root = str(authority.get("dev_worktree_root") or "")
    if dev_root:
        for field in _dev_source_root_keys:
            for value in _operator_supervised_direct_main_request_claim_values(
                body, field
            ):
                raw = str(value or "").strip()
                if not raw:
                    continue
                try:
                    actual = str(Path(raw).expanduser().resolve(strict=True))
                except (OSError, RuntimeError, ValueError):
                    continue
                if actual == dev_root:
                    return True
    dev_head = str(authority.get("dev_head_commit") or "").strip().lower()
    if dev_head and any(
        str(value or "").strip().lower() == dev_head
        for field in (
            "target_head_commit",
            "head_commit",
            "candidate_commit_sha",
            "requested_commit",
            "commit_sha",
            "base_commit",
        )
        for value in _operator_supervised_direct_main_request_claim_values(
            body, field
        )
    ):
        return True
    dev_execution_ids = set(authority.get("dev_contract_execution_ids") or ())
    return bool(
        dev_execution_ids
        and any(
            str(value or "").strip() in dev_execution_ids
            for field in ("task_id", "contract_execution_id")
            for value in _operator_supervised_direct_main_request_claim_values(
                body, field
            )
        )
    )


def _operator_supervised_direct_main_request_mismatches(
    request_body: Mapping[str, Any] | None,
    *,
    execution_id: str,
    world_authority: Mapping[str, Any],
    selector_authority: Mapping[str, Any] | None = None,
) -> list[dict[str, str]]:
    """Reject caller attempts to redirect stable or dev runtime authority."""

    body = request_body if isinstance(request_body, Mapping) else {}
    plane = _runtime_plane()
    identity = _runtime_plane_identity()
    if world_authority:
        expected_root = str(world_authority.get("target_project_root") or "")
        expected_head = str(world_authority.get("target_head_commit") or "")
        expected_ref = str(world_authority.get("target_ref") or "")
        expected_branch = str(world_authority.get("branch") or "")
        expected_port = int(
            world_authority.get("runtime_port") or AC_DEV_SERVICE_PORT
        )
    elif plane == "stable":
        expected_root = str(identity.get("worktree_root") or "")
        loaded = governance_loaded_runtime_identity(get_server_version())
        expected_head = str(
            loaded.get("loaded_commit") or identity.get("commit") or ""
        ).strip().lower()
        expected_branch = str(identity.get("branch") or AC_STABLE_BRANCH)
        expected_ref = f"refs/heads/{expected_branch}"
        expected_port = AC_STABLE_SERVICE_PORT
    else:
        expected_root = ""
        expected_head = ""
        expected_branch = ""
        expected_ref = ""
        expected_port = 0
    enforce_loaded_authority = bool(world_authority) or plane == "stable"
    mismatches: list[dict[str, str]] = []
    if plane != "dev" and _operator_supervised_direct_main_request_uses_dev_selector(
        body,
        selector_authority=selector_authority,
    ):
        mismatches.append(
            {
                "field": "runtime_plane",
                "expected": "dev@127.0.0.1:40008",
                "actual": plane,
            }
        )
    for field in _dev_source_root_keys:
        for value in _operator_supervised_direct_main_request_claim_values(
            body, field
        ):
            raw = str(value or "").strip()
            if not raw or not enforce_loaded_authority:
                continue
            try:
                actual = str(Path(raw).expanduser().resolve(strict=True))
            except (OSError, RuntimeError, ValueError):
                actual = raw
            if actual != expected_root:
                mismatches.append(
                    {"field": field, "expected": expected_root, "actual": actual}
                )
    for field in (
        "target_head_commit",
        "head_commit",
        "candidate_commit_sha",
        "requested_commit",
        "commit_sha",
        "base_commit",
    ):
        for value in _operator_supervised_direct_main_request_claim_values(
            body, field
        ):
            actual = str(value or "").strip().lower()
            if actual and enforce_loaded_authority and actual != expected_head:
                mismatches.append(
                    {"field": field, "expected": expected_head, "actual": actual}
                )
    for field in (
        "target_ref",
        "branch",
        "branch_ref",
        "requested_branch_ref",
    ):
        for value in _operator_supervised_direct_main_request_claim_values(
            body, field
        ):
            actual = str(value or "").strip()
            if not actual:
                continue
            if not enforce_loaded_authority:
                continue
            allowed = {expected_ref, expected_branch}
            if not expected_ref or actual not in allowed:
                mismatches.append(
                    {"field": field, "expected": expected_ref, "actual": actual}
                )
    for field in ("runtime_port", "port"):
        for value in _operator_supervised_direct_main_request_claim_values(
            body, field
        ):
            actual_raw = str(value or "").strip()
            if not actual_raw or not enforce_loaded_authority:
                continue
            actual = int(actual_raw) if actual_raw.isdigit() else -1
            if actual != expected_port:
                mismatches.append(
                    {
                        "field": field,
                        "expected": str(expected_port),
                        "actual": actual_raw,
                    }
                )
    for field in ("task_id", "contract_execution_id"):
        for value in _operator_supervised_direct_main_request_claim_values(
            body, field
        ):
            actual = str(value or "").strip()
            if actual and actual != execution_id:
                mismatches.append(
                    {"field": field, "expected": execution_id, "actual": actual}
                )
    return mismatches


def _operator_supervised_direct_main_public_selector_mismatches(
    mismatches: Sequence[Mapping[str, Any]],
) -> list[dict[str, str]]:
    """Project mismatch fields and one-way hashes, never raw selector values."""

    return [
        {
            "field": str(item.get("field") or ""),
            "expected_value_hash": stable_sha256(
                {"value": str(item.get("expected") or "")}
            ),
            "actual_value_hash": stable_sha256(
                {"value": str(item.get("actual") or "")}
            ),
        }
        for item in mismatches
    ]


def _raise_operator_supervised_direct_main_selector_mismatch(
    *,
    mismatches: Sequence[Mapping[str, Any]],
    world_authority: Mapping[str, Any],
    execution_id: str,
    selector_request: Mapping[str, Any] | None,
    selector_authority: Mapping[str, Any] | None,
) -> NoReturn:
    """Raise one public-safe exact-world rejection for every Onboard role."""

    plane = _runtime_plane()
    raise GovernanceError(
        "ac_direct_main_runtime_candidate_identity_mismatch",
        "caller candidate identity does not match the loaded runtime world",
        409,
        {
            "identity_mismatches": (
                _operator_supervised_direct_main_public_selector_mismatches(
                    mismatches
                )
            ),
            "runtime_world_authority": {
                "schema_version": str(
                    world_authority.get("schema_version") or ""
                ),
                "runtime_plane": str(
                    world_authority.get("runtime_plane") or ""
                ),
                "runtime_port": int(
                    world_authority.get("runtime_port") or 0
                ),
                "namespace_hash": str(
                    world_authority.get("namespace_hash") or ""
                ),
                "world_hash": str(world_authority.get("world_hash") or ""),
                "authority_hash": str(
                    world_authority.get("authority_hash") or ""
                ),
                "server_derived": (
                    world_authority.get("server_derived") is True
                ),
                "caller_claims_trusted": False,
            },
            "contract_execution_id_hash": stable_sha256(
                {"contract_execution_id": execution_id}
            ),
            "runtime_plane": plane,
            "required_endpoint": (
                "http://127.0.0.1:40008"
                if plane == "dev"
                or _operator_supervised_direct_main_request_uses_dev_selector(
                    selector_request,
                    selector_authority=selector_authority,
                )
                else ""
            ),
            "zero_write_rejection": True,
            "writes_performed": False,
            "public_safe": True,
            "secret_safe": True,
        },
    )


def _require_onboard_dev_selector_endpoint(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    request_body: Mapping[str, Any] | None,
    role: str,
    work_type: str,
) -> dict[str, Any]:
    """Reject every exact dev authority selector before Onboard dispatch."""

    authority = _operator_supervised_direct_main_dev_selector_authority(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
    )
    if _runtime_plane() == "dev":
        has_explicit_selector = any(
            str(value or "").strip()
            for field in _onboard_runtime_selector_keys()
            for value in _operator_supervised_direct_main_request_claim_values(
                request_body,
                field,
            )
        )
        if not has_explicit_selector:
            return authority
        world_authority = (
            _operator_supervised_direct_main_dev_world_authority()
        )
        execution_id = ""
        task_claims = _runtime_context_service_dedupe(
            [
                str(value or "").strip()
                for field in ("task_id", "contract_execution_id")
                for value in _operator_supervised_direct_main_request_claim_values(
                    request_body, field,
                )
                if str(value or "").strip()
            ]
        )
        if len(task_claims) == 1 and backlog_id:
            records = _operator_supervised_direct_main_strict_records(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                contract_execution_id=task_claims[0],
            )
            if len(records) == 1:
                execution_id = str(
                    records[0].get("contract_execution_id") or ""
                ).strip()
            elif not records:
                definition = (
                    _operator_supervised_direct_main_fresh_definition()
                )
                revision = str(definition.get("revision") or "").strip()
                if revision:
                    execution_id = (
                        _operator_supervised_direct_main_execution_id(
                            project_id,
                            backlog_id,
                            revision=revision,
                            world_authority=world_authority,
                        )
                    )
        mismatches = _operator_supervised_direct_main_request_mismatches(
            request_body,
            execution_id=execution_id,
            world_authority=world_authority,
            selector_authority=authority,
        )
        if mismatches:
            _raise_operator_supervised_direct_main_selector_mismatch(
                mismatches=mismatches,
                world_authority=world_authority,
                execution_id=execution_id,
                selector_request=request_body,
                selector_authority=authority,
            )
        return authority
    if not _operator_supervised_direct_main_request_uses_dev_selector(
        request_body,
        selector_authority=authority,
    ):
        return authority
    raise GovernanceError(
        "ac_onboard_dev_selector_wrong_endpoint",
        "dev runtime selectors require the isolated 40008 Onboard endpoint",
        409,
        {
            "runtime_plane": _runtime_plane(),
            "requested_role": str(role or ""),
            "requested_work_type": str(work_type or ""),
            "required_endpoint": "http://127.0.0.1:40008",
            "dev_selector_authority": {
                "schema_version": str(authority.get("schema_version") or ""),
                "server_derived": authority.get("server_derived") is True,
                "caller_claims_trusted": False,
                "authority_hash": str(authority.get("authority_hash") or ""),
                "dev_branch": str(authority.get("dev_branch") or ""),
                "dev_runtime_port": int(
                    authority.get("dev_runtime_port") or AC_DEV_SERVICE_PORT
                ),
                "unique_dev_worktree": (
                    authority.get("unique_dev_worktree") is True
                ),
                "physical_namespace_verified": (
                    authority.get("physical_namespace_verified") is True
                ),
            },
            "zero_write_rejection": True,
            "writes_performed": False,
            "public_safe": True,
            "secret_safe": True,
        },
    )


def _operator_supervised_direct_main_fresh_definition() -> dict[str, Any]:
    """Resolve authority for a new Direct execution without caller pinning."""

    return _CONTRACT_DEFINITION_REGISTRY.resolve_for_new_execution(
        "operator_supervised_direct_main",
        version="v1",
    )


def _operator_supervised_direct_main_authority_source(revision: str) -> str:
    revision = str(revision or "").strip()
    return f"source_backed_operator_supervised_direct_main_{revision}"


_OPERATOR_SUPERVISED_DIRECT_MAIN_AUTHORITY_SOURCES = frozenset(
    _operator_supervised_direct_main_authority_source(revision)
    for revision in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
)


def _operator_supervised_direct_main_execution_id(
    project_id: str,
    backlog_id: str,
    *,
    revision: str = "",
    world_authority: Mapping[str, Any] | None = None,
) -> str:
    """Return the deterministic id for one selected Direct revision."""

    selected_revision = str(revision or "").strip()
    if not selected_revision:
        selected_revision = str(
            _operator_supervised_direct_main_fresh_definition().get(
                "revision"
            )
            or ""
        ).strip()

    identity_parts: list[Any] = [
        project_id,
        backlog_id,
        "operator_supervised_direct_main",
        "v1",
        selected_revision,
    ]
    authority = (
        dict(world_authority)
        if isinstance(world_authority, Mapping)
        else _operator_supervised_direct_main_dev_world_authority()
        if _runtime_plane() == "dev"
        else {}
    )
    if authority:
        identity_parts.extend(
            ("dev_runtime_namespace", authority["namespace_hash"])
        )
    return _contract_runtime_stable_id("cex-direct-main", *identity_parts)


def _operator_supervised_direct_main_record_matches_dev_world(
    record: Mapping[str, Any],
    world_authority: Mapping[str, Any],
) -> bool:
    if not world_authority:
        return True
    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    record_world = (
        binding.get("runtime_world_authority")
        if isinstance(binding.get("runtime_world_authority"), Mapping)
        else {}
    )
    identity_fields = (
        "schema_version", "accepted", "server_derived", "caller_claims_trusted",
        "runtime_plane", "runtime_port", "bind_host", "target_project_root",
        "worktree_path", "branch", "target_ref", "stable_anchor_commit",
        "database_identity", "world_id", "runtime_stale", "violations",
        "namespace_hash", "storage_contract_id",
    )
    if not (
        world_authority.get("accepted") is True
        and world_authority.get("runtime_plane") == "dev"
        and world_authority.get("runtime_port") == AC_DEV_SERVICE_PORT
        and world_authority.get("bind_host") == AC_DEV_BIND_HOST
        and world_authority.get("runtime_stale") is False
        and not world_authority.get("violations")
        and all(record_world.get(key) == world_authority.get(key)
                for key in identity_fields)
    ):
        return False
    current_commits = {
        str(world_authority.get(key) or "").strip().lower()
        for key in ("target_head_commit", "loaded_runtime_commit")
    }
    record_commits = {
        str(record_world.get(key) or "").strip().lower()
        for key in ("target_head_commit", "loaded_runtime_commit")
    }
    root = Path(str(world_authority.get("target_project_root") or ""))
    if (len(current_commits) != 1 or len(record_commits) != 1
            or not all(re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", commit)
                       for commit in current_commits | record_commits)):
        return False
    if record_commits == current_commits:
        return True
    return all(_git_commit_is_ancestor(root, commit, next(iter(current_commits)))
               for commit in record_commits)


def _operator_supervised_direct_main_strict_records(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    world_authority: Mapping[str, Any] | None = None,
    contract_execution_id: str = "",
) -> list[dict[str, Any]]:
    runtime = _contract_runtime(conn)
    world_authority = (
        dict(world_authority) if isinstance(world_authority, Mapping) else
        _operator_supervised_direct_main_dev_world_authority()
        if _runtime_plane() == "dev" else {}
    )
    records = runtime.store.list_by_backlog(
        project_id=project_id,
        backlog_id=backlog_id,
        contract_id="operator_supervised_direct_main",
        storage_contract_id=(
            str(world_authority.get("storage_contract_id") or "") or None
        ),
    )
    world_valid_records = [
        dict(record)
        for record in records
        if str(record.get("revision") or "").strip()
        in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        and isinstance(record.get("metadata"), Mapping)
        and isinstance(
            record["metadata"].get(
                "operator_supervised_direct_main_runtime_binding"
            ),
            Mapping,
        )
        and _operator_supervised_direct_main_record_matches_dev_world(
            record,
            world_authority,
        )
    ]
    if world_authority and records and not world_valid_records:
        raise GovernanceError(
            "ac_dev_direct_main_runtime_world_lineage_invalid",
            (
                "the loaded dev HEAD must preserve the active Direct Main "
                "namespace and descend from its immutable initial world"
            ),
            409,
            {
                "runtime_world_authority": dict(world_authority),
                "candidate_execution_ids": [
                    str(record.get("contract_execution_id") or "")
                    for record in records
                ],
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    return [
        record for record in world_valid_records
        if not contract_execution_id
        or str(record.get("contract_execution_id") or "").strip()
        == contract_execution_id
    ]

def _operator_supervised_direct_main_operational_terminal_selection(
    conn, *, project_id: str, backlog_id: str,
    caller_contract_execution_id: str = "", caller_route_token_ref: str = "",
    world_authority: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Classify one Direct predecessor without accepting caller custody."""
    def result(state: str, **extra: Any) -> dict[str, Any]:
        return {
            "schema_version": "operator_supervised_direct_main."
            "operational_terminal_selection.v1",
            "state": state, "server_derived": True,
            "caller_claims_trusted": False, "read_only": True, **extra,
        }
    def blocked(reason: str) -> dict[str, Any]:
        return result("blocked", reason=reason)
    def caller_matches(execution_id: str, route_ref: str) -> bool:
        return not (
            (caller_contract_execution_id
             and caller_contract_execution_id != execution_id)
            or (caller_route_token_ref and caller_route_token_ref != route_ref)
        )
    if _runtime_plane() != "dev":
        return blocked("runtime_plane")
    if project_id != "aming-claw":
        return blocked("project_scope")
    try:
        world = (
            dict(world_authority) if isinstance(world_authority, Mapping)
            else _operator_supervised_direct_main_dev_world_authority()
        )
        if not isinstance(world, Mapping) or world.get("accepted") is not True:
            return blocked("runtime_world")
        world = dict(world)
        row = conn.execute(
            "SELECT status FROM backlog_bugs WHERE bug_id=?", (backlog_id,)
        ).fetchone()
        records = _operator_supervised_direct_main_strict_records(
            conn, project_id=project_id, backlog_id=backlog_id,
            world_authority=world,
            contract_execution_id=caller_contract_execution_id,
        )
    except (ContractRuntimeError, GovernanceError, sqlite3.Error, TypeError):
        return blocked("authority_read_failed")
    if not row:
        return blocked("backlog_missing")
    if not records:
        family_exists = bool(
            caller_contract_execution_id
            and _operator_supervised_direct_main_strict_records(
                conn, project_id=project_id, backlog_id=backlog_id,
                world_authority=world,
            )
        )
        return (
            blocked(
                "caller_identity_mismatch"
                if family_exists else "caller_claim_without_family"
            )
            if caller_contract_execution_id or caller_route_token_ref
            else result("ordinary", contract_execution_ids=[])
        )
    if len(records) != 1:
        return blocked("direct_family_cardinality")
    execution_id = str(records[0].get("contract_execution_id") or "").strip()
    try:
        current = _contract_runtime(conn).current_record(
            execution_id, actor_role="observer"
        )
        route_ref = str(current.get("route_token_ref") or "").strip()
        route_authority = _operator_supervised_direct_main_route_authority(
            conn, project_id=project_id, backlog_id=backlog_id,
            contract_execution_id=execution_id, route_token_ref=route_ref,
        )
    except (ContractRuntimeError, KeyError, sqlite3.Error):
        return blocked("current_record_unavailable")
    metadata = current.get("metadata")
    binding = metadata.get(
        "operator_supervised_direct_main_runtime_binding"
    ) if isinstance(metadata, Mapping) else {}
    binding = binding if isinstance(binding, Mapping) else {}
    if not (
        execution_id
        and current.get("project_id") == project_id
        and current.get("backlog_id") == backlog_id
        and current.get("contract_id") == "operator_supervised_direct_main"
        and current.get("contract_execution_id") == execution_id
        and _operator_supervised_direct_main_record_matches_dev_world(
            current, world
        )
    ):
        return blocked("current_record_identity")
    if not (
        route_ref
        and route_authority.get("accepted") is True
        and route_authority.get("route_token_ref") == route_ref
        and route_authority.get("contract_execution_id") == execution_id
        and dict(binding.get("route_identity") or {})
        == dict(route_authority.get("route_identity") or {})
    ):
        return blocked("route_authority")
    completed = [
        line for line in current.get("completed_lines") or []
        if isinstance(line, Mapping)
    ]
    if not any(
        str(line.get("evidence_kind") or "") == "contract_line_bypass"
        for line in completed
    ):
        return (
            result("ordinary", contract_execution_ids=[execution_id])
            if caller_matches(execution_id, route_ref)
            else blocked("caller_identity_mismatch")
        )
    if len(completed) != 2:
        return blocked("terminal_prefix_shape")
    expected = (
        ("route_gate", "observer_bind_direct_scope", "contract_binding"),
        ("graph_first", "observer_graph_context", "graph_trace"),
    )
    for line, (stage_id, line_id, evidence_kind) in zip(completed, expected):
        if not _contract_runtime_strict_no_pass_bypass_audit(
            conn, project_id=project_id, record=current, line=line,
            expected_stage_id=stage_id, expected_line_id=line_id,
            expected_blocked_evidence_kind=evidence_kind,
            expected_event_task_ids={execution_id}, runtime_context_id="",
            task_id=execution_id, line_instance_id="",
            expected_actor_roles={"observer"},
            expected_blocked_owner_role="observer",
            line_instance_required=False,
        ):
            return blocked("terminal_prefix_audit")
    generation = _contract_runtime_no_pass_generation(current)
    second_payload = completed[1].get("payload")
    second_payload = second_payload if isinstance(second_payload, Mapping) else {}
    inherited = second_payload.get("no_pass_generation")
    inherited = inherited if isinstance(inherited, Mapping) else {}
    next_line = _contract_runtime_next_line(current)
    exact_generation = (
        str(row["status"] or "").upper() == "OPEN"
        and generation.get("root_generation_persisted") is True
        and generation.get("root_completed_line_index") == 0
        and generation.get("inherited_gate_count") == 1
        and generation.get("no_pass_claim") is True
        and generation.get("authoritative_pass_synthesized") is False
        and str(inherited.get("role") or "") == "inherited_gate"
        and inherited.get("generation_id") == generation.get("generation_id")
        and inherited.get("root_diagnostic_backlog_id")
        == generation.get("root_diagnostic_backlog_id")
        and str(next_line.get("stage_id") or "") == "pre_mutation"
        and str(next_line.get("line_id") or "")
        == "observer_direct_implementation_exception"
    )
    if not exact_generation:
        return blocked("terminal_generation_or_position")
    if not caller_matches(execution_id, route_ref):
        return blocked("caller_identity_mismatch")
    revision = str(current.get("revision") or "").strip()
    state_revision = int(current.get("execution_state_revision") or 0)
    chain_id = str(current.get("contract_chain_id") or "").strip()
    namespace_hash = str(world.get("namespace_hash") or "").strip()
    generation_id = str(generation.get("generation_id") or "").strip()
    diagnostic_id = str(generation.get("root_diagnostic_backlog_id") or "").strip()
    if not all((revision, state_revision, chain_id, namespace_hash,
                generation_id, diagnostic_id)):
        return blocked("successor_identity_incomplete")
    successor_id = _contract_runtime_stable_id(
        "cex-direct-main-successor", project_id, backlog_id, execution_id,
        revision, state_revision, chain_id, namespace_hash,
        generation_id, diagnostic_id,
    )
    return result(
        "exact_terminal_predecessor",
        predecessor_contract_execution_id=execution_id,
        expected_successor_contract_execution_id=successor_id,
        no_pass_generation_id=generation_id,
    )

def _operator_supervised_direct_main_selected_execution_identity(
    conn,
    *,
    project_id: str,
    backlog_id: str,
) -> dict[str, Any]:
    """Select one pinned record, otherwise the registry-owned fresh revision."""

    records = _operator_supervised_direct_main_strict_records(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
    )
    if len(records) > 1:
        return {
            "resolved": False,
            "ambiguous": True,
            "records": records,
            "candidate_execution_ids": [
                str(record.get("contract_execution_id") or "").strip()
                for record in records
            ],
        }
    if records:
        record = records[0]
        return {
            "resolved": True,
            "ambiguous": False,
            "source": "pinned_record",
            "contract_execution_id": str(
                record.get("contract_execution_id") or ""
            ).strip(),
            "revision": str(record.get("revision") or "").strip(),
            "record": record,
            "records": records,
        }
    definition = _operator_supervised_direct_main_fresh_definition()
    revision = str(definition.get("revision") or "").strip()
    return {
        "resolved": bool(revision),
        "ambiguous": False,
        "source": "fresh_registry_authority",
        "contract_execution_id": (
            _operator_supervised_direct_main_execution_id(
                project_id,
                backlog_id,
                revision=revision,
            )
            if revision
            else ""
        ),
        "revision": revision,
        "definition": definition,
        "records": [],
    }


def _operator_supervised_direct_main_generic_crud_rejection(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Project the pinned strict Direct facade-only write policy."""

    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    if not (
        str(record.get("contract_id") or "").strip()
        == "operator_supervised_direct_main"
        and str(record.get("revision") or "").strip()
        in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        and metadata.get("generic_crud_exposed") is False
        and binding.get("strict_runtime_binding_required") is True
    ):
        return {}
    revision = str(record.get("revision") or "").strip()
    result = _contract_runtime_unchanged_line_rejection(
        record,
        [
            f"operator_supervised_direct_main {revision} rejects agent-facing "
            "generic ContractRuntime line writes; use the exact timeline facade"
        ],
    )
    result.update(
        {
            "error": "operator_supervised_direct_main_generic_crud_forbidden",
            "required_facade": "task_timeline_append",
            "generic_contract_runtime_submit_line_allowed": False,
            "zero_write_rejection": True,
            "writes_performed": False,
        }
    )
    return result


def _operator_supervised_direct_main_route_authority_from_resolved(
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
    route_token_ref: str,
    row_files: Sequence[str],
    route: Mapping[str, Any] | None,
    route_error: str = "",
    source_free_operation: bool = False,
) -> dict[str, Any]:
    """Validate one resolved or freshly server-minted exact Direct route."""

    route = route if isinstance(route, Mapping) else {}
    route_token_ref = str(route_token_ref or "").strip()
    row_files = sorted(
        {str(path or "").strip() for path in row_files if str(path or "").strip()}
    )
    allowed_actions = sorted(
        {
            str(action or "").strip()
            for action in (route or {}).get("allowed_actions") or []
            if str(action or "").strip()
        }
    )
    expected_actions = sorted(
        _OPERATOR_SOURCE_FREE_ACTIONS
        if source_free_operation
        else _OPERATOR_SUPERVISED_DIRECT_MAIN_FULL_ROUND_ACTIONS
    )
    target_files = sorted(
        {
            str(path or "").strip()
            for path in (route or {}).get("target_files") or []
            if str(path or "").strip()
        }
    )
    owned_files = sorted(
        {
            str(path or "").strip()
            for path in (route or {}).get("owned_files") or []
            if str(path or "").strip()
        }
    )
    route_identity = {
        field: str((route or {}).get(field) or "").strip()
        for field in (
            "route_id",
            "route_context_hash",
            "prompt_contract_id",
            "prompt_contract_hash",
            "visible_injection_manifest_hash",
            "route_token_ref",
        )
    }
    accepted = bool(
        route
        and str(route.get("caller_role") or "").strip() == "observer"
        and allowed_actions == expected_actions
        and (not row_files if source_free_operation else bool(row_files))
        and target_files == row_files
        and owned_files == row_files
        and bool(route.get("source_free_operation")) is source_free_operation
        and bool(route.get("source_mutation_forbidden")) is source_free_operation
        and all(route_identity.values())
    )
    authority = {
        "schema_version": (
            "operator_supervised_direct_main.route_authority.v1"
        ),
        "accepted": accepted,
        "status": "accepted" if accepted else "rejected",
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": contract_execution_id,
        "route_token_ref": route_token_ref,
        "route_identity": route_identity,
        "row_declared_files": row_files,
        "route_target_files": target_files,
        "route_owned_files": owned_files,
        "allowed_actions": allowed_actions,
        "expected_allowed_actions": expected_actions,
        "route_resolution_error": route_error,
        "zero_write_on_failure": True,
        "historical_backfill_allowed": False,
        "source_free_operation": source_free_operation,
        "source_mutation_forbidden": source_free_operation,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _operator_supervised_direct_main_route_authority(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
    route_token_ref: str,
) -> dict[str, Any]:
    """Resolve the exact full-round route and closed backlog file fence."""

    from . import observer_route_context

    route_token_ref = str(route_token_ref or "").strip()
    row_files = sorted(_backlog_declared_direct_file_scope(conn, backlog_id))
    source_free_operation = bool(
        _backlog_source_free_operation_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        ).get("accepted")
    )
    try:
        route = observer_route_context.resolve_route_token_ref(
            conn,
            project_id=project_id,
            storage_project_id=_route_registry_storage_project_id(project_id),
            route_token_ref=route_token_ref,
            backlog_id=backlog_id,
            task_id=contract_execution_id,
        )
        route_error = ""
    except observer_route_context.RouteTokenRefError as exc:
        route = {}
        route_error = str(exc)
    return _operator_supervised_direct_main_route_authority_from_resolved(
        project_id=project_id,
        backlog_id=backlog_id,
        contract_execution_id=contract_execution_id,
        route_token_ref=route_token_ref,
        row_files=row_files,
        route=route,
        route_error=route_error,
        source_free_operation=source_free_operation,
    )


def _operator_supervised_direct_main_world_ref(
    *,
    project_id: str,
) -> dict[str, Any]:
    """Resolve the one canonical pre-mutation Git world for Direct rev2."""

    dev_world = (
        _operator_supervised_direct_main_dev_world_authority()
        if _runtime_plane() == "dev"
        else {}
    )
    if dev_world:
        authority = {
            "schema_version": (
                "operator_supervised_direct_main.pre_mutation_world_ref.v1"
            ),
            "accepted": True,
            "status": "accepted",
            "server_derived": True,
            "caller_claims_trusted": False,
            "project_id": project_id,
            "target_project_root": dev_world["target_project_root"],
            "worktree_path": dev_world["worktree_path"],
            "base_commit": dev_world["target_head_commit"],
            "target_head_commit": dev_world["target_head_commit"],
            "repository_root_exact": True,
            "resolution_error": "",
            "runtime_world_authority": dict(dev_world),
            "zero_write_on_failure": True,
        }
        authority["authority_hash"] = stable_sha256(authority)
        return authority
    try:
        project_root = Path(
            project_service.resolve_project_root(
                project_id,
                None,
                fallback_self=True,
            )
        ).resolve()
        top_level = _qa_git_bytes(
            project_root,
            ["rev-parse", "--show-toplevel"],
        )
        resolved_top_level = Path(
            top_level.stdout.decode(
                "utf-8", errors="surrogateescape"
            ).strip()
        ).resolve()
        head = _qa_git_bytes(
            project_root,
            ["rev-parse", "--verify", "HEAD^{commit}"],
        )
        head_commit = head.stdout.decode(
            "ascii", errors="ignore"
        ).strip().lower()
    except (OSError, TypeError, ValueError, _QACandidateOverlayError) as exc:
        project_root = Path()
        resolved_top_level = Path()
        head_commit = ""
        error = str(exc)
    else:
        error = ""
    accepted = bool(
        project_root
        and resolved_top_level == project_root
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", head_commit)
    )
    authority = {
        "schema_version": (
            "operator_supervised_direct_main.pre_mutation_world_ref.v1"
        ),
        "accepted": accepted,
        "status": "accepted" if accepted else "rejected",
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "target_project_root": str(project_root) if accepted else "",
        "worktree_path": str(project_root) if accepted else "",
        "base_commit": head_commit if accepted else "",
        "target_head_commit": head_commit if accepted else "",
        "repository_root_exact": bool(accepted),
        "resolution_error": error,
        "zero_write_on_failure": True,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _operator_supervised_direct_main_build_runtime_binding(
    *, project_id: str, backlog_id: str, execution_id: str,
    route_authority: Mapping[str, Any], world_ref: Mapping[str, Any],
    dev_world: Mapping[str, Any],
) -> dict[str, Any]:
    project_root = Path(str(world_ref["target_project_root"])).resolve()
    head_commit = str(world_ref["base_commit"])
    binding = {
        "schema_version": "operator_supervised_direct_main.runtime_binding.v1",
        "strict_runtime_binding_required": True,
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": execution_id,
        "route_identity": dict(route_authority["route_identity"]),
        "owned_files": list(route_authority["row_declared_files"]),
        "target_files": list(route_authority["row_declared_files"]),
        "target_project_root": str(project_root),
        "worktree_path": str(project_root),
        "base_commit": head_commit,
        "target_head_commit": head_commit,
        "pre_mutation_world_ref": dict(world_ref),
        "runtime_world_authority": dict(dev_world),
        "stable_visible_chain_projection_written": not bool(dev_world),
        "same_execution_retry_allowed": False,
        "same_generation_retry_allowed": False,
        "post_hoc_pass_backfill_allowed": False,
    }
    binding["binding_hash"] = stable_sha256(binding)
    return binding


def _operator_supervised_direct_main_create_fresh_runtime(
    conn,
    runtime: ContractRuntime,
    *,
    project_id: str,
    backlog_id: str,
    selected_revision: str,
    execution_id: str,
    route_token_ref: str,
    route_authority: Mapping[str, Any],
    world_ref: Mapping[str, Any],
    dev_world: Mapping[str, Any],
) -> dict[str, Any]:
    """Create one fresh Direct record from server-validated route authority."""

    current_world_ref = _operator_supervised_direct_main_world_ref(
        project_id=project_id,
    )
    if not (
        world_ref.get("accepted") is True
        and current_world_ref.get("accepted") is True
        and stable_sha256(dict(world_ref))
        == stable_sha256(dict(current_world_ref))
    ):
        raise GovernanceError(
            "operator_supervised_direct_main_world_ref_changed",
            "Direct Main pre-mutation world changed before execution start",
            422,
            {
                "expected_world_ref": dict(world_ref),
                "current_world_ref": current_world_ref,
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    binding = _operator_supervised_direct_main_build_runtime_binding(
        project_id=project_id, backlog_id=backlog_id, execution_id=execution_id,
        route_authority=route_authority, world_ref=world_ref,
        dev_world=dev_world,
    )
    record = runtime.start_execution(
        "operator_supervised_direct_main",
        version="v1",
        revision=selected_revision,
        project_id=project_id,
        backlog_id=backlog_id,
        actor_role="observer",
        contract_execution_id=execution_id,
        root_contract_execution_id=execution_id,
        contract_chain_id=_contract_runtime_stable_id(
            "cchain-direct-main",
            project_id,
            backlog_id,
            selected_revision,
            str(dev_world.get("namespace_hash") or ""),
        ),
        route_token_ref=route_token_ref,
        role_binding={
            "observer": "observer",
            "qa": "qa",
            "binding_source": (
                "operator_supervised_direct_main_route_authority"
            ),
        },
        backlog_lineage={
            "project_id": project_id,
            "backlog_id": backlog_id,
            "task_id": execution_id,
        },
        metadata={
            "facade": "observer_direct_mutation_exception",
            "generic_crud_exposed": False,
            "operator_supervised_direct_main_runtime_binding": binding,
            "operator_supervised_direct_main_route_authority": dict(
                route_authority
            ),
        },
    )
    if not dev_world:
        upsert_contract_chain_root_current_binding(conn, record)
    return runtime.current_record(execution_id, actor_role="observer")


def _operator_supervised_direct_main_start_runtime(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    route_token_ref: str,
    world_ref: Mapping[str, Any],
) -> dict[str, Any]:
    """Start fresh authority or read one immutable pinned Direct execution."""

    runtime = _contract_runtime(conn)
    dev_world = (
        _operator_supervised_direct_main_dev_world_authority()
        if _runtime_plane() == "dev"
        else {}
    )
    strict_records = _operator_supervised_direct_main_strict_records(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        contract_execution_id=task_id,
    )
    if len(strict_records) > 1:
        raise GovernanceError(
            "operator_supervised_direct_main_execution_not_unique",
            "Direct Main bounded row must resolve exactly one strict execution",
            409,
            {
                "candidate_execution_ids": [
                    str(record.get("contract_execution_id") or "")
                    for record in strict_records
                ],
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    if strict_records:
        selected_record = strict_records[0]
        selected_revision = str(
            selected_record.get("revision") or ""
        ).strip()
        execution_id = str(
            selected_record.get("contract_execution_id") or ""
        ).strip()
    else:
        fresh_definition = (
            _operator_supervised_direct_main_fresh_definition()
        )
        selected_revision = str(
            fresh_definition.get("revision") or ""
        ).strip()
        execution_id = _operator_supervised_direct_main_execution_id(
            project_id,
            backlog_id,
            revision=selected_revision,
            world_authority=dev_world,
        )
    if str(task_id or "").strip() != execution_id:
        raise GovernanceError(
            "operator_supervised_direct_main_execution_identity_mismatch",
            (
                "Direct Main requires the exact selected pinned execution id"
            ),
            409,
            {
                "field": "task_id",
                "expected": execution_id,
                "actual": str(task_id or "").strip(),
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    route_authority = _operator_supervised_direct_main_route_authority(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        contract_execution_id=execution_id,
        route_token_ref=route_token_ref,
    )
    if route_authority.get("accepted") is not True:
        raise GovernanceError(
            "operator_supervised_direct_main_route_binding_invalid",
            "Direct Main route, task, actions, and file fence must be exact",
            422,
            {
                **route_authority,
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )

    if strict_records:
        record = strict_records[0]
        metadata = record.get("metadata") or {}
        binding = metadata.get(
            "operator_supervised_direct_main_runtime_binding"
        ) or {}
        if (
            str(record.get("contract_execution_id") or "") != execution_id
            or str(record.get("route_token_ref") or "") != route_token_ref
            or dict(binding.get("route_identity") or {})
            != dict(route_authority.get("route_identity") or {})
        ):
            raise GovernanceError(
                "operator_supervised_direct_main_execution_binding_changed",
                "Direct Main execution route binding is immutable",
                409,
                {
                    "contract_execution_id": execution_id,
                    "zero_write_rejection": True,
                    "writes_performed": False,
                },
            )
        return runtime.current_record(execution_id, actor_role="observer")

    return _operator_supervised_direct_main_create_fresh_runtime(
        conn,
        runtime,
        project_id=project_id,
        backlog_id=backlog_id,
        selected_revision=selected_revision,
        execution_id=execution_id,
        route_token_ref=route_token_ref,
        route_authority=route_authority,
        world_ref=world_ref,
        dev_world=dev_world,
    )


def _operator_supervised_direct_main_pre_mutation_fingerprint(
    event: Mapping[str, Any],
) -> str:
    """Hash the complete normalized request admitted by the public facade."""

    admitted_payload = deepcopy(
        dict(event.get("payload") or {})
        if isinstance(event.get("payload"), Mapping)
        else {}
    )
    for generated_key in (
        "route_token_gate",
        "route_action_scope_lineage",
        "source_backed_contract_gate_authority",
        "contract_gate_decision",
        "agent_facing_decision_source",
        "meta_contract_gate_decision_source",
        "acceptance_scope_closure",
        "observer_direct_pre_mutation_authority",
        "direct_contract_runtime_binding",
        "direct_contract_runtime_lineage",
    ):
        admitted_payload.pop(generated_key, None)
    canonical = {
        "schema_version": (
            "operator_supervised_direct_main.pre_mutation_request.v1"
        ),
        "event": {
            **{
                key: deepcopy(event.get(key))
                for key in (
                    "project_id",
                    "backlog_id",
                    "task_id",
                    "event_type",
                    "event_kind",
                    "phase",
                    "status",
                    "decision",
                    "actor",
                    "verification",
                    "artifact_refs",
                )
            },
            "payload": admitted_payload,
        },
        "server_admitted_canonical_request": True,
        "generated_event_fields_included": False,
    }
    return stable_sha256(canonical)


def _operator_supervised_direct_main_facade_action_projection(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
    route_token_ref: str,
    target_files: Sequence[str],
    record: Mapping[str, Any],
    runtime_next: Mapping[str, Any],
    active_route_identity: Mapping[str, Any],
) -> dict[str, Any]:
    """Project the existing public facade for one strict Direct rev2 line.

    ContractRuntime remains the selector and evidence authority.  This helper
    only projects its first missing line onto the already-existing graph or
    timeline facade; it must never make the generic submit-line body executable
    for a contract whose pinned Rule forbids agent-facing generic CRUD.
    """

    line_id = str(runtime_next.get("line_id") or "").strip()
    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    bound_route_identity = (
        dict(binding.get("route_identity") or {})
        if isinstance(binding.get("route_identity"), Mapping)
        else {}
    )
    presented_route_identity = (
        dict(active_route_identity)
        if isinstance(active_route_identity, Mapping)
        else {}
    )
    route_identity = (
        presented_route_identity
        if (
            _observer_root_route_identity_complete(
                presented_route_identity
            )
            and str(
                presented_route_identity.get("route_token_ref") or ""
            ).strip()
            == str(route_token_ref or "").strip()
        )
        else bound_route_identity
    )
    completed_lines = [
        line
        for line in (
            record.get("completed_lines")
            or (
                record.get("execution_state", {}).get("completed_lines")
                if isinstance(record.get("execution_state"), Mapping)
                else []
            )
            or []
        )
        if isinstance(line, Mapping)
    ]
    implementation_commits = _runtime_context_service_dedupe(
        [
            str(line.get("commit_sha") or "").strip().lower()
            for line in completed_lines
            if str(line.get("line_id") or "").strip()
            == "observer_implementation"
            and re.fullmatch(
                r"[0-9a-f]{40}|[0-9a-f]{64}",
                str(line.get("commit_sha") or "").strip().lower(),
            )
        ]
    )
    implementation_commit = (
        implementation_commits[0]
        if len(implementation_commits) == 1
        else ""
    )
    base_projection = {
        "schema_version": (
            "onboard_route_guide.operator_supervised_direct_main."
            "facade_action_projection.v1"
        ),
        "line_id": line_id,
        "contract_execution_id": contract_execution_id,
        "source_of_authority": "contract_runtime_first_missing_line",
        "selector_owned_by_facade": False,
        "transport_projected_by_facade": True,
        "generic_contract_runtime_submit_line_allowed": False,
        "generic_contract_runtime_payload_executable": False,
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
    }

    if line_id in {
        "observer_bind_direct_scope",
        "observer_graph_context",
        "observer_direct_implementation_exception",
    }:
        guidance = _onboard_parentless_direct_main_pre_mutation_event_guidance(
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=contract_execution_id,
            route_token_ref=route_token_ref,
            target_files=target_files,
        )
        missing = list(guidance.get("replace_before_submit") or [])
        return {
            **base_projection,
            "facade_tool": "observer_direct_mutation_exception",
            "action_input": deepcopy(
                dict(guidance.get("arguments_template") or {})
            ),
            "copy_safe_body": deepcopy(
                dict(guidance.get("arguments_template") or {})
            ),
            "action_input_ready": bool(
                guidance.get("identity_ready") and not missing
            ),
            "action_input_missing_fields": missing,
            "replace_before_submit": missing,
            "graph_query_close_authority": (
                _onboard_parentless_direct_main_graph_query_guidance(
                    project_id=project_id,
                    backlog_id=backlog_id,
                    task_id=contract_execution_id,
                    route_token_ref=route_token_ref,
                    target_files=target_files,
                )
            ),
            "consumes_contract_runtime_lines": [
                "observer_bind_direct_scope",
                "observer_graph_context",
                "observer_direct_implementation_exception",
            ],
        }

    post_mutation = _onboard_parentless_direct_main_post_mutation_event_guidance(
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=contract_execution_id,
        route_token_ref=route_token_ref,
        target_files=target_files,
    )
    if line_id == "observer_implementation":
        template = dict(post_mutation.get("implementation") or {})
        body = deepcopy(dict(template.get("arguments_template") or {}))
        if isinstance(body.get("payload"), Mapping):
            body["payload"] = {
                **route_identity,
                **dict(body["payload"]),
            }
        missing = list(template.get("replace_before_submit") or [])
        return {
            **base_projection,
            "facade_tool": "task_timeline_append",
            "action_input": body,
            "copy_safe_body": deepcopy(body),
            "action_input_ready": bool(
                template.get("identity_ready") and not missing
            ),
            "action_input_missing_fields": missing,
            "replace_before_submit": missing,
            "same_value_replacements": deepcopy(
                dict(template.get("same_value_replacements") or {})
            ),
            "consumes_contract_runtime_lines": [
                "observer_implementation"
            ],
        }

    if line_id in {"qa_graph_context", "qa_independent_verification"}:
        commit_value = implementation_commit or (
            "<replace with the exact Direct implementation commit>"
        )
        qa_principal = "<copy the authenticated QA principal_id>"
        qa_graph_trace = "<copy a DB-verified QA graph_query trace_id>"
        test_command = "<copy one or more exact QA commands that passed>"
        body = {
            "project_id": project_id,
            "backlog_id": backlog_id,
            "task_id": contract_execution_id,
            "event_type": "qa.independent_verification",
            "event_kind": "independent_verification",
            "phase": "qa",
            "status": "passed",
            "actor": qa_principal,
            "commit_sha": commit_value,
            "verification": {
                "tests_run": [test_command],
                "diff_check": {"unexpected_files": []},
                "live_regression": {"status": "passed"},
            },
            "payload": {
                "graph_trace_ids": [qa_graph_trace],
                "observer_impersonation": False,
            },
        }
        qa_writer_binding = _contract_runtime_write_from_record(
            record,
            actor_role="qa",
            stage_id=str(runtime_next.get("stage_id") or "").strip(),
            line_id=line_id,
            evidence_kind=str(
                runtime_next.get("evidence_kind") or ""
            ).strip(),
        )
        qa_facade_binding = {
            field: qa_writer_binding.get(field)
            for field in (
                "contract_execution_id",
                "execution_state_revision",
                "stage_id",
                "line_id",
                "runtime_guide_hash",
            )
        }
        qa_facade_binding["direct_runtime_binding_hash"] = str(
            binding.get("binding_hash") or ""
        ).strip()
        body.update(qa_facade_binding)
        missing = [
            "actor",
            "verification.tests_run",
            "payload.graph_trace_ids",
        ]
        missing.extend(
            field
            for field, value in qa_facade_binding.items()
            if value in (None, "")
        )
        if not implementation_commit:
            missing.append("commit_sha")
        return {
            **base_projection,
            "facade_tool": "task_timeline_append",
            "action_input": body,
            "copy_safe_body": deepcopy(body),
            "action_input_ready": not missing,
            "action_input_missing_fields": missing,
            "replace_before_submit": missing,
            "qa_session_required": True,
            "qa_authored": True,
            "observer_may_submit": False,
            "managed_qa_session_token_required": True,
            "raw_qa_session_token_exposed": False,
            "consumes_contract_runtime_lines": [
                "qa_graph_context",
                "qa_independent_verification",
            ],
        }

    def close_ready_projection(
        reconcile_authority: Mapping[str, Any],
        *,
        consumes_lines: Sequence[str],
    ) -> dict[str, Any]:
        template = dict(post_mutation.get("close_ready") or {})
        body = deepcopy(dict(template.get("arguments_template") or {}))
        close_commit_placeholder = "<replace with the exact closing HEAD commit>"
        snapshot_placeholder = (
            "<replace with the active current-HEAD full reconcile snapshot id>"
        )
        snapshot_id = str(
            reconcile_authority.get("active_snapshot_id") or ""
        ).strip()

        def replace_exact(value: Any) -> Any:
            if isinstance(value, Mapping):
                return {
                    key: replace_exact(item) for key, item in value.items()
                }
            if isinstance(value, list):
                return [replace_exact(item) for item in value]
            if value == close_commit_placeholder and implementation_commit:
                return implementation_commit
            if value == snapshot_placeholder and snapshot_id:
                return snapshot_id
            return value

        body = replace_exact(body)
        if isinstance(body.get("payload"), Mapping):
            body["payload"] = {
                **route_identity,
                **dict(body["payload"]),
            }
        missing = ["verification.test_results.commands"]
        if not implementation_commit:
            missing.append("commit_sha")
        if not snapshot_id:
            missing.extend(
                [
                    "verification.full_reconcile_snapshot.snapshot_id",
                    "payload.full_reconcile_snapshot_id",
                ]
            )
        return {
            **base_projection,
            "facade_tool": "task_timeline_append",
            "action_input": body,
            "copy_safe_body": deepcopy(body),
            "action_input_ready": not missing,
            "action_input_missing_fields": missing,
            "replace_before_submit": missing,
            "current_full_reconcile_authority": dict(reconcile_authority),
            "consumes_contract_runtime_lines": list(consumes_lines),
            "reconcile_line_materialized_by_close_facade": (
                "observer_reconcile" in consumes_lines
            ),
        }

    if line_id == "observer_reconcile":
        reconcile_authority = (
            _operator_supervised_direct_main_current_full_reconcile_authority(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                contract_execution_id=contract_execution_id,
                record=record,
            )
            if implementation_commit
            else {}
        )
        if reconcile_authority:
            return close_ready_projection(
                reconcile_authority,
                consumes_lines=[
                    "observer_reconcile",
                    "observer_close_ready",
                ],
            )
        commit_value = implementation_commit or (
            "<replace with the exact Direct implementation commit>"
        )
        body = {
            "project_id": project_id,
            "target_commit_sha": commit_value,
            "activate": True,
            "require_clean": True,
            "semantic_enrich": False,
            "backlog_id": backlog_id,
            "task_id": contract_execution_id,
            "contract_execution_id": contract_execution_id,
            "observer_session_id": (
                "<copy the active observer_session_id>"
            ),
            "observer_route_token_ref": route_token_ref,
            "response_view": "compact",
        }
        missing = ["observer_session_id"]
        if not implementation_commit:
            missing.append("target_commit_sha")
        return {
            **base_projection,
            "facade_tool": "graph_current_full_reconcile",
            "action_input": body,
            "copy_safe_body": deepcopy(body),
            "action_input_ready": not missing,
            "action_input_missing_fields": missing,
            "replace_before_submit": missing,
            "requires_current_runtime_qa_position": True,
            "consumes_contract_runtime_lines": ["observer_reconcile"],
        }

    if line_id == "observer_close_ready":
        reconcile_authority = (
            _operator_supervised_direct_main_current_full_reconcile_authority(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                contract_execution_id=contract_execution_id,
                record=record,
            )
            if implementation_commit
            else {}
        )
        return close_ready_projection(
            reconcile_authority,
            consumes_lines=["observer_close_ready"],
        )

    return {
        **base_projection,
        "facade_tool": "",
        "action_input": {},
        "copy_safe_body": {},
        "action_input_ready": False,
        "action_input_missing_fields": ["supported_direct_rev2_line_id"],
        "status": "blocked_unknown_direct_rev2_line",
    }


def _operator_supervised_direct_main_public_runtime_record(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Hide the forbidden generic write body from the facade projection."""

    public_record = deepcopy(dict(record))
    runtime_guide = (
        public_record.get("runtime_guide")
        if isinstance(public_record.get("runtime_guide"), Mapping)
        else {}
    )
    next_action = (
        dict(runtime_guide.get("next_legal_action") or {})
        if isinstance(runtime_guide.get("next_legal_action"), Mapping)
        else {}
    )
    if next_action:
        for field in (
            "action_input",
            "copy_safe_body",
            "canonical_executable_action",
            "writer_role_safe_copy_payload",
        ):
            next_action.pop(field, None)
        next_action.update(
            {
                "executable": False,
                "facade_projection_required": True,
                "generic_contract_runtime_submit_line_allowed": False,
                "generic_contract_runtime_payload_executable": False,
            }
        )
        public_runtime_guide = dict(runtime_guide)
        for field in (
            "action_input",
            "copy_safe_body",
            "canonical_executable_action",
            "writer_role_safe_copy_payload",
        ):
            public_runtime_guide.pop(field, None)
        public_runtime_guide.update(
            {
                "generic_contract_runtime_submit_line_allowed": False,
                "generic_contract_runtime_payload_executable": False,
            }
        )
        public_record["runtime_guide"] = {
            **public_runtime_guide,
            "next_legal_action": next_action,
        }
    return public_record


def _onboard_operator_supervised_direct_main_runtime_response(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    route_token_ref: str,
    role: str,
    work_type: str,
    response_view: str,
    request_context: RequestContext | None = None,
    request_body: Mapping[str, Any] | None = None,
    request_selector_claims: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Project fresh Direct authority or one immutable pinned execution.

    Historical rows that already admitted the legacy parentless event retain
    their old projection.  A fresh row instead receives the deterministic
    Direct CEX identity before route issuance, so every later graph/timeline
    Fact can bind to the source-backed ContractRuntime execution.
    """

    if not (
        str(role or "").strip() == "observer"
        and str(work_type or "").strip()
        in {"direct_main", "operator_supervised_direct_main"}
    ):
        return {}
    dev_world = (
        _operator_supervised_direct_main_dev_world_authority()
        if _runtime_plane() == "dev"
        else {}
    )
    selector_request = (
        request_selector_claims
        if isinstance(request_selector_claims, Mapping)
        else request_body
    )
    execution_claims = _runtime_context_service_dedupe(
        [
            value for field in ("task_id", "contract_execution_id")
            for value in _operator_supervised_direct_main_request_claim_values(
                selector_request, field
            )
        ]
    )
    strict_records = _operator_supervised_direct_main_strict_records(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        contract_execution_id=(
            execution_claims[0] if len(execution_claims) == 1 else ""
        ),
    )
    historical_events = _onboard_parentless_direct_main_timeline_events(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        event_kind="observer_direct_implementation_exception",
    )
    if not dev_world and not strict_records and any(
        _onboard_parentless_direct_main_event_is_accepted(event)
        for event in historical_events
    ):
        return {}
    if len(strict_records) > 1:
        return {
            "schema_version": (
                "onboard_route_guide.operator_supervised_direct_main.v2"
            ),
            "ok": False,
            "status": "blocked",
            "error": (
                "operator_supervised_direct_main_execution_not_unique"
            ),
            "project_id": project_id,
            "backlog_id": backlog_id,
            "candidate_execution_ids": [
                str(record.get("contract_execution_id") or "")
                for record in strict_records
            ],
            "writes_performed": False,
        }

    if strict_records:
        selected_revision = str(
            strict_records[0].get("revision") or ""
        ).strip()
        execution_id = str(
            strict_records[0].get("contract_execution_id") or ""
        ).strip()
    else:
        fresh_definition = (
            _operator_supervised_direct_main_fresh_definition()
        )
        selected_revision = str(
            fresh_definition.get("revision") or ""
        ).strip()
        execution_id = _operator_supervised_direct_main_execution_id(
            project_id,
            backlog_id,
            revision=selected_revision,
            world_authority=dev_world,
        )
    selector_authority = _operator_supervised_direct_main_dev_selector_authority(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
    )
    claim_mismatches = _operator_supervised_direct_main_request_mismatches(
        selector_request,
        execution_id=execution_id,
        world_authority=dev_world,
        selector_authority=selector_authority,
    )
    if claim_mismatches:
        _raise_operator_supervised_direct_main_selector_mismatch(
            mismatches=claim_mismatches,
            world_authority=dev_world,
            execution_id=execution_id,
            selector_request=selector_request,
            selector_authority=selector_authority,
        )
    target_files = sorted(_backlog_declared_direct_file_scope(conn, backlog_id))
    source_free_authority = _backlog_source_free_operation_authority(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
    )
    source_free_operation = bool(
        source_free_authority.get("accepted") is True and not target_files
    )
    persisted_ref = (
        str(strict_records[0].get("route_token_ref") or "").strip()
        if strict_records
        else ""
    )
    requested_ref = str(route_token_ref or "").strip()
    strict_binding = (
        (
            strict_records[0].get("metadata") or {}
        ).get("operator_supervised_direct_main_runtime_binding")
        if strict_records
        and isinstance(strict_records[0].get("metadata"), Mapping)
        and isinstance(
            (strict_records[0].get("metadata") or {}).get(
                "operator_supervised_direct_main_runtime_binding"
            ),
            Mapping,
        )
        else {}
    )
    immutable_route_identity = (
        strict_binding.get("route_identity")
        if isinstance(strict_binding.get("route_identity"), Mapping)
        else {}
    )
    active_route_authority = (
        _operator_supervised_direct_main_active_route_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=execution_id,
            immutable_route_identity=immutable_route_identity,
            active_route_token_ref=requested_ref,
            expected_files=target_files,
        )
        if strict_records and requested_ref
        else {}
    )
    if (
        strict_records
        and requested_ref
        and active_route_authority.get("passed") is not True
    ):
        return {
            "schema_version": (
                "onboard_route_guide.operator_supervised_direct_main.v2"
            ),
            "ok": False,
            "status": "blocked",
            "error": "operator_supervised_direct_main_route_binding_changed",
            "project_id": project_id,
            "backlog_id": backlog_id,
            "contract_execution_id": execution_id,
            "expected_route_token_ref": persisted_ref,
            "requested_route_token_ref": requested_ref,
            "active_route_authority": active_route_authority,
            "writes_performed": False,
            "zero_write_rejection": True,
        }
    effective_ref = (
        requested_ref
        if strict_records and active_route_authority.get("passed") is True
        else persisted_ref
        if strict_records
        else requested_ref
    )
    route_authority = (
        _operator_supervised_direct_main_route_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            contract_execution_id=execution_id,
            route_token_ref=effective_ref,
        )
        if effective_ref
        else {}
    )
    if active_route_authority.get("passed") is True:
        route_authority = {
            **route_authority,
            "active_route_authority": active_route_authority,
            "immutable_route_identity_preserved": True,
        }
    route_ready = bool(route_authority.get("accepted") is True)
    if requested_ref and not route_ready and not strict_records:
        return {
            "schema_version": (
                "onboard_route_guide.operator_supervised_direct_main.v2"
            ),
            "ok": False,
            "status": "blocked",
            "error": "operator_supervised_direct_main_route_not_registered",
            "project_id": project_id,
            "backlog_id": backlog_id,
            "contract_execution_id": execution_id,
            "requested_route_token_ref": requested_ref,
            "required_action": "observer_route_context_issue",
            "writes_performed": False,
            "zero_write_rejection": True,
        }
    route_issue_body = {
        "project_id": project_id,
        "caller_role": "observer",
        "backlog_id": backlog_id,
        "task_id": execution_id,
        "target_files": target_files,
        "owned_files": target_files,
        "allowed_actions": list(
            _OPERATOR_SOURCE_FREE_ACTIONS
            if source_free_operation
            else _OPERATOR_SUPERVISED_DIRECT_MAIN_FULL_ROUND_ACTIONS
        ),
        "evidence_refs": [
            f"backlog:{backlog_id}",
            f"contract_runtime:{execution_id}",
            (
                "contract_definition:operator_supervised_direct_main.v1."
                f"{selected_revision}"
            ),
            *(
                [f"dev_runtime_world:{dev_world['world_hash']}"]
                if dev_world
                else []
            ),
        ],
    }
    if source_free_operation:
        # This fact is projected from the durable row/CEX authority.  The dev
        # issuer accepts only the byte-for-byte guide body, so a caller cannot
        # turn an ordinary route into an empty-fence route by adding this flag.
        route_issue_body["source_free_operation"] = True
    if route_ready:
        graph_guidance = _onboard_parentless_direct_main_graph_query_guidance(
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=execution_id,
            route_token_ref=effective_ref,
            target_files=target_files,
        )
        pre_mutation = (
            _onboard_parentless_direct_main_pre_mutation_event_guidance(
                project_id=project_id,
                backlog_id=backlog_id,
                task_id=execution_id,
                route_token_ref=effective_ref,
                target_files=target_files,
            )
        )
        next_action: dict[str, Any] = {
            "schema_version": "onboard_route_guide.next_action.v1",
            "id": "operator_supervised_direct_main_graph_first",
            "action": "observer_direct_mutation_exception",
            "interface": "observer_direct_mutation_exception",
            "mcp_tool": "observer_direct_mutation_exception",
            "owner_role": "observer",
            "requires_role": "observer",
            "requires_graph_first": True,
            "requires_operator_approval": True,
            "requires_route_token_ref": True,
            "action_input": dict(
                pre_mutation.get("arguments_template") or {}
            ),
            "copy_safe_body": dict(
                pre_mutation.get("arguments_template") or {}
            ),
            "action_input_ready": bool(pre_mutation.get("identity_ready")),
            "graph_query_close_authority": graph_guidance,
            "copy_safe_pre_mutation_event": pre_mutation,
            "source_of_authority": (
                "operator_supervised_direct_main.v1."
                f"{selected_revision}+route_registry"
            ),
        }
    else:
        next_action = {
            "schema_version": "onboard_route_guide.next_action.v1",
            "id": "operator_supervised_direct_main_route_issue",
            "action": "observer_route_context_issue",
            "interface": "observer_route_context_issue",
            "mcp_tool": "observer_route_context_issue",
            "owner_role": "observer",
            "requires_role": "observer",
            "action_input": dict(route_issue_body),
            "copy_safe_body": dict(route_issue_body),
            "action_input_ready": bool(target_files or source_free_operation),
            "action_input_missing_fields": (
                [] if target_files or source_free_operation else ["target_files"]
            ),
            "source_of_authority": (
                "operator_supervised_direct_main.v1."
                f"{selected_revision}+"
                + (
                    "backlog_source_free_operation_authority"
                    if source_free_operation
                    else "backlog_file_fence"
                )
            ),
        }

    current_record: dict[str, Any] = {}
    graph_bootstrap_projection: dict[str, Any] = {}
    if strict_records:
        current_record = _contract_runtime(conn).current_record(
            execution_id,
            actor_role="observer",
        )
        runtime_next = (
            current_record.get("runtime_guide", {}).get("next_legal_action")
            if isinstance(current_record.get("runtime_guide"), Mapping)
            else None
        )
        contract_runtime_first_missing_line = ""
        if isinstance(runtime_next, Mapping) and runtime_next:
            line_id = str(runtime_next.get("line_id") or "").strip()
            contract_runtime_first_missing_line = line_id
            facade_projection = (
                _operator_supervised_direct_main_facade_action_projection(
                    conn,
                    project_id=project_id,
                    backlog_id=backlog_id,
                    contract_execution_id=execution_id,
                    route_token_ref=effective_ref,
                    target_files=target_files,
                    record=current_record,
                    runtime_next=runtime_next,
                    active_route_identity=(
                        route_authority.get("route_identity")
                        if isinstance(
                            route_authority.get("route_identity"), Mapping
                        )
                        else {}
                    ),
                )
            )
            facade_tool = str(
                facade_projection.get("facade_tool") or ""
            ).strip()
            public_runtime_next = dict(runtime_next)
            for field in (
                "action_input",
                "copy_safe_body",
                "canonical_executable_action",
                "writer_role_safe_copy_payload",
            ):
                public_runtime_next.pop(field, None)
            public_runtime_next.update(
                {
                    "executable": False,
                    "facade_projection_required": True,
                    "generic_contract_runtime_submit_line_allowed": False,
                    "generic_contract_runtime_payload_executable": False,
                }
            )
            next_action = {
                **public_runtime_next,
                "schema_version": "onboard_route_guide.next_action.v1",
                "id": f"contract_runtime:{line_id}",
                "action": facade_tool,
                "interface": facade_tool,
                "mcp_tool": facade_tool,
                "owner_role": str(
                    runtime_next.get("owner_role")
                    or runtime_next.get("required_owner_role")
                    or "observer"
                ),
                "requires_role": str(
                    runtime_next.get("owner_role")
                    or runtime_next.get("required_owner_role")
                    or "observer"
                ),
                "action_input": deepcopy(
                    dict(facade_projection.get("action_input") or {})
                ),
                "copy_safe_body": deepcopy(
                    dict(facade_projection.get("copy_safe_body") or {})
                ),
                "action_input_ready": bool(
                    facade_projection.get("action_input_ready")
                ),
                "action_input_missing_fields": list(
                    facade_projection.get("action_input_missing_fields")
                    or []
                ),
                "replace_before_submit": list(
                    facade_projection.get("replace_before_submit") or []
                ),
                "facade_action_projection": facade_projection,
                "contract_runtime_next_legal_action": public_runtime_next,
                "source_of_authority": "contract_runtime_first_missing_line",
                "selector_owned_by_facade": False,
                "transport_projected_by_facade": True,
                "generic_contract_runtime_submit_line_allowed": False,
                "generic_contract_runtime_payload_executable": False,
            }
            graph_query_close_authority = facade_projection.get(
                "graph_query_close_authority"
            )
            if isinstance(graph_query_close_authority, Mapping):
                next_action["graph_query_close_authority"] = deepcopy(
                    dict(graph_query_close_authority)
                )
        else:
            next_action = None

        if (
            _runtime_plane() == "dev"
            and route_ready
            and contract_runtime_first_missing_line
            == "observer_graph_context"
        ):
            try:
                graph_readiness = _dev_graph_zero_write_readiness_projection(
                    conn,
                    project_id=project_id,
                )
            except GovernanceError as exc:
                graph_bootstrap_projection = {
                    "schema_version": "onboard_route_guide.dev_local_graph_bootstrap.v1",
                    "state": "incompatible",
                    "local_active_graph_present": False,
                    "graph_query_ready": False,
                    "current_full_reconcile_ready": False,
                    "error": exc.code,
                    "diagnostics": dict(exc.details),
                    "writes_performed": False,
                }
                next_action = {
                    "schema_version": "onboard_route_guide.next_action.v1",
                    "id": "dev_local_graph_bootstrap_incompatible",
                    "action": (
                        "refresh_onboard_route_guide_after_graph_schema_repair"
                    ),
                    "mcp_tool": "onboard_route_guide",
                    "action_input_ready": False,
                    "query_ready": False,
                    "current_full_reconcile_ready": False,
                }
            else:
                from . import graph_snapshot_store as _graph_store

                active_snapshot = (
                    _graph_store.get_active_graph_snapshot(conn, project_id)
                    if graph_readiness is None
                    else {}
                ) or {}
                if (
                    active_snapshot
                    and active_snapshot.get("status") == "active"
                    and active_snapshot.get("snapshot_kind") == "full"
                    and str(active_snapshot.get("commit_sha") or "").lower()
                    == str(dev_world.get("target_head_commit") or "").lower()
                ):
                    active_binding = (
                        _graph_store._current_full_snapshot_provenance_binding(
                            conn,
                            project_id,
                            active_snapshot,
                        )
                    )
                else:
                    active_binding = {}
                exact_active = bool(
                    active_snapshot
                    and active_snapshot.get("status") == "active"
                    and active_snapshot.get("snapshot_kind") == "full"
                    and str(active_snapshot.get("commit_sha") or "").lower()
                    == str(dev_world.get("target_head_commit") or "").lower()
                    and active_binding.get("verified") is True
                )
                if exact_active:
                    graph_bootstrap_projection = {
                        "schema_version": "onboard_route_guide.dev_local_graph_bootstrap.v1",
                        "state": "exact_active",
                        "materialization_required": False,
                        "local_active_graph_present": True,
                        "graph_query_ready": True,
                        "current_full_reconcile_ready": False,
                        "active_snapshot_id": str(
                            active_snapshot.get("snapshot_id") or ""
                        ),
                        "writes_performed": False,
                    }
                else:
                    bootstrap_auth: dict[str, Any] = {}
                    auth_error = ""
                    if request_context is not None:
                        try:
                            bootstrap_auth = _require_current_full_reconcile_auth(
                                request_context,
                                conn,
                                "graph-governance.reconcile.current-full",
                                accepted_route_actions=(
                                    "graph_current_full_reconcile",
                                ),
                            )
                        except (GovernanceError, PermissionDeniedError) as exc:
                            auth_error = str(
                                getattr(exc, "code", "")
                                or type(exc).__name__
                            )
                    else:
                        auth_error = "request_context_unavailable"
                    bootstrap_qa_preflight = (
                        _operator_supervised_direct_main_reconcile_qa_preflight_authority(
                            conn,
                            project_id=project_id,
                            target_commit=str(
                                dev_world.get("target_head_commit") or ""
                            ),
                            current_full_auth=bootstrap_auth,
                        )
                    )
                    bootstrap_authority = (
                        _dev_direct_graph_bootstrap_reconcile_authority(
                            conn,
                            project_id=project_id,
                            auth=bootstrap_auth,
                            direct_main_qa_preflight=(
                                bootstrap_qa_preflight
                            ),
                        )
                    )
                    action_input = dict(
                        bootstrap_authority.get("copy_safe_action_input") or {}
                    )
                    eligible = bool(
                        bootstrap_authority.get("eligible") is True
                        and action_input
                    )
                    descendant_predecessor = bool(
                        bootstrap_authority.get(
                            "same_wip_descendant_active_predecessor"
                        )
                        is True
                    )
                    graph_bootstrap_projection = {
                        "schema_version": "onboard_route_guide.dev_local_graph_bootstrap.v1",
                        "state": (
                            "same_wip_descendant_active_predecessor"
                            if descendant_predecessor
                            else (
                                "incompatible"
                                if active_snapshot
                                else (
                                    "materialization_required_no_local_active"
                                    if graph_readiness is not None
                                    else "exact_schema_no_local_active"
                                )
                            )
                        ),
                        "materialization_required": bool(
                            bootstrap_authority.get("materialization_required")
                        ),
                        "exact_schema_no_local_active": bool(
                            bootstrap_authority.get(
                                "exact_schema_no_local_active"
                            )
                        ),
                        "local_active_graph_present": bool(active_snapshot),
                        "same_wip_descendant_active_predecessor": (
                            descendant_predecessor
                        ),
                        "active_predecessor_snapshot_id": str(
                            bootstrap_authority.get(
                                "active_predecessor_snapshot_id"
                            )
                            or ""
                        ),
                        "graph_query_ready": False,
                        "current_full_reconcile_ready": eligible,
                        "contract_runtime_first_missing_line": str(
                            bootstrap_authority.get(
                                "contract_runtime_first_missing_line"
                            )
                            or ""
                        ),
                        "route_session_authority_verified": bool(
                            bootstrap_authority.get(
                                "route_session_authority_verified"
                            )
                        ),
                        "route_session_authority_error": auth_error,
                        "runtime_custody_verified": bool(
                            bootstrap_authority.get(
                                "runtime_custody_verified"
                            )
                        ),
                        "bootstrap_authority": dict(bootstrap_authority),
                        "owner_states": dict(
                            (graph_readiness or {}).get("owner_states") or {}
                        ),
                        "planned_objects": list(
                            (graph_readiness or {}).get("planned_objects") or []
                        ),
                        "writes_performed": False,
                        "contract_runtime_line_advanced": False,
                    }
                    if active_snapshot and not descendant_predecessor:
                        graph_bootstrap_projection["error"] = (
                            "exact_active_current_full_required"
                        )
                    if eligible:
                        next_action = {
                            "schema_version": "onboard_route_guide.next_action.v1",
                            "id": "dev_local_graph_current_full_reconcile",
                            "action": "graph_current_full_reconcile",
                            "mcp_tool": "graph_current_full_reconcile",
                            "requires_role": "observer",
                            "action_input": dict(action_input),
                            "copy_safe_body": dict(action_input),
                            "action_input_ready": True,
                            "graph_query_deferred": True,
                            "query_ready": False,
                            "contract_runtime_line_advanced": False,
                            "authorizes_write": False,
                            "synthesizes_qa": False,
                            "synthesizes_pass": False,
                        }
                    elif active_snapshot:
                        next_action = {
                            "schema_version": "onboard_route_guide.next_action.v1",
                            "id": "dev_local_graph_active_incompatible",
                            "action": "refresh_onboard_route_guide_after_graph_repair",
                            "mcp_tool": "onboard_route_guide",
                            "action_input_ready": False,
                            "query_ready": False,
                            "current_full_reconcile_ready": False,
                        }
                    else:
                        next_action = {
                            "schema_version": "onboard_route_guide.next_action.v1",
                            "id": "dev_local_graph_bootstrap_blocked",
                            "action": "refresh_onboard_route_guide_after_correcting_graph_bootstrap_authority",
                            "mcp_tool": "onboard_route_guide",
                            "action_input_ready": False,
                            "graph_query_deferred": True,
                            "query_ready": False,
                            "current_full_reconcile_ready": False,
                        }

    public_current_record = (
        _operator_supervised_direct_main_public_runtime_record(current_record)
        if current_record
        else {}
    )

    response = {
        "schema_version": (
            "onboard_route_guide.operator_supervised_direct_main.v2"
        ),
        "ok": True,
        "response_view": str(response_view or "full"),
        "project_id": project_id,
        "backlog_id": backlog_id,
        "selected_role": "observer",
        "selected_work_type": "operator_supervised_direct_main",
        "selected_backlog_source": "backlog_row",
        "contract_execution_id": execution_id,
        "contract_id": "operator_supervised_direct_main",
        "contract_version": "v1",
        "contract_revision": selected_revision,
        "runtime_world_authority": dict(dev_world),
        "dev_world_partitioned": bool(dev_world),
        "source_backed_contract_selected": True,
        "onboard_service_proxy_selected": False,
        "target_files": target_files,
        "source_free_operation_authority": dict(source_free_authority),
        "route_authority": dict(route_authority),
        "observer_route_context_issue": {
            "required": not route_ready,
            "mcp_tool": "observer_route_context_issue",
            "copy_safe_body": dict(route_issue_body),
            "bind_response_field": "route_token_ref",
        },
        "next_legal_action": next_action,
        "contract_runtime_current": public_current_record,
        "position_skippable": False,
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
    }
    if graph_bootstrap_projection:
        response["dev_local_graph_bootstrap"] = graph_bootstrap_projection
    return response


def _ac_dev_direct_route_issue_rejection(
    *,
    code: str,
    message: str,
    body: Mapping[str, Any] | None = None,
    expected_body: Mapping[str, Any] | None = None,
    extra: Mapping[str, Any] | None = None,
) -> GovernanceError:
    """Build one secret-safe physical-zero-write bootstrap rejection."""

    details = {
        "schema_version": "ac_dev_direct_route_bootstrap.rejection.v1",
        "runtime_plane": "dev",
        "required_endpoint": "http://127.0.0.1:40008",
        "request_body_hash": stable_sha256(dict(body or {})),
        "expected_body_hash": stable_sha256(dict(expected_body or {})),
        "zero_write_rejection": True,
        "writes_performed": False,
        "mutation_performed": False,
        "contract_runtime_mutated": False,
        "route_registry_mutated": False,
        "public_safe": True,
        "secret_safe": True,
        "raw_route_token_exposed": False,
    }
    details.update(dict(extra or {}))
    return GovernanceError(code, message, 409, details)


def _ac_dev_direct_route_issue_precheck(
    conn,
    *,
    project_id: str,
    body: Mapping[str, Any],
    query: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Prove one request is exactly the current guide-issued Direct route action."""

    if _runtime_plane() != "dev" or project_id != "aming-claw":
        raise _ac_dev_direct_route_issue_rejection(
            code="ac_dev_direct_route_bootstrap_wrong_runtime",
            message="Direct route bootstrap is confined to AC dev runtime",
            body=body,
        )
    backlog_id = str(body.get("backlog_id") or "").strip()
    task_id = str(body.get("task_id") or "").strip()
    if not backlog_id or not task_id:
        raise _ac_dev_direct_route_issue_rejection(
            code="ac_dev_direct_route_bootstrap_identity_incomplete",
            message="guide-bound Direct route bootstrap identity is incomplete",
            body=body,
            extra={
                "missing_fields": [
                    field
                    for field, value in (
                        ("backlog_id", backlog_id),
                        ("task_id", task_id),
                    )
                    if not value
                ]
            },
        )
    selector_claims = _onboard_runtime_selector_claims(body, query)
    guide = _onboard_operator_supervised_direct_main_runtime_response(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        route_token_ref="",
        role="observer",
        work_type="operator_supervised_direct_main",
        response_view="full",
        request_body=body,
        request_selector_claims=selector_claims,
    )
    issue_projection = (
        guide.get("observer_route_context_issue")
        if isinstance(guide.get("observer_route_context_issue"), Mapping)
        else {}
    )
    expected_body = (
        dict(issue_projection.get("copy_safe_body") or {})
        if isinstance(issue_projection.get("copy_safe_body"), Mapping)
        else {}
    )
    if not expected_body or dict(body) != expected_body:
        raise _ac_dev_direct_route_issue_rejection(
            code="ac_dev_direct_route_bootstrap_not_guide_bound",
            message=(
                "dev route issuance requires the exact current guide copy-safe body"
            ),
            body=body,
            expected_body=expected_body,
            extra={
                "contract_execution_id_hash": stable_sha256(
                    {
                        "contract_execution_id": str(
                            guide.get("contract_execution_id") or ""
                        )
                    }
                ),
                "guide_world_hash": str(
                    (guide.get("runtime_world_authority") or {}).get(
                        "world_hash"
                    )
                    if isinstance(
                        guide.get("runtime_world_authority"), Mapping
                    )
                    else ""
                ),
            },
        )
    world = (
        dict(guide.get("runtime_world_authority") or {})
        if isinstance(guide.get("runtime_world_authority"), Mapping)
        else {}
    )
    if not world or world.get("accepted") is not True:
        raise _ac_dev_direct_route_issue_rejection(
            code="ac_dev_direct_route_bootstrap_world_invalid",
            message="dev route bootstrap requires one exact loaded runtime world",
            body=body,
            expected_body=expected_body,
        )
    return {
        "schema_version": "ac_dev_direct_route_bootstrap.precheck.v1",
        "accepted": True,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "task_id": task_id,
        "guide": guide,
        "expected_body": expected_body,
        "world_authority": world,
        "selected_revision": str(guide.get("contract_revision") or "").strip(),
        "zero_write_projection": True,
    }


def _ac_dev_completed_source_free_route_issue_precheck(
    conn,
    *,
    project_id: str,
    body: Mapping[str, Any],
) -> dict[str, Any]:
    """Rebuild one completed-parent operation route without Direct authority."""

    backlog_id = str(body.get("backlog_id") or "").strip()
    task_id = str(body.get("task_id") or "").strip()
    authority = _backlog_source_free_operation_authority(
        conn, project_id=project_id, backlog_id=backlog_id
    )
    expected_task_id = _onboard_service_execution_id(project_id, backlog_id)
    projection = _contract_chain_current_projection(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        rebuild_if_missing=False,
    )
    resume = _onboard_runtime_resume_from_current_projection(projection)
    action = _onboard_route_guide_completed_next_action(
        role="observer",
        work_type="system_operation",
        runtime_resume=resume,
        backlog_row_status="OPEN",
        project_id=project_id,
        backlog_id=backlog_id,
        route_token_ref="",
        target_files=(),
        source_free_operation_authority=authority,
    )
    expected_body = (
        dict(action.get("copy_safe_body") or {})
        if isinstance(action.get("copy_safe_body"), Mapping)
        else {}
    )
    accepted = bool(
        _runtime_plane() == "dev"
        and project_id == "aming-claw"
        and authority.get("accepted") is True
        and _onboard_runtime_resume_is_complete(resume)
        and task_id == expected_task_id
        and str(resume.get("current_contract_execution_id") or "")
        == expected_task_id
        and str(resume.get("root_contract_execution_id") or "")
        == expected_task_id
        and action.get("id") == "completed_system_operation_route_issue"
        and expected_body
        and dict(body) == expected_body
    )
    if not accepted:
        raise _ac_dev_direct_route_issue_rejection(
            code="ac_dev_completed_source_free_route_not_guide_bound",
            message=(
                "completed source-free route issuance requires the exact current "
                "guide copy-safe body and completed onboard-service parent"
            ),
            body=body,
            expected_body=expected_body,
            extra={"contract_runtime_mutated": False},
        )
    world = _operator_supervised_direct_main_dev_world_authority()
    if not world or world.get("accepted") is not True:
        raise _ac_dev_direct_route_issue_rejection(
            code="ac_dev_completed_source_free_route_world_invalid",
            message="completed source-free route requires the loaded AC dev world",
            body=body,
            expected_body=expected_body,
        )
    return {
        "accepted": True,
        "backlog_id": backlog_id,
        "task_id": task_id,
        "expected_body": expected_body,
        "world_authority": dict(world),
    }


def _ac_dev_completed_source_free_route_issue_precheck_from_request(
    *, project_id: str, body: Mapping[str, Any]
) -> dict[str, Any]:
    conn = get_connection(project_id)
    try:
        return _ac_dev_completed_source_free_route_issue_precheck(
            conn, project_id=project_id, body=body
        )
    finally:
        conn.close()


def _handle_ac_dev_completed_source_free_route_context_issue(
    ctx: RequestContext,
    *,
    project_id: str,
    body: Mapping[str, Any],
) -> dict[str, Any]:
    """Atomically persist only the completed-parent operation route."""

    from . import observer_route_context

    conn = get_connection(project_id)
    try:
        _ac_dev_completed_source_free_route_issue_precheck(
            conn, project_id=project_id, body=body
        )
        with sqlite_write_lock():
            conn.execute("BEGIN IMMEDIATE")
            try:
                precheck = _ac_dev_completed_source_free_route_issue_precheck(
                    conn, project_id=project_id, body=body
                )
                backlog_id = str(precheck["backlog_id"])
                task_id = str(precheck["task_id"])
                expected_body = dict(precheck["expected_body"])
                storage_project_id = _route_registry_storage_project_id(project_id)
                rows = conn.execute(
                    "SELECT route_token_ref FROM observer_route_token_refs "
                    "WHERE project_id=? AND backlog_id=? AND task_id=?",
                    (storage_project_id, backlog_id, task_id),
                ).fetchall()
                if len(rows) > 1:
                    raise _ac_dev_direct_route_issue_rejection(
                        code="ac_dev_completed_source_free_route_ambiguous",
                        message="completed source-free operation route is not unique",
                        body=body,
                    )
                if rows:
                    route_token_ref = str(_row_get(rows[0], "route_token_ref", ""))
                    token = observer_route_context.resolve_route_token_ref(
                        conn,
                        project_id=project_id,
                        storage_project_id=storage_project_id,
                        route_token_ref=route_token_ref,
                        backlog_id=backlog_id,
                        task_id=task_id,
                    )
                    if (
                        not isinstance(token, Mapping)
                        or list(token.get("target_files") or []) != []
                        or list(token.get("owned_files") or []) != []
                        or list(token.get("allowed_actions") or [])
                        != list(_OPERATOR_SOURCE_FREE_ACTIONS)
                        or not set(expected_body.get("evidence_refs") or []).issubset(
                            set(token.get("evidence_refs") or [])
                        )
                        or token.get("source_free_operation") is not True
                    ):
                        raise _ac_dev_direct_route_issue_rejection(
                            code="ac_dev_completed_source_free_route_replay_mismatch",
                            message="existing operation route does not match current guide",
                            body=body,
                            expected_body=expected_body,
                        )
                    issued = {
                        "route_token": dict(token),
                        "route_token_ref": route_token_ref,
                        "merge_queue_id": observer_route_context.derive_merge_queue_id(token),
                        "provider": {},
                    }
                    conn.rollback()
                    response = _ac_dev_direct_route_issue_response(
                        project_id=project_id,
                        issued=issued,
                        idempotent_replay=True,
                        contract_execution_id=task_id,
                    )
                    response["atomic_route_and_contract_materialization"] = False
                    response["contract_runtime_mutated"] = False
                    return response
                world = dict(precheck["world_authority"])
                issued = observer_route_context.issue_observer_write_route_context(
                    project_id=project_id,
                    backlog_id=backlog_id,
                    task_id=task_id,
                    target_files=[],
                    allowed_actions=list(_OPERATOR_SOURCE_FREE_ACTIONS),
                    evidence_refs=list(expected_body.get("evidence_refs") or []),
                    project_root=Path(str(world.get("target_project_root") or "")),
                    source_free_operation=True,
                )
                token = dict(issued.get("route_token") or {})
                token["owned_files"] = []
                route_token_ref = str(issued.get("route_token_ref") or "").strip()
                observer_route_context.persist_route_token_ref(
                    conn,
                    project_id=project_id,
                    storage_project_id=storage_project_id,
                    route_token_ref=route_token_ref,
                    token=token,
                )
                if conn.in_transaction:
                    conn.commit()
            except Exception:
                if conn.in_transaction:
                    conn.rollback()
                raise
        issued = {**dict(issued), "route_token": token}
        response = _ac_dev_direct_route_issue_response(
            project_id=project_id,
            issued=issued,
            idempotent_replay=False,
            contract_execution_id=task_id,
        )
        response["atomic_route_and_contract_materialization"] = False
        response["contract_runtime_mutated"] = False
        return response
    finally:
        conn.close()


def _ac_dev_direct_route_issue_precheck_from_request(
    *,
    project_id: str,
    body: Mapping[str, Any],
    query: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Middleware-safe read-only wrapper for exact dev route issuance."""

    conn = get_connection(project_id)
    try:
        return _ac_dev_direct_route_issue_precheck(
            conn,
            project_id=project_id,
            body=body,
            query=query,
        )
    finally:
        conn.close()


def _ac_dev_direct_route_issue_response(
    *,
    project_id: str,
    issued: Mapping[str, Any],
    idempotent_replay: bool,
    contract_execution_id: str,
) -> dict[str, Any]:
    """Project one initial or idempotently replayed dev route issue result."""

    route_token = (
        dict(issued.get("route_token") or {})
        if isinstance(issued.get("route_token"), Mapping)
        else {}
    )
    route_token_ref = str(issued.get("route_token_ref") or "").strip()
    route_identity = {
        key: str(route_token.get(key) or "")
        for key in (
            "route_id",
            "route_context_hash",
            "prompt_contract_id",
            "prompt_contract_hash",
            "visible_injection_manifest_hash",
        )
        if str(route_token.get(key) or "").strip()
    }
    route_identity["route_token_ref"] = route_token_ref
    response = {
        "ok": True,
        "project_id": project_id,
        "route_token": route_token,
        "route_token_ref": route_token_ref,
        "route_identity": route_identity,
        "canonical_route_identity": dict(route_identity),
        "merge_queue_id": str(issued.get("merge_queue_id") or ""),
        "execute_backlog_row_payload": dict(
            issued.get("execute_backlog_row_payload") or {}
        ),
        "provider": dict(issued.get("provider") or {}),
        "ref_registered": True,
        "contract_execution_id": contract_execution_id,
        "dev_world_materialized": True,
        "atomic_route_and_contract_materialization": True,
        "idempotent_replay": idempotent_replay,
        "writes_performed": not idempotent_replay,
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
        "route_token_public_identity_only": True,
        "public_safe": True,
        "secret_safe": True,
    }
    for key, value in route_identity.items():
        response.setdefault(key, value)
    for key in ("parent_route_lineage", "child_route_lineage", "route_lineage"):
        value = route_token.get(key)
        if isinstance(value, Mapping):
            response[key] = dict(value)
    return response


def _ac_dev_direct_route_issue_replay(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    record: Mapping[str, Any],
    route_storage_project_id: str,
) -> dict[str, Any]:
    """Read one existing exact dev CEX+route as an idempotent issue replay."""

    from . import observer_route_context

    route_token_ref = str(record.get("route_token_ref") or "").strip()
    resolved = observer_route_context.resolve_route_token_ref(
        conn,
        project_id=project_id,
        storage_project_id=route_storage_project_id,
        route_token_ref=route_token_ref,
        backlog_id=backlog_id,
        task_id=task_id,
    )
    if not isinstance(resolved, Mapping):
        raise _ac_dev_direct_route_issue_rejection(
            code="ac_dev_direct_route_bootstrap_replay_route_missing",
            message="existing dev Direct execution has no active bound route",
        )
    token = dict(resolved)
    token.setdefault("route_token_ref", route_token_ref)
    merge_queue_id = observer_route_context.derive_merge_queue_id(token)
    issued = {
        "route_token": token,
        "route_token_ref": route_token_ref,
        "merge_queue_id": merge_queue_id,
        "execute_backlog_row_payload": (
            observer_route_context.build_execute_backlog_row_payload(
                token,
                route_token_ref=route_token_ref,
                merge_queue_id=merge_queue_id,
            )
        ),
        "provider": {},
    }
    return _ac_dev_direct_route_issue_response(
        project_id=project_id,
        issued=issued,
        idempotent_replay=True,
        contract_execution_id=task_id,
    )


def _ac_dev_direct_mint_route_authority_persist(
    conn, *, project_id: str, backlog_id: str, execution_id: str,
    request_body: Mapping[str, Any], expected_body: Mapping[str, Any],
    world_authority: Mapping[str, Any], route_storage_project_id: str,
) -> dict[str, Any]:
    from . import observer_route_context
    issued = observer_route_context.issue_observer_write_route_context(
        project_id=project_id, backlog_id=backlog_id, task_id=execution_id,
        target_files=list(expected_body.get("target_files") or []),
        allowed_actions=list(expected_body.get("allowed_actions") or []),
        evidence_refs=list(expected_body.get("evidence_refs") or []),
        project_root=Path(str(world_authority.get("target_project_root") or "")),
        source_free_operation=bool(
            expected_body.get("source_free_operation") is True
        ),
    )
    token = (
        issued.get("route_token")
        if isinstance(issued.get("route_token"), dict)
        else {}
    )
    token.setdefault("owned_files", list(expected_body.get("owned_files") or []))
    route_token_ref = str(issued.get("route_token_ref") or "").strip()
    route_authority = _operator_supervised_direct_main_route_authority_from_resolved(
        project_id=project_id, backlog_id=backlog_id,
        contract_execution_id=execution_id, route_token_ref=route_token_ref,
        row_files=list(expected_body.get("target_files") or []),
        route={**token, "route_token_ref": route_token_ref},
        source_free_operation=bool(
            expected_body.get("source_free_operation") is True
        ),
    )
    if route_authority.get("accepted") is not True:
        raise _ac_dev_direct_route_issue_rejection(
            code="ac_dev_direct_route_bootstrap_route_invalid",
            message="server-minted dev Direct route failed exact scope",
            body=request_body,
            expected_body=expected_body,
        )
    observer_route_context.persist_route_token_ref(
        conn, project_id=project_id,
        storage_project_id=route_storage_project_id,
        route_token_ref=route_token_ref, token=token, commit=False,
    )
    return {"issued": issued, "route_token_ref": route_token_ref,
            "route_authority": route_authority}


def _ac_dev_direct_materialize_fresh_route_execution(
    conn, *, project_id: str, backlog_id: str, execution_id: str,
    selected_revision: str, request_body: Mapping[str, Any],
    expected_body: Mapping[str, Any],
    world_authority: Mapping[str, Any], route_storage_project_id: str,
) -> dict[str, Any]:
    """Materialize one prechecked Direct route+CEX inside the caller transaction."""

    materialized = _ac_dev_direct_mint_route_authority_persist(
        conn, project_id=project_id, backlog_id=backlog_id,
        execution_id=execution_id, request_body=request_body,
        expected_body=expected_body, world_authority=world_authority,
        route_storage_project_id=route_storage_project_id,
    )
    record = _operator_supervised_direct_main_create_fresh_runtime(
        conn, _contract_runtime(conn), project_id=project_id,
        backlog_id=backlog_id, selected_revision=selected_revision,
        execution_id=execution_id,
        route_token_ref=str(materialized["route_token_ref"]),
        route_authority=dict(materialized["route_authority"]),
        world_ref=_operator_supervised_direct_main_world_ref(project_id=project_id),
        dev_world=world_authority,
    )
    return {**materialized, "record": record}


def _ac_dev_direct_terminal_successor_plan(
    *, project_id: str, backlog_id: str,
    predecessor_record: Mapping[str, Any],
    terminal_selection: Mapping[str, Any], route_authority: Mapping[str, Any],
    world_ref: Mapping[str, Any], dev_world: Mapping[str, Any],
) -> dict[str, Any]:
    predecessor_id = str(predecessor_record["contract_execution_id"])
    successor_id = str(terminal_selection["expected_successor_contract_execution_id"])
    transition = {
        "schema_version": "contract_runtime.direct_terminal_successor_transition.v1",
        "transition_kind": "fresh_generation_after_terminal_source",
        "predecessor_contract_execution_id": predecessor_id,
        "successor_contract_execution_id": successor_id,
        "source_no_pass_generation_id": terminal_selection["no_pass_generation_id"],
        "runtime_world_identity_hash": stable_sha256(dev_world),
        "source_contract_revision": predecessor_record["revision"],
        "source_execution_state_revision": predecessor_record["execution_state_revision"],
        "initial_child_execution_state_revision": 1,
        "initial_child_completed_lines_hash": stable_sha256([]),
    }
    transition_hash = stable_sha256(transition)
    role_binding = {"observer": "observer", "qa": "qa", "binding_source": "operator_supervised_direct_main_route_authority"}
    lineage = {"project_id": project_id, "backlog_id": backlog_id, "task_id": successor_id}
    metadata = {
        "facade": "observer_direct_mutation_exception",
        "generic_crud_exposed": False,
        "operator_supervised_direct_main_runtime_binding": (
            _operator_supervised_direct_main_build_runtime_binding(
                project_id=project_id, backlog_id=backlog_id,
                execution_id=successor_id, route_authority=route_authority,
                world_ref=world_ref, dev_world=dev_world,
            )
        ),
        "operator_supervised_direct_main_route_authority": dict(route_authority),
        "direct_terminal_successor_transition": {
            "transition_core": transition, "transition_hash": transition_hash,
        },
    }
    start = {
        "version": predecessor_record["version"], "revision": predecessor_record["revision"],
        "project_id": project_id, "backlog_id": backlog_id, "actor_role": "observer",
        "contract_execution_id": successor_id,
        "parent_contract_execution_id": predecessor_id,
        "root_contract_execution_id": predecessor_record.get("root_contract_execution_id") or predecessor_id,
        "contract_chain_id": predecessor_record["contract_chain_id"],
        "route_token_ref": route_authority["route_token_ref"],
        "role_binding": role_binding, "backlog_lineage": lineage, "metadata": metadata,
    }
    immutable = {key: value for key, value in start.items() if key != "actor_role"}
    immutable.update({"contract_id": "operator_supervised_direct_main", "definition_hash": predecessor_record["definition_hash"]})
    core = {
        "schema_version": "contract_runtime.direct_terminal_successor_core.v1",
        "project_id": project_id, "backlog_id": backlog_id,
        "predecessor_contract_execution_id": predecessor_id,
        "successor_contract_execution_id": successor_id,
        "child_route_token_ref": route_authority["route_token_ref"],
        "transition_core": transition, "transition_hash": transition_hash,
    }
    return {"start_kwargs": start, "immutable_child_projection": immutable,
            "expected_receipt_core": core}
def _ac_dev_direct_terminal_successor_compact_response(
    core: Mapping[str, Any], *, receipt_hash: str, receipt_event_id: int = 0,
    writes_performed: bool = False, idempotent_replay: bool = True,
) -> dict[str, Any]:
    correlation_id = _contract_runtime_stable_id(
        "direct-terminal-successor-receipt", core["project_id"], core["backlog_id"],
        core["predecessor_contract_execution_id"], core["successor_contract_execution_id"], core["transition_hash"],
    )
    capsule = {
        "schema_version": "ac_dev_direct_terminal_successor.v1",
        "ok": True, "state": "exact_successor",
        "project_id": core["project_id"], "backlog_id": core["backlog_id"],
        "predecessor_contract_execution_id": core["predecessor_contract_execution_id"],
        "successor_contract_execution_id": core["successor_contract_execution_id"],
        "route_token_ref": core["child_route_token_ref"],
        "transition_hash": core["transition_hash"],
        "correlation_id": correlation_id, "receipt_hash": receipt_hash,
        "public_safe": True, "secret_safe": True,
        "raw_route_token_exposed": False, "raw_session_token_exposed": False,
        "raw_fence_token_exposed": False,
    }
    capsule_hash = stable_sha256(capsule)
    if _onboard_guide_capsule_serialized_bytes(capsule) > _ONBOARD_GUIDE_CAPSULE_MAX_SERIALIZED_BYTES:
        raise GovernanceError("ac_dev_direct_terminal_successor_capsule_oversized", "terminal successor capsule exceeded its existing bound", 409, {"writes_performed": False, "safe_retry": False})
    if receipt_event_id <= 0:
        return {"capsule": capsule, "capsule_hash": capsule_hash}
    response = {
        **capsule, "capsule_hash": capsule_hash,
        "receipt_ref": f"timeline:{receipt_event_id}", "writes_performed": writes_performed,
        "idempotent_replay": idempotent_replay, "safe_retry": False,
    }
    if _onboard_guide_capsule_serialized_bytes(response) > _ONBOARD_GUIDE_CAPSULE_MAX_SERIALIZED_BYTES:
        raise GovernanceError(
            "ac_dev_direct_terminal_successor_response_oversized",
            "terminal successor compact response exceeded its existing bound", 409,
            {"writes_performed": False, "safe_retry": False},
        )
    return response
def _ac_dev_direct_terminal_successor_receipt_audit(
    conn, *, project_id: str, backlog_id: str,
    predecessor_execution_id: str, expected_core: Mapping[str, Any] | None,
) -> dict[str, Any]:
    def exact(value: Any, schema: str, keys: Sequence[str]) -> bool:
        return isinstance(value, Mapping) and set(value) == set(keys) and value.get("schema_version") == schema
    def blocked(reason: str) -> dict[str, Any]:
        return {"schema_version": "ac_dev_direct_terminal_successor.v1", "ok": False,
                "state": "blocked", "reason": reason, "writes_performed": False,
                "safe_retry": False}
    if not conn.in_transaction:
        return blocked("transaction_required")
    rows = conn.execute(
        "SELECT id,phase,event_kind,status,actor,correlation_id,payload_json,"
        "length(CAST(payload_json AS BLOB)) payload_bytes FROM task_timeline_events "
        "WHERE project_id=? AND backlog_id=? AND task_id=? AND "
        "event_type='contract_runtime.direct_terminal_successor' ORDER BY id LIMIT 2",
        (project_id, backlog_id, predecessor_execution_id)).fetchall()
    if expected_core is None:
        return {} if not rows else blocked("unexpected_receipt")
    if len(rows) != 1:
        return blocked("receipt_missing_or_ambiguous")
    row = rows[0]
    if int(row["payload_bytes"] or 0) > _ONBOARD_GUIDE_CAPSULE_MAX_SERIALIZED_BYTES:
        return blocked("receipt_payload_oversized")
    try:
        payload = json.loads(str(row["payload_json"] or "{}"))
        payload_keys = "schema_version audit_only authoritative_evidence pass_synthesized direct_terminal_successor_receipt meta_contract_gate".split()
        if not exact(payload, "contract_runtime.direct_terminal_successor_event.v1", payload_keys):
            return blocked("receipt_payload_schema")
        gate = payload["meta_contract_gate"]
        gate_keys = "schema_version meta_contract_schema_version meta_contract_id meta_contract_hash allowed status role action observer_event_validated on_behalf self_attesting observer_worker_transport forbidden_always allowed_actions".split()
        gate_valid = exact(gate, "meta_contract_timeline_event_gate.v1", gate_keys) and all((
            gate.get("meta_contract_schema_version") == gate.get("meta_contract_id") == "meta_contract.v1",
            re.fullmatch(r"sha256:[0-9a-f]{64}", str(gate.get("meta_contract_hash") or "")),
            (gate.get("allowed"), gate.get("status"), gate.get("role"), gate.get("action"), gate.get("observer_event_validated")) == (True, "passed", "observer", "contract_binding", True),
            gate.get("on_behalf") is gate.get("self_attesting") is gate.get("observer_worker_transport") is False,
            isinstance(gate.get("forbidden_always"), list) and isinstance(gate.get("allowed_actions"), list) and "contract_binding" in gate["allowed_actions"],
        ))
        receipt = payload["direct_terminal_successor_receipt"]
        receipt_keys = "schema_version core receipt_hash capsule_hash".split()
        if not exact(receipt, "contract_runtime.direct_terminal_successor_receipt.v1", receipt_keys):
            return blocked("receipt_schema")
        core = receipt["core"]
        core_keys = "schema_version project_id backlog_id predecessor_contract_execution_id successor_contract_execution_id child_route_token_ref transition_core transition_hash".split()
        transition_keys = "schema_version transition_kind predecessor_contract_execution_id successor_contract_execution_id source_no_pass_generation_id runtime_world_identity_hash source_contract_revision source_execution_state_revision initial_child_execution_state_revision initial_child_completed_lines_hash".split()
        transition = core["transition_core"] if isinstance(core, Mapping) else {}
        if not exact(core, "contract_runtime.direct_terminal_successor_core.v1", core_keys):
            return blocked("receipt_core_schema")
        if not exact(transition, "contract_runtime.direct_terminal_successor_transition.v1", transition_keys):
            return blocked("receipt_transition_schema")
        if dict(core) != dict(expected_core):
            return blocked("receipt_core_mismatch")
        receipt_hash = str(receipt["receipt_hash"])
        rebuilt = _ac_dev_direct_terminal_successor_compact_response(
            core, receipt_hash=receipt_hash, receipt_event_id=int(row["id"] or 0),
        )
    except (KeyError, TypeError, ValueError, sqlite3.Error):
        return blocked("receipt_unreadable")
    valid = all((
        int(row["id"] or 0) > 0,
        row["phase"] == "orchestration", row["event_kind"] == "contract_binding", gate_valid,
        row["status"] == "accepted", row["actor"] == "observer",
        payload["audit_only"] is True, payload["authoritative_evidence"] is False,
        payload["pass_synthesized"] is False,
        core["transition_hash"] == stable_sha256(transition),
        receipt_hash == stable_sha256(core),
        receipt["capsule_hash"] == rebuilt["capsule_hash"],
        row["correlation_id"] == rebuilt["correlation_id"],
    ))
    return rebuilt if valid else blocked("receipt_audit_mismatch")


def _ac_dev_direct_terminal_successor_response(
    conn, *, project_id: str, backlog_id: str, route_token_ref: str,
    role: str, work_type: str, request_body: Mapping[str, Any] | None,
    request_selector_claims: Mapping[str, Any] | None,
) -> dict[str, Any]:
    if _runtime_plane() != "dev" or project_id != "aming-claw" or role != "observer" or work_type not in {
        "continue_contract_chain", "rollback_or_recover_contract",
    }:
        return {}
    claims = request_selector_claims if isinstance(request_selector_claims, Mapping) else request_body
    execution_ids = _runtime_context_service_dedupe([
        value for field in ("task_id", "contract_execution_id")
        for value in _operator_supervised_direct_main_request_claim_values(claims, field)
    ])
    route_refs = _runtime_context_service_dedupe([
        route_token_ref, *[value for field in ("route_token_ref", "observer_route_token_ref")
                          for value in _operator_supervised_direct_main_request_claim_values(claims, field)]
    ])
    def blocked(reason: str) -> dict[str, Any]:
        return {"schema_version": "ac_dev_direct_terminal_successor.v1", "ok": False,
                "state": "blocked", "reason": reason, "writes_performed": False,
                "safe_retry": False}
    created = False
    with sqlite_write_lock():
        conn.execute("BEGIN IMMEDIATE")
        try:
            world_ref = _operator_supervised_direct_main_world_ref(project_id=project_id)
            world = world_ref.get("runtime_world_authority") if isinstance(world_ref, Mapping) else {}
            world = dict(world) if isinstance(world, Mapping) else {}
            family = _operator_supervised_direct_main_strict_records(
                conn, project_id=project_id, backlog_id=backlog_id,
                world_authority=world,
            )
            if not family:
                return {}
            if world_ref.get("accepted") is not True or len(execution_ids) != 1 or len(route_refs) != 1:
                return blocked("exact_predecessor_authority_required")
            predecessor_id, predecessor_route = execution_ids[0], route_refs[0]
            selection = _operator_supervised_direct_main_operational_terminal_selection(
                conn, project_id=project_id, backlog_id=backlog_id,
                caller_contract_execution_id=predecessor_id,
                caller_route_token_ref=predecessor_route, world_authority=world,
            )
            if selection.get("state") != "exact_terminal_predecessor":
                return blocked(str(selection.get("reason") or "terminal_predecessor_required"))
            successor_id = str(selection["expected_successor_contract_execution_id"])
            records = {str(item["contract_execution_id"]): item for item in family}
            if predecessor_id not in records or set(records) - {predecessor_id, successor_id}:
                return blocked("direct_family_sibling_or_collision")
            runtime = _contract_runtime(conn)
            predecessor = runtime.current_record(predecessor_id, actor_role="observer")
            predecessor_authority = _operator_supervised_direct_main_route_authority(
                conn, project_id=project_id, backlog_id=backlog_id,
                contract_execution_id=predecessor_id, route_token_ref=predecessor_route,
            )
            if predecessor_authority.get("accepted") is not True:
                return blocked("predecessor_route_authority")
            child = records.get(successor_id)
            created = child is None
            if created:
                if _contract_runtime_execution_record_exists(conn, successor_id):
                    return blocked("successor_identity_collision")
                storage_project = direct_main_dev_storage_project_id(project_id, str(world["namespace_hash"]))
                if conn.execute(
                    "SELECT 1 FROM observer_route_token_refs WHERE project_id=? AND backlog_id=? AND task_id=? LIMIT 1",
                    (storage_project, backlog_id, successor_id),
                ).fetchone():
                    return blocked("successor_orphan_route")
                absence = _ac_dev_direct_terminal_successor_receipt_audit(
                    conn, project_id=project_id, backlog_id=backlog_id,
                    predecessor_execution_id=predecessor_id, expected_core=None,
                )
                if absence:
                    return absence
                if work_type == "rollback_or_recover_contract":
                    return blocked("rollback_receipt_required")
                expected_body = {
                    "target_files": list(predecessor_authority["row_declared_files"]),
                    "owned_files": list(predecessor_authority["row_declared_files"]),
                    "allowed_actions": list(predecessor_authority["allowed_actions"]),
                    "evidence_refs": [], "source_free_operation": predecessor_authority["source_free_operation"],
                }
                minted = _ac_dev_direct_mint_route_authority_persist(
                    conn, project_id=project_id, backlog_id=backlog_id,
                    execution_id=successor_id, request_body={}, expected_body=expected_body,
                    world_authority=world, route_storage_project_id=storage_project,
                )
                child_authority = minted["route_authority"]
            else:
                child = runtime.current_record(successor_id, actor_role="observer")
                child_authority = _operator_supervised_direct_main_route_authority(
                    conn, project_id=project_id, backlog_id=backlog_id,
                    contract_execution_id=successor_id,
                    route_token_ref=str(child.get("route_token_ref") or ""),
                )
            if child_authority.get("accepted") is not True:
                return blocked("successor_route_authority")
            plan = _ac_dev_direct_terminal_successor_plan(
                project_id=project_id, backlog_id=backlog_id,
                predecessor_record=predecessor, terminal_selection=selection,
                route_authority=child_authority, world_ref=world_ref, dev_world=world,
            )
            if created:
                child = runtime.start_execution("operator_supervised_direct_main", **plan["start_kwargs"])
                if int(child.get("execution_state_revision") or 0) != 1 or child.get("completed_lines"):
                    return blocked("fresh_successor_not_empty")
                upsert_contract_chain_successor_binding(
                    conn, parent_record=predecessor, child_record=child,
                    edge_kind="direct_terminal_successor", binding_kind="direct_terminal_successor_current",
                )
                core = plan["expected_receipt_core"]
                receipt_hash = stable_sha256(core)
                capsule = _ac_dev_direct_terminal_successor_compact_response(core, receipt_hash=receipt_hash)
                payload = {"schema_version": "contract_runtime.direct_terminal_successor_event.v1",
                           "audit_only": True, "authoritative_evidence": False, "pass_synthesized": False,
                           "direct_terminal_successor_receipt": {
                               "schema_version": "contract_runtime.direct_terminal_successor_receipt.v1",
                               "core": core, "receipt_hash": receipt_hash, "capsule_hash": capsule["capsule_hash"]}}
                if _onboard_guide_capsule_serialized_bytes(payload) > _ONBOARD_GUIDE_CAPSULE_MAX_SERIALIZED_BYTES:
                    return blocked("successor_receipt_oversized")
                from . import task_timeline
                task_timeline.record_event(
                    conn, project_id=project_id, backlog_id=backlog_id, task_id=predecessor_id,
                    event_type="contract_runtime.direct_terminal_successor", phase="orchestration",
                    event_kind="contract_binding", actor="observer", status="accepted",
                    correlation_id=capsule["capsule"]["correlation_id"], payload=payload,
                    post_commit_hooks=False,
                )
            actual = {key: child.get(key) for key in plan["immutable_child_projection"]}
            if actual != plan["immutable_child_projection"]:
                return blocked("successor_projection")
            response = _ac_dev_direct_terminal_successor_receipt_audit(
                conn, project_id=project_id, backlog_id=backlog_id,
                predecessor_execution_id=predecessor_id,
                expected_core=plan["expected_receipt_core"],
            )
            if response.get("ok") is not True:
                return response
            if created:
                response = {**response, "writes_performed": True, "idempotent_replay": False}
                if _onboard_guide_capsule_serialized_bytes(response) > _ONBOARD_GUIDE_CAPSULE_MAX_SERIALIZED_BYTES:
                    return blocked("successor_response_oversized")
            final_world_ref = _operator_supervised_direct_main_world_ref(project_id=project_id)
            if final_world_ref.get("accepted") is not True or stable_sha256(world_ref) != stable_sha256(final_world_ref):
                return blocked("runtime_world_changed")
            if created:
                conn.commit()
            return response
        finally:
            if conn.in_transaction:
                conn.rollback()
def _handle_ac_dev_direct_route_context_issue(
    ctx: RequestContext,
    *,
    project_id: str,
    body: Mapping[str, Any],
) -> dict[str, Any]:
    """Atomically materialize the first exact dev Direct CEX and route."""

    from . import observer_route_context

    conn = get_connection(project_id)
    try:
        _ac_dev_direct_route_issue_precheck(
            conn,
            project_id=project_id,
            body=body,
            query=ctx.query,
        )
        with sqlite_write_lock():
            conn.execute("BEGIN IMMEDIATE")
            try:
                precheck = _ac_dev_direct_route_issue_precheck(
                    conn,
                    project_id=project_id,
                    body=body,
                    query=ctx.query,
                )
                backlog_id = str(precheck["backlog_id"])
                task_id = str(precheck["task_id"])
                route_storage_project_id = (
                    _route_registry_storage_project_id(project_id)
                )
                strict_records = _operator_supervised_direct_main_strict_records(
                    conn,
                    project_id=project_id,
                    backlog_id=backlog_id,
                )
                if len(strict_records) == 1:
                    response = _ac_dev_direct_route_issue_replay(
                        conn,
                        project_id=project_id,
                        backlog_id=backlog_id,
                        task_id=task_id,
                        record=strict_records[0],
                        route_storage_project_id=route_storage_project_id,
                    )
                    conn.rollback()
                    return response
                if len(strict_records) > 1:
                    raise _ac_dev_direct_route_issue_rejection(
                        code="ac_dev_direct_route_bootstrap_execution_ambiguous",
                        message="dev Direct bootstrap execution is not unique",
                        body=body,
                    )
                orphan_routes = conn.execute(
                    """
                    SELECT route_token_ref
                    FROM observer_route_token_refs
                    WHERE project_id=? AND backlog_id=? AND task_id=?
                    """,
                    (route_storage_project_id, backlog_id, task_id),
                ).fetchall()
                if orphan_routes:
                    raise _ac_dev_direct_route_issue_rejection(
                        code="ac_dev_direct_route_bootstrap_orphan_route",
                        message=(
                            "a route exists without its exact dev Direct execution"
                        ),
                        body=body,
                        extra={"orphan_route_count": len(orphan_routes)},
                    )
                expected_body = dict(precheck["expected_body"])
                world = dict(precheck["world_authority"])
                materialized = _ac_dev_direct_materialize_fresh_route_execution(
                    conn, project_id=project_id, backlog_id=backlog_id,
                    execution_id=task_id,
                    selected_revision=str(precheck["selected_revision"]),
                    request_body=body, expected_body=expected_body,
                    world_authority=world,
                    route_storage_project_id=route_storage_project_id,
                )
                issued = materialized["issued"]
                route_token_ref = str(materialized["route_token_ref"])
                if conn.in_transaction:
                    conn.commit()
            except Exception:
                if conn.in_transaction:
                    conn.rollback()
                raise
        resolved = observer_route_context.resolve_route_token_ref(
            conn,
            project_id=project_id,
            storage_project_id=route_storage_project_id,
            route_token_ref=route_token_ref,
            backlog_id=backlog_id,
            task_id=task_id,
        )
        if not isinstance(resolved, Mapping):
            raise RuntimeError(
                "atomic dev Direct route persistence did not read back"
            )
        public_token = dict(resolved)
        public_token.setdefault("route_token_ref", route_token_ref)
        public_merge_queue_id = observer_route_context.derive_merge_queue_id(
            public_token
        )
        public_issued = {
            **dict(issued),
            "route_token": public_token,
            "route_token_ref": route_token_ref,
            "merge_queue_id": public_merge_queue_id,
            "execute_backlog_row_payload": (
                observer_route_context.build_execute_backlog_row_payload(
                    public_token,
                    route_token_ref=route_token_ref,
                    merge_queue_id=public_merge_queue_id,
                )
            ),
        }
        return _ac_dev_direct_route_issue_response(
            project_id=project_id,
            issued=public_issued,
            idempotent_replay=False,
            contract_execution_id=task_id,
        )
    finally:
        conn.close()


_AC_DEV_DIRECT_ROUTE_RENEW_SENSITIVE_TOKENS = frozenset(
    {
        "token",
        "route_token",
        "raw_route_token",
        "observer_route_token",
        "session_token",
        "raw_session_token",
        "observer_session_token",
    }
)


def _ac_dev_direct_route_renew_claim_values(
    body: Mapping[str, Any] | None,
    query: Mapping[str, Any] | None,
    *fields: str,
) -> list[str]:
    values: list[str] = []
    for source in (body, query):
        source_map = source if isinstance(source, Mapping) else {}
        for field in fields:
            raw = source_map.get(field)
            candidates = (
                list(raw)
                if isinstance(raw, Sequence)
                and not isinstance(raw, (str, bytes, bytearray))
                else [raw]
            )
            values.extend(
                str(value or "").strip()
                for value in candidates
                if str(value or "").strip()
            )
    return values


def _ac_dev_direct_route_renew_secret_fields(
    value: Any,
    *,
    prefix: str,
) -> list[str]:
    found: list[str] = []
    if isinstance(value, Mapping):
        for key, item in value.items():
            field = str(key or "").strip()
            path = f"{prefix}.{field}" if field else prefix
            if field in _AC_DEV_DIRECT_ROUTE_RENEW_SENSITIVE_TOKENS and item not in (
                None,
                "",
                [],
                {},
            ):
                found.append(path)
            found.extend(
                _ac_dev_direct_route_renew_secret_fields(item, prefix=path)
            )
    elif isinstance(value, Sequence) and not isinstance(
        value,
        (str, bytes, bytearray),
    ):
        for index, item in enumerate(value):
            found.extend(
                _ac_dev_direct_route_renew_secret_fields(
                    item,
                    prefix=f"{prefix}[{index}]",
                )
            )
    return sorted(set(found))


def _ac_dev_direct_route_renew_rejection(
    *,
    code: str,
    message: str,
    body: Mapping[str, Any] | None = None,
    query: Mapping[str, Any] | None = None,
    mismatch_fields: Sequence[str] = (),
) -> GovernanceError:
    """Return one secret-safe, physical-zero-write dev renewal rejection."""

    return GovernanceError(
        code,
        message,
        409,
        {
            "schema_version": "ac_dev_direct_route_renew.rejection.v1",
            "runtime_plane": "dev",
            "required_endpoint": "http://127.0.0.1:40008",
            "request_body_hash": stable_sha256(dict(body or {})),
            "request_query_hash": stable_sha256(dict(query or {})),
            "mismatch_fields": sorted(
                {str(field or "").strip() for field in mismatch_fields if field}
            ),
            "zero_write_rejection": True,
            "writes_performed": False,
            "mutation_performed": False,
            "route_registry_mutated": False,
            "contract_runtime_mutated": False,
            "public_safe": True,
            "secret_safe": True,
            "raw_route_token_exposed": False,
            "raw_observer_session_token_exposed": False,
        },
    )


def _ac_dev_direct_route_renew_exact_claim(
    body: Mapping[str, Any],
    query: Mapping[str, Any],
    *,
    field: str,
    aliases: Sequence[str],
) -> str:
    values = _ac_dev_direct_route_renew_claim_values(body, query, *aliases)
    unique = sorted(set(values))
    if len(unique) != 1:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_identity_invalid",
            message="dev route renewal requires one exact guide-bound identity",
            body=body,
            query=query,
            mismatch_fields=[field],
        )
    return unique[0]


def _ac_dev_verify_observer_session_read_schema(conn) -> None:
    """Verify the stable-owned observer session schema without lazy DDL."""

    verify_existing_schema_capabilities(
        conn,
        owner="observer_session.dev_route_renew",
        required_tables=("observer_sessions",),
        required_indexes=(
            "idx_observer_sessions_project_status",
            "idx_observer_sessions_last_seen",
        ),
        required_index_definitions={
            "idx_observer_sessions_project_status": {
                "table": "observer_sessions",
                "sql": (
                    "CREATE INDEX idx_observer_sessions_project_status "
                    "ON observer_sessions(project_id, status)"
                ),
            },
            "idx_observer_sessions_last_seen": {
                "table": "observer_sessions",
                "sql": (
                    "CREATE INDEX idx_observer_sessions_last_seen "
                    "ON observer_sessions(project_id, last_seen_at)"
                ),
            },
        },
    )
    expected_columns = {
        "session_id": ("TEXT", 0, 1),
        "project_id": ("TEXT", 1, 0),
        "observer_kind": ("TEXT", 1, 0),
        "session_label": ("TEXT", 1, 0),
        "pid": ("INTEGER", 1, 0),
        "cwd": ("TEXT", 1, 0),
        "capabilities_json": ("TEXT", 1, 0),
        "token_hash": ("TEXT", 1, 0),
        "status": ("TEXT", 1, 0),
        "registered_at": ("TEXT", 1, 0),
        "last_seen_at": ("TEXT", 1, 0),
        "closed_at": ("TEXT", 1, 0),
        "revoked_at": ("TEXT", 1, 0),
    }
    rows = conn.execute('PRAGMA table_info("observer_sessions")').fetchall()
    actual_columns = {
        str(row["name"] if isinstance(row, sqlite3.Row) else row[1]): (
            str(row["type"] if isinstance(row, sqlite3.Row) else row[2]).upper(),
            int(row["notnull"] if isinstance(row, sqlite3.Row) else row[3]),
            int(row["pk"] if isinstance(row, sqlite3.Row) else row[5]),
        )
        for row in rows
    }
    missing = sorted(set(expected_columns) - set(actual_columns))
    unexpected = sorted(set(actual_columns) - set(expected_columns))
    invalid: dict[str, dict[str, str]] = {}
    for column, expected in expected_columns.items():
        actual = actual_columns.get(column)
        if actual is None or actual == expected:
            continue
        mismatch: dict[str, str] = {}
        for field, expected_value, actual_value in zip(
            ("type", "notnull", "pk"),
            expected,
            actual,
        ):
            if expected_value != actual_value:
                mismatch[f"expected_{field}"] = str(expected_value)
                mismatch[f"actual_{field}"] = str(actual_value)
        invalid[column] = mismatch
    if unexpected:
        invalid["__column_set__"] = {
            "expected_columns": ",".join(sorted(expected_columns)),
            "actual_columns": ",".join(sorted(actual_columns)),
        }

    token_hash_unique = False
    for index_row in conn.execute(
        'PRAGMA index_list("observer_sessions")'
    ).fetchall():
        unique = int(
            index_row["unique"]
            if isinstance(index_row, sqlite3.Row)
            else index_row[2]
        )
        origin = str(
            index_row["origin"]
            if isinstance(index_row, sqlite3.Row)
            else index_row[3]
        )
        partial = int(
            index_row["partial"]
            if isinstance(index_row, sqlite3.Row)
            else index_row[4]
        )
        if not unique or origin != "u" or partial:
            continue
        index_name = str(
            index_row["name"]
            if isinstance(index_row, sqlite3.Row)
            else index_row[1]
        )
        escaped_index_name = index_name.replace('"', '""')
        key_columns = tuple(
            (
                str(item["name"] if isinstance(item, sqlite3.Row) else item[2])
                if (
                    item["name"] if isinstance(item, sqlite3.Row) else item[2]
                )
                is not None
                else None
            )
            for item in conn.execute(
                f'PRAGMA index_xinfo("{escaped_index_name}")'
            ).fetchall()
            if int(item["key"] if isinstance(item, sqlite3.Row) else item[5])
        )
        if key_columns == ("token_hash",):
            token_hash_unique = True
            break
    if missing or invalid or not token_hash_unique:
        raise DevRuntimeSchemaVerificationError(
            "observer_session.dev_route_renew",
            missing_columns={"observer_sessions": missing} if missing else {},
            invalid_columns={"observer_sessions": invalid} if invalid else {},
            missing_unique_constraints=(
                {"observer_sessions": (("token_hash",),)}
                if not token_hash_unique
                else {}
            ),
        )


def _ac_dev_read_only_observer_session_authority(
    conn,
    *,
    project_id: str,
    session_id: str,
) -> dict[str, Any]:
    """Read one public session identity without migration or credential data."""

    _ac_dev_verify_observer_session_read_schema(conn)
    row = conn.execute(
        "SELECT session_id, project_id, status, last_seen_at "
        "FROM observer_sessions WHERE session_id=?",
        (str(session_id or "").strip(),),
    ).fetchone()
    if row is None:
        return {
            "schema_version": "ac_dev_observer_session_authority.v1",
            "state": "missing",
            "session_id": str(session_id or "").strip(),
            "project_id": str(project_id or "").strip(),
            "computed_status": "missing",
            "verify_only": True,
        }
    public_row = {
        "session_id": str(row["session_id"] or "").strip(),
        "project_id": str(row["project_id"] or "").strip(),
        "status": str(row["status"] or "").strip(),
        "last_seen_at": str(row["last_seen_at"] or "").strip(),
    }
    if public_row["project_id"] != str(project_id or "").strip():
        state = "foreign"
        computed_status = "foreign"
    else:
        computed_status = observer_session.computed_session_status(public_row)
        state = (
            "active"
            if public_row["status"] == "active" and computed_status == "active"
            else "stale"
        )
    return {
        "schema_version": "ac_dev_observer_session_authority.v1",
        "state": state,
        "session_id": public_row["session_id"],
        "project_id": public_row["project_id"],
        "computed_status": computed_status,
        "verify_only": True,
    }


def _ac_dev_direct_route_renew_precheck(
    conn,
    *,
    project_id: str,
    body: Mapping[str, Any],
    query: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Verify the one server-owned dev route/session/world before renewal."""

    query_map = query if isinstance(query, Mapping) else {}
    if _runtime_plane() != "dev" or project_id != "aming-claw":
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_wrong_runtime",
            message="Direct route renewal is confined to the AC dev runtime",
            body=body,
            query=query_map,
            mismatch_fields=["runtime_plane"],
        )
    secret_fields = [
        *_ac_dev_direct_route_renew_secret_fields(body, prefix="body"),
        *_ac_dev_direct_route_renew_secret_fields(query_map, prefix="query"),
    ]
    if secret_fields:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_secret_rejected",
            message="dev route renewal accepts public refs, never raw credentials",
            body=body,
            query=query_map,
            mismatch_fields=secret_fields,
        )
    storage_claims = _ac_dev_direct_route_renew_claim_values(
        body,
        query_map,
        "storage_project_id",
        "route_storage_project_id",
    )
    if storage_claims:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_storage_claim_rejected",
            message="dev route storage authority is server-derived",
            body=body,
            query=query_map,
            mismatch_fields=["storage_project_id"],
        )
    project_claim = _ac_dev_direct_route_renew_exact_claim(
        body,
        query_map,
        field="project_id",
        aliases=("project_id",),
    )
    if project_claim != project_id:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_project_mismatch",
            message="dev route renewal requires the canonical AC project",
            body=body,
            query=query_map,
            mismatch_fields=["project_id"],
        )
    caller_role = _ac_dev_direct_route_renew_exact_claim(
        body,
        query_map,
        field="caller_role",
        aliases=("caller_role",),
    ).lower()
    if caller_role != "observer":
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_role_invalid",
            message="dev route renewal requires caller_role=observer",
            body=body,
            query=query_map,
            mismatch_fields=["caller_role"],
        )
    backlog_id = _ac_dev_direct_route_renew_exact_claim(
        body,
        query_map,
        field="backlog_id",
        aliases=("backlog_id", "bug_id"),
    )
    session_id = _ac_dev_direct_route_renew_exact_claim(
        body,
        query_map,
        field="observer_session_id",
        aliases=("observer_session_id", "observer_session_ref"),
    )
    route_token_ref = _ac_dev_direct_route_renew_exact_claim(
        body,
        query_map,
        field="route_token_ref",
        aliases=("route_token_ref", "observer_route_token_ref"),
    )
    task_claim = _ac_dev_direct_route_renew_exact_claim(
        body,
        query_map,
        field="task_id",
        aliases=("task_id", "contract_execution_id"),
    )
    world = _operator_supervised_direct_main_dev_world_authority()
    if world.get("accepted") is not True:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_world_invalid",
            message="dev route renewal requires one exact loaded runtime world",
            body=body,
            query=query_map,
            mismatch_fields=["runtime_world"],
        )
    records = _operator_supervised_direct_main_strict_records(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
    )
    if len(records) != 1:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_execution_invalid",
            message="dev route renewal requires one exact Direct execution",
            body=body,
            query=query_map,
            mismatch_fields=["contract_execution_id"],
        )
    record = records[0]
    task_id = str(record.get("contract_execution_id") or "").strip()
    if not task_id or task_claim != task_id:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_execution_mismatch",
            message="dev route renewal execution does not match the current CEX",
            body=body,
            query=query_map,
            mismatch_fields=["task_id", "contract_execution_id"],
        )
    selector_claims = _onboard_runtime_selector_claims(body, query_map)
    selector_mismatches = _operator_supervised_direct_main_request_mismatches(
        selector_claims,
        execution_id=task_id,
        world_authority=world,
    )
    if selector_mismatches:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_selector_mismatch",
            message="dev route renewal selectors do not match the loaded world",
            body=body,
            query=query_map,
            mismatch_fields=[
                str(item.get("field") or "") for item in selector_mismatches
            ],
        )
    try:
        session = _ac_dev_read_only_observer_session_authority(
            conn,
            project_id=project_id,
            session_id=session_id,
        )
    except DevRuntimeSchemaVerificationError:
        raise
    except sqlite3.DatabaseError as exc:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_session_read_failed",
            message="dev route renewal session verification was unavailable",
            body=body,
            query=query_map,
            mismatch_fields=["observer_session_id"],
        ) from exc
    if str(session.get("state") or "") != "active":
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_session_invalid",
            message="dev route renewal requires the exact active observer session",
            body=body,
            query=query_map,
            mismatch_fields=["observer_session_id"],
        )

    from . import observer_route_context

    storage_project_id = _route_registry_storage_project_id(project_id)
    root_ref = str(record.get("route_token_ref") or "").strip()
    if not root_ref:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_root_ref_missing",
            message="current dev Direct execution has no bound route ref",
            body=body,
            query=query_map,
            mismatch_fields=["route_token_ref"],
        )
    if route_token_ref != root_ref:
        try:
            root_descendant = (
                observer_route_context.resolve_route_token_ref_renewal_descendant(
                    conn,
                    project_id=project_id,
                    storage_project_id=storage_project_id,
                    route_token_ref=root_ref,
                )
            )
        except observer_route_context.RouteTokenRefError as exc:
            raise _ac_dev_direct_route_renew_rejection(
                code="ac_dev_direct_route_renew_lineage_invalid",
                message="dev route renewal ref is outside the Direct route lineage",
                body=body,
                query=query_map,
                mismatch_fields=["route_token_ref"],
            ) from exc
        renewal = (
            root_descendant.get("renewal_resolution")
            if isinstance(root_descendant, Mapping)
            else {}
        )
        chain = list(renewal.get("route_token_ref_chain") or [])
        if route_token_ref not in chain:
            raise _ac_dev_direct_route_renew_rejection(
                code="ac_dev_direct_route_renew_ref_mismatch",
                message="dev route renewal ref is not bound to the current CEX",
                body=body,
                query=query_map,
                mismatch_fields=["route_token_ref"],
            )
    replay_route: dict[str, Any] = {}
    try:
        active_route = observer_route_context.resolve_route_token_ref(
            conn,
            project_id=project_id,
            storage_project_id=storage_project_id,
            route_token_ref=route_token_ref,
            backlog_id=backlog_id,
            task_id=task_id,
        )
    except observer_route_context.RouteTokenRefError as exc:
        if str(getattr(exc, "code", "") or "") != (
            "route_token_ref_not_active"
        ) or str((getattr(exc, "details", {}) or {}).get("status") or "") != (
            "superseded"
        ):
            raise _ac_dev_direct_route_renew_rejection(
                code="ac_dev_direct_route_renew_ref_invalid",
                message="dev route renewal requires an exact active lineage ref",
                body=body,
                query=query_map,
                mismatch_fields=["route_token_ref"],
            ) from exc
        try:
            replay_route = dict(
                observer_route_context.resolve_route_token_ref_renewal_descendant(
                    conn,
                    project_id=project_id,
                    storage_project_id=storage_project_id,
                    route_token_ref=route_token_ref,
                )
                or {}
            )
        except observer_route_context.RouteTokenRefError as descendant_exc:
            raise _ac_dev_direct_route_renew_rejection(
                code="ac_dev_direct_route_renew_descendant_invalid",
                message="superseded dev route has no exact active descendant",
                body=body,
                query=query_map,
                mismatch_fields=["route_token_ref"],
            ) from descendant_exc
        active_route = {}
    if not active_route and not replay_route:
        raise _ac_dev_direct_route_renew_rejection(
            code="ac_dev_direct_route_renew_ref_unknown",
            message="dev route renewal ref is not registered in this world",
            body=body,
            query=query_map,
            mismatch_fields=["route_token_ref"],
        )
    return {
        "schema_version": "ac_dev_direct_route_renew.precheck.v1",
        "accepted": True,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "task_id": task_id,
        "observer_session_id": session_id,
        "route_token_ref": route_token_ref,
        "storage_project_id": storage_project_id,
        "world_authority": dict(world),
        "record": dict(record),
        "active_route": dict(active_route or {}),
        "replay_route": dict(replay_route),
        "idempotent_replay": bool(replay_route),
        "zero_write_projection": True,
    }


def _ac_dev_direct_route_renew_precheck_from_request(
    *,
    project_id: str,
    body: Mapping[str, Any],
    query: Mapping[str, Any] | None,
) -> dict[str, Any]:
    conn = get_connection(project_id)
    try:
        return _ac_dev_direct_route_renew_precheck(
            conn,
            project_id=project_id,
            body=body,
            query=query,
        )
    finally:
        conn.close()


def _ac_dev_direct_route_renew_replay_response(
    precheck: Mapping[str, Any],
) -> dict[str, Any]:
    from . import observer_route_context

    route = dict(precheck.get("replay_route") or {})
    route_token_ref = str(route.get("route_token_ref") or "").strip()
    route_identity = {
        field: str(route.get(field) or "").strip()
        for field in (
            "route_id",
            "route_context_hash",
            "prompt_contract_id",
            "prompt_contract_hash",
            "visible_injection_manifest_hash",
        )
    }
    route_identity["route_token_ref"] = route_token_ref
    merge_queue_id = observer_route_context.derive_merge_queue_id(route)
    return {
        "schema_version": "observer_route_token_ref.renewal.v1",
        "ok": True,
        "project_id": str(precheck.get("project_id") or ""),
        "previous_route_token_ref": str(
            precheck.get("route_token_ref") or ""
        ),
        "route_token_ref": route_token_ref,
        "status": "renewed",
        "renewed": True,
        "superseded_previous_ref": True,
        "scope": dict(route.get("scope") or {}),
        "allowed_actions": list(route.get("allowed_actions") or []),
        "target_files": list(route.get("target_files") or []),
        "owned_files": list(route.get("owned_files") or []),
        "route_identity": route_identity,
        "renewed_route_token_ref": route,
        "merge_queue_id": merge_queue_id,
        "execute_backlog_row_payload": (
            observer_route_context.build_execute_backlog_row_payload(
                route,
                route_token_ref=route_token_ref,
                merge_queue_id=merge_queue_id,
            )
        ),
        "idempotent_replay": True,
        "writes_performed": False,
        "mutation_performed": False,
        "dev_world_renewal": True,
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
        "raw_route_token_persisted": False,
        "public_safe": True,
        "secret_safe": True,
    }


def _handle_ac_dev_direct_route_context_renew(
    ctx: RequestContext,
    *,
    project_id: str,
    body: Mapping[str, Any],
) -> dict[str, Any]:
    """Renew only one exact physical dev route; replay retries read-only."""

    from . import observer_route_context

    conn = get_connection(project_id)
    try:
        _ac_dev_direct_route_renew_precheck(
            conn,
            project_id=project_id,
            body=body,
            query=ctx.query,
        )
        try:
            ttl_hours = float(body.get("ttl_hours", 24))
            renew_within_seconds = int(
                body.get(
                    "renew_within_seconds",
                    observer_route_context.ROUTE_TOKEN_REF_RENEW_WITHIN_SECONDS,
                )
            )
        except (TypeError, ValueError) as exc:
            raise _ac_dev_direct_route_renew_rejection(
                code="ac_dev_direct_route_renew_options_invalid",
                message="dev route renewal options are invalid",
                body=body,
                query=ctx.query,
                mismatch_fields=["ttl_hours", "renew_within_seconds"],
            ) from exc
        for field in ("allowed_actions", "target_files", "owned_files", "evidence_refs"):
            if body.get(field) is not None and not isinstance(body.get(field), list):
                raise _ac_dev_direct_route_renew_rejection(
                    code="ac_dev_direct_route_renew_options_invalid",
                    message="dev route renewal list options are invalid",
                    body=body,
                    query=ctx.query,
                    mismatch_fields=[field],
                )
        with sqlite_write_lock():
            conn.execute("BEGIN IMMEDIATE")
            try:
                precheck = _ac_dev_direct_route_renew_precheck(
                    conn,
                    project_id=project_id,
                    body=body,
                    query=ctx.query,
                )
                if precheck.get("idempotent_replay") is True:
                    conn.rollback()
                    return _ac_dev_direct_route_renew_replay_response(precheck)
                renewed = observer_route_context.renew_route_token_ref(
                    conn,
                    project_id=project_id,
                    storage_project_id=str(precheck["storage_project_id"]),
                    route_token_ref=str(precheck["route_token_ref"]),
                    backlog_id=str(precheck["backlog_id"]),
                    task_id=str(precheck["task_id"]),
                    caller_role="observer",
                    allowed_actions=(
                        _observer_route_context_issue_allowed_actions(
                            body.get("allowed_actions")
                        )
                        if body.get("allowed_actions") is not None
                        else None
                    ),
                    target_files=body.get("target_files"),
                    owned_files=body.get("owned_files"),
                    ttl_hours=ttl_hours,
                    renew_within_seconds=renew_within_seconds,
                    evidence_refs=body.get("evidence_refs"),
                    project_root=Path(
                        str(
                            (precheck.get("world_authority") or {}).get(
                                "target_project_root"
                            )
                        )
                    ),
                    commit=False,
                )
                if conn.in_transaction:
                    conn.commit()
            except Exception:
                if conn.in_transaction:
                    conn.rollback()
                raise
        result = dict(renewed)
        result.update(
            {
                "idempotent_replay": False,
                "writes_performed": True,
                "mutation_performed": True,
                "dev_world_renewal": True,
                "public_safe": True,
                "secret_safe": True,
            }
        )
        return result
    finally:
        conn.close()


def _operator_supervised_direct_main_bound_pre_mutation_events(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
) -> list[dict[str, Any]]:
    from . import task_timeline

    events = task_timeline.list_events(
        conn,
        project_id,
        backlog_id=backlog_id,
        task_id=contract_execution_id,
        limit=1000,
    )
    result: list[dict[str, Any]] = []
    for event in events:
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        authority = (
            payload.get("observer_direct_pre_mutation_authority")
            if isinstance(
                payload.get("observer_direct_pre_mutation_authority"),
                Mapping,
            )
            else {}
        )
        binding = (
            payload.get("direct_contract_runtime_binding")
            if isinstance(payload.get("direct_contract_runtime_binding"), Mapping)
            else {}
        )
        if (
            authority.get("accepted") is True
            and authority.get("server_projected") is True
            and str(binding.get("contract_execution_id") or "").strip()
            == contract_execution_id
            and str(binding.get("line_id") or "").strip()
            == "observer_direct_implementation_exception"
            and str(authority.get("pre_mutation_request_fingerprint") or "")
            .strip()
            .startswith("sha256:")
        ):
            result.append(event)
    return result


def _operator_supervised_direct_main_runtime_line_payload(
    record: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    metadata = record.get("metadata") if isinstance(record.get("metadata"), Mapping) else {}
    binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    return {
        **dict(payload),
        "direct_runtime_binding_hash": str(binding.get("binding_hash") or ""),
    }


def _operator_supervised_direct_main_qa_facade_binding(
    record: Mapping[str, Any],
    *,
    actor_role: str,
    line: Mapping[str, Any],
    body: Mapping[str, Any],
) -> dict[str, Any]:
    """Validate the copy-safe Direct QA binding before any runtime write.

    The public timeline facade carries the binding at top level so MCP schema
    validation cannot silently drop it.  The server independently rebuilds
    every expected value from the pinned execution and current writer Guide;
    caller values are equality proofs only and never become authority.
    """

    binding_fields = (
        "contract_execution_id",
        "execution_state_revision",
        "stage_id",
        "line_id",
        "runtime_guide_hash",
        "direct_runtime_binding_hash",
    )

    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    runtime_binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    line_id = str(line.get("line_id") or "").strip()
    if not (
        str(record.get("contract_id") or "").strip()
        == "operator_supervised_direct_main"
        and str(record.get("revision") or "").strip()
        in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        and runtime_binding.get("strict_runtime_binding_required") is True
        and str(actor_role or "").strip() == "qa"
        and line_id in {"qa_graph_context", "qa_independent_verification"}
    ):
        return {}

    nested_paths: list[str] = []

    def collect_nested(value: Any, path: str) -> None:
        if isinstance(value, Mapping):
            for raw_key, child in value.items():
                key = str(raw_key or "").strip()
                child_path = f"{path}.{key}" if key else path
                if key in binding_fields:
                    nested_paths.append(child_path)
                collect_nested(child, child_path)
        elif isinstance(value, (list, tuple)):
            for index, child in enumerate(value):
                collect_nested(child, f"{path}[{index}]")

    for container_key in ("payload", "verification", "artifact_refs"):
        collect_nested(body.get(container_key), container_key)
    if nested_paths:
        raise GovernanceError(
            "operator_supervised_direct_main_qa_binding_nested",
            "Direct Main QA runtime binding fields must be top-level",
            422,
            {
                "field": sorted(set(nested_paths))[0],
                "nested_binding_paths": sorted(set(nested_paths)),
                "required_top_level_fields": list(
                    binding_fields
                ),
                "caller_claims_trusted": False,
                "server_derived": True,
                "zero_contract_runtime_write": True,
                "zero_timeline_write": True,
                "writes_performed": False,
            },
        )

    expected_write = _contract_runtime_write_from_record(
        record,
        actor_role="qa",
        stage_id=str(line.get("stage_id") or "").strip(),
        line_id=line_id,
        evidence_kind=str(line.get("evidence_kind") or "").strip(),
    )
    expected = {
        field: expected_write.get(field)
        for field in (
            "contract_execution_id",
            "execution_state_revision",
            "stage_id",
            "line_id",
            "runtime_guide_hash",
        )
    }
    expected["direct_runtime_binding_hash"] = str(
        runtime_binding.get("binding_hash") or ""
    ).strip()
    mismatches = [
        {
            "field": field,
            "expected": expected_value,
            "actual": (
                "missing"
                if body.get(field) in (None, "")
                else body.get(field)
            ),
        }
        for field, expected_value in expected.items()
        if body.get(field) != expected_value
    ]
    if mismatches:
        first = mismatches[0]
        raise GovernanceError(
            "operator_supervised_direct_main_qa_binding_mismatch",
            "Direct Main QA facade binding does not match the current pinned writer line",
            422,
            {
                "field": first["field"],
                "expected": first["expected"],
                "actual": first["actual"],
                "identity_mismatches": mismatches,
                "required_top_level_fields": list(
                    binding_fields
                ),
                "caller_claims_trusted": False,
                "server_derived": True,
                "zero_contract_runtime_write": True,
                "zero_timeline_write": True,
                "writes_performed": False,
            },
        )
    return expected


def _operator_supervised_direct_main_expected_line_evidence(
    record: Mapping[str, Any],
    *,
    actor_role: str,
    stage_id: str,
    line_id: str,
    evidence_kind: str,
    payload: Mapping[str, Any],
    extra: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Rebuild the exact persisted line produced by the Direct adapter.

    This is used only for crash-window recovery after ContractRuntime accepted
    a line but before the public timeline event committed.  Reuse is legal only
    when every persisted field matches the write that the facade would submit;
    a line-id match alone is never retry authority.
    """

    body = {
        "stage_id": stage_id,
        "line_id": line_id,
        "evidence_kind": evidence_kind,
        "payload": _operator_supervised_direct_main_runtime_line_payload(
            record,
            payload,
        ),
        **dict(extra or {}),
    }
    write = _contract_runtime_line_write_body(
        record,
        body,
        actor_role=actor_role,
    )
    # ContractRuntime derives these two safe persisted surfaces immediately
    # before Gate evaluation.  Mirror that deterministic normalization so the
    # comparison covers the complete completed-line evidence, including QA.
    _enrich_line_instance_fields(write)
    _enrich_qa_evidence_provenance(write, actor_role)
    return _line_evidence_from_write(write, actor_role)


def _operator_supervised_direct_main_submit_runtime_line(
    conn,
    *,
    contract_execution_id: str,
    actor_role: str,
    expected_stage_id: str,
    expected_line_id: str,
    expected_evidence_kind: str,
    payload: Mapping[str, Any],
    extra: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    runtime = _contract_runtime(conn)
    record = runtime.current_record(
        contract_execution_id,
        actor_role=actor_role,
    )
    next_line = (
        record.get("runtime_guide", {}).get("next_legal_action")
        if isinstance(record.get("runtime_guide"), Mapping)
        else {}
    )
    actual = {
        "stage_id": str((next_line or {}).get("stage_id") or "").strip(),
        "line_id": str((next_line or {}).get("line_id") or "").strip(),
        "evidence_kind": str(
            (next_line or {}).get("evidence_kind") or ""
        ).strip(),
    }
    expected = {
        "stage_id": expected_stage_id,
        "line_id": expected_line_id,
        "evidence_kind": expected_evidence_kind,
    }
    if actual != expected:
        raise GovernanceError(
            "operator_supervised_direct_main_runtime_line_mismatch",
            "Direct Main timeline adapter does not match the current Contract line",
            409,
            {
                "contract_execution_id": contract_execution_id,
                "expected": expected,
                "actual": actual,
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    body = {
        "stage_id": expected_stage_id,
        "line_id": expected_line_id,
        "evidence_kind": expected_evidence_kind,
        "payload": _operator_supervised_direct_main_runtime_line_payload(
            record,
            payload,
        ),
        **dict(extra or {}),
    }
    write = _contract_runtime_line_write_body(
        record,
        body,
        actor_role=actor_role,
    )
    result = runtime.submit_line_write(
        contract_execution_id,
        write,
        actor_role=actor_role,
    )
    if result.get("ok") is not True:
        raise GovernanceError(
            "operator_supervised_direct_main_runtime_line_rejected",
            "Direct Main timeline evidence did not satisfy ContractRuntime",
            422,
            {
                "contract_execution_id": contract_execution_id,
                "stage_id": expected_stage_id,
                "line_id": expected_line_id,
                "decision": dict(result.get("decision") or {}),
                "zero_write_rejection": True,
                "writes_performed": False,
            },
        )
    return dict(result["record"])


def _operator_supervised_direct_main_reconcile_qa_candidate_matches_target(
    proof: Mapping[str, Any],
    *,
    target_commit: str,
) -> bool:
    """Match one DB-verified QA graph basis to the Direct reconcile target."""

    target_commit = str(target_commit or "").strip().lower()
    full_commit = r"[0-9a-f]{40}|[0-9a-f]{64}"
    if not re.fullmatch(full_commit, target_commit):
        return False

    graph_basis = str(proof.get("graph_basis") or "").strip()
    snapshot_commit = str(
        proof.get("snapshot_commit_sha") or ""
    ).strip().lower()
    base_commit = str(proof.get("base_commit_sha") or "").strip().lower()
    candidate_commit = str(
        proof.get("candidate_commit_sha") or ""
    ).strip().lower()
    candidate_diff_hash = str(
        proof.get("candidate_diff_hash") or ""
    ).strip().lower()
    changed_files = proof.get("changed_files")
    changed_files_source = str(
        proof.get("changed_files_source") or ""
    ).strip()
    nonempty_diff = bool(
        re.fullmatch(r"sha256:[0-9a-f]{64}", candidate_diff_hash)
        and candidate_diff_hash
        != f"sha256:{hashlib.sha256(b'').hexdigest()}"
    )
    bounded_changes = bool(
        isinstance(changed_files, list)
        and changed_files
        and all(str(path or "").strip() for path in changed_files)
    )

    if graph_basis == "canonical_base_plus_candidate_diff":
        return bool(
            re.fullmatch(full_commit, base_commit)
            and snapshot_commit == base_commit
            and base_commit != target_commit
            and candidate_commit == target_commit
            and nonempty_diff
            and bounded_changes
            and changed_files_source == "server_git_diff_name_status_z_m"
            and re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                str(proof.get("candidate_overlay_hash") or "")
                .strip()
                .lower(),
            )
        )

    if graph_basis != "exact_candidate_snapshot":
        return False
    comparison_base = str(
        proof.get("comparison_base_commit_sha") or ""
    ).strip().lower()
    return bool(
        snapshot_commit == target_commit
        and base_commit == target_commit
        and candidate_commit == target_commit
        and proof.get("comparison_authority_required") is True
        and re.fullmatch(full_commit, comparison_base)
        and comparison_base != target_commit
        and str(proof.get("comparison_base_commit_source") or "").strip()
        == _QA_DIRECT_MAIN_COMPARISON_BASE_SOURCE
        and str(
            proof.get("comparison_base_commit_lineage_source") or ""
        ).strip()
        == _QA_DIRECT_MAIN_COMPARISON_LINEAGE_SOURCE
        and nonempty_diff
        and bounded_changes
        and changed_files_source
        == "server_runtime_context_base_to_exact_candidate_diff"
    )


def _operator_supervised_direct_main_active_route_authority(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    immutable_route_identity: Mapping[str, Any],
    active_route_token_ref: str,
    expected_files: Sequence[str] = (),
    required_action: str = "task_timeline_append",
) -> dict[str, Any]:
    """Project an active Direct ref from the existing append-scope resolver."""

    immutable_identity = {
        field: str(immutable_route_identity.get(field) or "").strip()
        for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
    }
    immutable_ref = immutable_identity.get("route_token_ref", "")
    presented_ref = str(active_route_token_ref or "").strip()
    canonical_files = sorted(
        _runtime_context_service_dedupe(
            [str(path or "").strip() for path in expected_files]
        )
    )
    active_identity: dict[str, str] = {}
    resolution: dict[str, Any] = {}
    if (
        presented_ref
        and _observer_root_route_identity_complete(immutable_identity)
    ):
        active_identity, resolution = (
            _contract_runtime_resolve_append_scoped_child_route(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                contract_execution_id=task_id,
                route_token_ref=immutable_ref,
                supplied_route_authority=immutable_identity,
                required_actions=(required_action,),
                required_caller_role="observer",
            )
        )

    renewal = (
        dict(resolution.get("renewal_resolution"))
        if isinstance(resolution.get("renewal_resolution"), Mapping)
        else {}
    )
    renewal_used = bool(renewal)
    requested_identity = (
        renewal.get("requested_route_identity")
        if isinstance(renewal.get("requested_route_identity"), Mapping)
        else {}
    )
    chain_refs = [
        str(item or "").strip()
        for item in (renewal.get("route_token_ref_chain") or [])
        if str(item or "").strip()
    ]
    edge_types = [
        str(item or "").strip()
        for item in (renewal.get("edge_types") or [])
        if str(item or "").strip()
    ]
    renewal_exact = bool(
        renewal.get("schema_version")
        == "route_token_ref_exact_renewal_descendant_resolution.v1"
        and renewal.get("status") == "resolved_active_descendant"
        and renewal.get("registry_verified") is True
        and renewal.get("exact_scope_verified") is True
        and renewal.get("writes_performed") is False
        and renewal.get("raw_route_token_exposed") is False
        and all(
            str(requested_identity.get(field) or "").strip()
            == immutable_identity[field]
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        )
        and len(chain_refs) >= 2
        and chain_refs[0] == immutable_ref
        and chain_refs[-1]
        == str(active_identity.get("route_token_ref") or "").strip()
        and len(edge_types) == len(chain_refs) - 1
        and all(
            edge in {"renewal", "same_scope_reissue"}
            for edge in edge_types
        )
    )
    identity_resolution_exact = bool(
        resolution.get("status") == "resolved_append_scoped_ref"
        and _observer_root_route_identity_complete(active_identity)
        and presented_ref
        == str(active_identity.get("route_token_ref") or "").strip()
        and (
            renewal_exact
            if renewal_used
            else active_identity == immutable_identity
        )
    )
    scope_exact = bool(
        identity_resolution_exact
        and resolution.get("scope")
        == {
            "project_id": project_id,
            "backlog_id": backlog_id,
            "task_id": task_id,
        }
    )
    missing: list[str] = []
    if not _observer_root_route_identity_complete(immutable_identity):
        missing.append("immutable_direct_route_identity_complete")
    if not presented_ref:
        missing.append("active_direct_route_token_ref")
    if resolution.get("status") != "resolved_append_scoped_ref":
        missing.append("active_direct_route_renewal_lineage_verified")
    if not identity_resolution_exact:
        missing.append("active_direct_route_matches_immutable_binding")
    if not scope_exact:
        missing.append("active_direct_route_scope_exact")
    missing = list(dict.fromkeys(missing))
    authority = {
        "schema_version": (
            "operator_supervised_direct_main.active_route_authority.v1"
        ),
        "passed": not missing,
        "status": "passed" if not missing else "failed",
        "server_derived": True,
        "caller_claims_trusted": False,
        "source": "contract_runtime.append_scoped_child_route_resolution",
        "project_id": project_id,
        "backlog_id": backlog_id,
        "task_id": task_id,
        "required_action": required_action,
        "immutable_route_identity": immutable_identity,
        "active_route_identity": dict(active_identity),
        "presented_route_token_ref": presented_ref,
        "renewal_used": renewal_used,
        "route_token_ref_chain": (
            chain_refs or ([immutable_ref] if active_identity else [])
        ),
        "edge_types": edge_types,
        "identity_resolution_exact": identity_resolution_exact,
        "scope_exact": scope_exact,
        "registry_verified": bool(
            resolution.get("status") == "resolved_append_scoped_ref"
            and (not renewal_used or renewal.get("registry_verified") is True)
        ),
        "expected_files": canonical_files,
        "resolution_error_code": str(
            resolution.get("error_code") or ""
        ).strip(),
        "resolution_error_details": resolution,
        "missing_requirement_ids": missing,
        "identity_mismatches": (
            []
            if not missing
            else [
                {
                    "field": "active_route_authority",
                    "expected": {
                        "immutable_route_token_ref": immutable_ref,
                        "active_same_scope_descendant": presented_ref,
                    },
                    "actual": dict(active_identity),
                }
            ]
        ),
        "historical_pre_mutation_event_rewritten": False,
        "writes_performed": False,
        "zero_write_on_failure": True,
        "raw_route_token_exposed": False,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _operator_supervised_direct_main_persisted_active_route_authority_valid(
    authority: Mapping[str, Any],
    *,
    project_id: str,
    backlog_id: str,
    task_id: str,
    immutable_route_identity: Mapping[str, Any],
    active_route_token_ref: str,
    expected_files: Sequence[str] = (),
) -> bool:
    """Check only the hash-bound route Fact at the reconcile position.

    This is deliberately not a second lineage resolver.  Each new protected
    action resolves the live ref; a historical reconcile only consumes the
    already-frozen, server-derived result and its exact binding links.
    """

    persisted = dict(authority) if isinstance(authority, Mapping) else {}

    def identity(value: Any) -> dict[str, str]:
        if not isinstance(value, Mapping):
            return {}
        return {
            field: str(value.get(field) or "").strip()
            for field in _RUNTIME_CONTEXT_ROUTE_IDENTITY_FIELDS
        }

    immutable = identity(immutable_route_identity)
    frozen_immutable = identity(persisted.get("immutable_route_identity"))
    frozen_active = identity(persisted.get("active_route_identity"))
    immutable_ref = immutable.get("route_token_ref", "")
    active_ref = str(active_route_token_ref or "").strip()
    chain = [
        str(item or "").strip()
        for item in (persisted.get("route_token_ref_chain") or [])
    ]
    edges = [
        str(item or "").strip()
        for item in (persisted.get("edge_types") or [])
    ]
    renewal_used = persisted.get("renewal_used") is True
    resolution = (
        persisted.get("resolution_error_details")
        if isinstance(persisted.get("resolution_error_details"), Mapping)
        else {}
    )
    renewal = (
        resolution.get("renewal_resolution")
        if isinstance(resolution.get("renewal_resolution"), Mapping)
        else {}
    )
    exact_scope = {
        "project_id": project_id,
        "backlog_id": backlog_id,
        "task_id": task_id,
    }
    frozen_resolution_common_exact = bool(
        resolution.get("schema_version")
        == "contract_runtime.append_scoped_child_route_resolution.v1"
        and resolution.get("status") == "resolved_append_scoped_ref"
        and str(resolution.get("caller_role") or "").strip() == "observer"
        and str(resolution.get("field") or "").strip()
        == "allowed_actions"
        and list(resolution.get("expected") or [])
        == ["task_timeline_append"]
        and "task_timeline_append" in list(resolution.get("actual") or [])
        and resolution.get("public_safe") is True
        and identity(resolution.get("child_route_identity"))
        == frozen_active
        and str(resolution.get("route_token_ref") or "").strip()
        == immutable_ref
        and str(
            resolution.get("requested_route_token_ref") or ""
        ).strip()
        == immutable_ref
        and str(
            resolution.get("resolved_route_token_ref") or ""
        ).strip()
        == active_ref
        and resolution.get("scope") == exact_scope
        and resolution.get("writes_performed") is False
        and resolution.get("raw_route_token_exposed") is False
    )
    frozen_resolution_links_exact = bool(
        (
            renewal.get("schema_version")
            == "route_token_ref_exact_renewal_descendant_resolution.v1"
            and renewal.get("status") == "resolved_active_descendant"
            and renewal.get("registry_verified") is True
            and renewal.get("exact_scope_verified") is True
            and renewal.get("writes_performed") is False
            and renewal.get("raw_route_token_exposed") is False
            and identity(renewal.get("requested_route_identity"))
            == immutable
            and identity(renewal.get("resolved_route_identity"))
            == frozen_active
            and str(renewal.get("requested_route_token_ref") or "").strip()
            == immutable_ref
            and str(renewal.get("resolved_route_token_ref") or "").strip()
            == active_ref
            and renewal.get("scope") == exact_scope
            and list(renewal.get("route_token_ref_chain") or []) == chain
            and list(renewal.get("edge_types") or []) == edges
        )
        if renewal_used
        else not renewal and frozen_active == immutable
    )
    lineage_links_exact = bool(
        chain
        and chain[0] == immutable_ref
        and chain[-1] == active_ref
        and len(edges) == len(chain) - 1
        and all(edge in {"renewal", "same_scope_reissue"} for edge in edges)
        and (len(chain) >= 2 if renewal_used else chain == [immutable_ref])
        and (renewal_used or not edges)
    )
    canonical_files = sorted(
        _runtime_context_service_dedupe(
            [str(path or "").strip() for path in expected_files]
        )
    )
    return bool(
        persisted.get("schema_version")
        == "operator_supervised_direct_main.active_route_authority.v1"
        and persisted.get("passed") is True
        and str(persisted.get("status") or "").strip() == "passed"
        and persisted.get("server_derived") is True
        and persisted.get("caller_claims_trusted") is False
        and str(persisted.get("source") or "").strip()
        == "contract_runtime.append_scoped_child_route_resolution"
        and persisted.get("identity_resolution_exact") is True
        and persisted.get("scope_exact") is True
        and persisted.get("registry_verified") is True
        and persisted.get("historical_pre_mutation_event_rewritten") is False
        and not str(persisted.get("resolution_error_code") or "").strip()
        and persisted.get("writes_performed") is False
        and persisted.get("zero_write_on_failure") is True
        and persisted.get("raw_route_token_exposed") is False
        and not list(persisted.get("missing_requirement_ids") or [])
        and not list(persisted.get("identity_mismatches") or [])
        and str(persisted.get("project_id") or "").strip() == project_id
        and str(persisted.get("backlog_id") or "").strip() == backlog_id
        and str(persisted.get("task_id") or "").strip() == task_id
        and str(persisted.get("required_action") or "").strip()
        == "task_timeline_append"
        and list(persisted.get("expected_files") or []) == canonical_files
        and frozen_immutable == immutable
        and _observer_root_route_identity_complete(frozen_immutable)
        and _observer_root_route_identity_complete(frozen_active)
        and frozen_active.get("route_token_ref") == active_ref
        and str(persisted.get("presented_route_token_ref") or "").strip()
        == active_ref
        and lineage_links_exact
        and frozen_resolution_common_exact
        and frozen_resolution_links_exact
        and str(persisted.get("authority_hash") or "").strip()
        == stable_sha256(
            {
                key: value
                for key, value in persisted.items()
                if key != "authority_hash"
            }
        )
    )


def _operator_supervised_direct_main_no_pass_continuation_authority(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
    target_commit: str,
    record: Mapping[str, Any],
    binding: Mapping[str, Any],
    active_route_authority: Mapping[str, Any],
) -> dict[str, Any]:
    """Authorize deposit for one exact, open Direct no-PASS generation.

    This is intentionally separate from QA authority.  It only permits the
    already-implemented commit to reach the canonical graph/runtime world and
    never satisfies Direct close or rewrites a bypassed business line as PASS.
    """

    target_commit = str(target_commit or "").strip().lower()
    missing: list[str] = []
    completed_lines = [
        dict(line)
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
    ]
    implementation_lines = [
        line
        for line in completed_lines
        if str(line.get("line_id") or "").strip()
        == "observer_implementation"
    ]
    binding_hash = str(binding.get("binding_hash") or "").strip()
    immutable_route_identity = (
        binding.get("route_identity")
        if isinstance(binding.get("route_identity"), Mapping)
        else {}
    )
    immutable_route_ref = str(
        immutable_route_identity.get("route_token_ref") or ""
    ).strip()
    active_route_chain = {
        str(item or "").strip()
        for item in active_route_authority.get("route_token_ref_chain") or []
        if str(item or "").strip()
    }
    if immutable_route_ref:
        active_route_chain.add(immutable_route_ref)
    implementation = implementation_lines[0] if len(implementation_lines) == 1 else {}
    implementation_payload = (
        implementation.get("payload")
        if isinstance(implementation.get("payload"), Mapping)
        else {}
    )
    implementation_route_ref = str(
        implementation.get("route_token_ref")
        or implementation_payload.get("route_token_ref")
        or ""
    ).strip()
    if not (
        len(implementation_lines) == 1
        and str(implementation.get("commit_sha") or "").strip().lower()
        == target_commit
        and str(
            implementation_payload.get("direct_runtime_binding_hash") or ""
        ).strip()
        == binding_hash
        and binding_hash
        and implementation_route_ref
        and implementation_route_ref in active_route_chain
        and active_route_authority.get("passed") is True
    ):
        missing.append("exact_no_pass_implementation_binding")

    bypass_lines = [
        line
        for line in completed_lines
        if str(line.get("evidence_kind") or "").strip()
        == "contract_line_bypass"
    ]

    def bypass_parts(line: Mapping[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
        payload = (
            dict(line.get("payload"))
            if isinstance(line.get("payload"), Mapping)
            else {}
        )
        generation = (
            dict(payload.get("no_pass_generation"))
            if isinstance(payload.get("no_pass_generation"), Mapping)
            else {}
        )
        return payload, generation

    root_lines = []
    for line in bypass_lines:
        _payload, generation = bypass_parts(line)
        if str(generation.get("role") or "").strip() == "root":
            root_lines.append(line)
    root_line = root_lines[0] if len(root_lines) == 1 else {}
    root_payload, root_generation = bypass_parts(root_line)
    generation_id = str(root_generation.get("generation_id") or "").strip()
    diagnostic_backlog_id = str(
        root_payload.get("diagnostic_backlog_id")
        or root_generation.get("root_diagnostic_backlog_id")
        or ""
    ).strip()
    classification = str(
        root_payload.get("classification")
        or root_generation.get("root_classification")
        or ""
    ).strip()
    root_bypass_identity = str(
        root_payload.get("bypass_identity")
        or root_generation.get("root_bypass_identity")
        or ""
    ).strip()
    if not (
        len(root_lines) == 1
        and str(root_line.get("line_id") or "").strip()
        == "qa_graph_context"
        and str(root_line.get("status") or "").strip().lower() == "waived"
        and root_line.get("no_pass_claim") is True
        and root_payload.get("schema_version") == "contract_line_bypass.v1"
        and root_payload.get("no_pass_claim") is True
        and str(root_payload.get("source_backlog_id") or "").strip()
        == backlog_id
        and root_generation.get("schema_version")
        == "contract_line_bypass_generation_link.v1"
        and root_generation.get("no_pass_claim") is True
        and root_generation.get("authoritative_pass_synthesized") is False
        and root_generation.get("diagnostic_created") is True
        and generation_id
        and diagnostic_backlog_id
        and classification
        and root_bypass_identity
    ):
        missing.append("unique_exact_no_pass_root")

    required_line_ids = {
        "qa_graph_context",
        "qa_independent_verification",
        "observer_reconcile",
    }
    generation_lines: dict[str, list[dict[str, Any]]] = {}
    invalid_generation_line = False
    for line in bypass_lines:
        payload, generation = bypass_parts(line)
        line_id = str(line.get("line_id") or "").strip()
        line_generation_id = str(generation.get("generation_id") or "").strip()
        if line_id in required_line_ids:
            generation_lines.setdefault(line_id, []).append(line)
        expected_role = "root" if line_id == "qa_graph_context" else "inherited_gate"
        if line_id in required_line_ids and not (
            str(line.get("status") or "").strip().lower() == "waived"
            and line.get("no_pass_claim") is True
            and payload.get("no_pass_claim") is True
            and str(payload.get("source_backlog_id") or "").strip()
            == backlog_id
            and str(payload.get("diagnostic_backlog_id") or "").strip()
            == diagnostic_backlog_id
            and str(payload.get("classification") or "").strip()
            == classification
            and line_generation_id == generation_id
            and str(generation.get("role") or "").strip() == expected_role
            and str(generation.get("root_bypass_identity") or "").strip()
            == root_bypass_identity
            and str(
                generation.get("root_diagnostic_backlog_id") or ""
            ).strip()
            == diagnostic_backlog_id
            and generation.get("authoritative_pass_synthesized") is False
        ):
            invalid_generation_line = True
    if invalid_generation_line or any(
        len(generation_lines.get(line_id) or []) != 1
        for line_id in required_line_ids
    ):
        missing.append("exact_no_pass_generation_gate_chain")

    diagnostic_status = ""
    diagnostic_chain: dict[str, Any] = {}
    diagnostic_policy: dict[str, Any] = {}
    if diagnostic_backlog_id:
        diagnostic_rows = conn.execute(
            "SELECT status, chain_trigger_json, bypass_policy_json "
            "FROM backlog_bugs WHERE bug_id = ?",
            (diagnostic_backlog_id,),
        ).fetchall()
    else:
        diagnostic_rows = []
    if len(diagnostic_rows) == 1:
        diagnostic_status = str(diagnostic_rows[0]["status"] or "").strip().upper()
        diagnostic_chain = backlog_runtime.parse_json_object(
            diagnostic_rows[0]["chain_trigger_json"]
        )
        diagnostic_policy = backlog_runtime.parse_json_object(
            diagnostic_rows[0]["bypass_policy_json"]
        )
    if not (
        len(diagnostic_rows) == 1
        and diagnostic_status == "OPEN"
        and all(
            str(diagnostic_chain.get(key) or "").strip() == expected
            for key, expected in (
                ("source_backlog_id", backlog_id),
                ("contract_execution_id", contract_execution_id),
                ("line_id", "qa_graph_context"),
                ("no_pass_generation_id", generation_id),
                ("root_bypass_identity", root_bypass_identity),
                ("classification", classification),
            )
        )
        and diagnostic_chain.get("no_pass_claim") is True
        and diagnostic_chain.get("authoritative_pass_synthesized") is False
        and all(
            str(diagnostic_policy.get(key) or "").strip() == expected
            for key, expected in (
                ("source_backlog_id", backlog_id),
                ("contract_execution_id", contract_execution_id),
                ("line_id", "qa_graph_context"),
                ("no_pass_generation_id", generation_id),
                ("root_bypass_identity", root_bypass_identity),
                ("classification", classification),
            )
        )
        and diagnostic_policy.get("no_pass_claim") is True
        and diagnostic_policy.get("authoritative_pass_synthesized") is False
        and diagnostic_policy.get("keep_open") is True
    ):
        missing.append("open_exact_no_pass_diagnostic")

    root_evidence_refs = [
        str(item or "").strip()
        for item in root_payload.get("evidence_refs") or []
        if str(item or "").strip()
    ]
    candidate_snapshots: list[dict[str, Any]] = []
    for evidence_ref in root_evidence_refs:
        rows = conn.execute(
            "SELECT snapshot_id, commit_sha, snapshot_kind, status "
            "FROM graph_snapshots WHERE project_id = ? AND snapshot_id = ?",
            (project_id, evidence_ref),
        ).fetchall()
        for row in rows:
            candidate = dict(row)
            if (
                str(candidate.get("commit_sha") or "").strip().lower()
                == target_commit
                and str(candidate.get("snapshot_kind") or "").strip()
                == "full"
                and str(candidate.get("status") or "").strip().lower()
                in {"candidate", "active"}
            ):
                candidate_snapshots.append(candidate)
    unique_candidates = {
        str(candidate.get("snapshot_id") or "").strip(): candidate
        for candidate in candidate_snapshots
        if str(candidate.get("snapshot_id") or "").strip()
    }
    candidate_snapshot = (
        next(iter(unique_candidates.values()))
        if len(unique_candidates) == 1
        else {}
    )
    if not candidate_snapshot:
        missing.append("unique_exact_no_pass_candidate_snapshot")

    authority = {
        "schema_version": (
            "operator_supervised_direct_main."
            "no_pass_continuation_authority.v1"
        ),
        "applicable": bool(bypass_lines),
        "passed": not missing,
        "status": "passed" if not missing else "failed",
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": contract_execution_id,
        "target_commit_sha": target_commit,
        "implementation_commit_sha": str(
            implementation.get("commit_sha") or ""
        ).strip().lower(),
        "implementation_binding_hash": str(
            implementation_payload.get("direct_runtime_binding_hash") or ""
        ).strip(),
        "no_pass_generation_id": generation_id,
        "root_bypass_identity": root_bypass_identity,
        "classification": classification,
        "diagnostic_backlog_id": diagnostic_backlog_id,
        "diagnostic_status": diagnostic_status,
        "candidate_snapshot_id": str(
            candidate_snapshot.get("snapshot_id") or ""
        ).strip(),
        "candidate_snapshot_commit": str(
            candidate_snapshot.get("commit_sha") or ""
        ).strip().lower(),
        "candidate_snapshot_status": str(
            candidate_snapshot.get("status") or ""
        ).strip().lower(),
        "bypassed_line_ids": sorted(generation_lines),
        "qa_passed": False,
        "no_pass_claim": True,
        "authoritative_pass_synthesized": False,
        "deposit_only": True,
        "close_satisfying": False,
        "diagnostic_keep_open_required": True,
        "missing_requirement_ids": missing,
        "zero_write_on_failure": True,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _operator_supervised_direct_main_reconcile_qa_preflight_authority(
    conn,
    *,
    project_id: str,
    target_commit: str,
    current_full_auth: Mapping[str, Any],
) -> dict[str, Any]:
    """Require the exact pinned Direct QA Fact before current-full mutates."""

    from . import task_timeline

    route_scope = (
        current_full_auth.get("route_token_scope")
        if isinstance(current_full_auth.get("route_token_scope"), Mapping)
        else {}
    )
    backlog_id = str(route_scope.get("backlog_id") or "").strip()
    task_id = str(route_scope.get("task_id") or "").strip()
    try:
        record = _contract_runtime_store(conn).get(task_id)
    except ContractRuntimeError:
        record = {}
    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    applicable = bool(
        str(record.get("contract_id") or "").strip()
        == "operator_supervised_direct_main"
        and str(record.get("revision") or "").strip()
        in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        and binding.get("strict_runtime_binding_required") is True
    )
    if not applicable:
        return {
            "schema_version": (
                "operator_supervised_direct_main."
                "reconcile_qa_preflight_authority.v1"
            ),
            "applicable": False,
            "status": "not_applicable",
            "server_derived": True,
            "caller_claims_trusted": False,
        }

    target_commit = str(target_commit or "").strip().lower()
    missing: list[str] = []
    route_identity = (
        binding.get("route_identity")
        if isinstance(binding.get("route_identity"), Mapping)
        else {}
    )
    active_route_authority = (
        _operator_supervised_direct_main_active_route_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
            immutable_route_identity=route_identity,
            active_route_token_ref=str(
                current_full_auth.get("route_token_ref") or ""
            ),
            expected_files=list(binding.get("owned_files") or []),
        )
    )
    if not (
        str(record.get("project_id") or "").strip() == project_id
        and str(record.get("backlog_id") or "").strip() == backlog_id
        and str(record.get("contract_execution_id") or "").strip() == task_id
        and active_route_authority.get("passed") is True
    ):
        missing.append("direct_runtime_route_scope_exact")
    implementation_commits = _runtime_context_service_dedupe(
        [
            str(line.get("commit_sha") or "").strip().lower()
            for line in record.get("completed_lines") or []
            if isinstance(line, Mapping)
            and str(line.get("line_id") or "").strip()
            == "observer_implementation"
        ]
    )
    if implementation_commits != [target_commit]:
        missing.append("exact_direct_implementation_commit")

    completed_lines = [
        line
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
    ]
    qa_graph_lines = [
        line
        for line in completed_lines
        if str(line.get("line_id") or "").strip() == "qa_graph_context"
    ]
    qa_verdict_lines = [
        line
        for line in completed_lines
        if str(line.get("line_id") or "").strip()
        == "qa_independent_verification"
    ]
    runtime_position = _runtime_current_state_from_record(record)
    runtime_next = (
        runtime_position.get("next_legal_action")
        if isinstance(
            runtime_position.get("next_legal_action"), Mapping
        )
        else {}
    )
    if not (
        len(qa_graph_lines) == 1
        and len(qa_verdict_lines) == 1
        and str(qa_verdict_lines[0].get("commit_sha") or "")
        .strip()
        .lower()
        == target_commit
        and str(qa_verdict_lines[0].get("status") or "")
        .strip()
        .lower()
        in {"accepted", "completed", "ok", "pass", "passed", "succeeded"}
        and str(runtime_next.get("line_id") or "").strip()
        == "observer_reconcile"
    ):
        missing.append("contract_runtime_qa_position_exact")

    qa_candidates: list[dict[str, Any]] = []
    for event in task_timeline.list_events(
        conn,
        project_id,
        backlog_id=backlog_id,
        task_id=task_id,
        limit=1000,
    ):
        if str(event.get("event_kind") or "").strip().lower() not in (
            _QA_TIMELINE_VERIFICATION_EVENT_KINDS
        ):
            continue
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        authority = _contract_runtime_close_authority_first_deep_mapping(
            payload,
            "source_backed_contract_gate_authority",
        )
        proof = (
            authority.get("qa_session_proof")
            if isinstance(authority.get("qa_session_proof"), Mapping)
            else {}
        )
        if not (
            task_timeline._event_passed(event)
            and str(event.get("commit_sha") or "").strip().lower()
            == target_commit
            and task_timeline._source_backed_qa_session_authority_valid(
                authority,
                conn=conn,
            )
            and str(proof.get("project_id") or "").strip() == project_id
            and str(proof.get("backlog_id") or "").strip() == backlog_id
            and str(proof.get("task_id") or "").strip() == task_id
            and str(proof.get("commit_sha") or "").strip().lower()
            == target_commit
            and str(proof.get("snapshot_id") or "").strip()
            and _operator_supervised_direct_main_reconcile_qa_candidate_matches_target(
                proof,
                target_commit=target_commit,
            )
        ):
            continue
        qa_candidates.append(
            {
                "qa_event_id": int(event.get("id") or 0),
                "qa_event_ref": f"timeline:{int(event.get('id') or 0)}",
                "qa_snapshot_id": str(proof.get("snapshot_id") or "").strip(),
                "qa_session_id": str(
                    proof.get("qa_session_id") or ""
                ).strip(),
                "qa_authority_hash": str(
                    authority.get("authority_hash") or ""
                ).strip(),
            }
        )
    if len(qa_candidates) != 1:
        missing.append("unique_authenticated_qa_before_reconcile")
    qa_candidate = qa_candidates[0] if len(qa_candidates) == 1 else {}
    runtime_qa_authority_hashes = {
        str(
            (
                (line.get("payload") or {}).get("qa_authority")
                if isinstance(line.get("payload"), Mapping)
                and isinstance(
                    (line.get("payload") or {}).get("qa_authority"),
                    Mapping,
                )
                else {}
            ).get("authority_hash")
            or ""
        ).strip()
        for line in [*qa_graph_lines, *qa_verdict_lines]
    }
    if not (
        len(qa_graph_lines) == 1
        and len(qa_verdict_lines) == 1
        and qa_candidate
        and runtime_qa_authority_hashes
        == {str(qa_candidate.get("qa_authority_hash") or "").strip()}
    ):
        missing.append("contract_runtime_qa_authority_exact")
    qa_graph_line_hash = (
        stable_sha256(dict(qa_graph_lines[0]))
        if len(qa_graph_lines) == 1
        else ""
    )
    qa_verdict_line_hash = (
        stable_sha256(dict(qa_verdict_lines[0]))
        if len(qa_verdict_lines) == 1
        else ""
    )
    no_pass_continuation_authority = (
        _operator_supervised_direct_main_no_pass_continuation_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            contract_execution_id=task_id,
            target_commit=target_commit,
            record=record,
            binding=binding,
            active_route_authority=active_route_authority,
        )
    )
    qa_passed = not missing
    no_pass_continuation_passed = bool(
        no_pass_continuation_authority.get("passed") is True
    )
    mutation_allowed = bool(qa_passed or no_pass_continuation_passed)
    authority = {
        "schema_version": (
            "operator_supervised_direct_main."
            "reconcile_qa_preflight_authority.v1"
        ),
        "applicable": True,
        # ``passed`` remains the business QA result.  A no-PASS generation can
        # authorize deposit, but it must never be projected as QA success.
        "passed": qa_passed,
        "qa_passed": qa_passed,
        "mutation_allowed": mutation_allowed,
        "authority_mode": (
            "qa_pass"
            if qa_passed
            else "no_pass_continuation"
            if no_pass_continuation_passed
            else "blocked"
        ),
        "status": (
            "passed"
            if qa_passed
            else "no_pass_continuation"
            if no_pass_continuation_passed
            else "failed"
        ),
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": task_id,
        "target_commit_sha": target_commit,
        "active_route_authority": active_route_authority,
        **qa_candidate,
        "qa_candidate_count": len(qa_candidates),
        "contract_runtime_execution_state_revision": int(
            runtime_position.get("execution_state_revision") or 0
        ),
        "contract_runtime_execution_state_hash": str(
            runtime_position.get("execution_state_hash") or ""
        ).strip(),
        "contract_runtime_runtime_guide_hash": str(
            runtime_position.get("runtime_guide_hash") or ""
        ).strip(),
        "contract_runtime_next_line_id": str(
            runtime_next.get("line_id") or ""
        ).strip(),
        "contract_runtime_qa_graph_line_hash": qa_graph_line_hash,
        "contract_runtime_qa_verdict_line_hash": qa_verdict_line_hash,
        "no_pass_continuation_authority": (
            no_pass_continuation_authority
        ),
        "authoritative_pass_synthesized": False,
        "close_satisfying": qa_passed,
        "missing_requirement_ids": missing,
        "mutation_blocking_requirement_ids": (
            [] if mutation_allowed else list(missing)
        ),
        "zero_write_on_failure": True,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _operator_supervised_direct_main_current_full_reconcile_authority(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
    record: Mapping[str, Any],
) -> dict[str, Any]:
    """Project one exact Direct current-full provenance from existing Facts."""

    from . import graph_snapshot_store, task_timeline

    metadata = record.get("metadata") if isinstance(record.get("metadata"), Mapping) else {}
    binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    implementation_commits = _runtime_context_service_dedupe(
        [
            str(line.get("commit_sha") or "").strip().lower()
            for line in record.get("completed_lines") or []
            if isinstance(line, Mapping)
            and str(line.get("line_id") or "").strip()
            == "observer_implementation"
            and re.fullmatch(
                r"[0-9a-f]{40}|[0-9a-f]{64}",
                str(line.get("commit_sha") or "").strip().lower(),
            )
        ]
    )
    if len(implementation_commits) != 1:
        return {}
    implementation_commit = implementation_commits[0]
    try:
        project_root = Path(
            project_service.resolve_project_root(
                project_id,
                None,
                fallback_self=True,
            )
        ).resolve()
    except Exception:
        return {}
    canonical_head = _git_head_commit(project_root).strip().lower()
    if canonical_head != implementation_commit:
        return {}
    qa_candidates: list[dict[str, Any]] = []
    for event in task_timeline.list_events(
        conn,
        project_id,
        backlog_id=backlog_id,
        task_id=contract_execution_id,
        limit=1000,
    ):
        event_kind = str(event.get("event_kind") or "").strip().lower()
        if event_kind not in _QA_TIMELINE_VERIFICATION_EVENT_KINDS:
            continue
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        authority = _contract_runtime_close_authority_first_deep_mapping(
            payload,
            "source_backed_contract_gate_authority",
        )
        proof = (
            authority.get("qa_session_proof")
            if isinstance(authority.get("qa_session_proof"), Mapping)
            else {}
        )
        if not (
            task_timeline._event_passed(event)
            and str(event.get("commit_sha") or "").strip().lower()
            == implementation_commit
            and task_timeline._source_backed_qa_session_authority_valid(
                authority,
                conn=conn,
            )
            and str(proof.get("project_id") or "").strip() == project_id
            and str(proof.get("backlog_id") or "").strip() == backlog_id
            and str(proof.get("task_id") or "").strip()
            == contract_execution_id
            and str(proof.get("commit_sha") or "").strip().lower()
            == implementation_commit
            and str(proof.get("snapshot_id") or "").strip()
            and _operator_supervised_direct_main_reconcile_qa_candidate_matches_target(
                proof,
                target_commit=implementation_commit,
            )
        ):
            continue
        qa_candidates.append(
            {
                "event_id": int(event.get("id") or 0),
                "event_ref": f"timeline:{int(event.get('id') or 0)}",
                "snapshot_id": str(proof.get("snapshot_id") or "").strip(),
                "snapshot_commit_sha": str(
                    proof.get("snapshot_commit_sha") or ""
                ).strip().lower(),
                "qa_session_id": str(
                    proof.get("qa_session_id") or ""
                ).strip(),
                "authority_hash": str(
                    authority.get("authority_hash") or ""
                ).strip(),
            }
        )
    qa_authority = qa_candidates[0] if len(qa_candidates) == 1 else {}
    current_qa_graph_lines = [
        line
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
        and str(line.get("line_id") or "").strip() == "qa_graph_context"
    ]
    current_qa_verdict_lines = [
        line
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
        and str(line.get("line_id") or "").strip()
        == "qa_independent_verification"
    ]
    current_qa_graph_line_hash = (
        stable_sha256(dict(current_qa_graph_lines[0]))
        if len(current_qa_graph_lines) == 1
        else ""
    )
    current_qa_verdict_line_hash = (
        stable_sha256(dict(current_qa_verdict_lines[0]))
        if len(current_qa_verdict_lines) == 1
        else ""
    )
    try:
        rows = conn.execute(
            """
            SELECT *
              FROM graph_current_full_reconcile_provenance
             WHERE project_id = ? AND target_commit_sha = ?
             ORDER BY reconcile_event_id DESC, created_at DESC,
                      provenance_id DESC
            """,
            (project_id, implementation_commit),
        ).fetchall()
    except sqlite3.Error:
        return {}
    candidates: list[dict[str, Any]] = []
    for raw_row in rows:
        provenance = dict(raw_row)
        route_evidence = _json_loads(
            provenance.get("route_evidence_json"),
            {},
        )
        marker = _json_loads(provenance.get("marker_json"), {})
        marker_core = dict(marker)
        marker_hash = str(
            marker_core.pop("provenance_hash", "") or ""
        ).strip()
        qa_preflight = (
            route_evidence.get("direct_main_qa_preflight_authority")
            if isinstance(route_evidence, Mapping)
            and isinstance(
                route_evidence.get(
                    "direct_main_qa_preflight_authority"
                ),
                Mapping,
            )
            else {}
        )
        reconcile_active_route_authority = (
            qa_preflight.get("active_route_authority")
            if isinstance(
                qa_preflight.get("active_route_authority"), Mapping
            )
            else {}
        )
        binding_route_identity = (
            binding.get("route_identity")
            if isinstance(binding.get("route_identity"), Mapping)
            else {}
        )
        provenance_route_token_ref = str(
            route_evidence.get("route_token_ref")
            if isinstance(route_evidence, Mapping)
            else ""
        ).strip()
        persisted_active_route_authority_valid = (
            _operator_supervised_direct_main_persisted_active_route_authority_valid(
                reconcile_active_route_authority,
                project_id=project_id,
                backlog_id=backlog_id,
                task_id=contract_execution_id,
                immutable_route_identity=binding_route_identity,
                active_route_token_ref=provenance_route_token_ref,
                expected_files=list(binding.get("owned_files") or []),
            )
        )
        reconcile_event_id = int(
            provenance.get("reconcile_event_id") or 0
        )
        persisted_no_pass_authority = (
            qa_preflight.get("no_pass_continuation_authority")
            if isinstance(
                qa_preflight.get("no_pass_continuation_authority"),
                Mapping,
            )
            else {}
        )
        current_no_pass_authority = (
            _operator_supervised_direct_main_no_pass_continuation_authority(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                contract_execution_id=contract_execution_id,
                target_commit=implementation_commit,
                record=record,
                binding=binding,
                active_route_authority=reconcile_active_route_authority,
            )
        )
        no_pass_identity_fields = (
            "project_id",
            "backlog_id",
            "contract_execution_id",
            "target_commit_sha",
            "implementation_commit_sha",
            "implementation_binding_hash",
            "no_pass_generation_id",
            "root_bypass_identity",
            "classification",
            "diagnostic_backlog_id",
            "candidate_snapshot_id",
            "candidate_snapshot_commit",
            "bypassed_line_ids",
        )
        no_pass_mode_valid = bool(
            qa_preflight.get("passed") is False
            and qa_preflight.get("qa_passed") is False
            and qa_preflight.get("mutation_allowed") is True
            and str(qa_preflight.get("authority_mode") or "").strip()
            == "no_pass_continuation"
            and str(qa_preflight.get("status") or "").strip()
            == "no_pass_continuation"
            and int(qa_preflight.get("qa_candidate_count") or 0) == 0
            and qa_preflight.get("authoritative_pass_synthesized") is False
            and qa_preflight.get("close_satisfying") is False
            and not list(
                qa_preflight.get("mutation_blocking_requirement_ids") or []
            )
            and persisted_no_pass_authority.get("passed") is True
            and persisted_no_pass_authority.get("qa_passed") is False
            and persisted_no_pass_authority.get("no_pass_claim") is True
            and persisted_no_pass_authority.get(
                "authoritative_pass_synthesized"
            )
            is False
            and persisted_no_pass_authority.get("deposit_only") is True
            and persisted_no_pass_authority.get("close_satisfying") is False
            and str(
                persisted_no_pass_authority.get("authority_hash") or ""
            ).strip()
            == stable_sha256(
                {
                    key: value
                    for key, value in persisted_no_pass_authority.items()
                    if key != "authority_hash"
                }
            )
            and current_no_pass_authority.get("passed") is True
            and current_no_pass_authority.get("qa_passed") is False
            and current_no_pass_authority.get("no_pass_claim") is True
            and current_no_pass_authority.get(
                "authoritative_pass_synthesized"
            )
            is False
            and current_no_pass_authority.get("deposit_only") is True
            and current_no_pass_authority.get("close_satisfying") is False
            and all(
                persisted_no_pass_authority.get(field)
                == current_no_pass_authority.get(field)
                for field in no_pass_identity_fields
            )
            and str(
                current_no_pass_authority.get("candidate_snapshot_id") or ""
            ).strip()
            == str(provenance.get("snapshot_id") or "").strip()
        )
        qa_mode_valid = bool(
            len(qa_candidates) == 1
            and int(qa_authority.get("event_id") or 0) > 0
            and int(qa_authority.get("event_id") or 0) < reconcile_event_id
            and qa_preflight.get("passed") is True
            and qa_preflight.get("qa_passed") is True
            and qa_preflight.get("mutation_allowed") is True
            and str(qa_preflight.get("authority_mode") or "").strip()
            == "qa_pass"
            and str(qa_preflight.get("status") or "").strip() == "passed"
            and qa_preflight.get("close_satisfying") is True
            and int(qa_preflight.get("qa_event_id") or 0)
            == int(qa_authority.get("event_id") or 0)
            and str(qa_preflight.get("qa_snapshot_id") or "").strip()
            == str(qa_authority.get("snapshot_id") or "").strip()
            and str(qa_preflight.get("qa_authority_hash") or "").strip()
            == str(qa_authority.get("authority_hash") or "").strip()
            and str(
                qa_preflight.get("contract_runtime_next_line_id") or ""
            ).strip()
            == "observer_reconcile"
            and not list(qa_preflight.get("missing_requirement_ids") or [])
        )
        if not (
            reconcile_event_id > 0
            and isinstance(route_evidence, Mapping)
            and isinstance(marker, Mapping)
            and str(provenance.get("protected_action") or "").strip()
            == "graph_current_full_reconcile"
            and str(
                provenance.get("protected_entrypoint") or ""
            ).strip()
            == (
                "POST /api/graph-governance/{project_id}/"
                "reconcile/current-full"
            )
            and str(provenance.get("provenance_hash") or "").strip()
            == marker_hash
            and marker_hash == stable_sha256(marker_core)
            and marker.get("route_evidence") == route_evidence
            and route_evidence.get("schema_version")
            == "graph_current_full_reconcile.route_evidence.v1"
            and route_evidence.get("protected_action")
            == "graph_current_full_reconcile"
            and route_evidence.get("raw_route_token_persisted") is False
            and persisted_active_route_authority_valid
            and qa_preflight.get("schema_version")
            == (
                "operator_supervised_direct_main."
                "reconcile_qa_preflight_authority.v1"
            )
            and qa_preflight.get("applicable") is True
            and qa_preflight.get("server_derived") is True
            and qa_preflight.get("caller_claims_trusted") is False
            and str(qa_preflight.get("project_id") or "").strip()
            == project_id
            and str(qa_preflight.get("backlog_id") or "").strip()
            == backlog_id
            and str(
                qa_preflight.get("contract_execution_id") or ""
            ).strip()
            == contract_execution_id
            and qa_preflight.get("authoritative_pass_synthesized") is False
            and str(qa_preflight.get("target_commit_sha") or "")
            .strip()
            .lower()
            == implementation_commit
            and str(
                qa_preflight.get(
                    "contract_runtime_qa_graph_line_hash"
                )
                or ""
            ).strip()
            == current_qa_graph_line_hash
            and str(
                qa_preflight.get(
                    "contract_runtime_qa_verdict_line_hash"
                )
                or ""
            ).strip()
            == current_qa_verdict_line_hash
            and str(qa_preflight.get("authority_hash") or "").strip()
            == stable_sha256(
                {
                    key: value
                    for key, value in qa_preflight.items()
                    if key != "authority_hash"
                }
            )
            and (qa_mode_valid or no_pass_mode_valid)
            and marker.get("schema_version")
            == "current_full_reconcile.provenance.v2"
            and marker.get("protected_action")
            == "graph_current_full_reconcile"
            and marker.get("activate") is True
            and marker.get("normal_update_path") is True
            and str(marker.get("target_commit_sha") or "").strip().lower()
            == implementation_commit
        ):
            continue
        route_scope = (
            route_evidence.get("route_token_scope")
            if isinstance(route_evidence.get("route_token_scope"), Mapping)
            else {}
        )
        if not (
            str(route_scope.get("project_id") or "").strip() == project_id
            and str(route_scope.get("backlog_id") or "").strip()
            == backlog_id
            and str(route_scope.get("task_id") or "").strip()
            == contract_execution_id
        ):
            continue
        event_rows = conn.execute(
            """
            SELECT * FROM task_timeline_events
             WHERE project_id = ? AND id = ?
            """,
            (project_id, reconcile_event_id),
        ).fetchall()
        if len(event_rows) != 1:
            continue
        event = dict(event_rows[0])
        if not (
            str(event.get("backlog_id") or "").strip() == backlog_id
            and str(event.get("task_id") or "").strip()
            == contract_execution_id
            and str(event.get("event_type") or "").strip()
            == "graph.reconcile"
            and str(event.get("event_kind") or "").strip() == "reconcile"
            and str(event.get("status") or "").strip().lower()
            in {"accepted", "ok", "passed", "succeeded"}
            and str(event.get("commit_sha") or "").strip().lower()
            == implementation_commit
        ):
            continue
        snapshot_id = str(provenance.get("snapshot_id") or "").strip()
        snapshot_rows = conn.execute(
            """
            SELECT *
              FROM graph_snapshots
             WHERE project_id = ? AND snapshot_id = ?
            """,
            (project_id, snapshot_id),
        ).fetchall()
        if not (
            len(snapshot_rows) == 1
            and str(snapshot_rows[0]["commit_sha"] or "").strip().lower()
            == implementation_commit
            and str(snapshot_rows[0]["status"] or "").strip().lower()
            == "active"
            and str(marker.get("snapshot_id") or "").strip()
            == snapshot_id
        ):
            continue
        provenance_binding = (
            graph_snapshot_store._current_full_snapshot_provenance_binding(
                conn,
                project_id,
                dict(snapshot_rows[0]),
            )
        )
        if not (
            provenance_binding.get("verified") is True
            and str(provenance_binding.get("provenance_id") or "").strip()
            == str(provenance.get("provenance_id") or "").strip()
            and str(provenance_binding.get("provenance_hash") or "").strip()
            == str(provenance.get("provenance_hash") or "").strip()
            and int(provenance_binding.get("reconcile_event_id") or 0)
            == reconcile_event_id
        ):
            continue
        candidate = {
            "schema_version": (
                "operator_supervised_direct_main."
                "current_full_reconcile_authority.v1"
            ),
            "server_derived": True,
            "caller_claims_trusted": False,
            "db_verified": True,
            "current_full_reconcile": True,
            "canonical_head_verified": True,
            "active_snapshot_verified": True,
            "project_id": project_id,
            "backlog_id": backlog_id,
            "contract_execution_id": contract_execution_id,
            "target_commit_sha": implementation_commit,
            "canonical_head_commit": canonical_head,
            "active_snapshot_id": snapshot_id,
            "active_snapshot_commit": implementation_commit,
            "reconcile_event_ref": f"timeline:{reconcile_event_id}",
            "reconcile_event_id": reconcile_event_id,
            "reconcile_event_created_at": str(
                provenance.get("reconcile_event_created_at") or ""
            ).strip(),
            "authority_mode": (
                "qa_pass" if qa_mode_valid else "no_pass_continuation"
            ),
            "qa_passed": qa_mode_valid,
            "qa_event_ref": (
                str(qa_authority.get("event_ref") or "")
                if qa_mode_valid
                else ""
            ),
            "qa_event_id": (
                int(qa_authority.get("event_id") or 0)
                if qa_mode_valid
                else 0
            ),
            "qa_snapshot_id": (
                str(qa_authority.get("snapshot_id") or "")
                if qa_mode_valid
                else ""
            ),
            "qa_snapshot_commit": (
                implementation_commit if qa_mode_valid else ""
            ),
            "qa_session_id": (
                str(qa_authority.get("qa_session_id") or "")
                if qa_mode_valid
                else ""
            ),
            "qa_authority_hash": (
                str(qa_authority.get("authority_hash") or "")
                if qa_mode_valid
                else ""
            ),
            "qa_before_reconcile_verified": qa_mode_valid,
            "no_pass_continuation_verified": no_pass_mode_valid,
            "no_pass_claim": no_pass_mode_valid,
            "authoritative_pass_synthesized": False,
            "deposit_only": no_pass_mode_valid,
            "close_satisfying": qa_mode_valid,
            "no_pass_continuation_authority": (
                dict(current_no_pass_authority)
                if no_pass_mode_valid
                else {}
            ),
            "no_pass_generation_id": (
                str(
                    current_no_pass_authority.get(
                        "no_pass_generation_id"
                    )
                    or ""
                )
                if no_pass_mode_valid
                else ""
            ),
            "diagnostic_backlog_id": (
                str(
                    current_no_pass_authority.get(
                        "diagnostic_backlog_id"
                    )
                    or ""
                )
                if no_pass_mode_valid
                else ""
            ),
            "immutable_route_identity_preserved": True,
            "provenance_id": str(
                provenance.get("provenance_id") or ""
            ).strip(),
            "provenance_hash": str(
                provenance.get("provenance_hash") or ""
            ).strip(),
            "route_evidence": dict(route_evidence),
            "current_full_reconcile_marker": dict(marker),
        }
        candidate["authority_hash"] = stable_sha256(candidate)
        candidates.append(candidate)
    unique = {stable_sha256(candidate): candidate for candidate in candidates}
    return next(iter(unique.values())) if len(unique) == 1 else {}


def _operator_supervised_direct_main_runtime_deployment_authority(
    *,
    project_id: str,
    close_commit: str,
) -> dict[str, Any]:
    """Project self-runtime applicability and exact loaded-commit identity."""

    close_commit = str(close_commit or "").strip().lower()
    try:
        project_root = Path(
            project_service.resolve_project_root(
                project_id,
                None,
                fallback_self=True,
            )
        ).resolve()
    except Exception:
        project_root = Path()
    self_root = Path(__file__).resolve().parents[2]
    applicable = bool(project_id == "aming-claw" or project_root == self_root)
    authority: dict[str, Any] = {
        "schema_version": (
            "operator_supervised_direct_main.runtime_deployment_authority.v1"
        ),
        "applicable": applicable,
        "status": "not_applicable",
        "source": "governance_loaded_runtime_identity",
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "project_root": str(project_root) if project_root else "",
        "governance_runtime_root": str(self_root),
        "close_commit": close_commit,
        "loaded_commit": "",
        "runtime_stale": None,
        "runtime_stale_reasons": [],
    }
    if applicable:
        runtime_identity = governance_loaded_runtime_identity(
            get_server_version()
        )
        loaded_ref = str(runtime_identity.get("loaded_commit") or "").strip()
        loaded_commit = ""
        if loaded_ref:
            loaded_commit = _git_output(
                self_root,
                ["rev-parse", "--verify", f"{loaded_ref}^{{commit}}"],
            ).strip().lower()
        passed = bool(
            loaded_commit == close_commit
            and runtime_identity.get("runtime_stale") is False
        )
        authority.update(
            {
                "passed": passed,
                "status": "passed" if passed else "failed",
                "loaded_commit": loaded_commit,
                "runtime_stale": bool(
                    runtime_identity.get("runtime_stale")
                ),
                "runtime_stale_reasons": list(
                    runtime_identity.get("runtime_stale_reasons") or []
                ),
            }
        )
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _operator_supervised_direct_main_runtime_sync_or_redeploy_passed(
    verification: Mapping[str, Any],
) -> bool:
    """Return whether either Direct runtime deployment evidence item passed."""

    return any(
        str(evidence.get("status") or "").strip().lower()
        in {"accepted", "ok", "pass", "passed", "succeeded", "success"}
        for evidence in (
            (
                verification.get("runtime_sync")
                if isinstance(verification.get("runtime_sync"), Mapping)
                else {}
            ),
            (
                verification.get("governance_redeploy")
                if isinstance(verification.get("governance_redeploy"), Mapping)
                else {}
            ),
        )
    )


def _contract_runtime_operator_supervised_direct_main_close_authority_gate(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    record: Mapping[str, Any],
    close_commit: str,
) -> dict[str, Any]:
    """Recheck the completed pinned Direct Rule at backlog close."""

    metadata = (
        record.get("metadata")
        if isinstance(record.get("metadata"), Mapping)
        else {}
    )
    binding = (
        metadata.get("operator_supervised_direct_main_runtime_binding")
        if isinstance(
            metadata.get("operator_supervised_direct_main_runtime_binding"),
            Mapping,
        )
        else {}
    )
    if not (
        str(record.get("contract_id") or "").strip()
        == "operator_supervised_direct_main"
        and str(record.get("revision") or "").strip()
        in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        and binding.get("strict_runtime_binding_required") is True
    ):
        return {}

    contract_execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    definition = _contract_runtime(conn)._load_pinned_definition(record)
    expected_lines = [
        (
            str(stage.get("stage_id") or "").strip(),
            str(line.get("line_id") or "").strip(),
            str(line.get("evidence_kind") or "").strip(),
            str(line.get("owner_role") or "").strip(),
        )
        for stage, line in iter_stage_lines(definition)
    ]
    completed_lines = [
        dict(line)
        for line in record.get("completed_lines") or []
        if isinstance(line, Mapping)
    ]
    actual_lines = [
        (
            str(line.get("stage_id") or "").strip(),
            str(line.get("line_id") or "").strip(),
            str(line.get("evidence_kind") or "").strip(),
            str(line.get("actor_role") or "").strip(),
        )
        for line in completed_lines
    ]
    missing: list[str] = []
    pinned_revision = str(record.get("revision") or "").strip()
    if actual_lines != expected_lines:
        missing.append(
            f"exact_completed_direct_{pinned_revision}_lines"
        )

    definition_identity = {
        "contract_id": "operator_supervised_direct_main",
        "revision": pinned_revision,
    }
    line_binding_errors = {
        str(line.get("line_id") or "").strip(): errors
        for line in completed_lines
        if (
            errors := operator_supervised_direct_main_runtime_binding_errors(
                definition_identity,
                record,
                line,
            )
        )
    }
    if line_binding_errors:
        missing.append("direct_runtime_binding_revalidation")

    lines_by_id = {
        str(line.get("line_id") or "").strip(): line
        for line in completed_lines
        if str(line.get("line_id") or "").strip()
    }
    close_commit = str(close_commit or "").strip().lower()
    commit_line_ids = (
        "observer_implementation",
        "qa_independent_verification",
        "observer_reconcile",
        "observer_close_ready",
    )
    line_commits = {
        line_id: str(lines_by_id.get(line_id, {}).get("commit_sha") or "")
        .strip()
        .lower()
        for line_id in commit_line_ids
    }
    if not (
        re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", close_commit)
        and set(line_commits.values()) == {close_commit}
    ):
        missing.append("exact_close_commit_across_direct_lines")

    current_state = _runtime_current_state_from_record(record)
    if current_state.get("next_legal_action"):
        missing.append("direct_contract_runtime_complete")

    runtime_deployment_authority = (
        _operator_supervised_direct_main_runtime_deployment_authority(
            project_id=project_id,
            close_commit=close_commit,
        )
    )
    close_line_payload = (
        lines_by_id.get("observer_close_ready", {}).get("payload")
        if isinstance(
            lines_by_id.get("observer_close_ready", {}).get("payload"),
            Mapping,
        )
        else {}
    )
    persisted_runtime_deployment_authority = (
        close_line_payload.get("runtime_deployment_authority")
        if isinstance(
            close_line_payload.get("runtime_deployment_authority"),
            Mapping,
        )
        else {}
    )
    if not (
        persisted_runtime_deployment_authority
        and stable_sha256(dict(persisted_runtime_deployment_authority))
        == stable_sha256(dict(runtime_deployment_authority))
    ):
        missing.append("runtime_deployment_authority_still_current")
    if (
        runtime_deployment_authority.get("applicable") is True
        and runtime_deployment_authority.get("passed") is not True
    ):
        missing.append("governance_runtime_loaded_close_commit")

    persisted_reconcile = (
        lines_by_id.get("observer_reconcile", {}).get("payload")
        if isinstance(
            lines_by_id.get("observer_reconcile", {}).get("payload"),
            Mapping,
        )
        else {}
    )
    persisted_reconcile_authority = (
        persisted_reconcile.get("direct_current_full_reconcile_authority")
        if isinstance(
            persisted_reconcile.get("direct_current_full_reconcile_authority"),
            Mapping,
        )
        else {}
    )
    current_reconcile_authority = (
        _operator_supervised_direct_main_current_full_reconcile_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            contract_execution_id=contract_execution_id,
            record=record,
        )
    )
    if not (
        current_reconcile_authority
        and stable_sha256(dict(persisted_reconcile_authority))
        == stable_sha256(dict(current_reconcile_authority))
    ):
        missing.append("current_full_reconcile_authority_still_current")
    if current_reconcile_authority and not (
        current_reconcile_authority.get("qa_passed") is True
        and current_reconcile_authority.get("close_satisfying") is True
        and current_reconcile_authority.get("deposit_only") is False
        and current_reconcile_authority.get(
            "authoritative_pass_synthesized"
        )
        is False
    ):
        missing.append("current_full_reconcile_qa_pass_close_authority")

    close_payload = (
        lines_by_id.get("observer_close_ready", {}).get("payload")
        if isinstance(
            lines_by_id.get("observer_close_ready", {}).get("payload"),
            Mapping,
        )
        else {}
    )
    close_verification = (
        close_payload.get("verification")
        if isinstance(close_payload.get("verification"), Mapping)
        else {}
    )
    close_test_results = (
        close_verification.get("test_results")
        if isinstance(close_verification.get("test_results"), Mapping)
        else {}
    )
    runtime_sync_or_redeploy_passed = (
        _operator_supervised_direct_main_runtime_sync_or_redeploy_passed(
            close_verification
        )
    )
    if not (
        close_payload.get("schema_version")
        == "operator_supervised_direct_main.close_ready_evidence.v1"
        and runtime_sync_or_redeploy_passed
        and close_verification.get("preflight_ok") is True
        and str(
            (close_verification.get("live_regression") or {}).get("status")
            if isinstance(close_verification.get("live_regression"), Mapping)
            else ""
        ).strip().lower()
        in {"accepted", "ok", "pass", "passed", "succeeded", "success"}
        and str(close_test_results.get("status") or "").strip().lower()
        in {"accepted", "ok", "pass", "passed", "succeeded", "success"}
        and str(close_test_results.get("commit_sha") or "").strip().lower()
        == close_commit
    ):
        missing.append("direct_close_integrity_evidence")

    passed = not missing
    source_refs = [
        f"contract_runtime:{contract_execution_id}",
        *[
            f"contract_runtime:{contract_execution_id}:line:{line_id}"
            for _stage_id, line_id, _evidence_kind, _actor_role in expected_lines
        ],
    ]
    if current_reconcile_authority:
        source_refs.extend(
            ref
            for ref in (
                str(current_reconcile_authority.get("reconcile_event_ref") or ""),
                (
                    "graph_snapshot:"
                    + str(current_reconcile_authority.get("active_snapshot_id") or "")
                ),
                (
                    "current_full_reconcile_provenance:"
                    + str(current_reconcile_authority.get("provenance_id") or "")
                ),
            )
            if ref and not ref.endswith(":")
        )
    gate = {
        "schema_version": (
            "operator_supervised_direct_main.close_authority_gate.v1"
        ),
        "accepted": passed,
        "passed": passed,
        "status": "passed" if passed else "failed",
        "source": _operator_supervised_direct_main_authority_source(
            pinned_revision
        ),
        "source_of_authority": "ContractRuntime",
        "server_derived": True,
        "caller_claims_trusted": False,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": contract_execution_id,
        "contract_revision": pinned_revision,
        "close_commit": close_commit,
        "missing_requirement_ids": missing,
        "source_refs": list(dict.fromkeys(source_refs)),
        "completed_line_ids": [line[1] for line in actual_lines],
        "line_binding_errors": line_binding_errors,
        "current_full_reconcile_authority_hash": str(
            current_reconcile_authority.get("authority_hash") or ""
        ),
        "runtime_deployment_authority": runtime_deployment_authority,
        "checks": {
            "exact_completed_lines": actual_lines == expected_lines,
            "runtime_binding_revalidated": not line_binding_errors,
            "close_commit_exact": set(line_commits.values()) == {close_commit},
            "runtime_complete": not bool(current_state.get("next_legal_action")),
            "current_full_reconcile_still_current": bool(
                current_reconcile_authority
                and stable_sha256(dict(persisted_reconcile_authority))
                == stable_sha256(dict(current_reconcile_authority))
            ),
            "close_integrity_present": (
                "direct_close_integrity_evidence" not in missing
            ),
            "runtime_deployment_current": (
                not runtime_deployment_authority
                or runtime_deployment_authority.get("passed") is True
            ),
        },
    }
    gate["gate_hash"] = stable_sha256(gate)
    return gate


def _operator_supervised_direct_main_apply_timeline_runtime(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    contract_execution_id: str,
    event_kind: str,
    body: Mapping[str, Any],
    normalized_payload: Mapping[str, Any],
    pre_mutation_graph_trace_gate: Mapping[str, Any] | None = None,
    pre_mutation_request_fingerprint: str = "",
    trusted_qa_verification_authority: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Map accepted public timeline evidence onto the pinned Direct lines."""

    runtime = _contract_runtime(conn)
    try:
        record = runtime.current_record(
            contract_execution_id,
            actor_role="observer",
        )
    except (ContractRuntimeError, StalePinnedContractExecutionError):
        return {}
    if not (
        str(record.get("contract_id") or "")
        == "operator_supervised_direct_main"
        and str(record.get("revision") or "")
        in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        and isinstance(record.get("metadata"), Mapping)
        and record["metadata"].get(
            "operator_supervised_direct_main_runtime_binding"
        )
    ):
        return {}
    binding = record["metadata"][
        "operator_supervised_direct_main_runtime_binding"
    ]
    event_key = str(event_kind or "").strip().lower().replace("-", "_")
    line_refs: list[dict[str, Any]] = []

    def submit(
        actor_role: str,
        stage_id: str,
        line_id: str,
        evidence_kind: str,
        payload: Mapping[str, Any],
        extra: Mapping[str, Any] | None = None,
    ) -> None:
        nonlocal record
        existing_lines = [
            line
            for line in record.get("completed_lines") or []
            if isinstance(line, Mapping)
            and str(line.get("line_id") or "").strip() == line_id
        ]
        if existing_lines:
            from . import task_timeline

            materialized_events = task_timeline.list_events(
                conn,
                project_id,
                backlog_id=backlog_id,
                task_id=contract_execution_id,
                event_kind=str(event_kind or "").strip(),
                limit=2,
            )
            if materialized_events:
                raise GovernanceError(
                    "operator_supervised_direct_main_timeline_already_materialized",
                    (
                        "Direct Main completed-line reuse is limited to the "
                        "missing-timeline crash window"
                    ),
                    409,
                    {
                        "contract_execution_id": contract_execution_id,
                        "line_id": line_id,
                        "existing_timeline_event_ids": [
                            int(item.get("id") or item.get("event_id") or 0)
                            for item in materialized_events
                        ],
                        "zero_write_rejection": True,
                        "writes_performed": False,
                    },
                )
            expected_line = (
                _operator_supervised_direct_main_expected_line_evidence(
                    record,
                    actor_role=actor_role,
                    stage_id=stage_id,
                    line_id=line_id,
                    evidence_kind=evidence_kind,
                    payload=payload,
                    extra=extra,
                )
            )
            existing_line = dict(existing_lines[0])
            existing_payload = (
                existing_line.get("payload")
                if isinstance(existing_line.get("payload"), Mapping)
                else {}
            )
            expected_payload = (
                dict(expected_line.get("payload"))
                if isinstance(expected_line.get("payload"), Mapping)
                else {}
            )
            # These two fields are server projections captured at the first
            # admission.  Their current-state diagnostics legitimately advance
            # with ContractRuntime, so reconstruct the original complete write
            # from the durable line.  Caller route/contract identity fields and
            # every other payload/top-level field remain exact comparisons.
            for projected_once_field in (
                "route_token_gate",
                "source_backed_contract_gate_authority",
            ):
                if (
                    projected_once_field in existing_payload
                    and projected_once_field in expected_payload
                ):
                    expected_payload[projected_once_field] = (
                        existing_payload[projected_once_field]
                    )
            if expected_payload:
                expected_line["payload"] = expected_payload
            if not (
                len(existing_lines) == 1
                and stable_sha256(existing_line)
                == stable_sha256(expected_line)
            ):
                mismatched_fields = sorted(
                    key
                    for key in set(existing_line) | set(expected_line)
                    if stable_sha256(existing_line.get(key))
                    != stable_sha256(expected_line.get(key))
                )
                mismatched_payload_fields = sorted(
                    key
                    for key in set(existing_payload) | set(expected_payload)
                    if stable_sha256(existing_payload.get(key))
                    != stable_sha256(expected_payload.get(key))
                )
                raise GovernanceError(
                    "operator_supervised_direct_main_partial_admission_mismatch",
                    (
                        "Direct Main retry does not match its already "
                        "persisted ContractRuntime admission prefix"
                    ),
                    409,
                    {
                        "contract_execution_id": contract_execution_id,
                        "line_id": line_id,
                        "mismatched_fields": mismatched_fields,
                        "mismatched_payload_fields": (
                            mismatched_payload_fields
                        ),
                        "zero_write_rejection": True,
                        "writes_performed": False,
                    },
                )
            line_refs.append(
                {
                    "stage_id": stage_id,
                    "line_id": line_id,
                    "evidence_kind": evidence_kind,
                    "execution_state_revision": int(
                        record.get("execution_state_revision") or 0
                    ),
                    "existing_line_reused": True,
                }
            )
            return
        record = _operator_supervised_direct_main_submit_runtime_line(
            conn,
            contract_execution_id=contract_execution_id,
            actor_role=actor_role,
            expected_stage_id=stage_id,
            expected_line_id=line_id,
            expected_evidence_kind=evidence_kind,
            payload=payload,
            extra=extra,
        )
        line_refs.append(
            {
                "stage_id": stage_id,
                "line_id": line_id,
                "evidence_kind": evidence_kind,
                "execution_state_revision": int(
                    record.get("execution_state_revision") or 0
                ),
            }
        )

    if event_key == "observer_direct_implementation_exception":
        graph_gate = dict(pre_mutation_graph_trace_gate or {})
        graph_db = (
            graph_gate.get("db_evidence")
            if isinstance(graph_gate.get("db_evidence"), Mapping)
            else {}
        )
        trace_ids = [
            str(item).strip()
            for item in graph_db.get("verified_trace_ids") or []
            if str(item).strip()
        ]
        submit(
            "observer",
            "route_gate",
            "observer_bind_direct_scope",
            "contract_binding",
            {
                "schema_version": (
                    "operator_supervised_direct_main.route_binding_evidence.v1"
                ),
                "direct_runtime_binding": dict(binding),
            },
        )
        submit(
            "observer",
            "graph_first",
            "observer_graph_context",
            "graph_trace",
            {
                "schema_version": (
                    "operator_supervised_direct_main.graph_context_evidence.v1"
                ),
                "graph_trace_ids": trace_ids,
                "pre_implementation_graph_trace_gate": graph_gate,
            },
            {
                "graph_trace_ids": trace_ids,
                "query_source": "observer",
                "query_purpose": "global_architecture_review",
                "db_verified": True,
            },
        )
        submit(
            "observer",
            "pre_mutation",
            "observer_direct_implementation_exception",
            "observer_direct_implementation_exception",
            {
                "schema_version": (
                    "operator_supervised_direct_main.pre_mutation_evidence.v1"
                ),
                "pre_mutation_request_fingerprint": (
                    pre_mutation_request_fingerprint
                ),
                "server_admitted_single_pre_mutation": True,
                "same_generation_retry_allowed": False,
                "route_identity": dict(binding.get("route_identity") or {}),
                "graph_trace_ids": trace_ids,
                "event": {
                    "event_type": str(body.get("event_type") or ""),
                    "event_kind": str(event_kind or ""),
                    "phase": str(body.get("phase") or ""),
                    "decision": str(body.get("decision") or ""),
                    "status": str(body.get("status") or ""),
                },
            },
        )
    elif event_key == "implementation":
        submit(
            "observer",
            "implementation",
            "observer_implementation",
            "implementation",
            {
                "schema_version": (
                    "operator_supervised_direct_main.implementation_evidence.v1"
                ),
                **dict(normalized_payload),
            },
            {
                "commit_sha": str(body.get("commit_sha") or "").strip(),
                "changed_files": list(
                    normalized_payload.get("changed_files") or []
                ),
                "test_results": dict(
                    normalized_payload.get("test_results") or {}
                ),
            },
        )
    elif event_key in {
        "verification",
        "independent_verification",
        "qa",
        "qa_verification",
    } and isinstance(trusted_qa_verification_authority, Mapping):
        from . import task_timeline

        qa_session_proof = dict(trusted_qa_verification_authority)
        qa_authority = task_timeline.source_backed_qa_session_authority(
            qa_session_proof
        )
        trace_ids = _runtime_context_service_dedupe(
            [
                str(item or "").strip()
                for item in (
                    qa_session_proof.get("graph_trace_ids")
                    or normalized_payload.get("graph_trace_ids")
                    or []
                )
            ]
        )
        submit(
            "qa",
            "qa_graph_context",
            "qa_graph_context",
            "graph_trace",
            {
                "schema_version": (
                    "operator_supervised_direct_main.qa_graph_evidence.v1"
                ),
                "graph_trace_ids": trace_ids,
                "qa_authority": qa_authority,
            },
            {
                "graph_trace_ids": trace_ids,
                "query_source": "qa",
                "query_purpose": "independent_verification",
                "db_verified": True,
                "target_project_root": str(
                    binding.get("target_project_root") or ""
                ),
            },
        )
        submit(
            "qa",
            "qa",
            "qa_independent_verification",
            "independent_verification",
            {
                "schema_version": (
                    "operator_supervised_direct_main.qa_evidence.v1"
                ),
                "qa_authority": qa_authority,
                "timeline_payload": dict(normalized_payload),
            },
            {
                "commit_sha": str(body.get("commit_sha") or "").strip(),
                "status": str(body.get("status") or "").strip(),
            },
        )
    elif event_key in {"reconcile", "current_full_reconcile"}:
        reconcile_authority = (
            _operator_supervised_direct_main_current_full_reconcile_authority(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                contract_execution_id=contract_execution_id,
                record=record,
            )
        )
        if not reconcile_authority:
            raise GovernanceError(
                "operator_supervised_direct_main_current_full_reconcile_required",
                "Direct Main reconcile requires one exact active current-full provenance",
                422,
                {
                    "contract_execution_id": contract_execution_id,
                    "zero_write_rejection": True,
                    "writes_performed": False,
                },
            )
        submit(
            "observer",
            "reconcile",
            "observer_reconcile",
            "current_full_reconcile",
            {
                "schema_version": (
                    "operator_supervised_direct_main.reconcile_evidence.v1"
                ),
                "direct_current_full_reconcile_authority": (
                    reconcile_authority
                ),
                "timeline_payload": dict(normalized_payload),
                "verification": dict(body.get("verification") or {}),
            },
            {
                "commit_sha": str(
                    reconcile_authority.get("target_commit_sha") or ""
                ).strip(),
            },
        )
    elif event_key == "close_ready":
        current_line = (
            record.get("runtime_guide", {}).get("next_legal_action")
            if isinstance(record.get("runtime_guide"), Mapping)
            else {}
        )
        if str((current_line or {}).get("line_id") or "") == "observer_reconcile":
            reconcile_authority = (
                _operator_supervised_direct_main_current_full_reconcile_authority(
                    conn,
                    project_id=project_id,
                    backlog_id=backlog_id,
                    contract_execution_id=contract_execution_id,
                    record=record,
                )
            )
            if not reconcile_authority:
                raise GovernanceError(
                    "operator_supervised_direct_main_current_full_reconcile_required",
                    (
                        "Direct Main close requires one exact active "
                        "current-full provenance"
                    ),
                    422,
                    {
                        "contract_execution_id": contract_execution_id,
                        "zero_write_rejection": True,
                        "writes_performed": False,
                    },
                )
            submit(
                "observer",
                "reconcile",
                "observer_reconcile",
                "current_full_reconcile",
                {
                    "schema_version": (
                        "operator_supervised_direct_main.reconcile_evidence.v1"
                    ),
                    "direct_current_full_reconcile_authority": (
                        reconcile_authority
                    ),
                    "timeline_payload": dict(normalized_payload),
                    "verification": dict(body.get("verification") or {}),
                },
                {
                    "commit_sha": str(
                        reconcile_authority.get("target_commit_sha") or ""
                    ).strip(),
                },
            )
        submit(
            "observer",
            "close_ready",
            "observer_close_ready",
            "close_ready",
            {
                "schema_version": (
                    "operator_supervised_direct_main.close_ready_evidence.v1"
                ),
                "timeline_payload": dict(normalized_payload),
                "verification": dict(body.get("verification") or {}),
                "runtime_deployment_authority": dict(
                    normalized_payload.get("runtime_deployment_authority")
                    or {}
                ),
                "direct_close_ready_prewrite_authority": dict(
                    normalized_payload.get(
                        "direct_close_ready_prewrite_authority"
                    )
                    or {}
                ),
            },
            {
                "commit_sha": str(body.get("commit_sha") or "").strip(),
                "status": str(body.get("status") or "").strip(),
                "verification": dict(body.get("verification") or {}),
            },
        )
    else:
        return {}

    current = runtime.current_record(
        contract_execution_id,
        actor_role="observer",
    )
    lineage = {
        "schema_version": (
            "operator_supervised_direct_main.timeline_runtime_lineage.v1"
        ),
        "source_of_authority": "ContractRuntime",
        "contract_execution_id": contract_execution_id,
        "definition_hash": str(current.get("definition_hash") or ""),
        "definition_source_sha256": str(
            current.get("definition_source_sha256") or ""
        ),
        "instruction_bundle_hash": str(
            current.get("instruction_bundle_hash") or ""
        ),
        "authoritative_common_rule_join": dict(
            current.get("authoritative_common_rule_join") or {}
        ),
        "completed_line_refs": line_refs,
        "execution_state_revision": int(
            current.get("execution_state_revision") or 0
        ),
        "runtime_guide_hash": str(
            (current.get("runtime_guide") or {}).get("runtime_guide_hash")
            or ""
        ),
        "timeline_facade_adapter": True,
        "pass_synthesized": False,
    }
    lineage["lineage_hash"] = stable_sha256(lineage)
    return lineage


def _parentless_direct_main_test_results_template(
    *,
    commit_sha: str,
    command_placeholder: str,
) -> dict[str, Any]:
    """Return the only executable test-results shape for Direct Main."""

    return {
        "schema_version": _PARENTLESS_DIRECT_MAIN_TEST_RESULTS_SCHEMA,
        "status": "passed",
        "passed": True,
        "commit_sha": str(commit_sha or "").strip(),
        "commands": [
            {
                "command": str(command_placeholder or "").strip(),
                "status": "passed",
                "exit_code": 0,
            }
        ],
    }


def _contract_runtime_parentless_direct_main_test_results_gate(
    value: Any,
    *,
    expected_commit: str,
    field: str,
) -> dict[str, Any]:
    """Validate command-backed, commit-bound Direct Main test evidence."""

    normalized_commit = str(expected_commit or "").strip().lower()
    supplied = dict(value) if isinstance(value, Mapping) else {}
    validation = worker_implementation_test_results_validation(supplied)
    canonical = (
        dict(validation.get("canonical_test_results"))
        if isinstance(validation.get("canonical_test_results"), Mapping)
        else {}
    )
    missing: list[str] = []
    mismatches: list[dict[str, Any]] = []
    if validation.get("accepted") is not True:
        missing.append("canonical_test_results")
        mismatches.append(
            {
                "field": str(validation.get("field") or field),
                "expected": "finish-compatible structured test_results",
                "actual": str(validation.get("reason") or "invalid"),
            }
        )
    if str(canonical.get("schema_version") or "").strip() != (
        _PARENTLESS_DIRECT_MAIN_TEST_RESULTS_SCHEMA
    ):
        missing.append("canonical_test_results_schema")
    if str(canonical.get("status") or "").strip().lower() != "passed":
        missing.append("canonical_test_results_status")
    if canonical.get("passed") is not True:
        missing.append("canonical_test_results_boolean_verdict")
    supplied_commit = str(canonical.get("commit_sha") or "").strip().lower()
    if not normalized_commit or supplied_commit != normalized_commit:
        missing.append("canonical_test_results_commit_binding")
        mismatches.append(
            {
                "field": f"{field}.commit_sha",
                "expected": normalized_commit,
                "actual": supplied_commit,
            }
        )
    commands = canonical.get("commands")
    command_values: list[str] = []
    if not isinstance(commands, list) or not commands:
        missing.append("canonical_test_results_commands_nonempty")
    else:
        for index, raw_command in enumerate(commands):
            command = dict(raw_command) if isinstance(raw_command, Mapping) else {}
            command_text = str(command.get("command") or "").strip()
            command_status = str(command.get("status") or "").strip().lower()
            exit_code = command.get("exit_code")
            if (
                not command_text
                or (
                    command_text.startswith("<")
                    and command_text.endswith(">")
                )
                or command_status != "passed"
                or isinstance(exit_code, bool)
                or exit_code != 0
            ):
                missing.append("canonical_test_results_commands_passing")
                mismatches.append(
                    {
                        "field": f"{field}.commands[{index}]",
                        "expected": (
                            "non-placeholder command with status=passed and "
                            "exit_code=0"
                        ),
                        "actual": {
                            "command_present": bool(command_text),
                            "status": command_status,
                            "exit_code": exit_code,
                        },
                    }
                )
                continue
            command_values.append(command_text)
    if len(command_values) != len(set(command_values)):
        missing.append("canonical_test_results_commands_unique")
    missing = list(dict.fromkeys(missing))
    passed = bool(canonical) and not missing
    authority = {
        "schema_version": (
            "parentless_direct_main.test_results_authority.v1"
        ),
        "passed": passed,
        "status": "passed" if passed else "failed",
        "field": field,
        "expected_commit": normalized_commit,
        "command_count": len(command_values),
        "missing_requirement_ids": missing,
        "mismatches": mismatches,
        "validator": validation,
        "canonical_test_results": canonical if passed else {},
        "server_validated": True,
        "caller_aliases_accepted": False,
        "historical_backfill_allowed": False,
    }
    authority["authority_hash"] = stable_sha256(
        {
            key: value
            for key, value in authority.items()
            if key != "authority_hash"
        }
    )
    return authority


def _onboard_parentless_direct_main_event_is_accepted(
    event: Mapping[str, Any],
) -> bool:
    """Return only server-backed, append-time accepted direct-main boundaries."""

    payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
    authority = (
        payload.get("observer_direct_pre_mutation_authority")
        if isinstance(
            payload.get("observer_direct_pre_mutation_authority"), Mapping
        )
        else {}
    )
    identity = _observer_root_route_identity_from_event(event)
    route_token_backed = bool(
        _contract_runtime_close_authority_route_token_backed_event(
            event,
            identity,
            require_source_backed_authority=True,
        )
    )
    if (
        authority.get("accepted") is True
        and authority.get("server_projected") is True
        and str(authority.get("projection_source") or "").strip()
        == "task_timeline_append_pre_persistence_gate"
    ):
        return route_token_backed

    from . import task_timeline

    route_identity = {
        "route_ids": [identity.get("route_id", "")]
        if identity.get("route_id")
        else [],
        "route_context_hashes": [identity.get("route_context_hash", "")]
        if identity.get("route_context_hash")
        else [],
    }
    exception = task_timeline._observer_direct_exception_event(
        dict(event),
        route_identity,
    )
    return bool(exception.get("accepted")) and route_token_backed


def _onboard_parentless_direct_main_timeline_events(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    event_kind: str,
    task_id: str = "",
    after_event_id: int = 0,
) -> list[dict[str, Any]]:
    """Read the complete narrow lineage newest-first without ASC-prefix loss."""

    from . import task_timeline

    task_timeline.ensure_schema(conn)
    clauses = ["project_id = ?", "backlog_id = ?"]
    params: list[Any] = [project_id, backlog_id]
    if task_id:
        clauses.append("task_id = ?")
        params.append(task_id)
    if after_event_id:
        clauses.append("id > ?")
        params.append(int(after_event_id))
    event_kind_query = task_timeline._timeline_event_kind_query_parts(event_kind)
    if event_kind_query is not None:
        event_kind_clause, event_kind_params = event_kind_query
        clauses.append(event_kind_clause)
        params.extend(event_kind_params)
    rows = conn.execute(
        f"""SELECT * FROM task_timeline_events
            WHERE {' AND '.join(clauses)}
            ORDER BY id DESC""",
        tuple(params),
    ).fetchall()
    return [task_timeline._row_to_dict(row) for row in rows]


def _onboard_direct_main_transition_enter_event_is_authoritative(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    failed_qa_event_id: int,
    record: Mapping[str, Any],
    transition: Mapping[str, Any],
) -> bool:
    """Require an entered event created after the exact failed-QA boundary."""

    lineage = (
        record.get("backlog_lineage")
        if isinstance(record.get("backlog_lineage"), Mapping)
        else {}
    )
    successor_task_id = str(lineage.get("task_id") or "").strip()
    contract_execution_id = str(
        record.get("contract_execution_id") or ""
    ).strip()
    transition_hash = str(transition.get("transition_hash") or "").strip()
    if not successor_task_id or not contract_execution_id or not transition_hash:
        return False
    rows = conn.execute(
        """SELECT * FROM task_timeline_events
            WHERE project_id = ?
              AND backlog_id = ?
              AND task_id = ?
              AND id > ?
              AND event_type = 'mf_parallel.entered'
            ORDER BY id DESC""",
        (
            project_id,
            backlog_id,
            successor_task_id,
            int(failed_qa_event_id),
        ),
    ).fetchall()
    from . import task_timeline

    for row in rows:
        event = task_timeline._row_to_dict(row)
        payload = (
            event.get("payload")
            if isinstance(event.get("payload"), Mapping)
            else {}
        )
        event_transition = (
            payload.get("direct_main_contract_transition")
            if isinstance(
                payload.get("direct_main_contract_transition"), Mapping
            )
            else {}
        )
        artifact_refs = (
            event.get("artifact_refs")
            if isinstance(event.get("artifact_refs"), Mapping)
            else {}
        )
        meta_gate = (
            payload.get("meta_contract_gate")
            if isinstance(payload.get("meta_contract_gate"), Mapping)
            else {}
        )
        if (
            str(event.get("event_kind") or "").strip()
            == "contract_binding"
            and str(event.get("actor") or "").strip() == "observer"
            and str(event.get("status") or "").strip().lower() == "accepted"
            and meta_gate.get("allowed") is True
            and str(
                artifact_refs.get("successor_contract_execution_id") or ""
            ).strip()
            == contract_execution_id
            and str(
                artifact_refs.get("direct_main_contract_transition_hash") or ""
            ).strip()
            == transition_hash
            and str(event_transition.get("transition_hash") or "").strip()
            == transition_hash
            and dict(event_transition) == dict(transition)
        ):
            return True
    return False


def _onboard_parentless_direct_main_worker_implementation_is_authoritative(
    event: Mapping[str, Any],
    *,
    direct_event: Mapping[str, Any],
    project_id: str,
    backlog_id: str,
    task_id: str,
) -> bool:
    """Accept only an immutable server-gated worker-owned direct-main event."""

    payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
    actor = str(event.get("actor") or "").strip()
    commit_sha = str(event.get("commit_sha") or "").strip().lower()
    materialized_from = (
        payload.get("materialized_from")
        if isinstance(payload.get("materialized_from"), Mapping)
        else {}
    )
    worker_task = str(materialized_from.get("worker_task") or "").strip()
    decision = (
        payload.get("contract_gate_decision")
        if isinstance(payload.get("contract_gate_decision"), Mapping)
        else {}
    )
    decision_hash = str(decision.get("decision_hash") or "").strip()
    unsigned_decision = {
        key: value for key, value in decision.items() if key != "decision_hash"
    }
    authority = _contract_runtime_close_authority_first_deep_mapping(
        event,
        "source_backed_contract_gate_authority",
    )
    route_gate = (
        authority.get("route_token_gate")
        if isinstance(authority.get("route_token_gate"), Mapping)
        else {}
    )
    route_scope = (
        route_gate.get("scope")
        if isinstance(route_gate.get("scope"), Mapping)
        else {}
    )
    direct_identity = _observer_root_route_identity_from_event(direct_event)
    implementation_identity = _observer_root_route_identity_from_event(event)
    route_identity_matches = bool(
        str(direct_identity.get("route_id") or "").strip()
        and str(direct_identity.get("route_context_hash") or "").strip()
        and str(implementation_identity.get("route_id") or "").strip()
        == str(direct_identity.get("route_id") or "").strip()
        and str(implementation_identity.get("route_context_hash") or "").strip()
        == str(direct_identity.get("route_context_hash") or "").strip()
        and _observer_root_route_identity_matches_partial(
            implementation_identity,
            direct_identity,
        )
    )

    return bool(
        str(event.get("backlog_id") or "").strip() == backlog_id
        and str(event.get("task_id") or "").strip() == task_id
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", commit_sha)
        and actor
        and worker_task
        and actor == f"worker:{worker_task}"
        and str(payload.get("evidence_owner") or "").strip() == actor
        and str(payload.get("authored_by") or "").strip() == actor
        and payload.get("observer_authored") is False
        and not _qa_request_has_impersonation_claim(event)
        and str(materialized_from.get("schema_version") or "").strip()
        == "immutable_worker_result.v1"
        and materialized_from.get("immutable") is True
        and str(materialized_from.get("implementation_commit") or "")
        .strip()
        .lower()
        == commit_sha
        and str(payload.get("implementation_commit") or "").strip().lower()
        == commit_sha
        and _contract_runtime_projection_timeline_actor_role(event) == "mf_sub"
        and decision.get("ok") is True
        and str(decision.get("decision") or "").strip() == "allow"
        and str(decision.get("action") or "").strip()
        == "task_timeline_append"
        and str(decision.get("required_role") or "").strip() == "mf_sub"
        and str(decision.get("actor_role") or "").strip() == "mf_sub"
        and str(decision.get("source_of_authority") or "").strip()
        == "route_token_gate"
        and decision_hash
        and decision_hash == stable_sha256(unsigned_decision)
        and _contract_runtime_close_authority_route_token_backed_event(
            event,
            implementation_identity,
            require_source_backed_authority=True,
        )
        and str(route_gate.get("action") or "").strip()
        == "task_timeline_append"
        and str(route_scope.get("project_id") or "").strip() == project_id
        and str(route_scope.get("backlog_id") or "").strip() == backlog_id
        and str(route_scope.get("task_id") or "").strip() == task_id
        and route_identity_matches
    )


_DIRECT_MAIN_DIRTY_SCOPE_AUTHORITY_SCHEMA = (
    "parentless_direct_main.implementation_dirty_scope_authority.v1"
)


def _contract_runtime_parentless_direct_main_dirty_scope_authority(
    payload: Mapping[str, Any],
    *,
    row_declared_files: Sequence[str],
    verified_changed_files: Sequence[str] | None = None,
    verified_changed_files_source: str = "",
) -> dict[str, Any]:
    """Normalize one server-verified Direct Main implementation file scope."""

    missing: list[str] = []
    mismatches: list[dict[str, Any]] = []

    def canonical_paths(
        value: Any,
        *,
        field: str,
        required: bool,
    ) -> list[str]:
        if not isinstance(value, list):
            if required:
                missing.append(field)
            elif value not in (None, ""):
                mismatches.append(
                    {
                        "field": field,
                        "expected": "canonical file list",
                        "actual": type(value).__name__,
                    }
                )
            return []
        result: list[str] = []
        for raw_path in value:
            if not isinstance(raw_path, str) or raw_path != raw_path.strip():
                mismatches.append(
                    {
                        "field": field,
                        "expected": "trimmed repository-relative paths",
                        "actual": raw_path,
                    }
                )
                continue
            try:
                normalized = _qa_overlay_normalize_path(raw_path)
            except _QACandidateOverlayError:
                normalized = ""
            if not normalized or normalized != raw_path:
                mismatches.append(
                    {
                        "field": field,
                        "expected": "canonical repository-relative path",
                        "actual": raw_path,
                    }
                )
                continue
            if normalized in result:
                mismatches.append(
                    {
                        "field": field,
                        "expected": "unique canonical paths",
                        "actual": normalized,
                    }
                )
                continue
            result.append(normalized)
        if required and not result:
            missing.append(field)
        # File scope is an identity set.  Validate the caller's exact list
        # shape (including duplicate rejection) before imposing one stable
        # server order so equivalent row, caller, and Git projections cannot
        # disagree solely because their enumeration order differs.
        return sorted(result)

    declared_files = canonical_paths(
        list(row_declared_files),
        field="row_declared_files",
        required=True,
    )
    caller_changed_files = canonical_paths(
        payload.get("changed_files"),
        field="payload.changed_files",
        required=True,
    )
    changed_files = caller_changed_files
    if verified_changed_files is not None:
        changed_files = canonical_paths(
            list(verified_changed_files),
            field="server_verified_changed_files",
            required=True,
        )
        if caller_changed_files != changed_files:
            mismatches.append(
                {
                    "field": "payload.changed_files",
                    "expected": changed_files,
                    "actual": caller_changed_files,
                    "source": verified_changed_files_source,
                }
            )
    declared_file_set = set(declared_files)
    unexpected_files = [
        path for path in changed_files if path not in declared_file_set
    ]
    if unexpected_files:
        mismatches.append(
            {
                "field": "payload.changed_files",
                "expected": declared_files,
                "actual": changed_files,
                "unexpected_files": unexpected_files,
            }
        )

    caller_scope_fields: list[str] = []
    for field in ("dirty_scope_check", "diff_check"):
        if field not in payload:
            continue
        caller_scope_fields.append(field)
        candidate = payload.get(field)
        if not isinstance(candidate, Mapping):
            mismatches.append(
                {
                    "field": f"payload.{field}",
                    "expected": "object",
                    "actual": type(candidate).__name__,
                }
            )
            continue
        if candidate.get("exact_match") is not True:
            mismatches.append(
                {
                    "field": f"payload.{field}.exact_match",
                    "expected": True,
                    "actual": candidate.get("exact_match"),
                }
            )
        claimed_unexpected = list(candidate.get("unexpected_files") or [])
        if claimed_unexpected:
            mismatches.append(
                {
                    "field": f"payload.{field}.unexpected_files",
                    "expected": [],
                    "actual": claimed_unexpected,
                }
            )
        claimed_changed = canonical_paths(
            candidate.get("changed_files"),
            field=f"payload.{field}.changed_files",
            required=True,
        )
        if claimed_changed != changed_files:
            mismatches.append(
                {
                    "field": f"payload.{field}.changed_files",
                    "expected": changed_files,
                    "actual": claimed_changed,
                }
            )
        if "allowed_files" in candidate:
            claimed_allowed = canonical_paths(
                candidate.get("allowed_files"),
                field=f"payload.{field}.allowed_files",
                required=True,
            )
            if claimed_allowed != declared_files:
                mismatches.append(
                    {
                        "field": f"payload.{field}.allowed_files",
                        "expected": declared_files,
                        "actual": claimed_allowed,
                    }
                )

    persisted_scope = (
        payload.get("dirty_scope_check")
        if isinstance(payload.get("dirty_scope_check"), Mapping)
        else {}
    )
    persisted_hash = str(persisted_scope.get("authority_hash") or "").strip()
    if persisted_hash or persisted_scope.get("server_derived") is True:
        unsigned_persisted = {
            key: value
            for key, value in persisted_scope.items()
            if key != "authority_hash"
        }
        if (
            str(persisted_scope.get("schema_version") or "").strip()
            != _DIRECT_MAIN_DIRTY_SCOPE_AUTHORITY_SCHEMA
            or persisted_scope.get("server_derived") is not True
            or persisted_scope.get("caller_claims_trusted") is not False
            or not persisted_hash
            or persisted_hash != stable_sha256(unsigned_persisted)
        ):
            mismatches.append(
                {
                    "field": "payload.dirty_scope_check.authority_hash",
                    "expected": "valid server-derived dirty-scope authority",
                    "actual": persisted_hash,
                }
            )

    missing = list(dict.fromkeys(missing))
    passed = bool(
        declared_files
        and changed_files
        and not missing
        and not mismatches
        and not unexpected_files
    )
    canonical_scope = {
        "schema_version": _DIRECT_MAIN_DIRTY_SCOPE_AUTHORITY_SCHEMA,
        "server_derived": True,
        "caller_claims_trusted": False,
        "source": (
            "server.handle_task_timeline_append."
            "parentless_direct_main_implementation_prewrite_gate"
        ),
        "changed_files_source": (
            verified_changed_files_source
            or "validated_persisted_implementation_scope"
        ),
        "allowed_files": declared_files,
        "changed_files": changed_files,
        "changed_files_source": (
            verified_changed_files_source
            or "validated_persisted_implementation_scope"
        ),
        "unexpected_files": unexpected_files,
        "exact_match": passed,
    }
    canonical_scope["authority_hash"] = stable_sha256(canonical_scope)
    return {
        "schema_version": (
            "parentless_direct_main.implementation_dirty_scope_gate.v1"
        ),
        "applicable": True,
        "passed": passed,
        "status": "passed" if passed else "failed",
        "row_declared_files": declared_files,
        "changed_files": changed_files,
        "unexpected_files": unexpected_files,
        "caller_scope_fields": caller_scope_fields,
        "missing_requirement_ids": missing,
        "identity_mismatches": mismatches,
        "canonical_dirty_scope_check": canonical_scope,
        "zero_write_on_failure": True,
        "historical_backfill_allowed": False,
    }


def _qa_exact_candidate_direct_main_observer_implementation_is_authoritative(
    event: Mapping[str, Any],
    *,
    direct_event: Mapping[str, Any],
    project_id: str,
    backlog_id: str,
    task_id: str,
) -> bool:
    """Accept one canonical, server-gated observer Direct Main implementation."""

    from . import task_timeline

    payload = (
        event.get("payload")
        if isinstance(event.get("payload"), Mapping)
        else {}
    )
    direct_payload = (
        direct_event.get("payload")
        if isinstance(direct_event.get("payload"), Mapping)
        else {}
    )
    direct_authority = (
        direct_payload.get("observer_direct_pre_mutation_authority")
        if isinstance(
            direct_payload.get("observer_direct_pre_mutation_authority"),
            Mapping,
        )
        else {}
    )
    acceptance_scope = (
        direct_payload.get("acceptance_scope_closure")
        if isinstance(direct_payload.get("acceptance_scope_closure"), Mapping)
        else {}
    )
    declared_files = _runtime_context_service_dedupe(
        [
            str(path or "").strip()
            for path in (
                direct_authority.get("row_declared_files")
                or acceptance_scope.get("allowed_files")
                or []
            )
        ]
    )
    dirty_scope_authority = (
        _contract_runtime_parentless_direct_main_dirty_scope_authority(
            payload,
            row_declared_files=declared_files,
        )
    )
    commit_sha = str(event.get("commit_sha") or "").strip().lower()
    decision = (
        payload.get("contract_gate_decision")
        if isinstance(payload.get("contract_gate_decision"), Mapping)
        else {}
    )
    decision_hash = str(decision.get("decision_hash") or "").strip()
    unsigned_decision = {
        key: value for key, value in decision.items() if key != "decision_hash"
    }
    authority = _contract_runtime_close_authority_first_deep_mapping(
        event,
        "source_backed_contract_gate_authority",
    )
    route_gate = (
        authority.get("route_token_gate")
        if isinstance(authority.get("route_token_gate"), Mapping)
        else {}
    )
    route_scope = (
        route_gate.get("scope")
        if isinstance(route_gate.get("scope"), Mapping)
        else {}
    )
    direct_identity = _observer_root_route_identity_from_event(direct_event)
    implementation_identity = _observer_root_route_identity_from_event(event)
    test_results = _contract_runtime_parentless_direct_main_test_results_gate(
        payload.get("test_results"),
        expected_commit=commit_sha,
        field="implementation.payload.test_results",
    )
    commit_prewrite_authority = (
        payload.get("direct_main_implementation_commit_prewrite_authority")
        if isinstance(
            payload.get("direct_main_implementation_commit_prewrite_authority"),
            Mapping,
        )
        else {}
    )
    commit_prewrite_authority_hash = str(
        commit_prewrite_authority.get("authority_hash") or ""
    ).strip()
    unsigned_commit_prewrite_authority = {
        key: value
        for key, value in commit_prewrite_authority.items()
        if key != "authority_hash"
    }
    direct_event_id = int(
        direct_event.get("id") or direct_event.get("event_id") or 0
    )
    implementation_event_id = int(
        event.get("id") or event.get("event_id") or 0
    )
    decision_source = str(decision.get("source_of_authority") or "").strip()
    route_action_scope_lineage = (
        payload.get("route_action_scope_lineage")
        if isinstance(payload.get("route_action_scope_lineage"), Mapping)
        else {}
    )
    lineage_route_gate = (
        route_action_scope_lineage.get("route_token_gate")
        if isinstance(route_action_scope_lineage.get("route_token_gate"), Mapping)
        else {}
    )
    lineage_route_scope = (
        lineage_route_gate.get("scope")
        if isinstance(lineage_route_gate.get("scope"), Mapping)
        else {}
    )
    lineage_child_identity = (
        route_action_scope_lineage.get("child_route_identity")
        if isinstance(
            route_action_scope_lineage.get("child_route_identity"), Mapping
        )
        else {}
    )
    lineage_child = (
        route_action_scope_lineage.get("child_route_lineage")
        if isinstance(route_action_scope_lineage.get("child_route_lineage"), Mapping)
        else {}
    )
    lineage_parent_identity = (
        route_action_scope_lineage.get("parent_route_identity")
        if isinstance(
            route_action_scope_lineage.get("parent_route_identity"), Mapping
        )
        else {}
    )
    lineage_projection_actions = [
        candidate
        for candidate in (decision.get("projection_actions") or [])
        if isinstance(candidate, Mapping)
    ]
    route_action_scope_lineage_authoritative = bool(
        decision_source == "route_action_scope_lineage"
        and str(decision.get("gate_id") or "").strip()
        == "task_timeline_append:route_action_scope_lineage"
        and str(decision.get("gate_type") or "").strip()
        == "timeline_projection"
        and any(
            str(candidate.get("action") or "").strip()
            == "record_timeline_event"
            and str(candidate.get("source_of_authority") or "").strip()
            == "route_action_scope_lineage"
            for candidate in lineage_projection_actions
        )
        and str(route_action_scope_lineage.get("schema_version") or "").strip()
        == "route_action_scope_lineage.v1"
        and route_action_scope_lineage.get("accepted") is True
        and str(route_action_scope_lineage.get("status") or "").strip()
        == "accepted"
        and str(route_action_scope_lineage.get("source") or "").strip()
        == "server_route_token_action_scope"
        and str(
            route_action_scope_lineage.get("acceptance_source") or ""
        ).strip()
        == "server_route_token_action_scope"
        and str(route_action_scope_lineage.get("projected_by") or "").strip()
        == "handle_task_timeline_append"
        and route_action_scope_lineage.get("server_projected") is True
        and route_action_scope_lineage.get("server_issued_binding") is True
        and route_action_scope_lineage.get("registry_verified") is True
        and route_action_scope_lineage.get("resolved_from_ref") is True
        and str(route_action_scope_lineage.get("binding_source") or "").strip()
        == "observer_route_token_refs"
        and str(route_action_scope_lineage.get("allowed_action") or "").strip()
        == "task_timeline_append"
        and str(route_action_scope_lineage.get("route_token_ref") or "").strip()
        == str(implementation_identity.get("route_token_ref") or "").strip()
        and _observer_root_route_identity_complete(lineage_child_identity)
        and _observer_root_route_identity_key(lineage_child_identity)
        == _observer_root_route_identity_key(implementation_identity)
        and str(lineage_child_identity.get("route_token_ref") or "").strip()
        == str(implementation_identity.get("route_token_ref") or "").strip()
        and _observer_root_route_identity_complete(lineage_parent_identity)
        and str(lineage_child.get("project_id") or "").strip() == project_id
        and str(lineage_child.get("backlog_id") or "").strip() == backlog_id
        and str(lineage_child.get("task_id") or "").strip() == task_id
        and "task_timeline_append"
        in {
            str(action or "").strip()
            for action in (lineage_child.get("allowed_actions") or [])
        }
        and str(lineage_route_gate.get("action") or "").strip()
        == "task_timeline_append"
        and lineage_route_gate.get("allowed") is True
        and lineage_route_gate.get("server_projected") is True
        and lineage_route_gate.get("server_issued_binding") is True
        and lineage_route_gate.get("registry_verified") is True
        and lineage_route_gate.get("resolved_from_ref") is True
        and str(lineage_route_gate.get("binding_source") or "").strip()
        == "observer_route_token_refs"
        and _observer_root_route_identity_complete(lineage_route_gate)
        and _observer_root_route_identity_key(lineage_route_gate)
        == _observer_root_route_identity_key(implementation_identity)
        and str(lineage_route_gate.get("route_token_ref") or "").strip()
        == str(implementation_identity.get("route_token_ref") or "").strip()
        and str(lineage_route_scope.get("project_id") or "").strip()
        == project_id
        and str(lineage_route_scope.get("backlog_id") or "").strip()
        == backlog_id
        and str(lineage_route_scope.get("task_id") or "").strip() == task_id
    )
    route_caller_role = str(route_gate.get("caller_role") or "").strip()
    observer_actor_authoritative = bool(
        route_caller_role == "observer"
        or (
            not route_caller_role
            and str(decision.get("actor_role") or "").strip()
            == "observer"
        )
    )

    return bool(
        direct_event_id > 0
        and implementation_event_id > direct_event_id
        and str(event.get("project_id") or "").strip() == project_id
        and str(event.get("backlog_id") or "").strip() == backlog_id
        and str(event.get("task_id") or "").strip() == task_id
        and str(event.get("event_type") or "").strip()
        == "observer.implementation"
        and str(event.get("event_kind") or "").strip() == "implementation"
        and str(event.get("phase") or "").strip() == "implementation"
        and task_timeline._event_passed(dict(event))
        # `actor` was historically persisted as a caller display label. The
        # server-derived route decision and source-backed route authority
        # below are the authority for the observer role; current writes are
        # canonicalized to `observer` before persistence.
        and re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", commit_sha)
        and not _qa_request_has_impersonation_claim(event)
        and direct_authority.get("accepted") is True
        and direct_authority.get("server_projected") is True
        and str(direct_authority.get("projection_source") or "").strip()
        == "task_timeline_append_pre_persistence_gate"
        and declared_files
        and isinstance(payload.get("dirty_scope_check"), Mapping)
        and dirty_scope_authority.get("passed") is True
        and test_results.get("passed") is True
        and str(commit_prewrite_authority.get("schema_version") or "").strip()
        == "parentless_direct_main.implementation_commit_prewrite_authority.v1"
        and commit_prewrite_authority.get("server_derived") is True
        and commit_prewrite_authority.get("passed") is True
        and str(commit_prewrite_authority.get("status") or "").strip()
        == "passed"
        and str(commit_prewrite_authority.get("project_id") or "").strip()
        == project_id
        and str(commit_prewrite_authority.get("backlog_id") or "").strip()
        == backlog_id
        and str(commit_prewrite_authority.get("task_id") or "").strip()
        == task_id
        and str(commit_prewrite_authority.get("commit_sha") or "")
        .strip()
        .lower()
        == commit_sha
        and str(
            commit_prewrite_authority.get("resolved_commit_sha") or ""
        ).strip().lower()
        == commit_sha
        and str(
            commit_prewrite_authority.get("canonical_head_commit") or ""
        ).strip().lower()
        == commit_sha
        and commit_prewrite_authority.get("repository_root_exact") is True
        and commit_prewrite_authority.get("git_object_exists") is True
        and commit_prewrite_authority.get("worktree_clean") is True
        and commit_prewrite_authority.get("route_scope_exact") is True
        and commit_prewrite_authority.get("direct_route_identity_exact") is True
        and int(
            commit_prewrite_authority.get("direct_pre_mutation_event_count")
            or 0
        )
        == 1
        and str(commit_prewrite_authority.get("route_token_ref") or "").strip()
        == str(implementation_identity.get("route_token_ref") or "").strip()
        and commit_prewrite_authority_hash
        and commit_prewrite_authority_hash
        == stable_sha256(unsigned_commit_prewrite_authority)
        and _observer_root_route_identity_complete(direct_identity)
        and _observer_root_route_identity_complete(implementation_identity)
        and decision.get("ok") is True
        and str(decision.get("decision") or "").strip() in {"allow", "warn"}
        and str(decision.get("action") or "").strip()
        == "task_timeline_append"
        and observer_actor_authoritative
        and (
            decision_source == "route_token_gate"
            or route_action_scope_lineage_authoritative
        )
        and decision.get("primary_decision_source") is True
        and decision.get("meta_contract_gate_decision_source") is False
        and decision_hash
        and decision_hash == stable_sha256(unsigned_decision)
        and _contract_runtime_close_authority_route_token_backed_event(
            event,
            implementation_identity,
            require_source_backed_authority=True,
        )
        and str(route_gate.get("action") or "").strip()
        == "task_timeline_append"
        and str(route_scope.get("project_id") or "").strip() == project_id
        and str(route_scope.get("backlog_id") or "").strip() == backlog_id
        and str(route_scope.get("task_id") or "").strip() == task_id
    )


def _qa_exact_candidate_direct_main_implementation_is_authoritative(
    conn,
    event: Mapping[str, Any],
    *,
    direct_event: Mapping[str, Any],
    project_id: str,
    backlog_id: str,
    task_id: str,
) -> bool:
    """Preserve worker authority and add canonical observer Direct Main authority."""

    if _onboard_parentless_direct_main_worker_implementation_is_authoritative(
        event,
        direct_event=direct_event,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
    ):
        return True

    observer_event: Mapping[str, Any] = event
    payload = (
        event.get("payload")
        if isinstance(event.get("payload"), Mapping)
        else {}
    )
    if "direct_main_implementation_commit_prewrite_authority" not in payload:
        bootstrap_gate = (
            _contract_runtime_parentless_direct_main_implementation_prewrite_gate(
                conn,
                project_id=project_id,
                body=dict(event),
                event_kind=str(event.get("event_kind") or "").strip(),
                normalized_status=str(event.get("status") or "").strip(),
                normalized_payload=dict(payload),
            )
        )
        if bootstrap_gate.get("passed") is True:
            bootstrap_payload = dict(payload)
            bootstrap_payload[
                "direct_main_implementation_commit_prewrite_authority"
            ] = dict(
                bootstrap_gate.get("commit_prewrite_authority") or {}
            )
            observer_event = {**dict(event), "payload": bootstrap_payload}

    return _qa_exact_candidate_direct_main_observer_implementation_is_authoritative(
        observer_event,
        direct_event=direct_event,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
    )


def _onboard_parentless_direct_main_failed_qa_state(
    conn,
    *,
    project_id: str,
    backlog_id: str,
) -> dict[str, Any]:
    """Project an unresolved parentless direct-main QA failure from raw evidence."""

    from . import task_timeline

    direct_candidates_by_id: dict[int, dict[str, Any]] = {}
    for direct_event_kind in (
        "observer_direct_implementation_exception",
        "observer_direct_mutation_exception",
    ):
        for candidate in _onboard_parentless_direct_main_timeline_events(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            event_kind=direct_event_kind,
        ):
            event_id = int(
                candidate.get("id") or candidate.get("event_id") or 0
            )
            if event_id:
                direct_candidates_by_id[event_id] = candidate
    direct_candidates = [
        direct_candidates_by_id[event_id]
        for event_id in sorted(direct_candidates_by_id, reverse=True)
    ]
    direct_events = [
        event
        for event in direct_candidates
        if _onboard_parentless_direct_main_event_is_accepted(event)
    ]
    if not direct_events:
        return {}
    implementation_candidates = _onboard_parentless_direct_main_timeline_events(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=str(direct_events[0].get("task_id") or "").strip(),
        event_kind="implementation",
        after_event_id=int(
            direct_events[0].get("id")
            or direct_events[0].get("event_id")
            or 0
        ),
    )
    direct_event = direct_events[0]
    direct_event_id = int(
        direct_event.get("id") or direct_event.get("event_id") or 0
    )
    task_id = str(direct_event.get("task_id") or "").strip()
    if not task_id:
        return {}

    passing_statuses = {"accepted", "ok", "pass", "passed", "succeeded", "success"}
    failing_statuses = {"blocked", "error", "fail", "failed", "no_pass", "rejected"}

    def _event_id(event: Mapping[str, Any]) -> int:
        return int(event.get("id") or event.get("event_id") or 0)

    def _event_status(event: Mapping[str, Any]) -> str:
        return str(event.get("status") or event.get("decision") or "").strip().lower()

    def _is_direct_implementation(event: Mapping[str, Any]) -> bool:
        common = bool(
            str(event.get("backlog_id") or "").strip() == backlog_id
            and str(event.get("task_id") or "").strip() == task_id
            and _event_id(event) > direct_event_id
            and str(event.get("event_kind") or event.get("phase") or "").strip()
            == "implementation"
            and _event_status(event) in passing_statuses
        )
        if not common:
            return False
        if str(event.get("actor") or "").strip() == "observer":
            return True
        return _onboard_parentless_direct_main_worker_implementation_is_authoritative(
            event,
            direct_event=direct_event,
            project_id=project_id,
            backlog_id=backlog_id,
            task_id=task_id,
        )

    implementations = [
        event
        for event in implementation_candidates
        if _is_direct_implementation(event)
    ]
    if not implementations:
        return {}
    implementation = implementations[0]
    implementation_event_id = _event_id(implementation)
    implementation_commit = str(implementation.get("commit_sha") or "").strip()

    qa_candidates = _onboard_parentless_direct_main_timeline_events(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        task_id=task_id,
        event_kind="independent_verification",
        after_event_id=implementation_event_id,
    )
    qa_events: list[dict[str, Any]] = []
    for event in qa_candidates:
        if (
            str(event.get("task_id") or "").strip() != task_id
            or _event_id(event) <= implementation_event_id
        ):
            continue
        qa_commit = str(event.get("commit_sha") or "").strip()
        if implementation_commit and qa_commit and qa_commit != implementation_commit:
            continue
        if not task_timeline._observer_direct_independent_verification_event(
            dict(event),
            conn=conn,
        ):
            continue
        qa_events.append(dict(event))
    if not qa_events:
        return {}
    failed_qa = qa_events[0]
    failed_qa_status = _event_status(failed_qa)
    if failed_qa_status in passing_statuses or failed_qa_status not in failing_statuses:
        return {}
    failed_qa_event_id = _event_id(failed_qa)
    failed_qa_source_ref = f"timeline:{failed_qa_event_id}"

    try:
        runtime_records = _contract_runtime_store(conn).list_by_backlog(
            project_id=project_id,
            backlog_id=backlog_id,
        )
    except ContractRuntimeError:
        runtime_records = []
    for record in runtime_records:
        if (
            str(record.get("contract_id") or "").strip()
            != _MF_PARALLEL_CONTRACT_KIND
            or str(record.get("parent_contract_execution_id") or "").strip()
            != task_id
        ):
            continue
        metadata = (
            record.get("metadata")
            if isinstance(record.get("metadata"), Mapping)
            else {}
        )
        transition = (
            metadata.get("direct_main_contract_transition")
            if isinstance(
                metadata.get("direct_main_contract_transition"), Mapping
            )
            else {}
        )
        transition_hash = str(transition.get("transition_hash") or "").strip()
        expected_transition_hash = stable_sha256(
            {
                key: value
                for key, value in transition.items()
                if key != "transition_hash"
            }
        )
        if (
            transition.get("accepted") is True
            and transition.get("server_projected") is True
            and str(transition.get("projection_source") or "").strip()
            == "mf_parallel_enter_pre_persistence_gate"
            and str(transition.get("source_of_authority") or "").strip()
            == "authenticated_observer_typed_contract_transition"
            and str(transition.get("failed_qa_source_ref") or "").strip()
            == failed_qa_source_ref
            and int(transition.get("failed_qa_event_id") or 0)
            == failed_qa_event_id
            and transition_hash == expected_transition_hash
            and _onboard_direct_main_transition_enter_event_is_authoritative(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                failed_qa_event_id=failed_qa_event_id,
                record=record,
                transition=transition,
            )
        ):
            return {}

    return {
        "schema_version": "onboard_route_guide.direct_main_failed_qa_state.v1",
        "status": "failed_qa_direct_main_rework_required",
        "source_work_type": _OPERATOR_SUPERVISED_DIRECT_MAIN_WORK_TYPE,
        "source_contract_kind": _OPERATOR_SUPERVISED_DIRECT_MAIN_CONTRACT_KIND,
        "successor_work_type": _OPERATOR_SUPERVISED_DIRECT_MAIN_WORK_TYPE,
        "successor_contract_kind": _OPERATOR_SUPERVISED_DIRECT_MAIN_CONTRACT_KIND,
        "source_backlog_id": backlog_id,
        "source_task_id": task_id,
        "source_direct_main_event_ref": f"timeline:{direct_event_id}",
        "implementation_event_ref": f"timeline:{implementation_event_id}",
        "implementation_commit": implementation_commit,
        "failed_qa_source_ref": failed_qa_source_ref,
        "failed_qa_status": failed_qa_status,
        "source_generation_terminal": True,
        "same_row_resume_allowed": False,
        "separate_bounded_successor_row_required": True,
        "mf_parallel_enter_allowed": False,
        "source_refs": [
            f"timeline:{direct_event_id}",
            f"timeline:{implementation_event_id}",
            failed_qa_source_ref,
        ],
    }


