def _ac_promotion_rollback_expected_evidence_refs(
    *,
    backlog_id: str,
    candidate: Mapping[str, Any],
) -> list[str]:
    implementation_delta = dict(candidate.get("implementation_delta") or {})
    promotion_delta = dict(candidate.get("promotion_delta") or {})
    return sorted(
        {
            f"backlog:{backlog_id}",
            f"contract_runtime:{_AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID}",
            f"candidate_commit:{candidate.get('candidate_commit')}",
            f"candidate_tree:{candidate.get('candidate_tree_sha')}",
            f"stable_anchor:{AC_STABLE_ANCHOR_COMMIT}",
            f"implementation_delta:{implementation_delta.get('delta_hash')}",
            f"promotion_delta:{promotion_delta.get('delta_hash')}",
            f"candidate_authority:{candidate.get('authority_hash')}",
            "stable_database_identity:"
            + stable_sha256(candidate.get("stable_database_identity") or {}),
        }
    )


def _ac_promotion_rollback_route_authority(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    route_token_ref: str,
    candidate: Mapping[str, Any],
) -> dict[str, Any]:
    from . import observer_route_context

    ref = str(route_token_ref or "").strip()
    if not ref:
        return {}
    try:
        route = observer_route_context.resolve_route_token_ref(
            conn,
            project_id=project_id,
            storage_project_id=project_id,
            route_token_ref=ref,
            backlog_id=backlog_id,
            task_id=_AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID,
        )
    except observer_route_context.RouteTokenRefError:
        return {}
    route = dict(route or {})
    identity = {
        key: str(route.get(key) or "").strip()
        for key in (
            "route_id",
            "route_context_hash",
            "prompt_contract_id",
            "prompt_contract_hash",
            "visible_injection_manifest_hash",
            "route_token_ref",
        )
    }
    expected_files = sorted(candidate["implementation_delta"]["file_fence"])
    expected_evidence = _ac_promotion_rollback_expected_evidence_refs(
        backlog_id=backlog_id, candidate=candidate
    )
    accepted = bool(
        str(route.get("caller_role") or "") == "observer"
        and list(route.get("allowed_actions") or [])
        == [_AC_PROMOTION_ROLLBACK_ROUTE_ACTION]
        and sorted(route.get("target_files") or []) == expected_files
        and sorted(route.get("owned_files") or []) == expected_files
        and sorted(route.get("evidence_refs") or []) == expected_evidence
        and route.get("route_token_ref") == ref
        and all(identity.values())
    )
    if not accepted:
        return {}
    authority = {
        "schema_version": "ac_promotion_rollback_route_authority.v1",
        "accepted": True,
        "source": "canonical_stable_route_registry",
        "required_endpoint": "http://127.0.0.1:40000",
        "project_id": project_id,
        "backlog_id": backlog_id,
        "contract_execution_id": _AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID,
        "candidate_commit": candidate["candidate_commit"],
        "route_token_ref": ref,
        "route_identity": identity,
        "evidence_refs_hash": stable_sha256(expected_evidence),
        "writes_performed": False,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _ac_promotion_rollback_row_authority(
    conn,
    *,
    candidate: Mapping[str, Any],
) -> dict[str, Any]:
    row = conn.execute(
        """SELECT bug_id, status, fixed_at, "commit", updated_at
             FROM backlog_bugs WHERE bug_id=?""",
        (_AC_PROMOTION_ROLLBACK_BLOCKER_ID,),
    ).fetchone()
    candidate_commit = str(candidate.get("candidate_commit") or "").lower()
    accepted = bool(
        row is not None
        and str(row["status"] or "").upper() == "FIXED"
        and str(row["fixed_at"] or "").strip()
        and str(row["commit"] or "").strip().lower() == candidate_commit
        and str(candidate.get("candidate_parent_commit") or "").lower()
        == _AC_PROMOTION_ROLLBACK_BASELINE_COMMIT
    )
    authority = {
        "schema_version": "ac_promotion_rollback_row_authority.v2",
        "accepted": accepted,
        "status": str(row["status"] or "missing").upper() if row else "MISSING",
        "backlog_id": _AC_PROMOTION_ROLLBACK_BLOCKER_ID,
        "fix_commit": str(row["commit"] or "").strip().lower() if row else "",
        "fixed_at": str(row["fixed_at"] or "").strip() if row else "",
        "candidate_commit": candidate_commit,
        "candidate_parent_commit": str(candidate.get("candidate_parent_commit") or ""),
        "exact_descendant_d_required": True,
        "server_derived": True,
        "writes_performed": False,
    }
    authority["authority_hash"] = stable_sha256(authority)
    return authority


def _ac_promotion_rollback_qa_projection(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    candidate: Mapping[str, Any],
    qa_candidate_intent_sha256: str,
) -> dict[str, Any]:
    from . import task_timeline

    rows = conn.execute(
        """SELECT * FROM task_timeline_events
           WHERE project_id=? AND backlog_id=? AND task_id=?
             AND event_type='qa.independent_verification'
           ORDER BY id ASC""",
        (
            project_id,
            backlog_id,
            _AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID,
        ),
    ).fetchall()
    valid: list[dict[str, Any]] = []
    for row in rows:
        event = _ac_promotion_row_to_event(row)
        evidence = {
            "payload": event.get("payload") or {},
            "verification": event.get("verification") or {},
            "artifact_refs": event.get("artifact_refs") or {},
        }
        authority = _ac_promotion_first_mapping(
            evidence, "source_backed_contract_gate_authority"
        )
        proof = authority.get("qa_session_proof") if isinstance(
            authority.get("qa_session_proof"), Mapping
        ) else {}
        review = proof.get("candidate_review_context") if isinstance(
            proof.get("candidate_review_context"), Mapping
        ) else _ac_promotion_first_mapping(evidence, "candidate_review_context")
        impl_review = _ac_promotion_first_mapping(
            evidence, "implementation_delta_review_context"
        )
        results = _ac_promotion_first_mapping(evidence, "promotion_gate_results")
        branch = results.get("branch_service") if isinstance(
            results.get("branch_service"), Mapping
        ) else {}
        lanes = results.get("lanes") if isinstance(results.get("lanes"), Mapping) else {}
        authority_hash = str(authority.get("authority_hash") or "")
        replay_count = 0
        for project_row in conn.execute(
            "SELECT * FROM task_timeline_events WHERE project_id=?", (project_id,)
        ).fetchall():
            projected = _ac_promotion_row_to_event(project_row)
            projected_evidence = {
                "payload": projected.get("payload") or {},
                "verification": projected.get("verification") or {},
                "artifact_refs": projected.get("artifact_refs") or {},
            }
            if authority_hash and _ac_promotion_contains(
                projected_evidence, "authority_hash", authority_hash
            ):
                replay_count += 1
        promotion_delta = candidate["promotion_delta"]
        implementation_delta = candidate["implementation_delta"]
        lane_pass = bool(
            set(lanes) == {"direct_main", "mf_parallel", "mf_batch_parallel"}
            and all(
                isinstance(item, Mapping)
                and item.get("status") == "passed"
                and item.get("test_id")
                and re.fullmatch(
                    r"sha256:[0-9a-f]{64}", str(item.get("report_sha256") or "")
                )
                for item in lanes.values()
            )
        )
        accepted = bool(
            event.get("event_kind") == "independent_verification"
            and event.get("phase") == "qa"
            and str(event.get("status") or "").lower() in {"pass", "passed"}
            and event.get("commit_sha") == candidate["candidate_commit"]
            and task_timeline._source_backed_qa_session_authority_valid(authority, conn=conn)
            and proof.get("project_id") == project_id
            and proof.get("backlog_id") == backlog_id
            and proof.get("task_id") == _AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID
            and proof.get("commit_sha") == candidate["candidate_commit"]
            and proof.get("principal_id") == event.get("actor")
            and review.get("candidate_commit_sha") == candidate["candidate_commit"]
            and review.get("comparison_base_commit_sha") == AC_STABLE_ANCHOR_COMMIT
            and review.get("comparison_authority_required") is True
            and review.get("candidate_diff_hash") == promotion_delta["diff_sha256"]
            and list(review.get("changed_files") or []) == promotion_delta["file_fence"]
            and impl_review.get("candidate_commit_sha") == candidate["candidate_commit"]
            and impl_review.get("comparison_base_commit_sha")
            == _AC_PROMOTION_ROLLBACK_BASELINE_COMMIT
            and impl_review.get("candidate_diff_hash")
            == implementation_delta["diff_sha256"]
            and list(impl_review.get("changed_files") or [])
            == implementation_delta["file_fence"]
            and _ac_promotion_contains(
                evidence, "implementation_delta", implementation_delta
            )
            and _ac_promotion_contains(evidence, "promotion_delta", promotion_delta)
            and _ac_promotion_contains(
                evidence, "candidate_tree_sha", candidate["candidate_tree_sha"]
            )
            and _ac_promotion_contains(
                evidence,
                "stable_runtime_source_sha256",
                candidate["stable_runtime_source_sha256"],
            )
            and _ac_promotion_contains(
                evidence,
                "candidate_runtime_source_sha256",
                candidate["candidate_runtime_source_sha256"],
            )
            and _ac_promotion_contains(
                evidence,
                "qa_candidate_intent_sha256",
                qa_candidate_intent_sha256,
            )
            and _ac_promotion_contains(
                evidence,
                "stable_database_identity",
                candidate["stable_database_identity"],
            )
            and not any(
                item is True
                for item in _ac_promotion_nested_values(evidence, "pass_synthesized")
            )
            and branch.get("status") == "passed"
            and branch.get("runtime_plane") == "dev"
            and branch.get("port") == AC_DEV_SERVICE_PORT
            and branch.get("bind_host") == AC_DEV_BIND_HOST
            and branch.get("test_id")
            and re.fullmatch(
                r"sha256:[0-9a-f]{64}", str(branch.get("report_sha256") or "")
            )
            and lane_pass
            and replay_count == 1
        )
        if accepted:
            valid.append(
                {"event": event, "authority": authority, "results": results}
            )
    if len(valid) != 1:
        return {
            "accepted": False,
            "status": "missing" if not rows else "invalid_or_ambiguous",
            "event_count": len(rows),
            "valid_event_count": len(valid),
        }
    selected = valid[0]
    return {
        "accepted": True,
        "status": "passed",
        "timeline_event_id": int(selected["event"]["id"]),
        "event_hash": _ac_promotion_event_hash(selected["event"]),
        "actor": str(selected["event"].get("actor") or ""),
        "authority_hash": str(selected["authority"].get("authority_hash") or ""),
        "promotion_gate_results": selected["results"],
    }


def _ac_promotion_rollback_signoff_projection(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    candidate: Mapping[str, Any],
    qa: Mapping[str, Any],
    intent: Mapping[str, Any],
    promotion_intent_sha256: str,
    verifier_sha256: str,
) -> dict[str, Any]:
    rows = conn.execute(
        """SELECT * FROM release_operator_head_queue_events
           WHERE project_id=? AND action='reorder' ORDER BY id ASC""",
        (project_id,),
    ).fetchall()
    parsed: list[tuple[dict[str, Any], dict[str, Any]]] = []
    nonce_counts: dict[str, int] = {}
    for raw in rows:
        row = dict(raw)
        try:
            reason = json.loads(str(row.get("reason") or ""))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if reason.get("schema_version") != "ac_stable_promotion_operator_signoff.v2":
            continue
        nonce = str(reason.get("nonce") or "")
        nonce_counts[nonce] = nonce_counts.get(nonce, 0) + 1
        parsed.append((row, reason))
    valid: list[dict[str, Any]] = []
    for row, reason in parsed:
        nonce = str(reason.get("nonce") or "")
        operator_gate = {
            "status": "approved",
            "nonce": nonce,
            "operator_principal_id": reason.get("operator_principal_id"),
            "expires_at": reason.get("expires_at"),
        }
        signable = {
            **dict(intent),
            "promotion_intent_sha256": promotion_intent_sha256,
            "prior_promotion": {
                "kind": "bootstrap",
                "stable_commit": AC_STABLE_ANCHOR_COMMIT,
            },
            "gates": {
                "qa_verdict": {
                    "timeline_event_id": qa.get("timeline_event_id"),
                    "status": "passed",
                },
                "operator_signoff": operator_gate,
            },
        }
        manifest_hash = stable_sha256(signable)
        expected = {
            "schema_version": "ac_stable_promotion_operator_signoff.v2",
            "nonce": nonce,
            "operator_principal_id": reason.get("operator_principal_id"),
            "expires_at": reason.get("expires_at"),
            "project_id": project_id,
            "backlog_id": backlog_id,
            "contract_execution_id": _AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID,
            "stable_anchor_commit": AC_STABLE_ANCHOR_COMMIT,
            "candidate_commit": candidate["candidate_commit"],
            "candidate_tree_sha": candidate["candidate_tree_sha"],
            "stable_runtime_source_sha256": candidate[
                "stable_runtime_source_sha256"
            ],
            "candidate_runtime_source_sha256": candidate[
                "candidate_runtime_source_sha256"
            ],
            "promotion_intent_sha256": promotion_intent_sha256,
            "qa_candidate_intent_sha256": intent[
                "qa_candidate_intent_sha256"
            ],
            "promotion_manifest_sha256": manifest_hash,
            "verifier_sha256": verifier_sha256,
            "implementation_delta_hash": candidate["implementation_delta"]["delta_hash"],
            "promotion_delta_hash": candidate["promotion_delta"]["delta_hash"],
            "rollback_authority_hash": intent["rollback_authority_hash"],
            "custody_authority": intent["custody_authority"],
            "stable_database_identity": candidate["stable_database_identity"],
        }
        try:
            before = json.loads(str(row.get("before_json") or "{}"))
            after = json.loads(str(row.get("after_json") or "{}"))
            created = datetime.fromisoformat(
                str(row.get("created_at") or "").replace("Z", "+00:00")
            )
            expires = datetime.fromisoformat(
                str(reason.get("expires_at") or "").replace("Z", "+00:00")
            )
            if created.tzinfo is None:
                created = created.replace(tzinfo=timezone.utc)
            if expires.tzinfo is None:
                expires = expires.replace(tzinfo=timezone.utc)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if bool(
            reason == expected
            and row.get("reason") == json.dumps(reason, sort_keys=True, separators=(",", ":"))
            and row.get("backlog_id") == ""
            and before == after
            and _ac_promotion_operator_principal_valid(row.get("actor"))
            and row.get("actor") == reason.get("operator_principal_id")
            and re.fullmatch(r"[0-9a-f]{32}", nonce)
            and nonce_counts.get(nonce) == 1
            and expires > created
            and expires - created <= timedelta(hours=1)
            and datetime.now(timezone.utc) < expires
        ):
            valid.append(
                {
                    "row": row,
                    "reason": reason,
                    "operator_gate": operator_gate,
                    "manifest_hash": manifest_hash,
                }
            )
    if len(valid) != 1:
        return {
            "accepted": False,
            "status": "missing" if not parsed else "invalid_or_ambiguous",
            "candidate_signoff_count": len(parsed),
            "valid_signoff_count": len(valid),
        }
    selected = valid[0]
    return {
        "accepted": True,
        "status": "approved",
        "queue_event_id": int(selected["row"]["id"]),
        "operator_principal_id": selected["reason"]["operator_principal_id"],
        "nonce": selected["reason"]["nonce"],
        "expires_at": selected["reason"]["expires_at"],
        "manifest_hash": selected["manifest_hash"],
        "operator_approval_ref": (
            f"release-operator-head-queue-event:{int(selected['row']['id'])}"
        ),
    }


def _ac_promotion_rollback_response(
    *,
    project_id: str,
    state: str,
    response_view: str,
    next_action: Mapping[str, Any],
    details: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    operation = {
        "kind": "read_only_state_machine",
        "id": "ac_stable_promotion_rollback_successor",
        "backlog_id": _AC_PROMOTION_ROLLBACK_BLOCKER_ID,
        "state": state,
        "preparation_only": True,
        "activation_authorized": False,
        "deploy_ready": False,
        "authorizes_write": False,
    }
    response = {
        "schema_version": "onboard_route_guide.ac_promotion_rollback_successor.v2",
        "ok": True,
        "project_id": project_id,
        "backlog_id": _AC_PROMOTION_ROLLBACK_BLOCKER_ID,
        "selected_backlog_source": "exact_promotion_rollback_row",
        "response_view": response_view or "full",
        "promotion_rollback_state": state,
        "system_operation_index": {
            "schema_version": "onboard.system_operation_index.v1",
            "operations": {operation["id"]: operation},
        },
        "onboard_route_guide": {
            "schema_version": "onboard_contract.route_guide.v1",
            "system_operation_index": {
                "schema_version": "onboard.system_operation_index.v1",
                "operations": {operation["id"]: operation},
            },
            "next_legal_action": dict(next_action),
        },
        "next_legal_action": dict(next_action),
        "preparation_only": True,
        "activation_authorized": False,
        "deploy_ready": False,
        "authorizes_write": False,
        "writes_performed": False,
        "zero_write_projection": True,
        "raw_route_token_exposed": False,
        "public_safe": True,
        "secret_safe": True,
    }
    response.update(deepcopy(dict(details or {})))
    return response


def _ac_promotion_rollback_route_guide_overlay(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    route_token_ref: str = "",
    response_view: str = "",
    request_body: Mapping[str, Any] | None = None,
    request_selector_claims: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if project_id != "aming-claw" or backlog_id != _AC_PROMOTION_ROLLBACK_BLOCKER_ID:
        return {}
    if _runtime_plane() != "dev":
        return _ac_promotion_rollback_response(
            project_id=project_id,
            state="wrong_runtime_plane",
            response_view=response_view,
            next_action={
                "code": "promotion_rollback_requires_dev_projection",
                "required_endpoint": "http://127.0.0.1:40008",
                "actionable": False,
            },
        )
    try:
        candidate = _ac_promotion_rollback_candidate_authority()
        if candidate.get("status") == "baseline_only":
            return _ac_promotion_rollback_response(
                project_id=project_id,
                state="baseline_only",
                response_view=response_view,
                next_action={
                    "code": "promotion_rollback_descendant_d_not_materialized",
                    "actionable": False,
                    "baseline_commit": _AC_PROMOTION_ROLLBACK_BASELINE_COMMIT,
                },
                details={"candidate_authority": candidate},
            )
        mismatches = _ac_promotion_successor_request_mismatches(
            request_body,
            request_selector_claims,
            candidate,
            contract_execution_id=_AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID,
        )
        if mismatches:
            raise GovernanceError(
                "promotion_rollback_caller_claim_mismatch",
                "caller claims do not match server-derived D authority",
                409,
                {"mismatch_fields": mismatches, "writes_performed": False},
            )
        health = _ac_promotion_successor_stable_health()
        if health.get("stable_database_identity") and health.get(
            "stable_database_identity"
        ) != candidate["stable_database_identity"]:
            raise GovernanceError(
                "promotion_rollback_stable_database_identity_mismatch",
                "stable and dev do not share the canonical database",
                409,
                {"writes_performed": False},
            )
        implementation = _ac_promotion_rollback_implementation_record(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            candidate_commit=candidate["candidate_commit"],
        )
        body = dict(request_body or {})
        route_ref = str(body.get("promotion_route_token_ref") or "").strip()
        route_authority = _ac_promotion_rollback_route_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            route_token_ref=route_ref,
            candidate=candidate,
        )
        common = {
            "candidate_authority": candidate,
            "stable_health_authority": health,
            "implementation_authority": {
                "contract_execution_id": _AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID,
                "implementation_route_ref": implementation[
                    "implementation_route_ref"
                ],
                "binding_hash": implementation["binding_hash"],
            },
        }
        if not route_authority:
            expected_evidence = _ac_promotion_rollback_expected_evidence_refs(
                backlog_id=backlog_id, candidate=candidate
            )
            return _ac_promotion_rollback_response(
                project_id=project_id,
                state="promotion_route_missing",
                response_view=response_view,
                next_action={
                    "code": "promotion_rollback_prepare_route_required",
                    "action": "observer_route_context_issue",
                    "required_endpoint": "http://127.0.0.1:40000",
                    "actionable": True,
                    "copy_safe_body": {
                        "project_id": project_id,
                        "backlog_id": backlog_id,
                        "task_id": _AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID,
                        "caller_role": "observer",
                        "allowed_actions": [_AC_PROMOTION_ROLLBACK_ROUTE_ACTION],
                        "target_files": candidate["implementation_delta"]["file_fence"],
                        "owned_files": candidate["implementation_delta"]["file_fence"],
                        "evidence_refs": expected_evidence,
                    },
                    "writes_performed": False,
                },
                details=common,
            )
        deploy = {
            "authorized": True,
            "mode": "host_supervisor_activation_plan_v2",
            "stable_port": AC_STABLE_SERVICE_PORT,
        }
        activation_policy = {
            "schema_version": "ac_stable_activation_policy.v2",
            "prepare_required": True,
            "activation_plan_required": True,
            "automatic_activation": False,
            "rollback_required_after_first_mutation": True,
        }
        custody = _ac_promotion_rollback_custody_authority(
            candidate=candidate,
            implementation=implementation,
            promotion_route=route_authority,
        )
        qa_candidate_intent = _ac_promotion_rollback_qa_candidate_intent(
            project_id=project_id,
            backlog_id=backlog_id,
            candidate=candidate,
            deploy=deploy,
            activation_policy=activation_policy,
            custody_authority=custody,
        )
        qa_candidate_intent_hash = stable_sha256(qa_candidate_intent)
        qa = _ac_promotion_rollback_qa_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            candidate=candidate,
            qa_candidate_intent_sha256=qa_candidate_intent_hash,
        )
        rollback = _ac_promotion_rollback_row_authority(
            conn, candidate=candidate
        )
        common.update(
            {
                "promotion_route_authority": route_authority,
                "rollback_row_authority": rollback,
                "custody_authority": custody,
                "qa_candidate_intent_sha256": qa_candidate_intent_hash,
            }
        )
        if qa.get("accepted") is not True:
            return _ac_promotion_rollback_response(
                project_id=project_id,
                state="route_ready_qa_missing",
                response_view=response_view,
                next_action={
                    "code": "promotion_rollback_exact_d_qa_required",
                    "action": "qa.independent_verification",
                    "owner_role": "qa",
                    "candidate_commit": candidate["candidate_commit"],
                    "implementation_delta": candidate["implementation_delta"],
                    "promotion_delta": candidate["promotion_delta"],
                    "required_gate_results": [
                        "branch_service",
                        "direct_main",
                        "mf_parallel",
                        "mf_batch_parallel",
                    ],
                    "actionable": False,
                    "writes_performed": False,
                },
                details={**common, "qa_projection": qa},
            )
        if rollback.get("accepted") is not True:
            return _ac_promotion_rollback_response(
                project_id=project_id,
                state="qa_ready_rollback_row_missing",
                response_view=response_view,
                next_action={
                    "code": "promotion_rollback_fixed_commit_d_required",
                    "candidate_commit": candidate["candidate_commit"],
                    "qa_timeline_event_id": qa["timeline_event_id"],
                    "actionable": False,
                    "writes_performed": False,
                },
                details={**common, "qa_projection": qa},
            )
        intent = {
            "schema_version": "ac_stable_promotion_manifest.v2",
            "project_id": project_id,
            "backlog_id": backlog_id,
            "contract_execution_id": _AC_PROMOTION_ROLLBACK_CONTRACT_EXECUTION_ID,
            "stable_anchor_commit": AC_STABLE_ANCHOR_COMMIT,
            "stable_branch": AC_STABLE_BRANCH,
            "branch": AC_DEV_BRANCH,
            "candidate_commit": candidate["candidate_commit"],
            "candidate_tree_sha": candidate["candidate_tree_sha"],
            "stable_runtime_source_sha256": candidate[
                "stable_runtime_source_sha256"
            ],
            "candidate_runtime_source_sha256": candidate[
                "candidate_runtime_source_sha256"
            ],
            "implementation_delta": candidate["implementation_delta"],
            "promotion_delta": candidate["promotion_delta"],
            "qa_candidate_intent_sha256": qa_candidate_intent_hash,
            "rollback_authority_hash": rollback["authority_hash"],
            "deploy": deploy,
            "stable_database_identity": candidate["stable_database_identity"],
            "activation_policy": activation_policy,
            "custody_authority": custody,
        }
        intent_hash = stable_sha256(intent)
        common["promotion_intent_sha256"] = intent_hash
        verifier_hash = "sha256:" + hashlib.sha256(
            (
                Path(__file__).resolve().parents[2]
                / "scripts"
                / "merge-and-deploy.sh"
            ).read_bytes()
        ).hexdigest()
        signoff = _ac_promotion_rollback_signoff_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            candidate=candidate,
            qa=qa,
            intent=intent,
            promotion_intent_sha256=intent_hash,
            verifier_sha256=verifier_hash,
        )
        if signoff.get("accepted") is not True:
            return _ac_promotion_rollback_response(
                project_id=project_id,
                state="qa_ready_signoff_missing",
                response_view=response_view,
                next_action={
                    "code": "promotion_rollback_d_operator_signoff_required",
                    "required_schema": "ac_stable_promotion_operator_signoff.v2",
                    "candidate_commit": candidate["candidate_commit"],
                    "unique_nonce_required": True,
                    "actionable": False,
                    "writes_performed": False,
                },
                details={
                    **common,
                    "qa_projection": qa,
                    "operator_signoff_projection": signoff,
                },
            )
        manifest = {
            **intent,
            "promotion_intent_sha256": intent_hash,
            "promotion_manifest_sha256": signoff["manifest_hash"],
            "gates": {
                "qa_verdict": {
                    "timeline_event_id": qa["timeline_event_id"],
                    "status": "passed",
                },
                "operator_signoff": {
                    "status": "approved",
                    "nonce": signoff["nonce"],
                    "operator_principal_id": signoff["operator_principal_id"],
                    "expires_at": signoff["expires_at"],
                    "queue_event_id": signoff["queue_event_id"],
                },
            },
            "prior_promotion": {
                "kind": "bootstrap",
                "stable_commit": AC_STABLE_ANCHOR_COMMIT,
            },
        }
        return _ac_promotion_rollback_response(
            project_id=project_id,
            state="manifest_prepared",
            response_view=response_view,
            next_action={
                "code": "promotion_activation_plan_prepare_required",
                "action": "run_offline_prepare",
                "command": (
                    "scripts/merge-and-deploy.sh --prepare "
                    "--promotion-manifest <manifest.json> "
                    "--activation-plan <outside-repo-plan.json>"
                ),
                "activation_requires_separate_command": True,
                "automatic_activation": False,
                "actionable": False,
                "writes_performed": False,
            },
            details={
                **common,
                "qa_projection": qa,
                "operator_signoff_projection": signoff,
                "promotion_manifest_v2": manifest,
                "verifier_sha256": verifier_hash,
            },
        )
    except GovernanceError as exc:
        return _ac_promotion_rollback_response(
            project_id=project_id,
            state="degraded",
            response_view=response_view,
            next_action={
                "code": exc.code,
                "action": "stop_and_recover_exact_rollback_authority",
                "actionable": False,
                "writes_performed": False,
            },
            details={
                "projection_degraded": True,
                "projection_degraded_reason": {
                    "code": exc.code,
                    "details": dict(exc.details or {}),
                },
            },
        )


def _onboard_route_guide_service_response(
    conn,
    *,
    request_context: RequestContext | None = None,
    project_id: str,
    backlog_id: str,
    route_token_ref: str = "",
    role: str = "",
    work_type: str = "",
    response_view: str = "",
    request_body: Mapping[str, Any] | None = None,
    request_selector_claims: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    activation_blocker = _ac_promotion_successor_activation_preguard(
        request_context=request_context,
        project_id=project_id,
        backlog_id=backlog_id,
        response_view=response_view,
        request_body=request_body,
        request_selector_claims=request_selector_claims,
    )
    if activation_blocker:
        return activation_blocker
    rollback_successor = _ac_promotion_rollback_route_guide_overlay(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        route_token_ref=route_token_ref,
        response_view=response_view,
        request_body=request_body,
        request_selector_claims=request_selector_claims,
    )
    if rollback_successor:
        return rollback_successor
    from .parallel_branch_runtime import (
        get_active_integration_epoch,
        integration_epoch_resume_payload,
        integration_epoch_to_dict,
    )

    requested_route_token_ref = str(route_token_ref or "").strip()
    active_epoch = get_active_integration_epoch(conn, project_id)
    if active_epoch is not None:
        resume = _server_integration_epoch_resume_payload(conn, active_epoch)
        repair_authority = (
            resume.get("fresh_repair_successor_authority")
            if isinstance(
                resume.get("fresh_repair_successor_authority"), Mapping
            )
            else {}
        )
        exact_repair_request = bool(
            resume.get("id")
            == "active_epoch_worldref_precheck_fresh_repair_successor"
            and str(backlog_id or "").strip()
            == _ACTIVE_EPOCH_WORLDREF_REPAIR_BACKLOG_ID
            and str(role or "").strip() == "observer"
            and str(work_type or "").strip()
            in {"direct_main", _OPERATOR_SUPERVISED_DIRECT_MAIN_WORK_TYPE}
            and repair_authority.get("server_derived") is True
            and str(repair_authority.get("authority_hash") or "").strip()
            == stable_sha256(
                {
                    key: value
                    for key, value in repair_authority.items()
                    if key != "authority_hash"
                }
            )
        )
        if exact_repair_request:
            direct_repair = (
                _onboard_operator_supervised_direct_main_runtime_response(
                    conn,
                    project_id=project_id,
                    backlog_id=backlog_id,
                    route_token_ref=route_token_ref,
                    role=role,
                    work_type=work_type,
                    response_view=response_view,
                    request_context=request_context,
                    request_body=request_body,
                    request_selector_claims=request_selector_claims,
                )
            )
            if direct_repair:
                repair_next_action = (
                    dict(direct_repair.get("next_legal_action"))
                    if isinstance(
                        direct_repair.get("next_legal_action"), Mapping
                    )
                    else None
                )
                if repair_next_action is not None:
                    repair_next_action[
                        "active_epoch_parent_authority"
                    ] = deepcopy(dict(repair_authority))
                return {
                    **dict(direct_repair),
                    "schema_version": (
                        "onboard_route_guide.active_epoch_worldref_"
                        "fresh_repair.v1"
                    ),
                    "selected_backlog_source": (
                        "active_epoch_worldref_precheck_fresh_repair"
                    ),
                    "next_legal_action": repair_next_action,
                    "active_integration_epoch_parent": (
                        integration_epoch_to_dict(active_epoch)
                    ),
                    "active_epoch_parent_authority": deepcopy(
                        dict(repair_authority)
                    ),
                    "parent_refusal": deepcopy(
                        dict(resume.get("parent_refusal") or {})
                    ),
                    "position_skippable": False,
                    "old_epoch_mutated": False,
                    "pass_synthesized": False,
                }
        canonical_backlog_id = str(
            resume.get("backlog_id")
            or active_epoch.coordination_backlog_id
            or backlog_id
        ).strip()
        failure_domain_disposition = (
            _latest_observer_failure_domain_disposition(
                conn,
                project_id=project_id,
                backlog_id=canonical_backlog_id,
                task_id=str(active_epoch.active_task_id or ""),
            )
        )
        if failure_domain_disposition:
            resume = {
                **dict(resume),
                "failure_domain_disposition": failure_domain_disposition,
            }
        if response_view == "compact":
            current_projection = _onboard_guide_capsule_current_projection(
                conn,
                project_id=project_id,
                backlog_id=canonical_backlog_id,
                route_token_ref=route_token_ref,
            )
            return _onboard_route_guide_compact_service_response(
                project_id=project_id,
                backlog_id=canonical_backlog_id,
                role=role,
                work_type=work_type,
                record={
                    "contract_execution_id": str(
                        resume.get("contract_execution_id") or ""
                    )
                },
                next_action=resume,
                current_projection=current_projection,
                runtime_resume=resume,
                target_files=[],
                projection_degraded=False,
            )
        return {
            "schema_version": "onboard_route_guide.integration_epoch_resume.v1",
            "ok": True,
            "project_id": project_id,
            "backlog_id": canonical_backlog_id,
            "requested_backlog_id": backlog_id,
            "selected_role": str(role or "").strip(),
            "selected_work_type": str(work_type or "").strip(),
            "selected_backlog_source": "active_integration_epoch",
            "service": {
                "id": ONBOARD_ROUTE_GUIDE_SERVICE_ID,
                "kind": "guide_service",
                "source": "durable_integration_epoch",
            },
            "integration_epoch": integration_epoch_to_dict(active_epoch),
            "next_legal_action": resume,
            "failure_domain_disposition": failure_domain_disposition,
            "position_skippable": False,
            "raw_route_token_required": False,
            "raw_route_token_exposed": False,
        }
    entered_batch_resume = _entered_batch_successor_resume_projection(
        conn,
        project_id=project_id,
        coordination_backlog_id=backlog_id,
    )
    if entered_batch_resume:
        current_projection = _onboard_guide_capsule_current_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            route_token_ref=route_token_ref,
        )
        next_action = dict(
            entered_batch_resume.get("next_legal_action") or {}
        )
        try:
            record = _contract_runtime_store(conn).get(
                _onboard_service_execution_id(project_id, backlog_id)
            )
        except ContractRuntimeError:
            record = {}
        target_files = _runtime_context_public_file_values(
            (
                next_action.get("action_input") or {}
            ).get("target_files")
            if isinstance(next_action.get("action_input"), Mapping)
            else []
        )
        if response_view == "compact":
            return _onboard_route_guide_compact_service_response(
                project_id=project_id,
                backlog_id=backlog_id,
                role=role,
                work_type=work_type,
                record=record,
                next_action=next_action,
                current_projection=current_projection,
                runtime_resume=entered_batch_resume,
                target_files=target_files,
                projection_degraded=False,
            )
        return {
            "schema_version": "onboard_route_guide.entered_batch_resume.v1",
            "ok": True,
            "project_id": project_id,
            "backlog_id": backlog_id,
            "selected_role": str(role or "").strip(),
            "selected_work_type": str(work_type or "").strip(),
            "selected_backlog_source": "durable_entered_batch",
            "service": {
                "id": ONBOARD_ROUTE_GUIDE_SERVICE_ID,
                "kind": "guide_service",
                "source": "durable_entered_batch",
            },
            "contract_chain_current": current_projection,
            "runtime_resume": entered_batch_resume,
            "next_legal_action": next_action,
            "position_skippable": False,
            "raw_route_token_required": False,
            "raw_route_token_exposed": False,
        }
    promotion_successor = _ac_promotion_successor_route_guide_overlay(
        conn,
        request_context=request_context,
        project_id=project_id,
        backlog_id=backlog_id,
        route_token_ref=route_token_ref,
        role=role,
        work_type=work_type,
        response_view=response_view,
        request_body=request_body,
        request_selector_claims=request_selector_claims,
    )
    if promotion_successor:
        return promotion_successor
    direct_main_response = (
        _onboard_operator_supervised_direct_main_runtime_response(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            route_token_ref=route_token_ref,
            role=role,
            work_type=work_type,
            response_view=response_view,
            request_context=request_context,
            request_body=request_body,
            request_selector_claims=request_selector_claims,
        )
    )
    if direct_main_response:
        return direct_main_response
    terminal_successor = _ac_dev_direct_terminal_successor_response(
        conn, project_id=project_id, backlog_id=backlog_id, route_token_ref=route_token_ref, role=role, work_type=work_type,
        request_body=request_body, request_selector_claims=request_selector_claims)
    if terminal_successor: return terminal_successor
    preexisting_projection = _contract_chain_current_projection(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        rebuild_if_missing=False,
        route_token_ref=route_token_ref,
    )
    preexisting_projection_complete = _source_backed_contract_chain_is_complete(
        preexisting_projection
    )
    backlog_row_status = _backlog_row_status_for_onboard_route(conn, backlog_id)
    backlog_policy_row = conn.execute(
        """
        SELECT bypass_policy_json, chain_trigger_json, mf_type
          FROM backlog_bugs
         WHERE bug_id = ?
        """,
        (backlog_id,),
    ).fetchone()
    bypass_policy = backlog_runtime.parse_json_object(
        _row_get(backlog_policy_row, "bypass_policy_json", "{}")
    )
    chain_trigger = backlog_runtime.parse_json_object(
        _row_get(backlog_policy_row, "chain_trigger_json", "{}")
    )
    direct_fix_authority = _direct_fix_terminal_retirement_authority()
    no_direct_fix = not bool(direct_fix_authority["entry_allowed"])
    historical_source_resume = bool(direct_fix_authority["resume_allowed"])
    materialize_route_token_ref = route_token_ref
    if (
        str(role or "").strip() == "observer"
        and str(work_type or "").strip() == "legacy_operator_recovery"
    ):
        # The managed recovery ref is a proof for the sibling hotfix facade,
        # not authority to rewrite the active ContractRuntime chain binding.
        # The dedicated projection below validates it against the exact
        # backlog + parent CEX + hotfix action before exposing any action.
        materialize_route_token_ref = ""
    if str(work_type or "").strip() in {
        "multi_backlog_parallel",
        "mf_batch_parallel",
    }:
        try:
            existing_batch_parent = _contract_runtime_store(conn).get(
                _onboard_service_execution_id(project_id, backlog_id)
            )
        except ContractRuntimeError:
            existing_batch_parent = {}
        existing_batch_metadata = (
            existing_batch_parent.get("metadata")
            if isinstance(existing_batch_parent.get("metadata"), Mapping)
            else {}
        )
        existing_batch_binding = (
            existing_batch_metadata.get("mf_batch_parallel_entry_binding")
            if isinstance(
                existing_batch_metadata.get("mf_batch_parallel_entry_binding"),
                Mapping,
            )
            else {}
        )
        existing_batch_action = (
            existing_batch_binding.get("action_input")
            if isinstance(existing_batch_binding.get("action_input"), Mapping)
            else {}
        )
        if existing_batch_binding:
            existing_batch_binding = (
                _onboard_service_verified_mf_batch_entry_binding(
                    existing_batch_parent,
                    project_id=project_id,
                    backlog_id=backlog_id,
                    require_ready=False,
                )
            )
            existing_batch_action = dict(
                existing_batch_binding.get("action_input") or {}
            )
        if existing_batch_binding.get("ready") is True:
            materialize_route_token_ref = str(
                existing_batch_action.get("observer_route_token_ref") or ""
            ).strip()
        else:
            proposed_action_input = _mf_batch_parallel_entry_action_input_contract(
                project_id=project_id,
                backlog_id=backlog_id,
                route_token_ref=route_token_ref,
                request_body=request_body,
            )
            if not _mf_batch_parallel_entry_action_input_missing(
                proposed_action_input
            ):
                _onboard_service_require_mf_batch_guide_observer_proof(
                    request_context,
                    conn,
                    project_id=project_id,
                    backlog_id=backlog_id,
                )
    record = _onboard_service_materialize_parent_record(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        route_token_ref=materialize_route_token_ref,
    )
    route_token_ref = str(record.get("route_token_ref") or "").strip()
    batch_action_request_body = request_body
    if str(work_type or "").strip() in {
        "multi_backlog_parallel",
        "mf_batch_parallel",
    }:
        record = _onboard_service_bind_mf_batch_entry_contract(
            conn,
            record=record,
            project_id=project_id,
            backlog_id=backlog_id,
            route_token_ref=route_token_ref,
            request_body=request_body,
        )
        bound_metadata = (
            record.get("metadata")
            if isinstance(record.get("metadata"), Mapping)
            else {}
        )
        bound_entry = (
            bound_metadata.get("mf_batch_parallel_entry_binding")
            if isinstance(
                bound_metadata.get("mf_batch_parallel_entry_binding"), Mapping
            )
            else {}
        )
        if bound_entry:
            bound_entry = _onboard_service_verified_mf_batch_entry_binding(
                record,
                project_id=project_id,
                backlog_id=backlog_id,
                require_ready=False,
            )
        if bound_entry.get("ready") is True:
            batch_action_request_body = dict(bound_entry["action_input"])
    target_files = _onboard_contract_route_issue_target_files(
        conn,
        backlog_id=backlog_id,
        body={},
        metadata={},
    )
    mf_parallel_entry_authority = {}
    if (
        str(role or "").strip() == "observer"
        and str(work_type or "").strip() in {"parallel_worker", "mf_parallel"}
    ):
        mf_parallel_entry_authority = (
            _onboard_route_guide_completed_mf_parallel_entry_authority(
                conn,
                request_context=request_context,
                project_id=project_id,
                backlog_id=backlog_id,
                parent_record=record,
                route_token_ref=route_token_ref,
                target_files=target_files,
                request_body=request_body,
            )
        )
    current_projection = _contract_chain_current_projection(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        rebuild_if_missing=True,
        route_token_ref=route_token_ref,
    )
    current_projection = _contract_chain_current_with_backlog_close_blocker(
        conn,
        project_id=project_id,
        backlog_id=backlog_id,
        current_projection=current_projection,
        route_token_ref=route_token_ref,
    )
    current_projection = _contract_chain_current_with_runtime_authority_overlay(
        current_projection
    )
    preexisting_next_action = (
        preexisting_projection.get("next_legal_action")
        if isinstance(preexisting_projection.get("next_legal_action"), Mapping)
        else {}
    )
    if (
        str(role or "").strip() == "qa"
        and str(preexisting_next_action.get("line_id") or "").strip()
        in {"qa_graph_context", "qa_independent_verification"}
    ):
        current_projection = _contract_chain_current_with_backlog_close_blocker(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            current_projection=preexisting_projection,
            route_token_ref=route_token_ref,
        )
        current_projection = _contract_chain_current_with_runtime_authority_overlay(
            current_projection
        )
    projection_degraded = bool(current_projection.get("degraded"))
    record["metadata"] = {
        **dict(record.get("metadata") or {}),
        "route_token_issue_target_files": target_files,
        "backlog_storage_mf_type": str(
            _row_get(backlog_policy_row, "mf_type", "") or ""
        ).strip(),
        "no_direct_fix": no_direct_fix,
        "direct_fix_policy_source": str(
            direct_fix_authority["authority_source"]
        ),
        "historical_source_resume": historical_source_resume,
        "post_reconcile_action": str(
            chain_trigger.get("after_merge") or ""
        ).strip(),
    }
    runtime_resume = {}
    if current_projection and not projection_degraded:
        runtime_resume = _onboard_runtime_resume_from_current_projection(
            current_projection
        )
        selected_work_type = str(work_type or "").strip()
        current_projection_complete = _source_backed_contract_chain_is_complete(
            current_projection
        )
        if (
            selected_work_type
            in {"continue_contract_chain", "rollback_or_recover_contract", "direct_fix"}
            and not runtime_resume.get("next_legal_action")
            and not str(
                current_projection.get("active_child_contract_execution_id") or ""
            ).strip()
            and not current_projection_complete
        ):
            blocked_resume = _onboard_blocked_contract_resume_projection(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                actor_role=str(role or "").strip() or "observer",
                route_token_ref=route_token_ref,
            )
            if blocked_resume:
                blocked_resume["shadowed_current_projection"] = {
                    "source": "backlog_contract_chain_current",
                    "readiness_state": str(
                        current_projection.get("readiness_state") or ""
                    ),
                    "current_contract_execution_id": str(
                        current_projection.get("current_contract_execution_id") or ""
                    ),
                    "projection_hash": str(
                        current_projection.get("projection_hash") or ""
                    ),
                }
                runtime_resume = blocked_resume
        elif (
            selected_work_type
            in {"continue_contract_chain", "rollback_or_recover_contract", "direct_fix"}
            and current_projection_complete
        ):
            blocked_resume = _onboard_blocked_contract_resume_projection(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                actor_role=str(role or "").strip() or "observer",
                route_token_ref=route_token_ref,
            )
            if blocked_resume:
                suppress_stale_resume = preexisting_projection_complete or (
                    backlog_row_status == "FIXED"
                    and selected_work_type == "continue_contract_chain"
                )
                if suppress_stale_resume:
                    conflict_status = (
                        "suppressed_terminal_fixed_continue"
                        if (
                            backlog_row_status == "FIXED"
                            and selected_work_type == "continue_contract_chain"
                            and not preexisting_projection_complete
                        )
                        else "suppressed_stale_resume"
                    )
                    runtime_resume["projection_conflict"] = {
                        "schema_version": "onboard_route_guide.projection_conflict.v1",
                        "status": conflict_status,
                        "authoritative_source": "backlog_contract_chain_current",
                        "authoritative_readiness_state": str(
                            current_projection.get("readiness_state") or ""
                        ),
                        "backlog_row_status": backlog_row_status,
                        "shadowed_source": str(blocked_resume.get("source") or ""),
                        "shadowed_mode": str(blocked_resume.get("mode") or ""),
                        "shadowed_next_legal_action": dict(
                            blocked_resume.get("next_legal_action")
                            if isinstance(blocked_resume.get("next_legal_action"), Mapping)
                            else {}
                        ),
                        "safe_next_step": (
                            "do_not_enter_duplicate_successor; continue from "
                            "backlog_contract_chain_current"
                        ),
                    }
                    if backlog_row_status == "FIXED":
                        runtime_resume["projection_conflict"]["safe_next_step"] = (
                            "row_is_fixed; use explicit audit/reopen recovery "
                            "instead of normal continue_contract_chain"
                        )
                        runtime_resume["fixed_row_terminal"] = True
                    runtime_resume["stale_compact_ledger_suppressed"] = True
                else:
                    blocked_resume["shadowed_current_projection"] = {
                        "source": "backlog_contract_chain_current",
                        "readiness_state": str(
                            current_projection.get("readiness_state") or ""
                        ),
                        "current_contract_execution_id": str(
                            current_projection.get("current_contract_execution_id") or ""
                        ),
                        "projection_hash": str(
                            current_projection.get("projection_hash") or ""
                        ),
                    }
                    runtime_resume = blocked_resume
    else:
        runtime_resume = _onboard_blocked_contract_resume_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            actor_role=str(role or "").strip() or "observer",
            route_token_ref=route_token_ref,
        )
        if current_projection:
            runtime_resume["projection_degraded"] = True
            runtime_resume["projection_degraded_reason"] = (
                current_projection.get("degraded_flags") or {}
            )
    failure_domain_disposition = (
        _latest_observer_failure_domain_disposition(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
    )
    if failure_domain_disposition:
        runtime_resume = {
            **dict(runtime_resume),
            "failure_domain_disposition": failure_domain_disposition,
        }
        current_projection = {
            **dict(current_projection),
            "failure_domain_disposition": failure_domain_disposition,
        }
    contract_update_selection_authority = (
        _backlog_contract_update_selection_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
    )
    wrong_family_contract_update_supersession = (
        _onboard_wrong_family_contract_update_terminal_supersession(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            current_projection=current_projection,
            requested_work_type=work_type,
            selection_authority=contract_update_selection_authority,
        )
    )
    onboard_service_continuation_authority = {}
    if (
        str(role or "").strip() == "observer"
        and str(work_type or "").strip() == "continue_contract_chain"
    ):
        onboard_service_continuation_authority = (
            _onboard_service_contract_update_continuation_authority(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                current_projection=current_projection,
                route_token_ref=route_token_ref,
                target_files=target_files,
            )
        )
    source_free_operation_authority = (
        _backlog_source_free_operation_authority(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
        if str(role or "").strip() == "observer"
        and str(work_type or "").strip() == "system_operation"
        else {}
    )
    source_free_requested_route_ref = str(
        (request_body or {}).get("route_token_ref")
        or (request_body or {}).get("observer_route_token_ref")
        or ""
    ).strip()
    completed_route_token_ref = (
        source_free_requested_route_ref
        if source_free_operation_authority
        else route_token_ref
    )
    completed_source_free_reconcile_authority = (
        _completed_source_free_reconcile_authority(
            conn,
            request_context=request_context,
            project_id=project_id,
            backlog_id=backlog_id,
            route_token_ref=completed_route_token_ref,
            source_free_authority=source_free_operation_authority,
        )
        if source_free_operation_authority and completed_route_token_ref
        else {}
    )
    next_action = _onboard_route_guide_service_next_action(
        role=role,
        work_type=work_type,
    )
    if runtime_resume:
        resume_next = runtime_resume.get("next_legal_action")
        if runtime_resume.get("terminal") is True:
            next_action = _onboard_route_guide_completed_next_action(
                role=role,
                work_type=work_type,
                runtime_resume=runtime_resume,
                backlog_row_status=backlog_row_status,
                project_id=project_id,
                backlog_id=backlog_id,
                route_token_ref=completed_route_token_ref,
                target_files=target_files,
                request_body=batch_action_request_body,
                onboard_service_continuation_authority=(
                    onboard_service_continuation_authority
                ),
                mf_parallel_entry_authority=mf_parallel_entry_authority,
                source_free_operation_authority=(
                    source_free_operation_authority
                ),
                completed_source_free_reconcile_authority=(
                    completed_source_free_reconcile_authority
                ),
            )
        elif runtime_resume.get("scheduler_eligible") is False:
            next_action = {}
        elif isinstance(resume_next, Mapping) and resume_next:
            next_action = dict(resume_next)
        elif _onboard_runtime_resume_is_complete(runtime_resume):
            next_action = _onboard_route_guide_completed_next_action(
                role=role,
                work_type=work_type,
                runtime_resume=runtime_resume,
                backlog_row_status=backlog_row_status,
                project_id=project_id,
                backlog_id=backlog_id,
                route_token_ref=completed_route_token_ref,
                target_files=target_files,
                request_body=batch_action_request_body,
                onboard_service_continuation_authority=(
                    onboard_service_continuation_authority
                ),
                mf_parallel_entry_authority=mf_parallel_entry_authority,
                source_free_operation_authority=(
                    source_free_operation_authority
                ),
                completed_source_free_reconcile_authority=(
                    completed_source_free_reconcile_authority
                ),
            )
    if wrong_family_contract_update_supersession:
        supersession_authority = dict(
            wrong_family_contract_update_supersession.get("authority") or {}
        )
        terminal_action = dict(
            wrong_family_contract_update_supersession.get("terminal_action")
            or {}
        )
        parent_resume = {
            "schema_version": "onboard_route_guide.runtime_resume.v1",
            "status": "contract_complete",
            "readiness_state": "contract_complete",
            "project_id": project_id,
            "backlog_id": backlog_id,
            "current_contract_execution_id": _onboard_service_execution_id(
                project_id,
                backlog_id,
            ),
            "root_contract_execution_id": _onboard_service_execution_id(
                project_id,
                backlog_id,
            ),
            "contract_chain_id": _onboard_service_chain_id(
                project_id,
                backlog_id,
            ),
            "next_legal_action": {},
        }
        fresh_action = _onboard_route_guide_completed_next_action(
            role=role,
            work_type=work_type,
            runtime_resume=parent_resume,
            backlog_row_status=backlog_row_status,
            project_id=project_id,
            backlog_id=backlog_id,
            route_token_ref=completed_route_token_ref,
            target_files=target_files,
            request_body=batch_action_request_body,
            onboard_service_continuation_authority=(
                onboard_service_continuation_authority
            ),
            mf_parallel_entry_authority=mf_parallel_entry_authority,
            source_free_operation_authority=source_free_operation_authority,
            completed_source_free_reconcile_authority=(
                completed_source_free_reconcile_authority
            ),
        )
        if str(fresh_action.get("action") or "") == "no_runtime_action":
            next_action = terminal_action
        else:
            next_action = {
                **dict(fresh_action),
                "wrong_family_source_terminal_no_pass": True,
                "terminal_supersession_authority": supersession_authority,
                "copy_safe_no_pass_terminal_action": terminal_action,
                "old_evidence_carry_forward": False,
            }
        current_projection = {
            **dict(current_projection),
            "readiness_state": "terminal_supersession_ready_no_pass",
            "next_legal_action": dict(next_action),
            "scheduler_eligible": False,
            "resume_eligible": False,
            "source_execution_write_eligible": False,
            "terminal_supersession_authority": supersession_authority,
            "copy_safe_no_pass_terminal_action": terminal_action,
        }
        runtime_resume = {
            **dict(runtime_resume),
            "status": "terminal_supersession_ready_no_pass",
            "readiness_state": "terminal_supersession_ready_no_pass",
            "next_legal_action": dict(next_action),
            "scheduler_eligible": False,
            "resume_eligible": False,
            "source_execution_write_eligible": False,
            "terminal_supersession_authority": supersession_authority,
            "copy_safe_no_pass_terminal_action": terminal_action,
        }
    terminal_supersession_action = (
        _mf_parallel_terminal_supersession_guide_action(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            route_token_ref=requested_route_token_ref or route_token_ref,
            request_body=request_body,
        )
        if (
            str(role or "").strip() == "observer"
            and not wrong_family_contract_update_supersession
        )
        else {}
    )
    if terminal_supersession_action:
        next_action = dict(terminal_supersession_action)
        current_projection = {
            **dict(current_projection),
            "readiness_state": "terminal_supersession_ready_no_pass",
            "next_legal_action": dict(next_action),
            "scheduler_eligible": False,
            "resume_eligible": False,
            "source_execution_write_eligible": False,
            "terminal_supersession_authority": dict(
                next_action.get("terminal_supersession_authority") or {}
            ),
        }
        runtime_resume = {
            **dict(runtime_resume),
            "status": "terminal_supersession_ready_no_pass",
            "readiness_state": "terminal_supersession_ready_no_pass",
            "next_legal_action": dict(next_action),
            "scheduler_eligible": False,
            "resume_eligible": False,
            "source_execution_write_eligible": False,
            "terminal_supersession_authority": dict(
                next_action.get("terminal_supersession_authority") or {}
            ),
        }
    managed_hotfix_attempt = (
        _onboard_legacy_operator_hotfix_attempt_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            role=role,
            work_type=work_type,
            route_token_ref=requested_route_token_ref,
            next_action=next_action,
            current_projection=current_projection,
            runtime_resume=runtime_resume,
        )
        if (
            not terminal_supersession_action
            and not wrong_family_contract_update_supersession
        )
        else {}
    )
    if managed_hotfix_attempt:
        next_action = managed_hotfix_attempt
    direct_main_failed_qa_state = (
        _onboard_parentless_direct_main_failed_qa_state(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
        )
    )
    if direct_main_failed_qa_state:
        next_action = _onboard_parentless_direct_main_failed_qa_next_action(
            direct_main_failed_qa_state
        )
        current_projection = {
            **dict(current_projection),
            "readiness_state": "failed_qa_direct_main_rework_required",
            "next_legal_action": dict(next_action),
            "scheduler_eligible": False,
            "resume_eligible": False,
            "direct_main_failed_qa_rework": dict(
                direct_main_failed_qa_state
            ),
        }
        runtime_resume = {
            **dict(runtime_resume),
            "status": "failed_qa_direct_main_rework_required",
            "readiness_state": "failed_qa_direct_main_rework_required",
            "next_legal_action": dict(next_action),
            "scheduler_eligible": False,
            "resume_eligible": False,
            "direct_main_failed_qa_rework": dict(
                direct_main_failed_qa_state
            ),
        }
    irreversible_runtime_terminal_action = (
        _onboard_guide_irreversible_runtime_terminal_selection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            role=role,
            work_type=work_type,
            current_projection=current_projection,
            direct_main_failed_qa_state=direct_main_failed_qa_state,
        )
        if (
            not terminal_supersession_action
            and not wrong_family_contract_update_supersession
        )
        else {}
    )
    if irreversible_runtime_terminal_action:
        next_action = dict(irreversible_runtime_terminal_action)
        current_projection = (
            _onboard_guide_apply_irreversible_runtime_terminal_selection(
                current_projection,
                next_action,
            )
        )
        runtime_resume = {
            **dict(runtime_resume),
            "status": "irreversible_runtime_audit_terminal_ready",
            "readiness_state": "irreversible_runtime_audit_terminal_ready",
            "next_legal_action": dict(next_action),
            "scheduler_eligible": False,
            "resume_eligible": False,
            "irreversible_runtime_audit_terminal_authority": dict(
                next_action.get(
                    "irreversible_runtime_audit_terminal_authority"
                )
                or {}
            ),
        }
    qa_runtime_record: Mapping[str, Any] | None = None
    if (
        str(role or "").strip() == "qa"
        and str(next_action.get("line_id") or "").strip()
        in {"qa_graph_context", "qa_independent_verification"}
    ):
        qa_runtime_record = {}
        qa_execution_id = _onboard_route_guide_target_contract_execution_id(
            next_action=next_action,
            current_projection=current_projection,
            runtime_resume=runtime_resume,
        )
        try:
            candidate = _contract_runtime_store(conn).get(qa_execution_id)
        except ContractRuntimeError:
            candidate = {}
        if (
            str(candidate.get("project_id") or "") == project_id
            and str(candidate.get("backlog_id") or "") == backlog_id
            and not _onboard_service_record(candidate)
        ):
            qa_runtime_record = candidate
    if response_view == "compact":
        next_action = _onboard_worker_read_runtime_facade_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            next_action=next_action,
            current_projection=current_projection,
            runtime_resume=runtime_resume,
            requested_task_id=str(
                (request_body or {}).get("task_id") or ""
            ).strip(),
            requested_route_token_ref=requested_route_token_ref,
        )
        return _onboard_route_guide_compact_service_response(
            project_id=project_id,
            backlog_id=backlog_id,
            role=role,
            work_type=work_type,
            record=record,
            next_action=next_action,
            current_projection=current_projection,
            runtime_resume=runtime_resume,
            target_files=target_files,
            projection_degraded=projection_degraded,
            qa_runtime_record=qa_runtime_record,
            requested_task_id=str(
                (request_body or {}).get("task_id") or ""
            ).strip(),
        )
    guidance = _onboard_contract_agent_guidance(
        record,
        next_legal_action=next_action,
        selected_role=str(role or "").strip() or "observer",
        qa_runtime_record=qa_runtime_record,
    )
    if current_projection:
        guidance["contract_chain_current"] = current_projection
        guidance["contract_chain"]["current_projection"] = current_projection
        route_guide = guidance.get("onboard_route_guide")
        if isinstance(route_guide, dict):
            route_guide["contract_chain_current"] = current_projection
            chain_binding = route_guide.get("backlog_chain_binding")
            if isinstance(chain_binding, dict):
                chain_binding["current_projection"] = current_projection
    if runtime_resume:
        guidance["runtime_resume"] = runtime_resume
        guidance["contract_chain"]["runtime_resume"] = runtime_resume
        route_guide = guidance.get("onboard_route_guide")
        if isinstance(route_guide, dict):
            route_guide["runtime_resume"] = runtime_resume
            chain_binding = route_guide.get("backlog_chain_binding")
            if isinstance(chain_binding, dict):
                chain_binding["runtime_resume"] = runtime_resume
            observer_entry = (
                route_guide.get("role_entries", {}).get("observer")
                if isinstance(route_guide.get("role_entries"), Mapping)
                else {}
            )
            if isinstance(observer_entry, dict):
                observer_entry["runtime_resume"] = runtime_resume
    bypass_recovery_fallback = (
        runtime_resume.get("bypass_recovery_fallback")
        if isinstance(runtime_resume.get("bypass_recovery_fallback"), Mapping)
        else current_projection.get("bypass_recovery_fallback")
        if isinstance(
            current_projection.get("bypass_recovery_fallback"), Mapping
        )
        else {}
    )
    if bypass_recovery_fallback:
        guidance["bypass_recovery_fallback"] = dict(
            bypass_recovery_fallback
        )
        route_guide = guidance.get("onboard_route_guide")
        if isinstance(route_guide, dict):
            route_guide["bypass_recovery_fallback"] = dict(
                bypass_recovery_fallback
            )
    completed_repair_barrier = (
        runtime_resume.get("completed_repair_fresh_generation_barrier")
        if isinstance(
            runtime_resume.get("completed_repair_fresh_generation_barrier"),
            Mapping,
        )
        else current_projection.get(
            "completed_repair_fresh_generation_barrier"
        )
        if isinstance(
            current_projection.get(
                "completed_repair_fresh_generation_barrier"
            ),
            Mapping,
        )
        else {}
    )
    if completed_repair_barrier:
        guidance["completed_repair_fresh_generation_barrier"] = dict(
            completed_repair_barrier
        )
        route_guide = guidance.get("onboard_route_guide")
        if isinstance(route_guide, dict):
            route_guide["completed_repair_fresh_generation_barrier"] = dict(
                completed_repair_barrier
            )
    if failure_domain_disposition:
        guidance["failure_domain_disposition"] = dict(
            failure_domain_disposition
        )
        route_guide = guidance.get("onboard_route_guide")
        if isinstance(route_guide, dict):
            route_guide["failure_domain_disposition"] = dict(
                failure_domain_disposition
            )
    if direct_main_failed_qa_state:
        guidance["direct_main_failed_qa_rework"] = dict(
            direct_main_failed_qa_state
        )
        route_guide = guidance.get("onboard_route_guide")
        if isinstance(route_guide, dict):
            route_guide["direct_main_failed_qa_rework"] = dict(
                direct_main_failed_qa_state
            )
    _onboard_route_guide_apply_runtime_route_token_scope(
        conn,
        record=record,
        guidance=guidance,
        next_action=next_action,
        current_projection=current_projection,
        runtime_resume=runtime_resume,
        qa_runtime_record=qa_runtime_record,
    )
    response = {
        "schema_version": "onboard_route_guide.service_response.v1",
        "ok": True,
        "project_id": project_id,
        "backlog_id": backlog_id,
        "service": {
            "id": ONBOARD_ROUTE_GUIDE_SERVICE_ID,
            "kind": "guide_service",
            "source": "onboard_route_guide_service",
        },
        "selected_role": str(role or "").strip(),
        "selected_work_type": str(work_type or "").strip(),
        "work_type_storage_projection": (
            _onboard_work_type_storage_projection(
                requested_work_type=str(work_type or "").strip(),
                selected_work_type=str(work_type or "").strip(),
                storage_mf_type=str(
                    (record.get("metadata") or {}).get(
                        "backlog_storage_mf_type"
                    )
                    if isinstance(record.get("metadata"), Mapping)
                    else ""
                ),
            )
        ),
        "legacy_onboard_contract_waived": True,
        "onboard_contract_required": False,
        "onboard_service_waiver": {
            "schema_version": "onboard_service_waiver.v1",
            "service_id": ONBOARD_ROUTE_GUIDE_SERVICE_ID,
            "legacy_onboard_contract_waived": True,
            "contract_execution_id": record["contract_execution_id"],
            "root_contract_execution_id": record["root_contract_execution_id"],
            "contract_chain_id": record["contract_chain_id"],
            "route_token_ref": route_token_ref,
        },
        "agent_onboard_guidance": guidance,
        "onboard_route_guide": guidance["onboard_route_guide"],
        "contract_chain_current": current_projection,
        "projection_degraded": projection_degraded,
        "projection_degraded_reason": (
            current_projection.get("degraded_flags") if projection_degraded else {}
        ),
        "runtime_resume": runtime_resume,
        "next_legal_action": next_action,
        "raw_route_token_required": False,
        "raw_route_token_exposed": False,
    }
    if bypass_recovery_fallback:
        response["bypass_recovery_fallback"] = dict(
            bypass_recovery_fallback
        )
    if completed_repair_barrier:
        response["completed_repair_fresh_generation_barrier"] = dict(
            completed_repair_barrier
        )
    if direct_main_failed_qa_state:
        response["direct_main_failed_qa_rework"] = dict(
            direct_main_failed_qa_state
        )
    if response_view == "full":
        response["response_view"] = "full"
        return response
    return _qa_onboard_compact_selected_role_response(response)


def _onboard_contract_response(record: Mapping[str, Any]) -> dict[str, Any]:
    guide = record.get("runtime_guide") if isinstance(record.get("runtime_guide"), Mapping) else {}
    current_state = _runtime_current_state_from_record(record)
    next_legal_action = _runtime_next_action_from_guide(guide)
    return {
        "schema_version": "onboard_contract.runtime_facade_response.v1",
        "ok": True,
        "project_id": str(record.get("project_id") or ""),
        "backlog_id": str(record.get("backlog_id") or ""),
        "contract_execution_id": str(record.get("contract_execution_id") or ""),
        "root_contract_execution_id": str(record.get("root_contract_execution_id") or ""),
        "parent_contract_execution_id": str(
            record.get("parent_contract_execution_id") or ""
        ),
        "contract_chain_id": str(record.get("contract_chain_id") or ""),
        "contract_id": str(record.get("contract_id") or ""),
        "contract_runtime_current_state": current_state,
        "runtime_guide": guide,
        "runtime_guide_hash": str(guide.get("runtime_guide_hash") or ""),
        "next_legal_action": next_legal_action,
        "execution_state_revision": current_state["execution_state_revision"],
        "execution_state_hash": current_state["execution_state_hash"],
        "route_token_ref": str(record.get("route_token_ref") or ""),
        "agent_onboard_guidance": _onboard_contract_agent_guidance(
            record,
            next_legal_action=next_legal_action,
        ),
        "agent_facing_decision_source": "contract_runtime_first_missing_line",
    }


def _onboard_contract_require_contract_record(
    record: Mapping[str, Any],
    *,
    contract_execution_id: str,
    action: str,
) -> None:
    if str(record.get("contract_id") or "") == ONBOARD_CONTRACT_ID:
        return
    raise ValidationError(
        f"onboard_contract facade can only {action} onboard_contract executions",
        {
            "contract_execution_id": contract_execution_id,
            "contract_id": str(record.get("contract_id") or ""),
        },
    )


def _onboard_contract_start(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    actor_role: str,
    route_token_ref: str = "",
    contract_execution_id: str = "",
    metadata: Mapping[str, Any] | None = None,
    recovery_policy: str = "",
    stale_contract_execution_id: str = "",
) -> dict[str, Any]:
    deterministic_execution_id = _onboard_contract_execution_id(project_id, backlog_id)
    if contract_execution_id:
        raise ValidationError(
            "onboard_contract root execution id is deterministic; custom contract_execution_id is not allowed",
            {
                "contract_execution_id": contract_execution_id,
                "deterministic_contract_execution_id": deterministic_execution_id,
                "contract_id": ONBOARD_CONTRACT_ID,
            },
        )
    runtime = _contract_runtime(conn)
    execution_id = deterministic_execution_id
    try:
        record = runtime.store.get(execution_id)
        _onboard_contract_require_contract_record(
            record,
            contract_execution_id=execution_id,
            action="enter/read",
        )
        if route_token_ref and not str(record.get("route_token_ref") or ""):
            record["route_token_ref"] = route_token_ref
            runtime.store.update(execution_id, record)
    except ContractRuntimeError:
        if _contract_runtime_recovery_requested(recovery_policy):
            raise ValidationError(
                "onboard_contract recovery requested but no stale deterministic execution exists",
                {
                    "contract_execution_id": deterministic_execution_id,
                    "recovery_policy": recovery_policy,
                },
            )
        record = runtime.start_execution(
            ONBOARD_CONTRACT_ID,
            project_id=project_id,
            backlog_id=backlog_id,
            actor_role=actor_role,
            contract_execution_id=execution_id,
            root_contract_execution_id=execution_id,
            contract_chain_id=_onboard_contract_chain_id(project_id, backlog_id),
            route_token_ref=route_token_ref,
            role_binding={
                "observer": "observer",
                "binding_source": "onboard_contract_facade",
            },
            backlog_lineage={
                "project_id": project_id,
                "backlog_id": backlog_id,
            },
            metadata={
                "facade": "onboard_contract",
                "generic_crud_exposed": False,
                **dict(metadata or {}),
            },
        )
    try:
        record = runtime.current_record(execution_id, actor_role=actor_role)
        guide = record["runtime_guide"]
    except StalePinnedContractExecutionError as exc:
        if not _contract_runtime_recovery_requested(recovery_policy):
            raise
        if stale_contract_execution_id and stale_contract_execution_id != execution_id:
            raise ValidationError(
                "stale_contract_execution_id does not match the deterministic onboard execution",
                {
                    "stale_contract_execution_id": stale_contract_execution_id,
                    "deterministic_contract_execution_id": execution_id,
                },
            )
        recovery_execution_id = _contract_runtime_stale_recovery_id(exc)
        recovery_chain_id = _contract_runtime_stable_id(
            "cchain-recovery",
            project_id,
            backlog_id,
            ONBOARD_CONTRACT_ID,
            recovery_execution_id,
        )
        try:
            record = runtime.store.get(recovery_execution_id)
            _onboard_contract_require_contract_record(
                record,
                contract_execution_id=recovery_execution_id,
                action="enter/read",
            )
            if route_token_ref and not str(record.get("route_token_ref") or ""):
                record["route_token_ref"] = route_token_ref
                runtime.store.update(recovery_execution_id, record)
        except ContractRuntimeError:
            record = runtime.start_execution(
                ONBOARD_CONTRACT_ID,
                project_id=project_id,
                backlog_id=backlog_id,
                actor_role=actor_role,
                contract_execution_id=recovery_execution_id,
                root_contract_execution_id=recovery_execution_id,
                contract_chain_id=recovery_chain_id,
                route_token_ref=route_token_ref,
                role_binding={
                    "observer": "observer",
                    "binding_source": "onboard_contract_recovery_facade",
                },
                backlog_lineage={
                    "project_id": project_id,
                    "backlog_id": backlog_id,
                    "stale_contract_execution_id": execution_id,
                },
                metadata={
                    "facade": "onboard_contract",
                    "generic_crud_exposed": False,
                    "recovery_policy": "start_new_execution",
                    "stale_contract_execution_id": execution_id,
                    "recovery_reason": "stale_pinned_execution",
                    **dict(metadata or {}),
                },
            )
        execution_id = recovery_execution_id
        record = runtime.current_record(execution_id, actor_role=actor_role)
        guide = record["runtime_guide"]
    return record


def _onboard_contract_read(
    conn,
    *,
    contract_execution_id: str,
    actor_role: str,
) -> dict[str, Any]:
    runtime = _contract_runtime(conn)
    record = runtime.store.get(contract_execution_id)
    _onboard_contract_require_contract_record(
        record,
        contract_execution_id=contract_execution_id,
        action="enter/read",
    )
    record = runtime.current_record(
        contract_execution_id,
        actor_role=actor_role,
    )
    return record


def _onboard_contract_parent_for_successor(
    conn,
    *,
    project_id: str,
    backlog_id: str,
    actor_role: str,
) -> dict[str, Any]:
    runtime = _contract_runtime(conn)
    records = runtime.store.list_by_backlog(
        project_id=project_id,
        backlog_id=backlog_id,
        contract_id=ONBOARD_CONTRACT_ID,
    )
    if not records:
        deterministic = _onboard_contract_execution_id(project_id, backlog_id)
        raise ContractRuntimeError(f"unknown contract execution: {deterministic}")

    stale: list[StalePinnedContractExecutionError] = []
    incomplete: list[dict[str, Any]] = []
    for record in records:
        execution_id = str(record.get("contract_execution_id") or "")
        if not execution_id:
            continue
        try:
            refreshed = _onboard_contract_read(
                conn,
                contract_execution_id=execution_id,
                actor_role=actor_role,
            )
        except StalePinnedContractExecutionError as exc:
            stale.append(exc)
            continue
        if _runtime_record_is_complete(refreshed):
            return refreshed
        incomplete.append(refreshed)

    if incomplete:
        return incomplete[0]
    if stale:
        raise stale[0]
    deterministic = _onboard_contract_execution_id(project_id, backlog_id)
    raise ContractRuntimeError(f"unknown contract execution: {deterministic}")


def _onboard_contract_effective_actor_role(
    ctx: RequestContext,
    conn,
    *,
    action: str = "onboard_contract_facade",
    backlog_id: str = "",
    contract_execution_id: str = "",
) -> str:
    return _contract_runtime_effective_actor_role(
        ctx,
        conn,
        action=action,
        backlog_id=backlog_id,
        contract_execution_id=contract_execution_id,
    )


