@route("POST", "/api/projects/{project_id}/onboard-contract/start")
@route("POST", "/api/projects/{project_id}/onboard-contract/enter")
def handle_project_onboard_contract_start(ctx: RequestContext):
    """Legacy/internal onboard_contract facade; onboard_route_guide is the entrypoint."""
    project_id = ctx.get_project_id()
    body = dict(ctx.body or {})
    backlog_id = str(body.get("backlog_id") or body.get("bug_id") or "").strip()
    if not backlog_id:
        raise ValidationError("onboard_contract start requires backlog_id")
    route_token_ref = _contract_runtime_ref_value(
        ctx, "route_token_ref", "observer_route_token_ref"
    )
    contract_execution_id = str(body.get("contract_execution_id") or "").strip()
    metadata = (
        dict(body.get("metadata"))
        if isinstance(body.get("metadata"), Mapping)
        else {}
    )
    recovery_policy = str(body.get("recovery_policy") or "").strip()
    stale_contract_execution_id = str(
        body.get("stale_contract_execution_id") or ""
    ).strip()
    with DBContext(project_id) as conn:
        effective_execution_id = _onboard_contract_execution_id(project_id, backlog_id)
        metadata.setdefault(
            "route_token_issue_target_files",
            _onboard_contract_route_issue_target_files(
                conn,
                backlog_id=backlog_id,
                body=body,
                metadata=metadata,
            ),
        )
        actor_role = _onboard_contract_effective_actor_role(
            ctx,
            conn,
            action="onboard_contract_start",
            backlog_id=backlog_id,
            contract_execution_id=effective_execution_id,
        )
        if actor_role != "observer":
            raise PermissionDeniedError(
                actor_role,
                "onboard_contract_start",
                {"required_role": "observer"},
            )
        try:
            record = _onboard_contract_start(
                conn,
                project_id=project_id,
                backlog_id=backlog_id,
                actor_role=actor_role,
                route_token_ref=route_token_ref,
                contract_execution_id=contract_execution_id,
                metadata=metadata,
                recovery_policy=recovery_policy,
                stale_contract_execution_id=stale_contract_execution_id,
            )
        except StalePinnedContractExecutionError as exc:
            return _contract_runtime_stale_recovery_projection(
                exc,
                action="onboard_contract_start",
                route_token_ref=route_token_ref,
                actor_role=actor_role,
            )
        conn.commit()
    return _onboard_contract_response(record)


