@route("GET", "/api/projects/{project_id}/contract-add/{contract_execution_id}/current-state")
@route("GET", "/api/projects/{project_id}/contract-add/{contract_execution_id}/guide")
def handle_project_contract_add_current_state(ctx: RequestContext):
    """Read contract_add runtime guide/current-state without exposing CRUD."""
    project_id = ctx.get_project_id()
