@route("POST", "/api/projects/{project_id}/contract-update/{contract_execution_id}/line-writes")
def handle_project_contract_update_line_write(ctx: RequestContext):
    """Submit one role-bound contract_update evidence line via ContractRuntime."""
    project_id = ctx.get_project_id()
    contract_execution_id = str(ctx.path_params.get("contract_execution_id") or "").strip()
    if not contract_execution_id:
        raise ValidationError("contract_execution_id is required")
    body = dict(ctx.body or {})
    with DBContext(project_id) as conn:
        runtime = _contract_runtime(conn)
        record = runtime.store.get(contract_execution_id)
        _contract_update_require_contract_record(
            record,
            contract_execution_id=contract_execution_id,
            action="write",
        )
        actor_role = _contract_update_effective_actor_role(
            ctx,
            conn,
            action="contract_update_submit_line",
            backlog_id=str(record.get("backlog_id") or ""),
            contract_execution_id=contract_execution_id,
            record=record,
        )
        try:
            record = runtime.current_record(
                contract_execution_id,
                actor_role=actor_role,
            )
            record, _allocation_projection = (
                _contract_runtime_mf_parallel_dispatch_copy_safe_projection(
                    conn,
                    project_id=project_id,
                    record=record,
                )
            )
            blocked_record = _contract_runtime_apply_blocked_projection(
                conn,
                project_id=str(record.get("project_id") or ""),
                backlog_id=str(record.get("backlog_id") or ""),
                record=record,
                actor_role=actor_role,
            )
            blocked_next = (
                blocked_record.get("runtime_guide", {}).get("next_legal_action")
                if isinstance(blocked_record.get("runtime_guide"), Mapping)
                else {}
            )
            if (
                isinstance(blocked_next, Mapping)
                and str(blocked_next.get("status") or "") == "blocked"
            ):
                blocked_action = str(
                    blocked_next.get("next_operator_action")
                    or blocked_next.get("action")
                    or "enter_successor_contract"
                )
                response = {
                    "schema_version": "contract_update.line_write_response.v1",
                    "ok": False,
                    "project_id": project_id,
                    "contract_execution_id": contract_execution_id,
                    "actor_role": actor_role,
                    "decision": {
                        "schema_version": "contract_write_gate_decision.v1",
                        "ok": False,
                        "errors": [
                            f"contract execution is blocked; {blocked_action} before continuing"
                        ],
                    },
                    "agent_facing_decision_source": "contract_runtime_blocked_line",
                }
                response.update(_contract_update_response(blocked_record))
                response["ok"] = False
                response["decision"] = {
                    "schema_version": "contract_write_gate_decision.v1",
                    "ok": False,
                    "errors": [
                        f"contract execution is blocked; {blocked_action} before continuing"
                    ],
                }
                response["actor_role"] = actor_role
                response["agent_facing_decision_source"] = "contract_runtime_blocked_line"
                return response
            projected_completed_lines, successor_projection = (
                _contract_runtime_resumed_successor_projection(
                    conn,
                    project_id=str(record.get("project_id") or ""),
                    backlog_id=str(record.get("backlog_id") or ""),
                    record=record,
                    actor_role=actor_role,
                )
            )
            write_record = (
                blocked_record
                if projected_completed_lines is not None
                else record
            )
            write = _contract_runtime_line_write_body(
                write_record,
                actor_role=actor_role,
                body=body,
                worker_proof=getattr(ctx, "_contract_runtime_mf_sub_proof", None),
            )
            write, dispatch_errors = (
                _contract_runtime_bind_mf_parallel_dispatch_authority(
                    conn,
                    project_id=project_id,
                    record=write_record,
                    write=write,
                    _required_worker_count_override=1,
                )
            )
            if dispatch_errors:
                result = _contract_runtime_unchanged_line_rejection(
                    write_record,
                    dispatch_errors,
                )
            else:
                result = runtime.submit_line_write(
                    contract_execution_id,
                    write,
                    actor_role=actor_role,
                    projected_completed_lines=projected_completed_lines,
                    projection=successor_projection,
                )
        except StalePinnedContractExecutionError as exc:
            response = _contract_runtime_stale_recovery_projection(
                exc,
                action="contract_update_submit_line",
                route_token_ref=_contract_runtime_ref_value(
                    ctx, "route_token_ref", "observer_route_token_ref"
                ),
                actor_role=actor_role,
            )
            response["decision"] = {
                "ok": False,
                "errors": [str(exc)],
            }
            return response
        conn.commit()
        _publish_accepted_contract_runtime_line_write(
            project_id,
            result=result,
        )
    response = {
        "schema_version": "contract_update.line_write_response.v1",
        "ok": bool(result.get("ok")),
        "project_id": project_id,
        "contract_execution_id": contract_execution_id,
        "actor_role": actor_role,
        "decision": result.get("decision") or {},
        "agent_facing_decision_source": "contract_runtime_first_missing_line",
    }
    if isinstance(result.get("record"), Mapping):
        response.update(_contract_update_response(result["record"]))
        response["ok"] = bool(result.get("ok"))
        response["decision"] = result.get("decision") or {}
        response["actor_role"] = actor_role
    return response


@route("GET", "/api/projects/{project_id}/contract-runtime/{contract_execution_id}/current-state")
@route("GET", "/api/projects/{project_id}/contract-runtime/{contract_execution_id}/guide")
def handle_project_contract_runtime_current_state(ctx: RequestContext):
    """Read a source-backed ContractRuntime execution through the generic facade."""
    project_id = ctx.get_project_id()
    contract_execution_id = str(ctx.path_params.get("contract_execution_id") or "").strip()
    if not contract_execution_id:
        raise ValidationError("contract_execution_id is required")
    active_epoch_payload: dict[str, Any] = {}
    active_epoch_resume: dict[str, Any] = {}
    active_epoch_backlog_scope = ""
    runtime_context_projection: dict[str, Any] = {}
    compact_next_action_projection: dict[str, Any] = {}
    response_view = str(ctx.query.get("response_view") or "").strip()
    with DBContext(project_id) as conn:
        record = _contract_runtime_store(conn).get(contract_execution_id)
        actor_role = _contract_runtime_effective_actor_role(
            ctx,
            conn,
            action="contract_runtime_current",
            backlog_id=str(record.get("backlog_id") or ""),
            contract_execution_id=contract_execution_id,
            record=record,
        )
        try:
            record = _contract_runtime_read(
                conn,
                contract_execution_id=contract_execution_id,
                actor_role=actor_role,
            )
            record = _contract_runtime_bind_observer_dispatch_transport_proof(
                record,
                getattr(ctx, "_contract_runtime_observer_proof", None),
                conn=conn,
                project_id=project_id,
            )
        except StalePinnedContractExecutionError as exc:
            return _contract_runtime_stale_recovery_projection(
                exc,
                action="contract_runtime_current",
                route_token_ref=_contract_runtime_ref_value(
                    ctx, "route_token_ref", "observer_route_token_ref"
                ),
                actor_role=actor_role,
            )
        runtime_context_projection = (
            _contract_runtime_authoritative_runtime_context_projection(
                conn,
                project_id=project_id,
                record=record,
            )
        )
        if response_view in {"cli_current", "cli_guide"}:
            runtime_guide = (
                record.get("runtime_guide")
                if isinstance(record.get("runtime_guide"), Mapping)
                else {}
            )
            facade_next_action = _runtime_next_action_from_guide(
                runtime_guide
            )
            facade_current_state = _runtime_current_state_from_record(record)
            facade_current_next_action = (
                facade_current_state.get("next_legal_action")
                if isinstance(
                    facade_current_state.get("next_legal_action"), Mapping
                )
                else {}
            )
            if (
                facade_current_next_action.get("fresh_authority_required")
                is True
            ):
                facade_next_action = dict(facade_current_next_action)
            if facade_next_action.get("fresh_authority_required") is not True:
                for identity_field in ("runtime_context_id", "task_id"):
                    requested_identity = _contract_runtime_ref_value(
                        ctx,
                        identity_field,
                    )
                    if requested_identity and not facade_next_action.get(
                        identity_field
                    ):
                        facade_next_action[identity_field] = requested_identity
            facade_projection = _onboard_worker_read_runtime_facade_projection(
                conn,
                project_id=project_id,
                backlog_id=str(record.get("backlog_id") or ""),
                next_action=facade_next_action,
                current_projection={
                    "contract_execution_id": contract_execution_id,
                },
                runtime_resume={},
                requested_task_id=_contract_runtime_ref_value(
                    ctx,
                    "task_id",
                ),
                requested_route_token_ref=_contract_runtime_ref_value(
                    ctx,
                    "route_token_ref",
                    "observer_route_token_ref",
                ),
            )
            selected_line_id = str(
                facade_next_action.get("line_id") or ""
            ).strip()
            if selected_line_id in {
                "worker_finish_time_attestation",
                "worker_finish_gate",
            } or (
                facade_projection.get("actionable") is False
                and facade_projection.get("blocked_by_failed_qa") is True
            ):
                compact_next_action_projection = facade_projection
        from .parallel_branch_runtime import (
            integration_epoch_resume_payload,
            integration_epoch_to_dict,
            resolve_active_integration_epoch_for_backlog,
        )

        active_epoch, active_epoch_backlog_scope = (
            resolve_active_integration_epoch_for_backlog(
                conn,
                project_id,
                str(record.get("backlog_id") or ""),
            )
        )
        if active_epoch is not None:
            active_epoch_payload = integration_epoch_to_dict(active_epoch)
            active_epoch_resume = _server_integration_epoch_resume_payload(
                conn, active_epoch
            )
        conn.commit()
    public_record = (
        _operator_supervised_direct_main_public_runtime_record(record)
        if (
            str(record.get("contract_id") or "").strip()
            == "operator_supervised_direct_main"
            and str(record.get("revision") or "").strip()
            in _OPERATOR_SUPERVISED_DIRECT_MAIN_STRICT_REVISIONS
        )
        else record
    )
    response = _contract_runtime_response(
        public_record,
        actor_role=actor_role,
        response_view=response_view,
        request_id=ctx.request_id,
        compact_next_action_projection=compact_next_action_projection,
    )
    response["actor_role"] = actor_role
    if runtime_context_projection:
        response["runtime_context"] = runtime_context_projection
    if active_epoch_payload:
        from .contract_state_runtime import integration_epoch_resume_projection

        response["contract_runtime_next_legal_action"] = response.get(
            "next_legal_action"
        )
        epoch_projection = integration_epoch_resume_projection(active_epoch_payload)
        epoch_projection["next_legal_action"] = active_epoch_resume
        response["integration_epoch_resume_projection"] = epoch_projection
        response["integration_epoch"] = active_epoch_payload
        response["integration_backlog_scope"] = active_epoch_backlog_scope
        response["next_legal_action"] = active_epoch_resume
        response["position_skippable"] = False
    return response


@route("POST", "/api/projects/{project_id}/contract-runtime/recover")
def handle_project_contract_runtime_recover(ctx: RequestContext):
    """Start an idempotent current-definition execution for one stale pin."""

    project_id = ctx.get_project_id()
    body = dict(ctx.body or {})
    backlog_id = str(body.get("backlog_id") or "").strip()
    stale_execution_id = str(
        body.get("stale_contract_execution_id") or ""
    ).strip()
    recovery_policy = str(body.get("recovery_policy") or "").strip()
    requested_authority_hash = str(
        body.get("recovery_authority_hash") or ""
    ).strip()
    if not backlog_id:
        raise ValidationError("backlog_id is required")
    if not stale_execution_id:
        raise ValidationError("stale_contract_execution_id is required")
    if not _contract_runtime_recovery_requested(recovery_policy):
        raise ValidationError(
            "recovery_policy must request start_new_execution",
            {"recovery_policy": recovery_policy},
        )

    route_token_ref = _contract_runtime_ref_value(
        ctx, "route_token_ref", "observer_route_token_ref"
    )
    with DBContext(project_id) as conn:
        runtime = _contract_runtime(conn)
        stale_record = runtime.store.get(stale_execution_id)
        record_backlog_id = str(stale_record.get("backlog_id") or "").strip()
        if record_backlog_id != backlog_id:
            raise ValidationError(
                "stale contract execution backlog does not match recovery scope",
                {
                    "stale_contract_execution_id": stale_execution_id,
                    "backlog_id": backlog_id,
                    "record_backlog_id": record_backlog_id,
                },
            )
        actor_role = _contract_runtime_effective_actor_role(
            ctx,
            conn,
            action="contract_runtime_recover",
            backlog_id=backlog_id,
            contract_execution_id=stale_execution_id,
            record=stale_record,
        )
        if _normalized_contract_runtime_action(actor_role) != "observer":
            raise PermissionDeniedError(
                actor_role or "anonymous",
                "contract_runtime_recover",
                {"required_role": "observer"},
            )

        recovery_reason = "stale_pinned_execution"
        dead_initial_join_authority: dict[str, Any] = {}
        source_record = stale_record
        try:
            source_record = runtime.current_record(
                stale_execution_id,
                actor_role=actor_role,
            )
        except StalePinnedContractExecutionError as stale:
            if recovery_policy == "invalid_runtime_context_authority":
                raise ValidationError(
                    "runtime context authority recovery requires a current "
                    "source definition",
                    {
                        "contract_execution_id": stale_execution_id,
                        "fail_closed": True,
                    },
                )
            recovery_execution_id = _contract_runtime_stale_recovery_id(stale)
        else:
            if recovery_policy != "invalid_runtime_context_authority":
                raise ValidationError(
                    "contract runtime recovery requires a stale pinned "
                    "execution or exact invalid runtime authority",
                    {
                        "contract_execution_id": stale_execution_id,
                        "safe_to_continue_existing_execution": True,
                    },
                )
            if conn.in_transaction:
                conn.commit()
            conn.execute("BEGIN IMMEDIATE")
            stale_record = runtime.store.get(stale_execution_id)
            source_record = runtime.current_record(
                stale_execution_id,
                actor_role=actor_role,
            )
            locked_actor_role = _contract_runtime_effective_actor_role(
                ctx,
                conn,
                action="contract_runtime_recover",
                backlog_id=backlog_id,
                contract_execution_id=stale_execution_id,
                record=stale_record,
            )
            if _normalized_contract_runtime_action(locked_actor_role) != (
                "observer"
            ):
                raise PermissionDeniedError(
                    locked_actor_role or "anonymous",
                    "contract_runtime_recover",
                    {"required_role": "observer"},
                )
            dead_initial_join_authority = (
                _contract_runtime_dead_initial_join_recovery_authority(
                    conn,
                    project_id=project_id,
                    record=stale_record,
                )
            )
            actual_authority_hash = str(
                dead_initial_join_authority.get("authority_hash") or ""
            )
            if not (
                actual_authority_hash
                and requested_authority_hash
                and hmac.compare_digest(
                    actual_authority_hash,
                    requested_authority_hash,
                )
            ):
                raise ValidationError(
                    "runtime context recovery authority does not match "
                    "current durable state",
                    {
                        "contract_execution_id": stale_execution_id,
                        "fail_closed": True,
                        "zero_write": True,
                    },
                )
            recovery_execution_id = str(
                dead_initial_join_authority.get(
                    "recovery_contract_execution_id"
                )
                or ""
            )
            recovery_reason = "invalid_runtime_context_authority"

        historical_evidence = (
            _contract_runtime_stale_record_evidence_projection(stale_record)
        )
        current_repair_target = _contract_runtime_current_repair_target(
            stale_record
        )
        idempotent = False
        try:
            recovery_record = runtime.store.get(recovery_execution_id)
        except ContractRuntimeError:
            recovery_record = None
        if recovery_record is not None:
            recovery_metadata = (
                recovery_record.get("metadata")
                if isinstance(recovery_record.get("metadata"), Mapping)
                else {}
            )
            if str(
                recovery_metadata.get("stale_contract_execution_id") or ""
            ) != stale_execution_id:
                raise ValidationError(
                    "recovery execution id is bound to different stale history",
                    {
                        "recovery_contract_execution_id": recovery_execution_id,
                        "stale_contract_execution_id": stale_execution_id,
                    },
                )
            if recovery_reason == "invalid_runtime_context_authority" and (
                str(recovery_metadata.get("recovery_reason") or "")
                != recovery_reason
                or not hmac.compare_digest(
                    str(
                        recovery_metadata.get("recovery_authority_hash")
                        or ""
                    ),
                    requested_authority_hash,
                )
            ):
                raise ValidationError(
                    "recovery execution is bound to different runtime "
                    "authority",
                    {
                        "recovery_contract_execution_id": (
                            recovery_execution_id
                        ),
                        "stale_contract_execution_id": stale_execution_id,
                        "fail_closed": True,
                    },
                )
            persisted_target = recovery_metadata.get("current_repair_target")
            if (
                isinstance(persisted_target, Mapping)
                and persisted_target
                and dict(persisted_target) != current_repair_target
            ):
                raise ValidationError(
                    "recovery execution frozen repair target does not match "
                    "immutable stale history",
                    {
                        "recovery_contract_execution_id": recovery_execution_id,
                        "stale_contract_execution_id": stale_execution_id,
                        "fail_closed": True,
                    },
                )
            recovery_record = runtime.current_record(
                recovery_execution_id,
                actor_role=actor_role,
            )
            idempotent = True
        else:
            if recovery_reason == "invalid_runtime_context_authority":
                locked_authority = (
                    _contract_runtime_dead_initial_join_recovery_authority(
                        conn,
                        project_id=project_id,
                        record=stale_record,
                    )
                )
                if not hmac.compare_digest(
                    str(locked_authority.get("authority_hash") or ""),
                    requested_authority_hash,
                ):
                    raise ValidationError(
                        "runtime context recovery authority changed before "
                        "execution start",
                        {
                            "contract_execution_id": stale_execution_id,
                            "fail_closed": True,
                            "zero_write": True,
                        },
                    )
            backlog_lineage = dict(
                source_record.get("backlog_lineage")
                if isinstance(source_record.get("backlog_lineage"), Mapping)
                else {}
            )
            backlog_lineage.update(
                {
                    "stale_contract_execution_id": stale_execution_id,
                    "recovery_contract_execution_id": recovery_execution_id,
                    "recovery_policy": "start_new_execution",
                }
            )
            if current_repair_target:
                backlog_lineage["current_repair_target"] = (
                    current_repair_target
                )
            recovery_metadata = {
                "facade": "contract_runtime_recovery",
                "generic_crud_exposed": False,
                "recovery_policy": "start_new_execution",
                "recovery_reason": recovery_reason,
                "stale_contract_execution_id": stale_execution_id,
                "stale_completed_line_count": historical_evidence[
                    "completed_line_count"
                ],
                "stale_evidence_refs": historical_evidence[
                    "completed_line_refs"
                ],
                "historical_evidence_replayed": False,
                "authoritative_pass_synthesized": False,
            }
            if dead_initial_join_authority:
                recovery_metadata["recovery_authority_hash"] = str(
                    dead_initial_join_authority.get("authority_hash") or ""
                )
                recovery_metadata["recovery_authority"] = dict(
                    dead_initial_join_authority
                )
                backlog_lineage["recovery_authority_hash"] = str(
                    dead_initial_join_authority.get("authority_hash") or ""
                )
            if current_repair_target:
                recovery_metadata["current_repair_target"] = (
                    current_repair_target
                )
            try:
                recovery_record = runtime.start_execution(
                    str(source_record.get("contract_id") or ""),
                    project_id=project_id,
                    backlog_id=backlog_id,
                    actor_role=actor_role,
                    contract_execution_id=recovery_execution_id,
                    version=str(source_record.get("version") or "") or None,
                    revision=str(source_record.get("revision") or "") or None,
                    route_token_ref=route_token_ref,
                    parent_contract_execution_id=str(
                        source_record.get("parent_contract_execution_id") or ""
                    ),
                    root_contract_execution_id=str(
                        source_record.get("root_contract_execution_id") or ""
                    ),
                    contract_chain_id=str(
                        source_record.get("contract_chain_id") or ""
                    ),
                    role_binding=(
                        dict(source_record.get("role_binding") or {})
                        if isinstance(
                            source_record.get("role_binding"), Mapping
                        )
                        else {}
                    ),
                    backlog_lineage=backlog_lineage,
                    metadata=recovery_metadata,
                )
            except ContractRuntimeError as exc:
                if "contract execution already exists:" not in str(exc):
                    raise
                conn.rollback()
                recovery_record = runtime.store.get(recovery_execution_id)
                concurrent_metadata = (
                    recovery_record.get("metadata")
                    if isinstance(recovery_record.get("metadata"), Mapping)
                    else {}
                )
                if (
                    str(
                        concurrent_metadata.get(
                            "stale_contract_execution_id"
                        )
                        or ""
                    )
                    != stale_execution_id
                    or str(concurrent_metadata.get("recovery_reason") or "")
                    != recovery_reason
                    or (
                        recovery_reason
                        == "invalid_runtime_context_authority"
                        and not hmac.compare_digest(
                            str(
                                concurrent_metadata.get(
                                    "recovery_authority_hash"
                                )
                                or ""
                            ),
                            requested_authority_hash,
                        )
                    )
                ):
                    raise ValidationError(
                        "concurrent recovery execution is bound to different "
                        "authority",
                        {
                            "recovery_contract_execution_id": (
                                recovery_execution_id
                            ),
                            "fail_closed": True,
                        },
                    )
                idempotent = True
        recovery_record = runtime.current_record(
            recovery_execution_id,
            actor_role=actor_role,
        )
        conn.commit()

    response = _contract_runtime_response(
        recovery_record,
        actor_role=actor_role,
        request_id=ctx.request_id,
    )
    response.update(
        {
            "schema_version": "contract_runtime.recovery_response.v1",
            "status": "recovery_execution_started",
            "recovery_policy": "start_new_execution",
            "recovery_reason": recovery_reason,
            "stale_contract_execution_id": stale_execution_id,
            "recovery_contract_execution_id": recovery_execution_id,
            "idempotent": idempotent,
            "existing_record_preserved": True,
            "historical_evidence": historical_evidence,
            "historical_evidence_replayed": False,
            "authoritative_pass_synthesized": False,
            "agent_facing_decision_source": (
                "contract_runtime_stale_pinned_recovery"
            ),
        }
    )
    if current_repair_target:
        response["current_repair_target"] = current_repair_target
    if dead_initial_join_authority:
        response["recovery_authority_hash"] = str(
            dead_initial_join_authority.get("authority_hash") or ""
        )
    return response


@route("GET", "/api/projects/{project_id}/visualization/backlogs/{backlog_id}")
@_timeline_warm_cache_endpoint
def handle_project_contract_runtime_visualization(ctx: RequestContext):
    """Return the canonical public-safe visualization read model for one row."""

    project_id = ctx.get_project_id()
    backlog_id = str(ctx.path_params.get("backlog_id") or "").strip()
    if not backlog_id:
        raise ValidationError("backlog_id is required")
    try:
        limit = int(_first_query_value(ctx.query, "limit", "100") or "100")
    except (TypeError, ValueError):
        limit = 100
    limit = max(1, min(limit, 500))
    try:
        before_event_id = int(
            _first_query_value(ctx.query, "before_event_id", "0") or "0"
        )
    except (TypeError, ValueError):
        before_event_id = 0

    from . import task_timeline
    from .contract_runtime_visualization import (
        build_contract_runtime_visualization,
    )

    with DBContext(project_id) as conn:
        row = conn.execute(
            "SELECT * FROM backlog_bugs WHERE bug_id = ?",
            (backlog_id,),
        ).fetchone()
        if not row:
            raise GovernanceError("not_found", f"Bug {backlog_id} not found", 404)
        backlog = _backlog_compact_bug(row)
        if not backlog.get("public_safe", True):
            raise PermissionDeniedError(
                "anonymous",
                "read_private_contract_runtime_visualization",
                {
                    "backlog_id": backlog_id,
                    "public_safe": False,
                },
            )

        task_timeline.ensure_schema(conn)
        cache_query = dict(ctx.query or {})
        cache_query.update(
            {
                "view": str(
                    _first_query_value(ctx.query, "view") or "public"
                ).strip().lower(),
                "limit": str(limit),
                "before_event_id": str(before_event_id),
                "public_authority": "contract_runtime",
            }
        )
        cache_key, cache_watermark, cached_response, cache_metadata = (
            _timeline_warm_cache_prepare(
                conn,
                endpoint="contract_runtime_visualization",
                project_id=project_id,
                query=cache_query,
                resource_identity={
                    "backlog_id": backlog_id,
                    "contract_execution_id": _first_query_value(
                        ctx.query,
                        "contract_execution_id",
                    ),
                    "public_authority": "contract_runtime",
                },
            )
        )
        if cached_response is not None:
            cached_response["request_id"] = ctx.request_id
            return cached_response

        current = _contract_chain_current_projection(
            conn,
            project_id=project_id,
            backlog_id=backlog_id,
            rebuild_if_missing=False,
        )
        runtime_store = _contract_runtime_store(conn)
        records = runtime_store.list_by_backlog(
            project_id=project_id,
            backlog_id=backlog_id,
        )
        runtime_updated_at = {
            str(item["contract_execution_id"]): str(item["updated_at"] or "")
            for item in conn.execute(
                """
                SELECT contract_execution_id, updated_at
                FROM contract_runtime_executions
                WHERE project_id = ? AND backlog_id = ?
                """,
                (project_id, backlog_id),
            ).fetchall()
        }
        for record in records:
            record["updated_at"] = runtime_updated_at.get(
                str(record.get("contract_execution_id") or ""),
                "",
            )

        chain_edges = [
            dict(edge)
            for edge in conn.execute(
                """
                SELECT parent_contract_execution_id,
                       child_contract_execution_id,
                       edge_kind,
                       source_ref,
                       generation,
                       created_at
                FROM contract_chain_edges
                WHERE project_id = ? AND backlog_id = ?
                ORDER BY id
                """,
                (project_id, backlog_id),
            ).fetchall()
        ]
        event_where = "project_id = ? AND backlog_id = ?"
        event_params: list[Any] = [project_id, backlog_id]
        if before_event_id > 0:
            event_where += " AND id < ?"
            event_params.append(before_event_id)
        event_rows = conn.execute(
            f"""
            SELECT * FROM task_timeline_events
            WHERE {event_where}
            ORDER BY id DESC
            LIMIT ?
            """,
            (*event_params, limit + 1),
        ).fetchall()
        has_more = len(event_rows) > limit
        event_rows = event_rows[:limit]
        events = [task_timeline._row_to_dict(event) for event in event_rows]
        compact_events = [
            _task_timeline_recent_compact_event(
                event,
                task_timeline_module=task_timeline,
            )
            for event in events
        ]
        timeline_total = int(
            conn.execute(
                """
                SELECT COUNT(*) AS count
                FROM task_timeline_events
                WHERE project_id = ? AND backlog_id = ?
                """,
                (project_id, backlog_id),
            ).fetchone()["count"]
            or 0
        )
        event_ledger = task_timeline.build_compact_ledger(
            conn,
            project_id,
            events,
        )
        compact_row = next(
            (
                item
                for item in event_ledger.get("rows") or []
                if str(item.get("backlog_id") or "") == backlog_id
            ),
            {},
        )
        response = build_contract_runtime_visualization(
            project_id=project_id,
            backlog=backlog,
            runtime_records=records,
            chain_current=current,
            chain_edges=chain_edges,
            timeline_events=compact_events,
            legacy_compatibility_sources=events,
            compact_ledger_row=compact_row,
            timeline_total=timeline_total,
            timeline_limit=limit,
            timeline_has_more=has_more,
            next_cursor=(
                str(compact_events[-1].get("id") or "")
                if has_more and compact_events
                else ""
            ),
            generated_at=_utc_now(),
        )
    response["request_id"] = ctx.request_id
    return _timeline_warm_cache_store(
        cache_key,
        cache_watermark,
        response,
        cache_metadata,
    )


@route("POST", "/api/projects/{project_id}/contract-runtime/{contract_execution_id}/line-writes")
def handle_project_contract_runtime_line_write(ctx: RequestContext):
    """Submit one role-bound source-backed ContractRuntime line write."""
    project_id = ctx.get_project_id()
    contract_execution_id = str(ctx.path_params.get("contract_execution_id") or "").strip()
    if not contract_execution_id:
        raise ValidationError("contract_execution_id is required")
    body = dict(ctx.body or {})
    if str(body.get("line_id") or "").strip() == "worker_implementation":
        _runtime_context_require_worker_implementation_test_results(
            body,
            contract_execution_id=contract_execution_id,
            runtime_context_id=str(body.get("runtime_context_id") or "").strip(),
            task_id=str(body.get("task_id") or "").strip(),
            zero_db_access=True,
        )
    with DBContext(project_id) as conn:
        runtime = _contract_runtime(conn)
        record = runtime.store.get(contract_execution_id)
        request_execution_state_revision = int(
            record.get("execution_state_revision") or 0
        )
        request_total_changes_before = int(conn.total_changes)
        actor_role = ""
        try:
            actor_role = _contract_runtime_effective_actor_role(
                ctx,
                conn,
                action="contract_runtime_submit_line",
                backlog_id=str(record.get("backlog_id") or ""),
                contract_execution_id=contract_execution_id,
                record=record,
            )
            direct_crud_rejection = (
                _operator_supervised_direct_main_generic_crud_rejection(
                    record
                )
            )
            if direct_crud_rejection:
                result = direct_crud_rejection
            elif _onboard_service_record(record):
                record = _contract_runtime_read(
                    conn,
                    contract_execution_id=contract_execution_id,
                    actor_role=actor_role,
                )
                write = _contract_runtime_line_write_body(
                    record,
                    actor_role=actor_role,
                    body=body,
                    worker_proof=getattr(ctx, "_contract_runtime_mf_sub_proof", None),
                )
                result = _onboard_service_submit_line_write(
                    conn,
                    record=record,
                    write=write,
                    actor_role=actor_role,
                )
            else:
                record = runtime.current_record(
                    contract_execution_id,
                    actor_role=actor_role,
                )
                stored_record = record
                record, _dispatch_copy_projection = (
                    _contract_runtime_mf_parallel_dispatch_copy_safe_projection(
                        conn,
                        project_id=project_id,
                        record=record,
                    )
                )
                record, projection = (
                    _contract_runtime_apply_mf_parallel_context_projection(
                        conn,
                        project_id=project_id,
                        record=record,
                        actor_role=actor_role,
                    )
                )
                record = _contract_runtime_mf_parallel_atomic_lane_write_record(
                    runtime,
                    record=record,
                    source_record=stored_record,
                    projection=projection,
                    body=body,
                    actor_role=actor_role,
                    worker_proof=getattr(
                        ctx,
                        "_contract_runtime_mf_sub_proof",
                        None,
                    ),
                )
                write = _contract_runtime_line_write_body(
                    record,
                    actor_role=actor_role,
                    body=body,
                    worker_proof=getattr(ctx, "_contract_runtime_mf_sub_proof", None),
                )
                recovery_gate = (
                    _contract_runtime_same_lane_worker_commit_precheck(
                        stored_record=runtime.store.get(
                            contract_execution_id
                        ),
                        projected_record=record,
                        projection=projection,
                        write=write,
                        actor_role=actor_role,
                    )
                )
                if recovery_gate and not recovery_gate.get("ok"):
                    result = recovery_gate
                else:
                    write = _direct_fix_materialize_dispatch_runtime_context(
                        conn,
                        project_id=project_id,
                        record=record,
                        write=write,
                        request_id=ctx.request_id,
                    )
                    write = _contract_runtime_bind_server_line_authority(
                        ctx,
                        conn=conn,
                        project_id=project_id,
                        record=record,
                        write=write,
                        body=body,
                    )
                    prefill_plan_errors = (
                        _contract_runtime_mf_parallel_prefill_plan_write_errors(
                            stored_record,
                            write,
                        )
                    )
                    write, close_ready_binding_errors = (
                        _contract_runtime_bind_close_ready_worker_set(
                            conn,
                            project_id=project_id,
                            record=record,
                            write=write,
                        )
                    )
                    write, dispatch_errors = (
                        _contract_runtime_bind_mf_parallel_dispatch_authority(
                            conn,
                            project_id=project_id,
                            record=record,
                            write=write,
                        )
                    )
                    dispatch_errors = [
                        *prefill_plan_errors,
                        *close_ready_binding_errors,
                        *dispatch_errors,
                    ]
                    close_authority_precheck = (
                        _contract_runtime_mf_parallel_close_ready_precheck(
                            record,
                            write,
                            conn=conn,
                            project_id=project_id,
                        )
                    )
                    reconcile_idempotency = (
                        _contract_runtime_observer_reconcile_idempotency(
                            record=record,
                            write=write,
                            actor_role=actor_role,
                        )
                    )
                    reconcile_correction = (
                        _contract_runtime_reconcile_receipt_correction(
                            conn,
                            runtime=runtime,
                            project_id=project_id,
                            record=record,
                            write=write,
                            actor_role=actor_role,
                            mutate=True,
                        )
                    )
                    finish_attestation_facade_only = (
                        _contract_runtime_finish_attestation_facade_only_rejection(
                            record,
                            write,
                            actor_role=actor_role,
                        )
                    )
                    qa_missing_status = (
                        _contract_runtime_qa_missing_status_rejection(
                            record,
                            write,
                            actor_role=actor_role,
                        )
                    )
                    if reconcile_correction:
                        result = reconcile_correction
                    elif reconcile_idempotency:
                        result = reconcile_idempotency
                    elif dispatch_errors:
                        result = _contract_runtime_unchanged_line_rejection(
                            record,
                            dispatch_errors,
                        )
                    elif finish_attestation_facade_only:
                        result = finish_attestation_facade_only
                    elif qa_missing_status:
                        result = qa_missing_status
                    elif (
                        close_authority_precheck
                        and not close_authority_precheck.get("passed")
                    ):
                        missing = list(
                            close_authority_precheck.get(
                                "missing_requirement_ids"
                            )
                            or []
                        )
                        result = _contract_runtime_unchanged_line_rejection(
                            record,
                            [
                                "contract_runtime_close_authority_incomplete: "
                                + ", ".join(missing)
                            ],
                        )
                        result["close_authority_precheck"] = (
                            close_authority_precheck
                        )
                    else:
                        result = runtime.submit_line_write(
                            contract_execution_id,
                            write,
                            actor_role=actor_role,
                            projected_completed_lines=(
                                _contract_runtime_projection_completed_lines(
                                    projection
                                )
                            ),
                            projection=projection,
                        )
                    dispatch_timeline_event = (
                        _record_contract_runtime_mf_parallel_dispatch_event(
                            conn,
                            project_id=project_id,
                            record=record,
                            write=write,
                            result=result,
                            request_id=str(ctx.request_id),
                        )
                    )
        except ContractRetirementError as exc:
            return _contract_runtime_retirement_projection(
                exc,
                action="contract_runtime_submit_line",
                project_id=project_id,
                contract_execution_id=contract_execution_id,
                actor_role=actor_role,
            )
        except StalePinnedContractExecutionError as exc:
            stale_actor_role = actor_role or (
                "mf_sub"
                if _contract_runtime_mf_sub_proof_requested(ctx)
                else ""
            )
            response = _contract_runtime_stale_recovery_projection(
                exc,
                action="contract_runtime_submit_line",
                route_token_ref=_contract_runtime_ref_value(
                    ctx, "route_token_ref", "observer_route_token_ref"
                ),
                actor_role=stale_actor_role,
            )
            response["decision"] = {
                "ok": False,
                "errors": [str(exc)],
            }
            return response
        conn.commit()
        request_db_total_changes_delta = max(
            0, int(conn.total_changes) - request_total_changes_before
        )
        _publish_accepted_contract_runtime_line_write(
            project_id,
            result=result,
        )
    response = {
        "schema_version": "contract_runtime.line_write_response.v1",
        "ok": bool(result.get("ok")),
        "project_id": project_id,
        "contract_execution_id": contract_execution_id,
        "actor_role": actor_role,
        "decision": result.get("decision") or {},
        "agent_facing_decision_source": "contract_runtime_first_missing_line",
    }
    if isinstance(result.get("record"), Mapping):
        response.update(
            _contract_runtime_response(
                result["record"],
                actor_role=actor_role,
            )
        )
        response["ok"] = bool(result.get("ok"))
        response["decision"] = result.get("decision") or {}
        response["actor_role"] = actor_role
    if "dispatch_timeline_event" in locals() and dispatch_timeline_event:
        response["contract_runtime_dispatch_timeline_event"] = dispatch_timeline_event
    if isinstance(result.get("close_authority_precheck"), Mapping):
        response["close_authority_precheck"] = result[
            "close_authority_precheck"
        ]
    for field in (
        "error",
        "required_facade",
        "generic_contract_runtime_submit_line_allowed",
        "zero_write_rejection",
        "writes_performed",
    ):
        if field in result:
            response[field] = result[field]
    response.update(_contract_runtime_qa_rejection_response_fields(result))
    return _contract_runtime_bounded_line_write_response(
        response,
        record=(
            result.get("record")
            if isinstance(result.get("record"), Mapping)
            else None
        ),
        actor_role=actor_role,
        request_id=str(ctx.request_id),
        request_execution_state_revision=request_execution_state_revision,
        db_total_changes_delta=request_db_total_changes_delta,
    )


@route("POST", "/api/projects/{project_id}/contract-runtime/{contract_execution_id}/line-bypasses")
def handle_project_contract_runtime_line_bypass(ctx: RequestContext):
    """Waive one line, rooting or inheriting one no-PASS diagnostic generation."""

    from . import task_timeline

    project_id = ctx.get_project_id()
    execution_id = str(ctx.path_params.get("contract_execution_id") or "").strip()
    if not execution_id:
        raise ValidationError("contract_execution_id is required")
    body = dict(ctx.body or {})
    bypass_identity = str(body.get("bypass_identity") or "").strip()
    requested_diagnostic_id = str(
        body.get("diagnostic_backlog_id") or ""
    ).strip()

    with DBContext(project_id) as conn:
        runtime = _contract_runtime(conn)
        physical_dev = runtime.store.get_dev_direct_main_physical(execution_id)
        if physical_dev is not None and _runtime_plane() != "dev":
            raise GovernanceError(
                "historical_cross_world_contract_runtime_read_only",
                "historical dev Direct runtime evidence is local audit data only",
                409,
                {
                    "contract_execution_id": execution_id,
                    "project_id": project_id,
                    "zero_write_rejection": True,
                    "writes_performed": False,
                    "required_runtime_plane": "dev",
                },
            )
        record = runtime.store.get(execution_id)
        actor_role = _contract_runtime_effective_actor_role(
            ctx,
            conn,
            action="contract_runtime_bypass_line",
            backlog_id=str(record.get("backlog_id") or ""),
            contract_execution_id=execution_id,
            record=record,
        )
        try:
            # bypass_current_line owns the authoritative guide/precheck refresh.
            # Do not run the same guide path twice before the bypass can inspect
            # its current line; that creates a bootstrap deadlock when optional
            # guide enrichment is unavailable.
            record = runtime.store.get(execution_id)
            record, projection = _contract_runtime_apply_mf_parallel_context_projection(
                conn,
                project_id=project_id,
                record=record,
                actor_role=actor_role,
            )
            no_pass_generation = _contract_runtime_no_pass_generation(record)
            inherit_no_pass_generation = bool(
                no_pass_generation
                and not (
                    no_pass_generation.get("root_generation_persisted")
                    is not True
                    and str(body.get("line_id") or "").strip()
                    == "worker_commit"
                )
            )
            root_diagnostic_id = str(
                no_pass_generation.get("root_diagnostic_backlog_id") or ""
            ).strip()
            if inherit_no_pass_generation:
                if (
                    requested_diagnostic_id
                    and requested_diagnostic_id != root_diagnostic_id
                ):
                    raise ValidationError(
                        "active no-PASS generation requires its root diagnostic"
                    )
                diagnostic_id = root_diagnostic_id
            else:
                diagnostic_id = requested_diagnostic_id
                if not diagnostic_id and bypass_identity:
                    suffix = hashlib.sha256(
                        bypass_identity.encode("utf-8")
                    ).hexdigest()[:16]
                    diagnostic_id = (
                        f"AC-CONTRACT-LINE-BYPASS-{suffix.upper()}"
                    )
            body["diagnostic_backlog_id"] = diagnostic_id
            continuation_authority = {}
            if str(body.get("line_id") or "").strip() == "worker_commit":
                continuation_authority = (
                    _contract_runtime_worker_commit_bypass_continuation_authority(
                        conn,
                        project_id=project_id,
                        record=record,
                        request=body,
                    )
                )
                if not continuation_authority:
                    raise GovernanceError(
                        "contract_runtime_worker_commit_bypass_continuation_required",
                        (
                            "worker_commit bypass requires one server-verified current "
                            "implementation commit and clean runtime-context diff"
                        ),
                        422,
                        {
                            "contract_execution_id": execution_id,
                            "line_id": "worker_commit",
                            "no_pass_claim": True,
                            "fail_closed": True,
                        },
                    )
            result = runtime.bypass_current_line(
                execution_id,
                {
                    "bypass_identity": bypass_identity,
                    "stage_id": body.get("stage_id"),
                    "line_id": body.get("line_id"),
                    "execution_state_revision": body.get("execution_state_revision"),
                    "runtime_guide_hash": body.get("runtime_guide_hash"),
                    "diagnostic_backlog_id": diagnostic_id,
                    "classification": body.get("classification"),
                    "reason": body.get("reason"),
                    "decision": body.get("decision"),
                    "evidence_refs": body.get("evidence_refs") or [],
                    "continuation_authority": continuation_authority,
                },
                actor_role=actor_role,
                projected_completed_lines=(
                    _contract_runtime_projection_completed_lines(projection)
                ),
                projection=projection,
            )
        except ContractRetirementError as exc:
            return _contract_runtime_retirement_projection(
                exc,
                action="contract_runtime_bypass_line",
                project_id=project_id,
                contract_execution_id=execution_id,
                actor_role=actor_role,
            )
        except StalePinnedContractExecutionError as exc:
            return _contract_runtime_stale_recovery_projection(
                exc,
                action="contract_runtime_bypass_line",
                route_token_ref=_contract_runtime_ref_value(
                    ctx, "route_token_ref", "observer_route_token_ref"
                ),
                actor_role=actor_role,
            )
        if not result.get("ok"):
            conn.rollback()
            return {
                "schema_version": "contract_runtime.line_bypass_response.v1",
                "ok": False,
                "project_id": project_id,
                "contract_execution_id": execution_id,
                "actor_role": actor_role,
                "diagnostic_backlog_id": str(
                    body.get("diagnostic_backlog_id") or ""
                ),
                "decision": result.get("decision") or {},
            }

        timeline_events: list[dict[str, Any]] = []
        if not result.get("idempotent"):
            diagnostic_id = str(
                body.get("diagnostic_backlog_id") or ""
            ).strip()
            source_id = str(record.get("backlog_id") or "").strip()
            source = conn.execute(
                "SELECT * FROM backlog_bugs WHERE bug_id = ?", (source_id,)
            ).fetchone()
            if not source:
                raise ValidationError(f"source backlog row not found: {source_id}")
            existing = conn.execute(
                "SELECT * FROM backlog_bugs WHERE bug_id = ?", (diagnostic_id,)
            ).fetchone()
            written_line = (
                result.get("written_line")
                if isinstance(result.get("written_line"), Mapping)
                else {}
            )
            written_payload = (
                written_line.get("payload")
                if isinstance(written_line.get("payload"), Mapping)
                else {}
            )
            generation_link = (
                written_payload.get("no_pass_generation")
                if isinstance(
                    written_payload.get("no_pass_generation"), Mapping
                )
                else {}
            )
            inherited_generation = bool(
                str(generation_link.get("role") or "").strip()
                == "inherited_gate"
            )
            link = {
                "source_backlog_id": source_id,
                "contract_execution_id": execution_id,
                "line_id": str(body.get("line_id") or ""),
                "execution_state_revision": int(body.get("execution_state_revision") or 0),
                "bypass_identity": bypass_identity,
                "classification": str(body.get("classification") or ""),
                "reason_code": str(body.get("classification") or ""),
                "reason": str(body.get("reason") or ""),
                "disposition": "proceeded_with_exception",
                "no_pass_claim": True,
            }
            if generation_link:
                link.update(
                    {
                        "no_pass_generation_id": str(
                            generation_link.get("generation_id") or ""
                        ),
                        "no_pass_generation_role": str(
                            generation_link.get("role") or ""
                        ),
                        "root_bypass_identity": str(
                            generation_link.get("root_bypass_identity") or ""
                        ),
                        "root_diagnostic_backlog_id": str(
                            generation_link.get(
                                "root_diagnostic_backlog_id"
                            )
                            or ""
                        ),
                        "root_line_id": str(
                            generation_link.get("root_line_id") or ""
                        ),
                        "diagnostic_created": not inherited_generation,
                        "authoritative_pass_synthesized": False,
                    }
                )
            if existing:
                prior = backlog_runtime.parse_json_object(existing["chain_trigger_json"])
                expected_line_id = (
                    str(generation_link.get("root_line_id") or "").strip()
                    if inherited_generation
                    else str(link.get("line_id") or "").strip()
                )
                if (
                    existing["status"] != "OPEN"
                    or str(prior.get("source_backlog_id") or "")
                    != source_id
                    or str(prior.get("contract_execution_id") or "")
                    != execution_id
                    or str(prior.get("line_id") or "")
                    != expected_line_id
                ):
                    raise ValidationError(
                        "diagnostic_backlog_id is not the matching OPEN bypass row"
                    )
            else:
                if inherited_generation:
                    raise ValidationError(
                        "active no-PASS generation root diagnostic is missing"
                    )
                now = _utc_now()
                target_files = str(source["target_files"] or "[]")
                test_files = str(source["test_files"] or "[]")
                conn.execute(
                    """INSERT INTO backlog_bugs
                       (bug_id, title, status, priority, target_files, test_files,
                        acceptance_criteria, details_md, chain_trigger_json,
                        provenance_paths, bypass_policy_json, mf_type, created_at, updated_at)
                       VALUES (?, ?, 'OPEN', ?, ?, ?, ?, ?, ?, ?, ?, 'chain_rescue', ?, ?)""",
                    (
                        diagnostic_id,
                        f"ContractRuntime bypass diagnostic: {link['line_id']}",
                        str(body.get("diagnostic_priority") or "P1"),
                        target_files,
                        test_files,
                        json.dumps([
                            "Repair the blocked line without relying on this bypass.",
                            "Keep source and diagnostic timeline linkage durable.",
                        ]),
                        str(body.get("reason") or ""),
                        json.dumps(link),
                        json.dumps([
                            f"backlog:{source_id}",
                            f"contract-runtime:{execution_id}",
                        ]),
                        json.dumps({**link, "keep_open": True}),
                        now,
                        now,
                    ),
                )
            event_payload = {**link, "diagnostic_backlog_id": diagnostic_id}
            event_payload["request_hash"] = str(
                written_payload.get("request_hash") or ""
            ).strip()
            event_payload["evidence_refs"] = list(
                written_payload.get("evidence_refs") or []
            )
            common = {
                "project_id": project_id,
                "task_id": str(body.get("task_id") or execution_id),
                "correlation_id": f"contract-line-bypass:{bypass_identity}",
                "phase": str(body.get("phase") or "contract_runtime_bypass"),
                "event_kind": "record_blocker",
                "actor": actor_role,
                "commit_sha": str(body.get("commit_sha") or ""),
                "payload": event_payload,
            }
            timeline_events.append(task_timeline.record_event(
                conn,
                backlog_id=source_id,
                event_type="contract_line_bypass",
                status="proceeded_with_exception",
                decision=(
                    "inherited_root_diagnostic_no_pass"
                    if inherited_generation
                    else "linked_open_diagnostic_no_pass"
                ),
                **common,
            ))
            timeline_events.append(task_timeline.record_event(
                conn,
                backlog_id=diagnostic_id,
                event_type="contract_line_bypass_diagnostic_linked",
                status="open",
                decision=(
                    "record_inherited_gate_reason_keep_root_open"
                    if inherited_generation
                    else "keep_open_until_block_repaired"
                ),
                **common,
            ))

    _onboard_guide_capsule_invalidate_contract_runtime_transition(
        project_id=project_id,
        result=result,
    )
    response = {
        "schema_version": "contract_runtime.line_bypass_response.v1",
        "ok": True,
        "project_id": project_id,
        "contract_execution_id": execution_id,
        "actor_role": actor_role,
        "idempotent": bool(result.get("idempotent")),
        "diagnostic_backlog_id": str(
            body.get("diagnostic_backlog_id") or ""
        ),
        "diagnostic_status": "OPEN",
        "decision": result.get("decision") or {},
        "written_line": result.get("written_line") or {},
        "timeline_events": timeline_events,
    }
    written_payload = (
        response["written_line"].get("payload")
        if isinstance(response.get("written_line"), Mapping)
        and isinstance(response["written_line"].get("payload"), Mapping)
        else {}
    )
    if isinstance(written_payload.get("no_pass_generation"), Mapping):
        response["no_pass_generation"] = dict(
            written_payload["no_pass_generation"]
        )
    if isinstance(result.get("record"), Mapping):
        response.update(
            _contract_runtime_response(
                result["record"],
                actor_role=actor_role,
            )
        )
        response["schema_version"] = "contract_runtime.line_bypass_response.v1"
    return response


@route("POST", "/api/projects/{project_id}/contract-runtime/{contract_execution_id}/line-writes/precheck")
def handle_project_contract_runtime_line_write_precheck(ctx: RequestContext):
    """Precheck one role-bound ContractRuntime line write without appending evidence."""
    project_id = ctx.get_project_id()
    contract_execution_id = str(ctx.path_params.get("contract_execution_id") or "").strip()
    if not contract_execution_id:
        raise ValidationError("contract_execution_id is required")
    body = dict(ctx.body or {})
    if str(body.get("line_id") or "").strip() == "worker_implementation":
        _runtime_context_require_worker_implementation_test_results(
            body,
            contract_execution_id=contract_execution_id,
            runtime_context_id=str(body.get("runtime_context_id") or "").strip(),
            task_id=str(body.get("task_id") or "").strip(),
            zero_db_access=True,
        )
    with DBContext(project_id) as conn:
        runtime = _contract_runtime(conn)
        record = runtime.store.get(contract_execution_id)
        actor_role = ""
        try:
            actor_role = _contract_runtime_effective_actor_role(
                ctx,
                conn,
                action="contract_runtime_submit_line",
                backlog_id=str(record.get("backlog_id") or ""),
                contract_execution_id=contract_execution_id,
                record=record,
            )
            direct_crud_rejection = (
                _operator_supervised_direct_main_generic_crud_rejection(
                    record
                )
            )
            if direct_crud_rejection:
                result = direct_crud_rejection
            elif _onboard_service_record(record):
                record = _contract_runtime_read(
                    conn,
                    contract_execution_id=contract_execution_id,
                    actor_role=actor_role,
                )
                write = _contract_runtime_line_write_body(
                    record,
                    actor_role=actor_role,
                    body=body,
                    worker_proof=getattr(ctx, "_contract_runtime_mf_sub_proof", None),
                )
                result = _onboard_service_submit_line_write(
                    conn,
                    record=record,
                    write=write,
                    actor_role=actor_role,
                    mutate=False,
                )
            else:
                record = runtime.current_record(
                    contract_execution_id,
                    actor_role=actor_role,
                )
                stored_record = record
                record, _dispatch_copy_projection = (
                    _contract_runtime_mf_parallel_dispatch_copy_safe_projection(
                        conn,
                        project_id=project_id,
                        record=record,
                    )
                )
                record, projection = (
                    _contract_runtime_apply_mf_parallel_context_projection(
                        conn,
                        project_id=project_id,
                        record=record,
                        actor_role=actor_role,
                    )
                )
                record = _contract_runtime_mf_parallel_atomic_lane_write_record(
                    runtime,
                    record=record,
                    source_record=stored_record,
                    projection=projection,
                    body=body,
                    actor_role=actor_role,
                    worker_proof=getattr(
                        ctx,
                        "_contract_runtime_mf_sub_proof",
                        None,
                    ),
                )
                write = _contract_runtime_line_write_body(
                    record,
                    actor_role=actor_role,
                    body=body,
                    worker_proof=getattr(ctx, "_contract_runtime_mf_sub_proof", None),
                )
                recovery_gate = (
                    _contract_runtime_same_lane_worker_commit_precheck(
                        stored_record=stored_record,
                        projected_record=record,
                        projection=projection,
                        write=write,
                        actor_role=actor_role,
                    )
                )
                if recovery_gate and not recovery_gate.get("ok"):
                    result = recovery_gate
                else:
                    write = _contract_runtime_bind_server_line_authority(
                        ctx,
                        conn,
                        project_id=project_id,
                        record=record,
                        write=write,
                        body=body,
                    )
                    prefill_plan_errors = (
                        _contract_runtime_mf_parallel_prefill_plan_write_errors(
                            stored_record,
                            write,
                        )
                    )
                    write, close_ready_binding_errors = (
                        _contract_runtime_bind_close_ready_worker_set(
                            conn,
                            project_id=project_id,
                            record=record,
                            write=write,
                        )
                    )
                    write, dispatch_errors = (
                        _contract_runtime_bind_mf_parallel_dispatch_authority(
                            conn,
                            project_id=project_id,
                            record=record,
                            write=write,
                        )
                    )
                    dispatch_errors = [
                        *prefill_plan_errors,
                        *close_ready_binding_errors,
                        *dispatch_errors,
                    ]
                    close_authority_precheck = (
                        _contract_runtime_mf_parallel_close_ready_precheck(
                            record,
                            write,
                            conn=conn,
                            project_id=project_id,
                        )
                    )
                    reconcile_idempotency = (
                        _contract_runtime_observer_reconcile_idempotency(
                            record=record,
                            write=write,
                            actor_role=actor_role,
                        )
                    )
                    reconcile_correction = (
                        _contract_runtime_reconcile_receipt_correction(
                            conn,
                            runtime=runtime,
                            project_id=project_id,
                            record=record,
                            write=write,
                            actor_role=actor_role,
                            mutate=False,
                        )
                    )
                    finish_attestation_facade_only = (
                        _contract_runtime_finish_attestation_facade_only_rejection(
                            record,
                            write,
                            actor_role=actor_role,
                        )
                    )
                    qa_missing_status = (
                        _contract_runtime_qa_missing_status_rejection(
                            record,
                            write,
                            actor_role=actor_role,
                        )
                    )
                    if reconcile_correction:
                        result = reconcile_correction
                    elif reconcile_idempotency:
                        result = reconcile_idempotency
                    elif dispatch_errors:
                        result = _contract_runtime_unchanged_line_rejection(
                            record,
                            dispatch_errors,
                        )
                    elif finish_attestation_facade_only:
                        result = finish_attestation_facade_only
                    elif qa_missing_status:
                        result = qa_missing_status
                    elif (
                        close_authority_precheck
                        and not close_authority_precheck.get("passed")
                    ):
                        missing = list(
                            close_authority_precheck.get(
                                "missing_requirement_ids"
                            )
                            or []
                        )
                        result = _contract_runtime_unchanged_line_rejection(
                            record,
                            [
                                "contract_runtime_close_authority_incomplete: "
                                + ", ".join(missing)
                            ],
                        )
                        result["close_authority_precheck"] = (
                            close_authority_precheck
                        )
                    else:
                        result = recovery_gate
                        if not result:
                            result = runtime.precheck_line_write(
                                contract_execution_id,
                                write,
                                actor_role=actor_role,
                                projected_completed_lines=(
                                    _contract_runtime_projection_completed_lines(
                                        projection
                                    )
                                ),
                                projection=projection,
                            )
        except ContractRetirementError as exc:
            return _contract_runtime_retirement_projection(
                exc,
                action="contract_runtime_precheck_line",
                project_id=project_id,
                contract_execution_id=contract_execution_id,
                actor_role=actor_role,
            )
        except StalePinnedContractExecutionError as exc:
            stale_actor_role = actor_role or (
                "mf_sub"
                if _contract_runtime_mf_sub_proof_requested(ctx)
                else ""
            )
            response = _contract_runtime_stale_recovery_projection(
                exc,
                action="contract_runtime_submit_line",
                route_token_ref=_contract_runtime_ref_value(
                    ctx, "route_token_ref", "observer_route_token_ref"
                ),
                actor_role=stale_actor_role,
            )
            response["decision"] = {
                "ok": False,
                "errors": [str(exc)],
            }
            return response
        conn.commit()
    response = {
        "schema_version": "contract_runtime.line_write_precheck_response.v1",
        "ok": bool(result.get("ok")),
        "project_id": project_id,
        "contract_execution_id": contract_execution_id,
        "actor_role": actor_role,
        "decision": result.get("decision") or {},
        "would_mutate_completed_lines": False,
        "completed_lines_count": result.get("completed_lines_count"),
        "execution_state_revision": result.get("execution_state_revision"),
        "runtime_guide_hash": result.get("runtime_guide_hash"),
        "agent_facing_decision_source": "contract_runtime_line_write_precheck",
    }
    if isinstance(result.get("record"), Mapping):
        response.update(
            _contract_runtime_response(
                result["record"],
                actor_role=actor_role,
            )
        )
        response["schema_version"] = "contract_runtime.line_write_precheck_response.v1"
        response["ok"] = bool(result.get("ok"))
        response["decision"] = result.get("decision") or {}
        response["actor_role"] = actor_role
        response["would_mutate_completed_lines"] = False
        response["completed_lines_count"] = result.get("completed_lines_count")
        response["execution_state_revision"] = result.get("execution_state_revision")
        response["runtime_guide_hash"] = result.get("runtime_guide_hash")
        response["agent_facing_decision_source"] = "contract_runtime_line_write_precheck"
    if isinstance(result.get("close_authority_precheck"), Mapping):
        response["close_authority_precheck"] = result[
            "close_authority_precheck"
        ]
    for field in (
        "error",
        "required_facade",
        "generic_contract_runtime_submit_line_allowed",
        "zero_write_rejection",
        "writes_performed",
    ):
        if field in result:
            response[field] = result[field]
    response.update(_contract_runtime_qa_rejection_response_fields(result))
    return response


@route("GET", "/api/projects/{project_id}/hotfix/usage")
def handle_project_hotfix_usage(ctx: RequestContext):
    """Return audit-only HOTFIX entry and under_hotfix timeline usage."""
    project_id = ctx.get_project_id()
    try:
        limit = int(_first_query_value(ctx.query, "limit", "1000") or 1000)
    except (TypeError, ValueError):
        limit = 1000
    from . import task_timeline

    with DBContext(project_id) as conn:
        events = task_timeline.list_events(conn, project_id, limit=limit)
    hotfix_entered = [
        event for event in events
        if str(event.get("event_kind") or "") == "hotfix_entered"
        or str(event.get("event_type") or "") == "hotfix.entered"
    ]
    under_hotfix_events = [
        event for event in events
        if any(
            _contains_under_hotfix(event.get(key))
            for key in ("payload", "verification", "artifact_refs")
        )
    ]
    usage_events = []
    seen: set[int] = set()
    for event in [*hotfix_entered, *under_hotfix_events]:
        event_id = int(event.get("id") or 0)
        if event_id in seen:
            continue
        seen.add(event_id)
        usage_events.append(event)
    return {
        "ok": True,
        "project_id": project_id,
        "profile": "HOTFIX",
        "hotfix_entered": hotfix_entered,
        "under_hotfix_events": under_hotfix_events,
        "events": usage_events,
        "count": len(usage_events),
    }


@route("POST", "/api/backlog/{project_id}/{bug_id}/close")
def handle_backlog_close(ctx: RequestContext):
    """Close a backlog bug: set status=FIXED, commit, fixed_at."""
    pid = ctx.path_params["project_id"]
    bug_id = ctx.path_params["bug_id"]
    body = ctx.body
    now = _utc_now()
    conn = get_connection(pid)
    try:
        row = conn.execute(
            "SELECT * FROM backlog_bugs WHERE bug_id = ?",
            (bug_id,),
        ).fetchone()
        if not row:
            raise GovernanceError("not_found", f"Bug {bug_id} not found", 404)

        prior_status = row["status"]

        # Allow closing from OPEN or MF_IN_PROGRESS
        if prior_status not in ("OPEN", "MF_IN_PROGRESS"):
            raise GovernanceError(
                "invalid_status",
                f"Bug must be OPEN or MF_IN_PROGRESS to close, currently: {prior_status}",
                422,
            )

        # Verify commit SHA exists in the target project git log (best-effort).
        commit_verification_root = project_service.resolve_project_root(
            pid,
            fallback_self=True,
        )
        commit_sha = body.get("commit", "")
        if commit_sha:
            try:
                result = subprocess.run(
                    ["git", "rev-parse", "--verify", commit_sha],
                    capture_output=True,
                    text=True,
                    timeout=10,
                    cwd=commit_verification_root,
                )
                if result.returncode != 0:
                    raise GovernanceError(
                        "commit_not_found",
                        f"Commit {commit_sha} does not resolve to a real commit",
                        422,
                        {
                            "commit": commit_sha,
                            "project_id": pid,
                            "commit_verification_root": (
                                str(commit_verification_root)
                                if commit_verification_root
                                else ""
                            ),
                        },
                    )
            except subprocess.TimeoutExpired:
                log.warning("git rev-parse timed out for commit %s; allowing close", commit_sha)
            except FileNotFoundError:
                log.warning("git not found; skipping commit verification for %s", commit_sha)

        route_gate = _require_route_token_mutation_gate(
            ctx,
            action="backlog_close",
            backlog_id=bug_id,
        )
        materialized_qa_lane = conn.execute(
            """
            SELECT COUNT(*) AS event_count, COALESCE(MAX(id), 0) AS latest_event_id
            FROM task_timeline_events
            WHERE project_id = ? AND backlog_id = ?
              AND json_extract(payload_json, '$.schema_version') = ?
              AND json_extract(
                    payload_json,
                    '$.qa_evidence_provenance.authorization_source'
                  ) = 'qa_session_token_ref'
            """,
            (pid, bug_id, "independent_qa_verification.v1"),
        ).fetchone()
        timeline_gate = None
        if materialized_qa_lane and int(materialized_qa_lane["event_count"] or 0):
            try:
                timeline_gate = _verify_mf_close_timeline_gate(
                    conn, pid, bug_id, row, body, route_gate=route_gate
                )
            except GovernanceError as exc:
                raise GovernanceError(
                    exc.code,
                    "ContractRuntime close authority rejected the materialized QA lane",
                    exc.status,
                    {
                        "schema_version": "backlog_close.materialized_qa_rejection.v1",
                        "passed": False,
                        "event_count": int(materialized_qa_lane["event_count"]),
                        "latest_event_id": int(materialized_qa_lane["latest_event_id"]),
                        "zero_write_rejection": True,
                    },
                ) from exc
        hotfix_audit_event = _record_hotfix_backlog_close_tag(
            conn,
            project_id=pid,
            bug_id=bug_id,
            body=body,
            commit_sha=commit_sha,
        )
        route_action_precheck_event = _record_backlog_close_route_action_precheck_event(
            conn,
            project_id=pid,
            backlog_id=bug_id,
            body=body,
            route_gate=route_gate,
            commit_sha=commit_sha,
        )
        try:
            if timeline_gate is None:
                timeline_gate = _verify_mf_close_timeline_gate(
                    conn, pid, bug_id, row, body, route_gate=route_gate
                )
        except GovernanceError as exc:
            blocked_event = _record_backlog_close_blocked_event(
                conn,
                project_id=pid,
                backlog_id=bug_id,
                row=row,
                body=body,
                route_gate=route_gate,
                gate_error=exc,
                route_action_precheck_event=route_action_precheck_event,
                commit_sha=commit_sha,
            )
            if blocked_event:
                conn.commit()
            raise
        identity_block = _backlog_close_route_waiver_identity_block(
            route_gate,
            timeline_gate,
            body,
        )
        if identity_block:
            from .mf_subagent_contract import route_token_required_failure_details

            raise GovernanceError(
                "route_token_required",
                (
                    "route_waiver route identity does not match selected "
                    "MF close timeline route-context evidence"
                ),
                422,
                route_token_required_failure_details(
                    action="backlog_close",
                    reason=(
                        "route_waiver route identity does not match selected "
                        "MF close timeline route-context evidence"
                    ),
                    extra=identity_block,
                ),
            )
        _record_route_token_gate_event(
            conn,
            pid,
            route_gate,
            backlog_id=bug_id,
            commit_sha=commit_sha,
        )
        close_impact_check = _build_backlog_close_impact_check(conn, pid, body)
        from .parallel_branch_runtime import (
            INTEGRATION_EPOCH_RECONCILED,
            IntegrationEpochFrozenError,
            integration_epoch_to_dict,
            resolve_active_integration_epoch_for_backlog,
            validate_integration_epoch_backlog_close,
        )

        resolved_integration_epoch, integration_backlog_scope = (
            resolve_active_integration_epoch_for_backlog(conn, pid, bug_id)
        )
        integration_epoch_close_gate: dict[str, Any] = {}
        if resolved_integration_epoch is not None:
            try:
                integration_epoch_close_gate = validate_integration_epoch_backlog_close(
                    resolved_integration_epoch,
                    backlog_scope=integration_backlog_scope,
                    target_head_commit=commit_sha,
                )
            except IntegrationEpochFrozenError as exc:
                raise GovernanceError(
                    "integration_epoch_final_barrier_not_satisfied",
                    str(exc),
                    409,
                    {
                        "integration_epoch": integration_epoch_to_dict(exc.epoch),
                        "required_status": INTEGRATION_EPOCH_RECONCILED,
                        "required_target_head": exc.epoch.current_head,
                        "backlog_scope": integration_backlog_scope,
                    },
                ) from exc
        # Determine chain_stage based on prior status
        chain_stage = "manual-fix" if prior_status == "MF_IN_PROGRESS" else None

        update_sql = """UPDATE backlog_bugs
               SET status = 'FIXED',
                   "commit" = ?,
                   fixed_at = ?,
                   updated_at = ?"""
        params = [commit_sha, now, now]

        if chain_stage:
            update_sql += """,
                   chain_stage = ?"""
            params.append(chain_stage)

        update_sql += """
               WHERE bug_id = ?"""
        params.append(bug_id)

        conn.execute(update_sql, params)
        backlog_runtime.update_backlog_runtime(
            conn,
            bug_id,
            "manual_fix" if prior_status == "MF_IN_PROGRESS" else "fixed",
            project_id=pid,
            result={
                "commit": commit_sha,
                "route_token_gate": route_gate,
                "commit_verification_root": (
                    str(commit_verification_root)
                    if commit_verification_root
                    else ""
                ),
            },
            runtime_state="fixed",
        )
        _publish_current_task_changed(
            pid,
            backlog_id=bug_id,
            task_id=str(_row_get(row, "current_task_id", "")),
            source="backlog.close",
            runtime_state="fixed",
        )
        conn.commit()
        # Audit: backlog_close event
        try:
            audit_service.record(
                conn, pid, "backlog_close",
                actor=body.get("actor", "auto-chain"),
                bug_id=bug_id,
            )
            conn.commit()
        except Exception:
            pass  # best-effort audit
        result = {"ok": True, "bug_id": bug_id, "status": "FIXED", "fixed_at": now}
        if chain_stage:
            result["chain_stage"] = chain_stage
        if timeline_gate:
            # AC2: Return compact gate summary instead of the full timeline_gate tree.
            # Close DECISION logic above is byte-identical; only response payload shrinks.
            # Callers needing the full tree can call precheck(view=full).
            from . import task_timeline as _tl
            result["gate_summary"] = _tl.compact_gate_summary(
                {**timeline_gate, "bug_id": bug_id},
                request_id=str(ctx.request_id),
            )
        result["route_token_gate"] = route_gate
        if hotfix_audit_event:
            result["hotfix_audit_event"] = hotfix_audit_event
        if close_impact_check:
            result["close_impact_check"] = close_impact_check
        response_epoch = resolved_integration_epoch
        if response_epoch is not None:
            from .parallel_branch_runtime import integration_epoch_to_dict

            result["integration_epoch"] = integration_epoch_to_dict(
                response_epoch
            )
            result["integration_backlog_scope"] = integration_backlog_scope
            result["integration_epoch_close_gate"] = integration_epoch_close_gate
            result["child_close_preserved_epoch_freeze"] = (
                bool(integration_epoch_close_gate.get("preserve_epoch_freeze"))
            )
        return result
    finally:
        conn.close()


def _audit_recovery_route_refs(route_gate: Mapping[str, Any], body: Mapping[str, Any]) -> list[str]:
    refs: list[str] = []
    for value in body.get("references") or []:
        if isinstance(value, str):
            refs.append(value)
    for value in body.get("evidence_refs") or []:
        if isinstance(value, str):
            refs.append(value)
    for value in route_gate.get("evidence_refs") or []:
        if isinstance(value, str):
            refs.append(value)
    return refs


def _audit_recovery_root_ids(route_gate: Mapping[str, Any], body: Mapping[str, Any]) -> list[str]:
    roots: list[str] = []
    for key in (
        "audit_archive_backlog_id",
        "root_backlog_id",
        "source_backlog_id",
        "archived_backlog_id",
    ):
        value = str(body.get(key) or "").strip()
        if value:
            roots.append(value)
    for ref in _audit_recovery_route_refs(route_gate, body):
        if ref.startswith("audit_archive:"):
            roots.append(ref.split(":", 1)[1].strip())
    return [item for item in dict.fromkeys(roots) if item]


def _audit_recovery_close_commit(row, body: Mapping[str, Any]) -> str:
    for key in ("commit", "commit_sha", "close_commit", "head_commit", "target_head_commit"):
        value = str(body.get(key) or "").strip()
        if value:
            return value
    for key in ("commit", "commit_sha", "close_commit", "head_commit", "target_head_commit"):
        value = str(_row_get(row, key, "") or "").strip()
        if value:
            return value
    return ""


def _passed_audit_recovery_qa_events(events: list[dict], close_commit: str) -> list[dict]:
    passed: list[dict] = []
    for event in events:
        kind = str(event.get("event_kind") or "").strip()
        if kind not in {"independent_verification", "qa_verification"}:
            continue
        status = str(event.get("status") or event.get("decision") or "").strip().lower()
        if status not in {"pass", "passed", "accepted", "approved", "pass_with_followups"}:
            continue
        event_commit = str(event.get("commit_sha") or "").strip()
        if close_commit and event_commit and event_commit != close_commit:
            continue
        passed.append(event)
    return passed


def _verify_audit_recovery_close_gate(
    conn,
    project_id: str,
    bug_id: str,
    row,
    body: dict,
    *,
    route_gate: Mapping[str, Any],
) -> dict:
    from . import task_timeline

    close_commit = _audit_recovery_close_commit(row, body)
    root_ids = _audit_recovery_root_ids(route_gate, body)
    events = task_timeline.list_events(conn, project_id, backlog_id=bug_id, limit=1000)
    qa_events = _passed_audit_recovery_qa_events(events, close_commit)
    accepted_archives: list[dict] = []
    rejected_archives: list[dict] = []
    missing: list[str] = []

    if not close_commit:
        missing.append("close_commit")
    if not root_ids:
        missing.append("audit_archive_reference")

    for root_id in root_ids:
        root_row = conn.execute(
            "SELECT * FROM backlog_bugs WHERE bug_id = ?",
            (root_id,),
        ).fetchone()
        if not root_row:
            rejected_archives.append({"bug_id": root_id, "reason": "not_found"})
            continue
        audit_archive = _backlog_row_audit_archive(root_row)
        audit_close_gate = _json_object_field(audit_archive.get("audit_close_gate"))
        qa_acceptance = _json_object_field(audit_archive.get("qa_acceptance"))
        archive_commit = str(audit_archive.get("implementation_commit") or "").strip()
        root_status = str(_row_get(root_row, "status", "") or "").strip()
        archive_ok = (
            root_status == "WAIVED"
            and str(audit_archive.get("status") or "") == "audit_archived"
            and bool(audit_close_gate.get("passed"))
            and _qa_acceptance_passed(qa_acceptance)
            and (not close_commit or not archive_commit or archive_commit == close_commit)
        )
        archive_summary = {
            "bug_id": root_id,
            "row_status": root_status,
            "audit_archive_status": str(audit_archive.get("status") or ""),
            "audit_close_gate_passed": bool(audit_close_gate.get("passed")),
            "qa_acceptance_passed": _qa_acceptance_passed(qa_acceptance),
            "implementation_commit": archive_commit,
        }
        if archive_ok:
            accepted_archives.append(archive_summary)
        else:
            if close_commit and archive_commit and archive_commit != close_commit:
                archive_summary["reason"] = "implementation_commit_mismatch"
            else:
                archive_summary["reason"] = "audit_archive_not_accepted"
            rejected_archives.append(archive_summary)

    if not accepted_archives:
        missing.append("accepted_audit_archive")
    if not qa_events:
        missing.append("independent_qa_evidence")

    passed = not missing
    verification = {
        "schema_version": "audit_recovery_close_gate.v1",
        "passed": passed,
        "can_close": passed,
        "status": "passed" if passed else "failed",
        "applicable": True,
        "audit_recovery": True,
        "bug_id": bug_id,
        "close_commit": close_commit,
        "required_event_kinds": ["independent_verification"],
        "present_event_kinds": ["independent_verification"] if qa_events else [],
        "missing_event_kinds": [] if qa_events else ["independent_verification"],
        "missing_requirement_ids": missing,
        "accepted_audit_archives": accepted_archives,
        "rejected_audit_archives": rejected_archives,
        "qa_event_ids": [event.get("id") for event in qa_events if event.get("id")],
        "route_token_gate": {
            "status": route_gate.get("status"),
            "action": route_gate.get("action"),
            "route_token_ref": route_gate.get("route_token_ref"),
            "registry_verified": bool(route_gate.get("registry_verified")),
        },
        "checks": {
            "has_close_commit": bool(close_commit),
            "has_audit_archive_reference": bool(root_ids),
            "has_accepted_audit_archive": bool(accepted_archives),
            "has_independent_qa": bool(qa_events),
        },
    }
    if not passed:
        raise GovernanceError(
            "audit_recovery_close_gate_failed",
            (
                "audit_recovery backlog close requires accepted audit archive "
                f"and independent QA evidence; missing: {', '.join(missing)}"
            ),
            422,
            {"audit_recovery_close_gate": verification},
        )
    return verification


def _verify_mf_close_timeline_gate(
    conn,
    project_id: str,
    bug_id: str,
    row,
    body: dict,
    *,
    route_gate: Mapping[str, Any] | None = None,
) -> dict:
    """Require append-only timeline evidence before observer/MF backlog close."""

    applicability = _mf_close_timeline_applicability(row)
    if applicability.get("is_audit_recovery"):
        return _verify_audit_recovery_close_gate(
            conn,
            project_id,
            bug_id,
            row,
            body,
            route_gate=route_gate or {},
        )
    if not applicability["is_mf"]:
        return {}

    from . import task_timeline

    if bool(body.get("bypass_timeline_gate")):
        reason = str(body.get("timeline_bypass_reason") or "").strip()
        verification = {
            "schema_version": "mf_close_timeline_gate.v1",
            "passed": False,
            "status": "rejected",
            "bypass_timeline_gate": True,
            "reason": reason,
        }
        if not reason:
            task_timeline.record_event(
                conn,
                project_id=project_id,
                backlog_id=bug_id,
                event_type="mf_timeline_gate_bypass_rejected",
                phase="close",
                event_kind="mf_timeline_gate_bypass_rejected",
                actor=str(body.get("actor") or "observer"),
                status="rejected",
                payload={"bypass_timeline_gate": True, "reason": reason},
                verification=verification,
                commit_sha=str(body.get("commit") or ""),
            )
            conn.commit()
            raise GovernanceError(
                "mf_timeline_bypass_reason_required",
                "bypass_timeline_gate requires timeline_bypass_reason",
                422,
                verification,
            )
        task_timeline.record_event(
            conn,
            project_id=project_id,
            backlog_id=bug_id,
            event_type="mf_timeline_gate_bypass_rejected",
            phase="close",
            event_kind="mf_timeline_gate_bypass_rejected",
            actor=str(body.get("actor") or "observer"),
            status="rejected",
            payload={"bypass_timeline_gate": True, "reason": reason},
            verification=verification,
            commit_sha=str(body.get("commit") or ""),
        )
        conn.commit()
        raise GovernanceError(
            "mf_timeline_bypass_forbidden",
            "bypass_timeline_gate is forbidden; MF close timeline evidence cannot be skipped",
            422,
            verification,
        )

    gate_body = _timeline_gate_contract_runtime_projection_body(
        conn,
        project_id=project_id,
        backlog_id=bug_id,
        query=body,
        route_gate=route_gate,
    )
    events = task_timeline.list_events(conn, project_id, backlog_id=bug_id, limit=1000)
    contract = backlog_runtime.parse_json_object(_row_get(row, "chain_trigger_json", "{}"))
    contract = _mf_close_contract_with_route_context(contract, row, gate_body)
    runtime_projection = _contract_runtime_close_authority_projection(
        conn,
        project_id=project_id,
        bug_id=bug_id,
        body=gate_body,
        route_gate=route_gate,
        close_commit=_audit_recovery_close_commit(row, gate_body),
        timeline_events=events,
    )
    contract_runtime_required = _contract_runtime_close_authority_required_signal(
        gate_body,
        runtime_projection,
        route_gate=route_gate,
    )
    if runtime_projection.get("accepted"):
        legacy_verification = _mf_close_gate_verification(
            events,
            contract=contract,
            conn=conn,
            project_id=project_id,
        )
        verification = _contract_runtime_authoritative_close_with_legacy_diagnostics(
            legacy_verification,
            runtime_projection,
        )
        verification["contract_runtime_close_authority_projection"] = {
            key: value
            for key, value in runtime_projection.items()
            if key != "projected_events"
        }
    else:
        verification = _mf_close_gate_verification(
            events,
            contract=contract,
            conn=conn,
            project_id=project_id,
        )
        if runtime_projection:
            verification = dict(verification)
            verification["contract_runtime_close_authority_projection"] = {
                key: value
                for key, value in runtime_projection.items()
                if key != "projected_events"
            }
        if contract_runtime_required:
            if runtime_projection:
                runtime_failure_details = _contract_runtime_close_authority_failure_details(
                    verification,
                    runtime_projection,
                )
                missing_runtime = runtime_failure_details.get(
                    "missing_contract_runtime_close_authority_requirement_ids"
                ) or []
                status = str(runtime_projection.get("status") or "failed")
                missing_text = ", ".join(missing_runtime) if missing_runtime else status
                raise GovernanceError(
                    "contract_runtime_close_authority_incomplete",
                    (
                        "ContractRuntime close authority blocked backlog_close; "
                        f"missing: {missing_text}"
                    ),
                    422,
                    runtime_failure_details,
                )
            runtime_failure_details = _missing_contract_runtime_close_authority_details(
                verification,
                body=gate_body,
            )
            raise GovernanceError(
                "missing_contract_runtime_close_authority",
                (
                    "ContractRuntime close authority is required before backlog_close; "
                    "missing: contract_runtime_close_authority"
                ),
                422,
                runtime_failure_details,
            )
    if not verification.get("passed"):
        runtime_authority_failed = (
            contract_runtime_required
            and isinstance(runtime_projection, Mapping)
            and bool(runtime_projection)
            and (
                not bool(runtime_projection.get("accepted"))
                or bool(verification.get("runtime_projection_authority_failed"))
            )
        )
        if runtime_authority_failed:
            runtime_failure_details = _contract_runtime_close_authority_failure_details(
                verification,
                runtime_projection,
            )
            missing_runtime = runtime_failure_details.get(
                "missing_contract_runtime_close_authority_requirement_ids"
            ) or []
            status = str(runtime_projection.get("status") or "failed")
            missing_text = ", ".join(missing_runtime) if missing_runtime else status
            raise GovernanceError(
                "contract_runtime_close_authority_incomplete",
                (
                    "ContractRuntime close authority blocked backlog_close; "
                    f"missing: {missing_text}"
                ),
                422,
                runtime_failure_details,
            )
        missing_event_kinds = verification.get("missing_event_kinds") or []
        contract_gate = verification.get("contract_gate") if isinstance(verification.get("contract_gate"), dict) else {}
        missing_contract = contract_gate.get("missing_requirement_ids") or []
        route_context_gate = (
            verification.get("route_context_gate")
            if isinstance(verification.get("route_context_gate"), dict)
            else {}
        )
        missing_route_context = route_context_gate.get("missing_requirement_ids") or []
        lane_ownership_gate = (
            verification.get("lane_ownership_gate")
            if isinstance(verification.get("lane_ownership_gate"), dict)
            else {}
        )
        missing_lane_ownership = lane_ownership_gate.get("missing_lane_ownership_ids") or []
        close_commit_gate = (
            verification.get("close_commit_evidence_gate")
            if isinstance(verification.get("close_commit_evidence_gate"), dict)
            else {}
        )
        missing_close_commit = close_commit_gate.get("missing_requirement_ids") or []
        runtime_mf_parallel_authority_gate = (
            verification.get("contract_runtime_mf_parallel_close_authority_gate")
            if isinstance(
                verification.get("contract_runtime_mf_parallel_close_authority_gate"),
                dict,
            )
            else {}
        )
        missing_runtime_mf_parallel_authority = (
            runtime_mf_parallel_authority_gate.get("missing_requirement_ids") or []
        )
        missing = ", ".join([
            *missing_event_kinds,
            *missing_contract,
            *missing_route_context,
            *missing_lane_ownership,
            *missing_close_commit,
            *missing_runtime_mf_parallel_authority,
        ])
        if not missing:
            missing = "timeline gate failed"
        raise GovernanceError(
            "mf_timeline_gate_failed",
            f"MF backlog close requires task timeline evidence before FIXED; missing: {missing}",
            422,
            {
                "timeline_gate": verification,
                "failed_gates": verification.get("failed_gates") or [],
                "missing_event_kinds": missing_event_kinds,
                "missing_contract_requirement_ids": missing_contract,
                "missing_route_context_requirement_ids": missing_route_context,
                "missing_lane_ownership_ids": missing_lane_ownership,
                "missing_close_commit_requirement_ids": missing_close_commit,
                "missing_contract_runtime_mf_parallel_authority_requirement_ids": (
                    missing_runtime_mf_parallel_authority
                ),
            },
        )
    return verification


def _event_route_token_ref(event: Mapping[str, Any]) -> str:
    return (
        str(event.get("route_token_ref") or "").strip()
        or _route_request_identity_value(event, "route_token_ref")
    )


def _route_gate_from_resolved_ref(
    resolved: Mapping[str, Any],
    *,
    route_token_ref: str,
) -> dict[str, Any]:
    allowed_actions = [
        str(item or "").strip()
        for item in (resolved.get("allowed_actions") or [])
        if str(item or "").strip()
    ]
    gate = {
        "schema_version": "route_token_mutation_gate.v1",
        "allowed": True,
        "accepted": True,
        "status": "passed",
        "decision": "route_token_ref_resolved",
        "action": "task_timeline_append",
        "route_token_ref": route_token_ref,
        "resolved_from_ref": True,
        "server_issued_binding": True,
        "registry_verified": True,
        "binding_source": "observer_route_token_refs",
        "route_id": str(resolved.get("route_id") or ""),
        "route_context_hash": str(resolved.get("route_context_hash") or ""),
        "prompt_contract_id": str(resolved.get("prompt_contract_id") or ""),
        "prompt_contract_hash": str(resolved.get("prompt_contract_hash") or ""),
        "visible_injection_manifest_hash": str(
            resolved.get("visible_injection_manifest_hash") or ""
        ),
        "allowed_actions": allowed_actions,
        "scope": resolved.get("scope") if isinstance(resolved.get("scope"), Mapping) else {},
    }
    for key in ("parent_route_lineage", "child_route_lineage", "route_lineage"):
        value = resolved.get(key)
        if isinstance(value, Mapping):
            gate[key] = dict(value)
    return gate


def _route_lineage_enrichment_event_ref(event: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "id": event.get("id") or event.get("event_id"),
        "event_kind": event.get("event_kind"),
        "phase": event.get("phase"),
        "status": event.get("status") or event.get("decision"),
    }


_ROUTE_REGISTRY_IDENTITY_FIELDS = (
    "route_id",
    "route_context_hash",
    "prompt_contract_id",
    "prompt_contract_hash",
    "route_token_ref",
    "visible_injection_manifest_hash",
)


def _route_registry_json_mapping(value: Any) -> dict[str, Any]:
    if isinstance(value, Mapping):
        return dict(value)
    if not isinstance(value, str) or not value.strip():
        return {}
    try:
        parsed = json.loads(value)
    except (TypeError, ValueError):
        return {}
    return dict(parsed) if isinstance(parsed, Mapping) else {}


def _route_registry_row_identity(row: Mapping[str, Any]) -> dict[str, str]:
    return {
        field: str(row.get(field) or "").strip()
        for field in _ROUTE_REGISTRY_IDENTITY_FIELDS
    }


def _route_registry_identity_exact(
    actual: Mapping[str, Any],
    expected: Mapping[str, Any],
) -> bool:
    return all(
        str(actual.get(field) or "").strip()
        and str(actual.get(field) or "").strip()
        == str(expected.get(field) or "").strip()
        for field in _ROUTE_REGISTRY_IDENTITY_FIELDS
    )


def _route_registry_renewal_chain_projection(
    conn,
    *,
    project_id: str,
    event: Mapping[str, Any],
    requested_route_token_ref: str,
    resolved: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Bind a strict renewal descendant to its immutable predecessor event.

    The existing registry resolver proves the unique active descendant and the
    exact role/action/file/scope fence.  This read-only companion verifies that
    every registry row also keeps one byte-equivalent public parent identity,
    then projects the historical predecessor together with the current child.
    It never rewrites the persisted timeline event or route-token registry.
    """

    renewal = (
        dict(resolved.get("renewal_resolution") or {})
        if isinstance(resolved.get("renewal_resolution"), Mapping)
        else {}
    )
    chain_refs = [
        str(item or "").strip()
        for item in (renewal.get("route_token_ref_chain") or [])
        if str(item or "").strip()
    ]
    edge_types = [
        str(item or "").strip()
        for item in (renewal.get("edge_types") or [])
        if str(item or "").strip()
    ]
    current_ref = str(renewal.get("resolved_route_token_ref") or "").strip()
    if not (
        renewal.get("schema_version")
        == "route_token_ref_exact_renewal_descendant_resolution.v1"
        and renewal.get("status") == "resolved_active_descendant"
        and renewal.get("registry_verified") is True
        and renewal.get("exact_scope_verified") is True
        and renewal.get("writes_performed") is False
        and renewal.get("raw_route_token_exposed") is False
        and len(chain_refs) >= 2
        and chain_refs[0] == requested_route_token_ref
        and chain_refs[-1] == current_ref
        and len(edge_types) == len(chain_refs) - 1
        and all(edge == "renewal" for edge in edge_types)
    ):
        return {}, {}

    placeholders = ",".join("?" for _ in chain_refs)
    registry_rows = conn.execute(
        f"""
        SELECT project_id, route_token_ref, route_id, route_context_hash,
               prompt_contract_id, prompt_contract_hash,
               visible_injection_manifest_hash, backlog_id, task_id,
               caller_role, allowed_actions_json, target_files_json,
               owned_files_json, scope_json, parent_route_lineage_json,
               child_route_lineage_json, status
          FROM observer_route_token_refs
         WHERE project_id=? AND route_token_ref IN ({placeholders})
        """,
        (_route_registry_storage_project_id(project_id), *chain_refs),
    ).fetchall()
    rows_by_ref = {
        str(dict(row).get("route_token_ref") or "").strip(): dict(row)
        for row in registry_rows
    }
    if set(rows_by_ref) != set(chain_refs):
        return {}, {}
    ordered_rows = [rows_by_ref[route_ref] for route_ref in chain_refs]
    if any(
        str(row.get("status") or "").strip()
        != ("active" if index == len(ordered_rows) - 1 else "superseded")
        for index, row in enumerate(ordered_rows)
    ):
        return {}, {}

    predecessor_identity = _route_registry_row_identity(ordered_rows[0])
    current_identity = _route_registry_row_identity(ordered_rows[-1])
    requested_resolution_identity = renewal.get("requested_route_identity")
    current_resolution_identity = renewal.get("resolved_route_identity")
    if not (
        isinstance(requested_resolution_identity, Mapping)
        and isinstance(current_resolution_identity, Mapping)
        and _route_registry_identity_exact(
            requested_resolution_identity,
            predecessor_identity,
        )
        and _route_registry_identity_exact(
            current_resolution_identity,
            current_identity,
        )
    ):
        return {}, {}

    event_identity = {
        field: (
            requested_route_token_ref
            if field == "route_token_ref"
            else _route_request_identity_value(event, field)
        )
        for field in _ROUTE_REGISTRY_IDENTITY_FIELDS
    }
    if not _route_registry_identity_exact(event_identity, predecessor_identity):
        return {}, {}

    parent_identities: list[dict[str, Any]] = []
    child_identities: list[dict[str, Any]] = []
    for row in ordered_rows:
        parent = _route_registry_json_mapping(row.get("parent_route_lineage_json"))
        child = _route_registry_json_mapping(row.get("child_route_lineage_json"))
        row_identity = _route_registry_row_identity(row)
        if not parent or not child or not _route_registry_identity_exact(
            child,
            row_identity,
        ):
            return {}, {}
        parent_identities.append(parent)
        child_identities.append(child)
    common_parent = _route_identity_public_summary(parent_identities[0])
    if not common_parent or any(
        not _route_registry_identity_exact(parent, common_parent)
        for parent in parent_identities
    ):
        return {}, {}

    active_parent = resolved.get("parent_route_lineage")
    active_child = resolved.get("child_route_lineage")
    if not (
        isinstance(active_parent, Mapping)
        and isinstance(active_child, Mapping)
        and _route_registry_identity_exact(active_parent, common_parent)
        and _route_registry_identity_exact(active_child, current_identity)
    ):
        return {}, {}

    def string_list(row: Mapping[str, Any], field: str) -> list[str]:
        try:
            parsed = json.loads(str(row.get(field) or "[]"))
        except (TypeError, ValueError):
            parsed = []
        return sorted(
            {
                str(item or "").strip()
                for item in (parsed if isinstance(parsed, list) else [])
                if str(item or "").strip()
            }
        )

    projection = {
        "schema_version": "server_route_action_scope_renewal_chain.v1",
        "accepted": True,
        "status": "accepted",
        "source": "server_timeline_precheck_registry_renewal_chain",
        "projected_by": "server_timeline_precheck_enrichment",
        "server_projected": True,
        "registry_verified": True,
        "exact_scope_verified": True,
        "same_parent_verified": True,
        "authority_unchanged": True,
        "historical_event_rewritten": False,
        "writes_performed": False,
        "raw_route_token_exposed": False,
        "requested_route_token_ref": requested_route_token_ref,
        "resolved_route_token_ref": current_ref,
        "route_token_ref_chain": chain_refs,
        "edge_types": edge_types,
        "canonical_predecessor_route_identity": predecessor_identity,
        "current_route_identity": current_identity,
        "common_parent_route_identity": common_parent,
        "scope": dict(renewal.get("scope") or {}),
        "caller_role": str(ordered_rows[-1].get("caller_role") or "").strip(),
        "allowed_actions": string_list(ordered_rows[-1], "allowed_actions_json"),
        "target_files": string_list(ordered_rows[-1], "target_files_json"),
        "owned_files": string_list(ordered_rows[-1], "owned_files_json"),
    }
    predecessor_resolved = dict(resolved)
    predecessor_resolved.update(predecessor_identity)
    predecessor_resolved["parent_route_lineage"] = dict(parent_identities[0])
    predecessor_resolved["child_route_lineage"] = dict(child_identities[0])
    predecessor_resolved["route_token_ref_renewal_chain"] = projection
    return predecessor_resolved, projection


def _enrich_timeline_events_with_route_token_lineage(
    conn,
    *,
    project_id: str,
    events: list[dict],
) -> tuple[list[dict], dict[str, Any]]:
    from . import observer_route_context as _orc
    from . import task_timeline

    rows = events if isinstance(events, list) else []
    if conn is None or not project_id:
        return rows, {
            "schema_version": "server_route_lineage_enrichment.v1",
            "attempted_event_count": 0,
            "enriched_event_count": 0,
            "skipped_reason": "registry_unavailable",
        }

    enriched_rows: list[dict] = []
    enriched_events: list[dict[str, Any]] = []
    failed_events: list[dict[str, Any]] = []
    attempted = 0
    for raw in rows:
        event = dict(raw) if isinstance(raw, Mapping) else raw
        if not isinstance(event, dict):
            enriched_rows.append(event)
            continue
        if not task_timeline.is_protected_close_evidence(event):
            enriched_rows.append(event)
            continue
        stripped = _strip_route_action_scope_lineage_value(event)
        event = dict(stripped) if isinstance(stripped, Mapping) else dict(event)
        route_token_ref = _event_route_token_ref(event)
        if not route_token_ref:
            enriched_rows.append(event)
            continue
        attempted += 1
        payload = event.get("payload") if isinstance(event.get("payload"), Mapping) else {}
        payload = dict(payload)
        event_ref = _route_lineage_enrichment_event_ref(event)
        route_id = _route_request_identity_value(event, "route_id")
        route_context_hash = _route_request_identity_value(event, "route_context_hash")
        prompt_contract_id = _route_request_identity_value(event, "prompt_contract_id")
        missing_identity = [
            field
            for field, value in (
                ("route_context_hash", route_context_hash),
                ("prompt_contract_id", prompt_contract_id),
            )
            if not value
        ]
        if missing_identity:
            payload["route_action_scope_lineage_resolution"] = {
                "schema_version": "server_route_lineage_resolution.v1",
                "status": "failed",
                "reason": "missing_child_route_identity",
                "missing_fields": missing_identity,
                "route_token_ref": route_token_ref,
            }
            event["payload"] = payload
            failed_events.append({
                **event_ref,
                "route_token_ref": route_token_ref,
                "reason": "missing_child_route_identity",
                "missing_fields": missing_identity,
            })
            enriched_rows.append(event)
            continue
        renewal_projection: dict[str, Any] = {}
        try:
            resolved = _orc.resolve_route_token_ref_renewal_descendant(
                conn,
                project_id=project_id,
                storage_project_id=_route_registry_storage_project_id(project_id),
                route_token_ref=route_token_ref,
            )
            renewal = (
                resolved.get("renewal_resolution")
                if isinstance(resolved, Mapping)
                else None
            )
            if isinstance(renewal, Mapping):
                resolved, renewal_projection = (
                    _route_registry_renewal_chain_projection(
                        conn,
                        project_id=project_id,
                        event=event,
                        requested_route_token_ref=route_token_ref,
                        resolved=resolved,
                    )
                )
                if not resolved or not renewal_projection:
                    raise _orc.RouteTokenRefError(
                        "route-token renewal registry parent chain is not canonical"
                    )
            elif resolved:
                resolved = _orc.resolve_route_token_ref(
                    conn,
                    project_id=project_id,
                    storage_project_id=_route_registry_storage_project_id(project_id),
                    route_token_ref=route_token_ref,
                    backlog_id=str(event.get("backlog_id") or ""),
                    route_id=route_id,
                    route_context_hash=route_context_hash,
                    prompt_contract_id=prompt_contract_id,
                )
        except _orc.RouteTokenRefError as exc:
            payload["route_action_scope_lineage_resolution"] = {
                "schema_version": "server_route_lineage_resolution.v1",
                "status": "failed",
                "reason": str(exc),
                "route_token_ref": route_token_ref,
            }
            event["payload"] = payload
            failed_events.append({
                **event_ref,
                "route_token_ref": route_token_ref,
                "reason": str(exc),
            })
            enriched_rows.append(event)
            continue
        if not resolved:
            payload["route_action_scope_lineage_resolution"] = {
                "schema_version": "server_route_lineage_resolution.v1",
                "status": "failed",
                "reason": "route_token_ref_unknown",
                "route_token_ref": route_token_ref,
            }
            event["payload"] = payload
            failed_events.append({
                **event_ref,
                "route_token_ref": route_token_ref,
                "reason": "route_token_ref_unknown",
            })
            enriched_rows.append(event)
            continue
        resolved_route_id = str(resolved.get("route_id") or "").strip()
        if not route_id and not resolved_route_id:
            payload["route_action_scope_lineage_resolution"] = {
                "schema_version": "server_route_lineage_resolution.v1",
                "status": "failed",
                "reason": "missing_child_route_identity",
                "missing_fields": ["route_id"],
                "route_token_ref": route_token_ref,
            }
            event["payload"] = payload
            failed_events.append({
                **event_ref,
                "route_token_ref": route_token_ref,
                "reason": "missing_child_route_identity",
                "missing_fields": ["route_id"],
            })
            enriched_rows.append(event)
            continue
        allowed_actions = {
            str(item or "").strip()
            for item in (resolved.get("allowed_actions") or [])
            if str(item or "").strip()
        }
        if "task_timeline_append" not in allowed_actions:
            payload["route_action_scope_lineage_resolution"] = {
                "schema_version": "server_route_lineage_resolution.v1",
                "status": "failed",
                "reason": "route_token_ref_action_not_allowed",
                "route_token_ref": route_token_ref,
            }
            event["payload"] = payload
            failed_events.append({
                **event_ref,
                "route_token_ref": route_token_ref,
                "reason": "route_token_ref_action_not_allowed",
            })
            enriched_rows.append(event)
            continue
        route_gate = _route_gate_from_resolved_ref(
            resolved,
            route_token_ref=route_token_ref,
        )
        payload["route_token_gate"] = _route_gate_public_summary(route_gate)
        event["payload"] = payload
        lineage = _server_route_action_scope_lineage(event, event, route_gate)
        if lineage:
            lineage = dict(lineage)
            lineage["projected_by"] = "server_timeline_precheck_enrichment"
            if renewal_projection:
                lineage["route_token_ref_renewal_chain"] = renewal_projection
            payload["route_action_scope_lineage"] = lineage
            payload["route_action_scope_lineage_resolution"] = {
                "schema_version": "server_route_lineage_resolution.v1",
                "status": "passed",
                "route_token_ref": route_token_ref,
                **(
                    {"route_token_ref_renewal_chain": renewal_projection}
                    if renewal_projection
                    else {}
                ),
            }
            event["payload"] = payload
            enriched_events.append({
                **event_ref,
                "route_token_ref": route_token_ref,
            })
        else:
            payload["route_action_scope_lineage_resolution"] = {
                "schema_version": "server_route_lineage_resolution.v1",
                "status": "failed",
                "reason": "registry_lineage_incomplete",
                "route_token_ref": route_token_ref,
            }
            event["payload"] = payload
            failed_events.append({
                **event_ref,
                "route_token_ref": route_token_ref,
                "reason": "registry_lineage_incomplete",
            })
        enriched_rows.append(event)

    return enriched_rows, {
        "schema_version": "server_route_lineage_enrichment.v1",
        "attempted_event_count": attempted,
        "enriched_event_count": len(enriched_events),
        "failed_event_count": len(failed_events),
        "enriched_events": enriched_events,
        "failed_events": failed_events,
    }


def _mf_close_gate_verification(
    events: list[dict] | None,
    contract: dict | None = None,
    *,
    conn=None,
    project_id: str = "",
) -> dict:
    from . import task_timeline

    enriched_events, enrichment = _enrich_timeline_events_with_route_token_lineage(
        conn,
        project_id=project_id,
        events=events or [],
    )
    verification = task_timeline.mf_close_gate_verification(
        enriched_events,
        contract=contract,
        conn=conn,
    )
    startup_gate = verification.get("close_timeline_startup_gate")
    if isinstance(startup_gate, dict) and (
        startup_gate.get("demoted_startup_events")
        or startup_gate.get("accepted_startup_events")
    ):
        verification = dict(verification)
        verification["close_timeline_startup_gate"] = startup_gate
        checks = dict(verification.get("checks") or {})
        checks["mf_subagent_startup_close_satisfying"] = bool(
            startup_gate.get("passed")
        )
        verification["checks"] = checks
    if enrichment.get("attempted_event_count"):
        verification = dict(verification)
        verification["server_route_lineage_enrichment"] = enrichment
    return verification


def _mf_close_contract_with_route_context(contract: dict, row, body: Mapping[str, Any]) -> dict:
    enriched = dict(contract) if isinstance(contract, dict) else {}
    close_context: dict[str, Any] = {}
    for key in (
        "priority",
        "target_files",
        "test_files",
        "acceptance_criteria",
    ):
        value = _row_get(row, key, "")
        if key in {"target_files", "test_files", "acceptance_criteria"}:
            value = _string_list_field(value)
        if value not in (None, "", [], {}):
            close_context[key] = value
    for key in ("changed_files", "owned_files", "caller_role", "task_summary", "summary"):
        value = body.get(key) if isinstance(body, Mapping) else None
        if key in {"changed_files", "owned_files"}:
            value = _string_list_field(value)
        if value not in (None, "", [], {}):
            close_context[key] = value
    close_commit = ""
    if isinstance(body, Mapping):
        for key in (
            "close_commit",
            "commit",
            "commit_sha",
            "target_head_commit",
            "head_commit",
        ):
            close_commit = str(body.get(key) or "").strip()
            if close_commit:
                break
    if not close_commit:
        for key in (
            "commit",
            "commit_sha",
            "fixed_commit",
            "target_head_commit",
            "head_commit",
        ):
            close_commit = str(_row_get(row, key, "") or "").strip()
            if close_commit:
                break
    if close_commit:
        close_context["close_commit"] = close_commit
    if close_context:
        existing = enriched.get("close_context")
        if isinstance(existing, Mapping):
            close_context = {**dict(existing), **close_context}
        enriched["close_context"] = close_context
    return enriched


def _mf_close_timeline_applicability(row) -> dict:
    policy = backlog_runtime.parse_json_object(_row_get(row, "bypass_policy_json", "{}"))
    chain_trigger = backlog_runtime.parse_json_object(_row_get(row, "chain_trigger_json", "{}"))
    contract_reasons = _contract_state_backlog_applicability_reasons(chain_trigger)
    raw_mf_type = str(_row_get(row, "mf_type", "") or policy.get("mf_type") or "").strip()
    mf_type = backlog_runtime.normalize_mf_type(raw_mf_type, policy) if raw_mf_type else ""
    is_audit_recovery = mf_type == backlog_runtime.MF_TYPE_AUDIT_RECOVERY
    chain_stage = str(_row_get(row, "chain_stage", "") or "").strip()
    chain_stage_key = chain_stage.lower().replace("_", "-")
    prior_status = str(_row_get(row, "status", "") or "").strip()
    is_mf = bool(
        prior_status == "MF_IN_PROGRESS"
        or (mf_type and not is_audit_recovery)
        or chain_stage_key in {"manual-fix", "observer-hotfix", "chain-rescue"}
        or contract_reasons
    )
    reasons = []
    if prior_status == "MF_IN_PROGRESS":
        reasons.append("status=MF_IN_PROGRESS")
    if mf_type:
        reasons.append(f"mf_type={mf_type}")
    if chain_stage_key in {"manual-fix", "observer-hotfix", "chain-rescue"}:
        reasons.append(f"chain_stage={chain_stage}")
    reasons.extend(contract_reasons)
    return {
        "is_mf": is_mf,
        "is_audit_recovery": is_audit_recovery,
        "reason": ", ".join(reasons) if reasons else "not an MF/observer backlog row",
    }


def _contract_state_backlog_applicability_reasons(chain_trigger: Any) -> list[str]:
    trigger = chain_trigger if isinstance(chain_trigger, Mapping) else {}
    if not trigger:
        return []
    keys: list[str] = []
    direct_keys = (
        "contract",
        "contract_template_id",
        "contract_execution_id",
        "required_evidence",
        "successor_contract_policy",
        "active_contract_execution",
        "parallel_contract",
    )
    for key in direct_keys:
        value = trigger.get(key)
        if value not in (None, "", [], {}):
            keys.append(key)
    nested_contract_keys = (
        "template_id",
        "contract_template_id",
        "contract_execution_id",
        "contract_instance_id",
        "required_evidence",
        "evidence_requirements",
        "successor_contract_policy",
    )
    for parent_key in ("contract", "active_contract_execution", "parallel_contract"):
        nested = trigger.get(parent_key)
        if not isinstance(nested, Mapping):
            continue
        for key in nested_contract_keys:
            value = nested.get(key)
            if value not in (None, "", [], {}):
                keys.append(f"{parent_key}.{key}")
    if not keys:
        return []
    compact_keys = ",".join(sorted(set(keys))[:6])
    return [f"chain_trigger_json.contract_state:{compact_keys}"]


_MF_TIMELINE_REASON_HUMAN = {
    "mf_type=chain_rescue": (
        "chain_rescue is the MVP internal storage label for observer-hotfix "
        "and manual-fix work, not an error or limitation. See aming-claw://mf-sop."
    ),
}


@route("GET", "/api/docs")
def handle_docs_index(ctx: RequestContext):
    """Return available documentation sections."""
    sections = []
    for key, doc in _DOCS.items():
        sections.append({
            "section": key,
            "title": doc.get("title", key),
            "url": f"/api/docs/{key}",
        })
    return {"sections": sections}


@route("GET", "/api/docs/{section}")
def handle_docs_section(ctx: RequestContext):
    """Return a specific documentation section."""
    section = ctx.path_params.get("section", "")
    if section not in _DOCS:
        from .errors import GovernanceError
        raise GovernanceError(f"Unknown doc section: {section}. Available: {list(_DOCS.keys())}", 404)
    return _DOCS[section]


# ============================================================
# Server Entry Point
# ============================================================

def create_server(port: int = None) -> HTTPServer:
    p = port or PORT
    # Z0-sequel observer-hotfix 2026-04-24: ThreadingHTTPServer so a slow
    # handler (e.g. on_task_completed waiting on Z1's 60s busy_timeout DB lock)
    # doesn't starve every other HTTP request — the "post-completion wedge"
    # symptom that blocked the Z0+Z2 verification chain 3× in 30min.
    server = ThreadingHTTPServer((_runtime_bind_host(), p), GovernanceHandler)
    return server


def _run_governance_service():
    """Start side effects and bind only after manager certification succeeds."""

    with _GOVERNANCE_MANAGER_CERTIFICATES_LOCK:
        if (
            _GOVERNANCE_SINGLETON_LEASE is None
            or not _GOVERNANCE_MANAGER_CERTIFICATES
        ):
            raise GovernanceSingletonError(
                "governance_manager_generation_not_published"
            )
    print(f"Governance v{get_server_version()} (PID {SERVER_PID})")

    if _runtime_plane() == "dev":
        # A repair service shares only the allowlisted AC database.  It never
        # joins stable Redis/event workers, performs startup backfills, or owns
        # the port-40000 lifecycle.
        server = create_server()
        print(
            f"AC dev governance service listening on port {PORT}; "
            "background workers disabled"
        )
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            print("\nShutting down AC dev governance...")
            server.shutdown()
        return

    # Enable Redis Pub/Sub bridge for EventBus
    from .event_bus import get_event_bus
    redis = get_redis()
    if redis.available:
        get_event_bus().enable_redis_bridge()
        print("EventBus: Redis Pub/Sub bridge enabled")
    else:
        print("EventBus: Redis unavailable, in-process only")

    # Register chain context EventBus subscribers + recover active chains
    try:
        from .chain_context import register_events, get_store
        register_events()
        # Recover active chains for known projects
        from .db import _governance_root
        gov_root = _governance_root()
        if gov_root.exists():
            for pdir in gov_root.iterdir():
                if pdir.is_dir() and (pdir / "governance.db").exists():
                    get_store().recover_from_db(pdir.name)
        print("ChainContext: registered + recovered")
    except Exception as e:
        print(f"ChainContext: failed to start ({e})")

    # Start doc generator listener
    try:
        from .doc_generator import setup_listener
        setup_listener()
        print("DocGenerator: listening for node.created events")
    except Exception as e:
        print(f"DocGenerator: failed to start ({e})")

    # MF-2026-05-10-016: event-driven in-process semantic worker.
    # Subscribes to semantic_job.enqueued + system.startup. Drains the
    # /semantic/jobs queue (node_semantic only) into pending_review state
    # so dashboard Review Queue can gate operator acceptance.
    try:
        from .semantic_worker import register as register_semantic_worker
        register_semantic_worker()
        print("SemanticWorker: registered (event-driven, in-process)")
    except Exception as e:
        print(f"SemanticWorker: failed to start ({e})")

    # Start outbox worker for reliable event delivery
    try:
        from .outbox import OutboxWorker
        outbox_worker = OutboxWorker()
        outbox_worker.start()
        print("OutboxWorker: started")
    except Exception as e:
        print(f"OutboxWorker: failed to start ({e})")

    # Per-project chain history backfill at startup (R5)
    try:
        from .chain_trailer import backfill_legacy_chain_history
        _conn = get_connection("aming-claw")
        try:
            _rows = _conn.execute(
                "SELECT DISTINCT project_id FROM project_version"
            ).fetchall()
            _pids = [r["project_id"] if isinstance(r, dict) else r[0] for r in _rows]
        except Exception:
            _pids = ["aming-claw"]
        finally:
            _conn.close()
        for _pid in _pids:
            try:
                _res = backfill_legacy_chain_history(project_id=_pid, incremental=True)
                print(f"ChainTrailer: backfill[{_pid}] {_res.get('scan_mode','?')} — "
                      f"{_res.get('new_entries',0)} new, {_res.get('total_entries',0)} total")
            except Exception as _e:
                print(f"ChainTrailer: backfill[{_pid}] failed ({_e})")
    except Exception as e:
        print(f"ChainTrailer: backfill failed ({e})")

    server = create_server()
    print(f"Governance service listening on port {PORT}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down...")
        server.shutdown()


_contract_runtime_refresh_canonical_authority_field_inventory()


def main():
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s %(message)s",
        stream=sys.stderr,
    )
    dev_storage_root = ""
    if _runtime_plane() == "dev":
        dev_storage_root = os.environ.get("AMING_CLAW_DEV_STORAGE_ROOT", "").strip()
        if not dev_storage_root:
            raise GovernanceSingletonError("ac_dev_storage_root_required")
        from .db import _verified_stable_binding
        _verified_stable_binding()
        loaded_source = governance_loaded_runtime_identity().get("loaded_source_sha256")
        try:
            validate_dev_launch_receipt(dev_storage_root, source_sha256=str(loaded_source or ""))
        except (OSError, ValueError) as exc:
            raise GovernanceSingletonError("ac_dev_launch_receipt_invalid") from exc
        acquire_dev_runtime_writer_lease(dev_storage_root)
    try:
        _validate_runtime_plane_startup()
        lease = _establish_governance_manager_generation()
        try:
            _run_governance_service()
        finally:
            _release_governance_manager_generation(lease)
    finally:
        if dev_storage_root:
            release_dev_runtime_writer_lease(dev_storage_root)


if __name__ == "__main__":
    main()
